INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O An', 'o-an-sair-peymanlorin-6ekjw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bekliyorum, bekliyoruz.

Kalabalıklar ve gürültülü insan sesleri içinde

iki kişiyiz

yalnız başıma,

yalnız başına.

Mutsuz ama mutlu

Öyle bir An''da gel ki

Mutsuzluğu mutluluk yapsın

Mutluluğu mutsuz! 

Öyle bir An''da gel ki

Geçmişte yaşanmış pişmanlıkları yok etsin

Öyle bir An''da gel ki

Ölen duyguları yeşertsin

Öyle bir An''da gel ki

O ''An'' hiç hatırlanmasın

               hep yaşansın

ve

Öyle bir An''da gel ki 

Öyle bir An''da geldi diyeyim

Böyle bir An''da gelme yeter ki', 'Bekliyorum, bekliyoruz. Kalabalıklar ve gürültülü insan sesleri içinde iki kişiyiz yalnız başıma, yalnız başına. Mutsuz ama mutlu Öyle bir A...', ARRAY['Türk Edebiyatı','Şiir','Şair Peymanlorin']::text[], 8.5, '{"poet":"Şair Peymanlorin","poet_slug":"sair-peymanlorin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/o-an-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal bu Gece', 'kal-bu-gece-i-shak-ozlu-g9snz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geldin yurduma iki cihan bir oldu,

Cansuyu geldi topragıma gül verdi,

Şen oldu yaslı gönlüm can dostu gördü,

Gitme dost kal bu gece can ol bize.

Sen ben diyen diller geldinya biz oldu,

Güzde kışlayan gönlümüze yaz doldu,

Hüzün bulutları kendine yol buldu,

Gitme dost kal bu gece can ol bize.

Mordu daglarım açtı yeşile döndü,

Muhabbete hasret dil bülbüle döndü,

Susmuş meclis şenlenip şölene döndü,

Gitme dost kal bu gece can ol bize.

Dost gülleri bekledigi suyu buldu,

Uzadı güneş akşamın ufku soldu,

Bakma yollara gönlüm hüzün doldu,

Gitme dost kal bu gece can ol bize.', 'Geldin yurduma iki cihan bir oldu, Cansuyu geldi topragıma gül verdi, Şen oldu yaslı gönlüm can dostu gördü, Gitme dost kal bu gece can ol b...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kal-bu-gece-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmeni İsterim', 'bilmeni-i-sterim-gunduzalp-kayihan-jjx7p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir yıldız gibi kayan ömrümde,

tek durağım sendin.

aramızda samanyolu uzaklığı olsa da

seni bu alemde seven biri var bilmeni isterim.

buz gibi günden güne eriyişim,

güneş yakışları kadar acı verse de

bu bedenim güneşe girse de

seni senden çok seven biri var bilmeni isterim

titreyen kalemim bir gün kırılsa da,

bedenimi bir sıtma titreyişi sarsa da

gözlerindeki alevle ısınan bedenimle

seni,başkasına ve sana dahi emanet edemeyen

seni kendisinden çok seven biri var bilmeni isterim', 'bir yıldız gibi kayan ömrümde, tek durağım sendin. aramızda samanyolu uzaklığı olsa da seni bu alemde seven biri var bilmeni isterim. buz gi...', ARRAY['Türk Edebiyatı','Şiir','Gündüzalp Kayıhan']::text[], 8.5, '{"poet":"Gündüzalp Kayıhan","poet_slug":"gunduzalp-kayihan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bilmeni-isterim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceyi Yürüyen Adam (düz yazı)', 'geceyi-yuruyen-adam-duz-yazi-orhun-basat-bln5t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceyi yürüyen adam, ruhu acıkınca, ilk molayı çocukluğunda verdi. Oturup bir ilkokul sırasına, öğretmenlerinin ilk öğretilerini anımsamaya çalıştı. Aklında kalan bir şey yoktu; bir okul şarkısından başka: “ çiçekli bahçemizin yollarında koşarken, bu gün okullu olduk sınıfları doldurduk, neşeliyiz (belki, / sevinçliyiz / di kelime; tam olarak hatırlayamadı)  hepimiz, çünkü okullu olduk... “. Böyle bir şeylerdi .

	Oysa; ne evin bahçesi koşacak kadar büyüktü  ne de çiçekliydi. Okula başladığı için sevinip sevinemediğini de bilemedi. Yeni bir yoldu sadece yürünmesi gereken. o gün başlayıp, bir fakülteden mezun olana kadar sürecek on altı sene. Yedek subay okulunu da sayarsak, de ki onyedi..

	Yan sırada oturan adam, “ Sen, kaymakamın oğlu değil misin “ diye sordu.

	“ Evet “ dedi, geceyi yürüyen adam. “ Bu benim suçum değil, benim seçimim de.. “

	Kalktı sıradan, bahçedeki çocukluk seslerini çiğneyerek, dışarı çıktı.  Genç bir şair 

kardeşinin *  çok sevdiği dizeleri geçti aklından : “ En büyük ihaneti çocukluğuma yaptım / Büyüdüm..   “..   Okul bahçesinin bittiği yerde bulutlar başlıyordu. Bu yüzden nerede olduğunu anlayamadı, ilk bulutun içine yürüdü. Güneşi göremese de terlediğini farketti. Biraz ferahlayabilmek için, okul yıllarını silkeledi üstünden, bir kaç eski sevdanın tozu kaçtı gözüne, yaşardı. Yanaklarından  süzülen gözyaşını alıp, yüreğinin tavan arasındaki çeyiz sandığına koydu. 

	Bir sokağı andırır gibi, birbirine yanaşık duran iki bulutun üstünde solmuş resimler asılıydı. Hepsinin altında, isim çerçeveleri içinde “ özlem “ yazıyordu, nedense. Pek bir anlam veremedi ama cız etti bir yerleri, farketti. Sokağın ismi var mı diye bakındı, yoktu. Adına bakılmadan geçilen sokaklardan biri gibiydi işte, o kadardı. “ Bizi nereye götürdüğünü bilemediğimiz sokaklardan biri.. “ dedi. Solmuş resimlerdeki yüzler de pek tanımış gibi bakmıyorlardı zaten. Belli ki kendileri de çekip gitmişlerdi çoktan; bir yerlere ve birilerine. 

	Bulutlar kayboldu birden, yerini, dört bir yanı dikenli tel tel örgülerle çevrili tozlu ovalara bıraktı. Yelkovan dikenleri * uçuşup duruyordu etrafta. Bazıları gelip, orasına burasına çarpıp acıtıyordu , kaçamıyordu hepsinden. Kaçmak istemediğini farketti, üstelik. Dikenlerle birlikte yuvarlandı uzun süre. “ Gerekirse hepinizle yüzleşirim gene. Çekinecek bir şeyim yok benim..” diye söylenip durdu, yuvarlanırken.. “ Pek farkımız yok, rüzgarlarımız farklı sadece. Ben de hepiniz kadar iyi, hepiniz kadar kötüyüm...” 

 Tozlu ovanın bitimindeki  tel örgüye, birlikte takılıp durduklarında, geceyi yürüyen adam; kendini, üstüne yığılmış yelkovan dikenlerinden ayırabilmek için kimliğini çıkardı cebinden. Kimliğin üstünde farklı bir resim vardı, aldırmadan yürüdü. Tel örgünün bir yerlerde bitiyor olacağını var sayarak.

Kimliğini cebine koyarken, cebinin değişik kimlik fotokopileri ve ikametgah ilmühaberleriyle dolu olduğunu farketti. Kimbilir, kaç il ve ilçede, mahallede,  kaç değişik muhtardan kimlik sureti ve ikametgah almıştı bu güne kadar. Böyle birisi, aynı kişi olabilir miydi? ! . “ Beni ilgilendirmez.. “ dedi, kendi kendine.. “ Ben kimim ki? .. “

Tel örgü, biteceğe benzemiyordu. Zaman zaman iyice daralıyor, bazen biraz genişliyor ama bu fazla uzun sürmüyordu. Bir ara, hapishane parmaklıklarına  döndü tel örgüler, neyseki bu da uzun sürmedi.. En dar yerlerinin birinde bir nikah dairesi, onun yanında doğum evi vardı ve inanılmaz kalabalıklar vardı girişlerinde, her ikisinin de.

İçerdekilerse, çıkış kapısını bulma telaşında içindeydiler.

	Bir yerlerde, bir dere çıktı karşısına. yumuşak bir toprağın içinden kaynıyor, giderek genişliyordu. Suları sığdı. ayakkabılarını çıkarıp derenin içinden yürümeye başladı,  ferahlamıştı biraz. Tel örgüler mi bitmişti yoksa? .  Sağına soluna bakındı, duruyorlardı, araları  ıramışlardı  birbirlerinden. Yürüdükçe, tek tük ağaçlar görünmeye başladı, birbirinden değişik ağaçlar.  Kimi en ufak bir esintide bütün yapraklarını kaybeden, kimi en acımasız fırtınalara direnen, kimi; ötekinin gölgesinde kalmış, gelişememiş, kimi; köksüz, kimi hastalıklı, kırılgan, böceklenmiş, bodur.. Başka çaresi yoktu, geçilecekti bu ormanın içinden.. 

	Ormanın ve derenin içinden yürümeye devam etti. Diz kapaklarını bile bulmayan su, akıp gidiyordu sessizce.. Suyun verdiği ferahlık da akıp gidiyordu birlikte. Adam yürüdükçe, su bulanıyordu geçtiği yerlerde.. “ Sığ sular çabuk bulanır..” dedi, kendi kendine.. “  Bu yüzdendir benim denizlere sevdalanmam...”

	Bir keresinde, sessiz bir koya demirlemişti teknesini,  rüzgar , denizin yanağını oynaştıran orta güçte bir karayel olsa da teknenin demirlediği yere ulaşamıyordu. Koy, yanındaki küçük tepelere el vermiş, soyutlamıştı kendini hoyrat kuzey rüzgarlardan.  Dingindi. Adam gibi. 

	Güzel bir siyah zeytin, üzerine güzel bir zeytinyağı gezdirilip, güzel bir kekik ve kırmızı pul biberle harmanlanınca; güzel bir rakı mezesi olmuştur hep. Koyun kumsalından toplanan beş on tane cikcik * de varsa hele, değme rakının keyfine. 

	Cikcikleri bıçağıyla açıp, ufak bir tabağın içine topladı, biraz zeytinyağı döktü üzerlerine, biraz da karabiber. Rakıdan bir yudum aldı. Etrafına bakındı. Koyu çevreleyen tepeler, mutsuz insan yüzleriyle doluydu. Onlara seslenir gibi  “ Hayat, bu işte.. “  dedi.

 “ Kendinle barışıksan ve yalnızsan, ne problemi olur ki insanın.. “. Tepelerdeki yüzlerin çoğunluğu, başlarını sallayarak onayladı adamı.

	Devam etti: “.. Bir çoban düşünün, ne kadardır bir çobanın dünyası? Azığı, kepeneği ve kavalı yanındaysa, kurt girmemişse sürüsüne, ne ister başka, çoban? ! ! . Otlağını, dağlarını, yaylarını bilir, o..  Az bilir.. Bu yüzdendir huzurlu ve mutlu oluşu.. 

Bu yüzdendir  benim,  bildiğim her şeyi unutmak isteyişim.. “. Gene, baş sallandı tepelerden, azdı karayel..

	Dere aniden bitti. Önünde, ikiye ayrılan bir yol belirdi. Yolun biri, çiçeklerle bezeli, rengarenk çiçeklerle süslü, uçuşan ezgilerin , tek tük çiftlerin gezindiği güzel ama kısa bir yoldu. Olduğu yerden bile sonunu görebiliyordu yolun.  Keçiboynuzunun içine serpiştirilmiş bal kadar bir şeydi bu yol.

	Öbür yol, tozlu, zorlu, inişli çıkışlı, sarp geçitler olmasına rağmen daha kalabalık ve daha uzundu. Yürüyenler, pek hoşnut görünmese de, zamanla içlerinden bir kaçı yere düşüp kalsa da, gene de yürüyorlardı durmadan. Her atılan adımdan sonra, yolun arkada kalan kısmı siliniyor ve asla geri dönülemiyordu. Zaman zaman yollarına çıkan  – büyük olasılıkla, öbür yoldan karışan – çiçek kokularını, notaları fazla önemsemeden, fazla uzun sürmeyeceğini bilerek ama kabullenerek , asık yüzle ama nedense hem mutsuz görünüp hem de fazla acele etmeden, ağır ağır yürüyorlardı.

	“ Geri dönmek..” dedi, geceyi yürüyen adam; “...  bir tek klavyenin tuşlarında mümkün.. “. Sonra, yolun sonunda görülen parlak ışıklara bakmamaya çalışarak, kalabalığa karıştı..

	Ayakkabıların da dereye girdiği yerde unutmuştu, üstelik..  30.03.05 * 

    

* murat köse, istemsiz ihanet, hayal dergisi, sayı 1, sayfa 56

* cikcik: beyaz, yuvarlak; kum midyesi de denilen bir çeşit midye.

* yelkovan dikeni: yel önünde uçuşan dikenler.

* 30.03.05 (doğum günüm)  :))', 'Geceyi yürüyen adam, ruhu acıkınca, ilk molayı çocukluğunda verdi. Oturup bir ilkokul sırasına, öğretmenlerinin ilk öğretilerini anımsamaya ...', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/geceyi-yuruyen-adam-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitti', 'bitti-suleyman-yavuz-1gbgf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yazamıyorum durdum 

Bak halime bilmem ne oldum

Durdu elim 

Tutuldu dilim 

Düşünemiyor ki artık şu beynim

Ne oldum yar ne oldum

Azgın bir aşk seliydim bak 

Bende duruldum

Yoruldum artık yoruldum

Tutul uzvum 

Durdu nabzım

Artmıyor eski gibi yüreğim

Kurudu kalemim 

Soldu defterim 

Söndü ateşim

Eridim mum misali

Bittim işte 

Bilmem ne zaman dönerim

Belki bakarsın bir köşede 

Bende ölürüm giderim', 'Yazamıyorum durdum  Bak halime bilmem ne oldum Durdu elim  Tutuldu dilim  Düşünemiyor ki artık şu beynim Ne oldum yar ne oldum Azgın bir aşk...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Yavuz']::text[], 8.5, '{"poet":"Süleyman Yavuz","poet_slug":"suleyman-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bitti-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoban oğluna..(Ağıt)', 'coban-ogluna-agit-tuncay-akdeniz-fag01', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'AŞIK MURAT ÇOBANOĞLUNA (AĞIT) 

Yirmi altı martta yürüdün hakka

Tarih iki bin beş yıl Çobanoğlu

Doğruyu söylerdin sevdiğin halk''a

Susturma sazını çal Çobanoğlu

Tarih elli birde gördü rüyayı

Hakkın pınarından içmiş badeyi

Mecnun gibi çekmiş aşkı sevdayı

Sevdayla coşardı sel Çobanoğlu

Sevdayı sır etti sardı mendile

Duyguyu sazıyla okuttu tele

Çiçek,çiçek gezer konardı güle

Kovanlar peteksiz bal Çobanoğlu

Peh,pehle köroğlu leb değmez dile

Muamma deryası benzerdi göle

Dallar ses vermiyor bülbüle çile

Bülbüller figanda gül Çobanoğlu

Gönül sarayının yıkılmış hanı

Dağlar yas tutuyor yayla zamanı

Sen ağlattın Iğdır Kars Ardahan’ı

Sazında inliyor tel Çobanoğlu

Edirne den vana diyordu vatan

Anadolu baştan başa bir destan

Rahmetli babandı aşık gülistan

Koca çınar gibi dal Çobanoğlu

Söylerdi dünyanın yoktur tapusu

Bir günde bozulur ömrün yapısı

Aşıklar ustası gönül kapısı

Kars Ardahan gibi il Çobanoğlu

Çobanoğlu derdi güller solacak

Sen ölmesin eserlerin kalacak

Tuncay sanma dünya benim olacak

Rahmet olsun sana bil Çobanoğlu

					26.03.2005

Tuncay Akdeniz', 'AŞIK MURAT ÇOBANOĞLUNA (AĞIT)  Yirmi altı martta yürüdün hakka Tarih iki bin beş yıl Çobanoğlu Doğruyu söylerdin sevdiğin halk''a Susturma sa...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/coban-ogluna-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadere Bak', 'kadere-bak-fatih-ozkonyali-tn3eq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tunç burçlara sancağı çekmeli asker

Hıncını almadan zaman burgusu

Kılınçlar çıkmış kından, cenge meydan gerek,

Vur gürzü kaçmaz bu seferde kutlu ölüm, 

Keten tohumlu tarlalara yatır yüzü

Tarihinle dolsun satır satır öksüz semalar,

Nereye yorgun savaşçı, nereye talihsiz adam? 

Çelik nidalara yer yokmuş, kadere bak.

Gün sökerken tepeden verilir sâlâlar,

Gözümün önünde kundakta bebekler,

Haydi kalk deyip yollar uzaktan el sallar! 

Ve yolları kollayan boynu bükük selviler,

Kurumuş dallar, kırılmış kollar,

Gözlerim tek noktada, bölünür kırk kere satıhlar, 

Heybemi sırtlayıp kaçıyorum başımı eğip,

Dönüşüm var ki geri yıldızları bileyip,

Boynumu uzatsam yeridir urganlara

Gövdeler üstünde ser yokmuş, kadere bak.

Derlerdi ki söz var dağları deler,

Yiğit var ki afakı tuş edip beler,

Kıvılcım açarmış nalında atların,

Açtım her dürülü sırrı kavuştum sandım,

Meğer söz uçmuş kağıtlar düşünce mahpusa,

Susa susa ağıtlarda lal olmuş yiğitler,

Kalkanı düşmüş savaşta yaralı adam,

Sancağı dikilmiş tahta saltanatların,

Güneşler de sönermiş; er yokmuş, kadere bak...', 'Tunç burçlara sancağı çekmeli asker Hıncını almadan zaman burgusu Kılınçlar çıkmış kından, cenge meydan gerek, Vur gürzü kaçmaz bu seferde k...', ARRAY['Türk Edebiyatı','Şiir','Fatih Özkonyalı']::text[], 8.5, '{"poet":"Fatih Özkonyalı","poet_slug":"fatih-ozkonyali","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kadere-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsin', 'sen-varsin-leyla-isik-c0koa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutluluk,

         Dudaklarimda sarki bu gece

            Yuruyorum islak kaldirimlarda

                  Yagmur yagiyor,

                       Aldirmiyorum….

                           Suzuluyor saclarimdan damlaciklar

                             Uclarinda sen varsin.

                            Nereye gitsem ardimda ayak seslerim

                       Bir perde aralaniyor sisli gecede

                 Bir isik suzuluyor karanlik sokaga

            Bugulu penceremde sen varsin

                                Bu sokakta,

                            Bu kaldirimlarda

                      Sokaga suzulen isiklarda,

             Uzaktan uzaga soylenen sarkilarda

                               Sen varsin.

                            Huzunlu degil…

                    Sevginle sarhos gonlum.

                               Aradigin

                              Ozledigin,

                         Benim biliyorum.

                      Artik yalniz degilim

                       Tesellim sen varsin….

                                                       Leyla Isik', 'Mutluluk,          Dudaklarimda sarki bu gece             Yuruyorum islak kaldirimlarda                   Yagmur yagiyor,                   ...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-varsin-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakış', 'bakis-volkan-yoruc-05vow', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bakışki hayale değer ömrümde

Ve ne ömürki karşımda sen varsın sessizce

Geceler artık aydınlıktır benim

Sen varsın ya işte gönlümde

Bir bakışki arşa değer gayrı yüreğim

Yağan yağmurlardamı ıslanırım

Yahut esen rüzgarlardanmı sakınırım

Şimdilerde mevsim mevsim cihanda dolanırım

Bir bakışki sana erişirde yüreğine sığınırım', 'Bir bakışki hayale değer ömrümde Ve ne ömürki karşımda sen varsın sessizce Geceler artık aydınlıktır benim Sen varsın ya işte gönlümde Bir b...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bakis-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulut Bulut', 'bulut-bulut-i-smet-barlioglu-kazhu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beyaz bulutları albüm eyledim kendime

Açıkmaviler üstünde,

Seni çeviriyorum sayfalar yerine bulut bulut,

Kimisinde bir güz güneşi vurmuş gülrengi yüzüne,

Kimisinde fırtınalar içinde saçların,

Kimisinde dudaklarında parlıyor güneşler,

Kimisinde rüzgarlarla elele gidiyorsun,

Sanki hiç darılmamışsın bana; 

Gülüyorsun.

Bir şarkıdır olmuşsun rüzgarlara işleyen,

Deniz maviliklerinde bir alçalıp bir yükselen,

Pervazlanıp giden akşam güneşine doğru,

Varlığın yanık yüreğimde ibrişim,

Anıların gözlerimde yaş,

İçimde sanki sana kavuşabilecekmişim gibi

Bir telaş.

Çırpınır dururum sana doğru,

Güneş altında kıvrana kıvrana çarmıhlarımda,

Çatlayıp kanayam dudaklarımda karasevdam,

Delik delik delinen ciğerlerimde özlemim,

Kırılası elim kırılası elimden uzak,

Kırılası ayağım ayağımdan,

Talihsiz başım zavallı bedenimden,

İşte bir adındır dökülüp durur acılarım arasında

Dilimden.

(KANAMA YÜREĞİM isimli Serbest Şiirler ''inden > 85-86/100)', 'Beyaz bulutları albüm eyledim kendime Açıkmaviler üstünde, Seni çeviriyorum sayfalar yerine bulut bulut, Kimisinde bir güz güneşi vurmuş gül...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bulut-bulut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelliklerin', 'guzelliklerin-i-smet-barlioglu-7r8fp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben seni, denizi gözlerinde taşıdığın için seviyorum,

Yosun kokularını saçlarında,

Sedefi, ellerinde,

Fildişiyi yüzünde,

Güneşi dudaklarında taşıdığın için seviyorum,

Onun için kafiyeler arıyorum hasretinde

Ve melodiler acımasızlığında,

Bu yüzden baş başa oturuyorum hayalinle, sabahlara kadar

Yokluğunda.

Nesini tamamlayabilirim eksiksiz konuşan Havva ‘nın,

Kılı kırka yaranın, herhangi bir davranışında,

Baktığını görenin, dinlediğini duyanın? 

Ben bir seninle dünya olduğunu fark etmişim

Dünyanın.

Konuşurken kekeleyişin ne güzel,

Sözcükleri bulamayışın,

Şaşırışın,

Sözcüğü söxcük yerine söyleyişin ne güzel,

Ne güzel yanlışlıkların,

Ne güzel kendi değerini bilmeyişin,

Gelseydin; 

Beni bunca yıldır karasevdalara salar mıydı

Gelmeyişin? 

(KANAMA YÜREĞİM isimli Serbest Şiirler ''inden > 89-90/100)', 'Ben seni, denizi gözlerinde taşıdığın için seviyorum, Yosun kokularını saçlarında, Sedefi, ellerinde, Fildişiyi yüzünde, Güneşi dudaklarında...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/guzelliklerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinle ey sevgilim', 'dinle-ey-sevgilim-mehmet-ekici-c5nf4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sonbahar mevsimi gibi soguktun 

Bana hep uzak hep ucurum kenari

Yollarin hep cikmaz hep karanlik

Ben sana ömrümü vermeye hazirken

Senin yaptigina bak 

Gel gör su perisan halimi 

Beni bir enkaz gibi

Yollara savurdun

Eserinle övünebilirsin

Bakip bakip gül halime 

Sanada bu yakisir

Ben her aciya gögüs gerdim

Elbet bu aciyada katlanir

Katlanir ama ya bir akil hastanesinde yada 

Ezilmis bir gencin mezar basinda 

Son bulur...

Gözlerim cökmeye basladi artik

Unutmak icin kendimi ickilere verdim

Olmuyor yapamiyorum

Bu delikanli unutamiyor seni

Uykularim bölünüyor gece yarilari 

Sen düsüyorsun aklima 

Nerdesin ne haldesin

Bilmek istiyorum 

Vefasiz

                       SevgiliM

Ömer Kuş''tan alındı', 'Sonbahar mevsimi gibi soguktun  Bana hep uzak hep ucurum kenari Yollarin hep cikmaz hep karanlik Ben sana ömrümü vermeye hazirken Senin yapt...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ekici']::text[], 8.5, '{"poet":"Mehmet Ekici","poet_slug":"mehmet-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dinle-ey-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak, şair, çiçek;', 'toprak-sair-cicek-mutlu-ayar-9n9gu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '“I

Sevgilim 

       bir şiiri çiçek sandım 

                                   suladım bugün

II

Siz Türkçe’yi kollamayanlar

Çiçekleri Türkçe kokladınız mı 

                                                  hiç? 

III

Bir imgenin anavatanını bulamazsan 

                bir kağıda yaz, göm toprağa...

IV

Üstü pis, sarı sakallı bir adamdı; 

     sordum: Neden dedim, neden

neden tutuyorsun o kitabı yağmura

     çok seviyorum bu kitabı, dedi… 

V

Bundanmış meğersem 

       Hoşlanması sevgililerin 

                    yağmurda dolaşmaktan...

VI

Ben şiir yazmasaydım

        Bilemezdim şairlerin

                Toprak olduğunu 

                     önceki yaşamlarında.

VII

Ben şiir yazmasaydım

                Yazdığım şiirler olmazdı...', '“I Sevgilim         bir şiiri çiçek sandım                                     suladım bugün II Siz Türkçe’yi kollamayanlar Çiçekleri Türkçe...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Ayar']::text[], 8.5, '{"poet":"Mutlu Ayar","poet_slug":"mutlu-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/toprak-sair-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sema', 'sema-naime-erlacin-gsh7g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çoktu bir zamanlar

kartala uçacak sema

öyle böyle derken

kalbur saman içinde

epridi hikâyeler

yok şimdi o bildik gök 

mühürlendi külliyen

ayıbı kayıp bir ülkede

uçma dersleri 

ezber ediliyor

göğünü tanıyor büyük kuş

(30 Mart 2005)', 'çoktu bir zamanlar kartala uçacak sema öyle böyle derken kalbur saman içinde epridi hikâyeler yok şimdi o bildik gök  mühürlendi külliyen ay...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sema-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GarbınYalı...', 'garbinyali-i-brahim-ozcan-rs07o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Varsay ki büyüksün 

Var say ki erişilmez

Tanrıdan da devasa

Yılan donunda yenilmez asa

Velî olsan ne yazar

 Nebî olsan ne

Bandıra bandıra romana şiire

Yazın diye yutturdun ya

Anal yangılarını yıllarca

Bükebilir misin

özümün bir şahandaz dizesini

Gezdikçe akçe etmez

şiiriyetin pazar pazar

Unutma kabri olmaz hazretlerin

Künyesi yazarsa 

kulun mezar taşında yazar

Sen ey Payîtaht''ın sönük mumu

Sırça köşkün efemine maymunu

Boğaza nazır şimalî sofraların

kanlı kürdanı

Garbın yalı  bitti

Germeşikler şarkta şimdi 

Yağdıranlar mı sürdü seni

Bir Fırat''a bir Dicle''ye 

Kabızlıktan gitme diye

Yalnızlıktan yitme diye...

Mersin / 28 Mart 2005



Mini sözlük

Şahandaz:(Türkmence)       Coşkun, alçak gönüllü, ilhamlı, iyimser, yiğit..

Şimalî: Kuzeye özgü, kuzeyle ilgili

Şiiriyet: Şiir olma özelliği, şiirsellik..

Pöslük:Hayvan gübresi yığılan yer, Çöplük,.(Öz Türkçe TDK''da yok)        

Yal   : Köpek yemi

Yağdıran: Asagi Yel (Rüzgâr)    (TDK sozlukte yok)       

Germeşik: Yabani kızılcık (!)', 'Varsay ki büyüksün  Var say ki erişilmez Tanrıdan da devasa Yılan donunda yenilmez asa Velî olsan ne yazar  Nebî olsan ne Bandıra bandıra ro...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/garbinyali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Şikayetname 20 / Karalama Dosyaları...', 'sikayetname-20-karalama-dosyalari-naime-erlacin-gyite', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'uzun bacaklı tayın

ihtişamlı koşusunu banardık 

tedirgin akşamlara 

talandan korurdu çadırlarımızı

taze bir umut muştulardı 

erken ayazlara düşen 

ilk yağmur damlası

pusuda saklı hançer ve yüzümüze sırıtan

kara suratlı mağaraya kişnerdi küheylân

her şahlanış

içeriden yağmalanmış bir toprak parçası

arkamızdan kovalardı karalama dosyaları

orada gizlenirdi şiir

insafsız bir savaş artığı 

ganimet adaklar misali 

alnımıza sürülürdü harfin kanı

anılar tüterdi bacalardan 

ki kırlaşmışlardı

unutmuştuk çünkü insanca yaşlanmayı

ilân tahtalarına yapışırdı suretimiz

takvimleri ağlatırdık biz

b u   y ü z d e n “genç” koydular adımızı

“ölümsüz” dedi birileri

biraz alaycı

biraz küçümser bir tavırla 

b u   y ü z d e n  çözümsüzlük gurbetiydi

yanıtsız soruların tebliğ edildiği 

kayıp bütün adresler

başıbozuk 

isyankâr ve çılgın  tay

tıslayan gece yılanını b u   y ü z d e n

gündüze şikâyet ederdi bıkmaksızın 

dağlanırdı dudaklar karalama dosyalarında

bıçak 

rüzgâr 

ve kan

bu kadardı yaşam 

geçmişi geleceğe bağlayan 

ak kâğıttan farklı

sıradan bir zincir halkası

yoktu bir anlayan

kutsal aşkın kendisi 

ve aşkı bilenden başka 

(30 Mart 2005)  

(''ŞİKÂYETNAME'', Hayal Yay. Temmuz 2010, Sayfa 34)', 'uzun bacaklı tayın ihtişamlı koşusunu banardık  tedirgin akşamlara  talandan korurdu çadırlarımızı taze bir umut muştulardı  erken ayazlara ...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/sikayetname-20-karalama-dosyalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezatlık Gemi', 'mezatlik-gemi-i-brahim-ozcan-y1xpg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söktü yine sikkesini

Ürkek mezatlık gemi

Kaptan kayıp,

Filikalar azatlık,

Tayfalar dünden firari..

Birazdan vuracak kayalık

Girerken koynuna ummanın 

Sarılsa da nafile, boynuna asumanın

Birazdan anlayacak,

Ne yanı iskele, ne yanı sancak? ..

Birazdan anlayacak...

Mersin / 29 Mart 2005', 'Söktü yine sikkesini Ürkek mezatlık gemi Kaptan kayıp, Filikalar azatlık, Tayfalar dünden firari.. Birazdan vuracak kayalık Girerken koynuna...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mezatlik-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Çıraklık!', 'ciraklik-naime-erlacin-9jmx2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dinle şairi! 

“melâl”e karşılık bulamamış

ben de bulamamıştım

“gönül”ün bir eşi olmadığı gibi

yaban dillerde

günlerce

geceler boyu harf yazdım

biçerdöver oldum 

elifbanın içinde

usta hurufi''de*

benden önce ateşlemiş fitili 

bilemedim! 

hani sözden önce şiir

şiirden önce harf vardı

yaşamdan önce gelen ölüm gibi

amacım harfin sırrına varmaktı

bir dolu zarar ziyan

yakılacak söz var şimdi

bir dolu sancılı tanık

sel suyu heyhat 

çıraklık ah! 

ne zor işmiş meğer

bilemedim! 

(*)      Hurufi Şiirler: Hilmi Yavuz

(30 Mart 2005)', 'dinle şairi!  “melâl”e karşılık bulamamış ben de bulamamıştım “gönül”ün bir eşi olmadığı gibi yaban dillerde günlerce geceler boyu harf yazd...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ciraklik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimin Ucu Telli Mektubu', 'yuregimin-ucu-telli-mektubu-emine-deniz-hkux0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağlara da hüzün düşer zamanla,

            Kekikler döl vermez olur sevdiğim...

            Aşklara da yüzün küser zamanla

             Dilinde gel kalmaz olur sevdiğim...

. Bilmezler, kör bir incir kuşuyla aynı kaderi paylaştığımı da sorarlar düşkünlüğümü türkülere,sorarlar _’’bu yol nereye? ’’

    Islıklar sendeliyor dudaklarımın köhne sokaklarında.Yalancı öpüşlerden geriye kalan...Kendi hayatlarına yabancı,kendi sevdalarına sahipsiz itler uluyor karanlıklarımda.Tut elimden ve götür beni doğuramadığım masum çocuk...Çok uzaklara.Kendime yabancılaşmadığım uzaklara.Sevgisizlik damarlarımı çatlatmadan,götür beni.Buralar bize göre değil.

    Kimbilir,hangi gidişinde yok olacağım? Hangi serüvenin merdivenlerinde alacak canımı azrail...Öpmeye doyamadığım dudaklarında terlerken dudaklarım nerede olacak yüreğin? Ve bir türlü çözemediğim beynin...Hangi kalbin ufuklarına doğru çıkmış olacak yola.Ben elimde yırtılmaya yüz tutmuş mektupların anısına ağlıyorum hala.Sevdiğimiz türküyü söylüyor dudaklarım umarsızca. 

    Şimdi sen dönüşü olmayan bir yoldur gidiyorsun..Sana dön diyemiyorum.İçimden güzel bir günün hayali de kayıyor seninle yıldızlara doğru.Tut onları ellerinden.Öksüz bırakma düşlerimi.Ben yaşarım düşsüz,yaşarım bildiğimce...Kim yaşamış ki dilediğince.Aynı gökyüzünün iki yalnız yıldızı...Sana doğru attığım her adım beni kilometrelerce uzağa atıyor.Bu çaba, bu uğraş biliyorum boşuna.Unutulur herşey diyenler ne kadar unutmuşsa yalandır,yalandır zamanın ilaç olduğu...

   Ben kör bir incir kuşuyum unutma...seni aldıkları gün çizdiler ucu küflü bir iğneyle gözlerimi.Bu yüzdendir  yanıklığım dağlara...Elimi tut,tut elimi bırakma beni.Düşüyorum...

Sevdiğim,

yüreğimin ucu telli mektubu

.Nerdesin?', 'Dağlara da hüzün düşer zamanla,             Kekikler döl vermez olur sevdiğim...             Aşklara da yüzün küser zamanla              Dil...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuregimin-ucu-telli-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kâhanladıkça Kaderimi', 'k-hanladikca-kaderimi-i-brahim-ozcan-muhw6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kâhanladıkça kaderimi…

Yıraklaşır börtü böcek 

Kavurur kav meşesi 

Zulmetinde dağlarım? ..

Gelinparmağı gözlerinde

Gerdankıranlar gemrenir 

Gelinhavası gergeçimde

Gezer gezer ağlarım

Yıkar dağ selleri kefenimi

Evlek evlek balçıkla

Sarar sam yelleri bedenimi

Gever gever çağlarım

  Mersin /30 Ocak 2005

Mini sözlük  

                            :

Kâhanlamak: Çapalamak, kazmak

Yıraklaşmak: Uzaklaºmak, ıraklaşmak

Gerdankıran: Kuş

Gemrenmek: Dişlemek

Gelinhavası: Hafif çalkantılı deniz

Gever gever: Oluk oluk

Gergeç     : Tarih

Gezek       : Otlak, Koyak

Zulmet       : Karanlık 

Evlek         : Tarlada suyun akması için açılan yol, 

                       tarlanın bölünmüş kısmı', 'Kâhanladıkça kaderimi… Yıraklaşır börtü böcek  Kavurur kav meşesi  Zulmetinde dağlarım? .. Gelinparmağı gözlerinde Gerdankıranlar gemrenir  ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kahanladikca-kaderimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgeler', 'golgeler-yasar-pullu-791ty', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabahı yaralı bir bahar

Kuşları ölü, Elleri kan

İçimize düştü bu şivan

Ağızda  boğuldu dil

Ondandır susman

Ooy yaralı aslan

nemli bir çığlıktır şimdi

yüreğinde Ardahan

ve eyy yar

bizi sana emziren obalar

yetimdir, kimsesizdir 

bilirmisin ki

bizim çocuklar gölgelerinden önce

ve kendi iklimlerinde

büyümeden ölürler

...

Şimdi yiterecek yüzüm rengini

Kıyılarımda demirleyen 

Bu portatif hayat

Kelepçeler, hücreler beni

Elsa nın gözlerine aşık mı olunur

Bizi biz eden bu deli rüzgar

Doldururken hücrelerimi

Başı karlı iri dağlar sevmeliyim ben

Kokumu saklarken 

En mahrem yerlerinde

Kocaman kalçalı kadınlar

Yakmalıyım barutu koyup ömrüme

Yeniden doğursun beni

Bu kabaran bela

Yağmalanmış yurt, bu yağmur bu kök

Ve eyy yar sen üzülme

Her ateş 

Yakacak bir karanlık bulur kendine', 'Sabahı yaralı bir bahar Kuşları ölü, Elleri kan İçimize düştü bu şivan Ağızda  boğuldu dil Ondandır susman Ooy yaralı aslan nemli bir çığlık...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/golgeler-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...İfşaat...', 'i-fsaat-naime-erlacin-k7jzb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dubaları battı bu sahilin

aşırılığı fısıldıyor deniz mütemadiyen

tekneler küreksiz 

mendirek virane

can havliyle haykıran biçare derinlik

metafordur artık maviye

kirli suya düştü kulak zarlarım

sayrılıktan ağlıyorlar şimdi

kimse kanamadı böyle

ona yataklık eden yürekçe 

kanatmadı kendini

gideceğim

üzülme 

israf olmasın duygu 

sesim yine çınlayacak cümle âlemde

susturacak sirenleri nefesim

lirik bir ezgi yükselirken suyun rahminden

sahile koşan ilk rüzgârda ara beni

elbet dokunacaktır tenine parmak izlerim 

bölük pörçük 

eksik tam

tüm sevdalar ve kutsal aşk adına

temiz sularda boğulmak da haktır! 

gittim

turkuvaz bir isyanın uyanışında

katli vacip olmuştu sığ kıyıların

suç delilim albatros kanatları

görkemli bir kuşun 

ruhunu çaldığımdandır açığa gidişim 

anla! 

anla ki ne olsun

ifşa ediyorum kendimi...

(30 Mart 2005)', 'dubaları battı bu sahilin aşırılığı fısıldıyor deniz mütemadiyen tekneler küreksiz  mendirek virane can havliyle haykıran biçare derinlik me...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ifsaat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Hüzün de Gider...', 'huzun-de-gider-naime-erlacin-ecshk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'küçük ölümlere sığmaz devasa hüzünler

kenar süslü kitapların satır aralarına hiç

mor bir hüzündür her yerde adı

derin izi acı''nın

anlamlı

ne zaman kalp çarpıntısından ayrı düşse

gebelik sancılarından yaşamın

kaybolur evrende

el kapısında bir yetim kadar mahzun 

bir kıyım ki öyle 

serseri savruluş

şiirin haylaz militanından 

boşa akan cephane

bükülür boyun

güz yapraklarından çalıntı 

görkemli bir ölümdür artık mor

yağmalanır toynakları içimizin

kayboluş saatleri vurur deliler ormanında

anarşiyi ezberletir sessizlik

incirin sütü kara! 

cinnete gider hüzün 

adres sormadığı gibi 

ardına bakmayan aşk kadar mağrur

mağdur 

ve tek başına

o halde gerçekleri söylemeli çocuklara

(30 Mart 2005)', 'küçük ölümlere sığmaz devasa hüzünler kenar süslü kitapların satır aralarına hiç mor bir hüzündür her yerde adı derin izi acı''nın anlamlı ne...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/huzun-de-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyütmeli', 'buyutmeli-i-brahim-ozcan-mvepu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sert taşlarda büyütmeli 

Akçamların mert köklerini 

Boz toprakta değil

Kuşların gökleri sevdiği gibi

Yalçın koyaklarda büyütmeli 

Akşamları sevdayı.

Tarlada, bayırda, kıraçta değil

   Mersin / 30 Mart 2005', 'Sert taşlarda büyütmeli  Akçamların mert köklerini  Boz toprakta değil Kuşların gökleri sevdiği gibi Yalçın koyaklarda büyütmeli  Akşamları ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/buyutmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle', 'bekle-hidayet-avsar-6xtic', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni bir yaz gecesinde,

Ayın on dördüne inat

Parlamandan bilirim.

Yıldızlar parçalanır,

Okyanuslar kabarır aydınlığınca.

İrkilirim...

Işıklar söner,

Korku, aşık bedenlerin büyüsüdür.

Bir köşeye çekilirim...

Düşün ki; 

Son rüzgarın savurduğu

Sararmış son yapraksın...

Bekle beni

Gelirim...', 'Seni bir yaz gecesinde, Ayın on dördüne inat Parlamandan bilirim. Yıldızlar parçalanır, Okyanuslar kabarır aydınlığınca. İrkilirim... Işıkla...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bekle-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskandım', 'kiskandim-tuncay-akdeniz-0sxde', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kokunu güle benzettim

Güllerden seni kıskandım

Gül dermeye el uzattın

Dallardan seni kıskandım

Şu gözlerin bak seline

Çağlayıp aksan gölüme

Geçerim rüzgar önüne

Yellerden seni kıskandım

Başını koysan dizime

Gözlerin baksa gözüme

Nazar deymesin yüzüne

Ellerden seni kıskandım

Tuncay için dertle dolu

Mekan tuttum gurbet eli

Mecnun gibi oldum deli

Çöllerden seni kıskandım', 'Kokunu güle benzettim Güllerden seni kıskandım Gül dermeye el uzattın Dallardan seni kıskandım Şu gözlerin bak seline Çağlayıp aksan gölüme ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kiskandim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül kara', 'gul-kara-hidayet-avsar-pq2gd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnız bırakın canlarım,

Sular sel oldu taştı.

Yalnız bırakın beni,

Yaşım yüzbini aştı.

Neymiş bu dünya böyle,

Ağla kara, gül kara.

Geçmiş günler meğerse,

Yol ver artık dağlara...', 'Yalnız bırakın canlarım, Sular sel oldu taştı. Yalnız bırakın beni, Yaşım yüzbini aştı. Neymiş bu dünya böyle, Ağla kara, gül kara. Geçmiş g...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gul-kara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adalet(!)', 'adalet-ahmet-kurt-9ssqh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Oyunlar muhteşem, tezgahlar güzel,

Sana başkasını gönderir mi el,

Bunlar yağmur değil, çamur yüklü sel,

Diye diye dilimizde tüy bitti,

Vatan gitti, millet yitti, din bitti.

Gavura şefkatli, amade, kurban,

Mukaddes değere örtülür türban,

Vaden gelmese de soyulur urban,

Diye diye dilimizde tüy bitti,

Vatan gitti, millet yitti, din bitti.

Talimat gelince esas duruşta,

Gözü cebinde ki en son kuruşta,

Efendiye hizmet için yarışta,

Diye diye dilimizde tüy bitti,

Vatan gitti, millet yitti, din bitti.

Adalet diyerek hırsızı kollar,

Vurgunda talanda herkesi sollar,

Sade yandaşına açılır yollar,

Diye diye dilimizde tüy bitti,

Vatan gitti, millet yitti, din bitti.

Gülücük dağıtır, sempati toplar,

Haktan söz edince yerinden hoplar,

Biraz diklenince verilir haplar,

Diye diye dilimizde tüy bitti,

Vatan gitti, millet yitti, din bitti.

Kurdoğlu üzülme bunlar çanakçı,

Toplamış yanına üç beş yardakçı,

Kimisi acilci, kimi icapçı,

Diye diye dilimizde tüy bitti,

Vatan gitti, millet yitti, din bitti.', 'Oyunlar muhteşem, tezgahlar güzel, Sana başkasını gönderir mi el, Bunlar yağmur değil, çamur yüklü sel, Diye diye dilimizde tüy bitti, Vatan...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/adalet-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğrusu bu', 'dogrusu-bu-tuncay-akdeniz-dgo2s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eğer doğru yola varmak istersen

Zaman lazım mekan lazım hal lazım

Eğer bir topluma girmek istersen

Edep lazım erkân lazım yol lazım

Gidip gurbet eli mekan tutarsan

Vatandan sıladan ayrı kalırsan

Oturup arz-ı hal name yazarsan

Kağıt lazım kalem lazım pul lazım

Her şeye kadir''dir emir buyuran

Diyor kulum değil insan ayıran

Bir avuç topraktır gözü doyuran

Kazma lazım kürek lazım bel lazım

Cahille oturup eyleme sohbet

Dinlemez sözünü tutmaz nasihat

Doğru söylemeye edersen gayret

Mana lazım kelâm lazım dil lazım

Tuncay-i yaratmış beşer birisi

İçinde var ise Allah korkusu

En güzel şey insanların sevgisi

Sevgi lazım iman lazım kul lazım', 'Eğer doğru yola varmak istersen Zaman lazım mekan lazım hal lazım Eğer bir topluma girmek istersen Edep lazım erkân lazım yol lazım Gidip gu...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dogrusu-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-hidayet-avsar-nt7kq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben bilmedim kıymetini,

Kıymetini bilene git.

İlim saydım zahmetini,

Zahmetini çekene git.

Sanma gelir ömrüne yaz,

Sanma biter bir gün ayaz,

Yaz deftere, beni de yaz,

Sana “gülüm” diyene git.

Gönül buysa, al gönlümü,

Soldur gitsin tek gülümü.

Bir gülüşe bin ölümü,

Sefa diye sürene git.

Kimler dikti bu ağacı,

Kökü acı, dalı acı,

Zehir diye ver ilacı,

Zemzem sayıp içene git!', 'Ben bilmedim kıymetini, Kıymetini bilene git. İlim saydım zahmetini, Zahmetini çekene git. Sanma gelir ömrüne yaz, Sanma biter bir gün ayaz,...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/git-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nokta Ve Sonsuzluk', 'nokta-ve-sonsuzluk-altan-arisoy-5zrvk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilebilir misiniz

Her saniye

Ne kadar canlı oluşur yeryüzünde

Suşlar gram artı gram eksi bakteri

Çok hücreli tek hücreli amipsi

Planktonlar ve milyarlarca bitki

Bölünen hücreler çoğalan yaşam 

Değişir herşey her an

Ya da değişmez hiçbir şey

Hiçbir zaman

Bir çiçek açar 

Bin evren doğar

Bir yaprak düşer

Ölür milyonlar

Korkunç bir savaş olur 

Belki bir doğal yıkım

Belki de iklim değişir 

Akdeniz buz olur

Ya da kutuplar erir

Dünyanın sonudur 

Bir nova patlar

Karadelik olur

Enerji bulutsularından

Galaksiler oluşur

Yaratılmak mı

Yoksa bir son mudur

O an

Bir bakteridir

Belki de  bir galaksidir

Doğan ya da ölen 

Sonuç bellidir

Ne artar ne de eksilir evren

İnsanlar yaşar yeryüzünde 

İnsanlar düşünür 

Varlık nedir sonsuzluk ne

Nokta nedir boşluk ne

Ölüm nedir yaşam ne

Araştırıldı binlerce sene

Ve bir yanıt verildi bilgece

Aynı şeydir 

Varlık ve yokluk

Aynı şeydir

Nokta ve sonsuzluk', 'Bilebilir misiniz Her saniye Ne kadar canlı oluşur yeryüzünde Suşlar gram artı gram eksi bakteri Çok hücreli tek hücreli amipsi Planktonlar ...', ARRAY['Türk Edebiyatı','Şiir','Altan Arısoy']::text[], 8.5, '{"poet":"Altan Arısoy","poet_slug":"altan-arisoy","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/nokta-ve-sonsuzluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanırsın ki', 'sanirsin-ki-zumrut-demirtas-cc95y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sanırsın ki; 

kalbim boştur,

şunu bil ki; küçücük

yüreğime bütün sevgileri

sığdırıyorum ben...

şunu bil ki; 

bir kere evet demişim,

dönüşü olmayan yola 

çoktan girmişim,

yürüyorum ben...

ve şunu da bil ki; 

sen aşka aşıksın ama,

aşkı doya doya, kana kana 

ben yaşıyorum ben... 

(ümitsiz aşklara, aşıklara ithafımdır...)', 'sanırsın ki;  kalbim boştur, şunu bil ki; küçücük yüreğime bütün sevgileri sığdırıyorum ben... şunu bil ki;  bir kere evet demişim, dönüşü o...', ARRAY['Türk Edebiyatı','Şiir','Zümrüt Demirtaş']::text[], 8.5, '{"poet":"Zümrüt Demirtaş","poet_slug":"zumrut-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sanirsin-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu vatan bizim', 'bu-vatan-bizim-tuncay-akdeniz-2v71b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu vatan Türkiye Türkün ülkesi

Beş vakit susmayan ezan bir olsun

Laik Cumhuriyetin belli ilkesi

Yönetimde adil düzen bir olsun

Vatana yan bakan olur bin pişman

Tarihlere bakın gösterir nişan

Bilinki suyu uyur,uyumaz düşman

Gizli oyununu bozan bir olsun

Makamlar değişir değişmez düzen

Bir gün belasını bulacak azan

Batil zihniyettir düzeni bozan

Basında gerçeği yazan bir olsun

Her karış toprağı sulandı kanla 

Çok bedel ödedik sayısız canla

Bu vatan kolayca olmadı anla

Şehit diyarında gezen bir olsun

Gurbette sılada özümde vatan. 

Şehit acısıyla, közümde vatan. 

Şarkımda türkümde sözümde vatan

Sazıyla teliyle ozan bir olsun

Tuncay diyor bu vatanı sevmeli

Vatansız yurt olmaz bunu bilmeli

El ele verip de birlik olmalı

Ocakta kaynayan kazan bir olsun', 'Bu vatan Türkiye Türkün ülkesi Beş vakit susmayan ezan bir olsun Laik Cumhuriyetin belli ilkesi Yönetimde adil düzen bir olsun Vatana yan ba...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-vatan-bizim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi ki Doğdun', 'i-yi-ki-dogdun-hidayet-avsar-p9crt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu çayı yan masadan gönderdiler.

Çiçekleri arka masadan.

Bu şiiri ise prenses,

Tavan arasından...

Sevdana sızmış bir ayyaşın

Yüreğinin ağrısından...

Gönderdiler...', 'Bu çayı yan masadan gönderdiler. Çiçekleri arka masadan. Bu şiiri ise prenses, Tavan arasından... Sevdana sızmış bir ayyaşın Yüreğinin ağrıs...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/iyi-ki-dogdun-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düze Çıkmak Hayaldir.! !', 'duze-cikmak-hayaldir-zulfikar-yapar-kaleli-6hwxt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Fakirin karnı aç delikse cebi 

Doymayınca düze çıkmak hayaldir 

Haksızlık üstünden silindir gibi 

Kaymayınca düze çıkmak hayaldir 

Allah''ın korkusu neder birine? 

Sinmemişse kalpten daha derine 

Hakkı adaleti yerli yerine 

Koymayınca düze çıkmak hayaldir 

Hayali ihracaat maya hamuru 

Yapan besmelesiz beynimin uru 

Rüşveti, torpili toplum kamburu 

Saymayınca düze çıkmak hayaldir 

Kiminde zevk safa, acı kimine 

Her işi teslim et ehl-i emine 

Geliri toplumun her kesimine 

Yaymayınca düze çıkmak hayaldir 

Rüşvet memleketi kemiren kurttur 

Enflasyon milletin başına derttir 

Tasarruf tasarruf tasarruf şarttır 

Uymayınca düze çıkmak hayaldir 

Mesaiye evet son hızı verip 

Çalışma şevkinin tadına erip 

Yaptığı yanlışı mutlaka görüp 

Caymayınca düze çıkmak hayaldir 

1994', 'Fakirin karnı aç delikse cebi  Doymayınca düze çıkmak hayaldir  Haksızlık üstünden silindir gibi  Kaymayınca düze çıkmak hayaldir  Allah''ın ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/duze-cikmak-hayaldir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu millet', 'bu-millet-tuncay-akdeniz-wid2n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eğer yaşıyorsak biz bu vatanda

Birlik olsa huzur bulur bu millet

Sevgi saygı hürmet varsa insanda

Büyük küçüğünü bilir bu millet

Cehalettir insanlığın ayıbı

Oku öğren demiş o güzel nebi

İlim-li toplumun olmaz kayıbı

Büyük güçlü devlet olur bu millet

Candan sevse vatanını dini''ni

Düşman gibi sürdürmese kinini

Komşulara sevdirirse kendini

Huzur bulur güven alır bu millet

Tuncay diyor insanları sevmeli

Gönül alıp hatırları sormalı

İyi kötü günde birlik olmalı

Koşar imdadına gelir bu millet', 'Eğer yaşıyorsak biz bu vatanda Birlik olsa huzur bulur bu millet Sevgi saygı hürmet varsa insanda Büyük küçüğünü bilir bu millet Cehalettir ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-millet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişki? ? ?', 'celiski-zulfikar-yapar-kaleli-bqar7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dinle sözümü de sonra yanlış de,

Evde, sokaklarda kız iki türlü.

Doğrusunu bulmak çetin gene de,

Doğrusu, eğrisi söz iki türlü.

Helal ile haram girmiş iç içe,

Birin talibi az, gözler hep üçe.

Virgül gibi eğilinir bir hiçe,

İçerde dışarda yüz iki türlü.

Herşey sona doğru kemali bulur,

Baş eğer mutlaka cemali bulur,

Çokları tam arar, yamalı bulur,

Yandırır dediğin köz iki türlü.

Mühür gözlü güzel gayri salınma,

Belki sen temizsin, sen safsın ama...

Doğrusunu diyeceğim alınma,

Artık cilve, eda, naz iki türlü.

Ne köyümde Fatma Bacı yetişir,

Ne dağımda şen bülbüller ötüşür,

Öyle bir bahar ki mazlumlar üşür,

Milletimiz bir de biz iki türlü.

Yanlış oldu, evet, tabiri yanlış,

Kaleli mümkünse bunlara alış,

Velakin eğilme, dik dur, hep çalış,

Bu çağda yolunan kaz iki türlü.', 'Dinle sözümü de sonra yanlış de, Evde, sokaklarda kız iki türlü. Doğrusunu bulmak çetin gene de, Doğrusu, eğrisi söz iki türlü. Helal ile ha...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/celiski-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onun....', 'onun-tuncay-akdeniz-r3usb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlk onu görmüştüm pınar başında

Bakışı gözümden gitmedi onun

Boyu fidan gibi on beş yaşında

Hayalı sinemden çıkmadı onun

İçimden çıkmıyor o aşkın izi

Aşkımıza şahit akşam yıldızı

Kalbime yazmışım silinmez yazı

Ellerim elini tutmadı onun

Aşkımıza karşı yakmadı ışık

Gezdirdi peşinden yollar dolaşık

Mecnunda Leyla ya olmuştu aşık

Çöller sevdasına yetmedi onun

Tuncay a yükledin derdi veremi

Senin için yaktım kendi kendimi

Senden başka saran olmaz yaramı 

İçimde sevdası bitmedi onun

  			

Nice sine dosttur diye inandım 

Ne yazık ki fazlasıyla aldandım 

Sen mecnun deyince keremi andım 

Dünyada ocağı tütmedi onun...............Aşık Gürkanı', 'İlk onu görmüştüm pınar başında Bakışı gözümden gitmedi onun Boyu fidan gibi on beş yaşında Hayalı sinemden çıkmadı onun İçimden çıkmıyor o ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/onun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bozan bozana', 'bozan-bozana-tuncay-akdeniz-4qe67', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özümüz Türk aslımızı bilelim

Kafasına uyup kızan kızana

Vatan birdir bayrağını sevelim

Aramızı açıp bozan bozana

Türk geleneğine bağlı kalmalı

Medeniyet kültürüne uymalı

Gerekirse yerli malı giymeli

Avrupalı gibi gezen gezene

A.B.D elinde oyuncak olduk

Avrupa yolunda sınıfta kaldık

Temel eğitime tersinden daldık

Eğitime kitap yazan yazana

Tuncayım baktıkça sabır  taşıyor

Karnı doyan dışarıya kaçıyor

Hain gidip aramızı açıyor

Dışarıya sırlar sızan sızana', 'Özümüz Türk aslımızı bilelim Kafasına uyup kızan kızana Vatan birdir bayrağını sevelim Aramızı açıp bozan bozana Türk geleneğine bağlı kalma...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bozan-bozana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Aşkın Ehlinde BİR Kalem**', 'askin-ehlinde-bi-r-kalem-hulya-simsek-fccdh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Silüetini  görse 

Alkışlar göğsümdeki kuş

Sesinden bir hece düşse 

Örse

Aşkın ehlinde bir çekiç

Gelsen…

Öperdim alnından

………………..Gitsen

Ensenden öpmeyi de 

Bilirdim.

Aşkın ehlinde bir kalem

Arşa çıkmış bir dilekçe

Yazsa…

Gelir miydin? 

Ensenden  öpülmek için…

31.o3.2oo5   oo:42  İst.', 'Silüetini  görse  Alkışlar göğsümdeki kuş Sesinden bir hece düşse  Örse Aşkın ehlinde bir çekiç Gelsen… Öperdim alnından ………………..Gitsen Ense...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şimşek']::text[], 8.5, '{"poet":"Hülya Şimşek","poet_slug":"hulya-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askin-ehlinde-bir-kalem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurun Düşü', 'yagmurun-dusu-guler-ilgaz-w5e6i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmur yağarken

Sel düşü görenlere

Kar yağarken

Çığ düşü görenlere

Karşı düşü görmek için

Güneşi içimde hissettiğim anda

Gülümseyerek uyananlardan

Olmak için

Uyurmuş gibi kapadım gözlerimi

Karanlıkar içinde

Bir an bile ayırmadan

Gözlerimi yıldızlardan...

...

Yağmur yağarken artık

Sel düşü görmüyorum

Başak un ekmek getiriyor

Besliyor düşlerimi

Kar yağarken artık

Çığ düşü görmüyorum

Çorak topraklarıma can veriyor

Kavrulmuş dudaklarımı ısıtıyor 

Ulaşıyor yem yeşil yeşertiyor

Süreklenmesine izin vermiyorum

Biriktirdiğim düşüncelerimi...

....

Özgürlük hissediyorsa...

Savursana

Doğar yeniden endişelenme

Geliyorsa içinden

Hiç durma...

Yağmurun düşünü içinde hissediyorsa özgürlük

Bu işte!', 'Yağmur yağarken Sel düşü görenlere Kar yağarken Çığ düşü görenlere Karşı düşü görmek için Güneşi içimde hissettiğim anda Gülümseyerek uyanan...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yagmurun-dusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ve Hüzün ve Ayrılık', 'ask-ve-huzun-ve-ayrilik-zumrut-demirtas-p9yrk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnsan,

sevdikçe yüceleşir,

sevildikçe devleşir....

Sevgi,

istedikçe yaklaşır,

paylaştıkça çoğalır....

Aşk,

istemeden karşına çıkar,

kaçtıkça yakana yapışır....

Hüzün,

aşkla beraber gelir,

ardında izler bırakır....

Gözyaşı,

seven yüreklere damlar,

ayrılığın seline karışır....

Ayrılık,

feleğin hep oynadığı oyun,

aşığın ölüm fermanıdır....', 'İnsan, sevdikçe yüceleşir, sevildikçe devleşir.... Sevgi, istedikçe yaklaşır, paylaştıkça çoğalır.... Aşk, istemeden karşına çıkar, kaçtıkça...', ARRAY['Türk Edebiyatı','Şiir','Zümrüt Demirtaş']::text[], 8.5, '{"poet":"Zümrüt Demirtaş","poet_slug":"zumrut-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ask-ve-huzun-ve-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koylu kizi', 'koylu-kizi-husamettin-guven-6c9ac', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni gordum sevgi doldum

Ilk goruuste asik oldum

Inan sana ben vuruldum

Seviyorum koylu kizi

           suna boylum gel naz etme

           seviyorum deyip gitme

           beni senden mahrum etme

           seviyorum koylu kizi

koylu kizi dort dortluksun

gonlumde acan konca gulsun

he''''de artik bu garipde gulsun

seviyorum koylu kizi

Hollanda', 'Seni gordum sevgi doldum Ilk goruuste asik oldum Inan sana ben vuruldum Seviyorum koylu kizi            suna boylum gel naz etme            ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/koylu-kizi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur bakalım', 'dur-bakalim-gencay-coskun-qgva2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendi içimize uymayan 

Bize yabancı düşler öğretildi belki 

Belki yalnızlık ömür boyu değildi 

(M.F.Ö. ağbilerim bana kızmasın)

Yalnızlık  sonsuzdu içimizde

Kaç kaçabilirsen girdabından 

Savrul savrulabilirsen

Özünden en uzağa 

Nereye gidersen git

Kendinin hamallığını yaparsın 

Kayıp ruh olur 

Kayıp ruhlar cumhuriyetini ararsın 

Bulduğun bir avuç sonbahar

Üstüne az sonra  uzunca bir kış 

Sanırsın bu memlekette 

Hiç bahar gelmeyecek 

Sanırsın bu memlekette 

Hiç yaz gelmeyecek

Aslına bakacak olursak 

Kışın soğuk olmadığının 

Farkında bile değildir insan 

Bu memlekette

Bizi asıl soğutan

Birazda kurutan 

Yalnızlığın amansız beyazı 

Yitirmenin acımasız siyahıdır aslında

Aslında biz yolcuyduk

Ama yolumuzu adam gibi bilemedik 

Sevdalarımızı adam gibi yaşatamadık

Bugün bana düşsen 

Yarınlardaki gerçekliğini 

Hep serap sandım 

Dokunmaya bile kıyamadım 

Usuldan müebbet seyrettim belki 

Belki yanıldım 

Belki yarımdım 

Yarımda olsa bir otuz adamdım…

Zamanın tokatının acısını 

Yemeden anlayamadım 

Resimlerdeki yabancı yüzümü 

Aynalardan sakladım 

Yansa da aşım tencerede 

Bir yankı değildim hiçbir zaman 

Daima sesin önde gideni olmuştum

Dur bakalım 

Bu gidişim çok sessiz mi olacak ne?', 'Kendi içimize uymayan  Bize yabancı düşler öğretildi belki  Belki yalnızlık ömür boyu değildi  (M.F.Ö. ağbilerim bana kızmasın) Yalnızlık  s...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/dur-bakalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fakir', 'fakir-muhiddin-ates-10rmn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Derdi çileyi O''na sorun O bilir

Ne halde olsa hedefi sevgidir

Kuru ekmekte yese bal gibidir

Haram nedir bilmez arkadaş

Bir lokma ekmeğe boyun eğmez

Tembel değildir kazancı yetmez

Şükreder haline şikayet etmez

Gururunu pas pas etmez arkadaş

Derdin biri gider biri gelir

Ne ağlamayı ne gülmeyi bilir

Şerefi uğruna canını verir

İnsanlıktan taviz vermez arkadaş', 'Derdi çileyi O''na sorun O bilir Ne halde olsa hedefi sevgidir Kuru ekmekte yese bal gibidir Haram nedir bilmez arkadaş Bir lokma ekmeğe boyu...', ARRAY['Türk Edebiyatı','Şiir','Muhiddin Ateş']::text[], 8.5, '{"poet":"Muhiddin Ateş","poet_slug":"muhiddin-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/fakir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurumus bak dudaklarim', 'kurumus-bak-dudaklarim-husamettin-guven-4ooco', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Endamina vurulayim

Gozlerinde kayp olayim

Ince belden sarilayim

Kurumus bak dudaklarim

        Musadenle islatayim

        O sinende ben yatayim

        Doyasiya keyf catayim

        Kurumus bak dudaklarim

Kurumus bak melhem ister

Inan gonlum onu ister

O dudaktan canim ister 

Kurumus bak dudaklarim

Hollanda', 'Endamina vurulayim Gozlerinde kayp olayim Ince belden sarilayim Kurumus bak dudaklarim         Musadenle islatayim         O sinende ben yat...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kurumus-bak-dudaklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tipki bir melek', 'tipki-bir-melek-husamettin-guven-67q11', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Guldukce yuzunden guller aciyor

Mertligin insanlara guven saciyor

Sevenlere temiz kalp le kucak aciyor

Insanligin otesi tipki bir melek

Durustlugu insanlik ondan almali

Neseyi ve huzuru sende bulmali

Sevenlerin bence sana tapmali

Insanligin otesi tipki birmelek

Varligiyle guven verir tum isnsanlara

Sakasiyle gulucuk sacar tum insanlara

Tek dilegi mutlu olmak bahti pek kara

Insanligin otesi tipki birmelek

Hollanda', 'Guldukce yuzunden guller aciyor Mertligin insanlara guven saciyor Sevenlere temiz kalp le kucak aciyor Insanligin otesi tipki bir melek Duru...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tipki-bir-melek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fedakarlik ister', 'fedakarlik-ister-husamettin-guven-mb8pf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seviyorum demek olmaz

Sevgiler bedelsiz kalmaz

Bu isin ayibi olmaz

Sevmek fedakarlik ister

Sozcuklerle sevmek olmaz

Eylemsiz kaniti olmaz

Bu duygu bedelsiz kalmaz

Sevmek fedakarlik ister

Bak bana cok seviyorum

Gel deyince geliyorum

Sana teklif sunu yorum

Sevmek fedekerli ister

Hollanda', 'Seviyorum demek olmaz Sevgiler bedelsiz kalmaz Bu isin ayibi olmaz Sevmek fedakarlik ister Sozcuklerle sevmek olmaz Eylemsiz kaniti olmaz Bu...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/fedakarlik-ister-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Komur gozlum', 'komur-gozlum-husamettin-guven-et85s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Boyun egdin emirlere

Sabir ettin sevmeyenlere

Sevgi nedir bilmeyenlere

Hak etmedin komur gozlum

Esden dostdan hic fayda yok

Bos laflara karnin pek tok

Sen haklisin sucun hic yok

Hak etmedin komur gozlum

Yuvanda bir gonca gulsun

Sakin solma atilirsin

Firsat verme itilirsin

Hak etmedin komur gozlum

Hollanda', 'Boyun egdin emirlere Sabir ettin sevmeyenlere Sevgi nedir bilmeyenlere Hak etmedin komur gozlum Esden dostdan hic fayda yok Bos laflara karn...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/komur-gozlum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri dön', 'geri-don-veli-dalbudak-7iniz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bütün cihanı bana bırakıp, serseler ayaklarımın altına

Yinede değişmem bir-tanem, senin içten bir bakışına

Bütün deryaları bana verseler, içsem son damlasına kadar

Yinede söndüremez bir-tanem, senin aşkının yaktığı kadar

Bütün yıldızları yere indirip, doldursalar gönlüme aydınlığı

Yinede ışıtamaz bir-tanem, senin gidişindeki karanlığı

--Ne olur GERİ DÖN

(Stockholm 1998)', 'Bütün cihanı bana bırakıp, serseler ayaklarımın altına Yinede değişmem bir-tanem, senin içten bir bakışına Bütün deryaları bana verseler, iç...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/geri-don-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Son aradım', 'son-aradim-veli-dalbudak-04ub5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sıkıntı çöker bazan içime

Unutamıyorum bir türlü geçmişi

Yön arar dururum hep kendime

Bulamıyorum bir türlü kendimi

Güneşi seyrettim sabah erken

Geldi geçti ömür şura bura derken

Hangi insan iyilik bulduki kendisinden

DOST aradım bulamadım kendime

Usandım artık bırakın öleyim rahatca

Gülemiyorum gizli gizli aglamadıkca

Karıştırıp maziyi anılara baktıkca

SON ARADIM bulamadım kendime

(kulu 1978)', 'Bir sıkıntı çöker bazan içime Unutamıyorum bir türlü geçmişi Yön arar dururum hep kendime Bulamıyorum bir türlü kendimi Güneşi seyrettim sab...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-aradim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir başkaydı', 'bir-baskaydi-veli-dalbudak-sbg9r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unutursun demişti bana dostlarım

Silinmedi bir türlü senle olan anılarım

Yıllar geçti aradan hala hatırlarım

Bir başkaydı bakışın, bir başkaydı gülüşün

Çoook aradım çok, her yerde seni

Bulamadım bir yerde senin gibisini

Neyleyim senden başkasının sevgisini

BİR BAŞKAYDI bakışın bir başkaydı gülüşün

(Stockholm 1992)', 'Unutursun demişti bana dostlarım Silinmedi bir türlü senle olan anılarım Yıllar geçti aradan hala hatırlarım Bir başkaydı bakışın, bir başka...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-baskaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-kader Utansın', 'kader-utansin-veli-dalbudak-39cap', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kopar ömründen benle olan sayfaları

Karıştırıp baktığında gözlerin dolmasın,

Yaşamadım de, soran olursa o yılları

Anılar seni iki kez ağlatmasın.

Unut maziyi, böyle doğmuşum ben de,

Yaşlar belirmesin o güzelim gözlerinde

Karşılaşırsak ansızın bir gün bir yerlerde,

Bakmadan geç, gözlerin bende kalmasın.

Yak, kül olsun, eline alma resimlerimi

Rüyanda bile anma sayıklama ismimi

Çalışıp çırpınıp yinede unutamazsan beni

Sen utanma güzelim, KADER UTANSIN

(Stockholm 1991)', 'Kopar ömründen benle olan sayfaları Karıştırıp baktığında gözlerin dolmasın, Yaşamadım de, soran olursa o yılları Anılar seni iki kez ağlatm...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kader-utansin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avutmak', 'avutmak-mehmet-can-3zs7b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Avutmak

Kadırdım  hep kendimi..

Avutup durdum..

Herkes gibi..

Kalbim umutlara gebe kaldı..

Umutlar…Umutlara…

Bir rüzgar bekledim..

Alıp götürsün beni..

Uzaklara..

Uzaklara…

Yabancı yerlerde..

Bir yabancı olayım…

Bir yağmur bekledim..

Sel olup alsın beni…

Engin denizlere..

Salsın beni…

Bir aşk bekledim..

Kalbimi alsın benim..

İçini yarsın…

Anlarsın…

Anlarsın…', 'Avutmak Kadırdım  hep kendimi.. Avutup durdum.. Herkes gibi.. Kalbim umutlara gebe kaldı.. Umutlar…Umutlara… Bir rüzgar bekledim.. Alıp götü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/avutmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülmek', 'gulmek-mehmet-can-zgstb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gülmek

Gülmeyi unutmuşum..

Ne olur, güldür beni..

Ateş gibi  yanarsam..

O zaman söndür beni..

Aşk yolundan sapınca..

Sen geri döndür beni..

Yalanımı bulursan..

Boğarak öldür beni..

Önce sev, sonra terk et..

Sende süründür beni..

Sende süründür beni..', 'Gülmek Gülmeyi unutmuşum.. Ne olur, güldür beni.. Ateş gibi  yanarsam.. O zaman söndür beni.. Aşk yolundan sapınca.. Sen geri döndür beni.. ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gulmek-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Dostları', 'gonul-dostlari-oguzkan-bolukbasi-ro89n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'duyguların seri katilidir

güzelliklerin çiçek açtığı bu bahar ayları

ölmüş aşkları diriltmelidir, umuda açılan pencereler

yağmur götürmeden damları, saçakları

gönül dostlarım şimdi nerede demlenirler

onlar

aşkın mirasını mı bölüşürler', 'duyguların seri katilidir güzelliklerin çiçek açtığı bu bahar ayları ölmüş aşkları diriltmelidir, umuda açılan pencereler yağmur götürmeden ...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gonul-dostlari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'G-e-l-i-n-c-i-k', 'g-e-l-i-n-c-i-k-olgun-ekinci-2wtl2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gelişin gülüşün ışıl ışıl gözlerinle

Erguvanlar her mevsim açacak çiçeklerini

Lale sümbül mor menekşe

İğde dallarına uzanacak sevda türküleriyle

N ilüferler ılgamlara inat susuz yeşerecekler

Ceviz ağaçları Gülhane''den

İklimleri kirlenmemiş ülkelere dek boy verecekler

Kızıl karanfillerle gül kokacaksın.....

 28 Mart - Adana', 'Gelişin gülüşün ışıl ışıl gözlerinle Erguvanlar her mevsim açacak çiçeklerini Lale sümbül mor menekşe İğde dallarına uzanacak sevda türküler...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/g-e-l-i-n-c-i-k-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Güle Çobanoğlu', 'gule-gule-cobanoglu-hifzi-ozbekmez-oq1lw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalan dünya gelen gider

Güle güle ÇOBANOĞLU

Evvel Allah  yardım eder

Güle güle ÇOBANOĞLU

Sen büyük Türk ozanıydın

Aşka türkü yazanıydın

Sanki şerbet kazanıydın

Güle güle ÇOBANOĞLU

Sevenlerin kara bağlar

Boyun bükmüş sıra dağlar

Sazın bir köşede ağlar

Güle güle ÇOBANOĞLU

Latifim içim yanıyor

Gözlerim seni arıyor

Dostların her gün soruyor

Güle güle ÇOBANOĞLU

NOT:Bu şiir 26 Mart 2005 cumartesi günü aramıdan ayrılan kıymetli ozanımız Murat ÇOBANOĞLU anısına yazılmıştır. Allah Rahmet eylesin.Mekanı cennet olsun.', 'Yalan dünya gelen gider Güle güle ÇOBANOĞLU Evvel Allah  yardım eder Güle güle ÇOBANOĞLU Sen büyük Türk ozanıydın Aşka türkü yazanıydın Sank...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gule-gule-cobanoglu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairler Mekanı', 'sairler-mekani-hifzi-ozbekmez-nrypl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dostluğa yazılmış bir destan gibi

Şairler mekanı ŞİİR PERİSİ

Ballı su akıtan bedesten gibi

Şairler mekanı ŞİİR PERİSİ

Şaire yazdıran gönül sızısı

Kimisi gülerken ağlar bazısı

Sevgiyle örülmüş geçmiş mazisi

Şairler mekanı ŞİİR PERİSİ

Her hafta yazılan dörtlükleri var

Sevgiye dostluğa mertlikleri var

Şiir aleminde yıkılmaz duvar

Şairler mekanı ŞİİR PERİSİ

Yazılan şiirler burda yarışır

Dostluğa emeğe sevgi karışır

Gönülden sevenler burda buluşur

Şairler mekanı ŞİİR PERİSİ

Şiirin sevginin büyük konağı

Kararan kalplerin bir tek yunağı

Ozan latifinin en son durağı

Şairler mekanı ŞİİR PERİSİ', 'Dostluğa yazılmış bir destan gibi Şairler mekanı ŞİİR PERİSİ Ballı su akıtan bedesten gibi Şairler mekanı ŞİİR PERİSİ Şaire yazdıran gönül s...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sairler-mekani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-hifzi-ozbekmez-o3r7c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu meydandan edeplice çekil git

Kervan yürür boşa ürür derler it

Tertemiz bedende gezinen bir bit

Olma dostum benden sana nasihat

Yazdıklarım uyarıdır hep sana

Boşuna böğürür gezer bak dana

Salya sümüğünü bizim meydana

Salma dostum benden sana nasihat

Kendin ettin kendin buldun dilinle

Kime hava atan sen bu halinle

Oturup saçını kendi elinle

Yolma dostum benden sana nasihat

Dinlemem ben senin ahın vahını

Sen ufaksın gönder senin şahını

Ozan latifinin tutan ahını

Alma dostum benden sana nasihat', 'Bu meydandan edeplice çekil git Kervan yürür boşa ürür derler it Tertemiz bedende gezinen bir bit Olma dostum benden sana nasihat Yazdıkları...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasihat-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Deli Gönül', 'ey-deli-gonul-bayram-tunca-x3g6k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Allah şahit bu ateşten gömleği giydim giyeli

Gören dostlarım dahi, sandılar sanki de deli

Yeter deli gönül yeter çektirdiğin bunca çile

Ağaçlar kalem olsa, getiremezler çilemi dile

29.03.2005-03:29', 'Allah şahit bu ateşten gömleği giydim giyeli Gören dostlarım dahi, sandılar sanki de deli Yeter deli gönül yeter çektirdiğin bunca çile Ağaç...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ey-deli-gonul-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Bir Mum Gibi Sönme', 'sakin-bir-mum-gibi-sonme-huseyin-erdogan-bkad4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'her sabah doğuversen günüme

hiç dönüp bakar mıyım dünüme? 

öyle bir ateş düşürdün ki yüreğime

o güzel ellerinle tutmalısın ellerimi

artık çare olmalısın sensizliğime

benim dünyamı sen aydınlatır ısıtırsın

sen benim güneşim ay ve yıldızlarımsın

ne de sıcacık doğarsın gündüzlerime

ışıl ışıl çıkarsın benim zifiri gecelerime

her gece o kadar tatlı girersin ki düşlerime

bil ki rüyamda olsa bile seni isterim ömrümce

ne olur henüz başlamışken aşkımız geri dönme

sen benim ışığımsın sakın bir mum gibi sönme

                                                  31.03.2005', 'her sabah doğuversen günüme hiç dönüp bakar mıyım dünüme?  öyle bir ateş düşürdün ki yüreğime o güzel ellerinle tutmalısın ellerimi artık ça...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sakin-bir-mum-gibi-sonme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Kalsın', 'gece-kalsin-elcin-orhan-1lj48', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bana korkuyu sorma

sana korkusuzluğun izlerini gösteririm 

ta çocukluktan kalma

al sorularını git

soru sorma 

nefret gelir aklıma 

bir vakitler sevdiklerimi yalanlarım,

tün gibi, sevdiklerim gibi

sende ağır ağır iniyorsun yüreğime 

elinde deste deste ümit 

ümit sonu

acıyı bilir misin? 

içten içe öldürdüğüm benim 

yaradan bile acımaz yarattığına 

yaratıp acımadığı benim...

ümitlerini alda git dostum.

benle bırak beni.

sen gidince, yerine 

esmer diye sevdiğim gece kalsın.

Elçin ORHAN

30/03/2005', 'bana korkuyu sorma sana korkusuzluğun izlerini gösteririm  ta çocukluktan kalma al sorularını git soru sorma  nefret gelir aklıma  bir vakit...', ARRAY['Türk Edebiyatı','Şiir','Elçin Orhan']::text[], 8.5, '{"poet":"Elçin Orhan","poet_slug":"elcin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gece-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tenimde İzin Kalmamış', 'tenimde-i-zin-kalmamis-i-lknur-er-97mud', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağaçların yapraklarını döküp çıplak kalmış hali gibiyim

Kalbimde kıyıya vurmuş çakıl taşları

Parçalanmışım yaralanmışım

Yok yok sen değilsin 

Hadi yapma lütfen bir oyunmu bu

Bir rüyamı hayalmi düşmü

Düşümmüsün uykummusun

Tenimde izin kalmamış', 'Ağaçların yapraklarını döküp çıplak kalmış hali gibiyim Kalbimde kıyıya vurmuş çakıl taşları Parçalanmışım yaralanmışım Yok yok sen değilsin...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tenimde-izin-kalmamis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyku Kuşu', 'uyku-kusu-banu-aka-xcfhm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur yağmış

Dün

Benden habersiz

Bir uyku kuşu 

Konmuş gözlerimin üzerine

Görememişim

Sevdiğim şeyleri

Göstermeyecek kadar 

Uzanma 

Bir daha gözlerime 

Uyku.', 'Yağmur yağmış Dün Benden habersiz Bir uyku kuşu  Konmuş gözlerimin üzerine Görememişim Sevdiğim şeyleri Göstermeyecek kadar  Uzanma  Bir dah...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/uyku-kusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksik', 'eksik-banu-aka-ujht9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sıcacık 

Küçücük 

Güzel

Bir ev burası 

Kapısını dilediğim zaman açtığım

Duvarda istediğim yerlere

Çivi çakıp

Sevdiğim resimleri astığım

Uykum kaçınca 

Işıkları yakıp

Kitap okuyabildiğim

Banyoda 

Şarkı söyleyebildiğim

Yalın ayak gezebildiğim.

Her şeyi tamam da

“Terliklerini giy”

Diyecek  biri 

Ve onun terlik sesleri eksik...', 'Sıcacık  Küçücük  Güzel Bir ev burası  Kapısını dilediğim zaman açtığım Duvarda istediğim yerlere Çivi çakıp Sevdiğim resimleri astığım Uyku...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/eksik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karaciğerim', 'karacigerim-banu-aka-np80a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adını koyamam

Bilmiyorum

Nasıl bir şey

Başka birinin yokluğunu

Böylesine hissetmek 

Sanki

“Karaciğerim” 

Almış başını gitmiş gibi...', 'Adını koyamam Bilmiyorum Nasıl bir şey Başka birinin yokluğunu Böylesine hissetmek  Sanki “Karaciğerim”  Almış başını gitmiş gibi......', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karacigerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne olur', 'ne-olur-banu-aka-ks05c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak gözlerime 

Anlayan gözlerinle

Ne olur 

Bana 

Aynı şeyleri 

Söyletme yeniden

Yüreğime yaktığın ateş

Yüzüme vuruyor sonra.', 'Bak gözlerime  Anlayan gözlerinle Ne olur  Bana  Aynı şeyleri  Söyletme yeniden Yüreğime yaktığın ateş Yüzüme vuruyor sonra....', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-olur-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Bir Güneş', 'baska-bir-gunes-banu-aka-wzxv0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece örtünce gündüzü

Siyah kanatlarıyla 

Benim içimde 

Başka bir güneş doğuyor

Her gece 

Çok şükür.', 'Gece örtünce gündüzü Siyah kanatlarıyla  Benim içimde  Başka bir güneş doğuyor Her gece  Çok şükür....', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/baska-bir-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayarak', 'yasayarak-i-smet-barlioglu-aura0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tanıyamaz oldum bu bulutları,

Çiseleyen bu ilkbahar yağmurunu,

Ağaçların beyaza kesmiş körpe çiçeklerini,

Çiçekleri serin serin kucaklayan güneşi,

Tanıyamaz oldum

Aralarında göremediğim için

Seni.

Sensiz bulutları buluttan mı sayarım,

Yağmurdan mı sayarım çiseleyen bu ilknahar yağmurlarını,

Beyaza kesmiş körpe çiçeklerini ağaçların,

Güneşten mi sayarım bir dolu dolu ısınamamış güneşi? 

Güneş dediğin senli olmalı,

Ağaç senli, çiçek senli olmalı,

İnsan ilk bakışta; 

Bulutun bulut, yağmurun yağmur, güneşim güneş olduğunu

Anlamalı.

Senli olduğu için yüreğim yürek,

Gönlüm gönül,

Ruhum ruh,

Bedenim beden,

Ellerim el, ayaklarım ayak,

Ben bunun böyle olduğunu nasıl öğrendim,

Biliyor mususun? 

Yaşayarak.

(KANAMA YÜREĞİM isimli Serbest Şiirler ''inden > 91-92/100)', 'Tanıyamaz oldum bu bulutları, Çiseleyen bu ilkbahar yağmurunu, Ağaçların beyaza kesmiş körpe çiçeklerini, Çiçekleri serin serin kucaklayan g...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yasayarak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yağmur Bekliyorum', 'bir-yagmur-bekliyorum-i-smet-barlioglu-r46yt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yağmur bekliyorum,

Bizi elele yakalayan o ışıltılı yağmur gibi bir yağmur,

Bekliyorum ki; yine ıslatsın bizi sırılsıklam,

Sarı saçlarını arlın teller gibi yapıştırsın yüzüne,

Süzülsün kaşlarının uçlarından yanaklarına,

Islansın gül yaprakları gibi kıvrılmış dudakların,

O yağmur yine yağsın diye arkasına sığınıyorum

Duaların.

Bir yağmur bekliyorum,

Altına sığındığımız saçaklarda pıtırdayan,

Yıkayan, daldan düşmüş sonbahar yapraklarını,

İplik iplik uzanıp koşan denize doğru,

Bu kaskatı gerçekler ortasında

Birazcık aldanmak için,

Bir yağmur bekliyorum

O güzel günlerimize

Yeniden

Uzanmak için.

Bir yağmur bekliyorum,

Seni maziden alıp bana ve bugüne getirecek,

Ardında rengarenk bir gökkuşağı görünecek,

Çisiltisinde senin sesin bulunacak bir yağmur,

Damlalarında senin kokun,

Bereketinde senin varlığın,

Neminde sıcaklığın,

Bana yakınlardan daha bir yakın oldun diye

Uzaklığın.

(KANAMA YÜREĞİM isimli Serbest Şiirler ''inden > 93-94/100)', 'Bir yağmur bekliyorum, Bizi elele yakalayan o ışıltılı yağmur gibi bir yağmur, Bekliyorum ki; yine ıslatsın bizi sırılsıklam, Sarı saçlarını...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-yagmur-bekliyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmayınca', 'sen-olmayinca-i-smet-barlioglu-0pzgh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşam devam eder mi sanıyorsun, sen olmayınca,

Ayni sular mı akar acaba, ayni köprülerin altından,

Reçine mi kokar çamlar eskisi gibi,

Eski yosun kokusu mu yükselir bir yeni denizden,

Eski omuzlara yeni yağmurlar mı çiseler,

Sen olmayınca sürer gider mi rüzgarların dilinde

Türküler? 

Bir acaip deniz var senden sonra, ayaklarımın altında,

Ne sularında yosun kokusu, ne dalgalarında martı sesi,

Ne kumsala dokunan dudakları, ne dudaklarının busesi,

Soyunmuş dalgaları pırıltılarından,

Suları yakamozlarından,

Düşmüş o eski samanyollarının pelerini

Omuzlarından.

Rüzgarlıklarından soyunmuş rüzgarlar,

Ne bedenlerinde sarıçam kokuları,

Ne dallarında bir körpe yağmur,

Ne dillerinde birer türkü,

Ne ellerinde birer serinlik,

Hiçbiri anımsatmıyor senden sonra, eski bir ilkbaharı,

Sen olmayınca süslemez oluyor gökkuşakları

Dağları.

(KANAMA YÜREĞİM isimli Serbest Şiirler ''inden > 95-96/100)', 'Yaşam devam eder mi sanıyorsun, sen olmayınca, Ayni sular mı akar acaba, ayni köprülerin altından, Reçine mi kokar çamlar eskisi gibi, Eski ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sen-olmayinca-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller de Ölmüş', 'guller-de-olmus-i-smet-barlioglu-8ivqd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seninleymiş o güzel kokuları bu kırmızı güllerin,

Seninleymiş o şatafatlı renkleri,

Körpe dudakları andıran körpe yaprakları

Seninleymiş,

Gidersen bir ben ölürüm sanıyordum,

Güller de

Ölmüş.

Ne çığlık çığlığa uçuşması kalmış martıların,

Ne dalgaların körpe kumsalları öpüp okşaması,

Ne ayaklarında gezinmesi rüzgarların,

Ne o yosun kokularının sinmesi saçlara,

Ne de güneşin sarmaşıklar gibi tırmanması

Ağaçlara.

Bilemezdim koca bir doğanın seninle yaşadığını,

Seninle gülüp ağladığını,

Seninle var olduğunu,

Kokuların, seslerin, renklerin silineceğini, yokluğunda,

Bana bunu da sen öğrettin

Sonunda.

(KANAMA YÜREĞİM isimli Serbest Şiirler ''inden > 97-98/100)', 'Seninleymiş o güzel kokuları bu kırmızı güllerin, Seninleymiş o şatafatlı renkleri, Körpe dudakları andıran körpe yaprakları Seninleymiş, Gi...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/guller-de-olmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gidince', 'sen-gidince-sever-koz-5ae3b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen gidince

kursağımda kaldı.

sevincin yarısı,

özlemin yarısı,

ölümün yarısı.

borçlusun şimdi

sevincin, özlemin, ölümün

yarısı için...', 'sen gidince kursağımda kaldı. sevincin yarısı, özlemin yarısı, ölümün yarısı. borçlusun şimdi sevincin, özlemin, ölümün yarısı için......', ARRAY['Türk Edebiyatı','Şiir','Sever Köz']::text[], 8.5, '{"poet":"Sever Köz","poet_slug":"sever-koz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-gidince-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözler-20', 'guzel-sozler-20-huseyin-erdogan-u1ds8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Gözlerin bir Güneş,bakışların da bir ateş gibi.Aydınlattın dünyamı amma yaktın yüreğimi.Ben böyle aşkından yanıp tutuşurken,gelip bendeki yangını söndürmek varken,gönül bahçemdeki çiçeklerim göz yaşlarımla sulanırken,hiç mi üzülmüyorsun çekip giderken? Seyredebilecek misin beni, bitkisel hayatta yaşarken? Hiç mi için sızlamayacak,beni yaşama bağlayan sevgi köklerimi bir bir kuruturken? ''

''Yaşamak; soluk alıp vermek demek değildir.Yaşadığını hissedebilmek için,yarına umutla bakabilmek,her sabah Güneş''in doğuşunu heyecanla bekleyebilmek,paylaşmayı öğrenmektir.Önce sevmesini bilmek,sonra da sevilmeyi istemektir.Yani,yaşamak; aşk ve sevgidir...''

                                                                                  31.03.2005', '''Gözlerin bir Güneş,bakışların da bir ateş gibi.Aydınlattın dünyamı amma yaktın yüreğimi.Ben böyle aşkından yanıp tutuşurken,gelip bendeki y...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/guzel-sozler-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BeDeSTeN,', 'bedesten-mine-ozdemirtas-vl8gj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sanma ki,

sen yoksan; 

yüreğim çekekte 

hurdaya çıkarılır.

ve yok fiyatına satılır.

Gün ola harman döne

elbet yine dalga alır

küpeştesi ıslanır.

Alınma üstüne / bu ne gurur? 

Gözyaşım; 

gidişine değil

hala kalışımadır.

31/03/2005', 'sanma ki, sen yoksan;  yüreğim çekekte  hurdaya çıkarılır. ve yok fiyatına satılır. Gün ola harman döne elbet yine dalga alır küpeştesi ısla...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bedesten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Güzel Yar', 'ey-guzel-yar-hikmet-yakisir-wsay9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canıma can katan sevgili

Bir tek gün incitmedi beni

Ne bir kem bakış baktı gözleri

Nede acı bir söz söyledi bana dili

Şefkatle okşardı, saçımı tenimi elleri

Ey yar

Ne olursun, gezme diyar diyar

Dünyayı etme bana dar

Gel otur yanımda kal

Toysun, güzelsin, harcarlar seni

Çevrede çoktur çakal

Ey nazlı çiçeğim

Dünyada kaldıysa vazgeçemediğim

Biri sen, ki hiç incitmediğim

Biri de anam, elini öpeceğim

Ve bir kadeh mey içeceğim

Ey güzel yar,

Bakma bana öyle sitemkar,

Yorgunum, peşinden gelemem 

Yaşım genç ama ruhum ihtiyar

Mutlu yaşa, şen kal, sen ol bahtiyar

Ey güzel yar

30 Mart 2005', 'Canıma can katan sevgili Bir tek gün incitmedi beni Ne bir kem bakış baktı gözleri Nede acı bir söz söyledi bana dili Şefkatle okşardı, saçı...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ey-guzel-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Laviniam', 'laviniam-hikmet-yakisir-6cbp6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hüzünlüyüm

Sol yanım sızlıyor

Benliğimde bir boşluk var

Derin uçurumlardayım sanki

Sensizim Lavinia

Yoksun

Bir daha da olurmusun bilmiyorum.

Yüreğimdeki sızım,

Gözlerimdeki hüzün 

Bundandır Lavinia

Seninle

Hayalimizde canlandırdığımız sahilde

Yalınayak dolaşırken

Bıraktığımız ayak izlerimiz 

Duruyor mu Lavinia

Martılar

Af fermanını ararlarken

Koro halinde söyledikleri

Aşkımızın şarkısını

Dinliyor musun Lavinia’m

20 Ekim 2004', 'Hüzünlüyüm Sol yanım sızlıyor Benliğimde bir boşluk var Derin uçurumlardayım sanki Sensizim Lavinia Yoksun Bir daha da olurmusun bilmiyorum....', ARRAY['Türk Edebiyatı','Şiir','Hikmet Yakışır']::text[], 8.5, '{"poet":"Hikmet Yakışır","poet_slug":"hikmet-yakisir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/laviniam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin kar soğuk hayallerde bile.', 'ellerin-kar-soguk-hayallerde-bile-dilan-tan-xwpsf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerin kar soğuk hayallerde bile.

Yüzüne hüznü kim doğurdu yalan gecelerde.

Sevda yüzlüm, kara gözlüm.

Çıkmaz sokaklarda tarifsiz adresini bulamadığım.

Çözemediğim kördüğüm.

Tut ellerimden üşüyorum.

Tut ellerinden yoksa bu defa gerçekten gidiyorum.

Sensizlik buzdan putlar sinemde 

Yüreğimdeki yangınlar bile söndüremedi putları

Tut hayallerimi yoksa bitiyorum.', 'Ellerin kar soğuk hayallerde bile. Yüzüne hüznü kim doğurdu yalan gecelerde. Sevda yüzlüm, kara gözlüm. Çıkmaz sokaklarda tarifsiz adresini ...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ellerin-kar-soguk-hayallerde-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelepçe...', 'kelepce-dilan-tan-igitr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğime kelepçe taktım bu gece,

Senin gittiğin gece,

Bitti dediğin gece,

Ben ağladım sen durmadın,

Gittin bu gece...

Yüreğime kelepçe yetmedi prangalar taktım bu gece,

Perdeyi örttüm ışıkları kapattım.

Yıldızlara aya küstüm.

Sessizce yattım, hiç ağlamadım.

Kapattım gözlerim sıkı sıkı,

Dilime de kelepçe vurdum bu gece.

İsmini duymasın kulaklarım diye.

Yüreğime kelepçe vurdum,

Yetmedi pranga taktım özlemesin seni diye.

Gittigin bu gece...

Zifiri kara bu gece...', 'Yüreğime kelepçe taktım bu gece, Senin gittiğin gece, Bitti dediğin gece, Ben ağladım sen durmadın, Gittin bu gece... Yüreğime kelepçe yetme...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kelepce-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sanki Rüya...', 'bu-sanki-ruya-i-brahim-ethem-bingul-o15f6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk bir varmış, bir yokmuş

Bahar bahar içinde

Ben kalbimi tıkır mıkır saklarken

Güneş vurmuş üzerime, aslı ateş

Ayaz vurmuş kalplere rengini veren

Yalnız gönlümün

Yakamozu olurmuş puslu gecelerime...

Kasvetli kışa benzeyen umutlarıma

Yaz kokulu bahar akşamları getirmiş

Dönmüş aslına...

Bilmece hayatım

Körelen duygularım

Masal bu ya

Belki de hepsi rüya...

Bu rüya

Namlı bir kebabçıdan başlayıvermiş...

www.iebigul.com', 'Aşk bir varmış, bir yokmuş Bahar bahar içinde Ben kalbimi tıkır mıkır saklarken Güneş vurmuş üzerime, aslı ateş Ayaz vurmuş kalplere rengini...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-sanki-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar.', 'sonbahar-dilan-tan-atg2c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Usul usul geliyor ölüm benden yana.

Yapraklar vefasızca terk ediyor sonbahar hüznünü taşıyan ağaçları acımasızca.

Bilmiyorum neden ağlıyorum her sonbaharda...

Yorgunum...

Merakla  ölümü özlüyorum korkuyla.

Ben ölüyorum.

Yapraklar daha  vefasız

Sonbahar daha hüzünlü

Sende gidiyorsun vefasız yapraklar gibi.

Sonbahar ağlıyor.

Ben ağlıyorum.

Sırlarımla kaçıyorsun,

Dünyamı yıkıyorsun,

Ağlayamıyorum gözyaşlarım sen kokuyor. 

Yorgunum...

Terkedilmişlik yordu çocuk yüreğimi.

Bilmiyorum yasım kaç

İhtiyar bir yürek taşıyorum genç gözlerimde

Seni özlüyorum

Ve ölüm geldi bana yapraklar gibi vefasız değil...', 'Usul usul geliyor ölüm benden yana. Yapraklar vefasızca terk ediyor sonbahar hüznünü taşıyan ağaçları acımasızca. Bilmiyorum neden ağlıyorum...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sonbahar-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlan -1-', 'oglan-1-abdullah-atay-32eps', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'maniler yazan oğlan

yanıma uzan oğlan

anam beni verecek

çok para kazan oğlan...

gözünü süzen oğlan

anasın üzen oğlan

yarini eller almış 

yalınız gezen oğlan...

badeler içen oğlan 

kendinden geçen oğlan

onca güzel içinde

tek beni seçen oğlan...

dağlarda yatan oğlan

naralar atan oğlan

mecnun olup geziyor

kurt kuşa çatan oğlan...

saçın uzatan oğlan

bıyık kazıtan oğlan

saçına boncuk dizip

işi azıtan oğlan...

ay oğlan bekar oğlan 

mis gibi kokar oğlan

her gün başka güzeli

koluna takar oğlan...

karşımda duran oğlan

bıyığın buran oğlan

bir hayırsız yar için

kendini vuran oğlan...

söylendi yine mani

gönüller oldu kani

kimsenin kalbin kırma

gidenler nerde hani....', 'maniler yazan oğlan yanıma uzan oğlan anam beni verecek çok para kazan oğlan... gözünü süzen oğlan anasın üzen oğlan yarini eller almış  yal...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/oglan-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollarda', 'yollarda-i-brahim-kilinc-kniv6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Arayıp yıllarda bulamadığım

Çalıp kapıları soramadığım 

Hayaline bile doyamadığım

Bulmadan yitirdim seni yollarda

Hatıranı saklar yaşanan yıllar

Notalara döker aşkımı teller

Sır oldun ismini söylemez diller

Sarmadan yitirdim seni yollarda

Titrer dudakların çatık kaşların

Neden birbirine vurur dişlerin

Bir anda yıkılan tatlı düşlerim

Doymadan yitirdim seni yollarda

Senimi beklerim sensizliğimi 

Senimi severim sensizliğimi 

Senimi ararım sensizliğimi

Bilmeden yitirdim seni yollarda

Son yıllarda neden sevdim maviyi 

Ayıramam doğru ile eğriyi 

Bir ateşmiş insanların sevgi dediği

Bulmadan yitirdim seni yollarda', 'Arayıp yıllarda bulamadığım Çalıp kapıları soramadığım  Hayaline bile doyamadığım Bulmadan yitirdim seni yollarda Hatıranı saklar yaşanan yı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yollarda-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Limandan Çıkmalı', 'limandan-cikmali-aydin-erkurt-1min1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalın bir yorgan gibi yıllar,

Hem sıcak, hem ağır.

Tozlanan yastıkları silkeleme zamanı.

Eski yelkenlimizi, bezleri ile beraber yıkamalı,

Ne varsa, geride bırakıp,

Limandan çıkmalı.

Önce kalp odasının örümcek ağlarından kurtulmalı.

Vebasız bir gezegen,

Kurutmayan bir güneş bulmalı,

Okyanusları  uçarken,

Belki de sövüp saymalı,

Ama; 

İlla; 

Limandan çıkmalı.', 'Kalın bir yorgan gibi yıllar, Hem sıcak, hem ağır. Tozlanan yastıkları silkeleme zamanı. Eski yelkenlimizi, bezleri ile beraber yıkamalı, Ne...', ARRAY['Türk Edebiyatı','Şiir','Aydın Erkurt']::text[], 8.5, '{"poet":"Aydın Erkurt","poet_slug":"aydin-erkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/limandan-cikmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınım', 'kadinim-aydin-erkurt-lldp4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şerbetlenmiş felek ısırganına,

Nektardır,  ağulu teri.

Çıyanlar beslemiş

Çöllerde sulamış yüreğini.

Gözler hala doğuda,

Ayaklar; okyanus mavi.

Susmaz, 

Bebek düşlerin, teneke trampeti,

Devam eder dua.

Umutlar acı verir, aşk beklenti.

Göçmen kuşun,  kırık kanadında

Gelir yitmenin, zemherisi.

Buz rengi ağlar düşer can üstüne,

Kadınım! 

Kaf dağının, sevda işlemesi.', 'Şerbetlenmiş felek ısırganına, Nektardır,  ağulu teri. Çıyanlar beslemiş Çöllerde sulamış yüreğini. Gözler hala doğuda, Ayaklar; okyanus mav...', ARRAY['Türk Edebiyatı','Şiir','Aydın Erkurt']::text[], 8.5, '{"poet":"Aydın Erkurt","poet_slug":"aydin-erkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kadinim-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk milleti', 'turk-milleti-tuncay-akdeniz-8hkye', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'TÜRK MİLLETİ

Milli marşım okundukça

Var olmamız her gün lazım

Türk milleti yaşadıkça

Er olmamız her gün lazım

Haklar eşit her insana

Ne dayıma ne amcama

Adaletli her makama

Ser olmamız her gün lazım

Arkasını tutanlara

Tıka basa yutanlara

Dışa toprak satanlara

Zor olmamız her gün lazım

Yalakalık hile ile

Dağıttılar bile,bile

Son diyelim güle,güle

Dar olmamız her gün lazım

Huzur güveni bozana

Misyoner gibi gezene

Dine Kuran''a ezana 

Sur olmamız her gün lazım

Mazlumu yetim düşkünü

Üşümesinler kış günü

Deprem afet sel taşkını

Yar olmamız her gün lazım

Tuncayım T.C. uyruğu

Ay yıldızlı al  bayrağı

Bizde peygamber sancağı

Bir olmamız her gün lazım', 'TÜRK MİLLETİ Milli marşım okundukça Var olmamız her gün lazım Türk milleti yaşadıkça Er olmamız her gün lazım Haklar eşit her insana Ne dayı...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/turk-milleti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Özveri İster', 'sevgi-ozveri-i-ster-i-lknur-cekici-x44xn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzelliğin kalmaz elbet

Solarsın günü geldiğinde

Ben yanına kalanım

Sevgime sahip çıkanım

Ey aşka,asi başını

Akıtma gözyaşımı

Sevgiyi gücendirmeden

Yıllar geçip gitmeden

Sevgi özveri ister

Gül gibi ilgi bekler

Onu gücendirirsen

Gecene hasret girer

Hasretin bağrında

Kalırsın tek başına

Sevgimde yetmez artık

Bu aşkı yaşatmaya', 'Güzelliğin kalmaz elbet Solarsın günü geldiğinde Ben yanına kalanım Sevgime sahip çıkanım Ey aşka,asi başını Akıtma gözyaşımı Sevgiyi gücend...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgi-ozveri-ister-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberi Yok ki', 'haberi-yok-ki-osman-i-nci-8vpgi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gezerim divane gibi, çarşı-pazar,

Azrail peşimde, bana mezar kazar,

Bu koca cihan, benim olsa ne yazar,

Sevdiğimin benden, haberi yok ki…

Kaderi yenmek için, koşup durdum,

Beş para etmez oldu, benim postum,

Bütün dünya alem, olmuş ta dostum,

Sevdiğimin benden, haberi yok ki…

Kızarlar bana, niçin bağlandın diye,

Onun varlığı bana, en büyük hediye,

Mutlu olmalıymışım, sanki ne diye? 

Sevdiğimin benden, haberi yok ki…

Gözleri, çakmak çakmak beynimde,

Saçları uçuşur, uzayan gecelerimde,

Sözleri yaşa döndü, her iki gözümde,

Sevdiğimin benden, haberi yok ki…', 'Gezerim divane gibi, çarşı-pazar, Azrail peşimde, bana mezar kazar, Bu koca cihan, benim olsa ne yazar, Sevdiğimin benden, haberi yok ki… Ka...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haberi-yok-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-kemal-cakir-384kh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnan bana güzelim; 

Sensiz olduğum her an 

Akıp gidiyor gözlerimde zaman. 

Ne kadar derine nakşetmiş de olsam seni

Yılların acımasızlığında 

Unutulup gidiyor  hatıran.', 'İnan bana güzelim;  Sensiz olduğum her an  Akıp gidiyor gözlerimde zaman.  Ne kadar derine nakşetmiş de olsam seni Yılların acımasızlığında ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/zaman-186-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muamma', 'muamma-kemal-cakir-2plaa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni bana sordular anlatamadım,

Seni bana anlattılar tanıyamadım.', 'Seni bana sordular anlatamadım, Seni bana anlattılar tanıyamadım....', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/muamma-186-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suç Ve Ceza', 'suc-ve-ceza-atahan-cakir-abantli-pzrl6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Esir ol hakketmediğin koltuğunun haşmetine

Ye, iç, denizlerce servet kat olmayan servetine 

Alınırsın koltuğundan bir gün, dönersin eski günlere

Sorgulanır, yargılanırsın; hem derinden derine

Sonuçta “suçsuzsun” derler, bak şu Allah’ın işine.', 'Esir ol hakketmediğin koltuğunun haşmetine Ye, iç, denizlerce servet kat olmayan servetine  Alınırsın koltuğundan bir gün, dönersin eski gün...', ARRAY['Türk Edebiyatı','Şiir','Atahan Çakır Abantlı']::text[], 8.5, '{"poet":"Atahan Çakır Abantlı","poet_slug":"atahan-cakir-abantli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/suc-ve-ceza-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim seni.', 'sevdim-seni-dilan-tan-flfo0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdim seni.

Hayatı sever gibi.

Nefes almayı özler gibi.

Sevdim seni su gibi, aş gibi,

Gözümdeki yaş gibi,

Sevdim seni.

Sana ağlamayı deli gibi,

Sana yanmayı kor gibi,

Sana kavuşmayı yol gibi,

Sevdim seni tapar gibi,

Sevdim seni ölüme koşar gibi,

Sevdim mezara girer  gibi,

Saniye saniye diri diri,

Sevdim seni dua gibi,

Sevdim dilime dolanmış türkü gibi

Ağıt gibi kan kokan,

Sevdim seni su gibi, aş gibi, ana gibi toprak gibi...

Sadece sevdim seni tapar gibi,

Canıma kıyar gibi,

Ölüme gider gibi,

Dün gibi...

Tükeniş gibi...', 'Sevdim seni. Hayatı sever gibi. Nefes almayı özler gibi. Sevdim seni su gibi, aş gibi, Gözümdeki yaş gibi, Sevdim seni. Sana ağlamayı deli g...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevdim-seni-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lahit', 'lahit-atahan-cakir-abantli-afi3s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle donuk ki bakışları

Sanki gözleri bir heykele ait

Ömrü boyunca bütün sırları

Saklamış içinde olmuş lahit.', 'Öyle donuk ki bakışları Sanki gözleri bir heykele ait Ömrü boyunca bütün sırları Saklamış içinde olmuş lahit....', ARRAY['Türk Edebiyatı','Şiir','Atahan Çakır Abantlı']::text[], 8.5, '{"poet":"Atahan Çakır Abantlı","poet_slug":"atahan-cakir-abantli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/lahit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne zaman gittin...', 'ne-zaman-gittin-dilan-tan-e5juv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen gittiğinden beri martıları seyrediyorum.

Acıyla karışık yosun kokan denizde.

Ne zaman gittin,

Ne vakit hatırlamıyorum.

Ne derin sevmişim, sensizlik ne acı

Hiç bilmezdim martıları, denizin yosun kokusunu

Artık biliyorum

Ne zormuş seni sevmek, sensizlik ne acı

Şimdi anlıyorum

Sigaramın dumanı zehir

Sensiz çekiyorum ciğerime, sen diye

Ne zaman gittin bu kaçıncı sigara

Kaçıncı zehir,

Kaçıncı sen,

Hatırlamıyorum...', 'Sen gittiğinden beri martıları seyrediyorum. Acıyla karışık yosun kokan denizde. Ne zaman gittin, Ne vakit hatırlamıyorum. Ne derin sevmişim...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ne-zaman-gittin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem Ve Silah', 'kalem-ve-silah-atahan-cakir-abantli-rdhxi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yakışmaz silah

Kalem tutan ellere

Onca mürekkep boşuna mı

Boşuna mı kazınmıştır düşüncesine

Sevgi,dostluk,hoşgörü kavramı? 

Sevdiremezsin kalemlere

Kan dokulu,örümcek görüşlü mermiyi

Yer yoktur onda 

Silahlı hiçbir düşünceye.

Yıkılan her can

Yakılan, yok olan düşüncedir

Neyi temizlemiş şimdiye kadar kan

Onun dizeleri hep sevgiyedir.', 'Yakışmaz silah Kalem tutan ellere Onca mürekkep boşuna mı Boşuna mı kazınmıştır düşüncesine Sevgi,dostluk,hoşgörü kavramı?  Sevdiremezsin ka...', ARRAY['Türk Edebiyatı','Şiir','Atahan Çakır Abantlı']::text[], 8.5, '{"poet":"Atahan Çakır Abantlı","poet_slug":"atahan-cakir-abantli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kalem-ve-silah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Töre', 'tore-dilan-tan-yha9v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Asırlardır  sevdiğim; 

Kısmetimsin,

Yazımsın,

Karayazımsın çözemediğim,

Töremsin kurşunların gölgesinde

Kabuslarımsın kara gecelerde,

Boğulurcusuna uykularda,

Kurşun acısında sevdim seni.

Kan sıcaklığında,

Ölümün soğuk tebessümünde gördüm seni.

Sevdamdın sen benim.

Hiç bitmeyen karayazım,

Dağlardan düşer,denizde boğulur gibi

Gök gibi bir mavi, bir siyah sevdamdın

Mehtapta ürkek sevdam

Hala aklımdasın hala...

Sevmiştim delicisine

Gözleri kör bu sevdanın...', 'Asırlardır  sevdiğim;  Kısmetimsin, Yazımsın, Karayazımsın çözemediğim, Töremsin kurşunların gölgesinde Kabuslarımsın kara gecelerde, Boğulu...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tore-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman...', 'zaman-dilan-tan-gjhzw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalan sözleri yalan tebessümlerle birleştirdik adını da AŞK koyduk...

Acı çektik,

Ağladık,

Göçtük yabancı diyarlara hıçkırıklarla,

Aşk uğruna, yalan uğruna...

Yinede vazgeçmedik bu yalan oyunu oynamaktan

Zaman sevdamı alıp gidiyor,

Zaman beni sevdamdan çalıp gidiyor.

Zaman gençliğime kıyıp gidiyor.

Sensiz saniyeler sessiz akıyor.

Zaman yaşlı ruhumu ağlatıp duruyor.

Ah zaman zalim zaman,

Dünümü saklayan,

Yarınımı kaçıran,

Gençliğimi çabuk harcayan zaman

Yoruldum hızından ağır ağır git zaman...', 'Yalan sözleri yalan tebessümlerle birleştirdik adını da AŞK koyduk... Acı çektik, Ağladık, Göçtük yabancı diyarlara hıçkırıklarla, Aşk uğrun...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zaman-187-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ermeni', 'ermeni-aynur-baydar-utb5d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Türk dostu ermeni Edward Taşçı yoğun bakımda 

''Benim ailem 70 milyonluk Türk milleti'' diyen ermeni asıllı Türk dostu Edward Taşçı Jewish Medical Center''de tedavi ediliyor. 

NEW YORK - Ermeni soykırım iddialarına karşı hayatı boyunca Türklerin yanında yer alan Ermeni asıllı Türk dostu Edward Taşçı, New York''ta kaldırıldığı hastanede komaya girince yoğun bakıma alındı. Yakınlarından edinilen bilgilere göre, iki böbreği de çalışmayan 72 yaşındaki Taşçı, geçen cuma günü aniden fenalaşınca, Long Island Jewish Medical Center''a kaldırıldı. Önceki gece oksijen maskesinin düşmesi sonucu bir süre nefes alamayan Taşçı''nın beyninde hasar meydana geldiği ve bunun sonucunda komaya girdiği kaydedildi. Halen yoğun bakımda bulunan ve hayati tehlikeyi atlatamayan Taşçı''nın durumunun kritik olduğu ifade edildi. New York ve çevresinden Türk dostları hastaneye akın ederken, yıllarca katkıda bulunduğu Türk-Amerikan Dernekleri Federasyonu''na da (TADF)  sayısız geçmiş olsun mesajı geldiği kaydedildi. Son 20 yıldır TADF halkla ilişkiler direktörlüğünü yürüten Taşçı, Osmanlı Ermenisi bir anne-babanın oğlu olarak Amerika''da dünyaya geldi. Bütün yaşamı Amerika''da geçmesine rağmen kendi gayretleriyle Türkçe öğrenen Taşçı, ''vatanım'' dediği Türkiye ve Türk kültürü sevgisiyle tanınıyor. Başta Ermeni lobileri olmak üzere, ABD''de Türkiye''yi karalamaya çalışan tüm gruplara karşı hep Türk tezlerini savunan Taşçı, özel hayatının her kesimine de Türkiye ve Türklük sevgisinin izlerini taşımakla biliniyor. Otomobilinin plakasını bile ''Vatan'' olarak seçen Taşçı, sürekli olarak ay-yıldız şeklinde kolye takıyor. Her yıl hiç aksatmaksızın New York''ta yapılan Türk yürüyüşüne katılarak büyük bir Türk Bayrağı taşıyan Taşçı, mektuplarını, üzerinde ''Bana Türk dostu derler'' yazısı bulunan bir mühürle imzalıyor. New York''un Queens semtinde bulunan evini Topkapı Sarayı''nın minyatürü şeklinde inşa eden Taşçı, bu evi yine Osmanlı esintileri taşıyan sayısız eşyayla süsledi. Taşçı, paha biçilmez Türk sanat eserleri koleksiyonlarının yanı sıra geniş bir Türkçe taş plak koleksiyonuna da sahip bulunuyor. Bugüne kadar Ermeni iddialarına karşı, bu iddialara destek veren Amerikalı politikacı, bilim adamı, şirket, medya organı, öğretmen ve din adamlarına binlerce mektup yazan Taşçı, 1960''lardan bu yana New York''ta ve Washington''da görev yapan tüm Türk diplomatları tarafından saygı gösterilen bir isim. 40 yılı aşkın bir süredir Mary Taşçı ile evli olan Taşçı''nın çocuğu bulunmuyor. Yakınlarına daima, ''Benim ailem 70 milyonluk Türk milletidir'' diyen Taşçı''nın, vefatı durumunda Türk bayrağına sarılı olarak Türkiye''de defnedilmeyi vasiyet ettiği belirtiliyor. TADF yetkililerinin, eşinin de rıza gösterdiği bu vasiyeti gerçekleştirmek için gerek Türkiye''nin New York Başkonsolosluğu, gerekse Dışişleri Bakanlığı nezdinde girişimde bulunduğu ifade ediliyor. Taşçı''nın vasiyetleri arasında, sayısız Türk sanat eserinin yer aldığı evinin bir Türk tarafından müze olarak korunması da bulunuyor. Türk dostu Taşçı, son olarak, ''Bana Türk Dostu Derler-Ermeni İddiaları, Gerçek Söylenmeli'' adıyla, Ermeni soykırım iddialarına cevap teşkil eden bir kitap yazmıştı. Baskısı tamamlanan kitabın gelecek günlerde piyasaya çıkması bekleniyor. 

EDWART TAŞÇI BİZİ BÖLMEYE ÇALIŞAN HER TÜRLÜ ZİHNİYETE EN GÜZEL CEVAPTIR. TÜM ÖMRÜNÜ VATANI VE MİLLETİ İÇİN HARCAMIŞ EN BÜYÜK MİLLİYETÇİLERDEN BİRİDİR. O HOŞGÖRÜ VE DEV KÜLTÜRÜMÜZÜN EVLADIDIR. AL BAYRAĞIMIZ ONU ŞEFKATLE SARACAK VE TÜRK, KÜRT, LAZ, ÇERKEZ, TATAR ALEVİ SÜNNİ ŞEHİTLERİN KANIYLA SULANMIŞ VATAN TOPRAĞINDA ŞEREFLE YERİNİ ALACAKTIR.', 'Türk dostu ermeni Edward Taşçı yoğun bakımda  ''Benim ailem 70 milyonluk Türk milleti'' diyen ermeni asıllı Türk dostu Edward Taşçı Jewish Med...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ermeni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ı Bahar', 'ask-i-bahar-ali-gencay-cha6p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ruhumu emziren kadın

Göğsünde aşk, gözlerinde nar

Öpsem dudaklarından

Dökülür ölüme efsunlar

Geldin! 

Eteklerinde rüzgâr

Eridi buzdan çehrem

Gitti! 

Beynimden zonklamalar

Çiğdemler açmış tenin

Kokunda bahar

Çise serpilmiş sesine

Konuşmazsan! 

Yağmaz yağmurlar', 'Ruhumu emziren kadın Göğsünde aşk, gözlerinde nar Öpsem dudaklarından Dökülür ölüme efsunlar Geldin!  Eteklerinde rüzgâr Eridi buzdan çehrem...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ask-i-bahar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçu Çocuk Olmak Gözlerinin', 'sucu-cocuk-olmak-gozlerinin-ahmet-tekin-2-wsjki', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'suçu çocuk olmak gözlerinin

öylece masumdurmak

nefretsiz öfkesiz durmak

gözlerinin suçu gülecekbirşeylerbulmakher daim

oysa seninde yüreğine saplanmış kazıklarvardır

devası bulunmaz suçundan üstün

derin yaralar açan bıtıraklı kazıklar

nasıl dayandın bilmiyorum

nasıl yaşadın her kaynaştığında kanayan yaralarınla

nasıl takmadın sümbüllerine bile takılan dikenleri

nasıl inat edebildin hiç yılmadan

deli fırtınalar çıktı yollarına götürmek isteyenseni

yollarına uçurumlar kazdılar düşesin diye çıkmazlara

düşesin diye düşlerine girdiler çoğukez

çoğukez aldılar sevdiklerini elinden

oysa seninde yüreğine saplanankazıklar vardı

ve suçu çocuk olmaktı gözlerinin

biliyorum senin yüreğini

bir cam kadar saydam ve şeffaftır

bir damla su kadaraziz ve sade

biliyorum senin yüreğini

her zaman bir fenerin vardırkaybolmuşlara yol gösteren

şu nefsin şaaşalı,yalancı güzelliğine aldananları

sahte gülücüklerden sıkılanları

karamsarlığın girdabında can havliyle çırpınanları

çerkip çıkarayım diye biçırpıda biçareleri

her zaman bir halat taşırsın yanında alemden habersiz

biliyorum senin yüreğini

sözde küçük birsızısı vardır ötelerinde

sebebi hicran küçük bir sızısı vardır

yine söylüyorum suçu çocuk olmak gözlerinin', 'suçu çocuk olmak gözlerinin öylece masumdurmak nefretsiz öfkesiz durmak gözlerinin suçu gülecekbirşeylerbulmakher daim oysa seninde yüreğine...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tekin 2']::text[], 8.5, '{"poet":"Ahmet Tekin 2","poet_slug":"ahmet-tekin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sucu-cocuk-olmak-gozlerinin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşklardan korkmaya başladım artık', 'asklardan-korkmaya-basladim-artik-ziya-nizam-e6fv3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşklardan korkmaya başladım artık

Sensel terkedişler yıktı hep beni

Vurdum kadehleri hayalinin tebessümüne

Bırakıp gitmelerinin

Acısını hissettim kalbimin atışlarında

Adını gördüm rakı şişesinin dibinde

Şişecam özenle işlemişti sanki

Sırf bana nispet olsun diye.

Çilingir soframa meze yaptım seni bu akşam

Sigarama ateş.

Çıkan dumana adını işledim

Motif motif,halka halka.

Akıtamadığım gözyaşlarımla

Daha bir içime gömdüm yokluğunu.

Dağlar büyüklüğünde

Sancılar girdi mideme.

Sen şimdi dersin

“Gazdır o gaz”

Değil işte...

Bu seferki; 

		Sensizlik.

Anlamıyor musun? 

Yapamıyorum işte sensiz.

Çekilmiyor dalgalar

Hep eksik kalıyor

Rüzgarın getirdiği kokular.

Yakamozlar şirin gelmiyor artık.

Oysa seninleyken

Nasılda severdim onları.

Sanki sen yansırdın suya.

Ve ben bilemezdim

Sana mı aşığım yoksa onlara mı? 

Şimdi de bilemiyorum

Yakamozlardan mı nefret ediyorum

Yoksa kendimden mi? 

...

Yoksunluk zor! 

Yoksunluk acı! 

Sensizlik ölüm! 

Sensizlik yavaş...

Sensizlik yavaş yavaş ölüm...

Sensizlik son.

		Dönme artık bana,

		Çünkü; 

		Sensizliğe alıştığım gibi

Ölüme de alıştım.

	Kal artık oralarda...

			12.03.1998-Perşembe

			01:15 İbo’nun Ev Çerkezköy', 'Aşklardan korkmaya başladım artık Sensel terkedişler yıktı hep beni Vurdum kadehleri hayalinin tebessümüne Bırakıp gitmelerinin Acısını hiss...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/asklardan-korkmaya-basladim-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyar-ı alemlerde dalmışım sevgine', 'diyar-i-alemlerde-dalmisim-sevgine-ziya-nizam-821y4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Diyar-ı alemlerde dalmışım sevgine

Unutmuşum hayal kurmanın yanlışlığını

Sevsem demişim,

Çekinmeden.

Bir sarhoş akşamda haykırsam sana

Korkmadan bağırsam seni seviyorum diye.

Duysam ki anlatmışlar beni

Yalan yanlış doldurmuşlar aklına.

Çekmişsin sevgini hayallerimden

Sevmem,istemem demişsin.

Boş ver,

Benim dünyam bana ait,

Bende kalsın demişsin.

Duydum ki; 

	İnanmışsın başkalarına

		Kaçmışsın sevgiden

Ayrı kalmışsın seni seven ellerimden,

Kahırlara sürmüşsün beni.

			02.11.2001

			11:37 İbo’nun Ev Çerkezköy', 'Diyar-ı alemlerde dalmışım sevgine Unutmuşum hayal kurmanın yanlışlığını Sevsem demişim, Çekinmeden. Bir sarhoş akşamda haykırsam sana Korkm...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/diyar-i-alemlerde-dalmisim-sevgine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmadı Günüm', 'kalmadi-gunum-i-lyas-kambali-zqwvg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Lime olmuş yaralarım

Merhem almıyor

Söyleyin o yâre kem söz etmesin

Kalmadı günüm  ben ölüyom

Yâr olmuyor

Beklemesin yârenlerim

Yarın olmuyor

Söyleyin dostlara kem göz etmesin

Kalmadı günüm ben ölüyom

Yâr olmuyor

Hastalanmış, paralarım

Deva olmuyor

Söyleyin dostlara selam etmesin

Karardı bahtım söz oluyor

Dert oluyor

Kağıt almış karalarım

Kalem yazmıyor

Söyleyin anneme name yazmasın

Kırıldı gönlüm kâr etmiyor

Söz oluyor

İlyas KAMBALI

05/04/1999', 'Lime olmuş yaralarım Merhem almıyor Söyleyin o yâre kem söz etmesin Kalmadı günüm  ben ölüyom Yâr olmuyor Beklemesin yârenlerim Yarın olmuyo...', ARRAY['Türk Edebiyatı','Şiir','İlyas Kambalı']::text[], 8.5, '{"poet":"İlyas Kambalı","poet_slug":"i-lyas-kambali","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kalmadi-gunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm...', 'olum-dilan-tan-zzhkp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Usul usul geliyor ölüm benden yana.

Yapraklar vefasızca terk ediyor sonbahar hüznünü taşıyan ağaçları acımasızca.

Bilmiyorum neden ağlıyorum her sonbaharda...

Yorgunum...

Merakla  ölümü özlüyorum korkuyla.

Ben ölüyorum.

Yapraklar daha  vefasız

Sonbahar daha hüzünlü

Sende gidiyorsun vefasız yapraklar gibi.

Sonbahar ağlıyor.

Ben ağlıyorum

Sırlarımla kaçıyorsun,

Dünyamı yıkıyorsun,

Ağlayamıyorum gözyaşlarım sen kokuyor.

Yorgunum...

Terkedilmişlik yordu çocuk yüreğimi.

Bilmiyorum yasım kaç

İhtiyar bir yürek taşıyorum genç gözlerimde

Seni özlüyorum

Ve ölüm geldi bana yapraklar gibi vefasız değil...', 'Usul usul geliyor ölüm benden yana. Yapraklar vefasızca terk ediyor sonbahar hüznünü taşıyan ağaçları acımasızca. Bilmiyorum neden ağlıyorum...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olum-165-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-tuncay-akdeniz-az4uf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok bilmişler söyler,söyler durulur

Çok bilene sırrın verme arkadaş

Gönül bir cevherdir atma kırılır

İnsanı aşağı görme arkadaş

O güzel zamanın vaktini beşle

Tartında ibrenin milini eşle

Her işin başını erkenden başla

Faydasız bir işe girme arkadaş

Sakın ortak olma oyun bozana

Dikkat etmen lazım kuyun kazana

Hoş görülü davran sana kızana

Cahille kafanı yorma arkadaş

Tuncay diyor ölçtü biçtiler beni

Kaptansız rotasız yüzer mi gemi

Hoş görü muhabbet yüceltir seni

Sakın insan kalbi kırma arkadaş', 'Çok bilmişler söyler,söyler durulur Çok bilene sırrın verme arkadaş Gönül bir cevherdir atma kırılır İnsanı aşağı görme arkadaş O güzel zama...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/arkadas-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martılar', 'martilar-ozgur-kokturk-zeky5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Martıların çığlıkları

Ve çiseleyen yağmur damlaları

Bir yanımda gelip geçen güzel insanlar

Bir yanımda can yoldaşım, dert ortağım

Serin rüzgâr daha da essin

İçimdeki yangın dinsin

Seni sevmek nasıl bir şey

Sen bunu nereden bilirsin', 'Martıların çığlıkları Ve çiseleyen yağmur damlaları Bir yanımda gelip geçen güzel insanlar Bir yanımda can yoldaşım, dert ortağım Serin rüzg...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/martilar-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Telaş', 'telas-ozgur-kokturk-ztt50', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiçliğin telaşındayım şimdi

Bu uzamış sakallar

Bu kararmış tırnaklar

Bu sararmış dişler

Bu yontulmuş düşler benim mi

Yoksa yok olmuş bir hiçin mi? ! .

Girer miyim ansızın düşlerine

Haber vermeden

Gizlice

Yasa mı boğarım sevmemiş yüreğini

Sevilmemiş yüreğimle...

Uzanır mısın olmayan ellerime

Utanır mısın yoksa mahrem gecelerimden? ! .

Yağmur kokusu siner mi senin de gözlerine

Siler mi uykuna bulaşmış sevdamı kirpiklerine

Masum bir ecel benimki

Ellerinle verdiğin ellerime...

Uyanacaksın sen de bir ölüm vakti

Kimsesiz kalmış hiçliğinle...', 'Hiçliğin telaşındayım şimdi Bu uzamış sakallar Bu kararmış tırnaklar Bu sararmış dişler Bu yontulmuş düşler benim mi Yoksa yok olmuş bir hiç...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/telas-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudaklarının Kapısı', 'dudaklarinin-kapisi-palo-keko-vi5p7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaç kez öldüm 

dudaklarının kapısından

sürgün edilirken öpücüklerim

ve gözlerini sonuna kadar

kapatırken rüyalarıma.

vatanım gözyaşları oldu ardından,

kaburgalarımın ovasına

devrildi acının tüm ağaçları

portakal bahçesi yüzünde açtı

bahar sergisini

ben mahrumiyet terazisinde tartıldım gözlerinle.

ağlasam kumaşı eksik kalıyor ırmakların,

bir çocuk devriliyor 

yakılmış umut çalılarının içine 

bir kadın ayaklarını çırpıyor

ağladığım sokaklarda 

dağlı bir inilti alıyor 

bakışlarımdaki masumiyeti

yüzümdeki kuş yuvalarını

firaun rüzgarları süpürdü 

ve içimdeki oyuklara

sesin doluyor...kezzapp

gölgemin katları altında solmuş bedenim 

en uzun şarkısı oluyorum gitarının,

kırık besteler dökülüyor gözyaşlarımdan

toplasan aşklar coğrafyasında

bir ülke olur yalnızlığım_palo', 'Kaç kez öldüm  dudaklarının kapısından sürgün edilirken öpücüklerim ve gözlerini sonuna kadar kapatırken rüyalarıma. vatanım gözyaşları oldu...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dudaklarinin-kapisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koş (-ma) , Kendini dinle!', 'kos-ma-kendini-dinle-zafer-yazici-ylbdh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Koş! 

Arkanda bir toz bulutu bile bırakmadan

Deli gibi koş! 

İz bırakma geriye, bırakırsan yakalanırsın! 

Bakma geriye, ne var ki gerilerde ilginç olan? 

Bakarsan aldatırlar yine! o zamanda aldatmışlardı, 

Ne çabuk unuttun? .. 

Sen zaten hem koşup, hem bakamazsın geriye

Takılır düşersin yüzükoyun! 

Ya da çarparsın bir direğe burun üstü! ..

O yüzden sen en iyisi mi sadece önüne bak! 

Umutlar, gelecek hep önünde duruyor! ..

Yarınlarına koş, seni bekleyenlere, hasretliklerine..

(…………..biraz mola…………)

Sakin ol ve dur! 

Neden koşuyorsun deli gibi? 

Nereye bu gidiş farkında mısın? 

Kime diyorum, dursana! 

Sen, evet sen, bana bakan! 

Bir dakika dur, 

Sakin ol..

Kendini dinle..

İçinde atan bir şey var..

Ona kulak ver..

Fark et! ..

Farkında ol kendinin! ..

Üzülmeye değer mi? ..

Düşün! ..

Sevdiklerinin olduğunu düşün..

Seni düşünenleri düşün..

Mutluluğu, aşkı düşün…

(…………..mola bitti…………)

Kaç! 

durmadan kaç, ne anlamı var, 

düşünme! seni aldatanlardan kaç! ,

Sana düşman olanlardan kaç,

Korkularından kaç! 

Yalnızlığından, öfkenden

___kaç! .. 

_______ma dur! 

Yüzleş korkularınla..

__________Ger göğsünü, yılma! 

Her zaman sev, 

………katışıksız, ……..saf bir yürek ile….. 

…………..AŞK ile..', 'Koş!  Arkanda bir toz bulutu bile bırakmadan Deli gibi koş!  İz bırakma geriye, bırakırsan yakalanırsın!  Bakma geriye, ne var ki gerilerde ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Yazıcı']::text[], 8.5, '{"poet":"Zafer Yazıcı","poet_slug":"zafer-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/kos-ma-kendini-dinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan olanı (hayalimdeki aşkım Aykan)', 'i-nsan-olani-hayalimdeki-askim-aykan-hayalimdeki-ask-eay27', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir selamla kuruldu gönül bağı 

Neşe dolduruyor tebessümle her anı 

Sende ol insan gibi samimi ve saygılı 

Kimdir dersen arabul insanın insan olanını 

Vardır onda güzellikler öfke ve kinden gayri 

Çok kolay bulunmaz eşi sevgiden dostluktan ayrı 

Yalansızdır onun sevgisi dostluğu ve aşkı 

Karşılıksız sever sevdiği insan gibi insanı 

Bir ol özünde sözünde insan misali 

İnsana yakışmaz hayvan makamı 

Sen asilsin sakın olma köle uşağı 

Mertliktir insan olmanın manası 

Karşılıksız sevmekle varılır insan makamına 

Yalansız olmadan insan olunur sanma asla 

Terk et sende sevmeyen kalbi sana olur bela 

Var git dostum sen insan olmanın tadını yaşa 

Budur duygusalın tavsiyesi kendine ve sana 

(yıllarca arayıpta bulamadığımı sandığım anda bana dünyalardan daha degerli bir sevgi dostluk ve aşk hayali yaşatan degerli ve asil ''insan örneğini temsil eden'' AŞKIM AYKAN`IMA ithaf ediyorum)', 'Bir selamla kuruldu gönül bağı  Neşe dolduruyor tebessümle her anı  Sende ol insan gibi samimi ve saygılı  Kimdir dersen arabul insanın insa...', ARRAY['Türk Edebiyatı','Şiir','Hayalimdeki Aşk']::text[], 8.5, '{"poet":"Hayalimdeki Aşk","poet_slug":"hayalimdeki-ask","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/insan-olani-hayalimdeki-askim-aykan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Su perisi', 'adi-su-perisi-alaattin-colak-blu2p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adı Su Perisi

kendisi dünya tatlısı 

Dörtte üçü denizlerle kaplı bir dünyada 

Nereye baksan onu görürsün 

Sevgi dağıtıcısıdır o 

Güldürmenin Ustasıdır 

hayatın hep yeşil ağacıdır 

Sonbahar olur 

Yapraklar dökülür 

Herkes karamsarlığa düşer 

Yetişir İmdada 

Mutluluk saçar 

Neşe saçar 

Güzellikler sunar 

Dünyadaki bütün güzellikler bir olur 

Mutlu etmek ister Onu

Oysa O dalar gider YILDIZLARA 

Belki de gökyüzündeki 

Milyonlarca Yıldızın da perisidir O

Işığı ile aydınlatsa da herkesi 

Kayar, Kayar 

Kimse yakalayamaz.', 'Adı Su Perisi kendisi dünya tatlısı  Dörtte üçü denizlerle kaplı bir dünyada  Nereye baksan onu görürsün  Sevgi dağıtıcısıdır o  Güldürmenin...', ARRAY['Türk Edebiyatı','Şiir','Alaattin Çolak']::text[], 8.5, '{"poet":"Alaattin Çolak","poet_slug":"alaattin-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/adi-su-perisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O An Anlarsın (hayalini kuruğum sevgiliye)', 'o-an-anlarsin-hayalini-kurugum-sevgiliye-hayalimdeki-ask-8iq4r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün karşına deli gibi seveceğin biri çıkarsa 

Sen onun için kahrolurken o aldırmazsa 

Seninle alay edip gururunu kırarsa 

İşte benim neler çektiğimi o an anlarsın 

O kişi önce sevip sonra terkederse 

bütün ümitlerini yıkıp seni mahfederse 

Sen acı çekerken o arkandan gülerse 

İşte benim neler çektiğimi o an anlarsın 

Göz yaşını tutamayıp hergün ağlarsan 

Ona olan sevginle günden güne yanarsan 

Onu unutamayıp hala görmek istersen 

işte benim neler çektiğimi o an anlarsın 

Ona olan sevgin nefrete dönerse 

Unut dedikçe kalbin daha çok severse 

Dostların düşmanların bu haline gülerse 

Benim neler çektiğimi o an anlarsın 

Hergün çaresizliği yudum yudum içersen 

Tükenip bu sevdadan hayata küsersen 

Çektiğin acıyı unutmak için hep ölmek istersen 

İşte benim neler çektiğimi o an anlarsın 

Sevda yüklü yüreğini ayaklArına serersen 

O ilgilenmeyip kalbim dolu sevemem derse 

İşte o an başından kaynar sular dökülürse 

Tüm bedenin volkan gibi titreyip öldüğünü hissedersen 

Sevipte sevilmemek nedir o an anlarsın 

Bir yudum sevgi için gözlerine bakarsan 

Kalbindeki sevgiyi gözlerinde fırat gibi akıtırsan 

Seni sevsin diye ölüme bile hazırsan 

Kahrolmuşluğu yalnızlığı çaresizliği o an anlarsın 

Yine birgün yolda ona rastlarsan 

Ümit edipte sever diye beklersen 

O na koştuğunda kovulursan 

YAŞARKEN ÖLMEYİ O AN ANLARSIN', 'Bir gün karşına deli gibi seveceğin biri çıkarsa  Sen onun için kahrolurken o aldırmazsa  Seninle alay edip gururunu kırarsa  İşte benim nel...', ARRAY['Türk Edebiyatı','Şiir','Hayalimdeki Aşk']::text[], 8.5, '{"poet":"Hayalimdeki Aşk","poet_slug":"hayalimdeki-ask","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/o-an-anlarsin-hayalini-kurugum-sevgiliye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni sana anlatamam ki ben', 'seni-sana-anlatamam-ki-ben-hayalimdeki-ask-l8x0w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana şiir yazmak gelmiyor içimden 

Söylenen her kelime geliyor senden 

Senden geleni sana anlatamamki ben 

Sen değerlisin ay ve güneşten 

Güneş ısınırken senin kalbinden 

Seni sana anlatamamki ben 

Bu yürek yaralı seni ararken 

Akar sularım göz çeşmesinden 

Yalvarırım eksik etme tebessümünden 

Mutlu edersin beni bir damla sevginden 

Yüreğim yaşarken seni derinden 

Derdim derman bekler gözlerinden', 'Sana şiir yazmak gelmiyor içimden  Söylenen her kelime geliyor senden  Senden geleni sana anlatamamki ben  Sen değerlisin ay ve güneşten  Gü...', ARRAY['Türk Edebiyatı','Şiir','Hayalimdeki Aşk']::text[], 8.5, '{"poet":"Hayalimdeki Aşk","poet_slug":"hayalimdeki-ask","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-sana-anlatamam-ki-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben bir kumsaldım Sen bir dalga', 'ben-bir-kumsaldim-sen-bir-dalga-alaattin-colak-oh95y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben bir kumsaldım Sen bir dalga

Yokluğuna alışmalıyım

Varlığına alıştığım gibi

Ben bir kumsaldım

Sen bir dalga

Gelişinle mutlu ettin beni

Cesaret verdin

Huzur verdin

Hayat kattın

Şimdi deniz durulacak

Ve sen başka kumsala gideceksin

Gitmeden önce

Seni son defa içime çekip

Bir ömür yetecek kadar

Senden doldurmalıyım

Sen hangi kumsala gidersen git

Bil ki bu kumsaldan senin

Mutlu olman için dua edeceğim', 'Ben bir kumsaldım Sen bir dalga Yokluğuna alışmalıyım Varlığına alıştığım gibi Ben bir kumsaldım Sen bir dalga Gelişinle mutlu ettin beni Ce...', ARRAY['Türk Edebiyatı','Şiir','Alaattin Çolak']::text[], 8.5, '{"poet":"Alaattin Çolak","poet_slug":"alaattin-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ben-bir-kumsaldim-sen-bir-dalga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitemkar oldu', 'sitemkar-oldu-hayalimdeki-ask-w4v5l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugünde geçti yine tek başıma 

Günlerim sitem etti dostlarıma 

Aradım baktım sağıma soluma 

Sözüm insan olanlara 

Can fedadır varsa gerçek dostuma 

Hep aldattılar samimi dostlık ve sevgimi 

Bitince makamım şanım şöhretimi 

Kir saçtılar bedenime ruhuma 

Sözüm insan olanlara 

Can fedadır varsa gerçek dostuma 

Hala ararım bir hayal uğruna 

Makamdan şöhretten mada 

Böyle dost varmıdır acaba 

Sözüm insan olanlara 

Can fedadır varsa gerçek dostuma 

Cancazım derman bul bu gamdan 

Dost olmaz kıblesi para olandan 

Vazgeç şöhretten makamdan 

Açtım dostluk kapısı çıkarsız sana 

Sözüm insan olanlara 

Can fedadır varsa gerçek dostuma', 'Bugünde geçti yine tek başıma  Günlerim sitem etti dostlarıma  Aradım baktım sağıma soluma  Sözüm insan olanlara  Can fedadır varsa gerçek d...', ARRAY['Türk Edebiyatı','Şiir','Hayalimdeki Aşk']::text[], 8.5, '{"poet":"Hayalimdeki Aşk","poet_slug":"hayalimdeki-ask","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sitemkar-oldu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Papatya', 'papatya-alaattin-colak-32upi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzanmışsın yemyeşil çimlere

Rengarenk çiçekler arasındasın

Elinde bir papatya

Fal bakıyorsun

Belli ki seviyor çıkıyor 

Gülümsüyorsun

O ışıl ışıl sarı saçlarına

O güzelliğine

Dayanacak

Kimse yok ki

Sen de biliyorsun', 'Uzanmışsın yemyeşil çimlere Rengarenk çiçekler arasındasın Elinde bir papatya Fal bakıyorsun Belli ki seviyor çıkıyor  Gülümsüyorsun O ışıl ...', ARRAY['Türk Edebiyatı','Şiir','Alaattin Çolak']::text[], 8.5, '{"poet":"Alaattin Çolak","poet_slug":"alaattin-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/papatya-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Frezyalar Solmasın', 'frezyalar-solmasin-akif-ugur-r4fq4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hatırlıyor musun

Frezya mevsimiydi

Son görüştüğümüz

Belki de daha önceydi

Vedalaşıp öpüştüğümüz

Frezyaların açmasına

Ne kaldı ki şurada

Hadi söylesene

Ne kaldı ki sevgililer gününe

Sen hala yoksun

Sen sevdirmiştin

Frezyaları bana

Hatırlıyor musun

Elimde bir tutam

Frezya ve sümbülle 

Sevgililer gününde

Sana gelmiştim

Sen frezyalar kadar 

Güzel kokulu

Frezyalar senin kadar

Saf temiz ve buğulu

Frezyaları da seni de

Bilsen ne çok sevmiştim

Ne çok sevmiştim

İşte yine geldi

Frezya mevsimi

Depreştirdi sevgimi

Sen yine yoksun 

Oysa

Bana geldiğin zaman

Güller açardı yüzünde

Renk renk, desen desen

Destansı nağmeler 

Okunurdu gözünde

Sayfa sayfa, roman roman

Sınır tanımazdı arzular

Zaman mekan tanımazdı

Aşkın dört mevsimini

Hazzın en yücesini

Yaşardık seninle

Kısacık o zaman diliminde

Güçlü bir aşk dokunurdu

İlmik ilmik, nakış nakış

Gerçek bir sevda kiliminde

Sonra 

Dalgalar yükselirdi

Adam boyu

Ve bir uğultu kaplardı

Bu güzel koyu

O küçük 

Karadeniz sahilinde

Şimdi

Bir sessizlik çökmüş gibi

Sanki tüm koya

Yakamozlar da çekilmiş

Birer birer kuytuya

Ne o koyda bir seda

Ne de beyaz martılar

Artık yükselmez olmuş

Adam boyu dalgalar

Bense, önümde

Her dizesi, her bölümü

Seni anlatan

Umut dolu sayfalar

O yaşanmış anılar

Ve her dakikası

Bir ömre bedel

O güzel yıllar

Ve hep seni özleyen

Ve hep seni isteyen 

Bastırılmış arzular

Yorgun, bitkin ve yalnız

Koca bir yürekle

Seni beklemekteyim

Hadi git gidebilirsen

Adını hiç duymadığım

Hiç bilmediğim

Limanlara yelken aç

Her nereye kaçarsan kaç

Bir gün

Geri döneceksin

Ama frezya mevsimi

Geçmiş olacak

Elimdeki sümbüller

Frezyalar solacak

Yüreğimde

Pembe bir gül kalacak

Ve sen

Yalnızlıklar içerisinde

Bir ömür süreceksin

Geldiğin yere 

geri döneceksin

Göreceksin, göreceksin

               25. 1. 2004', 'Hatırlıyor musun Frezya mevsimiydi Son görüştüğümüz Belki de daha önceydi Vedalaşıp öpüştüğümüz Frezyaların açmasına Ne kaldı ki şurada Hadi...', ARRAY['Türk Edebiyatı','Şiir','Akif Uğur']::text[], 8.5, '{"poet":"Akif Uğur","poet_slug":"akif-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/frezyalar-solmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Çıplaktı Ayakların...', 've-ciplakti-ayaklarin-bekir-mutlu-gokcesu-2k5x2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyak seslerine uyandım dün gece...

Dudaklarında lirik fısıltısı

Eteklerinde pür telaşı aşkın

Bana geldin ve çıplaktı ayakların...

Sımsıkı tuttun ellerimi

Sonra kapayıp gözlerimizi

Salıverdik birbirlerine yüreklerimizi...

Her dokunuşta patladı, yağdı tepemizden

Havai fişekleri ruhlarımızın

Uçmaya durdum dudağından

Omuzlarından...

Gözlerin gözlerim oldu

İçtim aşkı avuçlarından...

Uyak seslerine uyandım dün gece...

Bir kokun var bende, ah... o şiir bakışın...

Bakışın birde...

Bana geldin ve çıplaktı ayakların

Islak topraklara bastık seninle özgürce...', 'Uyak seslerine uyandım dün gece... Dudaklarında lirik fısıltısı Eteklerinde pür telaşı aşkın Bana geldin ve çıplaktı ayakların... Sımsıkı tu...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ve-ciplakti-ayaklarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-cemal-gokmen-0oah2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şair olup mısralara döksem 

anlatılır mı kelimeler bilmem ki seni

ressam olup çizsem hayalini

fırçalar gösterir mi güzelliğini

bölük,pörçük,rüyalarda görsem seni

uykulara doyarmıydım sevgili

gel desen hani bana

beklerim sabaha

sabırsızlığımı duyarmıydın sevgili...', 'Şair olup mısralara döksem  anlatılır mı kelimeler bilmem ki seni ressam olup çizsem hayalini fırçalar gösterir mi güzelliğini bölük,pörçük,...', ARRAY['Türk Edebiyatı','Şiir','Cemal Gökmen']::text[], 8.5, '{"poet":"Cemal Gökmen","poet_slug":"cemal-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevgili-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu akşam', 'bu-aksam-cemal-gokmen-9u11k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu akşam 

aynalara gizledik hüznü..

çıkardık sandıklardan

sevinci,mutluluğu 

sardık yaralarımızı,yeni baştan...

Bu akşam

maziye baktık,en derinden..

kaybolan yıllara özlemle

sardık sevgiyi,en baştan..

Bu akşam

defterleri açıp,hesaplaşmaya başladık seninle

artı,eksileri topladık,çarptık,böldük..

netice

eşittirin,solunda sen,sağında ben..', 'Bu akşam  aynalara gizledik hüznü.. çıkardık sandıklardan sevinci,mutluluğu  sardık yaralarımızı,yeni baştan... Bu akşam maziye baktık,en de...', ARRAY['Türk Edebiyatı','Şiir','Cemal Gökmen']::text[], 8.5, '{"poet":"Cemal Gökmen","poet_slug":"cemal-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bu-aksam-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkiyüz elli lira', 'i-kiyuz-elli-lira-soner-demir-ng5ti', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir zamanlar binbir nazla bana verdiğin resmini; 

şimdilerde ikiyüz elli liraya satıyor gazeteler! ...

altında hazin bir intihar hikayesi......', 'bir zamanlar binbir nazla bana verdiğin resmini;  şimdilerde ikiyüz elli liraya satıyor gazeteler! ... altında hazin bir intihar hikayesi......', ARRAY['Türk Edebiyatı','Şiir','Soner Demir']::text[], 8.5, '{"poet":"Soner Demir","poet_slug":"soner-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ikiyuz-elli-lira-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçek mi', 'gercek-mi-cemal-gokmen-z6vvv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Onu görünce karşımda

bir meltem esintisi sarardı her yanımı

çocuksu gözlerine bakar

seni seviyorum derdim

gerçekmi diye sorardı

sevdiğimi söylemem hoşuna giderdi de

inanmazdı

tıpkı şiirlerime inanmadığı gibi

hergün o büyük parkın tek ıhlamur ağaçının

altında oturur

hayallarimi anlatırdım ona

bana gülerek,nasıl derdi,inanmazdı

varsın,yansın,izmir akşamları 

yazmasın kalemler kağıtlara

bugün inandığını söylerken bana

bende soruyorum sana

gerçekmi...', 'Onu görünce karşımda bir meltem esintisi sarardı her yanımı çocuksu gözlerine bakar seni seviyorum derdim gerçekmi diye sorardı sevdiğimi sö...', ARRAY['Türk Edebiyatı','Şiir','Cemal Gökmen']::text[], 8.5, '{"poet":"Cemal Gökmen","poet_slug":"cemal-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gercek-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Sevgisi', 'i-stanbul-sevgisi-akif-ugur-pjn28', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kara tren getirmişti beni sana

Yıllar öncesi,

Elimde eski bir valiz

Sırtımda ters çevrilmiş

Bir takım elbise.

Kadıköy vapuruna bindiğimde

Küçük dilimi yutacaktım

Nerdeyse.

Yemyeşil gerdanlık gibi önümde

Uzanıyordu boğaz,

Sana kaptırmıştım gönlümü İstanbul

Yüreğim, sana sevdalıydı o yaz.

Yeşilyurt,

Gözde mekanlardandı bir zaman

Ataköyde, Floryada geçen günler 

Bilseniz, 

Ne yamandı, ne yaman.

Kumkapı denince akla

Çamur Şevket gelirdi,

Dost meclisleri kurulur

Şarkılar söylenirdi.

Beyazıt Kulesinden

Camiler, minareler

Külliyeler görünürdü,

Hey! .. üniversitelim hey! ..

Kitaplar koltukta

Yenikapı’ya, 

Yakamoz’a yürünürdü.

Beyoğlu, Beyoğlu’ydu eskiden

Ütüsüz pantalonla 

Boyasız iskarpinle

Kravatsız, 

Beyoğlu’na çıkamazdık,

Şöyle gömlek düğmelerini 

Sereserpe açıp, 

Caka bile satamazdık.

Bir ahuya takılırdı gönül

Bebek’te,

Sürüklenirdi peşinden

Dalga dalga,

Ne hal kalırdı kolda

Ne de derman kürekte.

Kanlıca’nın şekerli yoğurdunu

Yemezsek hiç olmazdı,

Sevda Tepesi’nde

Sevdalı yüreklerde açan gül

Çamlıca’ya iner çıkar solmazdı.

Moda’dan Erenköy’e yürümek

Uzun zaman alırdı,

Ama her seferinde yüreğim

Bağdat Caddesi’nde kalırdı.

Bir Levent çiçek kokardı

Buram buram,

Orada yaşamak

Ayrı bir kavramdı

Ayrı bir kavram.

Gece boyu hiç susmazdı

Arnavutköy’ün neyleri,

Beni çağırırdı uzaktan

Emirgan’ın laleleri, gülleri.

Hey! İstanbul hey! 

Hani nerde yedi tepen

Fatih, Eyüp

Sultanahmet, desen desen,

Seher yeli gibi göğsümde esen.

Asırlara ışık tutan,

Ömürlere ömür katan İstanbul.

Seni tam anlatacak kelimeler

Henüz lügatlarda yok,

Seni çok seviyorum İstanbul

Çok seviyorum! .. çok! .. çok! ..

                    09. 06. 2003', 'Kara tren getirmişti beni sana Yıllar öncesi, Elimde eski bir valiz Sırtımda ters çevrilmiş Bir takım elbise. Kadıköy vapuruna bindiğimde Kü...', ARRAY['Türk Edebiyatı','Şiir','Akif Uğur']::text[], 8.5, '{"poet":"Akif Uğur","poet_slug":"akif-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/istanbul-sevgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ansızın', 'ansizin-ali-osman-tasci-g3405', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Takvimlerden yapraklar yavaş yavaş düşerken

Saçlarıma beyazlar sarılıyor ansızın

Yokluğun hançer gibi yüreğimi deşerken

Yüreğim yollarına seriliyor ansızın

Bir tenhada ellerim tutunca ellerini

Seyahate çıkıyor aklım,görünce seni

Gözyaşlarım düşerken yerlere deli deli

Ümitlerim cam gibi kırılıyor ansızın

Susmuş bütün dudaklar,bu hayat bitmez böyle

Ömrüm tükenmeden gel bana bir türkü söyle

Ayaküstü bir yerde karşılaşınca senle

Yüreğim bedenimden göç ediyor ansızın...', 'Takvimlerden yapraklar yavaş yavaş düşerken Saçlarıma beyazlar sarılıyor ansızın Yokluğun hançer gibi yüreğimi deşerken Yüreğim yollarına se...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Taşçı']::text[], 8.5, '{"poet":"Ali Osman Taşçı","poet_slug":"ali-osman-tasci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ansizin-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atalar böyle demiş', 'atalar-boyle-demis-tuncay-akdeniz-mgvlm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nice yiğitler öldürür

İçin de gizli kalan dert

Yanan ocağı söndürür

Erini sevmeyen avrat

Yağcılara geçme kıyak

Akılsız baş yorar ayak

Ne işe yarar ki dayak

Eşeği inadı inat

Ekme ikilik tohumu

Alma mazlumun ahı''nı

Tahtan indirir şahını

Mazlumdan alınan servet

Tuncay kendine güvenme

Senden yamanı var amma

Malın kurtaracak sanma

Önünü kesecek sırat

Not Bu şiir ata sözlerindendir', 'Nice yiğitler öldürür İçin de gizli kalan dert Yanan ocağı söndürür Erini sevmeyen avrat Yağcılara geçme kıyak Akılsız baş yorar ayak Ne işe...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/atalar-boyle-demis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Görüp Bir Kaybettim', 'bir-gorup-bir-kaybettim-akif-ugur-0hm2b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O zeytin gözlerini bir görüp bir kaybettim

Seni çok sevdiğimi sen gidince fark ettim

Yaman vurdu ayrılık ışıksız kaldı seher

Birlikte geçen günler nede güzelmiş meğer

Şimdi acı bir anı bırakıp gittiğin gün

Kaç kere öptüğünü şöyle bir kere düşün

Böyle bir ayrılığa yürekler dayanır mı

Al al olmuş duygular maviye boyanır mı

Mesafeler özlemi bitirirse zamanla

Yüreğimde sen varsın bunu iyice anla

Korkarımki gönüller aşka ferman biçemez

Her şeyden geçer gönül senden asla geçemez

					

				15 / 10 / 2004', 'O zeytin gözlerini bir görüp bir kaybettim Seni çok sevdiğimi sen gidince fark ettim Yaman vurdu ayrılık ışıksız kaldı seher Birlikte geçen ...', ARRAY['Türk Edebiyatı','Şiir','Akif Uğur']::text[], 8.5, '{"poet":"Akif Uğur","poet_slug":"akif-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-gorup-bir-kaybettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Diyerek Sana Geldim', 'dost-diyerek-sana-geldim-yusuf-ter-obeuu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dost diyerek sana geldim

kovma beni buralardan

bedenimde canım bildim

kovma beni buralardan

Gönül gözüm senden yana

Destur ver  geleyim bana

Saygım eksik etmem sana

kovma beni buralardan

bahçende gülün koklarım

dostumun sırrın saklarım

kırk yıl kapını beklerim

kovma beni buralardan

onca yıldır gülmez gözüm

sana bağlı özüm sözüm

sırtıma verip de sazım

kovma beni buralardan

girilmez kapılardan girdim

ağla yarime şiirim ağlasın

şirin yüzlüm tatlı dilim 

kovma beni buralardan

Yusuf’um zamana uydum

akıl başa geldi caydım

seni sevdim seni saydım

kovma beni buralardan

30.03.05

Saat 04:42 İsviçre 

www.yusufter.tr.cx', 'dost diyerek sana geldim kovma beni buralardan bedenimde canım bildim kovma beni buralardan Gönül gözüm senden yana Destur ver  geleyim bana...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dost-diyerek-sana-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ireniyorum kiz ben senden', 'ireniyorum-kiz-ben-senden-husamettin-guven-j66qw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sozde mahsun o gozlerden

Yalan dolu o sozlerden

Utanmiyan o yuzlerden

Ireniyorum kiz ben senden

Erkekmisali inadindan

Maskeli o suratindan

Supe dolu yavirlardan

Ireniyorum kiz ben senden

Iki ruhlu hareketten

Senden gelecek bereketten

Sahtekarce gulucukten

Ireniyorum kiz ben senden

Rest cekerek yatisindan

Terk ederek kacisindan

Bu yuvayi yikisindan

Ireniyorum kiz ben senden

Hollanda', 'Sozde mahsun o gozlerden Yalan dolu o sozlerden Utanmiyan o yuzlerden Ireniyorum kiz ben senden Erkekmisali inadindan Maskeli o suratindan S...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ireniyorum-kiz-ben-senden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün', 'huzun-kadir-ulu-nfpsz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaprak misali savrulsam

Sararıp solsam yok olsam

Sana dair kadehlerin içinde

Haykırışlarım çığlık çığlığa 

                          yükselirken; 

Öyle yağmur yağsaki

Buğulu gözlerin 

          masumluğunda; 

Baharı ağlıyor sansınlar

Sevdam sırıl sıklam

Benim kadar sarhoş olsa

Yalan olan hayallerim

Ay’ın soluk ışıklarında

Seninle maziye gömülsem

Hüzünler saraken 

                  kadehleri; 

Titrek ellerimle tutsam

Çırpınan tutsak kalpleri.', 'Yaprak misali savrulsam Sararıp solsam yok olsam Sana dair kadehlerin içinde Haykırışlarım çığlık çığlığa                            yükseli...', ARRAY['Türk Edebiyatı','Şiir','Kadir Ulu']::text[], 8.5, '{"poet":"Kadir Ulu","poet_slug":"kadir-ulu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/huzun-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbini Açarmısın?', 'kalbini-acarmisin-sahin-erturk-sawnc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana

KÜTAHYA yı değil

İSTANBUL u değil

Tüm TÜRKİYE yi

Dağlarıyla,Taşlarıyla

Denizleriyle,Ovalarıyla

Sırtlanıp getirsem

Kalemimde

Sevda şiirleri

Yüreğimde

Sevgi,Saygı,Özlem

Aşka susamışlık olsa

Kalbini,gönlünü

Kolunu,koynunu

Açarmısın bana

Açarmısın...? 

(31.03.2005-Yeni)', 'Sana KÜTAHYA yı değil İSTANBUL u değil Tüm TÜRKİYE yi Dağlarıyla,Taşlarıyla Denizleriyle,Ovalarıyla Sırtlanıp getirsem Kalemimde Sevda şiirl...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kalbini-acarmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zulum', 'zulum-husamettin-guven-inm0h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kurumus agac gibi curuyor su bedenim

Icin icin eriyor bir gun olur giderim

Mutlu kalin  dunyada sozde beni sevenlerim

Yaptigi zulumleri kardan sayip ovenlerim

Cok gordunuz siz benim mutlu olup gulmemi

Yavrulari oksayip sevkat ile sevmemi

Mutlu kalin dunyada sozde sevgi bilenlerim

Yaptigi zulumleri kardan sayip ovenlerim

Konustukca cok gordunuz suskunlugu kus bildiniz

Ben susdukca laf vurdunuz hergun kalbimi kirdiniz

Mutlu kalin dunyada sozde kusluk bilmeyenlerim

Yaptigi zulumleri kardan sayip ovenlerim

Evlimiyim bilmedim sicak yuva gormedim

Sayenizde gulmedem gulmek neymis  bilmedim

Mutlu kalin  dunyada sozde gulmek bilenlerim

Yaptigi zulumleri kardan sayip ovenlerim

Hollanda', 'Kurumus agac gibi curuyor su bedenim Icin icin eriyor bir gun olur giderim Mutlu kalin  dunyada sozde beni sevenlerim Yaptigi zulumleri kard...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/zulum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tam İsabet', 'tam-i-sabet-sahin-erturk-o0bdk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok acılar çektim

Çok gözyaşı döktüm

Çok yalnızlık çektim

Şükür değdi çektiğime

TAM İSABET

Sonunda onikiden vurdum

Kader seni çıkardı karşıma

Şimdi ben

Şiirlerinle ısınıyorum

Sıcaklığınla pişiyorum

Mutluluğa doyuyorum

TAM İSABET güzelim

Benim senin gibi

Sevmesini bilen

Yazmasını bilen

Sıcak birini tanımam

TAM İSABET,TAM İSABET

(31.03.2005-Yeni)', 'Çok acılar çektim Çok gözyaşı döktüm Çok yalnızlık çektim Şükür değdi çektiğime TAM İSABET Sonunda onikiden vurdum Kader seni çıkardı karşım...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tam-isabet-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tual', 'tual-ziya-nizam-ecgrz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hülya’ya	

Senle tanışmadan önce

Kirlibeyaz bir tualdim ben

Bekledim hep renklenmeyi

Hep şekillenmeyi bekledim.

İstedim ki birileri insanlığı işlesin bana

Sevgiyi işlesin,candanlığı işlesin.

Samimiyetiyle dostluğu yaratsın bende.

Sen geldin ya şimdi

Usta bir ressam edasıyla.

Hadi al fırçanı eline

Başla şimdi beni yaratmaya

Senin sevdiğin renkleri kullan bende.

Koşarken çiz beni.

Sana doğru koşarken.

Bir de tebessüm ekle suratıma

Seni bulmanın tebessümü olsun bu.

Hemen yanıma bir deniz kondur

Senin gözlerin kadar sıcak,

Senin gözlerin kadar içten bir mavi kullan

Bu denizi boyarken.

Sonra bir yunus olsun dalgalarla oynaşan

Bana senin yakınlığını anımsatsın.

Sana ait bir dünya yarat bu resimde.

Tüm dostluğun,tüm varlığın hissedilsin.

Ve hep koru bu halini

Resimlerde bile olsa.

			21.11.1997-Cuma

			12:46 Çerkezköy

			Zafer’in anısına', 'Hülya’ya	 Senle tanışmadan önce Kirlibeyaz bir tualdim ben Bekledim hep renklenmeyi Hep şekillenmeyi bekledim. İstedim ki birileri insanlığı...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tual-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelde anam geleyim sana', 'gelde-anam-geleyim-sana-husamettin-guven-q5jws', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Candan seven sen idin

Kanat gerer korurdun

Benim icin olurdun

Gelde anam geleyim sana

Ben yoruldum hayattan

Horlanarak yasamaktan

Itilerek kakilmaktan

Gelde anam geleyim sana

Ozledim o sicagini

Sevkat dolu kucagini

O simsicak ocagini

Gelde anam geleyim sana

Bir geldesen varacagim

Kefenimi saracagim

Ben yanina yatacagim

Gelde anam geleyim sana

Hollanda', 'Candan seven sen idin Kanat gerer korurdun Benim icin olurdun Gelde anam geleyim sana Ben yoruldum hayattan Horlanarak yasamaktan Itilerek k...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gelde-anam-geleyim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgimdir Seni Seven', 'sevgimdir-seni-seven-mehmet-emin-yesilmen-z4mzl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgimi kanıtlamak,

İmzamı isminin baş harfiyle atmak gibidir.

Kalabalık tramvaylarda

Kokunu bulmaktır, karmaşalarda

Seni buldum kendimi aradığımda.

Kendimi ise sende buldum,

İçini okuduğumda,

Yalnız iken karanlık dar sokaklarda...

Pankartlar taşıyorum

Seni içinde düşündüğüm,

Hayali ülkemde.

Karanlığın olmadığı beyazda.

Lekesiz ve sade özgünlüğü ile.

Güzellik kavramının

Sana benzeme isteği gibi...

Atom zerresinin gücüdür sevgim

Savaşların baş edemediği.

Beyazdaki yedi renktir,

Yeşilin gücü ile birleşen,

Sevgimdir seni seven...', 'Sevgimi kanıtlamak, İmzamı isminin baş harfiyle atmak gibidir. Kalabalık tramvaylarda Kokunu bulmaktır, karmaşalarda Seni buldum kendimi ara...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Yeşilmen']::text[], 8.5, '{"poet":"Mehmet Emin Yeşilmen","poet_slug":"mehmet-emin-yesilmen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevgimdir-seni-seven-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bir Roman', 'eski-bir-roman-nur-demirciler-upudk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkım sana yetmedi mi? 

Eski bir romanın 

kapanmış sayfaları gibi,

kapandı aşkımız hiç açılmayacak.

Hani ettiğin yeminler,

kurduğumuz düşler,

hani sen benim bir yanım,

ben senin öbür yanındım.

Bir bahar günü bulmuştum seni,

başka bir baharda terkediyorsun.

Hep aynı çiçekle bahar geçer mi diyorsun? 

Söyle aşkım sana yetmedi mi? 

Ama  sevdamın yüreği yufka,

kıyamaz yine de ah etmez sana,

Kimbilir bir başka sonbaharda,

çıkarsın umarım karşıma,

Hangi sevda ayazında,

parçalanmış yırtık sayfalarımla,

sen olursun kaldıran bu romanı,

ebedi rafına......', 'Aşkım sana yetmedi mi?  Eski bir romanın  kapanmış sayfaları gibi, kapandı aşkımız hiç açılmayacak. Hani ettiğin yeminler, kurduğumuz düşler...', ARRAY['Türk Edebiyatı','Şiir','Nur Demirciler']::text[], 8.5, '{"poet":"Nur Demirciler","poet_slug":"nur-demirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/eski-bir-roman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk düş(le) mesi...', 'ask-dus-le-mesi-ugur-deniz-ulkegul-d6zz7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En soğuk düşlerin

Kar yangınlarında kavrulan,

Koca bir dündü hayat…

En zoru biliyorduk,

Bu yüzden yetmiyordu ateş,

İçimizi ısıtmaya…

Yüreğimiz korlaştıkça,

Biz üşüyorduk…

Ben,

Vazgeçmiştim

Sokaktaki çocuk seslerinden…

Yönsüz bir yol alıştı gidişim,

Densiz belaların,

Kuytusunda uyuyordum…

Denize atmıştım zamanı,

Günsüz gecelerin,

Uykusuna dalıyordum…

Sen,

-Bilmiyordum-

İki elin kanda,

Toprağından kovulan,

Bir mülteci olmuştun…

Ve sonra kaybolmuştun

Bu yabanda…

Şaşkın bakışların,

Ve sessiz yakarışların,

Yükselirken semaya…

Tüketilmiş bir aşkın,

Sancısını yüklüyordun,

Hep aynı duaya…

Sonra bir gün,

Bir şey oldu…

Geri döndü zaman,

Ama mekan,

Kayboldu…

An’ı bulmuştuk,

Oysa viran olmuştu ülkemiz..

Ne yollarımız kalmıştı yürüyecek,

Ne şehirlerimiz…

Sonrayı bir türlü düşünemedik,

Öyle ağır geliyordu ki öncemiz…

Sıkıştık kaldık burada,

Dünsüz ve yarınsız…

Hadi, zamanı değil şimdi,

Birbirimizi kovmanın…

Gidecek ne bir yerimiz var

Ne de yurdumuz…

Yorulsun karanlıklar! 

Tadına varalım sevişmenin,

Yataksız, döşeksiz, yorgansız…

Umuda, iyiye, güzele dair

Artık bizim sorgumuz…

Düştük aşk kuyusuna,

Cevabı bizde saklı,

Yok ki korkumuz………', 'En soğuk düşlerin Kar yangınlarında kavrulan, Koca bir dündü hayat… En zoru biliyorduk, Bu yüzden yetmiyordu ateş, İçimizi ısıtmaya… Yüreğim...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/ask-dus-le-mesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül anlar seni', 'gul-anlar-seni-tuncay-akdeniz-892nz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her kumaşa atma eğreti teyel

Dikiş sağlam ise tel anlar seni

Yalan söyleme ki ödersin bedel

Dil doğru söylerse el anlar seni

Aldığın görevi getir yerine

Bu günkü işini koyma yarına

Yarınlar indirir seni derine

Gün doğru söylerse yıl anlar seni

Kuşlar bile konmaz diken çalıya

Aşık olan muhtaç olur sevgiye

Seven gönül dönemez ki geriye

Aşk mecnun olursa çöl anlar seni

Tuncay diyor hak bilirim ölümü

Can dostuma uzatırım elimi

Bilsem ki kırmasan benim dalımı

Sevgiyi bilirsen gül anlar seni', 'Her kumaşa atma eğreti teyel Dikiş sağlam ise tel anlar seni Yalan söyleme ki ödersin bedel Dil doğru söylerse el anlar seni Aldığın görevi ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gul-anlar-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakacagim sonuna kadar', 'bakacagim-sonuna-kadar-husamettin-guven-pdnvh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Herkes bunu boyle bilsin

Yuce allah sahit olsun

Benim babam yalniz sensin

Bakacagim sonuna kadar

Ufak defek darginliklar

Hayatin cilvesi bunlar

Kotu hisse kapilmasinlar

Bakacagim sonuna kadar

Allahimin lutfusun sen

Ben de senin oglun isem

Canim babam emin olsen

Bakacagim sonuna kadar

Mali mulku gozum gormez

Babam senin yerin dolmaz

Bu dunyada neden gulmez

Bakacagim sonuna kadar

Lazim ise kanim sana

Al vereyim canim sana

Gul yeterki doyasiya 

Bakacagim sonuna kadar

Hollanda', 'Herkes bunu boyle bilsin Yuce allah sahit olsun Benim babam yalniz sensin Bakacagim sonuna kadar Ufak defek darginliklar Hayatin cilvesi bun...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bakacagim-sonuna-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aykız', 'aykiz-deniz-onderoglu-5qd7k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aykız, ay yüzlü güzel kız

Daha ne kadar kalacaksın 

Düşüncelerimde

Gözlerimde daha ne kadar kalacak

Hayalin

Ay''da ne kadar göreceğim daha

Yüzünü

Aykız, ay yüzlü güzel kız...', 'Aykız, ay yüzlü güzel kız Daha ne kadar kalacaksın  Düşüncelerimde Gözlerimde daha ne kadar kalacak Hayalin Ay''da ne kadar göreceğim daha Yü...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aykiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pîr Bûm Dil Pîr Nabî', 'p-r-b-m-dil-p-r-nab-cigerxw-n-aol0x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey dilberê! 

______Peyxamberê

___________Lêv şekerê

_______________Ka soz û peymana berê? 

Biskan veke

______Zulfam şeke

___________Dil pîr meke

______________Me J’bîr meke

__________________Carek pişt perdê derê

Dêmên digeş

_______Çavên direş

___________Xalên hebeş

________________Birhên biweş

_____________________Hilde ko her, roj bê derê

Perde ji ser 

______Xalên diqer

__________Hilde ku her

______________Roj bête der

__________________Her kes bizanin vê sirê

Şêrîn kenê

_____Hingiv çenê

_________Dosta minê

_____________Dil hasinê

________________Dil girtiyê te ez tenê

Gul weke devê

________Lêv hingivê

_____________Min tim divê

__________________Roş û şevê

_____________________Ez bêm cîvanê dêm dirê

Sîh sal temam

_____Ez bende mam

__________Hûnan meqam

_______________Lê yek selam

___________________Carek li ber çavan nedam

Ez bende me

_____Perkende me

__________Şermende me

_______________Perwane me

___________________Sotim bi pêta agirê

Cigerxwîn', 'Ey dilberê!  ______Peyxamberê ___________Lêv şekerê _______________Ka soz û peymana berê?  Biskan veke ______Zulfam şeke ___________Dil pîr ...', ARRAY['Türk Edebiyatı','Şiir','Cigerxwîn']::text[], 8.5, '{"poet":"Cigerxwîn","poet_slug":"cigerxw-n","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/pir-bum-dil-pir-nabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöl oldun bana', 'col-oldun-bana-tuncay-akdeniz-bgkt8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ÇÖL OLDUN BANA

Gördüm bakışların küsmüşler gibi

Yad yabancı gibi el oldun bana

Kış gelmeden oldun kar boran tipi

Yağmursuz bulutsuz sel oldun bana

İçimde bıraktın acı bir sızı

Bizi ayıranın gülmesin yüzü

Ellerimden çıkmaz elinin izi

Konuşmaz söylemez lal oldun bana

Sevda denizinde sen ben yüzerken

Yeller mi ters esti bozuldu yelken

Gülünü sevene batar mı diken

Çiçeksiz yapraksız dal oldun bana

Güzel yaşamıştık biz anıları

Ayrılık getirdi dile bunları

Tuncay’a yaşattın sen mecnunları

Issız sahralarda çöl oldun bana', 'ÇÖL OLDUN BANA Gördüm bakışların küsmüşler gibi Yad yabancı gibi el oldun bana Kış gelmeden oldun kar boran tipi Yağmursuz bulutsuz sel oldu...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/col-oldun-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak ol yavrum uzak ol', 'uzak-ol-yavrum-uzak-ol-tuncay-akdeniz-ih2k1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Suyu durgun akan yerden

Uzak ol yavrum uzak ol

Mert görünüp kaçan erden

Uzak ol yavrum uzak ol

Çok bilirim ben diyenden

Seni aşağı görenden

Ona buna yerinenden 

Uzak ol yavrum uzak ol

Kendi kendini övenden

Çıkarı için sevenden

Yalana kılıf dikenden

Uzak ol yavrum uzak ol

Tuncay bilmez yoktan azdan

Uzak dur maşasız közden

Önündeki eğri izden

Uzak ol yavrum uzak ol', 'Suyu durgun akan yerden Uzak ol yavrum uzak ol Mert görünüp kaçan erden Uzak ol yavrum uzak ol Çok bilirim ben diyenden Seni aşağı görenden ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sakin-ha-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim gurbet', 'zalim-gurbet-tuncay-akdeniz-0glt8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Memleket hasreti gurbetin zoru

Benim gibi viran olasın gurbet

Sen benden ayırdın sevdiğim yarı

Gül yerine diken yolasın gurbet

Can dayanmaz oldu senin derdine

El vurdukça yaram indi derine

Tuttun zehir verdin ilaç yerine

Allah dan belanı bulasın gurbet

Her gelene attın çelikten kanca

Geçilmez yolların sırattan ince

Güller mi koklattın yaşlıya gence

Açılmadan sende solasın gurbet

Tuncay-i ayırdın ana babadan

Anlamasın zalim aşktan sevdadan

Ayırdın çoğunu sevdiği yardan

Benim gibi yalnız kalasın gurbet', 'Memleket hasreti gurbetin zoru Benim gibi viran olasın gurbet Sen benden ayırdın sevdiğim yarı Gül yerine diken yolasın gurbet Can dayanmaz ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zalim-gurbet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrı', 'tanri-deniz-onderoglu-hwfdr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tanrı olsaydım eğer; 

Ol derdim, olurdun

Öl derdim, ölürdün

Git derdim, giderdin

Gel derdim gelirdin

Ama tanrı değilim

Ne oluyorsun

Ne ölüyorsun

Ne gidiyorsun

Ne de geliyorsun...', 'Tanrı olsaydım eğer;  Ol derdim, olurdun Öl derdim, ölürdün Git derdim, giderdin Gel derdim gelirdin Ama tanrı değilim Ne oluyorsun Ne ölüyo...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tanri-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lal gibiyim', 'lal-gibiyim-tuncay-akdeniz-3d3bh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zemheri kışa benzerim

Müşkülüne hal gibiyim

Kerem misali gezerim

Yanıp bitmiş kül gibiyim

Hakka ayandır bu halim

Zehir oldu tatlı balım

Tutunacak yok bir dalım

Yad yabancı el gibiyim

Sevda gönlüme ekilir 

Dalım yaprağım dökülür 

Saç ağarır bel bükülür 

Susuz kurak çöl gibiyim

Dertliyim dedim özüme

İnanan olmaz sözüme

Dert ortağım sor sazıma

Üstündeki tel gibiyim

Özümüz aşına olsa 

Gönüller hakikat bulsa 

Muhabbet feyizle dolsa 

Yaradana kul gibiyim

Tuncayım dertli gezerim

Zamana resim çizerim

Haksıza ağız bozarım

Dilsiz insan lâl gibiyim', 'Zemheri kışa benzerim Müşkülüne hal gibiyim Kerem misali gezerim Yanıp bitmiş kül gibiyim Hakka ayandır bu halim Zehir oldu tatlı balım Tutu...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/lal-gibiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-husamettin-guven-nv1f8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Allahini kalp''den  zikret

Haram zina yalan terk et

Islam dini haktir elbet

Benden sana nasihat

Muhammedin ummedisin

Yalniz yaradana kulsun

Tek kitabin kuran olsun

Benden sana nasihat

Mala; mulke meyil verme

Allahina yuz cevirme

Hak yolundan sen ayrilma

Benden sana nasihat

Mali mulku israf etme

Fazlasini ziyan etme

Fakirleri sen unutma

Benden sana nasihat

Sen seytani dostun sanma

Sakin ola nefse kanma

Sonra kalirsin bir gun darda

Benden sana nasihat

Sen hayrini ver elinle

Bence gider o seninle

Gelsen benim sozum dinle

Benden sana nasihat

Hollanda', 'Allahini kalp''den  zikret Haram zina yalan terk et Islam dini haktir elbet Benden sana nasihat Muhammedin ummedisin Yalniz yaradana kulsun T...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/nasihat-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şenlenir', 'senlenir-tuncay-akdeniz-5jhvq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hep kendini değil beni de düşün

Bakarsan arına balın şenlenir

Ter dökmüşsen daim var olur işin

Bereketli olur malın şenlenir

Kötülük edenler her şeyden olur

Sen iyilik ette bilenler bilir

Bekle zaman gelir o seni bulur

Vicdan rahat olur elin şenlenir

Nasihat etmişsen evde kızına

Her söylenen  sözü alma özüne

Bir mecliste dikkat etsen sözüne

Artar itibarın dilin şenlenir

Tuncay çalışmasan dara düşersin

Namert bardağından zehir içersin

Ne ekersen geri onu biçersin

Bakarsan bağına dalın şenlenir', 'Hep kendini değil beni de düşün Bakarsan arına balın şenlenir Ter dökmüşsen daim var olur işin Bereketli olur malın şenlenir Kötülük edenler...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senlenir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-ebru-yucesoy-xtz7n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Apansız batar yüreğine,

Anlamazsın...

Bi gün çıkmak isterse,

Yavaşça gider, döne döne 

Oluk oluk kanarsın........', 'Apansız batar yüreğine, Anlamazsın... Bi gün çıkmak isterse, Yavaşça gider, döne döne  Oluk oluk kanarsın...........', ARRAY['Türk Edebiyatı','Şiir','Ebru Yücesoy']::text[], 8.5, '{"poet":"Ebru Yücesoy","poet_slug":"ebru-yucesoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ask-350-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam isen izin kalır', 'adam-isen-izin-kalir-tuncay-akdeniz-ssgef', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğru yolda yürüyorsan

Adam isen izin kalır

Beni insan görüyorsan

Adam isen özün kalır

Karanlığa seni iter 

Doğru söze yalan katar

Bire alır ona satar

Çoğun gider azın kalır

Kibirlenme kendini bil

İçinden kin nefreti sil

Söz değil özde doğru ol

Sevilecek yüzün kalır

Tuncay der her şey dengine

Yüksek uçma in engine

Acımaz fakir zengine

Taş üstünde yazın kalır

***************************

Dostlar dilinden 

Güzel söz''ü hoş diyorsun, 

İyiliğe koş diyorsun. 

Tuncay dost''a gidiyorsun. 

Dost gönlünde izin kalır........Hüseyin Durmuş', 'Doğru yolda yürüyorsan Adam isen izin kalır Beni insan görüyorsan Adam isen özün kalır Karanlığa seni iter  Doğru söze yalan katar Bire alır...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/adam-isen-izin-kalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin bitanem', 'neredesin-bitanem-husamettin-guven-3hyhj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Durmadan su gozlerim seni arar

Goremeyince gozlerim yuregim kanar

Iflas eden sukalbim adini anar

Neredesin bitanem geliver artik

Gece duslerimde seni gorurum

Sabah uyaninca bir hos olurum

Ruya degil gercek ol yoksa olurum

Neredesin birtanem geliver artik

Olmeden birdaha goreyim seni

Doyasiya sarilip sevyim seni

Allahin emri ile alayim seni

Neredesin birtanem geliver artik

Hollanda', 'Durmadan su gozlerim seni arar Goremeyince gozlerim yuregim kanar Iflas eden sukalbim adini anar Neredesin bitanem geliver artik Gece dusler...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/neredesin-bitanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükendim Azar...Azar...', 'tukendim-azar-azar-dursun-elmas-u9ur2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''Herkesin bir gülü var,ona nağmeler yazar

Gül mevsimi geldi mi,bülbüller bundan azar.''

Ben bülbül,sen gülümdün,yana yana köz oldum

Artık,eridim,bittim; tükendim azar azar! ..

Ağlıyor satırlarım,gözyaşına boğuldu

Kelime kifayetsiz,mısralardan kovuldu.

Kalemim garip artık,bundan sonra ne yazar? 

Artık,eridim,bittim; tükendim azar azar! ..

Anlamadım bir türlü,bu dünyanın halinden

Öyle zalim yarmış ki,bana ne zevâlinden.

Kanda derman kalmadı,sıra bekliyor mezar

Artık,eridim,bittim; tükendim azar azar! ..

Gül gülmez,bülbül ötmez,şimdi yastadır gönül

Hücreler biter tek tek,sona ermekte ömür.

Bundan böyle bu gönül,sana artık ne yazar? 

Artık,eridim,bittim; tükendim azar azar! ..', '''Herkesin bir gülü var,ona nağmeler yazar Gül mevsimi geldi mi,bülbüller bundan azar.'' Ben bülbül,sen gülümdün,yana yana köz oldum Artık,eri...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tukendim-azar-azar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğime sitem', 'sevdigime-sitem-tuncay-akdeniz-0t7u9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabah yeli gibi serinden esen

Estin acı,acı yoldurdun beni

Fistanına olsam al güllü desen

Giymeden üstüne soldurdun beni

	Can oy can oy..................

	Sende benim gibi solasın yar oy

Kalbimden silinmez sevdanın izi

Dertli aşıkların güler mi yüzü

Ben sensiz neyleyim kemanı sazı

Ayarsız düzensiz çaldırdın beni

Gönlüm söz dinlemez aşkına yandım

Aşkın pınarından bir yudum kandım

Derdimin devası ilacı sandım

İçirdin zehirsiz öldürdün beni

Tuncayım derdimi üst üste dizdim

Kırk beş yıldır aynı derdi nen gezdim

Aşkını kalbimin içine yazdım

Gönül defterinden sildirdin beni', 'Sabah yeli gibi serinden esen Estin acı,acı yoldurdun beni Fistanına olsam al güllü desen Giymeden üstüne soldurdun beni 	Can oy can oy........', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevdigime-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle bir gun sana gelecegim', 'bekle-bir-gun-sana-gelecegim-husamettin-guven-folhf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerime kelepce taksalar

Beni zindanlara atsalar

Cimbiz ile etlerimi kopartsalar

Bekle bir gun   sana gelecegim

Cellat boynumu vursa

Bu beden cansizda kalsa

Mapushaneler mezarimda olsa

Bekle bir gun sana gelecegim

Boynuma ipi gecirseler

Saadet serbetini icirseler

Vaz gec sevme onu deseler

Bekle bir gun sana gelecegim

Hollanda', 'Ellerime kelepce taksalar Beni zindanlara atsalar Cimbiz ile etlerimi kopartsalar Bekle bir gun   sana gelecegim Cellat boynumu vursa Bu bed...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bekle-bir-gun-sana-gelecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Büyük Sır', 'en-buyuk-sir-yakup-icik-an5qw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dostlarım, bana bunca yıl hep acı verdiler, ben ise onlara içimden koşarak gelen neşe verdim..', 'Dostlarım, bana bunca yıl hep acı verdiler, ben ise onlara içimden koşarak gelen neşe verdim.....', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/en-buyuk-sir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakisirmi sana guzel', 'yakisirmi-sana-guzel-husamettin-guven-3h799', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aldanmisim bildim sever

Ettin beni sen derbeder

Sonra verdin elem keder

Yakisirmi sana guzel

Canli canli sen oldurdun

Topragada hemen gomdun

Yasamami cokmu gordun

Yakisirmi sana guzel

Apar,topar karar verdin

Kefensizce beni gomdun

Bu karari neden verdin

Yakisirmi sana guzel

Hollanda', 'Aldanmisim bildim sever Ettin beni sen derbeder Sonra verdin elem keder Yakisirmi sana guzel Canli canli sen oldurdun Topragada hemen gomdun...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yakisirmi-sana-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel sevdigim dert ortagim olsana', 'gel-sevdigim-dert-ortagim-olsana-husamettin-guven-tvjc8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasta oldum yataklarda yatarim

Yok suan yardim bana yapanim

Caresizce gozum yasli bakarim

Gel sevdigim dert ortagim olsana

Seni sevdim seni bildim sevgilim

Careyi ben sende gordun be gulum

Hakkim yokmu istemek senden yardimin

Gel sevdigim dert ortagim olsana

Ne zor imis sevip caresiz kalmak

Gonlum ister her an yaninda olmak

Doyasiya koklayarak sarilmak

Gel sevdigim dert ortagim olsana

Hollanda', 'Hasta oldum yataklarda yatarim Yok suan yardim bana yapanim Caresizce gozum yasli bakarim Gel sevdigim dert ortagim olsana Seni sevdim seni ...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gel-sevdigim-dert-ortagim-olsana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Orucu', 'ask-orucu-goksel-akkaya-vlypm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neyine göverniyor kalbim 

Boyundan büyük bu sevda

En zorunu seçtim aşkın

Kendini bana sakla

Yaşamasam bu gün

Hayat beni bağışlamaz

Yarın bilmem umut dündü

Sana zararım dokunmaz 

Bozuyorum aşk orucumu 

Yıllar sonra seninle 

Aşğım hayranım her bir zerre ne

Sende kabul et beni 

Çünkü ben önceden

Hayata küsmüş biriydim

Ama seninle aşkın tam 

Anlamını öğrendim', 'Neyine göverniyor kalbim  Boyundan büyük bu sevda En zorunu seçtim aşkın Kendini bana sakla Yaşamasam bu gün Hayat beni bağışlamaz Yarın bil...', ARRAY['Türk Edebiyatı','Şiir','Göksel Akkaya']::text[], 8.5, '{"poet":"Göksel Akkaya","poet_slug":"goksel-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-orucu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyemediklerimi biriktirdim', 'soyleyemediklerimi-biriktirdim-goksel-dogru-a59cl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(''M''ilada...)         

         Söyleyemeyip biriktirdiklerim vardı

         Gözyaşıyla dizelere karışıp

         Kimsenin duymadığı bir hıçkırıkla

         Benimle birlikte ağlarlardı

         En çok da babamaydı söyleyemediklerim

         Kimsenin bilmediği.

         En güzel aşk şiirlerimde bile

         Ona söyleyemediklerim vardı

         Biriktirmiştim bir gün söylerim diye

        , yine söyleyemedim

         Ve artık

         Hiç söyleyemeyeceğim.

         Hepsi bir yana söyleyemediklerimin

         Hoşça kal  diyebilseydim son kez,

         Ve bütün söyleyemediklerime bedel

         Öpebilseydim yanağından bir kez

         Beni anlarmıydı bilemedim.

         Artık,

         Hiç bilemeyeceğim.

         Bir çocuk olsaydım,

         Üçüncü gün biterdi gözyaşım

         Oyle ya,çocukta dert ne gezer

         Ama hayatın ortasında

         Söyleyemediklerim ve ben

         Kalakaldım babasızlığımla.

         Artık bir başımayım bu yolda

         Bütün dünyayla yaşasam yan yana

         Hep bir ağızdan konuşsa, gülse

         Ve güldürseler beni yanı başımda

         Anlamazlar ki halimden

         Ben de anlatamam ki onlara

         Dedim ya söyleyemediklerim diye

         Söyleyemezdim ki onlara

         Söyleyemediklerimi diyebileceğim

         Dediklerimi anlayacak

         Anlayıp derdime koşacak

         Bir babam vardı benim, herkes gibi

         Ölünce söyleyemeyeceklerimi

         Ve yaşarken ki söyleyemediklerimi

         Söyleyebileceğim tek insan

         Babam vardı düne kadar,

         Ve artık,

         Söyleyemediklerimi hep biriktireceğim

         Babamın yanına gidene kadar! 

         (Haziran 2001, İzmir)', '(''M''ilada...)                   Söyleyemeyip biriktirdiklerim vardı          Gözyaşıyla dizelere karışıp          Kimsenin duymadığı bir hıç...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/soyleyemediklerimi-biriktirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toreye asla', 'toreye-asla-husamettin-guven-qp1ms', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Buyukler haklidiryanilmaz onlar

Hayatin zindanmis hic umursamazlar

Mutlumusun duye gelip sormazlar

Kadere raziyim toreye asla

Buyuk diye sizleri hep sevip saydik

Torelere yenildik sevgisiz kaldik

Sevgiyi oldurup ahrete saldik

Kadere raziyim toreye  asla

Yasamaya luzum kalmadi bence

Sensizlik bana izdirap verince

Olumu sececegim o gun gelince

Kadere raziyim toreye asla

Mutluluk gulun eglenin

Aldiniz kalbimden onu neyleyim

Nesesiz geciyor benim gunlerim

Kadere raziyim toreye  asla

Hollanda', 'Buyukler haklidiryanilmaz onlar Hayatin zindanmis hic umursamazlar Mutlumusun duye gelip sormazlar Kadere raziyim toreye asla Buyuk diye siz...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/toreye-asla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karlar Kasımı', 'karlar-kasimi-goksel-dogru-4p1lg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(olmayana...) 

Kasımlardan bir kasım

Kar yağıyordu şehre, ayaz mı ayaz

Vakitlerden akşam

Kimi karısına, çocuklarına

Kimi dönüşü imkansıza

İnsanlar gelip gidiyordu hayat yolunda

İnsanlar her gün, bir gün daha

Biçare ölüyorlardı bu yolda

Kasımlardan bir kasım

Üstüme üstüme gelirken şehir

Kar yağıyordu akşam ayazında

Bazen gözlerine, ellerine

Bazen sımsıcak gülüşüne 

Sana sığınıyordum sensizlik yolunda

İnsanların bir ömürde öldüğünü 

Bir anda ölüyordum bu yolda

Kasımlardan bir kasım

Ayaz mı ayaz, vakitlerden akşam

Kar yağıyordu evin bildiğin yüreğime

Bazen ellerin, gözlerin

Bazen sımsıcak gülüşün

Bende olmayan aklım bir de 

Beni çağırıyordu sonsuzluk yolunda

Er geç varacağım yere, vaktimden önce 

An be an yürüyordum bu yolda

Kasımlardan son kasım 

Vakitlerden son akşam

Sensizlikten bıktım, sonsuzluktayım

Kar yok, ayaz yok; sımsıcak bir iklim

Dönüşü imkansız bu yolda 

Yalnızlığımla yine sensizlikteyim.

(28 Kasım 1999, Altıparmak)', '(olmayana...)  Kasımlardan bir kasım Kar yağıyordu şehre, ayaz mı ayaz Vakitlerden akşam Kimi karısına, çocuklarına Kimi dönüşü imkansıza İn...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/karlar-kasimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-goksel-dogru-ww3qx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(bir hayale dair) 

Giden gençliğimi 

Tuttum paçasından

“Ne istersen yaparım,

Biraz daha kal” dedim.

Önce bir yar edindim kendime 

Küçük mü küçük, dünkü çocuk

Sonra aşk ıstırabıyla dolu

Uykusuz geceler 

Derken, 

Güneş doğdu bir gün ufkumda

Şu an ölüm döşeğindeyim

Kırk yıllık karım, dünkü çocuk 

Yanımda! 

(Ekim 2001, İzmir)', '(bir hayale dair)  Giden gençliğimi  Tuttum paçasından “Ne istersen yaparım, Biraz daha kal” dedim. Önce bir yar edindim kendime  Küçük mü k...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cocuk-103-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Seni Gerek Seni', 'bana-seni-gerek-seni-yunus-emre-orb6q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkın aldı benden beni 

Bana seni gerek seni 

Ben yanarım dün ü günü 

Bana seni gerek seni 

Ne varlığa sevinirim 

Ne yokluğa yerinirim 

Aşkın ile avunurum 

Bana seni gerek seni 

Aşkın aşıklar oldurur 

Aşk denizine daldırır 

Tecelli ile doldurur 

Bana seni gerek seni 

Aşkın şarabından içem 

Mecnun olup dağa düşem 

Sensin dünü gün endişem 

Bana seni gerek seni 

Sufilere sohbet gerek 

Ahilere ahret gerek 

Mecnunlara Leyla gerek 

Bana seni gerek seni 

Eğer beni öldüreler 

Külüm göğe savuralar 

Toprağım anda çağıra 

Bana seni gerek seni 

Cennet cennet dedikleri 

Birkaç köşkle birkaç huri 

İsteyene Ver anları 

Bana seni gerek seni 

Yunus''dürür benim adım 

Gün geçtikçe artar odum 

İki cihanda maksudum 

Bana seni gerek seni', 'Aşkın aldı benden beni  Bana seni gerek seni  Ben yanarım dün ü günü  Bana seni gerek seni  Ne varlığa sevinirim  Ne yokluğa yerinirim  Aşkı...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bana-seni-gerek-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınımda Yıldızımsın', 'yarinimda-yildizimsin-cemal-karsavran-ha1cv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni beklemek erişilmez olan bir nokta

Özlemin bir lokma ekmek parçası

Sevişmelerimiz gecenin aynası

Öksüz sevdamın masum çiçeği

Mühürlemişin kalbimi ya da büyü yapmışın

Bir yenilgi artık çoğaldıkça çoğalan

Tükenmez zamanların estetiği

Harmandalı oynuyor yüreğim seninle

Nevruz ateşi yanıyor bedenimde

Camgöbeğimde beyaz leke hayalin

Düş gezegenimde çıkmaz sokağım

Yolculuğunu düşünmek istemiyorum 

Arap atları cirit atıyor gözlerimde

Gözlerim hüzzam gözlerim dolunay

Hafızam dolup taşıyor yüreğim yangınlarda

Çınlar kulaklarım titrer bedenim

Yıldız düşerken dolunayın gizeminden

Masal perisisin düşlerimin düşlerim gerçek

Islak dudağında tattım mutluluğu

Mahşer olsan da yarınımda yıldızımsın

31-03-2005', 'Seni beklemek erişilmez olan bir nokta Özlemin bir lokma ekmek parçası Sevişmelerimiz gecenin aynası Öksüz sevdamın masum çiçeği Mühürlemişi...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yarinimda-yildizimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Şiirlerle', 'siirlerle-cemal-karsavran-zwnny', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şiir yağsın gecene demişsin

-bizim buralarda kıştır anam 

düşlerimiz yatağımız soğuk

yangınımız kızıl alevdir şiirlere

ermiş doğar yüreğimize 

gecelerde 

rengini kaybetmiş bulutlar olsa da başımızda. 

cenk ederiz hüzünlere

aşk adına

eksik yanlarımızı tamamlar ay ve yıldızlar

kayda değer bir şeyler olmasa da yazıp çizdiğimiz

istişare ederiz; danışırız 

yolun sonu bu mu dur

mahlasımız dost adınadır yürekten yüreğe

Liyakatsız çıkar her şiir arenaya

şiir ruhlara sunulur

yerçekimi var diye 

sesimizi yükseltiriz zaman zaman 

engel değildir bil

düşlere hiç bir şey 

rakımlar ne kadar yüksek olursa olsun 

çiçek eker bozkıra 

sevda biçeriz 

eğrelti düşlere inat uyanık yatarız 

kimsesiz ve sessiz gecelerle anılır adımız 

imzasız şiirler yağar darmadağınık 

mısralı kafiye düzenli yada serbest 

bir çırpıda okunur

hayaller kurulur

imkansız mutluluklardır tekrarı olmayan

yeni bir gün yeni bir iklim olur

emekleyen bebeler doğuran

resmi gökyüzüne çizilen 

çilek yanaklı umut bakışlı 

lüle lüle saçları 

ebabil kuşlarından dili olan 

kış güneşi gibi sıcacık gülüşlü 

mahsun mağrur 

inadına yaşamak sevdayı..şiirlerle', 'şiir yağsın gecene demişsin -bizim buralarda kıştır anam  düşlerimiz yatağımız soğuk yangınımız kızıl alevdir şiirlere ermiş doğar yüreğimiz...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/siirlerle-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarış', 'yaris-i-smet-barlioglu-6u6x7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yerleri, gökleri yaratan Tanrı

Seni yerlerden, göklerden güzel yaratmış.

Gecelerimi süsleyen yıldızlardan,

Denizdeki mehtaptan,

Karanlıklara değip geçen gecekuşlarından,

Martılara şifa olan körpe sabahlardan,

Renge hakkını veren ışıktan,

Kelebeklerden, arılardan,

İçinde çakılları görünen berrak kaynaklardan,

Mavi sulara inip kalkan martılardan,

Yeşili yeşile kavuşturan tozlu-tozaklı yollardan,

Açılan avuca sadaka bırakan ellerden,

her şeyden, her şeylerden,

Güzel yaratmış,

Sonra seni çelik bir mızrak gibi

Saplayıp kalbime,

Kanatmış.

Durakalmış zamanım seni gördüğüm günde,

Varlığın durakalmış,

Güzelliğin,

Bakışların,

Başını çevirip çevirip geçişlerin durakalmış.

Ne seni eskitebiliyor şimdi zaman,

Ne de beni.

Öylece durup duruyor yerli yerinde,

Sen şimdi bir benim için yaşıyorsun

Derinde.

Tam ortasından mızraklamış Tanrı ‘m, yüreğimi,

Kanlar içinde kalmış yüreğim, mızrak altında,

Ne gecelerimin farkındayım,

Ne gündüzlerimin farkında.

Buna yaşamak denirse; sözüm ona yaşıyorum,

Senin ardından bir tükenmez yarışa sokmuş beni,

Koşuyorum.

(KAFES İsimli Serbest Şiirler ''inden > 67-68/100)', 'Yerleri, gökleri yaratan Tanrı Seni yerlerden, göklerden güzel yaratmış. Gecelerimi süsleyen yıldızlardan, Denizdeki mehtaptan, Karanlıklara...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yaris-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vicdansız', 'vicdansiz-i-smet-barlioglu-pzcdi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne bomboş günlermiş

Seni tanımadan geçirdiğim günler,

Sorumsuz, amaçsız, umutsuz, kaygısız günler,

Yattımmı yatardım gecelerden sabahlara kadar,

Sabah olmuş, akşam olmuş, gece olmuş, fark etmezdi,

Taşı gördüm taş olarak,

Kuşu gördüm kuş olarak,

Ne mene şeymişim ki; yaşayabilimiş durmuşum

Bomboş olarak.

Çekerdim onun-bunun çilesini, çilesizlikten,

Dertsizlikten ona üzülürdüm, buna üzülürdüm,

Kadehimdeki rengi göremezdim kadeh kaldırsam,

Bilmezdim badelerde nelerin gizli olduğunu,

Sevdayı bilmezdim,

Çileyi, hüznü,

Yaralı bir yüreğin nasıl gözyaşı döktüğünü,

İnsanın için için nsaıl ağladığını,

Canın nasıl kebap kebap kavrulduğunu,

Ruhun nasıl kağıt gibi yırtıldığını boydan boya,

Sayende öğrendim aramadığım tüm nedenleri

Doya doya.

Şimdi bana sorsunlar

İki elin böğürlerde nasıl kaldığını,

İnsanın nasıl yattığını, nasıl uyandığını,

Suların neden göründüğü gibi akmadığını,

Mızrakların nasıl saplandığını yüreklere,

Yüreklerin nasıl kanadığını kansız,

Tüm bunları sayende öğrendim

Vicdansız.

(KAFES İsimli Serbest Şiirler ''inden > 69-70/100)', 'Ne bomboş günlermiş Seni tanımadan geçirdiğim günler, Sorumsuz, amaçsız, umutsuz, kaygısız günler, Yattımmı yatardım gecelerden sabahlara ka...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/vicdansiz-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnkar', 'i-nkar-goksel-dogru-24158', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşi de seveceksin

Gölgeyi de. 

Gölgedeyken güneşi,

Güneşlenirken 

Boy aşırı apartmanları 

Kıskandırmadan...

Sağanak yağarken yağmur, 

Gözlerini esirgemeyeceksin

Düşen onlarca damladan.

Bekleyeceksin güneşli, 

Güzel günleri. 

Neden ağladığını unutmadan.

(Temmuz 2002,İzmir)', 'Güneşi de seveceksin Gölgeyi de.  Gölgedeyken güneşi, Güneşlenirken  Boy aşırı apartmanları  Kıskandırmadan... Sağanak yağarken yağmur,  Göz...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/inkar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağustos Böcekleri', 'agustos-bocekleri-goksel-dogru-mofqt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni de ağlatır mı

Yaz ortasında

Fırtınayla gelen yağmurda 

Kokan toprak? 

Peki ya,

Ağustos böceklerinin sessizliği? 

(Ağustos 2002,Samsun)', 'Seni de ağlatır mı Yaz ortasında Fırtınayla gelen yağmurda  Kokan toprak?  Peki ya, Ağustos böceklerinin sessizliği?  (Ağustos 2002,Samsun)...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/agustos-bocekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavga', 'kavga-goksel-dogru-wjr48', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir insan,

Yaşarken yaşayamadıkları 

Konuşurken söyleyemedikleri 

Çoğaldıkça 

Kalem düşer önce eline 

Sonra önüne bir kağıt,

İlk olarak yazdığı:

“Ben seni hep sevdim 

Sen beni hiç sevdin...”

Sonraki günler geceler 

Her gün biraz daha artar

Yaşanamamışlar 

Ve söylenememişler

Basit dörtlükler yavaşça 

Bırakır yerini 

Anlaşılmazlıklarla dolu

Satırlarca satırlara

Öyle bir an gelir ki

Kağıt yakmak ister kendini

Kalem, silmek bütün yazdıklarını 

Bir kalem ve kağıdın gölgesinde

Böyle sürer gider 

Bir şairin yaşam kavgası...

(Kasım 2002, İzmir)', 'Bir insan, Yaşarken yaşayamadıkları  Konuşurken söyleyemedikleri  Çoğaldıkça  Kalem düşer önce eline  Sonra önüne bir kağıt, İlk olarak yazd...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kavga-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice erkekler gordum', 'nice-erkekler-gordum-husamettin-guven-puv09', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgi sozleri siralayan

Kibarlikta pot kirmayan

Kadinlari oyalayan

Kice erkekler gordum

Yavrusuna evlatlik

Kocasina ortaklik

Kadinada sapiklik

Diyen erkekler gordum

Kadinlari oynatan

Ovunerek anlatan

Sozde sevgiyi satan

Nece erkekler gordum

Telefonlar acacagim

Ben onunla yatacagim

Sonra tekme atacagim

Diyen erkekler gordum

Cok gecmeden birakirim

Sonra sizler goturun 

Aliskindir yatirin 

Diyen erkekler gordum

Hollanda', 'Sevgi sozleri siralayan Kibarlikta pot kirmayan Kadinlari oyalayan Kice erkekler gordum Yavrusuna evlatlik Kocasina ortaklik Kadinada sapikl...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nice-erkekler-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmadim unutamam', 'unutmadim-unutamam-husamettin-guven-nn3ig', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bekliyorum o anlari

Zamansizca vuranlari

Iki yuzlu olanlari

Unutmadim unutmam

Sudunyayi karaltani

Terk ederek kacanlari

Serefini satanlari

Unutmadim unutmam

Sanman sakin unutulur

Bu olaylar kapatilir

Zamani var anlatilir

Unutmadim unutmam

Hollanda', 'Bekliyorum o anlari Zamansizca vuranlari Iki yuzlu olanlari Unutmadim unutmam Sudunyayi karaltani Terk ederek kacanlari Serefini satanlari U...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unutmadim-unutamam-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmasin bu son opucuk', 'olmasin-bu-son-opucuk-husamettin-guven-r4gwb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalvaririm guzel sana

Beni biraz anlasana

Sonkez deme ne olur bana

Olmasin bu son opucuk

Beni son kez opup gitme

Opucukten mahrum etme

Bu garibi yetim etme

Olmasin bu son opucuk

Kolen olam inat etme

Opucugu sakin kesme

Bu oglani onsuz etme

Olmasin bu son opucuk

Hollanda', 'Yalvaririm guzel sana Beni biraz anlasana Sonkez deme ne olur bana Olmasin bu son opucuk Beni son kez opup gitme Opucukten mahrum etme Bu ga...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olmasin-bu-son-opucuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne’ylesin', 'ne-ylesin-sadik-softa-496az', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anlatmaya kalksan anlatamazsın,

Dilin suçu yoktur,diller n’eylesin? ! 

Benim bezginliğim gönülden gelir,

Ben bile bilemem, eller ne’ylesin? ! 

Neylesin Züleyha,Yusuf bir gerçek,

Ferhat’ta  inanç var, dağı geçecek,

Kerem bulsa çölde,  suyu içecek,

Yürekte yangın var,haller ne’ylesin? 

Yürekten başlayıp, kurur dudaklar,

Bıçak gibi keskin, durur dudaklar,

Sevdanın kalbinde, çürür dudaklar,

Konuşmaz bir türlü, diller ne’ylesin? 

Sus pus olur sanki, bıçaklar açmaz,

Düğümler boğazı, su bile geçmez,

Deryaları salsan, alevler kaçmaz,

Yangın yeri gönül, göller ne’ylesin? 

Sevda kök salınca, duygular bitmez,

Yalvarsan,yakarsan,başından gitmez,

Durmadan kovsan da yine kar etmez,

Anlamaz ki canan, geller ne’ylesin? 

Çankırı-12.10.2004', 'Anlatmaya kalksan anlatamazsın, Dilin suçu yoktur,diller n’eylesin? !  Benim bezginliğim gönülden gelir, Ben bile bilemem, eller ne’ylesin? ...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ne-ylesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendime Yolculuk..', 'kendime-yolculuk-aysun-erat-vfbxp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ses etme hiç! 

Sus kal birazcık.

Gecenin huzurlu kollarına sal beni.

Ah! Bilsen,

Ne kalabalık, zaten dört yanım

Sesleri beynimde cırcır böcekleri…

Az zaman ver biraz

Yüreğimle baş başa dertleşiyorum.

Doğru mu? Yanlış mı? 

Ak mı? Kara mı? 

Eğriyi, düzü seçemiyorum.

Nerelerde kaybettim? 

Nerde unuttum? 

Bir türlü kendimi bulamıyorum…

Dağ, 

Tepe, 

Yol, 

Yokuş,

Çetin arayış.

Bir türlü kendime varamıyorum..

03/2005', 'Ses etme hiç!  Sus kal birazcık. Gecenin huzurlu kollarına sal beni. Ah! Bilsen, Ne kalabalık, zaten dört yanım Sesleri beynimde cırcır böce...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kendime-yolculuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklerim', 'beklerim-sadik-softa-7vlkc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne iz kaldı,nede bir nişan senden; 

Şimdi vedalara verip busenden; 

Aynalar kaç kere utandı benden; 

Senden uzaklarda gamla beklerim.

Dağlarca gönlüme taşır gam yükü; 

Tarihin seyrinden gelir bu ülkü; 

Ferhat’tan Şirin’e uzar bir türkü; 

Dirhem dirhem,damla damla beklerim.

Mecnundan başlamış sevda çılgınlık; 

Ne kadar uzarsa biner yılgınlık; 

Belirgin nişandır aşkta dalgınlık; 

Dalgınlıkta üzgün, gamla beklerim.

Beklerim canana, can esir olmuş; 

Beklerim can,canan ile yoğrulmuş; 

Sevda yüceldikçe, O’nu bulurmuş; 

O’na dönüp o sevdayla beklerim.', 'Ne iz kaldı,nede bir nişan senden;  Şimdi vedalara verip busenden;  Aynalar kaç kere utandı benden;  Senden uzaklarda gamla beklerim. Dağlar...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beklerim-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sohbetdir.*..Şiir değildir.; ''''Çukur çukur dolaşdı''''..Sevda İzleri.. ''''Çukur çukur ''''..Birbirine dolanık....', 'sohbetdir-siir-degildir-cukur-cukur-dolasdi-sevda-i-zleri-cukur-cukur-birbirine-dolanik-galip-kemali-gunay-8xwfw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beyaza bıraksak hasreti...

Ellerimiz sıcacık 

Sevda solusak...

Özledin mi sen de...

Dolaşır mı sevdan acep 

Çukur çukur

Karda.....

Sevda basdı buralara 

Geziniyor

Çukur çukur kar...

Dolanıyor.................

Sevda izleri..

''''*Tadmam için  şairinn** başüstüme yolladığı şiirinin*** bana hatırlattığı izler ve şiiri hissedişimdir, şiir değildir.''''

**SITKI GÖKMEN

***İTİRAF', 'Beyaza bıraksak hasreti... Ellerimiz sıcacık  Sevda solusak... Özledin mi sen de... Dolaşır mı sevdan acep  Çukur çukur Karda..... Sevda bas...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sohbetdir-siir-degildir-cukur-cukur-dolasdi-sevda-izleri-cukur-cukur-birbirine-dolanik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Değmezmiş Sana', 'degmezmis-sana-enes-yildirim-saglam-q1yrl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk denilen bir oyundu

İkimizin oynadıgı

Ağlatan yine sen oldun 

Yalvaran hep ben oldum

Bir rüyaydı yaşananlar

Yaşandı bitti o anlar

Sevgilim unut beni

Mazide kaldıanılar

Geri dön deme bana

Dönemem bir daha

Değmezmiş sana

Ağladığım yaşadıklarıma', 'Aşk denilen bir oyundu İkimizin oynadıgı Ağlatan yine sen oldun  Yalvaran hep ben oldum Bir rüyaydı yaşananlar Yaşandı bitti o anlar Sevgili...', ARRAY['Türk Edebiyatı','Şiir','Enes Yıldırım Sağlam']::text[], 8.5, '{"poet":"Enes Yıldırım Sağlam","poet_slug":"enes-yildirim-saglam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/degmezmis-sana-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugünden Yarına', 'bugunden-yarina-bahaettin-karakoc-vzppd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '‘Gavurdan dost, domuzdan post olmaz! ’ derdi anam,

‘Kırılan çanak, bir daha dolmaz! ’ derdi anam,

‘Zulm edenin yanına kalmaz! ’ derdi anam...

Çiçektik, sulardı, ‘solmadan büyüyün! ’ diye

Anlamlı ninniler söylerdi, vitamini bol

Dinlerdik, özümlerdik bitevîye...

Düşeni kucaklayıp yerden kaldırır

Üşüyeni sevgisiyle sarardı anam,

Yanından birazcık ırayıp gitsek

Bizi köşe – bucak arardı anam,

Rüzgârın dağıttığı saçlarımızı

İnce parmaklarıyla tarardı anam...

Çiçektik, sulardı, ‘solmayın! ’ diye

Hep dua ederdi ‘çirkin ölmeyin! ’  diye...

Yıllar bu minval üzere akıp gitti,

Biz büyüdük, annem bizi bırakıp gitti.

Bilenler: ‘tam bir Osmanlı kadın! ’ derdi anama.

O gitti, onunla Osmanlı gibi bir devir bitti.

Bizler aldık insanlık ormanındaki yerlerimizi,

Gâvurlar da, domuzlar da ırgalamıyor bizi...

Alıştık, zalimlere omuz vermek ar gelmiyor bize,

Poşetlere de girsek dar gelmiyor bize,

El ağzıyla konuşmaksa hiç zor gelmiyor bize.

Elbet bir gün biz de gideceğiz, evrensel kader bu! 

Bizim çocuklarımız fışkın sürer aynı ormanda

Belki ilkbaharda, belki de harmanda...

Rabb’im çocuklarımızı bizden basiretli kıl,

Her mide gurultusunun peşine düşmesin akıl! ...

Bahaettin KARAKOÇ (Sürgün Vezirin Aşk Neşideleri – Dolunay Yayınları – 2004)', '‘Gavurdan dost, domuzdan post olmaz! ’ derdi anam, ‘Kırılan çanak, bir daha dolmaz! ’ derdi anam, ‘Zulm edenin yanına kalmaz! ’ derdi anam.....', ARRAY['Türk Edebiyatı','Şiir','Bahaettin Karakoç']::text[], 8.5, '{"poet":"Bahaettin Karakoç","poet_slug":"bahaettin-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bugunden-yarina-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerine İyi Çalış', 'duslerine-i-yi-calis-yetkin-aksungur-pt97p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mektubun uzak geldiği zaman

Yakın bir düş hazırla kendine! 

Son savaştan kalma yenilgileri koy

Son anlaşmayı kaydet içine! 

Yorulursa yollar kavuşma mevsiminde

Bir daha dene, iki defa düşle! 

Fırtınanın önünden kaçır tedirgin günlerini

İlk sakin koyda demirle! 

En güzel giyitin olsun üzerinde

En sıcak gülüşlerini eksik etme düşünden

Zaafları kahkaha atan güçsüzler gibi,

Belli etme çelişkilerini

Rüzgarın şiddetini yalnız sen belirlersin

İstemezsen düşler bile kıpırdamaz yerinden

Ayrılık her dilde aynı kolay sözcükle yazılır

Kavuşmak emek ister

Bir kez alışırsan tembelliğe

Düşlerinin rengi uzaklaşır önce

Sonra umut terk eder yarınlarını

O halde iyi çalış düşlere!', 'Mektubun uzak geldiği zaman Yakın bir düş hazırla kendine!  Son savaştan kalma yenilgileri koy Son anlaşmayı kaydet içine!  Yorulursa yollar...', ARRAY['Türk Edebiyatı','Şiir','Yetkin Aksungur']::text[], 8.5, '{"poet":"Yetkin Aksungur","poet_slug":"yetkin-aksungur","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duslerine-iyi-calis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meşgulüm', 'mesgulum-oguzkan-bolukbasi-0fsjc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni sevmeye devam edeceğim

sen başkalarını severken

hiç bir şey beklemeyeceğim

umut diye bir şey yok haznemde

bir yerlerde

her hangi bir şeyleri seyrederken

simit yerken çayın yanında

veya büyük denilen birinin makamında söz dinlerken

ben seni düşüneceğim

seni seveceğim

bekleyenlere

gelemeyeceğimi bildireceğim

meşgulüm

seni sevmekle

işim bitince öleceğim

beni ölümsüz kıl', 'seni sevmeye devam edeceğim sen başkalarını severken hiç bir şey beklemeyeceğim umut diye bir şey yok haznemde bir yerlerde her hangi bir şe...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mesgulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-arif-emrah-toyoglu-ctymn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bizimki ölüm değil

sadece bir ceset..

algılanan bu cisim yaşam

uydurma bir baş yapıt

dokunmak isteğine bağlı..

adımlarını körelterek

karşılaşmalara son verebilirsin

ama bir karşılaşmada göz göze gelmek

bizimki görmek değil

sadece bir bakış

bir kokuyu manşetinde gizlerken

asıl kokuyu dizelerinde işlersin

yetinmek arzusuna bağlı..

avuçlarını sıkarak

birine elini tutma fırsatını vermeyebilirsin

ama bir dokunuşta ruhunu titretmek

bizimki hissetmek değil

sadece bir duygu..

mavi bir dalga yaratmak zor

durgun bir denizde

önceden yaşamana bağlı..

bulutlar çizerek

bir çırpınma yapabilirsin

ama bir okyanusta deniz kizi görmek

bizimki yaşanmış değil

sadece bir olasılık

kalabalık bir caddede

insan bulmak raslantı olamaz

bulunma nedenine bağlı..

duyularını kapatarak

yalnız olduğunu kanttlayabilirsin

ama mutlak bir oyunda rekabet etmek

bizimki insan olmak değil

sadece bir kural

rengarenk uzay boşluğunda

beyaz sıradan bir parçadır

boyama yetisine bağlı..

bir ağaç dikerek 

istediğin bir meyveyi yiyebilirsin

ama ''var'' bir resimde saydam olabimek

bizimki bir gelecek değil

sadece bir amaç

ateş ve su yaşlanma gereğidir

zıtlık ancak manada

fikir yürütmene bağlı..

yağmurda öpüşerek

yangınını bir an söndürebilirsin

ama bir kibritte herşeyi yok etmek

bizimki koybalmak değil

sadece bir yitik

rahat bir yatakta çıplak vücudunu izlerken

büyük bir zevk kendi lehinizedir

sevişmek isteğine bağlı..

mahremini örterek

orgazmı geciktirebilirsin

ama çıldırmış bir anda giyinmek

bizimki üremek değil

sadece bir mantık

kahraman romanın ilgi çekiciliği

yazar kahramanın gerçek halidir

yazabilme hevesine bağlı..

romanı yakarak

kahramanın öldüğünü öğrenmeyebilirsin

ama büyük bir gerçeklikle ölümsüz olabilmek

bizimki bir dram değil

sadece bir başlık

bir kadın bir erkeğe bölünmez

parçaları hala kadındır

düşünme gücüne bağlı..

bir kadını severek

paydanda ruhunu hissedebilirsin

ama bir aşkı vücudunda dirilmek

bizimki karşılık değil

sadece bir sonuç

yüksek bir uçurumda intihar

karanlık bir intikam olmaz

cesaret edebilmene bağlı..

bileklerini keserek

yaşamına son verebilirsin

ama nedensiz bir sırla sonsuzluğa gömülmek

bizimki ölüm değil

sadece bir ceset........', 'bizimki ölüm değil sadece bir ceset.. algılanan bu cisim yaşam uydurma bir baş yapıt dokunmak isteğine bağlı.. adımlarını körelterek karşıla...', ARRAY['Türk Edebiyatı','Şiir','Arif Emrah Toyoğlu']::text[], 8.5, '{"poet":"Arif Emrah Toyoğlu","poet_slug":"arif-emrah-toyoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/biz-79-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrak Uğruna', 'bayrak-ugruna-zafer-sik-czoh8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vatanımda, olmadı sensiz leyâlin fecri,

Uğrunda ölenlerin ancak cennettir ecri.

Aşk kırmızısı kanlar döküldü yollarında,

Muâsır medeniyet şuûrunun altında! 

Âb-ı hayat iksiri dalgalandığın yerde,

İkliminde yaşayan asla düşmedi derde.

Milyonlar başlarımız fedâ sana bayrağım,

Mevsimin hazan değil, kış değil.. gül bayrağım.

Hele bak! Şehidimin kanıyla yıkanmışsın! 

Cihân dar geldi sana, yüreklerden taşmışsın! 

Cânân sensin her dâim gönüllere, ruha cân,

Cana cândır şu mavi göklerde dalgalanman.

Topraklarında hiçbir zaman güneş batmadı! 

Vatanımda en kutsal aşkın bayraktır adı! 

Mazimiz, uğruna hep zaferlerle dopdolu,

İstikbalimiz daha parlak, yol Allah yolu! 

Cânım ve cânânım sen, nâmus ve şerefim sen,

Yüreğime sığmayan, lahuti gül sevdam sen! 

İlk ve son arzum seni şu göklerde hür görmek,

Uğrunda gerekse, bir değil bin defa ölmek! 

Hep senin için atan bir kalbi taşıyorum,

Sensizlik yalancı tan, ben sende yaşıyorum! 

Hiç çiğnetmedik seni ve çiğnetmeyeceğiz

Sana uzanan eli mezara gömeceğiz! 

Anayurt Gazetesi 17 Nisan 2005', 'Vatanımda, olmadı sensiz leyâlin fecri, Uğrunda ölenlerin ancak cennettir ecri. Aşk kırmızısı kanlar döküldü yollarında, Muâsır medeniyet şu...', ARRAY['Türk Edebiyatı','Şiir','Zafer Şık']::text[], 8.5, '{"poet":"Zafer Şık","poet_slug":"zafer-sik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bayrak-ugruna-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derin Bir Sevdasın', 'derin-bir-sevdasin-hatice-bediroglu-h08fm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim

Hem sevdiğim

Hem hüznümsün

Hep özlediğim

Hiç ulaşamadığım

Hem çok uzak

Hem çok yakın

Hep içimde

Hiç bir yere gitmeyen

Sürekli 

Kabararak büyüyen

Derin bir sevdasın

www.haticebediroglu.net

(Şiirlerimin hepsi Noter tasdiklidir)', 'Sen benim Hem sevdiğim Hem hüznümsün Hep özlediğim Hiç ulaşamadığım Hem çok uzak Hem çok yakın Hep içimde Hiç bir yere gitmeyen Sürekli  Kab...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/derin-bir-sevdasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereme Dokunsam', 'nereme-dokunsam-hatice-bediroglu-8uiyf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir çığ gibi

Büyüyorsun içimde

Her yerim

Sıcak karlarınla kaplı

Eriyip dolduruyorlar içimi

Sımsıcak yumuşacık

İçimde geziyorsun

Nereme dokunsam

Sen oluyorsun

Ürperiyorum

www.haticebediroglu.net

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005', 'Bir çığ gibi Büyüyorsun içimde Her yerim Sıcak karlarınla kaplı Eriyip dolduruyorlar içimi Sımsıcak yumuşacık İçimde geziyorsun Nereme dokun...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nereme-dokunsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanatsız Uçuşlar', 'kanatsiz-ucuslar-hatice-bediroglu-wfdhw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni sevdiğini her söyleyişinde

Gökyüzüne…

Kanatsız uçuşlar yapıyorum.

Uçuşlarım iki kişilik.

Mavinin dinginliğinde

Huzur buluyorum.

Sana dokunmak istiyorum

Tutku alevleniyor içimde

Akan lavlara dönüşüyor

Dudaklarını arıyorum.

Öpmeye…

Hiç doyamadığım dudaklarını

Bulamıyorum.

Sen, yoksun işte

Düşüyorum hızla

Huzur..

Hüzne bırakıyor yerini.

Parçalanıyor duygularım

Eziliyor bedenim

Bir hoş oluyor içim

İzci düğümleri...

Sıkıştırıyor boğazımı

Çözülmemecesine.

Gözlerimde...

Dans etmeye başlıyor bulutlar.

Sevgi, tutku, hüzün

El ele verip

Kuvvetli bir sağanak oluyor.

Ve akıyorum yeryüzüne

İnadına coşarak...

İnadına çoğalarak…

Her damlasında

SEN VE BEN 

www.haticebediroglu.net

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005', 'Beni sevdiğini her söyleyişinde Gökyüzüne… Kanatsız uçuşlar yapıyorum. Uçuşlarım iki kişilik. Mavinin dinginliğinde Huzur buluyorum. Sana do...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kanatsiz-ucuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece', 'dun-gece-birsen-ates-42nfx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sana aitim, 

sende bana 

demiştin / demiştim 

ne kadar dilin söylese de 

dün gece

anladım/ağladım 

belki de 

derin tutkuydu 

yaşananlar 

bir anlık 

bedenin benimleydi 

içimi ısıtan gülüşlerin 

ama 

ruhun asla 

dün gece

anladım/ağladım 

işte bu yüzdendir 

gözyaşlarım 

yine mevsimler karıştı 

yanımdayken sensizliğin

sevgin eritirken 

yüreğimi 

buz kesti gülüşlerim 

dün gece

anladım /ağladım', 'sana aitim,  sende bana  demiştin / demiştim  ne kadar dilin söylese de  dün gece anladım/ağladım  belki de  derin tutkuydu  yaşananlar  bir...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dun-gece-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bade harabûl Basra*', 'bade-harab-l-basra-cem-hire-mx95r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Artık çok özlemişti evdekileri. 

Çocuklar top oynardı arkadaki sahada,

o da katılmak isterdi oyuna ama,

topu tutmayı bir kez olsun bile becerememişti.

Bazen oyuna girerdi de, çok sürmeden

birkaç tekmeyle tonla küfür yedikten sonra,

bulduğu ilk gölgeye uzanıverirdi çölün sıcağında. 

Umursamadı önce olanları, geçecek sandı. 

Geçecek, boşalacak sokaklar, sokaklar,

kendinde olalı beri hiç bu kadar  dolmamıştı? 

Sokakları dolduranlar tanıdıklardı ve

asıl bu onu şaşırtmıştı: Yan bahçedekiler, 

karşı evdekiler, çok sevdiği Attar, Ömer, Kader,

Fatma’yı da görmüş müydü ve Hasan,

okula giderken başını sıvazlamayı asla unutmayan.

Dün akşamki düğünde, ki düğün mevsimiydi yine,

ve, bunca ömrü zamanında çok düğün görmüştü,

Fatma’nın babasını anımsamıştı öncekilerden, 

elindeki kocaman tüfekle saydırmaya başladığını

adamın göğe doğru. Çok korkardı bu seslerden,

gölgesi en yüksek ağacın ardına sığınırdı hemen.

Anlatılır gibi değildi sesler bu sefer,

görmek lâzım, kaçacak bir yer de kalmamıştı,

günlerce aç dolaştıktan sonra bombardıman altında

Çomar, bir sabah, Hasan’ın kollarının altında

uyandı,sıcacık, akşam parmaklarını yediği,

bade harabûl Basra! 

 * Basra harap olduktan sonra..', 'Artık çok özlemişti evdekileri.  Çocuklar top oynardı arkadaki sahada, o da katılmak isterdi oyuna ama, topu tutmayı bir kez olsun bile bece...', ARRAY['Türk Edebiyatı','Şiir','Cem Hire']::text[], 8.5, '{"poet":"Cem Hire","poet_slug":"cem-hire","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bade-harabul-basra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-muhiddin-ates-3c32n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşin saltanatı bittiğinde

Gecenin karanlığı çöktüğünde

Gözlerin kapakları düştüğünde

İnsanlar uykuya daldığında gel

Sabah ezanları okunduğunda

İnsanlar namaza durduğunda

Gün ağarıp aydınlık olduğunda

Ak ile kara belli olunca  gel

İster kuşluk vaktinde

İster öğle saatinde

Sen kendi dilediğinde

İstediğin vakitte gel.', 'Güneşin saltanatı bittiğinde Gecenin karanlığı çöktüğünde Gözlerin kapakları düştüğünde İnsanlar uykuya daldığında gel Sabah ezanları okundu...', ARRAY['Türk Edebiyatı','Şiir','Muhiddin Ateş']::text[], 8.5, '{"poet":"Muhiddin Ateş","poet_slug":"muhiddin-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-167-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ege''de Bıraktığım Yerde', 'ege-de-biraktigim-yerde-cem-hire-5493u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Koyda kırılmış kimselerin vurmuş

yüzleri var her bir çakıl taşında,

diye biliyorum Midillili Bercise Hanım’dan.

Sabah, belki vururum ben de diye korkumdan,

hiç suya basmadan yürüyorum.

Bilir misin demişti, Bercise Hanım,

nereye koyar içini deniz kabukları? 

Akşam sofrada kupes ve rakı,

Ağzımda rokanın garip tadı,

Uzayıp giden gözlerle Midilli’ye bakıyorum.', 'Koyda kırılmış kimselerin vurmuş yüzleri var her bir çakıl taşında, diye biliyorum Midillili Bercise Hanım’dan. Sabah, belki vururum ben de ...', ARRAY['Türk Edebiyatı','Şiir','Cem Hire']::text[], 8.5, '{"poet":"Cem Hire","poet_slug":"cem-hire","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ege-de-biraktigim-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun', 'uzun-yusuf-ter-6igeq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzun 

Uzayacak karanlık

Tan şafağa tutacak

Sevdalardan uzaklaşarak

Hayattır tek paylaşmak

Can verirsin

Can uğruna

Bakarsın tek başına

Soğuk ayazlarda 

Son satırları yazarak

Isınmak istersin

Ak göğüslerde uyuyarak…

31.03.05

Saat 18:45 İsviçre 

www.yusufter.de.tl', 'Uzun  Uzayacak karanlık Tan şafağa tutacak Sevdalardan uzaklaşarak Hayattır tek paylaşmak Can verirsin Can uğruna Bakarsın tek başına Soğuk ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uzun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarap İçin O Vakit', 'sarap-i-cin-o-vakit-cem-hire-3ofx0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O büyük çınarın altında durdu 

köye giden dolmuş, küçük çağlayanın yanında. 

Mangallarda deve sucuğu su başında, 

kadınlar semizotu topluyor aşağılarda.

Karşıdaki taş çukurlarda, 

- onlar böyle demiyordu güçlü ihtimal – 

üzüm ezermiş çok eskiden 

çıplak ayaklarıyla kadınlar şarap için.

Şarap için onca acıya katlandı 

kadınlar o vakit, adamları baş dönmesi 

bizim için kandı, dedi Bercise Hanım, 

ben de onlara kandım.', 'O büyük çınarın altında durdu  köye giden dolmuş, küçük çağlayanın yanında.  Mangallarda deve sucuğu su başında,  kadınlar semizotu topluyor...', ARRAY['Türk Edebiyatı','Şiir','Cem Hire']::text[], 8.5, '{"poet":"Cem Hire","poet_slug":"cem-hire","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sarap-icin-o-vakit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zeytin', 'zeytin-cem-hire-3v0ug', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kasabaya girerken yükseklerde 

bir eski kilise ilişiyor gözüme, 

şimdi bir bağ evi olmuş. 

Yanındaki birkaç kavağın altındaki 

çeşmeye gitmiştim birkaç gün sonra, 

Hacı İsmail hayratına. 

Dönüşte yerlere saçılan 

zeytinlerden toplamıştım 

Bercise Hanım’ın sözleri aklımda: 

Zeytin tüm inançlardan 

daha önemlidir buralarda.', 'Kasabaya girerken yükseklerde  bir eski kilise ilişiyor gözüme,  şimdi bir bağ evi olmuş.  Yanındaki birkaç kavağın altındaki  çeşmeye gitmi...', ARRAY['Türk Edebiyatı','Şiir','Cem Hire']::text[], 8.5, '{"poet":"Cem Hire","poet_slug":"cem-hire","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zeytin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bergama''da O İlk Aşk', 'bergama-da-o-i-lk-ask-cem-hire-ocfaf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eski sütûnlu caddeyi tırmanıyor 

ağaçlıklı yoldan, tepede Asklepion’a 

varıyor, virankapısında Buraya 

Ölüm Giremez! yazan eskiden.

Belki de bu kapının eskiden olduğu yerde,

süslenmiş develerle poz veriyor şimdi, 

nereli olduklarını kestiremediği 

gülücüklerle genç, güzel kızlar. 

Her kalıtın önünde asılı levhaları 

okuyor dikkatle, bir de 

hiç inanmasa da mermer havuza 

bozuk para atıyor bir dilek tutup.

Bir kemerin altından usulca geçerken o, 

aşağıda günebakanlar eğilip selamlıyor 

ayı güneş henüz batmamışken, 

kızarmış narların tam çatlama zamanı.

Çamlar meltem üflüyor seyrelmiş uzun

sakalına görmüş geçirmiş durmuş 

adamın, söylencelere inandığı 

vakitler çok eskilerde kalmış, 

biliyor hiçbir uykunun yarasını 

iyileştirmeyeceğini ve hiçbir tanrının, 

hâlâ Bergama’da yaşayan o kadın 

kadar asla sevilemeyeceğini.', 'Eski sütûnlu caddeyi tırmanıyor  ağaçlıklı yoldan, tepede Asklepion’a  varıyor, virankapısında Buraya  Ölüm Giremez! yazan eskiden. Belki de...', ARRAY['Türk Edebiyatı','Şiir','Cem Hire']::text[], 8.5, '{"poet":"Cem Hire","poet_slug":"cem-hire","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bergama-da-o-ilk-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekirge', 'cekirge-cem-hire-56vm2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O kışa girerken o ayazda

tüm portakallar kavrulmuştu sahildeki,

yerlinin biri demeseydi farketmeyecektik.

 İki yanı selvili o yoldan ilerlerken sahildeki,

hep bir filmin içinden geçer gibi hissederdim kendimi,

bittiğinde, geriye doğru uzayıp genişleyen içimde bir

boşluk.

O kışa az kala o ayazda,

belki sonuncu çekirgesini gördüm mevsimin:

Güçlü denemezdi hareketlerine eskisi kadar ama,

- eskisini de bilmem ya gerçi – gideceği bir yer olacak ki,

hızla sıçradı köpükler taşıyan kanala doğru sağ yanımdaki.', 'O kışa girerken o ayazda tüm portakallar kavrulmuştu sahildeki, yerlinin biri demeseydi farketmeyecektik.  İki yanı selvili o yoldan ilerler...', ARRAY['Türk Edebiyatı','Şiir','Cem Hire']::text[], 8.5, '{"poet":"Cem Hire","poet_slug":"cem-hire","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cekirge-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Rüyaların Yolculuğu', 'kayip-ruyalarin-yolculugu-meltem-kaya-ul2wx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1.

Uykuları çağıran eski bir koku…Nerden ve hangi eskimeyen anılardan kopup geldiği aşikar olsa da; kendinden geçerek ardı sıra koşulan eski bir koku…

Uykuları çağıran o eski koku, uykulardan uyanmamayı ve dipsiz kuyularda merdivensiz kalmayı istiyor…bedelleri aşikar olsa da; düşünmeyi geçerek rüzgarında salınılan o eski koku…

2.

Saçlarım ne zaman bu yollara uzadı…bilmiyorum. Bu dipsiz kuyularda mataramda bir damla suyum yokken ben nasıl o kuyunun üzerinden dipteki kendime bakabildim…bilmiyorum. Ya da kuyunun dibindeki benliğim yukarılardan onu izleyen kendisine hiç kaldırıp başını konuştu mu? Diptekinin sözcükleri yok, gözlerinin rengi yok…yukarıdakinin sözcüklerinden kan damlıyor, gözleri nehirler kadar ıslak…. Bakıyor yukarıdaki, sözcüklerinden sızan kan ve gözlerinden akan nehir, diptekinin matarasına su diye doluyor….

3.

Uyku…Uykunun heybesinde dinlenmeler çok vakittir yok artık, nasıl olduğunu hatırlamıyorum. Uyku ölüme benziyor. Günün en ışıklı saatinde siyah bir perde çekilmiş gibi cama, uykuya dalmak istiyorum. Ama neden o siyah perdeden bunca çok ışık gözümü alıyor? Gözlerim ışık yorgunu, bedenim uykuya tutkun…Uyumak ve bir daha hiç uyanmamak…Sanki hiç gelmemişsin gibi, sanki yaşamak denen kervandan hiç geçmemişsin gibi dalıvermek uykuya…Sukunetin baş döndüren çağrısı! Ah, ne olurdu bu kayıp rüyalar beni bulup da yeniden yeryüzüne uyandırmasaydı…

4.

Dalıyorum…Uykunun heybesi rüyalarla dolu. Seç diyen bir ses var gizliden, benden başkası duymuyor. Ben seçemeden geliyor o kayıp konuk, uykunun heybesi yeni yollara düşüyor. Sonrası seyirciyim işte..başlıyor ve alkışlarla karşılıyorum rüya perdesini…Yavaş yavaş açılıyor perde, ama benden başka seyirci var mı..bilmiyorum. 

5.

Dalmakla uyanıklık arası bir uçurumda başlıyor kayıp rüyalar matinesi…Uyanmakla uyanmamak arası süren bir yolculuk da sanki oynayan benmişim gibi gözlerimi veriyorum kayıp rüyaların baş rol oyuncusuna…yoksa kuyunun dibindekinin gözlerinin rengi o yüzden mi yok…bilmiyorum….Benim sözcüklerimle başlıyor her şey, ben yazmışım gibi veriyorum her bir sözcüğümü o kayıp rüyalar oyuncusuna…yoksa diptekinin sözcükleri o yüzden mi kayboldu…bilmiyorum. 

6.

Benim sözcüklerim… Benim kanayan, benim ağlayan ve ağladığınca çok gülen sözcüklerim…Hep yoldaşım oldular. Neden lal dilim öyleyse? Neden rüyalarımda hep içimde konuşan sözcüklerimi benden başka kimse duymuyor? Kayıp rüyalar oyuncusu benim sözcüklerimle konuşuyor. Sanki ben gibi, sanki gece yarısı bir köşe başında vurulup da ölümle koyun koyuna yatar gibi, sanki ölümleri hiç bilmemiş gibi, sanki ten ölümle buluşunca buz kesmezmiş gibi sıcacık sözcüklerim… Hem bana yakın, hem benim değilsiniz. Şimdi anlıyorum usuldan…Dipteki benim sözcüklerimi kayıp rüyalar oyuncusuna armağan etti. Gördüm onu ben, eşi bulunmaz yeşil ipek bir halının içine sarıp sarmalanmıştılar. Sessizce açıldı ipek halı, sözcüklerim dört bir yana dağıldılar. Gördüm onu ben, kayıp rüyalar oyuncusu kocaman yeşil bir halının üzerinden papatyalar toplar gibi sözcüklerimi toplayıp cebine koyuyordu. Dilim sustu.

7.

Susuzluğum benim…Benim kanmayan, benim yarım kalan, benim asırlık çöl susuzluğum…Kayıp rüyalar matinesinde oturduğum sandalye denizin ortasında…Tuzun tadı ve denizin yeşili çağırıyor beni, oysa ben çok susuzum. Kayıp rüyalar oyuncusu seranatına başlarken akıl terazimde asırları saniyeyle çarparak su içmeyi düşlüyorum, bir de uyanmamayı…Kayıp rüyalar oyuncusunun sesi soluksuz bir ney gibi… O hiç susuzluk çekmez mi? Denizi içmek istiyorum, eğildikçe deniz uzaklaşıyor. Yerde çırpınan balıklar var, açılıp kapanan istiridyeler, yosunlar kurumuş, inciler dağılmış sanki…Koşuyorum, ama koşmamalıyım. Kayıp rüyalar oyuncusunun sesinden uzaklaşmamalıyım. Ama ona da bir avuç su taşımalıyım… Koştukça deniz bitti, ardıma baktıkça yaklaştı deniz…Usulca yerime dönerken küçük bir çocuk sesi uzaktan yaklaşıyordu…

8.

“Rüya sucusu çocuk, uykusu arasında susayanlara su veriyordu.”*Eduardo Galeano

9.

Susuzluğum dindi. Bazı kısımları pas tutmuş, siyaha ve yeşile çalan bakır bir ibrikten kanasıya içtim suyu…Yüzüm aydınlandı. Sırları dökülmüş gümüş çerçeveli bir aynada yüzümü gördüm birden. Bu benim yüzüm mü? Bu benim hangi yüzüm? Yüzümdeki bu boşluk neden? Yüzüm bin bir parçaya ayrılmış, bir parçasını bulamıyorum. Yüzüm tam değil…Sanki yüzümden kuş gibi, bulut gibi bir parça noksan. Kayıp rüyalar oyuncusunun yüzünde bir kuş gördüm o anda, gagasıyla ona su içirmekteydi. 

10.

Kuğular ne zamandır bu koyu lacivert gölde böyle edayla yüzmemişlerdi. Akça pakça, kar beyazı boyunlarında, aklığını hiç yitirmeyen bir yaşamın gölge düşmeyen mutluluğu vardı. Ben bir bulutun üstündeydim ve gözümü bir an olsun beyazlıktan ayırmadan salınışlarında dalgalandım. Yaşam sanki iki çam dalı arasında rüzgarıyla sevişen bir hamak gibi dingindi. Ben hamakta değildim. Ama kayıp rüyalar matinesinin oyuncusu hamaktaydı ve çam kokan bir gülüşle kuğulara dokunmaktaydı. Ellerime baktım, ellerim yoktu. 

11.

Birden kıyıda serçeler telaşlandılar. Birden kum fırtınaları yaklaştı dingin göle…Birden, birden gökyüzü karardı. Ne olduğunu anlayamadım. Kayıp rüyalar oyuncusu hızla kül rengi bulutların birinden diğerine koşmaktaydı. Ateş hızında pırıltılar gözbebeklerinde nakışlıydı. Yüreğim benim, ah benim yazgısı kara yüreğim! Bu ateş nasıl söner? …Yağmurlar yağdırmalıyım ben? Ama nasıl? Bulutları damlalarla doldurmalıyım. Kayıp rüyalar oyuncusu ateşler içinde…Damlalar bulmalıyım…Ama nasıl? Gözyaşlarım! Gözyaşlarımı çağırmalıyım. Damlalar kirpiklerimden bulutlara yağmaya başladı sonunda. Ateş söndü, gök aydınlandı, gökkuşağı boylu boyunca serildi göğün denizine. Kayıp rüyalar oyuncusu, gülümsüyor bana. Ama göz pınarlarım kurumuş artık, bakamıyorum. Son gözyaşı damlamla kurtardım onu, mutluyum. Ama artık gözyaşım kalmadı benim. Ağlayamam. 

12.

Kırık bir testi neyi anlatır kiremit tozlarının ağırlığında? Kırık bir testi ayrılığı anlatırken, kayıp rüyalar oyuncusu kavuşmayı anlatıyor. Çetelesini tutmuş ayrılıkların kırık testi, sızacak su kalmayacak kadar hayat damarı kurumuş. Kırık kulbu kalbi gibi darmadağın, ama matarasında hiç su kalmayan kayıp rüyalar oyuncusuna kulbun içindeki son damlayı bir cenin gibi sunuyor. Cenin hayat bulsun diye, tereddütsüzce sunuyor. Kendisini kiremit tozlarının ağırlığına bırakıyor, ama bedeli umrunda değil. Kayıp rüyalar oyuncusunun yolu uzun, yolu benden ayrılık, ama o yürümeli. Öylece bakıp kalıyor ardından kırık testi… Ama neden benim her yerim kiremit tozu içinde? Bilmiyorum…

13.

Filizler çürümeyen bir gecenin içinde uç vermişler. Kayıp rüyalar oyuncusu benim sözcüklerimle dillendiğinden bu yana, saymadığım saatler boyunca ıslak hüzünleri anlattı bana. Dağlar nazlı bir gelin gibi salınmaktaydı bahara karşı. Dağlar bu bahar gulilk çiçeğini doğurmuş ve kışlardan sakınmakta ve saklamaktaydılar. Tufanlar uzak gibiydi, ama dağlar dervişiydi tüm zamanların ve güvensizdiler. Dağ bir cesaret gerektiğini söyleyerek kayıp rüyalar oyuncusuna can gerek dediler bana… Çıkınıma baktım, azığım hiç yoktu, bedenimde taşıdığım bir can vardı yıllarca filizlenen, çıkın yapıp uzattım kayıp rüyalar oyuncusuna. Filizleri kattı kendi canına, yeşildi artık… Kayıp rüyalar oyuncusu gulilk çiçeği oldu, dağlar onu koynuna aldı. Ben kuru bir dal kaldım.

14.

Saç diplerim terliyor gittikçe daha çok…Bin hançerin ortaya yerinde çünkü O! O ki benim tereddütsüzce gözlerimi, ellerimi, sözcüklerimi  ve canımı sunduğum… Ben seyircisi olamam kayıp rüyalar oyuncusunun yitiminin, olamam. Bir hançer bulmalıyım. Ya da bin hançerin vurduğu ben olmalıyım. Ama ben seyircisiydim hep bu perdenin, o zaman oyuncusu olmalıyım. Hançerim yok, tek cephanem sözlerim…. Ne yapacağımı hiç bilmeden hızla yürüyorum perdeye… Kayıp rüyalar oyuncusu şaşkın, bin hançeri tutan bin kişi de şaşkın… Kimse tanımıyor beni, ama ben o büyük perdede taşıdığım rolü şimdiden öğrendim bile. Beni taşıyan ayaklarım ondandır ki kendinden eminler…Perdeye çıktığım anda bin hançerin bana doğrulmasına gülümsüyorum. Bin hançer bin yerden savruluyor üstüme, oracığa düşüyorum. Son gördüğüm şey kayıp rüyalar oyuncusu… El sallıyor bana, yüzündeki eflatun acı silinsin istiyorum sadece. O’na bin kez sunduklarımı O hiç bilmezken ben vardım, O’nun için bin hançerle bir kez öldüğümü bilip acı duymasını istemiyorum. Siliniyor yavaşça izler, son kez gözlerimi gözlerine iliştiriyorum. Ben gidiyorum. Hoşça kal perde! Hoşça, kal içimde…

15.

Pencereden bana hanımeli kokuları uzatan bir sabaha gözlerimi açtım. Uyandım…

16.

Var olmasına inanamadığım ellerimle gözlerime dokundum, bir damla gözyaşını tuttu ellerim… Gözyaşımın tuzunu hissettim. Islaklık kiremit tozu rengindeydi. Başucumda yıllardır durmakta olan testi bin parçaya bölünmüştü. 

17.

Odamda boylu boyunca yeşil bir halı seriliydi. Üzeri yeşile  tamamen serilmiş papatyalarla doluydu. Eğildim ve papatyaları toplayıp cebime yerleştirdim. Papatyalar sözcüklerimdi. 

18.

Baharla sevişen rüzgarı hissettim balkona çıktığımda…Kalbim kum fırtınasına tutulan serçeler gibi çırpınmaktaydı göğüs kafesimin içinde. Deniz? Ya yoksa yerinde? İlk bakışta sevişti gözlerim nazlıdan salınıveren denizle, kalbimdeki serçeler duruldular ve yeşeren dallarıma kondular usulcuk… Denizin yeşili yerini süt mavisine bırakmakta ve şehir yeni doğan güne kendini hazırlamaktaydı.

19. 

Biri seslenmiş gibi çabucak döndüm ve yürüdüm. Sırları dökülmemiş gümüş çerçeveli aynada yüzümü gördüm. Bu benim yüzüm mü? Yüzüm bin bir parça değil…. Yüzümde bir kuş gördüm, gagasıyla bana su içirmekteydi. Kanasıya içtim. 

20.

Aynadaki yüzüm kayıp rüyalar oyuncusunun yüzüydü.', '1. Uykuları çağıran eski bir koku…Nerden ve hangi eskimeyen anılardan kopup geldiği aşikar olsa da; kendinden geçerek ardı sıra koşulan eski...', ARRAY['Türk Edebiyatı','Şiir','Meltem Kaya']::text[], 8.5, '{"poet":"Meltem Kaya","poet_slug":"meltem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/kayip-ruyalarin-yolculugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Caresizsin caresiz', 'caresizsin-caresiz-husamettin-guven-h1mon', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hakkinyoktur sevemezsin

Karsilikmi goremezsin

Hep vururlar olemezsin

Caresizsin  caresiz

Neyapsan yaranamazsin

Sen kendini adarsin

Bir umuttur yasarsin

Caresizsin  caresiz

Hasta olsan bilmezler

Birgun hatir sormazlar

Ellerinden tutmazlar

Caresizsin  caresiz

Hollanda', 'Hakkinyoktur sevemezsin Karsilikmi goremezsin Hep vururlar olemezsin Caresizsin  caresiz Neyapsan yaranamazsin Sen kendini adarsin Bir umutt...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/caresizsin-caresiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karataşlı Zalim', 'karatasli-zalim-cem-hire-z6xqz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Baharın ilk zamanları, yağmur var yine biraz, 

kaygısız geziyorum Kadıköy’de sokakları. 

Postaneyi dönüyorum, eski bir şarkı çalınıyor 

kulaklarıma: Kadınım, sevdiğim o koku 

yok artık bu evde, kadınım... 

Bir anda geçmişi hatırladım: 

Çamlı bahçesinde yürüyoruz 

Karataş Lisesi’nin, ilk kez 

elele tutuşmuşuz, hafif bir yağmur 

üzerimizde konuşuyoruz.

Dersler mersler derken, nedendir bilmem, 

dayımdan sözediyorum ona, 

ne denli benzediğinden Tanju Okan’a. 

Onun kadar iri cüssesinden ve 

yüzünde gizlediği hüzünden onunki gibi.

Susuyoruz sonra ıslanıyoruz, 

durağa dek yürüyüp ayrılıyoruz. 

Sonra bir haftaya kalmadı 

- bunu nasıl yapabilmişti -, 

benden hayli çelimli biriyle çekip gitti.

Oysa dayımdan sözetmiştim ben ona, bir de 

romantik, hüzünlü hemşerim Tanju Okan’dan. 

Kızlar kesin anlamıyordu böyle şeyleri 

ve beni, ya da şimdi olduğu gibi o yıllarda da 

ben beceremiyordum bir şeyleri.', 'Baharın ilk zamanları, yağmur var yine biraz,  kaygısız geziyorum Kadıköy’de sokakları.  Postaneyi dönüyorum, eski bir şarkı çalınıyor  kula...', ARRAY['Türk Edebiyatı','Şiir','Cem Hire']::text[], 8.5, '{"poet":"Cem Hire","poet_slug":"cem-hire","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/karatasli-zalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-herkes derdini yazar', 'a-herkes-derdini-yazar-mikdat-bal-ukv9u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Herkes derdini yazar!

Herkes derdini yazar kimi söz kimi laftır

Söz uzadıkça uzar yazılan fotoğraftır

Her konuda yazılır sevgi ile düzülür

Ayrılanlar üzülür yazısı itiraftır

Gurbetçi hasretini dindar yazar dinini 

Kimi boyuna bakar kimi bakar enini

Kimi birinde ketum kimi yazar binini

Kindar yazar kinini terk ettiği insaftır

Kimi nefreti işler kimi sevgiyi anmaz

Kimi yalana uyar kimi doğruya kanmaz

Kimi dünyayı sever başka bir şeyi anmaz

Anlatmaktan usanmaz onun hali tuhaftır

Kimi aklı havada kimi esen yellerde

Kimi dağları deler kimi gezer çöllerde

Kimi gurbet ellerde başka, başka yerlerde

Ayrı, ayrı illerde dolaştığı etraftır

Kimi içinden yanar kimi derdi zahirdir

Her yazanın yazdığı bir konuya dairdir

Ozanda aşk, kahırdır şiir yazan şairdir

Aşık aşkta mahirdir bu konuda sarraftır

Mikdadi şahit olun tarzımı bozduğuma

Okurken anlarsınız kendime kızdığıma

Ben de farkına vardım çoğunu üzdüğüme

Bakmayın yazdığıma benim yaptığım gaftır

Şair Mikdat Bal', 'Herkes derdini yazar! Herkes derdini yazar kimi söz kimi laftır Söz uzadıkça uzar yazılan fotoğraftır Her konuda yazılır sevgi ile düzülür A...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/herkes-derdini-yazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan Yağmuru', 'nisan-yagmuru-meltem-kaya-fm94p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçinde olmadığım bir kalabalığı süpürüyor gözlerim

Bir nisan yağmuru kadar acelem var gitmelere…

Eskinin yaprakları hızla dökülüyor

Ben dökülüyorum hızla bir buluttan…

Adım yağmur, çağır beni! 

Düşüyorum, tut beni…

Düşlüyorum, tut beni…

Sadece sen biliyorsun…

Senden gayrısı yalan biliyor…

Sana düştüm, tut beni!', 'İçinde olmadığım bir kalabalığı süpürüyor gözlerim Bir nisan yağmuru kadar acelem var gitmelere… Eskinin yaprakları hızla dökülüyor Ben dökü...', ARRAY['Türk Edebiyatı','Şiir','Meltem Kaya']::text[], 8.5, '{"poet":"Meltem Kaya","poet_slug":"meltem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nisan-yagmuru-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tavuk Mahmut''un Kızı', 'tavuk-mahmut-un-kizi-cem-hire-dxuax', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geldik bayram sabahı, yine mi kavga, 

kim mi toplayacak balkondaki 

asmadan sarmalık yaprakları? 

Dizlerinin üzerinde battaniyesi 

otururken televizyonunun karşısındaki

yaşlı iskemlesinde, Bu kılıç oğlum, bir metre

olursa boyu, ev sahibi olurmuş bakanı,

bu güller asıl Fransa’nın 

güneyinde yetişirmiş, bu da menekşe, 

aslı Afrika’daymış diye tanıştırıyor 

çiçeklerini birer birer benimle. 

Kalkıp pencereden İşte yine o iki baykuş, 

dedi, kahretsin gelmişler, 

deniz kabaracak belli ki yine, 

sersem Mahmut açılır denize belki de gene! 

Topal bir kızı vardı Mahmut’un, 

severdi menekşeleri, gözü gibi bakardı, 

balkondan düşürmüştü de birini 

ardından nasıl da ağlamıştı.

Kaç kere bıkmadan deneyip dikmişti 

menekşeyi ama tutmamıştı, 

Az mı konuştum ki acaba 

onunla diye söylenirdi.

Mahmut’u topuğundan vurdular sonra,

Kızı da kaçtı, eminim en çok 

balkondaki menekşeyi özledi 

bir türlü geri getiremediği.

Bense Tavuk Mahmut’un tuttuğu 

kupeslerin tadını, kızının 

iyi de yaprak sardığını, bir de, 

Yamanlar’ın eteklerinden süzülerek 

dönerken eve yediğim dayak sonucu 

yitirdikten sonra bisikletimi, 

vitrinlerdeki kontrpedal Fransızları 

nasıl da hevesle izlediğimi anımsadım 

şöyle bir düşünürken geçmişi.', 'Geldik bayram sabahı, yine mi kavga,  kim mi toplayacak balkondaki  asmadan sarmalık yaprakları?  Dizlerinin üzerinde battaniyesi  otururken...', ARRAY['Türk Edebiyatı','Şiir','Cem Hire']::text[], 8.5, '{"poet":"Cem Hire","poet_slug":"cem-hire","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/tavuk-mahmut-un-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Topaç', 'topac-cem-hire-ogcn5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalınayak gezinmeyi çok severdik de 

basamazdık yanan asfaltına, 

Ramazan, bre Ramazaan gel de yoğurdunu ye! 

sesiyle çınlayan her öğle vakti mahallenin, 

oyunumuzun bozulmasına bozulurduk. 

Vaktinden evvel yerdik kayısılardan, 

çağla derdik, ekşi ekşi, komşu ağaçlardan.

Ömer, acıkınca karnı, yemek için yine 

salçalı yarım ekmeği, Nana, Nanaaa! 

diye bağırırdı bizim arka bahçeden. 

Her öğle zamanı, Pomakça’yı biraz daha 

kıvırmak için yeni bir fırsat sunardı.

Kızlar topaç çeviremez, en beceriklisi 

alttan çekerdi ipi, bizse kaldırdık mı 

taa baş hizasından çakar asfalta 

döndürürdük bir saat aleti.

Sonra tüfek icat oldu misali, 

topacın da çıktı otomatiği. 

N ede olsa memur çocuğuydum, 

ilk alan ben oldum ondan, 

alamadı ne Ömer ne de Ramazan, 

bir daha da benimle oynamadılar.

Ne şimdi severim ne de o zaman 

sevdim böyle şeyleri ama, 

söyleyemedim bir türlü de babama. 

Neden sonra anlıyor insan ne çok şeyi 

yitirdiğini, - belki bir sevgi ilânının 

gecikmesi gibi – sevmediğini 

söyleyemediği zaman çok kez.', 'Yalınayak gezinmeyi çok severdik de  basamazdık yanan asfaltına,  Ramazan, bre Ramazaan gel de yoğurdunu ye!  sesiyle çınlayan her öğle vakt...', ARRAY['Türk Edebiyatı','Şiir','Cem Hire']::text[], 8.5, '{"poet":"Cem Hire","poet_slug":"cem-hire","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/topac-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıklar Korkar Oysa İnsandan', 'karanliklar-korkar-oysa-i-nsandan-cem-hire-98l9g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '“Gece terketmiyor adamı diye endişelenen Eluard, 

yahut, Neşeli ve pembe tek ışığın girmediği 

somurtkan ev sahibesi gece diyen Baudelaure, 

hiç düşündüler mi bilmem 

gecenin açığa çıkardığını tüm gizleri, 

işi bunu becermek olan bir dedektif gibi. 

Yattıkları yerden okusalar şimdi

- ama imkânı yok - Ahmet Haşim’i: 

Her şey var, her şey görünüyor, 

gözlerinde bir damla gece yok.”

dedikten sonra hatırladı birden kürsüde, 

karanlıkta attığını ağını ordudan re’sen emekli 

Tavuk Mahmut’la yan yana o vakit her gece

ve bir de şunu dediğini Mahmut’un, gün devrilip

o asgâri iki şişe Sevilen’den sonra devrildiğinde

o gece motorun kıçına, o tok sesiyle: 

Karanlıklar korkar insandan 

ve gece gelecek birazdan.', '“Gece terketmiyor adamı diye endişelenen Eluard,  yahut, Neşeli ve pembe tek ışığın girmediği  somurtkan ev sahibesi gece diyen Baudelaure, ...', ARRAY['Türk Edebiyatı','Şiir','Cem Hire']::text[], 8.5, '{"poet":"Cem Hire","poet_slug":"cem-hire","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/karanliklar-korkar-oysa-insandan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esas kıral. kıralcılar.', 'esas-kiral-kiralcilar-galip-kemali-gunay-yl0bh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''''Kıral ölebilir

Yaşasın kıral.

Giden ağam 

Gelen paşam''''

Ah şu kıralcılar...

Bir cepde cenaze 

Diğerinde düğün marşı...

Hem kıral ve hem de kullar 

Ne çekmişdir bunlardan..

Bir kız da yok haykıran

''''Kıral çıplak. çıplak kıral''''...

.....................................

.........................................

.........................................

''''Çöker kıraliyet sonra

Kullar ve kıral ne yapar

Yaşasın kıralcılar.''''

..............................

..............................

Kıral suçsuz

Kulları süt kaşık

Yalar kıralcılar', '''''Kıral ölebilir Yaşasın kıral. Giden ağam  Gelen paşam'''' Ah şu kıralcılar... Bir cepde cenaze  Diğerinde düğün marşı... Hem kıral ve hem de...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/esas-kiral-kiralcilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ardıç Gölgesi İlk Düş..', 'ardic-golgesi-i-lk-dus-nevin-kurular-glblv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hatırladığım; 

ilk düşüm,

çocukluğum 

bizim dediğim

O hep  uzak diyarlarda

yağız atların zorlandığı tırmanışla

eriştiğim dağda eşeli kaldı.

"Kaş" denilen o düz yüksek ovada

yalnız bir ardıç ağacı vardı.

altında iki iri taş.

Çocuktum,

ilk aşk masalı düşümü o yerde kurmuştum

iki taşı bir aşka mezar yaparken

kız ve oğlana

şimdi hatırlamadığım adlar koymuştum

bilmiyordum

"Aslı ile Kerem"i 

duymamıştım 

"Ferhat ile Şirin"i.

Aşk efsanesini

rüzgarın dallarını eğdiği

ardıç ağacının yapraklarından dinliyordum.

ve

o iki taş  hissettiriyordu 

bir şeyler anlatıyordu o ağaç.

duyulmalı,görülmeliydi  bir bakışta

koruyan saklayan

meydan okuyan tavrıyla

“Ben, bu  boşluğun 

ve aşkın gömülmez-inin tek bekçisiyim"  der  gibi 

bir ardıç ağacı.

O küçük parmaklarımla 

eşeliyordum toprağı

iki güzel yüz görmek için

ya da onlara

yükselen güneşi göstermek içindi belki

ulaşma çabam bilmiyorum.

Ardıç gölgesine uyumam için bırakılmıştım

oysa! 

ne çok uyanmışım o çocuk kalbimle hayata

sonrasında

zaman uykularına yatmışım.

ölü topraklı uyumalara.

Düş

    -müş 

         yaşam…

tutamadan aşkı

olan akşam.', 'Hatırladığım;  ilk düşüm, çocukluğum  bizim dediğim O hep  uzak diyarlarda yağız atların zorlandığı tırmanışla eriştiğim dağda eşeli kaldı. ...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kurular']::text[], 8.5, '{"poet":"Nevin Kurular","poet_slug":"nevin-kurular","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/ardic-golgesi-ilk-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceğin Söyleniyor Bu Şehirden II', 'gidecegin-soyleniyor-bu-sehirden-ii-okan-savci-9la8p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oysa 

Yetiyordu bir zaman

Onca kopuşa rağmen 

Bir sinemanın bilet kuyruğunda sana rastlamak..

Ya da

Birbirimizden habersiz gittiğimiz

O şairin imza gününde

Senin tesadüf dediğin gerçeğe teslim olmak..

Bunlar güzel şeylerdi 

Sen bu şehirde yaşarken..

Ve o an

Yüreğimde iflas ederdi ayrılık

Düşler sürümden kazanırken..

Yararı olmasa da bilmeni isterim

Bazı günler yokluğuna satıldı

Sinema salonunda oturduğun o koltuk

Ve bu duruma oldukça içerledi

Feneriyle ekmeğini kazanan çocuk...

Sonunu anlamadığım o filmi

Seninle izlemek isterdim yeniden 

(bilirsin kafam almıyor bilim-kurguyuyu) 

Ama gel gör 

Gideceğin söyleniyor bu şehirden...', 'Oysa  Yetiyordu bir zaman Onca kopuşa rağmen  Bir sinemanın bilet kuyruğunda sana rastlamak.. Ya da Birbirimizden habersiz gittiğimiz O şair...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gidecegin-soyleniyor-bu-sehirden-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasım Çığlığı', 'kasim-cigligi-meral-vurgun-8p9xj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'karanfiller kopardılar yüreğimden

yoldular birer birer

düşlerimden aldılar önce

kuru dalda sararan yaprak misali 

düştüler...tutamadım...

ey insanlar

uçurumları bilir misiniz 

uçurum içinde sarmaşıkları

omuz omuza sarılıp gelenleri bilir misiniz

iftarsız sahursuz oruç tuttunuz mu 

siz o Kasım çığlıklarını 

duydunuz mu? 

onlar

oradaydılar...

sizin baktığınız ve göremediğiniz

bildiğiniz ve bilmezlik edip geçtiğiniz

''aç kaldım, susuz kaldım

tütünsüz, uykusuz kaldım

terketmedi sevdan beni''

dediği yerdeydiler şairin

insan böyle mi yanar

saçları diri, elbiseleri yeni

böyle mi dökülür insan yanınca etleri

bir şeyler söyleyin, susmasın diliniz

sesiniz nerede? 

adları kayıp listelerindeydi 

bedenleri tutsaktı

dağlardaydı yürekleri

karanlıkları yırtan çığlıktı 

ses katmadığınız sesleri

çınlatmadı kulaklarınızı

Kasım vuruldu, Şubat yandı

siz üşümediniz  mi...

neredeydiniz, insanlar neredeydiniz? ...', 'karanfiller kopardılar yüreğimden yoldular birer birer düşlerimden aldılar önce kuru dalda sararan yaprak misali  düştüler...tutamadım... ey...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kasim-cigligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bildiğim Halinle Geldin', 'bildigim-halinle-geldin-nevin-kurular-1g6ny', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine yaptın yapacağını

deli deli geldin delirtmeler

bildiğim halinle geldin! 

sevdiğim halinle..

buğusuna karıştırdığın tütsüsüyle

başımı döndürdün

gurupları içirdin şarap diye...

sarhoş ettin.

mahmur  cümlelerle şimdi koşuşum yollarına

bu yüzden..

bakma dağılıp dağınık savrulmasına

sığmıyor ya içi içine sevincin

yalpa yalpa kanatların  çırpışına aldırma.

dolu dizgin deli hoyrat

yaşa.. 

yaşat! bizi.. biz  olmalarda

uzat elini! 

dinle kalbimi

ve sustur susturabilirsen 

o çıvgın sesini

inanmazsan  delecek dağları 

gelecek kulaklarına', 'Yine yaptın yapacağını deli deli geldin delirtmeler bildiğim halinle geldin!  sevdiğim halinle.. buğusuna karıştırdığın tütsüsüyle başımı dö...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kurular']::text[], 8.5, '{"poet":"Nevin Kurular","poet_slug":"nevin-kurular","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bildigim-halinle-geldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Inanirmisin', 'inanirmisin-husamettin-guven-jop0o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gozum actim seni gordum

Ben sevgiyi sende buldum

Tum kalbimle senin oldum

Sevdim seni inanirmisin

Dogru durust sozlerinle

O mukemmel gozlerinle

Temiz olan yureginle

Sevdim seni inanirmisin

Seviyorum o nazinla

Hayat veren bakisinla

Gulucukler sacisinla

Sevdim seni inanirmisin

Saclarini atisinla

Kalem kasi catisinla

Sevgi dolu bakisinla 

Sevdim seni inanirmisin

Hollanda', 'Gozum actim seni gordum Ben sevgiyi sende buldum Tum kalbimle senin oldum Sevdim seni inanirmisin Dogru durust sozlerinle O mukemmel gozleri...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/inanirmisin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ney di? Ne oldu...?', 'ney-di-ne-oldu-musfik-saltik-3wate', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ferhat’a Dağlar deldirdi

Kerem''e çöller gezdirdi

Efsanelere konu edilirdi

İlham kaynağıydı 

Şairlere bir zamanlar

Şiirlere konu oldu

Bestelendi yüzlercesi

Dillerde dolanan şarkı oldu

En kutsal duyguydu bir zamanlar

Her şey gibi o da yozlaştırıldı

Plastik gül, kırmızı yastık

Kalpli bardak, tabak

Satışına malzeme oldu.

Kızaran yüzle titreyen sesle

İlan edilirdi  bir zamanlar

Şimdilerde iki kontör değerinde

Kısa mesajlara  malzeme oldu

Yetmedi o kutsal duyguya 

Bunca yapılan zulüm

Sonunda fuhuş un  adı da

AŞK YAPMAK oldu.

                     1 Nisan 2005', 'Ferhat’a Dağlar deldirdi Kerem''e çöller gezdirdi Efsanelere konu edilirdi İlham kaynağıydı  Şairlere bir zamanlar Şiirlere konu oldu Bestele...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ney-di-ne-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaktin beni biliyormusun', 'yaktin-beni-biliyormusun-husamettin-guven-enkcj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sacma sapan inadinla

Asik olan suratinla

Manalica bakisinla

Yaktin beni biliyormusun

Aslinda ben kahir cekmem

Korkma canim ben vazgecmem

Bas koymusum geri donmem

Yaktin beni biliyormusun

Zehir dolu sozlerinle

Kahir dolu gozlerinle

Kirgin olan yureginle

Yaktin beni biliyormusun

Hollanda', 'Sacma sapan inadinla Asik olan suratinla Manalica bakisinla Yaktin beni biliyormusun Aslinda ben kahir cekmem Korkma canim ben vazgecmem Bas...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yaktin-beni-biliyormusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halsiz Gece', 'halsiz-gece-utku-demir-6kwsz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece kaplıyor

Son gözyaşları dökülürken

Elem dolu bulutların

İğneler batmış

Can haliyle

Haykırış beklenirken

Yeri göğü inletecek

Sıkmakta gece kendini

Boşaltsa da bir kısmını

Yoğunluğu çekmekte arta kalanları

Söndürüyor tüm ışıkları

Sokmuyor alanına yolcuları

Kapatırken bütün girişleri

Düşünemiyor sanki bu sefer kendini sevenleri

Nerde senin dostluğun

Bırak girelim mekansızlığına

Geçmişe yolculuk edip

Dolaşalım şahit olduğun anlarımızda

Zor nefes alsakta 

Senin etkinliğinde

Sessizliğin en güzel yanın

Beyaz çizgilere açıksın 

Kapkara görünsen de

Farklı duygular yaratırsın

Hem de her seferinde

Anlıyorum seni de

Ey halsiz gece

Söyle nereden kaçıp geliyorsun

Dertlerin sırtında yüklü

Anlatmak bile istemiyorsun

Kendi halinde dalıp gidiyorsun

Yoruldun belli ki benim gibi

Taşıyamaz oldun artık bir yenisini', 'Gece kaplıyor Son gözyaşları dökülürken Elem dolu bulutların İğneler batmış Can haliyle Haykırış beklenirken Yeri göğü inletecek Sıkmakta ge...', ARRAY['Türk Edebiyatı','Şiir','Utku Demir']::text[], 8.5, '{"poet":"Utku Demir","poet_slug":"utku-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/halsiz-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek Varken...', 'seni-sevmek-varken-leyla-isik-ajnnd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana hasretim

                                         Vaz geçemiyorum senden

                                        Sensin her an düşündüğüm

                                        Süzülen yaşsın gözlerimden

                                            Öyle özlüyorumki seni

                                             Özlemin içimi yakıyor

                                           Gizleyemiyorum sevgini

                                           Sevgin beni bırakmıyor

                                      Tutup geri getirmek istiyorum

                                           Geçen o güzel günleri…..

                                       Seninle paylaşmak yeniden

                                                    Ve her şeye

                                     Yeniden başlamak istiyorum.

                                              Seni özlüyorum

                                       Vaz geçemiyorum senden

                                  Seninle dolu düşler kuruyorum

                              Tüm güzellikleri içiyorum ellerinden

                                              Sen bilmiyorken

                                               Senden uzakta

                                        Hep seni düşünüyorum

                            Bölüp parçalara ayırıyorum sensizliği

                               Sensizlik büyüyor içimde her gece

                                     Gömüp başımı yastıklara

                                     Göz yaşlarımla ıslatıyorum.

                           Dudaklarım öğrendi yaşlarımın tuzunu

                                    Hiç bir şey gidermiyor inan

                                          Sensiz susuzluğumu

                                             Seni özlüyorum.

                                     Çıkış yolu yok bu sevginin

                                    Çıkmazlarda kayboluyorum

                                          Yıkılıyor umutlarım

                                        Yalanlarda yaşıyorum

                                          Seni sevmek varken…

                                          Senin olmak varken…

                                             Senden uzakta,

                                         Sensizlikte ölüyorum.', 'Sana hasretim                                          Vaz geçemiyorum senden                                         Sensin her an düşündüğ...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/seni-sevmek-varken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başıma Bela Açtı', 'basima-bela-acti-veli-dalbudak-kflj1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her adımda bin kez kayar ayağım

Resminden başka kalmadı dayanağım

Gidin dostlar, yalnız kalıp ağlayacağım

O, başıma bela açtı gitti benim.

Kurudu dudağım, görmüyor gözüm

Çıldırdı gönlüm, geçmiyor sözüm

Sille yedi ömrüm,gülmüyor yüzüm

O, başıma bela açtı gitti benim

Teselli buluyor bende bince çileler

Rüyama giriyor istemediğim geceler

Gülüyor ardımdan, dostunum diyenler

O, başıma bela açtı gitti benim

Kırıyorum sevenleri sebepsiz yere

Koşuyorum, gittigimi bilmeden nere

Nasıl umutla bakayam, gelecek günlere

O, başıma bela açtı gitti benim.

(Stockholm 1995)', 'Her adımda bin kez kayar ayağım Resminden başka kalmadı dayanağım Gidin dostlar, yalnız kalıp ağlayacağım O, başıma bela açtı gitti benim. K...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/basima-bela-acti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'a-Nisan bir', 'a-nisan-bir-mikdat-bal-vac87', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nisanın birinde bazı gafiller! 

Yalan konuşmayı serbest sanıyor

Taklitçi maymunlar berbat sefiller! 

Konumundan daha dibe iniyor! 

Mümine yasaktır her türlü yalan 

Bunu kabul eder Müslüman olan 

Ancak bu olayı hafife alan! 

Anlamadan başka dine dönüyor! 

Nisan bir şakası neyin nesidir? 

Ahlakın çöküşü, değişmesidir 

Bu ancak iblisin bir fitnesidir 

Ona uyan cehennemde yanıyor

Aman uymayalım el kültürüne 

Herkes sahip çıksın kendi türüne 

Taklit etmeyelim körü körüne 

İnanan her zaman Hakkı anıyor! 

Sözcükler sermayem Türkçe pazarım

Şahsiyetsiz insanlara kızarım

Her konuyu ele alıp yazarım

Mikdadi’yi artık herkes tanıyor! 

Ozan Mikdadi', 'Nisanın birinde bazı gafiller!  Yalan konuşmayı serbest sanıyor Taklitçi maymunlar berbat sefiller!  Konumundan daha dibe iniyor!  Mümine ya...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/a-nisan-bir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına ve düş', 'firtina-ve-dus-esat-korkmaz-5gzqf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne ağır bir fırtına.

 Bulutlar kaynıyor

 Kiremit kırmızısı bulutlar 

 gökte Patlayan şimşekler

 İçini tırmalayan gürültüler

 Bir gürültü ki

 Sigaram düştü ürpertisinde

 Ne vurdum duymaz dumanı var

 Aldırmadan yükselir usulca

 Yükseğe, daha yükseğe..daha

 Seyre çıkan ruhu var sanki

 Doğa nasıl dayanır bu şiddete 

 nasıl başa çıkar

 Yağmur başlayana dek olanlarla. 

 Neyse ki düş 

 Ne garip bir düş.

 Ruhum yükseliyor.

 Bedenim eriyor,

 Kalabalıklar içinde 

 Olanı da seviyorum yalnız

 Bir düş arıyorum düş içinde

 İnanılmaz bir umut sarıyor içimi

 Öyle kısa, 

 Öyle anlık ve öyle muhteşem ki.

 Bir yalnızlık, bir kalabalık.

 Kalabalıklar içinde sen 

 Sağa sola bakınarak bulamamak seni

 Ve dokunamamak

 Ah! Bu acı işte,

 Düş işte

 Varsın düş olsun 

 Düşün içinde olabileceğin gerçeği 

 Ve kaç zaman geçecek kimbilir

 Çıkabilecek,yada çıkamayacaksın

 Kimbilir belki de istemeyeceksin

 Ve Şimdi oradasın,

Tam ortasında bir rüyanın,

Ve dimdiksin, gururla … 

Bin çiçekten Kır kokusu,

Atlas bir sabahta,

Yüzünü okşayan ılık bir rüzgar 

Düş’ün elleri ellerimde

Ve En net sensin son karede

Tatlı bir tebessüm var yüzünde

Gözlerin ışıl ışıl

Yüreğin ne deli çarpıyor

Aynı benim yüreğim', 'Ne ağır bir fırtına.  Bulutlar kaynıyor  Kiremit kırmızısı bulutlar   gökte Patlayan şimşekler  İçini tırmalayan gürültüler  Bir gürültü ki ...', ARRAY['Türk Edebiyatı','Şiir','Esat Korkmaz']::text[], 8.5, '{"poet":"Esat Korkmaz","poet_slug":"esat-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/firtina-ve-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-aladdin-kilic-ksrj6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasret yazdım kitabımın adını

Yaşadım hayatı ama alamadım tadını

Severse insan eğer almazsa muradını

“HASRET” katar böylece kitabının adını.

Hasret sözleri ile doldurur sayfaları

Gönlünde çalkalanır hasretin dalgaları

Çok uzakta görünür mutluluk adaları

Hasretle yüklü gelir bülbülün nidaları.

Gökyüzünde süzülen hür kuşlar uçuşuyor

Benim ise gözlerim acı dolu bakıyor

Acı çeken gönlümde yüreğim kan ağlıyor

Neşe ve sevincimi acı hasret alıyor.

Kavuşmak, mutlu olmak hasrete döndü birden

Sabredip beklediysem başka ne gelir elden

Çektiğim bu hasretim düşmez oldu dillerden

Güle küsmüş misali ses çıkmaz bülbüllerden.

Aladdin derdin bile susturdu bülbülleri

Gözünden akan yaşlar solduruyor gülleri

Hasrete, hasret katan sayısızca günleri

Kitabında yeşerdi hasretin sümbülleri.', 'Hasret yazdım kitabımın adını Yaşadım hayatı ama alamadım tadını Severse insan eğer almazsa muradını “HASRET” katar böylece kitabının adını....', ARRAY['Türk Edebiyatı','Şiir','Aladdin Kılıç']::text[], 8.5, '{"poet":"Aladdin Kılıç","poet_slug":"aladdin-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasret-234-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarim', 'yarim-orhan-tuncay-8hazd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Girdim gönül bahçesine

Sevdam yazdım güncesine

Düştüm aşkın pençesine

Yarim beni anlar mı hiç? 

Çiçeklerin deremedim

Yazdığımı veremedim

Girdabında yunamadım

Yarim bensiz eyler mi hiç? 

Bahçesinde viran kaldım

Güncesinde geçmez aşkım

Bundan kelli benim adım

Yarim bir gün sorar mı hiç?', 'Girdim gönül bahçesine Sevdam yazdım güncesine Düştüm aşkın pençesine Yarim beni anlar mı hiç?  Çiçeklerin deremedim Yazdığımı veremedim Gir...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yarim-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk elde değil', 'ask-elde-degil-aladdin-kilic-ludrp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir Pazar akşamı çıktı karşıma

Aşktan korkar iken geldi başıma

Ne kadar kaçmak istedim çaba boşuna

Aşk elde değil gönülde imiş.

						

        Unutmak istedim fakat unutamadım

Kalbimden atmak istedim hiç atamadım

Bir gün dahi düşünmeden ben yatamadım

Aşk elde değil gönülde imiş.

						

Sabah kalktığımda sanki karşımda 

Gezdiğim yerlerde yanı başımda

Böyle bir şey görmedim bunca yaşımda 

Aşk elde değil gönülde imiş.

						Hayali gözümden artık gitmiyor

						Her an gelir diye onu bekliyor

						Bir defa görmek elbet yetmiyor

						Aşk elde değil gönülde imiş.

						

Sevda şerbetini içenler bilir

Kalbine ayrı bir ferahlık verir

Tadını bilmeyene pek acı gelir

Aşk elde değil gönülde imiş.

					         Sorana Aladdin aşkı söylesin

						Yanındakiler onu iyi dinlesin

						Sevecekse insan gönülden sevsin

						Aşk elde değil gönülde imiş.', 'Bir Pazar akşamı çıktı karşıma Aşktan korkar iken geldi başıma Ne kadar kaçmak istedim çaba boşuna Aşk elde değil gönülde imiş. 						      ...', ARRAY['Türk Edebiyatı','Şiir','Aladdin Kılıç']::text[], 8.5, '{"poet":"Aladdin Kılıç","poet_slug":"aladdin-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ask-elde-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğumgünü', 'dogumgunu-ahmet-ferit-cosan-abapx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiçliğin odağında,

Beklemekteyim

Gözlediğim gözlerimi oyacak

Yirmidört kuzgunun

Telaşsız teşrifini

Bana kan işeten sözlerini,

Bu uzun gecemde

Sırf sarılabilmek için,

Peluş bir bebeğin 

İçini

Doldurmada sarfettim

Anne! 

Ey en nefret ettiğim,

Hep sayendedir ki

Zehrin fena urdur gönlümde,

Çileler paratoneriyim.

Civara çakan belalar

Hep benden toprağa akmaktalar

Toplanıp,

Topuklarım patlatan

Olanca kudretiyle.

Çizgi-----

-----	Çizgi

Aştım çizgileri sülalen aşkına,

Duy beni! 

Haykırdım yekün kinimi.

Nicedir 

Senden gelen soyu reddetmişim.

Kaç dizelerimden,

Dizelerim

Felç yağdırır üstüne.', 'Hiçliğin odağında, Beklemekteyim Gözlediğim gözlerimi oyacak Yirmidört kuzgunun Telaşsız teşrifini Bana kan işeten sözlerini, Bu uzun gecemd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/dogumgunu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyülü Sözler', 'buyulu-sozler-sahin-erturk-05q8q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin herşeyin

Benim

Aklıma,hayalime gelmeyen

Herşeyin ama herşeyin var...

Söylermisin İstanbul sevdalısı

Benim sana verebileceğim

Beş para etmeyen

Şiirlerim

BÜYÜLÜ SÖZLERİM

Sıcak sevgimden başka

Neyim var ki? 

Neyim var ki? 

(01.04.2005)', 'Senin herşeyin Benim Aklıma,hayalime gelmeyen Herşeyin ama herşeyin var... Söylermisin İstanbul sevdalısı Benim sana verebileceğim Beş para ...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/buyulu-sozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kekova anıları...', 'kekova-anilari-sair-gulsun1-e7799', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'insanlar takmış bu adı ona, 

esas adı ramazanmış 

nice sonra öğrendik... 

kekovanın eşsiz güzelliklerinde, 

koy,koy gezinti 

deniz ve güneş 

ve rambonun taze balık kokusu... 

gece.... 

dümdüz bir deniz, 

gökyüzünde dolunay. 

denizle sanki dans ediyor... 

uzanmışız teknede, 

gündüzden gelen rehavetle 

gözler kapanmak istemiyor 

eşsiz güzelliklere 

dalıp gitmek istiyor... 

gecenin sarhoşluğu, 

bizide içine almış. 

hafif bir müzikle 

uykuya dalıyor... 

eylül-2004 kekova(üçağız)', 'insanlar takmış bu adı ona,  esas adı ramazanmış  nice sonra öğrendik...  kekovanın eşsiz güzelliklerinde,  koy,koy gezinti  deniz ve güneş ...', ARRAY['Türk Edebiyatı','Şiir','Şair Gülsün1']::text[], 8.5, '{"poet":"Şair Gülsün1","poet_slug":"sair-gulsun1","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kekova-anilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nisan', 'bir-nisan-sahin-erturk-cvfuo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeni aşk lara yelken açtım

Her limana uğruyor gönlüm

Şıpsevdi biri olup çıktım

Şaka yaptım,kandırdım seni

Bugün seni düşünmüyorum

Özgürlüğümü kutluyorum

Nasıl kızdın,nasıl inandın

Şaka yaptım,bugün bir nisan

Sensiz harabe oldu gönlüm

Ağlamakla geçiyor ömrüm

Aşk tan yana hep sana yönüm

Şaka değil,doğru son sözüm

Şaka yaptım,kandırdım seni

Belki biraz,kızdırdım seni

Şaka yaptım,bugün bir nisan

Şaka yaptım,bugün bir nisan

(01.04.2005-Yeni)', 'Yeni aşk lara yelken açtım Her limana uğruyor gönlüm Şıpsevdi biri olup çıktım Şaka yaptım,kandırdım seni Bugün seni düşünmüyorum Özgürlüğüm...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-nisan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayacağım-"siz hiç ay aşığında ağladınız mı" Kitabından', 'aglayacagim-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-ggroq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'müjde mi aldım

gelişini mi gördüm kokusunu mu aldım

niye ağlamayayım ki niye

buyurmadı mı “çok ağlayın az gülün”

cemiyet hissiz edep terki diyâr

evlat ecdat tanımaz

sokak kıpkızıl ve duyarsız

emâre yok tefekkürden

çılgınlık azgın devrini yaşıyor 

tüm kavimlerin

bana ağlama demeyin

niye ağlamayayım ki

niye

bu gün kandil kutlu gün

nesepsizlere sözüm yok

ya diğerleri nasıl anlatayım bir geceliğine

gam yok iffet yok sanki yoktur hakikat

amin deyin çığlığıma affeder belki

bu gecenin aşkına imanım tamdır

amel sakat olsa da

diz çökmüş yıldızlar sus pus iblis

ağlayacağım ruhum titreyene dilim kalbe

ruhum dostun cemalini görene kadar

gül mü açtı bülbül mü öttü yanan yüreğime

ağlamadı mı hem adalet abidesi

ya ali

niye ağlamayayım ki niye

takva gemisine mi bindim

müjde mi aldım

Istırap derin sanki tufanı nuh’un

haykıracağım hasanlara alilere

ayşelere

ç/ağlasın gözyaşınız ç/ağlasın

ç/ağlasın ki teşrif eder belki yetimlerin babası

şefaat ede şefaat abidesi

şefaate layık olamasak da', 'müjde mi aldım gelişini mi gördüm kokusunu mu aldım niye ağlamayayım ki niye buyurmadı mı “çok ağlayın az gülün” cemiyet hissiz edep terki d...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/aglama-demeyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Bir Kız Çocuğu Gördüm...', 'kucuk-bir-kiz-cocugu-gordum-levent-sen-s4p2v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün küçük bir kız çocuğu gördüm rüyamda

Tatlımı tatlı şirin mi şirin yalanlarla büyüyordu bu güzel dünyada

Elinde küçük bir oyuncak büyüyünce yalanlarının esiri olacağını nerden Bilebilirdi

Ve o yalanların onu büyüteceğini ve başka aşklarda  küçülteceğini

Küçüktü kız çocuğu küçüklüğüne baktıkça büyüdü

Yalanlara alıştıkça küçüldü

Daha çok küçüktü kız çocuğu yaşadıkça yalanları gördü kızdı

Sonra kendide yalan söylemeye başladı

Ve büyüdü..

Daha çok ama çok küçüktü kız çocuğu

Yüzünde meleklerin masumiyeti ve elinde ufak bir sevda

Büyüttükçe büyüttü sevdasını

Yalanlarla büyüdü..

Küçüktü kız çocuğu ama kalbi dağlar kadar büyüdü

Ürktü küçük kız çok korktu ve kaçtı gerçeklerinden

Ve yeni bir aşkta büyüdü yalanlarınıda büyüttü..

Sonra kendide büyüdü ve daha çok sevdi, başkalarınıda sevdi

Kendini sevemedi..

Küçük kız büyüdü yalanlarıda sevdi..

Küçüktü bir rüya gördü,rüyasında birini çok sevdi

Sonra küçüldü sevdasını büyüttü kendini  sevdi...

Uyandı uykudan

Hala çok küçüktü hala çok masum

Kendini büyüttü, çocukluğunu büyüttü

Ama o hala masumdu.

Yanlışlarıyla hayata alıştı

Sevmeyi öğrenirken kendine küstü

Çok  küçüktü sevdikçe büyüdü..

Ve rüya bitti...

Uyandığımda

Küçük kız çocuğu yalanlarıyla çoktan gitmişti....', 'Bugün küçük bir kız çocuğu gördüm rüyamda Tatlımı tatlı şirin mi şirin yalanlarla büyüyordu bu güzel dünyada Elinde küçük bir oyuncak büyüyü...', ARRAY['Türk Edebiyatı','Şiir','Levent Şen']::text[], 8.5, '{"poet":"Levent Şen","poet_slug":"levent-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kucuk-bir-kiz-cocugu-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nisan Şiiri', 'bir-nisan-siiri-oguzkan-bolukbasi-fs088', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana sormadan sevda giyindim

Pek yakıştı üzerime

Sevindim

Fotoğrafların

Gülümseyen karelerindeyim şimdi

Yanağıma dudak izini bırakan bir öpücük kondurursan

Her şey tamam olacak gibi

Bütün başlangıçlar güzel oluyor

Bütün sevdalar güzel başlıyor

Çok bahar mı saydık ömrümüzde 

Daha çok bahar yaşasaydık doyar mıydık? 

Sanmıyorum 

Veya daha çok sevda

Her bahar bir yangın mesela

Her bahar bir gelincik ömründe içim kavrulsa

Rüzgârda savrulsa tohumlarım

Oraya buraya dağılsa

Binlerce aşka kucak açmak ayıp olmasa

Veya

Bir tek sen olmayı denesen sevdaların tümünde

Özlediğim bütün aşkların şekline girebilsen

Yalnızca seni özlesem

Bilsem ki

Her aradığım sendedir

Her aradığın bendedir

Baharı beklemezdim ben', 'Sana sormadan sevda giyindim Pek yakıştı üzerime Sevindim Fotoğrafların Gülümseyen karelerindeyim şimdi Yanağıma dudak izini bırakan bir öpü...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-nisan-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana İhtiyacım Var Annem', 'sana-i-htiyacim-var-annem-doner-ozeke-gjdo1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Daha büyümedim bebeğim annem 

Mamamı sütümü versene bana 

Üşüyorum sensiz her gece annem 

Beni de kollarına alıversene 

Ne olur hadi gel bana gelsene 

Hasretim cok büyük bunu bilsene 

Sensiz ağlıyorum yüreğim yanık 

Hadi rüyalarıma geliversene 

Rüyamda seninle olayım diye 

Hala yatıyorum bunu bilsene 

Ne olur hasretin düşmeden dile 

Gözlerime bakıp gülüversene 

Ne kadar büyüsem inan  bebeğim 

İnan annem her gün seni isterim 

Günler geçtikçe yollarını gözlerim 

Sana ihtiyacım var inan annem 

Ne kadar büyüdüm hala bebegim 

İnan senin hasretine gebeyim 

Kır zinciri gel annem bened güleyim 

Sana ihtiyacım var inan annem 

            DÖNER ÖZEKE

                 01.04.2005', 'Daha büyümedim bebeğim annem  Mamamı sütümü versene bana  Üşüyorum sensiz her gece annem  Beni de kollarına alıversene  Ne olur hadi gel ban...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sana-ihtiyacim-var-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beter Almanya', 'beter-almanya-doner-ozeke-6zomq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir Almanya türküsü düşmez dilimden 

Çok uzak bir diyar ne gelir elden 

Ne ruhumda ne beynimde nede gönlümden 

İstemedim yad ellere gidesin 

Kavalı bırakıp sen köyden indin 

La havle şaşırdın sen birden bire 

Sen esmer yarinden sarı dilbere

İstemedim yad ellere gidesin 

Beş bebekle yar bırakıp gidersin 

Yıllardır beklerim seni bilesin 

Belim bükülmeden hemen gelesin

İstemedim yad ellere gidesin 

Geçiçidir diye kıydın nikahı

Bizleri bitirdin yeter gel gayri 

Almanyanın kime olduki hayrı 

İstemedim yad ellere gidesin 

          DÖNER  ÖZEKE

             01.04.2005', 'Bir Almanya türküsü düşmez dilimden  Çok uzak bir diyar ne gelir elden  Ne ruhumda ne beynimde nede gönlümden  İstemedim yad ellere gidesin ...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beter-almanya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felluce', 'felluce-palo-keko-dywcx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gökyüzü harabeye döndü,

kan tokmakları yıkıyor

beynimin çalılıklarını.

bedenini namlunun ağzına

sermişler felluce.

kan çanağına döndü

yüreklerimiz, kuş sürüleri

yok artık semalarında,

uçağın kanadına

takıldı uçurtmaların,

tankların anırması yıkıyor

duvarlarını kulaklarımın.

ebu greyb zindanının soğuk duvarları

(d) üşüyor içime kırıntılarıyla,

kerbela da yıkılan göklerden sonra

ölülere pasaport vermiyorlar felluce.

kurumadan zeyneb'' in gözleri dicle de,

halen hz. hüseyin''in yaraları

kanarken fırat’ın gözlerinde,

kalbimdeki son kara parçası da 

sular altında kaldı acından felluce.

İşkence tezgahlarına yatırmışlar coğrafyanı,

utanır oldu toprak suratsız yüzler taşımaktan,

gök aşağılıklara yorgan olmaktan utandı da,

utanmadı insan olmakla övünen tekerlemeler. 

cehenneme sıfır acılarımız oldukça

yüreklerimiz  yeşerecek yumruklarımızda,

gün gelir duvağını da açınca tetiğin

bir çift gözün olacak özgürlük,

bahçende bir ağacın da direniş.

kapattılar sevdamızı şehvet tenekelerinin

bulanık kapaklarında,

kıymeti yok artık hayatın cebinden yemenin,

kavganın pasını sileceğiz hasta yüreklerden.

sesin gelmiyor ey kardeş,

ebu greyb zindanın duvarları titriyor,

kaburgalarının çatısında kan sızıyor,

dağlanan yürekler var giyotin saatinde,

feryad eden zeynebler oldukça 

hüseyn in bakışlarında

acılarımıza pasaport vermeyecekler felluce.

ketum bir yalnızlıkla büyüyorsun içimde,

unutmak yok yapılanları,

yetmez ardından ağlamak

hüzünlü bir bulut gibi,

bekle felluce ölmeye geleceğiz kavganda,

varsın mezarımızda olmasın

rujlu dudaklar lanet okusunlar ardımızdan,

dağlarımızda keklikler öttükçe

sevdamıza pasaport vermeyecekler felluce.

gökyüzünün yerdeki istasyonusun,

özgür olmak isteyen 

bekler durağında binmek için 

onur treninin son kompartımanına.

kavrulmuş buğday başağından yüzün

hırpalanmış dikenleri arasında rüzgarların,

gecenin kuşağında sıkışınca düşlerin

rüyaların bulanıklaşmaya başlar

çocuklarının göz kapakları arkasında.

dicle yastığın olmuş, fırat yorganın

biliyorum üşüyorsun,

kadavraların çatısı kurulmuş göğsünde,

ölüm pistine dönmüş her karış toprağın,

kapatma gözlerini, bir kadının baharı 

postalanırken ateş vadilerine,

yaşam prangalara vuruldu yüreğimizde,

başımız dik dolaştıkça savaş meydanlarında

göz yaşlarımıza pasaport vermeyecekler felluce.

yas tutmak yok

kanmak yok barış yalanlarına,

alınana dek intikamın 

kanında petrol kuyusu açandan

korkmak yok artık

cehennemin artıklarıyla 

besleneceğiz gerekirse.

özgürlük ölümün kapısını kırmaktır 

kilidi bozulmuşsa gecede uykuların,

ant olsun günün sahibine

boyun eğmek yok sana vurana,

her gözyaşında bir mezar kazıdık

zebun kuşlarının muşambadan beyinlerine.

kavruk buğday tenli gövdelerimizde 

boyunları çözülmüş rüzgar takımı,

deniz sahillerimizde yüzünü yitirince,

hiçbir kamyon taşıyamaz senin yüreğini.

güneşle doldurmuşsun ceplerini yüzünün

çocuk gülüşleriyle şarkın bestelendikçe,

düşlerimize pasaport vermeyecekler felluce.

biz bu dünyanın mültecisiyiz

hiroşima’ nın acılarına benzer acılarımız

vietnam’ın çocuklarıyla aynı gökte

uçurtmalarını uçurdu çocuklarımız,

temiz kaldıkça yüreklerimizin tek bir sayfası

adımıza pasaport vermeyecekler felluce_palo', 'gökyüzü harabeye döndü, kan tokmakları yıkıyor beynimin çalılıklarını. bedenini namlunun ağzına sermişler felluce. kan çanağına döndü yürekl...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/felluce-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşma 1', 'kosma-1-i-brahim-kilinc-1a2m7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sıkıntı, derdimi ondan gizleyip

Cânâna sevgimi vermeye geldim

Derdi, kaseveti, kalbe kitleyip

İyiyi, güzeli görmeye geldim

İçimde kopuyor ne fırtınalar

Gittikçe uzuyor, bitmiyor yollar

Sensiz çekilmiyor şu uzun yıllar

Böyle mi geçecek, sormaya geldim

Ruhumu kapladı kara bulutlar

Rüzgâr her parçamı bir yana atar

Çiçek, yağmur, bulut yasımı tutar

Güneş doğacak mı,  sormaya geldim

Ben nasıl seveyim söyle geceyi

Anlatacak iken sana her şeyi

Karanlık boğuyor dilde heceyi

Sabah olacak mı, sormaya geldim

Bazen kahrolurum dosta darılıp

Çok hata işledim bazen yanılıp

Bütün günahlardan artık arınıp

Kalbinde yer var mı, sormaya geldim

Söyle İbrahim''e derdini söyle

Boynu bükük, mahzun, gel durma öyle

Ok atıp Eros''un gerdiği yayla

Aşk ile kalbini vurmaya geldim', 'Sıkıntı, derdimi ondan gizleyip Cânâna sevgimi vermeye geldim Derdi, kaseveti, kalbe kitleyip İyiyi, güzeli görmeye geldim İçimde kopuyor ne...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kosma-1-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azrail''in Şarkısı:Ölüm', 'azrail-in-sarkisi-olum-palo-keko-zx277', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Azrail gelecek 

dökülecek güneşin pulları

yapraklar solacak ağaçların sonbaharın koynunda

yıldızlar kayacak uykumdan.

Azrail gelecek

götürecek iki çift karalastik ayakkabımı

giydirmek için cehennemin sakinlerine. 

bedenimde ki ışığı söndürüp

rütbelilerin yanına götürecek düşlerimi.



Azrail gelecek

çığlıklarım beynimde tavan yapacak

korkudan bedenimdeki kıllar dökülecek

dökülecek yüzümün sıvası

gecenin gömleği eskiyecek üzerimde.

anlamayacaksınız ne olduğunu

ta ki size de gelene kadar

en mutlu gününüzde sizin kapınızı da çalacak 

musluklarınızın korkudan gözyaşları kesilecek

güneşin kepenkleri üzerinize kapanacak.

ben cehennemin derinliğinde kahkahayla

size güleceğim,

imreneceksiniz bana korkunun çocukları

yalancı mutlulukların paravana şirketleri.

Azrail gelecek

tüm ateş kazanları üzerinize dökülecek

gölgeniz bedeninizi terk edecek,

gözlerinizin elektriği sönecek

sevgiliniz yerine

yılan çıyan koynunuza girecek.



Azrail gelecek

toplayacak mavi denizlerden  gözlerimi

çocukluğumdan karşıya geçeceğim.

meşe ağaçlarından silecek evimi

gözyaşı tokmaklarından penceremin camları  dökülecek

kapkaranlık bir dünya demleyecek 

üzerime giydiğim fecre.

Azrail gelecek

ve yeşil gözlerimin dümenine geçecek.



Azrail gelecek

kuşları kökleriyle yüzümden silecek

urania yüzün içimde harabeye dönecek

ay güneş acılarımın kundağında kalacak

Azrail gelecek 

Işıkları kapatacak

Ve bir daha gelmeyecek_palo', 'Azrail gelecek  dökülecek güneşin pulları yapraklar solacak ağaçların sonbaharın koynunda yıldızlar kayacak uykumdan. Azrail gelecek götürec...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/azrail-in-sarkisi-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Sökükleri', 'kus-sokukleri-palo-keko-foxz4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'başı vurulmuş yağmur damlaları

ayaklar altında gömüldüler toz zerrelerine

gölgelerin bedeninde uçurtma kuraklığı

kuş söküklerinden yırtılıyor ruhum.

taşıyor cehennemde budanmış gözyaşları

yıldız kümelerinden sağılmış gözlerin

solgun gece banyosunda ağlar rüyalarım.

Çocukluğumdan karşıya geçtim o yaşlarda.

kundağında büyütmek acıyı çıldırıcasına

bedenim namluların rayı olur.

çamurun taş bebekleri yalan fotokopi nüshaları,

matbaasız sokakların lambaları,

kör kuyu salıncakları,

mutlu olduğumu sanırsınız ağladıkça kahkahalardan.

cezaevi duvarları (d) üşer yastığımın desenlerine 

voltalardan şişer cüzdanı zamanın

işlemediğim suçların tebligatıyla dolu kalbim

kim diker kuş söküğünden baharı bir daha içime,

kökleriyle kurumuş şafağı kim sular alnımda.

umutlarımla gerdeğe girdi kamburu  bulutların.

gözyaşlarına parsellenmiş başka gök yok,

taze kurşun servisi yapın beynime,

avingolu kadınlardan öğrenmedim  ağlamayı,

ceviz yaprağı uykulardan kalktım

yıkıktı tüm odaları hayatın,

bana kapı önü kaldı,yıkılmış uçurtma kıyısı,

demirin kaburgalarını kullandım yıllarca

işkencedir her gece gaz lambası altında

yıldızların kaymasını görmek yüreklerden. 

ranzamın baharlığından koparılmış,

tavanı çökmüş acıdan başka yok kimliğim.

yersiz yurtsuz rüzgarların misafirliğinde kaldım

demlenmiş kahır buhranlarından

dağlarım hala dik kafa tutarım varolmak için,

çıkmak için prangalanmış zamanın yorganlarından.

taş blokları altında kaldı gözlerim mendilinin

varıp katranın köşelerinden kaldırdım.

bir ruh kazasıdır aşk, paramparça bir gözyaşı sepetinde

sürüyle van gogh un acı çeken renkleri

fıratın mahzun bakışlarında kaybolur köpüren dalgalar

kilitsiz kızlar düşünmedim, 

Sağnak yağmurdan da değildi duygularım,

Islanmadım bu kadar

ölüm pasaportuyla nişanlandı bir parçası

odun topluyor oysa ki şehvet beden treninde

soğan saatini takmış koluna 

bir çift mavi denizimi

kızıl bir gök akrebi soktu, 

kulaksız kar haritasını

boğar gülümsemen…_palo', 'başı vurulmuş yağmur damlaları ayaklar altında gömüldüler toz zerrelerine gölgelerin bedeninde uçurtma kuraklığı kuş söküklerinden yırtılıyo...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/kus-sokukleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fahişe Gömülü sözcükler', 'fahise-gomulu-sozcukler-palo-keko-69rcj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'fahişe gömülü sözcüklerin 

çıplak bedenli istasyonlarında

mahrem yerlerini örtüler 

şeytanın karanlık dudaklarıyla.

Yüzleri seslere karıştırılmış diller

kağıtların inlemelerinden 

uykuları rötar yapıyordu.

Demir kaşlı rüzgarlar kapılarını kilitlediler

denizin mavi çatılı uykularına 

sözcükler ithal ediyor gözyaşları bulutlardan 

yüzüm yedinci yaşımın ıstıraplarında

kaldı umutsuz ve çağalasız.

Şeytanın kötülük tenekeleri

yüzümün ovasında kasırgalar estiriyor

Pörsümüş gecelere düşlerimin. 

Raylarını düşüyorum gülücüklerinin

yüzün silkelenmiş baharların acısında

mevsimsiz kalıyorum.

Göbek bağlıyor gökyüzü uçurtmamda

dilim vites değişip adını çoğaltıyor,

gözbebeklerimin içinde hasret kamçısı

duruyor bulutun 

ateşin köprülerini direksiz kurdu

güneş penceremin yüzüne.

Kadim hasretler yapraklarını

açıyor bulanık akan yalnızlıkta

içim yer değiştiriyor dışımla.

Tüm portakalların renginde 

artık çıplağım senden.

Aforoz edilmiş bir akşam vaktiyim saatlerden,

ruhumun ağırlığı ortada kaldı gölgemden,

Filistin kadar perişanım

işgal edilmiş bir intihar mektubuyum

bembeyaz bir sayfa gibi ortadayım 

topuk seslerini duyuyorum dillerin 

perdelerini çekiyor sözcükler

Cehennem müdaviyim şimdi.

kötülük çiçekleri koparılmış

bir şeytanım çöllerde_palo', 'fahişe gömülü sözcüklerin  çıplak bedenli istasyonlarında mahrem yerlerini örtüler  şeytanın karanlık dudaklarıyla. Yüzleri seslere karıştır...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/fahise-gomulu-sozcukler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzü Köprüsü', 'gokyuzu-koprusu-palo-keko-w4xeu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gök(yüz) ün (d) üşerse

yıldızlar hangi 

gökte lamba olur çocuk. 

Yer düşerse

hangi yürekte

yaşarsın....

ölüm ölürse

sıkmaz mı yaşam 

kemerini düşlerimizin.



Gece uyanırsa 

uykuyu nerden 

alacağız

Rüyalarımı kim görür 

portakal çiçeği çocuk.



Rüzgar boğulursa gökte

yazık olmaz mı çocuklara

uçurtmalarını nasıl 

uçururlar o zaman,

vurulmuş kanatları

hangi kelimeler

tamir eder.....



Sesimizin giysisi sökülürse

kim anlar konuşulanlardan

ve gör nasıl ayaklanır 

noktalama işaretleri

yürek nasıl yanar.

Omurganın çıtırdayışlarının

kulak kapısından

kim kovar yalnızlığı çocuk_palo', 'Gök(yüz) ün (d) üşerse yıldızlar hangi  gökte lamba olur çocuk.  Yer düşerse hangi yürekte yaşarsın.... ölüm ölürse sıkmaz mı yaşam  kemerin...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gokyuzu-koprusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paris Kaçığları', 'paris-kaciglari-palo-keko-yq63n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'paris kaçığları

düşlerin başkenti

acının çeyizi

şairlerin intihar ederek 

dul bıraktığı nehirlerin gözdeki izi.

gözyaşı rengini

seine nehrinin dalgalarına bırakan 

celan dan sonra gülmedi

bir daha dalgalar kahkahayla.

paris

düşlerin başkenti

acının gelini

solmuş çiçeklerin rengini

giyen gökyüzü adresi.

elektrik direğine kendisini asan

nerval den sonra

güneş doğmadı bir daha kahkahayla.

paris 

düşlerin başkenti

acının gelini

hazan mevsiminin ipliğine serilmiş

dudak keyfini

baudelire nin esrar çekişlerinde

yitiren mutluluk yetimi.

picasso inşa etti guernica da

kırık kolları

öküz başlarını 

ve umutlarını

yitiren bahar gerdanlığından sonra

cezayir  gülmedi bir daha kahkahayla.

paris 

düşlerin başkenti

acının çeyizi

gecenin hayaleti.

rimbaud ağladı sokaklarında 

duymadın, kulaklarının kolonlarında

burjuvanın yemi vardı

van gogh renklerinin altında kaldı

resim tabloları gülmedi bir daha kahkahayla.

paris 

düşlerin başkenti

acının çeyizi

vasiyetimdir ölürsem

paris te gömün beni,

eyfel kulesinin gölgeliğini

örtün üzerime

yıldızlar içsin gözbebekliğimi

paris

acının başkenti

düşlerin çeyizi

şairlerin intihara yuvarlandığı

gökyüzü yokuşu_palo', 'paris kaçığları düşlerin başkenti acının çeyizi şairlerin intihar ederek  dul bıraktığı nehirlerin gözdeki izi. gözyaşı rengini seine nehrin...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/paris-kaciglari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimden Tanıyın Beni', 'gozlerimden-taniyin-beni-palo-keko-x1975', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gözlerimden tanıyın beni

az ağlamadım

buğday başakları dalgalanırdı sesimde.

kulaklarımın beton dökülmüş içlerine 

sağın kanımı içirin uçurumlara.

uçurtmaya gök kalmadı bende.

gök olsaydım

her yıldız bir gözüm olurdu

görürdüm seni nevruz ateşi içinde

geceleri iple çekerdim güneşe.

gözlerimden tanıyın ezilenleri

yosun tutmuş gözlerimden.

her yanım döküntü gözyaşlarından

mezar ezgileri duyulur geceden

gözlerimden tanıyın beni

en çok onlar fotoğraflarımı çektiler.

ölümden tanıyın beni.

bir yıldız dikin mezarıma 

beton dökün üzerine 

kilitleyin ateşi kadavrama,

uykunun sandığına kapatın rüyaları

gökyüzünün maviliğini kesin makaslarınızla,

piç doğmuş delik tenekelerden çıkmayacak sesim

portakal ağaçlarından tanıyın yüzümü

siz yarım kalple dolaşanlar

sizin payınıza düşmeyecek sevgim.

güneş tıkayın göz çukurlarıma 

karanlık giyecek içinizi

gözlerimden tanıyın beni

en çok onlar ördü hasretini.

beni kartalardan tanıyın 

koskaca gökyüzünde yapayalnız

köşe bucak gecekondu 

bir yürek benimkisi,

beni gözlerimden tanıyın

en çok onlar idam edildiler

senin portakal bahçesi yüzünde.

tanıyın beni van gogh un tablolarından

gökyüzüydüm kopardılar topraktan_palo', 'gözlerimden tanıyın beni az ağlamadım buğday başakları dalgalanırdı sesimde. kulaklarımın beton dökülmüş içlerine  sağın kanımı içirin uçuru...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/gozlerimden-taniyin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Ölüme Yazın', 'beni-olume-yazin-palo-keko-693qv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'beni ölüme yazın

portakalları mağaralanmış günlere

zamanın kırıkları arasına,

buluta yazın gecelerimi

mavi denizlerimi.

ölüme yazın düşlerimi

silkeleyin ateşi yüzüm kalır.

beni açlığa yazın

çöllerin geceliğini giydirin uykuma,

yalın ayak çocukların gülüşlerini

geçirin umutlarıma,

mideleri boş insanları 

kazıyın mezar taşıma,

açlığa yazın beni

uçurtmaların kıtlığına.

beni darağaçlarına yazın.

gözyaşı komasına giren çığlıklara

ekmeği elinden alınanların sayfasına

tırnaklanmış yüzlerin kanına.

darağaçlarına yazın beni,

sallandırayım boyun eğmeyi.

beni kurşunlara dizilmeye yazın.

bir kadının gözyaşlarının elinden tuttum

ağlayan bir ırmağın acısını duydum

çentik çentik oyuldu ruhum

gece ortada bıraktı acımı

gözlerinizin arka bahçesinde vuruldum.

kurşunlara dizilmeye yazın beni,

nadasa bırakılmış dünyada yaşayamam

takın beyin programınızn hafıza kartını

sıra size gelecek ardımdan

ölüme yazın beni_palo', 'beni ölüme yazın portakalları mağaralanmış günlere zamanın kırıkları arasına, buluta yazın gecelerimi mavi denizlerimi. ölüme yazın düşlerim...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/beni-olume-yazin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümce Senin Peşindeyim', 'omrumce-senin-pesindeyim-huseyin-erdogan-k2ukv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yıllar önce

1 nisan 1954''de

bir şair doğmuş

Anamur''da bir köyde

yüreği sevgiyle doluymuş

hiç ağlamamış 

anasından doğarken

sanki göz yaşlarını 

sonraya bırakmış

şimdi ağlıyor her yerde

gözleri ırmak olmuş

akıyor Akdeniz''e

hiç soran var mı niye? 

elbette bir gün 

beni anlayacaksınız

aşk yakarsa sizi de

sevgili güvercinim

sevdanın ateşindeyim 

güzelliğinin düşündeyim

aşkının yolunda ölsem de

ömrümce senin peşindeyim

bir rüya bir hayal olsan da

günüme hiç doğmasan da

düş görmek istemem inan

rüyalarımda sen yoksan

bil ki  canım benim için 

artık sensizlik karabasan

ne olursun sevdiğim çıkıp gelsen 

beni böyle korkularda bırakmasan

zindandan beni hemen kurtarıp  da

ölmeden önce bir gün bile olsa da

bana sevilmeyi öğretsen ezberletsen

                             01.04.2005', 'yıllar önce 1 nisan 1954''de bir şair doğmuş Anamur''da bir köyde yüreği sevgiyle doluymuş hiç ağlamamış  anasından doğarken sanki göz yaşları...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/omrumce-senin-pesindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey kadın!', 'ey-kadin-palo-keko-i2cp2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ey saçında

rüzgarın düş kurduğu

kadın! 

doluya tutulursa

portakal çiçeği gülüşlerin,

beyaz bir sayfada

kurursa

suyun

ey kadın! 

saçlarında rüzgarın 

düş kurduğu 

deniz.

darağacı kurarım

soru işaretinden

sallandırım 

pencerenin yüzüne

gülmeyen 

alfabeyi.

gözün kıyısındaki

kuşlara

çiftlikler kurarım

gülücüklerimden.

ey düşlerinde

denizin rüyasını gördüğü

kadın.

ey kadın! 

kelebeğin 

kanat çırpışında

duygularını bırakan

şarkı_palo', 'ey saçında rüzgarın düş kurduğu kadın!  doluya tutulursa portakal çiçeği gülüşlerin, beyaz bir sayfada kurursa suyun ey kadın!  saçlarında r...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ey-kadin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filistin', 'filistin-palo-keko-v5tjk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ey filistin

yürekte çarpan 

yaralı kuş 

sensin.

budanmış hurma ağacındaki

bu inilti senin sesin

adını unuttuğumuz

cümlerin köklerine 

alfabesini veren

senin nefesin.

ey filistin 

söcüklerin yaprağındaki

özgürlük ağacı..

bir damla eksilmekle 

kurumaz denizin,

kırılmasıyla teki kolunun

kanadı kırılmaz oğullarının.

oğuların ey filistin,

budanmış bir ağacın

damarındaki sıcaklık

tekrar dirilten bedenleri.

ey filistin! 

oğuların

ekilmesiyle bir gözün 

toprağa,

bütün ölüler 

görmeye başlar.

bir damla kanınla

yüzyılların azığını 

alır direniş.

bir kaç kelimenle

sözlükler ayaklanır

 içimizde.

namlusunda bakışlarının 

bedenleri çürür

tankların.

ey filistin! 

yeryüzünün göğü,

vagonu baharın 

menekşelerden.

ey filistin! 

yürekte çarpan 

sensin.

budanmış hurma ağacındaki

bu inilti

senin

ey filistin! ._palo', 'ey filistin yürekte çarpan  yaralı kuş  sensin. budanmış hurma ağacındaki bu inilti senin sesin adını unuttuğumuz cümlerin köklerine  alfabe...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/filistin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadavraların Sözlüğü', 'kadavralarin-sozlugu-palo-keko-k4wzs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kadavraların sözlüğü

en son rüzgarın asılmasıyla

kırılmış bir ağacın dalında

düğmelerinde kalır acı

portakal yüzlü ölümlülerin.

damarlarımdaki nehirler kırıldı

ustura yüzlü uykularda.

gözyaşlarıyla sınırını çizdim

ağaçların kadavrasında düşlerimin,

devrildi gölgem sünepe güneşin

uzun burunlu balkonunda.

karınları yırtılmış rüzgarlar 

denizin kavruk suratıyla

çarpar kıyısına beynimin,

tavanı çöker uykumdan rüyalarımın.

leşlerin dişleri arasında 

yüzünü silkeliyor toprak,

uzun gölgeden mezarın

kar da dikişleri atar.

ölüm nöbetlerini tutuyor

silah yüzlü demli bakışlar.

salyangozdan kiremit yüzleriniz

kırık uçurtma gömleği çocukluğumda

bir filistin...hep acı...hep kahr

ölümün sağ kalan kolları

kavrar ruhumun penceresini.

anarşistlik bulaştı 

içimdeki kötürüm kaldırımlara,

tesbih tanelerinde dağılıyor 

ayağıma prangalanmış yolların

geri gelmez kızakları.

öp alınlığını rüzgarın 

kuş yuvasından kalma

gözyaşında,temellerini 

atamazsın aşkın.

kol düğmesi kopmuş 

bir gecenin direğinde

titrer şehri acılarımın.

çatısı dilimin ağır yüklü

bir koku denizi sepetinde

sığ örülmüş bir gölgeyle

eteklerini topluyor güneşin.

çamur sığırlarından boşanmış bir yüz

körelmiş bıçaklara gerilince

elektrik telleri çekilir 

toprağın damarlarından beynime,

bir militan ölür kanla budanmış 

acılarıyla,aç gazetelerin satır arasında.

kanatları parçalanınca 

sözcüklerin,dilimde öksüz kalır

kabaran yağmurdan sokaklar.

istasyon bilmez bir ölüme

tutulmuş gece yarıları,

ruh zinası çeperler örmedim

kardan güneşin yağlanmış göbeğine,

dökülmüş etlerin sedirine 

oturmadı kemiklerim,

yüzünde basamakları yükselmedi 

hiç yüreğimin,kumaşları fazla 

geliyor toprağın eteklerine bulutun,

yüzümden taşabilir yüreğim.

avaz avaz bağıran pencereden

başlarıyla girer naaşlar 

gülüşlerimin hesabına depremler

yatırılır,toprağın

çeplerinde ateş vadileri.

kilitleri dilde bozulmuş 

yularları çıkarın boynunuzdan

züppe düşümlü paçalar giydirmeyin

harabeye dönmüş iskeletsiz mumlarınıza.

göz kapaklarımdaki kırmızıya

bayrağını astım umutların

ve hergün azap çekiyorum 

parçalanmış bir coğrafyanın 

omurgasında,

kuşların kanatlarını serpin yaralarıma

kopmuş dikişlerdan kan tavan yapıyor 

içimdeki kara parçasında.

murdar kokuyor sıvanmış

beton sayfaların kirpikleri.

leşlere batırılmış bir yüzle

sağılmış kurak gecelerin 

parçalı bulutlu kundaklarında

afaroz edildim.

biraz ütüsüz düşünün.

kulpsuz gülüşleriniz

patlamış dudaklarımdaki sözcükleri 

kaporasız ağlatıyor.

kambursuz güneşin rahmi

su toplamış nasırlarımda batıyor.

bacasız ağlayan benim,

içimin röntgenini çekersem

alaşağı olmuş ruhumun 

duvarsız batışları 

kundaklar uykumu.

siz bayan 

kartonpiyer 

fotokopi kağıdından gözleri olan

kaç baskı yaptı aşkım ardınızdan,

siz bayan 

dışınıza kapatın içinizi _palo', 'kadavraların sözlüğü en son rüzgarın asılmasıyla kırılmış bir ağacın dalında düğmelerinde kalır acı portakal yüzlü ölümlülerin. damarlarımda...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/kadavralarin-sozlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldırımsız Yüzler', 'kaldirimsiz-yuzler-palo-keko-61wm0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kaldırımsız yüzler

biz kaldırımsız yüzümüzde

çırılçıplak güneşle

çeperlerini öreriz özgürlüğün,

ağzımızın kenarında bir parça kan

portakal ağacı yüzüyle

güneşin penceresine bakan...

siz gölgelerinin kolonlarına

bedenlerini inşa edenler,

adımlarınız yıkılıyor güneşin 

bulut yüzlü gözlerinde.

kökleri nereye uzanır bakışlarınızın,

ağzınızdaki bulanık sözcüklerden

yalanlar boşanıyor karanlığın ambarına,

güneş santim santim küçülüyor 

uykularınızın giysisi gecede.

siz sokakların bağırsaklarına

rüzgarlarını ekip

topraktan gökyüzünü bekleyenler,

uykumda gece düğümlenirken

rüyalarımı nerede bulabilirim ki? 

çığlıksız ve giyinik,heykelsiz...

söyleyin? 

yüreğim nerede boy verecek

düşük yaparken toprak,

dönüşürken çoçukların yüzleri

tütün yaprağına...

yüreğim nerede boy verecek? 

eğer yumruğum yoksa.

söyleyin? 

hangi renk öleceksiniz? 

bozulurken gökyüzünün saatleri,

sürülürken çoçuksu kuşlar düşümüzden

uçak sürülerinin anırmasında...

dillerine pörsümüş sözcükleri giydiren

gözyaşlarında isa’ları çarmıha geren

soğan gözlü timsahlar, insan ruhlarındaki

renksiz çizikler.

 ve siz şaşbeş görenler,

hangi yüzle çıkacaksınız

 meryem’in karşısına,

kanarken toprak gökyüzünün

çatlamış damarlarında

 ve parçalanırken ciğerleri rüzgarın,

suratımız devrilirken gri rayların

kömür düşümlü istasyonlarına,

hangi gökyüzü kalacak? 

çocukların uçurtmalarını

umudun üzerine sürecekleri...palo', 'kaldırımsız yüzler biz kaldırımsız yüzümüzde çırılçıplak güneşle çeperlerini öreriz özgürlüğün, ağzımızın kenarında bir parça kan portakal a...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/kaldirimsiz-yuzler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muşamba Atkılı Ruhlar', 'musamba-atkili-ruhlar-palo-keko-09w1d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Siz beyinlerinizi muşambadan 

Kafatası duvarı içinde taşıyanlar,

Siz kalplerini ham güneşte

Pişirenler,köpekleri doğuruyor diliniz,

Semiz bir uşak gibi uzanıyor 

gövdenizde gece,siz düşlerini

kurumuş bahçelerde yeşertmeye çalışanlar,

siz okudukça aptallaşan merkepler,

yerin altında boyattıkça yürekleriniz,

samanla mutlulaşan bir inek gibi sevinin siz,

fotokopi kağıdından gözleri olan

ve bilgisayar çıktısı beyin taşıyan

sizin bayan 

çöplüklerinizde hiç horozum ötmedi.

Sizin gölgelerinizde paçavralara döndü

Güneşin kumaşları,askısı koptu rüzgarların

Şimdi talim yapıyor acılar kalbimizin çiftliğinde.

Bir heykel gibi duruyor çocukluğumdaki

Kartopundan sürgün umutlar

Kadavraları arasında beton yığınların.

Siz boğazlanmış portakal ağaçlarını

Uykularının iplerine serenler,

Bilir misiniz? 

Bir kadının çamurdan ayaklarına

Hangi bulut yüzünü kondurur

Dururken tavanında gökyüzünün

Kuş sürülerinin cesetleri,

Siz tek düdüklü beyinliler

Ve notasız orkestra müziğini sevenler

Gitarlarının tellerinde ninni seslendirenler,

Siz laflarını peynir gemisine sırtlatanlar

Ve hayatı perakende yaşayan 

Kdv muaf ürünler

Yüreğinizi giyinin gözlerinizde,

Bıçağın aç yüzü baktıkça içimize,

Uyanın, uşşaklaşmış beyinlerinizi

sıvayın güneşin tıraşlanmış yüzüyle.

Bir çocuğun ayvadan suratına,

İndirebilirseniz indiriniz gemilerinizi

Çatısız yüreklerinizin limanlarına,

aaa pardon

Siz beyinlerinizi süngerlere işleyen

Fotokopi kağıdında gözleri olan

ve bilgisayar çıktısında beyin taşıyan

Sizin bayan,

Çöplüklerinizde hiç horozum ötmedi_palo', 'Siz beyinlerinizi muşambadan  Kafatası duvarı içinde taşıyanlar, Siz kalplerini ham güneşte Pişirenler,köpekleri doğuruyor diliniz, Semiz bi...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/musamba-atkili-ruhlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmalanmış Ruhlar', 'yagmalanmis-ruhlar-palo-keko-qzq8p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ruhların senfonisi

ruhumun gölgesi golgotha tepesi

lime lime acılarımda yeşeriyor 

paçavra sinesiyle güneş.

toprağın bedeninde ölüm 

kemiriyor yüzümdeki tapınağı.

saatini bekleyen bir idamlık gibi

yüzünü üzerime kilitleme.

rahminde sözcüklerin dağılmış rüzgar

kırıntıları,kalbimde halay çeken 

jilet yüzlü bulutlar,

daye kaburgamın tavanına 

asmışlar darağaçlarını,

giyotin sokaklarını içirdiler düşlerime.

kan kırmızısı düşüyor arkamdan yağmur,

merdiveninde yüzünün sağılmış kaldırımları

dikiş atıyor uykumun çivilerinde.

hayat küçük bir çocuktur 

güneşin kumaşlarında,

hep acı çeken bir yaşlıdır

kayıtları yapılmayan kırıklar.

gözlerini açan mermiler önce

bedenimde uzanırlar 

sonra sünger beyinli tarlalarda

kan çanaklarını doldururlar

afaroz edilmiş aşkların.

sunmak için şafağın yamaçlarını 

dizlerinden kırılmış dalgalara,

pörsük raylı bakışlarla,

ölümün boynunda çürür 

içimin son kara parçasıda.

son yalnızlıktır düşüp kalkan

buluttan ırmaklar yıldızların kurutulmuş

göğüslerinde,son vapurda geçti uykumdan.

hep kahır... hepten kahır...

hep kadavradan bir bedenle

asılmışım hayatın gömütüne...

sözlüklerle budandı dilim 

bir kuru rüzgarı ensesinde

taşıyor  deniz,

bir kuru ölü gömleğini 

giydirdim pencereme,

yağlanmış fiilerin çekiminde

bir halatla asılı kalır gök

kayıp giden kendilerimizle.

ağğ meşe ağaçlarının silkelenmiş

kuru ayvadan yaprakları,

düşüyor yüreğim bıçaklara

zincirleri kırılmış sözcükler

dilimin rahminde..._palo', 'ruhların senfonisi ruhumun gölgesi golgotha tepesi lime lime acılarımda yeşeriyor  paçavra sinesiyle güneş. toprağın bedeninde ölüm  kemiriy...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/yagmalanmis-ruhlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay', 'ay-i-lknur-er-ylie1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerin ellerimdeydi henüz yıldızlar şahitti aşkımıza

Sonra sen gözünü aya diktin

Yalnızlığını mı kıskandın? 

Ellerini çektin ellerimden ardına bakmadan gittin

Öylece bakakaldım ardından

Ne bir sorum vardı

Nede beklediğim bir cevap 

Bu son görüşümdü seni anladım

Umudumda yoktu

Sen yoktun

Yıldızlarda yoktu artık

Ama ay vardı ben gibi yalnızdı sen gibi yalnızdı

Her gece uykuya dalmadan önce ona baktım

Benim gibi boynu bükük ama öyle parlaktı

El salladım sana belki bir yerlerde

Ona bakarsın diye 

Yıldızlar gibi her gece çoğaldı sevgim

Ama ay kadar yalnızdım yinede

Sensizdim', 'Ellerin ellerimdeydi henüz yıldızlar şahitti aşkımıza Sonra sen gözünü aya diktin Yalnızlığını mı kıskandın?  Ellerini çektin ellerimden ard...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ay-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağır Düşmüş Toprağa Yağmur', 'sagir-dusmus-topraga-yagmur-palo-keko-qs5o4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sağır düşmüş toprağa 

Döksün bulutlarını gözlerim.

Kan kırmızısı bulanık uykularda 

Çarmıha gerin rüyaları.

Beyaz bir sayfa gibi 

Taşıdım ölüm satırlarını

Toprağın kaşları arasından.

Sağın umutlarımı, bir ırmak kan 

Gökyüzünün boynunda gözyaşı çengellerinde

Asılı kalan,kadim yeminler gibi.

Dikin düğmesini karın 

Yamalı bedenimin kumaşından,

Kuduran bezekler,ceset gibi yürüyen

Kelimeler dilimde kaldı,avlusunu 

Acı otelleriyle dolduran yüzümün tavanı,

Yüzüm pörsümüş portakal,taşlanmış fahişe

Kininizin vinçlerinde,kırık kuşlara 

Yuva yaptım içimin oyuklarını,

Hala kan damlıyor ciğerlerimden

Toprağın rahmi patlayacak

Güneş dolanıyor gölgeme,çocuklar 

Asılı kalırken çocukluklarının dağlarında,

Ruhumun iskeletinde basması eskidi 

Bedenimin,palme ağaçlarının 

Damarları tıkandı kanın yapraklarıyla,

Çöl hurması gülüşlerimle çalacağım kapısını

Bıçağın,penceresini kıracağım güneşin

Camın yaralarında kalan acıda.

Ruh zinası tarlasına döndü gözlerim,

Hergün görünce çocuğunda asılan bir kadını:

Oğlunun cesedinde ölüm karnını doyuruyordu

Toprak ise zamanın giysinde kendisini

Sonsuz gökyüzüne gömmüştü ve

Rüzgarın yastığı azap çekiyordu

Dalgaların çığlığından.

Mavi esaretin dişleri arasında kendisini

Kustu,yıkılmadı mı sütunları karanlığın 

Güneşin kaldırımında.

Kazığını dikin göbek bağıma siyahın

Ve sandalyesiyle çivilerin

Ön cephesine yüzümün,

Guernica tablosunu asın.

Kabus günleri  tuttu beni,

Özledim bir ıraklı gibi ölmeyi

Portakal ağaçlarıyla gülmeyi

Özledim seni,cehennem tarlasında

Boyatan zakkum ağacı gölgesini

Düşlese de bedenime,

Yıkın dolaplar dolusu kamburunu

Hümanizm şarkılarınızın, gitarımın 

Yetim bırakılmış sularında.

Her gün gölgemin sandığında 

Basması dişlerini dökmüş menevşe,

Bir bez asın gözlerinize

İçimde kan basamakları yükseliyor

İçimden ölüm trenleri kalkıyor

İçimde hiçbir istasyon kalmadı

Yaşamaya dair, 

baharlarının başı vurulmuş

bir filistin’liyim toprakla beslenen,

vietnam’lıyım ölümün nefesinde büyüyen,

hiroşima lı bir menekşeydim,

zebun kuşları soldurdu rengimi.

Güneşin her doğuşuyla azabı artıyor 

Sokaklardaki çocukların, yüreğimde,

Hala insanım,gözyaşlarıyla

Bestesini bulutlara öğreten.

Guatamanu üssünde bir tutsağım,

Gözleriniz üzerime kilitlediniz.

Mahkumum,prangada kollarım kırıldı

Duvarın nabız atışlarında.

Süt sağılmıyor etinden zindanların,

Kiremit kokulu ölümün 

Her gün çarmıhını biledi sözcükler.

Fotokopi kağıdından gözleri olan

Siz sayın bayan,

Çöplüğünüzde horozum hiç ötmedi._palo', 'Sağır düşmüş toprağa  Döksün bulutlarını gözlerim. Kan kırmızısı bulanık uykularda  Çarmıha gerin rüyaları. Beyaz bir sayfa gibi  Taşıdım öl...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/sagir-dusmus-topraga-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeyğ Ahmed yasin', 'seyg-ahmed-yasin-palo-keko-on6we', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hurma ağaçları gazze''de

boyunlarını eğdiler paylaşmak için 

acını gökyüzünün beyaz gömlekleriyle

koparken bedenin düğmeleri  ruhundan.

köklerinden acının rayları geçerken 

çölün,rüzgarların kayışı koptu 

akdenizin dalgalarında,oturmuşken 

kırık boyunlu gölgeler bedenlerimize,

güneşin dizlerine dağlar çöktü.

bir şafak vaktinde filistinde

ve esaretin tüm beldelerinde,

yüzümüz eskidi gözyaşında.

mezarları açıldı içimizin

başsız umutlar kalktı ayağa ilkin

kanının gücüyle,sonra

ölümler rafa kalktı ebedileşmenle

ey şehid! 

sen ki gökyzünün mendilisin

seninle siler yüreğimizi rabbimiz

sen ki huseyn''in varisisin 

seninle şahlanır yüreğimiz.

sözcükler ikiye ayrıldı mateminden 

toprağın gözleri oldu gözlerin

sadece gökyüzüne bakıyorsun

portakal ağacı yüzün 

kumaşı oluyor tutsak şafakların.

öldü diyorlar senin için

hayır, ekilmesiyle bir bedenin 

toprağın uykusuna

gökyüzünde yeni yıldızlar boyverir

öldü diyorlar senin için

hayır,

her yürek seni büyütüyor 

kanın bir gürz gibi indi

karanlığın kafatasına,

sapana koyulan her taş 

tanır seni

bulutlar hüngür hüngür ağlasada arkandan

kavuştun sen muradına

ey davud un mirasçısı

kış mevsiminde açan kır çiçeği

buzlarının düğmelerini söktün

bacaklarını kırdın gecenin 

doğması için güneşin 

tutsak penceremize,

yırtmaçlarında çölün 

duaya duran kumlar 

insan seline dönüştü meydanlarda.

ey davudun mirasçısı! 

gölgelerini sürüyorlar güneşinin üzerine

karanlığın ipliği yalanlarıyla

yeryüzünü gökyüzünde asılı tutmaya

çalışıyorlar.bak çoçuklar sadece senin adınla

yeşertiyorlar yüreklerini yumruklarında,

zeytin ağaçlarının asılı kaldığı suratımıza

senin kanın getirdi bahar müjdesini.

dünya gördü,sen oturamazdın,

bir kadın asarken gözyaşlarını,

çığlıklar boğazlarken toprağı,

sen gecenin boynunu vurdun.

ey davudun mirasçısı! 

ağlamak yok bugün

kavuştun muradına

gözyaşı akıtmak yok

ancak imrenilir sana_palo', 'hurma ağaçları gazze''de boyunlarını eğdiler paylaşmak için  acını gökyüzünün beyaz gömlekleriyle koparken bedenin düğmeleri  ruhundan. kökle...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/seyg-ahmed-yasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebu Ammar', 'ebu-ammar-palo-keko-f07hj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ebu ammar

koptunya buğday başaklarının gülümseyişinden

rüzgar öfkesini serer denizin üzerine şimdi

sahipsiz kalmaz ardından sapana sürülen taşlar

bakışlar yağmura karıştı mendillerde yaser 

oturup ağlama zahmetine de girmedin 

sürdün bedenini namluların şafağına 

kalbin ateş ovalarında dağlanırken 

kuş yuvası yüzün 

bir bahçe oldu küçük genarellerin yalnızlığına

tiksinti kasırgalarına prangalanmış cellad

bayram ilan etti o günü

sanki arkadaki yük treni onun için kalkmıyacakmış gibi

ebu ammar 

kırılırken kollar taşlarla, 

ağlarken gökyüzünün beyaz sahifeleri

bırak yüzlerini ciltlesinler

ceninin sokaklarında raydan çkarken insanlık 

kalın kitaplarla boy göstersinler ekranlarda

sükunut ninnileri söylesinler bırak 

mevzisini kaybederken gözlerimiz

göyaşından cepleri dolarken uykularımızın 

gecenin kasvetli parmaklığında 

rayları söküldü umutların ebu ammar.

döşeyin yüreklerinize güneşi 

hurma ağaçları ekin bakışlarınıza 

ağuçlayın özgürlüğü kana kana

atıldın yatağından kuşluk vaktine

çölün kuraklığına balyoz oldun 

suskunluğun kundağından taştın 

karın göğsünde açınca kırmızı 

yüreklerimizin dağlıkları ova olacak 

tekrar açacak çiçekler senin için yaser.

şafaklara namludan çıkılır 

teslimiyetten daha büyük ölüm yok

ruhun güvercin gerdanlığında 

cennet bahçesinin damlığında

kanat çırpıyorsun şimdi

kötülük fıçılarına doldurulurken beyinler

musluklarından doğmaz güneş penceremize

sana göre değildi hesaplar arasında kaybolmak

kağıttan bir kalp de taşımıyordun

taştanda değildi ki gözlerin 

bulutlardan demlenmişti uykun yaser

kanser hücreleri emiyor toprağın şarkısını

zebun kuşunun tırnaklarından kanadı uçurtmalıklar

kamburda olmadın yaşama yaser

kadavralara konuşur kanın dipçikleri

uyanın, filistin bahçesinden koparıldı

bir güneş daha.

ardından bm (birleşmiş milletler= bitlenmiş mitoslar) 

değil bayrağın yarıya indirmeleri 

otursalar da direklere 

silinmez artık alınlarındaki leke

çünkü onlar kudüse  çıkarma yaptılar ilkin

sonra da onayladılar işgal edilmesini yeşil hurmalıkların.

kutsaldır her karış toprağın 

topraktan dikilir çünkü giysileri baharların

golgotha tepesinde teşhir edilmese de çarmığ

çiviler gözlerinden söküldü hep yaser.

postalınca ağıtlar gözyaşında

ramallah ta kuşlar dökülür tankların önüne

kuşlar bedenleri şarapnel parçalrıyla mühürlenmiş

nasıl sırtlar toprak bu acıyı

nasıl dayandın onca kahra bunca zaman

gözyaşaları kimliksiz gözyaşları pasaportsuz

ykılır iç şehri ebu ammar ın

parsellenmiş kahır tufanlarında

el aman cariyeleri beyaz saray çadırında 

bölüşürler toprağını kulpsuz kancığlar

ama doğar yaserler 

gölgesi olan tüm ağaçlarda meyvesini verir.

başları eğik olan enik yavruları

bakın nasıl yer öpücük konduruyor maviye

altn tasmalarıyla dolaşanlar

denk gelemez dünyanın tüm altınları 

bir gram onura.

çamurdan sığırlar kefen dikin celladın hareminde 

çocuklara ve övünün yaptıklarınıza 

sanmayın hesabı sorulmaz yaserlerin

içinizde  kanalizasyon kuyuları açılırken 

duyamazsınız yaserlerin şarkısını 

kulaklarınıza göre değil çünkü

geviş getiren ağızlarınızdaki çöplükler

kundaklandı yaser in tetiğinde

yol  olamaz korkaklar fecre 

çünkü kanatları var yaserlerin 

kanatları gökyüzünden.

alın çorak çölleri 

parsellemeye başladı yaser

ile şeyh ahmed yasin cenneti_palo', 'ebu ammar koptunya buğday başaklarının gülümseyişinden rüzgar öfkesini serer denizin üzerine şimdi sahipsiz kalmaz ardından sapana sürülen t...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/ebu-ammar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanımız Bayram şekeri gibi tatlı', 'kanimiz-bayram-sekeri-gibi-tatli-palo-keko-hl4e7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kanımız bayram şekeri gibi tatlı,

çekiyor kana susamış keneleri,

doluyor gökyüzünün  çizmeleri

gözyaşından felluce! 

çığlıklar birbirine dolanıyor dillerde,

yüzün asimavisi göklerin kalesi

adın onuru direnişin

lal toprak üzerinde,

adın bir sancak çocuklarının dilinde

adın çeyiz sandığı

bir kadının yüreğinde,

ölüm paydos etti direnişinde 

felluce! 

toprağın burun deliklerinden

bakıyor mezardakiler

imreniyorlar sana.

üç kat güneş üzerinde

filistin,cezayir ve 

gözleri hz hüseyn''in

iki kat bulut

fırat ve dicle.

özgürlük elbisesini

dikiyor direinşinden,

petrol kuyusuna dönüşen gözlerin

tahtaları çürüyor bedenlerinde güneşlerin

gülümsemenle felluce! 

yüzümüzdeki ümitlerin inşaatı 

tamamlanacak 

göreceksin bir çocuk uçurtmasını 

salacak yüzünden göğe

bir kadın gözyaşlarını silecek

bir çocuğun gülümsemesinde

felluce! 

kuşlarına kanattır rüzgar

düşlerimizin  söküğüne 

güneşini tıkayacağız şafağınla

felluce! 

iki düğüm atacağız geceye; 

filistin kanatlanacak ilkin

sonra yeryüzünün tüm halkları

sırtlarındaki mezarları gömecekler

felluce! _palo', 'kanımız bayram şekeri gibi tatlı, çekiyor kana susamış keneleri, doluyor gökyüzünün  çizmeleri gözyaşından felluce!  çığlıklar birbirine dol...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kanimiz-bayram-sekeri-gibi-tatli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Bir Pazardır -mensuriye-', 'dunya-bir-pazardir-mensuriye-zulfikar-yapar-kaleli-qduhc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünyada üç şey,

insanın helâk olmasına sebeptir. 

Bunlar: Süse çok düşkün olmak, 

Hatalara aldırmamak 

ve kaybolan dünyalığa üzülmek.

Nefsin zevk aldığı şeylere 

iyi bakmak lazım.

Pazarlara çok mal gelir, 

her türden, çeşit çeşit. 

Biz bize lazım olanı satın alırız. 

Bir kısım şeyleri almak aldanmaktır.

Pazarı sırtına vurmaksa aptallıktır.

Dünya pazarından herkes nasibi kadarını alır

İhtiras denilen şey, 

azgın ve önü alınamaz bir iştahtır. 

Bilirsiniz sert suları havuzlarda dinlendirirler, 

yumuşasın diye. 

İhtirası da kanaat havuzuna sokmalı ki, 

uysallaşsın. 

İnsan gördüğü her şeye sahip olsa ne kazanır.

Tekrar ediyorum, 

ÇOK MAL.

ÇOK HESAP VERMEYİ GEREKTİRİR.

 İhtiyaçların sınırına dikkat etmeli.

 Nitekim o kadar şey var ki lazım olmadığı halde,

 bize lazımmış gibi gösteriliyor.

Çağdaş teknoloji gözlerimizi kamaştırmasın. 

Nitekim insanların yaptıkları, 

insan kalbinin karmaşıklığı karşısında hiç kalır. 

İnsanların iyisi insanlara meyve sunandır. 

Her faydalı eser, 

her faydalı iş faydalı bir meyvedir. 

Fırsat eldeyken yarına hazırlık yapmalı. 

Zira geçen hiçbir günü geri getirmeye 

gücümüz yetmiyor. 

Havaya giden sözler söylemektense 

kalpleri okşayan, hoş sözler 

söylemek gerekmez mi? 

Hata bilmediğimizi yapmamızdır.

Bu yüzden 

yüzümüzden pişmanlık çizgileri 

eksik olmaz. 

Kendimizi bu yüzden yer bitiririz. 

Tamir edilen hatalardan ziyade

terk edilmeyen, devam ettirilen inat kötüdür.

İnsanlar genellikle üç nedenden dolayı 

açgözlülük yaparlar. 

Cahilliklerinden, 

kibirlerinden 

ve inatları yüzünden. 

O halde ameline güvenmek 

kibrin en büyüğüdür.

Dünya bizim için dönüp durmakta. 

Onun dönüşüne başımızı ayarlamayı bırakmalı, 

kendi şahsiyetimizi yaşamalıdır. 

Bir takım sözler var ki 

onları papağanlar da söyler. 

“Bin düşün, bir söyle” 

diyenler boşuna dememişler. 

Nice söz gevezelikten öteye geçmiyor, 

sahibini dara düşürüyor, 

gece uykularını kaçırıyor.

Gerçek zenginlik; 

hiçbir şeye ihtiyaç duymamaktır. 

Dünya malına çok ilgi duyanlar 

gerçek özgürlüğü bulamaz. 

Çünkü; çok mal insanı kendi esiri yapar. 

Gaflet içimizde  kışı yaşatır.

 Kışı yaşamamak için 

Neronlar’ın, 

Karunlar’ın,

Cemşitler’in

durumundan ibret almak gerekmez mi?', 'Dünyada üç şey, insanın helâk olmasına sebeptir.  Bunlar: Süse çok düşkün olmak,  Hatalara aldırmamak  ve kaybolan dünyalığa üzülmek. Nefsin...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/zy17-dunya-bir-pazardir-mensuriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A n n e. (Şükrümüz Menzile Varmıyor) ...', 'a-n-n-e-sukrumuz-menzile-varmiyor-zulfikar-yapar-kaleli-9u09y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu sevda vefasız, bu aşk yalancı

Kollar birbirini sarmıyor anne! 

Balı imrenilen arı talancı

Zikrini hamt ile karmıyor anne! 

Bağımızı basan yarların suyu

Aktıkça kirletir arların suyu

Sobranın, Kalenin Hurların suyu

Harşit’in bağrını yarmıyor anne! 

Doğru dedik, eğri gördük suç ettik

Varamadık, her varanı koç ettik

Suçlu dedik başımıza taç ettik

Yürekler topluca vurmuyor anne! 

Gözümüz göklerde kaldıktan beri

Yerlerde her saat gitmişiz geri

Şu kart horoz verdi acı haberi

Kimseyle meşveret kurmuyor anne! 

Bir makam uğruna eğil ha eğil

Sen bizi terk ettin, biz seni değil

Ne köyler köy artık, ne de iller il

Hiç kimse Sözünde durmuyor anne! 

Söz ile menzili görenimiz çok

Secdesiz, duasız erenimiz çok

Çok bilmişle, akıl verenimiz çok

Rüyamızı hayra yormuyor anne!

Her an bağrımıza saplanır her ok

Gelip geçen trenlere bakan çok.

Üstümüzde salavatın duan yok

Şükrümüz menzile varmıyor anne! 

Artık saçın yolup bağrın döven yok

Gemimizde gayret eden, iven yok

Şu görkemli makamlarda güven yok

Kimse halimizi sormuyor anne!', 'Bu sevda vefasız, bu aşk yalancı Kollar birbirini sarmıyor anne!  Balı imrenilen arı talancı Zikrini hamt ile karmıyor anne!  Bağımızı basan...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/a-n-n-e-sukrumuz-menzile-varmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Nedir', 'ask-nedir-suleyman-kaya-x6do9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yılan hikayesi

Sarmaşık dalı,çiçeği

Bir gidap,anafor

Eriyen bir buz kütlesidir.

Aşk...

Acı ve tatlı anın

Hasret ve kavuşmanın

Ayrılık ve buluşmanın

Yüreklerde sezinlendiği yerdir.

Aşk...

Asla satın alınamıyacağı

Paha biçilemiyeceği

Ayarının,gratının olamıyacağı

Değerinin biçilemiyeceği bir duygudur.

Aşk...

Gözyaşların kirpikleri ıslattığı

Bakıışların kalbleri serinlettiği

Hülyaların uykuları harapettiği

Sıcak tenlerin genizleri uyardığı yerdir.

Aşk...

Toprak anaya eşdeğer

İnsanın içine gömüldüğü yer

Ruhların arınıldığı yer

Libassız sevdiği bedendir.

Aşk..', 'Bir yılan hikayesi Sarmaşık dalı,çiçeği Bir gidap,anafor Eriyen bir buz kütlesidir. Aşk... Acı ve tatlı anın Hasret ve kavuşmanın Ayrılık ve...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Kaya']::text[], 8.5, '{"poet":"Süleyman Kaya","poet_slug":"suleyman-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ask-nedir-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığı derim', 'asigi-derim-aladdin-kilic-ax3qd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'On sekizlik dişi çıkmış yarimin

Hele yaşını doldursun bak Allah kerim

Gereken cevabı ona veririm

Seni seviyorum aşığım derim.

             On sekizlik dişim çıktı demişse

	      Evlenme çağına madem gelmişse

	      Teklifimi eğer ret etmez ise 

	      Seni seviyorum aşığım derim.

Cevabı ne olur acep bilinmez

Bu teklif şıp diye hemen söylenmez

Kapıdan eli boş geri dönülmez

Seni seviyorum aşığım derim.

	   Önce bir danışıp kararı versin

		İstediğin yerde görüşelim desin

		Yeter ki oda gönülden sevsin

		Seni seviyorum aşığım derim.

Bu gönül işidir gelmez her işe

İsterse şayet kalmaz endişe

Mutlu son ile varır bitişe

Seni seviyorum aşığım derim.

	Aladdin’in isteği sevsin dinini

         Haramdan günahtan çeksin elini

         O zaman gör bak güzel gelini

	Seni seviyorum aşığım derim.', 'On sekizlik dişi çıkmış yarimin Hele yaşını doldursun bak Allah kerim Gereken cevabı ona veririm Seni seviyorum aşığım derim.              O...', ARRAY['Türk Edebiyatı','Şiir','Aladdin Kılıç']::text[], 8.5, '{"poet":"Aladdin Kılıç","poet_slug":"aladdin-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/asigi-derim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Portakal Yüzlü Ay', 'portakal-yuzlu-ay-palo-keko-0t0rc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Portakal yüzlü ayın 

Kaldırımında yürüyorum 

Gözlerin bir çift yıldız

Kalp teknem akıntına kapılıyor 

karanlığın koridorunda yıkanıyor gözyaşlarım

ardından yapraklarını döktü kör bulutlarım

sibiryadan bir ruh benimkisi

sobası ısıtıyor gülücüklerinin

ayva toplamıyor uykum artık

kan baskısı yapıyor geceler

yüzünde mahsur kalınca düşler

kendime çakıldı çivilerin golgotha tepesine

düşmezdi sonbahar yaprakları 

kalemin ucuna

üşüyorum kar demledi saçlarım

çiçekler açıyor bastığın gökyüzünde 

topluyor gözlerin arkamdaki dağınıklığı.

Sevmekle tükenmez zaman 

Uzaklarda da aramamalı kendini insan

Uzaylarda düşlerinintapınağını kursa da

Gölgen daima bedeninin peşindedir

Ve sırtını dönersen güneşe

Gölgen önüne düşer.

Ben gecekondusu yaşamın 

Mutluluğun tohumu atılmaz ki

Nadasa bırakılmış uçurtmalıklarda.

Kelebekler kırılıyor sesimde.

Ölümün rayları geçti içimden

Boşken kompartmanları mutluluğun 

Acının giysisi dikilir çığlıklardan 

Ağlasam sel alır seni

Kundağında aşkın bir çocuğum

dizleri yırtılmış bir bulut parçası

namlunun dişleri dökülür bedenimden 

portakal ağaçlarının yapraklarını

toplarda uykumun sandığından.

Neden yaşar ki insan 

Hep bir yarayla kuduz olmuş yalnızlıkta

Kamburu çıkyor yaşamın 

Dizüstü çöktü kalem

Kağıt boynunu sallandırdı mürekkebe

Suyun çeperlerini alev sarmış

Toprağın rahmine bulutlar ağlamış

elinden tutan yok ürkek bakışlarımın

tabutlara konulmuş güvercin senfonisi

kumar oynuyorum ölümle 

cehennemin yeni müdavimi bendenizim

yeryüzünün samanlıkları 



gıpta edeceksiniz yandığıma.

En iyi yaptığım şeydir 

Toprak taneleri gibi

Yağmur güllerini yemek.

Oysa kimliğimdir aşk

Ama o ülkede bana vize vermiyorlar_palo', 'Portakal yüzlü ayın  Kaldırımında yürüyorum  Gözlerin bir çift yıldız Kalp teknem akıntına kapılıyor  karanlığın koridorunda yıkanıyor gözya...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/portakal-yuzlu-ay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olcay Özkul un Ceketi', 'olcay-ozkul-un-ceketi-palo-keko-cj3lz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bulutların rahminde kalmasın gülümsemen 

kundaklasın gece tutan acıyı mutluluğun.

üzerine giyindiğin ceketin 

baharları demlesin keke.

çiçeklerin düğmelerini  kapatma yüzünde

toprağın eteğinde gözyaşlarım

yıldızlar uyuyor şimdi çocukluğumda

uyandırma habis gölgeleri 

karanlıktan botları var onların

kapat gözlerini dünya üşümeden sevgisizlikten

saçlarımızda kış tavan yapmadan,

kapat pencereni ruhum dökülebilir.



umurunda değil senin dersler

hayatın geçme notunu almışsın dostum,

elli dokuz nokta dörtten uzadı 

bulutlar içimde.

yırtık kumaşlardan dağlar kilitleniyor

boğazımın çocukumsu bahçesinde.

rüzgarlar geçmiş yeşil gözlerimin dümenine,

yeter bunca acı 

soğukların heykelini dudaklarıma dikmeye.

küs namluları doğrultmadım sana

kaldıysan genel arkeoloji den

hayatın genelinden geçeceksin.

bir şakaydı kelimeleri olta yapma,

güneş postallarını giymiş yine gözbebeklerin

sevincimiz oluyorsun güneşsiz derslerimizin.

çiğ düşebilir uykumuza aşk

parçalanabilir küçük vazolu rüyalar 

darağaçlarını kafaya dikip ölebilirim keke

sağır düşmesin mutluluk yakanda. 

dökme kelebekleri taşıma yüreğinde

uçurtmamda olmadı hiç,

aşık olana kadar

o günde hava bulutluydu keke

trafiğe kapatmışlardı duyguları.



Olcay özkul un ceketi

bir bahar demeti

iliklemiş gözbebeklerine,

küçük beslenme çantasında

taşırdı yıdızların gömleklerini

gecenin bağcıklarını bağlardı

rüyalarımızın sünepe gölgeliğinde..._palo', 'bulutların rahminde kalmasın gülümsemen  kundaklasın gece tutan acıyı mutluluğun. üzerine giyindiğin ceketin  baharları demlesin keke. çiçek...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/olcay-ozkul-un-ceketi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nisan Şakası', 'bir-nisan-sakasi-ertugrul-sakar-1l9od', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çiçek beyazı kar bıraktın kapıma

Saçlarımı damla damla ıslattın

Sen aldatılmış geçmiş

Bu günde sen beni aldattın

Sevinmek,içimden geçen

Şu pardösü de sırtımda neyin nesi

Sev / meye ve sevil / meye merhaba

Hayat bu

Acısı,  tatlısı

Bir nisan şakası

Bahar olmasına bahar

Kar gözlerime bakar

Cilve dersen cilve

Ah kar, ah Şaka / r', 'Çiçek beyazı kar bıraktın kapıma Saçlarımı damla damla ıslattın Sen aldatılmış geçmiş Bu günde sen beni aldattın Sevinmek,içimden geçen Şu p...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-nisan-sakasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum Seni', 'seviyorum-seni-tulay-eker-tv29c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seviyorum seni 

Göğüsleri arasına başımı yaslayıp 

Anne sesinden ninni dinleyen 

Ruhumun derinlerine inen 

Sevginin titremesi misali 

Seviyorum seni 

Özlemin ayak seslerinin yaklaşması 

Sen olup boynuma sarılması 

Şehrimin karanlığından sıyrılıp 

Sokaklarımın aydınlanması misali 

Seviyorum seni 

Etle tırnak,kaşla göz 

İki dudak arası,alın ortası 

Yedi güneş ötedeki aydınlık 

Dört gölge boyu uzanmışlığım misali 

Seviyorum seni 

Üşüten ayaz gecelerde 

Yüreğimin dile gelip sustuğunda 

Gözlerimden kopup gelen 

Damarlarımda dolaşan ateş misali 

^^Zaman damlasa kar yağdırmayan buluttan,Üzeri yapış yapış Özlem olsa dallarının Uçurum sessizliği  Ürpertisin de yalnızlığımın

Adını sen koyarım duymazsın...Hissedersin ^^', 'Seviyorum seni  Göğüsleri arasına başımı yaslayıp  Anne sesinden ninni dinleyen  Ruhumun derinlerine inen  Sevginin titremesi misali  Seviyo...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/seviyorum-seni-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzü', 'gokyuzu-palo-keko-f1b5e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir gökyüzü var beynimde 

yıldızı eksik 

yükseltilmiş dağların omzunda 

umudun en çukur yeri..... 

bir gökyüzü düşlerimde 

hatırladıkça mavi denizi 

mavisini dalgalar ceplerine 

indirdi rüzgardan habersiz... 

hatırladıkça çocukluğumu 

istasyonda  kalıyor trenim 

yarıçıplak yolcular arasında..... 

dikilir kaşlarımın arasına raylar 

parça parça koptuğum ırmaklardan 

tüneller girmiş ümitlerime..... 

gökyüzü vardı sevdiğimin 

yıldızlar arasında kaldı 

bir tarafı hüzünlü gölgem 

ağladım üşüyordum 

düğmeleri kopmuştu 

üzerime giydiğim bulutların 

tırnaklarımı kemirdim ardından 

asfalt gibi beynimi aşındırdım acılara 

ağacların yaprakaları soldu 

kış kapı almış saçlarımda 

ve yıkıldı birbir fotoğrafımda 

geleceğin yollar 

insan duvarlarının 

soğukluğu hırpalar bedenimi 

kanter içinde uykularımın 

rüyasını aldı gözlerin 

ölü gibi ben 

yırtılmış gökyüzün altında_palo', 'bir gökyüzü var beynimde  yıldızı eksik  yükseltilmiş dağların omzunda  umudun en çukur yeri.....  bir gökyüzü düşlerimde  hatırladıkça mavi...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gokyuzu-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hurmanın Çocukları', 'hurmanin-cocuklari-palo-keko-b8afj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ceviz yaprağı dalında,

yeşil ağuçlu rüzgar,

ağzında kuş sesleri,

kırıkkanatlı düşler omzunda,

bağdattan haber getirdi.

dökülmüş yaprağını,

zeytini gözlerin

çöl kaburgasını,

yanmış bedenlerin

bağdattan, hurma ağaçlarının 

arasından getirdi feryadlarını...

bir çocuk devrildi toprağa

göğsünde yalanın resmi,

on yaşına basmadan

hurma olamadan

tamamlanmadan fotoğraftaki şekli şemali

yüzüstü serildi toprağa....

hurma olamadan 

on yaşına basmadan 

ağacı oldu çöllerin

umudu oldu yaslı gözlerin_palo', 'ceviz yaprağı dalında, yeşil ağuçlu rüzgar, ağzında kuş sesleri, kırıkkanatlı düşler omzunda, bağdattan haber getirdi. dökülmüş yaprağını, z...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hurmanin-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayın Şavkı', 'ayin-savki-palo-keko-yuxoc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayın şavkı vuruyor uykuma,

çeperinde rüyalarımın 

kanatları kırılmış kuşlar

dökülüyor, gagalarında boğulmuş

yastığımın  hüznü.

Kalemimi acıya biledim

bembeyaz bir sayfada

yol alan bir trendim

bedenim

en uzun ray

İstasyonu olmayan...

gömüldü içimde

açmaya duran portakal çiçekleri

vagonlarda solan yapraklar

ağaçların iç çekişlerinden 

ayna doğranıyor yüzüme,

yüzüme  gülücüklerini kaybeden

ayva ağaçları diktin

kapatarak tüm kapıları dilimin üzerine.

Tüm sözlüklerde bir yabancıyım 

ödünç alınmış bir kar tanesi

güneşin iliklerinde üşüyen

İntihar ederek döküldü kelebeklerim

yüzüm fahişeler kadar çıplak

Sokaklarda volta atar bakışlarım

tanıyanız var mı beni? 

boğazlandım

Aşka yazdılar çekimi

bir rüzgar esti, yarı kelebek 

ağlarken gözlerimi uçurdu

İçinde hiç yağmur çiseledi mi? 

kar çiçeğim.

Hayata yamalanmış bir ruhum 

maden ocağında gözlerinde

yandım kavruldum', 'Ayın şavkı vuruyor uykuma, çeperinde rüyalarımın  kanatları kırılmış kuşlar dökülüyor, gagalarında boğulmuş yastığımın  hüznü. Kalemimi acıy...', ARRAY['Türk Edebiyatı','Şiir','Palo Keko']::text[], 8.5, '{"poet":"Palo Keko","poet_slug":"palo-keko","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ayin-savki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda İstanbul', 'elveda-i-stanbul-haluk-mahmutogullari-n1yqs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elveda İstanbul 

                          Ölümsüz aşkların mezarı

                          Konstantin''in günahı elveda...

Bu benmiyim kollarımda? ..

Yaprak dökümü başlamış

Dolmabahçe yollarında

Oysa mevsim daha yazdı.

Maçka’da bir uğultudur aldı kulağımı

İnsan uğultusu, it uğultusu

İstanbul yanıyor rengârenk

Gözlerim kararıyor.

Her şey kaybolmağa başlıyor

Göz bebeklerimde,

İstanbul küçülüyor

Sen küçülüyorsun

Nokta gibi kalıyor herşey

Ayağımı kaldırıyorum

Ezeceğim bir izmarit gibi İstanbul’u

Sen geliyorsun aklıma

Vazgeçiyorum...

Avuçlarımı olta etmişim umutlarımı yem

Balık tutuyorum Arnavutköy’de

Umutlar bitti,zembilim boş

Dönüyorum...

Yirmi beşinci saatte

Kasımpaşa çöplüklerinde

Dostlukların 

Şereflerin

Aşkların

Kırıntılarına rastladım

Sordum dilencinin birine

Kimler atmış bunları? 

Ellerini kaldırdı

Beyoğlu tarafını gösterdi

“Bunları o yüksek yerlere

Çıkanlar atar zaman zaman.”

Hemen topladım

Dostluk kırıntılarını,

Şeref kırıntılarını,

Aşk kırıntılarını

Birbirine ekleyip

Uçurtma yaptım,

Kulaksız bayramyerinde

Çocukça bir hevesle 

Uçurmaya başladım.

Son sürat Taksim’e tırmanıyorum

Saat iki olmuş,geç kalmışım 

Her şeyi taksim etmişler Taksim’de

            Sevdayı- Karıyı- Kızı

            Vefayı- Sarayı- Sözü

            Semayı- Parayı- Sazı  

Yorgunum,

Eski bir fenerin altına oturuyorum

Asmalımescit Sokağında,

Kaşarlanmış bir kadın gelip soruyor

“Ne arıyorsun delikanlı”

“Senin aradığını değil” diye cevaplıyorum

Kadın gülüyor...

           Gülüyor...

           Gülüyor...

Kulaklarımı tırmalıyor kahkahaları

Çıldırmak işten bile değil,

Gırtlağına sarılıp susturmak istiyorum.

Nefret ediyorum her şeyden

                   Yazdan- Güzden

                    Sazdan- Sözden

                   Karıdan- Kızdan

Hattâ ürküp kaçırıyorum ben

                      Dağdan- Taştan

                      Kurttan- Kuştan

                      Dosttan- Aşktan

Oysa ki eskiden her canı, her nesneyi 

Doyasıya hem sevmeyi, hem sevilmeyi

Severdim

Severdim

Severdim

Ben

Beynim bir deli, hep bağırıyor

Ben kimim? ...

Ben neyim? ...

Ben ne arıyorum

Bu köhne kentte,

Bunca yabancı arasında

İşim ne benim? 

Arıyorum

Sevgiliyi mi? 

Dostları mı? 

Yoksa mutluluğu mu? ..

Hayır! 

Hayır! ..

Hiçbirini,

Sokaklarına düşmüşüm İstanbulun

Kendimi arıyorum  kendimi...

Saat 3.45

Yüksek kaldırımda 

Güneş doğmada

Galata köprüsü’nde

Pazarlığa oturuyorum

Balıkçının biriyle.

Soruyorum,

Kaptanı derya 

Benim mazimin tümünü

Kaça götürür atarsın

Okyanusun en derin yerine? 

Önce yedi yüz elli istiyor

Sonra beş yüze razı oluyor

Olmaz diyorum

Önce, senin bu taka

Taşıyamaz benim çirkef mazimi

Ve sonra, değil beş yüz

Beş para etmez benim hatıralarım

Çok kızıyorum

Hatıralarımı

Göz yaşlarıma katıyorum

Damla damla akıtıyorum

Marmara’ya,

Haliç’te bir çöp arabası

Çöplerini döküyor

Ben de hatıralarımı.

Ferahlıyorum

Artık gözlerim, kulaklarım rahat

Hiçbir şey hatırlamıyorum

Birkaç damla gözyaşından başka.

O suzinâk şarkı dökülüyor dudaklarımdan

“Şimdi uzaklardasın gönül hicranla doldu”

Karaköy iskelesi

Karşımda aydınlık yüzlü bir ihtiyar

Yorgun ve titrek sesi,

“Evladım bu ayrılanlar köprüsünde

Şafakta ağlayan çok genç gördüm

Hepsi zehirlerini akıttılar, gittiler

Aradıklarını bulmuş, olacaklar ki 

Bir daha dönmediler, 

Yalnız ben gitmedim

Senin aradığını kırk yıl var ki

Bulamadım.

Haydi yavrum şimdi sen de git 

Ama yıllar sonra dönüp te 

Göremezsen beni burada

Bil ki ben de bulmuşumdur aradığımı.

İşte o zaman

Denize bakıp

Bir fatiha oku ruhuma.”

Elini öptüm isimsizin

Ayrıldım yanından

Vapurun güvertesinden 

Son kez baktım İstanbul’a,

Geceden yorulmuş

Yeni yeni dalıyordu uykuya,

Makyajından arınmış

Benziyordu yaşlı yosmaya,

Ne var ki yine ihtişamlı

           Ölümüne güzel

           Hazır sevişmeye

Ve

Yeni günahlara günaydın demeye,

Elveda İstanbul

Ölümsüz aşkların mezarı

Konstantin’in günahı elveda.

Haydarpaşa istasyonunda

Anadolu ekspresi yanık yanık

İki kez çaldı düdüğünü

Daha ne İstanbul’a baktım...

Ne geriye,

Saat 7 yi geçmiş

Semanın doğusuna 

Pembelikler

Serpilmiş...', 'Elveda İstanbul                            Ölümsüz aşkların mezarı                           Konstantin''in günahı elveda... Bu benmiyim koll...', ARRAY['Türk Edebiyatı','Şiir','Haluk Mahmutoğulları']::text[], 8.5, '{"poet":"Haluk Mahmutoğulları","poet_slug":"haluk-mahmutogullari","theme":"Türk Şiiri","is_hero":false,"total_lines":168,"source_url":"https://www.antoloji.com/elveda-istanbul-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sırtım Sana Göre değildir', 'benim-sirtim-sana-gore-degildir-murat-demir-i39ex', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel olursa sıvazlama boşuna

Benim sırtım sana göre değildir

Tuzak kurup getirsende tuşuna

Benim tartım sana göre değildir

Sen insanı satıp çeker gidersin

Sen insanı tutup heder edersin

Sen ahtını bozar bozmadım dersin

Benim şartım sana göre değildir

Ben özümden taviz vermem ölsemde

Boyun eymem oyununa gelsemde

Hançerinle yüreğimi delsende

Benim tortum sana göre değildir

Sen güçlüyü sever garip ezersin

Sen mazluma söver seyif gezersin

Sen her şeyi yapar yapmadım dersin

Benim kortum sana göre değildir', 'Gel olursa sıvazlama boşuna Benim sırtım sana göre değildir Tuzak kurup getirsende tuşuna Benim tartım sana göre değildir Sen insanı satıp ç...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-sirtim-sana-gore-degildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-haluk-mahmutogullari-cqixq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Duyduğum ilk ses

Önce karnında

Sonra sırtında

Hep yüreğinde

Beni taşıyan

Azalmakta ki sevgi pınarının

Aşınmayan elmas kurnası anne

Söylediğim ilk söz 

Göz yaşlarında ben

Dualarında ben

Umutlarında ben

Solmakta ki sevgi çiçeklerinin

Tek dikensiz ve ölmez gülü anne...

Sevdiğim ilk kadın

Dönüşsüz yolculuğa çıktığımda 

Ah! Birde baş ucumda olabilsen

Ölüm yaşamaktan kolay olurda

Katlanır mısın bu acıya da sen? 

Kirlenmekte ki bu eski dünyanın

Tek taze ve temiz kalmışı Anne...

1984', 'Duyduğum ilk ses Önce karnında Sonra sırtında Hep yüreğinde Beni taşıyan Azalmakta ki sevgi pınarının Aşınmayan elmas kurnası anne Söylediği...', ARRAY['Türk Edebiyatı','Şiir','Haluk Mahmutoğulları']::text[], 8.5, '{"poet":"Haluk Mahmutoğulları","poet_slug":"haluk-mahmutogullari","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anne-129-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnşallah', 'i-nsallah-i-smet-barlioglu-aolc3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Arı gibi sana uğruyor yüreğim,

Kelebekler, kuşlar gibi sana uçuyor,

Seni arayıp duruyorum yıldızlar gibi,

Mehtap gibi,

Kumlarında ayışıklarının oynaştığı kumsal gibi,

Kumsalı öpen dalga ben oluyorum,

Işık oluyorum karanlık sulara vuran,

Sana bir olmadığım kalıyor

Kurban.

Vah benim yürüye yürüye eskittiğim yollarım, vah,

Vah menziline ulaşamayan yollarım,

Heyecanlar içinde çırpınıp duran yüreğim,

Vah benim özlemlerim,

Azaplarım, çilelerim, vah,

Birgün bu kahırlar biter de gider

İnşallah.

Hele bak ki; ne umutlara beller bağlamışım,

her biri ulaşılmaz birer dal,

her biri birer çıkmaz sokak,

her biri birer acıklı öykü,

Bir karasevdandır dilimde çığlığa dönen

Türkü.

Ecelle baş ettim bir ömür boyu,

Açlıkla, susuzlukla, uykusuzlukla baş ettim,

Çilelerle, acılarla, hüzünlerle,

Özlemlerle,

Açmazlarla baş ettim.

Fakat yüreğimle bir türlü baş edemedim,

Yüreğim benden hesabını sordu çektiklerinin,

Veremedim.

(KAFES İsimli Serbest Şiirler ''inden > 71-72/100)', 'Arı gibi sana uğruyor yüreğim, Kelebekler, kuşlar gibi sana uçuyor, Seni arayıp duruyorum yıldızlar gibi, Mehtap gibi, Kumlarında ayışıkları...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/insallah-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-i-smet-barlioglu-5l1ux', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sormadan anlatıyorlar seni,

Denizler; kendilerinden ne kadar hoşlandığını,

Rüzgarlar; saçlarını nasıl okşadıklarını,

Yağmur; saçlarını, omuzlarını

Güneş; nasıl oynaştığını ışıklarıyla çevrende,

Mehtap; nasıl her şeyi bırakıp sana baktığını,

Kumsal; izlerini nasıl bir özenle koruduğunu

Ve pırıltılı sular anlatıp duruyorlar

Kayalıklarda

Nasıl bir denizkızı gibi

Durduğunu.

Ben her gece dinlerim bu masalı,

Sabaha varamayan uykularıma dalmadan önce,

Rüzgarlardan dinlerim,

Denizden dinlerim,

Çamlardan, yosun kokularından, ormanlardan,

Vurup geçen gece kuşlarından,

Duvarlarımı yalayıp yalayıp silinen ışıklardan,

Dinlerim, dinlerim, dinlerim,

Uzak uzak ülkelerden

Sabahlara kadar bu masalı getirir durur

Gemilerim.

Sana kavuşmak için dalarım umut dolu uykulara,

Karabasanlarla uyanırım tam kavuşacakken,

Sonra yine uyku, yine karabasan,

Benim dinleyecek masallarım mı olurdu

Sen olmasan? 

(KAFES İsimli Serbest Şiirler ''inden > 73-74/100)', 'Sormadan anlatıyorlar seni, Denizler; kendilerinden ne kadar hoşlandığını, Rüzgarlar; saçlarını nasıl okşadıklarını, Yağmur; saçlarını, omuz...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/masal-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşlı Gözler', 'yasli-gozler-i-smet-barlioglu-uv4n4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neden gölgeler içinde kaldı yüzün

Yaşlı çınar altındaki göl suları gibi,

Neden sonbahar yaprakları gibi rengin,

Ceylan yavrusu gibi neden gözlerin yaşlı? 

Bana özlemli değilsin,

Çile-mile de çektirmedim sana,

Sen hele başını bir kaldırıp baksana

Bana.

Çamlıbellerden mi alınmış gözlerindeki bu sisler? 

Bu buğular çağlayan buğuları,

Dudaklarındaki bu ürperişler ürperiş değil, sevdam,

Hıçkırma yalvarırım, sanki ölmüşüm gibi,

Dayanamam.

Bizler zor günlerin sevdalısıyız,

Aşkımız hak edile edile alınmış kaderden,

Tadına varıla varıla alınmış,

Süslenmiş çilelerle,

Hüzünlerle,

Özlemlerle,

Biz bu karasevdanın diyetini verip de geçmişiz

Ömürle.

Ne oldu bizlere, sen biliyor musun,

Nedir bu durgunluk, deniz durgunluğu gibi,

Bu hüzün, bir sevda yorgunluğu gibi,

Üzülme, sana avuçlar dolusu sevgiler vereyim yüreğimden,

Saygılar göstereyim,

Yeter ki; sen bir kere gül,

Güller açsın yüzünde,

Ben

Öleyim.

(KAFES İsimli Serbest Şiirler ''inden > 75-76/100)', 'Neden gölgeler içinde kaldı yüzün Yaşlı çınar altındaki göl suları gibi, Neden sonbahar yaprakları gibi rengin, Ceylan yavrusu gibi neden gö...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yasli-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelir Diye Bekledim Giden Zamanı', 'gelir-diye-bekledim-giden-zamani-hakki-hakan-kaya-ydxbb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağıyordu

toprak göğe

buram buram 

hasret ile

kuruttu bulutlar

gözyaşlarını

hasret birikti

dökülemedi

çatlattı toprak

yüzünü

kavuşmayı bekledi

bükülemedi

yarıldı sevda tohumu

büyüttü hasretini

ne mevsimler geçti de

sökülemedi...', 'Yağıyordu toprak göğe buram buram  hasret ile kuruttu bulutlar gözyaşlarını hasret birikti dökülemedi çatlattı toprak yüzünü kavuşmayı bekle...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelir-diye-bekledim-giden-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Dönmek', 'geri-donmek-i-smet-barlioglu-t7htr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana ortak bir anımızı getirdim gençliğimizden,

Sularında akşam güneşinin yıkandığı denizden,

Avuçlarımda ıslak ve yumurta sarısı bir güneş,

Kucağımda ayaklarının altında altınlaşmış bir kumsal,

Ben sana,

Sen bana

Emsal.

Anımsar mısın, ayın çamlara süründüğü akşamı? 

Testekerlek, gümüş renkli ay,

Yarı aydınlık çimenler bölük bölük,

Çiçekler öbek öbek,

Karşımızda duvarları nur içindeki çiftlik evleri,

Yanında, eski değirmenin uysal suyu,

Nasıl haram etmiştik anımsar mısın, kendimize

Uykuyu.

Gençlik içimizde kaynaktı, elimizde hazine,

Uykusuzluk mu gelirdi insanın diline? 

Güneşleri aylara kavuşturmaktı işimiz,

Bütün bir evren bir yanaydı

Ve bir yanaydık

İkimiz.

Ben işte o anıları getirdim kucağımda,

Kulaklarımda hala küpe gibi duruyor şarkıların,

Gülüşlerin,

Yeni gülüşlere gebe çığlıkların,

Ömrünün geri kalanından vazgeçip

Geri dönesi geliyor

İnsanın.

(KAFES İsimli Serbest Şiirler ''inden > 77-78/100)', 'Sana ortak bir anımızı getirdim gençliğimizden, Sularında akşam güneşinin yıkandığı denizden, Avuçlarımda ıslak ve yumurta sarısı bir güneş,...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/geri-donmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karasevdamın Şerefine', 'karasevdamin-serefine-i-smet-barlioglu-bpem9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kadehimi karasevdama kaldırıyorum,

Bu kankırmızı şarap karasevdamın şerefine,

Şarabım kırmızı, sevdam kara,

Zerre kadar acımadım be sevdaya harcadığım yıllara,

Bebek gibi besledi sevdamı çilelerim,

Ayrılığım,

Hüznüm, besledi, büyüttü, yüceltti,

Gün oldu; tutup elimden engellerden geçirdi,

Gün oldu; 

Canıma yetti.

Kadeh kadeh içiyorum karasevdamı bir masada,

Yudum yudum içiyorum,

Karasevdama acılarımın acısı,

Acılarımda senin özlemlerin

Ve işte, yine gitmez oldu

Gözlerimin önünde,

Gözlerin.

Ben sarhoşu değilim meyhane kadehlerinin,

Adamı değilim bir ikiyüzlü dünyanın,

Ben sevdamın adamıyım,

Ben sevdamın sarhoşuyum,

Ondan dalıp dalıp giderim dopdolu kadehlerimde,

Nereye gittiğini bilmeyen küreksiz sandal gibi,

Bir solgun yaprak gibi bir deli rüzgar önünde,

Şereflere kaldırdığım kadehler boşalırken

Elimde.

(KAFES İsimli Serbest Şiirler ''inden > 79-80/100)', 'Kadehimi karasevdama kaldırıyorum, Bu kankırmızı şarap karasevdamın şerefine, Şarabım kırmızı, sevdam kara, Zerre kadar acımadım be sevdaya ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/karasevdamin-serefine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toz Pembe Boyalarla...', 'toz-pembe-boyalarla-i-brahim-ethem-bingul-gpaql', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneş kaç kez doğmuş, batmış

Ben uyumuşum.

İstekler kelepçe vurmuş ellerime

Gayeler unutulmuş

Arzuların yokuşlarında yorulmuşum...

Doğanlar görmüşüm... doğumu

Ölenler görmüşüm... ölümü

Düğünler görmüşüm... düğünü yaşamışım

En canlı

Ama hiç birine

Alışmamışım...

Anlamlı bakışlara gözümü kapamışım

Masalların dilinden Kaf Dağı''nın ardını

Anka''nın kanadını

Görmeye çalışmışım...

Hayal çiçekleriyle

Bahar gelmez, yaz olmaz

Gelincik tarlasında

Kelebekte naz olmaz...

Demişim de

Senelerdir boyalı resimlere

Bakıp bakıp durmuşum

Kartondan evler yapıp

Yıkılmaz hayaller kurmuşum

Deprem yeri dünyamda

Toz pembe boyalarla...', 'Güneş kaç kez doğmuş, batmış Ben uyumuşum. İstekler kelepçe vurmuş ellerime Gayeler unutulmuş Arzuların yokuşlarında yorulmuşum... Doğanlar ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/toz-pembe-boyalarla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Gerçek Mutluluk', 'gercek-mutluluk-bekir-gedikoglu-fmx2l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbimdeki acıyı giderecek aşk gerek

Gönlümdeki çiçeği yaşatacak yer gerek

Lazım olan sevgiyi verecek biri gerek

Tespih gibi dertlerim çekecek biri gerek

Kör olan gözlerimi açacak biri gerek

Lal olan dillerimi çözecek biri gerek

Şu kör talih bendeki yenecek biri gerek

Yardıma çok muhtacım edecek biri gerek

Sorunlarım kör düğüm koşacak biri gerek

Gittikçe batmaktayım tutacak biri gerek

Ağlayan gözlerimi silecek biri gerek

Gam yüküm ağırlaştı taşıyan biri gerek

Hayatıma gireni dünden tanımam gerek

İçimdeki sırları artık anlatmam gerek

Paylaştığım hayatı sonsuz yaşamam gerek

Mutluluğun tadını herkese yaymam gerek

Ankara 31.03.2005', 'Kalbimdeki acıyı giderecek aşk gerek Gönlümdeki çiçeği yaşatacak yer gerek Lazım olan sevgiyi verecek biri gerek Tespih gibi dertlerim çekec...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gercek-mutluluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suret', 'suret-cigdem-bir-genc-2n4q9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kırıldı ayna! 

etrafa saçıldı tek tek suretler 

suretler...

aynadan arta kalan cam kırığı

bir suret kesti şiirimin şah damarını

acıyla böğürdü bir imge! 

sen lal! 

çıt çıkmıyordu gözlerinden

gözlerin...

durgun göller...

ve yıldızsız bir gece gibi başıboş

ve aşk bitti...

ve aşk yitti...

bir şiir kaydı gözlerinden... 

şiir aşkına sustum...', 'kırıldı ayna!  etrafa saçıldı tek tek suretler  suretler... aynadan arta kalan cam kırığı bir suret kesti şiirimin şah damarını acıyla böğür...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/suret-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader Yaşansın', 'kader-yasansin-mehmet-cetinkaya-o7dnh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mazideki her günümde sen varsın

Mutluluğa ilaç aşkıma yarasın

Bilemedim ki sen bana neden yarsın

Bırak bize yazılan kader yaşansın

Oysa senin yüzüne bakıp gülerken

Dilinden dökülen acı sözler neden

Seninle geçen ömrü kül etsen de sen

Bırak bize yazılan kader yaşansın

Bende isterdim seninle mutlu olmak

Mutluluk ve sevinç içinde ağlamak

Yetmiyor canım aşk için güzel olmak

Bırak bize yazılan kader yaşansın

(07.03.2005 14.15)', 'Mazideki her günümde sen varsın Mutluluğa ilaç aşkıma yarasın Bilemedim ki sen bana neden yarsın Bırak bize yazılan kader yaşansın Oysa seni...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çetinkaya']::text[], 8.5, '{"poet":"Mehmet Çetinkaya","poet_slug":"mehmet-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kader-yasansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Abla', 'gonul-abla-mehmet-cetinkaya-tclzk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nerede o eski aşklar, utana sıkıla yaşananlar

Mutluluğa doğru uzanan pembe sevdalar

Şimdi ise reklam bile yapıyorlar, aşık oldum diye

Vallahi madalya verecekler, sevdiğiyle evlenene

Ah Gönül abla, sen olsaydın tüm madalyaları alırdın

Neyse boş ver... Çünkü sen aşkını reklam yapmazdın

On altılık taze bıyık, on sekizlik delikanlı, otuzluk yeni evli

Hepsinin de aşkları sendin, Gönül Abla, besbelli

Laf atan olmazdı, biz sevemedik derlerdi içinden

Sen yürüdükçe aşk hikayelerin yürürdü peşinden

Taş gibiydin be taş, büken olmazdı bileğinden

Her baba yiğit geçemezdi pencerenin önünden

Ben on üçümdeyken nasıl aşık olunur derdim

Aşk, mangal gibi yürek istermiş, on sekizde öğrendim

Senin aşkların okul gibiydi gençlere

Selam bile vermezdin terbiyesizlere

Ah o yabancı, içimize düşürdü sızı

Alıverdi mahallemizden senin gibi kızı

Taşlayasımız geldi o gün gelin arabanızı

Yapamadık be Gönül abla, atamadık taşları

Senden öğrendik yaşanacak en güzel aşkları

(29,01,2003  23:55) 

(Tavşanlı)', 'Nerede o eski aşklar, utana sıkıla yaşananlar Mutluluğa doğru uzanan pembe sevdalar Şimdi ise reklam bile yapıyorlar, aşık oldum diye Vallah...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çetinkaya']::text[], 8.5, '{"poet":"Mehmet Çetinkaya","poet_slug":"mehmet-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gonul-abla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zile''ye Sevdalanmak...', 'zile-ye-sevdalanmak-kazim-basekmekci-21a70', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sabahında simit satan çocukları,

Onlarla uyanmak, yeni bir güne.

Emeğin kokusunu duymak susamda.

İşçi kahvesinde bir yudum çay içmek.

Bir simidi paylaşmak, bir de tütünü.

Gündelikçi bacımı seyretmek,

Pancar tarlalarında.

Ve emeğe sevdalanmak...

Haziran’da bağlarında oturmak,

Kirazları küpe yapmak kulağa.

Kirtiğini, sarısını, alını...

Sepetlere tane tane doldurmak.

Tepsi tepsi dağıtmak komşulara.

Güz gelince,

Üzüm ezip, kömeleri batırmak.

Kazandibi pestilini, parmak parmak yalayıp

Ağızları tatlandırmak,

Ve doğaya sevdalanmak.

Zerdali ağacına tırmanmak,

Karıncalarla birlikte.

İlkyazın iğde koklamak, çay kenarında.

Yazın yaprak kırıp deveklerinden

Güzün gazel toplamak, sacın altına.

Ve kışa sevdalanmak...

İftar vakti, pide için yarışmak,

Top sesini beklemek pencerelerde.

Davet verip tüm dostlara

Türlü türlü ikramlarda bulunmak.

Teravih’te cami cami dolaşmak.

Sokaklarda konuşmak, sahura kadar.

Muharrem’de dumanı tüten aşureyi,

Kapı kapı gezinerek dağıtmak.

Geceleri evliyada mum yakmak

Ve duaya sevdalanmak...

Çocuk iken, top koşturmak Kale’sinde

Bir dizini kanatmak, bir de geçmişi.

Bozova’ya tepeden bakıp kartal gibi.

Gücünü hissetmek Sezar’la birlikte.

Burçlarında süzülmek, rüzgarla.

Ve yükseklere sevdalanmak...

İlkbahar’da bağlarında bülbülle,

Meşk ederken, seyreylemek bir gülü.

Dağlarında menekşeyi, sümbülü.

Ezgilerde dinleyip de, aşıktan.

Türkülerle dolaştırıp, dillerde,

Ve türküye sevdalanmak.

Curfalık’ta çul dokuyan abamı.

Yemeniye oya dizen anamı.

Motif motif izleyip de kenardan

Ve türklüğe sevdalanmak...

Bir güzeli seyretmek, kına gecesinde.

Avucunun orta yerine kına yakınmak.

Mendilini sallamak, halaybaşında.

Güvey hamamında, kaynar sular dökünmek.

Tutuşturup yüreğindeki ateşi,

Ve aşka sevdalanmak...

Bağdaş kurup, bir sofranın başında,

İşkefeyi sunak yapmak,madımağa.

Her sokumda hatırlamak komşuyu.

Lokmaları boğazına dizip de.

Ve dostluğa sevdalanmak...

Yaban eli, diyar diyar dolaşmak,

Hasreti yaşamak yüreğinde.

Her nefeste iç çekerek derinden,

Gurbet elde bulamamak, o demi,

Havasına sevdalanmak, suyuna...

Ve Zile’ye sevdalanmak...', 'Sabahında simit satan çocukları, Onlarla uyanmak, yeni bir güne. Emeğin kokusunu duymak susamda. İşçi kahvesinde bir yudum çay içmek. Bir si...', ARRAY['Türk Edebiyatı','Şiir','Kazım Başekmekçi']::text[], 8.5, '{"poet":"Kazım Başekmekçi","poet_slug":"kazim-basekmekci","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/zile-ye-sevdalanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuzeyin Işıkları', 'kuzeyin-isiklari-avni-aydin-cw7f8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kuzeyin ışıkları...

ne kadar yalnızsınız

belki mutluluktan,

belki de aşktan bihabersiniz.

her gece aydınlattığınız buzlar ülkesinde,

aşka da rastlamazsınız keza...

acıyla karışık dünya gecelerinde,

aydınlatın tüm karanlıkları

mutsuzluğa inat...

belki güneyde bir sahil kentinde

yüzünüzü bir kez olsun görmeden...

ya da soğuk bir kış gecesinde petersburg''un

donmuş gölün üstündeki aşıklar misali...

ulaşın ulaşanildiğiniz yere,

kadere inat 

kederli yüzlere...', 'kuzeyin ışıkları... ne kadar yalnızsınız belki mutluluktan, belki de aşktan bihabersiniz. her gece aydınlattığınız buzlar ülkesinde, aşka da...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kuzeyin-isiklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Bakış', 'hayata-bakis-suleyman-kaya-al48w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat ne garip

Bir acı bir tatlı

Ölüm ile Yaşam iç içe

Sevinç ile Keder

İç içe olmuş bir kardeş gibi

Hayata direnen Yeldeğirmeni,misali

Acıyla yoğrulmak,tadına varmakmış

Meğerse tadı Acıyı yaşamakmış

Hayat bir Garip

An olur yaşamak bir masal gibi

Bir varmış bir yokmuş 

An olur yaşamak kayan bir yıldız misali.', 'Hayat ne garip Bir acı bir tatlı Ölüm ile Yaşam iç içe Sevinç ile Keder İç içe olmuş bir kardeş gibi Hayata direnen Yeldeğirmeni,misali Acıy...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Kaya']::text[], 8.5, '{"poet":"Süleyman Kaya","poet_slug":"suleyman-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayata-bakis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koş', 'kos-ziya-nizam-cr55l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir umut oldun

Bin gözyaşı döktüm.

Sana hayaller adadım

Yıkık dökük bir harabe bıraktın.

Mutlu musun ya şimdi.

Seviyor musun onu

Ya o

O da seviyor mu seni

O da dağ yelleri getiriyor mu

Sana ciğerlerce.

Kalbinde sen atıyor musun

Sevgi dolu,damarlarını yırtarcasına.

O da deli oluyor mu sana.

İyi o zaman.

Hadi koş ona.

			13.12.1998-Pazar

			00:10 Radyo Mavideniz Rize', 'Bir umut oldun Bin gözyaşı döktüm. Sana hayaller adadım Yıkık dökük bir harabe bıraktın. Mutlu musun ya şimdi. Seviyor musun onu Ya o O da s...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kos-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerimden Kaçırdığım', 'gozlerimden-kacirdigim-ziya-nizam-p7gdk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerimden kaçırdığım yarimsin bu gece.

İstiyorum diyemediğimsin.

Alsam,kollarımda kalsan ömrümce.

Yandığımı haykırsam sana sessizce.

Yaşamak dediğin nedir

Seni senle yaşayamadıktan sonra.

Ölmektir aslolan

	Senden uzaklarda.

			24.07.2004-Cumartesi

			01:08 Avcılar', 'Gözlerimden kaçırdığım yarimsin bu gece. İstiyorum diyemediğimsin. Alsam,kollarımda kalsan ömrümce. Yandığımı haykırsam sana sessizce. Yaşam...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozlerimden-kacirdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kor kor olsa', 'kor-kor-olsa-nese-ersoy-rmd4q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'şehir geçiyor gözümden

puslu, çıplak, kan şehir

ne yana dönsem ucuz pırlanta

her yanı acil servis

aşkım aceleye gelmez ki benim

güz ateşi gibi serin de olsa

baharın tozu duruyor ayaklarımda

bir kıvılcım tabanlarımdan tutuşturuyor

ateşler karıyor ellerim

canım yanıyor, içim acıyor

acıyor bu sevda

sisler oturuyor içimdeki bahçelere

kanı çekiliyor her gül yaprağının

yıllar çoğalıyor,  yıllar yitiyor

hani yaşamaktı kavlim 

ekmeği elde sevdayı tende

kor, kor olsaydı, yansaydı elim

cezaya bırakılmış gibi

bayat mevsimler solutsa da bahçesi

o teneffüsünde

ben hep kendimdeyim

ah bu şehirde

reddediyor doğmayı sevinçlerim...', 'şehir geçiyor gözümden puslu, çıplak, kan şehir ne yana dönsem ucuz pırlanta her yanı acil servis aşkım aceleye gelmez ki benim güz ateşi gi...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kor-kor-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoruh’un kızı', 'coruh-un-kizi-nese-ersoy-9rvrs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'aşk damıtıyor dağlarım

dörtnala karadenizken kavlim

hırçın, öfkeli ve hassas

derinlerinden kaçkar’ın

seher taşıyorum öğle sıcaklarına

uykuya ter döküyor

sevdalar yitiriyor zaman

okyanuslar uçuruyor koynumdan

dönerken denizine aşk

salınıp türkü oluyorum âşığın sazına

vuruyor, dönüyor topuklar bir ağız

“daldalan daldalan daldan aşağı”

akıyor

ağaçlarda kestane

yükseklerde çetin cevizler

ademin eline elma

gül yüzlü bebelerin diline

anne oluyorum

varlığım kadar göğüm

volkanlar boşalır kirlenir ışığım

kaçkar’ın karı da yetmez bağrıma

asiliğim sesinde dingin, dokunuşunda

al koynunda uyut buklelerimi

hüzün açmasın toprak

koksun öpüşmelerimiz

dağlarda doğdum, yabanda

o deli akar ben dolu dolu

gelemem bentlere

çoruh kızıyım.', 'aşk damıtıyor dağlarım dörtnala karadenizken kavlim hırçın, öfkeli ve hassas derinlerinden kaçkar’ın seher taşıyorum öğle sıcaklarına uykuya...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/coruh-un-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diğer Yarımı Hiç Sorma', 'diger-yarimi-hic-sorma-murat-ceylan-49cg2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne garip yaşıyorum hayatı tastamam

Bak sol elim günahta sağ elim sevapta

Kalmadı artık bu savaşta takatim

Bir ayağım çukurda diğeri bulutta

Bak aldığım her nefes yaklaştırıyor beni

Adım adım ölümün eşiğine gönüllüce

Tutamıyorum artık zamanın ipini

Bir gözüm ahirete bakar diğeri dünyada

Tutma elimi ey benim gibi ölümlü insan

Kurtaracaksan git de önce kendini kurtar

Kalmadı bende mantık, kalmadı lisan

Bir yarım yok olmuş diğer yarımı ise hiç sorma

                                                 Murat Ceylan', 'Ne garip yaşıyorum hayatı tastamam Bak sol elim günahta sağ elim sevapta Kalmadı artık bu savaşta takatim Bir ayağım çukurda diğeri bulutta ...', ARRAY['Türk Edebiyatı','Şiir','Murat Ceylan']::text[], 8.5, '{"poet":"Murat Ceylan","poet_slug":"murat-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/diger-yarimi-hic-sorma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapkara Ölüm', 'kapkara-olum-deniz-yilmaz-eralp-dr2ti', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölüme o kadar yakınım ki,

Her an sıcaklığını hissediyorum..

Bütün bedenimde,

Bütün benliğimde O''nu

Bana o kadar yakın ki,

Bir gölge gibi arkamda dolaşan

Beni bir an bile yalnız bırakmayan

O ucsuz bucaksız ölüm

Bir an bile düşünmediğim

Hayalini bile kurmadığım

Kurmak bile istemediğim

O kapkara ölüm.

İnsan; doğar, yaşar ve ölür

Var mıdır bunun ötesi......', 'Ölüme o kadar yakınım ki, Her an sıcaklığını hissediyorum.. Bütün bedenimde, Bütün benliğimde O''nu Bana o kadar yakın ki, Bir gölge gibi ark...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yılmaz Eralp']::text[], 8.5, '{"poet":"Deniz Yılmaz Eralp","poet_slug":"deniz-yilmaz-eralp","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kapkara-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün şehri', 'surgun-sehri-nese-ersoy-yf5l7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yine sancıya duruyor gün batımı

nerede başlasam, inadına bitiyor

			orada aşk

hüzündür mevsim şimdi

soyundukça gök örtünür toprak

örtünür de ayrılıklara düşer yolum

alır başını gider birisi

yitik bir sevdanın çığırtkanı olurum

uykusuna düş bu şehrin

munis, şımarık, ürkek

göksüz bir yıldız olurum

menekşesi mor yine de ateşi kızıl

yangınımı kutsar bu şehir, sangılarımı

hatırım olmasa soluğunda

ve hatırı soluğumda

hangi telâşa sığar ömrüm

hangi uykuya az gelirim

değsin istedim yanmışlığıma

gelincikler açar elimde kor kor

sahralara savrulurum yeniden

hararetim kemikleşir

hiçliğe artar küllerim 

hiçlik her şeyken, ya da her şey hiç

hangi çölümü yeşertmeliyim önce

hangi tavımı gömmeliyim

ne denli koşsam

o denli geçim her şeye

kilit vurmuş duygulara

aşk mıydı iki yüzlü, yürek mi

çözemedim

büyümeden ölmeliydim aslında

düş kıvamlı gün biter

şavkına düşerim gecenin

anılarım darmadağın, salkım saçak

yoğunlaşır döngülerim

yüzdeye vurulur hata payları 

ne sarhoşum ne de çocuk

kusuruma bakın lütfen

ey yaşam

hadi, kanat göğümü

ufuklarımı yık

görüntüsüz gölgeler işle yarına

aşkın uzak şehrinde sürgün

göğümü arıyorum', 'yine sancıya duruyor gün batımı nerede başlasam, inadına bitiyor 			orada aşk hüzündür mevsim şimdi soyundukça gök örtünür toprak örtünür de...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/surgun-sehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız zamanlar', 'adsiz-zamanlar-nese-ersoy-h3r5g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'biraz mahcup, utangaç

cüretkâr kimi zaman

soluk soluğa

	tenimden

		misafir gibi...

				

hep yarım kalır bir şeyler

ve öksüz tırnak uçlarım

 bir “hoşça kal”da erir 		

rehavetim...', 'biraz mahcup, utangaç cüretkâr kimi zaman soluk soluğa 	tenimden 		misafir gibi... 				 hep yarım kalır bir şeyler ve öksüz tırnak uçlarım  ...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/adsiz-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara’da mevsim', 'ankara-da-mevsim-nese-ersoy-benj1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bu yıl da mevsimi geçti ankara’nın

yine başladı yağmurlar

puslu sabahlara açılır gözlerimiz

yine şemsiyeler tutar ellerimiz

ne kış olduğunu biliriz mevsimin

ne sonbahar

balçık içinde ezilir gider

güzelim sarı-kızıl yapraklar

kent kasvete bürünür sinsice

gurup görünmez olur akşamlarında

bulanık sular birikir her biri tuzak

sokaklarında

bu beşinci mevsimi ankara’nın

güzden kurtulmuş kışa gebe

hüzünlü telaşlar yaşanır

bütün evlerde

yediverenler ne açmayı bilir, ne solmayı

gezilecek keyfi kalmaz akşamların

bu halini de severim ben

ankara’nın', 'bu yıl da mevsimi geçti ankara’nın yine başladı yağmurlar puslu sabahlara açılır gözlerimiz yine şemsiyeler tutar ellerimiz ne kış olduğunu ...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ankara-da-mevsim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zindan', 'zindan-deniz-yilmaz-eralp-mha9h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanlık bir zindandayım

Öyle karanlık ki

Güneş değmemiş duvarlarına

Kapkara olmuş vücudum

Ama bu karanlık, 

Gecenin karanlığı değil.

Zindanın  karanlığı, 

Sinmiş üzerime.

Her yanım zindan kokuyor.

Her yer rutubet içinde,

Sular damlıyor tavanlarından.

Örümcek bağlamış duvarlar,

Kalbim gibi oda ağ bağlamış.

İğne deliği kadar ışık,

Vuruyor karşı duvara.

Evet! hava yine bugün 

Güneşli olsa gerek.

Gece gündüz uyumadan,

Ama hiç gözümü bile kırpmadan

Seni düşünüyorum.

Tek tesellim,

Bir fotoğrafın ve anılar.........', 'Karanlık bir zindandayım Öyle karanlık ki Güneş değmemiş duvarlarına Kapkara olmuş vücudum Ama bu karanlık,  Gecenin karanlığı değil. Zindan...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yılmaz Eralp']::text[], 8.5, '{"poet":"Deniz Yılmaz Eralp","poet_slug":"deniz-yilmaz-eralp","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/zindan-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolunay', 'dolunay-deniz-yilmaz-eralp-ieo7b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Evet! 

Bugün yine dolunay var.

Bitti bu hasret

Günlerce, haftalarca 

Beklediğim canım ay.

Severim seninle konuşmayı,

Beni tek dinleyen sensin,

Tek dert ortağım

Hiç bir şey söylemeden dinleyen.

Seninle sabahlara, 

Kadar konuşurduk.

Bir kere kaybolduğunda,

Yolunu gözlerdim hep.

Şafak sayardım,

Günlerce, haftalarca

Merak ederdim ne zaman

Döneceksin diye...', 'Evet!  Bugün yine dolunay var. Bitti bu hasret Günlerce, haftalarca  Beklediğim canım ay. Severim seninle konuşmayı, Beni tek dinleyen sensi...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yılmaz Eralp']::text[], 8.5, '{"poet":"Deniz Yılmaz Eralp","poet_slug":"deniz-yilmaz-eralp","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dolunay-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatırla', 'beni-hatirla-meral-yagcioglu-kr0bm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeniden sevdiğinde

Aşkı tadınca yüreğin

Benim sevda volkanımı düşün

Karşılaştır aşk derecesini

Farkı tavana vurduğunda

Beni hatırla unutama hiç

İlk ateşli öpüşünde

Benim sende bıraktığım

Kulağının arkasına taktığın

Masum beyaz busemi düşün

Ve şimdi dudaklarımda biten ısırganı

Beni hatırla unutama hiç

Sokakta yürürken aylak aylak

Yada neşeli bir kahvaltı  sofrasında 

Sıcacık çayını yudumlarken

Radyoda çalan sevda türkümüzü duyunca    

Beni hatırla unutama hiç

Her sigara yakışında

 “söndür şu mereti”diyerek

 Zararlarını anlatışımı

Ve hiçbir zaman vazgeçmediğini düşün

Beni hatırla unutama hiç

En mutlu anlarında

Kahkahaların çınladığında

Arkadaşlarınla yaptığın

En koyu sohbetlerde

Güzel vakit geçirdiğimiz

Yıldız Parkındaki o tatlı

Muhabbetlerimizi düşün

Beni hatırla unutama hiç

Soğuk kış günü pencerene konan

Minik serçe açlıktan ötemiyorsa

Avucuna alıp nefesinde ısıtmaya

Çalıştığın  zor dakikada

Bir damlacık hayat suyu

Bıraktığında gagasına

Yaşamla ölüm çizgisi arasında

O çaresiz med-cezir de

Yüreğimin donarak ellerinde öldüğünü düşün 

Beni hatırla unutama hiç	

Her ayrılış hüsranında

Çırpınırken sevda denizinde

Yüreğindeki alev yüzünü yalarken acı acı

Tütsülenirken bedenin

Göz yaşlarında yüzerken çaresiz 

Yangın sevdamı düşün

Beni hatırla unutama hiç

Her gece rüyalarında gör 

Her gün, her nefes de

Unutamadığımı bil

Sevip sevmediğini düşüm

Sevdiğimi hatırla unutama hiç

		15/08/2003', 'Yeniden sevdiğinde Aşkı tadınca yüreğin Benim sevda volkanımı düşün Karşılaştır aşk derecesini Farkı tavana vurduğunda Beni hatırla unutama ...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/beni-hatirla-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-dilan-tan-enlfa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni tanıdığım an hayatım değişti.

Sen celladıydın mutluluğumun,

Sen hırsızıydın hayallerimin.

Dumanlı sevdamın...

Kaç yangın söndürdüm kalbimde sen gelmedin...

Kaç fırtına dindi çılgın yağmurlarda sen nerdeydin? 

Kaç deli bahar küstü gitti, sen başka mevsimlerdeydin...

Kaç kez titredi gönlüm kapıyı çalan sensin diye,

Hiç bilmedin bilemezdin...

Dün senle yürüdüğümüz yollardan geçtim,

Kaldırımlarda adımlarını takip ettim

Ellerini hayal ettim sıcacıktı yine,

Ne kalabalıkmış sokaklar kaldırımlar çok dar...

Yeni farkettim ve gülümsedim ve  özledim...', 'Seni tanıdığım an hayatım değişti. Sen celladıydın mutluluğumun, Sen hırsızıydın hayallerimin. Dumanlı sevdamın... Kaç yangın söndürdüm kalb...', ARRAY['Türk Edebiyatı','Şiir','Dilan Tan']::text[], 8.5, '{"poet":"Dilan Tan","poet_slug":"dilan-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ozledim-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trabzon-Boztepe', 'trabzon-boztepe-deniz-yilmaz-eralp-3hgus', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin alaca karanlığında,

Yağmur damlalarının,

Tenine dokunduğu anda.

Vücudunun titreyerek

Omuzunda tüfekle,

İzledin mi hiç Boztepe''den  Trabzon''u.

Her gece nöbete kalktığında

Avucunu yakarak yudumladığın

Sigaranın her dumanında

Bir an bile aklından çıkmayan

Sevgilini düşünerek

İzledin mi hiç Boztepe''den  Trabzon''u.

Gök yüzünü kaplamış

Renk cümbüşü

Güneş batarken şafağın

O muhteşem tonuyla

Denize yansıdığını

Asker gözüyle izledin mi Trabzon''u.

Yaşlarla ıslanmış,

Göz kapaklarını aralayarak,

Güneşin doğduğu sırada,

Vururken dalgaların sarhoşça sahile,

Kuş sesleri eşliğinde

İzledin mi hiç Trabzon''u böyle delice.

26/08/1995 - Boztepe', 'Gecenin alaca karanlığında, Yağmur damlalarının, Tenine dokunduğu anda. Vücudunun titreyerek Omuzunda tüfekle, İzledin mi hiç Boztepe''den  T...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yılmaz Eralp']::text[], 8.5, '{"poet":"Deniz Yılmaz Eralp","poet_slug":"deniz-yilmaz-eralp","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/trabzon-boztepe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Yanımda Çelişkiler Yumağı', 'her-yanimda-celiskiler-yumagi-melih-coskun-zk6cz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her yanımda çelişkiler yumağı 

Son model bir arabanın ısıtmalı koltuğunda 

Devrim türküleri okumak kadar,

Ruhumuzu aldatmıştık oysa hepimiz 

Çünkü gerçek savaşçıların payına düşen 

Sadece acılardı

Ve buydu elbette onları her zaman haklı kılan   

Hangi umudu tazeler doğacak güneş 

Belki biraz ısıtır sadece üşüyen düşlerimizi. 

Çoktan unutmuşuz deliksiz gece uykularını 

Taze ekmeği, 

Sıcak bir odayı. 

Onun için dedik ki sana ey halkım 

En gerçeği budur sevebilmenin 

Yine duman kapladı aşılmaz dağların zirvesini. 

Üşüyorum 

Yok ellerimi tutabilecek kimse.

Düşüyorum

Kederin sarp yamaçlarından. 

Sadece bir bakışın yeter bana ey yar 

Ellerin olmasa da

Her şeye rağmen ayakta durmama 

Bir gülüşün yeter 

Sabahsız gecelerde buz tutmuş yüreğimi ısıtmaya.

Unutma beni en gerçek sevdam 

Biz seninle birlikte yenmeyi öğrendik acılarımızı…', 'Her yanımda çelişkiler yumağı  Son model bir arabanın ısıtmalı koltuğunda  Devrim türküleri okumak kadar, Ruhumuzu aldatmıştık oysa hepimiz ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/her-yanimda-celiskiler-yumagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Ada''da Piknik', 'buyuk-ada-da-piknik-gulsen-senderin-mdgku', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne hoş bir duygu; yıllar sonra paytona binmek

Bir yanda yeşil alan, bir yanda mavi sular

Ne güzel çamlar altı piknik yapıp eğlenmek

Romantik bir ortamda bulut bulut duyular

Ne de güzel eğlendik,  beş şair beş kafadar...

Tavla kağıt oynadık, kahve iştik kömürde

Martı, karga, kedi ne varsa yedirdik kırda

Kimi denize girdik,  kimi uzandık yerde

Yaşanan güzellikler baki kalır ömürde

Ne de güzel eğlendik,  beş şair beş kafadar...

İçki masası kurduk gölgeler uzanırken

Büyülendik adeta gün batımı yanarken

Sohbet muhabbet sevgi içten içe sararken

Buğulandı yürekler geçmişleri anarken

Ne de güzel eğlendik,  beş şair beş kafadar...

Elimizde çantalar bayır aşağı indik

Şarkı türkü söylerken çocuklar gibi şendik

Yolda fıkra anlatıp şakalaşıp eğlendik

Ya havlayan köpekten, nasıl da kovalandık

Ne de güzel eğlendik, beş şair beş kafadar...

Tek tek Kınalı, Burgaz, Heybeli, Büyük Ada

Yaşam çığlıklarıyla can bulur Marmara''da

Bir de mehtabın aksi hem deniz hem karada

Seyrine doyum olmaz dostlarla birarada

Ne de güzel  eğlendik,  beş şair beş kafadar...

03-09-2004.Cuma

Büyük Ada', 'Ne hoş bir duygu; yıllar sonra paytona binmek Bir yanda yeşil alan, bir yanda mavi sular Ne güzel çamlar altı piknik yapıp eğlenmek Romantik...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/buyuk-ada-da-piknik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Gönder Canan', 'bana-gonder-canan-mustafa-karamelek-3cbu6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Berbat bir sancı 

Musallat olmuş sana; 

Hem de sana ha.

Nice hak edenler varken

Nice her şeyi çirkinler varken,

Seni mi buldu bu musibet.

Bak, şimdi üzüldüm

Seni hep mutlu

Hep güzellikler içinde düşlerken

Nerden söyledin şimdi

Nasıl dilin vardı söylemeye

Beni bir daha bitirmeye

Ne kadar da hevesliymişsin..

Bakma dediklerime 

Ben alışkınım sancılara sızılara

Ha beş ha on ne fark eder

Hasretini özlemini çekiyorum yıllardır

Derdini de çeksem ne olur.

Yabancısı değilim kederin derdin

Bana geleydi sen üzülmeseydin

Benim olaydı sancın sızın

Bilirim göndermezsin sevgini

Hiç olmaz sa

Umarsızlıklarını bana gönder

Senden gelecek her cefa emanetindir.

Başım gözüm üstüne 

Senin her derdin

Hoş gelir sefa gelir

Beni dertler iyi tanır

Bana gönder canan.

Bana gönder……', 'Berbat bir sancı  Musallat olmuş sana;  Hem de sana ha. Nice hak edenler varken Nice her şeyi çirkinler varken, Seni mi buldu bu musibet. Ba...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Karamelek']::text[], 8.5, '{"poet":"Mustafa Karamelek","poet_slug":"mustafa-karamelek","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bana-gonder-canan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar', 'yollar-nur-demirciler-4pysk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yollar arıyorum kendime,

Hergün yeni yollar... 

Sözler veriyorum sonra kendime,

Hergün yeni sözler... 

Belki tutamayacağım ama,

Yine de hep verilen sözler... 

He hüzün olacak,

Ne ayrılıklar,

Ne yalandan sevmeler... 

Ne de yalnızlıklar...

Çıktığım en güzel yol,

Vardığım en güzel son olmalı, 

Yollar hep sana açık olmalı... 

Ne yeni yollar çizeyim uğruna,

Ne de sözler vereyim kendime,

Varayım artık yolun sonuna,

Bekleyenim sen ol ama....', 'Yollar arıyorum kendime, Hergün yeni yollar...  Sözler veriyorum sonra kendime, Hergün yeni sözler...  Belki tutamayacağım ama, Yine de hep ...', ARRAY['Türk Edebiyatı','Şiir','Nur Demirciler']::text[], 8.5, '{"poet":"Nur Demirciler","poet_slug":"nur-demirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yollar-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygularım İsyana kalktı', 'duygularim-i-syana-kalkti-emel-manav-4vkxv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kadın var! İçimde sakladığım, 

Duygularını, arzularını kısıtladığım 

Bunca kalabalık içinde / hırçın 

Yalnızlığın koynuna bıraktığım 

Kelepçelenmiş ruhu, örselenmiş, 

Prangasız esaretine isyan ediyor 

Aynalara her baktığında mahsun 

“Kadınım ben, kadın”/ artık anlayın 

Anlayın beni” diyor 

Saten çarşaflar, ipek askılı gecelikler, 

Ve düşlerde yaşanan fanteziler, 

Koca bir ömür akıp giden/ zamanda 

Ele avuca sığmayan, dizginlenemeyen 

Dinliyorum o sesi/ ıslak gözlerle 

Seyrediyorum paramparça aynaya  düşen aksi 

Yaşananlar çok acı 

Ben değil sanki oradaki 

Hakkı, bütün güzellikler  hakkı 

Ve layıkıyla yaşamalı 

Sunu: 

Ruh eşini bulamayışı kaderi 

Ne pazarda satılır, ne bağışlanır 

Bir bilseniz çaresizlik 

Yüreği nasılda acıtır.', 'Bir kadın var! İçimde sakladığım,  Duygularını, arzularını kısıtladığım  Bunca kalabalık içinde / hırçın  Yalnızlığın koynuna bıraktığım  Ke...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/duygularim-isyana-kalkti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Verdim Aşka', 'yol-verdim-aska-i-lknur-cekici-rqosk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana göre değil yaşamak

Yaşarken mutlu olmak

Hüzün dolu bir hayat

Yaşadım yoğrularak

Beklentilerle dolu

Bir ömrü tükettim

Gençliğimin baharında

Sevgisizliğe itildim

Oysa hayale konan

Güzel bir kelebektim

Hayalim kabus oldu

Gün yüzü göremedim

Aradım taradım

Sevgiyi bulamadım

Yoruldum bu hayatta

Yol verdim artık aşka', 'Bana göre değil yaşamak Yaşarken mutlu olmak Hüzün dolu bir hayat Yaşadım yoğrularak Beklentilerle dolu Bir ömrü tükettim Gençliğimin baharı...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yol-verdim-aska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Dünyam', 'benim-dunyam-mehmet-feyzullah-aydin-hy72a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir dünya istiyorum; 

      Huzur dolu,sevgi dolu,

           Barış ve kardeşliğin yaşandığı,

İnsanca yaşamın sembolü olan bir dünya.

Kara bulutlar çöksün istemiyorum

	Memleketimin semalarına,

İnsanları yalan söylemesin istiyorum.

Türk diye mutlu olan,

Kürt diye ezilen,

Laz diye alay edilen,

İngiliz diye  övünen,

Zenci diye hor görülen,

	Kadın diye geri plana atılan

				Ve 

Yaşamın acımasız şartlarında acımasızca süren savaşları, istemiyorum 

					Bu dünyamda…

Görmek istemiyorum bu dünyamda; 

	Ne kalpazanı,

		Ne mafyayı,

			Ne anarşiyi,

Ne de kör aydınları…

Eşit bölüşülsün istiyorum topraklarım.

	Herkesin çalışabileceği bir işi,

		Evinde pişireceği bir aş’ı olsun istiyorum.

Gözü dönmüş katilleri olsun istemiyorum bu dünyamda…

Öğretmeni dürüst,

Öğrencileri çalışkan olsun istiyorum.

Olsun ki; yarınlarına ümitle bakan,

Barışı seven,insanların mutluluğu için çalışan nesiller yetişsin bu dünyamda.

Yakılması o güzelim köyüm,

	Bağım,

		Bahçem, meyve ağaçlarım,

Uyutmasınlar, sahte politikacılar beni,

Aldatmasın.

Yalan söylemesinler gözüme baka baka,

	Çalmasınlar paralarımı,hırsııızlar, rüşvetçileeer,dolandırıcılar.

İdam kararları çıkmasın meclisimden,

işkence görmesin insanlarım; karakollarda hapishanelerde.

Adil kararlar alınsın mahkemelerimde,

Sözde değil özünde bağımsız olsun yargıçlarım.

Yalanı,

Dolanı,

Rüşvetçiyi savunan avukatları olmasın bu dünyamda…

Bu benden geri,

	Bu dinci,

		Bu komünist,

			Bu faşist,bu terörist demesin kimse başka birine…

Çiçekler açsın bahçelerimde,

	Her renkten,her çeşitten olsun istiyorum.

Dağlarım çıplak ovalarım çorak olmasın istiyorum.

Kurutulmasın kökü yediverenimin,

Ağlamasın yavrusunu kaybetmiş ceylanım,

Okşasın analar yavrularını,

	Ayırtmasınlar sevdalıları bu dünyamda.

İs

   Te

       Mi

          Yo

             Rum.', 'Bir dünya istiyorum;        Huzur dolu,sevgi dolu,            Barış ve kardeşliğin yaşandığı, İnsanca yaşamın sembolü olan bir dünya. Kara b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Feyzullah Aydın']::text[], 8.5, '{"poet":"Mehmet Feyzullah Aydın","poet_slug":"mehmet-feyzullah-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/benim-dunyam-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nisan', 'bir-nisan-i-lknur-cekici-pzs5v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir nisandı başladı

Duyanlar şaka sandı

Hayatımın tek gerçek

Aşkını yalan saydı

Yalan olmalıydı belki

Tatlı bir rüya sanki

Bir nisanda gerçekleşti

Hayatımın hayali

O gün bu gündür dilemem

Yalan olsun istemem

Vazgeçer miyim senden

Yalan olmak istesen', 'Bir nisandı başladı Duyanlar şaka sandı Hayatımın tek gerçek Aşkını yalan saydı Yalan olmalıydı belki Tatlı bir rüya sanki Bir nisanda gerçe...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-nisan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzur evi', 'huzur-evi-emel-manav-k6fep', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yutar da bunca seneyi. 

Barındırır dedeyi, nineyi. 

Tek özlemleri ziyaretçileri. 

Tonton ve şekercik kendileri. 

Her biri doludur, hayat tecrübesi. 

Hepsinin vardır, anlatacak hikayesi. 

Bir yürek olmuşlar bir yerde buluşmuşlar. 

Akları, kırışıkları olmuş payesi.! ! 

Ağlamayı, gülmeyi, bir masada yemeyi. 

Bir bahçede gezmeyi, kısaca paylaşmayı. 

İbret alsak, örnek alsak onlardan. 

Mutluluk akardı yuvalardan!', 'Yutar da bunca seneyi.  Barındırır dedeyi, nineyi.  Tek özlemleri ziyaretçileri.  Tonton ve şekercik kendileri.  Her biri doludur, hayat tec...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/huzur-evi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı gibi yağmurdu', 'adi-gibi-yagmurdu-goksel-dogru-vaalp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(bir hayale dair) 

Uzun bir kara kışın ardından

Daha erimeden karlarım

Toprağıma verdi veriştirdi

Gök gürültülü, sağanak yağışlı

Ne bir bakış teselli niyetine 

Ne de gül güleç bir yüz, ağlatan

Çok gördüğü sevgisini 

Ve o eşsiz gülümseyişini aldı gitti

Göz yaşlarım adı gibi yağmurdu; 

Yağmurlu bir nisan günü sabahı

(Nisan 1998,Bursa)', '(bir hayale dair)  Uzun bir kara kışın ardından Daha erimeden karlarım Toprağıma verdi veriştirdi Gök gürültülü, sağanak yağışlı Ne bir bakı...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adi-gibi-yagmurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zoraki', 'zoraki-goksel-dogru-jhfoh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(bir hayale dair) 

Nice karakışlarda dondu

Bir anlık güneşe hasret

Çöl sıcağında kavruldu

Bir yudum suya hasret

Sonunda 

Gönlümü bir kaşık suda boğdum

Gıkı bile çıkmadı.

(Ekim 1998,Bursa)', '(bir hayale dair)  Nice karakışlarda dondu Bir anlık güneşe hasret Çöl sıcağında kavruldu Bir yudum suya hasret Sonunda  Gönlümü bir kaşık s...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zoraki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sezi', 'sezi-goksel-dogru-ax75y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(bir hayale dair...) 

Yağmur yağacak

Seziyorum

Kapkara bulutlar belirdi 

Denizin ufkunda

Görüyorum.

Tırnaklarımla kazıyarak yaptığım

Kumdan tepeler yıkılacak

Bu savaşı da kaybedecek ordularım

Seziyorum

Yağmur yağacak! 

Umutlarım ıslanıp 

Doğduğu yere tersine akacak

Ve yine doğduğu yerden, bir anda

Umutsuzluk adlı sel olup

Yüreğime akacak.

An gelip yüreğimden taşıp

Gözlerime ulaşacak

Bir akşam yağarken yağmur 

Gök kubbeden,

“O ağlıyor” diyeceksin

Biliyorum.

(Ekim 1998,Bursa)', '(bir hayale dair...)  Yağmur yağacak Seziyorum Kapkara bulutlar belirdi  Denizin ufkunda Görüyorum. Tırnaklarımla kazıyarak yaptığım Kumdan ...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sezi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Tarlası', 'huzun-tarlasi-sahin-erturk-exklp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kutlarım güzelim

Kutlarım seni

Yeni bir rekor kırdın

Altı ay,on gün

Tam 4560 saat

Acı tattırmadın

Hüznü yaşatmadın bana

Şimdi sıra sende

Sür güzelim sür

Sen de sür

Nasıl olsa yüreğim

HÜZÜN TARLASI

Alışıktır acılara

Alışıktır yalnızlığa

Alışıktır kahrolmaya

Sür güzelim sür

Sen de sür

Nasıl olsa yüreğim

HÜZÜN TARLASI

(01.04.2005-Yeni)', 'Kutlarım güzelim Kutlarım seni Yeni bir rekor kırdın Altı ay,on gün Tam 4560 saat Acı tattırmadın Hüznü yaşatmadın bana Şimdi sıra sende Sür...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/huzun-tarlasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklambaç', 'saklambac-goksel-dogru-ocui0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mut 

Çık artık ortaya

Bir ömür bekledim

Sobelemek için seni

Çık 

Bitsin artık bu oyun

Bitsin artık saklambaç

(Nisan 2001,Samsun)', 'Mut  Çık artık ortaya Bir ömür bekledim Sobelemek için seni Çık  Bitsin artık bu oyun Bitsin artık saklambaç (Nisan 2001,Samsun)...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/saklambac-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin', 'gelin-goksel-dogru-9r4zy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün çocukluğuma gittim,büyüdüm sonra 

Ben oldum.

Yaşlandı gözlerim, yaşlandım bir anda

Ben oldum.

On ikisinde de, yetmişinde de 

Ben bendim

Yalnızdım, kederliydim

Yetmişinde torunların kucağında

Çocukların yanında

Benim bilmediğim duygular içindeydin.

On ikisinde gülüşün, güneşten sıcaktı

On ikisinde de yetmişindeki gibi

Mutluydun, sevinçliydin.

Bugün 

Yirmisindeydin, evleniyordun.

Bense yalnızdım, kederliydim.

(Nisan 2001,Samsun)', 'Bugün çocukluğuma gittim,büyüdüm sonra  Ben oldum. Yaşlandı gözlerim, yaşlandım bir anda Ben oldum. On ikisinde de, yetmişinde de  Ben bendi...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gelin-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mekan II', 'mekan-ii-goksel-dogru-gp2ob', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Olur da bir gün

Gece yarısında şehir ışıkları 

Uğurlarsa beni herkesten habersiz

Aynı gece yarısı gözlerim

Yanmaz olursa gecenin ayazında

Beyaz gelinlikler içinde yarim

Anarsa adımı söz arasında 

Eskilerden çıkıp gelirse ilk aşkım

Af dilerse benden geçmişe dair

Seviye dair yazdıklarım

Ulaşırsa yazılanın yüreğine

Bir ömür adımı anmayan

Anlarsa kadrimi yalnızca bir an

Bir kadının gözünden yaşlar

Dökülürse yalnız benim için

Gök gürültülü sağanak yağarsa yağmur 

Katarsa seline bütün geçmişimi

ve mevsim hep baharmış gibi 

Kokarsa köyümün taşı, toprağı

...

...

''Zeynebi bu hafta ettiler gelin''

Çalarken dağlarda kavalıyla çoban

Karşımda tüm güzelliğiyle Çırakman

Ben toprak altında, mevsim hazan

Çamlar içindeki mekandayım arzulanan

O gün eller üstünde uğurlandığımdır gündür 

Hayat yolundan

Bir cigara yakasım gelir efkardan,

Yapamam.

(Nisan 2001,Samsun)', 'Olur da bir gün Gece yarısında şehir ışıkları  Uğurlarsa beni herkesten habersiz Aynı gece yarısı gözlerim Yanmaz olursa gecenin ayazında Be...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/mekan-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı', 'yabanci-goksel-dogru-uz7fi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(anadilime...)  

garajdayım

istasyonda bekliyorum

gardayım

terminaldeyim

ne bekliyorsun? 

-otobüs

neden indin? 

-trenden.

Nerde kaldı milletin 

Öz be öz Türkçe hasretliği! 

Fransız mıyız be kardeşim? !', '(anadilime...)   garajdayım istasyonda bekliyorum gardayım terminaldeyim ne bekliyorsun?  -otobüs neden indin?  -trenden. Nerde kaldı millet...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yabanci-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeyizler Kitap Olsun', 'ceyizler-kitap-olsun-nurcan-ugurlu-75bcn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kusurdur adeta

 Bizim oralarda kız olmak

Ben nereli miyim 

Fark eder mi

Türkiye’nin her hangi bir yerinden

Yavaş gidersin yürü derler

Hızlı gidersin deli derler

Kız kısmı değimli

 Zavallı bir eksik etek

 Besler büyütürsün

Yarın çeker gider el evine

  Kimileri okutmaktan yanadır                  

 Kimileride okuyup ta ne olacak

Otursun evinin kadını olsun derler

 Çeyiz hazırlıkları başlar 

          

Yaşamak

 Sırf evlilikten ibaretmiş gibi yetiştirilirsin

Kocana, büyüklerine itaat edeceksin derler

Yaş onaltı dır

 Görücüler gelir beğenirler seni

 Senin ailende onları beğenir

Sorma gereği duymazlar, çünkü

 Saçın uzun aklın kısadır

Alır koyarlar uzunca bir yolun başına

Yürü derler

Bakarsın uzaktan 

Yaldızlarla süslenmiş bir ev

 Eşyalar, mücevherler hatta

 Kocaman harflerle yazılmış mutluluk tabelaları ve

Pembe, pembe baloncuklar…

 Aslında gözünü kamaştıran şey

 Kaçıştır kurtuluştur

Umuda umutsuzca gitmek gibi

Gidersin…

Hani yağmur yağdıktan sonra küçük su birikintileri olur ya

Baktığın zaman gökyüzü tersine dönmüş

 Uçsuz bucaksız bir boşluk vardır

İşte o boşluğun tam ortasında bulursun kendini

Ne girişi vardır nede çıkışı

Yaldızlar bakırlaşmış halka-halka sarıvermiştir etrafını

Kıramazsın 

Geriye de dönemezsin 

Çünkü sana, koca evine gelinlikle girer

 Ancak kefenle çıkarsın demişlerdir

Kimileri benimser

 Kaderim der  razı olur

Kimileride sahte dünyalar kurar

Kendi kabuğunun içinde yaşar kaplumbağa misali 

Kör kuyuya düşen umutlara ulaşmak için çırpınır durur

Her defasında belki, belki yarın diye avutur kendini

Ve düşünür 

Acaba o gördüğüm pembeler neydi 

Çaresizlikler içinde çareler arayan

Bir genç kızın düşleri…

Ve bu hikâye

Geleneklerin çelik duvarları arasına sıkışmış bir dünyada

İnsanlığını kaybetmemek için direnen

Bir bireyin son çığlıkları 

Lütfen, lütfen  çeyizler kitap olsun

ÇEYİZLER KİTAP OLSUN', 'Kusurdur adeta  Bizim oralarda kız olmak Ben nereli miyim  Fark eder mi Türkiye’nin her hangi bir yerinden Yavaş gidersin yürü derler Hızlı ...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Uğurlu']::text[], 8.5, '{"poet":"Nurcan Uğurlu","poet_slug":"nurcan-ugurlu","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/ceyizler-kitap-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm de Yakışır Bize', 'olum-de-yakisir-bize-ahmet-can-akyol-yo4on', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gidiyorum, 

Yarım kalan sözlerin merakına düştükten sonra

Belki yaşanacak aşkların gizlisinde kalırım

Belki kavgalara bilemem düşlere bulaşırım

Meraklanma sen

Yine de bir tutam güneş 

Hep olacak koynumda

Yeter ki  leke değmesin

Gül tenli ellerimize

Sevdalar yaşamak içindir

Bazen ölüm de yakışır bize

Soluk seslerini duydum aysız gecede 

Ilık bir tebessüm değildi 

Karanlık içlerinden seçmeye çalıştıklarım

Değildi 

Bu yorgunluk benim değildi

Ve ben 

Artık seninle koşamam bağışla beni küçüğüm

Ayaklarım uyum sağlamaz adımlarına

Yüzlerce kavga bıraktım ardımda

Üstelik bunlarda sen yoktun

Çağlara iz düşüren tekil kahramanlar yoktu

Bedeli peşin ödenmiş ömürlerin

Kanlı ibareleri vardı sadece

Gidiyorum

Sokak ışıklarında gölgeler büyüterek

Belki varlığı ispat istemez bir kurşun olurum

Belki körpecik bakışlara kalkan olurum

Meraklanma sen

Yine de gözyaşların 

Hep saklı kalacak

Yeter ki leke değmesin

Gül tenli ellerimize

Sevdalar yaşamak içindir

Bazen ölümde yakışır bize

Binlerce kez koştum 

Sadece koştum

Yıkık kentlerin enkaz bulvarlarında

Nasıl koşulursa molozlar içinde öyle koştum

Ve şarkılar dinledim 

Korkulu 

Çığlıklı

Ve içinde uçurumlar olan şarkılar

Ve şarkılar söyledim 

İnançlı 

Sabırlı

Ve sevdaya durmuş şarkılar

Yüreğimi kalkan ettim kanlı duruşlara 

Sevdamı volkan 

Hoşçakal küçüğüm

Bilesin ki

Bazen ölüm de yakışır bize

Bilesin ki bazen ölüm de yakışır', 'Gidiyorum,  Yarım kalan sözlerin merakına düştükten sonra Belki yaşanacak aşkların gizlisinde kalırım Belki kavgalara bilemem düşlere bulaşı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Akyol']::text[], 8.5, '{"poet":"Ahmet Can Akyol","poet_slug":"ahmet-can-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/olum-de-yakisir-bize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut goncam', 'umut-goncam-i-lhami-arslantas-uwcvs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Umut goncam solma yaban ellerde 

Ne gezersin ömrün biter yollarda 

Sam savurur sam kavurur bellerde 

Daha senin çağla döken zamanın 

Kâr istemem ehli kâmil ol yeter 

Gel gidelim bu aydınlık yol yeter 

Bir bedene bir tanecik kol yeter 

Daha senin çağla döken zamanın 

Kurban olam için yanmasın gayri 

Belli olmaz zaman, zamane seyri 

Yaşamaz ki bir can bedenden ayrı 

Daha senin çağla döken zamanın 

Makbul değil yavan sözler eğreti 

Oku da gör tabiat bir öğreti 

Karıncadan görmedin mi gayreti 

Daha senin çağla döken zamanın 

Der İlhami onca yıllar zar ettin 

Bu canını yokluklarla var ettin 

Sevdaları harmanladın yar ettin 

Daha senin çağla döken zamanın', 'Umut goncam solma yaban ellerde  Ne gezersin ömrün biter yollarda  Sam savurur sam kavurur bellerde  Daha senin çağla döken zamanın  Kâr ist...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/umut-goncam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kaldı Aşka Dair', 'ne-kaldi-aska-dair-atilla-guler-ji2i5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'çıplaklığını sevgiye sunan aşk

günlerce sevişti ruhumda...ruhunla

salaş meyhanelerde sundum bakirliğimi sana

sarı yaprakları yaktım koynunda/sevdamın 

sevdikçe istedim...istedikçe sevdim

daha çok sen koktum

ıslaktı...ıpıslak

dudaklarım dudaklarında

yumuşacıktı hayat öpüşlerinin ucunda

ıslak...ıpıslak saçlarından yakaladım

şehvetinde yandım...yaktı selin...ellerime sınır tanımadım

dayadım göğsümü göğsüne

bir dudak ötemde durdu aşk

sımsıkı sarıldım...saklandım koynunda

dipsiz kuyulara serdim yüreğimi/hırsızlığım tuttu

güneşten bir parça çaldım/yüzüme yapıştırdım

aşk oldum...aşık oldum

ne kaldı aşka dair söylenmeyen

uçurdu...yıktı...yangınlarında kavurdu

külünü savuramadık havaya

ıslattı

sevişmelere kattı tadını

bilinen o ki...hiç ölmedi

ne kaldı aşka dair söylenmeyen

aşk...

ne bakir...ne bakire

sen...yıllardır kucaktan kucağa sürten bir fahişe...', 'çıplaklığını sevgiye sunan aşk günlerce sevişti ruhumda...ruhunla salaş meyhanelerde sundum bakirliğimi sana sarı yaprakları yaktım koynunda...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ne-kaldi-aska-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımın Âbidesi', 'askimin-bidesi-bayram-durbilmez-3puzq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yudumlarım zevkle zehirse bile

O bal dudağından aşk bâdesini

Yanar aşk oduna yâr bile bile

Arzular bu gönlüm nâdidesini

Tanrım gönül vermiş severim ben de

Sevdân yudum yudum birleşir bende

Gül benine gönlüm eyledin bende

İnletir hep neden gül bendesini? 

Yanağında benin bir gül deseni

Görürüm bülbülde hem gülde seni

Sarayım sevdiğim bir gül de seni

Neyleyim sevginden ziyâdesini? 

Gönül bahçesinde gonca gülüm ser

Dilim seni söyler gitse gülüm ser

Cellâda gülümser, ipe gülümser

Alsalar gönlümün ifâdesini

Efsunkâr gülüşün Ozantürk''e yâr

Seni görürsün yâr, yüreğimi yar! 

Ördüm nakış nakış yüreğime yâr

Aşkımın emsalsiz âbidesini', 'Yudumlarım zevkle zehirse bile O bal dudağından aşk bâdesini Yanar aşk oduna yâr bile bile Arzular bu gönlüm nâdidesini Tanrım gönül vermiş ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Durbilmez']::text[], 8.5, '{"poet":"Bayram Durbilmez","poet_slug":"bayram-durbilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/askimin-abidesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-galip-sinecikli-1n8di', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cemreleri düşürdük, hava, su ve toprağa,

Sensiz şu gönlümüze, bahar gelmiyor Annem.

Dün kollarındaydık, bu gün düştük uzağa,

Sensizken uzaklarda, günler geçmiyor Annem.

Gelmiyorsak yanına, mutlak vardır sebebi,

Sanma seni unuttuk, unuturmuyuz Annem,

Burda gündüzle gece, sensiz belli değil ki,

Gece ile gündüzü, sensiz şaşırdık Annem…

Canım Anneme ve tüm Annesinden uzak olanlara Armağanım Olsun...

www.radyoerguvan.com

www.turkhaber.eu

[email protected]', 'Cemreleri düşürdük, hava, su ve toprağa, Sensiz şu gönlümüze, bahar gelmiyor Annem. Dün kollarındaydık, bu gün düştük uzağa, Sensizken uzakl...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/annem-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız İkimiz', 'yalniz-i-kimiz-bayram-durbilmez-hl035', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Canlandı gözümde mâzimiz bir bir

Hazar kıyısında Erciyes dağı

Bir nisan gününde uyandı nehir

Çiçeklendi yine gönlümün bağı

Konuşsun hayaller, susmasın düşler,

Sürsün vuslât demi çılgınca sürsün! 

Öpüşür rûhumla sıcak gülüşler

Gülsün arzularım, fidanlar sürsün! 

Sevdâ ülkesinin iklimi sarhoş

Coşturur kalpleri nisan yağmuru

Aşksız yüreklerin dünyası bomboş

Sarar gönülleri sevginin nûru

Aşkınla ışıttım karanlıkları

Karanlık dünyamda güldü dolunay

Gömdüm yüreğime hıçkırıkları

Kaf dağına attı gönlümü al tay

Isıttı gülüşün donuk gönlümü

Yunduk şiirlerle yalnız ikimiz

Eyledin gönlüne konuk gönlümü

Mısralara dizdik aşkımızı biz

		Bakü, 2.4.1994', 'Canlandı gözümde mâzimiz bir bir Hazar kıyısında Erciyes dağı Bir nisan gününde uyandı nehir Çiçeklendi yine gönlümün bağı Konuşsun hayaller...', ARRAY['Türk Edebiyatı','Şiir','Bayram Durbilmez']::text[], 8.5, '{"poet":"Bayram Durbilmez","poet_slug":"bayram-durbilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yalniz-ikimiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yüzlü Umutlar', 'gul-yuzlu-umutlar-bayram-durbilmez-o82jp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Süzülür ışık ışık nur yağar yüreğime

Gönlümün gökyüzünde toz pembe bulutlar var

Parıldar hayâllerim, gün doğar yüreğime

İçimde filizlenen rengârenk umutlar var

Sevgi yüklü gemiye sevdâlı gönlüm liman

Şiir serinliğinde süpürür derdi zaman

Zerrede gizli güneş, katrede gizli umman

Şiir denizlerinde inciler, yâkutlar var

Uçar ak güvercinler açar düşlere kanat

Sevgiye koşar gönlüm yılgınlıklara inat

Secde eder sevgiye, aşka bütün kâinat

Bir bakışa ömrünü adayan mesutlar var

Gülümser yüreğimde duygu tomurcukları

Paylaşır varlıklarla dostça mutlulukları

Adımlar muhabbetle bu gönlüm ufukları

Aydınlık âlemlere açılan hudutlar var

Cezbeder güzellikler sevdâlı bülbülleri

Ozantürküm gönlümde açar sevgi gülleri

Gönül ehli âşıklar kazanır gönülleri

Tanrının evi olan benzersiz konutlar var', 'Süzülür ışık ışık nur yağar yüreğime Gönlümün gökyüzünde toz pembe bulutlar var Parıldar hayâllerim, gün doğar yüreğime İçimde filizlenen re...', ARRAY['Türk Edebiyatı','Şiir','Bayram Durbilmez']::text[], 8.5, '{"poet":"Bayram Durbilmez","poet_slug":"bayram-durbilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gul-yuzlu-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm Orada', 'gonlum-orada-bayram-durbilmez-nj3oq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yunusça hoşgörü, Yunusça sevgi

Merhamet nerede gönlüm orada

Yunusça bir dostluk, Yunusça ilgi

Muhabbet nerede gönlüm orada

Dostluk kadehiyle sun muhabbeti

Kalplere bengisu birlik şerbeti

Kalpten kalbe köprü gönül sohbeti

Hoş sohbet nerede gönlüm orada

Ruhumda rakkase gökçe hülyalar

Gönlümde sevgili renkli ziyalar

Köpüren nehirler, coşan deryalar

Cesaret nerede gönlüm orada

Duygular pırlanta, arzular billûr

Kalpte sevgi ağı bir ilâhî nur

Açan gül bahçesi içimde huzur

Saadet nerede gönlüm orada

Sevgi eleğiyle gönlünü ele! 

Sevip sevilirsen düşmezsin ele

Ozantürk, sahip çık bu cennet ele! 

Bu millet nerede gönlüm orada', 'Yunusça hoşgörü, Yunusça sevgi Merhamet nerede gönlüm orada Yunusça bir dostluk, Yunusça ilgi Muhabbet nerede gönlüm orada Dostluk kadehiyle...', ARRAY['Türk Edebiyatı','Şiir','Bayram Durbilmez']::text[], 8.5, '{"poet":"Bayram Durbilmez","poet_slug":"bayram-durbilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gonlum-orada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm! Nedir', 'olum-nedir-deniz-yilmaz-eralp-4hmxa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölüm! nedir sence? 

Sadece bir bedenin 

Buz gibi kesilmesi midir.

Ölüm! 

Yoksa! 

Sevdiğini kaybetmek midir.

Yaşamak nedir sence? 

Sadece havayı solumak mıdır.

Yoksa! 

Sevdiğinle birlikte olmak  mıdır.', 'Ölüm! nedir sence?  Sadece bir bedenin  Buz gibi kesilmesi midir. Ölüm!  Yoksa!  Sevdiğini kaybetmek midir. Yaşamak nedir sence?  Sadece hav...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yılmaz Eralp']::text[], 8.5, '{"poet":"Deniz Yılmaz Eralp","poet_slug":"deniz-yilmaz-eralp","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olum-nedir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gülüş Birde Acı', 'bir-gulus-birde-aci-hasan-can-vs3mu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiçbir şey söylemeden,

Çekip gittin uzaklara.

Geride bıraktığın, bir gülüş,

Birde acı en büyüğünden.

Bıraktığın gülüş, hatırladıkça ağlıycam,

Acı ise giderken içime bıraktığın,

Ve hiçbir zaman silinmiycek olan tek hatıra.

Artık yaşadığımız bütün duygu dolu hatıraları,

Ve onlarla beraber seni de toprağa gömüyorum,

Bıraktığın o izi silinmeyecek tek hatırayı da,

İçime gömüyorum...', 'Hiçbir şey söylemeden, Çekip gittin uzaklara. Geride bıraktığın, bir gülüş, Birde acı en büyüğünden. Bıraktığın gülüş, hatırladıkça ağlıycam...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-gulus-birde-aci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nisan Günü', 'bir-nisan-gunu-onder-karadag-k23w7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birden açılıverdi gözlerim

...

Salınmış bir kuş gibi

Ürkük, yüreksiz

Unutuvermişim seni

Belleksiz

Şimdi ben nerelere gideyim

Bu baharda 

Bir nisan günü! 

(1 Nisan 2002)', 'Birden açılıverdi gözlerim ... Salınmış bir kuş gibi Ürkük, yüreksiz Unutuvermişim seni Belleksiz Şimdi ben nerelere gideyim Bu baharda  Bir...', ARRAY['Türk Edebiyatı','Şiir','Önder Karadağ']::text[], 8.5, '{"poet":"Önder Karadağ","poet_slug":"onder-karadag","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-nisan-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-ziya-nizam-1u3jh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Monarşik sistemlerde büyüttük yalnızlığımızı

Okyanuslar büyüklüğünde göllerde

Yüzdü platonik sevgilerimiz.

Kalabalık bir yalnızlığımız vardı hep.

Birbirinden kaçan bir benliğimiz vardı.

Kaçan kovalanır anlayışı hakimdi beyinlerimizde.

Gençliğimizin düşüncesizliğiyle

Hep kaçan olmayı yeğliyorduk.

Birbirimize yaklaşsak ölecekmişiz gibi geliyordu.

Sen bende arıyordun

Eski sevgilinde bulamadığın yakınlığı.

Yine bulamadın sanıyordun sonra.

Oysa ummadığın kadar yakındım ben

İstediğin yerde,istediğin şekildeydim.

Sadece beynin yeterdi aslında

Beni sen yapmaya.

Benim hep bir zaaf yanım vardı

O sendin.

Gizli öznelerinde yaşatıyordum seni

Kurduğum cümlelerin.

Yerçekimine eşdeğer bir çekim yayıyordun etrafına

En çok da ben etkileniyordum bu çekimden.

Kalbim,nezleden garip bir gribe çevirdi sevgini.

Damarlarıma oluk oluk sen akıyorsun artık.

Senleştikçe yaşasam mı,ölsem mi bilemiyorum.

Hücrelerimin bölünmekten başı döndü.

Her yeni doğan hücrede

Yepyeni bir sen varsın.

Hep bir zaaf yanım vardı

O sendin.

Hep bir çocuk yanım vardı.

Sadece seninleyken ortaya çıkan.

Ben tüm çocukluğumla

Denizler almıştım sana.

Hani sen çok seversin ya.

Kırmızı gül bahçeleri kurmuştum

Bu denizlerin tam orta yerine.

Çocukluk işte.

Seni seviyorum yazmıştım suya

Tuzdan yaldızlı harflerle.

Sanki çok mu önemliydi,

Benim seni safça seviyor olmam.

Gerçekçilik bile değildi.

Hayaldi,umuttu ve belki de rüyaydı.

Çocukluk işte.

Hiç bilmedin sen

Gülüşündeki tıpatıp benzerliği.

Hiç bilmedin

Bakışındaki aynılığı.

Hiç bilmedin

Sana olan tutkumun

Senden önceden beri var olduğunu.

Kaçırıyorum şimdi düşüncelerimi senden

Yoksa öldürüyorsun beni.

Kalbimi olduğu gibi

Beynimi de sensizliğe alıştırıyorum.

Acımdan,

Gözyaşı ekiyorum,son moda asfaltlara.

Beni sana götürmediklerine içerliyorum.

Yorgunluk tuttu ellerimden

Senin ellerin kadar sıcaktı.

Seni aramanın,seni anlama çabasının yorgunluğu

Artık tüm bedenimi sardı.

Sonsuzluğa açtım şimdi kapılarımı

Hadi koş bekliyorum seni de.

...

	Her ne kadar gelmem desende biliyorum kalbinin benimle olduğunu.Beynin değil,kalbin.Beynin hep zıttı çünkü,hep doğru bildiği yanlışlar yaptı.Biraz kalbinin dediklerini uygulasa daha güzel olurdu.Olsun,ben herşeye rağmen bekliyorum.Sen olarak gel.Hadi artık gel.

			13.10.1997-Pazartesi

			19:15 Çerkezköy', 'Monarşik sistemlerde büyüttük yalnızlığımızı Okyanuslar büyüklüğünde göllerde Yüzdü platonik sevgilerimiz. Kalabalık bir yalnızlığımız vardı...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/gel-168-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belli değil', 'belli-degil-tuncay-akdeniz-3tui7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu dünya bir sınav yeri

Sorusu belli değil''ki

Mekanı ademden beri

Kirası belli değil''ki

Bizim için bu cihanı

İki kapı geniş hanı

Ecel gelir alır canı

Sırası belli değil''ki

Kendin yakma bile,bile

Varamasın bir menzile

Türlü renkler katmış güle

Karası belli değil''ki

Kimseye kalmaz viranı

Devir ediyor devranı

Hiç boş kalmaz''ki kovanı

Arısı belli değil''ki

Tuncay’ım olmaz yuvası

Yalan diyorlar burası

Akıbet mekan orası

Neresi belli değil''ki', 'Bu dünya bir sınav yeri Sorusu belli değil''ki Mekanı ademden beri Kirası belli değil''ki Bizim için bu cihanı İki kapı geniş hanı Ecel gelir ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/belli-degil-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ayrılık Şiiri', 'bir-ayrilik-siiri-tulay-sustam-ukyp9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'apastrofla ayırdım senden kendimi

sen şehrin bir yakasında kaldın,

ben diğer yakasında...

o günden beri; 

bu şehrin iki yakası bir araya gelmedi

seni yeniden sevmem, sana yâr demem

sana geri dönmem artık imkansız

anlasana! ...

ayrılığımızın üzerinden boğazın suları geçti', 'apastrofla ayırdım senden kendimi sen şehrin bir yakasında kaldın, ben diğer yakasında... o günden beri;  bu şehrin iki yakası bir araya gel...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-ayrilik-siiri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalışanı severim', 'calisani-severim-tuncay-akdeniz-8bkkh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ÇALIŞANI SEVERİM

Haram mal insanı derbeder eder

Emek verip çalışanı severim

Haydan gelen derler vayına gider

Helâlinden oluşanı severim

Bütün altın olsa dünyada varın

Hakikatı bilmek en büyük kârın

Servetiyle helak oldu o Karûn

Hakkı için uğraşanı severim

Bu dünyanın doğum ölüm gerçeği

Mevsiminde açar gülü çiçeği

Sözü bir olmalı  erin yüreği

Dilde doğru konuşanı severim

Deli derler bakıp,bakıp gülene

Cahil derler çağrılmadan gelene

Yanlış derler öğrenmeden bilene

Cehaletle savaşanı severim

Mazlumun akmasın gözünün yaşı 

Bitsin artık ölüm kalım savaşı 

Başlasın dünyada dostluk yarışı 

Kardeş kardeş barışanı severim

Manevi değerden yoksun özümüz 

Dünya maddesine doymaz gözümüz

Eğriye karıştı her bir düzümüz 

Doğru için yarışanı severim

Atandan emanet bu bayrak sana

Sahip çıkmalıyız  güzel  vatana

Ser veripde sır vermesin düşmana

O kahraman nuru-şanı  severim

Tuncayım hatamın farkına vardım

Belkide insanın kalbini kırdım

En büyük iyilik düşküne yardım

Hatır sorup danışanı severim

Tuncay Akdeniz', 'ÇALIŞANI SEVERİM Haram mal insanı derbeder eder Emek verip çalışanı severim Haydan gelen derler vayına gider Helâlinden oluşanı severim Bütü...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/calisani-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asil Sevdam-2', 'asil-sevdam-2-hidayet-avsar-ssobr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen; olmayan bir ağacın

Görmediğim tonda yeşili,

Kayıp şehirde bir evin,

Hiç sönmeyen ışığısın.

Sen; karanlık sokakların

Işıktan sevgilisi,

Bitmeyen masalların

Sevdalı prensesi...

Sen; rüyamdaki susuzluk,

Ensemdeki soğukluk,

Bir bebek ağlaması...

Yaşanmamış mutluluğum...

Umudumsun...', 'Sen; olmayan bir ağacın Görmediğim tonda yeşili, Kayıp şehirde bir evin, Hiç sönmeyen ışığısın. Sen; karanlık sokakların Işıktan sevgilisi, ...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/asil-sevdam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Oyun', 'son-oyun-hidayet-avsar-2xnqf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seyrettiğim en güzel filmin

Son karesiydi gözlerin.

“En iyi kadın oyuncu” ödülünü veriyorum sana.

Kendime de “en iyi figüran”.

Konuşan ben değildim ama,

En iyi seslendirme benimdi.

Şimdi seninle son oyunu oynuyoruz; 

Baş rol benim! 

Sen artık sahnede yoksun,

Perdenin arkasından yönetiyorsun oyunu.

Şimdi “öl! ” diyorsun.

Ölüyorum son kez...

Son kez dediğini yapıyorum.

Artık “diril” desen de,

Dirilmeyi bilmiyorum.', 'Seyrettiğim en güzel filmin Son karesiydi gözlerin. “En iyi kadın oyuncu” ödülünü veriyorum sana. Kendime de “en iyi figüran”. Konuşan ben d...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/son-oyun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizler', 'denizler-hidayet-avsar-hu1v8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ya tümden çöl olmalı denizler,

Ya kudurmalı gönlünce.

Ya sevda uğruna açmalı güller,

Ya ölmeli, sevdalısı ölünce.

Unutursan gördüğün o son düşü,

Lanet olsun bülbüllerin ötüşü,

Her nefeste yad ettiğin gülüşü,

Yutsun! Sana aldırmasın denizler.', 'Ya tümden çöl olmalı denizler, Ya kudurmalı gönlünce. Ya sevda uğruna açmalı güller, Ya ölmeli, sevdalısı ölünce. Unutursan gördüğün o son d...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/denizler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicivler-IV', 'hicivler-iv-ugur-deniz-ulkegul-83n25', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnanmeyom ben sana, dinlemeeyom sozünü,

Kurda kuşa yem ettin, geceni gundüzünü,

Azıcık kızdık diye, çevirdin ya yüzünü,

Huysuz idik biz emme, hürmetimiz var idi…

Canın yandı bileeyom, sarmadık mı yaranı,

Onca düşman oldu da, yapmadık mı aranı,

Hain, alçak çoğ idi, görmedik mi zorunu,

Yurt’ suz idik biz emme, hatırımız var idi…

Kalenderi oyneyo, deyip bana çateyon,

Olmayanı söyleyip, bol keseden ateyon,

Onu bunu dinneyip, bedavaya sateyon,

Haksız idik biz emme, hukukumuz var idi…

Makamına bakmadan, sevdik para etmedi,

Haddimizi aşmadan, saydık ama yetmedi,

Onca uğraştık lakin, bu araba getmedi,

Yolsuz idik biz emme, pusulamız var idi…

Başa geçtin söyledin, kaç kişisi annadı,

Suyunu çekti akçen, hangisi tamamladı? 

Benim zaten yoğ idi, gerisi de kalmadı,

Çul’suz idik biz emme, dostluğumuz var idi…

Anlatma bana artık, geçmeyo bende sozün,

Gönül hatır bilmeeyo, seçmeyo bende sozün,

Biraz rahmet, biraz nur, saçmeyo bende sozün,

Kâr’sız idik biz emme, soluğumuz var idi…

Doğru söyledik diye, gozden düştük ne gözel,

Rahat durmadık diye, ozden düştük ne gözel,

Tellerimiz çekmedi, sazdan düştük ne gözel,

Kal’siz idik biz emme, yüreğimiz var idi…

İşine bak sen usta, ben gideeyom bu yerden,

E laf çok bu hususta, düşemeeyom ederden,,

El pençe divan susta, durameeyom kederden,

Hal’siz idik biz emme, bi sevgimiz var idi…

Sanırsın ki öfkeden, konuşeeyom bunları,

“Ahmak işte”, bilmeden, konuşeeyom bunları,

“Onlar gibi gülmeden”, konuşeeyom bunları,

Densiz idik biz emme, mertliğimiz var idi…

Ustasın ya, sanatın heba oldu gitti bak,

Şifa dedin ilacın, veba etti gitti bak,

Halis idi muradın, teba kurt’tu, it’ti bak,

Donsuz idik biz emme, gomleğimiz var idi…

Sen devam et yoluna, benim halim kalmadı,

Sövmediğim namussuz, alçak, zalim kalmadı,

Senin rahmetin çokça, benim kinim kalmadı,

Gemsiz idik biz emme, insafımız var idi…

Kerametin, makamın, kasede  senin olsun,

Merhametin şefkatin, tepside senin olsun,

İstemeeyom heç bi şey, hepside senin olsun,

Yem’siz idik biz emme, bi sabrımız var idi…

Cemaat horon tepmiş, hoca ders anlateeyo,

Ne dersi hoca emmi, millet keyif çateeyo,

Tuzu kuru adamın, Müslümanlık sateeyo,

Batmış idik biz emme, hesabımız var idi…

Hadi sağlıcakla kal, yokum gaari ben artık,

Sözünde sıcakla kal, pekim gaari ben artık,

Ocakla, bucakla kal, tekim gaari ben artık,

Gelmiş idik biz emme, gidişimiz var idi…', 'İnanmeyom ben sana, dinlemeeyom sozünü, Kurda kuşa yem ettin, geceni gundüzünü, Azıcık kızdık diye, çevirdin ya yüzünü, Huysuz idik biz emme...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/hicivler-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevdim', 'seni-sevdim-hidayet-avsar-wqyhg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gariptir; 

Ayaklarıma baktım, mutlu oldum.

Şöyle tüttüre tüttüre içtim 

Koca bir nargileyi.

Yanında meyve suyu...

Rüzgarı yakaladım esmeden evvel

Bir güzel gördüm,

Mutlu oldum.

Başka diyarları düşündüm,

Çakıl taşı topladım sokaklardan geçerken.

Ellerim kanadı cam kırıklarından.

Esmer bir çocuk dil çıkardı bana.

İnce bir ses duydum,

Görmediğim akşamlarda üşüdüm,

Mutlu oldum.

Beş taş oynadım

Oyun havalarında.

Kar yağarken geceleri

Soğuk sularda yüzdüm.

Güneş gibi sıcak yürekler gördüm,

Mutlu oldum.

Çırılçıplak kaldım okyanusun ortasında,

Azizlerin nefesiyle ısındım.

Karanlığa köleydim geldiğin zaman.

Geldiğin zaman ışığa doydum.

Seni sevdim,

Mutlu oldum.', 'Gariptir;  Ayaklarıma baktım, mutlu oldum. Şöyle tüttüre tüttüre içtim  Koca bir nargileyi. Yanında meyve suyu... Rüzgarı yakaladım esmeden ...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/seni-sevdim-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Badem-İlkbahar', 'badem-i-lkbahar-olgun-ekinci-atsfw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani ilkbahar geldiğinde 

Ağaçların en güzeli badem ağacıdır ya, müjdecisidir ya baharın 

Nicedir özlemişim kokusunu, çiçeklerini, yemişini 

Dağlardan esen rüzgarların meltemi 

Ansızın ılık sıcak çarpar ya yüreğine yüzüne tenine 

Nicedir özlemişim baharı, badem ağacını, kokusunu... 

30 Mart-Adana', 'Hani ilkbahar geldiğinde  Ağaçların en güzeli badem ağacıdır ya, müjdecisidir ya baharın  Nicedir özlemişim kokusunu, çiçeklerini, yemişini ...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/badem-ilkbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Desem', 'ne-desem-hidayet-avsar-yewjl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi zaman yanıyor,

Saat kaç oldu desem.

Biri beni anıyor,

Hayır mı, şer mi bilsem.

Yalınayak bir adam.

Sokakta, yapayalnız.

Neden karanlık odam,

Güneş doğunca gitsem…

Yeni kaydı bir yıldız,

Burdan demincek geçti.

Dünya neden vefasız,

Yoksa, sitem mi etsem...', 'Şimdi zaman yanıyor, Saat kaç oldu desem. Biri beni anıyor, Hayır mı, şer mi bilsem. Yalınayak bir adam. Sokakta, yapayalnız. Neden karanlık...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-desem-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AşığınYağız Atı', 'asiginyagiz-ati-hidayet-avsar-udfys', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“Aşığa Bağdat sorulmaz”

Gezer durur kainatı.

Ölür ama kalbi durmaz,

Koşar durur yağız atı.

Bütün renkler beyaz ona,

Bahar günü ayaz ona,

Çile çekmek niyaz ona,

Sürer gider, saltanatı.', '“Aşığa Bağdat sorulmaz” Gezer durur kainatı. Ölür ama kalbi durmaz, Koşar durur yağız atı. Bütün renkler beyaz ona, Bahar günü ayaz ona, Çil...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/asiginyagiz-ati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıymetsiz', 'kiymetsiz-hidayet-avsar-hirv3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Varlığın hayatıma nur,

Varlığın gönlüme huzur,

İnan bana varlığım,

Yokluğunda son bulur.

Seni buldum bulalı,

Biçare oldum olalı,

Şu gurbetin yolları,

Yanımda yoldaş olur.', 'Varlığın hayatıma nur, Varlığın gönlüme huzur, İnan bana varlığım, Yokluğunda son bulur. Seni buldum bulalı, Biçare oldum olalı, Şu gurbetin...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kiymetsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamadın', 'anlamadin-hidayet-avsar-m6gxn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlham olup geldin bana,

Gecenin bir yarısında.

Bir kaçamak uykusunda, 

Sardın ruhumu, bedenimi.

Şiirler yazıyordum duvarlara,

Umut olsun diye, karanlığa,

Şarkılar dinliyordum yarınlara,

Anlamadın çocuk, sevdiğimi...', 'İlham olup geldin bana, Gecenin bir yarısında. Bir kaçamak uykusunda,  Sardın ruhumu, bedenimi. Şiirler yazıyordum duvarlara, Umut olsun diy...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anlamadin-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahkaha', 'kahkaha-hidayet-avsar-gg9ev', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nerdedir o buğulu cam,

Rüyalar ne vakit hayır.

Kolaysa tut martıları,

Sonra bütün kalpleri kır.

Gül kadere, geçmişe,

Kahkaha neymiş göster.

Uyu, uyu sonsuzluğu,

Kaybettiğin kendini uyu

Bilirim sevdalıydın,

Nerdeyse oralıydın.

Adı sır, cemali sır...

Nerdedir kaç asırdır...', 'Nerdedir o buğulu cam, Rüyalar ne vakit hayır. Kolaysa tut martıları, Sonra bütün kalpleri kır. Gül kadere, geçmişe, Kahkaha neymiş göster. ...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kahkaha-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çilenin çilesi', 'cilenin-cilesi-tuncay-akdeniz-6kqv7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ÇİLENİN ÇİLESİ

Şu yoksulluk başa bela

Güldürmüyor ki gülesin

Sekiz kardeşe bir tarla

Böldürmüyor ki bölesin

Gücü yetenler eziyor

Yoksulluk beni üzüyor

Ayak  çorapsız geziyor

Giydirmiyor ki giyesin

Bu çilenin yok sınırı

Katığı yok ekmek kuru

Unuttuk pilav bulguru

Yedirmiyor ki yiyesin

Bayram girmez bizim eve

El öpmeyi bekler nine

Bir eşekle köyden köye

Gidilmiyor ki gidesin

Dertsiz bilmez dert çekeni

Görmez gözden yaş dökeni

Yüreğe batan dikeni

Sökülmüyor ki sökesin

Tuncayım bu mu kaderi

Gülmedi öteden beri

Kurumuş gözüm pınarı

Dökülmüyor ki dökesin

		.11,01.1978', 'ÇİLENİN ÇİLESİ Şu yoksulluk başa bela Güldürmüyor ki gülesin Sekiz kardeşe bir tarla Böldürmüyor ki bölesin Gücü yetenler eziyor Yoksulluk b...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cilenin-cilesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşün', 'dusun-hidayet-avsar-psgnj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yazın gönlüm harman yeri,

Kışın yalnız seni sevdim.

Güneş battığından beri,

Düşün, yalnız seni sevdim.', 'Yazın gönlüm harman yeri, Kışın yalnız seni sevdim. Güneş battığından beri, Düşün, yalnız seni sevdim....', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dusun-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzme kendini', 'uzme-kendini-mikdat-bal-aobd4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu dünyanın..................etrafında............döndün.....................Bukadar yeter

Etrafında......................döne döne..........söndün.....................nedir bu keder? 

Döndün,.....................Söndün,..........Vermez sandın bil ki.....Allah lutfeder

Bu kadar yeter.........Nedir bu keder.....Allah lutfeder............üzme kendini

Dünya için..............ağlıyorsan..............boşver........................nedir bu yaşlar? 

Ağlıyorsan..............sebebi ne? ............ancak.........................Boşa telaşlar

Boşver.......................ancak............tövbe eyle  seni..............Allah bağışlar

Nedir bu yaşlar.......boşa telaşlar......Allah  bağışlar.............Üzme kendini

Eğer bu gün............Elin darsa............Sen de.......................Sabrını eyle

Elin darsa...............Allah verir..............sabret.......................Çok şükür söyle

Sen de....................sabret............Mahzun olma sakın.........Yarışma beyle

Sabrını eyle........Çok şükür söyle.....Yarışma beyle.............Üzme kendini

Küsme eğer......................bazıları...............kalkıp...............Ederse sükse

bazıları........................görmemiştir..........Sen de.................Özenme lükse

kalkıp...............................Sen de..........Ona gıpta etme......Gökyüzü çökse

Ederse sükse.......Özenme lükse.......Gökyüzü çökse.......Üzme kendini', 'Bu dünyanın..................etrafında............döndün.....................Bukadar yeter Etrafında......................döne döne............', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uzme-kendini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Kendini Öldürdün', 'yuregimde-kendini-oldurdun-hasan-can-qu18x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben senin gözlerinde mutluluğu araken,

Bulabildiğim tek şey ayrılık gözyaşları oldu.

Ben o gözyaşlarını haketmedim,

Senden ayrılmayı kabul etmedim,

Sil o boşuna akıttığın gözyaşlarını,

Ben o damlaların üstüme yağmasını istemedim.

Artık yoksun yüreğimin hiçbir köşesinde,

Kulağıma fısıldadığın o güzel ama sahte sözler senin olsun.

Tek bir nefesin bile kalmadı içimde,

Ağlarken akıttığın yalancı gözyaşları dilerim gerçek olsun.

Keşke içimde acıma duygusu olmasaydı,

Olmasaydı da Seni tek kalemde silebilseydim,

Yüreğimden söküp atabilseydim.

Keşke içimde zerre kadar bir sevgi kıvılcımı olmasaydı,

Olmasaydı da yüreğim bu kadar acı çekmeseydi...

Tuvalime mutluluk resmi çizemiyorum artık,

O duygu acıyla kavruldu içimde.

Satırlara da acının şiirini yazıyorum artık,

Çok yıprandım sevgiye dair derman kalmadı yüreğimde.

Bırak artık yalancı sevdaların sefasını sürmeyi,

Başkalarının yüreğinde kendini öldürmeyi.

Bırak artık o güzelim gözlerden sahte yaş akıtmayı,

Hayatı doğrusuyla yaşamak varken bırak artık yalandan yaşamayı...', 'Ben senin gözlerinde mutluluğu araken, Bulabildiğim tek şey ayrılık gözyaşları oldu. Ben o gözyaşlarını haketmedim, Senden ayrılmayı kabul e...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yuregimde-kendini-oldurdun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-mehmet-halil-2x50n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İzmir’e bahar erken gelir.

İzmir’in çiçekleri güzeldir.

İzmirin çiçekleri kız,

Kızları çiçek gibidir.

bahar demek,çiçek demektir.

baharı saklar koynunda,

İzmir’in, binbir kokulu seraları,

İzmir’e bahar erken gelir.

Çingeneler koşturur baharı.', 'İzmir’e bahar erken gelir. İzmir’in çiçekleri güzeldir. İzmirin çiçekleri kız, Kızları çiçek gibidir. bahar demek,çiçek demektir. baharı sak...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bahar-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyandık', 'uyandik-ufuk-nazim-1aacl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyandık

Gün berrak 

Ve çiğ damlalarının 

Serinliği altında

Yüreğimiz ferahtı.

Unutmuştuk

Geçen her derdin 

Yüreğimize oturan 

Tortusunu.

Uyandık

Köhne uykulardan

Ellerimiz hünerli

Ve umutlu gözlerle

Takılmadan 

Geçmişin gizemine 

Ağdık göğe

Güneş güneş

Işık ışık...', 'Uyandık Gün berrak  Ve çiğ damlalarının  Serinliği altında Yüreğimiz ferahtı. Unutmuştuk Geçen her derdin  Yüreğimize oturan  Tortusunu. Uya...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/uyandik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile kuyusu', 'cile-kuyusu-tuncay-akdeniz-wllto', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaderime hayat acı yazılmış

Hicrâni bağrımı ırgalar gibi

Zindan kuyuları derin kazılmış

Yusufu kaderi yargılar gibi

Ne güzel donatmış aşkı mimarim

Sevdayla çağlıyor gönül pınarım

Umut bahçesinde çiçek ararım

Kırlarda dolaşan arılar gibi

Acımasız olmuş her geçen yıllar

Bazı kara giydim bazıda allar

Gül için baharı bekler bülbüller

Eşinden ayrılmış kumrular gibi

Acı dertler ile geçti çağlarım

Baharı görmeden soldu bağlarım

Kalbim Rabbim diyer özden ağlarım

Ana''sına sadık yavrular gibi

Tuncayım ne zaman oldum bahtiyar

Dünyası ömrümü etti ihtiyar

Kimleri güldürmüş bu fani diyar

Hergün gider gelir sorgular gibi', 'Kaderime hayat acı yazılmış Hicrâni bağrımı ırgalar gibi Zindan kuyuları derin kazılmış Yusufu kaderi yargılar gibi Ne güzel donatmış aşkı m...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cile-kuyusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskiden', 'eskiden-muhiddin-ates-k9xfu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İnsanlık dünyadan ayrıldı

Meydan namertlere kaldı

Dünyayı yüzsüzler sardı

Eskiden insanın hası vardı

Ağa oldu hırsızlar

Utanmadı arsızlar

Sardı etrafı nursuzlar

Eskiden ar ile namus vardı

Anaya babaya ikram kalktı

Kimi anasını sokağa attı

Ya da fikir ölsede kurtulsaktı

Eskiden ölünün yası vardı

Gençler bara pavyona daldı

Sevdalar da anlık yaşanır oldu

Aşklar bir gecede yeşerip soldu

Eskiden sevdanın tadı vardı.', 'İnsanlık dünyadan ayrıldı Meydan namertlere kaldı Dünyayı yüzsüzler sardı Eskiden insanın hası vardı Ağa oldu hırsızlar Utanmadı arsızlar Sa...', ARRAY['Türk Edebiyatı','Şiir','Muhiddin Ateş']::text[], 8.5, '{"poet":"Muhiddin Ateş","poet_slug":"muhiddin-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eskiden-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niyazi 05', 'niyazi-05-nurten-altinok-of3mr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '.........‘’Sıcak su akmıyor ‘  diye seslendi Niyazi. Sesi banyodan geliyordu.

Apartmandaki gürültüler yavaş yavaş azaldı. Kapının dürbününden dışarı baktım, karşı dairenin kapısı açıldı, on yaşlarında bir çocuk,  içinde ekmek ve gazete olan poşeti kapıcıdan aldı, kapıyı kapattı. 

            Kapıcı,  bizim kapıya doğru ilerledi. Niyazi, zilin sesini duymasın diye, kapıyı hemen açtım. 

-Ne var yine Niyazi efendi? 

-Akşam saat sekizde toplantı varmış,dedi, yeni yönetici seçilecekmiş, onu haber vermeye geldim, varsa çöpü de alayım abla. 

‘Bekle biraz’ dedim, büyükçe bir poşet alıp Niyazi’nin giydiği, sonra, zorla  çıkarttığım ne kadar deniz malzemesi varsa toplayıp poşetin içine koydum, kapıcının eline tutuşturdum.: 

- At bunları, ama dikkat et bizim Niyazi görmesin.

-Abla be, dedi, atmayayım da saklayayım. Bakarsın bir gün denize gideriz. Bizimkini de (şişme kadından bahsediyordu)      aşağıdaki lastikçiye veririm de yapıştırır. Hangi denize gideceksiniz? 

Gözündeki morluğa gözüm takıldı, gülmeye başladım. Elliyle gözünü ovuşturdu ‘kapıya çarptım az önce’ dedi.

Bir gürültü koptu içerde. Birkaç sandalye devrildi sanki, kapılar hızla açılıp kapandı. Arkamı döndüm, Niyazi nefes nefese:

-Deniz mi? Denize mi gidiyoruz? 

Kocaman açmış gözlerini Niyazi bana bakıyor ve sevinçle bağırıyor.

-Denize mi gidiyoruz? Yaşasın! 

-Çabuk banyoya, dedim.

Yarıçıplaktı. Beline düğümlediği bir havluya sarınmıştı. Elimdeki çöp poşetini gördü, çöp poşetinin içinde biraz önce zorla çıkarttığım deniz giysilerini. Ani bir hareketle poşete uzandı, elimden kaptı. 

Havlunun düğümü çözüldü! 

-Allah, dedim, seni bildiği gibi yapsın Niyazi. Çabuk banyoya git ve yıkan. Bırak o poşeti yere.

-Ne bağırıyorsun, dedi. Eğilmiş, yere düşen havlusunu almaya çalışırken. Mayo var altımda. 

Bedeninden birkaç numara büyük mayosu paçalarına doğru sarkıyordu. Utanmıştı. 

-Sıcak suyu açamıyorum işte, açar mısın? 

Yere düşen havlusunu aldı, beline sarmaya başladı, bir türlü düğüm atamadı.

Poşeti kapıcının eline tutuşturdum. 

-Uzaktaki bir çöp bidonuna at, Niyazi görmesin, dedim. Yoksa gider alır.

Sıcak suyu açmaya gittim. 

Niyazi iki saatten beri banyoda hala yıkanıyor. Kafam takıldı. Boğulmasın bu adam! Sesi soluğu da çıkmıyor! Bir daha banyo yaptığında bir düdük alayım bari. Ara sıra öttürsün de yaşadığını bileyim.

-Niyazi, hadi çıkmıyor musun? Dedim, merakla. Akşam oldu.

Biraz sonra kapıyı açtı.

-Sıhhatler olsun Niyazi, dedim. Yüzü gözü parlamış, tertemiz giyinmiş, taranmış.

Kapının açılmasıyla evin içine ağır bir parfüm kokusu yayıldı.

-Kızlar seni kapacak Niyazi, bu ne yakışıklılık böyle? Hadi gel seni sinemaya götüreyim.

Aynanın karşısına geçti, kendine bir daha baktı, gülümsedi.

-Yakışıklı olmuşum değil mi? dedi. Ama kravatım yok. Varsa,  Onur’ un kravatlarından bir tane verir misin takayım? Mavi olsun ama. Nasıl olsa o şimdi askere gidecek, ona kravat lazım olmaz.

-Evet, dedim. Haftaya gidiyor. 

Kalktım, mavi bir kravat aldım getirdim.

Bir hüzün çöktü evin içine. Yüzüme baktı. Dudağındaki gülümseme titredi. 

-Üzülme, dedi. Sayılı gündür gelir geçer. Hadi kalk çıkalım, sinemaya gitmeyecek miyiz? 

O da üzülmüştü.

Kravatı tüm uğraşmalarımıza rağmen bağlayamadık. 

Canım da hiçbir yere gitmek istemiyor ya,  hadi gitmeyelim, desem, daha çok üzülecek.

Üstündeki ceketini çıkarttı ani bir hareketle, sandalyenin üstüne koydu.

-Ne oldu? Dedim. Vaz mı geçtin gitmekten? 

-Geç oldu şimdi, dedi, başka zaman gitsek! Hem akşam apartman toplantısı varmış, gitmeyecek miyiz? Gel televizyon seyredelim, gidinceye kadar. Kahve ister misin? 

-Sende mi geleceksin toplantıya? Olmaz öyle şey. Çocuklar evde oturur. Bir de toplantıyı karıştırmayalım şimdi? 

Apartman toplantısını çoktan unutmuştum oysa.

Yarım saat televizyonda seyredecek bir şeyler aradık. Hiç birini beğenmedi. 

-Neden bu saatlerde hiç çizgi film koymazlar, anlamadım ki! ... 

Kendi kendine konuşmaya başladı. 

Kahve yapmak için mutfağa gittim. Döndüğümde, içi su dolu kocaman bir leğen salonun ortasında, televizyonun kumandası Niyazi’nin elinde gemi olmuş, yüzüyor leğende. Niyazi ikiseksen uzanmış yere. 

-Cuuufufuuuffff cuffff cuufffff.... ddüüüttttttt...düütttttt...

-Eyvah! Boğuldu kumandalar! Eh be Niyazi! 

-Gel, dedi, beni görünce. Hadi otur yanıma.

Elinde tuttuğu ikinci kumandayı da bana uzattı.

-Yolculuk nereye Niyazi? 

-Denize, denize...

-Benim gemim senin gemini geçer ama, dedim. Dirseklerime kadar kollarımı leğene daldırdım.

-Geçemezsin

-Geçerim

-Geçemezsin

-Geçerim 

Aaaaaa,  dedi, gemiler karaya oturdu. Dur, ben banyodan bir kova daha su getireyim.

Leğende su bitmiş ! 



-Çıkarttım da içimdeki çocuğu

Oturdum Niyazi’nin karşısına

Bir leğen dolusu su oldu dingin denizimiz 

İki kumandadan rotasız gemimiz

Rüzgarı lodosu poyrazı nefesimiz.

Bastırılmış duygularımız var ya hani, abdestbozan

Bir türlü su üstüne çıkaramadığımız

Ya ayıptır düşünmek ya günah 

Ya da ‘el alem ne der’ e kurban

Hani bitiremediğimiz işlerimiz var ya, hep yarım kalan

Hani söyleyemediğimiz sözlerimiz, dilimizin ucuna takılan

Cevaplayamadığımız sorularımız

Çözemediğimiz problemlerimiz, uykukaçıran

Anlatamadığımız kördüğüm sevdalarımız şiirlerde 

Karşılıksız sevmelerimiz maviyi delicesine

Nefes almalarımız karageceler içinde

Bütün bunları ve daha nicelerini

Atıverdim bir leğen okyanusun içine

Konuştum sorumsuzçocuk yüreğimle

Oyunlar oynadım  Niyazi’ yle

Günah çıkartır gibi acılardan

Bir kelebek kondu omuzlarıma

Yerçekimi kayınca ayaklarımdan

Taş sektirdim yakamozlara

Yelken açtım coğrafyasız dünyamdan

Seviyorum içimdeki çocuk beni

Seni de dert ortağım Niyazi

Seni de seviyorum düşMavisi

seni de masmavi

Benim hiç olmadı ki oynayacak gemim

Hep gerçek trenlerde ağladık ben ve bezbebeğim

Ayaklarımı uçuramadım ki suda, suyayangın 

Bu yüzdendir boğulur mavilerde yüreğim 

Bir leğen su oldu da dingin denizimiz 

Bir avuç suda yol aldı rotasız gemimiz...

....................devam edecek...', '.........‘’Sıcak su akmıyor ‘  diye seslendi Niyazi. Sesi banyodan geliyordu. Apartmandaki gürültüler yavaş yavaş azaldı. Kapının dürbününde...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":97,"source_url":"https://www.antoloji.com/niyazi-05-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Bizim Hâlimiz...(ı)', 'i-ste-bizim-h-limiz-i-dursun-elmas-j2vjk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Afyon yemiş milletim,uzaktan seyretmekte; 

Zalimin dâvâsına,''benim dâvâm''demekte.

Zürriyet haram oldu,ecdat lânet etmekte; 

Haram olunca evlât,zalime ''âbîd'' şimdi.

Siyaset amaç şimdi,dava tufan oluyor

Siyasetin uğruna,fikir talan oluyor.

Vaat yerine gelmez,ilke yalan oluyor

Döneklik pek revaçta,şirret rağbette şimdi.

''Cihad''fikri kayboldu,herkes ''liberal'' şimdi

Zalim zulmünde hâlâ,mazlum terörist şimdi.

Kâfire kâfir demek,ayıp şimdi,suç şimdi

Namertler yğit oldu,ihanet moda şimdi.

Küffârın nârâsına,''tekbirl''ler köle oldu

Kelime-i Tevhd''se,viranede kayboldu

Hidâyet nuru giti,dâlâlet izzet buldu

Düştüğümüz gaflete,asuman ağlar şimdi.

Kitaplar okunmuyor,raflarda tozlanıyor

Cehâlet hükme geldi,insanım yozlanıyor.

Bütün cihan önünde,zulüm palazlanıyor

Kitap mahkum,dil suskun,gönüller paslı şimdi.

Menfaat rağbettedir,herkes bakar keyfine

Yoksulluk unutuldu,musluk akar zengine.

Şecaati gömdüler,okyanusun dibine

''Emret Beyim''diyenler,itibar bulur şimdi.', 'Afyon yemiş milletim,uzaktan seyretmekte;  Zalimin dâvâsına,''benim dâvâm''demekte. Zürriyet haram oldu,ecdat lânet etmekte;  Haram olunca evl...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/iste-bizim-halimiz-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Gibisin', 'dus-gibisin-muhiddin-ates-obmz9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllardır aklımdan hiç çıkaramadığım

Rüya mı kabus mu ayıramadığım

Hayra yormak isteyip yoramadığım

Gecelerimi zindan eden düş gibisin

Bilmem ki aklım ermiyor nesin necisin

Sen hayatımda bir kördüğüm misalisin

Cevabını bulamam çözsem çözülmezsin

Aklımı karıştıran bulmaca gibisin

Hakkın yok senin dünyamı ters döndürmeye

Ağlattınya çaba harcama güldürmeye

Denizler yetmez yangınımı söndürmeye

Yüreğime düşüp yanan ateş gibisin.', 'Yıllardır aklımdan hiç çıkaramadığım Rüya mı kabus mu ayıramadığım Hayra yormak isteyip yoramadığım Gecelerimi zindan eden düş gibisin Bilme...', ARRAY['Türk Edebiyatı','Şiir','Muhiddin Ateş']::text[], 8.5, '{"poet":"Muhiddin Ateş","poet_slug":"muhiddin-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dus-gibisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralarım Azar Gider', 'yaralarim-azar-gider-muhiddin-ates-548g4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu böyle nasıl dertmiş

Yüreğime hasret ekmiş

Yar aşkımı pazar etmiş

Satar gider

Dert bende katar katar

İçerimde hasret yatar

Özlem alır sevda satar

Yaralarım azar giger

Aşk gemisinin içinde

Sevdam garip biçimde

Hasretin denizinde

Batar gider

Yarınlara umudu

Duyabilsem ne mutlu

Yar dallarımı kuruttu

Yıkar gider

Allah''ım bu nasıl çile

Kilit vurdu göze dile

Dertlerimi yüklesem file

Çöker gider', 'Bu böyle nasıl dertmiş Yüreğime hasret ekmiş Yar aşkımı pazar etmiş Satar gider Dert bende katar katar İçerimde hasret yatar Özlem alır sevd...', ARRAY['Türk Edebiyatı','Şiir','Muhiddin Ateş']::text[], 8.5, '{"poet":"Muhiddin Ateş","poet_slug":"muhiddin-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yaralarim-azar-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden başkasını Sevemem', 'senden-baskasini-sevemem-dursun-elmas-0s7zy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne kadar hassassın,incesin tezsin

Bir o kadar zarif ve de içtensin

Sen bilmezsen beni,eller ne bilsin

Senden başkasını  sevemem asla

Damarımda,kanımda, canımdasın

Varımda-yoğumda hep yanımdasın

Bu yürek harınla yanarsa yansın

Senden başkasını   sevemem asla

Sen sulu gönlümün nilüferisin

Sevda ülkemdeki,asil perisin

İnan ki; sen bana benden berisin

Senden başkasını  sevemem asla', 'Ne kadar hassassın,incesin tezsin Bir o kadar zarif ve de içtensin Sen bilmezsen beni,eller ne bilsin Senden başkasını  sevemem asla Damarım...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senden-baskasini-sevemem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Unutmam! ..(şarkı sözü)', 'seni-unutmam-sarki-sozu-dursun-elmas-xjovh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anladım,bir daha görüşemeyiz

Bir yarım ekmeği bölüşemeyiz

Bu dünyada artık buluşamayız

Unutmam sevgilim...Seni unutmam! ..

Hiç kırmadın beni,hiç de üzmedin

Katlandın çileme,bir gün bezmedin

Benden ayrı kimselerle gezmedin

Unutmam sevgilim...seni unutmam! ..

Bu can bedenimden çıkana kadar

Bir daha dönmesen ölene kadar

Mahşeri aleme göçene kadar

Unutmam sevgilim...seni unutmam! ..', 'Anladım,bir daha görüşemeyiz Bir yarım ekmeği bölüşemeyiz Bu dünyada artık buluşamayız Unutmam sevgilim...Seni unutmam! .. Hiç kırmadın beni...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-unutmam-sarki-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Evrenseldir', 'ask-evrenseldir-omer-bolat-1369n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '“Aşk evrenseldir” derler.

Kavganın ve savaşın

Yenilmez kahramanları,

Aşkın önünde diz çökerler.

Aşk kalem gibidir, lakin

Kalemden de, kılıçtan da

Üstündür sevgili…

Beni hayata döndüren,

Sensin sevgili.

Beni her an öldüren,

Yine sen…

Ne kalemle yerdiler 

Sanatımı

Ne de kılıçla kestiler 

Yazan ellerimi.

Daha keskindi, bana saplanan

Öldürmeyen kurşun gibi…', '“Aşk evrenseldir” derler. Kavganın ve savaşın Yenilmez kahramanları, Aşkın önünde diz çökerler. Aşk kalem gibidir, lakin Kalemden de, kılıçt...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bolat']::text[], 8.5, '{"poet":"Ömer Bolat","poet_slug":"omer-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ask-evrenseldir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlidillim guzel yuzlum', 'tatlidillim-guzel-yuzlum-husamettin-guven-3qtu2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Canim sensiz ben bir hicim

Eriyorum  icin icin

Anlamazsin beni nicin

Tatlidillim guzel yuzlum

Inat etme gel bu yana

Olayim ben kurban sana

Son sozonu soyle bana

Tatli dillim guzel yuzlum

Evetdersen ben varayim

Senin icin can vereyim

Ugrunda ben oleyim

Tatlidillim guzel yuzlum

Hollanda', 'Canim sensiz ben bir hicim Eriyorum  icin icin Anlamazsin beni nicin Tatlidillim guzel yuzlum Inat etme gel bu yana Olayim ben kurban sana S...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tatlidillim-guzel-yuzlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum seni yarim', 'seviyorum-seni-yarim-husamettin-guven-9wfi2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kahir dolu hep sozlerim

Yasla dolu bak gozlerim

Bilki seni cok ozlerim

Seviyorum seni yarim

Tatli tatli guluslerin

Nede hosdu bakislarin

O gozlerle suzuslerin

Seviyorum seni yarim

Kalem gibi  kaslarinla

Surmeli o gozlerinle

Inci gibi dislerinle

Seviyorum seni yarim

Hollanda', 'Kahir dolu hep sozlerim Yasla dolu bak gozlerim Bilki seni cok ozlerim Seviyorum seni yarim Tatli tatli guluslerin Nede hosdu bakislarin O g...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seviyorum-seni-yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım', 'canim-yusuf-ter-6kvbq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'can cana,

 hasret kalırsa 

 bu can seni arzular 

