INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öfkem Var', 'ofkem-var-alaattin-ceylan-6u3b9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ürünü olmayan toprağa

Dalı olmayan yaprağa

Her türlü sapıklığa sapmaya

Öfkem var gardaş 

Öfkem var gardaş

Kelimesi olmayan heceye

Gündüzü olmayan geceye

Kendini dev sanan cüceye

Öfkem var gardaş

Öfkem var gardaş

Evladını atan anaya

Sorumluluk bilmeyen babaya

Söz dinlemeyen balaya

Öfkem var gardaş

Öfkem var gardaş

Doğruyu söylemeyen alime

Müslümanım diyen zalime

Adaletle hükmetmeyen hakime

Öfkem var gardaş

Öfkem var gardaş

Gerçeği görmeyen göze

Yerini bulmayan söze

Namerte çöken dize 

Öfkem var gardaş

Öfkem var gardaş

Işığı olmayan güneşe

Yüzseksen derece dönüşe

Hiç direnmeden çöküşü

Öfkem var gardaş

Öfkem var gardaş

Fareden kaçan kediye

Kurt sanılan köpeğe

Semer vurulan eşeğe

Öfkem var gardaş

Öfkem var gardaş

Çakalın attığı naraya

Tuz basılan yaraya

Tav tutmayan mayaya

Öfkem var gardaş

Öfkem var gardaş', 'Ürünü olmayan toprağa Dalı olmayan yaprağa Her türlü sapıklığa sapmaya Öfkem var gardaş  Öfkem var gardaş Kelimesi olmayan heceye Gündüzü ol...', ARRAY['Türk Edebiyatı','Şiir','Alaattin Ceylan']::text[], 8.5, '{"poet":"Alaattin Ceylan","poet_slug":"alaattin-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ofkem-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kor Bakışların I', 'kor-bakislarin-i-fatih-taskin-ylub8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cama vuran yüzün yarısındaydı 

Beni aşık eden yar bakışların 

Gözümün yaşına daldığım andı 

Olmaz anlamında fer bakışların 

Güneştin sabahtan Başkente doğan 

Bakıp erirdi bu akşamdan kalan 

Şuh bir gülüşe ateşler yakan 

Haziran soğuğu kar bakışların

Aslından güzeldi cama yansıyan 

Suretinde  kaldı aklımı çalan 

Hilal  kaşlarınla  anlamlandıran 

Beni benden etti kor bakışların..

siyahbereli

mart-05', 'Cama vuran yüzün yarısındaydı  Beni aşık eden yar bakışların  Gözümün yaşına daldığım andı  Olmaz anlamında fer bakışların  Güneştin sabahta...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kor-bakislarin-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filistin Türküsü (1)', 'filistin-turkusu-1-i-lyas-kambali-a9bz6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Filistin ki bir yükselişin diyarı 

Şimdi kan ağlıyor taşı toprağı

Zalim dünyaya imdat haykırıyor kızları

Bu ümmet nasıl da oldu bir uşak

Kendi ülkesinde mülteci bir halk

Koşmaz yardımına ne bir el ne bir ayak

Hani bir vücudun azaları gibiydik biz

Nerde kaldı din kardeşliğimiz

Tükenmiş bugün vay tüm hasletlerimiz

Endülüs ki onu çoktan unuttuk

Heyhat! Filistin artık bir yatalak

Ha bugün ha yarın düştü düşecek

Uyanın ey dünya Müslümanları! 

O diyar ki İslam’ın namusu arı

Haydi! sürelim Siyonist postalları

Ey halkı Müslüman belde kralları! 

Bir avuç kafirin korkak oyuncakları

Sizi de boğacak şehit kanları

Bu ne atalet bu ne rehavet

Vay ölüm uykusunu kuşandı bu ümmet

Rabbim! Filistin’e sen eyle merhamet

İlyas KAMBALI

10. 04. 2002', 'Filistin ki bir yükselişin diyarı  Şimdi kan ağlıyor taşı toprağı Zalim dünyaya imdat haykırıyor kızları Bu ümmet nasıl da oldu bir uşak Ken...', ARRAY['Türk Edebiyatı','Şiir','İlyas Kambalı']::text[], 8.5, '{"poet":"İlyas Kambalı","poet_slug":"i-lyas-kambali","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/filistin-turkusu-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filistin Türküsü (2)', 'filistin-turkusu-2-i-lyas-kambali-u3cp9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Filistin ki bir yükselişin diyarı 

Şimdi kan ağlıyor taşı toprağı

İmdat  haykırıyor masum kızları

Yetim çocukları neni yavrum neni

Siyonist namlular ölüm saçıyor

Küçük bebekleri hedef seçiyor

Kör olası dünya nasıl uyuyor

Neni yavrum neni neni de neni

Rahmet düşmez yere kurşun yağıyor

Bir baba bir yavru kurban oluyor

Siyonist namlular kana doymuyor

Neni yavrum neni neni de neni

Bu ümmet nasıl da oldu bir uşak 

Kendi ülkesinde mülteci bir halk 

Koşmaz yardımına ne bir el ne bir ayak

Rabbim! Filistin’e sen eyle merhamet. 

İlyas KAMBALI

10. 04. 2002', 'Filistin ki bir yükselişin diyarı  Şimdi kan ağlıyor taşı toprağı İmdat  haykırıyor masum kızları Yetim çocukları neni yavrum neni Siyonist ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Kambalı']::text[], 8.5, '{"poet":"İlyas Kambalı","poet_slug":"i-lyas-kambali","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/filistin-turkusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Seni Kokmalı', 'her-sey-seni-kokmali-huseyin-erdogan-n7ubm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'geceleri bir tek

ben olsam rüyanda

her sabah bir güneş gibi

doğsam dünyana

bir bahar olup açsam

o güzel yüreğinde

söyler misin sen de? 

yalnızca 

beni koklar mısın ömrünce? 

kokum sinmeli

bedeninin her yerine iyice

tenin beni kokmalı

hem gündüz hem de gece

rüzgarlar esmeli

yağmurlar yağmalı

şair aromalı

çiçeklerin hepsi

kokularını benden almalı

dalgalar beni vurmalı

sahilleri benim kokum sarmalı

bana da her şey seni kokmalı

                        05.04.2005', 'geceleri bir tek ben olsam rüyanda her sabah bir güneş gibi doğsam dünyana bir bahar olup açsam o güzel yüreğinde söyler misin sen de?  yaln...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/her-sey-seni-kokmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Puslu,siyah,Beyaz', 'puslu-siyah-beyaz-cemal-gokmen-39zlj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece bir başkalık var gökyüzünde

siyah,mavi karışımı kızıla dönmüş

ağlayan bir adam var 

puslu,siyah beyaz hatıralarına..

bir rüzgar ıslığı duyuluyor

aman vermez yaralarda

yalayıp,yakmakta düşümsü beraberliklerin

uykusuz gecelerinde..

farkedilmez rüyaların anımsanmayan

zamanlarında bir adam bakıyor

puslu,siyah,beyaz hatıralarına', 'Bu gece bir başkalık var gökyüzünde siyah,mavi karışımı kızıla dönmüş ağlayan bir adam var  puslu,siyah beyaz hatıralarına.. bir rüzgar ıslı...', ARRAY['Türk Edebiyatı','Şiir','Cemal Gökmen']::text[], 8.5, '{"poet":"Cemal Gökmen","poet_slug":"cemal-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/puslu-siyah-beyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tohum', 'tohum-ayhan-isin-taf7k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bahar mı geliyor? 

Ağaçlarda tomurcuklar,

Gülde göz göz olmuş filizler, 

Havada güneş, ak ak olmuş bulutlar.

Toprak fışkırmak için

Kuşların şarkılarını mı bekler? 

Sokaklarda yamur gölcükleri,

Eşiklerde kadınlar,

Bahçelerde çocuklar.

Bebeklerin ağlamaları,

Kedilerin aşk şarkılarına karışır.

Genç bir delikanlının,

Aşk dolu tebessümü,

Güzel bir kızın gözlerinde,

Közlenmiş külleri alevlendirir.

Bahar mı geliyor? 

Ben senin gözlerine,

Mahkum olmuş,

Toprağına düşmüş tohum,

Yeniden can bulacakmıyım? 

Köklerimi salacakmıyım,

Toprağına.

Kollarımı uzatacakmıyım? 

Kollarına,

Buluşacakmıyız, güneşin tahtında? 

Ben güzde kalmış tohum,

Çürümeye yüz tutmuş.

Bekliyorum toprağının sıcağında

Beni kavuşturacakmısın? 

Gözlerinin alevine.

Yine yakacakmısın, Alevinle? 

Bekliyorum baharın gelmesini,

Geçmiş Baharın Özlemiyle....

(24-02-2005)', 'Bahar mı geliyor?  Ağaçlarda tomurcuklar, Gülde göz göz olmuş filizler,  Havada güneş, ak ak olmuş bulutlar. Toprak fışkırmak için Kuşların ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Işın']::text[], 8.5, '{"poet":"Ayhan Işın","poet_slug":"ayhan-isin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/tohum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancı', 'sanci-mehmet-ali-cibikli-7nbt8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni bende bırakıp

Gittiğini hiç sanma.

Ya beni de götürdün

Ya sen geldin yanıma.

Birden bırakıp gitmek

Öyle kolay mı sandın? 

Aşk derdine düşmüşsen

Yandın güzelim yandın.

Sen gittin ya buradan

Yokluğun bana kaldı.

Sensizliğin tadı yok

Sensiz içim daraldı.

Sensizliğin ötesi,

Seninle dolu dolu.

Sensizliğin berisi

Bir garip Anadolu.

Seninle gezdiğimiz

Yerler şimdi yabancı.

Yokluğun yüreğimde

Dinmeyen büyük sancı.', 'Beni bende bırakıp Gittiğini hiç sanma. Ya beni de götürdün Ya sen geldin yanıma. Birden bırakıp gitmek Öyle kolay mı sandın?  Aşk derdine d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sanci-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bakış', 'bir-bakis-i-smet-barlioglu-h9q14', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Böyle mi vururmuş bir bakış, yüreğinden insanı,

Böyle mi altı üstüne gelirmiş dünyanın,

İnsan böyle mi karayı ak, akı kara görürmüş

Binbir kavak yelleri eserken başında,

Bir ayağı maşrıkta,

Bir ayağı mağripteyken,

Böyle mi dalarmış enginlere

Pupayelken? 

Unutabilir misin içinde bir şeylerin kıpırdandığını,

Gönlüne sıcak yağmurların yağdığını,

Birer bez gibi yırtılıp açıldığını karanlıkların,

Unutabilir misin

Boğulduğunu çevrenin güle-çimene

Ve keskin bir hançerin saplandığını

Yüreğine? 

Ben bir bakışıyla düştüm sevdasına yarin,

Bilemedim sağımı, solumu

Nice bir geceler,

Kuştüyü yastıklarda bıraktım uykuyu.

Ağladım, hüzne yordular,

Güldüm, deli bellediler,

Kabahatin sevende değil, sevilende olduğunu

Bilemediler.

El ne bilsin. Ben bilirim içimi kavuran ateşi,

İsa gibi gerilmişim çarmıhlara,

Vadedilmiş toprak arıyorum Musa gibi çöllerde,

Ben bu sevdaya gerçekten yakışmışım ki; 

Aşkım dillerde.

(TANRI ÖNCE BENİ YARATTI isimli Serbest Şiirler ''inden > 65-66/100)', 'Böyle mi vururmuş bir bakış, yüreğinden insanı, Böyle mi altı üstüne gelirmiş dünyanın, İnsan böyle mi karayı ak, akı kara görürmüş Binbir k...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bir-bakis-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Sultanı', 'gonul-sultani-i-smet-barlioglu-g0x7r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen bu kadar güzel olamazsın, benim gözlerim olmasa,

Kuşlar gibi cıvıldayamazsın böyle,

Keklikler gibi yürüyemezsin,

Boy ölçüşemezsin fidanlarla, boy söz konusu oldukta.

Benim gözlerim olmasa; 

Sen kayan bir yıldız gibi parlayamazsın

Karanlıkta.

Giyinen sen değilsin,

Ben seni giydiriyorum,

Seni ben süslüyor, ben bezetiyorum,

Ben bulup buluşturuyor, ben sarıyorum seni tüllere,

Ben serpiyorum üstüne gül kokularını,

Miski, amberi,

Bu yeni olmuş bir şey değil anam, babam,

Tanıdığımdan beri.

Ben öğrettim sana, elifin mertek olmadığını,

Ayvanın sarı, narın kırmızı olduğunu,

İnsanın birine bir bakışta tutulduğunu,

Sana ben öğrettim Hanya ‘yı-Konya ‘yı,

Ben olmasam sen nereden bilip anlayacaktın

Dünyayı? 

Şimdi bir elin mühürde, biri fermanda,

Sultanlarca fermanlar yazıyorsun katlime,

Sen bir dev olmuşsun, ben senin yanında karınca,

Vur boynumu vurabildiğin gibi,

Ellerimi-kollarımı kestir kırk satırla,

Beni kırk katıra bağlatıp sürdür bir yana her birini,

İnan ki; ne dilim söyler, ne kanım akar; 

Bir gönül sultanına baş mı kaldırabilir

Kullar? 

(TANRI ÖNCE BENİ YARATTI isimli Serbest Şiirler ''inden > 67-68/100)', 'Sen bu kadar güzel olamazsın, benim gözlerim olmasa, Kuşlar gibi cıvıldayamazsın böyle, Keklikler gibi yürüyemezsin, Boy ölçüşemezsin fidanl...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gonul-sultani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar Sonra...', 'yillar-sonra-i-brahim-ethem-bingul-l24ia', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaçmıştım gerçeklerden, acıdır yakar diye

Senelerin selinde akmış, sürüklenmişim

Musallanın tahtından, odur vefakâr diye

Kucak açan toprağa bayram olsun inişim...

Kolları beni sarar, ona derler sadık yâr

Sözümde sadakati göstermezsem fayda yok

Kendime yâr olmazsam temenni neye yarar

Işık kalpte olmalı; güneşte yok, ayda yok...

Sağlıklı her nefeste ne yüce değer gizli 

Aşikar bir hazine huzuru bulan her kalp

İnleyen hastalarda ıstıraplar aleni

Kalp gözü âmaların görebildiği serap...

Kaçmıştım gerçeklerden, acıdır yakar diye

Gerçekten kaçılmazmış, yıllar sonra anladım

Bugün gerçeğin oku uçup düştü kalbime

Bugün maziye güldüm, geleceğe ağladım...

www.iebingül.com', 'Kaçmıştım gerçeklerden, acıdır yakar diye Senelerin selinde akmış, sürüklenmişim Musallanın tahtından, odur vefakâr diye Kucak açan toprağa ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yillar-sonra-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaratan Düşürmüş Eline', 'yaratan-dusurmus-eline-i-smet-barlioglu-2hg1c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir güzel dünyaya kapatmışlardı beni,

Aşkı-sevdayı bilmediğim için,

Bağlamışlardı ellerimi güllerle, çiçeklerle,

Önüme dağları, denizleri koymuşlardı,

Çevremde kuşlar cıvıldaşırdı,

Irmaklar akardı yanımdan-yöremden,

Bir elim yağda, bir elim baldaydı, senin anlayacağın,

Benim bile aklıma gelmemişti

Karşıma çıkacağın.

Değişen fazla bir şey olmadı,

Aydınlıklardan çıkarıp verdiler karanlıklarımı

Kalkıp aşka-sevdaya düştüğüm için,

Zincirlerle bağladılar ellerimi-kollarımı

Gülleri, çiçekleri çıkarıp.

Artık ne önümde dağlar, denizler,

Ne çevremde kuş cıvıltıları,

Ne de ırmaklar; yanımdan-yöremden akan,

Zira, aşkı işte böyle bir şey yapmış

Yaratan.

Artık ne bir elim yağda, ne obir elim balda,

her biri zehir-zakkum lokmalarımın,

Her damla suyum zehir-zemberek,

Her bir derde,

Her bir çileye alışır oldum

Giderek.

Şimdi aradığım sensin uykularda,

Varlığınla aydınlanacak olan karanlıklarda,

Şimdi seni edinmişim kuş cıvıltısı çevreme,

Yanıma-yöreme seni edinmişim ırmak,

Seni koymuşum dağların, denizlerin yerine,

Zira, Yaratan beni pek beter düşürmüş

Eline.

(TANRI ÖNCE BENİ YARATTI isimli Serbest Şiirler ''inden > 69-70/100)', 'Bir güzel dünyaya kapatmışlardı beni, Aşkı-sevdayı bilmediğim için, Bağlamışlardı ellerimi güllerle, çiçeklerle, Önüme dağları, denizleri ko...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yaratan-dusurmus-eline-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Hüzün**Hoş geldin', 'elveda-huzun-hos-geldin-olgun-ekinci-p5i98', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gürül gürül, sarıl şarıl

Irmak ırmak, deniz deniz

Dalgalarla, boranlarla

Geldin

Gelen sen değil suretin, sesin...

Soğuk tu, yanlız dım, yağmur çiseliyor du

Solist kızın buğulu sesiyle seslendirdiği

DOYMADIM DOYAMADIM SEVMELERE SENİ BEN

KİMSEYİ KOYAMADIM YERİNE… nin ardından

Şelalere çağlayanlara dönüşen 

Bahar çimenlerini sulayan sağanaklarla geldin

Gökkuşağına dönüşen renklerle ışıttın

Saatlerin 01.e vurduğu gece yarısını

Seyhan nehrinde gün döndü gece döndü

Şimşekler havai fişeklerce süzülürken lacivert semalarda

1 Nisan şakası mıydı? 

Esrikliğimin dayanılmaz hafifliği mi? 

Düş bitti

__Yağmur bitti

____Gök kuşağıydı gelen…

Hoş geldin... Hoş geldin... Hoş geldin...

1 Nisan 2005 - Adana', 'Gürül gürül, sarıl şarıl Irmak ırmak, deniz deniz Dalgalarla, boranlarla Geldin Gelen sen değil suretin, sesin... Soğuk tu, yanlız dım, yağm...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/elveda-huzun-hos-geldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrak Oğlum Ve Ben', 'bayrak-oglum-ve-ben-olgun-ekinci-2cz3r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yer siyah

__Gök Beyaz

En büyüksün-Şampiyonsun

__Beşiktaş

Sloganlarıyla odaları inlettiğimiz oğlum

Kara kartal mozaikli

Tüm bayraklara el koydu

Dikiz aynamdaki flamayı

__Panosuna

Bagajımdaki çubuklu bayrağı

__Penceresine

Kilerdeki en güzel bayrağı

__Duvarına astı

Koçum birini geri ver dedim

''Hak verilmez alınır		

Dönmeye değil		

Ölmeye		

_Ölmeye		

__Ölmeye geldik'''' sloganlarıyla		

Karşı tribünlere kovaladı		

Bayraksız kaldım		

__Bayraksızım artık…		

1 Nisan 2005 - Adana', 'Yer siyah __Gök Beyaz En büyüksün-Şampiyonsun __Beşiktaş Sloganlarıyla odaları inlettiğimiz oğlum Kara kartal mozaikli Tüm bayraklara el koy...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bayrak-oglum-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz', 'karadeniz-ziya-nizam-vl9ft', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine coştu bak Karadeniz

Aynı yüreğim gibi.

Kimbilir kimi seviyor o da.

Bazen kızıyor

Dövüyor kıyıları.

Bazen uysal,

Ufacık bir bebek gibi,

Sakin ve pürüzsüz.

Yağmurla dans ediyor ara sıra.

Gemileri korkutuyor fırtınasıyla.

İnsanları,insanlardan daha çok seviyor.

Ne zaman kırsak birbirimizi

Hemen vuruyor suyunu taşlara

Durun diyor,ne oluyor size.

Bizi bizden daha iyi tanıyor.

Yaşıyor sevgiyle Karadeniz.

			16.01.1997-Perşembe

			01:10 Karadeniz FM Rize', 'Yine coştu bak Karadeniz Aynı yüreğim gibi. Kimbilir kimi seviyor o da. Bazen kızıyor Dövüyor kıyıları. Bazen uysal, Ufacık bir bebek gibi, ...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/karadeniz-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme Bahar Gelme', 'gelme-bahar-gelme-olgun-ekinci-1n2pj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gelme Bahar Gelme			

Ben her bahar			

Viraneye dönerim			

Sevdiğim o güzel insanlar			

O güzel dostlar			

Hep baharlar da gittiler			

Hep baharlar da yittiler…			

Birer birer			

__Gittiler…			

			

Benim baharlarım			

Kışlar, fırtınalar, soğuklar			

Ve Ankara''ya yakışan kar…			

Sizin baharlarınız da 			

Yine yeniden yaralanırım			

			

Ben baharlarım geldiğinde			

Üşürüm			

Üşüdükçe ısınır			

Isınıp çiçekler açtırırım yüreğimde			

Ben her kış geldiğinde			

Çiçek bahçemi üşütürüm			

Üşütür			

__Isıtır			

____Çiçekler büyütürüm…			

			

2 Nisan2005 - Adana', 'Gelme Bahar Gelme			 Ben her bahar			 Viraneye dönerim			 Sevdiğim o güzel insanlar			 O güzel dostlar			 Hep baharlar da gittiler			 Hep ba...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gelme-bahar-gelme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sigara ve Sen', 'sigara-ve-sen-ziya-nizam-vafss', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sigarayı seviyorum

Senden bile fazla.

Ciğerlerimi isyan ettire ettire

Çekiyorum en derine.

Doktor yasaklamış bana

Ben yine içiyorum.

Hem sende yasaksın bana.

Olamayız belki birlikte,

Sonumuz ayrılık belki.

Bu yüzden korkuyorum.

Senden korkuyorum,

Seni yıpratmaktan,

Seni kaybetmekten korkuyorum.

Sigarayı bu yüzden

Daha fazla seviyorum.

Onu üzemem,

Onu bırakamam.

O da beni.

Neyse

Tüm yasaklara rağmen

Ben seni de sigarayı da

Çok seviyorum.

			14.01.1997-Salı

			01:45 Karadeniz FM Rize', 'Sigarayı seviyorum Senden bile fazla. Ciğerlerimi isyan ettire ettire Çekiyorum en derine. Doktor yasaklamış bana Ben yine içiyorum. Hem sen...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sigara-ve-sen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-kemal-cakir-mpfjr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Göle atılmış bir taş gibi

Dalga dalga yayılıyor yalnızlığım

Vadilerde yaralı kartal misali

Hiç kimseye güvenim kalmadı.

Geçemiyorum üstüne basa basa

Kaldırım taşlarının

Her an  tutsak sular fışkırıp

Beni boğacak sanıyorum.

Bakamıyorum ağaçların dallarına,

Sarp kayalıklara,

Ansızın kalkıp bir şahin yada kartal

Konuverir diye omuzlarıma.

			

Ne zaman kış gelse içim ürperir

Sanki dağ başında yalnız ve çaresizim

Kurda kuşa yem olmaktan,

Üzerime çığ düşmesinden korkuyorum.

	

Alkol gibiyim, bir zerreyim bu dünyada

Uçacak bir gün ne varsa bende

Dibe vuracak yalnızlığım, tükenmişliğim

Sadece ölmekten korkmuyorum. Nedense? 

Bıktım!  rüzgarların amansız esişinden; 

Kasırgasından, melteminden...

Bıktım!  gecenin ürküten çehresinden; 

Yıldızından, ayından.

Bıktım gökyüzünün ağlayıp durmasından; 

Deresinden, ırmağından.

Bıktım artık, bıktım! 

Korkunun korkutan çehresinden.

Cesaretim doruğa vursun birden bire, 

Kanat açıp süzülsün bir kartal gibi

Korkunun cılız bedeni üzerinde 

Yuvalansın istiyorum.', 'Göle atılmış bir taş gibi Dalga dalga yayılıyor yalnızlığım Vadilerde yaralı kartal misali Hiç kimseye güvenim kalmadı. Geçemiyorum üstüne b...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yalnizligim-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cenaze Arabası Sürücüsü', 'cenaze-arabasi-surucusu-olgun-ekinci-em40u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çocukluğumda

İtfaiye şoförü olmak isterdim

En çok,

Siren sesleri çığlığında

Yol veren araçlar

Keyiflendiriyor, özendiriyordu yollar açıldığında

Çocuk yüreğimi…

Şimdilerde en çok

Cenaze arabası sürücüsü olmak istiyorum

Soğuk, kalpsiz, kaskatı

Düşünce yetilerini yitirmiş

Kurşun işlemez bir adam oldum

Duymuyor, algılamıyor, suskunum

Cenaze arabası sürücüsüyüm…

2 Nisan 2005 - Adana', 'Çocukluğumda İtfaiye şoförü olmak isterdim En çok, Siren sesleri çığlığında Yol veren araçlar Keyiflendiriyor, özendiriyordu yollar açıldığı...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cenaze-arabasi-surucusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gayrisi Sıratta Sorulsun', 'gayrisi-siratta-sorulsun-cafer-tayyar-ozkan-5ppov', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasret dayanmaz delicesine atıp duran kalplere,

Bir kere gelinmediyse vuslat kokan dehlizlere,

Ya uğruna feda olacağın sevgiden mahrum,

Ya da hiç uğruna heba ettiğin bedene sahipsin…

Yasak duyguların gölgesinde özgürlük aranmaz,

Özgürlüğün olmadığı kalplerde sevda barınmaz,

Kim derse ki sonsuza dek gerçek sevgiyle bağlıyım,

Öznesi değil, fiili çeker sevda duygularının içinden…

Sakın ha! kandırma sevgi hazinesi dolmuş kalbini,

Çorak toprak doldurur en değerli aşk emanetini,

Ya uğruna sefasını süreceğin gerçekleri görecek,

Ya da uğrunda cefasını çekeceğin ahları bileceksin…

Gerçekten seviyorsan kalpteki gibi durmaz hislerin,

Gecen cehennem diyarı, gündüzse hüzün terhislerin,

Varlığın çekemezse sevda denen duygunun kahrını,

Gün gelir acıyla verirsin, gönül bahçenin baharını…

Bedeninde binlerce periyle beslediğin ihtiraslarını,

Sevdiğim dediğin kişiyle saracak gücü bulamazsan,

Tutkunun dehşetini artırıp durursan içinde habire,

Ardından dayanılmaz acıları sırtlar götürürsün kabre…

Zaman acımasız olur uğruna roman yazılan yüzlere,

Tedavülde var mı ki gönlüne hitap eden duygular,

Bir yüzü kader, öteki yüzü tel örgülü hapishaneler,

Şarkısı eksilmeyen hüzün kokan sancılı meyhaneler…

Bir kere de olsa emir yok aşk sancısı çeken beynine,

Uğruna can koyulan sevdayı yaşamak senin neyine,

Mevla’nın kılıcı yok ki hercai kaderine vurulsun,

Kula söz hakkı bırakmadın, gayrisi sıratta sorulsun… 

04 Nisan 2005 Ankara', 'Hasret dayanmaz delicesine atıp duran kalplere, Bir kere gelinmediyse vuslat kokan dehlizlere, Ya uğruna feda olacağın sevgiden mahrum, Ya d...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gayrisi-siratta-sorulsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku Yalnızlığı', 'korku-yalnizligi-kemal-cakir-s5tvu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dön gel karanlıktaki yalnızlığım, dön gel.

Görünmeze boya, seni saran korku çemberini

Sırtına güneşi, alnına bulutları al da gel

Dost edin onları korkuya inat.

Serinlesin acıların zıpkın gibi güneş altında

Bundan böyle bulutlarla yarışmalısın

Bir yudum cesaret, sevgi biraz da

Dost edin onları korkuya inat.

Bir daha bırakma korkularını karanlıkta

Tutma ellerini dost bildiğin alkolün

Bakma gözlerine, mavi umut sunmuş olsa da

Dost edin cesaretini tüm korkulara  inat.', 'Dön gel karanlıktaki yalnızlığım, dön gel. Görünmeze boya, seni saran korku çemberini Sırtına güneşi, alnına bulutları al da gel Dost edin o...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/korku-yalnizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Hediye', 'benden-hediye-kemal-cakir-0ik8w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen değilsin hali perişanıma sebep

Bütün çektiklerim  bana benden hediye

Üzme kendini hiç, sorma sebep ne diye

Bütün çektiklerim bana benden hediye.

Tutulup aşkına çöllere düşmüş isem

Bir gün terkedilip sersefil kalmış isem

Kimin hatası bu, kime edeyim sitem 

Bütün çektiklerim bana benden hediye.', 'Sen değilsin hali perişanıma sebep Bütün çektiklerim  bana benden hediye Üzme kendini hiç, sorma sebep ne diye Bütün çektiklerim bana benden...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/benden-hediye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Bestesi', 'olum-bestesi-kemal-cakir-bfd7f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kol kola, omuz omuza, el ele

Bir sürü akrep, 

Yılan ve örümcek.

Birlikte yarış halindeler

Nefret edilesi duygularıyla

Yazmak için bir bestenin güftesini.

Anlaşamıyorlar bir türlü 

Güftenin ismi konusunda.

Tartışmaları boşuna bizce

Çünkü; 

Olan olacak yine ve

Kimimiz kızgın, kimimiz üzgün

Öğreneceğiz ismini sonunda.

İsmi; 

İster 

Trafik kazası,

İster 

Kaza kurşunu,

İsterse 

Kurşunlu/kurşunsuz intihar olsun

Ne farkeder ki? 

Üzülsek de, çoktan alıştık bizler 

Bu tür isimlere.

Önemli olan, yapılması  gereken:

Bu tür güfteler yazmayacak 

İnsanlar yetiştirmek,

Yada güftenin bestelenmesine 

Fırsat vermemek.', 'Kol kola, omuz omuza, el ele Bir sürü akrep,  Yılan ve örümcek. Birlikte yarış halindeler Nefret edilesi duygularıyla Yazmak için bir besten...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/olum-bestesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşa', 'yasa-aynur-baydar-4w1bl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ömür rüyaymış

Göz açıp kapayacak kadar kısaymış

Sonsuzluğun tarlasıymış

Uzatalım şu ömrü

Ö yü, m yi, ü yü, r yi

Geleceği özleme

Gözün de hep olmasın geçmiş de

Geçmişinle güçlenmiş sen

Mutlu yaşadığın şimdin

Olsun daha da iyi geleceğin

Özgüvenli olan, özverili olurmuş

Almak değil vermek mutlulukmuş

Mehtap mutlu etmeye yeter

Bir şarkı söyle ömre bedel

Acıkmış bir miyav sesi

Doyurduğunda kesilince sesi

Tersten sev kediyi

Herkese uymak gerekmez hata da

Dimdik oluversin, bozulursa bozulsun

Tüyleri, düzeni

Aşk sız olmaz, aşka çoğul yakışmaz

Oldu mu özel olmalı

Ruhunda kazınmalı

Yokluğu alimallah yüreğini kanatmalı

Hani şöyle candan kandan olmalı

Sevgiyi, merhameti her cana sunmalı

Kötü ye karşı cengaver durmalı

Pisliğe göz yummamalı

Gerçek dostların, iyinin

Kıymetini bildiren turnusol kağıtları

Demek ki kötüler pisler de olmalı

Üzülme riyaya

Meraklanma artan yaşların ayırır onları

Hakkını vermek her şeyin

Özü varlık sebebimizin

Takvimde kısa olsa da

Ömrünü uzatarak yaşa

Ruhunla yaşa

Çocukça safça, delinin gözü karalığıyla

Bilgenin hoşgörü edasıyla

Leylaca Mecnunca

Yaşadığının farkındalığıyla

Hakkını vererek, kıymetini bilerek

Sinmeyerek, sivrilerek

İnsan gibi insanlara 

Halı misali yerlere serilerek

Dipte de, doruk da ufuk da

Yerinde zamanında

Yaşa be yaşa', 'Ömür rüyaymış Göz açıp kapayacak kadar kısaymış Sonsuzluğun tarlasıymış Uzatalım şu ömrü Ö yü, m yi, ü yü, r yi Geleceği özleme Gözün de hep...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/yasa-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ernesto Che Guevera', 'ernesto-che-guevera-olgun-ekinci-ue4y9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kızıl beren					

Sakalın					

Gözlerindeki yırtıcı kartal bakışların					

Üniforman					

Elindeki Havana puron ile					

Asi, isyankar bakışına					

Asi ce hastayım Che Guevera					

Hastayım usta...					

					

Nisan 2005 - Adana', 'Kızıl beren					 Sakalın					 Gözlerindeki yırtıcı kartal bakışların					 Üniforman					 Elindeki Havana puron ile					 Asi, isyankar bakışı...', ARRAY['Türk Edebiyatı','Şiir','Olgun Ekinci']::text[], 8.5, '{"poet":"Olgun Ekinci","poet_slug":"olgun-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ernesto-che-guevera-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvarlar', 'duvarlar-kemal-cakir-6t8xu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün sadece duvarları seyrettim:

O, insanları ayıran, hapseden

Renk renk 

Kimi alçak kimi yüksek

Genç, orta yaşlı, ihtiyar

Çok şey bilip de konuşamayan

O bildiğimiz duvarları.

Çok hatıra saklıdır her birinde 

Acı - tatlı,  iyi - kötü.

Her şeye tanık olmuşlar, 

Olmasına da; 

Oturmamıştır hiç biri 

Bir kere bile tanık koltuğuna,

Duyarsız olmalarından ötürü.

Bize benzerler çoğu yönleriyle:

Gurur abidesi,

Utanç  vesilesi,

Özgürlük meş''alesi,

Suskunluk ve yalnızlık timsali,

Zamana direnen, teslimiyetci,

Acımasız, korumacı, 	

Sır tutkunu, tüketici...

Pek farkı yoktur çoğumuzun 

Onlardan,

Sadece canlı olma  ötesi.

İşte onları seyrettim

O bildiğimiz duvarları.

Çok hoşnut olduğum söylenemez

Çünkü, 

Gurur duyduklarım daha azdı

Utanç duyduklarımdan.			

	

Bu nedenle: 

''Yeni sezon, yeni  inşaat, 

Bakım ve onarım gerekli artık'' 

Diye düşünüyorum. 

Silkinip şöyle bir, 

Gelmeliyiz kendimize 

Ve, ve! 

Kurtarmalıyız kendimizi

Harabeye, enkaza dönüşmekten.', 'Bugün sadece duvarları seyrettim: O, insanları ayıran, hapseden Renk renk  Kimi alçak kimi yüksek Genç, orta yaşlı, ihtiyar Çok şey bilip de...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/duvarlar-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresiz', 'caresiz-atahan-cakir-abantli-9qna3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Başını kaldırıp gözlerime baktı 

Tam bir belirsizlikteydi düşünceleri.

Görevini yapamamış olmanın  acısıyle 

Küçülüp büyüyordu gözbebekleri. 

	

Neler söylemek istediğini düşündü

Birara, gözlerini oğuşturarak.

Ama yine sustu, düşünceleri üşüdü

''Konuşamam'' dedi sıkılarak.

Büyük yankılar uyandıracaktı

Yıllarca sakladığı sır dolu sözleri.

Ama korkuyordu, can bu, çok tatlıydı...

Bu güvensiz ortam yok edecek bizleri.', 'Başını kaldırıp gözlerime baktı  Tam bir belirsizlikteydi düşünceleri. Görevini yapamamış olmanın  acısıyle  Küçülüp büyüyordu gözbebekleri....', ARRAY['Türk Edebiyatı','Şiir','Atahan Çakır Abantlı']::text[], 8.5, '{"poet":"Atahan Çakır Abantlı","poet_slug":"atahan-cakir-abantli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/caresiz-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Karşılıksız Sevdim', 'ben-seni-karsiliksiz-sevdim-ozgur-demir-nye05', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yıldız kaydı gönlüme

Uçları kalbimi yaralayan

Bir şiir yazdım sevgime

Kalemi kalbimin tuttuğu

Mürekkep yerine

Yüreğimden kanın aktığı

Ben seni sevdim bir kere

Melek gözüken yüzünü göster diye

Bir çok aşklar yaşadım

Sevdiğim,sevildiğim aşklar

Ama ben seni karşılıksız yaşadım

Buna da aşk dediler platonik diye adlandırdıkları

Ben kendim gibisini sevmek istedim

Öylesine muhtaçtım ki her şeyiyle ben olan birini sevmeye

Ben seni karşılıksız düşüncelerle sevdim

Neyi düşündüğümü bilmeden

Kalbimin ne yaptığını hissetmeden

Ben sende beni sevmeyi sevdim

Sende başkalarını seviyordun

Aynı benim gibi,karşılıksız sevdiğin

Ben seni şiirlerde sevdim

Yazarken kalbime güvendiğim

Mürekkebim kanımın

Garantisinde ki şiirlerde...', 'Bir yıldız kaydı gönlüme Uçları kalbimi yaralayan Bir şiir yazdım sevgime Kalemi kalbimin tuttuğu Mürekkep yerine Yüreğimden kanın aktığı Be...', ARRAY['Türk Edebiyatı','Şiir','Özgür Demir']::text[], 8.5, '{"poet":"Özgür Demir","poet_slug":"ozgur-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-seni-karsiliksiz-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma', 'unutma-atahan-cakir-abantli-7x0nl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgilim, bir gün ayrılacak yollarımız

Sen bir yerde, ben bir yerde

Habersiz, selamsız, kimsesiz.

Kavuşmak özlemiyle açık kollarımız.

Şayet bir gün ellerin bir başka eli tutar,

Gözlerin bir başka göze takılırsa eğer 

Unutma! ellerine hasret ellerim,

Gözlerinde düğümlenen gözlerim var.

Bir ayrılık şarkısı duyar da 

Gözlerin dolar, kalbin çarparsa eğer

Hatırla! hala bizim de bir  şarkımız,

Aşkla kıpır kıpır çarpan kalbimiz var.

Bir bahçe görürsen, gülsüz bülbülsüz

Tasa etme, üzülme, ağlama sakın.

Unutma! hala seni seven bir bülbül,

Bahçesinde açıp duran bir gül var.

			Temmuz 1985', 'Sevgilim, bir gün ayrılacak yollarımız Sen bir yerde, ben bir yerde Habersiz, selamsız, kimsesiz. Kavuşmak özlemiyle açık kollarımız. Şayet ...', ARRAY['Türk Edebiyatı','Şiir','Atahan Çakır Abantlı']::text[], 8.5, '{"poet":"Atahan Çakır Abantlı","poet_slug":"atahan-cakir-abantli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/unutma-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayak Sesleri', 'ayak-sesleri-atahan-cakir-abantli-da2rz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küf kokan koridorlarda biraz gezerseniz 

Görürsünüz çürümüş yaşam izlerini.

Kulak verip dinlerseniz ağlayan muslukları 

Duyarsınız terkedilmişliğin ayak seslerini.', 'Küf kokan koridorlarda biraz gezerseniz  Görürsünüz çürümüş yaşam izlerini. Kulak verip dinlerseniz ağlayan muslukları  Duyarsınız terkedilm...', ARRAY['Türk Edebiyatı','Şiir','Atahan Çakır Abantlı']::text[], 8.5, '{"poet":"Atahan Çakır Abantlı","poet_slug":"atahan-cakir-abantli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ayak-sesleri-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'kapandı Aşk Sayfan', 'kapandi-ask-sayfan-atahan-cakir-abantli-gk5yn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çoktan tükettim bendeki seni inan 

Artık ben olmam senin uğruna yanan

Acı bir gülüş senden hatıra kalan

Kapandı  bende aşk sayfan anlasana.

Ne  zaman bana gerçek değeri verdin

Hep kötü sözler söyler eleştirirdin

Şayet sevseydin hiç böyle mi ederdin

Kapandı bende aşk sayfan anlasana.

Ne zaman benim için gözyaşı döktün

Sen gününü gün ettin ben ise çöktüm	

Hatırla, beni sonkez ne zaman öptün

Kapandı bende aşk sayfan anlasana.', 'Çoktan tükettim bendeki seni inan  Artık ben olmam senin uğruna yanan Acı bir gülüş senden hatıra kalan Kapandı  bende aşk sayfan anlasana. ...', ARRAY['Türk Edebiyatı','Şiir','Atahan Çakır Abantlı']::text[], 8.5, '{"poet":"Atahan Çakır Abantlı","poet_slug":"atahan-cakir-abantli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kapandi-ask-sayfan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Desen Gelirim', 'gel-desen-gelirim-sahin-erturk-ipqes', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel desen,gelirim

Yasakları delerim

Zincirleri kırarım

Engelleri aşarım

Aşkı öğretmek için

Sevgimle,hasretimle

Sıcaklığımla

Aşka susamışlığını

Gidermek için

Ellerinden tutmak için

Dizlerinde yatmak için

Şiirlerini okumak için

Gel desen,gelirim

Senin için gelirim

Kendim için gelirim

Aşk için gelirim

Çağırdın da gelmedim mi? 

Gel desen inan

Gelirim güzel gelirim

(05.04.2005)', 'Gel desen,gelirim Yasakları delerim Zincirleri kırarım Engelleri aşarım Aşkı öğretmek için Sevgimle,hasretimle Sıcaklığımla Aşka susamışlığı...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-desen-gelirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Olmadan Anlaşılmıyor Aşk', 'ayrilik-olmadan-anlasilmiyor-ask-atilla-guler-mrx28', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ardına düşen her duygu

sağanak bir esrikliğe davet

nisan yine oyun oynuyor

baharın ilk demlerinde

leylakların kokusunda solunan

her yüreğe açık kapılar

akasya beyazlığında sevdanın

bakir izleri

şebboylar açıyor çocuksuz bahçemin

üşüyen çimenlerinde

ılık meltemlerine açıldı yelken

kasırgadan çıkmış denizimin

limanda tek yanmamış gemi seninki

mavi bir merhaba bekliyor güvertesinde

ısrarla dilsiz dil

yanan kızıl gülün küllerinden doğuyor

orkide

rembetikolarda söylendi esaretim

ağıtlar kulağımda çınlıyor

aykırı bir düş kurdum sana

yılan bakışlı fahişeler saldırdı yalnızlığıma

ruhumda patlayan her çığlık

ılık bir akşamüstü karanlığında

bir yıldıza takıldı

alaca güneşin renklerinde saklandı

ateşe düşüyor gözyaşları

kırık bir vazoda

kırmızı bir karanfil sözlerin

operadaki hayalet artık yüreğe düşmüş

serseri bir aşkın şaşkın serserisi serkeş kollarda

meskenimde yanan ocakta aş kalmadı

azına kandığım aşk niye hiç çoğalmadı

dudaklarımda inleyen ismini

ayrılık sessizce çaldı

bıraktığın yerde değil aşk

bir minik kır çiçeği tutunmuş toprağa

fırtınalar sıyırır yapraklarımı

ayrılık olmadan anlaşılmıyor aşk', 'ardına düşen her duygu sağanak bir esrikliğe davet nisan yine oyun oynuyor baharın ilk demlerinde leylakların kokusunda solunan her yüreğe a...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ayrilik-olmadan-anlasilmiyor-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Yakındır', 'son-yakindir-halil-aslan-1iaqe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu bir isyandır bitmeye yüz tutmuş sevdalara, ve bir sitemdir sevip de vazgeçmelere. Ne acıdır ki kaçarak korkular yenilmiyor…

Dil söylerken kalp dinlemişse,

Türlü bahaneleri mazeret etmişse,

Sevda kıyaslanmaya başlanmışsa,

Uğruna fedakarlık artık zor geliyorsa,

Artık son yakındır biliyorum…

Bakma gözümden yaş gelmediğine,

Yüreğim kan revan içinde,

O kelimeyi söylediğin andan beri,

Kalbim atmakla atmamak arasında,

Ama son yakındır artık biliyorum…

Sevda dedikleri bu olsa gerek,

Benim bildiğim bu olmasa da,

Sevginin ömrü, yaşamdan daha kısa,

Ölümüne sevsem de yetmiyor nafile,

Artık korksam da son yakındır biliyorum…', 'Bu bir isyandır bitmeye yüz tutmuş sevdalara, ve bir sitemdir sevip de vazgeçmelere. Ne acıdır ki kaçarak korkular yenilmiyor… Dil söylerken...', ARRAY['Türk Edebiyatı','Şiir','Halil Aslan']::text[], 8.5, '{"poet":"Halil Aslan","poet_slug":"halil-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-yakindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Yalanım', 'ben-bir-yalanim-halil-aslan-0hlr9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatında hep varım ama dışında,

Vazgeçmiyorsun belki ama emin de değilsin,

Nihayetinde ben bir yalanım sende,

Tıpkı hayattaki yerim gibi…

Bazen yüreğindeki sızıyım,

Bazen gözünden akan yaş,

Ben bir yalanım sende,

Tıpkı sahte mutluluklar gibi…

Bazen sığındığın bir liman,

Bazen sevgiye susuzluğunum,

Ama ben, sende bir yalanım,

Tıpkı ölümüne sevdalar gibi..

An olur doğan güneşim aydınlık,

An olur geceyim zifiri karanlık,

Ama ben bir yalanım sende,

Tıpkı dilden söylenen nameler gibi…

Bir gün baktığın her yerde,

Bir gün kavuşulmaz meçhuldeyim,

Evet ben bir yalanım sende,

Tıpkı yaşayamadığım hayat gibi…

Hayatında hep varım ama dışında,

Vazgeçmiyorsun belki ama emin de değilsin,

Nihayetinde ben bir yalanım sende,

Tıpkı hayattaki yerim gibi…

Özlemekten öte, sevmekten azım,

Yalnızlıkta nimet, kalabalıkta hiçim,

Haklısın ben bir yalanım sende,

Tıpkı sararmış yapraklar gibi…

Anladım ki ben bir yalanım sende,

Tıpkı işim yaşım gibi,

Ve hep yalan kalacağım beklide,

Tıpkı adım gibi…', 'Hayatında hep varım ama dışında, Vazgeçmiyorsun belki ama emin de değilsin, Nihayetinde ben bir yalanım sende, Tıpkı hayattaki yerim gibi… B...', ARRAY['Türk Edebiyatı','Şiir','Halil Aslan']::text[], 8.5, '{"poet":"Halil Aslan","poet_slug":"halil-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ben-bir-yalanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısmet', 'kismet-halil-aslan-jtm5t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yarısı,

Yine bir yol ayrımı,

Yaşlar dökülmekle dökülmemek arası,

Gözler kan çanağı,

Karanlıktan utanırcasına ürkek,

Yürek dağlanmış 

Tamiri zor olsa gerek,

Baştan epeyce uzaktayım,

Sona hayli yakın.

Ardın sıra tükenen kadeh, 

Birbirine eklenen sigara,

Kulakta çınlayan namelerle bir kez daha,

İnadına yeniden, 

Yeniden kanıyor yürekteki yara.

Sevda yorgunu, 

Ama bir o kadarda aç bu yürek,

Artık tamam demeli, 

Kim bilir beklide vazgeçmek gerek,

Gidince…

Bitince….

Kaybedince….

Bilir ya insan kıymet,

Anlamsız bir devamdansa,

Manalı bir sondur belki kısmet…', 'Gecenin bir yarısı, Yine bir yol ayrımı, Yaşlar dökülmekle dökülmemek arası, Gözler kan çanağı, Karanlıktan utanırcasına ürkek, Yürek dağlan...', ARRAY['Türk Edebiyatı','Şiir','Halil Aslan']::text[], 8.5, '{"poet":"Halil Aslan","poet_slug":"halil-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kismet-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dal koymadın', 'dal-koymadin-tuncay-akdeniz-i73xs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Diyar,diyar çok dolaştım

Gidilecek yol koymadın

Arı gibi çok çalıştım

Kovanım da bal koymadın

Tabipler derdimi bilmez

Özüm ağlar yüzüm gülmez

Yürek susmuş dil söylemez

Konuşacak dil koymadın

Yedin ömrümü zamanla

Her günüm geçiyor gamla

Yaş dökerim damla damla

Gözlerimde sel koymadın

El açtım Yüce Mevlaya

Derdim kavuşmak Leyla ya

Ayı günü saya saya

Yaşayacak yıl koymadın

Sevgim değildir manevi

Aradığım gerçek sevi

Viran olmuş gönül evi

Ocağında kül koymadın

Tuncay kadersiz kul oldum

Ne verdiysen geri aldın

Tuttuğum dalı budadın

Koklanacak gül mü koydun', 'Diyar,diyar çok dolaştım Gidilecek yol koymadın Arı gibi çok çalıştım Kovanım da bal koymadın Tabipler derdimi bilmez Özüm ağlar yüzüm gülme...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dalmi-koydun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal', 'hoscakal-osman-i-nci-kzk9y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerine belki, bakmayacağım,

Dizlerine zevkle, yatmayacağım,

Saçlarına taçlar, takmayacağım,

Ayrıldı yollarımız, sen hoşça kal..

Yaşandı da bitti, en güzel günler,

Mazilerde kalacak, o tatlı sözler,

Bir ömür boyu, ağlasa da o gözler,

Ayrıldı yollarımız, sen hoşça kal…

Ne pişmanlık duy, ne de an beni,

Okşayamam şimdi, o masum teni,

Ben unuttum artık, bendeki seni,

Ayrıldı yollarımız, sen hoşça kal…

Neden ayrıldığımızı, sormasın eller,

Ayrılığın şarkılarını, söylesin diller,

Hasretini getirsin hep, esen yeller,

Ayrıldı yollarımız, sen hoşça kal…', 'Gözlerine belki, bakmayacağım, Dizlerine zevkle, yatmayacağım, Saçlarına taçlar, takmayacağım, Ayrıldı yollarımız, sen hoşça kal.. Yaşandı d...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hoscakal-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Umu..', 'umu-ertugrul-sakar-fr8l8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Daha tatmadın umutsuzluğun çaresizliğini 

Hissettiğin gerçekleşmeyen hayaller sadece 

Acıyı duymak kezzap gibi 

Boşluklarda gerilmiş azap gibi 

Kanlanmış avuçlar gibi 

Bilmiyorsun ki umutsuzluğu 

Umut senin tat tuzluğun 

Biraz uykusuzluğun 

Belki de huysuzluğun 

Daha tatmadan umutsuzluğu 

Bilemezsin umudu 

Ağaçta tomur gibi 

Bir vadide sur gibi 

Karanlıkta nur gibi

Tekrar düşün iyice 

Bir yorum bul yenice 

Umutsuzluk sanarak

Hüzünlere kanarak

Yitirme umudunu

Umu 

Kumu 

Umut 

Dökülüyor ellerinden 

Tutmalısın 

Soğumadan 

Çiçekler açacak bir sabah

Gün doğmadan daha...', 'Daha tatmadın umutsuzluğun çaresizliğini  Hissettiğin gerçekleşmeyen hayaller sadece  Acıyı duymak kezzap gibi  Boşluklarda gerilmiş azap gi...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/umu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamadı', 'anlamadi-murat-demir-atvt1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O nu başımda baş saydım

O nu bağrımda taş saydım

O nu gözümde yaş saydım

Yine beni anlamadı 

Anlamadı anlamadı

Beni yaktı o yanmadı

Gurbet elde sürünerek

Ölür diye inanmadı

O nu aşkıma bal saydım

O nu kanımda al saydım

O nu tutmaya dal saydım

Yine beni anlamadı

Anlamadı anlamadı

El yar oldu o olmadı

Sağır sultan bile duydu

Figanımı o duymadı

O nu canımda can saydım

O nu kalbimde kan saydım

O nu her şey, her an saydım

Yine beni anlamadı

Anlamadı anlamadı

Gelip beni tamlamadı

Bende yaşlar sele dönmüş 

Ondan damla damlamadı!', 'O nu başımda baş saydım O nu bağrımda taş saydım O nu gözümde yaş saydım Yine beni anlamadı  Anlamadı anlamadı Beni yaktı o yanmadı Gurbet e...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anlamadi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'derman O değildi, demiştim sevgili', 'derman-o-degildi-demistim-sevgili-zafer-yazici-ndjim', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen, sarıl ona sımsıkı,

bir aşık gibi, yan! 

o sana sarılmasa da.

zaten hep ateştir bu aşkta,

yakmaz senin tenini bu kış gecelerinde,

sen sarılmadıkça O’na! .. 

___ne kadar dönersen dön, ister pervane ol! 

____yakar kavurur seni yüreğindeki aşk

_____sevgiliye kavuşmadıkça! ...

ayrılıkları da yaman olur; 

o istemez, sen istersin

sen istemezsin, o ister! ..

bir çok kişi ayırmak için uğraşırken

siz tarifsiz acılar çekerken feryat figan

dışarıda, gülenler olacaktır her zaman! ..

__bağlar elini kolunu her yaşadığın tat! 

___kim bu aşk uğruna olmaz ki feda

____kim yaşamak istemez ki aşkı, doya doya? ...

…………………………………

şimdi, yukarıda okuduğun bu dizeler

merhem oluyor mu yaralarına sevgili? 

Oysa, ben demiştim sana, çaresi o değildi! 

“gözlerinden akan yaş bu aşka, derman olmaz sevgili”

demiştim dün gibi hatırlıyorum! …

sarılmayacaktın “aşk ile” ona! ...

“faydalı gördüğümüz aşkın acısı yaman olur! ”

demiştim sana!', 'sen, sarıl ona sımsıkı, bir aşık gibi, yan!  o sana sarılmasa da. zaten hep ateştir bu aşkta, yakmaz senin tenini bu kış gecelerinde, sen sa...', ARRAY['Türk Edebiyatı','Şiir','Zafer Yazıcı']::text[], 8.5, '{"poet":"Zafer Yazıcı","poet_slug":"zafer-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/derman-o-degildi-demistim-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet mektubu', 'gurbet-mektubu-tuncay-akdeniz-52uzu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Köyümden bir mektup gelmiş adıma

Gurbet mektubunda pul kokusu var

Dedim sevdiğimin düşmüş yadına

Gurbet mektubunda el kokusu var

Gariplere mekan olmaz burası

Çıkmaz akıllardan köyü sılası

Yar kokuyor mektubumun arası

Gurbet mektubunda gül kokusu var

Bu gurbetin yok mu sonu durağı

Her gün içilir mi zehir bardağı

Mektubuna koymuş sevgi yaprağı

Gurbet mektubunda dal kokusu var

Tuncayım gurbetten almış yarayı

Zalim yardan uzak koymuş arayı

Hasretine yaktım ana babayı

Gurbet mektubunda kül kokusu var', 'Köyümden bir mektup gelmiş adıma Gurbet mektubunda pul kokusu var Dedim sevdiğimin düşmüş yadına Gurbet mektubunda el kokusu var Gariplere m...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gurbet-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Dökük İnsan', 'kirik-dokuk-i-nsan-sezer-odabasioglu-a3414', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-insana özel-

öyle sağlıksız değildi

içi gülerdi gözünün

içi depremdi, duyardım

hastı yüreği, bilirdim

onu en son, son kuşları 

sevgiyle öperken gördüm.

hep bir şeylere üzülür

üzgün şiirler yazardı

konuşmazdı pek, suskundu

arada bir saz çalardı

onu en son, gökyüzünü 

sevgiyle öperken gördüm.

hasret yüklüydü sevdası

zorlu severdi yaşamı

fırtınalıydı, korkardım

hiç istemezdi ölümü

onu en son, kırık dökük

sessizce giderken gördüm.

''Senden Yana Büyür Çığlığım'' başlıklı şiir dosyasından.', '-insana özel- öyle sağlıksız değildi içi gülerdi gözünün içi depremdi, duyardım hastı yüreği, bilirdim onu en son, son kuşları  sevgiyle öpe...', ARRAY['Türk Edebiyatı','Şiir','Sezer Odabaşıoğlu']::text[], 8.5, '{"poet":"Sezer Odabaşıoğlu","poet_slug":"sezer-odabasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kirik-dokuk-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceden Sabaha', 'geceden-sabaha-duygu-dinc-nql6c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“Sev! ” demiş güneş; 

Sevmiş toprak suyu…

Yummuş gözlerini gece

İyice kararmış ortalık

Göz gözü görmez olmuş

Gez gez bitmez olmuş kuytular

Karanlığa saklanmış ayrılık; 

Güneş onu görseymiş

Belki sevdaya sevdirirmiş

Ama görmemiş

Sevda da sevmemiş ayrılığı

Dünya ne çok dönüyormuş

Ve ne çok duruyormuş öylece…

İki satır yazası varmış şairin

İki kadeh de içesi…

İçememiş ama yazmış

İçmiş kadar da olmuş ayrıca…

Kopmuş çıkmış gündelik hayatından

Bizzat kendi sahte kahkahalarından

Dışı rengarenk

İçi simsiyah kutusundan

Ölüm kokan hayat bağlarından…

Sıyırmış atmış kendini çıkmazlarından

Yine yalnızmış ama

Bu sefer koymuyormuş yalnızlık

Minnet duymuş kalemine

Bir de zincirin ilk halkası olan geceye…

Karanlık mı daha iyiymiş

Yoksa aydınlık mı daha kötü

Karar verememiş

Çıkamamış içinden…

Çıkmazlarına geri döndüğünü hissetmiş

Sonra susmuş…

Kalemine bakmış:

Tek dostuna! 

İyi ki varsın! demiş

Şerefine! 

Hayat senin şerefine

Dünya senin şerefine

Her şey senin şerefine

Çünkü katlanabilirlikleri senin sayende! 

Bağırma demiş deniz,

Geceyi uyandıracaksın

Büyü bozulacak

Bitmesin demiş hayallerin 12de

Balkabağına dönüşmesin kalemin

Haklıymış

Şair susmuş

Sonra bir daha susmuş

Sırf bu hazzı daha fazla yaşayabilmek için

Sözün kendilerine gelmesini sabırsızlıkla bekleyen

Dolayısıyla karşısındakileri dinlemeyenlere inat

Bir kez daha susmuş

Sessizliği dinlemiş

Kulak vermiş

Ne çok şey anlatıyormuş meğer! 

Daha önce fark edemediğine yanmış

Üzülmüş

Kalemine bakmış tekrar

Teselli bulmuş

Göz kırpmış deniz, kaçak bir martıya

“Kudret mi,işte orda! ” demiş şair

Denizi göstermiş

Sessiz ol demiş martı

Biliyorum zaten

Ama sus ki gece uyanmasın…

Selam vermiş şair martıya

Haklısın demiş,fısıldayarak

Martı uçmuş gitmiş

El sallamış şair

Yine gel demiş içinden

Bir burukluk sarmış içini yeniden

Hüznün efendisinden…

Ay düşmüş denize

Geceden ironik bir hediye

Kendi çemberine dönmüş şair

Emniyet kemerini takmış

Çünkü hızlanacakmış

Dur durak bilmeyecekmiş

Çemberi darmış

Sınırlıymış gidilecek yerler

Ama yine de hızlanacakmış

Tüm üzüntülere inat

Tüm karşılıksız sevgilerine inat

Tüm gülünç ümitlerine inat…

Ağlamış

Ondan kopup gidenlere ağlamış

Hep kaybettiğine ağlamış

Bazen kaybetmek de bir çeşit kazanmak olsa da…

Ters giden hayatına bakmış

Sonra da onu ters yola sokana…

Kendisine…

Madem onu oraya getiren oymuş

O zaman çözüm kolaymış

Değişim…

Korkuya kapılmış gece

-Nedense-

Korkma demiş şair

Korkma ki ben de korkmayayım

Atılayım hayata yeniden

Sarılayım dört elle

Demin uçup giden martı kadar özgür

Şu deniz kadar kudretli olayım

Gece utanmış

Sağol demiş şair geceye

Her şey için…

Uğurlamış sessizce

Güneş doğmuş

Gece gitmiş

Yine gel demiş şair içinden

Daha seninle yapacaklarımız bitmedi

Yeni bir güne başlamanın sevinci

Bir geceyi daha geride bırakmanın hüznü…

Karışıvermiş…

“Dur! ” demiş şair

Hüzün durmuş

Şair inmiş

Bu onun yeni hayatının ilk günüymüş…

(04.04.05)', '“Sev! ” demiş güneş;  Sevmiş toprak suyu… Yummuş gözlerini gece İyice kararmış ortalık Göz gözü görmez olmuş Gez gez bitmez olmuş kuytular K...', ARRAY['Türk Edebiyatı','Şiir','Duygu Dinç']::text[], 8.5, '{"poet":"Duygu Dinç","poet_slug":"duygu-dinc","theme":"Türk Şiiri","is_hero":false,"total_lines":119,"source_url":"https://www.antoloji.com/geceden-sabaha-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Dünya', 'baska-dunya-duygu-dinc-5k9pp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uçtun mu göklere kadar uçup

Düştün mü dibe kadar düşeceksin

Başka türlü tadı çıkmaz bu boktan hayatın

Ucundan incecik iple bağlı gibi zaten

Koparsan koparamazsın

Sarılsan sarılamazsın

Hep bir korku

Hep bir kaçış

Sebepsiz yere

Belki lüzumluluk dolu

Kapat gözlerini

Sanki dünya yokmuş gibi

O uçsuz bucaksız karanlıkta

Tek ışık senmişsin gibi

Sus

Konuşma ki manasını yitirmesin karanlık

Yada aydınlık

Herneyse işte

Şimdi oyun zamanı

Hadi Tanrıcılık oynayalım

Doldur karanlığı dilediğince

Nerde ne olmasını istiyorsan koy

Yarat kendi dünyanı

Bırak etrafın hep sevdiklerinle dolsun

Seni üzecek hiçbirşey olmasın dünyanda

Ama ses olmasın

Herkes sussun,kimse konuşmasın

Konuştukça anlamını yitirmesin sözcükler

Hepsi hep anlam dolu kalsın

Açma gözlerini sakın! 

Orası senin dünyan

Terk etme sana ait tek dünyanı

Üzülme

İstersen hep orda kalır dünyan

Göz açıp kapayıncaya kadar

Yada göz kapatıp hiç açmayıncaya kadar

Kendini kötü hissettiğinde

Kaçıverirsin mabedine

Islak yanakların kuruyuverir

Nede olsa üzüntü yok senin dünyanda

Özlemini duyduğun her şeye sahip olursun

Bir göz kapatmayla…

Ama ses çıkmasın

Kimseden…

Sessizlik olsun hep

Anlam dolu olsun kelimeler senin dünyanda

Kirletilmesin, yıpratılmasın

Hor kullanılmasın “Seni seviyorum”lar

“Özür dilerim”ler,”seni özledim”ler…

Tertemiz kalsın

Dar sokakları olmasın dünyanın

Kuytu köşeleri olmasın

Saat,gece gündüz kavramı olmasın

Hep güneş olsun

Sıcacık olsun dünyan

Hem güneşle hem sevgiyle…

Gözyaşı olmasın

Ayrılık olmasın

Karşılıksız sevgi kapısından bile bakamasın! 

Kocaman olsun dünyan

Bu dünyadan da büyük

Ama dertler kederler sığmasın

İnşa bittiyse 

Artık hazırsın

Yaşa kendi dünyanda dilediğince

Unutma

İki kural var

Birincisi gözlerin kapalı

İkincisi sessizlik…

Konuşma

Konuşma ki

Anlamını yitirmesin sözcükler…

(05.04.05)', 'Uçtun mu göklere kadar uçup Düştün mü dibe kadar düşeceksin Başka türlü tadı çıkmaz bu boktan hayatın Ucundan incecik iple bağlı gibi zaten ...', ARRAY['Türk Edebiyatı','Şiir','Duygu Dinç']::text[], 8.5, '{"poet":"Duygu Dinç","poet_slug":"duygu-dinc","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/baska-dunya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'La Période De Partir', 'la-p-riode-de-partir-i-lter-fatih-korkut-62vvh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Je ne suis pas prêt pour ceci

Pour aller et puis vous laisser seul

Peux être je dois

Peut se produire, ceci est la bonne option

Je ne veux pas vous laisser

Mais je dois 

J''essaye de cesser de vous aimer

Mais, c''est impossible...

J''ai besoin d''une certaine heure à la trouvaille moi-même

Pour penser, penser seulement

et étudiez notre rapport

Si il y a n''importe quelle manière de sauver notre amour 

Queest-ce que je peux faire 

Est-ce que je peux aller sur mon propre chemin 

Est-ce que je peux dessiner ma propre manière

Je ne pense pas ainsi...

Je ne veux pas vous laisser 

Mais je dois

j''essaye d''oublier votre amour

Je ne suis pas parvenu à faire cela...', 'Je ne suis pas prêt pour ceci Pour aller et puis vous laisser seul Peux être je dois Peut se produire, ceci est la bonne option Je ne veux p...', ARRAY['Türk Edebiyatı','Şiir','İlter Fatih Korkut']::text[], 8.5, '{"poet":"İlter Fatih Korkut","poet_slug":"i-lter-fatih-korkut","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/la-periode-de-partir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevapla', 'cevapla-duygu-dinc-9f2si', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neydi sanki hayatın benden beklediği

Neydi üstüme üstüme gelen

Neydi beni bunca soruyla 

Ve yanıtsız bırakan

Neydi beni karanlıkta bırakan acımasızca

Bilmiyor muydu benim umudum yoktu ki

Bilmiyor muydu cam topraktan oluşmuş

Bilmiyor muydu mutluluk bensiz

Ben mutluluksuz

Çok mu umrundaydı mutluluğun, bensiz olmak

Yada ben çok mu önemsiyordum onsuz olmayı

Yada neden kelebeklerin ömrü 3 gündü…

Her gün yeni bir başlangıç mıydı

Yoksa sonu muydu birşeylerin

Ben miydim çıkmazları yaratan

Yada çıkmazlardan sonra mı yaratılmıştım

Üzgün müydü kelebek 3 gün benim ömrüm diye

Yada ben mi mutsuzdum 

3 günden fazla yasıyorum diye

Çok sevinmiş miydi Fatih

İstanbul''u fethedince	

Yada sevinen parkta oynayan çocuk muydu

Yada sevinen ben miydim

Onca olan bitene rağmen…

Korkmamış mıydı pamuk prenses

Şap diye öpünce prens

Yada patlatmamış mıydı tokadı

Ben senin bildiğin kızlardan değilim diye

Peki ben neden bu kargaşanın içindeydim

Dışında yer kalmamış mıydı

Kapılmış mıydı her yer

Sığmamış mıydım yoksa

Yada askerleri mi gelmişti bilmem kaçıncı Murat''ın

Alıcaz ya illaki Viyana''yı

Düşmüş müydü son yaprağı koca yazın

Yada özlememiş miydi mecnun Leyla''yı

Niye sarılmamıştı ki…

Ya herkes neden dağılmıştı

Işıkları kim söndürmüştü yada

Bu kadar acınası mıyım terk edilecek kadar

Yada terk eden terk edilen kadar terk edilmiş midir

Çizgi romanlar çizik çizik midir

Yada kahramanların yüzleri…

7 tane cüce nasıl bir araya gelmiş

Neden 8 değil de 7

Neden içlerinde büyük yok

Büyükleri kabul etmiyorlarsa

Pamuk prenses neci? 

Adı bende mi saklı sende mi

Madem saklamışım yerini niye söylüyorum

Ben de 100 yıl uyur muydum parmağıma iğne batsaydı

Yada güzel olur muydum 1oo yılın sonunda

Ne güzel de sevinmiştim o kıvılcımda

Artık sorunsuz bir hayatım var diye

Artık ağlamıycam diye

Sihirli değnek dokundu diye

Ama unutmuşum ben prenses değilim

12ye kadar bile sansım yok…

Nereye kadardı

Uyanana kadar mı

Yoksa uyuyana kadar mı…

Çok mu üşümüştü kibritçi kız

Küçücük kibritle ısınılır mıydı

Aptal mıydı o kız

Yoksa aptal olan ben miydim

Tüm bu zırvalıkları yazdığımdan dolayı

Yeni bir çizgi çekmenin zamanı gelmişti

Hayatla mutsuzluğun arasına

-------- 

Umarım yeterli olur

Nede olsa benim derdim kendimle

Neron muyum Roma''yı yakayım

Ben kendi kendimi yakmışım zaten

Bırakayım masallar hep öyle kalsın

Bırakayım kim nereyi alırsa alsın

Devam etsin yasam kaldığı yerden

Tarih de olduğu yerde kalsın

Ben kendime bakayım

Bir çizgi daha çekeyim ki sağlam olsun

-------- 

Tamamdır…….

(25.10.04)', 'Neydi sanki hayatın benden beklediği Neydi üstüme üstüme gelen Neydi beni bunca soruyla  Ve yanıtsız bırakan Neydi beni karanlıkta bırakan a...', ARRAY['Türk Edebiyatı','Şiir','Duygu Dinç']::text[], 8.5, '{"poet":"Duygu Dinç","poet_slug":"duygu-dinc","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/cevapla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybeden sen oldun aslinda...', 'kaybeden-sen-oldun-aslinda-mehmet-yilmaz-hi9b3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gittin ve ben arkandan bombos gözlerle bakmayi yegledim,

Simdi yagmurlar istlatiyor gezdigimiz o sokaklari,

Apansiz gidisin  ve benim yürek vurgunuyla dibe cöküsüm, beni bu yalnizliga mahkum etti.

Gittin kelimeler bogazima dizildi kal diyemedim.

Biraktin limani olmayan gemiler gibi denizin ortasinda yapayalniz tek basina,

Geri dönecegin günü bekleme umuduyla rüzgara actim yelkenimi,

Dönmeyecegini biliyorum, her sey bosa aslinda,

Biraktin beni kiyiya sensiz ulasmam mümkün olmayacak bir daha.

Kactin ve bu gece sensizligin izdirabiyla son sabahi bekliyorum,

Aglamakli gözlerimle, titreyen ellerimle sana son satirlari yaziyorum,

Bu son cümlem sana ve kendimi bir nokta kadar anlamsiz hissediyorum,

Kactin simdi baktigim her yerde görebilmek icin seni gözlerimde tasiyorum.

Terkettin ve aksamin son bulan ufuklarinda günes damla damla eriyor avuclarimda,

Bu gecede sensizlik karisacak,

Artik adi olmayacak ne gecemin ne de gündüzümün,

Terkettin ve bu sensiz gecen son seferi ömrümün.', 'Gittin ve ben arkandan bombos gözlerle bakmayi yegledim, Simdi yagmurlar istlatiyor gezdigimiz o sokaklari, Apansiz gidisin  ve benim yürek ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kaybeden-sen-oldun-aslinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Söz', 'son-soz-nesat-turan-ou26l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'acılar... sevdalı yürekleri buruşturan acılar 

kalp sancım bitmeyen şarkı 

hüzün kokan şarap 

Rize şehrin ortasında 

bir masal kahramanı 

bir şövalye 

acılar...sevdalı yürekleri buruşturan acılar 

içimde zakkum zehri 

uyuşuk fırtınalı gecelerin sabahında 

karabasanlı ilkbahar 

dallarım süslü püslü 

bir kurban 

acılar...sevdalı yürekleri buruşturan acılar 

ölüm döşeğinde yaşlı bir adam 

inleyen yüzüyle 

son nasihati 

merhametli ve cömert olun 

ilk mektup 

acılar... sevdalı yürekleri buruşturan acılar 

düşüncemin yansısı olan sevgi 

gönül bağım 

ver kurtar artık bu azaptan 

ellerini, kumru bükmelerini 

barışalım 

45’lik bir plak 

acılar....! 

sevdalı yüreklere bu kadar yüklenmeyin', 'acılar... sevdalı yürekleri buruşturan acılar  kalp sancım bitmeyen şarkı  hüzün kokan şarap  Rize şehrin ortasında  bir masal kahramanı  bi...', ARRAY['Türk Edebiyatı','Şiir','Neşat Turan']::text[], 8.5, '{"poet":"Neşat Turan","poet_slug":"nesat-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/son-soz-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nur Doğuyor', 'nur-doguyor-necmiye-sarpkaya-zs8y3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlık zifiri karanlıklar 

Geceler aysız yıldızsız 

Geceler nursuz ışıksız 

Mehtapsız dipsiz kuyular

Zindanlar gibi karanlık

Afak karanlık 

Ufuklar umutsuz 

Kainat yasta 

İnsanlık hasta 

Küfür şirk yalan 

Hile zulüm zalim 

Günahlar diz boyu 

Günahlar 

Aydınlıkları boğmakta 

Karanlıklar 

Her taraf zifiri karanlık 

Diller suskun 

Gönüller küskün 

Ruhlar mutsuz umutsuz 

Şafak yaklaşmakta adım adım 

Güneş doğacak 

Karanlıkları boğacak 

Sonsuz nur doğacak 

Selama durmuştu kainat 

Muştular sunmuştu düşler 

Lal olmuştu diller 

Tatlı bir telaş 

Bir heyecan 

Bütün alemler beklemede 

Alemlerin efendisini 

Güllerin efendisini 

Nebiler nebisini beklemede 

Günlerden Pazartesi 

Kutlu bir gün şafak vakti 

Bir yıldız doğar gök kubbeye 

Kisra Sarayında yıkılır burçlar 

Kabe de kırılır putlar 

Mecusi ateşleri söner 

Hasedinden 

Bir nur bir nur 

Kutlu bir nur görünür 

Asumanda 

Teker teker 

Salkım salkım 

Dökülür yıldızlar 

Gökyüzünden 

Nur çocuk açar gözlerini 

Sevince boğulur bütün dünya 

Şifa Hatun şaşar bu işe 

Şerbetler sunulur 

Muştular sunulur 

Beşer aklı şaşar 

Göklerde Ahmet 

Yeryüzünde Muhammet (s.a.v)

Bir yıldız bir güneş 

Bir umut doğar 

Karanlıkları boğar 

Allah’ın selamı rahmeti 

Üzerine olsun

Necmiye Sarpkaya', 'Karanlık zifiri karanlıklar  Geceler aysız yıldızsız  Geceler nursuz ışıksız  Mehtapsız dipsiz kuyular Zindanlar gibi karanlık Afak karanlık...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/nur-doguyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-erhan-arslan-77g8q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Son sözündü ayrılık

Sonbaharın ilk günüydü

Soğuk rüzgarlar esmişti aramızda

Sert ve zamansız gelen yağmur

Şahitti göz  yaşlarımıza 

Dudaklarını kıpırtadamıyordun soğuktan

Cümleleri kuramıyordun hıçkırıktan

Korkuyordun ayrılıktan

Ellerin soğuktu ve donuk

Aşk kalmamıştı anlaşılan

                      (2002)', 'Son sözündü ayrılık Sonbaharın ilk günüydü Soğuk rüzgarlar esmişti aramızda Sert ve zamansız gelen yağmur Şahitti göz  yaşlarımıza  Dudaklar...', ARRAY['Türk Edebiyatı','Şiir','Erhan Arslan']::text[], 8.5, '{"poet":"Erhan Arslan","poet_slug":"erhan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ayrilik-235-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Durulmuşum', 'durulmusum-volkan-yoruc-f68p6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün bahar mevsimi

Durulmuşum

Azgın sulardan çıkmışım

Gökmaviye bakar artık gözlerim

Şimdi içten bir türkü tutturmuşum

Durulmuşum

Bir sofaya öylece sakince kurulmuşum

Yalınayaklarıma batan dikenlerle avunmuşum

Sevda denen yoldan dönenler gibi

Yorguncasına bir köşeye çekilipte uyumuşum

Gün umut mevsimi

Durulmuşum

Bahar çağlarımda ne acılar tatmışım

Öğrenmişim, görmüşüm, unutulmuşum

Umut demişim yaşamışım

İnadına inadına

Ve hayatın saklı köşesinden bırakmamacasına asılmışım', 'Gün bahar mevsimi Durulmuşum Azgın sulardan çıkmışım Gökmaviye bakar artık gözlerim Şimdi içten bir türkü tutturmuşum Durulmuşum Bir sofaya ...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/durulmusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnadına Varsın...', 'i-nadina-varsin-ugur-deniz-ulkegul-sq0cy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '“Yıkık dökük bir hayatın,

  İçinde rastladık aşk’a...

  Kim kırar bizi gülüm? 

  İkimizden başka…”

Hani söyler ya birileri,

Fısıldar kulağına…

Mavisine çatar Deniz’in,

Kimi zaman dalgasına…

Sığ sularında boğulur sözleri…

Dönüp baksan, tanıyamazsın,

“Değişkendir” yüzleri…

Söyler ya birileri,

Anlatır yalnızlığına…

“Yokluğun gece bekçileri” 

Girer kararsızlığına…

Oysa gölgeleri yoktur onların,

Kaldırımlarda ayak izleri…

Kölesi olmuşlardır korkuların,

Saklı tutarlar, en zavallı gizleri…

Hani eğip bükerler ya cümleleri,

Utanır kelam, ar eder kendinden…

Soysuzluğun en asil kelimeleri,

Sızar nefs-i emmare’ lerinden…

Hani söyler ya birileri,

Kara’dan, Deniz’den…

Güler bir balıkçı, taka’ sında,

Dönerken Karadeniz’den…

Çakıl taşlarına inat,

Vira Bismillah’dır kelamı…

Yoktur korkumuz der,

Ne rızkımız, ne nevalemizden…

Üç somun ekmek, bir döşek,

Bir avuç toprak, biraz gökyüzü,

Yorgunluğa inat sevişmek,

Karanlığa soyup gündüzü…

Namusum demek sana,

Özlemek yakınında seni…

Dalıp gitmek yar uykusuna,

Saklamak koynunda nefesini…

Hani söyler ya birileri,

Fısıldar kulağına…

“Deniz boran,

Deniz fırtına,

Deniz soğuk

Gelir kumlarına…”

Bak,

Deniz su,

Deniz saydam,

Deniz berrak…

Bırak! ...

Gömülsünler…

Kendi çamurlarına…

Gül açmışsa…

Gönül sevmişse…

Sür kulaçlarını sen,

Aşk’ın en derin,

Okyanuslarına…

Sığ sular…

Onların olsun…

Sen…

Benimsin…

Sen…

Sevdiğimsin…

Biliyorsun…', '“Yıkık dökük bir hayatın,   İçinde rastladık aşk’a...   Kim kırar bizi gülüm?    İkimizden başka…” Hani söyler ya birileri, Fısıldar kulağın...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/inadina-varsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımdan Geçer', 'aklimdan-gecer-ozgur-kokturk-nrdp5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aklımdan neler geçer

Bir sen geçer mavi gözleriyle

Hüznüme eşlik eden yabancı bir rüzgâr

Bir gecenin saat iki buçuğu

Yaşanmış yıllara duyulan özlem

Ve daha neler neler

Aklımdan geçer...

Geçer ya; 

Bir kaldırım taşının üzerine dökülen umut yığını

Bir de basıp geçenler

Kaldırıma bakmadan

Bir de karabasan çökmüş karanlık düşler

Bir de sen geçer 

Mavi gözleriyle...

Tutmayacak fidanlara yağan yağmurlar

Çatlamayacak toprağa...

Senetsiz, pazarlıksız harcanan bir ömür

Ömre biçilmemiş bedel geçer

Mühürlenmiş kapılara vurulan kilitler

Bir de kenetli ellerin 

Bir de sen geçer

Mavi gözleriyle

Bir de ben

Esmer düşleriyle

Ve daha neler neler

Aklımdan geçer...

26 / 03 / 2001     17:03', 'Aklımdan neler geçer Bir sen geçer mavi gözleriyle Hüznüme eşlik eden yabancı bir rüzgâr Bir gecenin saat iki buçuğu Yaşanmış yıllara duyula...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/aklimdan-gecer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiği Gün', 'gittigi-gun-erhan-arslan-mcac1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani; 

       bir gün elveda dersen bana

       ilk gözlerime bak giderken

Hani; 

       gidiyorum kalbinden 

       taşınıyorum yüreğinden 

       dediğin gün:

       tüm yıdızlarıda götür buralardan

       ağlama deyipte sarıldığın gün

       bulutlarıda götür buralardan

Hani; 

       bir neden uydurup 

       beni bırakıp gittiğin gün

       karanlıklarıda götür buralardan

       umutlarımı yok edip

       hayellerimi suya düşürdüğün gün

       hasretinide götür buralardan

Hani; 

       beni unutma dediğin gün

       başta rüzgarları götür buralardan

       gideceğin an; özür dileyip

       arkana bakmadan sessizce gittiğin gün

       BENİ ÖLDÜRDE GİT BURALARDAN

                                 (20002)', 'Hani;         bir gün elveda dersen bana        ilk gözlerime bak giderken Hani;         gidiyorum kalbinden         taşınıyorum yüreğinden ...', ARRAY['Türk Edebiyatı','Şiir','Erhan Arslan']::text[], 8.5, '{"poet":"Erhan Arslan","poet_slug":"erhan-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gittigi-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diye Diye', 'diye-diye-ozgur-kokturk-c199d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevda ırmağında yundu desinler

Bir gönüle girdi, çıktı desinler

Su idi ateşler sundu desinler

Desinler diye diye sevilmez ki

Dostlar gülsünler düşmanlar gülsünler

Deli sevdası solanlar gülsünler

Derdi dermansız olanlar gülsünler

Gülsünler diye diye ağlanmaz ki

Azı çoğu saymayanlar bilsinler

Uykulardan aymayanlar bilsinler

Sır olmasın, duymayanlar bilsinler

Bilsinler diye diye söylenmez ki', 'Sevda ırmağında yundu desinler Bir gönüle girdi, çıktı desinler Su idi ateşler sundu desinler Desinler diye diye sevilmez ki Dostlar gülsünl...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/diye-diye-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-emine-deniz-6t67r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '..................... Aşklar yıkadım fakir gecelerimin karanlığında 

..................... Güneş görmemiş 

Yitirilmiş zamanların kıskacında asıldığımız 

hayatın ta kendisiydi. 

otobüse yetişmeye 

ya da 

Bir koşu ekmek almaya benzedi 

_______Sevişmelerimiz. 

Dar sokaklarda saklambaç oynanmaz gülüm 

Saksıda sarmaşık gülü yetiştirmeye benzer 

Kan olur 

________ellerimiz... 

Kalsın dudaklarımın tadı dudaklarına 

Hatıra 

Ve teninde ellerim 

Unutma... 

________Bu biz değiliz. 

Eksik yağmurlardan ve unutulmuş bahardan bir gün daha 

Çalmak ve yaşamak adına 

Yelpazesini suya düşüren kadın tutsaklığında

Kanatlandım adınla. 

Ki adın anlam kazandı dudaklarımda... 

Bir an 

Gözlerin değmedi gözlerime 

Sevişirken seninle 

Kadınlar düşündün adı olmayan? 

Kadınlar, 

saçları sarı kurdelelerle tutturulmuş 

çocuksu edalarla gökyüzüne gelişigüzel oturtulmuş... 

elleri güzel kadınlar,saçları sarı 

Sevişirken benimle... 

Suya yazıldı 

______İhanetimiz 

sen 

Kafatasımın içini kemiren tümör 

kan kokmayan sevdalar beslediğim 

...sevdiğim 

Aşk bu değilmiş 

Yalanmış bütün 

_______Bildiklerimiz.', '..................... Aşklar yıkadım fakir gecelerimin karanlığında  ..................... Güneş görmemiş  Yitirilmiş zamanların kıskacında ...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yalan-139-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Ki', 'yok-ki-ozgur-kokturk-upxw4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ay geceyi ışıtmıyor

Parlak yıldızlarım yok ki

Bulutlar kapkara oldu

Isıtan güneşim yok ki

Bülbül oldum avazlandım

Konacak bir gülüm yok ki

Şahin oldum havalandım

Yükseklerde yarim yok ki

Gönlüm yangınlara düştü

Söndürmeye gücüm yok ki

Yağmur içimde üşüdü

Gücenmedim öcüm yok ki

Dertliyim dertlere sardım

Dermanım say derdim yok ki

Bilmem artık ne yapayım

Aklım var say fikrim yok ki', 'Ay geceyi ışıtmıyor Parlak yıldızlarım yok ki Bulutlar kapkara oldu Isıtan güneşim yok ki Bülbül oldum avazlandım Konacak bir gülüm yok ki Ş...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yok-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yelken Açarım', 'yelken-acarim-yavuz-agir-k9sf8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umutlara yelken açarım

Kederin, hüzünün,acının olduğu yerde.

S. yarime içim dökerim.

Dermansız derdimin olduğu yerde..

Umutlarım,hayellerim,düşlerim; 

Bir bir yok olsada gülüşlerim,

Özgürlüğe yelken açarım

Yanan ışığın söndüğü yerde...

Gönül bağıma artık kuşlar konmuyor

Çektiğim,acılar,ızdıraplar dinmiyor

Güzel günlere yelken açarım

Kırmızı gülümün solduğu yerde....', 'Umutlara yelken açarım Kederin, hüzünün,acının olduğu yerde. S. yarime içim dökerim. Dermansız derdimin olduğu yerde.. Umutlarım,hayellerim,...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yelken-acarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte O Zaman', 'i-ste-o-zaman-nur-demirciler-z5kv9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşkı kaybettim,

satır aralarında,

işte o zaman 

hissettim,

tırnaklarımın kanatırcasına acısını,

tenimde ilk kez.

işte o zaman 

daha kolay geldi,

gerçekten kaçıp,

yalana sarılmak.

Ben oynaşırken kelimelerle,

onlardı beni uzaklaştıran,

................ AŞKTAN', 'Aşkı kaybettim, satır aralarında, işte o zaman  hissettim, tırnaklarımın kanatırcasına acısını, tenimde ilk kez. işte o zaman  daha kolay ge...', ARRAY['Türk Edebiyatı','Şiir','Nur Demirciler']::text[], 8.5, '{"poet":"Nur Demirciler","poet_slug":"nur-demirciler","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/iste-o-zaman-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamozlar', 'yakamozlar-yasin-yamak-r9yrp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merhaba deniz köpüğü yakamoz,

Sen mi beliriverdin aniden yüreğimde? 

Yoksa o çocuksu çırpınış isteğin mi bu son gecemde? 

Neden benimle berabersin? 

Ayın ışığı bıçak gibisin ve yakamoz masumsun o bıçaktan,

Deniz üzerinde beliren sen misin? 

Kelimelerim dil üstünde,ifadeye güç yetirememe korkusu içindeler.

Bu gece yine kendinden kaçmış gibi yakamozlar,gözlerimin önündeler.

Ben mi seslerin aksedişini hissedemiyorum yoksa bu güç ısrarla,

Çınlatmak mı istiyor duru denizi? 

Merhaba yine deniz rakkasesi yakamoz,

Sen mi çıktın aniden doğan gözyaşları tuzluluğunda? 

Yoksa o hafif sallanış isteğin mi bu son rüzgarda? 

Neden sen denizle sevda çekersin? 

Buğday kokusu hasret gibisin ve yakamoz titreyerek o kokudan,

Buğu gibi göğsüme doluşan sen misin? 

Gidişin saatin üzerinde,beklemeye sabır edememe korkusu içimde,

Bu şafak vakti yine hoşçakal tadında yakamozlar,gitmek üzere.

Ben mi gitmelerini istiyorum yoksa bu göç ısrarla,

Savurmak mı istiyor üzerindekini,rehavet sarılı gecenin koynuna?', 'Merhaba deniz köpüğü yakamoz, Sen mi beliriverdin aniden yüreğimde?  Yoksa o çocuksu çırpınış isteğin mi bu son gecemde?  Neden benimle bera...', ARRAY['Türk Edebiyatı','Şiir','Yasin Yamak']::text[], 8.5, '{"poet":"Yasin Yamak","poet_slug":"yasin-yamak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yakamozlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşıyoruz...rezilce', 'yasiyoruz-rezilce-dursun-elmas-qquuc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ahmet,Mehmet''in 

Ayağın kaydırıyor... 

Mehmet,Hasan''ın 

Hasan da; Hüseyin''in. 

....''Kaydır babam kaydır! '' 

Ayşe,Mustafa''da ısrarlı 

Mustafa,Fadime''de. 

Fadime,Orhan''a aşık... 

İşler karmakarışık... 

....''Yandır babam yandır! '' 

Adem’den bu zamana 

Yasa zenginden yana. 

Bal tutan parmağını

Yalayan yalayana

....''Bandır babam bandır! '' 

En güzel yaratıldık, 

Diyor,övünüyoruz. 

Ne helâl biliyoruz, 

Ne de haramı... 

Habire çalıyoruz... 

Araklıyoruz... 

....''Çal babam çal! '' 

Bir eli yağda 

Ötekisi balda gavatın... 

Hayatını yaşıyor 

Variyetin içinde. 

Sürdürüyor zevkini 

Hemi de o biçimde... 

....''Vay babam vay! '' 

Ayırmak mümkün değil 

Kavun değil ki,insan 

....................koklayasın. 

Alnında yazmıyor ki, 

Doğrusunu bulasın... 

Çalmazsan, dürüst isen

Olursun andavallı. 

Kaz yerine milleti

Soyup soğan edenler

Hepsi yasadan ballı... 

....''Yol babam yol! '' 

Yaşamak buysa eğer? 

Yaşıyoruz...rezilce. 

Bir de bakıyorsun ki, 

Ölüyoruz gizlice... 

....''Öl babam öl! ''

Dursun ELMAS', 'Ahmet,Mehmet''in  Ayağın kaydırıyor...  Mehmet,Hasan''ın  Hasan da; Hüseyin''in.  ....''Kaydır babam kaydır! ''  Ayşe,Mustafa''da ısrarlı  Mustafa...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/yasiyoruz-rezilce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler Sokağı', 'dusler-sokagi-ziya-nizam-h9q3z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün hava kararmış

Odanın duvarları

Dostluğunu paylaşmaya başlamışsa

Ve kumsala vuran dalgaların sesini

Kulaklarında hissediyorsan

Hemen yanında olup ta

Aslında çok uzakta olan

Bir sevgiliye hasretsen

Daha bir sıkıca sarıl hayata

Yaşanmış güzel günleri düşün

Ve yaşanacaklara kucak aç.

Dalmışsan maziye yaşlı gözlerle

Gir düşler sokağına

Orada sana bir dost mutlaka vardır.

Çünkü orası senin düşlerinin sokağı.

	25.12.1996-Çarşamba

	03:08 Karadeniz FM Rize

	1996 Karadeniz FM Düşler Sokağı program tanıtım metni.

	2002-2005 Meltem Radyo Kadir Çaça’yla Düşler Sokağı program tanıtım metni.', 'Bir gün hava kararmış Odanın duvarları Dostluğunu paylaşmaya başlamışsa Ve kumsala vuran dalgaların sesini Kulaklarında hissediyorsan Hemen ...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dusler-sokagi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gideceksin Şimdi', 'sen-gideceksin-simdi-ziya-nizam-b3wf9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen gideceksin şimdi.

Benim yine içim acıyacak

Görünmez yaşlar akıtacağım gözlerimden

Sırf sana gitme diyemedim diye.

Kalbim duracak sen tekrar gelinceye dek.

Gözlerim kararacak

	Seni tekrar görünceye dek.

Artık biliyorum

Yokluğunda yaşayamayacağım ben.

			04.02.2003-Salı

			16:44 Bauhaus Bayrampaşa', 'Sen gideceksin şimdi. Benim yine içim acıyacak Görünmez yaşlar akıtacağım gözlerimden Sırf sana gitme diyemedim diye. Kalbim duracak sen tek...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-gideceksin-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Konamayan Aşk', 'adi-konamayan-ask-ziya-nizam-uib4e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saatler önceydi,koptuk biz.

Yoksa

	Yıllar mı oldu.

Gözüyaşlı otobüs camlarını

	Daha dün siliyordu silecekler.

Ne sevdanın adına yakıştı bizimki

Ne de ayrılığın.

İçme; 

	Diyorsun bana

		Her kafam güzel olduğunda.

Her gece içmem,ondan işte.

Yeni başladım; 

Sensizliği,sen gibi yaşamaya.

Şimdi bir dilek parası attım

Kör karanlığa.

Adı  konmasın dedim bu sevdanın.

Adı konamasın.

Otursam,

	Saatlerce yazacağım sana.

Otursam,

	Saatlerce içeceğim tüketilmiş yıllara.

Otursam,

	Ağlayacağım.

İnatçı lekeler her yanımda

İnatçı lekeler

Çıkmıyor bu aşktan hiç.

Az önce,yıldızlı bir gecede

Bir damla yağmur olmayı başardım

				Sayende.

Hayatımdaki üç tehlikeli beyazdan birisin şimdi.

Sigara,rakı ve tenin.

İlk ikisinden vazgeçmek öyle kolay.

Teninse vazgeçilmez bir tutku.

			20.07.2004-Salı

			00:12 Avcılar', 'Saatler önceydi,koptuk biz. Yoksa 	Yıllar mı oldu. Gözüyaşlı otobüs camlarını 	Daha dün siliyordu silecekler. Ne sevdanın adına yakıştı bizi...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/adi-konamayan-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylemek İstediğim', 'soylemek-i-stedigim-yasin-yamak-ae1gb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yaşam düşlüyorum sevgiliye dair,

Bir yaşam ki hem İstanbul var içinde,

Hem de gözlerin.

Ve de o çok sevdiğim Üsküdar geceleri,

Sensizliği yaşadığım bu evde,

Bu düşler sanki bir kadeh zehir...

Bir çile düşlüyorum geceye dair,

Bir çile ki hem yalnızlık var içinde,

Hem de sensizliğim.

Ve de o İstanbul''un nefret ettiğim sisi.

Sisden göz gözü görmez olmuş bu şehirde,

Bu sis insana çok acı çekitirir...

Bir özlem düşlüyorum sevilenin gelişine dair.

Bir özlem ki hem onu kokusu var içinde,

Hem de sevgisi.

Ve de o umudum yani ellerimde elleri,

Sulanmış gözler bu şehri izlemekte,

Beni bu sevilen daha çok bekletir...

Bir söz söylemek istiyorum aşka dair,

Bir söz ki akseder sürekli içimde,

Hem de aydınlatır içimi.

Ve de yaşartır sevinçten gözlerimi

Söylemeden duramam her an dilimde 

Bu söz ki manası 

Seni seviyorum demektir...', 'Bir yaşam düşlüyorum sevgiliye dair, Bir yaşam ki hem İstanbul var içinde, Hem de gözlerin. Ve de o çok sevdiğim Üsküdar geceleri, Sensizliğ...', ARRAY['Türk Edebiyatı','Şiir','Yasin Yamak']::text[], 8.5, '{"poet":"Yasin Yamak","poet_slug":"yasin-yamak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/soylemek-istedigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamazdım Sensizliğimi', 'unutamazdim-sensizligimi-yasin-yamak-s1qy8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oturup kıyıda köşede bir yerde,

Geçen her anıma küfretmek için,

Her düşündüğümde kızıp,

Gözyaşlarımla öfkemi söndürmeye uğraşmak için,

Oturup,beklemek istedim.

Beklesem bile bilirdim,ellerim titrerdi.

Senin yokluğunu beklediğim için,korkardım istemeden,

Oturup dizlerimi hayaline dayayıp,tebessüm ederken,

İrkilirdim birden,kabus olurdu bana gecem...

Aklım karışırdı deniz dalgasında oynaşan yakamoza bakınca,

Işığı sönünce ayın,giden sahte oyuncular,birer dosttu rüzgarda.

Oturup düşünürken güzel İstanbul''un yalnız mahiyetini,

Yine de anlam veremezdim,unutamazdım sensizliğimi..', 'Oturup kıyıda köşede bir yerde, Geçen her anıma küfretmek için, Her düşündüğümde kızıp, Gözyaşlarımla öfkemi söndürmeye uğraşmak için, Oturu...', ARRAY['Türk Edebiyatı','Şiir','Yasin Yamak']::text[], 8.5, '{"poet":"Yasin Yamak","poet_slug":"yasin-yamak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unutamazdim-sensizligimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Azın', 'cok-azin-erdal-gisi-fp9wu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '__Dalgaların boğmasın…

Bu kırık tekneyi çıkar sahile

Kurban istiyorsan yalnız beni al..

__Bu ağır emaneti..

Uzatacaksan elini ne gam…

Unutacak, kıracaksan bilemem

__Soluyorken yine içimde bir yer..

Beni hiç kimseye imtihan yapma

Hiç kimseyi bana dünya beşiği

__Ki bana çok gelir senin en azın

Rahmetin damlası taşar taşar...

Elimde ufacık kırık bir testin..

Ocak 2005', '__Dalgaların boğmasın… Bu kırık tekneyi çıkar sahile Kurban istiyorsan yalnız beni al.. __Bu ağır emaneti.. Uzatacaksan elini ne gam… Unutac...', ARRAY['Türk Edebiyatı','Şiir','Erdal Gişi']::text[], 8.5, '{"poet":"Erdal Gişi","poet_slug":"erdal-gisi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cok-azin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baksana bana Nasıl görüyorsun...', 'baksana-bana-nasil-goruyorsun-mehmet-selim-tolay-626p8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç belli olmaz 

baksana bana nasıl görüyorsun,

içimde ki mutluluğu nasıl süzüyorsun.

bir mum al ellerine gözlerimi ışılt

hiç belli olmaz belki

günlerim güneş dolar

asırlar gülüşlerinin akışında savrulur belki...

hiç belli olmaz

kadehim kuru gölgeli

penceremde lavların püskürüş seli.

Baksana bana nasıl görüyorsun

lodosu poyrazı nasıl seçiyorsun

granit yalnızlığımda neş''eler saçıyorsun.

Hiç belli olmaz yarınlarda 

hüzünleri biçiyorsun.

Herşeyin bir sonu var

tıpkı bizler gibi

doğar yaşar ve ölür.

Neden hafife alıyorsun

bunları biliyor musun? 

neden naz yapıyorsun.

Tam kırk derece ateşim var,

hiç belli olmaz biliyor musun

kırk derece gözlerin mezartaşım seziyor musun

baksana bana nasıl görüyorsun

hiç belli olmaz

göçerim uzaklara turnalar gibi

biliyor musun

sende biter başlangıçlar

sende tükenir sonuçlar

anlıyor musun?', 'Hiç belli olmaz  baksana bana nasıl görüyorsun, içimde ki mutluluğu nasıl süzüyorsun. bir mum al ellerine gözlerimi ışılt hiç belli olmaz be...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Tolay']::text[], 8.5, '{"poet":"Mehmet Selim Tolay","poet_slug":"mehmet-selim-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/baksana-bana-nasil-goruyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir aşkına yanıyorum', 'bir-askina-yaniyorum-tuncay-akdeniz-df078', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özüm bağlıdır birine

Bir aşkına yanıyorum

Bak alemin her yerine

Nur aşkına yanıyorum

Arif olan kendin bilir

Bu dünyadan feyiz alır

Çekirdek toprakta büyür

Sır aşkına yanıyorum

Yardanın bak işine

Uçmayı vermiş kuşuna

Can verir cansız taşına

Pir aşkına yanıyorum

İnsan kadere darılır

Arı çiçeğe sarılır

Mecnunlar çölde yorulur

Yâr aşkına yanıyorum

Arzından arşına baksan

Varmı bir yerinde noksan

Şu doğayı bir koklasan

Yer aşkına yanıyorum

Tuncayım yönüm Mevlaya

Gece baksan bir semaya

Alemler durmuş duaya

Tur aşkına yanıyorum', 'Özüm bağlıdır birine Bir aşkına yanıyorum Bak alemin her yerine Nur aşkına yanıyorum Arif olan kendin bilir Bu dünyadan feyiz alır Çekirdek ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-askina-yaniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Beni Dinleyin.', 'hey-beni-dinleyin-ali-osman-yilmaz-0feje', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hey beni dinleyin,

Seven yürekler,

Tüm güzel gönüller,

Size sesleniyorum.

Hiç bir şey beklemeden,

Yüreğinizin sizi,

Götürdüğü yere gidin.

Ve yalnızca,

Yüreğinizle sevin.

Sevmezseniz eğer,

Mutlu olmak,

İnanın,

Mümkün değil.', 'Hey beni dinleyin, Seven yürekler, Tüm güzel gönüller, Size sesleniyorum. Hiç bir şey beklemeden, Yüreğinizin sizi, Götürdüğü yere gidin. Ve...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hey-beni-dinleyin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Aidatınızı Ödeyiniz! ...', 'sevgi-aidatinizi-odeyiniz-tulay-sustam-lpzm7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kendini sevmekle başlar; bir insanı sevebilmek...

Kaçımızın hayatında halâ çocukluk ve okul yıllarından kalma dostlukları var. Kaçımız bir sokak çocuğunun ve bir yetimin yüzünü güldürebiliyoruz.

Kaçımız hiç tanımadığımız bir insanın acısına ortak olup kendi acımız bilip gözyaşı dökebiliyoruz. Kaçımızın sımsıkı sarılabileceği, başını omuzuna koyabileceği, bütün sıkıntılarını anlatabileceği dostları var.

Kaçımız sevdiğimiz birinin doğumgününü kendi doğumgünümüz gibi unutmuyoruz.

Kaçımızın adı yaşadığımız şehrin sınırlarını aştı. Kaçımız gerçek bir dost,

bir sırdaş ve bir sevgili diye anıldık. Kaç kişi size sevdiğim, yüreğim, dostum, kardeşim iyi ki varsın ve hep yanımda ol diyebildi. Ve kaç kişi sizi ailesinden bir parça gibi görüp anne, baba, abla, abi, kardeş diyebildi. Bugüne kadar yüreğinizin kapısını kaç kişi çaldı ve siz ''tanrı misafiri'' diyerek yüreğinizi ona açtınız. Kaçınız dost ve düşmanı birbirinden ayırıp dostunuzu düşmanınıza satmadınız. Kaçınız bir çiçeği dalında sevdiniz. Kaçınız yaşadıklarınızdan ders alıp bir daha tekrarlamadınız. Kaçınız her gece ettiğiniz duâ da kendiniz için istediklerinizi sevdikleriniz için, yüzünü bile görmediğiniz insanların mutluluğu için dilediniz. Kaçınız şimdi adını bile hatırlamadığınız bir insanın sayesinde şu an ki bulunduğunuz konuma gelmeniz de büyük bir etkisi

olduğunun farkına varabildiniz. 

Kaçınız yüzünü bile görmediğiniz birine dostum dediğiniz için kalemi elinize aldığınız da yazabildiniz. Kaçınızın hiç gerçekleşmeyecek bir hayali gerçekleştiğinde mutlu olduğunuz zaman, bende bir insanın hayalinin

gerçekleşmesi için bir umut, bir ışık olacağım diyebildiniz. Kaçınızın yıllar sonra bile anlatırken gülümsebildiği hattâ gözyaşı dökebildiği anıları var. Kaçınız size yapılan bir hatayı görmemezlikten gelip bende yanlış yapabilirim, bende yanılabilirim diyerek o insanı affedebildiniz.

Aslında düşündüğünüz de bütün bunları yapabilecek hem yüreğimiz hemde vaktimiz var. Hayatta her şeyin bir bedeli var. Ama insanları sevmenin yok. Hepimiz bu hayat yolunda bir şekilde giden yolcularız. Beraber yolculuğa çıktığımız ve hayatı paylaştığımız sevdiklerimizi gelip geçici değerler için ihmal etmeyelim. Unutmayalım ki hayatımız da olan her insan yüreğimizin bir sahibi. Ve bizler onlara olan ''sevgi aidatımızı'' zamanın da ödeyelim. Hem kendimizi hemde sevdiklerimizi mutlu edelim. Hayatta ki her şey ertelenebilir ama sevdiklerimiz ertelenmeye gelmez. Bizden beklenen

sıcacık bir sevgiyi, bir tebessümü, bir merhabayı onlara çok görmeyelim. Hadi dostlar bugün hepimiz üzerimize düşen ''sevgi aidatımızı'' ödeyelim...

Kendini sevmekle başlar; bir insanı sevebilmek...

Allah''ıma şükrediyorum bana bütün bu güzellikleri yaşattığı için...', 'Kendini sevmekle başlar; bir insanı sevebilmek... Kaçımızın hayatında halâ çocukluk ve okul yıllarından kalma dostlukları var. Kaçımız bir s...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgi-aidatinizi-odeyiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islansın Bırak Yanaklarım.', 'islansin-birak-yanaklarim-ali-osman-yilmaz-jvgx1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağ suratıma usul usul,

Bırak ıslansın yanaklarım,

İnadına değil ama,

Öfkeyle hınçla değil,

Sevgiyle özlemle ak,

Seni öptüğüm günki gibi,

Islat yanaklarımı,

Çölleşmiş dudaklarımda,

Tuzlu bir tad oluşsun

Ve sensiz geçen,

Yaban yalnızlığımda,

Irmaklar gibi aksa da,

Yanaklarımdaki ıslaklık,

Ve tuz tadın dudaklarımda,

Seni öptüğümü düşliyeyim,

Göz yaşlarımda.', 'Yağ suratıma usul usul, Bırak ıslansın yanaklarım, İnadına değil ama, Öfkeyle hınçla değil, Sevgiyle özlemle ak, Seni öptüğüm günki gibi, Is...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/islansin-birak-yanaklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilimde ay tutuldu../..dilsizim', 'dilimde-ay-tutuldu-dilsizim-pelin-onay-w8djx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(akşam şaraba yatıracağım yüreğimi../..yarına bi''şeyciğim kalmaz) 

korunaklı şiirler yaz bana, sevgilim olmayan sevgili

sağanak yağışlı günlerimde sığınacağım bir yer bulunsun

bari, şiirlerde bir ev''cağızım olsun

üç oda bir salon yalnızlığımı kiraya vereceğim

heveslenme, senin için düşlerim başka

aklını başından alıp, gezmeye götüreceğim

ne güzel gülüyorsun, dudaklarında eski İstanbul resimleri

öyle kal lütfen, yüzüme baktığın anın resmini çekeceğim

sana söz veriyorum, sen de bana umut ver

sonra her şeyi unutup, ülkeme geri döneceğim

bende bir hoşum, şarkıların belalı güzelliğine vuruldum

o uzak ay''da kaldı onayladığım gülüşler

raks eden sevişmelerin çingene zamanındayım,

''gel'' desen, gidemeyecek kadar sarhoştur özlemler

anlayışımı kaybettim, beni anla

karşılığında gözlerimin kahvesinden içireceğim

düşe kalka düşledim, son baharım kaldı

beni şimdi tutmazsan, dudaklarına devrileceğim

oturaklı şiirler yaz bana, sevgilim olmayan sevgili

yorgun günlerimde dinleneceğim bir yer bulunsun

şiirlerde bari, bir nefeslik yerim olsun

''05-izmir havası', '(akşam şaraba yatıracağım yüreğimi../..yarına bi''şeyciğim kalmaz)  korunaklı şiirler yaz bana, sevgilim olmayan sevgili sağanak yağışlı günl...', ARRAY['Türk Edebiyatı','Şiir','Pelin Onay']::text[], 8.5, '{"poet":"Pelin Onay","poet_slug":"pelin-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dilimde-ay-tutuldu-dilsizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmuyorsun', 'unutulmuyorsun-alaeddin-i-kican-i08z5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unutulmuyorsun

                             (Babama) 

Yapraklar durgun,hiç hareket yok,

Sanki fışkıran nimetler,bereket yok,

Sessizlik,boş bakan gözler,

Bana birşeyler fısıldıyor,

Babana koş sarıl diyor,

Saatin zili çalıyor,

Anladım,babam gidiyor,

Engel olamam,

Dağları çin seddi gibi,

Önüne koyamam,

Sana fütursuzca bakıyorum,

Sadece dua ediyorum.

Uyan baba uyan,

Son kez ışıldayan gözlerinle bana bak,

Nur tanesi sözlerinle bana öğüt ver,

Gücüm kalmadı baba,yalvaramıyorum,

Sana doymadan,sen hayatı yaşamadan,

Gitme dur diyemiyorum,

Öyle bir güç varki baba,

Sesim kesildi,konuşamıyorum,

Sadece sana dua ediyorum.

Damarlarımdaki kanda seni hissediyorum,

Ahlaksız şuursuz yaşamda seni arıyorum,

Sen rahat ol baba,yattığın yerde rahat uyu,

Bu dünya kahpeler,yalancılarla dolu,

Sen toprak altında değilsin,

Bulutlarda uçuyorsun,

Kalplerimizde coşuyorsun,

Dualarımızda bitiyorsun,

Sen unutulmuyorsun baba.!', 'Unutulmuyorsun                              (Babama)  Yapraklar durgun,hiç hareket yok, Sanki fışkıran nimetler,bereket yok, Sessizlik,boş b...', ARRAY['Türk Edebiyatı','Şiir','Alaeddin İkican']::text[], 8.5, '{"poet":"Alaeddin İkican","poet_slug":"alaeddin-i-kican","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/unutulmuyorsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delimiyim Neyim.', 'delimiyim-neyim-ali-osman-yilmaz-ei13o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben sensiz,

Yelkensiz,dümensiz,

Hatta küreksiz,

Bir tekneyim.

Açılmışım enginlere,

Bir başıma ve sensiz,

Delimiyim,neyim?', 'Ben sensiz, Yelkensiz,dümensiz, Hatta küreksiz, Bir tekneyim. Açılmışım enginlere, Bir başıma ve sensiz, Delimiyim,neyim?...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/delimiyim-neyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Harfler Bile Ağlıyor.', 'harfler-bile-agliyor-ali-osman-yilmaz-tmynn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben yazıyorum durmadan,

Seni seviyorum diye,

Ama bak,

Harfler bile ağlıyor,

Kurduğum cümleler,

Kan kaybediyor,

Böyle giderse eğer,

Sana yazdığım kelimeler,

Benimle birlikte,

Ölecekler.', 'Ben yazıyorum durmadan, Seni seviyorum diye, Ama bak, Harfler bile ağlıyor, Kurduğum cümleler, Kan kaybediyor, Böyle giderse eğer, Sana yazd...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/harfler-bile-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşulsuz sev seveceksen', 'kosulsuz-sev-seveceksen-ali-osman-yilmaz-5ptfz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne olur,

Seveceksen,

Koşulsuz sev.

Ben seni ölesiye,

Sana sormadan sevdim.

Hadi seveceksen,

Koşul koyma,

Sevmek,

İstemeden vermek,

Almadan verebilmek,

Yalnızca vermek,

İşte bu,

Aşk demek.', 'Ne olur, Seveceksen, Koşulsuz sev. Ben seni ölesiye, Sana sormadan sevdim. Hadi seveceksen, Koşul koyma, Sevmek, İstemeden vermek, Almadan v...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kosulsuz-sev-seveceksen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygular', 'duygular-alaeddin-i-kican-cfbhl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duygular

Ne içindeyim yar gözlerinin,

Ne de tamamen dışında geziyorum.

Kulaklarımın pasını silen sözlerinin,

Ahengiyle duygularımı süslüyorum.

Tan yeri ağarıyor bak sıcak sıcak,

Dağlara yaslanmış kızıl bakışlı şafak,

Seyrediyor sırlara bürünmüş insan takımlarını,

Öpüşmeler,bakışmalar,sevişmeler hep kaçak.

Rüzgarda döğüşen yağmur tanecikleri,

Yıkıyor,ağlamaktan kızaran gözlerimi,

Unutmak mümkün mü? içime sinen,

O inci tanesi sözlerini.', 'Duygular Ne içindeyim yar gözlerinin, Ne de tamamen dışında geziyorum. Kulaklarımın pasını silen sözlerinin, Ahengiyle duygularımı süslüyoru...', ARRAY['Türk Edebiyatı','Şiir','Alaeddin İkican']::text[], 8.5, '{"poet":"Alaeddin İkican","poet_slug":"alaeddin-i-kican","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/duygular-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
