INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıran', 'hatiran-cenk-aksal-y0fyb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bu sabah...

her sabah...

baktığım aynadaki:

yüz benim değil...

anlamsız gözlerde,

yorgunluk izleri....

bu benim seven..

gözlerim değil...

ey vefasız! 

gördünmü bak,

senden kalan,

tek hatıra...

defterler dolusu,

şiir değil...

   ''aynada gördüğüm yüz benim değil''', 'bu sabah... her sabah... baktığım aynadaki: yüz benim değil... anlamsız gözlerde, yorgunluk izleri.... bu benim seven.. gözlerim değil... ey...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hatiran-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalemime', 'kalemime-seref-akar-1dq99', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey gecelerimi sabaha ulaştıran antik kemer

Ey kan deryası hüzünlerimin katıklı bereketi

Eriştir beni

Ateşin biriktirdiği küllerden

Kül kokan damarlarımı çeken

Yüreğime kıymık çakan aşkımın

Hüzünlü lisanı

Eriştir beni

Kırılacak belki dalların

Ey ıstırabımın hayat ağacı

Ey hayatına tutunduğum bel kemiğim

Kırılacak belki

Sen ey zarif 

Yalnızlığım gibi parmaklarımın arasına dolan

Ve ruhumun alın teri

Eriştir beni

Eriştir beni 

Tabiatın saklı gerdanlığına

Bir parça zümrüt çalayım kızlarım için

Ustalığınla işlensin o taş

Kalplerine iman gibi tutuşturayım sonra 

Kalplerinden imanları dökülmesin

Sen ey! , ustamın yadigârı 

Sadık dostum

Acılarımın dökümlü bereketi

Eriştir beni 

Tabiatın yasaklı gerdanlığına

Bir parça yakut çalayım oğullarım için

Ustalığınla işlensin o taş

Ellerine yürek gibi tutuşturayım sonra

Ellerinden yürekleri dökülmesin.', 'Ey gecelerimi sabaha ulaştıran antik kemer Ey kan deryası hüzünlerimin katıklı bereketi Eriştir beni Ateşin biriktirdiği küllerden Kül kokan...', ARRAY['Türk Edebiyatı','Şiir','Şeref Akar']::text[], 8.5, '{"poet":"Şeref Akar","poet_slug":"seref-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kalemime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yaşamadan Öldüm', 'ben-yasamadan-oldum-mehmet-yilmaz-bulancakli-55kk0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Keşke doğmasaydın yavrum,

Bu dünya yaşanmaz oldu.

Yok ki sana hiç umudum,

Ömrümüz bahara gelmez oldu.

Sevgi,umut,hayallerle bir,

Dünya ateşin altında.

Yaşamak bir kabus gibidir,

Borçlarımız hat safhada.

Keşke doğmasaydın yavrum,

Yarından endişe doluyum.

Zor günlerde şu yurdum,

Ben dertlerin yoluyum.

Yaşamak,yine kör sabahı,

Umutların çöküşünü gördüm.

Ya RAB! , nedir bu yavruların günahı,

Ben yaşamadan öldüm.

     

07.03.2003', 'Keşke doğmasaydın yavrum, Bu dünya yaşanmaz oldu. Yok ki sana hiç umudum, Ömrümüz bahara gelmez oldu. Sevgi,umut,hayallerle bir, Dünya ateşi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-yasamadan-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Yabancı/Söyle', 'ey-yabanci-soyle-cenk-aksal-7dlp2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ey yabancı:

söyle sevda üstüne,

tüm türküleri,

ben sarhoş oldum.

bulmaz yolunu/aşkım

şaşar sokakları,

bir mezarlık sessizliğinde

zaman/zamansızlık

kanıma dokunur:

bu anlamsız/yalnızlık

vur sazın teline/söz olsun

ayrılığın üstüne:

suskun dinlerim namelerini..

bu akşam/bir başkayım,

dokunsan ağlar gözlerim,

her damla yaşta:

bir başkadır isyanım...

haydi söyle/kırılmam

ayrılık üstüne yazılmış,

bütün türküleri,dinlerim...

ey yabancı:

gelinmez yollardan/geldin

söyle aşkların üstüne yazılmış,

tüm türküleri/bu akşam,

dökülsün gözümden yaşlar:

aksın içimdeki zehir,

nasılsa ayrılık/öldürecek

türkülerden olsun gidişim...', 'ey yabancı: söyle sevda üstüne, tüm türküleri, ben sarhoş oldum. bulmaz yolunu/aşkım şaşar sokakları, bir mezarlık sessizliğinde zaman/zaman...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ey-yabanci-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Coğrafyam TALAN', 'cografyam-talan-aygul-ece-ha5ao', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bak gün ağarmaya başladı.

Gece sustu,sen sustun

Soruları taşıma sabaha

Erteleme duygularını,

Susma,sustukça

Gece uçurum olur,düşer avuçlarıma

Anlat anlat ki

Dinledikçe yaşamın biteviyeliğinden çıkıp

Hoyratça kamçılar vurayım yaşanmamışlıklara

Anlat ki

Şarkılar sussun,

Sözcükler yetersiz kalsın.

Yaşamın rengi, tükensin dudaklarımızda

Kırılan kanatlarımız, yalnız gecelerimiz

Ağrılı ezgilerimiz son bulsun

Anlat ki

Eksilmek yerine çoğalalım

Ömrümüzün ikinci emekleme döneminde

Beraber öğrenelim yürümeyi

Bil ki  bundan gayrı sensiz paslıdır bu yürek

Anlat ki yüreğim senindir.

Destursuzca gir...', 'Bak gün ağarmaya başladı. Gece sustu,sen sustun Soruları taşıma sabaha Erteleme duygularını, Susma,sustukça Gece uçurum olur,düşer avuçlarım...', ARRAY['Türk Edebiyatı','Şiir','Aygül Ece']::text[], 8.5, '{"poet":"Aygül Ece","poet_slug":"aygul-ece","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cografyam-talan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum 1', 'cocuklugum-1-cenk-aksal-p5f7a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'küçük bir misket..

mutlu ederdi beni,

çoşkuyla koşardım.

ahmet amcanın,

bahçesine,

arkadaşlarımın yanına..

yüzümde hafif tebessüm..

ellerimde,gurur simgem

birkaç kırık misket...

mutluydum...

çocukluğumda/onbir yaşımda..', 'küçük bir misket.. mutlu ederdi beni, çoşkuyla koşardım. ahmet amcanın, bahçesine, arkadaşlarımın yanına.. yüzümde hafif tebessüm.. ellerimd...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cocuklugum-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İvd. Marina', 'i-vd-marina-haydar-zeki-xrob8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'iki  sessiz  harf  arasından...

kısa  ve  hızlı  hareketlerle  kurtarıyorum  kendimi.

yağmur  yağıyor  ıslanıyor  bütün  kapı  önlerim,

-  annem  diyorum, bütün  yönlerim  benim.

iki  sessiz  saat  arasından...

şarap  bardağımı  gece  çatılarına  atarak  kurtarıyorum  kendimi.

hiç  imge  kullanmadan  eksik  bir dizeyi  tamamlıyorum  yani,

-  masal  diyorum,  çelişkiler  barındırmayan  tek  anlatı.

iki  sessiz  gün  arasından...

bir  gece  kimliğimi  kırarak  kırarak  kurtarıyorum  kendimi.

sesimin  olgunluğunca  bakabiliyorum  dün  kapılarıma,

-  aşk  diyorum,  üşüyor  halen  yarına  bakan  çocuklarım.

                                                                                                dip not: 

bu  şiirin  dip notu  için  önceden  kaydettiğim  kaybettiğim

düşlerimi  ve  belki  ilktir  sevgilim  kullanmayacağım

annemim  sesini,  şimdi  elimde  ne  varsa  odur  yazacaklarım.

-  yağmur  yağıyor  ıslanmaya  yüz  tutmuş  üçüncü

hamur  kağıttan  suratım  şimdi  sisler  içindeyken...

istemesemde  kabülümdür  elimde  iki  harf  var

sadece  ikiside  sessiz  ve  ikiside  aynı,  yani  yetecek mi 

ki  yetsin  istiyorum  bu  aşkı  kurtarmaya  ve  kazansınlar

istiyorum...   zor  değil  çünkü  tekrar  sevişmek  şiirselleşmek.

baktığımız  gözlerimiz  içinde  kullandığımız  bütün

sesli  cümleler  adına  anısına,  yaşamımız  içinde.

zaman  sabrın  bütün  sessiz  imgelerini  doğrultmuş   üzerime, 

beni  kendi  küllerim  içinde  sınıyorken  hiç  imge  kullanmadan

uzun  saçlarından  ve  göz  renginden  yüreğime  sızıyor

sevgilimin  kokusu  ve  onu  kaybetme  korkusu,  anlımdaki

yara  iziyle  düz  bir   çizgi  çiziyorum  sevgilimin  koynundaki

geceye  ve  yeni  bir  isim  veriyoruz,  yoruluyor  dillerimiz

yoruldukça  dinginleşiyor  çelişkilerimiz,  olgunlaşıyor  korkularımız.

baktığımız  gözlerimiz  içinde  kullandığımız  bütün

sesli  cümleler  adına  anısına,  yaşamımız  içinde.

günlerdir  bu  kentin  aldığı  yeni  ve  sessiz  renk

bir  şairin  göz  yaşları  ile  tonlanıyorsa  gecede  bu  aşk

yeni  bir  kimlik  kazansın  diyedir  çekilen  bu  sancı,  tüm  olan

biten  tek  bir  kelimede  ve  tek  bir  renkte  buluşsun  diyedir  tekrar.

 - (Barok  tarzı  duruşumla  sesli  bir  harfin okunuşu)    gibi.

ben  aşk  diyorum  o  renge  ve  kadınım  diyorum  o  kelimeye.

baktığımız  gözlerimiz  içinde  kullandığımız  bütün

sesli  cümleler  adına  anısına,  yaşamımız  içinde.

02.10.2004 / 01.04.2005

ınnsbruck', 'iki  sessiz  harf  arasından... kısa  ve  hızlı  hareketlerle  kurtarıyorum  kendimi. yağmur  yağıyor  ıslanıyor  bütün  kapı  önlerim, -  a...', ARRAY['Türk Edebiyatı','Şiir','Haydar Zeki']::text[], 8.5, '{"poet":"Haydar Zeki","poet_slug":"haydar-zeki","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ivd-marina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum 2', 'cocuklugum-2-cenk-aksal-y18v4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'lastik bir top,

almıştı,

birol dayım..

dünyalar benim olmuştu sanki...

mahalleli hep peşimde..

zaman o zaman ya...

lastik olsada top, hak getire

her sabah kapımda beklerdi:

arkadaşlarım..

ben çıkayımda oynayalım diye..

bende az değildim ama..

en güzel kızı alırdım yanıma,

bi yekartop yapardık..

değmeyin keyfime...

mutluydum ya/onbir yaşımda...', 'lastik bir top, almıştı, birol dayım.. dünyalar benim olmuştu sanki... mahalleli hep peşimde.. zaman o zaman ya... lastik olsada top, hak ge...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cocuklugum-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahmet(s.a.v) ''e özlem', 'ahmet-s-a-v-e-ozlem-sair-ahrazi-i1tv6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yoktu bir benzerin elbet,daha bir cüsseliydin,

Onca yüksek tepelerden sen ışırdın bakınca.

Görmedik böylesi nurdan,seneler geldi geçti,

Ne cihan gördü ne toprak,ne de bir başka mevki.

Tattığım aşk bile mahcup,değil ruhum ve şeklim,

Kimde var sendeki cevher,bu nasıl bir şehadet? 

Asrın ismiyle beraber gelen insanlara bak; 

Dünyevi sohbet için söz umuyorlar ki ah’tan,

Bahsi geçmiş nice iblis,çekinir bu günahtan.

Şimdi yoksun..a benim cânım,inandığım Ahmet! 

Belki toprakta yatarsın fakat,aşkınla her yer,

Bembeyaz örtüsü,ufkunda sevinç göz yaşıyla,

Her an imana bürünmüş,gelecek bizi bekler…

* * *', 'Yoktu bir benzerin elbet,daha bir cüsseliydin, Onca yüksek tepelerden sen ışırdın bakınca. Görmedik böylesi nurdan,seneler geldi geçti, Ne c...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ahmet-s-a-v-e-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedenim Türklük,Ruhum İslam', 'bedenim-turkluk-ruhum-i-slam-taner-nisanci-u2fi5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüce Yaratanın kemter kuluyum

Oğuz elde yirmidört, can suyuyum

Sinede, Hakkın aşkıyla doluyum

Bedenim Türklük,Ruhum İslam benim

Türk’e aşıklık var asil kanımda

Mazim şan dolu, kılıcım kınında

Allah’a teslim, imanlı soyumda

Bedenim Türklük,Ruhum İslam benim

Çağlar ötesinden gelen gür sesim

Dünyaya nizam vermek asıl işim

Yoktur,olamaz bana, denk bir eşim

Bedenim Türklük,Ruhum İslam benim

Dost olana Hızır olurum her an

Düşmanıma demem asla, el aman

Ay yıldızım gökte, dilimde Kur’an

Bedenim Türklük,Ruhum İslam benim

Bir garip benim,şükrümü ederim

Ülkümdür daim, zikrini ederim

Kimseden çekinmem,fikrin güderim

Bedenim Türklük,Ruhum İslam benim

04/05/2004', 'Yüce Yaratanın kemter kuluyum Oğuz elde yirmidört, can suyuyum Sinede, Hakkın aşkıyla doluyum Bedenim Türklük,Ruhum İslam benim Türk’e aşıkl...', ARRAY['Türk Edebiyatı','Şiir','Taner Nişancı']::text[], 8.5, '{"poet":"Taner Nişancı","poet_slug":"taner-nisanci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bedenim-turkluk-ruhum-islam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğu Türkistan''a Ağıt', 'dogu-turkistan-a-agit-taner-nisanci-eomf5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Taşmak isterim aşamam bendimi

Eller ne bilsin ki benim derdimi

Yaşasam da bulamam ki kendimi

Can evim yanık can evim yaralı

Sarı Çin Uygur Türk’ünü kıralı

Hani nerede birleşmiş milletler 

Nerede haktan gözüken suretler

Ödenmedi mi o bitmez diyetler

Can evim yanık can evim yaralı

Sarı Çin Uygur Türk’ünü kıralı

Doğu Türkistan diye vatanım var

Çoluk çocuk demeden mezalim var

Unutmam ben, atide hesabım var 

Can evim yanık can evim yaralı

Sarı Çin Uygur Türk’ünü kıralı

Haklı öz hakkını alacak elbet

Bu zulüm payidar olamaz elbet

Aslı Kürşad nesli gelecek elbet 

Can evim yanık can evim yaralı

Sarı Çin Uygur Türk’ünü kıralı

Bir garip benim ağlasın gözlerim

Zalimlere haykırsın hep sözlerim

Derdimi kinimde saklar gizlerim

Can evim yanık can evim yaralı

Sarı Çin Uygur Türk’ünü kıralı

19/09/2004', 'Taşmak isterim aşamam bendimi Eller ne bilsin ki benim derdimi Yaşasam da bulamam ki kendimi Can evim yanık can evim yaralı Sarı Çin Uygur T...', ARRAY['Türk Edebiyatı','Şiir','Taner Nişancı']::text[], 8.5, '{"poet":"Taner Nişancı","poet_slug":"taner-nisanci","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dogu-turkistan-a-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybetmeye Başlama', 'kaybetmeye-baslama-sevilay-emirza-uo885', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaybetmeye başladığın an sonunun geleceğini hayal etmeye dalarsın

Yalvarırsın sonsuz umuda

Yapma diye 

Öyle bir yakarıştır ki yüreğinden kopan

Sesini duymuyorcasına  basarsın çığlığı sessizliğe

Karabasandır geceler o günden sonra

Umutla rahat soluğu beklersin

O gelmese de

İnadın hiç böylesine inat etmemiştir kadere

Yapışmışsındır yakasına ve sarsarsın tüm bedenini zavallıca

Kaçışı yoktur çekeceğin cezanın

Bilirsin ve korkarsın

En çokta bir kez daha kaybedeceğinden

Sabrına seslenirsin sabırla

Dilenirsin gözyaşına belirsizlikte yitmemesi adına

Nankör gülücüğünü saklarsın ardına ve çıkarırsın kandırmak adına

Yanlışı sorgulamazsın ve sarılırsın tüm coşkunla

Sonra sende sarılırsın kendi dünyana

Kendi yalanlarına

Tüm korkulardan korkmamak adına

                                                             18.03.05', 'Kaybetmeye başladığın an sonunun geleceğini hayal etmeye dalarsın Yalvarırsın sonsuz umuda Yapma diye  Öyle bir yakarıştır ki yüreğinden kop...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Emirza']::text[], 8.5, '{"poet":"Sevilay Emirza","poet_slug":"sevilay-emirza","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kaybetmeye-baslama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişkilerim', 'celiskilerim-sevilay-emirza-rqydo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çelişkilerim 

Nasıl bir çelişkiydi, hayata sahip çıkan ben’likler ve ben olmayanlar

Hiç acıyı özlemedim, hiç arkasından ağlamadım oysaki

Nasıl bir sahiplenişlikti peki bu? 

Yaramaz çocuğu uslandırıyor,

İşte en çokta o zaman kızıyorum ona.

İşte en çokta o zaman korkuyorum ondan,

Ama yine de vazgeçemiyorum…

Güneşin canımı acıtması kadar gerçek, benden nefret edişi,

Adımı sayıkladığı kadar yalan, benim sayıklamam,

Biliyorum.

Çelişkilerim, hayatıma sahip çıkan çelişkilerim,

Hiç mi uyumazsınız? 

Hiç mi vazgeçmezsiniz nefes almaktan? 

Hiç mi korkmazsınız benden? 

Zerresi kalmadı mı merhametin? 

Peki ya günahın? .

Anladım ki faydası yok yakarışın

Kabullenmeninse imkanı …

Gitmeyeceksin biliyorum ve biliyorum

Seni seviyorum.

Nedeni de bu değimli zaten yüzsüzlüğünün? 

Ne garip değimli yine seninleyim…

                                                          10-03-2005', 'Çelişkilerim  Nasıl bir çelişkiydi, hayata sahip çıkan ben’likler ve ben olmayanlar Hiç acıyı özlemedim, hiç arkasından ağlamadım oysaki Nas...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Emirza']::text[], 8.5, '{"poet":"Sevilay Emirza","poet_slug":"sevilay-emirza","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/celiskilerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalma Artık Bu Kadar', 'dalma-artik-bu-kadar-sevilay-emirza-sx0xn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Susuz tendedir gözyaşım,

Yıpratmaz sessizliğini,

Elinde beyaz bir papatya,

O da sakin ve narin.

Hiç duydun mu korkunun isyan sesini,

Gördün mü gözlerinde ki nemi

Dalma artık bu kadar,

Faydasızlıklardan vazgeç.

Sevdiğini söyle tüm yüreğinle,

İlk önce kendine

Sonra papatyaya,

Ve sonrada korkularına.

                                                 02-12-2003', 'Susuz tendedir gözyaşım, Yıpratmaz sessizliğini, Elinde beyaz bir papatya, O da sakin ve narin. Hiç duydun mu korkunun isyan sesini, Gördün ...', ARRAY['Türk Edebiyatı','Şiir','Sevilay Emirza']::text[], 8.5, '{"poet":"Sevilay Emirza","poet_slug":"sevilay-emirza","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dalma-artik-bu-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barışla yaşasın her nefes', 'barisla-yasasin-her-nefes-mehmet-yilmaz-bulancakli-ufrq2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Barışı seç dünya,

Kan,gözyaşı bitsin.

Umut olsun yaşamaya,

Kötü günler gitsin.

Barışı seç, akıl''la,

Her şey değerine gelsin.

Felaketler inatlıkla,

İnsan,yaşadıkça sevilsin.

Barışı seç dünya,

Nefes alsın herkes.

Canlar dayanmaz bu acıya,

Barışla yaşasın her nefes.

23.03.2003-Bulancak', 'Barışı seç dünya, Kan,gözyaşı bitsin. Umut olsun yaşamaya, Kötü günler gitsin. Barışı seç, akıl''la, Her şey değerine gelsin. Felaketler inat...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/barisla-yasasin-her-nefes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-memed-ayaz-ok5vz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çevrimin içindeyim.

kimi nereye çevirir, nerden geriye ya da ne taraftan ileriye

bilmem...

bakmamda çevrildiğim ya da çevrilemediğim tarafa

başımın ağırlığından mı, ışığa bakamadığımdan mı, tembelliğimden mi

bilmem...

sen ne bilirsin diye sorarsan eğer

bilmediğimi bildiğimden gayrı, tek bildiğim...

YOKSUN.

(Nisan-2005 Kızıldağ)', 'Çevrimin içindeyim. kimi nereye çevirir, nerden geriye ya da ne taraftan ileriye bilmem... bakmamda çevrildiğim ya da çevrilemediğim tarafa ...', ARRAY['Türk Edebiyatı','Şiir','Memed Ayaz']::text[], 8.5, '{"poet":"Memed Ayaz","poet_slug":"memed-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yoksun-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarmaşık Gülleri', 'sarmasik-gulleri-yavuz-agir-04glu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Samaşık gülleri,

Gelir dolan dolanı.

Yar karşıdan görünür,

Gider salanı salanı...

Giymiş reng reng etekleri

Döner alanı alanı...

Düştüm derin sevdalara,

Gönül ahlanır ahlanır.

Bir öpücük verse bana,

Dudak ballanır ballanır...

Göz görür,gönül sever.

Aşkım dallanır dallanır.

Maziye karışır her şey

Sunam ahlanır ahlanır...', 'Samaşık gülleri, Gelir dolan dolanı. Yar karşıdan görünür, Gider salanı salanı... Giymiş reng reng etekleri Döner alanı alanı... Düştüm deri...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sarmasik-gulleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Tutmuyor Ellerim', 'yine-tutmuyor-ellerim-ahmet-tekin-2-ru0hc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sor her yağmura sor her rüzgara

sen varken beynimde

bir deprem daha olur bende

biraz daha yıkılırım biraz daha

kahretsin yine tutmuyor ellerim

bir ara unuttum sandım seni

koştum güldüm ağladım oynadım

içimde bir çocuk yetiştirdim içimde bir çiçek besledim

arasıra uslu arasıra asi

her evden kaçtığında koştum tren yollarında yağmurda

adım adım her şehirde

ümidimdi sevincimdi baharımdı güneşimdi

sonra her öldüğünde sen geldin aklıma

sen her aklıma geldiğinde o öldü

ve ben biraz daha yıkıldım biraz daha

kahretsin yine tutmuyor ellerim...', 'sor her yağmura sor her rüzgara sen varken beynimde bir deprem daha olur bende biraz daha yıkılırım biraz daha kahretsin yine tutmuyor eller...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tekin 2']::text[], 8.5, '{"poet":"Ahmet Tekin 2","poet_slug":"ahmet-tekin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yine-tutmuyor-ellerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-ahmet-tekin-2-by3yt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'her ne kadar sığnacak yerim olsada

sakınılacak bir hal benimkisi

alem karar vermiş yığma tepe bu kaş çatıklığı

arta kalan arkaya kalan üzüntü dolu bir ev

şerefli bir kıyamet övünmesi

başlangıcı olmayan uykularda baki kalmış bela başıma

bir güvercin yüreğinde umut iklimlerine salınmış aşkım

mühür basmabir fermana k gibi bir şey artık seni sevmek', 'her ne kadar sığnacak yerim olsada sakınılacak bir hal benimkisi alem karar vermiş yığma tepe bu kaş çatıklığı arta kalan arkaya kalan üzünt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tekin 2']::text[], 8.5, '{"poet":"Ahmet Tekin 2","poet_slug":"ahmet-tekin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-sevmek-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Üstüne', 'sevgi-ustune-salih-ozalasan-9n94r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yarılsa gök, yıkılsa üzerime arş''ı alem

Çağ kapansa, heyhat değişse devri alem

Hayat bir nefes, dolsa da  zamansız benim vadem

Gaipten bir ses dese ki, günahkarsın ey beni adem

Günahım sevmek, vazgeçilmez ne yârden ne serden

Suç mu gönül vermek? Vazgeçememek edalı bir yârden

Çıkmadıkça bu tatlı can bu fani bedenden

Yer ile gök birleşse, yok dönüş bende bu sevgiden

Hayatta olmanın anlamı sevmek canı yürekten

Dolsa da vademiz, bir şans daha dileriz felekten

Sevmeden yaşamak bir zulüm, bana bin ölümden

Sevgi semaya uzanan bir direktir her gönülden

Kim/ki seviyorsa, sevgi için fedakarlık ediyorsa özünden

Derdini dert bilip kanlı yaş akıtmışsa iki gözünden

Korkusu olmaz ne er, nede geç gelen ölümden

Sevgi kutsal, ölüm bile silemez onun nurunu yüzünden

Y.Tarihi 05-04-05 Saat 18-30

Salih ÖZALAŞAN', 'Yarılsa gök, yıkılsa üzerime arş''ı alem Çağ kapansa, heyhat değişse devri alem Hayat bir nefes, dolsa da  zamansız benim vadem Gaipten bir s...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevgi-ustune-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Sevdan', 'kara-sevdan-ahmet-tekin-2-048zt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dahasıda var bu aşkın

ama senin limitin doldu

ya yeniden çiz rotaları kandır beni

yada örtbas olsun kara sevdan', 'dahasıda var bu aşkın ama senin limitin doldu ya yeniden çiz rotaları kandır beni yada örtbas olsun kara sevdan...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Tekin 2']::text[], 8.5, '{"poet":"Ahmet Tekin 2","poet_slug":"ahmet-tekin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kara-sevdan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznün Gölgesinde Yağmalanmış Düşlerim', 'huznun-golgesinde-yagmalanmis-duslerim-emine-deniz-fi64q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '_______Anlamsız dokunuşlar peşinde tenim 

_______ Hüznün gölgesinde yağmalanmış düşlerim

Kuruyan tüm damarlarım yeniden canlansın diye 

Vazgeçtim aşktan 

belki yeter bir damlası yağmurun 

Üfle ki soluğunu ey sevgili 

Kopanları birleştirelim en baştan



Ceplerim yırtık 

ve iğne delikleri gözlerim için çok küçük 

yeni giysiler istiyorum,cepleri yırtılmamış 

bütün iğnelerin canı cehenneme... 

ki yüreğinde izi çıksın diye 

yüreğimi koyabilirim ortaya 

parmaklarımı değil...



Ellerim sessiz 

Kelimelerim çaresiz

 Sendelerken dilimde ıslıklarım 

Nasıl dolanabilirim yüreğine 

Yeter mi sevilmek adına 

bildiğim bir kaç kelime

Seni bulduğum gün 

Muhtemelen ölmüş olacağım.. 

Ve beni ne kadar sevdiğini 

 ____asla sorgulamayacağım...', '_______Anlamsız dokunuşlar peşinde tenim  _______ Hüznün gölgesinde yağmalanmış düşlerim Kuruyan tüm damarlarım yeniden canlansın diye  Vazg...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/huznun-golgesinde-yagmalanmis-duslerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Baharlara Küstüm', 'artik-baharlara-kustum-zulfikar-yapar-kaleli-wnbki', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birlikten umudu kestim

Hayallerim boşa çıktı

Artık baharlara küstüm

Tüm zamanlar kışa çıktı

Toy toylarım toynağında

Pınarların kaynağında

Sandım huzur oynağında

Ömür kırk beş yaşa çıktı

Gözlerini yuma, yuma

Kafasını sokar kuma

Kavağa çıkmadı ama

Balık geldi, taşa çıktı

Nutuk atmış, iz sürmüşüm

Aklım sıra ders vermişim

Güpegündüz düş görmüşüm

Güldüklerim başa çıktı.', 'Birlikten umudu kestim Hayallerim boşa çıktı Artık baharlara küstüm Tüm zamanlar kışa çıktı Toy toylarım toynağında Pınarların kaynağında Sa...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/artik-baharlara-kustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Bensiz Olamazdın?', 'hani-bensiz-olamazdin-salih-ozalasan-8gcxu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani bensiz olamazdın? 

Güneş doğmazdı beni görmeden

Bensiz hayatı yaşayamazdın? 

Önemliydim, aldığın her nefesten

Gece olmuşsa, mehtabın ben olmalıydım

Gece başlamazdı beni görmeden

Daima aynı yerde parlayan kutup yıldızıydım

Gözlerini kapamazdın beni görmeden

Hani sende her yol bana çıkardı? 

Ateş böceğiydim sana yol gösteren

Bende seni bağlayan bir giz vardı

Hep karşındaydım baktığın her yönden

Havaydım, suydum, akan terdim tenden

Belli olurdu benliğim, gülümsemenden

Gururlu, sevinçli, başın daima dik

Ölümsüz bir aşk doğmuştu beni özümsemenden

Ben senden bir parçaydım

Ayrılamazdım ölüm olsa da bedenden 

Hani bensiz ölürsen 

Kara toprağa sığmazdın, parçalardın

Kurtarırdın bedenini

Seni bensiz saran kefenden

Hani can çıkardı zamanı geldiğinde

Ama ben asla çıkmazdım o bedenden

Biz bir bedende doğmamıştık

Ama tek beden gibi olmalıydık

Mahşer günü tek beden doğmalıydık

İsrafil Sûr''a üflerken

Mizanda beraber tartılmalıydı

Sevgimiz konmalıydı bir yanına

Günahlarımızı tartan kefe aşağı inerken

Cezamız cehennemse, birlikte yanmalıydık

Bizi sevdamız korurdu kor ateşten

Cennet bahçesi olursa yolumuz

Hani farklı olacaktık biz herkesten

Başımızda sevgiden bir halka olacaktı

Farkımız belirecekti ayan beyan

Cennet''le müjdelenen her Adem''den

İşte bunlar hayatı acı tatlı

Sevgileri için yaşamışlardı

İki ayrı bedende tek canlı

Beraber toprağa konmuşlardı

Çileli iki beni ademdiler

Mahşere kaldı mükafatları

Birlikte acı çektiler

Beraber doğmaktı tanrıya duaları

Issız bir çölde serapmış gördüklerim

Gülün dikeniymiş sen diye öptüklerim

Yağmur yağdı, kayboldu çölde vaha

Belkide bir rüyaymış gördüklerim

Ne sen varsın, ne senden bir haber

Yüreğimde anlatılmaz bir acı

Gülen gözlerimde derin bir keder

Susmuş konuşan dilim

Dökülmez artık kelimeler

Sana sevdasını anlatmaya dilimden

Aynalarda yansımam yok

Ruhum ayrılmış sanki bedenden

Bildiğim, söyleyebildiğim

Sadece cevapsız bir soru

Yoksa hiç hayata gelmedim mi ben? 

Y.Tarihi 03-04-05 Saat 13,30

Salih ÖZALAŞAN', 'Hani bensiz olamazdın?  Güneş doğmazdı beni görmeden Bensiz hayatı yaşayamazdın?  Önemliydim, aldığın her nefesten Gece olmuşsa, mehtabın be...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/hani-bensiz-olamazdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A n n e (Bütün Anneler Güzeldir)', 'a-n-n-e-butun-anneler-guzeldir-zulfikar-yapar-kaleli-tiysr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sensiz bu hayatın tadı tuzu yok                  

Gönül sensiz nasıl yaşıyor anne                  

Koyun meler arkasında kuzu yok                

Seherler sabahı kaşıyor anne                     

                                                                  

Sağ solu bilmezdim, sen idin ışık                

Entarin yorgandı, ayaklar beşik                   

Dünyam allak bullak, karma karışık             

Dualar göklere koşuyor anne                       

Analar sultanı, başların tacı                          

Eğildik kadere, ve lakin acı                          

Ben ki senin her duanın muhtacı                                        

Gönlüm hayalinle ışıyor anne

Güzel annelerin en güzelinden

Güzel duaların en özelinden

Tomurcuk çiçekten, gül gazelinden

Derlediğim selâm üşüyor anne

Bu dünya malına tamah etmemiş

Şüpheliyse haram deyip gitmemiş

Yatağında rahat edip yatmamış

Huyunu erenler taşıyor anne

Yaratana teslim olunca kendi

Ağrısı, sızısı o anda dindi

''Cennet ayağının altında'' idi

Çok gördün yüreğim düşüyor anne', 'Sensiz bu hayatın tadı tuzu yok                   Gönül sensiz nasıl yaşıyor anne                   Koyun meler arkasında kuzu yok          ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/a-n-n-e-butun-anneler-guzeldir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-omer-bolat-j2qjp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eski loş bir oda, ortasında ben

Her bir eşya derdini anlatıyor

Sarı bir ışık sızıyor geriden

Hain dertlerim pusuya yatıyor

Köşelerdeki örümcek ağları

Sanki benim bedenimi bürümüş

Bir tarih gibi eskitmiş çağları

“Hayat, hayat” diye ruhum çürümüş

Duvarlardaki is lekelerinde

Bir tılsım gibi gizlenmiş kaderim

Tıpkı benim gibi siyah renginde

Kaybolup gitmiş, gözlerimde ferim

Saçlarım hayat yolunda süpürge

Git ve gel! Izdırabın ta kendisi

Çile hakikat, sevinçlerse gölge

Ölmüyor, isteklerin efendisi

27 Ocak 2001

ALACA', 'Eski loş bir oda, ortasında ben Her bir eşya derdini anlatıyor Sarı bir ışık sızıyor geriden Hain dertlerim pusuya yatıyor Köşelerdeki örümc...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bolat']::text[], 8.5, '{"poet":"Ömer Bolat","poet_slug":"omer-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hayat-197-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmeyecek Sevgiliye', 'gelmeyecek-sevgiliye-omer-bolat-3gy6i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Belki yanımdasın,

Belki alemin bir ucunda.

Ama bilemezsin sen

Bir sen daha var

Kalbimin başucunda.

Ruhun benimdir artık.

Gelmeyeceksin…

Ama gam yok.

Bil ki, benim yoklukla

Kavgam yok.

Gelmeyeceksin...

Son kez saçlarımı

Okşa ellerinle.

Ve kupkuru bedeninle

Git gideceğin yere…

Mayıs 2004

Maltepe', 'Belki yanımdasın, Belki alemin bir ucunda. Ama bilemezsin sen Bir sen daha var Kalbimin başucunda. Ruhun benimdir artık. Gelmeyeceksin… Ama ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bolat']::text[], 8.5, '{"poet":"Ömer Bolat","poet_slug":"omer-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gelmeyecek-sevgiliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-omer-bolat-war1i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ömür boyu ben onu aradım

Gönlüm bir saliha kadına hasret

Dilime dolandı, çıkaramadım

Dilim onun meçhul adına hasret.

Arz-ı endamıyla ruhumu ezmiş

Rabbim, baştan başa bir sanat çizmiş

Varlığı, alemde bulunmaz gizmiş

Kaldım, onun meçhul tadına hasret…

27 Aralık 2003

ADAPAZARI', 'Bir ömür boyu ben onu aradım Gönlüm bir saliha kadına hasret Dilime dolandı, çıkaramadım Dilim onun meçhul adına hasret. Arz-ı endamıyla ruh...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bolat']::text[], 8.5, '{"poet":"Ömer Bolat","poet_slug":"omer-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hasret-236-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Sen', 've-sen-meral-vurgun-im6li', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'doruklara bak gün batımlarında

dağlarına iner akşam vakitleri 

alnın akı kadar serin ve selin

bakma yorgun tebessümüne

ay sevdalı, ay aşıktır aleme

buseni rüzgarlara bırak 

esip şafak vakitleri

okşasın yüzümde gelincikleri

ölüm gelir yoklar sol yanımı

tan atışları sensiz ışır

donuklaşır us’um

kirpik uçların çiy döker

bitmeyen imgeler dokurum

yarım kalmış şiirlere

ay aşıktır aleme sevgili

ondandır sen kaşını yıkınca

yağmur yağar gözlerime

tüm kırık telleri kanar yüreğimin

kovgunuyum çöl yangını yüreklerin

ellerin sevgili ellerin

ah beni sürgün, beni vurgun eden

beni dokunmadan yakıp kavuran ellerin

ellerinde karanlığı yaran 

kalemin inci nakış dizgileri

ve sen...', 'doruklara bak gün batımlarında dağlarına iner akşam vakitleri  alnın akı kadar serin ve selin bakma yorgun tebessümüne ay sevdalı, ay aşıktı...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ve-sen-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne fark ederki', 'ne-fark-ederki-husamettin-guven-p6zqc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dusun bu isin sonu nereye varacaksa

Tasinamaz dertler beni bulacaksa

Onca dertler benim sonum olcaksa

Yasamisim olmusum ne fark ederki

Cevremdeki insanlar gulup cosarken

Mutluluktan oynayip gobek atarken

Butun derler bana kucak acarken

Yasamisim olmusum ne fark ederki

Istememmi sanki gulup cosmayi

Mutluluga dogru ilk ben kosmayi

Kapattim sayende ben o sayfayi

Yasamisim olmusum ne fark ederki

Hollanda', 'Dusun bu isin sonu nereye varacaksa Tasinamaz dertler beni bulacaksa Onca dertler benim sonum olcaksa Yasamisim olmusum ne fark ederki Cevre...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ne-fark-ederki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birkez Daha', 'birkez-daha-emali-aksoy-b5q8w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aynı ışığı yüzünde gördüğüm o gün; 

Birkez daha çekmiştim bu fotoğrafı.

Hani o gökyüzü,ne çok açıkne çok koyu mavi.

Öğlen olmasına rağmen; 

Güneş çoktan batıya devrilmiş bir sonbahar başı.

Lodos bugün dalgalandırmış denizi,

Onun uzun uçuşan saçlarını dalgalandırdığı gibi.

Güneşin sarısı bir başka yansımış bronz teninde.

Yuvarlak hatlarında kıvrılmış, akmış gitmiş,

Lodostanmıdır nedir? kaşların çatık bu sefer.

Dudağın hafif bükük sağdan yukarı.

Belkide,seni çağırıp poz vermeni istediğim için kızmışsındır bana.

Ama öpücük almadan bırakmam; 

O kalın, kızıl dudaklardan.

Haydi git şimdi,ben dalgaları dinleyeceğim ğözlerimi kapatıp.

Ogün üçtün bugün dört.

Işık aynı ışık, aşk aynı aşk...

Haydi oğlum git; git oyna dalgalarla.', 'Aynı ışığı yüzünde gördüğüm o gün;  Birkez daha çekmiştim bu fotoğrafı. Hani o gökyüzü,ne çok açıkne çok koyu mavi. Öğlen olmasına rağmen;  ...', ARRAY['Türk Edebiyatı','Şiir','Emali Aksoy']::text[], 8.5, '{"poet":"Emali Aksoy","poet_slug":"emali-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/birkez-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemre Düştü', 'cemre-dustu-selahattin-olmez-jnsc3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nazar boncuğu dediler; senin gözlerin,bana

Koştum geldim sana ki,nazar değmesin aşkımıza.

Gözlerinde güller açmış,sanki bir demet gonca,

Koklasam seni delicesine,doyulmaz ki sana ömür boyunca.

Cemre düşmüş gözlerine,alevlenmiş kaşların,

Dudakların kor olmuş,yanıyor yanakların,

Saçlarından dökülen narla,kızıllaşmış şakakların,

İlla da yakıyor beni,İpekleşmiş saçların.zülüflerin tellerin.

Kadife yumuşaklığındaydı,cezp edici sözlerin,

Sanki pırlantadan yapılmış,Sütunlaşmış gerdanın,

Tarifi ne mümkündür,sana olan sevdamın,

Bana gereği yok,İçinde sen olmayan dünyanın.

Sanki yanar dağ gibisin,lavların yakıyor beni,

Ekvator rüzgarı gibi,İçimde hissederim nefesini,

Yanaklarında kor kırmızı açan,Gülden güzel gamzeni,

Sen yoksan içinde eğer,İstemem dünyanın hiçbir yerini.

Ben sana sevdalıyım tutmak istiyorum ellerini,

Sevmek istiyorum seni,seni sen yapan benliğini,

Al ömrümü senin olsun,sensiz yoktur gereği,

Sensizlik yakıyor işte,Cemre gibi düştüğü her bir yeri.

Cemre düştü kalbimize,cemre düştü sevdamızın üstüne,

Kor,kor oldu alevlendi sevgimiz,benzedi gül bahçesine,

Katre,katre karanfiller açtı,sevdalandık ölürcesine,

Bir yıl değil,bin yıl değil,Sevgimiz sürecek ömür sürdükçe…', 'Nazar boncuğu dediler; senin gözlerin,bana Koştum geldim sana ki,nazar değmesin aşkımıza. Gözlerinde güller açmış,sanki bir demet gonca, Kok...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Ölmez']::text[], 8.5, '{"poet":"Selahattin Ölmez","poet_slug":"selahattin-olmez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cemre-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lanet olsun sahte ask ve asiklara', 'lanet-olsun-sahte-ask-ve-asiklara-husamettin-guven-4lu1s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eskidenmiş sevipde mutlu olmak

Sağlam temeller üzerine yuvayı kurmak

Acılı tatlılı hayatı paylaşmak

Lanet olsun sahte aşk ve aşıklara

Sıkıldım vallahi yalan dünyadan

Eşten dostan sahtekarlardan

Yalanla dolanla sürdürülen aşktan

Lanet olsun sahte aşk ve aşıklara

Seviyormuş gibi görünenlerden

Fırsatını bulsa öldürenlerden

En acısı düşmanı güldürenlerden

Lanet olsun sahte aşk ve aşıklardan

Hollanda', 'Eskidenmiş sevipde mutlu olmak Sağlam temeller üzerine yuvayı kurmak Acılı tatlılı hayatı paylaşmak Lanet olsun sahte aşk ve aşıklara Sıkıld...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/lanet-olsun-sahte-ask-ve-asiklara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim ..Böyle öldürme..', 'kalbim-boyle-oldurme-mehmet-can-ejhpr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalbim ..Böyle öldürme..

Sana dargınım bu gün..

Dinlemedin beni, hiçbir zaman…

Olmazları istedin hep..yeniden..

Uslanmadın..

İstedin..

Kalbim..

Sana dargınım bu gün..

Boşuna çarpıyorsun..

Çarpma dedim..

Durursun..

Kalbim..yapma..

Durursun…

Tatlı bir bakışa aldandın yine..

İlk baharda değiliz..

Mevsim..sonbahar….

Kış gelecek..ardından..

Yapma kalbim..

Ne olursun..

Yapma sonra.. 

Durursun…

Ne verecek duygu kaldı..

Ne soracak soru kaldı..

Gülümsemeye dudakta,

 Güçmü kaldı? 

Hala bakarsın ardından..

Nemli gözlerle..

Özlemlerle..

Hatıralarla 

Umutlarla 

Yapma dedim sana..

Kızıdırma beni..

Öldürme beni..

Böyle öldürme..

Böyle öldürme..', 'Kalbim ..Böyle öldürme.. Sana dargınım bu gün.. Dinlemedin beni, hiçbir zaman… Olmazları istedin hep..yeniden.. Uslanmadın.. İstedin.. Kalbi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Can']::text[], 8.5, '{"poet":"Mehmet Can","poet_slug":"mehmet-can","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kalbim-boyle-oldurme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykunun Kumsalları', 'uykunun-kumsallari-hatice-bediroglu-rb2o3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Lacivert gökyüzünde

Milyonlarca yıldız

Oynaşıyor bu gece

Hadi bir tanem

Kelimelerim beyninde

Ellerim bedenin de kalsın

Böylece

Git yat yatağına

Hiçbir şey düşünme! 

Seni

Usul usul severken

Bir tüy hafifliğinde

Parmak uçlarımdan

Akıtırken sana sevdamı

Sonsuz şefkatimi

Okşarken yüzünü, saçlarını

Uyu bir tanem uyu

Ben yanındayım diye

Fısıldayacağım kulağın

Yüzüne…

Bir gülümseme yerleşecek

Sevmenin ve sevilmenin

Güvenli gülümsemesi

Aydınlatacak oday

Beynin, sadece,

Koşulsuz sevgimin

Tınılarını algılarken

Yanağına konduracağım

Yumuşacık bir öpücük 

İyice gevşemiş

Yorgun, hasta bedenini

Hızla çekip götürecek

Dalga dalga vuran

Uykunun kumsallarına

Ben...

Kulağım  soluklarında

Aydınlık yüzündeki! 

Kıpırtıları

Kazırken beynime

Sevginin hazzı

Iğıl ığıl eritirken içimi

Göz kapaklarıma

Mandallar takacağım

www.haticebediroglu.net

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005', 'Lacivert gökyüzünde Milyonlarca yıldız Oynaşıyor bu gece Hadi bir tanem Kelimelerim beyninde Ellerim bedenin de kalsın Böylece Git yat yatağ...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/uykunun-kumsallari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Danışma..''''.HÖFTUR ''''', 'danisma-hoftur-galip-kemali-gunay-f41s7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '..Allah Allah

Kardeşim HÖFTUR burası

Tamam

Biletin doğru, ne dönüşü

Biz 

Yalnız ve yalnıza

Gidiş satarız...

Lütfen 

Sıradaki...

Biz 

Yalnız ve yalnız', '..Allah Allah Kardeşim HÖFTUR burası Tamam Biletin doğru, ne dönüşü Biz  Yalnız ve yalnıza Gidiş satarız... Lütfen  Sıradaki... Biz  Yalnız ...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/danisma-hoftur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maşallah Kriz Üretim Merkezi!', 'masallah-kriz-uretim-merkezi-kadir-soyturk-4almj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir adım ileri, bin adım geri...

Ne gam, ilk  500 de yok imiş yeri; 

Sorarım var mı bir üniversite

Kriz üretmede bizden ileri?', 'Bir adım ileri, bin adım geri... Ne gam, ilk  500 de yok imiş yeri;  Sorarım var mı bir üniversite Kriz üretmede bizden ileri?...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/masallah-kriz-uretim-merkezi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken.', 'giderken-galip-kemali-gunay-5ws8p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Omzuna dokunmadan önce

Yalnız iken şehirde 

Yani

Sevmenden önce

Bana senden. ben gibi, birşey söyle..

Söyle ki aşkım 

İşlesin içime, sana dokunduğum için değil..ayrıldığımıza hiç değil

Bana senden çok güzel 

Birşey söyle.

Dayalı ise başım cama 

Bakamıyorsam sana

Bana senden ben gibi.ama senden az güzel 

Birşey söyle', 'Omzuna dokunmadan önce Yalnız iken şehirde  Yani Sevmenden önce Bana senden. ben gibi, birşey söyle.. Söyle ki aşkım  İşlesin içime, sana do...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/giderken-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey İstanbul', 'ey-i-stanbul-i-lknur-cekici-alpvv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstanbul''u anlatmaya

Yeter mi? dizeler bilmem

Her yerini gezerken

Bu rüyayı tatmak gerek

Eminönün de balık ekmek

Turşu suyu içmek gerek

Tarabya,Bebek,Üsküdarı

Doyasıya gezmek gerek

Boğazın sessiz maviliklerini

Bir tekneyle aşmak gerek

Rüyalarımın şehri

Ne güzel doğar güneşin

Bir başka güzel her bir yerin

Seni sevmek için

Adım adım seninle

Bu duyguya varmak gerek

Salkım salkım bulutların

Gölgesinde kalsan bile

İnsanların yüreğine 

Doğarsın her an güneş diye

Gölgeleyemez hiçbir şey

Gözümü alan renklerini

Silemez hiçbir zaman

O bendeki izlerini

                           (06.04.2005)', 'İstanbul''u anlatmaya Yeter mi? dizeler bilmem Her yerini gezerken Bu rüyayı tatmak gerek Eminönün de balık ekmek Turşu suyu içmek gerek Tara...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ey-istanbul-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim kadın kim?', 'sevdigim-kadin-kim-adnan-mehmet-tufekci-vt343', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdiğim kadından vazgeçmek kolay değil. 

Sevdiğim kadın kim,

Sevdiğim kadın sen misin? 

Ya hayal kırıklığı yaşatan, kızdıran ve yaralayan kadın... 

Benim tanıdığım ve aşık olduğum sen ve şu an ki sen,

Niçin biri için dünyaları vermeye hazırken, diğerinden korkuyorum?

Sevdiğim kadın mı olunacak, yoksa sevdiğim kadın kendi mi olacak? 

Kendisi olduğunda, aslında sevdiğim kadın mı olacak? 

Gördüğüm kabusu tekrar görecek miyim? 

O kabusu silebilecek miyim? 

Neye inanmam gerekiyor, gördüklerime mi, yoksa göreceklerime mi? 

Hala bir mücadele için elimde neler kaldı ki. 

Gözlerimi kapattığımda, düşüncelerim  sadece bana acıları getiriyor.

Kızgınlık ve acılar duygularımı  görmeme engel mi oluyor? 

Bir ütopyamıydı inandıklarım, boşa mı gitti yıllarım? 

Biri uyandıracak ve terlemişsin, kötü rüyalar görmüşsün diye mi sarılacak.

Ne yapmam gerekiyor? Ne düşünmem, ne hissetmem...

Tek bildiğim, O’ nu çok sevdim ve inandım. 

Çok şey almasam da sevgi adına,  Onsuz olamazdım. 

Sadece sevdim, sevdim ve sevdim. 

O muhteşemdi, 

Oğlumun sorduğu soru gibi, 

var mıydı gerçek hayatta öyle biri?', 'Sevdiğim kadından vazgeçmek kolay değil.  Sevdiğim kadın kim, Sevdiğim kadın sen misin?  Ya hayal kırıklığı yaşatan, kızdıran ve yaralayan k...', ARRAY['Türk Edebiyatı','Şiir','Adnan Mehmet Tüfekci']::text[], 8.5, '{"poet":"Adnan Mehmet Tüfekci","poet_slug":"adnan-mehmet-tufekci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sevdigim-kadin-kim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaktaki Sesler', 'sokaktaki-sesler-ensar-cevval-yv0g5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana bir çocukluk verin 

İçinde yoksulluk olmayan

Bir  pantolon ve gömleği olan

Bir zenginlik verin

Boş alanlar bırakın

Gözlerimle resimler çizeyim

Bitmeyen renklerle; 

Şarkılar söyleyeyim

Dudağımda raks eden kelimelerle

Yemyeşil çimenlerde koşturayım

Gökyüzünde salınan uçurtmamın ardından

Sarı yaprakları avuçlayayım

Sonra beyaz karları

Bana bir çocukluk verin

İçinde yalnızlık olmayan

Ana,baba ve kardeşlerden oluşan

Bir zenginlik verin.

Bana bir çocukluk verin

Mavi gökyüzü,yeşil çimenler

Şırıl şırıl akan dereler olsun

Tüm hayalim bu,gerisi sizin olsun.

Sirkeci 10,02,2004', 'Bana bir çocukluk verin  İçinde yoksulluk olmayan Bir  pantolon ve gömleği olan Bir zenginlik verin Boş alanlar bırakın Gözlerimle resimler ...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sokaktaki-sesler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Enişteler Öper', 'enisteler-oper-ekrem-sama-jhib5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her gün yeni bir olay, eskisinden beter,

Beyni olanı terletiyor, buram buram...

Beyinsizler zevk denizinde batar,

Enişteler sırada ya, her gün bayram.

(İstanbul:02.04.2005)', 'Her gün yeni bir olay, eskisinden beter, Beyni olanı terletiyor, buram buram... Beyinsizler zevk denizinde batar, Enişteler sırada ya, her g...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Şama']::text[], 8.5, '{"poet":"Ekrem Şama","poet_slug":"ekrem-sama","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/enisteler-oper-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak Ülkenin Çocukları...', 'yasak-ulkenin-cocuklari-ugur-deniz-ulkegul-e1b6g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir de tetik düşüren ellerinizden

Ekmek yiyen çocukların bakışları...

Ve siyaha boyadığınız gecenizden

Dul kalan kadınların çığlıkları

Dokunur yüreğime...

Terk ettiğimiz gün,

Özlemle baktık

Geride bıraktıklarımıza...

Anamızın gözlerinde ki yaşı

Yarimizin ardımızdan bakışı

Sessizce yüklendi omuzlarımıza....

Sizin öfkenize inat

Sevdalandık umuda, dirence...

Korkuları yendik önce

Belayı dost edindik kendimizce...

Aklanırken insanlık onurumuz

Tek suçumuz

Karşı çıkmaktı

Emperyalizminize

Kapital düşlerinize

Sırnaşık gülüşlerinize...

Sürülmeyi seçtik yurdumuzdan

Belki de vurulmayı namertçe

Kuytu bir sokak köşesinde, sırtımızdan...

Biz bulutu seviyorduk,

Bir de gökyüzüne bakmayı...

Arada bir yar bakışı düşerdi

O yar bakışı deşerdi içimizi...

Seviyorduk işte,

Dalıp giden gözlerle bir sigara yakmayı...

Zindanlarınız bizi bekliyordu

Konuşamıyorduk kimi zaman

Mektup göndermek yasaktı

Türkü söylemek serbest...

Susuyorduk kimi zaman,

Ağlayan bir çocuğun başını okşamak,

Elini öpmek bir ihtiyarın,

Kısacası düne prangalı bir yarın,

Yasaktı...

Yoksul olmak serbest bırakılmıştı

Yırtık ayakkabılarla okula gitmek,

Karın tokluğuna çalışmak,

Ve şükretmek bu günkü nevaleye,

Yarının yokluğuna alışmak...

Sokaklarda sevişmeye

Özgürlük diyordunuz siz...

Parasıyla aşk satın alıyordu,

Soysuz kimlikleriniz...

Çok meşhurdu efendim çok,

Megaloman bar sohbetleriniz...

Susuyorduk kimi zaman

Düşünmek yasaktı

Tuvalete gitmek serbest...

Yazı yazmak yasaktı cama

Yarıda kesip çay sohbetini

Dinlemek yağmurun sesini, serbest...

İşten atılmak yasak değildi,

Genç kız olup satılmak...

Baklava aşırmak büyük yasaktı,

Çocuk olmak zor sanat....

Fişlenmek serbestti,

Hayatın içinde kadın olmak

Sonra hayat kadını diye anılıp

İşlenmek tutanaklara...

Dışarda olmak serbestti,

Mutlu görünmek ama kan ağlamak..

Oysa yasaktı içerde kaybolmak,

Sayım vakti izin yoktu hastalıklara...

Müdür beyin talimatıydı,

İkinci bir emre kadar,

Men cezası verilmişti mikroplara...

Sevişmek alabildiğine serbestti,

Yaş sınırı yoktu otel odalarında...

Uyuşturucu yasaktı,

Ama ölmek serbestti,eroin komalarında...

Polis olmak serbestti,

Ama patron olmak daha serbestti

Viskinin tadına varırken,

Ayrıcalıklı Mason Localarında....

Sürülmeyi seçtik yurdumuzdan

Yada içerde yorgun düşmeyi

Yönsüz ve mesafesiz voltalarımızdan...

Şimdi yağmuru seyrediyoruz

Bir de sessizce akan göz yaşlarını

Kadınımızdan, çocuğumuzdan...

Yeniden başladık...

Sevdik seni ülkem, çok sevdik

Ve vazgeçmedik Onurumuzdan.........', 'Bir de tetik düşüren ellerinizden Ekmek yiyen çocukların bakışları... Ve siyaha boyadığınız gecenizden Dul kalan kadınların çığlıkları Dokun...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/yasak-ulkenin-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yardım Ellerini Uzat Bana', 'yardim-ellerini-uzat-bana-kerem-alay-35u9l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İki ellim gitmez oldu yüzümden

Ah ettikçe yaşlar gelir gözümden

Bu sözleri söylüyorum özümden

Yardım ellerini uzat bana.....

   Gönlüm seni görmek ister gittiğim yerde

   O tatlı sözlerin şifa bendeki derde

   Bir eş sevdası var gönlümde serde

   Yardım ellerini uzat bana.....

Saçlarım ağardı kaşlarım kara

İçimde açıldı bir derin yara

Halim pek Perişan düşün beni ara

Yardım ellerini uzat bana.....

   Bağımda bahçemde soğuk sular akardı

   Sağlam bir aile bulsam evimize bakardı

   Yemeğimi yapar ateşimi yakardı

   Yardım ellerini uzat bana.....

Bilmem kaderim mi bilmem ki noldu

Bağım bahçem kurudu sarardı soldu

Dostlarım ağladı düşmanlar güldü

Yardım ellerini uzat bana.....

   Yarvarsam kadere yardım edmezmi? 

   Nedir bu çektiğim derdim yetmezmi? 

   Bu gördüğüm kara günler bitmezmi? 

   Yardım ellerini uzat bana.....

                   06.04.2005

                   Kerem Alay

                     Van', 'İki ellim gitmez oldu yüzümden Ah ettikçe yaşlar gelir gözümden Bu sözleri söylüyorum özümden Yardım ellerini uzat bana.....    Gönlüm seni ...', ARRAY['Türk Edebiyatı','Şiir','Kerem Alay']::text[], 8.5, '{"poet":"Kerem Alay","poet_slug":"kerem-alay","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yardim-ellerini-uzat-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Millet-i Sadıka ve Ermeni Tehciri', 'millet-i-sadika-ve-ermeni-tehciri-mustafa-angin-nqyqh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Millet-i Sadıka (Ermeniler)    ve 24 Nisan 1915 Ermeni Tehciri*

Fatih Sultan Mehmed Han, İstanbul’u fethettikten sonra, Rum’lara olduğu gibi Ermeniler’e de dillerinde ve dinlerinde tam bir serbestlik tanımıştır. Bu imtiyazların doğal bir sonucu olarak Anadolu’nun muhtelif kesimlerinde yaşayan Ermeniler, yoğun bir şekilde İstanbul bölgesinde toplanmış ve Türkler’le kısa bir sürede kaynaşarak, iş ve sanat hayatını geliştirmek suretiyle refah içinde rahat bir hayat sürmeye başlamışlardır. Bu devirde, bunlara “Hıristiyan Türkler” veya “ Tebaayı Sadıka /Millet-i Sadıka” denilmesinin sebebi, huzur ve güvenlik içinde yaşayan Ermeniler’in bu hoşgörülerden yararlanarak Türkler’le kaynaşmış olmalarındandır.

Ermeniler, önceleri Osmanlı’nın barışsever ve sevilen tebaları idiler. İki millet arasındaki düşmanlığı, dini sebeplere yormak, çok yaygın bir düşünce olmakla beraber, tamamen yanlıştır. Dokunulmadığı taktirde Türkler, başka dinde bulunanlara dünyanın en hoşgörülü insanlarıdır. İki ırk arasındaki düşmanlık, tamamen siyasi sebeplere dayanır. 

“Millet-i Sadıka” olarak yaşayan Ermeniler, yabancı teşvik ve tahrikleriyle Balkanlarda başlayan bağımsızlık hareketlerinden de esinlenerek özellikle din adamlarının yönetiminde örgütlenmeye ve seslerini yükseltmeye başlamışlardır. Özellikle Rusya’dan çeşitli kimliklerle gelen Rus kışkırtıcıların çabalarıyla saldırgan tutumlar baş göstermeye başlamıştır. Bazı Ermeni din adamları Kilislerde ellerindeki silahları gösterip “Türkler ancak bunlardan anlar, gerekirse öküzünüzü satın, silahlanın” diyecek kadar bozgunculuk çağrıları yapmışlardır.

Özetle ifade etmek gerekirse, 1800’lü yıların sonlarına doğru kıpırdanışlar başlamıştı. Bunun başlıca sebebi ise, İngiltere ve Rusya arasındaki menfaat çekişmesi (nüfuz)    mücadelesidir. Çarlık Rusya’nın büyük bir devlet olarak ortaya çıkmasından sonra gerek Balkanlarda yürütülen Pan-İslavizm ve gerekse Boğazlar yoluyla sıcak denizlere ulaşmayı amaçlayan Rusya karşısında Hint Yolu’nu güvence altına almak düşüncesiyle İngiltere’nin, 1878 savaşından sonra yıkılacak İmparatorluğun enkazından pay koparma hesaplarıdır.

İngiltere ve Rusya’nın ortak kararı ile Ayastafanos ve Berlin anlaşmalarında ilk defa uluslar arası platformda Ermeni meselesini gündeme getirmişler ve vaadlerin yerine getirilmesini Osmanlı Devleti’nden talep etmişlerdir. Berlin Antlaşmasının 61. maddesi gereğince İngiltere Osmanlıdan, Ermeniler’in yaşadıkları vilayetlerin yerlerinin gereği olarak ihtiyaç duydukları düzenlemeyi zaman geçirmeden yapmayı ve diğer unsurlara karşı Eremeniler’in güvenliğini sağlanmasını ve bu taleplerinin süratle yerine getirilmesini istemiştir.  İngiltere’nin amacı, işaret edildiği gibi Anadolu’nun doğusunda kendine sadık bir Ermenistan Devleti’nin kurulmasına imkan sağlamak ve böylece Rusların sıcak denizlere ulaşmasını önleyerek İngiltere’nin İmparatorluk Yolu’nu tehdit etmesine mani olmaktı. Bu tez “Sizin (Ermenilerin)    işleriniz beni ilgilendirmez. İngiltere Hükümeti çıkarlarınızı korumayı üstlenmiştir. Siz İngiltere Hükümetine başvurun” diyen Rus Çarı’nın sözüyle doğrulanmaktadır.

Osmanlı Devleti’nden pay koparmak isteyen sözüm ona büyük devletler gibi Ermeniler’de kendi emellerinin tahakkuku için ufukta görülen “Pay kapma” olayının asıl unsuru olmuşlardır. Ülkemizde mutlu, rahat bir durumda yaşayan, servet üzerine kazanan, Osmanlı’ya asker dahi vermeyen, okulları serbest olan ve okullarında milli tarihlerini okutan ve gençlerine sürekli Türk düşmanlığı aşılayan hain Ermeniler, bir ortak hareket içinde birleşerek milli komiteler kurup; adını “Hayır Cemiyetleri”, “Armenikan Komitesi”, Hınçak Komitesi”, “Taşnak Komitesi” koydukları bu cemiyet ve komitelerin besledikleri katil ve vatan hainleri ile cephe gerisinde isyanlar çıkartarak Osmanlı’yı sırtından vurmuşlar, savunmasız çocuk ve kadınlarımızı katletmişlerdir.

1914’te Anadolu’nun doğu cephesine Ruslar, güney cephesine Fransızlar, işgal ordularıyla gelip oturmuşlardır. İşte bu iğrenç işgal sırasında, Rus ordusunun yapmadığını, Hınça ve Taşnak Komitaları yaptı: Rus askeri kıyafetleri girmiş Ermeni ihtilalcileri, Türk ordusunun büyük bir kısmının  Sarıkamış harekatında, 250 bine yakınının da Çanakkale’de şehit olması ve bunun yanında Yemen, Süveyş, Suriye cephelerinin savunmasına giden askerlerin evlerinin korumazsızlığı düşünülürse, Avrupa emperyalizminin Ermenileri niçin kullandıkları kolayca anlaşılabilir. 

I. Dünya Savaşı’nda doğuda Ruslarla savaşırken, cephe gerisini sağlama almak için, bir tedbir olarak Ermeni uyruklarından bir kısmını zorunlu göçe (tehçire)    tutması amacıyla çıkartılan 1915 Tehcir Kararnamesi ahlak, siyasi ve haklı bir metindir. Bunu incelemeyenler, susmalıdırlar. 

1915 yılında tehcir edilen ve savaş sonunda Türkiye sınırları dışında kalan Ermeniler, göç ettikleri ülkelerde kamuoylarını soykırımı yapıldığı iddiaları ile şartlandırıp, tehcir olayının 50. yılına gelen 1965 yılında 24 Nisan 1915’i “Ermeni Soy Kırım Günü” olarak ilan ettiler ve sonrasında da intikam ve kanlı eylem safhasına geçtiler. İlk eylemlerini 27 Ocak 1973 yılında Los Angeles başkonsolumuz Mehmet Baydar ve yardımcısı Bahadır Demir’i şehit ederek başlattılar. Ermeni katil Gourgen Yanikyan daha önceden hazırlamış olduğu 118 sayfalık mektubunu “California Courer” gazetesine göndererek, Ermeni gençlere “Türk temsilcilerinin öldürülmesini ve her yerde Ermeni Sorunu’nun gündemde tutulmasını vasiyet etmiştir. Bundan sonra 1984 yılana kadar dış temsilciliklerde 28 diplomat ve görevlimiz Emeni terörünün kurbanı olmuştur.  

Tüm bunlar yaşanmışken, Ermenilerle bin yıldan fazla bir zamandır yan yana yaşayan Türk halkına iftira edenler, doğru olanlar apaçık oraya çıktığında, bir gün mutlaka utanacaklardır.

20 Ocak 2001 tarihli Milliyet gazetesinde yayımlanan Pierre Loti’nin şu sözlerini dikkatle okuyunuz lütfen. Pierre Loti, Ocak 1919 tarihinde biz Türler ve Ermeniler şu sözü kullanmıştır:

“Hayatım boyunca söyledim ki, Türkler, bütün Doğunun en sağlam, en dürüst insanları ve ayrıca hoşgörüsüzlüğün kendisi olan Ortadokslardan yüz kere daha fazla hoşgörülüdürler.

Biz Fransızlar’ın, Saint-Barhelemy katliamımız var. İspanya’nın engizisyon ayıbı var. Vahşice Yahudiler’i katlettiler ve ülkelerinden attılar. Onlar da Osmanlı’ya sığındılar ve orda büyük bir hoşgörü ile karşılandılar. Birer sadık Osmanlı vatandaşı oldular.

Türkiye’deki Ermeniler’i neredeyse bir meyvenin içinde ve onu kemiren kurtlara benzetmeye cesaret edeceğim.

1896 Van İsyanı ve Osmanlı Bankası Baskını olaylarını Türklerin üzerine yıkmadan önce Ermeni Devrimci Partisi’nin, nasıl bir vahşilikle saldırılar unutmamak gerekir.”

24 Nisan 2005 sözüm ona “Ermeni Soykırım Günü” nün 90. yılı olacak ve halen Ermeni lobileri bu tarihi Ermeni soykırım günü olarak tescil ettirme çabası içindeler ve bizler ne tepki veriyoruz. 

Bugün yurtdışında gerçekten haklı yerlere gelmiş bilim adamlarımız LÜTFEN SUSMAYINIZ. Ermeni’lerin yaptıkları vahşetleri, belgeleri ile tüm dünya milletlerine kabul ettiriniz ve Ermenileri UTANDIRINIZ. 

Ve gençler sizlere sesleniyorum. “Azınlık Meselesi Yok, Türk Düşmanlığı var…” Unutmayın ki sizler; 

Helâl olsun diyerek emdikleriniz:

Süt vermedim ağzınıza besmelesiz.

Mahzun kalmasın diyerek nefisleriniz:

Türlü nimetlerden kurdum soframı.

Bir tuttum evimle vatanımın mahremiyetini.

Kale bedenlerine eş; kirli emellere kapımı.

Kararmasın diyerek âlem içinde yüzünüz:

İffet verdim kızlarıma, oğullarıma namus.

Diyen iffetli anaların yiğit evlatlarısınız ve nasıl ki sıcak savaşlarda kahramanlıklar gösterdi iseniz soğuk savaşın diploması kahramanları da yine siz evlatlarımızdan çıkacaktır. 

Allah ülkemizi ve milletimizi bu canilerden ve onlara kucak açan sözüm ona batılı kalkınmış ve medeni! bilinen ülkelerin saldırılarından emin kılsın.

Mustafa ANGIN

Makine Mühendisi

Kaynakça:

*   Aydınlar Ocağı Dergisi’nin “Ermeni Sorunu” konulu 13. sayısından derlenmiştir.

** Merhum Araştırmacı Yazar A.Kadir Angın’ın “Gökler Destanı” adlı eserinden alınmıştır.', 'Millet-i Sadıka (Ermeniler)    ve 24 Nisan 1915 Ermeni Tehciri* Fatih Sultan Mehmed Han, İstanbul’u fethettikten sonra, Rum’lara olduğu gibi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Angın']::text[], 8.5, '{"poet":"Mustafa Angın","poet_slug":"mustafa-angin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/millet-i-sadika-ve-ermeni-tehciri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onun İçin Yandığını Bilmesin', 'onun-i-cin-yandigini-bilmesin-murat-demir-5zfbl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Deli gönül öne çıkma derdinle

İsyanını özelinde tut, dinle

İçten içe savaşsanda kendinle

Onun için olduğunu bilmesin

Hançer alıp yüreğini deşsende

Yaprak yaprak dallarından düşsende

Sus, söyleme ateşlerde pişsende

Onun için yandığını bilmesin

Fark ettirme geçmezsede gün, gece

Bitti sansın dilinde ki o hece

Sürünsende, buralarda ömrünce

Onun için kaldığını bilmesin

Şu alemde tek sen naçar kalsanda

Bedeninden canı dışa salsanda

Derin derin hayallere dalsanda

Onun için daldığını bilmesin

Birgün değil her an aşkla anarak

Sıcağının soğuğunda donarak

Tenhalarda ağlayarak, yanarak

Onun için öldüğünu bilmesin!', 'Deli gönül öne çıkma derdinle İsyanını özelinde tut, dinle İçten içe savaşsanda kendinle Onun için olduğunu bilmesin Hançer alıp yüreğini de...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/onun-icin-yandigini-bilmesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyamam', 'kiyamam-huseyin-sigirtmac-7d6fd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gam efkara of demedi yüreğim.

Hasret beni, ben hasreti yenemem.

Yare ulaşmaktı arzum, ereğim.

Yoruldum yollarda artık gidemem.

Gönlümün cananı çok uzaklarda.

Duygum isyan eder can tuzaklarda.

Başın aldı gitti yar yıldızlarda.

Hayal, düşte bile artık göremem.

Gönlümün tahtına girer güzeller.

Varıp her hücreye adın yazarlar.

Duygumdan oluşur nice radarlar.

Kesilir bağlantı haber veremem.

Her hücrem bir deniz, yüreğim derya.

Damarımda kanım çağlıyor sevda.

Sığırtmaç ok oldu gerilmiş yayda.

Hedefim yar ama ona kıyamam.', 'Gam efkara of demedi yüreğim. Hasret beni, ben hasreti yenemem. Yare ulaşmaktı arzum, ereğim. Yoruldum yollarda artık gidemem. Gönlümün cana...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kiyamam-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zafer''e', 'zafer-e-ziya-nizam-cbk50', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Heey.Kalk.

Kalksana yahu.

Bir tek sen kalmadın mı

Bana sabahlara kadar katlanan? 

Ne uykusudur bu.

Bak camdan dışarı

Burada yağan yağmuru göreceksin.

Ne yani; 

Mesafeler var aramızda diye

Aynı anı yaşayamayacak mıyız sandın? 

Bir yudum daha çektim dostluğunu.

Hadi şerefine.

			07.10.2004-Çarşamba

			00:33 Avcılar', 'Heey.Kalk. Kalksana yahu. Bir tek sen kalmadın mı Bana sabahlara kadar katlanan?  Ne uykusudur bu. Bak camdan dışarı Burada yağan yağmuru gö...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zafer-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir mum yanıyor çok uzaklarda', 'bir-mum-yaniyor-cok-uzaklarda-ziya-nizam-ko61r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zafer’e	

Bir mum yanıyor çok uzaklarda

Ateşi düşüyor ciğerimin ortasına

Küllenen bir aşkı anlatıyor soluk alevi.

Yalnızlığı tarif ediyor sanki.

Mum yalnız,mum kimsesiz.

Dibinde bir çiçek,

Gururlu ve soğuk.

Yetmiyor alevi aydınlatmaya.

Bir sonbahar yağmuru başlıyor,

Soluyor mumun alevi.

Gömülüyor yalnızlığı karanlığa.

Karanlık alıyor çiçeklerin en gizemlisini.

Karanlık alıyor çiğdemleri.

Bomboş bir yalnızlık kalıyor sadece.

			15.11.2004-Pazartesi

			21:14 Çayeli Rize', 'Zafer’e	 Bir mum yanıyor çok uzaklarda Ateşi düşüyor ciğerimin ortasına Küllenen bir aşkı anlatıyor soluk alevi. Yalnızlığı tarif ediyor san...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-mum-yaniyor-cok-uzaklarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-taha-karakoc-iktno', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Serin bir ilk bahar sabahında

Matemli doğa güneşle 

İçime doğmuştu gideceğin

Sebebini bilmediğim

Yanlızlığımla boğuşurken

Ardından gitme 

Diyemedim

Gidişin bir hançer gibi saplandı yüreğime

Ben sana ağlıyordum

Yüreğime saplanan hançer seni yaralamıştı

Yüreğimde sadece sen vardın

Sende gidersen

Benden geriye ne kalır

Artık seni küskün karamsar sayıfalara

Kırık bir kalemle yazacağım

Sensiz batan güneşe

Küskün veda edeceğim

Doğan güneşten seni dileyeceğim

Oysa güneşim gözlerinde saklıydı

Şimdi gözlerinde yok

Üşüyorum

Sen gülmeyen yüzümde

Tatlı bir tebesümdün

Gelmeyen baharımda

Yüreğimde açan kardelen

Şimdi sende yoksun

Haytımın anlamıda

Giderken ruhumuda al götür

04/06/2005', 'Serin bir ilk bahar sabahında Matemli doğa güneşle  İçime doğmuştu gideceğin Sebebini bilmediğim Yanlızlığımla boğuşurken Ardından gitme  Di...', ARRAY['Türk Edebiyatı','Şiir','Taha Karakoç']::text[], 8.5, '{"poet":"Taha Karakoç","poet_slug":"taha-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gitme-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek böyle bir şey', 'sevmek-boyle-bir-sey-nese-ersoy-2hymw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'başa dönmek istiyorum seninle

ikimize ayrı dünya dile tanrıdan

ruhlarımız sevişsin önce bir güzel

tadına varalım soluğumuzun

ağladığım geceleri unutmak istiyorum

nasıl çileler dolarsa bir gün

ey tanrım doldur çilemi

mutluluğumu geri istiyorum.', 'başa dönmek istiyorum seninle ikimize ayrı dünya dile tanrıdan ruhlarımız sevişsin önce bir güzel tadına varalım soluğumuzun ağladığım gecel...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevmek-boyle-bir-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman Bir Kalem Alsam Elime', 'ne-zaman-bir-kalem-alsam-elime-i-lknur-er-pc3t2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne zaman bir kalem alsam elime

Sana akar gider tüm cümlelerim

Hücrelerim süzülür harf harf hece hece

Sana yazar, seni yazar her bir kelime

Ne zaman bir kalem alsam elime

Bir kuş uçar gider çocuk kalbimden

Şımarırır kağıdım ellerim titrer

Sana yazar, seni yazarım her bir harfimde

Ne zaman bir kalem alsam elime

Adını yazarım herşeyden önce

Sonra bakmaya doymaz seyre dalarım

Sana bakar, seni görürüm hep hayalimde

Ne zaman bir kalem alsam elime

Harflerim sana koşar hep benden önce

Seviyorumla biter hep cümlelerim

Sana bakar, seni yazarım her bir kelime', 'Ne zaman bir kalem alsam elime Sana akar gider tüm cümlelerim Hücrelerim süzülür harf harf hece hece Sana yazar, seni yazar her bir kelime N...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-zaman-bir-kalem-alsam-elime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem’e', 'annem-e-nese-ersoy-fvp7m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu bayram da 

elini öpemedim

annemin

iyi evlât nasıl olur

bilemedim

ona sevgimi

gösteremedim

dizine yatmayalı çok oldu

ninni gibi gelirdi

saçımı okşaması

arada bir

koklaması

son gördüğümde tansiyonu çıkmıştı

yaşı fazla değildi ya

erken çökmüştü

dertlerimizi

gözüne perde diye çekmişti

biraz kiloluydu ama

et değil

dert doluydu

yıllardır

her bayram olduğu gibi

bu bayram da

elini öpemedim

annemin.', 'bu bayram da  elini öpemedim annemin iyi evlât nasıl olur bilemedim ona sevgimi gösteremedim dizine yatmayalı çok oldu ninni gibi gelirdi sa...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/annem-e-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gençlik Ufkunda', 'genclik-ufkunda-kerem-alay-o4cm6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gençliğin ufkunda bir güneş doğsun

Karanlıklar bitsin aydınlıklar olsun

Öyle bir arkadaşa can helal olsun

Hasretine yandım....... ağlarım.

    Atom zeresinden güneşe kadar

    Alem varlığına şehadet eder

    Pervaneler kendini ateşe atar

    İmdadıma yetiş sayı......

Arı çiçeklerde yapar balını

Ağaç meyve verir büker dalını

Kudret deposundan bunca malını

Dağıtır mutlaka sayın......

    Sözlerimi tamamladım bağladım

    Kederlendim ciğerimi dağladım

    Bu sözlerimi hem söyledim hem ağladım

    İmdadıma yetiş sayı......

                          

                           06,04,2005

                           Kerem Alay

                              Van', 'Gençliğin ufkunda bir güneş doğsun Karanlıklar bitsin aydınlıklar olsun Öyle bir arkadaşa can helal olsun Hasretine yandım....... ağlarım.  ...', ARRAY['Türk Edebiyatı','Şiir','Kerem Alay']::text[], 8.5, '{"poet":"Kerem Alay","poet_slug":"kerem-alay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/genclik-ufkunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-nese-ersoy-e1afc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ölüm, karda ayazda

ölüm, dağda denizde

ölüm her yerde

....

ölüm, kumda havada

ölüm, suda toprakta

ölüm değil uzakta

ölüm, yolumda soluğumda

ölüm, koynumda yatağımda

ölüm aşımda

yanıbaşımda.', 'ölüm, karda ayazda ölüm, dağda denizde ölüm her yerde .... ölüm, kumda havada ölüm, suda toprakta ölüm değil uzakta ölüm, yolumda soluğumda ...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olum-166-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharın Getirdiği...', 'baharin-getirdigi-i-brahim-ethem-bingul-vvbop', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir bahar gününde bulutla güneş

Beraber olurlar, dansa kalkarlar

Olurlar birlikte birbirine eş

Kâh bir ışık kâh bir yağmur, akarlar...

Bahardaki bol bereket bundandır...

Bir bahar gününde sevinç yüzlerde

Hece hece gözle okunur umut

Neşeye davet var, hem de yüzlerce

Her davet sanki der: Dertleri unut...

Bahar gelince hareket bundandır...

Bir bahar gününde çıktım kırlara

Tabiat yeşermiş, hava tertemiz

Böyle bir güzellik kalıcı sanma

Kopar bir fırtına, kalmaz hiçbir iz...

Bahara aldanma derler, bundandır...

Bir bahar gününde âşık olmuştum

O günü yâd etti gönlüm kaç bahar

Bir bahar gününde unutulmuştum

O günü dert etti gönlüm her bahar...

Baharlarda kalbim inler, bundandır...

www.iebingul.com', 'Bir bahar gününde bulutla güneş Beraber olurlar, dansa kalkarlar Olurlar birlikte birbirine eş Kâh bir ışık kâh bir yağmur, akarlar... Bahar...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/baharin-getirdigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diriltmek', 'diriltmek-bekir-mutlu-gokcesu-ud4wj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyuyup uyandım hep duvarlar...

Bir ışık, bir gölge düşmez odama

Kıpırdamaz bir ağaç ve bir kuş da

Bir göz gökyüzü bulunmaz arayınca...

Bilmezmişim gibi rengini meraklanırım

Perdelerde sımsıkı kapalı ya...

Geceler nerede başlıyordu? 

Ve nerede kavuşuyordu güne? 

Yaşadığım halde saniyesi saniyesine

Karışıp gidiyor aklım sayıklamalarımın nöbetine

Hastayım, takatim yok renkleri değiştirmeye...

Uyuyup uyanıyorum yine duvarlar...

Gün ışığından uzak düştüm doğmamışım gibi daha

Bu yüzden belki de sancılanıyor bana bir kadın rüyalarımda

Titriyor dudakları, zorlanıyor münferit bir gayretle beni diriltmeye

Ruhum ne kadar da aç hala şefkate ve bir kadın çok başka bir şey

Her şeyden başka bence...

Onu yaşıyorum, kendimi yaşıyorum, hissediyorum, izliyorum hayretle

Üşüyor içimiz, ellerimiz, boncuk, boncuk  terler alınlarımızda

Kabus da değil aslında fakat büzülmüşüm yatağımda

Bu kez farklı geçen seferden, ağlamayacağım, eğer başarırsa...', 'Uyuyup uyandım hep duvarlar... Bir ışık, bir gölge düşmez odama Kıpırdamaz bir ağaç ve bir kuş da Bir göz gökyüzü bulunmaz arayınca... Bilme...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/diriltmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dimdik Duran İstanbulum', 'dimdik-duran-i-stanbulum-i-lknur-cekici-o34om', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğduğum,büyüdüğüm

Toprağında yürüdüğüm

Mağrur bir gelin gibi

Dimdik duran İstanbulum

Saçlarını savur yele

Güzelleğini göster ele

Göğsümü gere gere

Bakırköyden Sarıyere

Gençliğimi bulsam sende

Uzaktayım içimdesin

Gönlümde bir incisin

Gençliğimin gizisin sen

Tekrar yollarına dönebilsem

Avcılardan Kadıköye

Bahçelievlerden Mertere

Adım adım

Yaşarken yüreğimde

Damla damla aksam senle

                                       (06.04.2005)', 'Doğduğum,büyüdüğüm Toprağında yürüdüğüm Mağrur bir gelin gibi Dimdik duran İstanbulum Saçlarını savur yele Güzelleğini göster ele Göğsümü ge...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dimdik-duran-istanbulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efendim', 'efendim-ali-riza-unal-qodwd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nur’u cemâlin şevkine geldim efendim.

Ayanım o şuleyi zuhuru sevdim efendim.

Ne haddir tahammül, firaka düçar eyleme.

Umudum rahmetine, visale evdim efendim.

Şükraneyim gönülden. Canı verdim efendim.

Fersah fersah, kerem’i lütfuna erdim efendim.

Hayayım sensiz ömre tapan bedbahtı gafilden.

Huşuyu hazzın meşkini, demdim efendim', 'Nur’u cemâlin şevkine geldim efendim. Ayanım o şuleyi zuhuru sevdim efendim. Ne haddir tahammül, firaka düçar eyleme. Umudum rahmetine, visa...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/efendim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızları Topladım', 'yildizlari-topladim-deniz-yilmaz-eralp-slro7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıldızları topladım,

Dün gece gök yüzünden.

Uzattım elimi,

Hayır demedi hiç biri.

Küçük bir çocuğun, 

Hayalindeki gibi. 

Yıldızlardan,

Yorgan yapacaktım sana.

Yatağına serecektim usulca,

Ben olamasamda yanında...

Ölümden öte köy var mı? 

Diyordun.

Sensizlikten başka,

Var mı ondan öte ölüm...

Varmı ayrılıktan öte köy...', 'Yıldızları topladım, Dün gece gök yüzünden. Uzattım elimi, Hayır demedi hiç biri. Küçük bir çocuğun,  Hayalindeki gibi.  Yıldızlardan, Yorga...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yılmaz Eralp']::text[], 8.5, '{"poet":"Deniz Yılmaz Eralp","poet_slug":"deniz-yilmaz-eralp","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yildizlari-topladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GiTMe.../ KaL....!', 'gitme-kal-mine-ozdemirtas-moank', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zamanı iğdiş etme

Acelen ne bu kadar? 

Taşların 

yerine oturmasına

daha çok var

üstelik; 

dillerin dönmediği

ve ıslık sesinin

artık

yankı vermediği

o en çorak tepenin

üstünde

kurtlara 

meydan okumaya

başlamadı ki çakal.

Niyetin; 

Karda boğmaksa

Ayak izlerini,

Sonsuzlukta kaybolmaktan

Daha kolay

Ne var? 

Zaten; 

Suyu gömemezsin ki

Toprağa

Bu çaba

Akla zarar

Arkanı döndüğün an

Bastığın her yerde

Önüne çıkar

Kısaca; 

............

............

gitme / Kal.

06/04/2005', 'Zamanı iğdiş etme Acelen ne bu kadar?  Taşların  yerine oturmasına daha çok var üstelik;  dillerin dönmediği ve ıslık sesinin artık yankı ve...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gitme-kal-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup-II', 'mektup-ii-ugur-deniz-ulkegul-phqp9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana bu mektubu çok uzaklardan yazıyorum güzel…Biliyorum yerini tutmayacak harfler bir bakışın,saçının teline bir dokunuşun…Biliyorum yetmeyecek özlemine beyaz bir sayfada eğreti duran kelimeler…

Yine de özlemek adına, düşünmek adına gözlerini, şu ayrı düşmüş yüreğimize bir teselli olsun istedim…Kim bilir, belki bir gün…

Belki bir gün içini boş bıraktığımız sevda küpüne, atacak bir sermayemiz olur bizim de…Belki bir gün yaşanası bir ülkenin sürülen topraklarında boy verir ektiğimiz tohumlar…Belki bir gün ağlamak yerine koşup oynamayı, mavi bir uçurtma yapıp gökyüzünde uçurmayı da bilir, tanıdığımız ve bildiğimiz o çocuklar….Kim bilir, belki bir gün…

Ama bu gün…Direnmenin vaktidir…

Nerede ve ne durumda olursan ol, kavgadan vazgeçmemelisin…Yaşamın bir kıyısından tutup, asılmalısın hayatın içinde var olan güzelliklere…Bir çocuğun gözlerine bak…Bir ihtiyarın bilgeliğini dinle…Bir kadının yalnızlığını paylaş…Ama vazgeçme…İnsanların vefasızlığı üzmesin seni…Riyakarlığı bozmasın yüreğini…Önceyi bırak, yarını düşün ve bu güne bak…Sen insansın…

Her gün biraz daha kötüye gidiyor demişsin…Aldanma buna…Kötülük arttıkça iyiler güçlenir…Ve bu güç öyle bir an gelir ki, karşısında durulamaz bir kuvvet meydana getirir…Ama her şey, yavaş yavaş…

Bir yanda haraç meraç satılırken genç kızların namusu, diğer yanda, er dediğin kafa, ar dediğin yürek gün gelip büyüyecek..Ama yavaş yavaş…

Bir yanda haram lokma düşerken boğazlardan içeri, diğer yanda namuslu annelerin ak sütüyle beslenecek,sinelerinde saklı cennet kokulu bebeleri.. Yüzlerinde gün be gün mertlik ve cesaret yeşerecek…Ama yavaş  yavaş…

Bir yanda,saltanat sofralarında şenlikler yapılırken ve soytarılar,sultanlık makamında oynaşırken diğer yanda tevazu ve onur abidesi gençler…Genç kızlar ve erkekler gelecek bizim ardımızdan…Ama yavaş yavaş..

Öyle çok ki burada o çocuklar…Soruyorlar…Soruyorlar…Ve durmadan yine soruyorlar…Bazen öyle sözler düşüyor ki ağızlarından, adamı katılasıya güldürüyorlar…

”Adalet hangi mülkün temelidir…? ”

“-Boş bakanlar- nereye bakar? “

“ Demokrasi hazım meselesi midir, yoksa hazımsızların diktesi midir? “

“Avrupa Birliği hangi mason ülkesinin başkentidir biliyor musunuz? “

“ Misyonerler hristiyan olan Türk Vatandaşlarına ömür boyu asgari ücret vaat ediyorlarmış, sizce bu, misyonerlerin ülkemizde biraz Türkleştiği ve özlerini yitirdikleri manasına gelebilir mi? ”

“Amerika’da yaşayan malum şahsın, verdiği fetvaları inceleyen CIA ajanlarının, hidayete erdikleri söylentisi ne derece gerçektir? ”

“ Milletvekili olmak istiyorum...Kime müracaat etmeliyim? (Torpil istiyor…) 

“ Sivil Toplum Kuruluşlarının, Kurdukları Vakıf ve Dernek isimlerinin başına, genel olarak Türkiye kelimesinin konması onların bağlantıda oldukları yabancı kuruluşlara ve istihbarat uzantılı kurumlara, Türkiye’nin tanıtımını yapmak amacını taşıyor olabilir mi? “

“ Ajan mısınız? “

Bizler, yalnızlığın ve bazen terk edilmişliğin en yalın halinde bile hayata küsmeden yolumuza devam etmeyi başarabilmiş kimseleriz…Bizler, korkaklığın sinmişliğin onur sayıldığı, bu şekilde saygınlık kazanıldığı bir ülkede, her şeye ve her duruma rağmen, ayakta kalabilmiş kimseleriz

Ve bizler bu ülkede yaşayan her ferdin ve her insanın, en büyük sorununun,

farkında olamamak olduğunu fark etmiş kimseleriz…İşte bunun için konuşuyor, bunun için anlatıyor, bunun için dinliyoruz..

Ve bunun için ayrıyız gülüm…Birleştirebilmek için…

Geldiği gibi yazdık vesselam…Hal hatır sormak niyetine…Biraz emeğimiz olsun istedik sevdamızda…Hani açıp telefonu, Üç beş kelime konuşmak yerine…

Sana da, bana da iyi bak gülüm…Ama en çok, etrafına bak…Açıkta olan giz’leri…Giz’de olan açıkları görmek için…

Bildiğimiz ve anladığımız kadar özgürüz…Umutlu yarınlar için…Rastgele…', 'Sana bu mektubu çok uzaklardan yazıyorum güzel…Biliyorum yerini tutmayacak harfler bir bakışın,saçının teline bir dokunuşun…Biliyorum yetmey...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/mektup-ii-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Arayan Kara Gökler', 'mavi-arayan-kara-gokler-necmi-unsal-jdgfe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalplerden taşıp çölleri kaplar bu kaynayan pınarlar.

Kumla yıkanan bezgin yüzlerin sonsuz gülmesi için.

Tüm sevdalara el pençe divan durur yaşlı çınarlar.

Baharın yeni sevgilerle hep uzun sürmesi için.

Kaybetmiş gülü bekleyen bülbül gözlerinden ferini.

Sümbüller mavi arayan kara göklere selam verir.

Her ayrılıkla hasret kutlar da yeni bir zaferini,

Hüzün elveda demetlerinden acı bir kelam verir.

2 Mayıs 2004 Pazar, Danimarka-Køge 22.16

5+5+7', 'Kalplerden taşıp çölleri kaplar bu kaynayan pınarlar. Kumla yıkanan bezgin yüzlerin sonsuz gülmesi için. Tüm sevdalara el pençe divan durur ...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mavi-arayan-kara-gokler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuzun Umudu', 'tuzun-umudu-uysal-himmet-uxa9i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hangi zamanlara dökülmüş gülümün saçları 

kanun mudur ışıklara hep karanlık yazılır 

dem dem bulutlar geçiyor yüzünden 

hangi yaz biriktirmiş bu yağmurları 

bir gözünden pul pul balıklar dökülüyor 

bir gözünde kanlı baharlar çırpınıyor 

insanım, canım benim 

akıl düşmüş de yüreğinin peşine 

emzirmeye susamış tuzlu dudakları 

ah çirkin kız çirkin kız 

çirkin bir kız ağlıyor duvardaki resimde', 'hangi zamanlara dökülmüş gülümün saçları  kanun mudur ışıklara hep karanlık yazılır  dem dem bulutlar geçiyor yüzünden  hangi yaz biriktirmi...', ARRAY['Türk Edebiyatı','Şiir','Uysal Himmet']::text[], 8.5, '{"poet":"Uysal Himmet","poet_slug":"uysal-himmet","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tuzun-umudu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış', 'kis-tolgahan-bostan-soxre', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dışarıda kış ne kadar üşütüyorsa sokakları 

Kuru bir yaprak nasıl acıtıp ayrılabilirse dalından

İşte o kadar kanatabilirsin beni

Yağmurlarda durulan bu kirli şehir gibi 

Hadi şimdi terk et beni.', 'Dışarıda kış ne kadar üşütüyorsa sokakları  Kuru bir yaprak nasıl acıtıp ayrılabilirse dalından İşte o kadar kanatabilirsin beni Yağmurlarda...', ARRAY['Türk Edebiyatı','Şiir','Tolgahan Bostan']::text[], 8.5, '{"poet":"Tolgahan Bostan","poet_slug":"tolgahan-bostan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kis-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünden Kalan Gözyaşım', 'dunden-kalan-gozyasim-sahin-erturk-qw7ye', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim herşeyim sensin

Acılarım

Yalnızlığım

Çaresizliğim

Umutsuzluğum

Şairliğim

Dünden kalan gözyaşım

Herşeyim ama herşeyim

Sensin güzel sensin

(06.04.2005-Yeni)', 'Benim herşeyim sensin Acılarım Yalnızlığım Çaresizliğim Umutsuzluğum Şairliğim Dünden kalan gözyaşım Herşeyim ama herşeyim Sensin güzel sens...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dunden-kalan-gozyasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldürmeselerdi anne..', 'oldurmeselerdi-anne-turgut-gundogmus-fuzk1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'senin yokluğunda, 

hasret koynumda.. 

coştum 

bir deli tay edasıyla 

sana koşmak istedim anne.... 

olmadı, 

bir gün gelir de 

sana sunarım diye 

bir yürek büyüttüm anne... 

yakmasalardı....

bir gün gelir de 

avuçlarına bırakırım diye 

bir çicek büyüttüm anne 

koparmasalardı....

bir gün gelir de 

gözlerine bırakırım diye 

bir mavi büyüttüm anne 

kirletmeselerdi.... 

hiç bir mavi 

senin kadar sonsuz değildi... 

bir gün gelir de 

umutlarına bırakırım diye 

bir sevgi büyüttüm anne 

çalmasalardı 

bir gün gelir de

yüreğine bırakırım diye

bir aşk büyüttüm anne

almasalardı

bir gün gelir de 

yarınlarına bırakırım diye 

bir çocuk büyüttüm anne

bir çocuk,

öldürmeselerdi anne

 öldürmeselerdi...', 'senin yokluğunda,  hasret koynumda..  coştum  bir deli tay edasıyla  sana koşmak istedim anne....  olmadı,  bir gün gelir de  sana sunarım d...', ARRAY['Türk Edebiyatı','Şiir','Turgut Gündoğmuş']::text[], 8.5, '{"poet":"Turgut Gündoğmuş","poet_slug":"turgut-gundogmus","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/oldurmeselerdi-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız Toplayıcısı', 'yildiz-toplayicisi-umut-ulbegi-ydgsv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıldızları gökten sıyırıp

daha parlak parlak

sıcak sıcakken vereceğim sana

ışıltısı güneş gibi dudaklarında

sokak sokak gezerken istanbul''u

sola gitsem dudakların

sağa gitsem gözlerin

yaşarken sonsuzluğun tek yolu

''Durdurun

gemileri durdurun

denizlere mahkum değiller

sevdalılarsa eğer

Durdurun beni

durdurun

aşk yücedir

herşeye değer''

Yıldızları tek tek toplayıp

gökyüzünü vereceğim sana

gözlerin her gece bir yıldız

yatağımda', 'Yıldızları gökten sıyırıp daha parlak parlak sıcak sıcakken vereceğim sana ışıltısı güneş gibi dudaklarında sokak sokak gezerken istanbul''u ...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yildiz-toplayicisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımı Verirdim', 'canimi-verirdim-i-smet-barlioglu-n8u92', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küçüklüğünü görmeyi çok isterdim,

Kısa kesilmiş saçlarında beyaz kurdelalar,

Üstünde siyah okul önlüğü,

Boynunda beyaz yakalık,

Sıska bacakların dizlerine kadar açık,

Dizinden aşağı bembeyaz çoraplar,

Ayaklarında bayram ayakkabıları

Ve sırtında okul çantası.

Yine kulun-kölen olurdum

Körolası.

Basıl da bir istedim

Seninle bir ilkokul sırasında yan yana oturmayı,

Okul şarkıları okumayı birlikte,

Bembeyaz tebeşirler tutmayı ellerimizde,

Andımızı yazmayı karatahtaya,

Nasıl da bir isterdim

Yeniden gelebilsek

Dünyaya.

Paydoslarda köşekapmaca oynardık seninle,

Tüm köşeleri bomboş bırakırdım

Sırf sen koşup kapasın diye,

Çizgi oynardık, ip atlardık, uçurtma uçururduk,

Herkes yürüyüp giderdi

Bir yaşam çizgisinde,

Biz kalırdık.

Öperdim körpecik yüzünü-gözünü,

Saçlarını okşardım elimle,

Yiyeceklerimi sana yedirir,

İçeceklerimi sana içirirdim.

Kazasız-belasız bugünlere gelebilesin diye

Canımı verirdim.

(TANRI ÖNCE BENİ YARATTI isimli Serbest Şiirler ''inden > 71-72/100)', 'Küçüklüğünü görmeyi çok isterdim, Kısa kesilmiş saçlarında beyaz kurdelalar, Üstünde siyah okul önlüğü, Boynunda beyaz yakalık, Sıska bacakl...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/canimi-verirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizim VE Sensiz', 'sessizim-ve-sensiz-ahmet-akceken-4duaz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sessizim ve Sensiz...

Elbet bundandır. Sessizliğim...

Kimbilir belki de; Sensizliğim.

Hayatın tadıydın, tek gerçeğim.

Sessizim ve sensiz...

Belki de; Bu sessizlik bir fırtına habercisi.

Ve bu fırtına bir gece yarısı,

Silecek herşeyi...

       Sessizliğimi

        Sensizliğimi...', 'Sessizim ve Sensiz... Elbet bundandır. Sessizliğim... Kimbilir belki de; Sensizliğim. Hayatın tadıydın, tek gerçeğim. Sessizim ve sensiz... ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Akceken']::text[], 8.5, '{"poet":"Ahmet Akceken","poet_slug":"ahmet-akceken","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sessizim-ve-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönen Tekerlekler', 'donen-tekerlekler-i-smet-barlioglu-skn0a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her dönen tekerlek beni sana getiriyor,

Vapurların pervaneleri, uçakların motörleri,

Arabaların atları,

Kuşların kanatları,

Bulutlar ve rüzgar.

Sen benden uzak olmasan; 

Tüm bunlar

Neye yarar? 

Sana gelebilsem bir gün

Altımda deniz köpüklerinden yapılmış bulutlar

Veya kırbaçlanmış bir serin rüzgar,

Acaba dolar mı gözlerin yaşlarla

Ve gülücüklerle süslenir mi dudakların,

Acaba bana doğru bir-iki adım atar mı

Ayakların? 

Akşamın dar bir vaktinde

Görürsen göğüsleri masmavi kırlangıç sürülerini

Veya katarlarını turnaların

Yahut öteye-beriye uçtuklarını kelebeklerin,

Bil ki; ben sana gelmek istiyorumdur

İçinden

Çiçeklerin.

(TANRI ÖNCE BENİ YARATTI isimli Serbest Şiirler ''inden > 73-74/100)', 'Her dönen tekerlek beni sana getiriyor, Vapurların pervaneleri, uçakların motörleri, Arabaların atları, Kuşların kanatları, Bulutlar ve rüzg...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/donen-tekerlekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teller', 'teller-i-smet-barlioglu-rmzjt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dokun parmaklarınla usta bir ozan gibi

Yanan gönlümün tellerine,

Vur vurabildiğince, acıma ellerine,

Oradadır senin aradığın o yanık türkü,

Sen çalmana bak, yüreğim söylesin,

Çevresini bir karabulut gibi

Bir karasevda sarmışsa; 

Yürek n ‘eylesin? 

Çile sevilir mi? 

Sevilir, hep çileler içindeysen,

Yaşanan bir sevdanın biryerlerindeysen,

Çilesiz sevda olmaz, dikensiz gülün olmayışı gibi,

Çile gönül yangınıyla başlar,

İstesen,

İstemesen.

Çektiklerim gizlidir teller içinde,

Özlemlerim, gözyaşlarım gizlidir,

Saçına değemediğim, ellerine dokunamadığım gizlidir,

Bir cim teline bağlanmış bölük-pörçük bedenim,

Sakın tezene altında ağlayan

Tellerdir sanma; 

Benim.

(TANRI ÖNCE BENİ YARATTI isimli Serbest Şiirler ''inden > 75-76/100)', 'Dokun parmaklarınla usta bir ozan gibi Yanan gönlümün tellerine, Vur vurabildiğince, acıma ellerine, Oradadır senin aradığın o yanık türkü, ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/teller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeye İnat', 'herseye-i-nat-ahmet-akceken-8gz98', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şiir yazmak için gece yarısını beklemiyorum...

Çünkü senin sayende, artık zaman kavramı

diye birşey kalmadı benim için...

Herşey senin üstüne kuruluydu,

Ve sen çekip gittin. Ve yıkıldı herşey...

Bunun içindir ki; Değişti artık benim için,

zaman,mekan ve diger tüm kavramlar.

Herşey altüst oldu belki,

fakat herşeye ragmen,

ve sana ragmen,

Herşeye İnat...

Yaşanır Bu Hayat...', 'Şiir yazmak için gece yarısını beklemiyorum... Çünkü senin sayende, artık zaman kavramı diye birşey kalmadı benim için... Herşey senin üstün...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Akceken']::text[], 8.5, '{"poet":"Ahmet Akceken","poet_slug":"ahmet-akceken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/herseye-inat-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül-ü İstanbul', 'eylul-u-i-stanbul-sevcan-koyuncu-n42ib', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eylül-ü İstanbul

                                                  Yalnızlığın dile gelir de suçlarsın güzelim Eylül’ü 

                                                                                           ayrılıklardan zayıf düşüp

                                                       Ayrılıklar Eylül’ü seçiyorsa Eylül ne yapsın? ! 

Denizin orta yerinden iki parçaya ayırdığı bir kentte doğmuşsun sen

                                                               henüz ben dünyaya gelmemişken

Kentine ilk gelişimde yedimi bitirmemiştim daha

Bir vapur hatırlıyorum

       zira ondan da öte ne çok korktuğumu hareket edince

Vapur da korku gibi ilk kez girmişti hayatıma

Biliyor musun şimdi anlıyorum

           o sevdiğim martının gözlerindekinin sen olduğunu

O uzak kent senden öte yüreğimi barındırıyormuş içinde

                                                          şimdi öyle yakın kendine

Ne garip değil mi

İlk korkumu yaşatan kent

          ilk sevişimi saklayan kentmiş ellerinde...

Artık yolun yarısına dayamışım sırtımı

           o uzak kentin hayalini kurup tutunuyorum düşüme

Haydarpaşa’dan gözlerime çarpmasıyla irkiliyorum Kadıköy sahilinin

Doluveriyorum maviyle ürperip

Bir bankta oturur buluyorum kendimi sonra

                                      yüreğim yanımda sımsıkı

Gecem kavuşuyor gündüzüne...

İlk defa inanmaya başlıyordun biliyorum

			aşksız bir hayat istemediğine

Altın bir aşk oku da senin için çıkarmıştı sanki Eros sadağından

Ve bir atışla delmişti kalbinin zırhını işte

Oysa sen

Alışmaya bile başlamıştın neredeyse 

                  maşuk olmadan aşık olmaya belki de

(Y) akan hasretimdi ölü bedeninin damarlarında

Sense ha bire yıldızlar adıyordun

          hayat veren gülüşümü bir kez daha görebilmek/duyabilmek adına

O kara bulutlar arasından doğmadıkça ben

O kent hep yağmurlu olacaktı biliyordun

Yağmurlarla bir düşerdim çünkü hep aklına

Ve kahretsin(!) 

         çok yağmur yağıyordu İstanbul’a...

“kül vadisinde açan iri yapraklı papatyam”

                                               böyle derdin sen

Bense kaçırır dururdum 

         o Mayıs yeşilinde Eylül rüzgarı ellerimi utancımdan

Şimdi her sokağın sonunda denizi arıyor gözlerim

	ve yazık ki hep duvarlara çarpıyor minik bedenim...

İstiklal Caddesi... 

Her zaman kalabalıktır bilirim

Boğar üzerine üzerine gelen insan denizi insanı

Ama beraberken bomboş kalırdı hep 

         tek gördüğün yıldız çalan gözlerim olurdu

         tek duyduğunsa sesimin o dinlemeye doyamadığın eşsiz müziği...

Bostancı Sahili... 

Yalnızken huzur bulmak için giderdin hep oraya

Dalga şırıltılarına bırakıp kendini hayaller kurardın bazen

                                                                              anlatırdın bana

Bazen kitap okurdun oturup bir kayanın üzerine

Bazen de koşuya çıkardın sabah serinliğinde sahil boyunca

Kimseyle paylaşmaya kıyamazdın Bostancı Sahili’ni biliyorum

Ama ben... 

Kimse değildim/her şeyindim/her şey bendim/her şeyin bendim

                                                                             sen hep böyle derdin 

Başım dizlerinin güvencesinde

Dinlendirirken yorgun bedenimi 

Sen saçlarımı okşarken

Avuç içlerimi öperdin/incir kuşu gibi narin ellerinin içlerini

Zamanı durdurmak isterdin her seferinde

                      onun içinden akıp geçmek sonra usulca...

Heybeliada... 

Yeşille mavinin seviştiği

             faytonların aşıkları taşıdığı o Marmara adası

Çiçeklerin renkleri daha bir canlı

İnsanları daha bir güleç

Martıların sesleri daha bir güzel gelirdi kulaklarımıza beraberken

                                                                                              çığlık çığlık

Deniz daha bir mavi

Ağaçlar daha bir yeşil

Ve sen...

İşte tam orada çalmıştın benden 

                çöl meltemi misali yüreğini serinleten buseleri...

Sen İstanbul’u seçtin sevgili

Bense Eylül’lüğümle kaldım

Korkma(!)

Her Eylül’ü İstanbul’da yaşarım ben

Sense İstanbul’da her daim Eylül’ü...

Sevcan KOYUNCU/Ankara 2005', 'Eylül-ü İstanbul                                                   Yalnızlığın dile gelir de suçlarsın güzelim Eylül’ü                      ...', ARRAY['Türk Edebiyatı','Şiir','Sevcan Koyuncu']::text[], 8.5, '{"poet":"Sevcan Koyuncu","poet_slug":"sevcan-koyuncu","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/eylul-u-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı buldum', 'aski-buldum-meryem-i-sler-m9yx9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Derdinden hasta oldum düştüm yatağa

Anlamadım birden ne oldu bana

Meğer sevdammış beni böyle yapan

Gece ğündüz göz yaşımı akıtan

Ne isterim ki şimdi şu dünyadan 

Vermiş zaten dilediğimi yaradan

Bir meleğim var etrafımı saran

Ağlıyorum şimdi mutluluktan

Gözüm görmez asla parayı pulu

Arasamda bulamam böyle mutluluğu

Tanrıdan dileğim sürsün ömür boyu

Sensin demiş rabim dünyanın en şanslı kulu

Emanettir mal mülk burada

Aşkım kalıcıdır asırlar sonrasına

Yaşam pınarını bulup içtim kana kana

Ölsemde gam yemem artık asla', 'Derdinden hasta oldum düştüm yatağa Anlamadım birden ne oldu bana Meğer sevdammış beni böyle yapan Gece ğündüz göz yaşımı akıtan Ne isterim ...', ARRAY['Türk Edebiyatı','Şiir','Meryem İşler']::text[], 8.5, '{"poet":"Meryem İşler","poet_slug":"meryem-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aski-buldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ötelerden', 'otelerden-ali-gencay-zed8q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ötelerden, yar ötelerden

Saçına çiğdem takar

Kokusu gelir ötelerden

Hasret tenime yağar

Uzansam toprağına

Filizlenir aşk böğrümden

Kollarım açık bekler

Şafaklar düşüp günlerden

Kekeler dilim, tekler

Heyecan söküp hecelerden

Sessizliğe kulak keser

Sesin gelir ötelerden

Çimene boyadığım gözler

Islanır çiselerden

Çatlamış tohum, biter

Fışkırır yüreğimden

Kahkahalar atar yer, gök

Gülüşün gelir ötelerden

Güneş doğar erir karlar

Nehir olup akar tepelerden

Peşine nisan takmış

Gelir yar ötelerden', 'Ötelerden, yar ötelerden Saçına çiğdem takar Kokusu gelir ötelerden Hasret tenime yağar Uzansam toprağına Filizlenir aşk böğrümden Kollarım ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/otelerden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Beklersin?', 'nasil-beklersin-i-smet-barlioglu-2a2e9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Havasız yaşayabilir misin,

Susuz, uykusuz, ekmeksiz yaşayabilir misin,

Üstünde şu bulutlar,

Altında şu çayırlar, çimenler,

Bu dağlar, tepeler, bu ağaçlar, kuşlar,

Bu güneş, bu mehtap,

Bu deniz, bu yağmurlar,

Bu şarkılar, türküler,

Bu öyküler, masallar olmasa; yaşayabilir misin? 

Bana bunlar kadar gerekli, bunlar kadar güzelsin,

Sensiz yaşamamı

Nasıl beklersin? 

Havasız kalınca seni solumak isterim

Bir çam ormanının havası gibi.

Seni içmek isterim su yerine,

Kitap yerine seni okumak,

Uyku yerine seni uyumak,

Seni sevmek, sana dokunmak

Ve sabahları körpe bir bahar güneşi gibi

Seninle uyanmak.

Ellerim var sana dokunamıyorum,

Okşayamıyorum saçının tellerini,

Elini tutamıyorum,

Gözlerim var, sesini duyamıyorum,

Şaşmamak elde değil; 

Güya ben

Yaşıyorum.

(TANRI ÖNCE BENİ YARATTI isimli Serbest Şiirler ''inden > 77-78/100)', 'Havasız yaşayabilir misin, Susuz, uykusuz, ekmeksiz yaşayabilir misin, Üstünde şu bulutlar, Altında şu çayırlar, çimenler, Bu dağlar, tepele...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/nasil-beklersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özge', 'ozge-serhat-yucel-xnjac', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ö zelsin benim için sen özel

Z or anlarımda nerelerde oluyorsun sen güzel

G ücendirme beni zaten yanımda olmuyor ezel

E sti gene gönlüm söyleyesim geldi şarkı gazel', 'Ö zelsin benim için sen özel Z or anlarımda nerelerde oluyorsun sen güzel G ücendirme beni zaten yanımda olmuyor ezel E sti gene gönlüm söyl...', ARRAY['Türk Edebiyatı','Şiir','Serhat Yücel']::text[], 8.5, '{"poet":"Serhat Yücel","poet_slug":"serhat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ozge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyaya barış geliyor', 'dunyaya-baris-geliyor-aysenur-yazici-iawd8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kuru toprak tutmuş parmak uçlarım

ne kadar sana dokunsam,

sanki, o kadar yağmur yağıyor...

kırmızı tomurcuklar peydahlanıyor kalp kenarlarımda

ne kadar göz göze değersek,

o kadar fidan göğe uzuyor....

bir tüfek ateş alıyor

incittiğim dağ kenarında,

ne kadar av mahlukatı varsa

ormana sığınıyor...

tüyden bir çiçek açıyor,

bin bulut düğün yapıyor avuçlarımda...

seni ne kadar severek erisem,

dünyaya öyle barış yayılıyor

     Üsküdar

      (09:30) 

   03.Nisan.2005

   Andrea and', 'Kuru toprak tutmuş parmak uçlarım ne kadar sana dokunsam, sanki, o kadar yağmur yağıyor... kırmızı tomurcuklar peydahlanıyor kalp kenarlarım...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dunyaya-baris-geliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Yakınımdaki Duvarlar', 'en-yakinimdaki-duvarlar-utku-demir-itn32', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öyle manalı bakmayın 

Yatağımı çevreleyen taş duvarlar 

Şahidisiniz sizler

Sevgi dolu kalp atışlarımın 

Yankılanırken paslanmış kulaklara 

Beğenmiyorum halinizi 

Gömdüreceksiniz güvenimi 

Sonsuz kuyuda 

Büzüşüp kaybolacak 

Ulaşamazsınız da içeri atlayıp 

Kütlenizi yitirmeyi başarmadıkça 

Demek şeytanlara kandınız 

Bana yıllarca rol yaptınız 

Sevgiyi bile kullandınız 

Şahsi menfaatle akliyi ezdiniz 

Hiç mi kendinizden utanmadınız...? 

Beyazlattım sizi 

Üzerinize erittiğim 

Tükenmeye yüz tutmuş mumla 

Karardınız şimdi 

Lekeler saçarken 

İçinizi kaplayan menfaat tutkunuzla', 'Öyle manalı bakmayın  Yatağımı çevreleyen taş duvarlar  Şahidisiniz sizler Sevgi dolu kalp atışlarımın  Yankılanırken paslanmış kulaklara  B...', ARRAY['Türk Edebiyatı','Şiir','Utku Demir']::text[], 8.5, '{"poet":"Utku Demir","poet_slug":"utku-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/en-yakinimdaki-duvarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoruh 2', 'coruh-2-sezer-odabasioglu-ypjex', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'günaydınla merhabayla

karşılarken bir şafağı bir günü

doludizgin bir atlı zamanda

ve hep çoruh kalmış sevinciyle

koşarken denize

bir deli su coğrafyamda

bir selamın sözü mü olurmuş dostum

binlerce selam sana

binlerce selam.

''Irmak Türküleri'' başlıklı şiir dosyasından.', 'günaydınla merhabayla karşılarken bir şafağı bir günü doludizgin bir atlı zamanda ve hep çoruh kalmış sevinciyle koşarken denize bir deli su...', ARRAY['Türk Edebiyatı','Şiir','Sezer Odabaşıoğlu']::text[], 8.5, '{"poet":"Sezer Odabaşıoğlu","poet_slug":"sezer-odabasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/coruh-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şu Dünya''da Senden Başka Kimim Var', 'su-dunya-da-senden-baska-kimim-var-tayyip-sag-welvz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni alıp deryalara salan yar,

İçerimde çare bulmaz yaram var,

Genç yaşımda gönlüm oldu ihtiyar,

Şu Dünya''da senden başka kimim var,

Kararımız böylemiydi nazlı  yar.

Yuvarlanan taş yosun tutmaz derler,

Yan yana getirip bina ederler,

Yalnız kalmış bir gönüle ne derler,

Şu Dünya''da senden başka kimim var,

Kararımız böylemiydi nazlı yar.

Derelerde öter yeşil kurbağa,

Dağlarıma yağmur yağa, kar yağa,

Hasretim yaş olur düşer toprağa,

Şu Dünya''da senden başka kimim var,

Kararımız böylemiydi nazlı yar.

   06.04.2005', 'Beni alıp deryalara salan yar, İçerimde çare bulmaz yaram var, Genç yaşımda gönlüm oldu ihtiyar, Şu Dünya''da senden başka kimim var, Kararım...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/su-dunya-da-senden-baska-kimim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk..', 'ask-nese-ersoy-zivv6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'önce, 

kulağıma fısılda

aşkı bileyim

sonra dudağıma

bir ışık ol süzül ruhuma

seni hissedeyim

mum misali eriyip

gözlerinde biteyim.', 'önce,  kulağıma fısılda aşkı bileyim sonra dudağıma bir ışık ol süzül ruhuma seni hissedeyim mum misali eriyip gözlerinde biteyim....', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-351-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medet', 'medet-nese-ersoy-pmwcr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir çocuk çalışır şurda

yapıda

kızgın güneş altında iki büklüm

teri sümüğüne karışmış

yaşını çoktan aşmış

ne zaman görsem

gözleri kısık,

keskin bakışlı

hınçlı.

...

akranları yazlıkta,

şurda burda

oyunda.

o,

terini,

taşa kuma akıtmakta

harç yapmakta

bakışları,

“bir gün” der gibi

“bir gün öcümü alacağım”

yanına yaklaştım adını sordum

“medet” dedi usulca

“okula gidiyor musun? ” dedim

“yok” dedi, ezildi

“kardeşlerin var mı? ” sorusu 

fazla gelmişti

bir bakış attı yüzüme 

yine keskindi

sorgumdan sıkılmış gibi

döndü, gitti

adı medet! 

belli ki birileri

medet umar medet’ten

aş kavgasında bir çocuk

on üçünde var-yok

kimsenin ondan haberi yok.', 'bir çocuk çalışır şurda yapıda kızgın güneş altında iki büklüm teri sümüğüne karışmış yaşını çoktan aşmış ne zaman görsem gözleri kısık, kes...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/medet-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstek', 'i-stek-nese-ersoy-tu2o4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'senden

öylesine bir bakış istemem

bana yüreğinle bak, düşlerinle

içimi titret, tenimi ürpert

şefkatle bak, sadakatle

yüreğimi ısıt, ruhumu arıt

bana, hem uzaklardan hem yakından

hem derinlerden hem yüzeyden bak

bana sevgiyle bak

başlasın artık bu aşk! ..', 'senden öylesine bir bakış istemem bana yüreğinle bak, düşlerinle içimi titret, tenimi ürpert şefkatle bak, sadakatle yüreğimi ısıt, ruhumu a...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istek-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin', 'gelin-nese-ersoy-gas54', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bütün Nazlı Gelin’lere    

Baba ocağından çıktı bir kere

Daha  on dördünde verdiler ele

Isınır mı acep gittiği yere

Elleri kınalı Nazlı Gelin’in

El oğlu gariptir sever görünür

Sevdasından dizlerinde sürünür

Daha ilk geceden kurda bürünür

Yazması oyalı Nazlı Gelin’in

Yıllar geçer boy boy kızları olur

Onlarla beraber Nazlı da büyür

Hanyayı konyayı o zaman görür

Elleri çamurlu Nazlı Gelin’in

Kız doğurdu diye hep hor görürler

Üstüne kuma der, kız getirirler

Hep susar konuşmaz aptal bilirler

Gözleri buğulu Nazlı Gelin’in

Erkeğine hasret kalakalmıştır

Kumasının kızlarına bakmıştır

Ateşini yüreğinde yakmıştır

Saçları beyazlı Nazlı Gelin’in

Dizinde yorgunluk var, alnında ter

Pişirir kotarır hep başkası yer

Dayanmaz yüreği hoşça kalın der

Toprağı kurumuş Nazlı Gelin’in.', 'Bütün Nazlı Gelin’lere     Baba ocağından çıktı bir kere Daha  on dördünde verdiler ele Isınır mı acep gittiği yere Elleri kınalı Nazlı Geli...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gelin-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-nese-ersoy-fu58r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanrıya nasıl da kızgınım bilsen

Henüz baharında kopardı benden

Ne olur dünyaya bir daha gelsen

Canım, nasıl mutlu ederdin beni

Bu aşk, bu dünyaya fazla mı geldi

Kader oyununu önüme serdi

Bana sensizliği dert diye verdi

Tanrıya nasıl da kızgınım bilsen

Çare yok ölüme olmuş bir gaflet

Geleceğim yanına bugün de sabret

Aşkımız yeniden yeşerir elbet

Tanrıya nasıl da kızgınım bilsen

Ba’l gözlüm, kara sevdam, her şeyim

Nasıl yıktı beni sessiz gidişin

Bir avuç toprakmış bana tercihin

Tanrıya nasıl da kızgınım bilsen.', 'Tanrıya nasıl da kızgınım bilsen Henüz baharında kopardı benden Ne olur dünyaya bir daha gelsen Canım, nasıl mutlu ederdin beni Bu aşk, bu d...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/isyan-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zannetme', 'zannetme-nese-ersoy-b1ggm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zannetme sevgilim sensiz ölürüm

Bu aşkı boynumda böyle sürürüm

Ömrümce perişan halde yürürüm

Senden önce vardım, sonra da olacağım

Gidiyorsan eğer sen kaybedersin

Bir gün geri dönüp pişmanım dersin

Yalvarır, diz çöker, boyun eğersin

Senden önce vardım, sonra da olacağım

Boynum kıldan ince değil bu aşka

Etmem seni bir daha başıma şapka

Koklayacak çok gül var senden başka

Senden önce vardım, sonra da olacağım', 'Zannetme sevgilim sensiz ölürüm Bu aşkı boynumda böyle sürürüm Ömrümce perişan halde yürürüm Senden önce vardım, sonra da olacağım Gidiyorsa...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zannetme-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık oldum', 'asik-oldum-nese-ersoy-lnsud', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık açar çiçekler

Uçuşur kelebekler

Gözüm yolunu bekler

Ben aşık oldum

Yüreğim dolu umut

Ne şimşek ne de bulut

Korkutmaz, elimi tut

Ben aşık oldum

Şimdi dünya toz pembe

Yüreğim kaldı sende

Gözüm yok hiç kimsede

Ben aşık oldum

Çocuklar gibi şenim

Çırpınıyor yüreğim

Dünya yalnızca benim

Ben aşık oldum', 'Artık açar çiçekler Uçuşur kelebekler Gözüm yolunu bekler Ben aşık oldum Yüreğim dolu umut Ne şimşek ne de bulut Korkutmaz, elimi tut Ben aş...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asik-oldum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Ankara', 'ah-ankara-nese-ersoy-h4sfi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu Ankara vurdu beni

Genç yaşımda yordu beni

Kara kışta koydu beni

Açamadan solan güller gibiyim

Gün batarken gurubuna dalarım 

Onunla beraber ben de batarım

Yorgun düşen kaderime çatarım

 Açamadan solan güller gibiyim', 'Şu Ankara vurdu beni Genç yaşımda yordu beni Kara kışta koydu beni Açamadan solan güller gibiyim Gün batarken gurubuna dalarım  Onunla berab...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ah-ankara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yâr Benim - Senden Sonra Kitabından', 'y-r-benim-senden-sonra-kitabindan-omer-ekinci-micingirt-o4r34', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Haya edep yamacına yaslanan 

Leylak gözlü bahar tenli yâr benim 

Gözyaşımın huzmesinde ıslanan 

Sükutunda gölgelenen har benim

Uzağında yakınına varmışım 

Ufuktaki belirlenen zor benim 

Feda olsun ömrüm ona kardeşim 

Kalp titreten sevdalarım var benim', 'Haya edep yamacına yaslanan  Leylak gözlü bahar tenli yâr benim  Gözyaşımın huzmesinde ıslanan  Sükutunda gölgelenen har benim Uzağında yakı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yar-benim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renkler', 'renkler-nese-ersoy-cu1jo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'severim kırmızıyı

gün batarken ankara’da

	 ve doğarken...

yeşili, dalda, çimde severim

oynaşırken gölgeler üzerinde

sarıyı hasat zamanı ekinde

bir de nefes kesen gülümde

moru sümbülde menekşede

maviyi severim denizde gökte

kahverengiyi,

kahverengiyi bir tek gözlerinde', 'severim kırmızıyı gün batarken ankara’da 	 ve doğarken... yeşili, dalda, çimde severim oynaşırken gölgeler üzerinde sarıyı hasat zamanı ekin...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/renkler-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hissediyorum Gidişini', 'hissediyorum-gidisini-ozgur-kokturk-ivtjl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hissediyorum gidişini

Ayak seslerini duyar gibiyim

Bir utkuya hazırlanırcasına

Heyecanlı ve sabırsız...

Seni beklese yüreğim 

Sonsuza dek

Ve sen

Zafer marşları söyleyen çocuklar gibi

Uygun adımlarla ilerleyerek

Okyanuslar aşarak

Dağlar delerek

Gidebileceğin en son noktaya giderek

Arkamda biri var diye düşünmeden

Ne kadar yol alabilirsin

Nereye varabilirsin ki? 

Git gürültüsüz, sessiz

Usul usul git istersen

İstersen sebepsiz

Düşlerimde solan gül gibi

Dikensiz...

Hissediyorum gidişini

Haber vermeden 

Aşkımı çalan hırsız gibi

Sevgisiz! ! ! 

20 / 05 / 1997     11:56', 'Hissediyorum gidişini Ayak seslerini duyar gibiyim Bir utkuya hazırlanırcasına Heyecanlı ve sabırsız... Seni beklese yüreğim  Sonsuza dek Ve...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hissediyorum-gidisini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göresi ne?', 'goresi-ne-nese-ersoy-pgajn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çok sevdim dedi

yüzünde mevsimin kısır gölgesi

aşktı, aceleye gelmez

sözcükler çoğaldı, sessizliği de

zaman 

gözleri ciğerci kedisi

yanlış (mı)  körpe bir gülüş

doğurgandı elleri oysa

öfkenin yabanıl sevdası çiçeklenir

çok sevdim dedi

soluğunda, yasaklı bahçeye düşen

			topun korkusu

yaşamla yüze yüz

tanıdık olmaktan çıktı bakışlar

bilgisizliği yetiyordu kendine

yine de

göresi ne dedi doğrunun

buluta verip gözlerini.', 'çok sevdim dedi yüzünde mevsimin kısır gölgesi aşktı, aceleye gelmez sözcükler çoğaldı, sessizliği de zaman  gözleri ciğerci kedisi yanlış (...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/goresi-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldönümü', 'yildonumu-nese-ersoy-x4go8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bugün yıldönümü bir tanem

güneş, çarşafa bürünmüş

	görünmeyi bilmiyor

uzadıkça uzadı gün

	tükenmeyi bilmiyor

ve sen, gelmeyi...

bugün yıldönümü bir tanem', 'bugün yıldönümü bir tanem güneş, çarşafa bürünmüş 	görünmeyi bilmiyor uzadıkça uzadı gün 	tükenmeyi bilmiyor ve sen, gelmeyi... bugün yıldön...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yildonumu-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül bahçeleri', 'eylul-bahceleri-nese-ersoy-ge1ni', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vazgeçiyorum işte

sıkıntılarımdan, 

   günahlarımdan 

             ve aşktan

yelken açıyorum, gecenin 

gözlerindeki müthiş denize

uçuyor, bir kuşun kanadındaki tüy

gülücükler sunuyorum derin siyahlara

şahlanıyor sanki tenimin, her zerresi

canı yanıyor 

unuttum sandığım duygularımın

ellerim...ellerim yine titriyor,                                                       

                                       bağışlanmıyorum  

bir çınar devriliyor sessizce   

minik bir yıldız, kayıyor,

                           kayboluyor gölgesinde

gülücüklerim  yağıyor eylül bahçelerine

öyküler fısıldıyor

öylesine ruhsuz ki bu şehir

anlaşılmıyor, anımsanmıyorum', 'Vazgeçiyorum işte sıkıntılarımdan,     günahlarımdan               ve aşktan yelken açıyorum, gecenin  gözlerindeki müthiş denize uçuyor, bi...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/eylul-bahceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-nese-ersoy-n0qe1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unuttuğum ne varsa gözlerinde

yeniden

yeniden heceler dilim

gece, tarafsız kalır uykuma

ateş(ten)  ateş

sudan ıslak

toprağı yakınsar tenim

tin ezgin, düş çalıntı

ilkyazın bir akşamında

dilinde riya, gözünde

kokular bıraktın ve gittin

şehirden, benden

bulmadan yitirdiğimsin', 'Unuttuğum ne varsa gözlerinde yeniden yeniden heceler dilim gece, tarafsız kalır uykuma ateş(ten)  ateş sudan ıslak toprağı yakınsar tenim t...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-532-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O da Sevdi.', 'o-da-sevdi-serpil-dilsener-srieu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdim onu,oda beni sevdi bazen,

Bir ilah gibi seyrederdim onu uzun uzun,

Derin bir nefes gibi çekerdim kokusunu,

Gözlerim dolardı,içim burkulurdu,

O uyurken yanımda ben ağlardım gizli gizli.

Beni sevdiği zamanlar öyle azdı ki,

Anlardım bir gün onu yitireceğimi,

Düşündükçe o korkunç anın geleceğini,

Lanet ederdim yaşadığıma,

Değmez derdim, bu dünyada yaşamaya

Ölsem,ölsemde görmesem onu yitirdiğimi,

Belkki daha iyi olurdu böylesi,

Ama onu bırakıp ölemezdim ki,

Beklerdim onun beni öldüreceği saati.', 'Sevdim onu,oda beni sevdi bazen, Bir ilah gibi seyrederdim onu uzun uzun, Derin bir nefes gibi çekerdim kokusunu, Gözlerim dolardı,içim burk...', ARRAY['Türk Edebiyatı','Şiir','Serpil Dilşener']::text[], 8.5, '{"poet":"Serpil Dilşener","poet_slug":"serpil-dilsener","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/o-da-sevdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir I', 'siir-i-nese-ersoy-4zoo3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni anlamaya çalıştınız mı hiç

düşündünüz mü  sevme olasılığımı

görebildiniz mi yüreğimi

geçtiniz mi kapımdan

                            gittiniz mi', 'Beni anlamaya çalıştınız mı hiç düşündünüz mü  sevme olasılığımı görebildiniz mi yüreğimi geçtiniz mi kapımdan                             g...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/siir-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım geldi', 'askim-geldi-ziya-nizam-hnfd4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkım geldi...

Bembeyaz,tertemiz.

Sevsem,tutulsam

	Ölsem uğruna.

Aşkım geldi...

	İçime oturdu

		Az önce.

			26.09.2004-Pazar

			23:08 Çavuşoğlu Otel Çayeli Rize', 'Aşkım geldi... Bembeyaz,tertemiz. Sevsem,tutulsam 	Ölsem uğruna. Aşkım geldi... 	İçime oturdu 		Az önce. 			26.09.2004-Pazar 			23:08 Çavuşo...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/askim-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir II', 'siir-ii-nese-ersoy-9zmeo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün seni sildim pencerelerden

kapı elceklerinden, sehpalardan

toz bezinde sen vardın bugün', 'Bugün seni sildim pencerelerden kapı elceklerinden, sehpalardan toz bezinde sen vardın bugün...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/siir-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Yüreğimdesin*', 'yuregimdesin-nilufer-aslantas-zh118', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dolmasın gözlerin,sus ağlama! 

Sus... ağlama! 

Sanma ki gidiyorum.

Bakma bana öyle haşiiin haşin,

Yakma yüreğimi,

Sanma ki istiyorum.

Sen bilemezsin bebeğim,

Daha çok küçüksün.

İstemesemde... 

İstemesemde gitmeliyim...

Gitsemde unuturum sanma,

Yüreğimdesin...', 'Dolmasın gözlerin,sus ağlama!  Sus... ağlama!  Sanma ki gidiyorum. Bakma bana öyle haşiiin haşin, Yakma yüreğimi, Sanma ki istiyorum. Sen bi...', ARRAY['Türk Edebiyatı','Şiir','Nilüfer Aslantaş']::text[], 8.5, '{"poet":"Nilüfer Aslantaş","poet_slug":"nilufer-aslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuregimdesin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanan Güne Sakla Kavgamı', 'uyanan-gune-sakla-kavgami-vedat-koparan-33mbw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-''rüzgâra ağlayan şair-''

gün gelir de gücüm yetmezse

dayanılmaz acıların içinde

işte o gün geldiğinde

tükenirsem beni  göremezsen

nehre düşen kırık bir dal gibi

savrulan saman çöpü misali

batmış ufuklarda güneş gibi

kaybolup yitmişsem eğer

direnci muştulayan al yalımı

daha ne denizler çağlar

ne dağların bağrı yırtılır 

kül rengi bulutlara sarınsa da sevda

sen bir başına kalmış olsan da

kara çatal höyük sevdam sevdandır

uyanan güne sakla kavgamı

Vedat Koparan 06.04.2005

-''Rüzgâra ağlayan şair-''(Yusuf Ter)  sevgili can kardeşim şiiri okuyunca içinden gelen bu sözü onurlandırarak eklememi istedi,güce güç  yaşama anlam katan olmak adına

çok teşekkür ederim sevgili Yusuf Ter.', '-''rüzgâra ağlayan şair-'' gün gelir de gücüm yetmezse dayanılmaz acıların içinde işte o gün geldiğinde tükenirsem beni  göremezsen nehre düşe...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/uyanan-gune-sakla-kavgami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir şarkının içinde kalmış aşkım.', 'bir-sarkinin-icinde-kalmis-askim-ziya-nizam-n8ar3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şarkının içinde kalmış aşkım.

Her mısrada yudum yudum ölmüşüm.

Gözlerin diye bakmışım her notaya

Arabesk olmuş yokluğun.

Bir şarkının içinde yaşamışım aşkını.

Sen diye diye her mısrada içmişim.

			25.10.2004-Pazartesi

			21:38 Banu’ların Ev İstanbul', 'Bir şarkının içinde kalmış aşkım. Her mısrada yudum yudum ölmüşüm. Gözlerin diye bakmışım her notaya Arabesk olmuş yokluğun. Bir şarkının iç...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-sarkinin-icinde-kalmis-askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgâra Ağlayan Şair', 'ruzg-ra-aglayan-sair-yusuf-ter-29epq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Es poyrazım

Ey haşaran

Bulutların tülleri

Açılsın gelin duvağı

Gök boşalsa da

Dindirse şu rüzgârı

Hürriyet aydınlanır 

Göz perdelerinden damlar

Rüzgâra ağlayan şair

Parçalar bağrını

Yel ılık düşer

Güneşin gölgesine

akar ter alın değişir

Çıkar içinden 

Korkak cesareti….

Yusuf Ter 06.04.05

Saat 15:08 İsviçre 

http://www.yusufter.tr.cx', 'Es poyrazım Ey haşaran Bulutların tülleri Açılsın gelin duvağı Gök boşalsa da Dindirse şu rüzgârı Hürriyet aydınlanır  Göz perdelerinden dam...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ruzgara-aglayan-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Nefes', 'i-lk-nefes-i-lknur-er-b31do', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sensiz aldığım ilk nefes

ciğerlerim tütün katranında bile bu kadar acı çekmemişti

ne hasretler yaşamıştımda hiç biri bu kadar ağır değildi

yuvasından uçmuş kuş gibiyim ve vakitsiz öten horoz gibi

kestiler sen imi şimdi sensiz ve seninsizim

tutki bir gülüm derdin dokunsan dikenlerim batabilir

benki o dikenlerin batışına bile aşıktım 

tut ki uçurum kenarında bir dağ lalesiyim derdin uzanırsan düşebilirsin

ben ki o uçurumdan yuvarlanmaya her bir dönüşte sana sarılmaya razıydım

Sensiz aldığım ilk nefes

annemin ilk kez içirdiği sıcak çay gibi yanık bir tat var ağzımda

ve nisan yağmurlarında sırısıklam ıslanmışlığın şaşkınlığı

hangi mevsimdeyiz kaçıncı bahar ayın kaçı ne farkeder

sen yoksunkii...', 'sensiz aldığım ilk nefes ciğerlerim tütün katranında bile bu kadar acı çekmemişti ne hasretler yaşamıştımda hiç biri bu kadar ağır değildi y...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ilk-nefes-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Son Yaprak*', 'son-yaprak-nilufer-aslantas-5ck35', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kararmasın hava,olmasın akşamlar,

Esmesin rüzgarlar sussun,

Sussun konuşmasın,

Yağmurlar yağmasın,ağlamasın gökyüzü,

Korkutmasınlar,korkutmasınlar beni,

Titretmesin yüreğimi dalındaki son yaprak.

Düşmesin...düşmesin...düşmesin...

Düşmesin tek umudum son yaprak.

Düşerse eğer,

Ben...

Ben biterim...', 'Kararmasın hava,olmasın akşamlar, Esmesin rüzgarlar sussun, Sussun konuşmasın, Yağmurlar yağmasın,ağlamasın gökyüzü, Korkutmasınlar,korkutma...', ARRAY['Türk Edebiyatı','Şiir','Nilüfer Aslantaş']::text[], 8.5, '{"poet":"Nilüfer Aslantaş","poet_slug":"nilufer-aslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/son-yaprak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-i-lknur-er-botn6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzun bir kış gecesinden sonra açtı gözlerini

Saçları hiç bozulmamıştı bukleleri dans ediyordu adeta

Gözlerinin içi parlıyordu kendimi görüyordum taaa içinde

Sende benim taaaa içimdesin dedim güldü.....

Eskidendi o dedi çok eskiden 

Külleri bile kalmamış bir hikayeydi bu

Sen hangi sayfadan çıktın geldin dedi kaçıncı sabahtan

Bende hangisi olmamı istiyorsan o olsun dedim güldü...

Gözlerinin yanındaki çizgilerden anladım

Ağlamıştı daha kurumamıştı göz yaşları

Yanlızlık kapımı çalmadan önce böyle değildim dedi

Yine çok güzelsin dedim yine çok alımlı 

Uzaklar bazen daha uzak gelir insana dedi

Parmak uçları ile buklelerini sararken gözleri daldı

Sustum öylece seyrettim

Kara trenler vardı dedi birde ona binenler; gidipte dönmeyenler

Kim üzülür dedim gidene yavaş yavaş geçmezmi yangını yüreğin

Geçmez dedi gözlerime çevirdi bakışlarını ürperdim 

Her gün bir parçam her gün bin parçam eksildi 

Her gün büyüdü yanlızlığım dedi 

Sustum....

06.04.05', 'Uzun bir kış gecesinden sonra açtı gözlerini Saçları hiç bozulmamıştı bukleleri dans ediyordu adeta Gözlerinin içi parlıyordu kendimi görüyo...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/masal-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçindi Bugünüm Oysa', 'senin-i-cindi-bugunum-oysa-yakup-icik-4wkjk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün,

Senin için uyandım

Sana nefes aldım

Ve seni düşündüm

Sımsıcak bir tebessümle

Dudaklarımla

Adını mırıldandım

Sımsıcak bir duygu ile

Varlığını hissettim.

...Bu şiiri sana yazdım...

Esen rüzgar,

Nefesindi sanki

Güneşin sıcagi tenindi

Öyle çabuk geçti ki bugün

Seninle sensiz

Yanımda sen yoktun.', 'Bugün, Senin için uyandım Sana nefes aldım Ve seni düşündüm Sımsıcak bir tebessümle Dudaklarımla Adını mırıldandım Sımsıcak bir duygu ile Va...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-icindi-bugunum-oysa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anahtar', 'anahtar-banu-aka-akh2z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sadece bir tane

Anahtarım var

Benim 

Uymadı hiç başka kilitlere 

Ben aramaktan usanmadım

Seni 

Ama

Hadi 

Al anahtarımı

Kendi kilidini kendin aç', 'Sadece bir tane Anahtarım var Benim  Uymadı hiç başka kilitlere  Ben aramaktan usanmadım Seni  Ama Hadi  Al anahtarımı Kendi kilidini kendin...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anahtar-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Layıksın', 'layiksin-adnan-ozkan-o9ljp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Varken sende bu fikir

Elin yanında hakir

Kendi yurdunda fakir

Görünmeye layıksın.

İslam’a uymadıkça 

Günaha doymadıkça

Hakk’a doğrulmadıkça

Sürünmeye layıksın.

Mahkumsun ezilmeye

Ezilip büzülmeye

En sonunda ölmeye

Yakılmaya layıksın.

Uyarsın Avrupa’ya 

Yollar da koyar ya

Kıyarlar gündüzüne

Gecelere layıksın.

Camiler boş kaldıkça

Meyhaneler doldukça

Haya edeb kalktıkça

Alçalmaya layıksın.

Daha çok çekersin çok

Hayal kalır mutluluk

Yokken sende doğruluk

Eğrilmeye layıksın.

ÖZKAN, kinim yok sana

Kızıyorum susmana

Gelmedikçe imana

Kahrolmaya layıksın.', 'Varken sende bu fikir Elin yanında hakir Kendi yurdunda fakir Görünmeye layıksın. İslam’a uymadıkça  Günaha doymadıkça Hakk’a doğrulmadıkça ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Özkan']::text[], 8.5, '{"poet":"Adnan Özkan","poet_slug":"adnan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/layiksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşün', 'dusun-adnan-ozkan-ckx1e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dönüşü olmayan o yolculuğu

Toprakta kaybolan son mutluluğu

Varlığa ermişken bir gün yokluğu,

Sabahı olmayan günleri düşün! 

Bir mekan düşün ki, doğmuyor güneş,

Bir mekan düşün ki, zindanlara eş.

Bedeni sarmadan kızgın bir ateş,

Yerlerde savrulan külleri düşün! 

Zaman çare değil, uysan da çağa,

Ölüm bu, kök salmış dört bir bucağa.

Olanı düşünme, bak olacağa,

Zamansız kuruyan gülleri düşün! 

ÖZKAN’ım akmakla durulur bir gün,

Sana da makber kurulur bir gün

Ey! Kara haberin duyulur  bir gün,

Kara gün eseri makberi düşün!', 'Dönüşü olmayan o yolculuğu Toprakta kaybolan son mutluluğu Varlığa ermişken bir gün yokluğu, Sabahı olmayan günleri düşün!  Bir mekan düşün ...', ARRAY['Türk Edebiyatı','Şiir','Adnan Özkan']::text[], 8.5, '{"poet":"Adnan Özkan","poet_slug":"adnan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dusun-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tövbe 1', 'tovbe-1-ali-riza-unal-cphv2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Allahım bu nasıl rahmeti meşk, azabını aştı fakrımı yakar oldu.

Kalmadı sensiz bir şey, külli masiva yok imiş her biri hayal oldu.

Bumuydu azbını aşan vaadi Rahmetin, aman Allahım aman.

Takate muhtacım, aczime lütfeyle. Bana sen diye bakar oldu.

Medet ey şahı resul medet ey maliki mevlâ.

Medet ey ya evliya, embiya külünüz bir oldu.

Estâfirullah el Azim min küllü zenbin ve etübü ileyh.

Tövbeyi nasuh ile tövbe  Ali Rıza naçar oldu', 'Allahım bu nasıl rahmeti meşk, azabını aştı fakrımı yakar oldu. Kalmadı sensiz bir şey, külli masiva yok imiş her biri hayal oldu. Bumuydu a...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tovbe-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilara', 'dilara-serkan-tulgar-6ecu5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kentin orta yerinde yangın çıkartır; 

Ve ağlardım ardından bir çocuk gibi...

İyi, kötü bende ki her satır satır

İşte o her şeyin sahibi sen Dilara...

Saçlarında düş kokusu ellerinde gül

Yüreğim kelepçede ellerim özgür...

O yürür, ardından bin bahar yürür; 

Adı sinemde gizli bir şehir Dilara...

Haneme gül girerdi, sineme kokun...

Yollarını silerdim sen gitme diye...

Önce gibi yine gel, kalbime sokul...

ömrüme en güzel hediye Sen Dilara...', 'Kentin orta yerinde yangın çıkartır;  Ve ağlardım ardından bir çocuk gibi... İyi, kötü bende ki her satır satır İşte o her şeyin sahibi sen ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Tulgar']::text[], 8.5, '{"poet":"Serkan Tulgar","poet_slug":"serkan-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dilara-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaniya Evînê', 'kaniya-ev-n-cigerxw-n-xwhjb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ez û bilbil bi gul û yar navdar in

Nîşanê evînê ne tenê ne dildar in

Dost û yar du dar in, payebilind û şîn

Dostanî, dilbijî di nav da pêtî û ar in

Evîndar her yek rengekî dixwazin

Hin dilbijê sorgul û dilbijê reşxar in

Evîn kanî ye, şêrîn û tehlî tê da yek so

Lê li hawir beden û çember û dîwar in

Ji wê kaniyê cihokek tê ser dilê hejar

Pêlên pêşi xweş in, lê ên paşî dijwar in

Cigerxwîn', 'Ez û bilbil bi gul û yar navdar in Nîşanê evînê ne tenê ne dildar in Dost û yar du dar in, payebilind û şîn Dostanî, dilbijî di nav da pêtî ...', ARRAY['Türk Edebiyatı','Şiir','Cigerxwîn']::text[], 8.5, '{"poet":"Cigerxwîn","poet_slug":"cigerxw-n","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kaniya-evine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'a-Televizyonda', 'a-televizyonda-mikdat-bal-4espg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Televizyonda

	Kur’an’ı................reklam ederler.....maksat....................maddi menfaat

	Reklam ederler.....Nebi yi.................niyet.......................değil şefaat

	Maksat..................niyet.....................dünyalıktır, riya.... ettiği vaat

	Maddi menfaat.....değil şefaat............ettiği vaat...............televizyonda

	Güzel bir ses..........kaydederek....der ki....................seversen eğer

	Kaydederek...........dinleterek.......hemen..................Ezan’ı al der

	Der ki....................hemen.............arayınız,bir de......İstismar eder

	Seversen eğer........Ezan’ı al der...istismar eder….....televizyonda

	Bu istismar...........serbest midir? .......hani......................nerde savcılar? 

	Serbest midir? ....nerde kaldı? ...........nerde...........,,,,,....meşhur avcılar? 

	Hani......................nerde.....................uyaranlar,sussun...istismarcılar

	Nerde savcılar? ...meşhur avcılar? ......istismarcılar….....televizyonda

	Kur’anın............değeri yüce.........maddi.....................olmamalıdır

	Değeri yüce.......okuyan................para........................almamalıdır

	Maddi................para.....................neşri için hiç kar…kalmamalıdır 

	Olmamalıdır......almamalıdır.......kalmamalıdır............televizyonda

	Karşına çıkar...…...bir hoca..….…….onun...................her şeyi madde

	Bir hoca.................konuşur durur…...ancak..................kaygısı sahte

	Onun......................ancak.....................bir çıkarı olsa.....konuşur lehte

	Herşeyi madde.......kaygısı sahte…....konuşur lehte…..televizyonda

	Mikdadî der….....yazdıklarım............bil ki........................devede kulak

	Yazdıklarım.........tekrarlanır..............çünkü………….…...bunlar asalak

	Elbet.....................çünkü....................bu yüzsüzler halkı.....sanırlar salak

	Devede kulak……bunlar asalak……sanırlar salak............ televizyonda

	Ozan Mikdadî', 'Televizyonda 	Kur’an’ı................reklam ederler.....maksat....................maddi menfaat 	Reklam ederler.....Nebi yi...................', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/a-televizyonda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz Mıydı Ne', 'olmaz-miydi-ne-serkan-tulgar-ayj68', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geçtikçe uzuyor verdiğin zaman,

Aşka böyle sınır konmaz mıydı ne? ..

Sinemde tütüyor olduğun her an,

Ateşler söndükçe yanmaz mıydı ne? ..

Aklımı rehnettim bir gülüşüne,

Ömrümden geçmişim bir öpüşüne...

Kapılıp kalmışım yarin düşüne...

Bu yürek böylesi yanmaz mıydı ne? ..

Çok oldu unuttum ben sevilmeyi,

İstemezsin bilirim halim bilmeyi...

Her günün gecesi yağlı ilmeği; 

Bu yürek tek kurtuluş sanmaz mıydı ne? ..

Ağlasam kimseler duymaz sesimi,

Ölümüm bir kadeh zehir içimi...

ille de yaparsam yanlış seçimi

Melekler adımı anmaz mıydı ne? ..

Bitmiyor aşkıma kestiğin ceza,

Dar oldu kinine koskoca feza...

Her şeyin kabulüm, yarimsin keza; 

Seven bu kadar nazlanmaz mıydı ne? ...', 'Geçtikçe uzuyor verdiğin zaman, Aşka böyle sınır konmaz mıydı ne? .. Sinemde tütüyor olduğun her an, Ateşler söndükçe yanmaz mıydı ne? .. Ak...', ARRAY['Türk Edebiyatı','Şiir','Serkan Tulgar']::text[], 8.5, '{"poet":"Serkan Tulgar","poet_slug":"serkan-tulgar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olmaz-miydi-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Ayrı Sevgili', 'i-ki-ayri-sevgili-yakup-icik-7vxfi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzeldi; bir aşk yaşadık seninle sevgilim

Her geçen anı dolu dolu sevgi ile

Sular gibi coştuk akan damarlarımızdan

Kalbimize biriktik, taştık sevinçle gözlerimizden.

Zamansız bir rüzgar esti icimizde birden

Aldı seni benden, beni senden savurdu uzaklara

Attı gelemiyeceğimiz diyarlara ayrı ayrı bizi

Çaresizliğin kollarında sende acı, bende keder.

Bitmez ve ölmez sandığımız aşktı bizimkisi

Ne olduğunu anlamadan bitiverdi şimdi

Yemin etmiştik, ağaçlara yazmıştık adımızı

Kuşlar şahidimizdi oysa; şimdi hüzünlü iki ayrı sevgili.', 'Güzeldi; bir aşk yaşadık seninle sevgilim Her geçen anı dolu dolu sevgi ile Sular gibi coştuk akan damarlarımızdan Kalbimize biriktik, taştı...', ARRAY['Türk Edebiyatı','Şiir','Yakup Icik']::text[], 8.5, '{"poet":"Yakup Icik","poet_slug":"yakup-icik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iki-ayri-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktan', 'uzaktan-yunus-yakup-w0cqq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kırmızı rüyadan 

eli incinmiş bir çiçek gibi uzandın 

yüreğim işte tam burası rengini bul 

kana

üstüme bir sağanak boşal 

gözlerim kirpiklerinden kırılsın

sarındığım yalnızlığımı gökyüzü düşün

yıldızlar kondur

hiç bilinmeyenleri içinde saklayan

bir kenarda ağlayan olsun bütün hayallerim

bir parça ekmek kağıttan oyuncaklarıyla 

yanı başımda uyusun çocukluğum

işte gizlerimiz kadar uzağız birbirimize

küçük yaralar topluyorsa esrik hayat

sanma ki doğurganlığını unutmuş 

seslerimiz içimizde gömülü

olurda bir düşünceden kalkarsak 

kuşlar en sevdiğimizdi kanatlarına değdiğimiz

seyredilen uykulu denizler coşuyordu birden

böyle daha nicelerini avuçlarımıza tutuşturduk

şimdi ayrı kalmaya hükümlü

artık bu suskunluğumu tanıyorum

gülmek adına ne varsa yalan

sevişmek adına her şey yalan

çekip gitmek desenli mendiller sallanıyor 

nereye baksam gördüğüm sevmenin adı uzaktan', 'kırmızı rüyadan  eli incinmiş bir çiçek gibi uzandın  yüreğim işte tam burası rengini bul  kana üstüme bir sağanak boşal  gözlerim kirpikler...', ARRAY['Türk Edebiyatı','Şiir','Yunus Yakup']::text[], 8.5, '{"poet":"Yunus Yakup","poet_slug":"yunus-yakup","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/uzaktan-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burjuva Maşası', 'burjuva-masasi-zumrut-demirtas-tjs8r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hey,

Burjuva maşası! 

bir kaç maddiyata 

sahip oldun diye,

emeğimizi, yüreğimizi

satın alacağını mı sandın? 

Sen, iki yüz elli YTL ''yi bile

kıyamıyorsun vermeye; 

ben, bir sözümle iki yüz elli

can dostunu takarım peşime,

hangimiz daha zengin acaba...

Paranla belki çok şeyi, çok kişiyi 

satın alırsın ama beni, beynimi, 

doğruluğumu, dürüstlüğümü asla alamazsın,

sermayen yetmez bu ASİ ''ye, zincir vuramazsın....

''Belki bugün, belki yarın''

diye bekledik hakkımızı,

yarından sonra da bir şey olmadı,

olmadı, tadı kalmadı, bize

yiğitlik yolu göründü, eyvallah....

Ya Rab! 

sen derman ol her derdime,

şimdi ve son nefese kadar,

muhtaç etme beni nağmerde....', 'Hey, Burjuva maşası!  bir kaç maddiyata  sahip oldun diye, emeğimizi, yüreğimizi satın alacağını mı sandın?  Sen, iki yüz elli YTL ''yi bile ...', ARRAY['Türk Edebiyatı','Şiir','Zümrüt Demirtaş']::text[], 8.5, '{"poet":"Zümrüt Demirtaş","poet_slug":"zumrut-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/burjuva-masasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim İstanbul', 'sevgilim-i-stanbul-murat-cengiz-giray-4lh1o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağtır saçlarını

Tepelerden esen yel

Umutlar hayaller

Saklı kalbinde

Masmavi gözlerini

Unutmak,özlememek

Mümkün mü? 

Seni terk etmek

İmkânsız

Sana âşık olmamak

Seni sevmemek

Elde değil...

(Bir Damla Umut Bir Damla şiir adlı kitabımdan)', 'Dağtır saçlarını Tepelerden esen yel Umutlar hayaller Saklı kalbinde Masmavi gözlerini Unutmak,özlememek Mümkün mü?  Seni terk etmek İmkânsı...', ARRAY['Türk Edebiyatı','Şiir','Murat Cengiz Giray']::text[], 8.5, '{"poet":"Murat Cengiz Giray","poet_slug":"murat-cengiz-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgilim-istanbul-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çınaraltı-Reşitpaşa', 'cinaralti-resitpasa-cem-hire-40id0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Reşitpaşa''dan Çınaraltı Kahvesi

sakin bir yürüyüşle bir ömür sürer'' derdi.

''Emirgan''ın çocukları yüzmeyi

otuzbeş metreden öğrenirlerdi.

Kilisenin kapısını taşlar,

peşlerinde zangoçlar, yokuşaşağı

koşmayı pek severlerdi.

Yeni delikanlılar içki içip kıyıda,

şişeleri denize fırlatırlardı ama

yakalanıp her seferinde abilerine

bir güzel dayak yerlerdi.''

Muharrem biraz içerilerde otururdu,

kutu gibi ahşap bir evde.

Büyüyünce düşünmemişti asker olmayı hiç

-ama ne yapsınlar, ne elde para ne de

 üniversiteyi kazanacağı var bizimkinin, 

giysi, yemek, yatak bedava hiç değilse askeriyede-,

Maçka Endüstri Meslek''ten doğru askeri mektebe.

Askeri öğrencilikti bu tabii biraz sıkıcı,

durulmuştu epeyce eski canlı hayatı,

göremez olmuştu artık ne çifte sevgilileri

ne de bıçkın dostları.

Evlilik, çoluk çocuk derken,

göz kapayınca emeklilik gelirken

bir gün bizim Muharrem,

''Gidip göreyim,'' dedi ''doğduğum güzel evi.''

Çınaraltı''ndan yukarı bir yokuş yürüdüler,

Yorgancı Yusuf''ta durup birer bardak çay içtiler,

onca samimiyet varken yıllar öncesinden

Yusuf bir şey demedi, karşıda küller içinden

 bir güvercin devrildi.', '''Reşitpaşa''dan Çınaraltı Kahvesi sakin bir yürüyüşle bir ömür sürer'' derdi. ''Emirgan''ın çocukları yüzmeyi otuzbeş metreden öğrenirlerdi. Kil...', ARRAY['Türk Edebiyatı','Şiir','Cem Hire']::text[], 8.5, '{"poet":"Cem Hire","poet_slug":"cem-hire","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/cinaralti-resitpasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Gözlü Kız', 'mavi-gozlu-kiz-murat-cengiz-giray-45qtw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Masmavi gözleriyle gülümsüyor

Saçları dağılıyor yedi tepeden rüzgârlarla

Bazen sinirlenip bağırıyor

Bazende sıcacık gülümsüyor

Düşünceler karmaşası yaratıyor insanda

Trafiğiyle, kalabalığıyla,taş yığınlarıyla

Her şeyi ile

Yine de ona aşığım

Yine de seviyorum

Mavi gözlü kız İstanbul''u...

(Bir Damla Umut Bir Damla şiir adlı kitabımdan)', 'Masmavi gözleriyle gülümsüyor Saçları dağılıyor yedi tepeden rüzgârlarla Bazen sinirlenip bağırıyor Bazende sıcacık gülümsüyor Düşünceler ka...', ARRAY['Türk Edebiyatı','Şiir','Murat Cengiz Giray']::text[], 8.5, '{"poet":"Murat Cengiz Giray","poet_slug":"murat-cengiz-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mavi-gozlu-kiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebişim', 'bebisim-sibel-oner-3ctcm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman öncesi bende bir bebektim				

Acaba olmayan bebeğim kadar tatlımıydım				

Hatırlamıyorum bebekliğimi ama 				

İstiyorum bebeğimi				

Onu kucaklayıp demek istiyorum bebeğim				

				

Tüm bebekler saf ve temiz güzeldir				

Oysa beynimdeki bebeğim kadar değil				

Bebekler insanı yüceltecek kadar büyüktür				

Ama benim bebeğim kadar değil				

				

''Bebeğim''ne kadar güzel anlamlı manalı				

Senin canından olan canı nasıl avutmalı				

Biblo yerine alıp vitrine koymalı				

İncitmesinler diye üzerine titremeli				

				

Minnacık elleri,yumuş yumuş gözleri				

Güldüğünde oluşan çukur gamzeleri				

Kin,nefret bilmeyen saf ve temiz bakışları				

Her şeye bedelsin sen bebeğim				

				

Kucağıma alıp ninniler söylemek istediğim				

Senin için nefes alıp hayata bağlanacağım				

Seninle varolduğumu,ayrılığını dayanamayacağım				

Olmayan bir tanecik bebeğim				

				

Senin için canımı bile feda edeceğim				

Seninle kah gülüp kah ağlayacağım				

Uzun kış gecelerinde tenimle ısıtacağım				

Hayalimdeki canımdan çok sevdiğim bebeğim				

				

Şu an sen zaten varsında ben sana varamıyorum				

Elimi uzatsam tutacağım ama niyetlenemiyorum				

Çok yakında kavuşacağımıza inan biliyorum				

Az kaldı bende sende sabret bebeğim				

				

				Sibel ÖNER', 'Zaman öncesi bende bir bebektim				 Acaba olmayan bebeğim kadar tatlımıydım				 Hatırlamıyorum bebekliğimi ama 				 İstiyorum bebeğimi				 O...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bebisim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek inatla', 'sevmek-inatla-mehmet-yilmaz-bulancakli-3632d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen! esmerim,kumralım,

Sevgiye gölge düşürme,

Yaşarken dürüst olalım,

Ömre acılar hiç geçirme.

Keyfine bak,gönülden,

Sevgisiz,aşksız kalma,

Konuş,anladığım o dilden,

Başkasına alet olma.

Sen! esmerim,kumralım,

Doğru olanı yürekten kutla.

Nankör yürekleri vuralım,

Sevmek,yaşamak,inatla.

30.03.2005', 'Sen! esmerim,kumralım, Sevgiye gölge düşürme, Yaşarken dürüst olalım, Ömre acılar hiç geçirme. Keyfine bak,gönülden, Sevgisiz,aşksız kalma, ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevmek-inatla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu bayrağa iyi bak', 'bu-bayraga-iyi-bak-mehmet-yilmaz-bulancakli-sk0b0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bayrağımız göklere yaraşır,

Yıldızlara,göklere hilal.

Buna kim,nasıl karışır? 

Bu uğurda kanlarımız helal.

Bayrağımız şeref,gurur,

Yaşamak için himayesinde.

Ona sahip çıkan olmaz mağdur,

Herşey bayrağımızın sayesinde.

Ey Türk! bu bayrağa iyi bak,

Rengi şehitlerimizin kanından,

Bu bayrakla şereftir yaşamak,

Olsan dahi en tatlı canından.

05.04.2005', 'Bayrağımız göklere yaraşır, Yıldızlara,göklere hilal. Buna kim,nasıl karışır?  Bu uğurda kanlarımız helal. Bayrağımız şeref,gurur, Yaşamak i...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-bayraga-iyi-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaş elli bir', 'yas-elli-bir-mikdat-bal-jydbx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaş elli bir yorgun dizler

Yokuş oldu bana düzler

Bitti yazlar, bitti güzler

Kışa girdim üşüyorum

Son mevsimi yaşıyorum         oy

Sinsi sinsi, gizli gizli

Ömür geçti hızlı hızlı

Oynar iken sizli bizli

Şimdi düzde düşüyorum

Artık baston taşıyorum          oy

Ömür saatim dönerek

Eksilerek, tükenerek

Dünya hevesim sönerek

Ahirete koşuyorum

Son engeli aşıyorum            oy

Mikdat der bu son anımla

Sağ yanımda Kur’anımla

Arzum ölmek imanımla

Bu arzuyla pişiyorum

Şu dünya ya şaşıyorum      oy', 'Yaş elli bir yorgun dizler Yokuş oldu bana düzler Bitti yazlar, bitti güzler Kışa girdim üşüyorum Son mevsimi yaşıyorum         oy Sinsi sin...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yas-elli-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '- D o s t l u k....(Düet ŞiiR)', 'd-o-s-t-l-u-k-duet-siir-metin-eser-78cj9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ömrün orta yerini iki adım geçmişim,

düşündüm de geçen gün, 

gelip geçtiğim yollara/yıllara baktım da 

……..s a n k i…d ü n…g i b i……

Bir de mazide bıraktığım izlere, 

Bir de hala omuz omuza 

……..kol kola yürüdüklerime, 

Ömrün her parçasını uğruna sürüdüklerime,

ne kadar çok insan geçmiş 

……..hayatın çarkları arasında 

……..……..günü birlik tecrübeler içinden…

meğer hayat; 

ne kadar çok farklı yüz çıkartmış karşıma, 

ne kadar çok karar vermek zorunda kalmışım, 

ve ne kadar çok hata yapmışım…

Dostluk yüreğimde habis bir yara 

Sadakat yok ruhunda, hapis vaka 

dost kelâmına hürmet,

……..hatıralar dökülürken 

……..……..mazinin perdelerinden,

Heyhat! 

Kimler gelip geçti dost kervansarayından, 

Bir dost bulamadın konduğun daldan 

Vefayı alıp giderken bu mekandan 

Bakmamış sana,dostun dönüp ardından 

ne çok dostum dediğim isim olmuş meğer,

oysa dostluk hangi dünya malına değer, 

sır için onur için tutulan yeminler varsa eğer,

dost için can da verilirmiş meğer…

Dostluk çetin bir yol... 

Güven,ilgi,sevgi ister 

Bir gül gibidir dostluk 

Kökten tomurcuğa sevgi dolmalı 

Sarmalı sadakati ellerini 

Gözlerinde görmeli güveni 

Zamansızlık deme,bir an yeter 

Mutluluğun gülün besin kaynağıdır 

Kimi gün sevinçten 

Kimi gün mutsuzluktan akar 

Susuzluğuna gözyaşlarından doyar…

Lâkin dost namına sığamamış

……..dost olmamış bana dost bildiklerim,

Ve anladım ki, hata değilmiş

……..defterden sildiklerim,

omzuma omuz olursa bir gün, 

……..yokluğun içinde varım olursa biri,

Tâ Fîzan’da olsa cansız bedenim,

Seksen küsür de olsa hayat yaşım,

……..üzülmem canımın son gidişine 

……..……..ve hüzün akıtmaz gözyaşım…

Ulubatlı gibi veririm ruhumu arşın hakimine giderim,

“Ardımda beni de yaşatan bir dostum var” derim.

Dostluk; 

Varlıkla yokluk arası o tenha yol 

Dostun duyguları dönüşür sele 

Ölüm bile kesemez dost düğümünü 

Saadete dönüşür bir gün zahmet ve çile…

06.04.05 / Frankfurt-Kayseri

Metin Eser - Nur Ulusoy

Not: Bu bir düet şiirdir...', 'Ömrün orta yerini iki adım geçmişim, düşündüm de geçen gün,  gelip geçtiğim yollara/yıllara baktım da  ……..s a n k i…d ü n…g i b i…… Bir de ...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/d-o-s-t-l-u-k-duet-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlasan', 'aglasan-memed-ayaz-zw2pw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni yorgunluguna sevmışım..

dağıldığın sabaha

kan yorgunu gozlerıne..

daha bir yakınsın şimdi 

daha bir yakınık gözlerin....

seni galiba hüznünle sevmişim 

karanlığı avuçlayıp

ortasında ellerimin

seni şimdi içebilsem..

sonra terini yudumlasam

tüm yorgunluguna inat

üzüm kaçkını gözlerini sızlatana dek ortasında otursam

sen ağlasan

                     ağlasan

                                  ağlasan...

tum zamanları 

                     saysam bende

ben gulsem sen......

                                  AĞLASAN.', 'seni yorgunluguna sevmışım.. dağıldığın sabaha kan yorgunu gozlerıne.. daha bir yakınsın şimdi  daha bir yakınık gözlerin.... seni galiba hü...', ARRAY['Türk Edebiyatı','Şiir','Memed Ayaz']::text[], 8.5, '{"poet":"Memed Ayaz","poet_slug":"memed-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aglasan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin düşlerim', 'sensin-duslerim-mehmet-yilmaz-bulancakli-04b22', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönlümden kaçamazsın,

                                   Gözümden uçamazsın,

                                   Sevgimden kaçamazsın,

                                   Seni yüreğime işledim.

                                                                                Dert seni bulmasın,

                                                                                Mevlam bizi ayırmasın,

                                                                                Sensiz canım yanmasın,

                                                                                Seni kalbime işledim.

                                  Sana hasret doluyum,

                                  Ben sevenin kuluyum,

                                  Aşkına sevda yoluyum,

                                  Seni hep düşledim.

                                                                                    1998-Bulancak', 'Gönlümden kaçamazsın,                                    Gözümden uçamazsın,                                    Sevgimden kaçamazsın,       ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz Bulancaklı']::text[], 8.5, '{"poet":"Mehmet Yılmaz Bulancaklı","poet_slug":"mehmet-yilmaz-bulancakli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sensin-duslerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sükut', 'sukut-sair-ahrazi-6228p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yamacında bir hayli gün eskittik,

Bir hayli yol aldık,yorulduksa da.

Ey sükut,sabırla imtihan ettik,

Ne sırlar bulduk sende,söz yoksa da.

* * *', 'Yamacında bir hayli gün eskittik, Bir hayli yol aldık,yorulduksa da. Ey sükut,sabırla imtihan ettik, Ne sırlar bulduk sende,söz yoksa da. * ...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sukut-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mertebe', 'mertebe-sair-ahrazi-ciakw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayyuka çıktın ya,boş ver yağmurları,

Fırtına kopmuş,kıyametmiş,neyine.

Dağıtsın bu korku en yüksek dağları,

Sen ayyuka bak,yokluğu seyret yine…

* * *', 'Ayyuka çıktın ya,boş ver yağmurları, Fırtına kopmuş,kıyametmiş,neyine. Dağıtsın bu korku en yüksek dağları, Sen ayyuka bak,yokluğu seyret yi...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mertebe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapı', 'kapi-aysun-erat-jkrxs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilseydim gelmezdim inanın.

Kapınızı ardına kadar açık görünce! 

Dost bildim sizi de,

Kendim gibi..

Meğer, ne de nefret doluymuş içiniz dışınız.

Bilemedim ben… bilemedim.

Denize düşen misali,

Sarıldım düşünmeden.

Aşk olsun diyeceğim,

Aşk kirlenecek.

En iyisi geldiğim gibi gitmek sessizce…

Ha unutmadan! 

Son bir dilek, sizin için,

Üşüteceksiniz.

Kapayın kapınızı gözünüzü seveyim.

Hem biliyorsunuz değil mi? 

Açık gören dalıyor içeri..

04/2005', 'Bilseydim gelmezdim inanın. Kapınızı ardına kadar açık görünce!  Dost bildim sizi de, Kendim gibi.. Meğer, ne de nefret doluymuş içiniz dışı...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kapi-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlık Öyküler', 'ciglik-oykuler-leyla-ayyildiz-rr6hy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O çok bildik görünen öykülerin bile, 

Gecelerinin sefil karanlığına gizlenen 

Başka başka çığlıkları vardır.

Ne kadar insan; o kadar çığlık. 

Ne kadar insan; o kadar öykü. 

Hepsi birer yaşamlık öyküler... 

Hani; tüm zamanlar içinde, 

Bir kelebeğin ömrü kadar bile yer tutmayıp, 

Bir hayat kadar uzun olan öyküler. 

Hani; çoğunun anlatmadığı, 

Ağzı sıkıca kapatılmış bir küfenin içinde, 

Çekip gidilen yere götürülen öyküler.

Bazen bir günlüğün sayfalarında, 

Bazen bir fotoğrafta, 

Bazen bir yazmanın el işi oyasında, 

Artlarında bıraktıkları sandıklarda 

İzleri aranan öyküler.

Çığlık, çığlık öyküler.', 'O çok bildik görünen öykülerin bile,  Gecelerinin sefil karanlığına gizlenen  Başka başka çığlıkları vardır. Ne kadar insan; o kadar çığlık....', ARRAY['Türk Edebiyatı','Şiir','Leyla Ayyıldız']::text[], 8.5, '{"poet":"Leyla Ayyıldız","poet_slug":"leyla-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ciglik-oykuler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç', 'hic-aysun-erat-qld5s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yok! 

Vallahi  de yok! 

Kalmadı hiçbir şeyim.

Neyim varsa satıldı,

Haraç mezat üç pula.

Aldı götürdü yıllar, bendeki tüm olanı.

Gözyaşım sel oldu aktı ardından,

Kimsecikler duymadı.

Şimdilerde, 

Sadece..

Hiçsizliğin hafifliği ile yaşıyorum.

Bir canım kaldı verilecek.

O da, ikinci el piyasada.

04/2005', 'Yok!  Vallahi  de yok!  Kalmadı hiçbir şeyim. Neyim varsa satıldı, Haraç mezat üç pula. Aldı götürdü yıllar, bendeki tüm olanı. Gözyaşım sel...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hic-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Vay Benim Vefalı Dostlarım', 'vay-benim-vefali-dostlarim-veli-dalbudak-t3j2j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocukluğumu tadamadım,gençlik geldi önce

Gençliğimi yaşayamadım,bu günleri görünce

-Buyrun, önce size dedim.Tanıdığım herkese

Biride rüyalarımı süslemedi benim.

Ne yangınlar söndürdüm,nice gönüllerde

Nice yarenlikler ettim, suskun dillerde

Ağlatanı bile karşıladım, al güllerle

Biride yareme merhem, sürmedi benim.

Kesmedim umudu, arıyorum inadına

Birgün çıkacak,bir sevenim diye karşıma

Yalvardım,  yakardım,  çıldırmışcasına,

Biride yüreğime su, serpmedi benim.

Dost dediklerim nafile, unuttu biliyorum

Bittim artik, vakit geldi gidiyorum

Mezarım yerde, ben yukarda görüyorum

Biride üstümü örtmedi benim.

(Stockholm 2002)', 'Çocukluğumu tadamadım,gençlik geldi önce Gençliğimi yaşayamadım,bu günleri görünce -Buyrun, önce size dedim.Tanıdığım herkese Biride rüyalar...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/vay-benim-vefali-dostlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama İstanbul!', 'aglama-i-stanbul-cetin-hacifettahoglu-0u5l6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şımarıklığımın Yalan Sözcüsü,

Yıkılan Onca Medeniyetlerin miydi Yoksa Doğruların? 

Damsız Barınanları Yutan,

Ama Bir Türlü Uslanmayan,

Acıların Sahte Mutluluğu,

Sende Kalır Umutların Haykırışları…

Ne O? 

 Yoksa Yaşlandın mı…? 

Ellerin mi Titriyor Artık? 

Güzelliğinle Döndürdüğün Dünyanın Başını,

Şimdi Omuzlarında mı Uyutuyorsun? 

Tutmuyor mu Artık Bacakların? 

Ne Umutlar Taşıdın Kadıköy’den Vapurlarınla,

Ve Yine Eminönü’nden Gömdürerek Geri Çevirdin,

Gülüşen Ağlamaklı Yüzleri.

Sen miydin, Yoksa Biz Miydik? 

Hayalleri Yıkan…

Ne O? 

Fatihin Koca İstanbul u Yoksa Cevap Vermeyecek mi Artık? 

Sen ki Uğruna Öldüğüm,

Sen ki Uğruna Öldürdüğün,

Aç Kalmalarının Ardından Koşturan,

Namuslarını Denizinde Batıran

Ey Koca İstanbul! 

Gülümse Hadi Bir Şeyler Söyle Artık,

Küçükyalı’dan Heybeli Nede Hoştur Geceleri,

İşte O Gecelerde Şiirler Yazıp Attım Şişelerle Denizine,

Hep Bekledim Cevabını İstanbul,

Hep Bekledim Kara Gecelerinde, 

Ne Ağıtlar Yaktım O Gecelerine,

Ne Ağıtlar  Yakıldı Kim bilir Sularında Kaybolan,

Ne Şarkılara Nota Oldun,

Bağıramayanlar Senin Sesin Oldu,

Haykırdılar Anadolu’ya,

Süleymaniyeden Ezanların Yankılanır Eminönü Yamaçlarına,

Oturup Dinler Seninle Yaşlanan Nice İnsanlar,

Güvercinlerin Uğultuları Arasında Varoluşunu,

Çocukluğun Savaşlarla Geçti Asırlarca,

Her Baba Evlat Almak İstedi Seni Anadolu’nun Kucağından

Yaşlanınca Maskaramı Oldun,

Nice Yeni Çiçeği Burnunda,

Beton Yığınlarına? 

Sultan Ahmet’ten Altı Minare Yükselir Göklerine,

Ne Yana Baksan Kendini Görürsün,

Arnavut Kaldırımlı Avlularda,

Dervişlere Kucak Açtın Eyüp Sultanınla,

Selzenen Nice Yüreklere Nur Yağdırdın,

Kirletmelere Savaş Açtın, Açtın da Hep Yenik Düştün,

Etilerde Nişantaşı’nda,

Hani Yeminin Vardı Gökyüzüne,

Akıp Giden Sularına Borcun Vardı,

Seni Kirletenleri Almayacaktın Koynuna,

Şimdi Harem Kurmuşsun Seni Satan Riyakarlara,

Of Be İstanbul! ,Of Be İstanbul! 

Biz Kötüyüz  İstanbul! 

Ben Nankörüm Biz Nankörüz Aslında,

Biliyorum Hep Seni Suçladık Yıllarca,

Hadi Ağlama Sil Göz Yaşlarını,

Hatalıyım Biliyorum Ben Gibi Biz Gibiyiz,

Senin Avuçlarında Terleyen Ellerimizi,

Senin Kucağında Uykularımızı,

Ne Çabuk Unutuyoruz,

Dedim ya… Biz Nankör, Sen İse Bonkördün Hep,

Ağlama Be İstanbul, Hadi Parıldasın O Tarih Yazan Gözlerin,

Sil Göz Yaşlarını Bende Kalsın Şiir Kokan İzlerin…', 'Şımarıklığımın Yalan Sözcüsü, Yıkılan Onca Medeniyetlerin miydi Yoksa Doğruların?  Damsız Barınanları Yutan, Ama Bir Türlü Uslanmayan, Acıla...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/aglama-istanbul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapıcı Rüstem', 'kapici-rustem-muhiddin-ates-lsguq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kapı çaldı anladım gelen sen

Tam da hayaline dalmıştım zaten

Hay Allah düşüyorum,sevinçle koşarken

Kapıyı açıyorum gelen,Kapıcı Rüstem

Sanki bir kova kaynar su

Boşalıyor kafamdan doğrusu

Olur mu ya,şimdi bu

Rüstem de nerden çıktı

Bende ne hayaller kurmuştum

Seni karşıma alıp oturmuştum

Kapı çalınca sevinçten kudurmuştum

Taa ki Rüstem''i görünceye kadar

İyi kadın hayalinin üstüne gelir derken

Bu gece başka olacak diye düşünürken

Yapma bunu Rüstem

Ben de sanmıştım ki gelen yengen

Buyur,gelsene Rüstem

Yengen gelmedi madem

İki bardak çay iç benden

Dertleşelim eskiden yeniden.', 'Kapı çaldı anladım gelen sen Tam da hayaline dalmıştım zaten Hay Allah düşüyorum,sevinçle koşarken Kapıyı açıyorum gelen,Kapıcı Rüstem Sanki...', ARRAY['Türk Edebiyatı','Şiir','Muhiddin Ateş']::text[], 8.5, '{"poet":"Muhiddin Ateş","poet_slug":"muhiddin-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kapici-rustem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hevesim Kursağımda Kaldı', 'hevesim-kursagimda-kaldi-veli-dalbudak-acnra', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Azmıyım sence,bir damlacık sevgiye

Yalan dedin, ölüm kadar gerçeğe

Harman kadar sevsemde ben yine,

Razıyım buğday darısı kadar sev beni.

Çilemi zincir edip,tane tane çeksemde

Unutmam seni, hafızamı kaybetsemde

Ayağına yıldızlar kadar sevgi döksemde

Razıyım ay ışığı kadar sev beni.

Kiminle, kimlerlesin, ben seni düşünürken

Hevesim kursağımda kaldı,terkedip giderken

Pişman olupta eğer, bir gün geri dönersen

Razıyım zerrenin yarısı kadar sev beni

(Stockholm 1991)', 'Azmıyım sence,bir damlacık sevgiye Yalan dedin, ölüm kadar gerçeğe Harman kadar sevsemde ben yine, Razıyım buğday darısı kadar sev beni. Çil...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hevesim-kursagimda-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Sen', 'hep-sen-omer-bolat-z9wf2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana çıkıyor yine yollar

Deli dolu coştuğum anda sen.

Durdurur beni incecik kollar

Ölümlere koştuğum anda sen.

Bir duygu ki gülden zarif

Manayı bulup olmalı arif

Sende bulunur imkansız tarif

Kaf Dağı’nı aştığım anda sen...

14 Ekim 2002 

ADAPAZARI', 'Sana çıkıyor yine yollar Deli dolu coştuğum anda sen. Durdurur beni incecik kollar Ölümlere koştuğum anda sen. Bir duygu ki gülden zarif Man...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bolat']::text[], 8.5, '{"poet":"Ömer Bolat","poet_slug":"omer-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hep-sen-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paradigma', 'paradigma-omer-bolat-sdmn8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vuruyorsun,

Bakışlarınla beni.

Harp ilan eden

Nefer gibisin.

“Esirinim senin” dememi

İtiraf et

Der gibisin.

Anlamıyorsun sen beni

İsmin boğazda bıçak.

Ne zaman sayıklasam ismini

Akıyor kanım,

Sımsıcak…

Şiire de dökemiyorum seni

Kaçıyor kelimeler,

Köşe bucak.

Gönderiyorum nefretimi

Sana kucak kucak.

Kusura bakma sevgilim

Aşkın mevzu bahis olunca

Susacak Ömer

Susacak! 

6 Nisan 2005

ADAPAZARI', 'Vuruyorsun, Bakışlarınla beni. Harp ilan eden Nefer gibisin. “Esirinim senin” dememi İtiraf et Der gibisin. Anlamıyorsun sen beni İsmin boğa...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bolat']::text[], 8.5, '{"poet":"Ömer Bolat","poet_slug":"omer-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/paradigma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırış', 'haykiris-ozlem-yilmaz-hp06z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her düşüş bir çıkışsa

eğer bu yol bir sonsa

Tek bir kelime bile eklenemez

Bu sonsuz anlamsızlığa

Sözcükler boş ve yalın

Değmez anlamlar yüklemeye sırtlarına

İnan ki tiz çığlıklar gözlerden taşan

Daha huzurlu bir seçim ulaşmak için sonsuzluğa

Durdurmak kolay aslında kalp atışlarını

Eğer çoktan solmuşsa ruhun bakışları

Ne yazık ki kıramazken hayatla bağlarını

Neden daha sıcak gelir mezartaşları

                                                                           

                                                     (02.02.2004)', 'Her düşüş bir çıkışsa eğer bu yol bir sonsa Tek bir kelime bile eklenemez Bu sonsuz anlamsızlığa Sözcükler boş ve yalın Değmez anlamlar yükl...', ARRAY['Türk Edebiyatı','Şiir','Özlem Yılmaz']::text[], 8.5, '{"poet":"Özlem Yılmaz","poet_slug":"ozlem-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/haykiris-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-ozlem-yilmaz-1benn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kapılar kapanır, el ayak çekilir 

Ve kalırsın başbaşa yalnızlığınla

Bilirsin nereye gidersen git ne yaparsan yap

Hep yanıbaşındadır 

Nefes alıp verişini hissedersin ensende

Soğuk dokunuşlarını ise teninde

Kurtuluş yoktur ne yazık ki

Bir kere girdi mi hayatına, bütünleşti mi ruhunla

Farketmeden mesafeler açıverir sevdiklerinle arana 

O ne derin soğukluktur ki 

Karşında dursa da sevdiğin dokunamazsın ona

Bir türlü ulaşamaz ellerin 

Yetmez sevgi sözcüklerin ya da hissettiklerin

Uzaklarda kalmış o kalbe ulaşmaya

Oysa ne kadar büyük bir çelişkidir ki bu 

En büyük acımasızlığı yapan en çok anlayış beklediklerindir hep

En çok yanında olduğuna inandıkların en uzağında olandır aslında

Kabullenemediğin bu durumla savaş verirken ruhun

Giderek ağırlaşır senden beklenenlerden dolayı omzun

Anlamların anlamsızlık denizine doğru akmaya başladığı anda

Yitirilmişliğin yaşandığı son zerredir ruhunda 

Ve en sonunda sen, yalnızlığın, uçup giden amaçların,

Seni terketmiş olan umutlarınla

Kalırsın başbaşa boş bir odada

               

                                     (6 Mayıs 2004)', 'Kapılar kapanır, el ayak çekilir  Ve kalırsın başbaşa yalnızlığınla Bilirsin nereye gidersen git ne yaparsan yap Hep yanıbaşındadır  Nefes a...', ARRAY['Türk Edebiyatı','Şiir','Özlem Yılmaz']::text[], 8.5, '{"poet":"Özlem Yılmaz","poet_slug":"ozlem-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yalnizlik-237-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul...''''Yarışma varmış..Aldırma... Istanbul...''''.Gene birileri....Devamlıdır ha..', 'istanbul-yarisma-varmis-aldirma-istanbul-gene-birileri-devamlidir-ha-galip-kemali-gunay-nydiu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Istanbul''un nesi güzel

Ankara''ya dönmesi..

Gördü isen 

Bir Veli

Boğaziçi''nde

...........................

..........................

..........................

Istanbul 

Ankara  kadar güzel

Ah Istanbul

Gene birileri.....', 'Istanbul''un nesi güzel Ankara''ya dönmesi.. Gördü isen  Bir Veli Boğaziçi''nde ........................... .......................... ...........', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/istanbul-yarisma-varmis-aldirma-istanbul-gene-birileri-devamlidir-ha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Proje.. Anadolu..', 'proje-anadolu-galip-kemali-gunay-z9x9j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akıl Osman 

Ömer tartı

Ali dövünsün

Mustafa yandı

................

..................

....................

....................

Maalesef...

Kim hatırlayacak.............', 'Akıl Osman  Ömer tartı Ali dövünsün Mustafa yandı ................ .................. .................... .................... Maalesef... ...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/proje-anadolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunma', 'dokunma-meral-vurgun-31k7l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dokunma yüreğime

durgunum bu gece

gül koklasam genzim yanar

ayışığı geceden de kara

ağlasam yağmur yağacak

tuvalimde kararmış bütün renkler

çizemedim resmini hayalime

ne özgürlüğün, ne de senin

tükendi sözcükler 

kalemim küstü bu gece

ne tarifini yapabildim bu sevdanın

ne de adını yazabildim yüreklice

tırnakla kazınmış yazgımıza sürgün

kır çiçekleri kokar saçları anamın

gözlerim çiy damlası

hüzün dalgası bir keşmekeş

vurgunum bu gece

eli kanlı, yüzü kara

pençesi leş kokulu 

vurdular... 

kanıyor İstanbul’um uzaklarda 

aslanlar tutsak

can kafeste direşken

yirmidokuz harfe kan damlıyor

hani şiirlerim

umutlar kelepir

yok pahasına onur satılıyor

sorma 

yangınım bu gece

canhıraş ren nehri

kendi içimde üşüyorum

gel diyorum sana gel! 

gel de çözülsün bu bilmece...', 'dokunma yüreğime durgunum bu gece gül koklasam genzim yanar ayışığı geceden de kara ağlasam yağmur yağacak tuvalimde kararmış bütün renkler ...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dokunma-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haliç’te Çizgiler', 'halic-te-cizgiler-cem-hire-0ji1h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzayıp giden kıvrılarak, sonra bir anda

mezarlığın orada yiten göz alıcı sarı

şerit yeni çizilmiş yola belli.

Piyer Loti bu açıdan o vakit göremezdi.

Sağda boğaza has süslü erguvanlar

içinden yükselen büyülü çizgiler göğe,

öyle incelen… Kentin bu sağır sesini

işitirdi muhakkak o vakit Piyer Loti.

Yüzlerde belirgin silik çizgiler çevrede,

iki adacık Haliç’te iki damla mum.

Piyer Loti hangisinde yatar, yatar mı? 

Haliç izler: Bakır cezvelerde işlemeler,

fincanlarda telvelerden yollar sonra,

pilili etekleriyle liseli kızların bilinmez gizler,

bilir miydi Piyer Loti? 

Biliyorum, “Bu kitap benim, alıyorum raftan,

bak, altını çizmişim, oradan belli benim olduğu”

demişti, hatırlıyorum ve istemiyorum şimdi çizgileri, gizleri:

Ne düne ne şimdiye ait olan altı çizili hiçbir şeyi.', 'Uzayıp giden kıvrılarak, sonra bir anda mezarlığın orada yiten göz alıcı sarı şerit yeni çizilmiş yola belli. Piyer Loti bu açıdan o vakit g...', ARRAY['Türk Edebiyatı','Şiir','Cem Hire']::text[], 8.5, '{"poet":"Cem Hire","poet_slug":"cem-hire","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/halic-te-cizgiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-ahmet-agdere-rt75u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umut; 

Her ayrılık sonrası,

Sokak çocuklarının 

Keman dinlemesi…

Umut; 

Ay ışığında terlerken,

Dokundukça yorgana,

Belirsizliği bilmek…

Umut; 

Kel duygular aynasında,

Kestirdikçe saçları,

Soğukluğu hissetmek...

Umut; 

Dizelere saklanmak,

Kahraman sanılmak,

Ve sonra kaybolmaktır! ...

Umut, fakirin ekmeğidir...

Umut, bizim çocuğumuzdur...', 'Umut;  Her ayrılık sonrası, Sokak çocuklarının  Keman dinlemesi… Umut;  Ay ışığında terlerken, Dokundukça yorgana, Belirsizliği bilmek… Umut...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/umut-164-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalışıyor cincin..Sordum....', 'calisiyor-cincin-sordum-galip-kemali-gunay-sru4p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beş mısralı  beş şiirde

Beş mısra.......................... kaç şiir eder', 'Beş mısralı  beş şiirde Beş mısra.......................... kaç şiir eder...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/calisiyor-cincin-sordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderim', 'giderim-suheyl-turkoglu-tmpal', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkın tarifine,

Takıldım kaldım,

Böylesine,

Küser giderim.

Seyirciye oynayan,

Sahte sevgiyi,

İstemem,

Çeker giderim.

Çıkarlarla yalanlar,

Birlikte oynarlarsa,

Dayanamam,

Kaçar giderim.

Etrafım sarılsa,

Bu timsahlarla,

Ölümüne,

Yüzer giderim.

Hasretim oldu,

Temiz duygular,

Bulabilirsem,

Koşar giderim.

Kader gibiyse,

Bulamamak,

Bu dünyadan,

Göçer giderim.', 'Aşkın tarifine, Takıldım kaldım, Böylesine, Küser giderim. Seyirciye oynayan, Sahte sevgiyi, İstemem, Çeker giderim. Çıkarlarla yalanlar, Bi...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/giderim-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
