INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-suheyl-turkoglu-kbgw6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Büyüten,

Tırnağını esirgeyen,

En zor anında,

Çocuklarını düşünen,

Başka dünya bilmeyen, 

Canım annem,

Güçlü annem,

Şu an karşımdasın,

Hastasın,

Lekeler oluşmuş,

Şefkatle okşayan,

Güzel ellerinde,

Öksürsem çıldırırdın,

Ceketler yağdırırdın,

Omuzuma,

Fırtınalarda,

Sana sığınır,

Rahatlardım,

Kucağında.

Kalk anne,

Sarıl bana,

Eskisi gibi,

Bütün gücünle,

Güzel kokunu,

Çok özledim.

Beceremiyorum,

Kahrediyor,

Vicdan azabı,

Borçlu,

Ya da nankör,

Hissediyorum kendimi.', 'Büyüten, Tırnağını esirgeyen, En zor anında, Çocuklarını düşünen, Başka dünya bilmeyen,  Canım annem, Güçlü annem, Şu an karşımdasın, Hastas...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/annem-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çİçeklerim...', 'ci-ceklerim-leyla-isik-wbwke', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim sınıfım…

 Benim yavrularim…..

    Benim çiçeklerim bunlar….

      Dağlarda açan nadide çiçekler.

         Her birinin rengi ayrı, kokusu başka

            Dağ çiçeklerim,

              Kır çiçeklerim bunlar.

                 Sevginin en güzelini onlarda tattım

                     Sevginin en yalansızını,

                        En katıksızını

                         Şu Ayşem,

         “Büyüyünce gelin olacağım’ diyen.

                            Şu Cenk,

                             Şu  Fatih,

                                Şu  İnanç,

                                    Şu  Pınar,

                 Berrak sular kadar duru temiz.

                                     Ya şu? ..

                                   Elvan’ım

                                Karabiberim,

                            Kıvırcığım benim.

               Yazmada okumada nazlanan Elvan’ım.

  Bende Elvan çok…

     Minik Elvan…

             Yilmaz Elvan…nazar boncuğu gözleri.

                             Bahar’ım da var.

                “ Ben güzelliklerin mujdecisiyim,

                           Ben sonbahar değil,

                     İlkbaharım öğretmenim” diyen.

                                   Fatma’m, 

                    Çimenlerden almış rengini gözleri

                                 Şu Gül''üm…

                        Esmer Gül''üm,gonca gülüm.

                                  Kiraz dudaklı.

   Mehmet’im

          Hakan’ım

                  Sinan''ım

                           Hasan’ım

                                      Bal Coşkun’um da var….

                                             Ufacık tefecik.

                                                 Ya Ebru’m

                                              Edalı çalışkan,

                                  Çiçeklerin içinde nadide çiçek.

                                                      Sibel’im

                                    Hep ilgi isteyen, sevgi  bekleyen,

                                     Kelebekler gibi narin Sibel’im.

                                                       HEPSİ

                                       Ama hepsi benim çiçeklerim.

                                     ''Çiçek olun çocuklar’ deyince

                                           Çiçek olan çiçeklerim…

  Ben çiçeklerime sevgi verip,

        Sevgiyle beslerim.

                                           Gözümün içine bakma öyle! 

                                              Ceylan gözlü Şenay’ım….

                                                     Seni unutmadım.

                                  Siyah saçların perçem olmuş alnında

                                                     Gözlerin ışıl ışıl…

                                            Bin nazla dökülür sözcükler

                                               O, güzel dudaklarından

                                Bir çift minik küpe sallanır kulaklarından.

   Sınıfım vazom,

             Çocuklarım bir demet çiçek.

                       Hepsi güzel,

                                Hepsi birarada..

                                         Hepsi birlikte,

                                                   Ben çiçeklerimle güzelim.

                                                                                           Leyla IŞIK

                                         Uşak Mehmetçik ilkokulu 1/F sınıfı öğrencilerime ithafen 1991', 'Benim sınıfım…  Benim yavrularim…..     Benim çiçeklerim bunlar….       Dağlarda açan nadide çiçekler.          Her birinin rengi ayrı, koku...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/ciceklerim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Bir Umut', 'bos-bir-umut-sahin-erturk-wmd7x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün,yarın diye,diye

Otuz yıldır bekliyorum

Boş bir umut benimkisi

Boş bir umut,umut işte

(07.04.2005-Yeni)', 'Bugün,yarın diye,diye Otuz yıldır bekliyorum Boş bir umut benimkisi Boş bir umut,umut işte (07.04.2005-Yeni)...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bos-bir-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerin Şehri', 'duslerin-sehri-sahin-erturk-foa6w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Övmeye fazla söze ne gerek var

Bu şehri ben,sen o dünya biliyor

Buram,buram tarih,sanat kokuyor

Düşlerin şehri,orası İSTANBUL

Süleymaniye,Fatih,Eyüp CAMİ

Valide SULTAN,Sultan ahmet cami

Saymakla bitmez ki,çoktur mabedi

Camiler şehri,Orası İSTANBUL 

TOPKAPI sarayı,TEKFUR sarayı

YILDIZ  sarayı,ÇIRAĞAN sarayı

Dolmabahçe,Beylerbeyi sarayı

Saraylar şehri,orası İSTANBUL

Fakir,fukaranın umudu sensin

Şöhret olmanın rotası sensin

Sporun,sanatın merkezi sensin

Düşlerin şehri,orası İSTANBUL

Başkadır boğazda,vapur sefası

Sarıyer,Kavak ta balık yemesi

Kilyos,Şile de denize girmesi

Bir başka şehir,orası İSTANBUL

Kenttekinin düşlerinde İSTANBUL

Köydekinin düşlerinde İSTANBUL

Dağdakinin düşlerinde İSTANBUL

Düşlerin şehri,orası İSTANBUL

Şairler çok güzel yazmışlar onu

Ressamlar çok güzel çizmişler onu

Bilsen ne kadar çok özledim onu

Düşlerin şehri,orası İSTANBUL

Kadıköy,Üsküdar seni dolaşsam

Çamlıcaya çıksam seni seyretsem

Gözümle,gönlümle hasret gidersem

Özledim İSTANBUL,düşlerimdesin

Gördüğüm yüzler,İSTANBUL kokuyor

Giydiğim şeyler,İSTANBUL kokuyor

Senin herşeyin GÖZÜMDE TÜTÜYOR

Özledim İSTANBUL,düşlerimdesin

(07.04.2005-Yeni)', 'Övmeye fazla söze ne gerek var Bu şehri ben,sen o dünya biliyor Buram,buram tarih,sanat kokuyor Düşlerin şehri,orası İSTANBUL Süleymaniye,Fa...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/duslerin-sehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bursa’dan Selam', 'bursa-dan-selam-huseyin-sigirtmac-pc2l8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yüreği sevgiyle çarpan dostlarım.

Uludağ’dan selam, Bursa’dan selam.

Sevgiyi yüceltir, nefret asarım.

Uludağ’dan selam, Bursa’dan selam.

Sevgi ile çarpar fani yüreğim.

Gönüllerde taht kurmaktır ereğim.

Deryanın içinde damla değilim.

Uludağ’dan selam, Bursa’dan selam.

Sevgisiz yaşam yok, bulunmaz merhem.

Sevginin kahrıyla kül oldu Kerem.

Sevgisiz kalplere verilmez selam.

Uludağ’dan selam, Bursa’dan selam.

Yaşadığım yerdir yeşil şu Bursa.

Sevgiyle bakarım Yurtta herkese.

Karlı Erciyes’e, yüce Toros’a.

Uludağ’dan selam, Bursa’dan selam.

Sığırtmaç’tan selam şiir sevenler.

Sevgi çarkı ile aşka dönenler.

Şiire can veren şair yarenler.

Uludağ’dan selam, Bursa’dan selam.', 'Yüreği sevgiyle çarpan dostlarım. Uludağ’dan selam, Bursa’dan selam. Sevgiyi yüceltir, nefret asarım. Uludağ’dan selam, Bursa’dan selam. Sev...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bursa-dan-selam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Dünyayı Zehir Etme Bana', 'sakin-dunyayi-zehir-etme-bana-huseyin-erdogan-jh64z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ne olur dalga dalga gelme artık üzerime

zaten,darmadağın etti beni bu gidişin

hüzün düşmüşse eğer gözlerime

inan ki sevince boğacak beni gelişin

bir günü bile zor geçirdim sensiz

bil ki yokluğunda delirdim dünden beri

bilmem sen orada ne yapıyorsun bensiz? 

hala söylemedin bana dönecek misin geri? 

karabasanlar zindan ediyor gecelerimi

ay ışığı da sızmıyor artık penceremden

bir tek sen süslüyorsun hayallerimi

gittin gideli yangın çıkıyor bedenimden

kapının kilitlerini değiştirmedim inan

açar da girersin diye bana döndüğün zaman

bir gün beni mutlu etmek istersen sevgili canan

bir sabah erkenden uzanıver yanıma güneş doğmadan

ben de uyanınca,sevineyim seni yatağımda bulduğum an

sakın dünyayı zehir etme bana ben  sana doyamadan

vallahi sensizliğe dayanamam  hasretinden ölürüm inan

                                                         07.04.2005', 'ne olur dalga dalga gelme artık üzerime zaten,darmadağın etti beni bu gidişin hüzün düşmüşse eğer gözlerime inan ki sevince boğacak beni gel...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sakin-dunyayi-zehir-etme-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukça Yaşamak', 'cocukca-yasamak-suleyman-kaya-u8yhq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'El ele tutuşmuş yürüyorlardı

Baba ve oğul, İstanbul''un sokaklarnı

Gelenektir devam eden onlarınki

Ata erkil,yani erkek egemenliği provası

Baba düşünceli.endişeli ve dertli

İçindeki duygu; ''yıkılmalı.değişmeli''

Kızlarıda vardı,bir dahaki sefere

Onları da beraberinde getirmeli

Nereye...? 

Yaşama,yaşamı zorlaştıran sisteme

Karşı koyma eğitimini geliştirme 

Gelenekleri,tabuları yıkma seminerine

Korkmadan katılarak; bak,oğlum-kızım

Bu yaşadığımız dünya çok çok tatlı

Çoğul toplumlu,bir okadar kültürlü(lü) 

Hanoi''li Almanı,Afrikalı Zulu''lu

Beraber yaşamasalar da onlar dünyalı

Kimi avrupalı,kimi kara afrikalı ve diğerleri

Bizce ne rengine nede diline bakılmalı

Beyazı,karayı,sarıyı ve kızılı ayırmamalı

Hayat bir film şeridi gibi sardığı

Gözlerin gördüğü,kulakların işittiği

Düşüncelerin daldığı libidolu karkuyu

Acımasızca her şeyi çekip nakışlıyor(du) 

Çocuklarla el ele tutunmuş baba istanbul

Ellerin de,hep beraber yürüyorlardı

Gözlerdeki bakışlar  çok şeyler anlatıyordu

Babaya,belliki teselli edeceklerdi o''nu

Belki de şöyle diyeceklerdi; ''baba korkma,

Seninle beraberiz,bizlere bir sey alma! 

Satın alma gücünü biliyoruz,sakın ha! 

Alınma babaciğim,biz çocuk değiliz,anla! 

Çocukça yaşamak,çocukça düşünmek

Ne güzel şey,safça ayrımsız bir dünya

Onlarınki; berrak bir su kaynağı ışıl ışıl

Parıldar,harıl harıl akan zamana direnerek

Ey dünya çocukları! 

Çocuklarımı sevdiğim kadar sizleri de 

Çok çok seviyorum,sizinle hep el ele

Tutuşuyorum, sizinle yaşamak ne güzel! 

                             

                          Süleyman Kaya', 'El ele tutuşmuş yürüyorlardı Baba ve oğul, İstanbul''un sokaklarnı Gelenektir devam eden onlarınki Ata erkil,yani erkek egemenliği provası Ba...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Kaya']::text[], 8.5, '{"poet":"Süleyman Kaya","poet_slug":"suleyman-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/cocukca-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşlandık mı Yoksa?', 'yaslandik-mi-yoksa-osman-i-nci-c1jii', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden hüzünlü şimdi, gülen gözlerin,

Bak titremeye başlamış, narin ellerin,

Eskilerdeki gibi, sıcak değil sözlerin,

Yaşlandık mı yoksa, başka bir şey mi? 

Hüzün dost oldu, ayrılmaz dizimizden,

Yaşlar akıyor şimdi, iki gözümüzden,

Yıllar neler çalmış, götürmüş bizden,

Yaşlandık mı yoksa, başka bir şey mi? 

Her şey mazide kaldı, özlenen anı gibi,

Gençlik akıp gitmiş, çeşmedeki su gibi,

Mutluluk hayâl, yaşam bir kâbus gibi,

Yaşlandık mı yoksa, başka bir şey mi? 

Ne güzel gezerdik, bahçe ve parklarda,

Her mevsim aynıydı, yaşardık baharda,

Nerede güzel günler, hepsi mi anılarda,

Yaşlandık mı yoksa, başka bir şey mi?', 'Neden hüzünlü şimdi, gülen gözlerin, Bak titremeye başlamış, narin ellerin, Eskilerdeki gibi, sıcak değil sözlerin, Yaşlandık mı yoksa, başk...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaslandik-mi-yoksa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin Ey Neyzen!', 'neredesin-ey-neyzen-ali-osman-yilmaz-fjoxp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bozuldu ülkem insanı,nerede vatanım,

Yüzümüz kalmadı bakacak,kabrine Ata''mın,

Tükürür billahi yüzümüze Çanakkaleden,

Gelen hep, seçtiğimiz,edepsizden,rezilden.

Kuru sözler ile beni rahatsız etme,

Davulu dinlerken,kulak mı asarım Kös''e,

Bu seçilmişleri mi,bize layık gördün tanrım? 

Anladım neden,eşekleri insan kılığında yarattın.

Un döken zamlara kalkmış yeniden,

Vallahi zamcılık bunlara yetmez gibidir,

Susun,fazla karıştırmayın bunların işlerini,

Ele aldıkça büyür,Çünkü.......k gibidir.

Kükre be,kafayı millete tut,çünkü yutar,

Bu işin sırrıdır,siyasetçinin aklına yatar,

Para eder mi buşt karşısında caka,

Sen söyle,medyada yazar elbet bir yalaka.

Aç gözünü hey,zırlamayı bırak,

Sen yarına,geleceğine bir bak,

Çocuklarını şimdiden alıştır zulme,

Bu sözümü uyarı bilde,tedbire bak.', 'Bozuldu ülkem insanı,nerede vatanım, Yüzümüz kalmadı bakacak,kabrine Ata''mın, Tükürür billahi yüzümüze Çanakkaleden, Gelen hep, seçtiğimiz,e...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/neredesin-ey-neyzen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Mecnun Eden O Leyla Nerde', 'beni-mecnun-eden-o-leyla-nerde-tayyip-sag-ebnj0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yarama bir merhem aradım gezdim,

Kabuklandı artık olmaz diyorlar,

Çaresiz sevdamı gönlüme yazdım,

Vefasız yar halden  bilmez diyorlar.

Dermanı dert ile vermiş yaratan,

Dertlerden bulursun derdine derman,

Zamandır derdine çare arayan,

Varlığın çareni bulmaz diyorlar.

Tayyip der bu gönül düşmüşse derde,

Oynarsın her derdi hep perde perde,

Beni mecnun eden o leyla nerde,

Sır oldu görünmez, gelmez diyorlar.

     28.03.2005', 'Yarama bir merhem aradım gezdim, Kabuklandı artık olmaz diyorlar, Çaresiz sevdamı gönlüme yazdım, Vefasız yar halden  bilmez diyorlar. Derma...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beni-mecnun-eden-o-leyla-nerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorulursun', 'yorulursun-abdurrahim-karakoc-8y4vb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yorulmam deme gönül mutlaka yorulursun

Ortada seyrederken kenara savrulursun

Zamanın tenceresi, penceresi çok farklı

Temmuz’da buz tutarsın, Ocak’ta kavrulursun..

07.04.2005/Vakit', 'Yorulmam deme gönül mutlaka yorulursun Ortada seyrederken kenara savrulursun Zamanın tenceresi, penceresi çok farklı Temmuz’da buz tutarsın,...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yorulursun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ester(Akrostiş)', 'ester-akrostis-serhat-yucel-2b631', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eks Aşkım oldun benim.

Sezsiz Seninle bu avare bedenim 

Tutuldum Sana Cevabını bekledim hep

Evet demeni beklemem bile bir edep.

Ruhumu aydınlatın Sagol gülüm, Sensizliği isteyemem bana ölüm.....!', 'Eks Aşkım oldun benim. Sezsiz Seninle bu avare bedenim  Tutuldum Sana Cevabını bekledim hep Evet demeni beklemem bile bir edep. Ruhumu aydın...', ARRAY['Türk Edebiyatı','Şiir','Serhat Yücel']::text[], 8.5, '{"poet":"Serhat Yücel","poet_slug":"serhat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ester-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sabret Gönül', 'sen-sabret-gonul-akif-ugur-bwukr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani gittin ya

Sessiz sedasız

Bir daha aramam deyip

Hani tuşlara son defa

Dokundu ya parmakların

Hani kıpkırmızı oldu ya

Yanakların

Gerçeklerin önünde

Titredi ya dudakların

Öfkeden

Sevgililer gününde

İşte o gün

O gün var ya o gün

Ulu bir çınar yıkıldı

Açılmış bir kuytuya

Sessiz sedasız

Kaydı gitti uykuya

Bir anlamı yoktu aslında

Gidişinin

Sebepsiz isyan edişinin

Bak nasıl da geçti zaman

Of of aman aman

Kimbilir

Hangi sular aktı

Köprülerin altından

kimbilir

Kaç sabaha merhaba dedik

Ayrı ayrı yerlerde

Uykusuz seherlerde

Kimbilir

Kaç yağmur damlası

Düştü yanaklarına

Kimbilir 

Kaç buse 

Kondu dudaklarına

Ne çıkar

Bende özlemlerin en özlemi

Bende söylemlerin en söylemi

Sende 

Sende sorunler gizemi

Bugünlerde geçecek elbet

Sen sabret gönül 

Sabret

Nisan yağmurlarının 

Yağmasına az kaldı

Baharların doğmasına az kaldı

Gönüllerin çağmasına az kaldı

Cemre bile çoktan düştü toprağa

Bir gün o cemre 

Suya da düşecek suya

O zaman 

Ne büyük aşklar yaşanacak

Hazan bahçelerinde

Kime niyet kime kısmet

Bu günler de geçecek elbet

Sen sabret gönül

Sabret, sabret

Akif Uğur', 'Hani gittin ya Sessiz sedasız Bir daha aramam deyip Hani tuşlara son defa Dokundu ya parmakların Hani kıpkırmızı oldu ya Yanakların Gerçekle...', ARRAY['Türk Edebiyatı','Şiir','Akif Uğur']::text[], 8.5, '{"poet":"Akif Uğur","poet_slug":"akif-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/sen-sabret-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul', 'istanbul-orkun-isik-fds8b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ah içimin kaçkın şehri Istanbul ah! 

Kimseler yokken ne güzel eyleşiyorduk 

Bilmiyorlardı ki seninle ne güzel sevişiyorduk 

Dedim ya, 

Ah içimin kaçkın şehri Istanbul ah! . 

Firardaydım sana bir gece vakti 

Ellerimde kelepçe ayaklarımda pranga 

Gözlerimde ebediyet denen yaş 

Ne güzeldi seninle muhabbetimiz 

Muhabbetin demindeydi güneşimiz. 

Ah içimin kaçkın şehri Istanbul ah! 

Yedi Kule zındanları içimde 

Anlatamam türlü türlü biçimde 

Seni anarken içli, dünya hiçimde 

Ah içimin kaçkın şehri Istanbul ah! . 

Kaçır beni kendi içime... 

Ne güzel müjdelenmişsin Peygamberce 

Anlı şanlı feth edilmişsin Fatih''çe 

Ruhum özgür, bedenimde var kelepçe 

Beni de alsan diyorum koynuna 

Ah içimin kaçkın şehri Istanbul ah! 

Uzak desem değilsin, yakın desem çok uzak 

Dizginlerim kopuyor, yolların bana tuzak 

Ak ne olursun bir kez olsun sende ak! 

Umutların tükendiği, yeniden yeşerdiği Kent 

Ah içimin kaçkın şehri Istanbul ah! . 

Ülkemin Başkenti Ankara, sense gönüllerin 

Kâinatın bir yeri, seninse cennettir heryerin 

Dillere destan yakuttan, sultan boğaziçin 

Hayallerimle çizerim seni derinliklerime 

Ah içimin kaçkın şehri Istanbul ah! 

Eminönün''de yemiştim balık ekmek 

Meğerse tad burdaymış demek 

Martılar bir şey fısıldadılar 

Kıskandırdılar hep kıskandırdılar 

Ah içimin kaçkın şehri Istanbul ah! ...

Ah Istanbul! ..

Anlattıkları kadar dinledim senin güzelliğini

Ve 

Anlatamadıkları kadar da öylece sevdim seni', 'Ah içimin kaçkın şehri Istanbul ah!  Kimseler yokken ne güzel eyleşiyorduk  Bilmiyorlardı ki seninle ne güzel sevişiyorduk  Dedim ya,  Ah iç...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/istanbul-170-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Yıl Sevginin Yılı', 'bu-yil-sevginin-yili-akif-ugur-13y8g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Pırıl pırıl yanağın ışıl ışıl gözlerin

İçimi ısıtıyor senin güzel sözlerin

Kaldır kahküllerini yeşil dünyam görünsün

Kuruyan gönül bahçem baharlara bürünsün

Örnek olsun aşkımız bizden sonrakilere

Yürekten seven insan teslim olmaz kadere

Sen goncalar goncası ince bir bahar dalı

Bense çoktan kurumuş dağ başında bir çalı

Bizim ortak noktamız aşkımız hiç kuşkusuz

Unutma ki bir tanem bu yıl sevginin yılı

 Örnek olsun aşkımız bizden sonrakilere

Yürekten seven insan teslim olmaz kadere

		

		    İstanbul

		(17.03.2005)', 'Pırıl pırıl yanağın ışıl ışıl gözlerin İçimi ısıtıyor senin güzel sözlerin Kaldır kahküllerini yeşil dünyam görünsün Kuruyan gönül bahçem ba...', ARRAY['Türk Edebiyatı','Şiir','Akif Uğur']::text[], 8.5, '{"poet":"Akif Uğur","poet_slug":"akif-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bu-yil-sevginin-yili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor', 'zor-serpil-dilsener-jxyyu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yanında ne çabuk geçiyor,şu üç beş saat,

Gecen her dakikanın acısı içime işliyor,

Biraz sonra ayrılacağım yanından,

Yüreğim buruk,gözlerim ağlamaklı.

Değişmeyen kaderime döneceğim yeniden,

Dağlara denizlere sığmayan özlemine,

Yine seni düşüneceğim hiç durmadan,

Yüreğimin üstünde yeni kederler büyütüp.

Yokluğuna dayanmak,yolunu beklemek zor,

Günleri,ayları,yılları tek tek saymak,

Yok hayır sevenlere göre değil sabretmek,

Bilsen zaman nasıl solduruyor insanı.', 'Yanında ne çabuk geçiyor,şu üç beş saat, Gecen her dakikanın acısı içime işliyor, Biraz sonra ayrılacağım yanından, Yüreğim buruk,gözlerim a...', ARRAY['Türk Edebiyatı','Şiir','Serpil Dilşener']::text[], 8.5, '{"poet":"Serpil Dilşener","poet_slug":"serpil-dilsener","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zor-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskancım!', 'kiskancim-serpil-dilsener-0dq86', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yarısı uanıyorum aniden,

Göğsümde korkunç bir sızı başlıyor,

Seni düşünüyorum,bir kıskançlık hissi,

İçten içe beynimi kemiriyor sanki.

Ne yapıyor diyorum,ne yapıyor acaba,

Ben onun aşkından ölürken,o kimin kollarında,

O duygulu elleri kimi okşuyor şimdi,

Aşkla, şehvetle kime bakıyor gözleri.

Sabaha kadar cıldırtıyor bu düşünceler,

Üzerime yıkılıyor sanki bütün duvarlar,

Biliyorum hakım yok kıskanmaya,

Ama kahretsin elimde değil kıskancım işte', 'Gecenin bir yarısı uanıyorum aniden, Göğsümde korkunç bir sızı başlıyor, Seni düşünüyorum,bir kıskançlık hissi, İçten içe beynimi kemiriyor ...', ARRAY['Türk Edebiyatı','Şiir','Serpil Dilşener']::text[], 8.5, '{"poet":"Serpil Dilşener","poet_slug":"serpil-dilsener","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiskancim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sığınmak', 'siginmak-bekir-mutlu-gokcesu-l91vb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu devasa çınar yok mu? 

Karşımda duran şu istikrar abidesi

Dudağımda dua, gözlerimde yağmur olursun da 

Kocaman yüreğini açar, saklar beni

Kaçar, konar dallarına ruhum hani...

Sığınmak bu işte şu bir çift kuş misali

Gagalarında dallar gidip gelen

Bir yuva kurmak için çırpınan sabah beri...

Şu devasa çınar yok mu hani? 

Tutsaklığı özgürlüklere adanmış

Sonsuz bir yaşam gibi...', 'Şu devasa çınar yok mu?  Karşımda duran şu istikrar abidesi Dudağımda dua, gözlerimde yağmur olursun da  Kocaman yüreğini açar, saklar beni ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/siginmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Perisine', 'siir-perisine-huseyin-sigirtmac-6gk09', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sevgi yumağı gördüm sizleri.

Şiir Perisine ermek isterim.

Özlerim sevgiyle bakan gözleri.

Şiir Perisine ermek isterim.

Aşkı can bilenler bıkmaz sevgiden.

Kim ayrılır aşkla doğan ilgiden? 

Sevene can kurban, dönmüyor giden.

Şiir Perisine ermek isterim.

Sevil ile başlar şiir teması.

Sığırtmaç’ın bitmez sevgi davası.

Atıp yüreklerde kiri ve pası.

Şiir Perisine ermek isterim.

(Şiir Perisi Grubuna ithafen yazılmıştır.)', 'Bir sevgi yumağı gördüm sizleri. Şiir Perisine ermek isterim. Özlerim sevgiyle bakan gözleri. Şiir Perisine ermek isterim. Aşkı can bilenler...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/siir-perisine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşümden düştün../..canın acımadı ya', 'dusumden-dustun-canin-acimadi-ya-pelin-onay-ik15b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ne zaman düştün sol yanıma da, vuruldum sözlerimden

benim yazım değilsin, korkarım kışım da

tenimde çıldırmış bir dilek tutuşturur iliklerimi

sen ateşsin

saat 17:28

kimbilir, şimdi neredesin

yoruldum korktuğum yangınlara yakalanmaktan

suya düştü intihar, boğuldu son bakış

kimi istesem uzaktır kıyı boyları

vedalar alnıma işlenmiş, nakış nakış

aşk! Sevdiğim ama dokunamadığım çiçek

kulaç attığım dalgalara sıkıştı haykırışım

gitmeyi öğrettiler bana, kalmak nasıldır..? 

nasıldır bir göğüste endişesiz uyumak..? 

yırttığım takvim yapraklarında ağlıyor çocukluğum

söylesene, nasıldır dudaklarını bir dudakta uyutmak..? 

ne zaman girdin aklıma da, karıştım gecelerde..? 

benim sevdam değilsin, korkarım sevenim de

yürekte şaha kalkmış bir arzu ıslatır dilimi

sen havasın

saat 22:16

kimbilir, şimdi hangi kuytudasın

arındım ve çözüldüm geçmişin kirli nefesinden

geceye düştü uyku, titredi acı soluk

kimi çağırdıysam, kapalıdır seslerinin yolu

üşümeler içimden akıyor, oluk oluk

tutku! Bildiğim ama gösteremediğim resim

akıttığım renklere takıldı gül yüzlü uçurtmam

susmayı öğrettiler bana, konuşmak nasıldır..? 

nasıldır, bir sesin içinde bağdaş kurup dinlenmek..? 

yitirdiğim öpüşlerde yanıyor sevgilerim

söylesene, nasıldır bir yüreğin içinde demlenmek..? 

ne zaman geldin yanıma da, dağıldı hüznüm

kaçarım değilsin, korkarım tutanım da

sen topraksın

saat 22:39

kimbilir, şimdi hangi duygunun uykusundasın

06.04.''05 / izmir akşamı', 'ne zaman düştün sol yanıma da, vuruldum sözlerimden benim yazım değilsin, korkarım kışım da tenimde çıldırmış bir dilek tutuşturur iliklerim...', ARRAY['Türk Edebiyatı','Şiir','Pelin Onay']::text[], 8.5, '{"poet":"Pelin Onay","poet_slug":"pelin-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/dusumden-dustun-canin-acimadi-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar gelirken', 'bahar-gelirken-i-brahim-kilinc-pm9oq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Baharı güneşle görürken cihan

Hazanı baharda görenler vardı

Bahçelerde gonca güller açarken

Köşede kuruyup solanlar vardı

Baharla canlılar kaynaşıyorken

Bülbüller gülüne kavuşuyorken 

Kuşlar cıvıl cıvıl ötüşüyorken

Ayrılığa mahkûm olanlar vardı

Karınca, arılar iş görüyorken

Kimisi umutlu düş görüyorken

Her yerden yeşillik fışkırıyorken

Baharda kuruyup solanlar vardı

Kimi arzu ile hedefe koştu

Kimisi ulaştı, sevindi, coştu

Kiminin hedefi, umudu boştu

Umutsuz, çaresiz olanlar vardı

Milyonlarca insan fâni dünyada

Milyonlarca umut, hayâl ve rüya

Milyonlarca yalan, hile ve riyâ

Mutluluğu umut olanlar vardı', 'Baharı güneşle görürken cihan Hazanı baharda görenler vardı Bahçelerde gonca güller açarken Köşede kuruyup solanlar vardı Baharla canlılar k...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bahar-gelirken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Dostlar', 'eski-dostlar-akif-ugur-cg2d1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yol uzanırdı Kalamış’tan Moda’ya

Bir çift göz geçen gemileri sayardı gün boyu

Kimselere söylemezdi

Söyleyemezdi beklediği yolcuyu

Akşam olup zifiri karanlık

Kaplayınca tüm koyu

Dayanılmaz acılar sarardı

Küçücük yüreğini

Gecenin sessizliğine kapatırdı

O güzel gözlerini.

Yeşilyurt’ta hasır vardı bir zaman

Yişilköylü’m oradaydı her zaman

Tahta masalarda kenetlenirdi eller

Yemyeşil bir vadiye dalınca

Tutulurdu o tatlı diller

Akşama değin süren sessiz söylemler

Bir veda busesiyle noktalanırdı

Koşarak uzaklaşırdı evine doğru

Gönlü bende kalırdı.

Kanlıca’dan Çamlıca’ya yürünür

Yağmur gözlüm uzaklardan görünür

Savurur saçlarını

Çamlıca’nın rüzgarı tel tel

Yüreği, sevgisi, endamı ayrı güzel

Özleyince gel derdi çekinmeden

Haydi gel

Elleri, gözleri, sözleri ayrı güzel

Nerede o kibrit kutusunda

Mektup verdiğimiz yıllar

Şimdi aramızda

Mesafeler, denizler, dağlar

Göründü mü pencereden

Komşunun esmer kızı

Yüreğimde başlardı hemen

İnce bir sızı

Sen de duy sesimi

Duy sesimi faytoncunun baldızı

Hey gidi Kumkapı’nın efesi

Toyluk günlerimin aşkı neşesi

Kaldırımları titretirdi yürürken

Topuklarının sesi

Leylaklar, güller kokardı teni nefesi

Bir tek gün bile görmese

Nasıl da kabarırdı öfkesi

Fatih’li ikide bir evden kaçardı

Annesine babasına karşı çıkardı

Zaman zaman benimle

Mutlu günler yaşardı

Her ilişkide evlenir

Üç gün sonra boşardı

Şişli’de otururdu dostların en güzeli

Yolumu beklerdi hep

Gözleri nemli

Simsiyah saçları

Yemyeşil gözleri vardı

Sevmek değildi onunkisi dostlar

Sanki tapardı

Şimdi onlar yüreğimde

Yaşadığım her yerde

Unutmak ne kelime

Bahçemdeki çiçeklere

Tuttuğum tüm dileklere

Sorun düşlerime

Sorun şiirlerime

Onlar eski dostlar

Onlar hiç unutulmazlar.

İstanbul', 'Bir yol uzanırdı Kalamış’tan Moda’ya Bir çift göz geçen gemileri sayardı gün boyu Kimselere söylemezdi Söyleyemezdi beklediği yolcuyu Akşam ...', ARRAY['Türk Edebiyatı','Şiir','Akif Uğur']::text[], 8.5, '{"poet":"Akif Uğur","poet_slug":"akif-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/eski-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben..Ben Öpücükmüyüm?', 'ben-ben-opucukmuyum-gokalp-celik-ipraq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her gün  sabah olur…

Yaşanası güne değil…

Sana başlarım…

Oynama güzelim oynama…

Ben oyuncakmıyım? 

Her gün öğle olur…

Suya değil …

Sana kanarım…

Sallama güzelim sallama…

Ben salıncakmıyım? 

Her gün akşam olur…

Karanlığa değil…

Sana yanarım…

Yakma  güzelim yakma…

Ben yakacakmıyım? 

Her gün gece olur…

Uykuya değil…

Sana dalarım…

Öpme güzelim öpme…

Ben…

Öpücükmüyüm?', 'Her gün  sabah olur… Yaşanası güne değil… Sana başlarım… Oynama güzelim oynama… Ben oyuncakmıyım?  Her gün öğle olur… Suya değil … Sana kana...', ARRAY['Türk Edebiyatı','Şiir','Gökalp Çelik']::text[], 8.5, '{"poet":"Gökalp Çelik","poet_slug":"gokalp-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ben-ben-opucukmuyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman Değilim', 'pisman-degilim-serpil-dilsener-gfw94', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Pişman değilim,hiçbir zaman olmadım,

Çektiğim acılara rağmen seni hep sevdim,

Çoğu zaman sana kızdığım doğru,

Yalan değil öfkeyle lanet okuduğum,

kimi zaman adını nefretle andığım.

Bütün öfkem sensizliğe isyanımdı,

Bir an olsun aklımdan çıkmadın,

Bir gecem olmadı ağlamadığım,

Tanrıdan sonra diz çökeceğim,

En yüce,en kutsal varlığımdın.

O kahrolası sensizlik yokmu,o büyük ıstırap

Her gün yiyip bitiriyor içimi,

Yinede pişman olmadım seni sevdiğime,

Gençliğim solsada hasretinle,

Yalnız seni seveceğim ömrüm boyunca', 'Pişman değilim,hiçbir zaman olmadım, Çektiğim acılara rağmen seni hep sevdim, Çoğu zaman sana kızdığım doğru, Yalan değil öfkeyle lanet okud...', ARRAY['Türk Edebiyatı','Şiir','Serpil Dilşener']::text[], 8.5, '{"poet":"Serpil Dilşener","poet_slug":"serpil-dilsener","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/pisman-degilim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neşer Selman’a', 'neser-selman-a-huseyin-sigirtmac-0oz7w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir şair dostuma gönül borcum var.

Saygı, sevgi olsun Neşer Selman’a.

Tanıdığım günden beri arzum var.

Saygı, sevgi olsun Neşer Selman’a.

Vefalı bir dosttur, güzel yüreği.

Aşkı muhabbetle şair direği.

Kimseyi incitmez şiir ereği.

Saygı, sevgi olsun Neşer Selman’a.

Şiirlerin olur kulağı, gözü.

Yücedir mekanı, yiğittir özü.

Bir derya andırır, şiir her sözü.

Saygı, sevgi olsun Neşer Selman’a.

Şiirleri sezer gönlümün eri.

Arşa değsin başı, köşk olsun yeri.

Yunus bahçesinde gül olan biri.

Saygı, sevgi olsun Neşer Selman’a.

Az görür gözlerim bu yüceliği.

Şiirin hakanı, dost inceliği.

Sığırtmaç anlarım her güzelliği.

Saygı, sevgi olsun Neşer Selman’a.

(Şiirlerime ilgisini kesmeyen Değerli Şairim Neşer Selman''a ithaf olunur.)', 'Bir şair dostuma gönül borcum var. Saygı, sevgi olsun Neşer Selman’a. Tanıdığım günden beri arzum var. Saygı, sevgi olsun Neşer Selman’a. Ve...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/neser-selman-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bogaziçi', 'bogazici-metin-yalti-b7om4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu güzel görünüme iyice bak

Ki ne kadar baksan gene de az

Bin sevda yükünü taşırcasına

Akıtır sularını bugüne Boğaz.

Suların böyle çılgın akışı 

Engine kavuşmaya özlemdir biraz

İnsanlar,vapurlar ve martıların

iç içe kaynaştığıt bir yerdir Boğaz', 'Şu güzel görünüme iyice bak Ki ne kadar baksan gene de az Bin sevda yükünü taşırcasına Akıtır sularını bugüne Boğaz. Suların böyle çılgın ak...', ARRAY['Türk Edebiyatı','Şiir','Metin Yaltı']::text[], 8.5, '{"poet":"Metin Yaltı","poet_slug":"metin-yalti","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bogazici-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözler Gazeli', 'gozler-gazeli-abdulkadir-karaman-jt2yo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçime alevler saçtı gözlerin

Başıma belâlar açtı gözlerin.

Tutunmak için yalvardım, lâkin

Duymadı hiç benden kaçtı gözlerin.

Ruhumda her mevsim açan çiçekti

Başımda her iklim taçtı gözlerin.

Ne kadar gizlese, inkar etse de

Aşka benden çok muhtaçtı gözlerin.

01-04-2001 İst', 'İçime alevler saçtı gözlerin Başıma belâlar açtı gözlerin. Tutunmak için yalvardım, lâkin Duymadı hiç benden kaçtı gözlerin. Ruhumda her mev...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gozler-gazeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin', 'neredesin-servet-ciftci-g7kh5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yapraklar dökülüyor

sarı sarı

Yollar bütün bütün hüzün

Sonbahar gelmiş

Sevdiğim

neredesin

Ağaçlar kızıl bir eylüle bürünmüş

Havada sessiz bir hüzün

Ben sana bürünmüşüm 

Sevdiğim

neredesin

Adın düğümleniyor dudaklarımda

Dilimde hece hece 

İsmin

Gözlerin düşümüş gözlerime

Sevdiğim

neredesin

Mavi bir ayı bölüyor bulutlar

Yüreğimde bir ağrı gibi sevdan

Büyüdükçe büyüyor bir sızı içimde.

Ellerimi parçalıyor isyanım

neredesin

Yarı geceyi geçmişim hülyalarda

Yıldızları saymışım

Umudu işleyen danteller gibi

Büyümüş sevgim 

Büyümüş sığmaz içime

neredesin', 'Yapraklar dökülüyor sarı sarı Yollar bütün bütün hüzün Sonbahar gelmiş Sevdiğim neredesin Ağaçlar kızıl bir eylüle bürünmüş Havada sessiz bi...', ARRAY['Türk Edebiyatı','Şiir','Servet Çiftçi']::text[], 8.5, '{"poet":"Servet Çiftçi","poet_slug":"servet-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/neredesin-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sabah', 'bir-sabah-i-smail-sahin-8hrmp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saçın düşmüş yastığa

yastıkta kokun

kokun sizmiş yatağa

yatağın suskun

Mutfakta ayak seslerin

sesinde çay buğusu

buğusunda yorgun nefesinin

nefesinde bahar kokusu

Emri vaki çağırıyorsun beni

beni seninle bir bahçeye

bahçeye sürüyorum ezik bedeni

bedenimi bir çiçeğe

Özenle donanmış bir masa

masaya bir kuş konar

konar gözlerin bakışlarıma

bakışlarım gizli gizli yanar', 'Saçın düşmüş yastığa yastıkta kokun kokun sizmiş yatağa yatağın suskun Mutfakta ayak seslerin sesinde çay buğusu buğusunda yorgun nefesinin ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-sabah-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekrar', 'tekrar-tulay-yilmaz-cyu0l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Fısılda,bana en içten nağmeleri

En güzel şarkıları dinlemek,istiyorum.

Şiirler okumayı,yazmayı istiyorum.

Düşünürken dalıp,gitmeyi

Hayallerde gezinmeyi,

Tozpembe bir düş istiyorum.

Gözlerimi kapatıp,

En mutlu anılarımı 

Unuttuğum bir köşeden çıkarmayı,

Yaşamayı,istiyorum.

Tekrar o anıları.', 'Fısılda,bana en içten nağmeleri En güzel şarkıları dinlemek,istiyorum. Şiirler okumayı,yazmayı istiyorum. Düşünürken dalıp,gitmeyi Hayallerd...', ARRAY['Türk Edebiyatı','Şiir','Tülay Yılmaz']::text[], 8.5, '{"poet":"Tülay Yılmaz","poet_slug":"tulay-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tekrar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmez', 'bilmez-tulay-yilmaz-exb27', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Parmaklarımın arasında bir kalem

Ne yazacağını,bilmez.

Ne yol bulur,ne de iz.

Duyguların haritası mı var ki! 

İçimde bir his

Ne olduğunu, bilmez.

Yaşanmamış,anlar mı var ki!', 'Parmaklarımın arasında bir kalem Ne yazacağını,bilmez. Ne yol bulur,ne de iz. Duyguların haritası mı var ki!  İçimde bir his Ne olduğunu, bi...', ARRAY['Türk Edebiyatı','Şiir','Tülay Yılmaz']::text[], 8.5, '{"poet":"Tülay Yılmaz","poet_slug":"tulay-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bilmez-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Destan Şehir', 'bir-destan-sehir-abdulkadir-karaman-i707d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir şehir ki; âlemde yoktur dengi, benzeri

Baygın baygın, herkesin ona bakar gözleri 

Bakışları mest eder, tutuşturur özleri

Sevdiğine kendini tam verir bu şehir

Sevmediğine acı, gam verir bu şehir.

Bağrı yanık tarihin, içi ezik mensubu

Gözü yaşlı zamanın, düşlerdeki efsunu

Hayal olmuş tâlihin, tortulaşmış yosunu

İsimsizlere isim, nâm verir bu şehir

Sevmediğine acı, gam verir bu şehir.

Ah bu şehir, bu şehir; sevgisi coşkun nehir

Manzarası emsalsiz, güzelliğiyse mâhir

Onunla olmak Kevser, onsuz kalmaksa zehir

Hizmet edenlerine dem verir bu şehir

İhânet edenlere gam verir bu şehir.

Yedi tepede sönmez meşâle ezel, ebet

Ayrılığı idamlık, muhabbeti müebbet

Sevenlerine yârdır, bilinsin ilelebet

Derde devâ, hastaya em verir bu şehir

İhânet edenlere gam verir bu şehir.

23-09-2000', 'Bir şehir ki; âlemde yoktur dengi, benzeri Baygın baygın, herkesin ona bakar gözleri  Bakışları mest eder, tutuşturur özleri Sevdiğine kendi...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-destan-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Zamanı', 'ask-zamani-aysun-erat-0di0b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk, zamanın ötesinde bir yerde,

Şaşırmış gözlerle bakıyor yeryüzüne

Kim yaşıyor onu dolu dizgin? 

Zehir zemberek kışların gecesinde.

Asi yürekler kovalıyor durmadan,

Miğferli yiğitler arıyor savaşın ortasında.

Akan kan mı? O mu damarlarda? Soruyor durmadan.

Nasıl yaşamaz ki insan aşkı? 

Işığı kör edici, kendi büyüleyici…

04/2005', 'Aşk, zamanın ötesinde bir yerde, Şaşırmış gözlerle bakıyor yeryüzüne Kim yaşıyor onu dolu dizgin?  Zehir zemberek kışların gecesinde. Asi yü...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ask-zamani-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İstanbul Sevdalısı', 'bir-i-stanbul-sevdalisi-abdulkadir-karaman-gw1bd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nazlı bir güzeldi o, bahtında yazı idim

Hüsnüne yüreğimin yanık avazı idim

Her şeyimi uğruna vermeye râzı idim

Belli değil süresi, tutuşturdu yanarım

Yazık ki ayırdılar, özlemiyle kanarım.

Sevdâlılara durak, düşkünlere limandı

Hissizlerin elinde teli kırık kemandı

Her seheri hikaye, her mehtâbı romandı

Sisler içinde kaldı içimdeki dağlarım

Yazık ki ayırdılar, özlemiyle kanarım.

Kahrolurum küserse, gönlüm bahtına küser

Boğazda doğan meltem, buruk bağrıma eser

Ufkumda gurup idi, ruhumda coşan Kevser

Şimdi hüzün akıtır, Kevser akan pınarım

Yazık ki ayırdılar,özlemiyle kanarım.

Tutuldu fırtınaya, sevdâsında yüreğim

Ahd ettim kavuşmaya, dümenimde özlemim

Ondan sürgünde olmak, girdabım ve elemim

Kimse bilmez hicranla için için ağlarım

Yazık ki ayırdılar,özlemiyle kanarım.

Yedi tepede yedi meşalemdi, yanardım

Ey şehir! Aşkın için herkese gül sunardım

Sana hor bakanları hor görürdüm, kınardım

Gülşenim hazan şimdi, viran bahar bağlarım

Yazık ki ayırdılar,özlemiyle kanarım.

Sanmam âlemde başka bulunsun bir benzeri

Bilirim ki âlemin ondadır aç gözleri

Söndüremem, içime atmış sevdâ közleri

Böyle yanmak zor mu zor, şaşkınım, bîkararım

Yazık ki ayırdılar,özlemiyle kanarım.

23-09-2000', 'Nazlı bir güzeldi o, bahtında yazı idim Hüsnüne yüreğimin yanık avazı idim Her şeyimi uğruna vermeye râzı idim Belli değil süresi, tutuşturd...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-istanbul-sevdalisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ziyan', 'ziyan-ozgur-kokturk-9eqss', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine gece

Yine yalnızım

Yine hayâlinle başbaşayım

Nasıl da suskunum

Nasıl da zavallı

Ve ne kadar pervasızca

Utanmazca şiirler yazabiliyorum

Bir anlık bakışından ilhamla

Bir kelimen nasıl da yetiyor ömrüme

Dudaklarından süzülen bir harf

Nasıl kuşatıyor benliğimi

Ne uyku var gözümde

Ne de içimde isyan

Sensiz geçen her saniye

İsraf

Ziyan...', 'Yine gece Yine yalnızım Yine hayâlinle başbaşayım Nasıl da suskunum Nasıl da zavallı Ve ne kadar pervasızca Utanmazca şiirler yazabiliyorum ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ziyan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah İstanbul..', 'ah-i-stanbul-burhan-kucuk-slbc6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah İstanbul..

		 

		 Bir akşam üstü,hüzün ve sen

		 Aklıma düştün Ah İstanbul

		 Kadıköy de kafe denizatında

		 Dinlersin tangonun güzelliğini

		 Yanında İstanbul’un en kral kızı! ... 

		 Oturup karşıya bakarsınsın

		 Bütün ihtişamıyla Sultan Ahmet

		 Ve deniz serili minarelerin arasından

		 Tatlı bir vapur çığlığı

                                 Kaplar tüm boğazı

		 Kıyısında martılar 

                                 Yem kapma telaşında

		 Bir de kızları İstanbul''un

		 Demezler mi sevdiğine bağışlasın 

		 Zorda bırakırlar insanı

		 Takılırsın koyu mavi gözlerine

		 Tüter burnuna boğazın iyot kokusu 

		 Karşıda Orta köy telaşı

		 İstisnasız kedileri besleyen kız...

		 Sallanıverir geçerken köprüsü

		 Meze masasında dansöz misali

		 Kafayı çekersin galata da

		 Nefis olur balıkla rakısı

		 Ah İstanbul...

                                Yine çıkardın beni baştan..... 

                         		 

		 Burhan KÜÇÜK

                                 Kdz.Ereğli', 'Ah İstanbul.. 		  		 Bir akşam üstü,hüzün ve sen 		 Aklıma düştün Ah İstanbul 		 Kadıköy de kafe denizatında 		 Dinlersin tangonun güzelliği...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ah-istanbul-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balık', 'balik-sitki-gokmen-3xovt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Derinlerde yüzen büyük balık,

Sen hiç kırmızı güneş gördün mü? 

Mavi renkli çim, 

Mor açan gül,

Siyah yapraklı ağaç,

Aşk kokan rüzgar soludun mu? 

Peki ya yar kokan su içtin mi? 

Sen hiç düşlerinde kanatsız uçtun mu aya? 

Kısaca aşık olup denizlerde boğuldun mu? 

(ANTALYA 25 MART 2005 01:30)', 'Derinlerde yüzen büyük balık, Sen hiç kırmızı güneş gördün mü?  Mavi renkli çim,  Mor açan gül, Siyah yapraklı ağaç, Aşk kokan rüzgar soludu...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/balik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal', 'hoscakal-ozgur-kokturk-lah5u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ecelin çığlığı kulaklarımda

Yankıları beynimin kıvrımlarında

Uzat ellerini demiyorum artık

Ellerim kabir sıcaklığında

Usul usul gözlerim kapanıyor

Kanım iliklerimde işte donuyor

Sabahım yok, sabahın bensiz

Gecenin metresi güneş de gidiyor

Bu içimdeki son ihtilâl

Aslında her ölüm bir intihâl

Çalıyoruz geleceği geçmişten

Yarın senin olsun, sen de hoşçakal...', 'Ecelin çığlığı kulaklarımda Yankıları beynimin kıvrımlarında Uzat ellerini demiyorum artık Ellerim kabir sıcaklığında Usul usul gözlerim kap...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hoscakal-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bank', 'bank-sitki-gokmen-uf44m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir bank koydum.

Deniz kıyısındakibir yolun kenarına,

Ahşap bir bank.

Bir ağacın dibi,

Tam da gölge altı.

Demir ayaklı bir bank.

Ara sıra coşan denizin taneleri vurur üstüne.

Bazen kuşlar,

Üstündeki simit kırıntılarını almaya,

Bazen bir bahar günü gençler,

En yalın ve çıkarsız aşklarını anlatmaya,

Bazen bir gece yarısı berduşlar,

Elerindeki şarabın son zerrelerini içmeye,

Bazen ise sonbaharlarını yaşayan yaşlılar,

Geçmişlerindeki mutluluklarını yad etmeye gelecekler.

Kimi zaman ise ayrılıklar konuşulacak üzerinde,

Mutluluklar konuşulduğu gibi.

Belki ben gelirim bir gün sevinçli veya kederli,

Bu deniz kıyısında,

Bu ağaç dibinde,

Bu ahşap bankta,

Ne yaşanırsa yaşansın onu oraya ben koydum.

(ANKARA 24 HAZİRAN 2003 00:35)', 'Bir bank koydum. Deniz kıyısındakibir yolun kenarına, Ahşap bir bank. Bir ağacın dibi, Tam da gölge altı. Demir ayaklı bir bank. Ara sıra co...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bank-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilerim ki! .. (güzel dilekler)', 'dilerim-ki-guzel-dilekler-zafer-yazici-71sqh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dilerim ki; 

Bir sabah uyandığında, 

Seni ilk karşılayan 

Açık camdan içeri giren

Rüzgar olsun

Yazdan kalma..

Kuş senfonisi kulağının pasını alsın

Burnunun direğini sızlatsın çiçek kokuları

Güneş görsün, üşüyen yerlerin..

Burnunun ucunda bir kelebek olsun

İlk gözlerini açtığında! 

Rengarenk bir kelebek, 

Kanatları ebem kuşağı..

bir çift göz, sımsıcak gülüşlü! ..

Kalktığında gerinip sonrası; 

Ellerinden tutsun uğur böceği 

Ve eşlik etsin sana kahvaltı için

Ve sen ona tereyağlı ballı ekmek ver,

Annen, terlik papuç alsın yolculuk öncesi

Sonra da ardından bir tas su dök

Geriye dönüşleri için, yolcunun! ..

Yaşadığınca; 

Dört yapraklı yoncalar açsın ömrüne! 

zamanlı zamansız

Ve hiç gitmeyecek bir sevgili ile

Doğsun aşk gönlüne! ..

Hiç ağıtlı türküler söylemeyesin

Sılaya, mektuplar hiç yollamayasın! 

Ve bir şeylerin eksikliğini hiç duymayasın

Bir gülüşe hasret kalmayasın

Yalnız geceler hiç görmeyesin

Göz yaşların hüzünden, hiç akmasın! 

Dilerim ki hiç,

Hiçbir şey için geç kalmış olmayasın

Sevgili! ..

(Aşık, Dost, Yoldaş, Arkadaş! …)

“dilerim ki hiçbir zaman bet bir dua almazsınız! ..”', 'Dilerim ki;  Bir sabah uyandığında,  Seni ilk karşılayan  Açık camdan içeri giren Rüzgar olsun Yazdan kalma.. Kuş senfonisi kulağının pasını...', ARRAY['Türk Edebiyatı','Şiir','Zafer Yazıcı']::text[], 8.5, '{"poet":"Zafer Yazıcı","poet_slug":"zafer-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/dilerim-ki-guzel-dilekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-sitki-gokmen-4k0ka', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün gece de seni düşledim,

Bembeyazdı elbisen bir tanem,

Sen bir tanrıça kadar güzel.

Uçuyorduk sanki kuşlar gibi.

Dansımızı ediyorduk bulutlarda.

Ne mutluydum tanrım dün gece.

Uyanıncaya kadar yatağımda.

(ANKARA  MART1986-29 MART 2005)', 'Dün gece de seni düşledim, Bembeyazdı elbisen bir tanem, Sen bir tanrıça kadar güzel. Uçuyorduk sanki kuşlar gibi. Dansımızı ediyorduk bulut...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dus-113-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-sitki-gokmen-kzxq2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin geç bir saatinde,

Senden uzakta,

Seni düşünüyorum.

Gözlerim noktalarda ararken seni,

Gönlüm dolu hasretinle.

Akşamın doğan karanlık krallığında,

Beynimin her hücresi sana aşıkken,

Kalbimin her zerresinde seni istiyor.

Yalnız seni düşünüyor,

Sensiz fakat seninle dolu geceler yaşıyorum.

(ANKARA  ŞUBAT 1986-18 MART 2005)', 'Gecenin geç bir saatinde, Senden uzakta, Seni düşünüyorum. Gözlerim noktalarda ararken seni, Gönlüm dolu hasretinle. Akşamın doğan karanlık ...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gece-146-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebek', 'kelebek-sitki-gokmen-uefwn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Resimler yaptım bir günlük hayatlara,

Şiirler yazdım tülsü kanatlara,

Umutlar yükledim incecik ayaklara,

Ve saldım havaya.

Gittikleri her yerde resimlerim asılacak,

Her kanat çırpışında şiirlerim dillenecek,

Ve umutlarım ayak izlerinde taşınacak,

Hayatları günlük olsa da aşkları yaşayacak,

Ve gönderdiklerim sana kadar ulaşacak.

Nerde bir kelebek görsen,

Sevgimi görecek,

Kanatlarında şiirlerimi dinleyecek,

Yarınlar için günlük hayatları gözleyeceksin.

(ANKARA 18 MART 2005 12:15)', 'Resimler yaptım bir günlük hayatlara, Şiirler yazdım tülsü kanatlara, Umutlar yükledim incecik ayaklara, Ve saldım havaya. Gittikleri her ye...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kelebek-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızlarıma', 'kizlarima-sitki-gokmen-o8lqo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuşlar ağaçlarda,

Ağaçlarda yuvalar,

Yuvalarda yavrular.

Yavrular çok küçük,

Yavrular çok güçsüz.

Yarına hazırlanıyorlar.

Kırmızı karınları,

Çıplak bedenleriyle.

Bugün anneleri beslese de,

Öğrenecekler uçmayı,

Uçacaklar yakında.

Yakında yeni ağaçlara,

Yeni yuvalar yapacaklar.

Yeni yuvalarda yeni yavrular olacak.

Kızlarım da öğreniyorlar 

Bugün hayatı,

Yarın onurlu yaşamı.

Her ne kadar biz yardımcı olsak da bugün,

Onlarda uçacaklar dünyalarına.

Öğrenince savaşı.

Onurlu yarınlar için.

(ANKARA 10 TEMMUZ  2003 01:15)', 'Kuşlar ağaçlarda, Ağaçlarda yuvalar, Yuvalarda yavrular. Yavrular çok küçük, Yavrular çok güçsüz. Yarına hazırlanıyorlar. Kırmızı karınları,...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kizlarima-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mak', 'mak-sitki-gokmen-gaatm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir çiçek,

Hayattan bir sayfa.

Sevmek,

Ve bütün bir ömre sığdırmak,

Günler dolmak onunla,

Korumak,

Her şeyden ürkerek,

Dua etmek solmasın diye,

Ve biten ömrün ardından,

Yeni bir çiçek,

Belki kırmızı,

Belki mavi? 

(ANKARA 1987-16 MART 2005)', 'Bir çiçek, Hayattan bir sayfa. Sevmek, Ve bütün bir ömre sığdırmak, Günler dolmak onunla, Korumak, Her şeyden ürkerek, Dua etmek solmasın di...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Örümcek Sevişmelerin İhanetine Bulanan Bir Aşk Öyküsü', 'orumcek-sevismelerin-i-hanetine-bulanan-bir-ask-oykusu-atilla-guler-w7zp1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sevişmelerin koynunda yandı gerçekliği duyguların

koyuverdin arsızlığını susamışlığının

sıyırdın sızlanmalarını yüreğin

vur/kaç

ye/bitir

dilinde yatan zehri saldın damardan içeri

çekildin

inine

hiç dinmedi arzular

yeni bir kurban

yeni bir savunmasız sağanağı saflığın

yemyeşildi haykırışları baharın

istenmedi

ısrarında yitti sevişlerin/sevmeyişlerin

ne koyusu vardı

ne açığı

renksiz bir geceye kurban gitti bekareti

beklentinin

sığınılan her yalana bir çentik

bu kaç oldu

kaçıncı sesleniş -sözüm ona-sevgiliye

kaçıncı terk edişin

terk edilişin

sırtlanın sırtına vurdu sahte sevdanın sinsiliği

geceye beş kala yakıldı odu günahların

ardından sallanan bir el bile yokken

otobüste son veda

“hadi geç kalıyorsun/kalk artık”

sonrası bir muamma

yangınlar çabuk söner

izlerinde birikir köz

yanar

yakar

bir gün

ele verir kendini

yalan sırıtışların

yalan sevecenliği

sen

yalan hayatın(ın)   içinde

örümcek', 'sevişmelerin koynunda yandı gerçekliği duyguların koyuverdin arsızlığını susamışlığının sıyırdın sızlanmalarını yüreğin vur/kaç ye/bitir dil...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/orumcek-sevismelerin-ihanetine-bulanan-bir-ask-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neydi', 'neydi-sitki-gokmen-f44c5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırmızıyı mı severdim, yoksa sarımı? 

Galiba elma şekerinden olacak kırmızıydı,

Beklide horoz şekerinden sarı.

Pembeyi de sevmez değildim Ayşe’nin elbisesinden.

Peki ya misketlerimin  mavisi,

Gökyüzünün laciverdi, 

Bulutların beyazı,

Renklerle mi başladı bilmem gönlümün hovardası,

(ANKARA 04 EKİM 2004 11:20)', 'Kırmızıyı mı severdim, yoksa sarımı?  Galiba elma şekerinden olacak kırmızıydı, Beklide horoz şekerinden sarı. Pembeyi de sevmez değildim Ay...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/neydi-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-sitki-gokmen-zx1xs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimizdeki adalet ve sevgi bir kuş.

Uçmuş gitmiş.

Kalmamış geride barış.

Hep yalan hayat.

Ölüm bir kurtuluş,

Bu pislikten bir kaçış.

Her şey sahte.

İlişkiler yapmacık.

Yaşananlar öylesine

Amaç nerede peki,

Aşk nerede? 

Barış nerede? 

Dünya batıyor saat, saat.

Uzaklaşıp insanlıktan,

Ölmeden ölüyoruz,

Yaşamadan bitiyoruz,

Peki niçin solduruyoruz,

Yeni yepyeni,

Senin, benim, herkesin ihtiyacı olan,

Umut çiçeğini? 

Bize sevgi ve direnme gücü verecek,

Ölümü düşündürmeyecek,

Kaybolanlarımızı kazandıracak,

Ve tohumu içimizde  olan,

Sadece sevgiyle büyüyen,

Kurtuluşa çıkan en kısa yol.

Ama inanıyorum ki bulunacak bir gün,

O gün ölümü bile yenip ey insan,

Hürsün.

(ANKARA ARALIK 1986-18 MART 2005)', 'İçimizdeki adalet ve sevgi bir kuş. Uçmuş gitmiş. Kalmamış geride barış. Hep yalan hayat. Ölüm bir kurtuluş, Bu pislikten bir kaçış. Her şey...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/olum-167-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-sitki-gokmen-tijwt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiir yazdım yine sensizlik üstüne.

Öylesine başladım gecenin bir vakti.

Ve öylesine geldi kelimeler dilime.

Ve öylesine devam etti ardı sıra.

Yazarken ağladım sensizlikten.

Okunurken ağlatmasınlar diye.

(Ankara 06 Mart 2005 03:15)', 'Şiir yazdım yine sensizlik üstüne. Öylesine başladım gecenin bir vakti. Ve öylesine geldi kelimeler dilime. Ve öylesine devam etti ardı sıra...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sensizlik-170-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soru', 'soru-sitki-gokmen-5ynld', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne diye söyle,

Bu kavga niye? 

Kime karşı,

Ve neyle? 

Mutlu yaşamak varken,

Sevmek varken,

İnsanı,

Doğayı ve her şeyi,

Şu az zamanda,

Kırılar bu kalpler niye? 

(ANKARA NİSAN 1985-18 MART 2005)', 'Ne diye söyle, Bu kavga niye?  Kime karşı, Ve neyle?  Mutlu yaşamak varken, Sevmek varken, İnsanı, Doğayı ve her şeyi, Şu az zamanda, Kırıla...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/soru-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suç', 'suc-sitki-gokmen-jrw5v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kadınlar girmekte istemesem de beynime.

Beynimin kapılarını kapatsam da,

Gözlerim de kapalı yaşayamam ya! 

Alnıma mı yazmam lazım bilmiyorum; 

Göğüsleri seviyorum.

Sevmeyen var mı; ne yalan onu da merak ediyorum.

Neden bakıyorsun diye sormasınlar sakın.

Gördüğümün ötesine bakamam,

Gözlerimle de kimseyi soyamam.

Suç bende mi sen gösteriyorsan? 

(ANTALYA 24 MART 2005 01:00)', 'Kadınlar girmekte istemesem de beynime. Beynimin kapılarını kapatsam da, Gözlerim de kapalı yaşayamam ya!  Alnıma mı yazmam lazım bilmiyorum...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/suc-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usta', 'usta-sitki-gokmen-gswar', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökyüzüne saldığın uçurtmalarla,

Çocukluğumun özlemiydin.

Sevginden sevgini verdiğin,

Yirmi yedimde baba dedim.

Sevginden sevgini verdiğimde,

Yirmi sekizimde dedeydin.

Bizim Sevinç''imiz,

Senin torunundu.

Kırk birinde merhaba derken hayata,

Yoksun yanımda.

Ne özlem bitti,

Ne baba kaldı,

Ne de dede.

Sen ulaşılmaz oldun be USTA.

(Antalya 25 Ocak 2005)', 'Gökyüzüne saldığın uçurtmalarla, Çocukluğumun özlemiydin. Sevginden sevgini verdiğin, Yirmi yedimde baba dedim. Sevginden sevgini verdiğimde...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/usta-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşadıklarım ve Gençlik Heyecanım', 'yasadiklarim-ve-genclik-heyecanim-sitki-gokmen-d07vj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gençliğim bir geminin limanlarda bıraktığı yükleri gibi,

Arkada, 

Ve uzak.

Oysa ne yakın gençlik hatıralarım.

Ne kadar yakın ilk öpüşmeler,

Heyecanla yapılan ilk dans, 

Beklemeler köşelerde,

Ali amcaların evinin önünde ne çok beklemiştim.

Sarı saçlının geçişini.

Çok uzak değil ki onlar,

Bilemediniz geçen ay gibi daha,

Dostların yüzleri ve sesleri bile yakın,

Dostlar ya biz çok ihtiyarladık,

Ya da zaman bizi aldatarak çabuk geçti.

	

(28 Mayıs 2003 ANKARA)', 'Gençliğim bir geminin limanlarda bıraktığı yükleri gibi, Arkada,  Ve uzak. Oysa ne yakın gençlik hatıralarım. Ne kadar yakın ilk öpüşmeler, ...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yasadiklarim-ve-genclik-heyecanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine', 'yine-sitki-gokmen-gu75k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kapkara bir gün yine,

Kaybolmuş ümitlerin ardından; 

Acı dolu,

       Yalnızlık dolu,

              Göz yaşı dolu.

Biten ümitlerle beraber, 

Ortaya çıkan,

Acı gerçek, soğuk dolu.

(ANKARA EKİM 1986-29 MART 2005)', 'Kapkara bir gün yine, Kaybolmuş ümitlerin ardından;  Acı dolu,        Yalnızlık dolu,               Göz yaşı dolu. Biten ümitlerle beraber, ...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yine-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yük', 'yuk-sitki-gokmen-ad442', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kızıldı saçları.

Güneşin doğumuna gebe gökyüzü gibi,

Yüzündeki hüzün.

Gözlerindeki keder yaşlandırmış gibiydi.

Henüz yirmi beş bilmediniz yirmi sekizindeydi oysa.

Onu ilk omzumda ağlarken tanıdığımda,

On ikinci günüydü tanışmamızın.

Bir yabancıyken dost olmuştuk.

Paylaşılan dertler onu hafifletmiş,

Beni yormaya başlamıştı.

Bir anda güldü, 

Sonra ağladı,

Gülüşüm benim içindi dedi.

Sayende bir dost kazandım.

Ağlamam ise senin için,

Benim çözemediğim sorunlarım sana da yük.

(NİSAN 2003 DİYARBAKIR)', 'Kızıldı saçları. Güneşin doğumuna gebe gökyüzü gibi, Yüzündeki hüzün. Gözlerindeki keder yaşlandırmış gibiydi. Henüz yirmi beş bilmediniz yi...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yuk-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçmasapan', 'sacmasapan-bilgun-gungor-k0oo3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben seni bana sakladım

Gözlerinin gönlümde açtırdığı çiçeklere inat

Bir demet papatya topladım 

Terkedilmiş dağ yamaçlarından

Güz yapraklarını kirpiklerine buladım

Hepsi yeşerdiler.

Umarsız gözlerinin perdelerine inmiş 

Sabah mahmurluğu

Bir seher vakti

Solmasını izlediğim ortancalar

Ve eski zamanların 

Dibi yanmış çaydanlıkları

Bunlar değil miydi? 

Beni sana bağlayan

Hepsini alacakmışsın giderken

Yağma yok

Ben onları da bana sakladım.

Kalabaklığın verdiği yalnızlık içinde

Ve el değmemiş eski bir kasabanın

Tozlu yollarını arşınlarken

Ben seni bana sakladım

Sözlerinin gönlümde açtığı yaraya inat

Bahar yapraklarını kelimelerine buladım

Hepsi sarardılar

Ben seni bana sakladım

Merak etme

Gözlerin en emin yerde saklı

Gömleğimin sol üst cebinde

Hala gitmek mi istiyorsun? 

O zaman gözlerin bende kalsın

Sen, sözlerini al ve git... 

                                              06.06.1998', 'Ben seni bana sakladım Gözlerinin gönlümde açtırdığı çiçeklere inat Bir demet papatya topladım  Terkedilmiş dağ yamaçlarından Güz yaprakları...', ARRAY['Türk Edebiyatı','Şiir','Bilgün Güngör']::text[], 8.5, '{"poet":"Bilgün Güngör","poet_slug":"bilgun-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sacmasapan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor', 'zor-sitki-gokmen-f5vg0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Söylemek isteyip de 

		Söyleyemediğin,

Yazmak isteyip de

		Yazamadığın,

Arayıp ta 

	   Bir şey bulamadığın

			Seninde oldu mu? 

Peki ya; 

	Çok sevip de 

		Ayrıldığın oldu mu? 

Bilemezsin sen,

Sevgiyi

Tanımamışsın  çünkü.

Tatmamışsın sen aşkı.

Düşünmemişsindir hiç karamsarlığı.

İnan; 

Konuşmak zor geldiğinde,

Ve hele kimse yoksa yanında,

Denizdeki bir sandal gibiysen,

İçindekileri haykırmak isteyip de,

Haykıramıyorsan,

Yine en büyük dostundur

		Yalnızlığın.

Sen bilemezsin bebeğim bunları.

İşte onun için,

Yalnız onun için bir tanem

			Çok zor oluyor,

O iki güzel sözcüğü söylemek.

(ANKARA KASIM 1986-18 MART 2005)', 'Söylemek isteyip de  		Söyleyemediğin, Yazmak isteyip de 		Yazamadığın, Arayıp ta  	   Bir şey bulamadığın 			Seninde oldu mu?  Peki ya;  	Ç...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/zor-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Melek', 'kayip-melek-ozlem-yilmaz-8eowt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Olsaydı bir diyarım eğer

Bu kadar siner miydi ruhuma hiçbir yere ait olamama hissi

Ya da savrulur muydum rüzgarda bir kum tanesi gibi

  

Olmasaydı o yitik zaman

Büyür müydüm bir anda her yıl beş yaş yaşlanma pahasına

Ya da izin verir miydim her geçen saniyenin ruhumu soldurmasına

Olsaydı bir ismim

Gerçekten yakıştırabileceğim şu benliğime

Dönüşmezdim bu şehrin ve bu bedenin kayıp meleğine... 

  

(6 Nisan 2005)', 'Olsaydı bir diyarım eğer Bu kadar siner miydi ruhuma hiçbir yere ait olamama hissi Ya da savrulur muydum rüzgarda bir kum tanesi gibi    Olm...', ARRAY['Türk Edebiyatı','Şiir','Özlem Yılmaz']::text[], 8.5, '{"poet":"Özlem Yılmaz","poet_slug":"ozlem-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kayip-melek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Erkek Adamım', 'ben-erkek-adamim-kemal-cakir-tuofl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Daha yeni oturmuştum masama

Rakımı da  mezelerimi de 

Yenice almıştım karşıma

Bu işleri hep ben yaparım da.

	

O gün efkar dağıtmak istiyordum

Biraz da mazi olmuş, köhnemiş 

Hatıraları yaşamak. 

Ama ne gezer! 

Yine başımda; 

Her zaman olduğu ve yaptığı gibi 

Dikildi karşıma.

Yüzünden akan bin parça

Sanırsınız rahmetli kaynanamı

Bendim öbür dünyaya yollayan,

Ya da bendeki dertleri oydu yaşayan.

	

Şöyle bir uzandım bir yudum almak için; 

Neler söylemedi, 

Neler yapmadı ki o mel'' un! 

Gözlerime baka baka.

Yine de içtim. 

Erkek adamım ben.

Ne ondan korkarım, ne de kendimden.

İyi geldi ilk yudum. 

Kendimi toplar,

Maziyi hatırlar gibi oldum birden.

Neyse ki fazla kalmadı başımda

Öbür  odaya geçti, telaş içinde aniden.

	

Rahattım...

Kadehi ikinci kez doldurdum. 

İşini bitirmiş olacak  ki,

Yine dikildi karşıma; 

''Boşver, aldırma '' dedim 

Kendi kendime.

Erkek adamım ben 

Ne ondan korkarım ne de kendimden,

Bir dikişte götürdüm bu kadehi de.

	

Yine birşeyler söylendi

(Delimidir ne!) 

Bakmadan benim kim,

Kendisinin ne olduğuna.

Böylesi bir hatun 

Mumla arasan bulunmaz da 

Biz bulmuşuz nasıl başardıksa.

Kafam iyi olur gibi oldu ya! 

''Bir iki lokma birşey getirip, koy''

Dedim masama.

Nerden söyledim, nasıl unuttum bir ara,

''Sen misin bunu söyleyen ayyaş'' deyip,

Öyle bir indirdi ki  oklavayı başıma,

Meğer ilk kadeh sonrası

Oklava almak için geçmiş öbür odaya.

Nevrim döndü, fena oldum 

Bir ara içimden bir ses dedi ki! 

''Çek silahı, uzat şunu 

boylu boyunca yere.''

Kulak vermedim bu sese,

Hemen düşündüm; 

''Ne yapacaksın erkek de olsan,

karşındaki kadındır'' dedim

Aklımı almak geldi başıma.

Bir- iki sefer daha böyle yapmıştı 

Hatta daha da fazlasını.

Bu nedenle dikiş attırmıştım

Yarılan  sağ kaşıma.

	

Ne ise, ''ya sabır ya sabır'' diye diye

Bir-iki kadeh daha içip

Yanaştım mazinin o köhne limanına.

Demirleyip hayal gemisini oraya,

İndim aşağıya.

Şöyle biraz açıldım

Onunla gezdiğimiz kumsala doğru.

Yenice basmıştı ayaklarım kuma

Kendimi de çok iyi hissediyordum.

Yalnız değildim, başbaşa kalmış

Birşeyler konuşmaya başlamıştım

Onunla:

O unutulmaz öpüşlerden, 

Sabırsız bekleyişlerimizden... filan 

sözediyorduk.

Niçin ayrıldığımızı hatırlamaya çalışırken

Güneş çarpması gibi bir hal oldu bana; 

Sanki dünya başıma yıkılmıştı, aniden.

Onun beni aldatışını hatırladım

Her zamanki süslü sözlerinin ardından.

Fırladım deliler gibi  hemen yerimden,

Bir sağa bir sola bakınıp 

Döndüm gerçeğe yeniden.

Bir iki güzel söz söylemek için

Yaklaştım yanına,

Sarıldım onun oklava tutan ellerine.

İçkimi zehir edip burnumdan getirdiği,

Üstelik de oklavayı başıma indirdiği bile 

Gelmeden aklıma. 

Bir kere daha vurmasını istedim  bana.

Lakin ben erkek adamım

Dövülmeye katlanırım ama, 

Aldatılmaya asla.

O mendebur hiç aldatmadı beni.

Zaten böyle yapsaydı

Alabilir miydi oklavayı eline? 

İlgilenmezdi, bırakırdı beni kendi halime.

Hatta içip, zom olmamı beklerdi 

Çünkü, bu daha çok gelirdi işine.

	

İşte böyle... 

Kendisi gibi sevgisi de delice; 

Bir yandan sever beni 

Canımsın, ciğerimsin der,

Diğer taraftan alır oklavayı eline.

Böyle öğrenmiş herhalde

Telkini de sevgiyi de.

Ne yapacaksın, ne söyleyeceksin? 

Böyle namuslu ve koca kıymeti bilir 

Allahın garibine...', 'Daha yeni oturmuştum masama Rakımı da  mezelerimi de  Yenice almıştım karşıma Bu işleri hep ben yaparım da. 	 O gün efkar dağıtmak istiyordu...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":113,"source_url":"https://www.antoloji.com/ben-erkek-adamim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolum...', 'anadolum-i-mdat-ozcan-2n099', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Toprağına , daşına

Gurbanam Anadolum

Ekmeğine. aşına

Gurbanam Anadolum

Sürmeli gözlerine

Aşk dolu sözlerine

Gışına, yazlarına

Gurbanam Anadolum

Ortasında Gayseri

Yigidin harman yeri

Sanki cennet kevseri

Gurbanam Anadolum

Havasına, suyuna 

Sevdiceğim huyuna

Irmağına, çayına

Gurbanam Anadolum

Anlatamam sevdamı

Dillere destan namı

Siler kederi gamı

Gurbanam Anadolum...', 'Toprağına , daşına Gurbanam Anadolum Ekmeğine. aşına Gurbanam Anadolum Sürmeli gözlerine Aşk dolu sözlerine Gışına, yazlarına Gurbanam Anado...', ARRAY['Türk Edebiyatı','Şiir','İmdat Özcan']::text[], 8.5, '{"poet":"İmdat Özcan","poet_slug":"i-mdat-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anadolum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özür', 'ozur-emre-oguz-jzg6a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimdeki büyüme isteği köreldiğinde

Heyhat! 

Çoktan yarılanmıştı yol

Anladim ki

Daha çıkışta belli oluyor

Kazananlar, kaybedenler

Onca yıldan sonra

Şimdi

Özür diliyorum

Baharini bana oynayan 

Bütün mevsimlerden

Bir yalnız için katlanilabilir izdirap miktari insanlik için öldürücü olabilir', 'İçimdeki büyüme isteği köreldiğinde Heyhat!  Çoktan yarılanmıştı yol Anladim ki Daha çıkışta belli oluyor Kazananlar, kaybedenler Onca yılda...', ARRAY['Türk Edebiyatı','Şiir','Emre Oğuz']::text[], 8.5, '{"poet":"Emre Oğuz","poet_slug":"emre-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozur-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Gizler Kuytularına', 'karanlik-gizler-kuytularina-meral-yagcioglu-zxvnk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aktığında güneş deryaya damla damla

Bastırırken akşamın alaca karanlığı 

Bulutlara saklanınca uyku mahmurluğunda martılar

Yaslanır ayın sisli şavkı pencereye 

Benim için başlar koca bir gün

Geçiririm sırtıma siyah pelerin 

Uçamam, yarasa misali

Asılırım, yüreğimde ibrişimden sancı ipi 

Kadife bir tabutla

Gömerim derinlere hüzünleri

Yanar içten içe gönlüm 

karanlık ışıltılı yalnızlık giysim

Sıyrılır pelerinden

Kucaklar samanyolu tüm ihtişamıyla

Kuş sütü bile mevcut 

Kurulu çilingir sofram

Bir tarafta dolunay, bir tarafta yalnızlık

Tam karşımda büyük ayı

Samanyolu’nun en nadide gülü 

Şerefe der kalkar kadehler

Küçük ayı tüm zarafetiyle

Dumanı tüten kahve servisi

Yapmak üzere beklemede

Gizler, içine alır karanlık

Ne ağladığım görülür, ne de 

Boş kadehteki kızıl mey.

İçimde çalan melodi eşliğinde

Dans ederiz ay ışığı altında

kol kola yalnızlık kavalyem

Alkışlamakta büyük ve takipçisi küçük ayı

Samanyolu tümden ayakta

Baykuşlara yoldaş olur, yaşarım geceleri

Aydınlık ürkütür,göz kamaştıran yakıcı cazibesinde güneşin

Korkarım kaybolup yok olmaktan

Yüreğimde kopan fırtına eser savurur

Gözyaşları sicim gibi iner bağrı açık toprağa

Karanlık gizler kuytularına hüznü

O kuytularda ararım kocaman yürekleri

Esmer yalnızlığa  sırtımı yaslar

Destekler gecenin karanlığı

Gece kuşlarıyla birlikte

Yiteriz samanyolu koynunda

28.04.2003', 'Aktığında güneş deryaya damla damla Bastırırken akşamın alaca karanlığı  Bulutlara saklanınca uyku mahmurluğunda martılar Yaslanır ayın sisl...', ARRAY['Türk Edebiyatı','Şiir','Meral Yağcıoğlu']::text[], 8.5, '{"poet":"Meral Yağcıoğlu","poet_slug":"meral-yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/karanlik-gizler-kuytularina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-salim-diyap-zujdx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'buruşturulup atılan o kağıttaydı yüreğim

kim

ne zaman

neden

kime göndermişti bilmiyorum

ama o yüreğime saplanan ağrıdan mıdır nedir

anladım ki o buruşturulup atılan kağıttaydı yüreğim

beklemişti

arzulamıştı

vermişti karşılıksız sevgilerinde döllediği her duyguyu

iki sürmeli göz hatırına

o yaban mersini kokan yüzüne hürmeten

akdeniz in yorgun mavisine yüz suretini çiziyordu

her gün yüreğimdeki avare çocuk

şimdi tuzundan mıdır nedir

bilinmeyen bir tat var ki Akdeniz de

acı mı acı

kekre mi kekre

yediğim her meyve ham hurmadır

ve zamansız koparılmış dalından

yar

bir bilsen bu can tırmalayan özlemleri

bir bilsen selamların tadını alınmışsa kuş kanadından

ben martıların bile uğramadığı o ada da

selamımı kendi kendime yollarım da

sen bilmezsin

bu selamların bir avuntudan ibaret olduğunu

o buruşturup attığın kağıtta da bir yürek olduğunu

yüreğim

sana gelen her selamın bir yalandan ibaret olduğunu bilsen de umursamasın

sen

selama açsın çünkü

gerçeğe değil

yüreğim

hangi fırtınanın çiçek kıran esintilerinden alabilirdin ki

bu yürek yarısı selamı

o gün doğuşuna eş sima olmazsa

yüreğim

yalanın selamı olur da siması olmaz mı hiç

sevdaya dair her yalana yelken tutan

yürek vuruşlarına inip çıkan gönüllerin

yolgeçen hanı olmuşsa özlemlerin

her gün doğumunda misfirinse o kırlangıç çırpınışlı gözler

yalanın sureti olmaz mı hiç

sen oralı olmasan da yüreğinde allı pullu yalanların elvan şekli yüklüdür

ve sana öyle yakındır ki

saymaktadır iç çekişlerini

artık sen

baharlara beşik sallayan güzel bir simanın süslediği yağmur sesinden anlarsın

güzel bir yüzün kapıyı çaldığını

ufuklarda bulutlanır her an o güzel yüz

oysa sen çoğu zaman sadece rüzgara açarsın kapını

güzel bir simaya açarcasın

ama fark eder ki

o ne denli özlense de yoktur

sen yaratmışsan onu

ve her zaman ondan güzeline yollar döşeyebilirsin yüreğinden

rüzgar gelir rüzgar gider

o esintiler de arzuladığın

çağırdığın

yarattığın

gidici misafirindir artık bahar kokularıyla

gel gör ki o senin kendine söylediğin bir yalandır

ve bu yalana inanmışsındır

inanmışsın

ve tatlar değişmiş hayatında

ekmeğine gül kokusu sinmiştir bir kez

ya açsın artık

ya gülle paylaşırsın lokmalarını gönül sofranda

her lokmada büyür yediğin içtiğin tat

ne yersen gül dür artık

ne içsen bir yudum sevda

ağrıların diner

onarır yaralarını acıların

hiç kimseye elini vermeden kalkarsın ayağa

seni dermanından alıkoyan bu rüzgar kapını her yokladığında

seni bulur o gülün kucağında

Marmaris 

5  Mart 2005', 'buruşturulup atılan o kağıttaydı yüreğim kim ne zaman neden kime göndermişti bilmiyorum ama o yüreğime saplanan ağrıdan mıdır nedir anladım ...', ARRAY['Türk Edebiyatı','Şiir','Salim Diyap']::text[], 8.5, '{"poet":"Salim Diyap","poet_slug":"salim-diyap","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/gul-le-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus', 'yunus-adem-kalinsaz-q1tis', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey Yunus! 

Mavi resimler yap,

Denizin en derin noktasına,

Gümüş sularda coşsun,

Kardeş olan yengeçler

Mehtaba karşı yakamoz şarkıları söylesin

Bu bizim ilk şarkımız olsun

Bu bizim ilk şarkımız 

Bu bizim... 

En can alıcı noktasından

Varsın ahtapotlar kollarını sarsın

Sen ona gülücükler gönder

Sen Emre’nin dostu Yunus’sun

Sen Emre’nin dostu 

Sen...

Yunus’um, peygamberi kucağına al

Nefes ver âb-ı hayattan

Kurtuluşu senin yüreğinde olsun

Kurtuluşu senin yüreğinde

Kurtuluşu...

Ey Yunus

Denizler senin olsun

Dualar senin

Gönlündeki Yunus senin

Sense bizim

Bizse senin

Yunus’um 

Yunus

(18 Mayıs 2004)', 'Ey Yunus!  Mavi resimler yap, Denizin en derin noktasına, Gümüş sularda coşsun, Kardeş olan yengeçler Mehtaba karşı yakamoz şarkıları söyles...', ARRAY['Türk Edebiyatı','Şiir','Adem Kalınsaz']::text[], 8.5, '{"poet":"Adem Kalınsaz","poet_slug":"adem-kalinsaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/yunus-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaklar', 'sokaklar-adem-kalinsaz-fpahq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu şehrin sokaklarında

Bir garip yolcuyum

Arkama rüzgarı ve senin nefesini aldım

Bir de gençlik düşüncelerimi

Yolumuz aydın

Tam gaz gidiyorum

Mevsimsel yağışlara göz yaşlarım karışmış

Çisil çisil yağıyor

Ağlıyor gökyüzü

Ve ben de...

.................

Islanıyorum

İkinci sokaktayım

Hâlâ rüzgar ve nefesin

Ve hâlâ

Göz yaşı ve rahmet

Duygularım yoğunlaşıyor

En taze lise yıllarım

Belleğimde iz bırakan o an; 

Yani sen ve ben

Ben ve çiçek...

Sen ve gül

Ve

Sen ve tebessüm

Ve ben

Rahmani renk kırmızı

Üçüncü sokaktayım

Yağmur ve sen yok

Yanaklarımda kalan birkaç damla...

Gökyüzü ve hayallerim berraklaşıyor

Gerçekler yüreğimde taze bir acı bırakıyor

Sen yoksun bu sokaklarda

Sen yoksun bu şehirde

Ve 

Sen varsın

Senin nefesin

Sokaklar âh sokaklar

Yıllar sonra

Komşuyuz aynı sitede

Çocuklarımız

 Bu sokaklarda saklambaç oynuyor

Sizde hâlâ tebessüm

Bende rahmani renk kırmızı

(20 Mayıs 2004)', 'Bu şehrin sokaklarında Bir garip yolcuyum Arkama rüzgarı ve senin nefesini aldım Bir de gençlik düşüncelerimi Yolumuz aydın Tam gaz gidiyoru...', ARRAY['Türk Edebiyatı','Şiir','Adem Kalınsaz']::text[], 8.5, '{"poet":"Adem Kalınsaz","poet_slug":"adem-kalinsaz","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/sokaklar-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sevdim*', 'sevdim-nilufer-aslantas-poqnz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben, sende seni sevdim,

Ben seni, sende sevdim,

Seni seninle sevdim...

Ben, bende sevdim seni,

Bendeki seni sevdim...

Yeminlerim oldu bozduğum,

Sitemlerim... 

İsyanlarım...

Gözyaşlarım...

Umutlarım...

Hepsi sende, hepsi seninle

Hepsi...

Senin için...', 'Ben, sende seni sevdim, Ben seni, sende sevdim, Seni seninle sevdim... Ben, bende sevdim seni, Bendeki seni sevdim... Yeminlerim oldu bozduğ...', ARRAY['Türk Edebiyatı','Şiir','Nilüfer Aslantaş']::text[], 8.5, '{"poet":"Nilüfer Aslantaş","poet_slug":"nilufer-aslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevdim-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Saatler', 'son-saatler-i-lknur-er-u8uz8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hissediyorum son saatler bunlar

Vakit gelecek yetmeyecek 

İstemek kalmaya

Bir kuş olup uçacağım göklere

Ekmek koysanda benim için pencerene

Gelmeyeceğim

Yemek aş ihtiyacım olmayacak gittiğim yerde', 'Hissediyorum son saatler bunlar Vakit gelecek yetmeyecek  İstemek kalmaya Bir kuş olup uçacağım göklere Ekmek koysanda benim için pencerene ...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/son-saatler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Camın önündeki bir tıkırtıydı', 'camin-onundeki-bir-tikirtiydi-ziya-nizam-pqles', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Camın önündeki bir tıkırtıydı 

Kalbim,

Çıkmayan lodosta 

Sallanmayı unutmuş bir dal sevdam.

Soldan sağa üçüncü soruydu 

Sensizlik

Çözmeyi bilemediğim bir aşktın sen.

			15.02.2005-Salı

			00:32 Avcılar', 'Camın önündeki bir tıkırtıydı  Kalbim, Çıkmayan lodosta  Sallanmayı unutmuş bir dal sevdam. Soldan sağa üçüncü soruydu  Sensizlik Çözmeyi bi...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/camin-onundeki-bir-tikirtiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun Yol Şoförü', 'uzun-yol-soforu-hikmet-kavas-yc9bz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çekti kamyonunu kapıya

uzun yoldan geldi

ırak''tan

çok yorulmuş belli ki

bomba seslerini boğmaktan

kamyonun kornasıyla

çekti kamyonunu

içinde ağlamaklı bir bayram sabahıyla

çekti çekeceği kadar

ya çekmeseydi

bu da var

kimin ekmeğini doğrardı evde çocuklar

şoförün alnıyla doldurulmuş

bakır sahana

çekti sarı kamyonunu şoför

göndere bayrak çeker gibi

kapısının önüne

ve tozlu bir öpücük kaynattı

karısının ağzında

patlamış şamriyeli kaynatır gibi', 'çekti kamyonunu kapıya uzun yoldan geldi ırak''tan çok yorulmuş belli ki bomba seslerini boğmaktan kamyonun kornasıyla çekti kamyonunu içinde...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Kavas']::text[], 8.5, '{"poet":"Hikmet Kavas","poet_slug":"hikmet-kavas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uzun-yol-soforu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninleyim', 'seninleyim-i-smet-barlioglu-llg7s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni Kaf Dağı ‘nın arkasında arıyorum perilerle,

Saba Melikesi Belkis ‘le arıyorum

Babil ‘in Asma Bahçeleri ‘nde,

Eti, Kalde, Asur, Sümer, Akat topraklarında,

Tendürek, Nemrud, Süphan Dağları ‘nda,

Fırat ‘ın, Dicle ‘nin sularında arıyorum,

Sanki iğnemi yitirmişim samanlar arasında

Bulamıyorum.

Zelve ‘de misin,

Göreme ‘de, Üçhisar ‘da mısın,

Torosların harami gibi yol kestiği tırparlarda mısın,

Seyhan ‘la, Ceyhan ‘la mı indin Çukurova ‘ya,

Barbaros ‘un kalyonları gibi mi geçtin Akdeniz ‘den

Ve Ege Denizi ‘nden, değip dokunmadan karaya? 

Bulmak umuduyla bakındım durdum Marmara ‘ya,

Ayvalık ‘ta Şeytan Sofrası ‘ndaki Şeytan ‘a sordum,

Ivrandı, kıvrandı,

Bilemedi.

Benimle birlikteydin,

Göremedi.

Seninleyim, bu dertli başımı alıp her nereye gitsem,

Bir yudum su içsem,

Bir lokma ekmek yesem,

Uyusam yaşlı bir çınarın gölgesinde,

Gökyüzündeki bulutları seyretsem,

Akıp giden sulara bıraksam elimi

Veya göğsümü bir deli rüzgara versem,

Bilmem inanır mısın

Dünyayı tanık göstersem.

(TANRI ÖNCE BENİ YARATTI isimli Serbest Şiirler ''inden > 81-82/100)', 'Seni Kaf Dağı ‘nın arkasında arıyorum perilerle, Saba Melikesi Belkis ‘le arıyorum Babil ‘in Asma Bahçeleri ‘nde, Eti, Kalde, Asur, Sümer, A...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/seninleyim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dileyelim', 'dileyelim-i-smet-barlioglu-nontp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen oradan, ben buradan

Yalvaralım Yaratan ‘a

Avuçlarımızı geniş geniş açıp gökyüzüne,

Tek bir kerecik duyursun bize, lütfedip

Var mıdır kaderimizde gülecek bir günümüz,

Yoksa hep böyle çilelerle mi geçip gidecek

Ömrümüz? 

Nasipte var mıdır el ele verip tutunmamız,

Bakışmamız bir dolu dolu yüzyüze,

Senin tüllere, gelinliklere,

Tellere, duvaklara bürünmen,

Sonra evlenmen benimle, bir tek fişek ‘He’ deyip

Ve arkasından, mutlu bir yaşantı; özlemsiz? 

Ekmeğimiz var imiş, ya ki yok imiş,

Önemsiz.

Varsa da kaderimizde çile, özlem,

Varsa da gidip gelmemekler, gelip de görememekler,

Dikilmişse de aramıza kara dağlar,

Kesmişse de engin uçurumlar yolumuzu,

Kabarmışsa da yüreklerimiz kahve fincanlarında; 

Yaratan bunları değiştiremez mi

Anında? 

Yeter ki; sen iste,

Ben isteyeyim,

Yeter ki; yalvaralım birlikte.

Yapabilirsen söyle

Bileyim.

(TANRI ÖNCE BENİ YARATTI isimli Serbest Şiirler ''inden > 83-84/100)', 'Sen oradan, ben buradan Yalvaralım Yaratan ‘a Avuçlarımızı geniş geniş açıp gökyüzüne, Tek bir kerecik duyursun bize, lütfedip Var mıdır kad...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dileyelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönemem', 'donemem-i-smet-barlioglu-jh7v4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevda koktu yine bu şekersiz kahve,

Sevda koktu yine bu demli çaylar,

Bu kolonyalar, bu lavantalar,

Bu evler, bu dükkanlar,

Durgun ve sessiz denizi süsleyen bu mehtap,

Bu yıldızlar, bu samanyolları,

Sevda koktu yine

Bu bayram davulları.

Karası, beyazı olmaz mı sevdanın? Olur,

Benimki bir karasevda; 

Çilesi karanlığında

Ve elleri

Birer demir kerpeten gibi

Yakamda.

Sen beyazsın, denizden yeni çıkarılmış sedef gibi,

Saçların; rüzgarda dalgalanan başaklar,

Bana bakıyor gözlerinden karanlıklar.

Boyun fidanlardan farksız; 

Körpe, ince, uzunca,

Gönlüm bu güzellik yüzünden düşüyor karasevdaya,

Bakınca.

Geri gitmeye alışkın değilim,

‘Bırak. Git.’ Desen, gidemem,

İki gözüm kör olmuş bir karasevdada,

‘Başkalarını sev,’ Desen ‘yerime’,

Sevemem.

Öyle bir yola girmiş ki iki ayağım birden

Dönemem.

(TANRI ÖNCE BENİ YARATTI isimli Serbest Şiirler ''inden > 85-86/100)', 'Sevda koktu yine bu şekersiz kahve, Sevda koktu yine bu demli çaylar, Bu kolonyalar, bu lavantalar, Bu evler, bu dükkanlar, Durgun ve sessiz...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/donemem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Demişler', 'ask-demisler-esin-liman-i6eya', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi onlara geldiğinde

İkisi de şaşırmış.

Daha önce bir yerlerde görmemişler

Yine de almışlar içeri.

Bütün eşyalarını bir bir serpmiş yüreklerine sevgi.

Bu ikisinin de yürekleri dolmuş.

Yankı yapmıyormuş artık ayak sesleri

Sesler kaybolmuyor,

Yerlerine geçip oturuveriyorlarmış.

Sonra 

İkisine de ağır gelmiş yürekleri

Şimdi her sesin bir anlamı,

Her bakışın sızısı geziniyormuş içlerinde.

Bir de isim koymuşlar bu sızıya,bu anlama

Aşk demişler...

Bu aşk yerleştikçe yerleşmiş,

Büyüdükçe büyümüş

Taşmış içlerinden

Bizimkilere zor gelmiş taşımak.

Uçurum kenarında bir sevgi...

Yanında iki kişi...

Biri çeker mi kolundan 

Kurtarır mı onu? 

Biri iter mi sırtından 

Yuvarlar mı uçurumdan? 

Yoksa ikisi de sarılır mı 

Bırakmaz mı bir daha....', 'Sevgi onlara geldiğinde İkisi de şaşırmış. Daha önce bir yerlerde görmemişler Yine de almışlar içeri. Bütün eşyalarını bir bir serpmiş yürek...', ARRAY['Türk Edebiyatı','Şiir','Esin Liman']::text[], 8.5, '{"poet":"Esin Liman","poet_slug":"esin-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ask-demisler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizem (2)', 'gizem-2-ahmet-agdere-kwfhk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gayri meşru çocuğu olmuş

İsmini Yaşam koymuş

Zannetse de öldü, yaşamış

Ezmiş kendisini yine yaşamış

Memur olsa da yaşama, yaşamış..', 'Gayri meşru çocuğu olmuş İsmini Yaşam koymuş Zannetse de öldü, yaşamış Ezmiş kendisini yine yaşamış Memur olsa da yaşama, yaşamış.....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gizem-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Saçlarımın yüzünü örttüğü geceye yasla başını', 'saclarimin-yuzunu-orttugu-geceye-yasla-basini-emine-deniz-m67rh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saçlarımın yüzünü örttüğü geceye yasla başını... Ey hayatımın kararan noktasında parlayan tütsü gözü aydınlığım. Gel... Gel ki kuruyan uçlarımız yeniden cana gelsin, gel ki delirsin damarda kan.Kurudum kış ayazlarında şerefsiz sevdalardan.Baharım ol gel, mevsimsiz olsun güneşlerim ne çıkar. Yağmurum ol gel, rüzgarsız dağlarda ıslanalım. Yeniden döl versin papatyalar. 

Ne çok baharlar eskittim ben. Senden önce ne yalancı güneşlere aldandım bir bilsen. Gel... Acıyan yaralarım var hala. Hala eksik düşlerim. Tamamla beni. Ne mesafeler eritir içimizdeki alevi, ne yağmur söndürür ormanlarımda çıkardığın yangını. Hani ben mumdum,sen içimde ipim. Sen yandıkça ben eriyorum işte,ben eridikçe sen yan. Bitimsiz olsun bu har... Bitimsiz olsun bu akış içime... Sen nehrim ol, ben denizin. Sana ayırdım en nadidesini tuzumun. Islat dudaklarını ve doyur beni. Rengimi seninle buldum ben, öksüz bırakma gülüşlerimin aydınlığını... Avuçların varsın benzesin göğün yarıklarına, bırak sevinçlerini sokaklarıma. Ayırdım ikimize alnımın en temiz sayfasını, sevişsin diye içimizde incir kuşları... 

Sen gelene dek meyveyi çoktan kesmiş bir incir ağacıydım. Şimdi yeşil bir zeytin döl veriyor içimde. Beyaza bu kadar yakışmamıştır siyah. Bu kadar masum yaşanmamıştır hiçbir günah.Yan! Şimdi yanmak zamanı. Kuduran arzuların, ertelenmiş heveslerin hesap verme zamanı... Şimdi sevmek zamanı... Hesapsızca. 

İşte bahar... İçimde koşan deli taylara yetiş. O kadar hızlı olmalısın ki kurtulamamalıyım ellerinden. Yorulma. Sakın vazgeçme benden. Aydınlığa dönüşecek karanlıklar hatrına, bir yürekte yol alacak iki beden hatrına, terinin mendili tenim hatrına... Gövdende yol alıp raksetsin düşlerim. 

Ben aşka müptela... Akıt damarımdan çekilen kanı... Serseri bir kurşun gibi sokul kalbime. Hoyratça, sessizce, erkekçe... İndir omuzundaki mavzeri, bitir savaşlarını. Bak ben geldim. Sensiz de yaşar dağ yamaçlarında çiçekler, sensiz de gider gemiler... Oysa ben kurumak üzereyim. Akıt suyunu yatağıma. Gel... Gel ki yeşersin siyaha dönen nilüferler tenimde. Gel ki güneşler doğsun bedenimde. 

Mutluyum sevgili, unuttuğum kadar mutluyum şimdi. Yaşamak ağır bir döngüdeyken ve ben boğulmak üzereyken... Artık ölümden söz etmek yok. Bedeninde ölümsüzleşmeden! 

Yüzümün yüzünü gölgelediği günlere kaldır başını. Hiçtik düne kadar unutma... Ben varım yanında. Düşürme umutlarını, düşürme umutlarımı şerefsiz sevdalara. Beni özlemeyi aklından çıkarma. Verecek o kadar çok sevgim var ki daha. Korkak sevdalardan yola çıktım ben. Cesaret sokaklarında yalnız bırakma. 

07.04.2005', 'Saçlarımın yüzünü örttüğü geceye yasla başını... Ey hayatımın kararan noktasında parlayan tütsü gözü aydınlığım. Gel... Gel ki kuruyan uçlar...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/saclarimin-yuzunu-orttugu-geceye-yasla-basini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şüphe', 'suphe-sibel-oner-f8m6l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ş Ü P H E 		

				

Hayalimde bir değil bin manzara				

Her saniye değişiyor çizemiyorum.				

Yüzbinlerce nokta biri anahtar				

İşte o noktayı sezemiyorum.				

				

İçimde duygular karmakarışık				

Okuyup kalemle yazamıyorum.				

Soruları öylesine zor bir imtihan ki; 				

Ne yazıkki çoğunu çözemiyorum.				

				

Dalgalı bir denize düşmüşüm sanki				

Var gücümü kullanıyor yüzemiyorum.				

Ah! Diyorum kaderime neden böyle? 				

Lakin hak yazmıştır kızamıyorum.				

				

				Sibel ÖNER', 'Ş Ü P H E 		 				 Hayalimde bir değil bin manzara				 Her saniye değişiyor çizemiyorum.				 Yüzbinlerce nokta biri anahtar				 İşte o noktay...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/suphe-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretim', 'hasretim-sibel-oner-hffgu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'H A S R E T İ M 			

				

Hasretim herşeye				

Sevgisiz kurumuş çiçek gibi				

Yaşıyorum herşeye				

Tıpki damarda akan kan gibi				

Çiçeğin özlediği su sevgidir.				

Sevdadır gönüllerde taht kuran				

Meyvasıdır sonuca ulaşılan AŞK				

Bende bu viranda olmak istiyorum				

Nedir şu dünyadan çektiğim çile				

Hasretim bir sevgiliye				

En güzel yaşımda çekildim sineye				

Bir yaralı ceylan gibi				

Çektiğim bu acı				

Bir ömür boyu yeter bana				

İstemem artık yeni bir dert daha				

Çekecek gücüm yok artık benim.				

				

				

				Sibel ÖNER', 'H A S R E T İ M 			 				 Hasretim herşeye				 Sevgisiz kurumuş çiçek gibi				 Yaşıyorum herşeye				 Tıpki damarda akan kan gibi				 Çiçeğin ...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hasretim-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oysa Sen? ...', 'oysa-sen-sibel-oner-x439p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O Y S A   S E N? ...			

					

Sevgimi veriyorum sana					

Oen erişilmez zirvesini benliğimin					

Tutkularımı seriyorum yollarına					

Vazgeçip bütün ilkelerimden					

Esiri olmak istiyorum o yeşil gözlerinin								

Kimsenin giremediği kapıları					

Ruhumun zenginliklerini harcıyorum uğruna					

Bir yana bırakıyorum,yaşadıklarımı,yaşayacaklarımı					

Oysa sen? ...					

Bütün gizemlerimden vazgeçip hayatımın					

Bir insana yapabileceğim en büyük iyiliği yapıyorum.					

İşte en sakıncalısını itiraf ediyorum sırlarımın					

Seni seviyorum.					

Oysa sen? ...					

Bütün çiçeklerinin dünyanın					

Erişilmez bütün mücevherlerini					

Sana sunmak istiyorum					

Bir yana bırakıp engel olan her şeyi					

Sana mutluluğu yaşatmak istiyorum					

Oysa sen? ...					

					

				Sibel ÖNER', 'O Y S A   S E N? ...			 					 Sevgimi veriyorum sana					 Oen erişilmez zirvesini benliğimin					 Tutkularımı seriyorum yollarına					 Vazge...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/oysa-sen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan aşkı', 'vatan-aski-i-lhami-arslantas-salrz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gelin kin nefreti atalım özden 

Yürekleri alıp düştüğü közden 

Şöyle kendimizi geçirip gözden 

Acı dilimizi bal eyleyelim 

Saygıyla sevgiyle yurdumda barış 

Vatan toprağında hep karış karış 

Olsun mutluluğa sevgiye yarış 

Çalıyı dikeni gül eyleyelim 

Haydi kucaklaşın işte bu bahar 

Olmadı olamaz düşmanlıkta kar 

Gözü bu vatanda Amerika var 

Yırtık çulumuzu şal eyleyelim 

Bu günden tezi yok barış zamanı 

Fakir ocağının tütsün dumanı 

Tarihten silelim zan’ı, güman’ı 

Yurdu çiçek açan dal eyleyelim 

Şiarımız olsun sevginin adı 

Gitmesin kimsenin ağzının tadı 

Her zaman ozanın budur inadı 

Bileği bükülmez kol eyleyelim 

Hep beraber göze alıp hedefi 

Yurda bezeyelim inci sedefi 

Düzeltelim gelin eğriyi, sefi 

Güzel yanağında hal eyleyelim 

Der İhami her gün eriyor zaman 

Hatırı, gönül ü kırmayın aman 

Kalksın başımızda şu kara duman 

Gelin yolumuzu yol eyleyelim', 'Gelin kin nefreti atalım özden  Yürekleri alıp düştüğü közden  Şöyle kendimizi geçirip gözden  Acı dilimizi bal eyleyelim  Saygıyla sevgiyle...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/vatan-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yada...', 'yada-sibel-oner-92a97', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'YADA...			

				

Bir zamanlar sevmiştim				

Yada...				

Sevdiğimi zannetmiştim				

Bir zamanlar sevilmiştim				

Yada...				

Sevildiğimi inanmışım				

Bir zamanlar mutluydum				

Yada...				

Öyle hissetmişim				

Bir zamanlar yaşamıyordum				

Yada...				

Yaşıyor sanmışım				

				

Ama; şimdi herşey değişti				

Bende yeni bir kişilik				

Yeni bir hayat				

Bekliyor kollarına				

				

Aç kollarına hayat tut beni				

Bugün yeniden doğdum.bırakma beni				

Bekle kelebek geliyorum				

Uçmak istiyorum tutma beni				

				

				

			Sibel ÖNER', 'YADA...			 				 Bir zamanlar sevmiştim				 Yada...				 Sevdiğimi zannetmiştim				 Bir zamanlar sevilmiştim				 Yada...				 Sevildiğimi inanm...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yada-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıra sizdedir', 'sira-sizdedir-i-lhami-arslantas-k3sve', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kargamı kuzgun mu gözünü oyan 

Uyan başım uyan gafletten uyan 

Duyun dostlar bu hal size de ayan 

Susmayın dostlarım sıra sizdedir 

Yılanlar çıyanlar emmiş kanımı 

Tenimden koparmış tatlı canımı 

Çaylak yere vurmuş hasta yanımı 

Susmayın dostlarım sıra sizdedir 

İnsan sayılmadım düzen içinde 

Adamlık görmedim dizen içinde 

Nice zalim gördüm ezen içinde 

Susmayın dostlarım sıra sizdedir 

Asla incitmedim bir karıncayı 

Ne gülü soldurdum nede goncayı 

Vurup düşürdüler boynu inceyi 

Susmayın dostlarım sıra sizdedir 

İlhami sazların bam tellerinde 

Türkü olup kalsın dost dillerinde 

Helâk oldum namerdin ellerinde 

Susmayın dostlarım sıra sizdedir', 'Kargamı kuzgun mu gözünü oyan  Uyan başım uyan gafletten uyan  Duyun dostlar bu hal size de ayan  Susmayın dostlarım sıra sizdedir  Yılanlar...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sira-sizdedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalimdeki Bekleyişin', 'hayalimdeki-bekleyisin-sibel-oner-x24q2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'HAYALİMDEKİ BEKLEYİŞİN				

					

					

Kapanmayan pencerelerin var senin					

Vahşi rüzgarların kapatamadığı					

Kollarım uzansa tutacak					

Bekler,beni ömür boyu ellerin					

					

Bahçende çiçekler benim için büyür					

Yokluğumu aratmaz uçan kelebekler					

Birgün gelmezsem hepsi mahsur					

İkiside birer birer ölür					

					

Şu anda kendi yanlızlığımla odamdasın					

Koyuverseler ağlayacaksın gelmediğim için					

Sabret daha.............senemiz var					

Şimdi tam bekleme anındasın.					

					

					

					

					

			Sibel ÖNER', 'HAYALİMDEKİ BEKLEYİŞİN				 					 					 Kapanmayan pencerelerin var senin					 Vahşi rüzgarların kapatamadığı					 Kollarım uzansa tutacak			...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayalimdeki-bekleyisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak Gel Artık', 'birak-gel-artik-sibel-oner-kye83', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BIRAK GEL ARTIK			

				

				

Bir yuva düşündüm				

Adını bilmediğim bir yerde				

Bırak gel artık				

Orda yaşamakta güzel sevmek de...				

				

Çiçekler arısız yaşamazmış				

Bülbül konmaz oldu güllere				

Bırak gel artık				

Elveda diyelim ellere				

				

Bu yürüyüş birgün bitecek				

Dönemezsin yarı yolda				

Bırak gel artık				

Mutluluk bekliyor kollarımda				

				

				

				

			Sibel ÖNER', 'BIRAK GEL ARTIK			 				 				 Bir yuva düşündüm				 Adını bilmediğim bir yerde				 Bırak gel artık				 Orda yaşamakta güzel sevmek de...				 ...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/birak-gel-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dil yarası', 'dil-yarasi-i-lhami-arslantas-gu1th', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neşter vurma tabip hazinyarama 

Sinemde onmayan dil yarasıdır 

Her derde elbet bir çare var ama 

Sinemde onmayan dil yarasıdır 

Çıkmaz canda her an umut ararsın 

Bilmem nasıl kesip nasıl sararsın 

Elle yapılacak ne ki tararsın 

Sinemde onmayan dil yarasıdır 

Sevgi, saygı, şefkat dolu doludur 

Alın gönlüm size dostluk yoludur 

Hançerde saplasan derim gülüdür 

Sinemde onmayan dil yarasıdır 

Dilde kusur etmek en büyük özür 

Başında tacıyla olsa da nazır 

Barışı kuralım yurt dolsun huzur 

Sinemde onmayan dil yarasıdır 

Acı söz söyleme dostuna sakın 

Yürekte yer eder olur bir çıkın 

Bu derdin örneği bende var bakın 

Sinemde onmayan dil yarasıdır 

İlhami’yim yandım ama külüm yok 

Bir dostu kıracak sivri dilim yok 

Ben beni söylerim çünkü velim yok 

Sinemde onmayan dil yarasıdır', 'Neşter vurma tabip hazinyarama  Sinemde onmayan dil yarasıdır  Her derde elbet bir çare var ama  Sinemde onmayan dil yarasıdır  Çıkmaz canda...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dil-yarasi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ohh Bee Ohhhh', 'ohh-bee-ohhhh-sibel-oner-ry9yj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'OHH BEE OHHHH			

				

				

Boşluktayım be kardeş				

Nasıl  yaşanacak bilmiyorum				

Dermansız bir dertteyim				

Nasıl çözülecek bilmiyorum				

Hayal dünyam alt üst oldu be kardeş				

Hayal etmeyi unutuyorum				

Çaresizlikler içindeyim				

Çare aramasını bilmiyorum				

Gönlümce taht kuramadım be kardeş				

Çıkılacak taht kuramadım				

Beceremiyorum be kardeş				

				

				

				

			Sibel ÖNER', 'OHH BEE OHHHH			 				 				 Boşluktayım be kardeş				 Nasıl  yaşanacak bilmiyorum				 Dermansız bir dertteyim				 Nasıl çözülecek bilmiyorum	...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ohh-bee-ohhhh-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerideki Hatıralar', 'gerideki-hatiralar-sibel-oner-bghi4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'GERİDEKİ HATIRALAR			

				

				

Bir dünya sevdim				

Bana				

Güzelliğine,ödülümü				

Verdi....				

Hep o kazandı				

Hayatımı,yıllarımı verdim				

Bir gün terketti gitti				

Aldı götürdü herşeyimi				

Bir hatıram kaldı şimdi				

Elimde uçar birgün oda....				

Şairliğim,benliğim				

				

				

				

			Sibel ÖNER', 'GERİDEKİ HATIRALAR			 				 				 Bir dünya sevdim				 Bana				 Güzelliğine,ödülümü				 Verdi....				 Hep o kazandı				 Hayatımı,yıllarımı ver...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gerideki-hatiralar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmam Lazım', 'unutmam-lazim-sibel-oner-taxlh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'UNUTMAM LAZIM			

					

					

Nasıl bırakıp gittin					

Yağmur taneleriyle beni					

Vicdanın sızlamadımı senin					

Beni böyle terkettin					

					

		Anladım sevmiyorsun beni			

		Unutmam lazım birgün seni			

					

Her mevsimden kalan yaprak					

İçimdeki yıllarım kadar toprak					

Senin yokluğun her yerde					

Bırakın gelemez,terketti beni					

					

		Anladım sevmiyorsun beni			

		Unutmam lazım birgün seni			

					

Yıllar varki unutulmaz					

Bir kalemin dertlerini					

Beyaz yaprakların söyleyişi					

Unutmam lazım seni					

					

		Anladım sevmiyorsun beni			

		Unutmam lazım birgün seni			

					

Sen yağmurları seversin					

Yağmurlu aşkları,sevdaları					

Bense yağarken ağladığım					

Günlerimi					

					

		Anladım sevmiyorsun beni			

		Unutmam lazım birgün seni			

					

					

					Sibel ÖNER', 'UNUTMAM LAZIM			 					 					 Nasıl bırakıp gittin					 Yağmur taneleriyle beni					 Vicdanın sızlamadımı senin					 Beni böyle terkettin				...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/unutmam-lazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendime Sadığım', 'kendime-sadigim-sibel-oner-hd1y9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'KENDİME SADIĞIM			

				

Bir kıpırdayış,bir titreyiş				

Sonra buruk bir gülümseyiş				

Şen şakrak hoş sohbet				

Doluya almayan bir muhabbet				

Sonu gelmez tartışmaların				

Didişmelerin,çabaların				

Tatlı bir söz bir kıvılcımdır				

İz bırakan bir kuvvettir.				

Dikeni olan bir güldür				

Kendidir insana en sadık olan				

Benliğindedir içine kemiren kin				

Kendidir insana en zararı dokunan 				

Altıncı hissidir içinde var olan				

				

				

				

			Sibel ÖNER', 'KENDİME SADIĞIM			 				 Bir kıpırdayış,bir titreyiş				 Sonra buruk bir gülümseyiş				 Şen şakrak hoş sohbet				 Doluya almayan bir muhabbet...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kendime-sadigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahh Benim Şiirlerim...', 'ahh-benim-siirlerim-i-mdat-ozcan-ounsd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ahh benim şiirlerim

Yalınayak bir serüven

Diken tarlası çıkmazlığında dünyanın

Öylesi bir tebessüm 

Sevgili dudağına düşen

Gün olanda

Azad olmuşluğu Bilal ‘ in

Gün olanda

Yusuf  kuyuda

Bir çift kara göze talan edilmiş kent

Hoyratça çatılanda hilal kaş

Ahh benim sevmelerim

Azalırım çokluğundan yar

Yağmur düşmez ya

Sahipsiz yürüyüşlerime

Köşe başı gölgelerinde

Islıklanmış sızım

Ne şenlik var ıssızlığın da öksüzlüğümün

Ne de mahur besteler de ağlaşacak Müjgan

Çetrefil sorular düşünce bünyeme

Ahh benim dik duruşlarım

Rüzgar arkadan vurur

____tecelli

_______vuslat diyarına ırak

Gül sen ey yar

Ahh benim düşlerim

Düşüşlerim 

Yarının tenhasında

Yaşanılası hürriyetler kuşan 

Her ölümün ardından dirilende yiğitler

Ahh benim ellerim

Sıra sıra uzanan parmaklıklar tutsaklığında

Ranza soğukluğunda

Ahh benim kalemin 

______boynuma yafta

__________kırılanda…', 'Ahh benim şiirlerim Yalınayak bir serüven Diken tarlası çıkmazlığında dünyanın Öylesi bir tebessüm  Sevgili dudağına düşen Gün olanda Azad o...', ARRAY['Türk Edebiyatı','Şiir','İmdat Özcan']::text[], 8.5, '{"poet":"İmdat Özcan","poet_slug":"i-mdat-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ahh-benim-siirlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başkalaşıyorum Ben', 'baskalasiyorum-ben-sibel-oner-cj32v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BAŞKALAŞIYORUM BEN				

					

					

İnsan bir başkadır sevince					

Bir başkadır dünya onca					

Yaşamak zevk verir sevilince 					

Sevip,sevip karşılığını bulunca					

Aşk güzeldir,aşkı yaşayınca					

Yaşamak hoştur,tadına varınca					

Tat almayı bilmek kolyadır sevince					

Sevmek güzeldir,sevmeyi öğrenince					

Öğrenmeyi bilmek geneldir,hedefini varınca					

Hedefini ulaşmak güzeldir,amacına anlayınca					

Amaç yaşamaktır,yolunu bilince					

Yolunda ilerlemektir,ayakta kalınca					

Ayaklarının üzerinde yürümektir,ömür boyunca					

Ömür kısadır değerlendiremeyince					

Sahip olduğun değerlerin kıymetini bilmeyince					

Tutunabildiklerin seni içinde barındırınca					

Barınacak bir yuva bulunca					

Bulduğunu sandığı şeyleri ulaşınca					

O şeyler varki,asla bir daha unutulmaz					

Hatta terkedilmez ve hatta affedilmez					

Sevince varya insan unutulmaz					

Hiçbir şey gözüne görünmez					

					

					

					Sibel ÖNER', 'BAŞKALAŞIYORUM BEN				 					 					 İnsan bir başkadır sevince					 Bir başkadır dünya onca					 Yaşamak zevk verir sevilince 					 Sevip,sev...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/baskalasiyorum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılmayalım Sevgilim', 'ayrilmayalim-sevgilim-sibel-oner-f9bag', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'AYRILAMAYALIM SEVGİLİM				

					

A   yrılmayalım sevgilim					

Y   angınları düşünüyorum da nasıl olur diye 					

R  ahatmıyız dünyada ölesiye					

I    lıman bir bahar gününde					

L  afını etmiştim istemeye istemeye					

M  ahmurluğu atmak isterken üstümden					

A   ydınlatıyordu güneş heryerden tepeden					

Y   azın sıcağı başlıyordu şimdiden					

A   nlamıyormusun sıcağın neden erken başladığını					

L  afını ettiğimden olacak herhalde					

I    şıldıyordu güneş yüksekte					

M  is kokulu baharın son gününde					

					

S   ana biraz daha yaklaşıyorum o anda					

E   llerini uzatsaydın bana					

V   erseydim tüm amacıyla kalbimi sana					

G   erisini hatırlamıyorum anlasana					

İ    PEK SAÇLARIMA DOKUNDUĞUNDA					

L  akin; 					

İ    ğreniyorsun sanki benden					

M  asum bir kız çocuğundan					

AYRILAMAYALIM SEVGİLİM					

					

				Sibel ÖNER', 'AYRILAMAYALIM SEVGİLİM				 					 A   yrılmayalım sevgilim					 Y   angınları düşünüyorum da nasıl olur diye 					 R  ahatmıyız dünyada ölesi...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ayrilmayalim-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhul asker', 'mechul-asker-i-lhami-arslantas-n9zz8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öz evladıydı bu vatanın… 

Her gün, 

Taze bir yokluktu, 

O minik yüreğini inciten… 

Ve taze bir, 

ekmek gibi sunulmuş, 

.....Bir dürüm yokluktu, 

dağarcığında… 

Her yarın, 

yeni bir uçurum 

Her uçurum yarındı onun için 

Arzularını kemiren… 

Ekmek kavgasına 

adamıştı o çocukluğunu 

Çaresizdi… 

….Daha o 

ekmeğini büyütecek, 

büyüyecekti ekmekle… 

iş arıyordu 

kocaman adam gibi… 

kocaman 

umutları vardı… 

dopdolu gözünün mavisinde. 

…Geride 

kalacak kimsesi yoktu 

Acılarından başka… 

henüz 

Ana kuzusuydu, 

Şefkate muhtaç 

Suskundu utanç duvarları… 

suskundu çünkü, 

vicdanları körelmişti beylerin… 

bu vatanın öz evladıydı 

asker olacaktı 

ve bir gün 

ölecekti vatan için 

bu utancı 

sahiplenecek 

bir vicdan sahibi olmasa da 

o şimdi 

meçhul bir asker 

vatanının şefkatli kollarında 

Söylediği 

son sözdü 

ağzını doldurup 

VATAN SAĞ OLSUN…!', 'Öz evladıydı bu vatanın…  Her gün,  Taze bir yokluktu,  O minik yüreğini inciten…  Ve taze bir,  ekmek gibi sunulmuş,  .....Bir dürüm yokluk...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/mechul-asker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Değilmisin? ? ?', 'sen-degilmisin-sibel-oner-z6cfh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SEN DEĞİLMİSİN? 			

				

				

Ayrılıkmı vardı anlaşmamızda				

Dargınlık mı vardı yazışmamızda				

Unutmak mı vardı aşkımızda				

Bunları bana öğreten sen değilmisin? 				

				

Ayrılık baş tacım oldu				

Dargınlık yaşantım oldu				

Ağlamak sanatım oldu				

Bunları bana öğreten sen değilmisin? 				

				

				

				Sibel ÖNER', 'SEN DEĞİLMİSİN? 			 				 				 Ayrılıkmı vardı anlaşmamızda				 Dargınlık mı vardı yazışmamızda				 Unutmak mı vardı aşkımızda				 Bunları ba...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-degilmisin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşları Yalan Söylemez', 'gozyaslari-yalan-soylemez-sibel-oner-gj0us', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'GÖZYAŞLARI YALAN SÖYLEMEZ				

					

					

G   ülme arkadaş					

Ö    ksüzlüğüme,   Z    oruma					

Y     alan dünyaya					

A     lıştım artık onsuz yaşamaya					

Ş     arkılar ağlatıyor artık beni					

L      enetliyorum artık aşkı					

A      şk ne ki; lanetliyesin					

R      ahat bulasın					

I        lık bir meltem mi? 					

Y      umuşak bir elmi? 					

A      lışılmış bir dert mi? 					

L      azım olan kader mi ki; sana					

A      şıksın işte					

N      eden, neden ona taptın					

S       eni sevdiğimi sandım					

Y       alandır her sözün					

L       akin tanırsın					

E       şini sende					

M       esut olursun					

E        vet ama; 					

Z        aten iş işten geçmiştir,tıpki benimki gibi					

					

					

					Sibel ÖNER', 'GÖZYAŞLARI YALAN SÖYLEMEZ				 					 					 G   ülme arkadaş					 Ö    ksüzlüğüme,   Z    oruma					 Y     alan dünyaya					 A     lıştım artı...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gozyaslari-yalan-soylemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek açmış yeni dünyalar', 'cicek-acmis-yeni-dunyalar-i-lhami-arslantas-wh12a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merhaba..! 

Umutlarımı süsleyen 

Özgürlük, 

Mutluluk, 

Huzur 

Ve barış için 

Atan yürek 

Merhaba…! 

Çiçeği burnunda 

Özgürlüğün türküsü 

Merhaba yeni dünyalar 

Bak, 

Rengi barış, 

Sevgi sıcaklığında gözleri 

Biri, 

Yıldızı sevmiş 

Diğeri, 

Görücüyle boy atmış 

Güneşi, 

Kucaklarcasına 

tutarcasına ellerini 

Okşarcasına 

sarışın saçlarını 

yeni dünyalar açmış 

çiçeği burnunda 

merhaba…! 

Kavgamın çiçeği 

Merhaba yeni dünya 

Ve merhaba 

Aynı gün doğan umut 

gözleri çakırım 

Merhaba …! 

Artık, 

Düşecek asmanın davası 

Badem, 

kurtulacak acı iftiradan, 

İncir bırakacak arsızlığı, 

Gündöndülerim gülerek 

Dönecekler, 

Gün döndükçe hayata 

Merhaba…! 

Merhaba yeni dünya 

ve merhaba…! 

masmavi umut.', 'Merhaba..!  Umutlarımı süsleyen  Özgürlük,  Mutluluk,  Huzur  Ve barış için  Atan yürek  Merhaba…!  Çiçeği burnunda  Özgürlüğün türküsü  Mer...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/cicek-acmis-yeni-dunyalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Anı', 'bir-ani-sibel-oner-vbxas', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BİR ANI				

					

Serin bir sonbahar akşamında hani o gün					

Ayrılmıştık çaresiz					

Düşen her yaprağın soluk renginde hani ozaman					

Ayrılık vardı imkansız					

Damlayan her yağmur damlasına hani o gece					

Ağlamıştık ümitsizlik					

Doğan güneşin soluk ışığında hani o sabah					

Garip bir hüzün vardı; kalpler buruk çaresiz					

					

					

				Sibel ÖNER', 'BİR ANI				 					 Serin bir sonbahar akşamında hani o gün					 Ayrılmıştık çaresiz					 Düşen her yaprağın soluk renginde hani ozaman					 A...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-ani-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Yağmuru', 'yaz-yagmuru-sibel-oner-6ammo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'YAZ YAĞMURU		

			

			

Bir yaz yağmuruydu			

Sevgimiz			

Hemen gelip geçen			

Bir yaz yağmuruydu			

Gözlerimizde inan			

Dalga dalga			

Bir yaz yağmuruydu			

Gönüllerimize düşen			

Sağanak sağanak			

Nehirler,denizler oluşturan			

Çılgın dalgalar arasında			

Çırpınan kalplerimiz			

Dedim ya! 			

Bir yaz yağmuruydu			

Sevgimiz			

Başlamadan biten aşkımız.			

			

			

			

			Sibel ÖNER', 'YAZ YAĞMURU		 			 			 Bir yaz yağmuruydu			 Sevgimiz			 Hemen gelip geçen			 Bir yaz yağmuruydu			 Gözlerimizde inan			 Dalga dalga			 Bir y...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yaz-yagmuru-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun', 'sen-yoksun-sibel-oner-crl3x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SEN YOKSUN			

				

Şimdi yaşamıyormusun sanki sen				

Ümit bağlayıp ardından koştuğum				

Bir yaram var sadece kalbimde				

Bir zamanlar sevginle coştuğum				

				

Terketti tüm şarkılar beni				

Mazim yıklıdı,görmüyor gözlerim				

Nerden çıktı bu kahrı yalnızlık				

Gençlik yıllarım dönmüyor geri				

				

Güzel şarkılar seninle güzelmiş				

Senin sevginmiş beni yaşatan				

Hayatım,deyip arayacağım yıllarca				

Yılları beni zindan eden ''ALÇAK''				

				

				

				

				Sibel ÖNER', 'SEN YOKSUN			 				 Şimdi yaşamıyormusun sanki sen				 Ümit bağlayıp ardından koştuğum				 Bir yaram var sadece kalbimde				 Bir zamanlar sev...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-yoksun-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendin Ve Başkaları', 'kendin-ve-baskalari-sibel-oner-3kj1r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'KENDİM VE BAŞKALARI				

					

					

Yaşamdan iyi dersler aldım					

Örnek mi vereyim					

Herkesin kendi için yaşaması					

Her koyunun kendi bacağından asılması					

					

Düşünüyorumda niye insanlar acımasız					

Vicdansız ve merhametsiz					

Olanlardan habersiz görünüp					

Herşeyde parmağı olan insancıklar					

					

İnsancık diyorum,çünkü hepiciğini de					

Zaman zaman acıyor					

Merak ettikleri konuda					

Aydınlatmayı bir görev biliyorum					

					

Ama ne kazanıyor,ne kaybediyorum					

Bunu kendim dahil kimse bilmiyor					

Yeter be kızım kendinden bu kadar					

Ödün veripte ne elde edeceksin					

				Sibel ÖNER', 'KENDİM VE BAŞKALARI				 					 					 Yaşamdan iyi dersler aldım					 Örnek mi vereyim					 Herkesin kendi için yaşaması					 Her koyunun kend...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kendin-ve-baskalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum', 'seviyorum-sibel-oner-zpm9k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SEVİYORUM				

					

Sensiz olamıyorum çünkü					

Hala seninleyim					

Sensiz yapamıyorum çümkü					

Hala seni çok seviyorum					

					

Sensiz yaşayamam desemde					

Hala bak yaşıyorum					

Sensiz dünyayı					

Hep ama hep boş görüyorum					

					

Senle ben bir bütündük					

Parçalandık ayrıldık					

Ayırdılar ikimizi					

Boynu bükük kaldık					

Sevenler ayrılamazdı hani					

Sevenler mutlu olurdu					

Yaşam sevenler içindi					

Sevildiğini bilmek ti					

İnsanlar sevenlerin yanındaydı					

Sevenler ayrılamazdı hani					

				Sibel ÖNER', 'SEVİYORUM				 					 Sensiz olamıyorum çünkü					 Hala seninleyim					 Sensiz yapamıyorum çümkü					 Hala seni çok seviyorum					 					 Sensi...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seviyorum-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asya', 'asya-muhiddin-ates-2djc0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akrostiş şiirler yazıyorum

Sana olan ilgimden

Yemiyor içmiyorum

Adını andıkça doyuyorum

Alelade bir şey değil benimkisi

Sığ bir sevgi sanma

Yeryüzünden arşa çıkar

Az gelir bu dünya

Aldatıcı sözler değil bunlar

Samimi itirafımdır

Yere göğe sığmayan

Aklın almadığı duygular', 'Akrostiş şiirler yazıyorum Sana olan ilgimden Yemiyor içmiyorum Adını andıkça doyuyorum Alelade bir şey değil benimkisi Sığ bir sevgi sanma ...', ARRAY['Türk Edebiyatı','Şiir','Muhiddin Ateş']::text[], 8.5, '{"poet":"Muhiddin Ateş","poet_slug":"muhiddin-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/asya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrıldık İşte', 'ayrildik-i-ste-sibel-oner-v57tc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'AYRILDIK İŞTE				

					

					

Çok gördüler aşkımızı					

Kıskandılar evliliğimizi					

Çekemediler bizi					

Ayrıldık işte					

					

Herşeyden üstündü sevgimiz					

Bir bütündü beraberliğimiz					

Tattığımız ilk mutluluktu aşkımız					

Ayrıldık işte					

					

Aşkımız üstüne vardı andımız					

Yürütmek vardı evliliğimiz					

Mutlu olmaktı hedefimiz					

Ayrıldık işte					

					

Kim demiş sevenler ayrılmaz					

Sevilip sevenler hata yapmaz					

Son pişmanlık fayda etmez					

Ayrıldık işte					

					

					

				Sibel ÖNER', 'AYRILDIK İŞTE				 					 					 Çok gördüler aşkımızı					 Kıskandılar evliliğimizi					 Çekemediler bizi					 Ayrıldık işte					 					 Herşey...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ayrildik-iste-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayana', 'anlayana-osman-kilic-yd8lj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu eve ilk kez sensiz girdim bugün

Çökmüştü hep dimdik duran omuzlarım

Apartman boşluğuna düşen gölgemden

Ne kadar yorulduğumu anladım

Bir hıçkırık duydum sanki

Anahtarı çevirdiğimde

Bu ne dağınıklık be kardeşim? 

Böylemiydim sen gitmeden önce..

Yeni serdiğim çarşafta dünyanın kiri

Üzerinde kıvranmış bu toprağın kafiri

Herkesin o olmaktan korktuğu biri

Sırtı kaşınmış baharlık aygır gibi..

Gıcırtısına hep söylendiğin bu yatak

Kalmazdı bu vakit sessiz

Olmazdı elbet böyle durgun

Yüreğim çamura bulanmış bir karabatak

Çırpındıkça kabaran bir ümitsizlik..eşsiz..

Kalbinden yakalamış o en amansız vurgun

Öylesine hür ve öyle ezik...

Masamın üzerindeki ölgün silik

Deşilmiş karnı gururu kadar devrik

Çayları etrafa saçılmış o isli demlik

Hüzün fışkırtıyor duvarlara

Kol geziyor silüetin

Ve yalnızlık...

Her yanda panik...

Anlayana.....', 'Bu eve ilk kez sensiz girdim bugün Çökmüştü hep dimdik duran omuzlarım Apartman boşluğuna düşen gölgemden Ne kadar yorulduğumu anladım Bir h...', ARRAY['Türk Edebiyatı','Şiir','Osman Kılıç']::text[], 8.5, '{"poet":"Osman Kılıç","poet_slug":"osman-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/anlayana-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedim Ya', 'dedim-ya-sibel-oner-ykriv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'DEDİM YA			

				

Sevdim dedim				

Yaşamı sevdim				

Unuttum dedim				

Ölümü hissettim				

Ayrıldım dedim				

Boşlukta kaldım				

				

Gecelerce ağladım				

Sel oldu yaşlarım				

Kurudu pınarlarım				

Sönmedi yangınım				

				

				

			Sibel ÖNER', 'DEDİM YA			 				 Sevdim dedim				 Yaşamı sevdim				 Unuttum dedim				 Ölümü hissettim				 Ayrıldım dedim				 Boşlukta kaldım				 				 Gecele...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dedim-ya-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığımız', 'ayriligimiz-sibel-oner-7wi1w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'AYRILIĞIMIZ				

					

Soruyorlar nedenini ayrılığımızın					

Demiyorlar ki çaresini					

Soruyorlar unutup,unutulduğumu					

Bilmiyorlar ki hala çok sevdiğimi					

					

Diyorlarki hep					

Osana layık değildi					

Diyorlarki hep					

Yürümezdi bu evlilik					

					

Benim akıla değil ihtiyacım					

Mutluluğa muhtacım					

Sevgiye hasretim					

Aşkı susadım					

					

Akıl değil,sevgi verin bana					

Teselli değil,aşkımı verin bana					

Vaad değik,gerçeği verin bana					

Ayırmayın ikimizde hayalimde bana					

					

					

				Sibel ÖNER', 'AYRILIĞIMIZ				 					 Soruyorlar nedenini ayrılığımızın					 Demiyorlar ki çaresini					 Soruyorlar unutup,unutulduğumu					 Bilmiyorlar ki ...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ayriligimiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Sevgilim', 'canim-sevgilim-sibel-oner-mcwdt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'CANIM SEVGİLİM			

				

				

Hayatımı aydınlatan ışıktın				

Dünyamı renklendiren ilahtın				

Sevmesini öğreten sevgiliydin				

Benim canım sevgilim				

				

Samanlığa seyran eden				

Dolu dizgin pervasızca koşan				

Olanlardan habersiz olan				

Benim canım sevgilim				

				

Sana canım bile diyemiyorum				

Seni seviyorum diyemedim				

Körolası gururum engel oldu				

Gerçekleri söyleyemedim				

				

				

				

			Sibel ÖNER', 'CANIM SEVGİLİM			 				 				 Hayatımı aydınlatan ışıktın				 Dünyamı renklendiren ilahtın				 Sevmesini öğreten sevgiliydin				 Benim canım s...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/canim-sevgilim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Ayrılamayız', 'biz-ayrilamayiz-sibel-oner-vetb1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BİZ AYRILAMAYIZ				

					

					

Sevdiğim yeminimiz vardı					

Biz ayrılamayız					

Bir tanem şarkımız vardı					

Biz ayrılamayız					

Hayatım sözümüz olan					

Biz ayrılamayız nerde? 					

					

Sevdiğim sensiz olamam					

Sensiz yapamam					

Sensiz yaşayamam					

Ölürüm diyordun					

Şimdi nerdesin? 					

					

Hani herşey halledilecekti					

Su aka aka deresini bulacaktı					

Deliler uslanıp oturacaktı					

Kinlerin yerine sevgi alacaktı					

Bizde rahata ulaşacaktık nerde? 					

					

Soruyorum niye beni ektin					

Pardon ben seni terkettim					

Sen beni düşünmezken					

Ben sana dersi(hayat)  verdim					

					

					

				Sibel ÖNER', 'BİZ AYRILAMAYIZ				 					 					 Sevdiğim yeminimiz vardı					 Biz ayrılamayız					 Bir tanem şarkımız vardı					 Biz ayrılamayız					 Hayatı...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/biz-ayrilamayiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçüncü dereceden yanık gibi', 'ucuncu-dereceden-yanik-gibi-osman-kilic-h36za', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmem kaç bin volt geldi

Ayrılığın gerilimi

Gittin de unutabildim mi sanki? 

Mümkünü yok kaldın yüreğimde

Üçüncü dereceden yanık gibi! ....', 'Bilmem kaç bin volt geldi Ayrılığın gerilimi Gittin de unutabildim mi sanki?  Mümkünü yok kaldın yüreğimde Üçüncü dereceden yanık gibi! .......', ARRAY['Türk Edebiyatı','Şiir','Osman Kılıç']::text[], 8.5, '{"poet":"Osman Kılıç","poet_slug":"osman-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ucuncu-dereceden-yanik-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımcım Sevgilim', 'canimcim-sevgilim-sibel-oner-kcr9c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'CANIMCIM SEVGİLİM			

				

				

C    üretkar ama cesaretsiz				

A     lçak gönüllü ama saf				

N     amuslu fakat iradesiz				

I       lımlı lakin isteksiz				

M     ert ama yüreksiz				

				

S     evecen olsa				

E      msali görülmemiş olsan				

V      efalı da olsan ne olur ki				

G      elişi güzel hayatın içinde				

İ        steklerin gerçekleşemez				

M      utlu yuvanı kurtarmalıydın sen				

				

				

				

			Sibel ÖNER', 'CANIMCIM SEVGİLİM			 				 				 C    üretkar ama cesaretsiz				 A     lçak gönüllü ama saf				 N     amuslu fakat iradesiz				 I       lımlı ...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/canimcim-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-ahmet-alptekin-fixli', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SİTEM

Ufkumu sardı kapkara bulutlar

Söndü gitti o güzelim umutlar

Kötüler toplanmış halay başına

Ben kan ağlarım, onlar bayram kutlar.

Sormayın gardaşlar yaram derinden

Yoruldum, sıkıldım, bıktım ilinden

Kargalar anlamaz bülbül dilinden

Mor güller kahrolur, kozalar patlar.

Sabır taşım çatladı beklemekten

Gurbet ellerinde hasret çekmekten

Bizlere pay düşer mi hiç gülmekten

Acılarım artar, dertlerim katlar.

Bunca yıldır verdiğimiz emekler

Kimler, kimden, nerde,bilmem ne bekler

Bir söz ile kırılırmış yürekler

Gönüller burkulur, sineler çatlar.

                                        Ahmet Alptekin', 'SİTEM Ufkumu sardı kapkara bulutlar Söndü gitti o güzelim umutlar Kötüler toplanmış halay başına Ben kan ağlarım, onlar bayram kutlar. Sorma...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Alptekin']::text[], 8.5, '{"poet":"Ahmet Alptekin","poet_slug":"ahmet-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sitem-132-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Biz Ayrılamayız', 'biz-biz-ayrilamayiz-sibel-oner-utxyv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BİZ BİZ AYRILAMAYIZ				

					

B    en buyum işte					

İ      kili arasında kalmış					

Z     afere ulaşmak isteyen					

					

A     şık olunduğunu sanan					

Y     anlızlığı alışmaya çalışan					

R     ahat yaşam süremeyen					

I       slak yollarda sessiz yürüyen					

L      oş odalarda yalnız uyuyan					

A      şık olup karşılığını bulamayan					

M     mutsuz olup da mutlu görünen					

A      lışıp herşeyini kaybeden					

Y      aşaran gözlerini silen					

I       slanan yaşlarını kurutan					

Z      oraki mutluluğu yakalamaya çalışan					

					

					

					

				Sibel ÖNER', 'BİZ BİZ AYRILAMAYIZ				 					 B    en buyum işte					 İ      kili arasında kalmış					 Z     afere ulaşmak isteyen					 					 A     şık olun...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/biz-biz-ayrilamayiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gecenin Bitiminde', 'her-gecenin-bitiminde-sibel-oner-xo9g9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'HER GECENİN BİTİMİNDE			

				

				

Bir şarkı,bir şiir olmak istiyorum				

Gün boyu hep söylenen dilinde				

Bir rüzgar,bir yel olmak istiyorum				

Olmalı saçlarım dalga dalga elinde				

				

Ve,seni istiyorum				

Ve seni özlüyorum inan				

Ve seni arzuluyorum				

Her gecenin bitiminde				

				

Gözlerin gözlerinde asılı				

Sen ben,ben sen olmalıyız				

Bırakma can bakışlım				

Biz ancak ölümle ayrılmalıyız.				

				

				

				

				

			Sibel ÖNER', 'HER GECENİN BİTİMİNDE			 				 				 Bir şarkı,bir şiir olmak istiyorum				 Gün boyu hep söylenen dilinde				 Bir rüzgar,bir yel olmak istiyor...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/her-gecenin-bitiminde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Suçlu Sen Ve Onlar', 'tek-suclu-sen-ve-onlar-sibel-oner-v0yjv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'TEK SUÇLU SEN VE ONLAR				

					

Soruyorum sana					

Sevmişmiydin beni					

Benden sana tavsiye					

Sevme artık beni					

					

Unutuyormusun yoksa,çalışıyorsan					

Unut......					

Yaşıyormusun yoksa,çabalıyorsan					

Öl.......					

Ağlıyormusun yoksa,sabrediyorsan					

Ağla derim.					

					

Beni benim kadar sevseydin					

Unut demez.......					

Beni benim kadar yaşasaydın					

Öl demez........					

Beni ben olduğum için ağlasaydın					

Ağla demezdim.					

					

Kaybeden ben ve sen					

Kazanan o ve onlar					

Ve.......					

Tüm şarlatanlar					

Tüm insafsızlar					

Tüm caniler					

Tüm lanetliler					

Tüm belalılar					

Tüm  onlar...........					

					

				Sibel ÖNER', 'TEK SUÇLU SEN VE ONLAR				 					 Soruyorum sana					 Sevmişmiydin beni					 Benden sana tavsiye					 Sevme artık beni					 					 Unutuyormus...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/tek-suclu-sen-ve-onlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık..', 'ayrilik-osman-kilic-lde8r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine seversin demiştin

Ne ayrılıklar yaşarsın yine

Hep zor gelir insana gitmek

Bu da benden olsun ey yitik sevgili:

Böylesi ayrılık için önce

Böyle derin sevmek gerek! ...

Böylesi ayrılık sarhoşluktur gülüm

Görmemiş sarhoşluğu hem

Yada ölüm..

Ayırdına ancak uyanınca varırsın

Belki de artık hiç uyanamazsın! ....', 'Yine seversin demiştin Ne ayrılıklar yaşarsın yine Hep zor gelir insana gitmek Bu da benden olsun ey yitik sevgili: Böylesi ayrılık için önc...', ARRAY['Türk Edebiyatı','Şiir','Osman Kılıç']::text[], 8.5, '{"poet":"Osman Kılıç","poet_slug":"osman-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ayrilik-236-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çelişki', 'celiski-akin-tekin-7evge', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Barut fıçısına dönmüş dünya! 

Ve gerilen yayların ucunda,fırlamaya hazır

ateşli oklar gibi yaşanıyor hayatlar

Hiç bitmeyen hırslarıyla insanlar,

hep daha fazlasını isterlerken; 

ve bir nalıncı keseri misali,

hep kendilerine isterlerken; 

üstlerine basıp geçtiklerine bakmazlar bile! ..

Şimşekler çakar üzgün gözlerimde! 

Bir kibrit çöpünün ucundadır artık dünya! 

Ama tüm bunlara rağmen; 

yaşamla alay eder gibi,

sen gelirsin aklıma,keyiflenirim...

Tatlı bir huzurla dolar içim,

bir de üstelik,gülümserim...

Kar altında kentler görürüm geceleri,

ve sokaklarında, yalınayak çocuklar...

Kar altında kentler görürüm geceleri,

ve sıcak salonlarında,

pofuduk terlikler içinde,pedikürlü ayaklar...

Üzülürüm...

Mutlu azınlığın şanslı insanları,

balı böreği çöpe atarken,

açlık sınırında yaşayanlar üzer beni...

Ama tüm bunlara rağmen,

seni düşünür,keyiflenirim...

Sinir olur kendime küfrederim! 

İhanet ediyormuş gibi,kuşkulara düşerim.

Elimde değil,düşündükçe seni; 

değişir renkleri gözlerimin...

İnsanlar ölür bir hiç yüzünden...

Çocuklar ölür,Irak''ta Filistin''de,Afrika''da! 

Ateş düşen yüreklerden,

yanık türküler yükselir gökyüzüne! ..

Fışkırır gözyaşı çiçekleri; 

Açar! 

Hırsla! 

Kahırla! 

İnatla! 

Korku,kara pelerinli bir hayalettir artık...

İşkenceye yatar insanlık; 

tırnakları sökülür,dişleri çekilir! ...

Elektrik şoklarıyla kuruyan kanların arasından,

son gördüğü şey; 

dünyanın tepesindeki beyaz bir şatoda

sırıtkan bir çakal yüzüdür,insanlığın! 

Üzülürüm! ..

Ama,

pat diye düşersin aklıma birden! ..

Biliyorum bencillik oluyor bu.

Hatta,suç işliyorum diyebilirim.

İstem dışı oluşan,

ele avuca sığmaz bir duygu bu? 

Çaresiz,gizlice gülümserim...', 'Barut fıçısına dönmüş dünya!  Ve gerilen yayların ucunda,fırlamaya hazır ateşli oklar gibi yaşanıyor hayatlar Hiç bitmeyen hırslarıyla insan...', ARRAY['Türk Edebiyatı','Şiir','Akın Tekin']::text[], 8.5, '{"poet":"Akın Tekin","poet_slug":"akin-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/celiski-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin -2-', 'gelin-2-abdullah-atay-rs4t0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'baharda dalmış gelin

dallarda gülmüş gelin

yar yolunu beklerken

uykuya dalmış gelin...

sevdaya düştü gelin

dağları aştı gelin

ne karaymış yazısı

kötüye düştü gelin...

gönlümü çalan gelin

sevdaya salan gelin

üstüne yar sevmişim

vallahi yalan gelin...

badeleri iç gelin

gerdanını aç gelin

bağımdaki gülümsün

kokuları saç gelin...

al fistanı dar gelin

sende gönlüm var gelin

başkaları inan ki

olmaz bana yar gelin...

zilleri takan gelin

oyuna kalkan gelin

cilvesiyle nazıyla

yüreğim yakan gelin...

dağımda ki kar gelin

bağımda ki nar gelin

yarini eller almış

senin işin zor gelin...

al şalvarı bol gelin

sen de mutlu ol gelin

benden başka seversen

sararıp da sol gelin..

el sözüne kanma gelin

kanıpta yanma gelin

sevdiceğin ele gitmiş

onun adın anma gelin...', 'baharda dalmış gelin dallarda gülmüş gelin yar yolunu beklerken uykuya dalmış gelin... sevdaya düştü gelin dağları aştı gelin ne karaymış ya...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gelin-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sende Ölmeyi Özledim', 'ben-sende-olmeyi-ozledim-nurol-banabak-pd2w4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben seni bir yağmur mevsiminde sevdim

Sular süzülürken saçının telinden

Saçının telini özledim

Ben seni ayışığı altında sevdim

Dalarken gözlerin ayışığına

Gözlerini özledim

Ben seni ilkbaharda kuş seslerinde sevdim

Sen hüzünle gülümserken

Yüzünü özledim

Ben seni yasakların sıratında sevdim

Ruhlarımız çarmıha geriliyken

Bedenini özledim

Ben seni ölümlü bir ömürde sevdim

Karışsın diye ölümlerimiz

Ölmeyi özledim.

. 2002 Şubat', 'Ben seni bir yağmur mevsiminde sevdim Sular süzülürken saçının telinden Saçının telini özledim Ben seni ayışığı altında sevdim Dalarken gözl...', ARRAY['Türk Edebiyatı','Şiir','Nurol Banabak']::text[], 8.5, '{"poet":"Nurol Banabak","poet_slug":"nurol-banabak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-sende-olmeyi-ozledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ömür', 'bu-omur-yilmaz-korkankorkmaz-tdeec', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yitirilmiş umutlar toplamıdır 

bu ömür 

kendi kıyısında yalnızlaşmış 

çocuklukları toplayan 

bütün yolculukları 

gözleriyle saran bir hüznün 

aynaya yansıyan yorgunluğudur birazda 

ve aldatılmış bir kadının 

gözyaşları gibi 

derinden kanatır bileklerini zamanın', 'yitirilmiş umutlar toplamıdır  bu ömür  kendi kıyısında yalnızlaşmış  çocuklukları toplayan  bütün yolculukları  gözleriyle saran bir hüznün...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Korkankorkmaz']::text[], 8.5, '{"poet":"Yılmaz Korkankorkmaz","poet_slug":"yilmaz-korkankorkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-omur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-tuncay-akdeniz-2xav0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '34-İSTANBUL-34

Harikalar şehri dünya gözünde

Osmanlı mirası malı İstanbul.

Peygamber duası vardır özünde

Bayrağın,sancağın alı İstanbul.

İmarı Sinan’dan, ne güzel yapı.

İslam’ın özüne, kesilmiş tapu.

Kıyamete kadar, açık bir kapı.

Dünya aleminin, yolu İstanbul.

Fatihler, Sinanlar,senin izinde.

Şehitler bağrında,hak niyazında.

İslam’ı eserler,cami tarzında,

Evliya,alimin,gölü İstanbul.

Otuz altı sultan,karmış harcını,

Fatih’in elinden.giymiş tacını.

Al bayrak süslemiş,kale burcunu,

Şehit kanlarının seli İstanbul.

Türkler ezelinden,sana sevdalı,

Şehit toprağının,olmaz bedeli.

Bütün şehirlerin,sensin güzeli,

Türkiye’nin lale,gülü İstanbul.

Haliçten denize,çekilmiş suru,

Boğazında vardır,iki hisarı.

Limanda gemiler dolu ambarı

Ticaretin eli,kolu İstanbul

Camiler,saraylar,hisarlar süsü.

Mavi denizleri,yeşil örtüsü.

Boğazın incisi,iki köprüsü,

Bir ağacın,iki dalı İstanbul

Yedi tepelerin,uyur dizinde

Gemiler oynaşır,deniz yüzünde.

Anadolu kokar,senin özünde,

Bin bir çiçeğin,balı İstanbul.

Uluslar arası,hava meydanı

Denizle çevrili,her iki yanı.

Turgut reislerin,oldun limanı,

Denizde kaptanın,mili İstanbul.

Türkiye’nin sensin,hanı konağı,

Taş,toprağı altın,göçler durağı.

Çalışan insanın,geçim kaynağı

Kazması küreği,beli İstanbul

Türkiye’nin gözü kaşı burası

Asya Avrupa’nın merkez ortası

Medeniyet şehri,ilim yuvası

Bilim dünyasının dili İstanbul.

Tuncay’ın gönlünde sevgisi saklı

Şairin gözünde manzaran farklı

İlçeler sayısı,farzlara denkli

Otuz iki ilçe,ili İstanbul.

Tuncay AKDENİZ

.', '34-İSTANBUL-34 Harikalar şehri dünya gözünde Osmanlı mirası malı İstanbul. Peygamber duası vardır özünde Bayrağın,sancağın alı İstanbul. İma...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/istanbul-171-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrenilen Masallar', 'ogrenilen-masallar-leyla-ayyildiz-hskxq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Evvel zaman içinde,

Kalbur saman içinde,

Küçük bir çoban varmış.

Sürüsünü alarak,

Kavalını çalarak,

Dağlara çıkarmış.

''Kurt var! '' ''Kurt var! ''

Diye bağırmış,

Köy halkını çağırmış.

Köylü koşup, gelmiş,

Meğer, kurt falan yokmuş,

Hepsi yalanmış.

Kurt nerede miymiş? 

Çok acıkmış,

Arkadaşlarıyla birlikte

Yiyecek arıyormuş.

Az gitmişler,

Uz gitmişler,

Dere, tepe düz gitmişler,

Bizim çoban ve sürüsüyle

Bir türlü karşılaşamamışlar.

Açlıktan ölmek üzerelermiş,

Büyük bir halka oluşturup,

Hızla koşmaya başlamışlar.

Koşmuşlar, koşmuşlar,

Koşmuşlar.

Hızla, hızla, daha hızla.

Taa ki,

İçlerinden biri yorulup,

Düşünceye dek.

İlk düşeni,

Parçalayıp, yemişler! 

Kurtlar sofrası! 

O sırada çoban hala,

''Kurt var, kurt var''.

Diye, bağırıyormuş.

Sesi duymuş bizim kurt.

Karnı tok, sırtı pek.

Hani, tatlı niyetine

Bir iki kuzu, bir de çoban,

Hiç de fena olmazmış.

Dalmış sürünün içine.

Küçük çoban şaşkın,

Yine, ''Kurt var, Kurt var''

Diye bağırmış,

Köy halkını çağırmış.

Fakat kimse inanmamış,

Yalancıyı kurt yemiş.

Tüm bu olanları

Bir akrep izlemiş.

Kurt, akrebi görünce,

''Gel, buyur'' demiş.

''Sen de ye''.

Akrep, teşekkür edip,

Karnını bir güzel doyurmuş.

''Susadım'' demiş,

''Su da verebilir misin? ''...

Karnını ovuşturmuş kurt.

''Derenin kenarına gidelim'',

Dişlerinin arasında et parçaları,

Kana kana içmişler suyu.

Akrep, rica etmiş; 

''Beni karşı kıyıya geçirir misin? ''

''Hayır'' demiş kurt.

''Seni hiç sırtıma alır mıyım,

Sokarsın beni.''

Kurt haklı; 

Akrep bu, sokar.

Binlerce kez yemin etmiş akrep,

''Ant olsun ki,

seni sokmayacağım''

Kurt dayanamamış,

Kabul etmiş.

Almış sırtına akrebi,

Yavaş yavaş geçmişler dereyi.

Tam karşı kıyıya ulaşacakken,

Sokmuş akrep kurdu.

Can çekişirken,

Acı ile sormuş kurt; 

''Neden, neden yaptın bunu? ''.

Akrep gülmüş,

''Neden mi? ''

''Huyum bu! ''', 'Evvel zaman içinde, Kalbur saman içinde, Küçük bir çoban varmış. Sürüsünü alarak, Kavalını çalarak, Dağlara çıkarmış. ''Kurt var! '' ''Kurt var...', ARRAY['Türk Edebiyatı','Şiir','Leyla Ayyıldız']::text[], 8.5, '{"poet":"Leyla Ayyıldız","poet_slug":"leyla-ayyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/ogrenilen-masallar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümün Sisi', 'olumun-sisi-omer-bolat-c8gwf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '26 yaşında toprağa düşen bir cana ithafen...

Ölümün sisi üstüme çökünce

Aldı beni, derin bir düşünce

Akranlarım da toprağa düşünce

Ben de bir gün öleceğim diyorum…

Ecel, bu akşam gelecek gibi

Ruhumu bedenden alacak gibi

Attığım her adımda ölecek gibi

Ölüme doğru gidiyorum…

31 Mart 2005

ADAPAZARI', '26 yaşında toprağa düşen bir cana ithafen... Ölümün sisi üstüme çökünce Aldı beni, derin bir düşünce Akranlarım da toprağa düşünce Ben de bi...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bolat']::text[], 8.5, '{"poet":"Ömer Bolat","poet_slug":"omer-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olumun-sisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla Gözlerim', 'agla-gozlerim-ali-fikri-karadeniz-3005i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağla gözlerim

Yıkayın tenimi de 

Kapansın her gün kanayan yaralarım

Sönsün alev alev yanan dudağım

Ah… Derdime derman olmayan gözlerim…

Ağla gözlerim

Baharında çiçeklerin de solmuş

Göçmen kuşlar uçmuş gitmiş sıladan

Hayallerin alev olmuş, kül olmuş

Dua’larla yolculuğa hazırlan…

Ağla gözlerim

Sen gördün, sen beğendin

Çıldır kulağım

Sen duydun, sen işittin

Yok ol yüreğim

Sen sevdin, sen işittin

Erisin tenim, bitsin bedenim…

Ağla gözlerim

Şimdi; 

Bedenimi alev alev yakan

Ve göz bebeğime yapışan

Ve kalbime hançer gibi saplanan

Ve beni benden alan

Yıka Da at atabilirsen

Günahını çek gözlerim…

Ağla gözlerim

Dualar beddua’ya dönüştü

Korkum kalbimden değil

Değil sana inanmaktan

Beddua edenleri güldürüyorsun

İşte bu yüzden

Sırf bu yüzden

Sen beni kahrediyorsun…! ! ! 

                                                  01/04/2005

Ali Fikri Karadeniz', 'Ağla gözlerim Yıkayın tenimi de  Kapansın her gün kanayan yaralarım Sönsün alev alev yanan dudağım Ah… Derdime derman olmayan gözlerim… Ağla...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/agla-gozlerim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın', 'kadin-omer-bolat-ihk5m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu ne hoş güzellik, bu ne ince biçim

Kadın, duyguların nazik törpüsüdür.

Ben bu inceliğe gerçek sanat derim

Sanat ki, ilahi aşkın köprüsüdür.

Yüreğim bir kapı, kadınsa anahtar

Ben en çok kadının gücünden korkarım

Ben istemesem de, nefsim taraftar

Sarhoşça peşinden sürünür akarım.

06 Şubat 2001

YERKÖY', 'Bu ne hoş güzellik, bu ne ince biçim Kadın, duyguların nazik törpüsüdür. Ben bu inceliğe gerçek sanat derim Sanat ki, ilahi aşkın köprüsüdür...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bolat']::text[], 8.5, '{"poet":"Ömer Bolat","poet_slug":"omer-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kadin-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban', 'kurban-omer-bolat-092v6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben hep yalnız, ben sevilmeyen adam

Beynimde bilinmezler örgün.

Tek dostum dudağımda sigaram

Aklım Nuh''un gemisinde sürgün...

Ben, sefil hayatın sefil kurbanı

Benim, ızdırabın güzel cananı

Dünyaya inat, zevkin yabanı

Bir meçhule doğru giderim bugün...

3 Mayıs 2000

ALACA', 'Ben hep yalnız, ben sevilmeyen adam Beynimde bilinmezler örgün. Tek dostum dudağımda sigaram Aklım Nuh''un gemisinde sürgün... Ben, sefil hay...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bolat']::text[], 8.5, '{"poet":"Ömer Bolat","poet_slug":"omer-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kurban-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''um... (Serbest)', 'i-stanbul-um-serbest-atakan-kartaltepe-ad6yg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çıkıp da bakmaya ne hacet? 

Bir tepesinden...

İstanbul''um ki güzeldir! 

Hep(i)    sinden...

- - -

Bir şehir ki...iki yaka''da,

Boğaz''ı nehir...

Göğü çakır...

Gün batımı bakır...

Ayrılığı kahır...İstanbul''um! 

- - - 

Hava''sı...su''yu...

Güneş''i...Ay''ı...

Bayan''ı...Bay''ı...İstanbul''um! 

- - - 

Toprağı...taş''ı...

Ekmeği...aş''ı...

Bilinmez yaş''ı...İstanbul''um! 

- - - 

Dünya''ya inci...

Her an birinci...

Gönül sevinci...İstanbul''um! 

- - - 

Ayrı kalan yanar...

Hasretle anar...

Resminle kanar...İstanbul''um! 

- - - 

Kış''ı bir başka...

Yaz''ı bir başka...

Bahar''da aşka...düşürensin İstanbul''um! 

- - - 

Bin değerinde her bir ân''ı...

Cennet''tir dört bir yanı...

Gönüller üşürensin...İstanbul''um! 

- - - 

Geçmiş''im, sende...

Gel''mişim, sende...

Sev''mişim, sende...İstanbul''um! 

- - -

Bir şehir ki...iki yaka''da...

Boğaz''ı nehir...

Göğü çakır...

Gün batımı bakır...

Ayrılığı kahır...İstanbul''um! 

- - - 

Taşının değerini Fuzulî bilir...

Yaz, Güz, Kış, Bahar gönül alır...

Şiir''im yetmez ki...yetersiz kalır! 

Güzeldir hepsinden! ..

İstanbul''um! 

                           07.04.2005/12.00', 'Çıkıp da bakmaya ne hacet?  Bir tepesinden... İstanbul''um ki güzeldir!  Hep(i)    sinden... - - - Bir şehir ki...iki yaka''da, Boğaz''ı nehir....', ARRAY['Türk Edebiyatı','Şiir','Atakan Kartaltepe']::text[], 8.5, '{"poet":"Atakan Kartaltepe","poet_slug":"atakan-kartaltepe","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/istanbul-um-serbest-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümceyim', 'gonlumceyim-ayse-birgul-yilmaz-whvar', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İyi günde, kötü günde

Hastalıkta ve sağlıkta

Yarında, bugünde, dünde

Bir ömür aynı yastıkta

Kendimleyim..

Yatağımda, sağımda solumda boş

Yorganım çekilmiyor

Sere serpe ohh ne rahat ne kadar hoş

Uykularım bölünmüyor

Gönlümceyim..', 'İyi günde, kötü günde Hastalıkta ve sağlıkta Yarında, bugünde, dünde Bir ömür aynı yastıkta Kendimleyim.. Yatağımda, sağımda solumda boş Yor...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gonlumceyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ve İstanbul', 'ben-ve-i-stanbul-cem-han-v67du', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzel bir mayıs ayında,bir bebek doğdu cennet gibi bir şehirde...

Bütün sahillerinde tertemiz denizine girilen,

Uskumru diye bir balıktan çiroz yapmak için ip gerilen.

Dolma ve kazıklı yolların yapılmadığı,dalgaların evlerin kıyısını yaladığı,

Martıların bolca balık bulup,sevinç çığlıkları attığı.

İnsanlar da binaları kadar süslü ve güzeldi,

Beyoğlu''na çıkışları görülmeye değer bir şölendi.

Yedi tepe olarak tarihe geçti şimdi oldu on yedi tepe,

Herkes acımadı,hoyratça kullandı tepe,tepe.

Her yerden insanlar akın,akın göç etti koynuna,

Hepsi de ne kadar nankörmüş vurdular boynuna boynuna.

Çocuklar tanımadı bu şehirde ağacın filizini,

Hepsi betonlarla büyüdü,orman sandı demirin filizini.

Güya gerdanlıkmış köprü yapıp bizi kandırdılar,

Bir ucundan diğer ucuna geçmek isteyenlerin anasını ağlattılar.

Şimdi denizinin altı kalmıştı delinmedik,

İnsanlara yaptıracaklar galiba Köstebeklik.

Yenilik,medeniyet,uygarlık için kursunlar bir sistem,

Ama öldürmesinler İstanbul''umun güzelliğini,doğallığını,

Benimkisi sadece bir sitem...', 'Güzel bir mayıs ayında,bir bebek doğdu cennet gibi bir şehirde... Bütün sahillerinde tertemiz denizine girilen, Uskumru diye bir balıktan çi...', ARRAY['Türk Edebiyatı','Şiir','Cem Han']::text[], 8.5, '{"poet":"Cem Han","poet_slug":"cem-han","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-ve-istanbul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennemde Yer Kalmadı!', 'cehennemde-yer-kalmadi-ayse-birgul-yilmaz-x2hbb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Günahlar hep harabe yüzlere gülümsüyor 

Kinci, öfkeli yüreklerde ihanetler harlanıyor

Sevginin goncası hoyrat ellerde çürüyor

Başı dönen başıboş korkular darlanıyor…

Utancın yangını çığ gibi büyüyor

Kurt sürüleri çıktı karanlık sığınağından

Seyyar iblisler fırladı kirli yatağından

Herkes kendi penceresi ardında acı çekiyor

Perdeler sırılsıklam! Kıymeti bilinmeli,

Bir nimettir yaşamak, büyük bir şanstır…

Soğuk gecelerin kabus dolu yığınağından

Yalvaran gözlerle bakan can çekişen köpekler,

Kediler ağlıyor acımasızlığa bir umut bekliyor

İstanbul’un cıvıl cıcıl geceleri saat 24 den sonraki sokağında

Birkaç çöpçüden başka kimseler kalmadı.

Bütün caddeler yitirdi saflığını, trenler, istasyonlar

Telefon kulübeleri, otobüs durakları, okullar, meydanlar

Hasta haneler, evler.. fırlamış gözlü eşkıyalarla dolu

Köşe başları esrar, afyon, tiner, dehşet kokuyor.

Sokaklar ortasında namus adına dökülen kanlar..

Çocuklarımıza anlatacak hayalet masallarımız var

Çaresizliğe gebe hüzünlü bakışlı kadınların 

Lekelenmiş eteklerinden başsız çocuklar doğuyor

Cami avlularında terk edilip adına kader diniliyor

Hayat ve sorunlar sanki bir çekiç 

Zalimlik, hainlik paslı bir çivi

Kalmadı huzur kayboldu sevinç

Kaybettik seyrimizi, güvenimizi 

Bu zorbalığı kaldırabilir mi, hangi vinç? 

Masumluk, ahlak ve vicdanlar ahlaksızlarca edildi linç

Bir şeyler yapmalı, bir şeyler yapmalı..

Kahpe ellerin sülalesi kırılmalı

Rakının beyazlığına kan damladı

Cehennemde yer kalmadı…

29/03/2005', 'Günahlar hep harabe yüzlere gülümsüyor  Kinci, öfkeli yüreklerde ihanetler harlanıyor Sevginin goncası hoyrat ellerde çürüyor Başı dönen baş...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/cehennemde-yer-kalmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yarası', 'gul-yarasi-hamit-kunt-25xi5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilir misiniz

Bülbül hiç gül dalına konmamış

Güle hiç dokunmamış

Ama gülden başka bir çiçeğe

Ömründe hiç yanmamış

Biliyormuş ki bülbül

Konarsa güle

Gül dokunursa bülbüle

Ne gülde koku kalır 

Ne bülbülde figan

Yanık yanık seherlerde

                           Hamit Kunt 

       	           07/04/2005

 	                İzmir', 'Bilir misiniz Bülbül hiç gül dalına konmamış Güle hiç dokunmamış Ama gülden başka bir çiçeğe Ömründe hiç yanmamış Biliyormuş ki bülbül Konar...', ARRAY['Türk Edebiyatı','Şiir','Hamit Kunt']::text[], 8.5, '{"poet":"Hamit Kunt","poet_slug":"hamit-kunt","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gul-yarasi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalga Dalgadır', 'dalga-dalgadir-sadik-softa-jojy7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Canımda bağlıdır bilmez misiniz,

Al rengi damarda dalga dalgadır.

Hürriyetin timsalidir  burçlarda,

Rüzgar esse şanla dalga dalgadır.

Daha dün İzmir’de ne demiş Önder? 

Bayramda sevincim, düğünde önder,

Türk milleti varken,boş kalmaz gönder.

Gönder dopdoludur dalga dalgadır.

Güzellikte eşi yoktur dünyada,

Türk’ten başka düşü yoktur dünyada,

Millet vardır, kişi yoktur dünyada,

Bir dünya onunla dalga dalgadır.

Nazı ve edası bağlar gönlümü,

Sevgisi,sevdası bağlar gönlümü,

Şehidi, mevtası bağlar gönlümü,

O’na olan aşkım dalga dalgadır.

Keyif ile bayrak dalgalanınca,

Şahlanır bu millet darda kalınca,

Ardına hiç bakmaz karar alınca,

Yücelir tüm ruhlar dalga dalgadır.', 'Canımda bağlıdır bilmez misiniz, Al rengi damarda dalga dalgadır. Hürriyetin timsalidir  burçlarda, Rüzgar esse şanla dalga dalgadır. Daha d...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dalga-dalgadir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalı Mektuplar...3 (Şiir)', 'sevdali-mektuplar-3-siir-zulfikar-yapar-kaleli-7zmc6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dertlerini yüreğime dert ettim

Kan ağlıyor, oyuluyor bitanem.

Hasretinle yandım, eridim, bittim

Feryat, figan duyuluyor bitanem.

Seni sevda düzlerinde aradım

Nur-u Kur’an sözlerinde aradım

Seni senin gözlerinde aradım.

Duman dağa yayılıyor bitanem.

Hal-hatır sorarım, ruhumu emer

Anılarım beni maziye gömer

Derler ki; Yasemin erden daha er

Delikanlı sayılıyor bitanem.

Bu kaçıncı cemre, gönlüme düşen

Bu kaçıncı elem, yürekte şişen

Bu kaçıncı sitem, kabrimi eşen

Selam yola koyuluyor bitanem.

Ellerine kara kına yakan da

Vuslat ağlar, ta uzaktan bakan da

Sevda bitse, sevgi ağlar o anda

Sebepsizce uyuluyor bitanem.

Sen ağlarsan, zaman ağlar, yar ağlar

Selam ağlar, sitem ağlar, ar ağlar

Bülbül feryat eder, bağda bar ağlar

Sevdalara kıyılıyor bitanem.

Özlemlerim körük, yollarım ırak

Sızlarım, yakamı bırakmaz merak

Her türlü duyguyu bir yana bırak

Bazen sözden cayılıyor bitanem.

Anlar mısın beni, duyar mı bilmem? 

Ahı-vahı  yana koyar mı bilmem? 

Yoksa beni elden sayar mı bilmem? 

Bayılanlar ayılıyor bitanem.

Kaleli “baba”yı hamura kattın

Alev alev yanan fırına attın

Samsun’dan buraya elin uzattın

Tut diyorsun, “bayılıyor” bitanem.', 'Dertlerini yüreğime dert ettim Kan ağlıyor, oyuluyor bitanem. Hasretinle yandım, eridim, bittim Feryat, figan duyuluyor bitanem. Seni sevda ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sevdali-mektuplar-3-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cunku biz konyaliyiz', 'cunku-biz-konyaliyiz-husamettin-guven-eyhd3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Konyaliyiz gururluyuz

Mevlanayla ovunuruz

Mertligin tek makaniyiz

Cunku biz konyaliyiz

Bos laflari hic sevmeyiz

Mal,mulk ile ovunmeyiz

Insanlikta tek ornegiz

Cunku biz konyaliyiz

Iyiligi cok severiz

Kotuluge yermeyiz

Kalp kirmayi hic sevmeyiz

Cunku biz konyaliyiz

Hollanda', 'Konyaliyiz gururluyuz Mevlanayla ovunuruz Mertligin tek makaniyiz Cunku biz konyaliyiz Bos laflari hic sevmeyiz Mal,mulk ile ovunmeyiz Insan...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cunku-biz-konyaliyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda sümsüklenmiş..', 'sevda-sumsuklenmis-galip-kemali-gunay-zgsd9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''''Sevda'''' lanıyorduk şiirde.tertemiz

Bak sen sümsüğe sevda şifre imiş

Nurlarının canlarının edası, ondan imiş

Düşün Türkçe''den, gidin..çanıza, mertebe imiş..

Yıkarız.. yani yunarız sevdamızı, kelime bizim

Sen ay, ay lav yu  den, ötelerinden

Kulların da uyanıyor ha,düşündün mü neden, şimdi seni lavlıyorlar

Yunarız sevdayı. yıkarız, bi al damla da bizden

Mustafaları hepden sen, hep yanacak mı sandın 

Çek elini sevdalardan', '''''Sevda'''' lanıyorduk şiirde.tertemiz Bak sen sümsüğe sevda şifre imiş Nurlarının canlarının edası, ondan imiş Düşün Türkçe''den, gidin..çanız...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevda-sumsuklenmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lutfen biraz merhamet', 'lutfen-biraz-merhamet-husamettin-guven-m1pdl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Malumunuz yalniz kaldim

Anami ahrete saldim

Etmen ne olur yetim kaldim

Lutfen biraz merhamet

Benim derdim bana yeter

Birgun husamettinde gider

Nicin bana zulum eder

Lutfen biraz merhamet

Sanki bana gulmek haram

Dokunmayin derin yaram

Dostlar desin bahti karam

Lutfen biraz merhamet

Yeter artik allah askina

Donderdin beni saskina

Alma yeter beni karsina

Lutfen biraz merhamet

Hollanda', 'Malumunuz yalniz kaldim Anami ahrete saldim Etmen ne olur yetim kaldim Lutfen biraz merhamet Benim derdim bana yeter Birgun husamettinde gid...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Güven']::text[], 8.5, '{"poet":"Hüsamettin Güven","poet_slug":"husamettin-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/lutfen-biraz-merhamet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi gel felekten bir gün çalalım', 'hadi-gel-felekten-bir-gun-calalim-huseyin-i-rfan-kibrislioglu-b44w4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hadi gel felekten bir gün çalalım seninle bu gün

Şöyle adalara doğru yada daha yükseklere

Yakacık’tan bir köşeye oturalım istersen

İstanbul’a bakıp, bakıp uzaklardan

Batan güne karşı 

Hüzünlenelim biraz. 

Beyoğlu’na gidelim olmazsa

Nevizade sokakta Yorgo ustaya,

Balık pazarında kokoreç, fıçı bira

İstiklal’de kitaplar, kasetler, incik, boncuk,

insan seli, insan sıcağı 

Keyiflenelim biraz. 

Bırak o dümdüz, çok steril yaşayan

ve hayata demir attıklarını sananlar 

uzaklardan seyredip dudak büksünler bize,

bırak onlar yaşamanın anlamını

hayatta gün eskitmek sansınlar yine

Biz inandığımız gibi yaşayalım hayatı

Şarkıyla, türküyle, şiirle, meyle

Ve elbette ki sonsuza kadar Sevgiyle.', 'Hadi gel felekten bir gün çalalım seninle bu gün Şöyle adalara doğru yada daha yükseklere Yakacık’tan bir köşeye oturalım istersen İstanbul’...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin İrfan Kıbrıslıoğlu']::text[], 8.5, '{"poet":"Hüseyin İrfan Kıbrıslıoğlu","poet_slug":"huseyin-i-rfan-kibrislioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hadi-gel-felekten-bir-gun-calalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalanların Ardından', 'kalanlarin-ardindan-cetin-hacifettahoglu-4qf1a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sarılsam Ağlasam Dizlerinde

Gökyüzü Doldursan İçime

Koynuna Süzülse Yaşlarım

Islak Nemli Kalırmı Hatıralarım

Hep Aynı Yerde

Hep Aynı Perde 

Ve Garip Bir Rüzgar Var Yine O Pencerede

Ben Yağmurum

Nefesim Susar

Susarda Nefesim

Şimşek Çakar Gözlerim

Yine Sırlarımız Geçiyor Sokaklardan

Haykırıyor Yedi Düvel

Saklı Kalan Yanlarımızı

Seni Yitirmek Uğruna Düşmüşüm Ağızlara

Tükürürler Beni Her Sokak Başlarına

Yine Her Yağmur Yağdığında Akıp Gelirim Pencerenin Altına

Şimdi Yoksun O Pencerede

Ne Rüzgarlar Esti Boş Kalan Duvarına

Bense Hep O Sokak Lambasının Altında

Bekliyorum Hala….', 'Sarılsam Ağlasam Dizlerinde Gökyüzü Doldursan İçime Koynuna Süzülse Yaşlarım Islak Nemli Kalırmı Hatıralarım Hep Aynı Yerde Hep Aynı Perde  ...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kalanlarin-ardindan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzur', 'huzur-adulera-ayza-cwqxk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşümde düş gördüm

Işık süzmesi idim öldüm

Seni gördüm

Ama öldüm

Hayalde olsa anımsıyorum

Benim yanıma geliyorsun

Sevdiğini söylüyorsun

Uyanıyorum 

Ağzımın içinde bir tat

Senin beni sevdiğini

Söylediğin bir tat

Artık ölsem de gam yemem

Umarım diliyorum 

Biliyorum

Sende benim gibi

Mezarında rahat yat', 'Düşümde düş gördüm Işık süzmesi idim öldüm Seni gördüm Ama öldüm Hayalde olsa anımsıyorum Benim yanıma geliyorsun Sevdiğini söylüyorsun Uyan...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/huzur-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resim Şiir idi...Vallahi de.Bilmedi, kendini de Sarıkız..', 'resim-siir-idi-vallahi-de-bilmedi-kendini-de-sarikiz-galip-kemali-gunay-fvgoj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şiir idi resimi

Kazdağı''nda çektiğim

Koynum oldu çerçeve 

Çamlar altı gezerken

Bir gördü de gürledi 

Kim kim dedi kim bu kız

Vallahi de bilmedi, kendini de

Sarıkız', 'Şiir idi resimi Kazdağı''nda çektiğim Koynum oldu çerçeve  Çamlar altı gezerken Bir gördü de gürledi  Kim kim dedi kim bu kız Vallahi de bilm...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/resim-siir-idi-vallahi-de-bilmedi-kendini-de-sarikiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Çiçeğim', 'guz-cicegim-meral-vurgun-84lib', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ay süzüldü, gün dolandı

çözüldü belik belik 

döküldü karası zülüf tellerinin

karbeyaz cadde sokak bütün şehirler

ince bir kurt kıvrıla kemire 

için için deldi kökünden ucuna 

devrildi bir arşın boyu servinin

damar damar yırtıldı yapraklar mevsimsiz

gökte bulut kurudu, toprak çatladı 

savruldu, kavruldu susuzluktan yeşil

kara meşe dalları kaldırdılar başını göğe

saçları yolunmuş kel tepeleri gördüler

yeşil, yeşil olalı böyle dalsız 

can, can olalı böyle yarsız

yoldaşsız kalmamıştı o tepelerde

o tepeler ki

yamaçlarından artları sıra 

aç kurt sürüleri kan izileri süre süre

şahin bakışlı, çelik yürekli

dillerinde bağımsızlık türküleri 

nefer-nefer bizimkiler gelip geçtiler

gün oldu türküleri vuruldu

mızrapsız sızladı telleri ozanın

gün oldu kalemini kırdılar

tırnaklarından döktü şiiri şair 

o tepelerin ardında gelinler

yol gözledi yemen çölleri gibi

babasız çocuklar büyüdü aç arık

şivan düştü, ak memede süt kurudu 

analar tabut salladı beşik beşik

o tepeler uğruna gelinlik kızlar 

altın bilezik gibi kelepçe taşıdı kollarında 

topuklarında pranga sürüdü delikanlılar

denizsiz martı, martısız deniz olmaz

mavisiz saçaklarda güvercinler sevişmez

yağmursuz yuvalarda cıvıldaşmaz serçeler

geri dönmez kırlangıç kuşları ovalara

yıldızlar sulara aysız düşmez

ağla bulut, esirgeme, dök bereketini

başaksız bahar, tarlasız buğday yeşermez

aşk yüreğimizden de çok

bu kara sevdalı seri şimdi

duman olup dağlara vurmak gerek 

tütmez ocaklarda tandırlar yansın

sofralarda aş-ekmek buğulasın

davullar vurulup halaylar kurulsun

ağaçlar dikmek, çoğalmak gerek

tepelerden eteklere ırmaklar çizmek

vadilere akmak, denizlere dolmak 

pul pul balık olmak  gerek

ayışığına mavi yakamozlar sürmek

gecenin karardığı saatlere ışık sermek

ustura gibi yanmak gerek

yıldız toplayıp koyun koyuna yatmak

al güneş bahar şafaklara uyanmak gerek

hani ellerinin nasırı

duymuyorum sesini okşayışlarının

kare kare çöl kıraç tende akkor

dipsiz uçurumlara akıyor kanım

sen o dağlarda bir salkım söğüt dalı

ben deli bir rüzgâr uzaklarda

yaktığımız ateşlere döke döke 

neşterleyip bileklerimizden

kopara kopara kılcal damarlarımızı

mevsimler gelip geçti üzerimizden 

artık yoksun bırakma beni senden

saçlarımla süpürmeliyim sevgileri

yar, yaren, yavuklu

yoldaş gibi dayanmalısın omuzuma

erguvan kokmalı terin

kara imge''m

güz çiçeğim

soysuz sevdalara inat

öyle gelmelisin ki bana

sol yanın dağ olmalı 

dilerse dönmesin 

varsın dursun bu devri kâinat...', 'ay süzüldü, gün dolandı çözüldü belik belik  döküldü karası zülüf tellerinin karbeyaz cadde sokak bütün şehirler ince bir kurt kıvrıla kemir...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/guz-cicegim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlaydanın Güncesi', 'i-laydanin-guncesi-birsen-ates-0uoca', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yalnızlığın

tam ortasındayım

dibe vurmuş

boşlukta asılmış

kanayan duygularım

acı

acım

acılarım

bedenime sarılı

dikenli tellerim

silindi

yaşam renklerim

geçen günler

ruhuma örtülü perde

artık uzak denizlerin

fırtınasıyım

dalgalı ve hırçın

kıyılarında tekneler batıran

gittiğinde

günlerce düşündüm

sana doğru koşmak

seninle ölmek

istedim

çaresizlik 

korkularım

Ö l ü m

sen bir kere öldün

bu şuursuz kentte

acılarımla

yalnızlığımla

her gün ölüyorum

ö l ü / y o r u m', 'yalnızlığın tam ortasındayım dibe vurmuş boşlukta asılmış kanayan duygularım acı acım acılarım bedenime sarılı dikenli tellerim silindi yaşa...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ilaydanin-guncesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir... ''''Allahaısmarlandık ya ''''...sen bilirsin ben gibi seni de.. gene de iş de..', 'siir-allahaismarlandik-ya-sen-bilirsin-ben-gibi-seni-de-gene-de-is-de-galip-kemali-gunay-q9jtn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiir be

Yak Ergenekon''u, ver ellerine sapsız tavayı da için döndürsünler

Aç çilenden  bir uç. sal dünyanın ipini de çeksinler

Şiir be elleşme düğümlere, bırak çözsünler 

Çözsünler de görsünler', 'Şiir be Yak Ergenekon''u, ver ellerine sapsız tavayı da için döndürsünler Aç çilenden  bir uç. sal dünyanın ipini de çeksinler Şiir be elleşm...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/siir-allahaismarlandik-ya-sen-bilirsin-ben-gibi-seni-de-gene-de-is-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun Acıların Çetelesi', 'suskun-acilarin-cetelesi-meltem-kaya-kf0mt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Omzumda bir hayatla öylece dikiliyorum karşında…Çok kalabalıktan gelen azlıktım ben aslında, sen bunu bildin de, o yüzden mi kalabalık bir sevgi sundun üşüyen ellerinle? 

Silik sokaklara yağmurlar düşerken

Ben yalnızlığa vuruldum

Bir sokak başında buldular beni

Adım hükümsüzdü…

Boynumda inci bir kolye gibi salınan günler, acının tekkesiydi en çok da… Susuşun sesini bölüştüğümüz günlerde gözlerimiz o yağmura yakalandı. Sen yağmurdan sızladığımı anladın da, o yüzden mi gözlerinde bir avuç yağmur taşıdın? 

Bal koyusu gözler ayrılığı tattı

Kavuşmak imkansız bir ıraktı

Hükümsüzlüğüm kıyıya vururken

Sevdalar uçurumdu…

İçimdeki ağaç kırık dalları bedeninden hiç ayırmadı. Yaşım bahardı, genç ömrüm baharın solgun hazan bahçelerine benzemediğini bilse de, yangından geriye kalan küller közlenmezdi. Sen bunu sezdin de, o yüzden mi içinin yangınından kan kızıl güller derledin bakışlarınla? 

Her evin saçağında sarkıtlar vardı

Güneş ürperen serçeler gibi ıslaktı

Çiçek satan çingene kızın kara bakışları

Elleri gibi ırgat ve poyrazdı…

Dalgakırandaki deniz fenerinin kırmızı ışığı söneli çok oldu. Bir ben bildim yalınayak bir hasretle hala yandığını, bir de sesini uçuramadığın uzaklarda sen bildin, bildim ki gerisi yalan bildi. Sen o ışığı seçtin de, o yüzden mi hiç beklemezken bin kat yerin altından toprağı delen çiğdemler gibi uzandın bana?  

Güvertesi ayak izleri dolu beyaz bir gemi

Hep bildi dalgakırandaki ışığın yerini

Özlem üşütüp dalga ısıtamadığı zaman 

Onulmaz bir yarayla kayalara attı kendini…

Çetelesini tutmadım uyuduğum ölüm uykularının, neden uyandığımı kendime hiç sormadım. Yüreğim donduğu anda, bir avuç kar gibi hasretinle ovuşturup yaşattım yüreğimi… Sen yorgunluğumu görüp de, o yüzden mi kar soğuğunda iğde kokan sabahlara taşıdın beni? 

Şarap masada duruyordu ben içmedim onu

Ama Hayyam kadar sevdim üzümün eflatunluğunu

Mevsimler pencereme saran asma dalıydı

Her akşam kalbimi vura vura izledim koyuluğunu…

Omzumda bir hayatla öylece dikiliyorum karşında…Bir nehir gibi aktıkça sen derinleşiyorum. Yaralarımı öptükçe iyileşiyorum. Adım hükümsüz değil… Saçlarımı savuran rüzgarın bana fısıldadıklarını dinlerken kıyıya vuran bedenim bir limanda soluklanıyor. Artık yokluğunla sınama beni, gözlerinle dokunduğun yüreğim, mavisi yazgısını reddeden bir denizin af dilemez soluğuna kilitlidir.', 'Omzumda bir hayatla öylece dikiliyorum karşında…Çok kalabalıktan gelen azlıktım ben aslında, sen bunu bildin de, o yüzden mi kalabalık bir s...', ARRAY['Türk Edebiyatı','Şiir','Meltem Kaya']::text[], 8.5, '{"poet":"Meltem Kaya","poet_slug":"meltem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/suskun-acilarin-cetelesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Güzel İstanbul...', 'ah-guzel-i-stanbul-ugur-deniz-ulkegul-lep1o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiir yazcem İstanbul’a okunsun diye

İstanbul’da martılara dokunsun diye

Martılara dokununca dökünsün diye

Balıklara yem olacak sözümüz gaari

Valla bunu söylemezsem çatlar giderim

Bi punduna getirmezsem patlar giderim

Sözüm çoktur arada bir atlar giderim

Azınlığa muhaliftir çoğumuz gaari

Güzel şeyler yazcem emme içim almeyo

Biraz moral bozcem emme açım kalmeyo

İstanbul’da işlenmedik suçum olmeyo 

Gönül var da kırık bizim sazımız gaari

Geceleyin kondulara tapunuz nerde

Hırsızına arsızına topunuz nerde

Haksızlığa açılacak kapınız nerde 

“Kaçak” diye koyvereeyo sözünüz gaari

Sokaktaki kadınlara eviniz var mı 

Yetim kalmış çocuklara seviniz var mı 

Kap kaçlara vur kaçlara savınız var mı 

Konuştukça kızareeyo yüzünüz gaari

Beyoğlunda gece vakti dolaşın biraz

Sarhoş, ayyaş, travesti dalaşın biraz

Yanlış yere arabayla yanaşın biraz

Gerdi hemen yüzünüzü gezimiz gaari

Yağmur yağdı  İstanbul’u seller baseyo

Arap kızı bizim kıza camdan bakeyo

Sular damdan değil emmi yoldan akeyo

Fazla geldi suyunuza  kurumuz gaari

Otobüste sıkışınca  gerileeyom ben

Şoför bana çıkışınca  darıleeyom ben

İstif olup her birine sarıleeyom ben

Fortçu diye anılacak  adımız gaari

Gülhane’nin parkındaki ceviz ağacı

Selam verir Sirkeci’ de tren garına

Cennet  idir İstanbul’un ucu bucağı

Duyulur mu bilemeeyom sesimiz gaari', 'Şiir yazcem İstanbul’a okunsun diye İstanbul’da martılara dokunsun diye Martılara dokununca dökünsün diye Balıklara yem olacak sözümüz gaari...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ah-guzel-istanbul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satarım Dünyayı.', 'satarim-dunyayi-suheyl-turkoglu-1dlpb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Satarım dünyayı,

Hiç düşünmeden,

Birileri çıkıp,

Bedelini öderse.

Eski ideallerim,

Çöp arabasında,

Boğazıma çöküyor,

Acımasız gerçekler.

Kim vurduya gitti,

Koca ömür,

Başımda dolanıyor,

Eli sopalı yıllar.

Telafi etmiyor,

''Keşke'' demek,

Yanlışlara uyanmak,

Geleceğe yetmiyor.

Güçlüyken kırdığım,

Çelik zincirler,

Şimdi halkalarla,

Vücudumu sarıyor.

Hergün etrafımda,

Yağmurla fırtınalar,

Farkında olamadım,

Kesemden gitti Bahar.

İsyanımda haksızım,

Doğan güneşe,

Işığını pazarladım,

Gitti beleşe.

Fantazi değil,

Vallahi istiyorum,

Uygun fiat verene,

Satarım dünyayı.', 'Satarım dünyayı, Hiç düşünmeden, Birileri çıkıp, Bedelini öderse. Eski ideallerim, Çöp arabasında, Boğazıma çöküyor, Acımasız gerçekler. Kim...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/satarim-dunyayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkek Adam Ağlamaz', 'erkek-adam-aglamaz-ahmet-agdere-xpjbk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şaka bir yana, ağlamayalı çok oldu.. 

Mantığım duygularımdan önde olduğundan olsa gerek. 

Halbuki eskiden ne çok ağlardım. 

İstediğimi elde edemeyince, 

Sevdiklerim ölünce, 

Aşık olunca, 

Ve aşkımın sorunlarını görünce. 

En çok ta hesap makinalı aterimi kaybedince ağlamıştım 

O da babamdan korkumdan, 

Tabiatı çok serttir babamın 

Godum mu oturtan cinsten.. 

Şimdi her ne kadar duygulu olsam da, 

Ağlayamıyorum aşıkken, 

Veya yastayken.. 

İsteklerim veya korkularım mı? 

Çocukluğu bırakalı seneler oldu...', 'Şaka bir yana, ağlamayalı çok oldu..  Mantığım duygularımdan önde olduğundan olsa gerek.  Halbuki eskiden ne çok ağlardım.  İstediğimi elde ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/erkek-adam-aglamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayanım', 'yasayanim-sair-mavinin-karanligi-2xdim', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim için kurulmuş bir hayatın ortasındayım

Sadece ben ve koskoca evren

Benim kavgam kendimle

Sen anlayamassın gözyaşlarımı

Çünkü sen ruhsuz bir dünyanın kuklası

Çekil karşımdan defol

Anlayamassın karanlığın seslenişini

Benim kavgam kendimle

Yaşamayı başaramadığım dünyamla

Yalan hayallerim ve ikiyüzlü duygularımla

Beynimi zorluyorum açık kapı bulamıyorum

Yorgunum belki tembel

Doyumsuzum belki ruhsuz

Aşksızım belki kimsesiz

Dilim bile beceriksiz

Ömrüm  boyunca zevksiz

Gözyaşlarım acılarım ve sevgim

Kimseyi sevmek istemiyorum 

Yalnız bir savaşcıyım ben

Tek başına yaşayan bir dünyayım

İnsanlar anlamıyor beni

Deli olmak istiyorum

Karışık duygularımı ben anlamak istiyorum

Çarem yok tedavim yok

Ölüm var

Dermanım yok

Çözemiyorum ayrıca hayatımın bilmecesini

Sıradan bir varlıkta olmak istemiyorum

Şiiri bile tadında bulamıyorum

Açım

Herşeye aklına ne geliyorsa herşeye

Sevgisizim

Saygısızım

Yanlızım

Sensizim

Bul beni ey hayat doğru yaşa 

Bende seni

Çıkar beni bu karanlık çukurdan

Bul beni YAŞA ey kurtuluşum

ÇIKMAZIM 

ÇIKMAZDAYIM', 'Benim için kurulmuş bir hayatın ortasındayım Sadece ben ve koskoca evren Benim kavgam kendimle Sen anlayamassın gözyaşlarımı Çünkü sen ruhsu...', ARRAY['Türk Edebiyatı','Şiir','Şair Mavinin_karanlığı']::text[], 8.5, '{"poet":"Şair Mavinin_karanlığı","poet_slug":"sair-mavinin-karanligi","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yasayanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebe', 'ebe-aysun-erat-8sb9p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şaşkınım sadece.

Üzgün değilim.

Hayatın bu anlamsız oyunlarını

Daha önce de görmüştüm.

Ruhları bedenlerini terk etmiş insanlar var, biliyorum

Sayılamayacak kadar…

Rollerini ezberlemiş oynuyorlar usta oyuncu gibi.

Kabiliyet istiyor elbette.

Bir de şeytanla anlaşmalı olmak.

Ben bir türlü yapamadım bunu

Şeytan beni sevemedi nedense.

Ellerim var benim

Gözlerim, ayaklarım.

Dudaklarım öpmek için.

Ve yüreğim,

Yanmak için.

Ben beceremedim bir türlü…

Ebe kaldım her oyunda.

Sobeleyemedim.

Beceremedim..

04/2005', 'Şaşkınım sadece. Üzgün değilim. Hayatın bu anlamsız oyunlarını Daha önce de görmüştüm. Ruhları bedenlerini terk etmiş insanlar var, biliyoru...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ebe-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram', 'bayram-bayram-simsekoglu-38pbm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kolayıma geldi,

şiir yazdım.

Pişmanım.

Sensiz Nazım olacağıma,

senle bayram etmeli,

her gün.', 'Kolayıma geldi, şiir yazdım. Pişmanım. Sensiz Nazım olacağıma, senle bayram etmeli, her gün....', ARRAY['Türk Edebiyatı','Şiir','Bayram Şimşekoğlu']::text[], 8.5, '{"poet":"Bayram Şimşekoğlu","poet_slug":"bayram-simsekoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bayram-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cebroldum Tezine,,Sorun Cevabın İçinde..Üçü Kümeden ve X,YŞiir, Kare Kökü,''Cin '''' ''''BİR'''' KIZ ''Elde varım, ''''BİR'''', Bir Şiir', 'cebroldum-tezine-sorun-cevabin-i-cinde-ucu-kumeden-ve-x-ysiir-kare-koku-cin-bi-r-kiz-elde-varim-bi-r-bir-siir-galip-kemali-gunay-eq4nr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başlıkdan devam...

Beşbenzemez beş mısralı 

Beş şiiri 

Cebr etsem 

Kümelesen mısraları

Beş şiirde 

Beşbenzemez...

Yeni meselen de bu

Hadi bakalım

*Çözümüm, üçü kümeden ikisi x, y benden, beşe ayırdım yanıtını. bir şiir buldum, beş mısralı. bu bir şiir eder,

.nerde gizemi.''''..', 'Başlıkdan devam... Beşbenzemez beş mısralı  Beş şiiri  Cebr etsem  Kümelesen mısraları Beş şiirde  Beşbenzemez... Yeni meselen de bu Hadi ba...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cebroldum-tezine-sorun-cevabin-icinde-ucu-kumeden-ve-x-ysiir-kare-koku-cin-bir-kiz-elde-varim-bir-bir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karmaşa', 'karmasa-serhat-aksungur-uk9ym', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dışardan yakınsama bizimkisi

Uzak iklimlerin beklentisi

Yakınlaştıkça o noktaya

Giden şairin dediği gibi; 

Utanmamak için kaçtım oraya.

Demişti oysa ki saydam adam

''Elini çabuk tut, git uyandırmadan! ''

Mesafelerin tayini sığmazken geometriye

İsyan,

Rahat durmayan benliğe.

Cinayet saati hızla yaklaşmada

İntihar mı bu, yaşamak mı komada? ...', 'Dışardan yakınsama bizimkisi Uzak iklimlerin beklentisi Yakınlaştıkça o noktaya Giden şairin dediği gibi;  Utanmamak için kaçtım oraya. Demi...', ARRAY['Türk Edebiyatı','Şiir','Serhat Aksungur']::text[], 8.5, '{"poet":"Serhat Aksungur","poet_slug":"serhat-aksungur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karmasa-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanat Sesleri', 'kanat-sesleri-hatice-bediroglu-16orq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana sarıldığımda,

Siliniyor her şey.

En gerçek,

Sen oluyorsun.

Her biri aşk kokan,

Birbirine sevdalı,

Mavi yıldızlar,

Kaplıyor üstümüzü.

Uzanıveriyoruz.

Toprak, çimen, ağaç,

Sevdanın  kokusu,

Harmanlaşıyor.

Mis gibi bir koku,

Yayılıyor ortalığa.

Koklamaya doyamıyoruz.

Gecenin karanlığını,

Aydınlatıyor,

Teninin sıcaklığı.

Alevlerin gölgesi,

Upuzun oluveriyor.

Tenlerimizin sıcaklığı,

Besliyor bu  ateşi.

Gölgelerin boyu,

Ha bire yükseliyor.

Tutkunun kırmızısını,

Ekleyerek sevdamıza,

Yorgun düşünceye dek,

Seviyoruz birbirimizi.

Ruhlarımız birleşiyor,

Biz, oluyoruz.

Yüreğimizde,

Uçan kuşların,

Kanat sesleri.

www.haticebediroglu.net

(Şiirlerimin hepsi Noter tasdiklidir)', 'Sana sarıldığımda, Siliniyor her şey. En gerçek, Sen oluyorsun. Her biri aşk kokan, Birbirine sevdalı, Mavi yıldızlar, Kaplıyor üstümüzü. Uz...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kanat-sesleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtyol', 'dortyol-gokhan-oflazoglu-t51e1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İşte dörtyol ağzı

artık geldiğin.

Seçeceğin; yazgın

olsa da sen aldırma.

Belki çok kırıldın

ya da umarsızsın.

Her durumda 

duyumsadığın; 

temiz yüreğin,

vazgeçilmezin.

İndirir yere gökyüzünü.

08/04/2005', 'İşte dörtyol ağzı artık geldiğin. Seçeceğin; yazgın olsa da sen aldırma. Belki çok kırıldın ya da umarsızsın. Her durumda  duyumsadığın;  te...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dortyol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahte yüzler', 'sahte-yuzler-dursun-onal-6s9du', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hangi yüzlere baksan ihanet

Sevgileri kim çaldıki bizden

Kimden bu zulüm bu eziyet

Yalandan sevmeler olmuş meziyet

Kime güvenip başımız çevirdiysek

Dostum arkadaşım canım dediysek

Yüreğimizi ellerine verdiysek

Çektirdiler bize binbir eziyet

Bir damla gözyaşına sığınmış gülücükler

Sevgi hangi yüreklerde saklı görünmez

İblis olmuş dost bildiğimiz yüzler

Melekten geçtik insanlık nerde bilinmez

Nereye bakarsan hep sahte yüzler

Yalandan akıtır oldu yaşları gözler

Yüzüne bakarak göremezsin kalbini

Yüzü gibi gülümsermi kalbi görünmez', 'Hangi yüzlere baksan ihanet Sevgileri kim çaldıki bizden Kimden bu zulüm bu eziyet Yalandan sevmeler olmuş meziyet Kime güvenip başımız çevi...', ARRAY['Türk Edebiyatı','Şiir','Dursun Onal']::text[], 8.5, '{"poet":"Dursun Onal","poet_slug":"dursun-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sahte-yuzler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Prangalar', 'prangalar-dursun-onal-mmo8w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yokluğunda çok prangalar eskittim

Göçüp gitti gülücükler bilinmez diyarlara

Gözlerim yaş yerine kan ağladı

Bilsen ben bu gözlerle ne prangalar çürüttüm

Yokluğunda çok günahlar işledim

İsyanlar savurdum sensiz günlerime

Ellere diken oldu sözlerim

Bilsen ben bu sözlerle ne prangalar çürüttüm

Yokluğunda çok günler öldüm

Adını her andığımda ruhum koptu bedenimden

Dizlerim tutmaz oldu bitkinlikten

Bilsen ben bu dizlerle ne prangalar çiğnedim

Yokluğunda çok kez gündüzüme gece kattım

Seni düşündüm karanlıkla birlikte

Gülüşünü düşündüm birde ansızın sarışını

Bilsen sen, yokluğunda ne prangalar vurdun bana

Yokluğunda çoğu zaman yüreğim prangalar eskitti

Çoğu zamanda prangalar yüreğimi

Yalan dostluklara zamanla alışıyor insan

Bilsen yalan dostluklar yüreğime ne prangalar vurdu', 'Yokluğunda çok prangalar eskittim Göçüp gitti gülücükler bilinmez diyarlara Gözlerim yaş yerine kan ağladı Bilsen ben bu gözlerle ne prangal...', ARRAY['Türk Edebiyatı','Şiir','Dursun Onal']::text[], 8.5, '{"poet":"Dursun Onal","poet_slug":"dursun-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/prangalar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutla bekliyorum', 'umutla-bekliyorum-dursun-onal-mzmbe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni hayelde de olsa paylaştığımı düşündüğümde

Sanki oklar saplanıyor benim beynime

Kıskançlığımdan sert rüzgarlar içimi yalayıp geçti

Derinden, zehir gibi bir acı oluştu sanki içimde

Bak bugünde akşam oldu,  yıkıldım olduğum yere

Kendi kendimle büyük savaşlar veriyorum yine

Her defasında yenik düşüyorum yine kendime

Gök yüzüne baktığımda senin yıldızın parlamıyordu yine

Dinlediğim şarkılarda bulamıyorum eskisi gibi seni

Yine ufuklara bakıyorum ama, göremiyorum gözlerini

İşte o zaman, bir kez daha anlıyorum seni sevdiğimi

Benim seni sevmem değil, senin beni sevmen bağladı sana beni

Her güneş batımında, akşamın mehtabında, sende yoksun artık resminde

Yavaş yavaş doğan güneşin ışığını göremiyorum artık sende

Sen beni bende, seni sana hapsettiğinde

Mezara gömdün beni, duygularının esiri olarak bırakıp gittiğinde

Senin yokluğunda yeni aşklara kapattım gönlümün kapılarını

Belki birgün tekrar geleceğini düşündüğümden

Seni düşündükçe durduramıyorum yüreğimin sancılarını

Hep bir kıvılcımla alevleneceğini düşünüp duruyorum ben

Sevgi umuduyla bekliyorum, olmazsa bir başka zamana

Bu defa olmadı belki, umudum tutuyor beni ayakta', 'Seni hayelde de olsa paylaştığımı düşündüğümde Sanki oklar saplanıyor benim beynime Kıskançlığımdan sert rüzgarlar içimi yalayıp geçti Derin...', ARRAY['Türk Edebiyatı','Şiir','Dursun Onal']::text[], 8.5, '{"poet":"Dursun Onal","poet_slug":"dursun-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/umutla-bekliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar ne bilir', 'onlar-ne-bilir-dursun-onal-6bn46', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Onlar nereden bilir seni sevmenin tadını

Onlar koca kalabalıklarda yalnız kaldımıki

Geceler boyu yalnızlığına ağladımı

Hiç silip tüm gülücükleri masum yüzlerinden

Umudunu bir telefona bağladımı ki

Onlar hasreti hiç damarlarında hissettimi

Başını yastığa koyupta uykuyla savaştımı

Bakıp bakıp bir cansız resme, seni seviyorum dedimi

Onlar kavuşmanın acı sabırsızlığını yaşadımı ki

Onlar hiç sevgisiz kaldımı ki hayatta

Sevgisizliğin ne olduğunu bildilermi ki

Bir tarafları eksik kaldı can damarları kesildimi

Bir yalnızlıktır ki aldımı akıllarını

Onlar sevmenin güzel yanını tattımı ki

Kilometrelerce uzaktan tenlerini hissettimi sevdiklerinin

Her telefon konuşmasında sevdiğinin tatlı sesiyle

Aşık olmanın, ayrı kalmanın sızısını yüreğinde hissettimi ki

Yada bırakıp tüm kabusları geceye

Rüyaların en güzelini sevdiğine ayırdımı ki

Ne bilir onlar, sevdanın, hava kadar nefes kadar gerekliliğini

Ne bilir onlar, candan sevmeyi sevilmeyi bir sor bakalım

Onlar benim seni sevdiğim kadar kimseyi sevdilermi ki', 'Onlar nereden bilir seni sevmenin tadını Onlar koca kalabalıklarda yalnız kaldımıki Geceler boyu yalnızlığına ağladımı Hiç silip tüm gülücük...', ARRAY['Türk Edebiyatı','Şiir','Dursun Onal']::text[], 8.5, '{"poet":"Dursun Onal","poet_slug":"dursun-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/onlar-ne-bilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk... İki Yürek...', 'bir-ask-i-ki-yurek-ugur-deniz-ulkegul-t2iek', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dokunmak var mı sıcağına elinin,

Söyle kadın, bu şehir verir mi bana seni…

Bak, yine düştüm peşine çekip gitmelerin,

Meteliksiz cebimde saklarım gözlerini…

Denize attım düşlerimin gizini,

Sancılı yakamozların ışığındadır gece,

Koynumda sakladığım dalga seslerini,

Duyduğun gün çözülür bu zor bilmece… 

Kolay değildir…

Zaman aşımı yol alışlarda,

Hükümsüz gelmelerin sürgünü olmak…

Kolay değildir…

Buz tutarken avuçları adamın,

Dumansız bir alevin, korunda yanmak…

Okşamak var mı saçlarının telini,

Ve bilmek,

Yastığa düşen yorgunluğumun sebebini…

Sende kovmak geceyi, sabahı karşılamak,

Ve tek bir uyanışa prangalamak gözlerini…

De ki söylesin şehir,

Hangi duvar çalmıştır gözlerinin rengini…

Ve hangi ağaç saklar dalında yüreğini…

Hangi buluta astın, de ki bileyim,

Kokusuna yol aldığım özlemlerini…

Molasında yer tutmuşken belanın,

Ertesine sancılandık sevdanın…

İsim koyma zamansızlığına kadın,

Sır tutalım bu aşkın, gel-gitlerini…

Kolay değildir…

İki sözden bir kelam çıkarabilmek…

Bilirim kolay değildir elbet,

Bir kelamda iki söz anlatabilmek…

Lakin bir olmaktır mesele,

Bir şehir, bir ülke, bir deniz…

Bir adam, bir kadın, bir de aşk! 

Anlatılmasa da olur bizim hikayemiz…', 'Dokunmak var mı sıcağına elinin, Söyle kadın, bu şehir verir mi bana seni… Bak, yine düştüm peşine çekip gitmelerin, Meteliksiz cebimde sakl...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bir-ask-iki-yurek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Durak', 'son-durak-aynur-i-lkay-wob01', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sessizce ruh ucmus bedenden

		Herkes konusuyor gidenden

		Gitmis artik ne gelir elden

		Son duraga ilerliyoruz

		Kosede o sessizce yatiyor

		Onune gelen dua yapiyor

		Inanmayan gozlerle bakiyor

		Son duraga ilerliyoruz

		

		Genc bir askermis bir zamanlar

		Serilmis aldigi nisanlar

		Resimlerde mutlu oldugu anlar

		Son duraga ilerliyoruz

		

		Ailesi uzgun ugurluyor

		Es dost gelip soyle ugruyor

		Unutulan dostlar buluyor

		Son duraga ilerliyoruz

		Hep siramiz gelecek bir gun

		Mazi geride kalan her gun

		Vucut ancak ruhla bir butun

		Son duraga ilerliyoruz

		

		Aynur Ilkay

		23 Agustos 2003

		Niagara Ont.

		Kanada', 'Sessizce ruh ucmus bedenden 		Herkes konusuyor gidenden 		Gitmis artik ne gelir elden 		Son duraga ilerliyoruz 		Kosede o sessizce yatiyor 	...', ARRAY['Türk Edebiyatı','Şiir','Aynur İlkay']::text[], 8.5, '{"poet":"Aynur İlkay","poet_slug":"aynur-i-lkay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/son-durak-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım İstanbul', 'canim-i-stanbul-hakan-kilic-8na4t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günahım aşkım ve tüm duygularım

Hayata dair bütün bulgularım

Ani çıkışlarım ve vurgularım

Hepsi sende saklı canım İstanbul

Mısralarda sevdiğim yari andım 

Aşkın ateşiyle kül olup yandım

Kalbimle sana ve aşka inandım

Aldın benden aklı canım İstanbul

Ne günler gördüm, ne aşklar yaşadım

Gül ve dikeni, birlikte okşadım 

Cezam oldu, attığım,her yaş adım

Yanlış da, yasaklı,canım İstanbul

Geçmişe yanışım fayda sağlamaz

Biliyorum,kendi düşen ağlamaz

Gayri bu yürek, artık dayanamaz 

Ver, aldığın aklı, canım İstanbul

Ne güzel sözler,söylemiş atalar

İnsan anlıyor olunca hatalar 

Ne sözcükler yeter, ne de kıtalar

Mısralar yasaklı canım İstanbul

İnsanların gönlünde bir taht kurdun

Umutla gelindi her yandan yurdun

Suçlu dururken, sen suçsuza vurdun

Kim haksız, kim haklı, canım İstanbul

Saf biri buldunmu,kaz gibi yoldun

Çakal''a bir bağ,dürüste dağ oldun

Kimi için, umut dolu bir yoldun 

Garibe, yasaklı canım İstanbul

İnsan bir gün gelir,ve de hatırlar

Der ki, anlatmış geçmişi satırlar

Ve açıklanmayan,o gizli sırlar

Mısralar da saklı canım İstanbul

Herşeye rağmen,yine sevenler mi

Taşı toprağı altın diyenler mi

Yoksa, hayaller ile gelenler mi

Kim haksız,kim haklı,canım İstanbul', 'Günahım aşkım ve tüm duygularım Hayata dair bütün bulgularım Ani çıkışlarım ve vurgularım Hepsi sende saklı canım İstanbul Mısralarda sevdiğ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kılıç']::text[], 8.5, '{"poet":"Hakan Kılıç","poet_slug":"hakan-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/canim-istanbul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ISTANBUL, Boğaziçi''nde Bir Düştür Umutlar..', 'istanbul-bogazici-nde-bir-dustur-umutlar-orkun-isik-rlqz0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cebimde uçurumlarını taşıdığım Şehir! 

Ararken seni içimde, nereye bassam mayın! 

Tutunamıyorum, ellerim sana nasır

Güzelliğinden başka hiç bir yerine …

Seni hep gözyaşımın içinde sakladım

Tutabilmek için seni

Bir bilsen ne kadar ağladım.

Ah İstanbul.

Hep anlattılar güzelliğini

Hal bu ki; 

Benim sevgim anlatamadıkları kadardı.

Anlatmalıydılar seni

İliklerime kadar anlatmalılardı.

Anlattıkları kadar bildim seni,

Anlatanlardan daha çok sevdim seni! 

Ah İstanbul ah! 

Ne kadar çok isterdim,

Martılarına  veremediğim ekmek kırıntılarını

Seninle paylaşmayı.

Ne kadar çok istedim ah! İstedim! 

Korkusuzca yanına yaklaşmayı.

Ya sen! 

Ah Istanbul! 

Dedim ya göz yaşlarım da saklıydın.

Dokunmak istedikçe sana,

Ağlıyordum doyasıya…

Bir an da avuçlarımda büyüyordun, özlem özlem.

Bir Cuma vakti! 

Evet! bir Cuma vakti Sultanahmet de, Eminönü''nde

Secdeye getirseydim alnımı, ah alnımı

Seni güzelleştiren rabbime.

Dua etmek isterdim fevç fevç,

Kavuşmak için her yerine.

Ah İstanbul ah! 

Ne sen sor ahımı

Ne de ben anlatayım vahımı…

İlliğinde niyetlenmek

İftar vakti Oruç açmak! ! 

Doya doya Kızkulesine bakmak.

Ve âşık olmak istemiyorum sana

Ne olursun çalma beni benden.

Ah İstanbul! .. 

Sen misin içimde, ben miyim içinde

Konuş_sana! ..

Sen! benim…', 'Cebimde uçurumlarını taşıdığım Şehir!  Ararken seni içimde, nereye bassam mayın!  Tutunamıyorum, ellerim sana nasır Güzelliğinden başka hiç ...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/istanbul-bogazici-nde-bir-dustur-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nergis Bakışlım-"siz hiç ay aşığında ağladınız mı" Kitabından', 'nergis-bakislim-siz-hic-ay-asiginda-agladiniz-mi-kitabindan-omer-ekinci-micingirt-yozjh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nergis bakışlım gül açmış

Sineme kor sevda saçmış

Bu sevda benide aşmış

Mecnunum nergis bakışlım

Gönlüm seni bana seçmiş

Bu can aşk şerbeti içmiş

Kefenim yolunda biçmiş

Mecnunum nergis bakışlım

Pür ateşim bir baksana

Tutuşmuş yanmışım sana

Bakışların bir ver bana

Mecnunum nergis bakışlım

Hem aşığım hemde hasret

Ömer biraz daha sabret

İnayet ola ha gayret

Mecnunum nergis bakışlım', 'Nergis bakışlım gül açmış Sineme kor sevda saçmış Bu sevda benide aşmış Mecnunum nergis bakışlım Gönlüm seni bana seçmiş Bu can aşk şerbeti ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ekinci Micingirt']::text[], 8.5, '{"poet":"Ömer Ekinci Micingirt","poet_slug":"omer-ekinci-micingirt","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nergis-bakislim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah! Sana Sevdiğim Diyebilsem', 'ah-sana-sevdigim-diyebilsem-huseyin-erdogan-wwwjk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her sabah uyanınca

ilk seni düşünürüm

gün doğumlarında

güneşle yan yana

seni getiririm

inan ki canım

sen daha parlaksın

daha aydınlık daha sıcaksın

güneşin yanında

bil ki ben sensiz olunca

yaz aylarında bile

tir tir titrer üşürüm

bir gün ansızın

çıkarsam karşına

sakın benden kaçma

ne olur iki sevgiliymiş gibi

hasretle atılıver kollarıma

yoksa donar kalırım orada

gecem bile gün olur

sen yanımda olsan

kışım bahar açar

gelip bana sarılsan

keşke yüreğine 

sıcacık sevgimi

bir dolabilsem

o güzel kalbine

bir girebilsem

hep sende kalabilsem

ah! sana sevdiğim diyebilsem 

harika bir sevgili olabilsem

bil ki ölünceye değin

yollarına bakacağım umutla

bir kez bile olsa da

sana sevdiğim diyeceğim

benden böyle hep kaçarsan da

seni mahşerde bekleyeceğim

                             08.04.2005', 'her sabah uyanınca ilk seni düşünürüm gün doğumlarında güneşle yan yana seni getiririm inan ki canım sen daha parlaksın daha aydınlık daha s...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ah-sana-sevdigim-diyebilsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Kaybettigim Yer...', 'seni-kaybettigim-yer-funda-sag-g6yge', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bulduğum yerde kaybettim seni..

Kargaşanın, 

         kalabalıklığımızın içinde.

Büyüdükçe çocuklaşmamızın,

         hiçbirşeyi yadırgamamamızın içinde.

Sırtına yükler yüklediğimiz bu dünya kırbaçlandıkça geri teper,

geri teper sancılarını.

Körebedir ayrılık,

sesine gelir,

sözüne gelir,

kaçtıkça hep,

                     ama hep üstüne gelir.

Bulunmuşluğun hıncımıdır,

yoksa korkusumu karanlığın,

için içini yer,

için için bitirir.

İmkansızlığın en inkarsızındayım,

en uzağındayım sukunetin.

Ya hayat çok çetin, 

                               ya ben çok narin.

Talan edilmiş, 

harabeleşmiş anılara emanet bıraktığımız sevinçler.

Cebimize koyup gidemedik ki…

Zaten neyi taşıdık o günden bu güne yanımızda? 

Ömür boyu mutluluğun bile değerini bilemedik. 

Ya hayat büyük bir yalan, 

                                          ya biz hep yalan dinledik..

En büyük yanlışı biz en doğruyken yaptık

Görüp inanmamamız,

duyup söylemememizdi.

Ne dili şait ettik ne aklı,

tek şaidimiz aynamızdı.

Sonuçtada son kullanma tarihi geçmiş bir karar verdik. 

Ya hayat çok hızlı, 

                              ya biz çok geciktik.

Körebedir ayrılık,

sesine gelir,

sözüne gelir,

kaçtıkça hep,

                     ama hep üstüne gelir.

Bulunmuşluğun hıncımıdır,

yoksa korkusumu karanlığın,

için içini yer,

için için bitirir.

Seni kaybettiğim yer, 

                                  bulduğum yerdir.

Bu bendeki ben değil,

                                  sensizliğimdir…', 'Bulduğum yerde kaybettim seni.. Kargaşanın,           kalabalıklığımızın içinde. Büyüdükçe çocuklaşmamızın,          hiçbirşeyi yadırgamamam...', ARRAY['Türk Edebiyatı','Şiir','Funda Sağ']::text[], 8.5, '{"poet":"Funda Sağ","poet_slug":"funda-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/seni-kaybettigim-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Desteği', 'sair-destegi-huseyin-sigirtmac-vtnzy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Başların üstünde şair yeriniz.

Yaşamın ışığı, gün her biriniz.

Bir işe yaramaz yoksa diriniz.

Şiir için olsun şair desteği.

Doğru şiir yazmak temel felsefe.

Hissi arzularla olmaz vesvese.

İlan ediyorum şair herkese.

Şiir için olsun şair desteği.

Yerden yere vurup etmem temaşa.

Şiir tarzı ile düşmem telaşa.

Şimşir tarak olsa bile kel başa.

Şiir için olsun şair desteği.

Bozmayın şiiri, gönül bahçesi.

Anlam bütünlüğü, dili, lehçesi.

Bazen hüzün, bazen yürek neşesi.

Şiir için olsun şair desteği.

Kalbur üstü kalsın yüce şairler.

Yüzyıllar unutmaz, değer bilirler.

Rüzgarla gelenler, sele giderler.

Şiir için olsun şair desteği.

Bazen türkü sözü, bazen şarkıdır.

Hece ve söz çalmak, beşer farkıdır.

Şair sarhoş olur, sanma rakıdır.

Şiir için olsun şair desteği.

Hakkın eseridir, yüce bu ilham.

Şair olgun gerek, olmaz asla ham.

Türk halkı adına bu engin sedam.

Şiir için olsun şair desteği.

Faydası yok asla kırıp dökmenin.

Rencide ederek dara çekmenin.

Lüzumu yok hatır, gönül yıkmanın.

Şiir için olsun şair desteği.

Şiir yaşam tarzı, şiir haykırış.

Yüreğin sesidir, belki dil yanlış.

Duygu ifadesi, değildir yarış.

Şiir için olsun şair desteği.

Seviye ararım can diyarında.

Bu gün var olanlar yaşar yarında.

Sığırtmaç yok olur varın yanında.

Şiir için olsun şair desteği.', 'Başların üstünde şair yeriniz. Yaşamın ışığı, gün her biriniz. Bir işe yaramaz yoksa diriniz. Şiir için olsun şair desteği. Doğru şiir yazma...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sair-destegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-suleyman-kaya-35c26', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çocukluğunun bittiği dönemi

Gençliğinin ilk yıllarını

Sende var olan değişimi

Babama olan aşkını anlatırmısın

Anne.. 

İlk bakışın kalp atışlarını

Buluştuğunuz yeri,zamanı

Karşılıklı söylediğiniz sözleri

Çevreye var olan korkuyu anlatırmısın

Anne.. 

Köyün engüzel sizdiniz

Yusuf''a tutulmştunuz

Dul da olsan mutluydunuz

Başkasına hiç bırakır mıydınız

Anne.. 

Köşe bucak töre kaçamakları

El ele tutunarak uzak ellere kaçşınızı

Aşkınızı  yaşatma hayallerinizi

Bir bir anllatırmısın

Anne..

Hadi söyle..

Söylenecek takat mı kalmadı

Bak tenine dokunuyorum

Dokuz ay,dokuz gün içinde kaldığım göbeği okşuyorum

Sakın ölme Anne.. 

Ölme Anne,

Ölme Anne,! 

            Süleyman Kaya', 'Çocukluğunun bittiği dönemi Gençliğinin ilk yıllarını Sende var olan değişimi Babama olan aşkını anlatırmısın Anne..  İlk bakışın kalp atışl...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Kaya']::text[], 8.5, '{"poet":"Süleyman Kaya","poet_slug":"suleyman-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/anne-132-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Rüzgar', 'ey-ruzgar-burak-killioglu-swckr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Başımda bir ağrı; onulmaz sızı

Yine hasta ettin beni ey deli rüzgar

İçimdeki fırtınaya eştir elbette hızı

Minik sandallar gibi kaldırıp at beni rüzgar.

Uçur eteklerini bu zembereksiz şehrin

Kafatasımdan çıkar bin belaya eş beynimi

Uzak diyarlara at kalbimdeki hanendeyi

Kendimden kaçmak için bir vesile ol rüzgar.

Nefs bir dipsiz kuyu; düştükçe düşer insan

İnsan bir kör çıkmaz; ne avcı ne de kurban

Öylesine sert es ki, gözlerim dolsun yaştan

Bedbaht olmuş gönlümü bir okşayıver rüzgar.

Diyebilirsin, normal; ''ben bir garip rüzgarım''

''Üşütebildiysem seni, bil ki; o benim kârım”

Zamansız gelip geçen binbir türlü efkârım

Zihnimi süpürmesen, geçer mi sandın rüzgar?', 'Başımda bir ağrı; onulmaz sızı Yine hasta ettin beni ey deli rüzgar İçimdeki fırtınaya eştir elbette hızı Minik sandallar gibi kaldırıp at b...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ey-ruzgar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Git başımdan be amerikalı! ! ....', 'git-basimdan-be-amerikali-osman-kilic-xbc0x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Git başımdan be amerikalı

Bana mı öğreteceksin coğrafyamı

Sen anandan doğmadan daha

Bin kez sancılanmıştım ben

Bilmem kaçıncı çocuğuma

Henüz keşfedilmemişken yenidünyan

Ben ne çılgın savaşlara

Ve ne mecnun sevdalara soyunmuştum

Anadan üryan.....

Git başımdan be amerikalı

Bana mı öğreteceksin insanlığı

Herkesin insan doğduğu ve yaşadığı

Tarih dediğin çağlara hükmettim ben

O vakitler kimse sebepsiz gitmezdi

Ve ardına bakmazdı giden....

Git başımdan be amerikalı

Bana mı öğretiyorsun kafa tutmayı

Başıboş kalmasın afgan dağları

Silah kan ve kin bürümesin

Çiroz bünyelerin taşıdığı

O genç dimağları

Ağlamasın Filistin''de çocuklar

İnlemesin Bağdat

Asılmasın coğrafyamda artık

Birtek hoşnutsuz surat....

Git başımdan be amerikalı

Yüzyılların yorgunluğu omuzlarımda

Zorlama..

Uyandırma uykudan aslanı

Git buralardan amerikalı

Git! ! ! ...', 'Git başımdan be amerikalı Bana mı öğreteceksin coğrafyamı Sen anandan doğmadan daha Bin kez sancılanmıştım ben Bilmem kaçıncı çocuğuma Henüz...', ARRAY['Türk Edebiyatı','Şiir','Osman Kılıç']::text[], 8.5, '{"poet":"Osman Kılıç","poet_slug":"osman-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/git-basimdan-be-amerikali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Aşkın Yükünü Çekemez Oldum', 'bu-askin-yukunu-cekemez-oldum-tayyip-sag-m7uwb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimden akan yaşlara yazık,

Bir sevda yüzünden yüreğim ezik,

Yıllardır felekle aramız bozuk,

Bu aşkın yükünü çekemez oldum.

Aşıkmıyım, kölemiyim ben  neyim,

Gönüldemi, dildemiyim nerdeyim,

Kime güveneyim, kimi seveyim,

Bu aşkın yükünü çekemez oldum.

Tayyip der sevdiğim, nazdan usandım,

Dilimdeki sözden, sazdan usandım,

Sensiz geçen bahar,  yazdan usandım,

Bu aşkın yükünü çekemez oldum.

     07.04.2005', 'Gözlerimden akan yaşlara yazık, Bir sevda yüzünden yüreğim ezik, Yıllardır felekle aramız bozuk, Bu aşkın yükünü çekemez oldum. Aşıkmıyım, k...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-askin-yukunu-cekemez-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslı Gül...', 'asli-gul-i-brahim-ethem-bingul-rk3qq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nisanı getirmiş aylar

Kuşların kanadında

Kanat çırpmakta sevdalar

Baharda müjdeler var...

Beklenen gelmiş 

Kuşların kanadında

Saçlarını gönül yurduma sermiş...

Aslı gül olan

Rayihasını serpmiş

Yayılmış etrafa hoş kokular

Gül bahçesinin tomurcukları

Âlemi yeşertmiş...

Evet, nevbahar gelmiş

Mart ağlarmış, şaşmış bu işe

Demiş:  Ne var bende

Sevdalar küskün, niye? ..

Ben de ay '' ım bahara gebe...

Ağlama derim ben de

Aşk

Hangi ayda aslını bulursa

O ay bahardır

O ay pür neşe...

www.iebingül.com', 'Nisanı getirmiş aylar Kuşların kanadında Kanat çırpmakta sevdalar Baharda müjdeler var... Beklenen gelmiş  Kuşların kanadında Saçlarını gönü...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/asli-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemile Cem ile', 'cemile-cem-ile-suleyman-kaya-ho7u0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Diline gem vurdular

Sevgini nara attılar

Sebile saldılar

Ah cemile Cem ile

Mah cemaline,kemaline

Aşkın destan olmuş il''ine iline

Gönül sende, şahın yaban elde

Ah Cemile Cem ile

Talihsiz bahtın mı  kara

Sendedir endam,tabibin düşmüş dara

Yaktılar seni, attılar nara

Ah Cemile Cem ile

Aşkı bilmeyenler,aşkınızı verdi ele

Hiyanet dolu,atılar bulanık ele

Aşkına inat,verdiler hergeleye,ele

Ah Cemile Cem ile

Sevmiştin Cemi,Cem de seni

Toprağa cemre düşercesine

Ruhlar canlanır diyercesine

Ahh..! Cemile Cem ile

     Süleyman Kaya', 'Diline gem vurdular Sevgini nara attılar Sebile saldılar Ah cemile Cem ile Mah cemaline,kemaline Aşkın destan olmuş il''ine iline Gönül sende...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Kaya']::text[], 8.5, '{"poet":"Süleyman Kaya","poet_slug":"suleyman-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cemile-cem-ile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doyarım', 'doyarim-i-smet-barlioglu-ln4y4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herkes kendisinde olmayanı ister,

Onun için ben seni istiyorum,

Konuşurken kekelemeni istiyorum,

İkide bir sürçen dilini,

Sakarlıklar yapan elini istiyorum.

Zira, noksansızlıklardan

Oldum olası

Tiksiniyorum.

Noksanlıkların olmasa; 

Beyini tamamlayayım ben senin,

Neyine derman olayım,

Nasıl sevdayı öğreteyim sana; o bilmediğin,

Sana nasıl yüreğimi göstereyim; 

O görmediğin,

Nasıl sevdireyim sana gönlümü; 

İrdediğin? 

Aldırma güzeller güzeli olmadığına,

Bir Dünya Güzeli Fatma,

Bir Güzeller Güzeli Züleyha olmadığına aldırma,

Karga bile,

Yavrusunu kuzgundan sayarak basarmış

Bağrına.

Ben seni bağrıma ceylanlar gibi basmışım,

Gözlerinin pırıltısını sevmişim,

Ağlatmak istemişsin, ağlamış,

Güldürmek istemişsin,

Gülmüşüm.

Sen bildiğin gibi sözcükler söyle bana

Yalan-yanlış,

Sözcükleri birbirine bağlayamayıp kekele,

Yerli-yersiz ağla, yerli-yersiz gül,

Ben her şeyi yerli yerine koyarım,

Bir tamamlanmamış tablo gibi dur karşımda,

Doyarım.

(TANRI ÖNCE BENİ YARATTI isimli Serbest Şiirler ''inden > 87-88/100)', 'Herkes kendisinde olmayanı ister, Onun için ben seni istiyorum, Konuşurken kekelemeni istiyorum, İkide bir sürçen dilini, Sakarlıklar yapan ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/doyarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılıklar', 'ayriliklar-i-smet-barlioglu-iucs1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayrılık bir fişek kader oldu bize,

Dağ dağa kavuşamazmış,

Biz de kavuşamadık.

Birbirimizle güzel günler yaşarız

Sanmıştık.

Yaşayamadık.

Bu dereler,

Bu ırmaklar,

Bu nehirler,

Bu denizler bizim gözyaşlarımız değil,

Bu dumanlar bizim sislerimiz değil,

Bizim gözyaşlarımız

Karayaş, karaduman, birer büyük karaduman,

Bir ayrılıktır işte,

Gelir harami gibi arkamızdan

Durmadan.

Düşüncelerimiz bölündü karanlık ayrılıklarla,

Yüreklerimiz bölündü bölük-pörçük,

Yaşantımız bölündü lime lime,

Gönlümüz bölündü parça parça,

Ele yakın gelir ömür tüketen uzaklıklar,

Bizim yakınlığımız

Uzakça.

Böyle mi uzak kalırmış seven sevdiğine,

Öpücükler göndersem neyle gelip değsin ellerine,

Rüzgarın selam taşıdığına inanır mısın bu çağda,

Turnaların gönül acılarını taşıdığına? 

İnsan bu ayrılıklar yüzünden

Lanetler ediyor

Yaşadığına.

(TANRI ÖNCE BENİ YARATTI isimli Serbest Şiirler ''inden > 89-90/100)', 'Ayrılık bir fişek kader oldu bize, Dağ dağa kavuşamazmış, Biz de kavuşamadık. Birbirimizle güzel günler yaşarız Sanmıştık. Yaşayamadık. Bu d...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ayriliklar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yağmuru', 'gul-yagmuru-i-smet-barlioglu-zg5ac', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çiçeklerden bir yatak üstüne uzandım hayalimde,

Üstüne papatyalardan bir yorgan örttüm,

Sedefi andıran yüzünü öptüm,

Okşadım saçlarını tıpkı seni okşar gibi,

Gözlerine baktım gözkapakların kapalı mı diye,

Yandı yüreğim, tutuştu sevdanla,

Ondan hiçbir şey kalmadı

Geriye.

Üstüne bir gül yağmuru yağmaktaydı

Damla damla,

Gonca gonca,

Katmer katmer,

Kırmızı kırmızı güller,

Bülbüller esiyordu kıbleden keşişlemeye,

Ötüş ötüş, gülüş gülüş bülbüller,

Huzurunda sus-pus kesilmişti

Uykunu bozmamak için

Karanfiller.

Masallardan çıkmış periler gibiydin,

Gergeflerde işlenmişti altın kanatların,

Gül yaprakları içindeydi ayakların,

Yıldızlar üşüşmüştü kiraz dallarına,

Minicik melekler ellerini ellerine almışlardı

Bakmak için

Falına.

Falında ben vardım,

Bana ulaşıp duruyordu döne-kıvrıla giden yolların,

Dağlar kalkıyordu bir bir aradan,

Kabarıyordu yüreğin karasevdamla,

Kapalı gözkapaklarına binlerce öpücükler kondurdum

Dudaklarımla.

(TANRI ÖNCE BENİ YARATTI isimli Serbest Şiirler ''inden > 91-92/100)', 'Çiçeklerden bir yatak üstüne uzandım hayalimde, Üstüne papatyalardan bir yorgan örttüm, Sedefi andıran yüzünü öptüm, Okşadım saçlarını tıpkı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gul-yagmuru-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaram Yarim,Yarim Yadigârım', 'yaram-yarim-yarim-yadig-rim-tulay-eker-gmskh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uçurum sessizliği ürpertisinde yalnızlığım....

Yalın ayak dudak kıvrımlarım,sol yanım

Üstü yapış yapış özlem dolu dallarımın

Öyle yorgun

Öyle yarımım ki 

Yaram yarim,yarim sana yadigârım.', 'Uçurum sessizliği ürpertisinde yalnızlığım.... Yalın ayak dudak kıvrımlarım,sol yanım Üstü yapış yapış özlem dolu dallarımın Öyle yorgun Öyl...', ARRAY['Türk Edebiyatı','Şiir','Tülay Eker']::text[], 8.5, '{"poet":"Tülay Eker","poet_slug":"tulay-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yaram-yarim-yarim-yadigarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul’da', 'i-stanbul-da-ender-altinisik-06n60', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kar yağıyor İstanbul ’a

hem de ne çok yağıyor bu gece…

yürümeyi en çok sevdiğim akşamlardır

bu akşamlar…

Yürüyorum

geceyi aydınlatan karların beyazlığında …

Sokak lambaları gölgeme vuruyor,

buz kesen rüzgar kalbime…

En sevdiğim havada yürüyorum

en sevdiğime yanıyorum…

Beyoğlu’ndayım bu gece

caddenin kalabalığı yürüyor üstüme,

ben sakınmıyorum

ne kalabalıktan, ne kartanelerinden

seni görme umudu içimde

gözümü bile kırpmıyorum bir an bile…

Cadde her bittiğinde bir sigara daha yakıyorum,

dönüp sensizliğimi adımlıyorum

yüreğimde yankılanan nağmelerde…

Sigarayı her götürdüğümde dudağıma

seni öpüyorum uluorta.

Oysa bilirsin; 

elini tutmaya bile çekinirim aslında…

İşte böyle sevgili

kar yağıyor istanbul’a; 

ben yürüyorum,

şarkımızı dinliyorum,

sigaramda seni öpüyorum…

Oysa sen uzaktasın…

Bir daha dönecek misin 

aşkları grileşen istanbul’a,

yanımda olacak mısın bir daha! 

Gittin; 

bu kenti bana bıraktın,

beni yalnızlığa…

Ben seni arıyorum

sevdamızın şehri istanbul’da…', 'Kar yağıyor İstanbul ’a hem de ne çok yağıyor bu gece… yürümeyi en çok sevdiğim akşamlardır bu akşamlar… Yürüyorum geceyi aydınlatan karları...', ARRAY['Türk Edebiyatı','Şiir','Ender Altınışık']::text[], 8.5, '{"poet":"Ender Altınışık","poet_slug":"ender-altinisik","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/istanbul-da-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal Kurmak Yasak mı?', 'hayal-kurmak-yasak-mi-kadir-soyturk-pc2gc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki elim ensemde, düşünüp duruyorum

Bilmem işe yarar mı? hayaller kuruyorum:

Hiç kimsenin haram yok, sofrada ki aşında

Mühendis fabrikada, doktor hasta başında....

Hiç kimse hiç kimseye zulmetmek nedir bilmez

Secde hariç vatandaş, kimselere eğilmez! 

Herkesin mesleği var, yapar kendi işini

Şikayetin var ise, dişçi çeker dişini! 

Mahkemelik işin var, korkma adliyeye koş

Orda vardır erbabı, seni döndürmezler boş

Fetva mı verilecek, onu alimlere sor

Biz değil, bu konuda ayet – hadis ne diyor? 

Ne memur, ne de amir, kendi haddini aşmaz

Gerçek insan olana, haddi aşmak yaraşmaz! 

Bizden hizmet bekliyor, bakın milyonlarla can

Sevenlerin omzunda, yükselecek bu vatan! 

Görevini yapıyor, herkes yerli yerinde; 

Bunlar gerçek olacak, elbet günün birinde!', 'İki elim ensemde, düşünüp duruyorum Bilmem işe yarar mı? hayaller kuruyorum: Hiç kimsenin haram yok, sofrada ki aşında Mühendis fabrikada, d...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hayal-kurmak-yasak-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu şehir', 'bu-sehir-nese-ersoy-xsi21', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Iğıllar geçiyor düşünlerimden

hoyrat kullanıyor harfler sesimi

ellerime, sis damlıyor ince ince

çağıltı bekliyor, susuyorum  

cesaretim bileytaşında

maviyi aşan tenimden geçsin

asiyim kumsalıma

küçük ve ıssız çakıl

sokaklarda yürüyorum sarı

her şey ceset

tekil kalıyor adımlarım

eriyor mevsim soluğumda

gecesi erken inen şehirdeyim

nefesi kül kokuyor kadınların

...

eğretiyim.', 'Iğıllar geçiyor düşünlerimden hoyrat kullanıyor harfler sesimi ellerime, sis damlıyor ince ince çağıltı bekliyor, susuyorum   cesaretim bile...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-sehir-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor kazağından arındı menekşe', 'mor-kazagindan-arindi-menekse-nese-ersoy-rhwd2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceye seni giydiriyorum

gökkuşağına beyazı

bakışım buharlaşıyor

düşlerimden taşan

deli dalga saçmaları

sen aşk, ben...

mor kazağından arındı menekşe

bataklık ellerimi de tutuyor

yitip yitip bulunuyorum

seviştiriyorum

okyanusla kendimi

kokunu dinliyor 

güneşi ıslatıyor gözümdeki

paslı mavi, kırmızı çığlık

vurulup vurulup uçuyorum

yağmurlar tavşankanı

sesini soruyorum kimse tanımıyor

kaldırımlar ayak izlerini

ölüyor gecenin sığlığında

yalnızlığımla beslenen zaman

ateşler yakıyorum ölümden sokaklara

yanıp yanıp artıyorum', 'Geceye seni giydiriyorum gökkuşağına beyazı bakışım buharlaşıyor düşlerimden taşan deli dalga saçmaları sen aşk, ben... mor kazağından arınd...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mor-kazagindan-arindi-menekse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler Ilgarda', 'dusler-ilgarda-nese-ersoy-24ev5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Noktalanır imgeler düş kıtlığında

incisi dökülür gecenin

umut (mu)  yaşamla aramda

bin ölümü yeğlerim

bir gönül esimi uzaklardan

gözlerimde aşk ışıltısı

beklenmedik

ve düşler ılgarda.', 'Noktalanır imgeler düş kıtlığında incisi dökülür gecenin umut (mu)  yaşamla aramda bin ölümü yeğlerim bir gönül esimi uzaklardan gözlerimde ...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dusler-ilgarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair ve ben', 'sair-ve-ben-nese-ersoy-a2bk4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben diyor şair şiirinde

ya ben! 

alçaldı tavan

daraldı odalar masalar

ben’i bulamıyorum

düğmeler işlevsiz

saatler kör 

kuyu diplerinde

belleğim yetisiz

aşkı kaçımsayışım bilerek ya da

gece eskidikçe

gökyüzü bulut gözlü

bir yalnız yürek ahmak ıslatanlarda

sırılsıklam.. yitik..

          su kümeciklerinde

ne güneşi sunabildim şaire

  ne beni', 'Ben diyor şair şiirinde ya ben!  alçaldı tavan daraldı odalar masalar ben’i bulamıyorum düğmeler işlevsiz saatler kör  kuyu diplerinde belle...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sair-ve-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimliksiz', 'kimliksiz-nese-ersoy-kjbng', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen daralan gecede 

bir serzeniştin, denizine düştüm

hep soru benliğim 

güneş inadına uzak penceremden

ayışığına saklıyorum gözlüklerini

aşk yaşanırken bağnaz ayrılıkta sevecen

kimliksiz bir terördün 

hapsediyorum sorgusuz

gözlerine geç kalıyor ayışığı

ellerin, sesin vardı

gecesi ürkek şehrin kalabasında

gözlerin vardı, adımların

sen yoktun

aşktın yaşlanmak istemeyen

çilekli rüzgarı soluyandın

kirdin ellerime duaydın yayılan

kokuydun ayrık otuna her şeydin

ekspresler geçiyor uzak yollardan

kokular taşıyor denizden dağa

firardasın iz bırakıp dilime 

geldiğinde kimliksiz kaçarken yine

es kuzeye, güneye, kendine

yetiş, gündüz açmadan çiçeklerime', 'Sen daralan gecede  bir serzeniştin, denizine düştüm hep soru benliğim  güneş inadına uzak penceremden ayışığına saklıyorum gözlüklerini aşk...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kimliksiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasaklı ve laçin', 'yasakli-ve-lacin-nese-ersoy-bkdbq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çoruh’a vermişim sırtımı

palavra tozuntusu şöyle bir uğramak

gecesi masif ürkü

bu benim dağım, yasaklı ve laçin

gözlerimin ertesi deniz

ladinler yalın ve ölü

ellerim ıskarça sabır

bir çağrıma kabarıyor

çürüyor sabır ireşmelerim

ve kopuyor gözlerimden çoruh

imbatlara salınıyor

esiyorum sesine mecbur kılarak istencimi

çamlardan geçiyorum, menekşelerden

sularla sevişiyorum senden öncesi

bir taşcılın coşkusunu paylaşıyor 

                                     ellerimde üveyik

sokak lambası ölüyor gökyüzü meneviş

yüzünde yanıyorum dilim pas

kör iliklere çabalanıyor aşk

eskiyor ölümler ve zaman

ağlıyor gecenin hoşça kal sesine

yasaklı ve laçinde

kokunu saklıyor, öpüyorum.', 'Çoruh’a vermişim sırtımı palavra tozuntusu şöyle bir uğramak gecesi masif ürkü bu benim dağım, yasaklı ve laçin gözlerimin ertesi deniz ladi...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yasakli-ve-lacin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı düş II', 'adi-dus-ii-nese-ersoy-m9bq7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gemiler boşaltır limanlar

aşka amade imler pür telaş

kapılar zorlanır, kapılar

kırılır orta yerinden ben/deniz

zaman eskidi, aşk da

bir bak ne kaldı

bugüne elimde hiç

yorgunum yoldan da

ağlaşır ayrılan kaldırımlar

küskün bakışlara ayna her biri

dilimin duymadığı bu/sesin

gözümün tatmadığı

bağışla

seni düşümden çıkardım', 'Gemiler boşaltır limanlar aşka amade imler pür telaş kapılar zorlanır, kapılar kırılır orta yerinden ben/deniz zaman eskidi, aşk da bir bak ...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/adi-dus-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevi', 'sevi-nese-ersoy-n4tln', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yağmurkuşu göç etti, serçeler de

güneşim kül

yağmuru sorguladım sen yağdın

ben sırılsıklam.

yalınkat seviler kutsanır (mı) 

yaşanır dolu dizgin 

      de.. yorulur aşk

devinir mevsimler istemesen de

bir karcılın diklenişi tutkum

yolculuk başlar beyazdan

ben ağır ağır...

bakışın düşer

gözünde örtünür yalıncak tenim', 'Yağmurkuşu göç etti, serçeler de güneşim kül yağmuru sorguladım sen yağdın ben sırılsıklam. yalınkat seviler kutsanır (mı)  yaşanır dolu diz...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevi-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni seviyorum', 'seni-seviyorum-nese-ersoy-ewd0p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çiğnediğim başak, yunduğum bulut

                          giyindiğim yürek

ama aç, ama yalın.

...

gülüşünü sakladığım menekşeler susuyor

çizdiğim gölgeler, bakışını

sözcükler sahte, harfler yalancı

yıldızlar herkesin, ben kimsenin

karanlık öylece yerli yerinde.

...

bir orta oyunu bu

beceriksiz şehrin sergilediği

kaç yol ağzından döndüm

kaç dereden su getirdim

tez geçer bu eylül

varmadan beyaza

...

şehrin korkak gölgeleri çekilirken bir bir

özlemi dinliyor akreple yelkovan

donmuş bir gülün buruşuk solgunluğu

                          yansıyor dudaklarıma

ellerim çekingen, ellerim fısıldıyor

...

gelecek 

umarsız hazları atıp avuçlarından

meddahlar terkedince oyunu

karanlık kopacak yerinden

gözlerine bırakıp gözlerimi

...aşk ve ben', 'Çiğnediğim başak, yunduğum bulut                           giyindiğim yürek ama aç, ama yalın. ... gülüşünü sakladığım menekşeler susuyor çi...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/seni-seviyorum-244-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoksun -yoksun', 'coksun-yoksun-nese-ersoy-q4ggz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'seni imgeler belleğim

zamansızlık şiirinde

aşağılaşır gökyüzü 

yıldızlar düşer avuçlarıma

her biri sen, çoksun

ellerim ışıldar, aşk şimdi

yükselir gece gözüm kapalı

bir şafak ayazı tenimde

...

her şey sen

yorgun dizeler yinelenir

şimdiler ötesiz', 'seni imgeler belleğim zamansızlık şiirinde aşağılaşır gökyüzü  yıldızlar düşer avuçlarıma her biri sen, çoksun ellerim ışıldar, aşk şimdi yü...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/coksun-yoksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamaksa... yarınlar', 'yasamaksa-yarinlar-nese-ersoy-98ese', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir çaresizlik, her zerresinde tenimin

Suyunu deviren nehir

gecesini kaybeden sokak lambası

bahçesini şaşıran ağaç

bir ses, bir soluk... ellerim yetmiyor

			

tütün tadında herşey

giderken pencereler

üzgün ve ezik

özgürlüğüm satılıyor, boşvermişliğim

ne karanlık saklayabiliyor beni,

		                 ne kalabalık

çarşısı riya satıyor kapış kapış

seyiri kan kapalı gişe

neyi özlediğini bilmiyor,

ortak oluyor günahlarına imlerin

yarınlar gömülüyor 

göçü biliyor da kuşlar...bir ben

...

aynamla barışık

ağaçlar şaşırmaz bahçelerini

buluşturur sokak lambası sevgileri

kartopu oynasın çocuklar

ay parlasın, güneş yaksın

“bir mendil al abla n’olur”

kuş kadar da değilim

yaşamaksa, yarınlar...', 'Bir çaresizlik, her zerresinde tenimin Suyunu deviren nehir gecesini kaybeden sokak lambası bahçesini şaşıran ağaç bir ses, bir soluk... ell...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yasamaksa-yarinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydar', 'haydar-mehmet-dag-8ctau', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çökmesin kara cellat gibi üstüne bir kez

Yalnızlık kötüdür  korkunçtur HAYDAR

Açtı mı Baykuş gibi gözünü sende

Bir daha  O seni terk etmez HAYDAR

Gündüzler uzundur incedir ama

Geceler,geceler çekilmez HAYDAR

Ne doğal afetler olur içinde

Yanarsın,yanarsın sönersin HAYDAR

Bilirim fakirlik acıdır, kötüdür ama

Dışarıda dolaşmak güzeldir HAYDAR

Dört duvar pis koğuş zulümdür fakat

Hücrede yalnızlık ölümdür HAYDAR

Toprak olsan kayar,kayar gidersin

Demir olsan çürüyüp paslanırsın

Taş olsan da lime,lime erirsin 

Ama bu bende ki yürektir HAYDAR

 Ama bu bendeki bir candır HAYDAR

(Avcılar)', 'Çökmesin kara cellat gibi üstüne bir kez Yalnızlık kötüdür  korkunçtur HAYDAR Açtı mı Baykuş gibi gözünü sende Bir daha  O seni terk etmez H...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dağ']::text[], 8.5, '{"poet":"Mehmet Dağ","poet_slug":"mehmet-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/haydar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sevgi Hikayesi', 'bir-sevgi-hikayesi-zumrut-demirtas-35410', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıl 1989,

bir üniversitenin kantininde

başlamıştı bizim hikayemiz,

tanıştırılırken; ellerimizi

sıktığımız o cumartesi sabahı,

üzerinde kırmızı bir hırka vardı,

muhtemelen pantolonun kumaştı.

''haydi dedi arkadaşlar, çıkıyoruz

şehrin güzellikleri bizleri bekliyor''

hoş tesadüf, yanyana oturduk,

başımızı çevirip, dışarı bakıp durduk....

kolumda babadan kalma erkek saati,

üstelik bir saat ileriyi gösteren,

geçen yarım saat sonunda sen,

ilk cümleni kurmuştun: ''saatiniz yanlış''....

bütün gün aynı cümleyle yetindin,

fazladan bir kelime bile sarfetmedin,

akşama kadar grupça beraberdik,

yollarımızın ayrılmayacağını bilmedik....

ve öyle oldu, 

o gün bugündür, çok şükür birlikteyiz,

ben artık erkek saati takmıyorum ama,

sen fazladan bayağı kelime sarfediyorsun....

olsun, ben sana hala,

o cumartesi sabahı kadar

taze duygular besliyorum,

seni çok ama çok seviyorum....', 'Yıl 1989, bir üniversitenin kantininde başlamıştı bizim hikayemiz, tanıştırılırken; ellerimizi sıktığımız o cumartesi sabahı, üzerinde kırmı...', ARRAY['Türk Edebiyatı','Şiir','Zümrüt Demirtaş']::text[], 8.5, '{"poet":"Zümrüt Demirtaş","poet_slug":"zumrut-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-sevgi-hikayesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''a...', 'i-stanbul-a-emirhan-bala-o8u1y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Merhaba İstanbul’a; 

Onu görmek yalnızca, yaşamak değil,

Nazar değmemiş kıvrımlarına,

Kavgalar sürse de asırlarca,

Kanlar aksa da halicine boğazına,

Müslüman’ı, Musevi’si, Ermeni’si ve Rum’u

Dervişlik işlemiş bunca zaman ruhuna…

Rasgele galata’ daki balıkçısına,

Tünelde keman çalan ihtiyarına,

Üsküdar vapurundaki işportacıya,

da…da…da…

Merhaba yaşayamadığım ruhuma

Merhaba destansı İstanbul’a…', 'Merhaba İstanbul’a;  Onu görmek yalnızca, yaşamak değil, Nazar değmemiş kıvrımlarına, Kavgalar sürse de asırlarca, Kanlar aksa da halicine b...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/istanbul-a-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sevdam Ölünce Biter', 'benim-sevdam-olunce-biter-osman-i-nci-1fdu1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seversem birini, ölene dek severim,

Onun uğruna, çelik kayalar delerim,

Yıldızları toplayıp, ayağına sererim,

Benim sevdam ancak, ölünce biter...

Sevgi denilince, yalan dolan olmaz,

Sevgiyle açan çiçekler, asla solmaz,

Beklendiği anlarda, zaman dolmaz,

Benim sevdam ancak, ölünce biter...

O saçlarına dokunmak, rüya gibidir,

Tüm gerçekler onda, gerisi hayâldir,

Bunu bana yaşatan, gerçek sevgidir,

Benim sevdam ancak, ölünce biter...

Mehtaplı gecelerimin, tek ışığıdır o,

Büyük mutlulukların, kaynağıdır o,

İçimdeki çağlayanların, ırmağıdır o, 

Benim sevdam ancak, ölünce biter...', 'Seversem birini, ölene dek severim, Onun uğruna, çelik kayalar delerim, Yıldızları toplayıp, ayağına sererim, Benim sevdam ancak, ölünce bit...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-sevdam-olunce-biter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gundim', 'gundim-ayten-ozlem-yesilcali-02uah', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neyime güvendigimi bilemiyorum.

Kalbimin temizliginemi....

En zor anlarda kalbim aşkı bildi.

Bozdum sevmemeyi sevilmemeyi.

Gönlüme hükmedemedim....

Doyamadım bakmaya....

Kalbime söz geçiremedim

Özledim her zaman tenini kokunu

Bakmaya doyamadım

Okşamaktan sakındım

Eller seni sevmesin diye

Sana zarar vermemek için canımın içi

Yıllar sonra sevmenin bedeli bu olsa gerek.

Gundim.......

Neyime güvendim bilmem.

Yaşamasaydım bu günü senle

Aşk beni bagışlamazdı

Aşık oldum senin gülen gözlerine

Gundimmmmm

Son,  nefesim de aşkın zorunu gördüm.

Aşığım her yerine...

Kalbim neye güveniyor bilemiyorum

Benden çok büyük bu sevdam

Aşamam.

Yarını bilemiyorum.

Unuttum geçmişimi senle Gundi.

Nazar değmesin

Aşığım tüm bedenine

Bakmaya doyamadım..

Sevmeye kıyamadım incinirsin diye..

Yokluğuna alışamadım çok kısa süre olsa da bile.

Seni hep yanımda sesini sesimde soluğunu nefesimde; 

Hissettim.

Ben Gundi yim...

Senide Gundi olduğun için çok sevdim,taptım

Kıyamadım seni sevmeye doyamadım sana bakmaya

Gundimmmmmmmmmmmm', 'Neyime güvendigimi bilemiyorum. Kalbimin temizliginemi.... En zor anlarda kalbim aşkı bildi. Bozdum sevmemeyi sevilmemeyi. Gönlüme hükmedeme...', ARRAY['Türk Edebiyatı','Şiir','Ayten Özlem Yeşilçalı']::text[], 8.5, '{"poet":"Ayten Özlem Yeşilçalı","poet_slug":"ayten-ozlem-yesilcali","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gundim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-yunus-kara-okco0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gizlenmiş,karışmış çem-i giryeme,

Gözümden gönlüme akar yalnızlık.

Endülüs’e vurgun Tarık misâli,

Bütün gemileri yakar yalnızlık.

Ferhat’ım, saçımda sevdanın tozu,

Külüngümde gizli vuslatın yazı.

Elimde Kerem’in o dertli sazı,

Dilimden sazıma akar yalnızlık.

Yalnızlık; sevdanın sancağı surda,

Yalnızlık; kuzunun selamı kurda.

Öfkesi kurşundan şaki olur da,

Her yerde yoluma çıkar yalnızlık.

Âdem’im girmişim haram bağına,

Yalnızım, hasretim dost kucağına.

Bir bilinmez güçle takmış ağına,

Her gece ruhumu çeker yalnızlık.

Yalnızlık, gecenin yanan gözleri,

Ruhuma dikilen ateşten deri.

Zamanın sırtında gezer her yeri,

Postunu gönlüme serer yalnızlık.

Hayalim buz tutar,gerçeğim narda,

Gülümü kaybettim umudum harda.

Zümrüdüanka’dan feyiz alır da,

Sonunda kendini yakar yalnızlık.

*Simav Anadolu Dergisi Şiir Yarışması İkincilik Ödülü (Mayıs 2001) 

Kahraman Maraş İl MEM ve Yeni Ufuk Dergisi Şiir Yarışması İkincilik Ödülü (2005)', 'Gizlenmiş,karışmış çem-i giryeme, Gözümden gönlüme akar yalnızlık. Endülüs’e vurgun Tarık misâli, Bütün gemileri yakar yalnızlık. Ferhat’ım,...', ARRAY['Türk Edebiyatı','Şiir','Yunus Kara']::text[], 8.5, '{"poet":"Yunus Kara","poet_slug":"yunus-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yalnizlik-238-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlle de mezar', 'i-lle-de-mezar-nese-ersoy-zrena', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nicedir geçer ömrümden eylül

salına salına, anlayamam

her gün düne karışır, hesap

  “kayda değer bir şey yok”

unuttum, neydi yüreğimi titreten

her denizin sahili başka konuşur

ateşi külleyen zaman.

aşk mı demiştin? .. geç bir kalem

şair mi? .. kendini beğenmiş

elbet şaşırır belleğim

	giydiğim şapkalar 

demedim hiç “dilim seni dilim dilim”

	sığınıp, üç duvar bir deliğe

çektiği bülbülün

duvardaki çivi kadar zavallı yine

albüm kadar soluk, dün kadar gecikmiş

cehennem turşusu, her öğün! 

üşütürken şehri cam gözlü kaldırımlar

neden korkar ki ölü? ..”ille de mezar”

...

nereye gidiyorsan eylül', 'Nicedir geçer ömrümden eylül salına salına, anlayamam her gün düne karışır, hesap   “kayda değer bir şey yok” unuttum, neydi yüreğimi titret...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ille-de-mezar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir III', 'siir-iii-nese-ersoy-zrxdx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Su ve toprak hayat verir

acı vermez aslında

neden ayaklarım acıyor anne? 

duvarım yok

sokak lambalarım

posta kutumuz kayıp

çatımız nereye gitti? 

...

şehrimi elimden alıyorlar anne.', 'Su ve toprak hayat verir acı vermez aslında neden ayaklarım acıyor anne?  duvarım yok sokak lambalarım posta kutumuz kayıp çatımız nereye gi...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/siir-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perde Kapanmaz', 'perde-kapanmaz-zafer-mutlu-6i810', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen ki yeditepeli,baş aktris kaidesi

sen ki göz pınarları kurumuş utangaç..

şimdi senin için,

çok kırılgan diyorlar..

kapanan son perde değil,seni üzen

oysa yüzyıllardır,sırılsıklam aşık figüranların

melodram bakışları değilmiydi,

seni dillendiren..

mabet ağaçları gibi üzerinde

kök salanlar,

korku damarlarını tıkamış

post kavgasındalar şimdi...

senin için kırılgan diyorlar

kapanan son perde değil bu...

figüranlar değişir günden güne..

sen kalırsın,baş karakter yeryüzünde....', 'sen ki yeditepeli,baş aktris kaidesi sen ki göz pınarları kurumuş utangaç.. şimdi senin için, çok kırılgan diyorlar.. kapanan son perde deği...', ARRAY['Türk Edebiyatı','Şiir','Zafer Mutlu']::text[], 8.5, '{"poet":"Zafer Mutlu","poet_slug":"zafer-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/perde-kapanmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını koyamadım', 'adini-koyamadim-nese-ersoy-6rtz6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Minik ıhlamur ağacında parmak izlerin

yağmurlar yıkasa da silinmez

yaprağında büyür ellerin

büyür

dibine düşer yine ellerin

ertelenmiş zevklerin izdüşümü 

	        gözümdeki halkalar

duyduğum her koku

yaşanmayan anlara acıktırır

yüreğimi, tenimi

ıhlamurun dibinde varsın 

yabani reyhanların kokusunda, 

                                          çerçevelerde

sen... kollarımda yoksun

gözümü kapatırım yer yerinden oynar

yanardağlar kusar yüreğime

eririm.', 'Minik ıhlamur ağacında parmak izlerin yağmurlar yıkasa da silinmez yaprağında büyür ellerin büyür dibine düşer yine ellerin ertelenmiş zevkl...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/adini-koyamadim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakmadı Aşk Beni', 'birakmadi-ask-beni-yunus-kara-mwbtw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her gönülden bin sevdayı gül ile,

Derdim yine bırakmadı aşk beni.

Hamsın diye koymadılar dergâha,

Erdim yine bırakmadı aşk beni.

Bir peri kızıyla tutup el ele,

Çıkıverdim âzâd adlı sefere.

Masallardan örtü yapıp her yere

Serdim yine bırakmadı aşk beni.

İlhamı ben verdim neyzene neye,

Kurtuluş Mevlana,Şems’dedir diye,

Bin bir günden sonra başka Çile’ye,

Girdim yine bırakmadı aşk beni.

Siliverdim sevda yazan yerimi,

Kimi sır der,kara büyü der kimi,

Nesîmîyim her çıplağa derimi,

Verdim yine bırakmadı aşk beni.

* Ana Dergisi Şiir Yarışması Birincilik Ödülü (2001)

   Nüzhet Erman Şiir YarışmasıMansiyon (2000)', 'Her gönülden bin sevdayı gül ile, Derdim yine bırakmadı aşk beni. Hamsın diye koymadılar dergâha, Erdim yine bırakmadı aşk beni. Bir peri kı...', ARRAY['Türk Edebiyatı','Şiir','Yunus Kara']::text[], 8.5, '{"poet":"Yunus Kara","poet_slug":"yunus-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/birakmadi-ask-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahçede aşk', 'bahcede-ask-nese-ersoy-5hbjd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Böyle güneşli günleri sever

bahçemdeki ağaçlar

yaprakları bir başka parıldar.

rüzgar, 

oynaştırır dalları hafifçe

sarmaş dolaş olur yerlerde

gölgeler

soluksuz sevişir böyle günlerde', 'Böyle güneşli günleri sever bahçemdeki ağaçlar yaprakları bir başka parıldar. rüzgar,  oynaştırır dalları hafifçe sarmaş dolaş olur yerlerde...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bahcede-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşama dair', 'yasama-dair-nese-ersoy-jvlht', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Irgatım tarlalarında

yarın sepiler dün biçerim

sangılı

kutuplaşırım kendimle

aldanışın serinliğinde tutuşur tenim

külbeyazı saatler yavaşça yüzümden

sevişir buz ve güneş

bit pazarlarında çalıntı akşamlar

büyük vurgunlarda küçük beyinler

el pençe asılır güne

yorgun kalçalarda uyanan dinçlik

yolunu şaşırmış da tuz çalısı

salkımı ellerimde pembe

aşk da yaşlanır

tende ölümün avansı üzgü

im sepiler...', 'Irgatım tarlalarında yarın sepiler dün biçerim sangılı kutuplaşırım kendimle aldanışın serinliğinde tutuşur tenim külbeyazı saatler yavaşça ...', ARRAY['Türk Edebiyatı','Şiir','Neşe Ersoy']::text[], 8.5, '{"poet":"Neşe Ersoy","poet_slug":"nese-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasama-dair-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben...', 'ben-emirhan-bala-g3ohi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kocaman bir çocuk,

bir adam kadar kocaman.

kocaman bir adam, 

bir sevmek olgunluğu kadar kocaman.

kocaman bir yürek,

bir çocuk yüreğindeki sevmek duygusu kadar kocaman...', 'kocaman bir çocuk, bir adam kadar kocaman. kocaman bir adam,  bir sevmek olgunluğu kadar kocaman. kocaman bir yürek, bir çocuk yüreğindeki s...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ben-159-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznün', 'huznun-yunus-darbogaz-5syes', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hüznün

perdesi çekik pencereden

geceye vuran

                        mavilik

Ezan

Tam akşam namazını duyurduğunda

Çınlattı şehri

Bir siren sesi

Oy anan öle

Hüznün

Çıkmaz bir sokağın lambasında titriyor', 'Hüznün perdesi çekik pencereden geceye vuran                         mavilik Ezan Tam akşam namazını duyurduğunda Çınlattı şehri Bir siren s...', ARRAY['Türk Edebiyatı','Şiir','Yunus Darboğaz']::text[], 8.5, '{"poet":"Yunus Darboğaz","poet_slug":"yunus-darbogaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/huznun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiginde', 'gittiginde-sair-sursemtes-aeqak', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'icimde gokyüzü parcalandi gittiginde

herkes kendi yanlizligina cekildi

artik beklemem bü sehri

 ardina düsergibi sevileri

beklemem bekler gibi geceleri 

artik beklemem hicbiryeri 

ve toplamam ardina düsen dizeleri 

gulleri

öluleri', 'icimde gokyüzü parcalandi gittiginde herkes kendi yanlizligina cekildi artik beklemem bü sehri  ardina düsergibi sevileri beklemem bekler gi...', ARRAY['Türk Edebiyatı','Şiir','Şair Sürsemtes']::text[], 8.5, '{"poet":"Şair Sürsemtes","poet_slug":"sair-sursemtes","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gittiginde-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynaya Baktım', 'aynaya-baktim-guner-kaymak-m5nmk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aynaya baktım bakmaz olaydım

Dökülmüş saçlarım bem beyaz benim

Yaşamadım ama çabuk yaşlandım

Bükülmüş belim dogrulmaz benim

Gönlüm beni çok ucuza harcamış

Arı gibi çiçek çiçek dolaşmış

Boşa vızıldamış bal alamamış

Beyhude  geçmiş yıllarım benim

Halden bilmeyene halim söyledim

Olur olmaz ile gönül eğledim

Ben gönlüme göre yar sevemedim

Talihim yüzüme gülmedi benim

Dost bilip sevdigin ihanet etti

Yüzüme gülenler terk edip gitti

Madde tükenince manada bitti

Kimseye kalmadı güvenim benim

Bayramları gurbet elde kutladım

Alem eglenirken ben hep agladım

Bin bir çesit sıkıntıya dayandım

Dayanacak gücüm kalmadı benim

Aşksız yaşayamam elimde değil

Nice vefasıza vermişim meyil

Ozan Güner der Gel hakka eğil

İnsana inancım kalmadı benim

Güner Kaymak / Amsterdam

07.04.2005', 'Aynaya baktım bakmaz olaydım Dökülmüş saçlarım bem beyaz benim Yaşamadım ama çabuk yaşlandım Bükülmüş belim dogrulmaz benim Gönlüm beni çok ...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/aynaya-baktim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir''den Bir''e', 'bir-den-bir-e-can-bilge-lyode', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sıfır idim

Bir ettin

Yoluma ışık serdin

Yokluğunda bir hiçtim

Varlığınla şenlendim

Sıfır idim

Bir oldum

Bir iken iki olamam

Bir bir daha iki etmez

İki etmesi gerekmez

Gel birlikte olalım

Bir''likte buluşalım

Ruhlarımız kenetlensin

Bir''likte yoğrulalım

Sıfır idim

Bir oldum

Bir''den Bir''edir yolum

Hüzünlerim Bir''den Bir''e

Bir''den Bir''edir sevincim

Herşey Bir''den Bir''edir

Bir''den Bir''e tüm sevgim

Sıfır idim

Bir oldum

Sevgidir tüm umudum

Toplayalım tüm Bir''leri

Kenetlensin tüm eller

Sonsuz ışığa koşalım

Birleşsin tüm sevgiler

Hepimiz Bir olalım', 'Sıfır idim Bir ettin Yoluma ışık serdin Yokluğunda bir hiçtim Varlığınla şenlendim Sıfır idim Bir oldum Bir iken iki olamam Bir bir daha iki...', ARRAY['Türk Edebiyatı','Şiir','Can Bilge']::text[], 8.5, '{"poet":"Can Bilge","poet_slug":"can-bilge","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bir-den-bir-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir''den Bir''e - Eylül Sarkısı', 'bir-den-bir-e-eylul-sarkisi-can-bilge-uphho', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yerlere dökülmüş sevgi kırıntılarını toplamak derdindeydim,

Ekmek kırıntıları gibi, bilirsin öyle yetişmişiz,

Öyle öğrendik, günahtır, üzerine basılmaz nimetin

En büyük nimet değilmidir karşılıksız verilen sevgilerin

Konak Meydanında buğday tanelerini savururlar ya

güvercinler ürkek, titrek, hep gözleri insanlarda bir taraftan

taneleri toplamak telaşında,

İşte benimkisi de o hesap be güzelim

Bir kaç sevgi kırıntısını kurtarırım belki ezilmekten

Sevgileri toplar tamamlarım belki, yüreğimdeki parçaları, hep eksik kaldığını hissettiğim

Dostlukların peşindeyim, bir kır kahvesinin tahta sandalyelerinde

oturup yudumladığımız o tavşan kanı çayın sıcaklığı gibi içimizi ısıtan 

dostluklardı benim aradığım,

nerden bilebilirdim be güzelim

nerden bilirdim aslında sevgi ve dostluk arayan yüreğimin,

bir balıkçının ağlarına takılan tek bir balık gibi çırpınan

ve özlemlerinle sarmalanan bir ağın içine düştüğünü.

Hiç böyle bir tat almadım hayattan,

yaşadığım tüm dostlukları, tüm sevgileri

serdim önüme tek tek yeniden yaşar gibi sanki

ve bunca yıl yaşadığım özlemleri,

Olsa olsa gün batımı aşkıdır bu,

batan güneşi birlikte seyredip sonra birlikte yummak gözleri

Ve sonsuz maviliğin kucağında birlikte yelken açmak ufuklara

Dümene ihtiyaç yok artık, yolculuğun sonu nasıl olsa

Her yeni son, yeni bir başlangıçtır bu sonsuzlukta

Kapını ne zaman, kimin çalacağı belli olmaz hiç

habersizce çalıverir kapını

bir açarsın, bir açarsın, bir açarsın

Bir açarsın ışıl ışıl yıldızları andırır gözleri

Ve dudaklarından dökülen, sonsuzluğa sürükleyen bir aşk melodisi

Güzel olanda bu değilmidir be güzelim? 

Dalgalara aldırmadan ve rüzgarı alıp arkana

Bir başıma yelken açmışken yeni yalnızlıklara

Hiç beklenmedik bir anda çıkıp ortaya

Bir elin sarılması, bir başın göğsüme yaslanması

Ve raksetmek hoyratça, mavi sulardan bir halının ortasında

Güneşin ferinin söndüğü zamanlardayız artık 

Kızıllığının yapraklara karıştığı,

O güvercinlerin unuttuğu bir buğday tanesinden yeşeren

Aşkın zamana karşı çıktığı

Nedir beni darmadağın eden, nedir bu duygu içimdeki

Olsa olsa gün batımı aşkıdır bu,

batan güneşi birlikte seyredip sonra birlikte yummak gözleri', 'Yerlere dökülmüş sevgi kırıntılarını toplamak derdindeydim, Ekmek kırıntıları gibi, bilirsin öyle yetişmişiz, Öyle öğrendik, günahtır, üzeri...', ARRAY['Türk Edebiyatı','Şiir','Can Bilge']::text[], 8.5, '{"poet":"Can Bilge","poet_slug":"can-bilge","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bir-den-bir-e-eylul-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birlik Olalım', 'birlik-olalim-i-smail-dogan-9gp00', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgiye hizmettir hisleri yazmak,

Sevdamız  şiirse,  birlik  olalım.

Aşkıma hikmettir şiiri yazmak, 

Hülyamız  şiirse,  birlik olalım.

İnsanın içinde saklanmış gizi,

Yazar mısraları  da  dizi dizi,

İnsan sevgiside aşk eder bizi,

Sevgimiz şiirse, birlik olalım.

İnsan beraberce gülüp çalışır,

İnsanoğluna da  birlik  yakışır,

Şiirli yürekler  kalpler  yarışır,

Meyvemız şiirse, birlik olalım.

Hepimiz elmadan dalda gülüyüz,

Çekirdek kabuğu şeker balıyız,

Şiirin  kalemi  gülün  dalıyız,

Elmamız şiirse, birlik olalım.

Temiz hava gelsin aç pancereyi, 

Okşasın  ciğeri  beyni cehreyi, 

Yumuşatır  ruhu bulur çareyi, 

Çabamız şiirse, birlik olalım.

Hayalimiz olsun çağdaş Türkiye,

Atatürk  yolunda  gidek ileriye,

Ülkemi  incitme kurtla tilkiye,

Davamız şiirse, birlik olalım.

Yüreğinden bakan gözümde nurdur,

Sözünde durmayan paradan kurdur,

Kalbim kirli söze kaleden surdur,

Duamız  şiirse,  birlik  olalım.

Mecnun leyla için çöllerde yanar.

Ferhatın dağlardan elleri kanar,

Kin kusan yüreği DOĞANİ kınar,

Hudamız  şiirse,  birlik  olalım.

Şiir Perisi Grub''unun ''Bir Dörtlük de Sen Yaz'' aktivitesininden esinlenilerek yazılmıştır.', 'Sevgiye hizmettir hisleri yazmak, Sevdamız  şiirse,  birlik  olalım. Aşkıma hikmettir şiiri yazmak,  Hülyamız  şiirse,  birlik olalım. İnsan...', ARRAY['Türk Edebiyatı','Şiir','İsmail Doğan']::text[], 8.5, '{"poet":"İsmail Doğan","poet_slug":"i-smail-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/birlik-olalim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuksun Çocuğum', 'cocuksun-cocugum-mehmet-selim-tolay-r1alk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir mızıka,bir fülüt,bir kaval

biri gözlerin,biri gülüşlerin,biri dertlerim benim.

Ayrımı düştük saatlerce umrunda mı sanki? 

çocuksun çocuğum büyü artık,

ruhuna erdemli sunular bulaşsın artık.

Kim kalmış sağnak bakışların kan kırmızı uzun yollarında

Kim ölmemiş uzanıpta serin topraklara

çocuksun çocuğum anla artık.

Anlayamadığım bir şey var kaçışında ilmiklenen,

gerçi çocukluk kokan tatlı bir kaçış bu...

angarya sevdamı sandın sen sevda mı? 

sen ruhsuz sen anlamaz sevdayı.

Bulutların dirhem yağmura cimri vaktinde

suskunluğun nedendir? 

güzel bir portredir kuşların kanadında

mavi tuvale,rengi kahve gözlerin,

ve yüreğime yayılan hasretin...

çocuksun çocuğum dinle artık

sessiz senfoniye son baskı gülüşlerini ekle artık.

Ne yapılır ki bilinmez bu renk cümbüşünde

bir renk cümbüşü ki kül bırakmaz esnek gidişiyle.

Yaprağın yeşil işlemeli esmer can damarında

bir su birikintisi...kızıl bir bilmece...

çocuksun çocuğum renklen artık

yeşili maviyi sarıyı tanı artık.

08,04,2005', 'Bir mızıka,bir fülüt,bir kaval biri gözlerin,biri gülüşlerin,biri dertlerim benim. Ayrımı düştük saatlerce umrunda mı sanki?  çocuksun çocuğ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Tolay']::text[], 8.5, '{"poet":"Mehmet Selim Tolay","poet_slug":"mehmet-selim-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cocuksun-cocugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapı Anahtarla Açılmalı', 'kapi-anahtarla-acilmali-gokhan-karaduman-dg2ty', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kapı anahtarla açılmalı

Sen olmalısın gelen

Usul bir buse ile

Uyandırmalısın beni

Elimde kitabımla

Uyukladığım koltuktan

Önce iki neskafe yapmalısın

Sonra çayları ben koymalıyım

Türk kahvelerini yine sen

Hiç bitmemeli bahanelerimiz

Uzanmalıyız yan yana

Biraz sevgili, biraz dostça

Biraz resmi, biraz samimi

Konuşup bozmamalıyız anı

Kapı Anahtarla açılmalı.', 'Kapı anahtarla açılmalı Sen olmalısın gelen Usul bir buse ile Uyandırmalısın beni Elimde kitabımla Uyukladığım koltuktan Önce iki neskafe ya...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kapi-anahtarla-acilmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlle Allah', 'i-lle-allah-ali-riza-unal-hwphr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey güzeller güzeli.

Sana sevdam ezeli.

Mevt ettin varımı.

Naçarım ya ilâhi

Tükenmesin sana sevgim.

Ebedi kıl ebedi.

Valsına mesti nuş’um

Saçarım şan’ı ar’ımı.

Bir garip meşki cuş’um

Firakın azaptır bilene.

Bizi sensiz eyleme sevgili.

Ebedi kıl ebedi.

Vuslatın cennettir arife billah.

Şükraneyim lütfuna elhamdülillah.

Adın her nefeste bismike bismillah.

Tevhidim euzû bike minke, vallahi.

Ebedi kıl ebedi, ya ilâhe ille Allah.', 'Ey güzeller güzeli. Sana sevdam ezeli. Mevt ettin varımı. Naçarım ya ilâhi Tükenmesin sana sevgim. Ebedi kıl ebedi. Valsına mesti nuş’um Saç...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ille-allah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Boğazına Düğümlenir', 'ayrilik-bogazina-dugumlenir-i-smail-ozabaci-yrpj0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eğer bir gün ayrılırsa yolarımız

Ellerimiz ve yüreğimiz koparsa aniden

Gidenin arkasından çalınan yüreğine takılırsa

Geride kalan yaşlı gözler

Bilirsin sen de imkansızdır unutmak

Her nisan, her eylül

Aralık, beklide bir mart

Gecelerin ötesinden savrulan hüzün

Hep unutmak isterken onu

Çayından aldığın bir yudumla

Düğümlenir binlerce anı boğazına…', 'Eğer bir gün ayrılırsa yolarımız Ellerimiz ve yüreğimiz koparsa aniden Gidenin arkasından çalınan yüreğine takılırsa Geride kalan yaşlı gözl...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ayrilik-bogazina-dugumlenir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimden Tutmazsan Öleceğim Sanmıştım', 'elimden-tutmazsan-olecegim-sanmistim-i-smail-ozabaci-tsia6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir hastane odasında

Yarım kalmıştım

Burnumda bir ilaç kokusu

Elimden tutmazsan öleceğim sanmıştım

En çoçuk yanınla yalnız kalmıştım

Annen oluyordum

Baban oluyordum

Ellerinde bir çiçek gibi soluyordum

Gözlerin doluyor lakin

Ağlamıyordun

Belli etmiyordun bana

Bir yıldız gibi kayıyordum avuçlarından

Yüzüm solmuş, gözümün altında morluklar

Bir hastane odasında en sevdiğin adam oluyordum

Ellerimi sıkıyordun

Acıtıyordun istemeden

Belli ki içinden “hayır ölemezsin “diyordun

Aldırmıyordun kolumdaki seruma

Anlamsız bakışlarıma

Başucumda bekliyordun öylece

Uykusuzdun bilmem kaç gece

(ben seni çok seviyordum) 

düşeceğim sandım

sana tutunuyordum

belki son kez seni seviyorum demek istiyordum

olmuyordu

üşüyordum

anlarsın diye var gücümle elini sıkıyordum,

vakit gelmişti

zaman dolmuştu

hayatın renkleri bir bir sönmüştü

bir veda kalmıştı geriye

oda sadece ellerineydi

önceleri dokunamadığım ellerine

düz bir çizgiye döndü sonra kalp atışlarım

-/-/-//-----------

sonra sustu ve sonsuza uzandı bu çizgi

elim elinden düşmüştü,

hepsi bu...', 'Bir hastane odasında Yarım kalmıştım Burnumda bir ilaç kokusu Elimden tutmazsan öleceğim sanmıştım En çoçuk yanınla yalnız kalmıştım Annen o...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/elimden-tutmazsan-olecegim-sanmistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babil Kulesi', 'babil-kulesi-nurol-banabak-kp4li', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '“en büyük ceza değil midir insan insana”

not: buradaki şiir tarafımdan kaldırılmıştır /nb', '“en büyük ceza değil midir insan insana” not: buradaki şiir tarafımdan kaldırılmıştır /nb...', ARRAY['Türk Edebiyatı','Şiir','Nurol Banabak']::text[], 8.5, '{"poet":"Nurol Banabak","poet_slug":"nurol-banabak","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/babil-kulesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Gece', 'ey-gece-i-smail-ozabaci-mhxe9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yar olup

Yaramı deşme ey gece

Nice yarlar geçtim

Yardan öte

Sen kendini karanlık san

Sen kendini yalnız

Bahtım karadır senden

Yalnızlığım en az senin kadar

Bak yine gece

Ekliyorum acımı yine

Ne senin haberin var bundan

Ne de yıldızların

Ey gece

Bir o biliyor yandığımı

Bir o anlıyor beni

İnan gece bahane

Ey gece

Sen de bekle benim gibi güneşin doğuşunu

Hadi sıyrıl karanlığından ve

Ayağa kalk artık

 Haykır dünyaya

Yıldızları sevdiğini

Ey gece', 'Yar olup Yaramı deşme ey gece Nice yarlar geçtim Yardan öte Sen kendini karanlık san Sen kendini yalnız Bahtım karadır senden Yalnızlığım en...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ey-gece-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resmin Yoktu Ellerimde', 'resmin-yoktu-ellerimde-i-smail-ozabaci-t29oi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Resmin yoktu ozaman karşımda

Gözlerin yıldızlar kadar güzel

Ve en az onlar kadar uzaktı bana

Öyle uzaktan sevmiştim seni oysa

Oysa gözlerimde bir hüznün kırıntıları vardı

Resmin yoktu o zamanlar elimde

Her istediğimde bakamazdım yüreğine

Ellerin yağmur damlalarını andırırdı ve

Geceleri senin için yürürdüm caddelerde

Yüreğim sana yazılan şiirleri barındırırdı

Ben sevdana düşmüşken sen nerelerde

Resmin yoktu o zamanlar elimde

Her istediğimde dokunmazdım ellerine

Yalnızlığımı aşırıp gün gün pencerenden

Öylece yanında bitiriverirdim güneş misali

Sen kendini sorgularken geceleri

Islak gözlerimde ortak bir hüznün izleri

En muhtaç olduğum an gözlerine

Resmin yoktu o zamanlar

Her şeyi söyleyemezdim yüreğine

Hep sen anlardın beni

Cümleler kurulmamışken daha

Anımsadığım her anıda yine  bulurdum seni

Oysa sen yanımdaydın

Oysa aylardan ocaktı

Oysa söyleyememiştim sana

Çiçeklere ezberlettiğim ama sana

Söylenmesi gerekenleri

Oysa hep sen anlardın beni

Aşktan yorulduğu an sabır

Kapıma dayandı cümleler

Seni aradı heryerde

Gözlerimden okuduğun hüzünler

Belki söyleyememiştim

Belki cesaretim yoktu

Belki hazır değildim

Oysa çok ihtiyacım vardı gözlerine

Resmin yoktu o zamanlar elimde

Her istediğimde anlatamazdım yüreğine

Neden sonra açmıştım yüreğimi sana

Karşımda susuyordun

Belki zamansızlığımı

Belki ansızlığımı düşünüyordun

Oysa ben gül yüzüne

Seni sevdiğimi söylüyordum,oysa resmin yoktu ellerimde', 'Resmin yoktu ozaman karşımda Gözlerin yıldızlar kadar güzel Ve en az onlar kadar uzaktı bana Öyle uzaktan sevmiştim seni oysa Oysa gözlerimd...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/resmin-yoktu-ellerimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-i-smail-ozabaci-8tp8o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni düşündüm sevgili

ve küfrettim sevdiğin tüm adamlara

kendime kızdım sonra

sana çiçeğim derken

meğer ne çok çiçek ezmişim ayaklarımın altında,

oysa sen de basıp geçmiştin 

kalbimin üstüne 

''kalbime basmayın'' yazıyordu tabelada oysa

bir ''ben'' olsaydım diye düşündüm yanında

yüzünde bir ben olsaydım,

senden bir parçayım diye

severmiydin beni sonunda,

o zaman kendime küfretmiş mi olurdum acaba?', 'seni düşündüm sevgili ve küfrettim sevdiğin tüm adamlara kendime kızdım sonra sana çiçeğim derken meğer ne çok çiçek ezmişim ayaklarımın alt...', ARRAY['Türk Edebiyatı','Şiir','İsmail Özabacı']::text[], 8.5, '{"poet":"İsmail Özabacı","poet_slug":"i-smail-ozabaci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-160-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlarımı Göresim Geldi', 'dostlarimi-goresim-geldi-dogan-i-nceman-h7m70', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gamzedeyim Deva Bulmam''ı

Barış Manço''dan dinlerdik,

Ya '' Ben Gamlı Hazan? 

Melahat Pars''ın bestesi,

Bir Bahar Akşamı Rastladım Size...

Ya Nasıl Geçti Habersiz

O Güzelim Yıllarım? 

Bahar değil miydi hepimize? 

Tatlılar ucuzdu,

Dostlara paha biçilmezdi...

Kızlar bizim için geçerdi

Ali İhsan Hoca''nın Kahvesi''nin önünden.

Ve biz bir kitap okurda

Memleketi kurtarırdık.

Hatta Paranın Ne Önemi Var,diyordu Özdemir Erdoğan,

Bu günlere geldi bizim nesil; 

''Hadi İçelim,Aşkın Şarabını Mest Edelim,

Kusura bakma Avni Usta,

Ya siz Sayın Yusuf Nalkesen,

Gölgesinde oturulacak ne ağaç,ne sevgili kaldı...

Ya Şekip Ayhan  Özışık,

Ya Teoman Alpay,

Ya Zeki Bey? Şimdi Nerelerdesin? 

Gönül Hicranla Dolu...

Karşı kaldırımdan takip ettiğimiz

Lise aşkımız vardı; 

Karlar yağar,gecenin soğuğunda

Aşkımızın evinin önünden geçerdik,

Burç Şarabı içerdik sarı elmayla,

Birazda kudama,

Dişlerimiz sağlamdı,kırardı o zaman,

HERŞEYİN BİR RACONU VARDI OYSA; 

Niye uzaklaştık bu kadar? 

Mahalleler aynı,

Sokak bekçileri yok diye,

Birileri geçmişimizi mi çaldı?', 'Gamzedeyim Deva Bulmam''ı Barış Manço''dan dinlerdik, Ya '' Ben Gamlı Hazan?  Melahat Pars''ın bestesi, Bir Bahar Akşamı Rastladım Size... Ya Na...', ARRAY['Türk Edebiyatı','Şiir','Doğan İnceman']::text[], 8.5, '{"poet":"Doğan İnceman","poet_slug":"dogan-i-nceman","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/dostlarimi-goresim-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolaymı', 'kolaymi-mehmet-dag-84o33', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Daha dün yeşermek için can atıyordum.

Bu yurt  toprağında allı,yeşilli

Aç madan gözlerime kezzap döktüler

Kazmayla baltayla vurup söktüler. 

Vatan perverlerim,yönetenlerim.

Şimdi mendili elinde bir dilenciyim 

Yaban ellerinde  ekmek arayan.

........

Ağlamak ağrıma gitmiyor benim 

Hasretin, ciğerin fiyatı kaça

Dağılmak, bölünmek öyle kolay mı

Bütünü ömründe görmeyenlerim

....

Yol bekler sılada anam, avradım

Sağ böbrek sol gözüm satıp ta yedim

Ölmüş diye eve haber yolladım 

Yaşayan bir ölü  sizce kolay mı? 

(Avcılar)', 'Daha dün yeşermek için can atıyordum. Bu yurt  toprağında allı,yeşilli Aç madan gözlerime kezzap döktüler Kazmayla baltayla vurup söktüler. ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dağ']::text[], 8.5, '{"poet":"Mehmet Dağ","poet_slug":"mehmet-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kolaymi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firtina', 'firtina-mehmet-yilmaz-ynhsf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben böyleyim,

Yagmurda gezerken semsiyemi acmam,

Yagmur bana degsin isterim.

Ben senden semsiye olmani degil,

Yagmur olmani istiyorum.

Ya sen kücük budala? 

Firtina koparabilecegine inaniyor musun?', 'Ben böyleyim, Yagmurda gezerken semsiyemi acmam, Yagmur bana degsin isterim. Ben senden semsiye olmani degil, Yagmur olmani istiyorum. Ya se...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/firtina-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Düşündünmü', 'hic-dusundunmu-hasan-akar-mkimk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nasıl geçti çocukluk gençlik yılların.

Birgün yaşlanacağını hiç düşündünmü? 

Arabaların yatların mücevher ve altınları. 

Bez parçasıyla gömüleceğini düşündünmü? 

Kalp kıra kıra geldin bu günlere.

Bunun için özür dilemeyi düşündünmü? 

Yükledin suçunu günlere aylara senelere.

Geriye dönüp yaşadığın hayatı düşündünmü? 

Oldu eşin çocuğun dostların yanında.

Onlarsız mezarda yalnız kalacağını düşündünmü? 

Yaşadın bol bol birelin balda birelin yağda.

Vücudunu yılanlar çıyanlar yiyecek düşündünmü? 

Demogoji yaptın siyaset yaptın bonusu kaptın.

Birgün tek tek hesap vereceğini düşündünmü? 

Zaman oldu zoru görünce arkadaşını dostunu sattın.

mahşerde kaçacak delik olmadığını hiç düşündünmü?', 'Nasıl geçti çocukluk gençlik yılların. Birgün yaşlanacağını hiç düşündünmü?  Arabaların yatların mücevher ve altınları.  Bez parçasıyla gömü...', ARRAY['Türk Edebiyatı','Şiir','Hasan Akar']::text[], 8.5, '{"poet":"Hasan Akar","poet_slug":"hasan-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hic-dusundunmu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketim İstanbul', 'memleketim-i-stanbul-deniz-onderoglu-xkqul', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Memleketim İstanbul

Yok dünya üzerinde senin gibi bir şehir

Aşk sende

Sevda sende

Mutluluk sende

Ayırılık sende sadece bu kadar güzel olablilr

Senin denizinin gözüyle bakmak dünyaya

Ve senin mavi göğünün altında nefes almak

Ve senin topraklarında yummak gözlerimi dünyaya

İstanbul, memleketim İstanbul

Eğer tekrar geleceksem bu dünyaya

Yine seninle yaşamak isterdim

Galata kulenden sana bakmak

Boğazında denizini seyre dalmak isterdim

Tarihin senin talihindir İstanbul

Memleketim İstanbul', 'Memleketim İstanbul Yok dünya üzerinde senin gibi bir şehir Aşk sende Sevda sende Mutluluk sende Ayırılık sende sadece bu kadar güzel olabli...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/memleketim-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşayan Aşkımız', 'yasayan-askimiz-deniz-onderoglu-5jrfh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geldiğin gün kapıma

Yüreğimin ve kalbimin kapılarını

Sonuna kadar açacağım sana

Sana yeminler edeceğim

Ruhum ve bedenimle

Sonsuza dek senin olacağıma

Söz etmeyeceğim sevdamızdan 

Kimselere

Bizimle ölecek

Yaşayan aşkımız!', 'Geldiğin gün kapıma Yüreğimin ve kalbimin kapılarını Sonuna kadar açacağım sana Sana yeminler edeceğim Ruhum ve bedenimle Sonsuza dek senin ...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yasayan-askimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilir misin?', 'bilir-misin-deniz-onderoglu-86c00', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen aşk nedir bilir misin? 

Ellerin boşluktayken bile

Onun ellerinin dokunuşunu hissetmektir

Gözlerin kapalıyken

Onun gözlerinin içine bakmaktır

Kalbinde her zaman onun sıcaklığını duymaktır

Aşk bazen savaşmaktır

Karşındaki ordu ne kadar büyük olsa da

Tek başına karşı koymaktır

Elindeki tek silahındır aşkın

Atacak tek kurşunun yoktur

Saldıracak düşmanın da yoktur aslında

Yalnızca sen olursun bu savaş oyununda

Ve kaybetmemek için 

Her şeyini vermelisin!', 'Sen aşk nedir bilir misin?  Ellerin boşluktayken bile Onun ellerinin dokunuşunu hissetmektir Gözlerin kapalıyken Onun gözlerinin içine bakma...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bilir-misin-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Issız Bir Liman', 'issiz-bir-liman-hasan-can-oly5y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Köşeme çekilmiş bekliyorum, 

Ne çayımın tadını alabiliyorum, 

Ne de sensiz yatabiliyorum. 

Sadece karşımdaki boş duvarla kendimi avutuyorum, 

Ben ona şarkılar söylüyorum, 

Kelimeler ona çarptığın da, 

heceleri bir bir kulağımda buluyorum, 

Yani kendimi kandırıyorum... 

Öyle karanlık ki geceler, 

Bir yanımda acının adına okunan şarkılar, 

Bir yanımda da senden kanal hüzünlü anılar. 

Bir yıldız bile yok gökyüzünde, 

Benim karanlık geceme ait. 

Bir ay ışığı bile yok, 

Bulutların arasından karanlığa süzülen. 

Karanlık bir köşede, 

Karşımda duran beyaz bir duvar ve ben, 

Daha ne bekleyebilirim ki geceden. 

Alıp kendini gündüze vursa, 

Bir umut bekleyemem sen olmayınca. 

Güneş gökyüzünü aniden sarsa, 

Sensiz neye yarar ki hep orada kalsa. 

Issız bir limanda, 

Karaya oturmuş bir gemi gibiyim, 

Öylece kalakalmışım... 

Bir dalga beni alıp götürür diye öylesine bekliyorum...', 'Köşeme çekilmiş bekliyorum,  Ne çayımın tadını alabiliyorum,  Ne de sensiz yatabiliyorum.  Sadece karşımdaki boş duvarla kendimi avutuyorum,...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/issiz-bir-liman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiyorum', 'i-stiyorum-hasan-can-u6bfy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceyi istiyorum, 

Günün yorgunluğunu atabilmek için, 

Ve sensizlikten kaçabilmek için. 

Rüzgarı istiyorum, 

Alıp götürsün diye bütün anıları, 

Ve karşımda duran hatıraları. 

Yağmuru istiyorum, 

Dokunduğun her varlık bir nasip alsın diye, 

Ve giderken bıraktığın izler silinsin diye. 

Bir sevda istiyorum, 

Sevgiye lanet ettirsin diye.', 'Geceyi istiyorum,  Günün yorgunluğunu atabilmek için,  Ve sensizlikten kaçabilmek için.  Rüzgarı istiyorum,  Alıp götürsün diye bütün anılar...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/istiyorum-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim Seni', 'ozledim-seni-nurten-altinok-bf32q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özledim seni

Özlemek buysa

Baktığım her yerde, seni görüyorsam

Özledim seni

Yokluğunu her an hissediyorsam

Özledim seni

Adın  bir ateş olmuş da, yanıyorsam

Özledim seni

Maviler ölümsüzleşiyor dizelerimde

Farketmedin mi? 

Davetsiz bir misafir gibi bitiversem kapında

Özledim seni

Özlemek buysa

Alıversen içeri...', 'Özledim seni Özlemek buysa Baktığım her yerde, seni görüyorsam Özledim seni Yokluğunu her an hissediyorsam Özledim seni Adın  bir ateş olmuş...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ozledim-seni-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buldum Derken...', 'buldum-derken-hasan-can-f9s4e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soğuk ve sakindi gece, 

Yoktu seni anlatacak bir hece, 

Çekip gittiğinden beri, 

Hayat sanki bir bilmece. 

Kendimi kaptırıp hayale daldığımda, 

Sen yoksun ama sesin kulağımda, 

Bulmak istercesine seni arkama baktığımda, 

Buldum derken kaybediyorum düşümden uyandığımda. 

Yoksun artık çareler tükendi, 

Oysan tüm benliğim sendeydi, 

Ama herşeye rağmen, 

Tattırdığın acılarda güzeldi...', 'Soğuk ve sakindi gece,  Yoktu seni anlatacak bir hece,  Çekip gittiğinden beri,  Hayat sanki bir bilmece.  Kendimi kaptırıp hayale daldığımd...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/buldum-derken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-seyit-ahmet-duzen-1x19c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu akşam öldün biliyor musun? 

Güneş soyunurken kızıllığına, 

Bolu dağının doruklarında, ansız gittin. 

Yalancı bahara aldanan çiçekler gibiydin, 

Filizlenirken tomurcukların, çöktü soğuk…

Hiç kimse fark etmedi yokluğunu öyle güzel ölmüştün ki.

Ne çok istemiştim ah bir bilseydin, bilseydin.

Keşkelerimin, nice sahibi olmak isteyen oldu. 

Keşke dedim seninle gelebilseydim.

Zamansız gittin ve habersiz

Tanımadığım bir kadının resmini buldum ve âşık oldum. 

Yıldızdılar döküldü her akşam pencereme. 

Ciğerine mermi saplanmış, bir kurbanın feryadıydı. 

Odamın tavanına çarpan 

Ah bir adını koyabilseydim senin. 

Yıldızlar, çiçekler, denizler, şehirler ve tüm şarkılar… 

Hiçbir şey, hiçbir isim ifade edemezdi adını…

Nereye gideceğini bilemeyen bir otostopçunun çaresizliği

Hangi istasyonda ineceğini bilemeyen adamın belirsizliği

Yinede her şeye rağmen, yaşamak sensizde güzel(yalan)', 'Bu akşam öldün biliyor musun?  Güneş soyunurken kızıllığına,  Bolu dağının doruklarında, ansız gittin.  Yalancı bahara aldanan çiçekler gibi...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Düzen']::text[], 8.5, '{"poet":"Seyit Ahmet Düzen","poet_slug":"seyit-ahmet-duzen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yalan-141-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Kuşlar', 'canim-kuslar-mehmet-dag-d0th4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sakın taş atmayın kuşlara

Kanadı kırılır uçamaz onlar

Kedi,Köpek neyse insandan sakla 

Alevler içinde pişirip yerler

                       (Avcılar)', 'Sakın taş atmayın kuşlara Kanadı kırılır uçamaz onlar Kedi,Köpek neyse insandan sakla  Alevler içinde pişirip yerler                        ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dağ']::text[], 8.5, '{"poet":"Mehmet Dağ","poet_slug":"mehmet-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/canim-kuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmek O Kentten', 'gitmek-o-kentten-ferhat-gencer-i-saca-tl9l8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gidiyorum buralardan

sensiz çekilmez bu kent 

sana bülbül kadar yakınken 

seni ayının kollarında görürken

üzerime çullanıyor bu  kentin sisi

gidiyorum buralardan

seni yüreğimin en derinine gömertek 

ve seni burada bırakarak

seni severek gidiyorum

gidiyorum

bilesin

çekemem bu şehri artık

hastayım ama farkındayım 

sana hastayım

derman bulmaya gidiyorum

 gidiyorum bulmaya 

seni bulamamaya', 'gidiyorum buralardan sensiz çekilmez bu kent  sana bülbül kadar yakınken  seni ayının kollarında görürken üzerime çullanıyor bu  kentin sisi...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Gençer İsaca']::text[], 8.5, '{"poet":"Ferhat Gençer İsaca","poet_slug":"ferhat-gencer-i-saca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gitmek-o-kentten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tebessüm', 'tebessum-hakan-tolunay-812da', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni tanımadan önce o güzel yüzünde bir tebessüm olsun istedim.', 'Beni tanımadan önce o güzel yüzünde bir tebessüm olsun istedim....', ARRAY['Türk Edebiyatı','Şiir','Hakan Tolunay']::text[], 8.5, '{"poet":"Hakan Tolunay","poet_slug":"hakan-tolunay","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/tebessum-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Afrika''da Çocuklar Ağlıyor', 'afrika-da-cocuklar-agliyor-nurten-koroglu-w2bub', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneşin o cehennem sıcağında

Haritanın unutulmuş  köşesinde

Açlık,sefalet bir yanda

Tüm dünya umursamazca bakıyor

Gözlerinde kan rengi yaşlar

Afrika''da çocuklar ağlıyor

Oyuncak olmuş tüm dünyanın seyrinde

Tarihin o utanç sayfasında

Sanki bir dram filmi çevriliyor

Filmin öbür perdesinde

Dünyada bugün yeni bir yıl kutlanıyor

Afrika''da çocuklar ağlıyor

İkibin''li yıllara üç kala

İnsan insan olduğundan utanıyor

Batıda teknoloji çağı

Bir eşyanın yerine,bir başkası konuyor

Öte yandan bir yudum ekmeğe hasret

Gözlerinde kan rengi yaşlar

Afrika''da çocuklar ağlıyor', 'Güneşin o cehennem sıcağında Haritanın unutulmuş  köşesinde Açlık,sefalet bir yanda Tüm dünya umursamazca bakıyor Gözlerinde kan rengi yaşla...', ARRAY['Türk Edebiyatı','Şiir','Nurten Köroğlu']::text[], 8.5, '{"poet":"Nurten Köroğlu","poet_slug":"nurten-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/afrika-da-cocuklar-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Epigram', 'epigram-nurol-banabak-82p6i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '“Aşk, bize güç veren tek özgürlük yitimidir.” 

(aragon) 

I

aşk bir sır sevgili

bizse ters durmuş

iki soru işareti

II

gecenin yarısı geçmiş

geçememişiz

geçilmiyor işte

aşk işte

işte

III

şiir ki, Tanrı’dan gelen kelamdır

şiir ki, senden geride kalandır

IV

Şair olmak uzun zaman alır

Bir ömür falan

V

Niye insanlar bu kadar farklı

Hiç şiir okumayanlar da insan

Şiirsiz edemeyenler de

VI

Kan üstünde çul serer

Bilmem bu kimi sever

Ey hikmetinden sual olunmazım

Amerika nire Irak nire! ?', '“Aşk, bize güç veren tek özgürlük yitimidir.”  (aragon)  I aşk bir sır sevgili bizse ters durmuş iki soru işareti II gecenin yarısı geçmiş g...', ARRAY['Türk Edebiyatı','Şiir','Nurol Banabak']::text[], 8.5, '{"poet":"Nurol Banabak","poet_slug":"nurol-banabak","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/epigram-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dindirdim Rüzgarını', 'dindirdim-ruzgarini-gulay-yildiz-ij0ko', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Efendisiydi ya rüzgarların; 

Gösterdi Efendiliğini! 

Dindirdim diye afeti, 

Kesti dans etmeyi rüzgarlarla

Ve şimdi,

Estiğinde üşüyen yanlarım

Hasretiyle yanmakta

*Rüzgarın Efendisi''ne

Nisan, 2005

23:48', 'Efendisiydi ya rüzgarların;  Gösterdi Efendiliğini!  Dindirdim diye afeti,  Kesti dans etmeyi rüzgarlarla Ve şimdi, Estiğinde üşüyen yanları...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dindirdim-ruzgarini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Yine Güzel', 'i-stanbul-yine-guzel-rahim-recep-akdora-o4ifc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İstanbul doğanın kucağında

sarmaş dolaş sularla

evrensel güzel

evrensel bir şehir

veremli şairlerin 

kalıcı kalemlerinde

İstanbul sırlar kalesidir

gecelerinin aydınlığı

karanlığı gündüzlerinin

çözülmesi olanaksız bir bulmaca

her güzellik bir çirkinliğin tülü

umut yaprakları

beklemeden dökülür Eylülü

dalgalarda dökülen gözyaşları	

çarpar acı acı İstanbul''un suratına

her adım atışta bir hile

her parmak bir sahteliğin idmanında.

İstanbul yine evrensel

duygusal insanların

iyi niyetlerinde

yine güzel bir şehir

İstanbul kucak açmalarda yine cömert.

Çıplak bir alüfte

bıyıklı bir erkeye sulanmış

sokakların suskunluğunda	

hilelerden uzak bir insan

kaldırım taşlarının utancında bırakmış

gözlerini

dürüstlüğüne bedel.

İstanbul yine evrensel güzel

İstanbul suların kucağında

yine evrensel bir şehir

Sarayburnu 

hep büyüklüğümüzü fısıldar bize

deniz mi sokulmuş oraya şıpır şıpır

Sarayburnu mu sokulmuş usul usul denize

mesajlar gelir	

mesajlar gider dünyaya

balıkların dilsizliğinde.

Rumelihisarı''ndaki gözümüz

göz açtırmaz korsanlara

düşünüyorum

Fatih Mehmet mi güzelleştirmiş İstanbul''u

yoksa Fatih''i bunca İstanbul mu büyütmüş

sahi Tefik Fikret''i kim götürmüş oraya

haykırışlarıyla yüceltmiş

Aşiyan doruklarını

Orhan Veli

niye hep gözleri kapalı dinlemiş İstanbul''u? 

Yeter artık,

Beyoğlunun ''Çiçek Pasajı''

el atsın kötülüklerin hücre evlerine

dile gelsin konuşsun

kadehler uzaktır kötülüklerden

ışık göndersinler

ışığa muhtaç

insan yüreklerine

Kaldırım taşları gurur duyar ezilmekten

gurur duyar kadın ayakları altında

ayakları altında	

mert, dürüst erkeklerin

ezilmekten mutlu bu taşları

kana bulamak niye? 

İstanbul''lular

insan olamıyorsak

sevemiyorsak insanları

saygımız yoksa ağaçlara

tek bir yaprağına bile hasret olduğumuz

ezilmekten gurur duyan taşları koruyalım

üstünde rahatça yürüdüğümüz.

Unutmayalım yıllardır nöbet tutan minareleri

saplanmış gibi düşmanın göğsüne 

kılıç kılıç minareler

delerler gökleri

füzeleşmiş uçlarından huzur rüzgarları eser

ulusumun yenilmezliğini haykırır uzaklara

Anıtsallıklarından ulusumun nefes alışı gülümser

İstanbul doğanın kucağında

sarmaş dolaş sularla

yine evrensel

yine doğal 

yine güzel', 'İstanbul doğanın kucağında sarmaş dolaş sularla evrensel güzel evrensel bir şehir veremli şairlerin  kalıcı kalemlerinde İstanbul sırlar kal...', ARRAY['Türk Edebiyatı','Şiir','Rahim Recep Akdora']::text[], 8.5, '{"poet":"Rahim Recep Akdora","poet_slug":"rahim-recep-akdora","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/istanbul-yine-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyandı Anka...', 'uyandi-anka-emine-deniz-xr9ly', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kanına batırdım avuçlarımı

Bıraktım ahlarımı eyvahlarına

___Uyandı Anka

Yeniden yoğur beni

Yitikliğinin bittiği yerde ör bütün hücrelerimi

___Vuruldum anla

Kızıl bir şiirle yakılsın gece

Şuursuz aşkları avutalım  gönlümüzce

Kaf Dağı bizimdir 

Heyyy bundan böyle

Bizim kainat....

''''ASBUZU'''' yarattım sana içimde

Nice bozgunlardan çıkmış bu beden

Nice puştlar yangın olmuş içimde

Dağlarında vurulan son serçeyim ben

Karga gözü kuzgun olur mu söyle

___Adın kanat oldu yanık tadıma

Sokakbaşlarıma adını verdim

Dokunuşlarındır gayrı alnımda yanan

Kadınlığıma sokulan

Sokuldukça çoğalan yılanları ateşe verdim

Zehir kokulu parmaklarındır

Düşlerime dokunan

___Kanatlandım adına

Ki! 

Kanat taktın dudaklarınla ıslattığın çığlıklarıma...

Adın yok

Adım yok

Bundan böyle sen DAĞ ben göğsünde KANARYA

____________Yıkılsın dünya.

8.04.2005', 'Kanına batırdım avuçlarımı Bıraktım ahlarımı eyvahlarına ___Uyandı Anka Yeniden yoğur beni Yitikliğinin bittiği yerde ör bütün hücrelerimi _...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/uyandi-anka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Zulümden Baska ne Bilirsiniz?', 'siz-zulumden-baska-ne-bilirsiniz-kadir-soyturk-youu0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İki yüzlülük sizde, en adi yalan sizde; 

Var mı alın teriniz? Soygun ve talan sizde

Elinizden çıkınca, bütün çaldıklarınız

Zulümden başka nedir, söyleyin kalan sizde?', 'İki yüzlülük sizde, en adi yalan sizde;  Var mı alın teriniz? Soygun ve talan sizde Elinizden çıkınca, bütün çaldıklarınız Zulümden başka ne...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/siz-zulumden-baska-ne-bilirsiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sohbetdir.. Şiir Ola.. Hoş Ola..''''.Gül Ve Diken''''', 'sohbetdir-siir-ola-hos-ola-gul-ve-diken-galip-kemali-gunay-4w3y1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Diken 

Dur, geçilmezidir gülün 

Batar adama,

Der, koktum mu sana... der.. her gonca  yar olmaz.

Kadifeden tüllü, dikensiz, bin bülbüllü, öylesi bir açar ki, abdal adama, Anlayınca 

Şaşarsın,

Dikensiz gül gördün mü...', 'Diken  Dur, geçilmezidir gülün  Batar adama, Der, koktum mu sana... der.. her gonca  yar olmaz. Kadifeden tüllü, dikensiz, bin bülbüllü, öyl...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sohbetdir-siir-ola-hos-ola-gul-ve-diken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '´´´´İHTİYARLIK pencereden bakıyor', 'i-hti-yarlik-pencereden-bakiyor-veli-dalbudak-27baw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '..45..

Dayamış  ellerini cama

İhtiyarlık pençereden bakıyor

- Bekle hele birkaç yıl sonra

Kapını çalacağim - diyor

..55..

Tak.Tak.Tak. çalınıyor kapı

Nasıl kovsam bu ihtiyarlığı

Kapadıysamda gözümü,kulağımı

Açmasanda içeri dalacağım diyor

..65..

Bir gözü toprakta,bir gözü bedenimde

Götüreceğim diyor,sen istemesende

Artık dizginlerin benim elimde

Kalkmasanda,elinden, tutacağım diyor

..75..

....ya görürüm ya göremem.

(Stockholm 2005)', '..45.. Dayamış  ellerini cama İhtiyarlık pençereden bakıyor - Bekle hele birkaç yıl sonra Kapını çalacağim - diyor ..55.. Tak.Tak.Tak. çalın...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ihtiyarlik-pencereden-bakiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trabzonda böyledir,yurtta böyledir', 'trabzonda-boyledir-yurtta-boyledir-mikdat-bal-bfo99', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu vatan bu millet tektir bölünmez

Şerefsiz bir dava için ölünmez

Türkün birliğine karşı gelinmez

Trabzonda böyledir,yurtta böyledir

Üç tane çabulcu uydu şeytana

Apo bayrağını açmış meydana

Yurtsever Türk genci dur dedi buna

Trabzonda böyledir, yurtta böyledir

Bu vatan boş değil türk genci dolu

Vatanperver solcu, ülkücü dolu

Aşik,şair, ozan, türkücü dolu

Trabzonda böyledir,yurtta böyledir

Yurduma göz diken hain düşmanlar

Maşası olmuştur bazı insanlar

Onların planını Türk genci anlar

Trabzonda böyledir, yurtta böyledir

Üç kişi halt etmiş uzunsokak ta

Türk genci orada, değil uzakta

Yediden yetmişe ihtiyar halk ta

Trabzonda böyledir, yurtta böyledir

Bayrağıma saldıran,vatansızlar

Kirli bir bez kaldıran, imansızlar

Hep aynı cins, cıldıran vicdansızlar

Trabzonda böyledir,yurtta böyledir

Mkdat der bu millet gereği gibi

Ayaktata dır bayrak direği gibi

Her an kükrer, aslan yüreği gibi

Trabzonda böyledir yurtta böyledir', 'Bu vatan bu millet tektir bölünmez Şerefsiz bir dava için ölünmez Türkün birliğine karşı gelinmez Trabzonda böyledir,yurtta böyledir Üç tane...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/trabzonda-boyledir-yurtta-boyledir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Var Mı', 'haberin-var-mi-yusuf-ter-qg964', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Haberin var mı 

Kara kaşlım

Al yanaklım

Kiraz dudaklım 

Sürmelim

Belik saçlım

İnce  bellim 

Güzel resmin

Yanı başımda

Haberin var mı 

Ak göğsünde düğmeler

Elvan elvan 

Kokar tenin

Avuçları kınalı

bak

Ayağına  geldim

Sevdiğim yar

Haberin var mı…

Yusuf Ter 07.04.05

Saat 18:26 İsviçre', 'Haberin var mı  Kara kaşlım Al yanaklım Kiraz dudaklım  Sürmelim Belik saçlım İnce  bellim  Güzel resmin Yanı başımda Haberin var mı  Ak göğ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/haberin-var-mi-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Didikleme Şiiri.. ''''Allahaısmarlanırsın''''..', 'didikleme-siiri-allahaismarlanirsin-galip-kemali-gunay-m4699', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Didikleme şiiri, SAKLANMAZ ÖKÜZALTI BUZAĞI AŞİKARKEN

Üç beş düşün

Var mı senden bir ilmik, ele gelen bir düğmük, giy yakışdır

Başka desen ve dersen 

Yakışmaz, al başına taş tacı ki şiirin şiir olsun

Her yer taş dolu, menderesler de kum da

Sürür gider bu ırmak da, yakışmaz

 Hemı de her taş her başı yarmaz

Söz uçara kalmışsın, tamam, kaydın alınmışdır

Ama gene de 

Şiir sohbetdir, bilesin ki bilsinler

Ben ve sen ''''Allaha ısmarlandık''''', 'Didikleme şiiri, SAKLANMAZ ÖKÜZALTI BUZAĞI AŞİKARKEN Üç beş düşün Var mı senden bir ilmik, ele gelen bir düğmük, giy yakışdır Başka desen ve...', ARRAY['Türk Edebiyatı','Şiir','Galip Kemali Günay']::text[], 8.5, '{"poet":"Galip Kemali Günay","poet_slug":"galip-kemali-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/didikleme-siiri-allahaismarlanirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüteç-1', 'yurutec-1-mustafa-ceylan-9wom9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '...................*AB yürüteçken 

...................*Devir de ''gelgeç''ken 

..................Ağlarım Kıbrıs için... 

Kar-buz duygularım siz, siz gidin yüreğimden 

Felç üstüne felçim ben, tutmuyor ki sol yanım. 

Yatağımın yanında sinsi durur yürüteç 

Ve yarılır ortadan düşlerimde bir karpuz... 

İlâç olmaz bilirim dostların tesellisi 

Yokluğun ruh köküme zulüm eden bir kırbaç. 

Süslenen vitrinlerde mahzun çocukluğumuz, 

Dön de bir bak halime; 

...............................gel ey sonsuzdan sonsuz! ... 

Nerde kaldı bütün gün koşturduğum o yollar? 

Salıncak salladığım, türkü söyleyen dallar? 

Bu ayıplı bahçeyi kim yaptı mahalleme? 

Çarpışan arabasız, 

..........................dolapsız, 

.....................................helezonsuz... 

Omuz ver anneciğim, doğrulayım yerimden 

Şu beton yığınları renk alsın gözlerimden... 

Yalnızlık sana mahsus, böyle mi yazım benim? 

Nasıl yaşarım Tanrım? 

..............................arkadaşsız, 

..............................................okulsuz.... 

Açma televizyonu hitap etmiyor bana 

Ses vermiyor sesime radyo ile kitaplar; 

Kuşlara, çocuklara özlem dolu caddede 

Bir çığırtkan satıcı dolaşıyor 

......................................balonsuz... 

Ey akreple yelkovan, siz tutun bileğimden! 

Sihirli değneklerle çıkalım annnemle ben... 

Merdiveni göklere kuralım da yeniden 

Bir menzile varalım, 

...........................tünelsiz, 

.........................................istasyonsuz... 

Yenerekten bu felçi, atmalı yürüteçi 

Gül, gülistan olmalı kara gözlü memleket... 

Gün çıksın güneş çıksın, erisin kar ile buz, 

Yarılsın ortasından hakikaten bir karpuz.... 

Ve 

Giymeliyim kırmızı beyazlı elbisemi 

Vakit bu vakit anne, çıkmalıyım balkona... 

Günaydın demeliyim, hatırın sormalıyım 

Gökteki bulutlara, bahçedeki çınara... 

Bu sinsi, yürüteçi fırlatarak kenara...', '...................*AB yürüteçken  ...................*Devir de ''gelgeç''ken  ..................Ağlarım Kıbrıs için...  Kar-buz duygularım si...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/yurutec-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Boynunun Kıvrımlarına Dolanmak Vardı İpince**', 'boynunun-kivrimlarina-dolanmak-vardi-i-pince-hulya-simsek-vxdkp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Boynunun  kıvrımlarına dolanmak vardı ipince 

Gözeneklerinden taşan emeği

İçerek beslenmeliydi aşkım

Kanım,

Etim,

kemiğimle

Dokunabilseydim tenine

Yüz parçaya ayrılacaktı

Ellerim…

Argos’un gözleriyle bakardım sana

Her geçişinde önümden

Düşlerine resmetmek uğruna…

Bir gözüm diğerini öldürürdü.

Boynunun kıvrımlarına dolanmak vardı içince

Mayhoş bir tadı olmalıydı terinin

Seline kapılıp inmeliydim göğsüne

Aşkın

Bir

Elinde

katil tutkusu vardır sevgili

göğsüne inersem 

ince bir urgan olurum

Boynunun kıvrımlarına dolanmak vardı ipince

Sırat köprüsü olurdum her öpüşümde

Ölen çocukların bakışlarını biriktirdim ben

Ceplerimdeki ince çığlıklar hazır gidişine 

Kaç düş

Girmiş

iç içe

Saçlarımdan bile daha karışık

Ahh Godot! 

Bir elim sevgiliye

Bir elim sende…

o9.o4.2oo5   o2:35      İst.', 'Boynunun  kıvrımlarına dolanmak vardı ipince  Gözeneklerinden taşan emeği İçerek beslenmeliydi aşkım Kanım, Etim, kemiğimle Dokunabilseydim ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Şimşek']::text[], 8.5, '{"poet":"Hülya Şimşek","poet_slug":"hulya-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/boynunun-kivrimlarina-dolanmak-vardi-ipince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Padişah Dayısı Kadar', 'padisah-dayisi-kadar-mustafa-ceylan-j7xeg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Taç oldun başıma ahir zamanda

Gökteki yıldızın sayısı kadar...

Benzeri olmayan şekersin, balsın

Tadından yarılan kayısı kadar...

Kucak açıyorken sularım aya

Aşkın nabız nabız başlar atmaya...

Züleyha yüreğin hazır yutmaya

Yusuf''un su dolu kuyusu kadar...

Neler yaptın neler, bu Ceylan için? 

Yorgun hafızamı işgal eden cin

Ya da şeytanımsın, dopdolu için

Çözülmeyen papaz büyüsü kadar...

Her saat ismini bahsederim ben,

İsminle dönerim, raksederim ben,

Seni görür, bilir, duyar; hissederim ben

Sağlam insanın beş duyusu kadar...

Sevda kuşum oldun dalda çırpınan,

Yaprağa, çiçeğe müjdeler sunan...

Olgunsun, dolgunsun güzelim inan

Sarı portakalın iyisi kadar...

Benziyor gözlerin çfte silâha,

Aşk kurşunu sıkar, ermem sabaha.

Sevdim ya ben seni şükür Allah''a! 

Mutluyum, padişah dayısı kadar...', 'Taç oldun başıma ahir zamanda Gökteki yıldızın sayısı kadar... Benzeri olmayan şekersin, balsın Tadından yarılan kayısı kadar... Kucak açıyo...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/padisah-dayisi-kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-*-Gör-*-', 'gor-mustafa-ceylan-acy1r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '....-Berhudar Ramazan Çeşme Kardeşime..-

Özlem ateşiyle yanmışım deme

Ayaz gecelerde ocak ol da gör.

Has gül bahçesinden öte gideme

Öksüze, yetime kucak ol da gör.

Çıkar anıları bir bir resimden,

Bunca olaylardan, bunca isimden...

Bengisu bekleme giden mevsimden

Çevir takvimleri çocuk ol da gör.

Her ne arar isen vardır insanda,

İnsan ki aşk arar Martta-Nisanda...

Direksiz semaya uçtuğun anda

Yakıtı tükenmiş uçak ol da gör.

Hacer ül esved ol dost Kâbesinde

Yedi dil, bir dile dönsün sesinde.

Yok olan aşkların kulübesinde

Ucundan buz sarkan saçak ol da gör.

Aynaya benzersin hem de tıpa tıp

İnsana insanı gözle yansıtıp; 

Umut doruğunda kından sıyrılıp

Buluta saplanan bıçak ol da gör.

Işık salkımıyla bağ yap özünü

Hoşça bak herşeye çevir yüzünü.

Karanlık gecede yumma gözünü

Soğuk güneşlere sıcak ol da gör...

''Ölmeden evvelce öl'' de öyle gör...', '....-Berhudar Ramazan Çeşme Kardeşime..- Özlem ateşiyle yanmışım deme Ayaz gecelerde ocak ol da gör. Has gül bahçesinden öte gideme Öksüze, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gor-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-emin-akduman-rnvoi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyormusun sensizliğin o korkunç heybetini? 

Sen hiç yaşadın mı,benim yerime sensizliği? 

Surları yıkılmış kale gibiyim inan

Beden varda can yok can.

Sensizlik; 

Sanki bir sigara, bir kibrit

Yakınca bitecek sanırsın.

Yanar için içinde beni de yakar inan

Beklerim sonu gelsin,

Sonu gelmez hiçbir zaman.

Sensizlik; 

İçimde bir boşluk.

Bir boşluk ki beni boğmakta.

Gittin gideli güzelim,

Nice günler nice aylar dolmakta

Titrer oldu ellerim,susmaz inan yüreğim.

Bilsen, ah bir bilsen seni nasıl özledim

Bak! 

Yine yağmur düştü gözlerime 

Yine arar oldu yüreğim, yüreğinin sesini

İnan kar bile hala,

Umutlarımdan daha kara

Yasakları yasakla da

Artık dön bana!', 'Biliyormusun sensizliğin o korkunç heybetini?  Sen hiç yaşadın mı,benim yerime sensizliği?  Surları yıkılmış kale gibiyim inan Beden varda c...', ARRAY['Türk Edebiyatı','Şiir','Emin Akduman']::text[], 8.5, '{"poet":"Emin Akduman","poet_slug":"emin-akduman","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sensizlik-1276-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Masalları', 'i-stanbul-masallari-kemal-gunduzalp-khb01', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mario Levi’ye

                    “Bu şehr-i Stanbul ki bîmisl-ü behâdur

                    Bir sengine yekpâre Acem mülkü fedadır.”

                                                                              (Nedim) 

I. MASAL

1/Deniz ve Dalga

Deniz ve dalga boylarında yürüdüm:

“Deniz dalgasız olmaz vay gülüm! ” 

Deniz dalgalanırken yağmur çiseliyor

dalga denizi sınıyor kıyılarına çarparak

üç beş martı ürküyor suyun üzerinde.

Denize baktıkça deprem dalgalarıyla tanışıyorum küskün Yalova’da

Nisan’dı ve keskin bir iyot kokusuydu zulmün adı sabahın erkeninde! 

2/Denizin Ortasında

Sis ve duman gözlerinize çarpıyor

kaptanın düşleri bozuluyor ansızın.

Ben ıssız bir adaya yanaşıyorum sanki

adanın gözlerinde sevinçten dalgalar! 

Kendime sakladığım dağlar vardı 

uzak bir yerde, tedirgin ve telaşlı

peki demişler, sonra ne olacak peki

ilkyazda denize yağan yağmur gibi.

Marmara Denizi’nin ortasında bir düşü parçalıyorum yeni ayaklanmalarla

Nisan’dı ve ben zalimce boğduruluyordum sürgüne yollanmış kaptanlara! 

 	

3/Çilenti

Uzun bir geceydi yaşadıklarım tanığı yok

hayatın avuçlarıma bıraktığı acı bir tortu

oldu. Ürkek kuşlardı hep kanadı kırık:

“Çok yıpranmışsın” dedi ayışığının gölgesi

gözlerine yağmur yağmasın yeniden ama

ah, şu çilenti; görünmeyen yağmur taneleri

boğazıma düğümlenen bir hıçkırıktı adın.

Denizin üzerinde yürümek isterdim hep

olanaksızı başarmak gibi bir duygudur bu.

İyi ama, ben bir kara çocuğuyum, bilemem 

gözyaşlarının denize aktığı görülmüş müdür? 

O zaman denizler niye hep tuzludur peki? 

Sen hangi çırpınmasın, bu hangi deniz? 

Ben karıştım günışığına, sen otur ağla...

Bir çilenti kokusuyla karışıyorum ilkyazda bakırdan bir köy/kente

Nisan’dı ve yolunu şaşırmış korkak bir zulümdüm kendi canıma! 

4/Ben ve Deniz

Ben ve İstanbul birbirimize baktık

sabahtı ve gözlerim denize dalmıştı.

Hadi sen de tut gözyaşlarını deniz feneri

sen de ağla Kız Kulesi çay ikindileri

benim hiç Üsküdar’ım olmadı sende.

Ben ve deniz ağlayarak bakıştık Üsküdar’ın yokuşlu sokaklarında

Nisan’dı ve bir zalime dönüşüyordu ikindi vakti ben ağladıkça! ..

5/Gül ve Erguvan

Sonra seni uzak bir yere gönderirler

sen gülü sorarsın, gülün adını değil.

Yüreğinin bir köşesinde kardelenler

gül sormaz mı seni özlemlere düşerek? 

Gül karanfilin üvey kardeşi midir? 

Bir büyüyü bozduk düşlerimizle...

Ah, ne çok erguvandı gözlerinde

gül, bütün çiçeklerin kraliçesidir! 

Ben hep gülü sevdim İstinye sularında gözlerimi yıkadığım gece	

Nisan’dı ve zulmün sarayında tutsak bir kız/çiçekti kırmızı gül! 

6/Ölüme Hazırlık

Artık dağları da fethedebilirim gibi

gözüm arkada kalmayacak İstanbul! 

Bu dünya sizin olsun, yeryüzü de

ben ölmeye hazırım bir kentte! ..

Kirletilmiş bir denizin suyusun

eskitilmiş bir denizin kıyısı, Haliç

içten ve duygusalsın gözlerinle

ben ölmeye hazırım bu kentte! ..

Bir deniz üstelik neyimi alabilir? 

Al götür beni ve köpüklerine sar.

Susuyorum ve ölüyorum sessizce

göz kapaklarımı kapat İstanbul! 

Ben ölmeye hazırım adım adım kapılara düşerken de yorgunluklarda

Nisan’dı ve kılıcı kınında bileylenmiş zalim bir hükümdardı İstanbul! 

7/Kentle Söyleşi

Bildik sözlerle konuşuyorum artık:

Senin ciğerini sökeceğim İstanbul! 

Senin kurtuluşun yok artık benden

sen bittin İstanbul! .. 

                                  Ben geldim işte.

Güzelsin, şirinsin, bir dünya kentisin, 

bütün varlığınla büyüksün, peki kabul

ama senin yüreğin benim elimde, ah

bana âşık bir kent olabilirsin İstanbul...

İşte gece: Yorgunluk uykusunda herkes

güzellik uykularına dalamamış insanlar 

gecedir ve beni düşünüyor yalnız ayışığı

sen yıldızlarını bana mı sakladın İstanbul? 

Sen de mi gözlerimde tüteceksin bir gün? 

Bu sevda bitmez! Alışmamalıyım sana.

Çok bildik sözlerle konuşuyorum, evet

seni de sevmenin eşiğindeyim İstanbul! 

Sen yıpranmış bir fahişe gibi koynumda

beni de diriltiyorsun yeniden sabahlarla! 

Ey benim gençliğim, ey yitirdiğim hayat

ozanca, “bana seni gerek seni” İstanbul! ..

İstanbul’la söyleşmek istiyordum, bıraksalar belki de dinleyecek

Nisan’dı ve yel gibi giden zalim bir kız inceliğindeydi Salacak! 

8/Kentin Gizemi 

Sana her gelişim bir utku gibidir

bütün dönüşlerim kötü bir yenilgi.

Aslında hangi kentte yaşıyorsam

o kenti seviyorum gizliden gizli.

Ama yüreğin şişmandır senin

benim yerim yok sanki orda.

Ben senin beynini dağıtacağım

bu gidişle İstanbul!  Bilesin,

dönüşlerini seviyorum hâlâ.

Ben aslında evim neredeyse

o kenti seviyorum sessizce.

Hadi git, bir yolculuk daha

sonsuz bir uçurum olsun hayat! 

Hadi git ve ardında bırak güzellikleri,

bu camileri, bu kuleleri ve balıkçıları 

eskimiş bir yalnızlıktır belki de yaşam.

Çayını iç, Salacak’ta bir konak düşle

ama gökyüzünü delen kuleleri unutma:

Belki de oralarda bir yerdedir umut

dün bir sevinci yaşadınız akşamüstü.

Benim bir İstanbul’um yok, Nisan yağmurlarına dönüştü zulmün! ..

Eskimiş bir umuttur, eski bir ağıttır

kim ne yapsın ağıtları şairlerden başka? 

Göz göze gelmeyen kahkahalar vardı

ötekilerse aşktı galiba, benim yeni rüyam! 

Akşam oluyor, İstanbul gizemli kadın

ben henüz vapur seslerine alışamadım

bir kediyi seviyorum, yorulmuş ellerim

işin kolayına kaçıyor hayat! Kız Kulesi,

beni anladın çocuk, sen yetersin belki de.

Hiç böylesine yakından görmemiştim 

uzun bir tankerin geçişini/kahverengi

sahi martılar nereye uçar akşamüstü, 

ya üzgün sokak kedileri Üsküdar’ın? 

Bir iskelede gülü sakladılar, gördüm

naylon çiçeklerle öptü kuşlar sevgililerini.

Ben de bu gemileri sevecek miyim acaba

kara çocuğu yüreğimle? Söyle İstanbul! 

Seni sevmek zorunda mıyım İstanbul gizeminle tuz ve nemdin

Nisan’dı ve bir hayata zulmediliyordu Üsküdar’ın gözlerinde! 

9/Denizi Sevmek

                                (a)    ada’ya sığındım! 

Bir geminin güvertesinde yalnız bir kadın

ve şaşkın bir kara adamı: O ben miydim? 

Biz neyiz ki zaten denizin orta yerinde? 

Şimdi bu gemi, bu dümdüz denizde nedir

fırtınaya tutulmuş bir aşk kırıntısı gibi! 

Sizin batmış ve eski Titaniğiniz yok mu? 

Bizim yüreklerimiz de vardı, severdik

benim ellerim soğuk ve çizgiliydi hep

onun parmakları uzun ve saçlarını tarardı. 

Sanki yüzüme baktı ve hiç gülümsemedi

ben bir gemiyi terk ettim sessizce kaptan

kendimi denize atarak: Boğuluyordum! 

“Can yelekleri tavandadır” demişlerdi 

oysa gemilerde:“Sigara içmek yasaktır.”

Bir sigarayı basarak söndürdü o kadın

bacaklarını kaşıdı incecik elleriyle

yüzü kördüğüm, alfabesiz bir dildi

bir rüyası bile olmuyor böyle kadınların! 

Dün bir sevinci yaşadık coşkuyla

bir gökdelenin terasında sevinçliydik.

Bir yeni geleceği konuştuk gençlerle

ben yaşlandım, amcayım şimdi

siz yüreğinizi ödünç verir misiniz? 

Biraz yoruldum da... bu döngü

self servis bir bankacılık hizmetidir

kendimi öpmeliyim doyasıya! 

Şişli’yi şişleyerek usulca karışıyorum kalabalığa ve ada’ya sığınıyorum 

Nisan’dı ve denizi sevmek için zalim bir ay gölgesi düştü günün ışığına! 

                                (b)    başaklar yeşeremedi! 

Başak solar, yağmur susar küserek

gözlerim yorgun düşer bir kente bakınca! 

Bir kenti eskitemeyeceğim artık çünkü 

ben geçmişin yenilgiler toplamıyım

paketlerinize sığdıramadığınız yani

bir kenti bitiremeyeceğim tek başıma.

Bir armağan olabilmektir asıl olan

ama siz kapattınız pencerelerinizi.

Ben bir ışık yumağıydım hani

kendimi aydınlattım mı peki? 

Rüya dönüşecek mi kendi gerçeğine

ey ayışığının eski düş yorumcusu? 

Bir denizin ortasındayım geceyarısı

bir yolcuyum garip dönüşsüzlüklerde.

Kendime kıyıyorum denizlerinizde

işte sonbahar kokusu uzaklarımda

ben denizleri de sever oldum galiba! 

Dönüyorum, kendime derman arıyorum karanlığınızla buğday başaklarında

Nisan’dı hâlâ ay ve nedense zalimdi denizin bakışı Yalova’nın kıyılarında! ..

A   r   a      N   a   ğ   m   e

Ne Bursa’yı gördüm ipek ve şal arasında

ne de Susurluk aydınlandı yol kazalarımda.

Ey ayağa kalkamayan küskün ülkenin sesi

biz ozanlarımızla kuşatıyoruz İstanbul’u! ..

Dalga kıranlar, kör deniz fenerleri, yakamozlar

sahi Manisa hangi şehzadenin kanlı zulmüdür ve

Börklüce ile Kemal’e ne oldu Aydın ellerinde? 

İzmir’e solgun bir çiçek gibi düşmeliyim imbatla! 

İstanbul eski bir masal mıydı, yoksa yine ben mi

kör kütük sarhoş olamadım Çamlıca Tepesi’nde? 

Ah, kalbime de yasak bir hançer soktular arada

gül yoktu, ebru ve dağladım kendimi nakkaş gibi! 

Ara©

Bir sabah ansızın bir türküyle başlayabilir

uzak şarkıları mırıldanırım dar kuytularda.

Ben bu denizi gençliğimde de yarmıştım

Tophane rıhtımında şaşkın bir çocuk gibi! 

Gönlüm Erdekli bir aşkın eteklerine değmişti

Puşkin yüzbaşıydı bir zaman ben de üvey oğlu.

İda’dan gelme sarışın bir top ışın ok gibi değdi

arındın ey yüreğim, o Çanakkaleli Mehmet’ti! 

İstanbul bir masaldı ve ben fena çarpılmıştım

kalbim hep vuruldu zaten göz değmeleriyle! ..

Trenlere bindim, bir gemi tayfası, kaçmıştım

hangi saati geri çevirebilirim ara nağmeleriyle? 

II. MASAL

                 (Şairler yalan söyleyebilir) 

1/Türkü

“Dağlar maralı” adlı türkü düşüyor aklıma sabahın köründe

oysa biz bir denizi yürüyeceğiz yalınayak sulara değmeden.

Denizle güneşin buluşma ânını da gördüm yılların sonunda

su yeşilmiş, güneşse kızıl uyunmamış uykuların kederinde.

Aylardan Temmuz’du...

2/Rüya

Bir rüyayı bitirirsiniz geç kalmış uykularda

köprülerin ayaklarına takılır uyanmalarınız.

Cebimde bildik adreslerle yürüyorum işte

şu İstanbul yüzüme gülmeyecek mi acaba? 

Aslında renksiz bir ömrü nakışlıyorum belki 

sizin de yitik düşleriniz olmadı mı bir kenarda? 

Aylardan Temmuz’du

ve gökyüzü ağlıyordu yine...

3/Arayış

Hadi dağları sevmiştiniz diyelim, peki

bu kentler ne olacak kalabalığınızda,

bu evler darmadağınık, bu çarşılar açık

her şey bir rüya gibi güzelleşir mi yoksa? 

Ben sarı bir harfi düşünüyorum, gizemli

örneğin “denizin ortasında ne var”ın N’si

tam da ben: Gecikmiş kuşluk uykusu! ..

ayrıntı’dır bir şövalyenin gizli başkaldırısı.

Bir soru imiyle donuyor dışardaki her şey:

Kaleler, surlar, kervansaraylar, köprüler.

Ara hadi adresleri, Piyer Loti Caddesi’ni

Çemberlitaş’ta, sonra kendini sokaklarda

kırgın ve yıkılmış düşleri Çatalçeşme’de

bulamadığın ve kaçırdığın ne varsa geride; 

kent insanlarının yorgun yüzlerini, kuşları

Hasan Öztoprak’ı, Enver Ercan’ı, dergileri.

Denizin sessizliğini izlerken, ah bu sesler

bölünür bir şiirin dolu dizgin koşturması.

Aylardan Temmuz’du

ve dağınık bir yaraydı yüreğim

çivilerle delik deşik edilmiş duvar diyerek...

4/Eskimeyen

Her şeyim sende, nasıl dönmem o uçuruma

çeyrek yüzyıllık en eski rüyamsın benim

eskitirken yenilenen dağ masalı da sendin

yorulurken ellerindi güzel olan alnımda.

Sonlanmış öykülerin nakış ustasıyım ben

sen dinmeyen sızım, baş ağrım, yürek acım.

Sen son çeyrek yüzyıllık rüyamsın benim

bütün gelgitlerim hiç eskimeyen sendedir.

Aylardan Temmuz’du

ve ben hâlâ bir bomba gibiydim

Taksim’in ortasında patlamaya hazır

o çocuklar olmasa, o solgun bakışlı kızlar...

5/Yontu

Senin kızgınlığında ıssızlaşır bazı anlar

durup dururken gitmelerinle uzaklara... 

Belki sen de bir rüyayı eskittin benimle

düşlersiz düşlerle bıraktın beni çok yorgun.

El değmemiş düşlerin vardı ıslak, kederli

belki güldüğün de görülmemiştir koynumda.

Hadi bana gün görmemiş yeni düşlerini aktar

vakt erişti, kayda geçirilsin hayatın ayrıntısı! 

Zamanın sarkacısın uzun sürmüş suskunluklarda

paylaştığım bütün sevgiler büyülü teninin kokusu,

ey güzellik! Çeyrek yüzyılın dimdik duran yontusu

ben ki, hep bir mermeri sevsem de diri varlığınla

yağmur olup yağdın, dağ rüzgârı estin yüreğinle...

Aylardan Temmuz’du

ve geceler uzun bir rüyaydı

bir paraşütün gölgesinde uçaklar

kalbimin ortasından geçiyordu dimdik

bölünmüş bir yürek oluyordum çatal matal...

6/Mahzen

Akşam vakti kitli bir kapıya dönüyor yüzleri

Laleli’den bir kız geçermiş eskiden şiirlerle

benim bir İstanbul’um olmadı daha, kentsizim

Laleli’den geçmeyecek bir kızı da aramıyorum,

ancak bir yeraltı çarşısı olabilirim Aksaray’da

derinliklerini gizleyemeyen karanlık bir mahzen

kullanılmamış sözcükler toplamıyım kentinizde! 

Aylardan Temmuz’du

ve duvarlar kırmızı tuğla	

ben yıktıkça onarılıyordu en baştan

geceleyin bir yerlerim çalınıyordu gizlice

kendimi nereye çarpsam ellerim kanıyordu iz iz

kimdi peşimden sürüklenmeyen, kendi gölgem mi? 

7/Ozanlar

Turgay Fişekçi, Enver Ercan, Adnan Özer

üç kısa günde üç ozanı gezdim de geldim! 

Ben olsam gözlerimle gülerdim toprağınıza

ben olsam “yaşasın edebiyat! ” derdim yine

denizi bile olmayan bir adamın bakışlarına

ben olsam aşk derdim, dostluk, dayanışma...

Ah, Ahmet Erhan ah, seni de görmeliydim

Ankara’dan Silivri’ye düşen solgun yaprak:

“Artık bir nihilistim! ..” diye başkaldırırken

oysa hep bir hiç’ti kendini yorumlarken de! 

Bir deniz kasabasını şenlendirmek mümkün

haydi; “Türkiye, ayağa kalk! ”/Susulmuştur! 

Aylardan Temmuz’du

ve sıcaktan bunalıyordu ayışığı

sense günışığına sığınıyordun

bir ozanın yitik düşlerini yorumluyordun

bu İstanbul İstanbul olalı kaç köprü geçildi

Mimar Sinan’nın sakalını sıvadım kesme taşlarla

Konstantiniye polis beni yakalayacak geçilmiş köprülerden...

8/Ölümler

Bir sokak köpeği havlayıp duruyor bütün gece

Fatih Camii’ne bir bebek bırakılmamıştı oysa! 

Çocukların çığlığı konuştu denizin bittiği yerde

sen gözlerini kapattığın zaman, “ört ki, ölem”di! 

Adnan Yücel de bırakıp gitmiş Adana’yı öfkelerle

bir kent nasıl eskir başka türlü? Elazığ ağlasın da

kendi ozanını kucaklasın toprakla buluştururken! 

Bir kenti ardında bırakıp gitmiş Adnan Yücel de

hangi ozan ölümsüzlüğü yakalar giderayak sence? 

Daha dündü, dinmemişti Ece Ayhan’ın zindan acısı

sen niye ölüverdin ki, çarçabuk Adnan? Ben olsam:

“Bu ülke insanı kanser yapar, öldürür bu halk bizi”

derdim belki de, sen benim akranımdın, böyle acele

ölünür mü, nereye koşturup duruyorsun erkenden? 

Beni de bu acılar öldürecek yakında, bu sessizlik

bu şair ölümleri sanki inadına yaz günü Temmuz’da! 

Kendi cenazemi görüyorum kırık bir tahta tabutta

ben zaten yontulmamış bir düşkırıklığı gibiyim hep

uzaktan düştüm kentinize bir sabah hiç uyandırmayın! 

Aylardan Temmuz’du

ve ozanlar ölüyordu peş peşe

bense ağıt yakmaya zorunlu

kaç yıllık şivandan kalma eski çocuk

dayanır mı yürek bu bozgunlara uğramış

surları dökülmüş kalelerle, bir Trakyahisarı

yapmalıyım dizlerimin dermanı çözülmeden daha

bendim Mezopotamya’dan kalbinize ağamayan o ak bulut...

9/Taş Beden

Sen çıkaramadın beni baştan zalim/çıplak türkülerle

hangi kentin yolları taş döşeli damperli kamyonlarla? 

Biz dikenle savrulmuşuz dört bir yana, masallarla ah

bütün kentleriniz taşra, bütün kasabalarınız sığınaktı

siz de bir anakentin kitlenmiş kapalı çarşıları oldunuz! 

Kandırılmış bir kedi bakışıdır gözlerin, gözlük takma

sevecen ve vahşi kal! El değmedik yerlerimiz mi kaldı? 

Hadi konuş! Sor: Ben nerenin artakalmış yolcusuyum? 

Az kullanılmış bir mermer gömüt taşı koy başucuma

ölümüne yatacağım dizlerine, taştan da olsa bedenin! 

Aylardan Temmuz’du

ve ben yine o ağlamaklı yüz

sulugöz bir çocuktum sokaklarda

at arabalarına koşulmuş yılkı atı gibi

bir Çingene’nin gözbebeğini oydular durmadan

ben öldüm adımı bilemedi kimseler dağlara yazmak için.

Hangi kör çocuğun gözlükleri numarasızdır biletler orada

bana yerimi gösterecek bir el feneri tutuldu sorgularda sinema

ben bu senaryoyu oynamam arkadaş, çöpleyin kamyonlarla hadi! ..

10/Sessiz Irmak

Ben kaç bin yılın toprağıyım gözlerinizin morunda

kapalı kapılarınız, eskimiş paslı kilitleri, taş yürek! 

Kimdi anakentlerde yalnızlığı mendillerle ağırlayan

hanginiz hiç gülmeyen bir taşrayı özlüyor, şaşarım:

Ah, hadi değiştirelim ayaklarımızı, siz çarık giyin de

ben iskarpin, yürüyelim eskimemiş yolculuklarımızı

kim nerede yürümek isterse artık; dağ, bayır, yayla

ben kıyısında olacağım koca kentinizin: Bir gemide! 

Grileşti gökyüzü, parçalı bulutlu, duman duman

ve yakamozlaştı deniz, dalga sessizliğinde ayışığı

gökdelik uzak yağmurlarla sel almış Güneysu’yu

ve çay kokusu Rize’nin, demlenmiş fırtınalarda.

Ey kalbim, sakın ha bu ıssızlıkta ölmeyi deneme 

hatta sakin bir yolculuğun sonunda bile yaşa! ..

Durulmuş yaşlı bir beden gibi çırpınmadan

kendi yatağında sessiz akan bir ırmak ol artık! 

Aylardan hâlâ Temmuz’du.

11/Zümrüt Rüya

Çamurlu bir gözyaşı tarlasıyım işte, tufan artığı

solgun çiçeklerin tuzlu köklerinde yanmış ağzı.

Ben eski bir rüyanın parçalarıydım yokluğunda

unutulmuş: Anımsa beni, topla kopmuş belleğimi

birleşik bir düş olayım gökyüzüne yıldız yağmuru! 

Ah, her şey ne kadar yalın ve uzak, benimki Anka 

bu gördüğüm son zümrüt rüya olacak biliyorum! ..

Ay						

      Temmuz.

S   o   n       N   a   ğ   m   e   l   e   r

Yıldız kayacak, taş yağacak, ömrümün fırtınası dinmiyor gecelerdir

beni ışıksız ve ıssız bir tepede unutmalısın belleksiz ve yüreksiz.

Haydi birlikte yürüyelim hangi kenti istersen sen yine yalnız yolcu

bense suyu kurumuş o eski sarnıç, yosun tutmuş duvarlarım.

Yağmur yağmalı, gözyaşım akmalı kör kuyulara, yağmur yağmalı

ben bir şiir ırmağının son yatak değiştirmesiyim bulanık sellerle.

Bu meltem de esmeyecek, yangınlar kor, ormanım kuru gazelden

hangi sokak itfaiyesi söndürecek erkenci ölümlerle bu harlı ateşi? 

Som altından bir yatakta zülüflerini yolarak ağlar mı şimdi de 

binbirgecenin o sevdalı masal kızları gözlerini kanatarak usulca? 

Sabah olmasın diye! “Evet sabâh olacaktır, sabâh olur, geceler.” 

Tevfik Fikret mi bu? Beni bir Aşiyan’a gömün toprak ve taşla...

Gözlerimi geri verin, ağlamamış haliyle ama, yitirdiğim her şeyi 

kızgın kazanlarda kanımı yıkadılar benim, soyulmuş soğandım! 

Bir cesedin küllerini savurdular havaya, denize attılar bedenimi

yüzme bilseydim, ölmeden yaşamak isterdim İstanbul masalını...

Artık bir köprünün ayaklarında ayak izlerim kim betonladı öyle

Mimar Sinan’ın gözlerinden kaçırılmış hem de heykeli önünde! 

“Nisan ayların en zalimi” mi demişti dalgınlıkla o İngiliz ozan? 

“Bekle Bizi İstanbul” demişti usta! Bir masal mıydı İstanbul o an? 

Aylardan gümüş rengi bir Zümrüt-ü Anka kuşu kanat açması yeniden! 

Ah, Nisan zulümdü gönlümde bahar açması ve Temmuz kurumasıydı gözlerimin dere yatağı: 

“İstanbul Bir Masaldı” Sevgili Mario Levi

Nedim! 

              Nedim! ..

                               Yalancı Nedim...

                                                             (Şairler yalan söyleyebilir) 

                                                                        (Yalova, 20-27 Nisan 2002

                                                                          İstanbul, 24-25 Temmuz 2002

                                                                         Aydın, 11-12 Ağustos 2002)', 'Mario Levi’ye                     “Bu şehr-i Stanbul ki bîmisl-ü behâdur                     Bir sengine yekpâre Acem mülkü fedadır.”       ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Gündüzalp']::text[], 8.5, '{"poet":"Kemal Gündüzalp","poet_slug":"kemal-gunduzalp","theme":"Türk Şiiri","is_hero":false,"total_lines":428,"source_url":"https://www.antoloji.com/istanbul-masallari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerini ve sonra yüzünü', 'ellerini-ve-sonra-yuzunu-akin-akca-zesws', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Evet onu sarardık, bu burguyu

Ve sonra karardık, sarardık, saramaz olduk.

Saramayan mıdır sararan, sorduk.

Böyle imla düzenleme, kendine ayrık.

İşlek, hala sarıyor karartıda manivela,

Bu mu, sararandaki sarıveren muamma? 

Bir karmaşa, evlere şenlik; 

Gülen yüzlere ağacın yeşilinde geldi

Sıvı suyun renksiz hali, denklik.

İyi ki su aktı musluktan,

Ellerini yıka

Ve yüzünü bolca.

09.04.''05 05:03

akın akça', 'Evet onu sarardık, bu burguyu Ve sonra karardık, sarardık, saramaz olduk. Saramayan mıdır sararan, sorduk. Böyle imla düzenleme, kendine ayr...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ellerini-ve-sonra-yuzunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorgulama', 'sorgulama-necmi-unsal-zxk0y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göğün ağlaması onmaz ayrılıklara mı? 

Yağmur taneleri neden kaybolur sellerde? 

Nura küs yarasa, övgü karanlıklara mı? 

Niçin kan kokusu arar vampirler yellerde? 

Bu gök gürültüsü değil gurbet mi kükrüyor? 

Yoksa sevdaya mı bu gök gürültülü azar? 

Çöken kara bulut aşka hüzün mü yüklüyor? 

Hasret, vuslatlara yoksa hep mezar mı kazar? 

2 Mayıs 2004 Pazar, Danimarka-Køge 23.09

2+4+2+6', 'Göğün ağlaması onmaz ayrılıklara mı?  Yağmur taneleri neden kaybolur sellerde?  Nura küs yarasa, övgü karanlıklara mı?  Niçin kan kokusu ara...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sorgulama-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nezle', 'nezle-goksel-dogru-xaxmh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(M''ilad''a...) 

O kadar da söyledim 

Git başkasını bul dedim

İstemem senden gayrısını

Dedi sensin benim aradığım, 

Nezle diyorum nezle 

Zamanı mıydı gelmenin

Bir randevu öncesinde 

Beni süründürmenin

Gelmiş geçmiş olsun diyen yok

Nane limon ıhlamur diyen de

Üç gün sonra gelsen ölür müydün? 

Zaten sallanıyorum durduğum yerde 

Git yahu git, hadi nolur 

İki gün sonra bekliyorum seni 

Aynı saatte ayrıldıgımız yerde 

Sonra istersen hasta et beni

(Kasım 2002, İzmir)', '(M''ilad''a...)  O kadar da söyledim  Git başkasını bul dedim İstemem senden gayrısını Dedi sensin benim aradığım,  Nezle diyorum nezle  Zaman...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/nezle-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyümek', 'buyumek-goksel-dogru-8798t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(Memleketime...) 

Beni hasretler büyüttü 

Onlar olmasaydı 

Çocuktum belki hala 

Çocuktum ağlayanların 

ve ağlatan yolculukların

Yokluğunda', '(Memleketime...)  Beni hasretler büyüttü  Onlar olmasaydı  Çocuktum belki hala  Çocuktum ağlayanların  ve ağlatan yolculukların Yokluğunda...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/buyumek-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse Bulunmaz', 'kimse-bulunmaz-osman-i-nci-depi3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen nadide bir gül, bitmez baharsın,

Bırak bütün çiçekler, seni kıskansın,

Kış’ta güneşimsin, yaz’da kar’ımsın,

Yerini dolduracak, kimse bulunmaz…

Varlığın umut, yokluğun çiledir bana,

Hiçbir kelime, aşkımı anlatmaz sana,

Bir anlık ayrılsan, ararım yana yana,

Yerini dolduracak, kimse bulunmaz…

Seninle hayat buluyor, aşkın anlamı,

Bakışların döndürür, küçük dünyamı,

Her zaman haykırırım, büyük sevdamı,

Yerini dolduracak, kimse bulunmaz…

Bütün karanlıkları, aydınlatır bakışın,

Yüreğime işlenmiş, o sevda nakışın,

Vücudumu ısıtıyor, damarımda akışın,

Yerini dolduracak, kimse bulunmaz…', 'Sen nadide bir gül, bitmez baharsın, Bırak bütün çiçekler, seni kıskansın, Kış’ta güneşimsin, yaz’da kar’ımsın, Yerini dolduracak, kimse bul...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kimse-bulunmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Dilek', 'son-dilek-i-smet-barlioglu-bbm52', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim, kulaklarındaki çınlama,

Benim, hançerendeki hıçkırık,

Güzel gözlerini bürüyen sis,

Yanaklarına süzülen yaşlar benim.

Benim, açık pencerendeki tülleri şişiren rüzgar,

Seni hüzünlere salan sonbahar,

Lapa lapa karlar çam dallarında,

Benim, bıraktığın izler karlarda,

Yanından ayrılmıyorum ki; başkasıdır diyesin,

Düşün ki; 

Bilesin.

Bir sana tutulmuşum senler içinde,

Canım candır ki veriyor canlar içinde,

Elişiden bir pervane gibiyim rüzgar altında,

Ne vakarım kalmış,

Ne de kararım.

Ellerim demir zincirlere perçinlenmiş

Ve paslı güllelere

Ayaklarım.

Biliyor musun sevdanın sevenlere neler yaptığını,

Ayrılığın insanı nerelere fırlattığını? 

Düşün ki; miller çekmişler gözlerime

Ayak basılmamış zindanlar içinde,

Tutup çarmıhlara germişler bedenimi,

Son dileğim olarak kendilerinden isteyeceğimi

Bilememişler,

Seni.

(TANRI ÖNCE BENİ YARATTI isimli Serbest Şiirler ''inden > 95-96/100)', 'Benim, kulaklarındaki çınlama, Benim, hançerendeki hıçkırık, Güzel gözlerini bürüyen sis, Yanaklarına süzülen yaşlar benim. Benim, açık penc...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/son-dilek-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabuklar', 'kabuklar-i-smet-barlioglu-y02iu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine sisler bastı yemyeşil dağları,

Yine sisler içinden çıkı çıkıveriyor kuşlar,

Yine çimen ıslak, çiçek ıslak,

Yine üst üste atlamakta terliklerim,

Yine bardağımda yüzmekte çay yaprakları.

İşte tüm alametler yerli yerinde; 

Belli ki sen geleceksin,

Gönlüm ayağa kalkmış seni bekliyor,

Neredesin? 

İster misin, parmağın zilinde olsun kapımın,

İster misin, yüzün görünsün penceremde,

Betin-bereketin dolsun evime,

Şavkın vursun güneş gibi,

İster misin, şükürler için kalkıp göğe açılsın elim

Ve ister misin bir anda

Sevinelim? 

Sanırım, uzun uzun dikili kalacak gözlerin gözlerime,

Belki de kamaşıp duracak gözlerim,

Dikilmek ne kelime.

Kamaşacak tıpkı bir çöl güneşinde kamaşır gibi,

Dolaşacak elim-ayağım birbirine

Ve ben biat eder gibi kapanacağım

Yere.

Ah bu hayallerim, bu tatlı hayallerim,

Korkarım ölümüm bunlar elinden olacak; 

Yatıyorum, çevremdeler,

Kalkıyorum, çevremdeler,

İçlerinde hep seb varsın, çiçeğin içindeki öz gibi,

Bir kabuğun içindeki çekirdek misali,

İç tatlı, kabuklar sert,

Seni bulmak için ne kabuklara saldırdım nice zaman,

Kabuklar namert.

(TANRI ÖNCE BENİ YARATTI isimli Serbest Şiirler ''inden > 97-98/100)', 'Yine sisler bastı yemyeşil dağları, Yine sisler içinden çıkı çıkıveriyor kuşlar, Yine çimen ıslak, çiçek ıslak, Yine üst üste atlamakta terl...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kabuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Fenerleri', 'deniz-fenerleri-i-smet-barlioglu-qvzor', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gel artık,

Yaşantım olmazlandı,

Uzatmaları oynuyorum soluk soluğa,

Akşamlarım hızlandı, sabahlarım doludizgin,

Enginler sabrım kadar bile değil engin,

Bir yazıdır işte, yazıyorum kumlar üstüne,

Ellerimle rüzgarları avuçluyorum,

Ne kumda kalıyor yazdıklarım,

Ne avuçlarımda rüzgar,

Seni ne kadar çok bekledim,

Ne kadar.

Bana bir gençliğin kalmış, gözbebeklerimde,

Sanki bir Doryan Grey portresi,

Aradaki tek fark; resmin sesi,

Biz yaşlanıp gidiyoruz, o yaşlanmıyor,

Ben çilelere dayanamadım, bittim,

O dayanıyor.

Kanatların yok mu, seni bana getirecek

Veya Zümrüdü Anka türünden

Bir kuş, bir böcek? 

Yok mu sıcak denizlere açacak yelkenin,

Küreklerin yok mu sulara dayanacak? 

Kayalıklara deniz fenerleri diktim senin için,

Yanacak.

(TANRI ÖNCE BENİ YARATTI isimli Serbest Şiirler ''inden > 99-100/100)', 'Gel artık, Yaşantım olmazlandı, Uzatmaları oynuyorum soluk soluğa, Akşamlarım hızlandı, sabahlarım doludizgin, Enginler sabrım kadar bile de...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/deniz-fenerleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercin', 'guvercin-i-smet-barlioglu-lywpn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boyanmamalı kızıla bu gurub, seni anınca,

Yıkanmamalı güneş bu kızıl sularda,

Akşam inmemeli bir tül gibi denize göklerden,

Kanamamalı yüreğimdeki yara, atan nabızlarca,

Yorgun beden nasıl dayansın böylesi hüzünlere

Yıllarca? 

Kanıyor yüreğim inen akşamlarla akşamlar boyu,

Küllenen ateşim yeniden başlıyor alazlanmaya,

Çilelerim çoğalmaya,

Üzüntülerim artmaya,

Gençliğimi tüketen bu karasevdada

Sen atlı oldun,

Ben yaya.

Ne sen duran bir menzil oldun, ne ben yolu bitirebildim,

Yıllarca yürüdüm, süründüm, öldüm,

Ne bir hana uğradı yollarım, ne bir ocağa,

Yol uzun, ben bitkin, yürek yaralı,

Yalçın kayalıklarda bir kekliktir arıyorum; 

Kınalı.

Sanki haramiler kesmiş yollarımı, uğrular tutmuş,

Kuyularımı kurutan çöllerde iyi kurutmuş,

Süs için mi bağrım ateşlerde,

Süs için mi yüreğim alevlerde? 

Belli ki; insaf namına hiçbir şey yokmuş

Kaderde.

Kızıla boyanmış tablolarda ibretlik öge olup kaldım,

Kızıllarım kan rengi kızıllar; öylesine koyu,

Saplanmış hançer gibi canevime karasevda,

Bir elkızıdır sayıklar dururum,

Canımı bir haberci güvercin etmişim yoluna

Uçururum.

(GÜVERCİN isimli Serbest Şiirler ''inden > 7-8/100)', 'Boyanmamalı kızıla bu gurub, seni anınca, Yıkanmamalı güneş bu kızıl sularda, Akşam inmemeli bir tül gibi denize göklerden, Kanamamalı yüreğ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/guvercin-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Telaffuz Çobanı', 'telaffuz-cobani-selcuk-sahin-gkwg6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzadı ceketim,

bacaklarım,başım...

Caddeden geçerken

önüm sıra uzadı bedenim...

Loş,hoş karanlık

savrulurken yanımda,

gölgem bırakıp beni

uzadı yol boyunca...

Bir telaffuz çobanı kelimeleri

güdüyordu uzaktaki ingilizce dersinde,

yanındaki binadan

bana küfrediyordu balkonlar,

Uzadım hemen ordan..

Kısık bir ses gibiydim sokakta..

24/10/2000 Kadıköy', 'Uzadı ceketim, bacaklarım,başım... Caddeden geçerken önüm sıra uzadı bedenim... Loş,hoş karanlık savrulurken yanımda, gölgem bırakıp beni uz...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Şahin']::text[], 8.5, '{"poet":"Selçuk Şahin","poet_slug":"selcuk-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/telaffuz-cobani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parmakların Her Dokunduğunda', 'parmaklarin-her-dokundugunda-ziya-nizam-ingd6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Parmakların her dokunduğunda

Sana aşık olan kalem olmak isterim.

Gece her olduğunda

Senin için mehtap olmak isterim.

Her yolculuğunda

Farkında olmadan yanından geçtiğin

Kurumaya yüz tutmuş ağaç olmak isterim.

Sevmiyorum derken bile

Sevdiğini bilmek tek sevincim.

Hadi şimdi bana doya doya git de! 

                    09.04.2005-Cumartesi

                    02:01 Avcılar-İstanbul', 'Parmakların her dokunduğunda Sana aşık olan kalem olmak isterim. Gece her olduğunda Senin için mehtap olmak isterim. Her yolculuğunda Farkın...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/parmaklarin-her-dokundugunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen şimdi', 'sen-simdi-ziya-nizam-zceyx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen şimdi 

Dalgalarını alıp gideceksin yine

Ve ben

Kalbi kırık boynu bükük kalacağım

Belediyenin süpürmeyi unuttuğu

Tozlu yolda.

Arkana baksan göreceksin

Kalbimin yarısı kalmış ayaklar altında.

Diğer yarısı,

Sen nereye gidersen zaten orada.

			10.02.2005-Perşembe

			00:02 Avcılar', 'Sen şimdi  Dalgalarını alıp gideceksin yine Ve ben Kalbi kırık boynu bükük kalacağım Belediyenin süpürmeyi unuttuğu Tozlu yolda. Arkana baks...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-simdi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma Demedinki', 'unutma-demedinki-denizhan-solmaz-6p6vm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne adın kaldı nede şanın

bittin bende 

gözün aydın...

ne hoş bir hatıra nede bir anın

sen bana hiç unutma demedinki', 'Ne adın kaldı nede şanın bittin bende  gözün aydın... ne hoş bir hatıra nede bir anın sen bana hiç unutma demedinki...', ARRAY['Türk Edebiyatı','Şiir','Denizhan Solmaz']::text[], 8.5, '{"poet":"Denizhan Solmaz","poet_slug":"denizhan-solmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/unutma-demedinki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-meryem-i-sler-oew26', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle yüce bir tarihtir ki

Dillere destan olmuş

Gönüllere taht kurmuş

Dünyanın gözlerine mest olmuş

İstanbul eşin benzerin yokmuş

Allah Alah dedi fatih ve askerleri

 Edirnede döktürdü topları mermileri

Tophanaden kasım paşaya kızaklar yerleştirdi

Geceyi gündüzgibi yetmiş iki parça gemiyi

Dolma bahçeden haliçe  indirdi

Elli üçgün bıkmadan usanmadan savaş sürdü

Oklarla tüfeklerle kazmalarla düşmanın üzerine yüründü

ikibine yakın askerin çoğu şehit düştü

29 mayıs 1453 de islanbul ele geçti

Yedi tepenin her birine bayrağımız dikildi

Bey oğlunun üzerine dökülür yıldızlar

Çamlıca her nefeste ciğerlerimizi açar

Taksim meydanında yaşanır çoşkular

Kızkulesi boğazın koynunda yatar

Dünyanın kalbi istanbulda atar', 'Öyle yüce bir tarihtir ki Dillere destan olmuş Gönüllere taht kurmuş Dünyanın gözlerine mest olmuş İstanbul eşin benzerin yokmuş Allah Alah ...', ARRAY['Türk Edebiyatı','Şiir','Meryem İşler']::text[], 8.5, '{"poet":"Meryem İşler","poet_slug":"meryem-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/istanbul-172-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli hazine', 'gizli-hazine-ali-riza-unal-9t7tg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tanrı hazinesi sır oldu, bir hoş söz ile dile.

Sanmaki o cevheri, içi boş, sureti insan bile.

Aşığa dür’ü ledün devlettir,idraka kuş dili gerek.

Meğer Süleymana aşinayı arif, siret’i insan bile.

Muradı ilâhi, kulda zatını, öz ile cem eylemiş.

Kamil olan sükûtu burda, hal ile dem eylemiş.

Maşuk münezzeh aşktanda öte. Lütûf gerek.

Hilkate marifet ihsandır er’e.bilen gayrı gem eylemiş.', 'Tanrı hazinesi sır oldu, bir hoş söz ile dile. Sanmaki o cevheri, içi boş, sureti insan bile. Aşığa dür’ü ledün devlettir,idraka kuş dili ge...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gizli-hazine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimle Evlenir Misin?', 'benimle-evlenir-misin-umut-ulbegi-hv48z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni al

Ellerim ellerin olsun

Ne gördüm ki sensiz

İsmim senin olsun

Mucizen benim

Liseli aşıklardanız

En derinlerimiz terliyor sevişirken

Erken değiliz

Vaktinde yaktık ışıkları

Lekesiz

Engin deniz

Naza çekiyor

İstanbul yanıyor aşkımızdan

Rüzgar ağlıyor

Mart parisi başkaymış

İki aşıklık rezervasyon

Sabahtan akşama sevdalı

İz bırakıyor gözlerimde

Nur ve ay birleşiyor', 'Beni al Ellerim ellerin olsun Ne gördüm ki sensiz İsmim senin olsun Mucizen benim Liseli aşıklardanız En derinlerimiz terliyor sevişirken Er...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/benimle-evlenir-misin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklardayım', 'uzaklardayim-birsen-ates-ki9e9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'g e l i ş i n

g i d i ş i n

bahara denk

kısacık bir an

mavi umut ışıkları

hırçın dalgalı bir deniz

k ı y ı l a r ı n d a y ı m

savrulmuş

lodosa yakalanmış.

gölgem bile soğuk

artık

inanmama izin vermedin

kendine inandın sadece

şimdi

senin sessizliğinde

i z l i y o r u m yaşamı

öylesine

kolay ve zorki

yanına gelmem

neden sen gelmedin 

artık gelme! 

sus! 

konuşma bir tek kelime bile

üşüyorum

güneş ısıtmıyor artık

senden çok uzaklardayım

uzaklarda

sağırdı ruhum

kalabalıklarda', 'g e l i ş i n g i d i ş i n bahara denk kısacık bir an mavi umut ışıkları hırçın dalgalı bir deniz k ı y ı l a r ı n d a y ı m savrulmuş lod...', ARRAY['Türk Edebiyatı','Şiir','Birsen Ateş']::text[], 8.5, '{"poet":"Birsen Ateş","poet_slug":"birsen-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/uzaklardayim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaklar', 'sokaklar-vedat-gungorur-qz0hf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sokaklar çıkmaz,...sokaklar Karanlık.

Soğuk ve zalim....

Düşme sakın..

Mecbur olma sokaklara 

Kendini bil,..aklın seninle olsun

Tanı  sokaklardakileri

İnsanlarını bil.

Ve yürü, yürürken eğilme

Nereye çıkarsa çıksın.. bilmesende

Sonu ne olursa olsun.. yürü 

ama dimdik yürü..

Kurtul sokaklardan 

Düşme,.. mecbur olma sokaklara

Alevini,... ateşini,yarınlarını söndürme

Sokaklarda yarınlar yok..

Yok.mutluluk,.. ışık yok

Zor sokaklar....zorlu..

Sakın ölümü bile dileme

Ölüm zor....yaşamak zor

Sokaklar acılı....soğuk ve zalim...

**************************

Evinden Yuvasından ayrı düşmüş.düşürülmüş..tüm sokaktaklilere..sevgilerimle

vedat GÜNGÖRÜR  ([email protected])', 'Sokaklar çıkmaz,...sokaklar Karanlık. Soğuk ve zalim.... Düşme sakın.. Mecbur olma sokaklara  Kendini bil,..aklın seninle olsun Tanı  sokakl...', ARRAY['Türk Edebiyatı','Şiir','Vedat Güngörür']::text[], 8.5, '{"poet":"Vedat Güngörür","poet_slug":"vedat-gungorur","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sokaklar-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul sen başkasın', 'i-stanbul-sen-baskasin-meryem-i-sler-uhauc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dalgalanır şanlı bayrağım kalesinde

Yol verir dünyanın her yerine

İki kıtayı birleştirdi köprüsüyle

İstanbul benzemez hiç bir şehre

Kucak açar yerlisine yabancısına

Mevlana gıbı çağırır herkesi dost ça

Dünyada görmek istediğin ne varsa

Hepsini yaşarsın istanbulda

İstanbul saraylar şehri

Padişahların ülkesi

Aşk  kokar her bir köşesi

İstanbulda yaşarsın ceneti

Dini dili ayırmaz bu şehir

Kucaklar insanları  bir bir

İstanbul aşktır sevgidir

Ceneti yaşamak istanbulu görmektir

Görmeden ölmek yaşamadım demektir

Eşi benzeri yoktur asla

 Dünyayı dolaşşanda  bulamazsın 

Böyle deniz böyle temiz hava

İstanbulda görürsün cennetten manzara

Doyamazsın yıllarca İstanbulun tadına', 'Dalgalanır şanlı bayrağım kalesinde Yol verir dünyanın her yerine İki kıtayı birleştirdi köprüsüyle İstanbul benzemez hiç bir şehre Kucak aç...', ARRAY['Türk Edebiyatı','Şiir','Meryem İşler']::text[], 8.5, '{"poet":"Meryem İşler","poet_slug":"meryem-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/istanbul-sen-baskasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak Ayıramaz ki!', 'toprak-ayiramaz-ki-zumrut-demirtas-wgby3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kesişti yollarımız,

Örüldü ağlarımız,

Kuruldu bağlarımız,

Kimse koparamaz ki...

Gözlerine bayıldım,

Sözlerine kapıldım,

Sanki baştan yazıldım,

Silen ayıramaz ki...

Gül dalıma konmuşsun,

Aşk bülbülüm olmuşsun,

Güneş gibi doğmuşsun,

Gece ayıramaz ki...

Yolunu gözlemişim,

Delice özlemişim,

Bir kere söz vermişim,

Eller ayıramaz ki...

Sensiz düşer, teklerim,

Derdime dert eklerim,

Koyup gitsen beklerim,

Yollar ayıramaz ki...

Çilelerle yoğrulsam,

Hasretinle kavrulsam,

Yaprak olup savrulsam,

Rüzgar ayıramaz ki...

Zaman seninle dondu,

Dünyam seninle doldu,

Yürek yandı kül oldu,

Kader ayıramaz ki...

Aşkınla dağlanmışım,

Gönülden bağlanmışım,

Ömrümü adamışım,

Ölüm ayıramaz ki...

Ölesiye sevmişim,

Herşeyimi vermişim,

Sana evet demişim,

Hakim ayıramaz ki...

Sensin yaram saranım,

Sensin benim dermanım,

Yazsan ölüm fermanım,

Ecel ayıramaz ki...

Gözümdeki yaşımsın,

Ekmeğimsin aşımsın,

Hayat arkadaşımsın,

Toprak ayıramaz ki...

(Can Yoldaşıma ithaf olunur,

O''nunla yaşadığım her güne şükürler olsun....)

09.04.2005', 'Kesişti yollarımız, Örüldü ağlarımız, Kuruldu bağlarımız, Kimse koparamaz ki... Gözlerine bayıldım, Sözlerine kapıldım, Sanki baştan yazıldı...', ARRAY['Türk Edebiyatı','Şiir','Zümrüt Demirtaş']::text[], 8.5, '{"poet":"Zümrüt Demirtaş","poet_slug":"zumrut-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/toprak-ayiramaz-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diriliş', 'dirilis-umut-ulbegi-pnldr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soğuktu

tutundum dudaklarına 

nefes gibi ısındım

Yanıktı

gözlerine her hücrem

atomlarına ayrılmışken yürek

birleştim

Mis kokun çağırıyor

dokun

dokun

Aşk çağırınca

umut

sökülen yürekleri

yuvasına dönen kuşlar gibi

yeniden dokuyor

Kırıktı

topladım parçalarını hayatın

seni de katınca ölüme

dirildim', 'Soğuktu tutundum dudaklarına  nefes gibi ısındım Yanıktı gözlerine her hücrem atomlarına ayrılmışken yürek birleştim Mis kokun çağırıyor dok...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dirilis-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem I', 'ozlem-i-mustafa-duman-y7gps', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gözkapaklarına geceyi taktın uyudun. bu kadar çok ağlama yüreğimi parçalıyorsun.

biraz toprak karıştı, biraz yorgunluk yandı. kokusundan bayıldık.

düştük teker teker yerlere. yanaklarımızda bir top kırmızı iz. ne yar dudağından kaldı, ne yüzümüzdan damlayan candan.

döküldük yollara yine, birbirimizin arkasından. dönüp bakmadık arkamızdakine.

döküldük bir kuruyemişçinin küreğinden bir kaç leblebi tanesi gibi. ya da ipi kopmuş inci bir gerdanlık gibi, yarin gerdanında duramadık.

yağmur olduysak birikemedik, camlara vurduk, aktık. izimiz varla yok arası. biz kalmadık. cevap olduysak sorumuz okunamadı, doğru soruların altına duramadık. soru olduysak, hep kendimize.

ufuk çizgisine kırılmış bir yumurta oldu güneş. biz bulandık baktıkça.

bir girdap olduk, kendimizde boğulduk. rüzgar olduysak şişirdiğimiz yelkenler bizi geçti gitti.

kırılan, burkulan, incinen.. uyuma, ağlama, kıyamam sana.

yüzünde beyaza anlam katacaktı kar. soğuk değil serin duracaktı. düşüşlerin sert olmayacaktı.

anlamsız bir düğüm oldun boğazımızda. sen düğüm oldun, biz yutkunmadık artık.

deney tüplerinde görülüp sevilen renklerdi gözlerin. bazen karıştı, bazen ayrı ayrı durdu hayatla.

biz seni aldık taşıdık, ceplerimizde, kasketimizde, çantamızda. defterinin içine sakladı bir kız. özenle yazdı seni geceleyin masasında.

biz seni muhallebi kıvamında, dokunmanın, koklamanın, görmenin muhallebi kıvamında doldurduk hayatımıza.

akışın da, açışın da, soluşun da, her türlü geçişin yavaş. ve sürekli.

biz seni çok özledik. hem varken, hem yokken, hem şimdi..

(2004)', 'gözkapaklarına geceyi taktın uyudun. bu kadar çok ağlama yüreğimi parçalıyorsun. biraz toprak karıştı, biraz yorgunluk yandı. kokusundan bay...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Duman']::text[], 8.5, '{"poet":"Mustafa Duman","poet_slug":"mustafa-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ozlem-i-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem II', 'ozlem-ii-mustafa-duman-nwcik', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'geçisinle yollardan hızlıca kalkan kuru yapraklar bu yaz sabahında bile aklıma gelebiliyor.

güneşin beyaz üstünde duruşu kadar parlaktın. hiç bir rengi emmedin hep yansıttın.

bir uçurum kenarında dengesini sağlamaya çalışıyordu sanki ay. itsen gece karanlık, çeksen sen vardın.

kokun 3 yüzyıl hatırlanır senden uzakta. ve geldiğinde yine ilk günki halini alır. üç yüzyıl kandırsam da kendimi.

ben şimdi yine toprağın çatlakları arasındayım. aklımın kırıkları gölgesini düşürüyor dakikalarıma.

umudun, bir dal yeşil değil, kendi başına bir ormandı. sesin başka tüm seslerin zamiri.

uzaktasın. kavanozda bir zeytin tanesinin yalnızlığı bendeki. rengimin önemi yok..

(2004)', 'geçisinle yollardan hızlıca kalkan kuru yapraklar bu yaz sabahında bile aklıma gelebiliyor. güneşin beyaz üstünde duruşu kadar parlaktın. hi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Duman']::text[], 8.5, '{"poet":"Mustafa Duman","poet_slug":"mustafa-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozlem-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Sensiz', 'seninle-sensiz-mustafa-sekerci-myvq2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül sende kaldı geri gelmiyor

Ben benimle bensiz yaşar gibiyim

Ne seninle nede sensiz olmuyor 

Senden kaçıp sana koşar gibiyim

İçimde cehennem saçımda karsın

Var desem yoktasın yoklarda varsın

Ne unuttuğumsun  ne bana yarsın

Muamma içine düşer gibiyim

Yoldaşım sensizlik yarenim tasa

Yokluğunla dünyam büründü yasa

Hele birde şu şiirler olmasa

Yazdıkça sel olup coşar gibiyim

Yaşama sebebim, canım dediğim

Canımı canına üste verdiğim

Geleceksen geç olmasın sevdiğim

Kendi mezarımı eşer gibiyim', 'Gönül sende kaldı geri gelmiyor Ben benimle bensiz yaşar gibiyim Ne seninle nede sensiz olmuyor  Senden kaçıp sana koşar gibiyim İçimde cehe...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Şekerci']::text[], 8.5, '{"poet":"Mustafa Şekerci","poet_slug":"mustafa-sekerci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seninle-sensiz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Sözlüm', 'guzel-sozlum-sahin-erturk-fws5y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Okyanus sanki yüreğin

Uçsuz,buçaksız sevgin

Sıcak sözlerinle

Ruhumu,gönlümü

Okşayanasın sen

Güzel sözlüm

Kapıldım sana

Şart''mı yanında olmak

Şart''mı yüzünü görmek

Güzel sözlerinle

Aşka,sevgiye

Doyurdun beni

GÜZEL SÖZLÜM

Kapıldım sana

(09.04.2005-Yeni)', 'Okyanus sanki yüreğin Uçsuz,buçaksız sevgin Sıcak sözlerinle Ruhumu,gönlümü Okşayanasın sen Güzel sözlüm Kapıldım sana Şart''mı yanında olmak...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/guzel-sozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O''nun Ölümü', 'o-nun-olumu-vedat-gungorur-hfkdg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölüm..soğuk nefesinimi üfürüyor..ne

Işığımı söndürmek

Akşamları mı karartmakmı istiyor

Kandilleri söndürür Senin ölümün..

ah o gidişin

Ve sen... sen biliyordun ki

Varlığın ışıtırdı dünyamı

Bedeninde  götürdüğün o yaşanmışlıklar

Onurdur şereftir ve onlar anıdır

Yalnızlık...bahçem olmayacak

Ve ben o bahçeyi hiç sulamayacağım

Yalnızlık bahçesi tufanlara gebe

Ve o tufanlar ki

Bir akşam alacak beni

Yatağımdan...belkide taburemden

Sana gelen istasyonlara doğru

Hem de dudaklarının bıraktığı

Bedenimdeki izlerle

Ellerinin ısıttığı

Ellerimdeki sıcaklığınla

Ben sana geleceğim

Ardından ve koşarak

Sen vargit gideceğin yere

Pişman olma ebediyet  yolcusu

Varacağın en son yerde 

Bekle..bekle beni..

***********************************

Tüm sevdiklerini kaybedenlere sevgilerimle

vedat GÜNGÖRÜR  ([email protected])', 'Ölüm..soğuk nefesinimi üfürüyor..ne Işığımı söndürmek Akşamları mı karartmakmı istiyor Kandilleri söndürür Senin ölümün.. ah o gidişin Ve se...', ARRAY['Türk Edebiyatı','Şiir','Vedat Güngörür']::text[], 8.5, '{"poet":"Vedat Güngörür","poet_slug":"vedat-gungorur","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/o-nun-olumu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olağanüstü', 'olaganustu-gokhan-oflazoglu-fm53s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Apaçıklığında kırılır saf neşe,

kalır ölgün birikintisi sızıntının,

dönüşür gri tonlara, kapatır

kapısını gövde kımıl kımıl

emen dalgayı. Şaşırmış; 

ilk kez duyar gibi, uğul uğul

kulakların uzağı benimsemiş,

bu kadar çaresiz, sormaz

artık hücre, kendine yakın,

başkasına uzak; açar kilitlerini

bir bir sakınılanın ve anlar

herkesin öyküsü olağanüstü.

09/05/2005', 'Apaçıklığında kırılır saf neşe, kalır ölgün birikintisi sızıntının, dönüşür gri tonlara, kapatır kapısını gövde kımıl kımıl emen dalgayı. Şa...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olaganustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Körfez''de Ölüm Kokusu', 'korfez-de-olum-kokusu-ozan-ozel-p2385', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlık dereler akar kentin içinden

Akarken yaşamı da ardından sürükler

Öylece uzanır gider Körfez''e doğru

Ve İzmit''i sarar ölüm kokusu

Karanlık dere, koku, ölüm

Mahşerin üç atlısı gibidir bu kentte

Dört nala giderler bir yöne

Yaşamdan alıp götürdükleri yükle

O yük ki; onlara hafif gelir

Bize ise ağırdır', 'Karanlık dereler akar kentin içinden Akarken yaşamı da ardından sürükler Öylece uzanır gider Körfez''e doğru Ve İzmit''i sarar ölüm kokusu Kar...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/korfez-de-olum-kokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beş Yüz Elli Adam', 'bes-yuz-elli-adam-ozan-ozel-m3oy4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beş yüz elli adam,

sağdan, soldan, ortadan

geldiler...

Geldiler, yediler, gittiler

Gittiler, geldiler, yediler

Yediler, yedirdiler

İş, aş, hak, adalet...

Bunları söyleyenler kimdiler', 'Beş yüz elli adam, sağdan, soldan, ortadan geldiler... Geldiler, yediler, gittiler Gittiler, geldiler, yediler Yediler, yedirdiler İş, aş, h...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bes-yuz-elli-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Namussuz Namuslu', 'namussuz-namuslu-ozan-ozel-f8cis', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir adam, namuslu! 

Evde on çocuk, iki eş

Biri nikahlı, biri beleş

Bir adam, namuslu! 

Eşleri memnunmuş hayatından

Bezilir mi hiç koca dayağından

Bir adam, namuslu! 

Sabah kalkmış yatağından

Meğer nikahlı eş kaçmış kucağından

Bir adam, namuslu! 

Öyle böyle dediler giden eşin ardından

Ölüm kararı çıktı aile efradından

Bir adam, namuslu! 

Ona buna sordu, buldu kadını

Önce vurdu, sonra söyledi adını; Namus! 

Ölmüştü Namus, adam hapiste

Töre yerini bulmuştu işte

Bir adam, Namus’suz! 

Pişmandı, belliydi halinden

Ama Namus gitmişti

Ne gelir elden!', 'Bir adam, namuslu!  Evde on çocuk, iki eş Biri nikahlı, biri beleş Bir adam, namuslu!  Eşleri memnunmuş hayatından Bezilir mi hiç koca dayağ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/namussuz-namuslu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kadın', 'bir-kadin-ozan-ozel-pgbp9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir kadın,

adı ''k'' ile başlar

ellisine dayanmış yaşı

hep vardır bir telaşı

bir kadın,

sigarası yemektir ona

tütün kokar her daim

parfüm kokusu esirdir teninde

bir kadın,

kurulmuş koltuğuna

ayağı yere değmez

kısadır boyu, kabul etmez

bir kadın,

sen değilsin o

o bilir kendini

belki de düzeltir fikrini', 'bir kadın, adı ''k'' ile başlar ellisine dayanmış yaşı hep vardır bir telaşı bir kadın, sigarası yemektir ona tütün kokar her daim parfüm koku...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-kadin-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş dili 1', 'kus-dili-1-ali-riza-unal-pfswx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karga leşi düşler, gül bağını neyler.

Aç yılan,bin umut ile fareyi gözler.

Kemre böceği gübrelikte, kemre severmiş.

Arılar çiçeğe hasret,sinek bala düşmüş gebermiş.

Karınca külhan olmuş,süleymana yol kesmiş.

Sineğin sillesi.file aş olsun diye.dal kesmiş.

Süleyman kuş dilinin piri dediler.

Kuş dili hak dili,hakkı birdir dediler.

Bir tilki ile iki obur çakal aslanı yediler.

Doymadı karınları daha varmı dediler.

Şahin cengâver oldu, turnayı göğden indirdi.

Yediğini yedi yemediğini,kırk haramiye yedirdi.

Sular kesilecekmiş, balık gitti yukarı dağa.

Ne olur ne olmaz,tedbir için kazan bulmağa.

En ucuz tarifeli kargo. Güvenli kaplunbağa.

Bu meydan meçhul,kim kapıcı kim ağa.

Öyle bir alemki ne saraya benzer ne bağa

Serçeden kız ister utanmaz, kartal denen ağa

Kösnüye aşık olmuş,öküz denilen boğa.

Bu nasıl düğündür su taşır kalbur ile kova

Mecnun sanır kedini,sarhoş sivri sinek

Vurur yolunu,batak göl diye çöl ile dağa.

Ehil olan kanmazmış üç beş akçe ne bala ne yağa.

Hırs bürüdü gözünü kelleyi kaptırdı,ganmaz kurbağa.

kene mihman olmuş koyun kıçına beş öyün bakar aşına

Kader bu ya sülük, hakan olmuş ahmak manda başına.

Çekirge kudum vurur.cırcır keman ile bağlama

Kaplan gelin olmuş kediye.gül pençem ağlama

Sultan serilmiş toprağa, fatiha bekler  mezar taşı.

Kimi huri gılman ile. Kimine belâ zeban başı.

Bu sözlere arif ol, duyda gel, zifaf ol gedeğe.

Zümrütü anka muhtaç olmuş.tüysüz ördeğe

Bu halden anlayan, bilki secdeyi rahmandır.

Her hayvan nefsi emmareye,nişanı gümmandır.

Ehline sosuz hürmet,bu fakir kıraat ile rûku eder.

Erenler o sevdayı visale,her dem ile mihmandır.

Sanmayın Rızanın bu  sözü, deli saçması.

Kuş dili derler buna. Haramdır ahraza açması.

Bilmişiz bu dil ile nesimiyi mısrıyi,gayrına ne gerek.

Hal ile pişen kamili erdem olur, hacet deyil kaçması.

Divanı subhaniyemizden arifana bir katreyi lütûftur.

Anlayan ehline bir ledün sofrası, yiyene afiyet helâl olsun.

    Talep olur ise daha açık şerh ederiz elhamdülillah.

-----------------------

özel not:: bu eseri her ne kadar değerli okuyucularımın yorumuna

bıraktık isede bir ip ucu verme ihtiyacı duymuş bulunmaktayım

bu nedenle kıymetli ve basiretli okuyucularımın dikkatini çekmek

ve daha isabetli okuması ve faydalanması için eserde geçen hayvan türlerinin

ademde bulunan emmare nefsin mizac ve mertebelerini anlatmaktadır

Cênâbı Hak talip olan her kuluna hazreti insan olmayı nasip etsin amiin.

bakalım şu antoloji deryasına,hal ve ehvalimize kaç ehil çıkacak nasıl olsa

çıkanda bizim çıkmayanda.bilende sağ olsun gülende...........', 'Karga leşi düşler, gül bağını neyler. Aç yılan,bin umut ile fareyi gözler. Kemre böceği gübrelikte, kemre severmiş. Arılar çiçeğe hasret,sin...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/kus-dili-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilsizim, Ben Sizim', 'dilsizim-ben-sizim-ozan-ozel-640a0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dilsizim ben

konuşmamı beklemeyin

şarkılar söylememi, mırıldanmamı

haykırmamı beklemeyin

kalemimden kağıda dökülür

duygularım, düşüncelerim

öyle ki; elim, kalemim

benim dilim

yazıyorum...

lütfen yazdıklarımla yetinin

isterim ki bir de okuyun

bendeki beni bilin

konuşmamı beklemeyin

işte ben buyum

ne bir eksik, ne bir fazla

dilsizim, bilin ki ben sizim', 'dilsizim ben konuşmamı beklemeyin şarkılar söylememi, mırıldanmamı haykırmamı beklemeyin kalemimden kağıda dökülür duygularım, düşüncelerim ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dilsizim-ben-sizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atatürküm uyanda bak halime', 'ataturkum-uyanda-bak-halime-hasim-koc-lg430', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Atatürküm uyanda bak halime

Seni anmak günah dendi elimde

İbadetimi TÜRK çe yapmak istedim

TÜRK çe olursa günah dendi elimde

Ağlarken anne dedim dilimde

Saygı duydum  baba dedim dilimde

TÜRK çe söyledim derdimi iyi kötü halimde

İbadetimi TÜRK çe yapmak istedim

Türk çe olursa günah dendi elimde

Çocuğumun ismi olsun istedim oya kaya bilge

Gönlüm ister açık olmayı yeniliğe

Anlaşılan dil aydınlık beyinlerde

İbadetimi TÜRK çe yapmak istedim

TÜRK çe olursa günah dendi elimde

ATATÜRK ÜM seni anladılar anlatmadılar

Senin özüne TÜRK insanının özüne katmadılar

Huzuruna gelip sözler verdiler verdikleri sözleri tutmadılar

Çocuğumun adını TÜRK çe koymak istedim

Ayşesi fatması mehmeti ahmeti olmazsa

Hepsi TÜRK çe olursa günah dendi elimde', 'Atatürküm uyanda bak halime Seni anmak günah dendi elimde İbadetimi TÜRK çe yapmak istedim TÜRK çe olursa günah dendi elimde Ağlarken anne d...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ataturkum-uyanda-bak-halime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karagözlü Şam'' dan Geldi...', 'karagozlu-sam-dan-geldi-i-brahim-ethem-bingul-jlx7i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaf Dağı''nın ardından

Umulmayan bir anda

Zeytin gözlüm

Gül kokularıyla geldi...

Özlemimin özü

Sevgilimin sözü

Gece gözlüm

Namınla Şam''dan geldi...

Gitme demiştim, gitmişti

Ömrümün neşesini silmişti

Bahar gibi yanıma 

Kara gözlüm al yanağında

Beniyle geldi...

Ne kızıla, ne sarıya özlemim

Senin prangana hasretim

Haziran küllerimi savursa da 

Nisan, Anka kuşunun gagasında 

Müjdelerle aşkımla hayat sundu...

www.iebingul.com', 'Kaf Dağı''nın ardından Umulmayan bir anda Zeytin gözlüm Gül kokularıyla geldi... Özlemimin özü Sevgilimin sözü Gece gözlüm Namınla Şam''dan ge...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/karagozlu-sam-dan-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Hey İstanbul', 'hey-i-stanbul-yunus-guzel-6tlz1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hey İstanbul! 

Başımda kavak yelleri esiyordu,

İndiğimde Haydarpaşa Garı''na

Yere düşmüştü gökyüzü,

Işıl ışıldı yıldızların...

Deniz ıslatıyordu tarihin yapraklarını

Şaşkınlıktan rüzgar gülüne dönmüştüm

Ben böyle cömert sevgili görmedim

Milyonlarca aşığını almışsın koynuna

Uçsuz bucaksız hayaller kurdurursun 

Nasıl bir şeysin sen? 

Sen, yedi yanaklı yosmam! 

Sen, sevdikçe güzelleşiyorsun! 

Orhan Veli olasım gelirdi Hisar’da

Varsın, rakım bardakta,balığım tabakta olsun...

Altımdan deniz geçerken Adalar Vapuru’nda

Ben içerdim,dalgalar yan basardı

Savrulurdum dalgaların salıncağında

Ve benim de olmayan yalıları,

Tek tek sayarak geçerdi  yolculuk…

Hey İstanbul! 

Dönüşünü kimsenin sevmediği yolculukların kenti

Benden başka,

Sana giden kimse geri dönmedi

Boğazın sularına gözü düştü bu güneylinin

Ne yardan, ne serden geçemedi

Ay hilalken,

Urganından salıncak yaptığımız

Yaralı bir kuş gibi,

Denize düşen kuyruklu yıldız...

Senin semalarında, 

Ama senden uzak...

Benim gibi yapayalnız …

Bereketlidir bugünlerde efkarım

Dağılsın bir lodos gönder 

Kös dinler bir gemi limanda

Bir can, gemiye ölü sevinçler yükler

Doymadım yosmam! 

Doymadım tepelerine! 

Açgözlü de! 

Doyumsuz de! 

Ne dersen de! 

Yeter ki; 

Kaş altından bir göz at! 

Hiç olmazsa, 

Selam söyle gözlerime...', 'Hey İstanbul!  Başımda kavak yelleri esiyordu, İndiğimde Haydarpaşa Garı''na Yere düşmüştü gökyüzü, Işıl ışıldı yıldızların... Deniz ıslatıyo...', ARRAY['Türk Edebiyatı','Şiir','Yunus Güzel']::text[], 8.5, '{"poet":"Yunus Güzel","poet_slug":"yunus-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/hey-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende sedayı özleyebilirim', 'bende-sedayi-ozleyebilirim-hasim-koc-gx1h7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özledimde özledim

Rüyalarıma girer oldu

Sanki seda dolu her yanım

Her anım özlemle doldu

Bende SEDA yı sevebilirim

Bende SEDA yı özleyebilirim

Bende SEDA yı görmeyi isterim

Her anım özlemle doldu', 'Özledimde özledim Rüyalarıma girer oldu Sanki seda dolu her yanım Her anım özlemle doldu Bende SEDA yı sevebilirim Bende SEDA yı özleyebilir...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bende-sedayi-ozleyebilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevil Nizamoğulları''na Nazire', 'sevil-nizamogullari-na-nazire-erdogan-ergin-y2qwp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevil NİZAMOĞULLARI''nın ''Demek ki Sevgim Bitmiş'' şiirine karşılık yazılmıştır.

Demek ki hala farkındasın hayatın, 

Yoldan geçen otobüsün peşine takılmışssın 

Kendi işinle meşgulken, duygularını çalıştırmışsın 

Kızmışsın, sevmişsin hatta darılmışsın 

Sevgi her zaman güldürmez yüzü, 

Bazen ateş yapar, soğuk algınlığından beter 

Demek ki; ölçü değilmiş gülmek 

Gülünce sevmek 

Bak bana hala üzülmekteyim 

Ama derinden sevmekteyim 

İnsanlar amaç edinir çalışmayı 

Oysa çalışmak amaç, mutlu olmak adına hayatta 

Çaycın simit getirmemiş! 

Bırak, bir gün de sen götür, o simidi 

Şaşırsın... 

Para, 

Varlığı ile yokluğu aynı ıstırapta 

Fazlasını da umma, 

Azının da ardında kalma 

Hayat bu, 

Bir kağıt parçası silmemeli umudu 

Değişim hayat boyu, 

Şairi aynalara bakıtmayan, 

Kaşa inmiş akları, kar sandıran 

Bir de bak aynaya tersinden

Ya ruh, onyedisinde değil mi 

Gülmek ruhu gençleştirir, 

Lakin kahkaha üzer kalbi 

Üzer garibi 

Hasret, 

İşte o bende de var, 

Boşu boşuna ruhum, hamallığını yapar 

Sevgi bitmez ki....... 

Bitse; 

Niçin seni bu ıstırap sarar', 'Sevil NİZAMOĞULLARI''nın ''Demek ki Sevgim Bitmiş'' şiirine karşılık yazılmıştır. Demek ki hala farkındasın hayatın,  Yoldan geçen otobüsün peş...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sevil-nizamogullari-na-nazire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim düğünler özelliklidir', 'bizim-dugunler-ozelliklidir-hasim-koc-q3lzh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uğra bizim köye uğra bir ara

Klarnet sesine karışan TÜRKÜ ler nicedir

Bizim düğünlerde klarnet çalar

Klarnet nağmeleriyle halay nicedir

Düğünler öyle bir gecede bitmez

Yaaa  tam üç gün üç gecedir

Bizim düğünler özelliklidir

Öyle bir pasta bir limonatayla bitmez

Etli sütlü kebaplı baklavalıdırda

Bazan onlar bile yetmez

Düğünler öyle bir gecede bitmez

Yaaa  tam üç gün üç gecedir

Birde klarnetçi MUSTAFA vardır

O çaldıkça yemekler yenir

O çaldıkça güveyi gelin giyindirilir

O çaldıkça oğlan evinden kız evine

Gelin almaya gidilir

İşte böyle çok hoştur

ARAPGİRDE EĞİNDE AĞINDA düğünler

Öyle bir gecede bitmez

Yaa tam üç gün üç gecedir bizde düğünler

İstanbul 30-06-2003

Pazartesi saat 08-50', 'Uğra bizim köye uğra bir ara Klarnet sesine karışan TÜRKÜ ler nicedir Bizim düğünlerde klarnet çalar Klarnet nağmeleriyle halay nicedir Düğü...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bizim-dugunler-ozelliklidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim çaylar hep bulanık akar', 'bizim-caylar-hep-bulanik-akar-hasim-koc-v9llu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bizim çaylar hep bulanık akar

Dolanır çevrilir bendine yakar

Şimdi ela gözlüm yoluma bakar

Kalmaya kalmaya ahım kalmaya

Beni yardan ayıran murat almaya

Bizim çayın suyu hep dolu dolu

Akar durur doldurur aşağı gölü

Benim nazlı yarim köyümün gülü

Kalmaya kalmaya ahım kalmaya

Beni yardan ayıran murat almaya

Bizim çayın yolları incedir ince

İnsan bir hoş olur yari görünce

Çifte kurban adarım yarim gelince

Kalmaya kalmaya ahım kalmaya

Beni yardan ayıran murat almaya', 'Bizim çaylar hep bulanık akar Dolanır çevrilir bendine yakar Şimdi ela gözlüm yoluma bakar Kalmaya kalmaya ahım kalmaya Beni yardan ayıran m...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bizim-caylar-hep-bulanik-akar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-sibel-maral-gv4d9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen,

Bir kar olsan

Gönlüme düşsen

Ama...

Hiç erimesen

Sen,

Bir dert olsan

Hayatıma girsen

Ama...

Çaresiz olsan

Sen,

Bir yol olsan

Bende yolcu

Ama...

Hiç bitmesen

Ben,

Bir ateş olsam

Gönlüne düşsem

Ama...

Hiç sönmesem...', 'Sen, Bir kar olsan Gönlüme düşsen Ama... Hiç erimesen Sen, Bir dert olsan Hayatıma girsen Ama... Çaresiz olsan Sen, Bir yol olsan Bende yolc...', ARRAY['Türk Edebiyatı','Şiir','Sibel Maral']::text[], 8.5, '{"poet":"Sibel Maral","poet_slug":"sibel-maral","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-534-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimde bir kalemim var', 'benimde-bir-kalemim-var-hasim-koc-4wvfu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elin sarayı köşkü varsa

Benimde bir gece kondum var

İçinde mutlu yaşarım

Evliyim dörtte çocuğum var

Heveslenmem el malına

Zenginin varmam yanına

Fakirlik gitmez zoruma

Yarınlardan umudum var

Herkes beni yoksul bilsede

Halime bazan gülsede

Parayı pulu benden fazla sevsede

Tüm insanlara muhabbetim var..', 'Elin sarayı köşkü varsa Benimde bir gece kondum var İçinde mutlu yaşarım Evliyim dörtte çocuğum var Heveslenmem el malına Zenginin varmam ya...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benimde-bir-kalemim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birbirine benzeyen çok şiir var', 'birbirine-benzeyen-cok-siir-var-mikdat-bal-fqk8l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birbirine benzeyen çok şiir var

Kurgu aynı,vurgu aynı tarz aynı

Bu sahada, birçok ozan şair var

Duygu aynı, görüş aynı, söz aynı

Türkçemiz bir,lehçemiz bir, lisan bir

Yetenek bir,beceri bir,imkan bir

Aşkımız bir,derdimiz bir, insan bir

Gönlümüz bir, kalbimiz bir öz aynı

Bazen olur mısra mısraya uyar

Önce yazan bunu okur,ya duyar

Sağa sola hemen bir haber yayar

Bu tiplerde tavır aynı, poz aynı

Mikdat der ki şairlerin dili bir

Fark varsa da, hedefi bir yolu bir

Bülbülü bir.bahçesi bir gülü bir

Duruşu bir, bakışı bir, göz aynı', 'Birbirine benzeyen çok şiir var Kurgu aynı,vurgu aynı tarz aynı Bu sahada, birçok ozan şair var Duygu aynı, görüş aynı, söz aynı Türkçemiz b...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birbirine-benzeyen-cok-siir-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serpil Barlas', 'serpil-barlas-hasim-koc-g5z9q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni methetmek için güfte yazmadım

Bu şiir seni anlatan kısa bir roman

Bize her zaman mutluluk sunan

Tatlı dilli güler yüzlü birisisin  sen

SERPİL BARLAS

Güzel şiiri müziği seversin bende severim

Sen şarkı söylerken dağılır gamım kederim

Proğram biter bitmez hemen özlerim

Tatlı dilli güler yüzlü birisisin sen

SERPİL BARLAS

Sarı saçın uzun boyun hoş endamın

Dilinden süzülen şiir gibi sözün

Ay parçası gibi güzel yüzün

Tatlı dilli güler yüzlü birisisin sen

SERPİL BARLAS

Her gün giyinirsin güzel giysiler

Kıskanırmis seni biriler

Rakibin ancak melekler huriler

Tatlı dilli güler yüzlü birisisin sen

SERPİL BARLAS', 'Seni methetmek için güfte yazmadım Bu şiir seni anlatan kısa bir roman Bize her zaman mutluluk sunan Tatlı dilli güler yüzlü birisisin  sen ...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/serpil-barlas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Düş', 'bir-dus-i-brahim-ozgan-jhz7f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir düşki kırık aynalara gebe silüeti 

adını mezar taşından almış 

ve arzı kendine gürz eyelmiş bir düş 

diyar diyar dolaşsan 

balığın karnında arasan 

gökkubbeyi ayaklar altına seripte 

balçık gibi çiğnesen 

ve diriltsen ölüleri yeniden 

yinede can bulmayacak bir düş 

bilmem nasıl olurdu 

bu düşe can vemek 

bölesi katmer katmer benliği saran 

gözüpek yalnızlıkları yerle bir eden 

ve dünyayı ters düz edecek bir düşe 

can vermek........ 

sahi nasıl olurdu? 

ey yerbilimciler! 

ey gökbilimciler! 

ey hümanistler! 

ey düşsel ögelerde kendini yitirmiş 

eyyam topluluklar! 

ey tıbbın bedbin doktorları! 

ey aşkın hodbin mecnunları! 

ey ilahiyatın bezirganları! 

ey yer küreyi kana bulayan cellatlar! 

ve yılanlar ve çıyanlar ve incin toplulukları 

böyle bir düş olurmuydu acaba? 

çorlu........09.04.05', 'bir düşki kırık aynalara gebe silüeti  adını mezar taşından almış  ve arzı kendine gürz eyelmiş bir düş  diyar diyar dolaşsan  balığın karnı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özğan']::text[], 8.5, '{"poet":"İbrahim Özğan","poet_slug":"i-brahim-ozgan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-dus-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Dem*', 'dem-hasan-tosun-2fwi9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yaşam bizi kandırıyor belki

umutlarımız son demlerinde 

heryerde isyanlar ve kavgalar

yokuz belki yeryüzünde

sana kanıyorum bir hasret rüzgarında

acılar bile farklı bedenimde

yaşam bile gülmüyor desem

sen yine aynı güzelliğinde

demiştin ya hani sen bana 

bende sana bir gülümsemede birleşmiştik

işte o isyanı yaşıyor hala gözlerim benliğimde', 'yaşam bizi kandırıyor belki umutlarımız son demlerinde  heryerde isyanlar ve kavgalar yokuz belki yeryüzünde sana kanıyorum bir hasret rüzga...', ARRAY['Türk Edebiyatı','Şiir','Hasan Tosun']::text[], 8.5, '{"poet":"Hasan Tosun","poet_slug":"hasan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah! O Melekler', 'ah-o-melekler-ali-kilic-kakiz-xxxx1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Görüp gözeten ah! o  melekler,

İnsan oturduğu zaman onlar gelirler,

Biri sağına,diğeri soluna  oturur.

O kimse yürüdüğü vakit,

Biri önünde,diğeri arkasında gider.

Kul yattığı vakit,

Biri baş tarafında,biri ayak uçunda otururlar.

O melekler asla insandan ayrılmazlar,

Bizi görüp gözeten ''Kiramen Katibin''  melekler.

Her kişinin işlemiş olduğu,sevap ve günahı yazarlar.

 Ecel gelene kadar bizden ayrılmazlar.

Kişi ölüp ruhu çıkınca, o melekler: 

Ya Rab! Bize izin ver semaya çıkalım derler. 

Hak Teâla: Gökler doludur, siz yerde tesbih ediniz,

Hasıl olan sevabı o kulumun defderine yazınız..

Hakka boyun eğen  bizi gözeten ah! o melekler. 

İnsan başı boş mu yaratıldı zannediyor?  vah bana! 

Biz sorumsuz değiliz. Görüp gözeten elçiler var ya.

Şahsi mesuliyet var! 

Ne büyüklenenlere,

Ne de şeytana,

Sorumsuzluğumuzu yıkamayız.

Brüksel / 2001', 'Görüp gözeten ah! o  melekler, İnsan oturduğu zaman onlar gelirler, Biri sağına,diğeri soluna  oturur. O kimse yürüdüğü vakit, Biri önünde,d...', ARRAY['Türk Edebiyatı','Şiir','Ali Kılıç Kakiz']::text[], 8.5, '{"poet":"Ali Kılıç Kakiz","poet_slug":"ali-kilic-kakiz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ah-o-melekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sana karşı sevdiğim*', 'sana-karsi-sevdigim-hasan-tosun-crwms', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hüzünler ne güzel seninleyken

uçurumlar bile nefile eser yüreğimizde

seni aramak hayatın sarı sayfalarında

kadere biat ederken senin yüreğinde

yaşlanmaya yüzüm tutmuyor 

baharda sana karşı

bir türkü tutturmuşum ayrılığı dışlayan 

saherde sana karşı

kelimeler düğüm oluyor sevdiğim

içimde türlü isyanlar

her yerde sen varsın

klasik bir değimle sevdiğim', 'hüzünler ne güzel seninleyken uçurumlar bile nefile eser yüreğimizde seni aramak hayatın sarı sayfalarında kadere biat ederken senin yüreğin...', ARRAY['Türk Edebiyatı','Şiir','Hasan Tosun']::text[], 8.5, '{"poet":"Hasan Tosun","poet_slug":"hasan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-karsi-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek! Nedir Bilirmisin?', 'seni-sevmek-nedir-bilirmisin-deniz-yilmaz-eralp-zowpu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni sevmek! 

Nedir bilirmisin? 

Seni Sevmek! 

Bir güvercinin kalbi gibidir,

kıpır kıpır.

Ve ağzındak zeyttin dalı, 

Uçurur insanı sevgiye,

Aşka ve barışa yolculuk.

Seni Sevmek! 

Hayattır, yaşamdır, 

Damarımda dolaşan kandır,

Bana hayat veren.

Ve içtiğim sudur

Su kadar temiz ve aziz.

Seni Sevmek! 

Bakire bir kızın

Göğsünde uyumaktır usulca. 

Hiç bir kötü niyet olmadan. 

Hiç bir  yere kıpırdamadan,

Uyuduğun gibi uyanmaktır.

Seni Sevmek! 

Umuttur, ümittir. 

Hayaldir düşlerini kurduğumuz

Dostluktur,

Beraberce paylaştığımız.

Seni Sevmek! 

Çölün ortasında bile,

Üşümektir,

O sıcakta

Ve susamaktır,

Kana kana.

Seni Sevmek! 

Çözümü olmayan

Bir denklemdir.

Cevabını bulamadığım.

Ve hala aradığım.

Seni Sevmek! 

Ağlayan bir çocuğun

Göz yaşıdır.

Ve gülümsemesidir 

Sonra gözünü kısarak

Seni Sevmek! 

Ömür''dür

doya doya yaşamaktır o''nu

ve bu ömür hiç bitmez

ölümsüzlük iksirini

içmiştir, kutsanmıştır.

Seni sensiz yaşamak ne zor gelir bana bilir misin? 

Seviyorum ''LAN'' seni anlasana...

Seviyorum seni, Ben.............', 'Seni sevmek!  Nedir bilirmisin?  Seni Sevmek!  Bir güvercinin kalbi gibidir, kıpır kıpır. Ve ağzındak zeyttin dalı,  Uçurur insanı sevgiye, ...', ARRAY['Türk Edebiyatı','Şiir','Deniz Yılmaz Eralp']::text[], 8.5, '{"poet":"Deniz Yılmaz Eralp","poet_slug":"deniz-yilmaz-eralp","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/seni-sevmek-nedir-bilirmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Sokaklar', 'garip-sokaklar-selcuk-ugur-5b9cg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine köşe başında bekler gibisin,

İşte şu aradan geliyor sesin,

Ayak seslerine karışıyor,

Günaydın deyişin.

Yine perişanım,kafam manyak,

Bekliyorsun zannediyorum işe bak,

Sanki sensiz başıma çöküyor,

Şu garip sokak.', 'Yine köşe başında bekler gibisin, İşte şu aradan geliyor sesin, Ayak seslerine karışıyor, Günaydın deyişin. Yine perişanım,kafam manyak, Bek...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Uğur']::text[], 8.5, '{"poet":"Selçuk Uğur","poet_slug":"selcuk-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/garip-sokaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur', 'ne-olur-selcuk-ugur-s3ocf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni özlemiştim

Okulada geç gelmiştim

Beni aramış sormuşsun

Gördünüz mü onu diye

Belli ki özlemişsin

Tıpkı benim gibi

Duydumda inanamadım

O zaman seni daha çok istedim

Ne olur beni sevmediğini söyle

Seni gördüm gözlerin parlıyordu

Ya bana nerdesin deyişin

Sanki özledim seni der gibisin

O an kendimden geçtim

Ne olur beni sevmediğini söyle

Sen namazdan çıkmıştın

Ben ise minibüsten inmiştim

Arkamdan Selçuk deyişin

Ya yürürken ettiğin muhabbetin

Ne olur beni sevmediğini söyle

Bana söz verdin buluşmak için

Bekledim Cuma gününe dek

Bir mesaj bile göndermedin

Sanki unutmuş gibisin

Ne olur beni sevmediğini söyle

Sonra aramama kararı aldım

Seni unutabilmek için

Sana koridorda görünmemek için

Görüpte yaramın kanamaması için

Ne olur beni sevmediğini söyle

Ve kahretsin beni görüyorsun

Gözlerimin içine bakarak geliyorsun

Nerdesin hiç görüşemiyoruz diyorsun

Ben ise sana bahane uyduruyorum

Ne olur beni sevmediğini söyle

Ve bugün ki tavrın

Sayende çok mutluyum deyişin

Benim mutsuzluğumu farkedişin

Mutsuzluğumun sen olduğunu söyleyişim

Ne olur beni sevmediğini söyle

Yurda geldim üzgün perişan

Kimseye selam bile vermedim

Öğleyi kıldım şöyle dua ettim

Allahım ya bir kapı aç yada canımı al diye

Ne olur beni sevmediğini söyle', 'Seni özlemiştim Okulada geç gelmiştim Beni aramış sormuşsun Gördünüz mü onu diye Belli ki özlemişsin Tıpkı benim gibi Duydumda inanamadım O ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Uğur']::text[], 8.5, '{"poet":"Selçuk Uğur","poet_slug":"selcuk-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ne-olur-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut Dediler', 'unut-dediler-selcuk-ugur-hyj1k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen git gönlünü avut dediler,

Göz yaşını sil de,kurut dediler,

Bir an evvel kalbinden sil at dediler,

Bana bugün yari unut dediler.

Gönlün viran senin harap dediler,

Sevme artık onu serap dediler,

Dokunmayın buna garip dediler,

Bana bugün yari unut dediler.

Dedim ki:

Kurularım gözümü ağlarsam eğer,

Halimden anlayın garipsem eğer,

Unuturum dedim ölürsem eğer.

Bana yari ne olur unut demeyin.', 'Sen git gönlünü avut dediler, Göz yaşını sil de,kurut dediler, Bir an evvel kalbinden sil at dediler, Bana bugün yari unut dediler. Gönlün v...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Uğur']::text[], 8.5, '{"poet":"Selçuk Uğur","poet_slug":"selcuk-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unut-dediler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüm Karası Gözlüm', 'uzum-karasi-gozlum-selcuk-ugur-yko8m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biliyor musun

Üzüm karası gözlerin

Bana memleketimin üzümünü hatırlatıyor

Biliyor musun

O hilal kaşların

Harput’un sıra sıra tepelerini hatırlatıyor

Kaşlarını çattığın zaman

Harput Kalesini görür gibiyim

Biliyor musun

Dudakların kırmızısı varya

Elazığ’ın çileğini hatırlatıyor

Biliyor musun

Yüzün öyle berrak ve doğal ki

Mavi bayrak almış Hazar Gölünü hatırlatıyor

… ve biliyor musun

SENİ SEVİYORUM', 'Biliyor musun Üzüm karası gözlerin Bana memleketimin üzümünü hatırlatıyor Biliyor musun O hilal kaşların Harput’un sıra sıra tepelerini hatı...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Uğur']::text[], 8.5, '{"poet":"Selçuk Uğur","poet_slug":"selcuk-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uzum-karasi-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-selcuk-ugur-xhkav', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benimki dert midir bilmem

Anlatsam dinler misin bilmem

Ruhum daralıyor desem

Okşar mısın bilmem

Satırlar satırda kalır

Kelimeler biçare kalır

Bir sevgiliye hasret kalır

Sensiz gönül dertli kalır

Bu dünya bana göre değil

Sensizlik bana çare değil

Adalet terazisi sağlam değil

Üniversite insan olana göre değil

Sanmaki çözümsüzlükten

Sanmaki güç yetmezlikten

Bilki hayatın çözüm şeklinden

Bilki sabır göstermekten', 'Benimki dert midir bilmem Anlatsam dinler misin bilmem Ruhum daralıyor desem Okşar mısın bilmem Satırlar satırda kalır Kelimeler biçare kalı...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Uğur']::text[], 8.5, '{"poet":"Selçuk Uğur","poet_slug":"selcuk-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgiliye-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Sızısına', 'gonul-sizisina-selcuk-ugur-qn3g9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neden hep üzülen benim

Hayır denilenim

Evete hiç mi layık değilim

Sanmaki sensiz başkalarındayım

Ben yalnız sendeyim

Kime güzel desem

Seni gördüğümdendir güldestem

Sırf sana benziyorlar diye

Onlarda seni gördüm diye

Bilmem nasıl anlatsam diye

Uzaktan seslendim sana

Önce kapattın bana

Kulakların; başka seslerdeydi

Şimdi duydunda neylesem

Hangi gizden çıkıpta ey desem

Burada Harput Kalesi yokki haykırayım

Hazar Gölü yokki ismine mürekkep bulayım

Neyleyim Sarahatun yokki niyaz edeyim

Ellerimi semaya kaldırıp seni dileyeyim

Ve bende olanı sana vereyim

Sanmaki sensiz gülmelerdeyim

Keyfe halikum sorusuna

Elhamdülillah demenin coşkusuna

Bilsen öyle hasretimki

Senle beraber olmanın mutluluğuna', 'Neden hep üzülen benim Hayır denilenim Evete hiç mi layık değilim Sanmaki sensiz başkalarındayım Ben yalnız sendeyim Kime güzel desem Seni g...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Uğur']::text[], 8.5, '{"poet":"Selçuk Uğur","poet_slug":"selcuk-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gonul-sizisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak İstemiyorum', 'yasamak-i-stemiyorum-selcuk-ugur-841dr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mevsim bahara gebeyken

Hava bazen yağmurlu

Bazen rüzgarlıyken

Dışarı çıkamazken

Yaşım yirmi ikiye girerken

Kafam bulutlu

Gönlüm esintiliyken

İçimdekiler dışarı hapsolacakken

Mevsim güneşe hazırlanırken

Hava açılacak

Ve ısınacakken

İçerden çıkamazken

Gençliğe girerken

Kafam serinleyecekken

Gönlüm güneşlenecekken

İçimdekiler dışarı çıkacakken

Anladım ki

Mevsim hep sonbaharmış

Hava hep yağmurlu

Ve hep rüzgarlıymış

İçerden çıkamamışım

Yaş yirmi ikide olsa 

Kafam buluttan

Gönlüm esintiden

İçimdekiler dışarı çıkar mı

Meğer mevsim güneşe hasret

Hava kapalı

Ve soğukken

İçerden çıkamadım

Meğer gençlik gelmemiş

Kafam serinlemez

Gönlüm güneşlenmez

İçerde hapis kaldım', 'Mevsim bahara gebeyken Hava bazen yağmurlu Bazen rüzgarlıyken Dışarı çıkamazken Yaşım yirmi ikiye girerken Kafam bulutlu Gönlüm esintiliyken...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Uğur']::text[], 8.5, '{"poet":"Selçuk Uğur","poet_slug":"selcuk-ugur","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yasamak-istemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilsem', 'bilsem-ozgur-kokturk-6ez15', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Korkarım şimdi

Vallahi korkarım

Tutar gelir sabahın köründe

Telaşa kapılır işte mısralarım

Öyle utanması, sıkılması da yok

Arsız kefere! ..

Teklifsiz gelir

Hem de buyursuz

Sanmayın kusursuz

Sualsiz

Sorgusuz...

Niye gelir

Nereden gelir bilmem

Korkarım şimdi

Vallahi korkarım

Kim gelir

Bir bilsem...', 'Korkarım şimdi Vallahi korkarım Tutar gelir sabahın köründe Telaşa kapılır işte mısralarım Öyle utanması, sıkılması da yok Arsız kefere! .. ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bilsem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''u Sensiz Yaşamak Çok Zor!', 'i-stanbul-u-sensiz-yasamak-cok-zor-neriman-akgul-cbm4w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbul ah! İstanbul.

Aynı kaderi mi paylaşıyoruz seninle? 

Nerede martı seslerin, nerede yeşil denizin? 

Her bahar olduğu gibi neden yeşermez boğaz? 

Manolyalar, erguvanlar 

Nereye gizlendiler? 

Kocaman buğulu bakışlarımız nerde? 

Ah sevgili! 

Sen halimi gel İstanbul’a sor

İstanbul’u sensiz yaşamak çok zor! 

Anlamsız artık Beyoğlu’nu dolaşmak

Pierre Loti’den boğazı seyre dalmak

Göksu’da küreklere sarılıp mehtaba çıkmak

Senin sesin yoksa duyulmaz Çamlıca’nın kasım sakaları

Ah sevgili! 

Sen halimi gel İstanbul’a sor 

İstanbul’u sensiz yaşamak çok zor! 

Her gün belki seni getirir diye 

Haydarpaşa’da dokuz trenini bekliyorum

Kah Kadıköy iskelesindeyim

Kah Yuşa tepesindeyim

Dualar ediyorum senin için

İstanbul göremez oldum güzelliğini

Ah sevgili! 

Sen halimi gel İstanbul’a sor 

İstanbul’u sensiz yaşamak çok zor

Kalemimi alıp elime

Bir İstanbul çiziyorum yüreğime

Buğulu bakışlarınla daha bir güzel

Yeşil gözlerinle daha bir yeşil

Sesinle şenleniyor Çamlıca

Gülüşünle güzelleşiyor boğaz

Ellerim açılmış Yaradan’a

Amin diyor Yuşa tepesi dualarıma

Gel diyorum gel, ey sevgili

Sensiz yaşanmıyor İstanbul’un ne günü ne gecesi

İstanbul ve sen

Yüreğimin en girift bilmecesi

Ah sevgili! 

Sen halimi gel İstanbul’a sor

İstanbul’u sensiz yaşamak çok zor!', 'İstanbul ah! İstanbul. Aynı kaderi mi paylaşıyoruz seninle?  Nerede martı seslerin, nerede yeşil denizin?  Her bahar olduğu gibi neden yeşer...', ARRAY['Türk Edebiyatı','Şiir','Neriman Akgül']::text[], 8.5, '{"poet":"Neriman Akgül","poet_slug":"neriman-akgul","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/istanbul-u-sensiz-yasamak-cok-zor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'istanbul-a-serenat', 'istanbul-a-serenat-neriman-akgul-zjzui', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Soğuk bir İstanbul sabahı

İliklerime dek üşüttü beni

Beyaz bir örtüye bürünmüş Sultanahmet

Hava tamda sıcak sahlep havası

Muhteşemsin İstanbul! 

Eşin yok dünyada

Her halinle güzelsin, her halin daha başka

Yanıma alıp birkaç arkadaşı

Şöyle bir gezmek lazım kapalıçarşıyı

Şark kahvesinde yudumlarken çaylarımızı

Anmamak olmaz burada oturmuş üstadları

Muhteşemsin İstanbul! 

Eşin yok dünyada 

Her halinle güzelsin, her halin daha başka

Haydi kalkın dostlar devam edelim yola

Hayranlıkla bakalım Sinan’ın yapısına

Bir Fatiha okuyup şanı büyük mimara

Allah Rahmet eylesin senin azizi ruhuna 

Muhteşemsin İstanbul! 

Eşin yok dünyada

Her halinle güzelsin, her halin daha başka

Ne çabuk oldu akşam, güneş dönüş yolunda

Güzel bir gün geçirdik İstanbul’un koynunda

Yazın güzel, kışın güzel baharların bir başka

Gecende ayrı tat var, günün bir ömre bedel

Muhteşemsin İstanbul! 

Eşin yok dünyada

Her halinle güzelsin, her halin daha başka', 'Soğuk bir İstanbul sabahı İliklerime dek üşüttü beni Beyaz bir örtüye bürünmüş Sultanahmet Hava tamda sıcak sahlep havası Muhteşemsin İstanb...', ARRAY['Türk Edebiyatı','Şiir','Neriman Akgül']::text[], 8.5, '{"poet":"Neriman Akgül","poet_slug":"neriman-akgul","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/istanbul-a-serenat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkistan Serencamı', 'turkistan-serencami-seref-akar-4ihj0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çekildi mızrak mızrak başımızda uzanan

Çekildi gölgeler gün batınca tepelerden

Çekildi sukutuna varlıklarda heyecan

Çekildim ay doğunca tefekkür köşeme ben

Biraz vakit geçince açtım tüm perdeleri

Gökyüzünde yıldızlar gözlerime döküldü

Yüreğimde Türkistan biraz Mecnun serseri

Bir yıldıza dokundu Çin’e  bakınca öldü

Türkistan gönlümüzde aşktı hilesiz ve saf

Türkistan Aziz Türk’e ruh veren asil töre

Türkistan benden taraf garp kıymetine hilaf

Türkistan katledildi gözümüz göre göre

Bir bakışı vardı ki gözleri dolu dolu

Biçare idi gördük biz gördük fakat kördük

Ölünce Uygur nasıl haykırdı Anadolu

Kulak tıkamasaydık yollara dökülürdük

Şimdi onun cesedi Kızılların elinden 

Yıldızlara savrulur saman yolu ağlaşır

Işıkları inlerken semavatın derinden 

Işıklar omuzlarda o cenazeyi taşır

Önde kıyam duran Ay tekbir getiren imam

Ardı sıra saf tutan Yıldızlarsa cemaat

Bense bakarım göğe baktıkça dayanamam

Gözlerim dumanlanır yüreğim benden firkat

Böğrüme hançerlenir bir hırıltılı nefes

Esaret duvarına saplanınca düşlerim

Türkistan Taş Medrese, çelik parmaklı kafes

Soysuzun zindanında, sönmekte gülüşlerim. 

Getirmek mümkün olsa geçip giden zamanı

Tersine çevirirdim dünyayı çabuk çabuk 

Lakin bu beyhude düş çağırırken ahzanı

korkularım diyor ki: "yaşar mı ölen çocuk"

Divane olsa bile, Türkistan’ın yokluğu

Oldukça içimizde, güneş yakınlaşamaz

Türkistan Türk ilinin örselenmiş çocuğu

Türkistan Kızılların bıraktığı son enkaz

Türkistan secdedardı kıblesi ise gönül

Gönül ki secdedardı ilahi Kâbe’sine

Gönül ki aşk-ı didar valsına açan bir gül

Türkistan secde etti gönlünün kıblesine

Türk illerine hastı gayrısına berattı

Yüz çevirip bakmazdı Batı ona namahrem

İsmi aşktı, Leyladan kalbe Hakkı arattı

Bir Yıldıza Mecnundu birde Hilale Kerem

Kızılın aslı şehvet, şehvet ki aşka tuzak

Şehvet ki tek başına milletleri bitirir

Şuleden daha cazip şeytandan bile alçak

Şehvet ki gün ortası pervaneyi getirir

Divane olsa bile, Türkistan’nın yokluğu

Oldukça içimize güneş yakınlaşamaz

Türkistan Türk ilinin katledilmiş çocuğu

Türkistan Kızılların bıraktığı son enkaz

Çekildi kandil kandil semavatta uzanan

Çekildi üstümüze bulutlar tepelerden

Çekildi sukutuna varlıklarda heyecan

Çekildim Türk ölünce en sefil köşeme ben', 'Çekildi mızrak mızrak başımızda uzanan Çekildi gölgeler gün batınca tepelerden Çekildi sukutuna varlıklarda heyecan Çekildim ay doğunca tefe...', ARRAY['Türk Edebiyatı','Şiir','Şeref Akar']::text[], 8.5, '{"poet":"Şeref Akar","poet_slug":"seref-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/sark-in-olen-cocugu-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Aşk', 'simdi-ask-zehra-birsen-yamak-ytj9y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk bir kez 

Bozmaya görsün dengesini

Ya da buzdağına 

Yörüngesini

Bir yürek darbesinde durur hoşluğun

Bir ömür 

Sallamış teknesini

Ayıklığında avunur sarhoşluğun

Şimdi ''Aşk Tutulması''dır

Vurur gölgesine nahoşluğun

Şimdi aşk 

Yorgun tutunmasında

Düşer

Harabesine bir boşluğun

Aşk bir kez

Bozmaya görsün

Dengesini

Ya da 

Buzdağına yörüngesini

Payında gurur 

Donmuşluğun

Şimdi ''Aşk Unutulması''dır

Bir  kardelen yüreğinde

Burkulmuşluğun 

Şimdi aşk...

Ölgün titremesinde

Gözlerinin sonsuzluğundadır

Kaybolmuşluğun

Şimdi Aşk...Şimdi Aşk...', 'Aşk bir kez  Bozmaya görsün dengesini Ya da buzdağına  Yörüngesini Bir yürek darbesinde durur hoşluğun Bir ömür  Sallamış teknesini Ayıklığı...', ARRAY['Türk Edebiyatı','Şiir','Zehra Birsen Yamak']::text[], 8.5, '{"poet":"Zehra Birsen Yamak","poet_slug":"zehra-birsen-yamak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/simdi-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar Yüzlü Kadınlar', 'sonbahar-yuzlu-kadinlar-emine-deniz-edxa0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ürkektir bakışları,sarı çiğdemler kadar 

Küflenmiş dudakların

...Süslendiği aynalar 

Kuşkularla beslenen 

Derin dağlara inat 

Ses vermez 

Sır geçirmez 

Sonbahar yüzlü kadınlar 

Vakit mi geçtir artık 

yoksa umut mu yorgun

 Kaçamak gülüşleri 

Sonbahar kadar solgun 

Çırpınarak geçilen 

Gökyüzü sancıları 

Verilen savaşların 

Dinmeyen acıları

 Susturur da dünyayı... 

Azrail kadar

 Yazılır anılara 

Sonbahar da kadınlar 

Aslolan sevilmek mi, 

tüketmek mi sevgiyi 

Denizin ortasında 

Buzdan bir heykel gibi

 Dokununca kırılan 

Kırıldıkça çoğalan 

Kar... 

Sevilmeye çırpınan

 Ar... 

Ve baharda gizlenen 

Sonbahar yüzlü kadınlar.', 'Ürkektir bakışları,sarı çiğdemler kadar  Küflenmiş dudakların ...Süslendiği aynalar  Kuşkularla beslenen  Derin dağlara inat  Ses vermez  Sı...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sonbahar-yuzlu-kadinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepimiz', 'hepimiz-i-lhami-arslantas-na9g5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi saygı tüm insanlar barışık 

Büyük küçük saymalıyız hepimiz 

Olmamalı açlar çöpte buruşuk 

Bir teknede doymalıyız hepimiz 

Bahtımıza yeni bir gün doğmalı 

Mutluluklar gök yüzüne ağmalı 

Karanlığı içimizde boğmalı 

Güneş gibi doğmalıyız hepimiz 

Kilimlerde güzide nakış gibi 

Güzellere türküler yakış gibi 

Bir çavlanda berrakça akış gibi 

Maviliğe yağmalıyız hepimiz 

Gayret kuşağını sarmalı bele 

El ele kurmalı sevgiden kale 

Ülkemiz gelmeli yıkılmaz hale 

Bu gafletten caymalıyız hepimiz 

İlhamiyim özüm yanar ışkına 

Bakmalıdır can taşıyan düşküne 

Gönlünüzle vatan insan aşkına 

Yürekleri koymalıyız hepimiz 

18 Mart Çanakkale şehitlerini anma günü dolayısıyla 

Ulusuma armağan olsun... Saygılarımla', 'Sevgi saygı tüm insanlar barışık  Büyük küçük saymalıyız hepimiz  Olmamalı açlar çöpte buruşuk  Bir teknede doymalıyız hepimiz  Bahtımıza ye...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hepimiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AŞKA (Ne Fark Eder ki)', 'aska-ne-fark-eder-ki-seref-akar-1rz8n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Diyorlar ki 

Dağlara şölen ateşleri yakmışlar

Alazları yıldız olmuş

Kandiller, kandiller

Atlar şaha kalkmış 

Gölgelerin ucunda

Diyorlar ki 

Kıl çadırlar ovaya inmiş

Dağın efsanesi Ferhat

Şirinin aşıkıymış

Şirin peri kızı

Ferhat arslan parçası

Ne fark eder ki 

Boğulmak varsa kazmanın atlığında

Diyorlar ki 

Kapısını örtmüş keşiş

Ve kuşlarla kaçmış

Otuz iki diş, otuz iki diş

Kıl çadırın izinde

Aslının dizinde

Kerem Aslıya inciler sunmuş

Otuz iki diş, otuz iki diş

Kerem Aslının aşıkıymış

Aslı Keremin güzeliymiş

Aslı güzel miymiş

Aslı da güzel miymiş

Ne fark eder ki

Diyorlar ki 

Rüzgâr vuruyor rüzgâr

Kalpte gül üşümüş

Dikeni batmış çadırın kalbe

Mecnun Leyla, Leyla Mecnunmuş

Batmaz ya kumlar

Yakmaz ya çıplak ayak adamı

Geçersin geçersin babam

Bu çöl ateşi ne ki

Mecnun gözünde iki bulut ağar

Garibime ekmek gibi umut yağar

Çimdiklenmez ya hayal

Doğrusu ya

Mecnun çölde Leyla

Leyle külde ateş

Diyorlar ki

Ölmek kolay

Yaşamak zor

Aşk kayıp

Doğrusu ya

Kolay olmak ölmek

Zor olmak yaşamak

Kaybolmak AŞK

Ne

fark

eder

ki

Neffarkederki', 'Diyorlar ki  Dağlara şölen ateşleri yakmışlar Alazları yıldız olmuş Kandiller, kandiller Atlar şaha kalkmış  Gölgelerin ucunda Diyorlar ki  ...', ARRAY['Türk Edebiyatı','Şiir','Şeref Akar']::text[], 8.5, '{"poet":"Şeref Akar","poet_slug":"seref-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/aska-ne-fark-eder-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilekçe', 'dilekce-seref-akar-rz461', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen merhamet çemberi, ben af bekleyen mahkûm

Kendine hapset beni, hürriyetten yoruldum.', 'Sen merhamet çemberi, ben af bekleyen mahkûm Kendine hapset beni, hürriyetten yoruldum....', ARRAY['Türk Edebiyatı','Şiir','Şeref Akar']::text[], 8.5, '{"poet":"Şeref Akar","poet_slug":"seref-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/dilekce-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Bu', 'siir-bu-mehmet-dag-hkbft', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şiir bu

Şiirce bu

Hanı.. tanışmıştınız ya

Karanlığı boğan ışıkta

Hangi..  ayın  kaçında..

Belki.. 7

Belki..10

Belki..80 yaşında

Buharını kaşıkladığın 

Tencerenin başında

Belki taşın altında, kaleyi onarırken                                          

Belki ilk göz yaşında 

Zamanı sormayın ona 

İlk raunt ‘ta nakavt etti

Dinlemez hiç kimseyi

Ne şahı... Ne fermanı..

Şiir bu su gibidir 

Maddenin özünü bulur 

Çölleri orman yapar

Dağları delip geçer

Dereler gibi  akar

Bülbülde, kanaryada, Martıda içip tadına bakar

Kimisi süzer içer,

    Kimisi koklayarak, 

        Kimide hoplayarak

Bir sunadır bu şiir

Süzülür gök yüzünden

Konuşur yıldızlarla

selama durur bulutlar

Rüzgar atına binip köşe bucak dolaşır

Bir yağmurdur bu şiir

Tanışır canlılarla

Cansızlarla kaynaşır

Denizle halay çekip 

Okyanusta buluşur

Bir yosmadır bu şiir

Kalpleri dolandıran

Sessizce gecenin kaçında kapını çalan

Ne uykuları bölüp ne ninniler söyleten

Ses gibi

Nefes gibi

Girer kanına insanın

Gezegenlerini dolaşır Evrenin

Ayak parmağından kafa tasına

Bilge bir doktor gibi yoklar seni

Bir ana gibi sarar ve saklar

Gök kuşağı kundağında

Anam avradım olsun

Bir bombadır  bu şiir

 Bir Mermidir 

 Bir Zıpkındır 

Alnının ortasından vurur insanı

Çayda demi

Şarapta  tadı

Aşkta, feryadı  bilir bu şiir

Bilmem hangi dilde

anlatsam nedir bu şiir

Yorma ŞAİR

Yorma kendini bu kadar

Emektir,sevdadır.havadır,sudur

Canlıdır,cansızdır deme şair

Anlatamazsın şiiri

Sığdıramazsın.Evrene

Çünkü VAROLMAKTIR

YAŞAMAKTIR ŞİİR.................

(Avcılar)', 'Şiir bu Şiirce bu Hanı.. tanışmıştınız ya Karanlığı boğan ışıkta Hangi..  ayın  kaçında.. Belki.. 7 Belki..10 Belki..80 yaşında Buharını kaş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dağ']::text[], 8.5, '{"poet":"Mehmet Dağ","poet_slug":"mehmet-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/siir-bu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Vardı Mor Mavisi Gök Kızılında', 'ask-vardi-mor-mavisi-gok-kizilinda-hikmet-i-sin-s69xv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geçerken dünyanın bir yerinden 

Aşkın mahsumiyetini gördüm 

Dokundum ellerimle, hissettim 

Çiseleyen yağmurlarında ıslandım aşkın 

Çok üşüdüm 

Güneşin sıcaklığını hissettim bütün çıplaklığıyla 

O zamanlar 

Sandallar mavi gökteydi ve aşklar vardı içinde 

Nurdan bir ışık vardı, mutlu sandalları takipte 

Leylakı kokularıyla, serçeler uyandırırdı sabahlarında 

Hanımeli, zakkum çiçeği, karanfiller eşliğinde 

Çeşmelerinde aşkı bekledim, ırmaklarından içtim 

Çok şelale seyrettim 

Aşk bir ırmak idi birleştiği denizde 

Ben ise balık idim yüzerken aşk denizinde 

Düşen yapraklarını gördüm baharlarında 

Dört mevsimi aynı anda yaşadım 

Güneşin doğuşunu gördüm, batışını seyrettim 

Tepelerinden koştum yoruldum 

Dayadım sırtımı çıplak yamaçlarına 

Okşadım ipekten çim saçlarını 

Ve aşkı gördüm 

Farkettim vücudunu tenimde 

Sıcaklığını hissettim, heyecanını 

Dokundum ellerimle, titriyordu 

Bir ceylan sekiyordu bozkırdan dağlarda 

Ahu gözlerinde hüznü gördüm 

Başımı dayadım ak sinesine, kalp atışlarını duydum 

Koştum, korkmuştum 

Dipsiz karanlıklarda kayboldum 

Yıldızları gördüm mor mavisi gök kızılında 

Şamdanlar ellerimde, yollarım aydınlıktı 

Karanlıklar geride ilerde ışık vardı, yürüdüm 

Dört yapraklı yoncayı buldum 

Bir dilek diledim aşkın adı üstüne 

Kır çiçekleri topladım demet demet 

Kolyeler yaptım papatyalardan, boynuna taktım 

Sevdim utanmadım söyledim 

Aşk  şarabından içtim Mecnun elinden 

Leyla ben değildim, Kerem idim dağlarda 

Kırklara karıştım aşk vardı orda 

Sevgiyle kutsandım 

Değirmenlerle savaştım

Yedi başlı ejderhayı ben öldürdüm

Sen vardın içimde cesareti gördüm 

Bir ülke kurdum 

Padişahı ben oldum, kraliçesi sendin 

Leyla Mecnun, Kerem Aslı, Ferhat Şirin onlarda vardı 

Aşk denilen bu duygu ne kadarda kutsaldı 

Çok fazla şey sığdırdım şu kısa ömre 

Geçerken dünyanın bir yerinden 

Ben aşkı sende gördüm 

Ve 

Öldüm', 'Geçerken dünyanın bir yerinden  Aşkın mahsumiyetini gördüm  Dokundum ellerimle, hissettim  Çiseleyen yağmurlarında ıslandım aşkın  Çok üşüdü...', ARRAY['Türk Edebiyatı','Şiir','Hikmet İşin']::text[], 8.5, '{"poet":"Hikmet İşin","poet_slug":"hikmet-i-sin","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/ask-vardi-mor-mavisi-gok-kizilinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Sevgili!', 'ey-sevgili-muhammed-gacar-12apb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey sevgili! Yetmiyor mu bana yaptığın bu eziyet? 

Ya gönülden sev beni ya da şimdi veda et! 

İster ölümlere at beni istersen insaf et

Ya çık gel tut ellerimi ya da şimdi veda et!', 'Ey sevgili! Yetmiyor mu bana yaptığın bu eziyet?  Ya gönülden sev beni ya da şimdi veda et!  İster ölümlere at beni istersen insaf et Ya çık...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Gacar']::text[], 8.5, '{"poet":"Muhammed Gacar","poet_slug":"muhammed-gacar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ey-sevgili-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Gözlerini Göster Bir Daha', 'guzel-gozlerini-goster-bir-daha-muhammed-gacar-a2ag2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni görmeyi ummadığım anda

Hayatta sevilmeyi unuttuğum anda

Aşktan umudu kestiğim anda

Sevinçten şaşkına döndür bir anda

Severek mecnuna döndür bir anda

Seni uzaklarda sandığım günde

Sensiz gecemin sabah güneşinde

Canımı verirken son nefesimde

Güzel gözlerini göster bir anda

Güzel gözlerini göster bir daha', 'Seni görmeyi ummadığım anda Hayatta sevilmeyi unuttuğum anda Aşktan umudu kestiğim anda Sevinçten şaşkına döndür bir anda Severek mecnuna dö...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Gacar']::text[], 8.5, '{"poet":"Muhammed Gacar","poet_slug":"muhammed-gacar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/guzel-gozlerini-goster-bir-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-serdar-uzdag-gpcpn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzel İnsan Ayşen''e.....

Anılar rıhtımından kor gözlerin geçiyor

Yine öyle yakıcı, yine derin geçiyor

O yaman tılsımıyla tutarak asumanı 

Ta fecre sürükleyen kahküllerin geçiyor

Saçlarımı bıraksam rüzgarın nefesine

Telleri arasından ak ellerin geçiyor

Bir bilinmez dert ki bu, devası sızısında

Yakarken, köz ederken, öyle serin geçiyor

Felek felek dolaşıp, arasam dursam seni

Bir saman alevinde tüm izlerin geçiyor

Senden yana hep umut, sana dair hep tasa

Zannetme zaman gibi bende yerin geçiyor

Anılar rıhtımından kor gözlerin geçiyor

Öyle derin yakıyor, öyle serin geçiyor....', 'Güzel İnsan Ayşen''e..... Anılar rıhtımından kor gözlerin geçiyor Yine öyle yakıcı, yine derin geçiyor O yaman tılsımıyla tutarak asumanı  Ta...', ARRAY['Türk Edebiyatı','Şiir','Serdar Uzdağ']::text[], 8.5, '{"poet":"Serdar Uzdağ","poet_slug":"serdar-uzdag","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sana-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vermem Kimseye Aşkımın Gülünü', 'vermem-kimseye-askimin-gulunu-muhammed-gacar-afbnx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kurumuş yaprağa çevirme gönlümü

Bırakma ellerimi tattırma ölümü

Her zaman gül bana unuttur zulümü

Seni vermem, vermem kimseye aşkımın gülünü', 'Kurumuş yaprağa çevirme gönlümü Bırakma ellerimi tattırma ölümü Her zaman gül bana unuttur zulümü Seni vermem, vermem kimseye aşkımın gülünü...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Gacar']::text[], 8.5, '{"poet":"Muhammed Gacar","poet_slug":"muhammed-gacar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/vermem-kimseye-askimin-gulunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yamalı Gönlüm', 'yamali-gonlum-mehmet-dag-t3a3f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl anlatsam gönlümü bilemiyorum

Kapıları kırık bir han misali

Ne hoş geldin eden var 

Ne güle, güle

Sahipsiz harabe konak  misali

İçim içime sığmıyor bazen

Kucaklamak istiyorum herkesi

Saniye  de dört mevsimi yaşıyorum 

Kanatları kırık kuşlar misali

Nerede başladı sevinç, hüzün nerede bitti

Sende anlayamadın değil mi yamalı gönlüm

Bir ömür nasıl tükenip gitti

                                                 22 / 01 / 2005 

                                                    –Avcılar/ist', 'Nasıl anlatsam gönlümü bilemiyorum Kapıları kırık bir han misali Ne hoş geldin eden var  Ne güle, güle Sahipsiz harabe konak  misali İçim iç...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dağ']::text[], 8.5, '{"poet":"Mehmet Dağ","poet_slug":"mehmet-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yamali-gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmenin Ülkesi İli Varmıdır', 'sevmenin-ulkesi-i-li-varmidir-mehmet-dag-m1tiy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gitme uzaklara dayanamam ki

Görmesem yüzünü yaşayamam ki

Yokluğun içimde sızlıyor sanki

Ayrılamam senden bırakma beni

Sensiz olmak en zor olan olaydır

Ölüm bana ayrılıktan kolaydır

Aylar oldu sormuyorsun ne haldir

Ayrılamam senden bırakma beni 

Yıkma bir sarayı yapması zordur

İçerim bir ateş gönlümde nardır

Kar gibi eriyip tükenen vardır

Ayrılamam senden bırakma beni

Sevmenin zamanı günü var mıdır

Sevdanın ülkesi ili var mıdır

Sevenlerin mutsuz anı var mıdır

Ayrılamam senden bırakma beni 

Ben perişan oldum sen istersen gül

Ölürsem sevdiğim mezarıma gel

Yanına bir avuç gül tohumu al 

Karıştır toprağa sar gitsin beni

 (Avcılar)     1-11-2004', 'Gitme uzaklara dayanamam ki Görmesem yüzünü yaşayamam ki Yokluğun içimde sızlıyor sanki Ayrılamam senden bırakma beni Sensiz olmak en zor ol...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dağ']::text[], 8.5, '{"poet":"Mehmet Dağ","poet_slug":"mehmet-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevmenin-ulkesi-ili-varmidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filistin''e', 'filistin-e-i-lhami-arslantas-dz6qk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ortadoğu kan ağlarken orada, 

Ben kendi adıma utanıyorum. 

Bir kaç sözcük mermim olsun şurada, 

Vicdan azabından yatamıyorum. 

.............Mevzi kurup tüfek çatamıyorum 

Taşla tanka karşı can diriyorlar, 

Çoluk çocuk,yaşlı hep ölüyorlar, 

Tüm dünya oturmuş seyrediyorlar, 

Ben kendi kendimi tutamıyorumç 

................Mevzi kurup tüfek çatamıyorum 

Bir şey gelmez elden, vahlar başıma, 

Onca yıllar zehir oldu aşıma, 

Kendim ile girdim bir savaşıma, 

Filistine ışık tutamıyorum. 

................Mevzi kurup tüfek çatamıyorum 

Besler amerika, şer güder onu, 

Mazlumlar düşmanı katil şaron''u 

Sırıtır ardından lordu baronu, 

Böyle bir lokmayı yutamıyorum. 

...........Mevzi kurup tüfek çatamıyorum 

İlhamiyim vicdanımla baş başa, 

Ben ozanım sözüm çalmayın taşa 

Feryadım var,çıkarsa çıksın arşa, 

Vicdanı yürekten atamıyorum. 

.............Mevzi kurup tüfek çatamıyorum 

selam olsun sevgili yüreklere', 'Ortadoğu kan ağlarken orada,  Ben kendi adıma utanıyorum.  Bir kaç sözcük mermim olsun şurada,  Vicdan azabından yatamıyorum.  ................', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/filistin-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum 3', 'cocuklugum-3-cenk-aksal-xbf9g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ayakkabılarım

yırtıktı altıda delik,

havalar çok sertti o zaman,

istanbul donuyordu.

ben yanıyordum,

yeni bir önlük almıştı babam.

buz gibi sulara dalsada ayağım,

donsada parmaklarım,,

gıcır gıcırdı okul önlüğüm,

istanbul donuyor.

ben yanıyordum/sevincimden

mutluydum ya...oniki yaşımda', 'ayakkabılarım yırtıktı altıda delik, havalar çok sertti o zaman, istanbul donuyordu. ben yanıyordum, yeni bir önlük almıştı babam. buz gibi ...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cocuklugum-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ustadım', 'ustadim-tuncay-akdeniz-3va53', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'USTADIM

Koydun yüreğime ateşi közü

Tavasında eriyorum ustadım

Hak bilirim haktan ayırmam gözü 

Dünyasını görüyorum ustadım

Cahil kalemine neylesin kağıt

Bin nasihat etsen almaz bir öğüt

Çırak et yanında beni de eğit

Acemice örüyorum ustadım

Adalet deyince vicdanın işi 

Yolundan gidenler en kutlu kişi

Hak deyince titrer dağ ile taşı

Kıyamına duruyorum ustadım

İçimize düştü çağın vebası

Kabul görür cehaletin duası

Namertin sırtında yiğit abası

Nankörleri dürüyorum ustadım

Bu düzen bu gidiş sıktı canımı

Nice mazlumların emdi kanını

Ben yiğit tanırdım gördüm damını

Babasına yoruyorum ustadım

Sen dedikçe hep gülüyor yüzüme

Vardan öte kulak tıkar sözüme

Ağustosda kar yağıyor düzüme

Zemheriye giriyorum ustadım

Tuncay düşündükçe sabrım taşıyor

 Elim bazen nasırları kaşıyor

 Doğru yolda ayaklarım şaşıyor

 Öylesine yürüyorum ustadım   

Tuncay Akdeniz', 'USTADIM Koydun yüreğime ateşi közü Tavasında eriyorum ustadım Hak bilirim haktan ayırmam gözü  Dünyasını görüyorum ustadım Cahil kalemine ne...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ustadim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay aşka küstü', 'ay-aska-kustu-fulya-celikbilek-6vw7b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '....Aşk  deniz/de-inde kaybolmak

gök yüzünde dans etmeye benzer....

çığlık çığlık

Çavlan sesi

sahikalarda 

kartal yuvası

engindeki gemi

kaybolan ümitler

beyaz martı

suskunluğu

gecenin yalnızlığı

ateş parcası

erguvan bahcelerinde

gizli

uzanan eller

karalar büründü

mehtap avuclarda

ay aşka küstü

(19.03.2005)', '....Aşk  deniz/de-inde kaybolmak gök yüzünde dans etmeye benzer.... çığlık çığlık Çavlan sesi sahikalarda  kartal yuvası engindeki gemi kayb...', ARRAY['Türk Edebiyatı','Şiir','Fulya Çelikbilek']::text[], 8.5, '{"poet":"Fulya Çelikbilek","poet_slug":"fulya-celikbilek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ay-aska-kustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çantada keklik (Hiciv)', 'cantada-keklik-hiciv-i-lhami-arslantas-9a55p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vaatlerle faka basar seçimde 

Fukara vatandaş çantada keklik 

Otururken isyan oynar içimde 

Fukara vatandaş çantada keklik 

Hediye gelince ayaklarına 

Gebe kalır seçim kıyaklarına 

Yazık olur vatan evlatlarına 

Fukara vatandaş çantada keklik 

Boyun büker kendi seçtiklerine 

Sonra ağlar kesip biçtiklerine 

Sesi çıkmaz yiyip içtiklerine 

Fukara vatandaş çantada keklik 

Yılı geçirmeden cukkalar dolar 

Düğünde partide saçarlar dolar 

Halkın umutları bir anda solar 

Fukara vatandaş çantada keklik 

Tez kokutur ibibikler yuvayı 

Zamlar yakar mutfağında tavayı 

Beyler alır pişkin pişkin nemayı 

Fukara vatandaş çantada keklik 

Der ilhami deve çıkmaz yokuşa 

Hendekte tökezler yatarlar tuşa 

Kırpa kırpa maaşlar döner kuşa 

Fukara vatandaş çantada keklik', 'Vaatlerle faka basar seçimde  Fukara vatandaş çantada keklik  Otururken isyan oynar içimde  Fukara vatandaş çantada keklik  Hediye gelince a...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cantada-keklik-hiciv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akortsuz keman', 'akortsuz-keman-i-lhami-arslantas-0h42a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ekonomi akort tutmaz bir keman 

Bir birine karışıyor sap saman 

Eyvah! Düzen failleri pek yaman 

Kim vurduya gitti uyanın vatan 

İmf’ye borçlu doğmadık bebe 

Yani daha şimdi onlara gebe 

Gemi batırılmış bak vurmuş dibe 

Kim vurduya gitti uyanın vatan 

Biz yem arar iken at-a, öküze 

Sömürdü bizleri o yaptı füze 

ABD,AB den fayda yok bize 

Kim vurduya gitti uyanın vatan 

Elden beklemekle olur mu zikir 

Üç çeki tespihle hep kaldık fakir 

Bilimden haber yok körlendi fikir 

Kim vurduya gitti uyanın vatan 

Emekliye boy boy kefeler biçmiş 

İşçi memur bitti esnafı seçmiş 

Bakın hele yoksul canından geçmiş 

Kim vurduya gitti uyanın vatan 

Ekmeği çalınmış tuzu yok aşta 

Beş parasız kalmış şu karakışta 

Vatandaşlar sessiz,arsızlar başta 

Kim vurduya gitti uyanın vatan 

Der İlhami artık uyan ne olur 

Halk kendi çaresin kendisi bulur 

İş işten geçerse olanlar olur 

Kim vurduya gitti uyanın vatan 

..........................Vatanı kurtaran atandan utan', 'Ekonomi akort tutmaz bir keman  Bir birine karışıyor sap saman  Eyvah! Düzen failleri pek yaman  Kim vurduya gitti uyanın vatan  İmf’ye borç...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/akortsuz-keman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Ağlıyorum', 'simdi-agliyorum-volkan-yoruc-hqagn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi ağlıyorum

Ama içten derinden

Kan damlalarında boğulur gibi

Öylesine dökülür benliğimden

Artık o yok, gitti

Hayata yeni başlamanın sevinci varken

Neden bu ayrılık şimdi, ama neden

Gitme diyecek vaktim bile olmadı ki aslen

Bir gölge gibi eridi karanlık sokaklarda

Ondan hatıra sözleri kaldı bir tek aklımda

Şimdi ağlıyorum

Yine o çağlardaki gibi yüreğimi dağlıyorum

İçin için dertler binmişken üzerime

Birde senden aldığım acıyla yanıyorum

Küller içinde nefessiz kalmışım

Mavi gökyüzüne hasretlerle buralarda dalmışım

Şimdi ağlıyorum

Ve benden sana dair bu son yorumum

Artık eller cebimde gidiyorum

Gülmek sana nasip olsun,ben artık yalnızlığa müptelayım

Şimdi ağlıyorum

Ama sana değildir artık bu yangınım

Yalnızlığa müptelayadır şu son mısralarım

Yüreğinden seslerle duvarlarda yankılanan

Aşka tutkun, elleri solgun bir delikanlıyım', 'Şimdi ağlıyorum Ama içten derinden Kan damlalarında boğulur gibi Öylesine dökülür benliğimden Artık o yok, gitti Hayata yeni başlamanın sevi...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/simdi-agliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-aziz-korkmazkurt-8ol3r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşam oluyor elde degil

Bu akşam başka akşam

Karanlik basmiyor aksamin böylesinde

Dolunay eşliğinde

Dilerim

Bu bahar bir baska düşe gir

Gözyaşların

Sığ ırmakların derinsuları olsun

Suskunluğun

Acık mavi denizin olsun

Gülücüğün

Sabah günesi gibi sevdiklerinin yüzüne vursun

Aşka gelip huuu diyen

Cömert olup sofrasını acan

Her dem muhabbet icen

Seni gönlünden hic cıkarmayan

Özü sözü bir

Gönül dostların olsun

Sönmeyen bir aşk ateşin

Hic eksilmeyen neşen

Saclarını okşayan

Menekşe kokulu rüzgarların

Gönlüne girmiş

Canını yoluna feda edecek bir sevgilin

Şiir gibi akan sözleri olsun

Zamanın yıpratamadığı özlemlerin

Kucaklanmış bir hayat

Yaşanmayı bekleyen yarınların

Sevda mavisi umutların olsun

Dertlere yudum yudum direnen

Yaşam hevesin

Hüznün perdesini yırtan

Coşkulu sevincin

Yüreğinin ovasında gezinen

Ceylanların

Firdevs mekanın olsun

Ey sevdiğim güzel dostum

Bu bahar bir baska düşe gir', 'Akşam oluyor elde degil Bu akşam başka akşam Karanlik basmiyor aksamin böylesinde Dolunay eşliğinde Dilerim Bu bahar bir baska düşe gir Gözy...', ARRAY['Türk Edebiyatı','Şiir','Aziz Korkmazkurt']::text[], 8.5, '{"poet":"Aziz Korkmazkurt","poet_slug":"aziz-korkmazkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/dilek-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşük  Cümle', 'dusuk-cumle-salim-diyap-10unx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ilkokullu bir çocuğun 

defterinden düşmüş bir cümleyim,

tut kolunu yeniden yazdır beni.

balıkçıyım, 

bu denizin mavisine gömülüş,

yapış yapışım tuzuna 

bu kısır kelimelerin.

bu gün de vermedi rızkımı sevdan. 

bir şiir bile yazamadım özlemine. 

oltalarım sözlerime batar habire benim. 

bir şiirin son hecesiyim,

öylesineyim işte!

mânâsız bulur her okur beni. 

yükle ne yükleyeceksen ses tonuma,

çağırabileyim seni 

ve her gideni

değeri bilinmemiş bir aşkın pişmanlığında

acılı bir söz 

sancılı bir cümleyim 

hatırlayanım yok 

sil beni', 'ilkokullu bir çocuğun  defterinden düşmüş bir cümleyim, tut kolunu yeniden yazdır beni. balıkçıyım,  bu denizin mavisine gömülüş, yapış yapı...', ARRAY['Türk Edebiyatı','Şiir','Salim Diyap']::text[], 8.5, '{"poet":"Salim Diyap","poet_slug":"salim-diyap","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dusuk-bir-cumleyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Umutlar', 'sari-umutlar-celal-sahin-w8rv3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir çift turkuvaz göz için

Zulada ki bir çuval zümrüttü terk edilen,

Göbek bağı diye çektiğin

Sevginin boynunda ilmekti fark etmedin.

Yabancı bir gülüş, alınca senden değerlerini 

Tersine akıtmaya çalışmak boşuna sevgi pınarını.

Ölümdür beklenen tek gözlü odada,

Renk cümbüşü duvara siyah perde çekilince.

Yüreğinde kurumuş aşk mürekkebi 

Sevdayı yazmak için dermansızsındır.

Tanrıya yakarışların nakarat halinde

‘Ya yanına al,ya bir şans daha’

En çaresiz anında, Çığlıklarını duyurabileceğin 

Bir bildik ararsın boş gözlerle

Tükenişine şahit olmaz sarı yapraklar.....

                     11.01.2005-

                       Ankara', 'Bir çift turkuvaz göz için Zulada ki bir çuval zümrüttü terk edilen, Göbek bağı diye çektiğin Sevginin boynunda ilmekti fark etmedin. Yabanc...', ARRAY['Türk Edebiyatı','Şiir','Celal Şahin']::text[], 8.5, '{"poet":"Celal Şahin","poet_slug":"celal-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sari-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tespihimin taneleri', 'tespihimin-taneleri-aydin-kansiray-75no6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Okuyormusun,

sana yazılan onca sözü anlıyormusun

onca aşka çizik çekmiş kalem ucu bu

tanıyormusun.

Bir yüzüm  var benim

bir adım oldugu gibi

ben yüreğini verene ihanet etmedim

seven gönüle yalan demedim.

Bilmezmisin ki ihanet sevgide başlar

bilmezmisin ki sadakat zor olanda başlar

Okuyamıyorum gerçekten aklından geçenleri

yazamıyorum sana söylemek istediklerimi

bak her yorgun göz şiir okuyor

ben bana bırakılan yetim seviyi avutuyorum

bak herkes sana bakıyor 

bak ben sende kaybolan sadakati uğurluyorum

bir teşekurde benden olsun,

bu şiirle elveda diyorum

.

12,12,2004-03:15', 'Okuyormusun, sana yazılan onca sözü anlıyormusun onca aşka çizik çekmiş kalem ucu bu tanıyormusun. Bir yüzüm  var benim bir adım oldugu gibi...', ARRAY['Türk Edebiyatı','Şiir','Aydın Kansıray']::text[], 8.5, '{"poet":"Aydın Kansıray","poet_slug":"aydin-kansiray","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tespihimin-taneleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi ki Doğdun', 'i-yi-ki-dogdun-aydin-kansiray-7br94', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni sevmek gibi hayata isyanlarım oldu

Ve seni beklemek gibi,

Tekrarlanan intiharlarım.

İki gün sonra doğum günün

Yanında olamayacağımı düşün

Farz et benim ölüm günüm

Farz et pastadaki mumum

Farz et gözündeki umudum

Farz et yeni yaşında ilk günüm

Beni affet, ben senin üzüntünüm.

.

Seninle aramızdaki aşk değilmiş

Sana göre tutku olsa da,

Bana göre en büyük isyanmış

En illegal pankartlar ikimize asılmalıymış

Sen, ben için içeri atılmalı

Ben, sen için  kurşuna dizilmeliymişim

Mezar taşım olmamalıymış

Üstüne seni yazmak yasak olmalıymış

Olmalıymış sevgili, olmalıymış

Senin için her gün ölmek

Boynumun borcu,

İnancımın farzı olmalıymış.

Senaaaa''ya', 'Seni sevmek gibi hayata isyanlarım oldu Ve seni beklemek gibi, Tekrarlanan intiharlarım. İki gün sonra doğum günün Yanında olamayacağımı düş...', ARRAY['Türk Edebiyatı','Şiir','Aydın Kansıray']::text[], 8.5, '{"poet":"Aydın Kansıray","poet_slug":"aydin-kansiray","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/iyi-ki-dogdun-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönmezmisin', 'donmezmisin-aydin-kansiray-ustzz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaç defa kaçacaksın daha

Kaç Gidişinin ardından ağlatacaksın çoçukluğumu

kaç.kaç, kaç...ma.! 

.

Yine Yıkılası bulutlara gömdün yüreğini

Her defasında, biliyorum zoru seçeceğini

Her defasında, kesip kesip bileklerimi

Biliyorum, ''''Arkamdan bir tas kan dök'''' diyeceğini.

.

Bak hele Gülüm; 

Yanında götürdüğün feryadımı ver

Sesimi Çocuklar duymasın.

.

Bak hele gülüm; 

Yollarına düşecek bir iz bırak

Sevdam acıktığında, Doyurmaya azık olsun.

.

Bak hele gülüm; 

Gidişin silah, dakikalar mermi

Boşalt şarjörünü, menzilinde öldür beni.

.

Aşkına ömrümü yaktığım yar,

Acıyı kitap yapıp ezberlettin, bilmezmisin.

Sevdasına, umudu hapseden yar,

Hasretini  çeken yerlerim acıyor, dönmezmisin.

.

(25.12.2004)', 'Kaç defa kaçacaksın daha Kaç Gidişinin ardından ağlatacaksın çoçukluğumu kaç.kaç, kaç...ma.!  . Yine Yıkılası bulutlara gömdün yüreğini Her ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Kansıray']::text[], 8.5, '{"poet":"Aydın Kansıray","poet_slug":"aydin-kansiray","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/donmezmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyam Ve Kabusum', 'ruyam-ve-kabusum-volkan-yoruc-0hq23', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Meğer yalanmışsın, şimdi anladım

Rüya olmanı dilerdim ben kendimce

Yahut bir anlık kabus

Şimdi  bakar olmuşum adımladığın yollara

Yüzümde yarım bir tebessüm edersin artık

Rüya olmanı dilerdim ben zannımca', 'Meğer yalanmışsın, şimdi anladım Rüya olmanı dilerdim ben kendimce Yahut bir anlık kabus Şimdi  bakar olmuşum adımladığın yollara Yüzümde ya...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ruyam-ve-kabusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canı Koru', 'cani-koru-oguzkan-bolukbasi-qtag9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kaç kişi cennetin kapısından kovulacağız

kaç kişi cehennemde boğulacağız

kim bilir

sen bilemezsin

insanın oğlu

ödül de

ceza da senin görevin değil

en büyük günahtır

yaratanın yerine karar vermek

kim iyidir

kim kötüdür bilmek

ilahi adalettir

yaratan bilir

sen

canı koru

nerede doğmuşsa doğmuş

kimin kızıymış

oğluymuş

sana ne

canı koru yeter ki

insan gibi

cananı koru', 'kaç kişi cennetin kapısından kovulacağız kaç kişi cehennemde boğulacağız kim bilir sen bilemezsin insanın oğlu ödül de ceza da senin görevin...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cani-koru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba Şiiri', 'baba-siiri-gokbu-yalcin-kaya-sxx1o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dün akşam yolda gördüm

bir sokak başında duruyordu

üzerinde kar beyazı bir elbise içerisinde

tebesüm içerisinde bana bakıyordu

koştukca uzaklaşıyordu

tuttukca kayboluyordu

o adam benim babamdı 

canımdan bir candı

aldılar onu benden aldılar

canımı canımdan ayırdılar

bir gece vakti bir telofon geldi

dedilerki baban öldü

kanım dondu gözlerim doldu

ağlamak istedim ağlayamadım

daha yaşı gençti

ne hayelleri düşleri vardı

neden aldın tanrım onu benden 

beni babamdan canımdan ayırdın

oadam benim babamdı 

canımdan bir candı

aldın onu banden aldın

alıpda ayrı koydun', 'dün akşam yolda gördüm bir sokak başında duruyordu üzerinde kar beyazı bir elbise içerisinde tebesüm içerisinde bana bakıyordu koştukca uzak...', ARRAY['Türk Edebiyatı','Şiir','Gökbu Yalçın Kaya']::text[], 8.5, '{"poet":"Gökbu Yalçın Kaya","poet_slug":"gokbu-yalcin-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/baba-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Ahh İstanbul', 'i-stanbul-ahh-i-stanbul-alaeddin-i-kican-7u57o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstanbul''un dünü bu günü.

     

İstanbul var ya İstanbul,

Taşı toprağı altın idi,

İstanbul ahh İstanbul,

Yaşanmaz orada şimdi.

Hanımı,beyi,efendisi,

Şarkılara konu olurdu,

Şimdi ise muhteşem adı,

Yaşayana korku saldı.

Vahşi batısı,Teksas''ı

İstanbul''um örnek aldı,

Kapkaççısı,tinercisi,

Sanki kentin sahibi oldu.

Sokaklar ağlıyordu sanki,

Balkonda çayımı yudumlarken demli,

Bir kadın sürükleniyordu,çantasında eli,

Islak kaldırım tek dostuydu,soğudu teni.

Gökyüzü dolu doluydu,ha döküldü,ha dökülecek,

Düşünüyorum hangi masum canlar silinecek,

Yanındaki eşkiyaya ses etmezse hiç bir zat,

Sıra kendine gelince beklemesin imdat.

Yollar,gökdelenler,taşıtlar,insanlar,

Gönlümdeki İstanbul''u yaşatmıyor,

Nerede kaldı hanfendiler,Beyfendiler,

İstanbul yok olur,içinde yoksa bunlar.

Gücü olmayan yaşayamaz diyorsun İstanbul,

Ama sevmeyen ölsün diyemiyorsun ya? 

Taşını,toprağını,suyunu,havanı seviyorum da,

Kalleşliğin,ahlaksızlığın,eşkiyalığın olmasa İstanbul.', 'İstanbul''un dünü bu günü.       İstanbul var ya İstanbul, Taşı toprağı altın idi, İstanbul ahh İstanbul, Yaşanmaz orada şimdi. Hanımı,beyi,e...', ARRAY['Türk Edebiyatı','Şiir','Alaeddin İkican']::text[], 8.5, '{"poet":"Alaeddin İkican","poet_slug":"alaeddin-i-kican","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/istanbul-ahh-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamadım', 'anlamadim-gulsen-goksu-2k8j0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen gülünce gönlüme baharlar gelir 

yüreğime bir heyecan sarardı

Gözlerimin içi dahi güler di 

Akşam olsa diye yolunu gözlerdim

Öyle zor gelir diki sanki saat hiç 

Çalışmıyor gibi bekler dururum...

Ama sen yine kızardın bana

Bense hep hata yapardım

Ama ben hala bilmiyorum sahi 

Suçum neydi benim

Hani şu telafisi olmayanı

Suçum seni sevmekti 

Cezamı çekiyorum işte

Varlığınla yokluğunun arasında

Seviyorum ama sevilmiyorum

Özlüyorum ama özlenmiyorum

Bekliyorum ama beklenmiyorum...

Hep hata yapıyorum

Acaba en büyük hatam neydi 

Seni sevmek? 

Dünyaya gelmek? 

Babasız olmak? 

Çaresiz olmak? 

Hangisi acaba......

  Söyleyecek misin......

09.04.2005

GÜLŞEN GÖKSU', 'Sen gülünce gönlüme baharlar gelir  yüreğime bir heyecan sarardı Gözlerimin içi dahi güler di  Akşam olsa diye yolunu gözlerdim Öyle zor gel...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Göksu']::text[], 8.5, '{"poet":"Gülşen Göksu","poet_slug":"gulsen-goksu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/anlamadim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedbaht', 'bedbaht-ali-gencay-4zyr9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saat sabah, daha er vakit uzuyor gölgem

Bu muyum ben, bu kadar mı cüssem

Başım ne kadar uzak ayaklarımdan eyvah! 

Yetişir mi başım başıma yüzükoyun düşsem

Avuntum yok, yalanlar kadar yalanım

Riyalar kadar ince gölgem kadar kabayım

Şafak atıyor şimdi var gör sabahlarımı

Dün bana candım, bugün el kadar yabanım

Saçlarımın arasından sızıyor güneş

Gölgemde saçlarım, bozkır çalılarına eş

Bir bozlak tutturup yaksam diplerinden

Geride bırakacağım ceset, oda kokmuş leş', 'Saat sabah, daha er vakit uzuyor gölgem Bu muyum ben, bu kadar mı cüssem Başım ne kadar uzak ayaklarımdan eyvah!  Yetişir mi başım başıma yü...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bedbaht-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Okul Çocuğuydu', 'i-lk-okul-cocuguydu-mehmet-emin-yesilmen-bd399', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İlk okul çocuğuydu.

Öğretmeni kafasından vurulan,

Çocukların bakışları altında.

Ağladı, ağladı ve ağladı yine çocuk...

Eğitimsiz kalan doğu çocukları dediler.

Psikolojileri altüst olmuş,

Yıllarca hafızalarından silinemeyecek olaylarla.

İlk okul çocuklarıydı...

Eve koşup anasına sarılan,

Öğretmenim vuruldu çığlığıyla,

İsyancıl bir ağlamayla,

En doğuda bir ilk okul çocuğuydu...

Bilmezdi gerilla, hizbullahı.

Tanımazdı pastelle guaş boyayı.

Ama çizerdi

Kara kalemle

Kırmızı olan kanı.

Bilir tanıklık eder ölüme

Ödün vermeden cesaretinden...', 'İlk okul çocuğuydu. Öğretmeni kafasından vurulan, Çocukların bakışları altında. Ağladı, ağladı ve ağladı yine çocuk... Eğitimsiz kalan doğu ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Yeşilmen']::text[], 8.5, '{"poet":"Mehmet Emin Yeşilmen","poet_slug":"mehmet-emin-yesilmen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ilk-okul-cocuguydu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağustosta Üşüyorum', 'agustosta-usuyorum-bayram-celikel-49o94', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün günlerden pazar

Ağustos''un onbiri

Ben üşüyorum

Ağustosta üşürmü insan? 

Yollarına barikatlar kurmuştum

Yapabilsem prangalar vuracaktım ayaklarına

Yapamamıştım, tutamamıştım seni

Belki bu yüzdendir Ağustosta üşümem

Sokak lambaları altında sabahlarken

Sizin evin sokağında

Ve üzerimde senden kalma bir sevdanın yorgunlu

Ve küskünlüğü varken hayata

Ve herses seni çağrıştırırken bana

Saat hep sensizlikken 

Ya sensizliğe beş yada sensizliği beş geçiyorsa hep 

Bu yüzdendir belki Ağustosta üşümem

Ellerim kendiliğinden uzanıyorsa telefon''a

Her telefon çalışı sen olma umuduyla koşarken 

Senin olmayışının hayal kırıklığını yaşarken

Ve senin olmayışını bilmek bu yerlerde

Tükendiğimi hissetmekten''dir belki

AĞUSTOSTA ÜŞÜMEM', 'Bugün günlerden pazar Ağustos''un onbiri Ben üşüyorum Ağustosta üşürmü insan?  Yollarına barikatlar kurmuştum Yapabilsem prangalar vuracaktım...', ARRAY['Türk Edebiyatı','Şiir','Bayram Çelikel']::text[], 8.5, '{"poet":"Bayram Çelikel","poet_slug":"bayram-celikel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/agustosta-usuyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat', 'vuslat-nihat-malkoc-7kagw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tarûmar etti bahçemi tez gelen rüzgâr

Yapraklar dalında misafir artık

Baharın buruk merasimi var

Ezel,ebed libasını giyinir artık

Batan güne karşı tutunamadık

İmkânın yolları kapalı artık

Zirvenin ucunda çaresiz kaldık

Vakit heyecanlı,tasalı artık

Hükmedemedik zamana,esiriz şimdi

Emaneti sahibi istiyor artık

Açmış sinesini ervah denizi

Elinde bir kırmızı gül  “gel”  diyor artık.', 'Tarûmar etti bahçemi tez gelen rüzgâr Yapraklar dalında misafir artık Baharın buruk merasimi var Ezel,ebed libasını giyinir artık Batan güne...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/vuslat-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşümdeki Sen', 'dusumdeki-sen-nihat-malkoc-2jk8h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine düşümde dalgalandın dün gece

Lapa lapa yağdın uykularıma

Zonklattın beynimi

Şifreli yolların kavşağında

Bir nehir gibi aktın rüyalarıma

Sırılsıklam oldum amansızca

Şimşek oldun,yaktın yüreğimi

Durdurdun saatleri zamanın inadına

Siliverdin pembe sayfalara

Yazdığımız kadife yazıları

Üşüttün,buz kestin duygularımı…

Hatırlattın o titrek dakikaları

Esirgedin bir katre ab-ı hayatı

Çok katı yüreklisin sen çok

Hani altın harflerle yazmıştık

Aşkımızın hikâyesini…

Nerde ettiğin bunca vaatler? ...

Viraneye çevirdin hayatımı

Nereden çıktı bu zamansız ayrılık? 

Neden gözyaşınla sildin adımı? ...', 'Yine düşümde dalgalandın dün gece Lapa lapa yağdın uykularıma Zonklattın beynimi Şifreli yolların kavşağında Bir nehir gibi aktın rüyalarıma...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dusumdeki-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-nihat-malkoc-zvgh4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gurbet ilde yine akşam oluyor

Tutkulu gözlerim kan yaş doluyor

Al yanağım yaprak gibi soluyor

Bu uzak ilde sılayı anarım

Kaplıyor içimi bir hasret seli

Tılsımlı dağların geçitsiz beli

Tesellim yalnızca aşk-ı ezelî

Sevgimi ulu makama sunarım

Sarmış kara,mağrur bulut illeri

Bizden apayrı,bir başka dilleri

Bülbüle naz eder solgun gülleri

Vatan aşkıyla her lâhza yanarım

Gurbet ilde duman yüceden inmez

Dosttan ayrılanın gözyaşı dinmez

Memleket hasreti ebedî sönmez

Ekmeğimi her gün tuza banarım

Sineme ayrılık közü düşeli

Yârândan uzakta olmuşum deli

Leylâ’yı arayan Mecnun misali

Yalan yanlış haberlere kanarım

Burda sitem yüklü yanık türküler

Hançere dönüşür bağrımı deler

Dile gelerek konuşur gölgeler

Sanki temmuz sıcağında donarım

Konuşsam da kimse anlamaz beni

Yüzdürmek mümkün mü sahrada gemi? 

Ne kadar mutlu görsem de kendimi

İnsanlar içinde yalnız sanarım

Vakit geçer,bir gün sıla görünür

Gönlüm aşka,muhabbete bürünür

Başım ta göklere kadar sürünür

Yurdumun ak toprağına kanarım', 'Gurbet ilde yine akşam oluyor Tutkulu gözlerim kan yaş doluyor Al yanağım yaprak gibi soluyor Bu uzak ilde sılayı anarım Kaplıyor içimi bir ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gurbet-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin-3-', 'gelin-3-abdullah-atay-9gna2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hasretlik çeker gelin 

gözyaşı döker gelin 

yari gurbete gitmiş 

yollara bakar gelin... 

bahçeye çıktı gelin 

seslendim baktı gelin 

koparıp gonca gülü 

göğsüme taktı gelin 

bir bakış baktı gelin 

yüreğim yaktı gelin 

gözleri pınar olup 

içime aktı gelin... 

bağıma geldi gelin 

gül verdim aldı gelin 

meramı gül değilmiş 

benimle kaldı gelin... 

yoluma durdu gelin 

yarini sordu gelin 

‘yarin gitti’ deyince 

kendini vurdu gelin... 

ay gelin çengi gelin 

gönlümün dengi gelin 

aşkınla küle döndü 

yüzümün rengi gelin... 

dağlarda gezen gelin 

zülfünü çözen gelin 

bir hayırsız yüzünden 

gönlünü üzen gelin... 

ay gelin,akça gelin 

elleri pakça gelin 

zalım anan duymadan 

gel bize sıkça gelin..', 'hasretlik çeker gelin  gözyaşı döker gelin  yari gurbete gitmiş  yollara bakar gelin...  bahçeye çıktı gelin  seslendim baktı gelin  koparıp...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gelin-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlarsın', 'anlarsin-mehmet-dag-pwqwt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hanı anlarsın müzikten

Çalarsın önünde piyanonda var

Notayı da biliyorsun

Besteni güfteni kendin yapar

Mezar taşıma da istediğini yazarsın

İşine geldiğinde 4/4 lük adamdı der

İşine gelmediğinde 

Sıfır bile etmezdi sahtekar

Deyip  matematikte yaparsın

Arada  bir felsefe yapmayı da unutma

Materyalizmi, İdealizmi  neyse yanı

Metafiziğe bulaştırma beni

Uğraşamam O hayali şeylerle, bilirsin zaten

Bak bir keman çalıyor arkamda birisi

İşinin ehlisi

Beynime ayar çekiyor doğrusu

Sanki 40 kişilik bir senfoni orkestrası

Bütün derslerin akıl hocası 

belki de Hayyamın son nefesi

Tam sırasıdır şimdi 

Estir bir Edebiyat havası 

Onsuzda olmaz ki

öznesini yüklemini teyet geç

Müstehcen yanlarına da gir Fuzuli misali

Şarabı da unutma bir kenarda

Sarhoş halime de yer ver

 İçmeden tabii

Şiiri sevdiğimi de söyle

Derinliğine girme fazla

İmgesine,vurgusuna  azıcık dokun yeter

Sanattan anladığımı da söyleme

Zor iştir sanattan anlamak

Bir içimde olsa damlada içmek lazım 

50 km hızla  gidiyorum

 Hala zerresini yakalayamadım sanatın

Sadece güzel kadınla tanıştığımda 

Sanat eseri gibisin derim

Bak Coğrafyayla uğraştığımı söyle

Köyleri,Kentlerin üzerine yıkardı

Kentleri de Memleketlerin 

Gezegenleri bir birine bağlayıp 

Trencilik oynardı 

Kültürlerden hamur yapıp 

Açlara gönderirdi de 

Bu arada sakar biri olduğumu da bilsinlerdi

Siyaseti Ekonomiye bağlardım

Onu da politikacılardan saklardım 

Bırakın torunlarım ne abdal dedemiz 

                                       Varmış desinler

Ama cahil etmesinler ne olur

Çünkü çok çektim onlardan

Bütün bodrumlardan  geçtim

En iyi Nazımı gördüm dar geçitlerde

Otu da yedim Samanı da

Bazıları bana insan değeri vermedi

Bende onlara hayvan bile demedim

Yazık olurdu hayvanlara

                 Haksızlık ederdim

Bak yine güzel sesli bir bayan 

Şarkı söylüyor

Gözleri kırpık,kırpık, elleri açık

Serçe gibi çırpınıyor

Piyanonun başında

Ritim karışık

Kendime benzetiyorum müziği

Çoğu kavgalı azı barışık

Ve yaşarken hep yarıştık

Bilim adamları gibi değil

Kürek mahkumları gibi                       

Çokta şikayetçi değilimdir 

Olsam  da ne yazar......... ancak

Ot gibi yaşamakta bir şey değil

Hoşça kalın diyorum 

Her zaman ki gibi değil

Bir daha gelmiyorum

Bilesiniz her ne kadar da 

          anlamadıysanız beni

Ben de çok beklemedim

                   anlamanızı hanı

Yinede seviyorum hepinizi

Bir daha hoşça kalın 

Daha, daha hoşça kalın

Kardeşçe kalın

(Avcılar)', 'Hanı anlarsın müzikten Çalarsın önünde piyanonda var Notayı da biliyorsun Besteni güfteni kendin yapar Mezar taşıma da istediğini yazarsın İ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dağ']::text[], 8.5, '{"poet":"Mehmet Dağ","poet_slug":"mehmet-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/anlarsin-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şanssızlık', 'sanssizlik-ayse-birgul-yilmaz-njwz3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karşıma senin gibi birisi çıkmadı

Hiç kimse böyle sevgiyle bakmadı

Ateşin öyle yaktı ki kül bırakmadı

Diyeceğim,

Ninni dinler gibi annemin şefkatli sesinden

Tatlı dilinden sevgi sözcükleri şelalesinden

Duygulu kelimelerin şırılıtısında, kollarında

Güvenle sarılabileceğim,

Huzur dolu sesinin fısıltısında başım omzunda

Rüyalara dalacağım ve tutkuyla bağlanacağım

Yavru kedi gibi dizi dibinden ayrılmayacağım

Yanımdayken bile özleyeceğim,

Ayrılık korkusu yaşamayacağım 

Kıskançlıktan çıldırtacağım,

Coşkuyla kapılarda bekleyeceğim, 

Çok sevileceğim hep seveceğim...

Birisi hiç olmadı... birisi olmalı...

09.05,2005', 'Karşıma senin gibi birisi çıkmadı Hiç kimse böyle sevgiyle bakmadı Ateşin öyle yaktı ki kül bırakmadı Diyeceğim, Ninni dinler gibi annemin ş...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sanssizlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçim Ağlar Ben Ağlayamam', 'i-cim-aglar-ben-aglayamam-gozde-hatiboglu-m1vuc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günün en kuytu saatleridir gündönümünden sonrakiler. 

Gece; sessizlikle ve karanlıkla kol koladır. 

Yalnızlığın boğazına yapıştığı olur. 

Yastık yorgan düşmandır sanki ve bölük uykularda sorgulanır yapılan yanlışlar.

Regresif bir tutumla sığındığın yatağın savunmasız bıraktığı ortadadır. 

İnadına kapatırsın gözlerini, acır göz kapakların. 

Uyur uyanık bir halde geceye isyankarsın. 

Düşünceler ve düşlemler birbirine girmiş, yaşanmış zamanlar tekrarlarken   her seferinde yeni senaryolarla oynanır. 

Her şey tamam olduğunda tek boşluk aşk kalır. 

Aşk..artık sözlük anlamını bile kavrayamadığındır. 

Aşk..bunca biriktirilenlerden sonra kalan ağırlıktır. 

Doğruların değişiyor ve aşka yakın olmaktan korkarken, nesne ilişkilerini   öfkeyle sorguladığındır. 

 İnpulsif çıkışlar yerini dinginliğe bıraktığında, gözlerimiz değince oluşan   parıltıdır aşk belki şimdilerde. 

 Sana dair yürekten geçenler, korkular tarafından alı konulduğunda, günler takvim yapraklarından düşerken ve biriken duygular bir arpa boyu yol gidemeyişle yüzleştirdiğinde, harekete geçmeli diyendir belki de aşk demeye çalıştığım. 

Her neyse yaşanan, şimdi fark ediyorum ki hayatın gerisinde bırakıyor. 

Onca şey olmasına rağmen birlikte yarattığımız, baksan yıllar geçmiş algısı uyandıran aslında koca bir yokluktan ibaret. 

Sevmeye çabaladığım şeyler boşlukta asılı duruyor. 

Ötekinden emin olmak ve her baktığında bulmak sanırım özelliği yok eden.

Kıymet bilmek uzaklık ve kayıpla başlıyor.

Şimdi sana dair her söylemim noktalı virgülle kesilmiş. 

Bağlaçlarımdan sonraki anlamlar aynı. 

Bitirebilmek için başlamış olmak lazım sevgili. 

Öyle bir yerde duruyorum ki şimdi; 

Arzularımla çatışarak gideceğim yada küçük harflerle sessizlikte bekleyeceğim.

İlişkiler mesafelerle sınanır bilir misin?

Yaşadığımızı sandığımız şeyin gerçekliği şimdi uzaklıkla sınanmada

Kalırsan; zamanın tuzaklarına rağmen, sağlam attığımız temellere yeni duygular eklenir.

Gidersen; göz yaşlarımı görmediğin için üzülme 

İçim ağlar, ben ağlayamam yitirilenlere..

(4.mart.2005)', 'Günün en kuytu saatleridir gündönümünden sonrakiler.  Gece; sessizlikle ve karanlıkla kol koladır.  Yalnızlığın boğazına yapıştığı olur.  Ya...', ARRAY['Türk Edebiyatı','Şiir','Gözde Hatiboğlu']::text[], 8.5, '{"poet":"Gözde Hatiboğlu","poet_slug":"gozde-hatiboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/icim-aglar-ben-aglayamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklıköy', 'saklikoy-i-shak-ozlu-sils7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Keder girdabında nefessiz duygularım,

Bogulurken İstanbul sokaklarında.

Özgür bıraktı ruhumu,kaygılarım.

Saklıköy''ün giz yüklü odalarında.

Çimenin koyu yeşilinde gözlerin,

Saka kuşunun ötüşünde sözlerin,

Sardı benligimi akşamın ufkunda,

Binicisiz tay''ın yelesinde rüzgarın.

Menekşede gizli neşeli gülüşün,

Kelebeğin kanadında göz kırpışın,

Yalnızlık duygumdan eser bırakmadı.

Dag kokularında odama doluşun.', 'Keder girdabında nefessiz duygularım, Bogulurken İstanbul sokaklarında. Özgür bıraktı ruhumu,kaygılarım. Saklıköy''ün giz yüklü odalarında. Ç...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/saklikoy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamaklıyım', 'aglamakliyim-serpil-dilsener-4iiyn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensizlik ölüme benziyor,

Tadı tuzu yok hiç birşeyin,

İçini çeken gökyüzü gibi,

Ağlamaklıyım her an.

Halbuki biliyorum,sözün sözdür,

Geleceğim diyorsun,ama ne zaman? 

Hiç açelen yok,telaşın yok,

Keyfe keder sevdan.

Ah tahammülüm yok ki sabredecek

Sen diye inlerken tenimin her zerresi

Gücümmü kaldı arzuma hükmedecek,

Bugün gelsen ne olur sanki,

Yarına kalmam ölürüm belki.', 'Sensizlik ölüme benziyor, Tadı tuzu yok hiç birşeyin, İçini çeken gökyüzü gibi, Ağlamaklıyım her an. Halbuki biliyorum,sözün sözdür, Geleceğ...', ARRAY['Türk Edebiyatı','Şiir','Serpil Dilşener']::text[], 8.5, '{"poet":"Serpil Dilşener","poet_slug":"serpil-dilsener","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aglamakliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Aşk Sen Delisin', 'ey-ask-sen-delisin-bekir-mutlu-gokcesu-d8wf1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey aşk

Sen delisin

Benden deli

Bırak ellerimi

Seyredemeyeceğim

Ve durduramayacağım

Allah korusun seni

Ben çoktan

Kapadım gözlerimi...', 'Ey aşk Sen delisin Benden deli Bırak ellerimi Seyredemeyeceğim Ve durduramayacağım Allah korusun seni Ben çoktan Kapadım gözlerimi......', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ey-ask-sen-delisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoş Geldin Bebeğim', 'hos-geldin-bebegim-adulera-ayza-b065q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hoş geldin bebeğim

Ağrılı uzun süren bir sancının ardından

Hoş geldin bebeğim

Sana yazacaklarımı bir nasihat olarak algılama

Hayat eğer yaşanmaya değer olsa idi

Ne şimdi bu ağlama

Farkına vardın demek ki o yüzden bu ağlama

Geç geldin bebeğim 

Geç geldin bu zamana

Ne çağına geldiğini bende bilmiyorum

Kimine göre uzay bana göre

Geç geldin bu zamana

Teknolojin olacak elbet

Kimsenin bilmediklerini öğrenerek başlayacaksın hayata

Elbet sekreterin olacak haber veren elektronik zamana

Seninde sevgilin olacak gerçek değil sanal hayatta

Senin de düşlerin olacak bir mp3 çalarda

Uzay çağındasın ya anında herkes olacak yakınında

Seni doğuranlar bizler öleceğiz

Ama bir tuş kadar olacağız yanında

Bizlere bakıp güleceksin ilkel diyeceksin ekranda

Seveceksin 

Terk edeceksin hissedeceksin

Bileceksin

Ama bizim bildiklerimizi değil

Teknoloji denen o zalim canavarlarla

Ne zaman sevineceksin

Biliyorum

Son tuşa bastığında klavyene 

Milyon dolar kazandığın zaman

Ne zaman üzüleceksin

Biliyorum son tuşa basamadan

Elektrikler kesilince

Ne zaman kızacaksın biliyorum kendine

En son teknolojiye yetişemedim diye

Hal bu ki biz seni dünyaya getirmeden önce

Elektrikler kesilince sevinirdik

Hal bu ki biz kavga edince üzülürdük

Biz seni dünyaya getirmek için bir elektrik kesilince

Karar verdik

Biz dünyayı siz yeni nesillerden 

Daha çok sevdik

Zaman geçer bilesin diye yazıyorum

Senden sonraki nesilde seni eleştirecek biliyorum

Doğanın kanunu bu saygı duyuyorum

Ama bebeğim

Bir nazımı bir Erol Taşı bir ayrılığın gözyaşını

Bir bayrak sevgisini bir Fener bahçeyi

Bir Demirel i   bir s a i d   nur si yi

Bir   ö c ü k   timi

Bir Rıdvan Dilmeni

Lef ter i

Yazıp sildiğimiz lise defteri

Sadri Alışık ı

Hatta tahta kaşığı

Can yücel i

Kızıp ta değiştiremediğin kaderi

A g o p un meyhanesini

Musa E r o ğ l u n u n telli turnasını

Laik bir ülkede türban yasasını

Yalanlarına inandığımız k a f dağının arkasını

V e l hasıl  her on yılda bir değişen Türkiye anayasasını

Bilmeni isterdim

Hoş geldin bebeğim

Geç geldin', 'Hoş geldin bebeğim Ağrılı uzun süren bir sancının ardından Hoş geldin bebeğim Sana yazacaklarımı bir nasihat olarak algılama Hayat eğer yaşa...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/hos-geldin-bebegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter Artık!', 'yeter-artik-kadir-soyturk-mu8y8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeter artık! yağmaya sorumlular '' dur '' desin; 

''Adalet! hainlerden  bir bir hesap sor '' desin

Bu milletin malını kimler çar - çur ettiyse

Gözyaşına bakmayın; kuruş kuruş ödesin!', 'Yeter artık! yağmaya sorumlular '' dur '' desin;  ''Adalet! hainlerden  bir bir hesap sor '' desin Bu milletin malını kimler çar - çur ettiyse G...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yeter-artik-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can çıkar da huy çıkmaz', 'can-cikar-da-huy-cikmaz-mikdat-bal-6vut2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Topraktan yaratıldım, topraktandır temelim

Toprak toprak üstüne, yine ona gömelim

Afakı hayalimin,ötesinde emelim

Can çıkar da huy çıkmaz, insan dünyadan bıkmaz

Vücudum iki nefes arasında mahkümdur

Ölüm Alla’ın emri,değişmez bir hukümdür

Her canlı tadacaktır,bu gerçek bilumumdur

Can çıkar da huy çıkmaz, insan dünyadan bıkmaz

Dünya yı kovaladım, ancak kendimi yordum

Kendime güvenirdim, gençliğim var diyordum

İş işten geçti artık, heyhat gerçeği gördüm

Can çıkar da huy çıkmaz, insan dünyadan bıkmaz

Çalıştım, çabaladım, bütün zahmetler boş’a

Yordu beni bu dünya, peşinden koşa koşa

Bilirim kalacağım  amelimle baş başa

Can çıkar da huy çıkmaz, insan dünyadan bıkmaz

Oturup da düşünsem, acaba nasıl kulum? 

Hazırlanmam gerekli, aniden gelir ölüm

Ne kadar da yaşasam, oradan geçer yolum

Can çıkar da huy çıkmaz, insan dünyadan bıkmaz

Mikdat der ki dünyadan koptum, o benden kopmaz

Yaşamanın bedeli, eller sena iş yapmaz

İnsan çalışsın dursun, nasipten fazla kapmaz

Can çıkar da huy çıkmaz, insan dünyadan bıkmaz', 'Topraktan yaratıldım, topraktandır temelim Toprak toprak üstüne, yine ona gömelim Afakı hayalimin,ötesinde emelim Can çıkar da huy çıkmaz, i...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/can-cikar-da-huy-cikmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gidiyorum', 'ben-gidiyorum-muhammed-gacar-cmd0b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eskiden şarkıların bir anlamı vardı. Her şarkı bana yazılmıştı sanki. Baktığım, gördüğüm, duyduğum her şeyde bir güzellik, her güzel şeyde de sen vardın. Artık sen yoksun. Ne şarkılar benim içinmiş ne de her güzel şeyde sen varmışsın. Güzel şeyler, güzel şarkılar yine var ama bu sefer içinde sen yoksun. Artık kendime döndüm. Güzel şeyleri güzel yapan benmişim meğer. Aslında sen de güzel değilmişsin, seninle güzel geçinmemişiz. Her şeyi güzel gören  benmişim. Senin olduğun her şeyi güzel gören, güzel görebilen ben isem,  sen yokken, senin olmadığın şeyleri de daha da güzel görebilecek yine benim. Hayat devam ediyor. Seninle de zaman geçiyordu sensiz de geçiyor. Bu yüzden hiç üzülmüyorum. Kusura bakma… ben gidiyorum…', 'Eskiden şarkıların bir anlamı vardı. Her şarkı bana yazılmıştı sanki. Baktığım, gördüğüm, duyduğum her şeyde bir güzellik, her güzel şeyde d...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Gacar']::text[], 8.5, '{"poet":"Muhammed Gacar","poet_slug":"muhammed-gacar","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/ben-gidiyorum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümün baharı', 'omrumun-bahari-mikdat-bal-kilq8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ömrümün baharı ve de yazını

Ağladım hepsinde, güldüm azını

Bir boğaz uğruna Of boğazını

Genç yaşta terkettim yaşarım burda

Bu hayatım bana kurdu çok tuzak

Ne bahçem var, ne çayırım, ne sazak

Sevdiğim ne varsa,hepsinden uzak

Dünyamı Mark ettim koşarım burda

Gençlik elden gitmiş,kafam sulanmış

Diz bağım çözüldü, ayak dolanmış

İstikbal düşündüm, hepsi yalanmış

Sonunda farkettim şaşarım burda

Kim dikkate alır benim çağrımı

Hasretlik acısı yaktı bağrımı

Erkekler ağlamaz derler, doğru mu? 

Yaşımı ark ettim boşarım burda

Hasret zirvesinden inmem zor benim

Yandım da kor oldum, sönmem zor benim

Temelli olarak dönmem zor benim

Meçhule çark ettim koşarım burda

Mikdat der sormayın,yolun sapa mı? 

Özlerim soyumu hem akrabamı

Nefsimi, neslimi, anne babamı

Hasrete gark ettim yaşarım burda', 'Ömrümün baharı ve de yazını Ağladım hepsinde, güldüm azını Bir boğaz uğruna Of boğazını Genç yaşta terkettim yaşarım burda Bu hayatım bana k...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/omrumun-bahari-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Mektup', 'son-mektup-muhammed-gacar-e03l6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün gece bana yazdığın son mektup geçti elime. Mektupta yazdıkların her zamanki gibiydi. İçinde biraz hasret, biraz umut, biraz mutluluk, bir parça sevgi vardı. En son çektirdiğin fotoğrafı da koymuşsun zarfa. Her zamanki gibi çok güzelsin. Hiç değişmemişsin. Ama bende bir gariplik var bugün. Okuduğum her satırda bir hançer saplanıyor sanki kalbime. Göz yaşlarıma engel olamıyorum. Sel olup akıp gidiyorlar. Seni çök özledim ondan mı acaba? Yoksa seni bir daha görememe gerçeği mi? Kendime şaşıyorum. Bitkin bir haldeyim, yıkılmış bir durumdayım, ama elimde bir kalem bir kağıt oturmuş sana mektup yazıyorum. Bu mektubun sana ulaşamayacağını bile bile üstelik. Belki de bana bu gücü veren son umut parçasıdır. Belki de seninle aynı kaderi paylaşabilme isteğidir bu. Kim bilir belki bende senin gibi, sana bu mektubu yolladıktan sonra, eve dönerken bir trafik kazası geçireceğim ve orada can vereceğim. İşte senden bana kalan son ve tek umut parçası bu.

İzmir, 2003', 'Dün gece bana yazdığın son mektup geçti elime. Mektupta yazdıkların her zamanki gibiydi. İçinde biraz hasret, biraz umut, biraz mutluluk, bi...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Gacar']::text[], 8.5, '{"poet":"Muhammed Gacar","poet_slug":"muhammed-gacar","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/son-mektup-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Şikayetname 9 / Çaresiz...', 'sikayetname-9-caresiz-naime-erlacin-igk9a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'intihar kuşları ötüyor beynimde

ense kökümde 

migrene dönüşecek 

o ağrı yuvalanıyor yine

neden böyle acıyor gözlerim

evsiz bir çocuğun 

sessiz çığlıklarına takıldım

ondandır 

kâr etmiyor zırvalama 

ve delilik

ah çaresizlik

ah çare-sizlik! 

(9 Nisan 2005) 

(''ŞİKÂYETNAME'', Hayal Yay. Temmuz 2010, Sayfa 62)', 'intihar kuşları ötüyor beynimde ense kökümde  migrene dönüşecek  o ağrı yuvalanıyor yine neden böyle acıyor gözlerim evsiz bir çocuğun  sess...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sikayetname-9-caresiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Şikayetname 10 / Lokma', 'sikayetname-10-lokma-naime-erlacin-bgxmx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kırbaçlandı yüreğim deli mor ah! 

parçalarım dökülüyor

yaralarımdan izle beni 

nafile öpücükler bırak kesiklerime

insana küsüyorum ben 

anam 

babam 

dostum 

arkadaşım

viran bir ağlama duvarına sürüldünüz şimdi

sizin için kanıyor harap mevzilerde

sizin için paralıyor kendini taşlar

gökyüzünü arama bakışlarımda

adres sorma hiç

neşter atılmış derin çıbanların 

ağır kokusunda yudum urbamı

iz bilmez muhacire döndü gözlerim

küsüyoruz şiire

ben ve yosunlaşmış insan tiryakiliğim

çılgın tayların koştuğu çayır çimen 

göğsümde sararıyor ay yere düşerken

bir nankörlük vardı

bir de vefasızlık 

çiğneyemediğim

ağzımda büyüyor lokma 

(9 Nisan 2005) 

(''ŞİKÂYETNAME'', Hayal Yay. Temmuz 2010, Sayfa 54)', 'kırbaçlandı yüreğim deli mor ah!  parçalarım dökülüyor yaralarımdan izle beni  nafile öpücükler bırak kesiklerime insana küsüyorum ben  anam...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sikayetname-10-lokma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Sabah Mutlu Olmak İçin Uyanırım', 'her-sabah-mutlu-olmak-i-cin-uyanirim-muhammed-gacar-3nuqo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneş dün akşam gizlendiği gibi bu sabah yine ortaya çıkıyor. Tüm güzellikleri yeniden görmemiz için her yeri aydınlatıyor. Bende yeni bir güne başlarken sadece güzellikleri görmek için uyanıyorum. 

Yanımda sen yoksun. Yine sensiz bir gün başlıyor. Aslında kendimi üzmem için sebep çok ama mutlu olmam için daha fazla sebep var. Belki şu anda yanımda sen yoksun, belki çok uzaklardasın ama unutma ki her zaman gönlümde hayalimdesin. Ben nereye gidersem hayalin hep benimle birlikte. Onunla dertleşiyorum, onunla şakalaşıyorum, onunla hayal kuruyorum. Günlerce, aylarca, yıllarca birbirimizden ayrı kalsak ta hayalin bana can yoldaşı oluyor. Yani senin hayalin bile beni mutlu etmeye yetiyor. Hayalin beni bu kadar mutlu edebiliyorsa sana kavuşacağım o gün hissedeceğim saadeti düşünemiyorum bile. 

Her sabah güneş doğduğunda, yeni bir güne başlarken sana kavuşacağım o günü düşünüyorum ve mutlu oluyorum. Üstelik bu günün öldüğüm gün olduğunu bilmeme rağmen.', 'Güneş dün akşam gizlendiği gibi bu sabah yine ortaya çıkıyor. Tüm güzellikleri yeniden görmemiz için her yeri aydınlatıyor. Bende yeni bir g...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Gacar']::text[], 8.5, '{"poet":"Muhammed Gacar","poet_slug":"muhammed-gacar","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/her-sabah-mutlu-olmak-icin-uyanirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Şikayetname 11 / Bilmece! ...', 'sikayetname-11-bilmece-naime-erlacin-1dmw0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ne zamandı adım

ne mevsim

acıklı bir 

yol hikâyesiydim

içinden Nil geçen kadın

öyküsü avazında gizli

ay ışığına tutuklandıkça su

tek yönlü akış bozkırda

isyanın dirilişi 

çiçekleri yoktu uçurumların

uçurumlar aslında 

uğramamıştı oraya

sazlıklardan yükselen 

iğdiş edilmiş 

son çığlıktı nefesim

bir bilmece

çözemediniz heyhat! 

izninizle

(9 Nisan 2005)

(''ŞİKÂYETNAME'', Hayal Yay. Temmuz 2010, Sayfa 117)', 'ne zamandı adım ne mevsim acıklı bir  yol hikâyesiydim içinden Nil geçen kadın öyküsü avazında gizli ay ışığına tutuklandıkça su tek yönlü a...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sikayetname-11-bilmece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum Ve Çocuğum', 'cocuklugum-ve-cocugum-muhammed-gacar-4tkdj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geçen akşam çayımı demledim ve eski fotoğraf albümlerini karıştırmaya başladım. Her fotoğrafta yine o günlere gittim ve o anı yeniden yaşadım. Sıra bebeklik fotoğraflarına gelince içim bir hoş oldu. O günleri hatırlayamıyordum. Neler yapardım, ne yer ne içerdim, nasıl konuşurdum hiçbir şey bilmiyorum. Aklıma bir fikir geldi. Belki bir hayalden öteye geçemeyecekti ama düşünmesi bile eğlenceliydi. 

Bir zaman makinesi yapsam içine binsem ve o günlere ışınlansam diye düşünmeye başladım…

Fotoğraflardaki mekanlarda yıllar öncesinde dolaşıyorum şimdi. Ben küçükken oturduğumuz evin önüne geldim. Evin bahçesinden bir çocuk sesi geliyor. Bahçenin kapısını açıyorum ve içeriye giriyorum. Yemyeşil çimleri çevreleyen rengarenk çiçekler arasında, ağaçların gölgesinde  oyuncak arabamla oynuyorum. Gözlerim doluyor. Ona, yani çocukluk halime koşuyorum. Onu kollarımın arasına alıp sımsıkı sarıyorum. Defalarca öpüyor, kokluyorum kendimi. Kalbim delice çarpıyor, tarifi imkansız duygular içindeyim. Kendimi bu kadar sevdiğimi bilmiyordum… 

Bu hayalden uyanınca aslında bunların imkansız olmadığını düşünmeye başladım. İleride benim de bir çocuğumun olabileceğini ve onu kendimden çok sevebileceğimi düşündüm ve o mutlu günleri beklemeye başladım...

Isparta, 2003', 'Geçen akşam çayımı demledim ve eski fotoğraf albümlerini karıştırmaya başladım. Her fotoğrafta yine o günlere gittim ve o anı yeniden yaşadı...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Gacar']::text[], 8.5, '{"poet":"Muhammed Gacar","poet_slug":"muhammed-gacar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cocuklugum-ve-cocugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Görünmeyen Yüzü', 'askin-gorunmeyen-yuzu-osman-turkmen-h4g9c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk din, dil, ırk, mezhep ve görüş tanımaz! 

Çünkü, sevgilerin önüne set çekmek,

		asla olmaz! 

Yüreğimde bir çiçek olsan,

			o çiçek hiçbir zaman solmaz! 

Bu dünya ne sana, ne de başkasına,

	sonsuza kadar kalmaz! 

şehvetin, kahpeliğin ve kalleşliğin olduğu yere,

				benim yolum çıkmaz! 

İçtenlik ve de samimiyet varken,

Dürüstlüğün yorgun masumiyeti, 

	gözlerine vururken,

		görünmese de dilim yalana dönmez! 

Bir ben ağlarım sana,

	bir de doğuran,

		başka kimse ağlamaz! 

ve beni senden başka kimse,

			ama kimse anlamaz!', 'Aşk din, dil, ırk, mezhep ve görüş tanımaz!  Çünkü, sevgilerin önüne set çekmek, 		asla olmaz!  Yüreğimde bir çiçek olsan, 			o çiçek hiçbir...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/askin-gorunmeyen-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanası', 'yasanasi-sair-kapel-1bibp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sırçalı aynalardan silinmiş yüzüm,

Ölümler ötesinde darmadağın.

Eti kemiği sıyrık bir bedenin,

Tasasız çaresizliğindeyim.

Susmuş saatim; 

Duvarlar kan kızılı çizgilerde,

Mavisi çalınmış haritalarımda,

Denizleri arıyorum hırçınlıkla. 

Ayaklarım,olmayan bir   ülkenin,

Hamursu,kahverengi topraklarında,

Ellerim,olmayan bir kadının

Beyaz,ıslak yanaklarında.

Gözlerim,olmayan güzellikler tutkunu

Kulaklarımda,olmayan bir türkünün ezgisi

Geçip gidiyorum dünyadan,

Dünyaya hiç uğramadan

En yakın yolum; 

Boğazımdaki taştan lokma,

Yutkuna yutkuna içtiğim su,

En insansı halim.

Seviyorum durmadan; 

Başka türlü  yaşanası yok,

Bu hayatın.', 'Sırçalı aynalardan silinmiş yüzüm, Ölümler ötesinde darmadağın. Eti kemiği sıyrık bir bedenin, Tasasız çaresizliğindeyim. Susmuş saatim;  Du...', ARRAY['Türk Edebiyatı','Şiir','Şair Kapel']::text[], 8.5, '{"poet":"Şair Kapel","poet_slug":"sair-kapel","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yasanasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim', 'benim-osman-turkmen-n4b8s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bütün güzel şarkılar, olsun sana armağan,

Islatsa ne olur, mevsim yağmurudur yağan,

Yağmurlar altında, yoktan sevgiye ağlayan,

O sesi çıkmayan çocuk benim! 

Bir kriz gibisin, kalbimi her an yoklayan,

Sade bir çiçeksin, başka kimseye kokmayan,

En anlamlı sözleri, söylemeden saklayan,

O duygu esiri çocuk benim! 

Eski bir hüznü, sanırım kalmadı duymayan,

En aydınlık şafağa bile, artık sığmayan,

Gündüzlerden gecelere, bir umut bağlayan,

O şair doğumlu çocuk benim! 

Zorum olduğunu düşünme sakın aklımdan,

Senden başka kimse, bilmesin dedim korkumdan,

Ecele faydası yoktu, söyledim sonradan,

O ölümüne seven çocuk bendim!', 'Bütün güzel şarkılar, olsun sana armağan, Islatsa ne olur, mevsim yağmurudur yağan, Yağmurlar altında, yoktan sevgiye ağlayan, O sesi çıkmay...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-osman-turkmen-sfebe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biz en ıslak yüzleri yağmurlarla,

En nemli bakışları gözlüklerle gizledik.

Hiç ağlamadık desek de biz,

Sorgusuz gecelerde kimseler görmeden,

Islattık karanlığı sessiz sessiz.

Onlar göremese de,

Yaşlardan yaptığımız buketi,

Ve gözlerden boncuk gibi akan,

O billur tanesi damlacıkları,

Hep türkülerle söyledik.

Yumruk kadar küçük,

Okyanus kadar büyük,

En ufak sözden bile incinen,

Ama dağlara dayanan yüreğimize gömdük.

Gizli sevdalarla büyüdük,

Her yalan aşka,

Ve her bırakılışa üzüldük.

Oysa biz,sevginin yolunda,

Hep sevgiliye yürüdük.

Biz en bitkin bedenleri hastalıklarla,

En yorgun ifadeleri yalanlarla gizledik.

Hiç ölmedik desek de biz,

Gün doğumunda Azrail’e görünmeden,

Hem ağlar, hem ölür ve çekip gideriz!', 'Biz en ıslak yüzleri yağmurlarla, En nemli bakışları gözlüklerle gizledik. Hiç ağlamadık desek de biz, Sorgusuz gecelerde kimseler görmeden,...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/itiraf-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-osman-turkmen-fmxcu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Haykıramadığım bir duygu bu Anne,

Hep içimde, yüreğimdesin.

Bir ömür verdin yoluma Anne,

Ne anlatabildim,

Ne söyleyebildim! 

Bilmezdim henüz yaşamasını Anne,

Umut oldun bana, hep sesinle,

Yol çizdin önüme, anlamazdım hiç Anne,

Işık oldun, sevgi oldun gönlüme! 

Her günüm bayram olsun,

	bırak deli desinler Anne,

Çünkü hep,

	huzurlu görmek isterdim seni.

Dün gibi gerçek,

İnsan gibi bütün gönlünde Anne,

Bir günün bitimi,

                       ve işte arkasındakiler! 

Yıllanmış sevgilerin,

	birikimi bendeki Anne,

Bulutlara değmek kadar güzel.

Uyumaz hiç gözlerin,

	uyurken bile Anne,

Acılı günler, kaldıkça geride.

Sana yazdığım ilk şiirim bu,

İçimdeki birikimlerin döküldüğü,

Sesimin çığlığa döndüğü,

		belki de ilk bu.

Beni doğurduğun,

Ve Annem olduğun için,

Mekanın cennet olsun Annecim!', 'Haykıramadığım bir duygu bu Anne, Hep içimde, yüreğimdesin. Bir ömür verdin yoluma Anne, Ne anlatabildim, Ne söyleyebildim!  Bilmezdim henüz...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/annem-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Battığı Yerdeyim', 'gunesin-battigi-yerdeyim-muhammed-gacar-zl9vc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geçen gün sandalıma bindim ve açıldım. Arkamı döndüğümde hiçbir şeyi göremeyecek kadar uzaklaştım sahilden. Tıpkı senin benden uzaklaştığın gibi…

Eyvah! .. ufukta güneş batıyor. Vaktim çok az geriye dönmek için. Eğer güneş batmadan dönemezsem karanlığın içinde kaybolurum. Denizin ortasında fazla kalamam. Yaşamak için geri dönmem lazım. Eğer geriye dönemezsen ölürüm. Aynı şekilde sende gittiğin yerlerde fazla kalamazsın. Yaşamak için bana geri dönmen gerek. Eğer dönemezsen yaşarken ölürsün. Hayallerin yıkılır, ümitlerin kaybolur, yaşamak azap olur. Ben geri dönüş yolumu biliyorum. Yaşamak istiyorum ve bu yüzden geri döneceğim. Sende yolunu biliyorsun. Eğer yaşamak istiyorsan ben burada güneşin battığı yerdeyim…

Isparta, 2004', 'Geçen gün sandalıma bindim ve açıldım. Arkamı döndüğümde hiçbir şeyi göremeyecek kadar uzaklaştım sahilden. Tıpkı senin benden uzaklaştığın ...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Gacar']::text[], 8.5, '{"poet":"Muhammed Gacar","poet_slug":"muhammed-gacar","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gunesin-battigi-yerdeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizce Adalet midir?', 'sizce-adalet-midir-kadir-soyturk-hrxb6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Reva mıdır millete, adalette erinmek

Erinmenin sonucu olur elbet yerinmek.

Allah aşkına deyin, sizce adalet midir; 

Mazluma ceza verip, zalime hoş görünmek?', 'Reva mıdır millete, adalette erinmek Erinmenin sonucu olur elbet yerinmek. Allah aşkına deyin, sizce adalet midir;  Mazluma ceza verip, zali...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sizce-adalet-midir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-osman-turkmen-ilh77', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne kadar isyan ederse etsin geceler,

Sabahı olacaktır karanlığın! 

Ne kadar çabuk geçerse geçsin seneler,

Umudu hep olacaktır yalnızlığın! 

Ne kadar saklarsa saklasın gözler,

Bir sebebi olacaktır ayrılığın! 

Ve ne kadar yok dese de hisler,

Ayrılık...

Yok demek değildir asla,

Yalnızca birlikteliği gizler...', 'Ne kadar isyan ederse etsin geceler, Sabahı olacaktır karanlığın!  Ne kadar çabuk geçerse geçsin seneler, Umudu hep olacaktır yalnızlığın!  ...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ayrilik-237-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buraya Başka Duygularla Gelmek İsterdim', 'buraya-baska-duygularla-gelmek-i-sterdim-muhammed-gacar-sj53u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Buraya başka duygular içinde gelmek isterdim. Geldiğimde elini tutmak, seni seviyorum demek isterdim. Ama artık mümkün değil bunları yapmam. Artık seni sadece uzaktan seyredebileceğim ve uzaktan seveceğim. Ömrümün sonuna dek uzaklarda olacağım. Belki senin bir adım arkanda olacağım ama boyu kısa bir çocuğun ağacın dalındaki meyveye uzanamaması gibi elimi uzattığımda sana ulaşamayacağım. Ve yine çocuklar gibi oturup ağlayacağım. Aslında burada olmak beni o kadar üzüyor ki anlatamam. Sırf seni mutlu görmek, seni tebrik etmek için geldim. İnşallah bundan sonra da hep böyle mutlu kalırsın. Allah bir yastıkta kocatsın…', 'Buraya başka duygular içinde gelmek isterdim. Geldiğimde elini tutmak, seni seviyorum demek isterdim. Ama artık mümkün değil bunları yapmam....', ARRAY['Türk Edebiyatı','Şiir','Muhammed Gacar']::text[], 8.5, '{"poet":"Muhammed Gacar","poet_slug":"muhammed-gacar","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/buraya-baska-duygularla-gelmek-isterdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geleceğe Hiç Kala', 'gelecege-hic-kala-osman-turkmen-dy4g0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'En uzun bildiğimiz yolculuklar,

			aslında en kısa olanıdır...

Yaşam vurgun yemiş bir köpekbalığı gibi çırpınmaktadır,

		beynimizin işler damarlarında...

Ama umut asla kaybolmayan bir yaşam yongasıdır...

Ve halen varolmaktadır,

		ucundan koparılmış dünyamızın 						bilinmezliğinde...

Her şeyden önce hiçbir şey vardı...

Hiçbir şey unutma...

Hiç...

	Bir...

		Şey...', 'En uzun bildiğimiz yolculuklar, 			aslında en kısa olanıdır... Yaşam vurgun yemiş bir köpekbalığı gibi çırpınmaktadır, 		beynimizin işler da...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelecege-hic-kala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-osman-turkmen-lrvyo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidiyorum işte...

	geleceğe sırtı dönük,

		ve umuda yenik bir vaziyette.

Gidiyorum işte...

	aşkın cemresi düşmeden denize,

		ve sevgiye küskün bir nihayette.

Dur desende şimdi,

	bedelini ödemek gerekiyordu,

		faturası kabarmış bir yaşamın.

Burukluğum sana değil bilesin,

		kurulu düzeniydi geceye akan akşamın.

Gidiyorum işte...

	kimsenin bilmediği bir esasta,

		ve yegane parçası sende kalmış düşlerimle.

Gidiyorum işte...

     düz bir çizgide sendeleyerek,

	ve sensizliği parçalamak istiyorum dişlerimle.

Dur diyemezsin zaten,

	izin vermezdi gizli hayaller,

		çabası boşunaydı, 

			verdiğim bu onulmaz savaşın.

Ömrüm boyunca tekme yemişim,

	bitmesini bekliyorum, 

		bu kaybedilmiş yarışın.

Gidiyorum işte...

Akrep burcunun ağılı zehrinde,

Hunhar akşamın tam on birinde,

Ayrılığın anlatımı bu son filmde,

Yokluğun ve yalnızlığın, gergefine işliyorum seni.

Gidiyorum işte...

	sana inat bir ihtirasla,

		sevgiyi bırakıp da ücraya.

Gidiyorum işte...

	sırf için rahat etsin diye,

		sana yanmışlığım sönmesin diye.

Gidiyorum işte...

	sen böyle istedin diye,

		son bulsun muattar çiçeğim,

			bitsin bu hazin hikaye...

Bitsin!', 'Gidiyorum işte... 	geleceğe sırtı dönük, 		ve umuda yenik bir vaziyette. Gidiyorum işte... 	aşkın cemresi düşmeden denize, 		ve sevgiye küsk...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gidiyorum-133-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamaktın Sen...', 'aglamaktin-sen-osman-turkmen-k12d3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünün mazisinden,yarının istikbalinden yoksun,

Bugünün bıdığına sesleniyorum.

Yaşanacak yılların yarım kalan türküsünü,

Yalnızca ona besteliyorum.

Uçan bir kuşun kanadında kimi zaman,

Yalnızlığa yakılan bir sigaranın dumanında,

Bir annenin gözü yaşlı duasında kimi zaman,

Seni anımsatan, tüm çocukların arasındasın.

Kimi zaman yangın,

Kimi zaman deprem,

Kimi zaman ayrılık,

Hasretliktin kimi zaman.

Beklemektin hep...

Özlemektin gizli gizli...

Ağlamaktın sen...

Yirmi dokuz harfle anlattım kağıtlara seni,

Belki yetmedi.

Yirmi dokuzdan sonrasını kullanmadım,

Otuzuncu harf hiç olmadı.

Oysa sen vardın,

Hep vardın.

Zamanı gelince yağan,

Geçince kaybolan, bembeyaz bir kardın.

Ağlamaktın...

Kan kokulu karanlık gecelerimde kimi zaman,

Bir yana devrilmiş ve örselenmiş bedenimde,

Kalkmak için yerden uzanmış ellerimde kimi zaman,

Kainatın bir ucunda da olsan, 

			tüm yaşamınla genlerimdesin.

Kimi zaman yasaklamak,

Kimi zaman tekrarlamak,

Kimi zaman anlatamamak,

Ezberlemektin kimi zaman.

Akılda tutmaktın...

Yarım kalmaktın...

Ağlamaktın sen...

Çok kez anlattım kendime seni,

Ama yetmedin.

Çok kez den sonrasını denemedim,

Daha fazlası hiç olmadı.

Yine de vardın...

Canımdın...kanımdın...parçamdın...

Gelecekteki soyumdun,

Yaşamam için sebep,

Ölmem için sonumdun.

Kimi zaman vardın,

Kimi zaman yoktun.

Ben senin öz baban,

Sen benim biricik oğlumdun.

Ağlamaktın! ..

Kimselerden habersiz,

Gülen gözlerinde ağlamak.

Hıçkırıklarım ve hayal kırıklığım duyulmadan,

Sensizliğin anısına, gecelerce yorulmadan,

Ayaza teslim olmuş alacakaranlığa,

ve duvardaki yosunumsu rutubete kafa tutarcasına

			ıslatmaktın her şeyi.

Biliyor musun? 

Ağlayamadan bakmaktın bazen,

ve ardından boşalan bir sağanaktın.

Ağlamaktın babasın...

Ağlamaktın sen...', 'Dünün mazisinden,yarının istikbalinden yoksun, Bugünün bıdığına sesleniyorum. Yaşanacak yılların yarım kalan türküsünü, Yalnızca ona besteli...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/aglamaktin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Işığı İstanbul''a...', 'ay-isigi-i-stanbul-a-osman-turkmen-x1q08', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ay’ın ışığı İstanbul’a,

	karanlığı Ankara’ ya bakıyordu.

Her baskında yüreğim,

	yüreğim biçare, isyanlara akıyordu.

Kim bilebilirdi söyle kim,

	zifiride umudum, bir şeyler saklıyordu.

Ay ışığında yitik,

	ve Ankara benim için artık

				bitik bir şehirdi.

Bendekiler bende,

Sendekiler sende kalmıştı.

Havayı öyle bir sis almıştı ki,

Bütün umutlarımı ayrılık denen,

			o hırsız çalmıştı.

Kıskanç olduğunu biliyorum İstanbul! 

Hayallerime gem vuracak kadar kıskanç,

Çaresizlik her yanımda sanki bir kıskaç,

Artık seni...

	bütün beyazları yutan,

		korkunç bir canavar görüyorum İstanbul! 

Ya tıkanıp kalmak sensizliğin çemberinde,

Ya da boğulmak hüzünlerin denizinde.

Dar mıydı Ankara sana? 

Böyle çekip gitmek var mıydı? 

Asabilir miydi hislerini insan,

			çiğ bir ağacın gölgesinde.

Ankara’da solgun bir sükunet vardı,

	ve yorgun bir emanet.

Adresi İstanbul’du onun,

	vurulan yoktu görünürde anlaşılan,

Oysa ki işlenen,

	duygusal bir cinayet! 

Yahşidir ay ışığında İstanbul! 

	karanlıkta bıraktığın Ankara’yı hiç sorma,

		o masumane bakışını boş yere yorma.

Müzmin geceler sensiz, daha da vahşi,

	kayıtlarda senin adında şimdi,

			görünmüyor bir kişi.

Bir iyilik yap desem İstanbul! 

Aldığın gibi göndermeni istesem,

Denizin, köprülerin, gecelerinle,

Ne kadar ihtişamlı, ne kadar güzelsen,

Sana güzel demek, gelmiyor içimden.

Düşündüğüm gibi değil aslında,

İnişi yoktu çıkılan merdivenin,

Takati kalmadı artık direnmenin,

Anlatamazdı hiçbir ifade,

			ne koyusunu yeşilin,

				ne de açığını mavinin.

Kış mevsiminde açan bir çiçeksin,

Baharda yağan bir kar,

Terk etmesen bu şehri ne çıkar.

Reddetmesen geri dönüşü,

Gözlerini kapasan da,

			seyretmesen savrulan bir düşü! ..

Kimse bilemezdi,

Hiç kimse seni sevdiğimi...

Giderken sen...

		Ay ışığı İstanbul’a bakıyordu...

				Karanlığı ise Ankara’ya...', 'Ay’ın ışığı İstanbul’a, 	karanlığı Ankara’ ya bakıyordu. Her baskında yüreğim, 	yüreğim biçare, isyanlara akıyordu. Kim bilebilirdi söyle ki...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/ay-isigi-istanbul-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizlere Ömür', 'sizlere-omur-osman-turkmen-9pm5z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Onun hikayesi,

Milyarlarca yıl önce başlamıştı belki de.

Tevellüdü tam olarak bilinmemekle,

Vefatı sanki cinayetti, 21. asrın içinde.

Bir yağmurun damlasıydı o,

Geleceğin aynası,

Tabiatın yasası,

Yokluğun tek varlığıydı.

Tertemiz karların beyazıydı o,

Gönüllerin sazı,

Mevsimlerin yazı,

Mazlum dünyamızın arsızıydı.

Her kurşuna siperdi.

Tek başına kalsa da,

Sözde ölümsüz bir neferdi.

Yüzyılların yorgunluğuyla,

Herkesi yalnızlığından öperdi.

Bilimin bile çözemediği bir gizemdi,

Duyguların paslı teninde, sanki erdemdi,

Tanımıyorum diyen yalan söylerdi,

Çünkü o; 

Beşerin yüreğinde sımsıcak bir özlemdi.

En güzel bestelerin,

Unutulmaz güftelerinde,

Yalnız adı kaldı şimdi.

Ölüm sebebi bilinmiyordu,

Otopside görünmüyordu,

Buz kesmiş iyimserliğiyle,

Ebedi yolculuğa giderken,

Sizleri seviyorum diyordu.

Gülüyordu...

İki rekatlık cenaze namazıyla,

	aramızdan ayrılan,

		tek mısralık bir şiir gibiydi.

Asırlardır gönüllere ilaç olan,

Bazen kahır verse de, hüzünlerle,

O tüm zamanlarda ihtiyaçtı.

Teoride varlığına inanılsa da,

Hakikatte ölmüştü.

Mevtanın adı...aşktı! 

Bin, bire uyamazdı,

Oysa bir, bine uymuştu.

Senin anlayacağın,

Artık aşk adında bir sevgili yoktu.

Kısacası; 

Aşk! ..sizlere ömür!', 'Onun hikayesi, Milyarlarca yıl önce başlamıştı belki de. Tevellüdü tam olarak bilinmemekle, Vefatı sanki cinayetti, 21. asrın içinde. Bir ya...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/sizlere-omur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim', 'sevdim-osman-turkmen-s1kks', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdim seni,

	bir de yüreğini,

		ve benim olmanı istedim.

Bir de...

	ölümsüzlüğün şahdamarında ölmeyi.

Ne sevebildim,

	ne ölebildim oysa.

Sözlerini içime attım,

sevgisizliği yüreğime.

Bir gün  çıkar gelirsin diye yolları,

ve her iştiyaktan önceki acıları sevdim.

Umut ektim her sene gibi bu sene de,

hasadı beklerken,

dolu vurdu umutlarımı.

Ama yine de ben,

	her doludan önceki esintiyi,

		akıbeti belli olmayan ferdadan önceki,

			hayalleri sevdim.

Ben sevdim sen değil,

Arşa yazdığım sevgimi, istiyorsan sil,

Seni sevdiğime herkes şahit, ama şunu da bil; 

Ben her varlıktan önceki yokluğu,

İlk sevdiğim günden beri, sensizliği de sevdim.

Belki de ben seni, hep sensiz seveceğim!', 'Sevdim seni, 	bir de yüreğini, 		ve benim olmanı istedim. Bir de... 	ölümsüzlüğün şahdamarında ölmeyi. Ne sevebildim, 	ne ölebildim oysa. Sö...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevdim-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Hakkın Aşığıyım', 'ben-hakkin-asigiyim-kadir-soyturk-uv79c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hak Allah''ın adıdır, insanın hedefidir; 

Hakka aşık olmayan, aşıkıdır ya kimin? 

Bir gün o da çıkacak, Hakimin huzuruna

Allah alsın canını adaletsiz hakimin!', 'Hak Allah''ın adıdır, insanın hedefidir;  Hakka aşık olmayan, aşıkıdır ya kimin?  Bir gün o da çıkacak, Hakimin huzuruna Allah alsın canını a...', ARRAY['Türk Edebiyatı','Şiir','Kadir Soytürk']::text[], 8.5, '{"poet":"Kadir Soytürk","poet_slug":"kadir-soyturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ben-hakkin-asigiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eller seveni biliyor', 'eller-seveni-biliyor-tuncay-akdeniz-750r4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel güzelim naz eyleme

Eller seveni biliyor

Aşkını benden gizleme

Kullar seveni biliyor

Seviyorum ben birini, 

Ferhat ta sevdi şirini

Sehere sordum yerini

Yeller seveni biliyor

Bülbül gibi dilimde zar 

İnsaf eyle ver bir karar

Sevilecek güzelim var

Güller seveni biliyor

Tuncay’ın inan sözüne

Gönül sevdalı özüne

Yakma keremin közüne

Küller seveni biliyor', 'Gel güzelim naz eyleme Eller seveni biliyor Aşkını benden gizleme Kullar seveni biliyor Seviyorum ben birini,  Ferhat ta sevdi şirini Sehere...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eller-seveni-biliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükenmişliğim', 'tukenmisligim-osman-turkmen-dtohd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecelerimin yalnızlığı,

Yasaklı günler kadar uzaksın,

Çığlıktaki isyanımın aksisedası,

Yutkunurken kayboluyordun.

Son nefesimdin ve son sözüm. 

Seni yaşarken seviyor,

Bunun acısını,

Severken yaşıyordum.

Tek beklentim, son umudum, yaşam sancım,

Sondun...sonum oldun!', 'Gecelerimin yalnızlığı, Yasaklı günler kadar uzaksın, Çığlıktaki isyanımın aksisedası, Yutkunurken kayboluyordun. Son nefesimdin ve son sözü...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tukenmisligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabaha Karşı', 'sabaha-karsi-osman-turkmen-m6y5t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sabaha karşı bir düş kurdum; 

Yalnızlığımın eşliğinde,

Acabalarımın senfonisi çalıyordu.

Belkilerim vardı,

Bir de, bir de sensizliğim.

Sabaha karşı bir düş kurdum; 

Sen bundan habersiz,

Benden habersiz uyurken,

Ben düşlerimi gezdirirdim,

Uykusuzluk diyarının,

Tenha caddelerinde.

Ve düşüncelerimin,

Hiç bilinmedik,

Issız köşelerinde, sen oldum.

Sabaha karşı bir düş kurdum; 

Seni kurdum zamansız,

Ve amansız,

Ve her şeyi yanıma alarak,

Adımlarının gölgesi oldum.

Sen oldum,

Sensizlik oldum.

Sabaha karşı bir düş kurdum; 

Düşümde güneşi,

Güneşte aydınlığı,

Aydınlıkta seni,

Sende ise kendimi buldum.

Neler  yazmadım ki adına,

Baş harflerini nerelerde kullanmadım ki,

Hatta, noktasızlara nokta koyup,

Adını bile kısalttım,

Kimse bilmesin diye.

Oysa...

Ütopyalarım çırpınırken benliğimde,

Her çocuğun saflığı kadar masum,

Ve her içerdeki gibi çaresiz,

Belki de anlamsızlıklara takılıyor,

Mana arıyordum,

Çözümsüzlüğün orta yerinde.

Sabaha karşı bir düş kurdum; 

Gecenin en sonuna gidiyor,

Günün ilk ışıklarını karşılıyordum.

Saat dördü vururken,

Ben hala seni yaşıyordum.

Sen yoktun biliyorum,

Biliyorum hiç olmadığını.

Benimkisi; 

Çok uzaklarda, bilinmedik bir şehrin,

En kuytu ve en uyduruk yamacında,

şimdilerde harabe olmuş bir evin,

Değişmesini bekleyen patlamış ampulü gibi,

Işıksız geceleri aydınlatma hevesi.

Kaybetmiş bir insan ne yapıyorsa,

Ben de onu yapıyordum.

Sensizliğe doğru yürüyor, 

Dönüp bakmadan ardına,

Gidiyordum işte,

Gidiyordum.', 'Sabaha karşı bir düş kurdum;  Yalnızlığımın eşliğinde, Acabalarımın senfonisi çalıyordu. Belkilerim vardı, Bir de, bir de sensizliğim. Sabah...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/sabaha-karsi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanadır Bu Sitem', 'sanadir-bu-sitem-osman-turkmen-m0lln', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yürek düşün, hiç açılmamış,

Bir yürek düşün, tadilata uğramamış,

Bir yürek düşün, umutsuzluğa kapılmamış,

Ve bu yürek hala, sensizliğe hiç mi hiç alışmamış.

Artık teslimat günü sanırım,

Bendeki bu emanet yüreğim,

Bundan böyle gerçek sahibinin.

Bir yürek düşün hadi durma,

Bitenin ardından, giden bir yürek.

şunu sakın unutma! 

Her gözünü açtığında sabaha,

Sana sevdiğini söyleyecek.', 'Bir yürek düşün, hiç açılmamış, Bir yürek düşün, tadilata uğramamış, Bir yürek düşün, umutsuzluğa kapılmamış, Ve bu yürek hala, sensizliğe h...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sanadir-bu-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An''ın Uzunluğu', 'an-in-uzunlugu-utku-demir-ygrnn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu şimdiden uzun bir roman sonu gelmesede

Zamanın böylesi yavaş akışında

Bense hayalperest ama gerçek bir kahramandım galiba

Üzerine bir kitap yazmalı

Bunca şeyi nasıl düşündün yaşadın dedirtmeli adeta

Hüzünlü kapandı pencere sebepsizce

Sabah erken doğan güneş daha da erken battı bugün

Herşey olağandışıyken bir olağanlık oldu sanki

Koşulsuzluk önüne konan bir engeldi

Bununla savaşıyordum oysa yıllardır

Yıkılmalıydı bence önyargısızca

Bu kadar mı önemliydi gelip geçici şeyler

Peki ya sona doğru yaklaştıkça ne olacaktı? 

Kimbilir belki güneş yeniden doğar

Boynu bükük solmaya yüz tuttu papatyalar

Bakamıyorum onlara başım eğik

Acaba denize attıklarım ne oldular

Yoksa onlar mı kaybolup bu duruma sebep oldular

Uykum var yıllardır yorgunum

Doluyken bomboş oldum

Karmaşıkken daha da karmaşıklaştım

Mumu söndüremeyecek hiç bir rüzgar

Tükenmeye gidecek belki bir an önce

Oysa alevlenirse sonsuza uzanacak

Sen de görüyorsun gerçekler böyle yaşar

Bütün varlığınla içindesindir anın

Çiçeğe bakışında böyledir

Sözcüklere döküşünde

Acı da çekersin mutlu da olursun

Ağlarsın ve gülersin

Kazanırsın ya da kaybedersin

Oysa bazı şeyleri hak edersin', 'Bu şimdiden uzun bir roman sonu gelmesede Zamanın böylesi yavaş akışında Bense hayalperest ama gerçek bir kahramandım galiba Üzerine bir kit...', ARRAY['Türk Edebiyatı','Şiir','Utku Demir']::text[], 8.5, '{"poet":"Utku Demir","poet_slug":"utku-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/an-in-uzunlugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sevdiğim', 'son-sevdigim-osman-turkmen-zevy9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben; 

Umut hamurunda yoğrulan, un gibiyim,

Muson yağmuruyla ıslanan, yosun gibi,

Hasret ikliminde, öğün gibi,

Yılmayan sevginin kölesi,

Dönüşü olmayan, yolculuk gibiyim.

Yüksek duvarlarla çevrili, kale gibiyim,

Göz yaşlarıyla sulanan, lale gibi,

Elde kalmış vale gibi,

Kazanamayan aşkın çilesi,

Yaramaz bir çocuk gibiyim.

Ya sen; 

Sessizlik içinde, seda eder gibisin,

Hoş çakal derken, veda eder gibi,

Giderken bile, eda eder gibi,

Ne ilerliyor, ne dönebiliyorsun,

Arada kalmış oyuncu gibisin.

Islak yağmurlarla yere düşen, duygu gibisin,

Korsan gecelerde çaresiz, uyku gibi,

Karanlıklarda varolan, korku gibi,

Öncesi sonrası yok bunun,

			ve sana vuruldum ben,

Herhalde sen...

Son gibisin!', 'Ben;  Umut hamurunda yoğrulan, un gibiyim, Muson yağmuruyla ıslanan, yosun gibi, Hasret ikliminde, öğün gibi, Yılmayan sevginin kölesi, Dönü...', ARRAY['Türk Edebiyatı','Şiir','Osman Türkmen']::text[], 8.5, '{"poet":"Osman Türkmen","poet_slug":"osman-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/son-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tutsan Ellerimi', 'bir-tutsan-ellerimi-hatice-bediroglu-zxva2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sanki! kış güneşi

Kuytularından çıkıp ormanın

Yüksek çok yüksek

Meşe ağaçlarının arasından

Geliyor üzerime süzülüp

Soğuk ısırıyor beni

Yanaklarım dökülüyor

Lime lime olmuşum

Titriyorum, sensizim

Bunca üşümem ondan

Takırdıyor çenelerim

Ağaçkakan misali

Kulaklarım bu sese

Dayanmıyor..

Bir tutsan ellerimi; 

Yaz güneşi 

Doğacak odama

Bedenimin içinde

İyi olacak ruhum

Sevinç titretecek

Yüreğimi

Bir tutsan ellerimi; 

Susacak ağaçkakanlar

Mavi turlara çıkacağım

O an da.

Süt beyazı

Martılar eşliğinde

Çığlık çığlığa...

Ve

Tüm mavi yıldızlarda

Tüm beyaz bulutlarda

Konaklayarak

Öpeceğim seni yumuşacık

Arkamda

Sevdamın rüzgarları

Ellerimde ilk yaz çiçekleri

www.haticebediroglu.net

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005', 'Sanki! kış güneşi Kuytularından çıkıp ormanın Yüksek çok yüksek Meşe ağaçlarının arasından Geliyor üzerime süzülüp Soğuk ısırıyor beni Yanak...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bir-tutsan-ellerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asil Sevdam-3', 'asil-sevdam-3-hidayet-avsar-o72k7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gelişin...

Sarı toprağın yağmuruydu.

Sonbaharla valsiydi sevdalarımın.

Yokluğunda,

Avucundaki denizlerde,

Sesindeki okyanusta yüzdüm,

Memleketinin yollarında yürüdüm; 

Adaya karşı türküler söyledim...

Şimdi... 

Siyah beyaz gülüyorum hayata.

Donup kalan bir çift bakışa,

Her sonbaharda aşina gözlerim...

Bekle beni ormanların uçarı yağmuru,

Sular yükseldiği zaman,

Nuh’un gemisine binip

Sana geleceğim...', 'Gelişin... Sarı toprağın yağmuruydu. Sonbaharla valsiydi sevdalarımın. Yokluğunda, Avucundaki denizlerde, Sesindeki okyanusta yüzdüm, Memlek...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asil-sevdam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakıp Sabancı', 'sakip-sabanci-i-shak-ozlu-pg7wn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhum Sakıp SABANCI ve geride kalan sevenlerine ithaf olunur.

Sakıp Ağa gözlerini yumdu dediler,

Seksenbir İl''den cenazene geldiler.

Hiç bir işadamına nasip olmayan,

Gerçek bir sevgi ile candan sevdiler.

Türk Milleti Ağa bildi,öyle dedi,

Yediden yetmişe sevip gönül verdi.

Bunca yıl kime Ağa demiş, bu Millet,

Tatlı dilini,güler yüzünü sevdi.

Sabancı Üniversiten Dünya çapında,

Eğitimde önderlik senin yapında.

Kurdugun Fabrikaların sayesinde,

İşsiz yüzbinler ekmek buldu kapında.

Dünya''ya ufkumuz seninle açıldı,

Eserlerin Vatan Sathına saçıldı,

Millet''i doymadan Sakıp Sabancı''ya,

Sonsuz yaşamın kapıları açıldı.

Büyükle büyük,küçükle küçük oldun,

Mutlulugu Ülke refahında buldun.

Türk''ün Dünya''ya parlayan Yıldızıydın,

Gün akşam olmadan tez zamanda soldun.

Veda''na alışamadık Yüce İnsan,

Ne çok özlüyoruz cismini bir bilsen.

Mekanın cennet olsun,Nur içinde yat.

Yüregimizde Taht kurdun yaşıyorsun.', 'Merhum Sakıp SABANCI ve geride kalan sevenlerine ithaf olunur. Sakıp Ağa gözlerini yumdu dediler, Seksenbir İl''den cenazene geldiler. Hiç bi...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sakip-sabanci-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumlar', 'kumlar-suheyl-turkoglu-y64vw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kumlar,

İrisiyle, tozuyla,

Kumsaldaki gibi,

Sevimli değil.

Kör ediyor gözleri,

Terli çamur,

Soluk bile eziyet,

Kumlara,

Sitemim var.

Hava nemli,

Ortam ıslak,

Sis çökmüş,

Umutlar üstüne,

Hepsi sırılsıklam,

Paslandı hayallerim,

Kızgınlığım bulutlara,

Rüzgara değil,

Yerli yerinde,

Beklerken her şey,

Öfkeleniyorum,

Uçan kumlara.', 'Kumlar, İrisiyle, tozuyla, Kumsaldaki gibi, Sevimli değil. Kör ediyor gözleri, Terli çamur, Soluk bile eziyet, Kumlara, Sitemim var. Hava ne...', ARRAY['Türk Edebiyatı','Şiir','Süheyl Türkoğlu']::text[], 8.5, '{"poet":"Süheyl Türkoğlu","poet_slug":"suheyl-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kumlar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umarsız Sevgi', 'umarsiz-sevgi-cemal-karsavran-nip0m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Firar etmiş uykuların gecesindeyim

Sevda kelepçesi kollarımda

Düş mü gerçek mi seçemiyorum

Aryalar çınlıyor kulaktan kulağa

Mahkum oldu mutluluklar dolunaya

Kayalıklarda gözyaşları üşür

Sır perdesi aralanmış ışıldar

Yıldızlar uçuşur hareli gözlerde

Kelimelerin dili olsa da söylese

Yüreğim ellerinde sabahlar iken

Avuç içim yangınlarda titrer

Dilim binlerce şarkı besteler

Duysun dağlar taşlar yaşanan anlar

Çemberimde gül oya ve de çiçekler

Rahvana koşuyor mutluluk atı

Tanrıdan dileğim bitmesin sürsün

Cemal im yüreğim hep canlı kalsın

Hayat vaat ediyor umarsız sevgi', 'Firar etmiş uykuların gecesindeyim Sevda kelepçesi kollarımda Düş mü gerçek mi seçemiyorum Aryalar çınlıyor kulaktan kulağa Mahkum oldu mutl...', ARRAY['Türk Edebiyatı','Şiir','Cemal Karsavran']::text[], 8.5, '{"poet":"Cemal Karsavran","poet_slug":"cemal-karsavran","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/umarsiz-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fazla Mesai', 'fazla-mesai-aysun-erat-9ic78', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gündüzler yetmiyor seni düşünmeye

Gececi de kalıyorum artık bak! 

Bir saat fazla mesai yapsam,

Biraz daha doluyorsun içime..

Karar verdim bundan böyle

Seri üretime geçeceğim.

Uykusuzluğu da alt edip,

Tam kapasite seni düşüneceğim.

Niyetim toplumsal refah değil.

Fert başıma düşen seni artırmak.

Biliyorsun…

Belki bencilce ama,

Konu sen olduğunda,

Ben…. 

İflah olmaz bir bireyciyim..

04/2005', 'Gündüzler yetmiyor seni düşünmeye Gececi de kalıyorum artık bak!  Bir saat fazla mesai yapsam, Biraz daha doluyorsun içime.. Karar verdim bu...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fazla-mesai-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlmeğinden Tuttum Yaşamı...', 'i-lmeginden-tuttum-yasami-ugur-deniz-ulkegul-7k0ar', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''İlmeğinden tuttum yaşamı...

Dalı urgan ağaçlarda meyve topladım...

Ne ölümler yetişti, boy verdi aramızdan,

Sancısını yüreğimde sakladım...''

Kınanmışlığın utancını yaşamaksa eğer,

Kabul-ü pişmanlığın yorgunuyum aşkta…

Söylenmiş sözlerin arifesinde, yalnız,

Ve bir o kadar kuralsız kalmaksa eğer,

Mecnun’u aşmışlığın vurgunuyum ben…

Seni sevmek…Bir başka…

Arsızlığına bakma sözlerimin

Benim gökyüzümde saklıdır en güzel mavi

En uçsuz bucaksız toprakların sürgünüyüm…

Ve en derin yaraların mecalsiz sahibi,

Henüz sona ermemiş karanlıkların, günüyüm…

Sesim ulaşmıyor diye kızma bana,

Yabani umutların peşinde suskun,

Ve inatçı bakışların suçlusuyum…

Gözlerim değmiyor evinin duvarlarına,

Sokağından geçmiyor yol bilmez adımlarım…

Ve sen kokmuyor diye

Voltamda kanayan çıkmaz sokaklarım…

Bu koca şehrin umarsız küskünüyüm…

Benim koynumda saklıdır düşlerin,

En sıcak elin vedasıdır omzumda ki…

Sigaranın dumanında,

Bozkır yaylasının esen rüzgarında,

Ve dağ eteklerinden parmak uçlarıma değen,

Kar yangını dokunuşların soğuğunda,

Bir avuç sıcaklık olur gülüşlerin…

Arsızlığına bakma sözlerimin,

Benim bakışlarımda durur en güzel sen,

En kusursuz yol alışları özlemenin…

Sabrın yüreğime koyduğu amansız yük,

Ve en büyük, en zamansız,

Karşılıksız Onurunu taşımak sevmenin…

Hani ölüm de var derler ya…

Oysa bir sebebi olmalı değil midir yaşamanın…

Bütün son buluşların gerekçesine küfretmek,

Kurşun sıkmak öfkesine alabildiğine yalnızlığın,

Pas geçmek belanın puşt bakışlı gözlerini,

Ve umursamadan dinlemek korkunun sözlerini…

Yetmeyecekse gözlerine uyanmaya bir sabah vakti,

Ne anlamı kalır her şeye yeniden başlamanın…

Hani ölüm de var derler ya…

İnadına gitmek üstüne dar ağaçlarının,

Türkü söylemek yürürken hain pusularda,

Ve kahkahalarla gülebilmek sözüne,

Tükürebilmek yüzüne işkenceci zamanların…

Bir merminin sancısında,

Düşünmek saçlarını bir çocuğun,

Bulutlara uzanmak uçurtmasında…

Kurulmuş bir akşam sofrasında,

Yoksul direnişlerin tokluğunu yaşamak…

Bilmenin ve anlamanın,

Ve direnmenin gülüm,

Direnmenin onurunu taşımak…

Arsızlığına bakma sözlerimin…

Benim tarlalarımda büyür en güzel tohum,

En derin sular benim denizlerimde durur,

En yüksek zirvelerden bakarım yüreğine,

Benim dağlarımda düşer delikanlılar,

Mert ve yürekli insanları bende vurulur…

Hani ölüm de var derler ya…

Gülüp geçtik işte…

Yaşamak sancısında,

Bölüşmek telaşıdır hayat,

Doğruyu, Güzeli, Direnci…

Elbet neden öldüğümüz

Bir gün sorulur….', '''İlmeğinden tuttum yaşamı... Dalı urgan ağaçlarda meyve topladım... Ne ölümler yetişti, boy verdi aramızdan, Sancısını yüreğimde sakladım......', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/ilmeginden-tuttum-yasami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaire', 'saire-mustafa-ceylan-dhz7s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sözcük dünyasının sultanısın sen

Dik gökdelenleri, şiir boş saha...

Busen yarınlara menekşelensin,

Daha ne beklersin..? ! ..

Fildişi kulenin yık duvarını,

Zaman teknesinde yoğur yarını; 

Dikkatli kullan dil fermuarını

Dil, seni ezberlesin...

Gönül meclisinde adın okunsun

Dokunsun haksıza kelam kılıcı...

Mısra zindanından çıksın da sesin; 

Yüreğin gümbürdesin...

Acı, ekmek-aşın; aşk kaderindir

Gözde uyku, sudan bile derindir.

Uyuma, sevdanın bahçesine gir! 

Bülbüller ''gülüm...! '' desin...

Eskisi, yenisi hepsi bu dünya,

Ses, ışık, koku, renk; böyle gördün ya...

Durma, çöz sırları; sanma yerdesin...! 

Özlenen seherdesin...

Sözcük dünyasının sultanısın sen,

Ey erenler ereni, ey paşalar paşası...! 

''Yaşasın'' diyen alkışlara inanma hiç...! 

Çiledesin,

Benimlesin...', 'Sözcük dünyasının sultanısın sen Dik gökdelenleri, şiir boş saha... Busen yarınlara menekşelensin, Daha ne beklersin..? ! .. Fildişi kulenin...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/saire-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Düşü-', 'bahar-dusu-mustafa-ceylan-ix9de', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeşil bir tebessüm iner dallara

Umut gözlüğüyle baktığım zaman.

Kuşlar meydan okur geçen yıllara

Bulutları yere yıktığım zaman.

Tutamam depreşir kanım, iliğim

Gelir de aklıma birinciliğim...

Çıkar durgun sudan mahzun gençliğim

Göllerden çöllere aktığım zaman.

Akça sütü saklar, otlar-çayırlar

Dönüşür evet''e dilde hayırlar,

Çiğdem çiçek olur kırlar-bayırlar

Gönül kuzusuyla çıktığım zaman.

Nazlı yâr avcuna yakar da kına

Ceylan yüreğimin varır farkına..

Uzaktaki dostlar gelir yakına

Çoban ateşini yaktığım zaman...', 'Yeşil bir tebessüm iner dallara Umut gözlüğüyle baktığım zaman. Kuşlar meydan okur geçen yıllara Bulutları yere yıktığım zaman. Tutamam depr...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bahar-dusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felâketimsin', 'fel-ketimsin-mustafa-ceylan-9nnq3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'De güzelim ''bana neler oluyor...? ''

Aklımın üstünde kıyafetimsin.

Sen yoksan, billâhi karnım doymuyor...! 

Sevda masasında ziyafetimsin...

Var mı ki dünyada ben gibi olan...? 

Mecnunca dolanan, Keremce yanan...? 

Seherde uyanan, aşkla boyanan

İçi gurbet dolu memleketimsin...

Sevgi işleminde ''ortak payda''yım,

Sivrilmiş ok gibi eğri yaydayım,

Hasret girdabında, zindanlardayım; 

Hüznümün kaynağı felâketimsin...

Has bahçemde açan ey çılgın lâle...! 

Düşürdün sonunda beni bu hale...

Mıknatıs bakışla eyledin köle; 

Kurtuluş olmayan esaretimsin

Damarda, kanımda gezip dolaşan

Terime, tenime sinip bulaşan...

Yaz-bahar ayında dört nala koşan

Deli taylardaki cesaretimsin...

Dudak mührün ile vurulur ''öpkü''n

Gül açar elinde zaman ile gün..

Tek sana âşığım tek sana tutkun; 

Hedefte vurduğum isabetimsin...', 'De güzelim ''bana neler oluyor...? '' Aklımın üstünde kıyafetimsin. Sen yoksan, billâhi karnım doymuyor...!  Sevda masasında ziyafetimsin... V...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/felaketimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaban sana', 'yaban-sana-i-shak-ozlu-56imm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen ellerin oldun sevdam,bende.

Senin olmadıgın yaban elde.

Zincir vurulsada yüregime,

Yaşar adın,zikir eder dilde.

Baktığın yüz hayli yaban sana,

Benimkide sencileyin bana.

Perde insede gören gözlerime,

Canan yakındır,senin bu can''a.

Yürek başka söyler,diller başka,

Sevgisiz soğuktur gönül meşk''e.

Mesafeler girsede araya,

Engel olmuyor düşlenen aşk''a.', 'Sen ellerin oldun sevdam,bende. Senin olmadıgın yaban elde. Zincir vurulsada yüregime, Yaşar adın,zikir eder dilde. Baktığın yüz hayli yaban...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yaban-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Işık Yak', 'bir-isik-yak-zulfikar-yapar-kaleli-x3jg7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Küfre karşı kur bir ordu

Yoldaşınla yaranla gel

Ve kurtulsun Türk’ün yurdu

Dilinde hep Kuran’la gel

Haktan taviz verme asla

Ruhu bile edep süsle

Sevdayı seninde besle

Hayalinde turanla gel

Gayret göster, kalma sona

Gönlünü ver, bağlan ona

Ehl-i şirki koy bir yana

Hakikati saranla gel

Feryadında, amanında

Olmuşuz onun yanında

En çaresiz zamanında

Zulme karşı duranla gel

Cömert davran, dağıt bol bol

Mutlak O''na çıkar her yol

Güneşlere sevdalı ol

Tipiyle gel, boranla gel

Gayret göster, terle ak ak

Sanma ölüm bize ırak

Cehaleti sele bırak

Hakikate varanla gel', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Küfre karşı kur bir ordu Yoldaşınla yaranla gel Ve kurtulsun Türk’ün yurdu Dilinde hep Ku...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-isik-yak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlık', 'baslik-zulfikar-yapar-kaleli-8sssg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Mazisine taş atanın'',

Atisine top atarlar.

Her gün yan gelip yatanın,

Emellerini yutarlar.

Dünle bugün köprü başı,

Beş bin yıldır bunun yaşı,

Tarih Türk’ün öz kardeşi,

Tutar bin yıla satarlar.

Beş bin yıla dört bin kurban,

Başlık diye verdi o an,

Deşilmezse şu kör çıban,

Arslan köşküne yatarlar.

Dilber derdin mahyasıdır,

Aşk güzelin hayasıdır,

Birlik yurdun ihyasıdır,

Ayrılığı pey tutarlar.

Doğu senin batı senin,

Ölmezliğin kati senin,

Mazi senin ati senin,

Pişmiş aşa su katarlar.', '''Mazisine taş atanın'', Atisine top atarlar. Her gün yan gelip yatanın, Emellerini yutarlar. Dünle bugün köprü başı, Beş bin yıldır bunun yaş...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/baslik-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna...', 'ayna-emirhan-bala-kuth5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen, hoyratça harcamışsan seni, 

insan manzaraları dizilmiştir 

kulağına küpeler misali. 

Hep varızdır fark edilmesen de, 

Damıtırsın duygularını hecelerle, 

Biz ulaştığımızda satırlarınıza, 

Dizersin bizi küpelere... 

Sen, külfetini yüklemişsen sana, 

Adalet ruhuna nakkaş, 

Geceler mazluma güneş, 

Havyar zalime zehir, 

Sen mi? 

Kendine öksüz yetim...', 'Sen, hoyratça harcamışsan seni,  insan manzaraları dizilmiştir  kulağına küpeler misali.  Hep varızdır fark edilmesen de,  Damıtırsın duygul...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ayna-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
