INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut düşler', 'umut-dusler-umut-simsek-xah78', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece ve düşlerim

düşlerimde sen

sen uzaksın

uzak özlem

özlem acı

acı umut

umut düşler

umut seni düşler

umut gecede seni düşler', 'Gece ve düşlerim düşlerimde sen sen uzaksın uzak özlem özlem acı acı umut umut düşler umut seni düşler umut gecede seni düşler...', ARRAY['Türk Edebiyatı','Şiir','Umut Şimşek']::text[], 8.5, '{"poet":"Umut Şimşek","poet_slug":"umut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/umut-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın Postu', 'zamanin-postu-orhan-demirtas-k44w7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana ağır yıkımlar yaşatan

.........Zamanın dört mevsimine

