INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm ve Sorgu-Sual.', 'olum-ve-sorgu-sual-osman-sofuoglu-xr1ub', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Diyelim ki şu an öldüm.

Burdan göçüp gideceğim.

Türlü türlü sorulara,

Nasıl cevap vereceğim? 

  Sorarlarsa neler yaptın? 

  Bir ömrü nasıl yaşadın? 

 O güzelim yıllarını,

  Nasıl nerede harcadın? 

Hiç kul hakkını yedin mi? 

Zekatlarını verdin mi? 

Anan-babana hürmette.

Acep hiç kusur ettin mi? 

İbadetlerin anası,

Namazlarını kıldın mı? 

Mübarek Ramazanlarda

Oruçlarını tuttun mu? 

Sağlığın yerinde miydi? 

Hastalanıp hep yattın mı? 

Maddi durumun iyiydi

Hac vazifeni yaptın mı?', 'Diyelim ki şu an öldüm. Burdan göçüp gideceğim. Türlü türlü sorulara, Nasıl cevap vereceğim?    Sorarlarsa neler yaptın?    Bir ömrü nasıl y...', ARRAY['Türk Edebiyatı','Şiir','Osman Sofuoğlu']::text[], 8.5, '{"poet":"Osman Sofuoğlu","poet_slug":"osman-sofuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olum-ve-sorgu-sual-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharlar Gelsin', 'baharlar-gelsin-osman-i-nci-bdtuc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeter bu üzüntüler, yeter gözyaşları,

Gözümde tütüyor, o gözleri, kaşları,

Unutalım artık biz, yağan bu karları,

Kederler dursun da, mutluluk gelsin…

Her yağmurdan sonra, güneşler açar,

İşte o zaman gülsün, bu acı bakışlar,

Bu yürek yokluğunla, her gün ağlar,

Hüzünler dursun da, tebessüm gelsin…

Ayrılıklar acıtır, kanatır bu yüreğimi,

Anlatamam sana, bitmeyen sevgimi,

Gel artık uzaklardan, tutuver ellerimi,

Hasretler dursun da, sevgiler gelsin…

İsmin bir duadır, hep okunan dilimde,

Resmin duruyor, uyurken bile elimde,

Her mevsimde, güller açsın gönlümde,

Hazanlar dursun da, baharlar gelsin…', 'Yeter bu üzüntüler, yeter gözyaşları, Gözümde tütüyor, o gözleri, kaşları, Unutalım artık biz, yağan bu karları, Kederler dursun da, mutlulu...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/baharlar-gelsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Zamanı Geldi', 'artik-zamani-geldi-osman-i-nci-tvx1z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Acılar bu beynime, balyoz gibi vuruldu,

Bedenim yaprak gibi, elden ele savruldu,

Yaşam boyu sorular, yalnız bana soruldu,

Soru soran olmanın, artık zamanı geldi…

Ağladım yıllar boyu, umursayan olmadı,

Acı çektim günlerce, benim çilem dolmadı,

Kafaya koydum şimdi, başka çare kalmadı,

Gülen taraf olmanın, artık zamanı geldi…

Mutluluğa rest çekti, işte bu deli yürek,

Her kavganın sonunda, bükülüverdi bilek,

Şimdi anlıyorum ki, boşa çekmişim kürek,

Yaşamdan tat almanın, artık zamanı geldi…

Çektiğim çile bitti, güzel günler geliyor,

Sevilmek benim hakkım, cümle alem biliyor,

Sadece dilim değil, yüreğim de söylüyor,

Aşık olup sevmenin, artık zamanı geldi…', 'Acılar bu beynime, balyoz gibi vuruldu, Bedenim yaprak gibi, elden ele savruldu, Yaşam boyu sorular, yalnız bana soruldu, Soru soran olmanın...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/artik-zamani-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Düşünceleri', 'yalnizlik-dusunceleri-murat-topcu-cwtdt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'düşünüyorum yine

seni düşünmenin alışılmışlığıyla

birden doluveriyor yüreğime

o güzel, sıcak sevgin

dinliyorum ezgilerde sen

görüyorum bir martının kanadında sen

öylesine bütünleştinki gökyüzüyle birlikte sarıyorsunuz beni

mavi gökyüzü ve sen

sonra imkansız diyorum

kıramayız biz bu tabuyu

kalıyorum yine yapayalnız

birtek mavi gökyüzü yanımda 

sense çok uzaklarda', 'düşünüyorum yine seni düşünmenin alışılmışlığıyla birden doluveriyor yüreğime o güzel, sıcak sevgin dinliyorum ezgilerde sen görüyorum bir m...', ARRAY['Türk Edebiyatı','Şiir','Murat Topçu']::text[], 8.5, '{"poet":"Murat Topçu","poet_slug":"murat-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalnizlik-dusunceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
