INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giz Buhranı (Yarın Olacak mı?)', 'giz-buhrani-yarin-olacak-mi-aysen-gacan-gulbag-31nvr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '“Her şey yazılmak için var.” 

                                              İlhan Berk

Umudun elleri armut topluyorken

yağmurda zıplayan tanelerini saydım aklımın

sıra dışı sıradanlıklar döner dolabına

raptedilmiş hayatın

artık berraklaşamayacak atık

sularında yüzüyor yüzüm

ellerimin delik deşik kalburunda kalan 

hiçle vedalaşamıyorken

işkencelere sokuluyorum yüz bin kere itirafçı

dalgasını geçiyor aşk benimle

eşşek sudan gelinceye dek 

dövülmüş ve yorgun

adımın tüm çekimleri

posamdan bir parça bırakıyorum

her sürüklendiğim yere

zehrini salıyor her gece durmadan

hain ve gaddar parmaklar

aklımın mahfazasından içeri

		*

umut yoktur yaratılmazsa mut da..

aşkın karanlık odasındayım

ölümün fotoğrafları sırıtıyor 

en yumuşak taraflarıma

giz buhranı sonbaharda

yarın olacak mı?', '“Her şey yazılmak için var.”                                                İlhan Berk Umudun elleri armut topluyorken yağmurda zıplayan tan...', ARRAY['Türk Edebiyatı','Şiir','Ayşen Gacan Gülbağ']::text[], 8.5, '{"poet":"Ayşen Gacan Gülbağ","poet_slug":"aysen-gacan-gulbag","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/giz-buhrani-yarin-olacak-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili''ye Mektup', 'sevgili-ye-mektup-cengiz-karabela-q0grs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sözlerime başlamadan gözlerinden öperim

Seni ne çok özledim inan bana sevgilim

Ağladım aklıma gelince senle geçenler

Kahrolsun bana sensizliği ferman biçenler

Sonbaharsa eğer ayrılığımıza davet

Aşkımızın baharı bir gün gelecek elbet

Bu hasret bu özlem biter de kavuşamazsak

Gözüm arkada kalır ölür de buluşamazsak

Bekle sevgilim bekle sabrın sonu selamet

Sabredip bekleyenler bir gün kavuşur elbet

Senin için yazacak daha neler var neler

Elbet gerçekleşecek hep sen dolu seneler

Mektubuma son verirken hoşçakal derim

Sen dolu gözlerinden doya doya öperim.

(Trabzon-1991)', 'Sözlerime başlamadan gözlerinden öperim Seni ne çok özledim inan bana sevgilim Ağladım aklıma gelince senle geçenler Kahrolsun bana sensizli...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Karabela']::text[], 8.5, '{"poet":"Cengiz Karabela","poet_slug":"cengiz-karabela","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgili-ye-mektup-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Geç', 'cok-gec-aysin-bali-32twc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gün gelecek anlayacaksın seni nasıl sevdiğimi,

işte o zaman başını vuracaksın duvarlara,

sende benim gibi ağlayacak; 

gecenin karanlığında saklayacaksın göz yaşlarını,

ve beni hatırlayacaksın; 

hayalimle avunacaksın belki; 

belkide beni arayacaksın; 

ama faydasız ulaşamayacaksın bana! ....

kendini gecenin ıssızlığına bırakacaksın.....

beni yaşayacaksın attığın her adımda

ama artık ne yapsan faydasız

beni bulamayacaksın.....

Ben çoktan kendimi sensizliğin toprağına gömmüş olucam; ...

artık çok geç sevgilim çok geç! .......

beni bulamayacaksın! .................', 'gün gelecek anlayacaksın seni nasıl sevdiğimi, işte o zaman başını vuracaksın duvarlara, sende benim gibi ağlayacak;  gecenin karanlığında s...', ARRAY['Türk Edebiyatı','Şiir','Aysin Balı']::text[], 8.5, '{"poet":"Aysin Balı","poet_slug":"aysin-bali","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cok-gec-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Dinlesen Beni', 'bir-dinlesen-beni-efsun-aydin-par0h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlatacak çok şeyim var aslında sana bugün

Dün de vardı yaa…

Boşver! 

Ne zaman görüşsek bir koşüşturma, bir kovalama…

Bugün gel - yarın gitler.

Seni bilmem ama bana yetmiyor,

Böyle hayal etmemiştim ben 

Böyle olmasının sözünü de vermemiştin bana sen.

Yani ben yapabilecegimi sanmistim da

YAPAMADIM. Iste…

Bana kizma simdilerde …

Sandim ki bu efsun surer gider boyle

Ama is isten gectikten sonra

Kus ucup gider…

Kanatlarim var benim, çirpmak istedigim…

Bu ask adina gocup gitmeyi hedefledigim..

Ben ne oldum derken

Bir baktım ki

Hala ayni yerdeyim.

Efsun 

04.05', 'Anlatacak çok şeyim var aslında sana bugün Dün de vardı yaa… Boşver!  Ne zaman görüşsek bir koşüşturma, bir kovalama… Bugün gel - yarın gitl...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-dinlesen-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben nereye sen oraya işte...', 'ben-nereye-sen-oraya-iste-efsun-aydin-63k3g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ardından bakakaldığım o günlerin hevesindeyim hala…

Gizliden gizliye yokluğunu hissettiğim ve  bakışını özlediğim sana,

Neydi ve neden diye sorduğum sorunun bile cevabını aramamak…

Öylece, öylesine ve ne olacağını bilmeden hissetmek,

Sadece dokunmak ve bakmak…

Bugünümün düşüncelerinde varolman ve ötesi için varetmek isteği,

Tüm bunların ardından donup kalmak…

Neyin doğrusunu ve  neyin yanlışını kime göre yaşamak ve kime yaşatmak? 

Bu zoru aşmak ve  nefes aldıgını hissetmek,

Hakedilmeyenin üzerimde ki  lekesi ve kurtulamamak …

Yaşanan ve kırıntılarını toplayıp avuntu misali sığındığım anılarda ki hasar

Heves ettiğim herşeye bir adim yaklasip, gerisine kacmak! 

Seviyorum demenin bir insan için değeri ve sorumluluğunun taraflara etkisi …

Sonucuna katlanilabilinir bir gucun mucadelesi,

Her yas daha eskimek, eskidikce yenilenen duygular yasamak,

Yenilendikçe cocuk kalma istegi …

Ve cocukluktan korkmamak…

Hep ama hep o saflikta kalmak! 

Ve o cocugu asla aglatmamak…..', 'Ardından bakakaldığım o günlerin hevesindeyim hala… Gizliden gizliye yokluğunu hissettiğim ve  bakışını özlediğim sana, Neydi ve neden diye ...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ben-nereye-sen-oraya-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresizlik....', 'caresizlik-efsun-aydin-h7cwi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir güc var beni sana bağlayan...

Korkularım var ya sonu gelmezse diye...

Bu özlem kahrediyor beni, caresizim....

En derin duygumdur beni sana getiren 

Ve itiraf ediyorum ki sevgindir beni senle bir bütün kılan.

Gordugum ilk anla beraber varlıgınla yanımda oldugun icin tesekkur ederim Benim canım sevgilim.', 'Bir güc var beni sana bağlayan... Korkularım var ya sonu gelmezse diye... Bu özlem kahrediyor beni, caresizim.... En derin duygumdur beni sa...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/caresizlik-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babacığım Senin Geçmişin ve hayatın', 'babacigim-senin-gecmisin-ve-hayatin-munevver-duver-a0e37', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Babacığım sen,süper yakışıklı,uzun boyunla

Tertemiz kalbinle,çok vicdanlı huyunla

Aynı zamanda da; çok çapkınlıklarınla

Sen yaşamın en kralını yaşayan biriydin

Devrin ağası,güzellerin sevdalısıydın

Çiftlikler,araziler,bağlar bahçenle sen

Pasajların,villaların,evlerinle sen

Sayısızda; sevgilileri olan süperdin sen

Annem senin ilk göz ağrın ilk eşindi

Amcanın kızı,sülalenin yıldızıydı annem

1700 yıllarında Orta Asya’dan gelen kökenin

Devirlere göre devlette ileri görev alan soyun

 Sen yaşamın en kralını yaşayan biriydin

Annemi çok sevdin,ama çok üzdün

Sen sarışın mavi gözlü uzun boylu biriyle evlendin

Ondan oldu altı,birbirinden güzel çocuğun

Annemden yaptın,sekiz dünya tatlısı,kızların ve oğulların

En kral yaşamak buysa,sen krallar gibi yaşadın

Ali dedemin ilk çocuğuydun,çok şımartıldın

Her gittiğin yerde,sevdaların oldu şaşırdın

Sana baban,annen çok yüz verdi nazikleştirdi

İstediğin şehirde istediğin pavyonlar kapattırdın

Sence güzel yaşamak buysa en güzelini yaşadın

Sen paralarla,işlerinle,sevdalarınla uğraşırken

Annemde sana canını sıkarak kendine bakarak

O da; kendi işleriyle uğraşarak sana kızarak

Sen sarışını her zaman yanında taşıyarak

Yaşamak buysa,sen en güzelini yaşadın

Sen kendi işlerinle güzel aşklarınla oldun

Annem kendi işini yürütür onunla meşgul oldu

Mavi gözlü cici annem de hayatını yaşadı saltanatı oldu

Üçünüzde kendinizle,ilgilendiniz nasıl oldu

Güzel yaşamak buysa,saltanatlar sizinle  olsun

Ama on dört çocuk nasıl yetişti sorsanıza

Babaları yanlarında olmayan,arada görebilen çocuklar

Anneleri işi düşünüp eşine kızıp duran bir anne

Cici annede saltanatı peşinde kürkler giyerek gezen tozan

Para saltanatsa,paralı saltanatı yaşadınız siz baba

Çocuklarınızı paralar içinde mutlu etmeye çalıştınız

Hizmetçiler ve dadılarla bir arada titizce yaşattınız

Çok güzel eğitimler vererek hepimizi okuttunuz

Ama bir şeyi unuttunuz,onları şefkatsiz bıraktınız

Onlara konuşma hakkı vermeyip,çok otoriterdiniz

Güzel yaşamak buysa,siz en güzelini yaşadınız

Sonunda çocuklarınız çalışıp çoğu emekli oldu

Sizde saltanat,sağlık bitti hasta oldunuz

Cici annem öldü,lüks yaşamı bitirip mezara gitti

Annemde iş kadınlığını bırakıp,kendi canının derdine düştü

Bizlere de; büyük şefkatler vermeye çalıştı

Güzel yaşamak buysa,üçünüzde en güzelini yaşadınız

Sen babacığım sen,sonunda başa döndün

Annenle evlendiğin gibi o yıllara döndün

Sattın çiftlikleri,pasajları,arazileri,villaları sen

Hızlı ve güzel yaşadın,hem de; sağlıklı oldun sen

Daha üç yıl önce hasta oldun,beyin kanaması geçirdin sen

Bu yaşama kadar hayatının en güzelini yaşadın bence sen

Sonunda sen kanser hastası olarak 

Annemde bir kalp hastası iflas etmiş organlarıyla

Çekilip kabuğunuza baş başa yaşıyorsunuz

Yine de kahya ve hizmetçilerinizle eskileri anlatarak

Çocuklarınızdan hep telefon bekleyerek sizler

Hastane kapılarına durmadan uğrayarak

Yaşamak buysa şu anda en kötüsünü yaşıyorsunuz

Tek güvendiğim sensin sarı gülüm diyerek bana

Mali işlerinizi yükleyerek sizler bana

Neredesin Münevver  diyerek günde beş kez arayarak

Siz nazlılarım,bana kendinizi nazlattırarak

Nazından da; çok keyif alarak sizler

Yaşam sizlere güzel olsun annem ve babam

Beni, kimsin diye merak edenlerin babama yazdığım

şiir''im ailemi ve beni,tüm soyumu anlatıyor....anlatıyor...                                                                                                                                                                                                      

   					

Kral babama ve canım anneme

Allah  rahmet etsin cici anneme

13.02.2004

Huzurkent/ADANA			

Cuma  Saat.04:12', 'Babacığım sen,süper yakışıklı,uzun boyunla Tertemiz kalbinle,çok vicdanlı huyunla Aynı zamanda da; çok çapkınlıklarınla Sen yaşamın en kralı...', ARRAY['Türk Edebiyatı','Şiir','Münevver Düver']::text[], 8.5, '{"poet":"Münevver Düver","poet_slug":"munevver-duver","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/babacigim-senin-gecmisin-ve-hayatin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kedi'' m...', 'kedi-m-efsun-aydin-9386t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kedi mi miyavliyor orada? 

Ne istiyor ki cani…

Aylardan mart mi yoksa kapıdan baktırıp hani kazma kürek yaktıran …

Aç mı bıraktılar seni güzel kedicik söyle…

Ne istiyor ki canın böyle…

Ne kadar da benziyorsun bana öyle...

Dilinin ucunda da konuşamıyorsun değil mi? 

Hiç olmazsa kedisin be kedi kardeş…

Yaa biz? ! 

Konuşsak bir insanlık;  konuşmasak bir kedilik hali,

En doğrusu yine miyavla dur be kedicik…

Tıp ki biz de olduğu gibi…

Hala birbirimize miyavlarız da 

Bir yumak bulunca unuturuz halimizi…

Dolaştı mı da çeker gideriz oradan.

Şimdi esas miyavlayan kim kedi kardeş? 

Hep beraber o zaman…

Miyavv miyavv miyavvv…

Efsun

04.05', 'Bir kedi mi miyavliyor orada?  Ne istiyor ki cani… Aylardan mart mi yoksa kapıdan baktırıp hani kazma kürek yaktıran … Aç mı bıraktılar seni...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kedi-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugun senin icin bir dilek tutmak istedim!', 'bugun-senin-icin-bir-dilek-tutmak-istedim-efsun-aydin-wtgdy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonunun ne olacagini bilememek,

Mesafeleri ozlem icin lehte kullanmak…

Bedenen uzakta saklı kalmak,

Istenilen yere tam akamamak…

Sormak; ve o esnada tikanmak,

Bilmek;  bildigini gizlemek,

Uzagina dusmek,

Tekrar yakinlasmak…

Tum gelgitler…

Bir dur ya da bu filmi bir yerden izledim deyisler…

Seviyorum derken ki basa donusler…

Hayatin gercekleriyle butunlesmek…

Uzaklara kacma istegi,

İki kisilik bir dunyada varolabilme dusuncesi…

Uykuya dalmak…

Ruyalarda yasamak tum ikilemleri…

Gercek dunyada yitirmek tum celiskileri..

Ama hala ne istedigini bilememek…

Tam biliyorum derken 

Ayni yuregi gorememek,

Pesin hayatina vade vade eklenmek,

Biriken borclarini odetmeden odemek…

Kimselere donmesin sevgi arkasini…

Ağır gelmesin yasananlar sevgi dolu yureklere hic! 

Mutlu olsun seven ve sevilen herkes…

Ve kimse kimsenin sevgi hakkini yemesin …

Dunyaya kim olarak geldigin degil bu dunyadan 

Kim olarak gittigin onemli cunku.

Sevgiler sonsuz ama asla sahipsiz olmasın.

Efsun AYDIN

04.05', 'Sonunun ne olacagini bilememek, Mesafeleri ozlem icin lehte kullanmak… Bedenen uzakta saklı kalmak, Istenilen yere tam akamamak… Sormak; ve ...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bugun-senin-icin-bir-dilek-tutmak-istedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım seni çekti bugün…', 'canim-seni-cekti-bugun-efsun-aydin-xxzd2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hem de en derininden bir nefesle.

Kalbim seni istedi bugün …

Tarifi olmayan yangınlara gebe duygularla.

Ne olacağımı bilmiyorum ben,

Ne olmak istediğimden de emin değilim.

Kime aşıkmışım ben meğer …

Kime sokulmuşum en safhane duygularımla da sömürülmüşüm bu kadar,

Neden hala o var ben de, bedenim de,beynimde? 

Neden? 

Sahip çıkamadığım neydi bu ilişkide 

Duygularım mıydı bizi sonlandıran yoksa hareketler mi? 

Onu seviyorum …

Bundan dahası ne olabilir ki….

Konuşmak boş, geçici kalp çarpıntıları anlık…

Zamansa hep alehte! 

Onu seviyorum …

Arasam …

Yapamam …

Gurur …

Beş para etmeyecek bu dünyada …

Kızgınım,

Kırgınım,

Herşeye rağmen 

Ben hala O’ na aşığım.', 'Hem de en derininden bir nefesle. Kalbim seni istedi bugün … Tarifi olmayan yangınlara gebe duygularla. Ne olacağımı bilmiyorum ben, Ne olma...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/canim-seni-cekti-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Sevgilimdin Sen Benim,', 'canim-sevgilimdin-sen-benim-efsun-aydin-r5grk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Canım Sevgilimdin Sen Benim,

Nasıl özlem duyuyorum sana, nasıl bir rüyada olma isteği hakim belleğimde anlatamam.Nedir bu kadar önemli ve özel kılan seni hayatımda çözemiyorum.Ne kadar çok seviyorum seni ben yaa...

Bir kerecik sesini duyursan bana ya da sadece bir defaya mahsus görsem seni...Bir kere öpsem, sadece bir kere yine eskisi gibi beraber olabilsek.

Rüyalarım hep senle olsa...

Sonra bitişler yaşasam doya doya tüm kötü şeyler için...', 'Canım Sevgilimdin Sen Benim, Nasıl özlem duyuyorum sana, nasıl bir rüyada olma isteği hakim belleğimde anlatamam.Nedir bu kadar önemli ve öz...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/canim-sevgilimdin-sen-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelsen mi gelmesen mi?', 'gelsen-mi-gelmesen-mi-efsun-aydin-f43dl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gelsen ayri bir dert,

Gelmesen ayrı…

Çıkamıyorum işin içinden.

Hala mı yazılıyor uğruna bunca şiir, bunca hikaye sonu asla gelmeyen…

Çalan her şarkı hatırlatır mı bir insanı bir insana bu kadar yoğun? 

Yeni aşklar var oysa ki kapımda...

Ben hiç riyakar olmadım ki kimselere.

Bencillik mi olur severken bir başkasını gönlüme almak? 

Çare bulmak gerek 

Biliyorum.

Ama ben seni severken, hala…

Alsan kurtarsan beni ve sadece biz olsa dünyamız

Sonra boy boy çocuklarımız…

Anlatacak bir yığın anımız, toplayıp biriktirdiğimiz sevgilerimiz…

Ben derim olsun …

Sonrası 

Boşver! 

Demeyenler utansın…

Efsun

Nisan 2005', 'Gelsen ayri bir dert, Gelmesen ayrı… Çıkamıyorum işin içinden. Hala mı yazılıyor uğruna bunca şiir, bunca hikaye sonu asla gelmeyen… Çalan h...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelsen-mi-gelmesen-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşılıklı Aşk', 'karsilikli-ask-efsun-aydin-zz2tx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karşılıklı sevmek  diye buna diyorlar heralde,

Her yaşadığım aşkın noktasında hiç kalmamışım ki hayatımda…

Noktası virgulü  hiçbir noktalama işareti yok ki bu duygunun sonuna konacak

Bulunmamış ya da gerek hiç duyulmamış

Çünkü ben ile sen ilk defa bir araya gelmiş

Bunu bir bilen, böyle buyurmuş.

Herkesler anlatmış hikayeyi de bir türlü uydurulamamış kahramanlar gerçeğe…

Gerçek zaten hiç düş olmamış ki,

Olsaymış yazılmamış bu şiir…

Hiç olmazmış Efsunlu bir dünya da yaşanan hayaller…

O bir rüyadaymış,

Göz açılınca uyanmış.', 'Karşılıklı sevmek  diye buna diyorlar heralde, Her yaşadığım aşkın noktasında hiç kalmamışım ki hayatımda… Noktası virgulü  hiçbir noktalama...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karsilikli-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haince Sevdin Sen Beni', 'haince-sevdin-sen-beni-efsun-aydin-dp3m6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimdi beni birtek aglatan bu hayatta

Ve kimdi içimi kaplayan siyahla

Neden bensiz kalmaya bu kadar tahammüllüydün sen? 

Ve neden beni hep ertelemek için uğraş verdin ki…

Seni sevmek boylesine bir aptallık mıydı yani…

Canımı sıkıyorsun her aklıma geldiğinde.

Aklıma gelmediğin an yok ki aslında…

Zaman geçtikçe acıyı daha derinimde hissediyorum.

Sensiz olmak kaldıramadığım birşey benim.

Bunu taşıyamıyorum artık…

Dayanamıyorum ben! 

Ne zaman yenileceğimide bilmiyorum.

Belki de en başta kaybetmişizdir birbirimizi kimbilir! 

Ben artık bulmak istiyorum seni …

Tüm gerçekliğinle hem de.

Beni bulmak için beklemeniyse yediremiyorum.

Kaybetme ihtimalin çok yakın oysa ki!', 'Kimdi beni birtek aglatan bu hayatta Ve kimdi içimi kaplayan siyahla Neden bensiz kalmaya bu kadar tahammüllüydün sen?  Ve neden beni hep er...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/haince-sevdin-sen-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nakarat Sevgi', 'nakarat-sevgi-efsun-aydin-qe306', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl istiyorum seni böyle tekrar tekrar….

Anlayamıyorum.

Sen benim yarımdın sanki.

Zor çok zor…

Dayanmak  zorlasıyor gün be gün.

Beynim aritmetik bir yan bulamıyor artık

Senin toplaman çıkarman yok

Bölmeye kalktıkça çoğalan bir yanın var tüm çarpanlarınla.

Biran da kapatmak istiyorum bu çekilmez yanımı

Kimseler görmesin istiyorum sana olan hevesimi

Hep saklamak istiyorum gün be gün yardıma ihtiyaç duyduğum zaaflarımı

Neye yarar ki bu gerçekle yüzleşmek

En son hangi halimdeysen

Ben hep O kızım…

Efsun', 'Nasıl istiyorum seni böyle tekrar tekrar…. Anlayamıyorum. Sen benim yarımdın sanki. Zor çok zor… Dayanmak  zorlasıyor gün be gün. Beynim ari...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nakarat-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim…', 'ozledim-efsun-aydin-rottp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özledim…

Hem de çok özledim

Yüreğim acıyor,yanıyor,sızlıyor…

Kimse olmasın ve birtek biz olalım…

Sahteliklerden uzak olan herşeyi kenarda bırakalım

Sen hatalarından arın, sadece ben olayım önemli…

Neden görmedin neden uzağımda kaldın hep…

Beni köpek gibi sevdiğini biliyorken üstelik! 

Neden neden neden…

Lanet olsun! 

Lanet! ! ! ! ! ! ! ! ! ! ! 

de ço közledim

Yüreğim acıyor,yanıyor,sızlıyor…

Kimse olmasın ve birtek biz olalım…

Sahteliklerden uzak olan herşeyi kenarda bırakalım

Sen hatalarından arın, sadece ben olayım önemli…

Neden görmedin neden uzağımda kaldın hep…

Beni köpek gibi sevdiğini biliyorken üstelik! 

Neden neden neden…

Lanet olsun! 

Lanet! ! ! ! ! ! ! ! ! ! !', 'Özledim… Hem de çok özledim Yüreğim acıyor,yanıyor,sızlıyor… Kimse olmasın ve birtek biz olalım… Sahteliklerden uzak olan herşeyi kenarda bı...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ozledim-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeyimsin...', 'herseyimsin-efsun-aydin-j8xuh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim herseyimsin,

Nefesimsin,atesimsin...

Atesimi sonduren ictigim su gibisin.

Oyle bir duygusun ki anlatamadigim

Her defasinda baslayip

Asla sonunu getiremedigim sarabin kanimda ki etkisi

Bu etkiyi bedenimde hissettigim sarhoslugumun ta kendisisin.

Kalbimde ki acı, o acıya yasam veren kan gibisin.

Seni sevmekten öte yaptıgım hicbirsey yok artık,

Senle baslanan gün  yine seninle sona eriyor.

Kalp çarpıntılarıyla uyanıyorum simdilerde uykularımdan

Beni alıp baska baska insanlar yaptı bu sevgin senin

Kimi zaman gaddarım sana karsı

Kimi zaman yufka yurekli…

Ama seni bu derece sevdigimi bilen her ben 

Katilim oluyor,ölüyorum…

Ben seni hala caresiz seviyorum…

Artık o kalpte olmasam bile.', 'Sen benim herseyimsin, Nefesimsin,atesimsin... Atesimi sonduren ictigim su gibisin. Oyle bir duygusun ki anlatamadigim Her defasinda baslayi...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/herseyimsin-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimden geldiği gibi...', 'i-cimden-geldigi-gibi-efsun-aydin-y3zyj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni her dakika opmek istiyorum

Hicbir anin aleyhimize islemesini istemiyorum

Ne zaman aklıma gelsen hep yanımda hissediyorum

Tekrar tekrar Tanrima sukrediyorum

Biliyorum ki gozlerin kapandıgında 

Anılarım tum karanlıgını dolduracak

Ve asla sen de ki anilarim bitmeyecek...

Her yeni gun yeni bir anim hep senle olacak...

Yarın icin gozlerini kapatacaksin 

Ve sonra  sadece yasayacaksin', 'Seni her dakika opmek istiyorum Hicbir anin aleyhimize islemesini istemiyorum Ne zaman aklıma gelsen hep yanımda hissediyorum Tekrar tekrar ...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/icimden-geldigi-gibi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep aynı Eylem', 'hep-ayni-eylem-efsun-aydin-0ehd2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni sevmekten biran olsun vazgecemiyorum.

Cigerime isleyen bir yanin var senin.Mumkun degil sokup atamiyorum icimden seni.

Ne zaman vazgecmeye niyet etsem iste o an karsimda oluyorsun benim.

Seni oyle cok seviyorum ki... 

Bana o suan da bilmedigim ama birsekilde durdugun yerden oylesinde bir guc veriyorsun ki! 

Kalbim seni aciyla karisik istiyor seviyor ozluyor.

Anliyor musun?', 'Seni sevmekten biran olsun vazgecemiyorum. Cigerime isleyen bir yanin var senin.Mumkun degil sokup atamiyorum icimden seni. Ne zaman vazgecm...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hep-ayni-eylem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Demet Teşekkür', 'bir-demet-tesekkur-efsun-aydin-y0au7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tum noksanliklar icin de beni tamamladigin

Kalbime dayanma gucu verdigin

Ve butun olasiliklar icin de seninle oldugum icin 

Askimla sevgimle ve tum cabamla yanindayim canim sevgilim.', 'Tum noksanliklar icin de beni tamamladigin Kalbime dayanma gucu verdigin Ve butun olasiliklar icin de seninle oldugum icin  Askimla sevgimle...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-demet-tesekkur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duman Ettiler', 'duman-ettiler-murat-demir-7hbpf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Er diye çıktım meydana

Katılmak için gaydana

Kimdir diyerek bu dana

Tozumu duman ettiler

Önce başlandı tımarla

Dert verdiler dert tomarla

Bir elense bir şamarla

Gözümü duman ettiler

Canımın yorgun kıratı

Yaşarım derken hayatı

Geçerken taşlı sıratı

Özümü duman ettiler

Bitirerek bir dilimde

Ömrümü, sevda selimde

Hasret alevken elimde

Közümü duman ettiler

Aşkı içimde bir beste

Yüreğim esir, kafeste

Ah çektikçe her nefeste

Sözümü duman ettiler', 'Er diye çıktım meydana Katılmak için gaydana Kimdir diyerek bu dana Tozumu duman ettiler Önce başlandı tımarla Dert verdiler dert tomarla Bi...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duman-ettiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderim, Sen Gidersen', 'giderim-sen-gidersen-mahya-sultan-tosun-rcgum', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sesini duyamamak bile 

Ne kadar yıkıcı oluyor.

Neden yokluğunu hemen hissediyorum

Neden sana hep ihtiyaç duyuyorum

Neden sana bu kadar bağlıyım

Neden yokluğunda kendimi eksik hissediyorum

Neden? Neden? 

Neden sen söz konusu olunca

Neden senin yokluğun, eksikliğin

Benim yetersizliğim oluyor

Neden? ? 

Sen gidersen ne olacak peki? 

Bilemezsin sen bunu

Sensizliği sen anlayamazsın

Ne menem birşey olduğunu bilemezsin

Sensiz bir dünyayı tatmaktansa

Hayalinle, anılarımızla

Sana olan sevgimle

Toprak olmayı tercih ederim.', 'Sesini duyamamak bile  Ne kadar yıkıcı oluyor. Neden yokluğunu hemen hissediyorum Neden sana hep ihtiyaç duyuyorum Neden sana bu kadar bağlı...', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/giderim-sen-gidersen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Zaman', 'zaman-zaman-mahya-sultan-tosun-sbf0k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Baharı yaşıyor yüreğim

Gözlerinin içi güldüğü zaman,

Sana doymak bilmiyor yüreğim

Bakışların sevgi saçtığı zaman,

Bazen ihtiyaç duyuyor yüreğim

Dudaklarından dökülecek sevgi sözcüklerine 

Zaman zaman...', 'Baharı yaşıyor yüreğim Gözlerinin içi güldüğü zaman, Sana doymak bilmiyor yüreğim Bakışların sevgi saçtığı zaman, Bazen ihtiyaç duyuyor yüre...', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/zaman-zaman-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonra', 'senden-sonra-mahya-sultan-tosun-hoyk5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Emin olduğum birşey var ki; 

Seni tanıdıktan sonra

Seni sevdikten sonra

Seni yaşadıktan sonra

Sensiz hayatın bir anlamı olmayacağı

Ve

Benim anlamsız bir hayatı asla yaşamayacağım! ..', 'Emin olduğum birşey var ki;  Seni tanıdıktan sonra Seni sevdikten sonra Seni yaşadıktan sonra Sensiz hayatın bir anlamı olmayacağı Ve Benim ...', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/senden-sonra-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen, Benimsin', 'sen-benimsin-mahya-sultan-tosun-r3ooa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen,

İlham kaynağım

Şiirler yazdıran sevgilimsin.

Sen,

Hayattaki amacım

Beni yaşatan sebebsin.

Sen, 

Ruhumun gıdası

Yüreğimin çiçeğisin.

Sen,

Her düşüncemin

Her hareketimin  öncüsüsün

Sen, 

Yaratanımsın

Varoluş nedenimsin

Sen, 

Benimsin

Sadece benimsin.', 'Sen, İlham kaynağım Şiirler yazdıran sevgilimsin. Sen, Hayattaki amacım Beni yaşatan sebebsin. Sen,  Ruhumun gıdası Yüreğimin çiçeğisin. Sen...', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-benimsin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zamanlar Aşk Vardı', 'bir-zamanlar-ask-vardi-efsun-aydin-p7rgw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzunca bir zaman önceydi 

Hali vakti çokta yerinde değildi esasen

Bir ihanet yemişlik vardı yüzünde

Bir hüzün, bir keder…

Ona nispet tebessümler…

Gözlerinin içine içine gülmelerdi, baktığımda aynaya gördüklerim.

Sonra korktum bende ki bu değişimden.

Aynı kalamamışlık ürpertti beni.kendimden.

İnançlarım sarsıldı bazen Tanrı ya

Çok ağladım çok isyan ettim kendi kendime 

Kimseyi kırmak istemedim hayatımda

Ne var ne yoksa kendimden aldım hayatıma girip çıkan herşeyin öcünü

Artık yorgunum ve aksi gibi cok da yoğun…

Hayat devam ediyor yaa…

Nefes alıp veriyoruz işte! 

Taa ki  o süreç tamamlanıp çekip gidene dek…

Can çekecek,

Gönülde hep aynı acıyı.

Bırakıp gitsen de 

Herşey ilk günkü gibi…

Çünkü; 

O ayna 

Hep aynı yüzü gösterecek.

Sen ne kadar değişsen de', 'Uzunca bir zaman önceydi  Hali vakti çokta yerinde değildi esasen Bir ihanet yemişlik vardı yüzünde Bir hüzün, bir keder… Ona nispet tebessü...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-zamanlar-ask-vardi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerekmez', 'gerekmez-asik-osman-feymani-8w39y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mihnetimiz yoktur dar-ı penaha,

Harabat ehliyiz dünya gerekmez.

Mecnun oluşumuz Didarullah’a,

Bulmuşuz Mevlâ’yı, Leyla gerekmez.

Sırat  korkusundan  yoktur kaygımız,

Can içinden gelir bize duygumuz,

Dost ile meşgulüz olmaz uykumuz,

Tabir etmek için rüya gerekmez.

Her halimiz geçti şeriat ile,

Kulluktan kurtulduk tarikat ile,

Marifete erdik  hakikat ile,

Biz vahdet ehliyiz, takva gerekmez.

İkrarı ezelde beli sözümüz,

Varlığından vücut buldu özümüz,

Vechi seyrullahtır gönül gözümüz,

Sıfata bakmağa ayna gerekmez.

Feymânî, bir nokta yazınca kalem,

Kevni mekan oldu, Kef  Nun ile hem,

Katremizde saklı felekler, alem,

Bahri umman olduk,derya gerekmez.', 'Mihnetimiz yoktur dar-ı penaha, Harabat ehliyiz dünya gerekmez. Mecnun oluşumuz Didarullah’a, Bulmuşuz Mevlâ’yı, Leyla gerekmez. Sırat  kork...', ARRAY['Türk Edebiyatı','Şiir','Aşık Osman Feymani']::text[], 8.5, '{"poet":"Aşık Osman Feymani","poet_slug":"asik-osman-feymani","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gerekmez-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçelim bugün', 'i-celim-bugun-yusuf-ziya-leblebici-35z5x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu sefer suçlama yalan dünyayı

Çocukca bakıp da gülelim bugün

Bırak şu dertleri, bırak tasayı

Haydi şerefine içelim bugün

Bu akşam kadehler ardı ardına gelsin

Karanlık geceler dost oluversin

Bizdeki şenliğe nazar değmesin

Haydi şerefine içelim bugün

Gideceği yere gitsin gidenler

Kalanlar bizdendir, bizimdir günler

Elbet ardımızdan ağlamaz dünler

Haydi şerefine içelim bugün

Siyaha beyaza kardeş diyelim

Bizi anlayanı bir dost bilelim

Karanlık günleri bugün geçelim

Haydi şerefine içelim bugün

Yusuf Ziya diyor, bu senin günün

Bu gün dertlerini ediver sürgün

Yüzlerin gülünce parlıyor gözün

Haydi şerefine içelim bugün', 'Bu sefer suçlama yalan dünyayı Çocukca bakıp da gülelim bugün Bırak şu dertleri, bırak tasayı Haydi şerefine içelim bugün Bu akşam kadehler ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/icelim-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halk Düşmanlarına', 'halk-dusmanlarina-omer-liman-rgnfy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boşaldı avanenin netameli yal kabı,

Dolacakmı bakalım, evladü iyal kabı.

Verildi cümle şerrin, yed-ine hak payesi,

Zahir oldu anların, şecere-i mayesi.

Ehl-i Zevk-i zevalde, tükendi cuş-u huruş,

Bir günde müflis oldu, sahib-i sam-ı kuruş.

Hemdemi divaneye divane refik oldu,

Beşeri biçareye ilahi tevfik oldu.

Bil umum desiseyle, çalınmıştı, minare,

Anlaşılan odur ki, dokundu zülf-ü yare.

Sert oldu palancıya, kahr-ı çifte-i himar,

Fevt eyledi meflucen, ayılmaz ayn-ı humar.

Kimi canib-i şimal, kimi ehli sakalib,

Kimi mağrib-i galat, urbani, ehl-i salib.

Nal-ı kırat söküldü, kayıp oldu eğeri,

Kimi yenden yaralı, ulumakta diğeri.

Nısf-i aydın hacivat, sekti düzen ayağı,

Güttüğü karagözden, ahz eyledi dayağı.

Hun-i fem-i timsahın yaşlıdır, ayn-i pak-i,

Sicmi nısf-i barizde, zahir oldu helaki.

Sept-i ben-i israil, ol mağrib-i avradı,

Sindi gayz-ı galizi, söndü şem-i muradı.

Hafriyat-ı enkaza teavünü çare od,

Meded ey şemsi zuhur, ihsan eyle pare od.

Yunus demezmi hoca, istersen var bin hacca,

Aklında kıllet varsa, vuslat varmaz amaca.

Dünya, ukba vaadi, efsun ile tutmadı,

Çaldı silleyi millet, ayaküstü yatmadı.

Saadetler nedamet oldu, rey ikibuçuk,

Şişti ayn-ı müezzin hocanın rengi uçuk.

Dokuz onda dokuzla doğru döndü yalana,

Hamletmez oldu millet, yazık oldu palana.

Nısf-ı arz dar olmalı, bahçede devlet olmaz,

Hane-i bicveanda rahmet-u şefket olmaz.

Kıyılarda kurulan haneyi seller alır,

Savuranlar savrulur, varlığın yeller alır.

Bilmem nerenin yolu bilmem nereden geçer,

Her gün fırtına eken bir gün kasırga biçer.

Biride  var ki zahir, değmez an-ı teşhire,

Bir galiz rayihayı borçludur, teneşire.', 'Boşaldı avanenin netameli yal kabı, Dolacakmı bakalım, evladü iyal kabı. Verildi cümle şerrin, yed-ine hak payesi, Zahir oldu anların, şecer...', ARRAY['Türk Edebiyatı','Şiir','Ömer Liman']::text[], 8.5, '{"poet":"Ömer Liman","poet_slug":"omer-liman","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/halk-dusmanlarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menekşe Gözlüm', 'menekse-gozlum-yusuf-ziya-leblebici-1b3km', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gitme uzaklara gönül bahçemden

Seni koparırlar menekşe gözlüm

Düşer yaprakların gider bedenden

Seni soldururlar menekşe gözlüm

Kıskanırlar senin güzelliğini

Karartırlar senin al yüzlerini

Bir gün terkeyleyip gidersen beni

Seni bırakmazlar menekşe gözlüm

Mevsimlerden bahar, gökte yağmursun

Yüreğimde sevdam, benim şuhumsıun

Deşseler de beni çıkmaz ruhumsun

Seni alamazlar menekşe gözlüm

Sıkı tut ellerimden bırakma beni

Şu yedi cihanda aratma beni

Sakın ha daraltma bana sevgini

Seni seviyorum menekşe gözlüm

Su değmezse sana yaşayamazsın

Bu gönülden başka barınamazsın

Yusuf Ziya açmış sana kalbini

Benden gayrısına ısınamazsın', 'Gitme uzaklara gönül bahçemden Seni koparırlar menekşe gözlüm Düşer yaprakların gider bedenden Seni soldururlar menekşe gözlüm Kıskanırlar s...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/menekse-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar diye diye', 'yar-diye-diye-yusuf-ziya-leblebici-fb0qr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Temmuzda üşüdüm sıcak nafile

Dertlere büründüm yar diye diye

Yollarım kapanmış çıkmaz günlere

Ne hallere düştüm yar diye diye

Kaderim oturmuş bir çınar gibi

Ağlıyor gözlerim pınar misali

Bu nasıl bir sevda, bilinmez dibi

Ben ne günler gördüm yar diye diye

Diyardan diyara sürüldüm gittim

Ölmeden mezara gömüldüm gittim

Bir zalim elinden vuruldum bittim

Yaşıyorken öldüm yar diye diye

Sevdanın tadına doyamadım ben

Acının adını koyamadım ben

Güneşin ışığı güle vururken

Güle yüzüm sürdüm yar diye diye

Yusuf Ziya’m alır sazı eline

Dertli dertli vurur ince teline

Alır başın gider seher yeline

Seni düşünürüm yar diye diye', 'Temmuzda üşüdüm sıcak nafile Dertlere büründüm yar diye diye Yollarım kapanmış çıkmaz günlere Ne hallere düştüm yar diye diye Kaderim oturmu...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yar-diye-diye-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cahil adam', 'cahil-adam-yusuf-ziya-leblebici-0nwmf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Okuyunca adam m’oldun

Dili kırık cahil adam

Bu millete imam m’oldun

Aklı kayıp cahil adam

Su aklamayan derelerde

Paça sıvama boş yere

Aç gözünü bir seyreyle

Gözü kayık cahil adam

Haydi göster parmağınla

Kimi aldın sen yanına

Milleti boşa kandırma

Aklı kaçık cahil adam

Kendini bir şey sanıp da

Sataşırsın ukalaca

Kolaysa çık şu tartıya

Kilon kılçık cahil adam

Otur oturduğun yerde

Gözün dikme bu meclise

Seni yerler bir celsede

Kapı açık cahil adam', 'Okuyunca adam m’oldun Dili kırık cahil adam Bu millete imam m’oldun Aklı kayıp cahil adam Su aklamayan derelerde Paça sıvama boş yere Aç göz...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cahil-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni seviyorum diyebilmek', 'seni-seviyorum-diyebilmek-yusuf-ziya-leblebici-4c7uu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevmeyi biliyorsan eğer

Seni seviyorum diyebilmek ne güzel…

Hele seviliyorsan,

O duygu ki; Dünyaya değer! 

Sazın tezeneye hasreti

Elin parmağa muhtaçlığı gibi.

Ekmeğin unsuz

Kanın susuz

Olamayacağı gibi

Sevgiye köle

Sevilmeye gebeyken

Seni seviyorum diyebilmek ne güzel! 

Bulutları özgürce selamlamak

Sevdayı, bir kuşun kanadında yaşamak

Gökyüzünün maviliğinde

Seni seviyorum diyebilmek ne güzel! 

Özgürlüğü anlatan o dillerde

Sevmek, sevilmek kadar güzel! ..', 'Sevmeyi biliyorsan eğer Seni seviyorum diyebilmek ne güzel… Hele seviliyorsan, O duygu ki; Dünyaya değer!  Sazın tezeneye hasreti Elin parma...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seni-seviyorum-diyebilmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buram buram sılam kokar', 'buram-buram-silam-kokar-yusuf-ziya-leblebici-du2eb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu dağların ötesinden

Selam geldi sevdiğimden

Buram buram sılam kokar

İşlemeli mendilinden

Cigaramın dumanında

Sevdam tüter arasında

Buram buram sılam kokar

Tütünümün kutusunda

Yollar uzun gidilmiyor

Dağlarından geçilmiyor

Uyku tutmaz hasretimden

Gecelerim hiç bitmiyor

Buram buram sılam kokar

Alnımdan hep özlem akar

Vurup gitsem şu sılama

Yollarıma kurtlar çıkar

Bu hasretlik ateşten kor

Yanan ateş hiç dinmiyor

Yusuf Ziya’m gurbet çok zor

Zalim gurbet çekilmiyor', 'Şu dağların ötesinden Selam geldi sevdiğimden Buram buram sılam kokar İşlemeli mendilinden Cigaramın dumanında Sevdam tüter arasında Buram b...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/buram-buram-silam-kokar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne günahım var Allahım', 'ne-gunahim-var-allahim-yusuf-ziya-leblebici-ro652', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kollarımı sana açtım

Sevdiğimi biliyorsun

Ne günahım var Allahım

Bir mutluluk vermiyorsun

Acılar mı benim karım

Dertlerimle eziyorsun

Kapanıyor hep yollarım

Beni benden ediyorsun

Ağlatın hep güldürmedin

Bu yazıyı hiç silmedin

Ne günahım var Allahım

Kaderim midir bu benim

Yusuf Ziyam elim kırık

Sırtımdaki belim çıkık

Ne günahım var Allahım

Neden dünyam hep karışık', 'Kollarımı sana açtım Sevdiğimi biliyorsun Ne günahım var Allahım Bir mutluluk vermiyorsun Acılar mı benim karım Dertlerimle eziyorsun Kapanı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-gunahim-var-allahim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Of Of', 'of-of-mahya-sultan-tosun-uptlp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni tanımadan önce

Bu kadar akmazdı gözyaşlarım

Beni aramadığın günler arttıkça

Şelaleye dönüşüveriyor göz pınarlarım.', 'Seni tanımadan önce Bu kadar akmazdı gözyaşlarım Beni aramadığın günler arttıkça Şelaleye dönüşüveriyor göz pınarlarım....', ARRAY['Türk Edebiyatı','Şiir','Mahya Sultan Tosun']::text[], 8.5, '{"poet":"Mahya Sultan Tosun","poet_slug":"mahya-sultan-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/of-of-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esra ceyhanı hatırlatıyor', 'esra-ceyhani-hatirlatiyor-hasim-koc-c4h32', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ALLAH ın yarattığı özel vede nadide

Her şey bana  sevgilimiz

ESRA CEYHAN ı hatırlatıyor

Munis yumuşak huyuyla

Sanki  MELEK

Güler yüzü biblo gibi

Konuşuyor  bülbül  gibi

Güzelliği açılmamış gonca gül gibi

ALLAH nazardan korusun

ESRA CEYHAN çok özel

ESRA CEYHAN çok güzel', 'ALLAH ın yarattığı özel vede nadide Her şey bana  sevgilimiz ESRA CEYHAN ı hatırlatıyor Munis yumuşak huyuyla Sanki  MELEK Güler yüzü biblo ...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/esra-ceyhani-hatirlatiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir insanım', 'bir-insanim-yusuf-ziya-leblebici-2zh47', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne beyazım ne de sarı

Ayrılmayan bir insanım

Ben öndere tapmam ama

Yürüdüğü yolundayım

Göstermelik giyinemem

Özümde ben bir çıplağım

Kelimeler süsleyemem

Oynaşmayan bir insanım

İncil’i Tevrat’ı bilen

İnkar etmez bir adamın

Kuran’a kitabım diyen

Körolmayan bir insanım

Benim korkum ölmek değil

Ben dünyayı yaşayanım

Bir gün gelecek Azrail

Ben korkmayan bir insanım

Yusuf Ziya’m sağım ama

Bir gün gelir çıkar canım

Dünya kalmaz padişaha

Ben anlayan bir insanım', 'Ne beyazım ne de sarı Ayrılmayan bir insanım Ben öndere tapmam ama Yürüdüğü yolundayım Göstermelik giyinemem Özümde ben bir çıplağım Kelimel...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-insanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulmuştum', 'bulmustum-hicret-katirci-6e19c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seninle Görüştüğümüz İlk An Varya; 

Yeniden Ümitlerimin Yeşerdiği Andı.

Kaybolan Yıllarımın Geriye Döndüğü,

O An: Çektiğim Acıların Bittiği Andı.

Sen... Yeniden Beni Hayata Döndürmüştün.

Geceleyin Gökyüzünde Parlayan Bir Yıldız Gibi,

Bana Aydınlık, Hayat Ve  Mutluluk Vermiştin.

Değişmisti Dünyam, Ben Farkında Olmadan.

Ama, Farkında Olmadığım Bir Şey Vardı,

Senin Çocukluğun! Yaşamı Sevmediğin.

Öğrendiğimde, Artık Cok Geçti Hepsi İçin.

Yine Ben, Eski Dünyama Dönmüştüm.

Ben Böyle Yaşama Da Alışkınım Güzelim

Behçemde Bir Patlıcanım Birde Kuru Ağacım Var.

Götüremez Beni, Ani Çıkan Fırtınalar,

Yagmur Olsan Ne Olur? Ya Da Bir Demet Çiçek...

(03 Eylül2002    00.15)', 'Seninle Görüştüğümüz İlk An Varya;  Yeniden Ümitlerimin Yeşerdiği Andı. Kaybolan Yıllarımın Geriye Döndüğü, O An: Çektiğim Acıların Bittiği ...', ARRAY['Türk Edebiyatı','Şiir','Hicret Katırcı']::text[], 8.5, '{"poet":"Hicret Katırcı","poet_slug":"hicret-katirci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bulmustum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Güneş Gibi', 'bir-gunes-gibi-huseyin-erdogan-8n986', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sakın hiç üzülme

hava sisli puslu diye

bu gün yine

bir güneş gibi

doğdun günüme

hem de 

pırıl pırıl

ben de

sevgi oldum

bir pınar gibi

şırıl şırıl 

aktım yüreğine

bil ki

kalbimde bahar oldun

açtın rengarenk

inan olacak ikimizde

mükemmel bir ahenk

günün şu ana kadar

nasıl geçti söyler misin? 

dilerim gülüyordur

o harika gözlerin

konduğun dalların

kırılmasın ömrünce

dünyan aydınlansın

gündüz ve gece

ne olursun 

adını ezberlet bana 

hece hece

bu dünyada

yeter artık çektiğim

boğ beni sevince

yoksa bir gecede

delireceğim sevdiğim

                 18.04.2005', 'sakın hiç üzülme hava sisli puslu diye bu gün yine bir güneş gibi doğdun günüme hem de  pırıl pırıl ben de sevgi oldum bir pınar gibi şırıl ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bir-gunes-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yedi Tepe', 'yedi-tepe-senol-ozuturk-4wglz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir akşam yangınlardan gelirim İstanbul

Alevlerini söndürmediğin

Küllerin saklı kalmış bende İstanbul

Cesaretsizliğini kalbime kilitlediğim.

Sensizliğin ızdırabı  nedir diye sorma İstanbul

Sensizliğin bana yaptıklarını hiç sorma.

Beyoğlunda gezip gözlerimi süzemiyorum

Dolaşamıyorum meyhanelerini İstanbul.

Notayı şaşırmış şarkıların anlamını çaldı kalbimden

mürekkep bile damlamaz oldu kalemden.

Sen gelme diye aklıma

Her gün ceza yazıyorum gülmeyen bahtıma.

Tarihini bilmediğim yıllar geliyor aklıma İstanbul

Islanmadığımız yağmurlar

Kaldırımında yürümediğimiz yollar.

Tozlu raflardan çıkartıyorum

Karacaahmette tazelenen bayat acıları

Bunlar adını koyamadığım

Taş sektirip kalbura çevirdiğm sahillerde

Yitirdiğim sevdanın sancıları.

Belanın içinden kopup gelen martıların 

Kanadındadır ayrılık dediğin alınyazıları.

Köprülerin sevdalıları kavuşturuyor mu İstanbul? 

Vuslatı bekleyen al işlemeli mendillerin sana sığınıyor

Bohçasını sarıp kaçan gelinlerin.

Sisli sabahlara başlarken yak bir sigara

Ey! Efkarını dindiremediğim koca çınar.

Aşılar ki sende kavuşur

Dargınlar sende barışır

gözyaşlarım boğaza karışır İstanbul.', 'Bir akşam yangınlardan gelirim İstanbul Alevlerini söndürmediğin Küllerin saklı kalmış bende İstanbul Cesaretsizliğini kalbime kilitlediğim....', ARRAY['Türk Edebiyatı','Şiir','Şenol Özütürk']::text[], 8.5, '{"poet":"Şenol Özütürk","poet_slug":"senol-ozuturk","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yedi-tepe-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''da Güneş', 'i-stanbul-da-gunes-musa-yasaroglu-3du43', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir başka doğar İstanbul''a güneş

Cilalar baştan başa boğazı

Martılar biraz daha alçak uçar semada

Türkü sanmışçasına vapur ıslığını

Gökdelen olur gözlerde Kız Kulesi

Çıkıldıkça cennet görülür her yerinden

Ve bir perde olur cehenneme

Karacaahmet''in boylu servilerinden

Güneş her gün bir kez daha

Fatih''e eşlik eder sanki fetihte

Yeniden yıkar Konstantin surlarını

Ve bayrağı son kez çeker göklere

Oklar kahramanı Ulubatlı

Sıraya dizilir açılmak için

Sultanahmet''in nazlı gülleri

Titretir zerre-i alemi her ezanda

Eyüp Sultan''ın kanatsız bülbülleri

Güneşin gidişi ağlatır tüm şehri

Son kez yakamozda görür onu gözler

Ondan sonra fasl-ı hazandadır İstanbul

Artık sessiz bir bekleyiş ile 

Karanlıklar içinde sabahı gözler', 'Bir başka doğar İstanbul''a güneş Cilalar baştan başa boğazı Martılar biraz daha alçak uçar semada Türkü sanmışçasına vapur ıslığını Gökdelen...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/istanbul-da-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yokmusun?', 'sen-yokmusun-hicret-katirci-9k3cv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep düşünüyorum da,

Senle ne günlerimiz geçmişti değil mi? 

Hele o salkım söğütün  altında oturuşumuz..

Sevda yemini edişimiz ne güzeldi değil mi? 

Hani, o tek kürekli sandalımız vardı..

Sen tek küreği çekip bende elimle suyu yarıyordum.

Kıyıdan biraz uzaklaşıp,

Mavinin arasında kayboluyorduk.

Bazen uzanıyorduk.

Kırık dökük sandalımızın içine..

Sen başını göğsüme koyup,

Bense kollarına yatıp,

Hayallerimizi fısıldıyorduk birbirimize...

Bazen el ele kimsesiz, sessiz sahillerde

Dolaşmayı seviyorduk.

Bazense akıp giden ırmakların,

Denizle buluştuğu yerleri geziyorduk.

Sanki onlar bizi, bizde onları taklit ediyorduk...

Saka kuşu bizim için ötüyordu,

Martılar bizim için uçuyordu.

Deniz dalgasını bize doğru gönderiyordu.

Hepsi bizim için,

Çırpınıyordu sanki...

Gel gör ki; 

Biz bunların farkına varamadık.

Uykudaydık sanki..

Uyandığımız da ne sen vardın ne de ben,

Ne de aşkımız kalmıştı..

Oysaki bizler: bir kuru ağacın dallarıymışız.

Sen koynumda beslediğim bir yılan bile olamazsın..

Bende yılanı koynunda besleyen adam.', 'Hep düşünüyorum da, Senle ne günlerimiz geçmişti değil mi?  Hele o salkım söğütün  altında oturuşumuz.. Sevda yemini edişimiz ne güzeldi değ...', ARRAY['Türk Edebiyatı','Şiir','Hicret Katırcı']::text[], 8.5, '{"poet":"Hicret Katırcı","poet_slug":"hicret-katirci","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sen-yokmusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Analizler-III (Aydın Tiplemesi)', 'analizler-iii-aydin-tiplemesi-ugur-deniz-ulkegul-ygp93', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İki “yorumsuz” yazıdan sonra bu kez yoruma, düşünceye, düşüncenin 

“özgürlüğüne”açık bir yazıyla yeniden merhaba…Çok sesli, çok renkli tepkilerden sonra bu yazıda tarzımızı biraz değiştirip, sohbet havasına sokalım dedik....Sanırım bir kaç noktada “yanlış algılanma” gibi problemlerimiz var…

Efendim şu an ki ahval içinde kimseye “şirin” görünme lüksümüz olmadığı gibi, yine hiç kimsenin sözcülüğünü, elçiliğini yada kaba bir tabirle 

“yardakçılığını” yapacak konumda değiliz..Günümüz şartlarında iyi-kötü, doğru-yanlış ve yalan-gerçek kavramlarının iç içe durduğu bu ortamda yaptığımız, yapmaya çalıştığımız gayretini gösterdiğimiz konu sadece

“düşünmeye davet” ten ibarettir…Gerisini insanların kendi yargılarına bırakmak “insana” duyduğumuz saygının neticesidir…

Eskinin “Ulema”sı, yakın tarihin (halk dilinde)   “okumuş”u,ve şimdinin “Aydın”ı hakkında gerek düz yazı, gerekse bazı şiirlerimizde geçen yakıştırmalardan dolayı, incinen sitemde bulunan bazı arkadaşlarımız oldu…Zaten bu günkü konumuzun ana başlığı da bu…Aydınlarımız…

“Aydın” kelimesi çok seçenekli, göreceli bir kavram…Havanın durumu, Rüzgarın yönüne göre değişkenlik gösterebiliyor.Basit bir Türkçe sözlükteki

anlamı: Okumuş, ileri düşünceli kimse…

Elbette biz bu kelimeyi bu kadarla sınırlı tutmayacağız…Biraz açalım isterseniz…Birlikte…

Hiç Çin’ li bir Aydın nasıl olur diye düşündünüz mü? Küçük çekik gözleri ile size ülkesinden bahsettiğini düşünün…Ülkesinde Demokrasi olmayan Aydın…Bir çocuktan fazlasına yasa gereği izin verilmemiş Aydın…Ülkesinde

stadyumlarda bazı suçları işleyenlere karşı önce bir tabak pilav, sonra ense köküne bir mermi ikram edilen Aydın…Ne oldu? Çok mu canice geldi..

Böyle bir ülkenin Aydını olamaz mı? Yada daha kritik bir soru…Olursa, nasıl olur? 

Peki Hintli bir Aydın? Öküze tapılan bir ülkenin Aydını…Trafiğin bile bu şirin hayvanlar sebebi ile yeri geldiğinde durma noktasına vardığı, kazara birini ezseniz ağır suçlara çarpılacağınız bir ülkede nasıl Aydın olunur? Efendim? Duyamadım? Yok mu dediniz? 

Ya Kongo? Sizce orada ormanda yaşayan Kabilelerde ki büyücülerin vasfı nedir? Büyücü mü? Falcı? Öğretmen? Doktor? Bilge? 

“Bir gergedan avlayacaksın...Boynuzunu bakır kapta altı saat kaynatıp,

evinizin bahçesinde dokuz tur atarak suyunu toprağa serpeceksin…Artık kötü ruhlar seni rahatsız etmeyecek…” 

Bilin bakalım Hiroşima’ya atılan atom bombasının mucidi kimdir? Çin’li bir sokak serserisi? Hintli bir dansçı kız? Afrikalı bir kabile şefi? Batılı bir Aydın olabilir mi? 

Okumuş…İleri görüşlü…

Ya onu atanlar…Ya atıldığında ertesi gün Amerikan basınında yapılan yorumlar…Üç yaşında bedeni kavrulan küçük kızın teninde ki “Siyahlığın” sebebi, failleri, “cahil” kimseler olabilir mi sizce…

Aydın deyince ne anlıyoruz? Yazar mı? Şair mi? Mühendis mi? Akademisyen…

Doktor…Pilot...Peki Milletvekili hangi sınıfa giriyor? Hani şu “yönetenler…

”Neyse..Bu işin esprisi..Konumuz bu değil…

Son yazdığım bir şiirde aynen şu cümle geçiyordu…

/”Aydın” denilen “hain” tiplemesi…/

Bu ve benzeri cümleleri son zamanlarda çok sık kullanıyorum..Gerekçelerim var tabi…Ama özellikle bu son cümle oldukça fazla tepki aldı…Kimi “Faşist” kimi “Görgüsüz” kimi de “Bağnaz” yakıştırmalarında bulundu…Hoş, kimi milliyetçi çevrelerden de “güzel iltifatlar” almadık değil…Burada yazmanın olanağı yok, mazur görsünler...

Bir çok konuyu çok iyi biliyor olabilirsiniz…Çok kültürlü, çok saygın, çok bilgili…Ve kendinizi akla gelebilecek bir çok konuda iyi yetiştirmiş olabilirsiniz…Bu özellikler sizi “Aydın” yapar mı? Bakın Aydın konusunda Gazi Mustafa Kemal ne demiş…Okuyalım, ondan sonra tartışalım…

“... bir ulusun kafası bozuk oldu mu, orada halkın büyük çoğunluğunun amacı başka bir hedefe, kendilerine ‘aydın’ denilen kesim ise, başka bir zihniyete sahiptir. Bu iki kesim arasında, tam bir uyuşmazlık, tam bir karşıtlık vardır. Aydınlar, asıl kalabalığı kendi amacına yönlendirmek ister; halk ve yoksullar ise, bu aydınlara bağlanmayı istemez; o da, başka bir yön belirlemeye çalışır. Aydın kesimi, yol gösterip akıl vermekle, çoğunluk halkı, kendi amacına inandırmayı başaramazsa, başka araçlara başvurur, halka hükmetmeye, ona zor kullanmaya başlar; halkı baskı altına almaya kalkışır. İşte burada asıl irdelenecek noktaya geldik. Biz halkımızı, ne ilk yöntemle,ne de zor kullanıp dayatmakla, kendi hedefimize sürüklemeyi başaramadığımızı görüyoruz, neden? ..”

Bu cümleleri alıp şimdiki zamana koyarak değerlendirelim…

Mustafa Kemal’in “Aydın denilen kesim ise, “Başka” bir zihniyete sahiptir” cümlesinde ki “Başka” kelimesine dikkat ediniz…Ve    Bu “başka”nın nedenlerine doğru yöneliniz…Bir “Aydın” kendi halkından daha ileri görüşlü, daha bilgili, daha sosyal, daha aktif olabilir ve olmalıdır da…Ama daha başka olamaz…Olursa ne olur? Sanırım bunun cevabı yeterince açık…Devam edelim…

 “... (çünkü)   bunu başarmak için,” aydın kesimiyle halkın zihniyet ve hedefi arasında, doğal bir uyum olmak gerekir”; yâni, aydın kesiminin, halka vereceği akıllar, “halkın ruh ve vicdanından alınmış olmalı.” Oysa bizde, öyle mi olmuştur? Aydınlarımızın halka gösterdiği yollar, ulusumuzun ruhundan alınmış idealler midir? Kuşkusuz hayır! Aydınlarımız arasında çok iyi düşünenler vardır; fakat genel olarak şu yanlışa düşeriz ki, inceleme ve araştırmalarımıza temel olarak, neredeyse daima kendi ülkemizi, kendi tarihimizi, kendi geleneklerimizi, kendi özellik ve gereksinimlerimizi almayız. Aydınlarımız belki bütün dünyayı, bütün diğer ulusları tanır, fakat kendimizi bilmeyiz...”

Evet…Sanırım bu “başka zihniyet” cümlesinin açık cevabı burada verilmiş oluyor…Aydının vereceği akıllar, “halkın ruh ve vicdanından alınmış değilse” o ülkenin geleceği karanlığa bürünmeye mahkumdur…Yani kendine değil de, “bir başkasına” benzemeye çalışan ”Aydın” kendinin değil,”benzemeye çalıştığı toplumun Aydınlığı için” çaba gösterir…Örneği değiştirip Yazar, Şair kavramından çıkararak çoğaltabiliriz…”Başka Zihniyette olan” Aydın bir Bilim Adamı, Aydın bir Öğretim Görevlisi, Aydın Bir Subay…

Allah Korusun ama, hele bu dönemde “Başka zihniyetli” Aydın bir Genelkurmay Başkanımız olduğunu düşünsenize…Irak’a girelim..

ABD bizim yakın dostumuz, canımız ciğerimiz diyen…Ne olurdu halimiz? 

“... aydınlarımız, ulusumu en mutlu ulus yapayım der; başka uluslar nasıl olmuşsa onu da aynen öyle yapalım der; fakat düşünmeliyiz ki, böyle bir düşünce, hiçbir zaman başarılı olmamıştır. (Çünkü)   bir ulusun mutluluk saydığı şey, diğer ulus, için felaket olabilir; aynı neden ve koşullar birisini mutlu ettiği halde, diğerini mutsuz edebilir. Onun için halka gideceği yolu gösterirken, dünyanın bütün bilimlerinden,buluşlarından,gelişmelerinden yararlanalım, ama unutmayalım ki, asıl temeli içimizden çıkarmak zorundayız...”

''Asıl temeli içimizden çıkarmak zorundayız…''  Kim çıkaracak? Nasıl çıkaracak? Neyle çıkaracak? Bazen düşünmüyor değilim…O dönemlerde yaşamak isterdim…Hani şu ülkenin dört bir yanında Hep birlikte başlatılan eğitim-öğretim seferliği, tarım ve sanayi alanında yapılan devrimler, Onurlu iç ve dış siyaset dönemleri…Acaba Atatürk öldükten sonra, bu ülkede rejim mi değişti? Yoksa rejimin sonraki sahiplerinde de “Zihniyet mi başkalaştı…” 

 “… milletimizin tarihini, ruhunu, gelenek ve göreneğini, doğru, sağlıklı, dürüst bakarak, görmeliyiz. İtiraf edelim ki, hâlâ ve hâlâ, aydın kesiminin gençleri arasında”, halkla ve   yoksullarla uyuşmazlık sürmektedir. Ülkeyi kurtarmak için, bu iki zihniyet arasındaki ayrılığı durdurmak; yürümeye başlamadan önce, bu iki zihniyet arasındaki uyumu gerçekleştirmek gereklidir. Bunun için de, biraz halk kitlesinin (yoksulların) , yürüyüşünü hızlandırması; biraz da aydınların, çok hızlı gitmesi lâzımdır. Fakat, halka yaklaşmak ve halkla kaynaşmak,daha çok ve çok daha fazla, aydınlara düşen bir görevdir...”

Mustafa Kemal böyle diyor ama, bu günkü “Aydın” tiplerine “başkaları tarafından verilen” “başka görevler” var…Mesela “Amerikan usulü Demokrasi” eğitimi vermek gibi…Mesela bir Mason icadı olan“İnsan Hakları” derneğine üye olup,“kendi ülkesi aleyhine faaliyet göstermek”  gibi…Mesela kendi halkının büyük bir bölümünü “aptal” olarak nitelendirip, sosyalist şovenist “şirinlikler” yapmak gibi…Mesela “Dış Emir” ile kurduğu onlarca derneğin başına “Türkiye” İsmini koyup, “Türkiye” aleyhinde her türlü dış bağlantı örgütleri ve dış istihbarat birimleri ile Ortak hareket eden “Sivil Toplum Örgütleri” yapılanmasına gitmek gibi…Mesela “Turizm”adı altında, “çok kültürlülük” kavramını esas alarak “etnik ayrılık” düşüncesini yerleştirmek gibi… Mesela mesela mesela…

Kelimelerin “sihirli” bir yanı vardır…Ve “Zihniyet Başkalaşımına” tabi olan bu “Aydın Tipleri” bunu çok iyi bilirler…Kullanmakta, uygulamakta oldukça mahir olduklarını söylememize gerek  yok sanırım…Ancak bu maharetleri, onların “Hain” sıfatlarını fark etmemize, görmemize ve anlamamıza engel teşkil etmez…

”Kendi” olmayı başaramamış insanların, “Dönüşmüş” “Başkalaşmış” fikir ve davranışları, bu insanları sadece ve sadece “okumuş” yapar…Lakin “Aydın” olabilmek bundan çok daha fazlasını gerektirir efendim…Siz hiç, “Türkçü” bir İngiliz aydınına rastladınız mı? Alman, Fransız? Efendim, duyamadım? 

Hepinize ''Aydınlık'' yarınlar diliyorum efendim....Saygılarımla…', 'İki “yorumsuz” yazıdan sonra bu kez yoruma, düşünceye, düşüncenin  “özgürlüğüne”açık bir yazıyla yeniden merhaba…Çok sesli, çok renkli tepki...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/analizler-iii-aydin-tiplemesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Şehir', 'beyaz-sehir-musa-yasaroglu-an3wl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beyaza açtım bu sabah gözlerimi

Taze bir gelin gibi hırçın İstanbul

Ve yaralı kuşlar kadar ürkek

Bir o kadar da yorgun bu yürek

Bulutlar yerde geçirmiş geceyi

Boğaziçi griyi çekmiş üstüne

Ve de güneş unutmuş görevini

Kapatıp kendini gökler ardına

Bitirmiş artık İstanbul seferini

Alabildiğince kalabalık Eminönü

Birbirini sarıyor her sıcak nefes

Dövüyor vapurları azgın dalagalar

Ses sesi kesiyor lanetler dudakta

İstanbul beyazken karanlıklarda

Kar, Beyazıt''ın yüreğine yağmış

Vücutlar titrek abdest başında

Yüzler hep soluk, gözler telaşlı

Kubbede huzursuz güvercinlerin

İstanbul söndü mü iman ateşin? 

Ayasofya beyaz döküyor gözyaşlarını

Günahlarını temizler gibi üzerinden

Ama bir hıçkıran daha var karşısında

İşte orada; bir tepe görünen

Yeşiline ağlıyor beyaz başlı Çamlıca

Gülhane''de yaslı bugün 

Ruhunu yitirmiş bir vücut

Yalnızlığı vuran saatler gibi

Kırgın ve ümitsiz bakıyor boğaza

Vuslatı bekleyen aşık misali

Anla artık, beyaz yakışmıyor sana

Yeşille uslanmış yaşlı İstanbul

Ak olmuyor alnın hiçbir beyazla

Sen yalnız seni yeşertecek

Islak güneşli, mavi gökler bul.', 'Beyaza açtım bu sabah gözlerimi Taze bir gelin gibi hırçın İstanbul Ve yaralı kuşlar kadar ürkek Bir o kadar da yorgun bu yürek Bulutlar yer...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/beyaz-sehir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hareket Yok!', 'hareket-yok-bulent-ahmet-alp-h65n4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tadını unutmuşum yaşamın...

Küçük,bazen çok küçük şeyler bile insanı harekete geçiriyor.

Ama öyle küçük mutluluklar yetmiyor işte...

Bazen kafamın bir mengeneye sıkıştırıldığını hissediyorum...

Çok fazla abartmıyorum,hayat bu...

Ve fazlasıyla gerçek...

Ne olup bittiğini anlamadan geçiyor zaman...

Bir labirente sıkışmış gibi,dönüp dolaşıp aynı yere geliyorum.

Önceden yaşadığım anları yaşıyorum yeniden...

Zaten aynı anı yaşıyorum...

Görmezden gelmek hiçbirşey yokmuş gibi...

Hep güzelmiş sanki...

Halının altına süpürülmüş pislik gibi görmezden mi geleyim? 

Biliyorum ki onlar oradalar...

Ve nasıl görmezden gelebilir ki bir insan? 

Sessiz kalmak bir ayırıcı özellik olabilir...

Ama çoğu zaman böyle olmuyor

Ve kaybolup gidiyor uğultu arasında...', 'Tadını unutmuşum yaşamın... Küçük,bazen çok küçük şeyler bile insanı harekete geçiriyor. Ama öyle küçük mutluluklar yetmiyor işte... Bazen k...', ARRAY['Türk Edebiyatı','Şiir','Bülent Ahmet Alp']::text[], 8.5, '{"poet":"Bülent Ahmet Alp","poet_slug":"bulent-ahmet-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hareket-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale', 'canakkale-hasan-kocamanoglu-59peb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ya Rap Celal’inin kahrını tez elden aşır

Şu Çanakkale yenilmez ibretini taşır 

Kutsal ruhların ayakları da ağırlaşır

Şu topraklar ezelden ebede sırlar taşır

Gelir, yedi düvelin kan kusan gemileri

Yiğitler dönmek nedir bilmez, hedef ileri

Zulüm kılıcı yakıp yıkar genç bedenleri

Çanakkale alır vermez, harbe gidenleri

Ateş kusardı zırhlılar hep mavi sulardan 

Yardıma gelirdi ruhlar, kavi ululardan

En samimi dualar ulaşır analardan

İbret levhası tarihe Anafartalar’dan

Gelibolu’da yılmaz yiğitler göğüs gerer 

İçer ecel şerbetini, şehitliğe erer

Şu türbeleri, şu uyanık yıldızlar bekler

Gök kubbenin altından saçılan nurlar ekler

Çanakkale hakikat ışıklarıyla dolardı

Binlerce canlar bu vatan uğrunda solardı

Şu âlem Türkün yüceliğini kucaklardı

Şehitlik şerbetiyle mutlu olacaklardı

Emelleri de gömülmüş, her yer mezar olmuş

Vahdet bahçesinde şu yatanlar şehit olmuş

Düşman emeli suya gömülmüş, hayal olmuş

Deniz, gök ve yer susmuş, yatanlar çok mesutmuş

Güllere sinmiş şehitliğin, senin kokundur

Çanakkale geçilmez, düşmana korkundur

Çanakkale hürriyetin ve özgürlüğündür

Tarihe şan ve şerefle yazılan gücündür

KM - 180305', 'Ya Rap Celal’inin kahrını tez elden aşır Şu Çanakkale yenilmez ibretini taşır  Kutsal ruhların ayakları da ağırlaşır Şu topraklar ezelden eb...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/canakkale-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Kahramanmaraş', 'ey-kahramanmaras-hasan-kocamanoglu-0aqer', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey Kahramanmaraş, Sen neler gördün neler

Savaşlarla, acılarla geçti seneler

Hitit, Asur, İran, Roma, Bizans, Araplar

Türkün damgası hepsini de birden paklar

İlçendir Pazarcık, Elbistan, Nurhak, Afşin, 

Göksun, Türkoğlu, Çağlayancerit, Andırın,

Ceyhan nehri bağrından çıkar, nazlı akar

Aksu koynunda yatar, baygın baygın bakar

Keşfedildiği günden bu yana, madenin

Şekli verilir Maraş’ta, Bakır, çeliğin 

Elindeki silah, Kahraman yaptı seni

Anadolu kaplanı, sen de al hisseni

Tohumdan toprağa, topraktan da pamuğa

Pamuktan ipliğe, iplik durdu kumaşa

Binboğa, Hazanlı, Engizek, Ahır dağın

Hala bin bir çeşit üzümler verir bağın 

Çam, kayın, sedir, gürgen ve meşe ağacın

Keklik, üveyik, toy ve turaçsız en acın

Göksun, Tekir, Fırnız ve Başkonuş dinlencen

Pınarbaşı, Kapıçam ve Kırksu eğlencen

Zeytin Ilıcan ise Ekinözü içmen

Firik, Tarhana ile meşhurdur dondurman

Bezdirme, sıkma, bükme ile hoştur yufkan

Keçe, sırma, bakır, çelikle eştir burman

Her üç kapının, ikisi şair bilinir

Üçte bir Türk senin kumaşınla giyinir

Sevdanın kıyısındandır sözün, destanın

Seni Maraş’a Kahraman yapar, unvanın

KM - 200305', 'Ey Kahramanmaraş, Sen neler gördün neler Savaşlarla, acılarla geçti seneler Hitit, Asur, İran, Roma, Bizans, Araplar Türkün damgası hepsini ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ey-kahramanmaras-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatay', 'hatay-hasan-kocamanoglu-rhdsz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Fransız’lara karşı her neferi, bir siperdi

Sınırları çizen, al kanlarıyla çizerdi

Hatay yaralıydı, ayrıydı ana vatandan

Hoş bir sada kaldı sana, güzellik atandan

Gökyüzünde ay yıldızlı bayrak dalgalanır 

Sana gönül koyanların yüreği dağlanır

Dünyada bir başka dengin de yoktur hiç senin

Yüzü güler, gönlü bir hoş olur, hep sevenin 

Antakya kültürlerden bir miras sunar sana

Huzur, barış ve mutluluk daima yan yana

Amik ovan uzanmış hep yatar sere serpe

Kırıkhan nazlı gelin, Kumlu daha çok körpe

İskenderun`da güneş batar, sular kızarır 

Belen yaylaya, Arsuz’un hep güneşe hazır

İs demir ülkeye çelik halatların serer

Dörtyol ve Erzin yaz kış narenciyeler derer 

Hassa’nın insanı hastır kendi adı gibi

Güzel üzümleri sunar, hep bal tadı gibi

Samandağı denize bakar, bakar evhamlı

Uzanır Yayladağı, Altınözü, Reyhanlı

KM - 050405', 'Fransız’lara karşı her neferi, bir siperdi Sınırları çizen, al kanlarıyla çizerdi Hatay yaralıydı, ayrıydı ana vatandan Hoş bir sada kaldı s...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hatay-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağla', 'agla-hasan-kocamanoglu-z10dh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çılgınca umutlarına

Dökülen gözyaşlarına

Umutsuz bakışlarına

Ağla gündüz - gece

Yüreğindeki hüzüne

Her vefasızın sözüne

Yangınlardaki özüne

Ağla gündüz - gece

Kırıp da astıklarına

Asıp da kestiklerine

Sevip de estiklerine

Ağla gündüz - gece

Boş geçen günlerine

Mevsimsiz güllerine

Karşılıksız sözlerine

Ağla gündüz - gece

Yüzündeki tebessüme

Hayaline ve düşüne

Zamansızın ölümüne

Ağla gündüz - gece', 'Çılgınca umutlarına Dökülen gözyaşlarına Umutsuz bakışlarına Ağla gündüz - gece Yüreğindeki hüzüne Her vefasızın sözüne Yangınlardaki özüne ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/agla-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yüzlü Gelin', 'gul-yuzlu-gelin-hasan-kocamanoglu-z0po6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Evlendiği gece, cepheye gitti yari

Susar, düşünür, bekler yanar anar gayri 

Kar beyaz eli, tatlı dili, billur kalbi

İlk günden çok mu gördü yar sevmeye Rabbi? 

Kar beyazından ak elbiseler giydiler

Beyaz atlarla gülen ölüme gittiler

Ölüm tarlaları kan revan içindeydi

Şehit olan yiğitler mesut biçimdeydi

Devrilen her fidan bir gözün bebeğiydi

Canlar, bedenler birer insan öbeğiydi

Bembeyaz kefenlerinden ruhlar çıkardı

Güvercinler gibi sonsuzluğa uçardı

Çakır ayazında karlar buza keserdi

Gül yüzlü bir gelin türküler bestelerdi

Hayat büyüsün kaybederdi hasretinden

Renkler siyahlara dönerdi mateminden

Gecelere ağlardı, yıldızlar sayardı

Şafaklara kadar gelecek diye yanardı

Gül yüzlü gelin, malını mülkü neylesin

Yarinden ayıranlar gün yüzü görmesin

Gelin, gönül mülkün viraneye döndürdü

Koca şehit, evlat yetim, ocak söndürdü

Gül yüzlü gelin ağlar da karalar bağlar

Gül yüzlü gelin, görenin yüreğin dağlar

KM-060305', 'Evlendiği gece, cepheye gitti yari Susar, düşünür, bekler yanar anar gayri  Kar beyaz eli, tatlı dili, billur kalbi İlk günden çok mu gördü ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kocamanoğlu']::text[], 8.5, '{"poet":"Hasan Kocamanoğlu","poet_slug":"hasan-kocamanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gul-yuzlu-gelin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılar Güzeli', 'acilar-guzeli-sair-calapverdili-hsn2q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Oysa ben sana

Nice baharlar bırakmıştım

Yüreğimin mevsimlerinden

Yediverenler toplamıştım

Üzerime sinen kokularından

Oysa ben sana

Kırkikindi yağmurları göndermiştim

İçime akan gözyaşlarımdan

Gecelerden yıldız toplamıştım

Saçlarındaki yakamozlara inat

Oysa ben sana

Vurulmuştum okların en acımazısıyla

Tam da kabuk bağlamışken

Aşkımızın tel tel yarası

Şimdi aynalar bana:

Ölü bakışlar odası

Ey acılarımın süzgecine takılıp

Beni nokta nokta sokan güzel

Ben seni 

Ay ışığından çalmıştım bir gece

Öksüz karanlıklar bırakmıştım

Tan ağarmalarına gebe

Oysa ben seni sürmüştüm

Ruhumun ağrılarına

Seni bulmuşken zambakların kokusunda

Şimdi yudumluyorum yalnızlığımı

Aşkımızın anısına', 'Oysa ben sana Nice baharlar bırakmıştım Yüreğimin mevsimlerinden Yediverenler toplamıştım Üzerime sinen kokularından Oysa ben sana Kırkikind...', ARRAY['Türk Edebiyatı','Şiir','Şair Çalapverdili']::text[], 8.5, '{"poet":"Şair Çalapverdili","poet_slug":"sair-calapverdili","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/acilar-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen misin, O?', 'sen-misin-o-ugur-deniz-ulkegul-gf0vi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Koynunda mı saklarsın gülüşümü? 

Gözlerinden damlayan buz sıcağıma, 

Ya nedir bıraktığın ''sus'', 

Hangi yokluğun sancısı düşer kucağıma... 

Sen misin 

Giden misin o? 

Bir ay ışığı gecede, 

Ayak izlerinden bellediğim... 

Yüreğime değen sancısından tanıdığım... 

Ve benden değil, 

Hep bir başkasından dinlediğim.... 

Görmediğim...Bilmediğim...Dokunmadığım... 

Sen misin 

Gülen misin o? 

Uykumun gizemli kuytusunda, 

Hani el verip gönül aldığım... 

Öncesiz zamanlardan çaldığım, 

Zamansız sonralarda yitirdiğim sen.... 

Ayrılık mı dedin? 

Kavuşmayı anlatmalısın önce, 

Hangi gecekondusunda saklıydım, 

Hangi sokağına yasaklıydım yüreğinin? 

Bir, ''gün'' var mı benim olan, bir ''gece''... 

Sen misin 

Ah ki yalan diyesim gelmez! 

De ki yalan dı bu aşk! fark etmez... 

Sevmiştim seni... 

Boş ver, çoktan giydim ceketimi, 

Artık çıkarmasan da olur güzel, 

Yüreğinin kalın elbisesini... 

Ayrılık mı dedin? 

Güldürme beni...', 'Koynunda mı saklarsın gülüşümü?  Gözlerinden damlayan buz sıcağıma,  Ya nedir bıraktığın ''sus'',  Hangi yokluğun sancısı düşer kucağıma...  S...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sen-misin-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayşe', 'ayse-serhat-yucel-3jsu8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'A dın dilimde her an Ayşem

Y aktın beni, duygularıma vuramıyorum gem

Ş ikayetçiyim senden,işitmiyorsun beni ne söylesem

E vet sensiz seninleyim ben her dem.....', 'A dın dilimde her an Ayşem Y aktın beni, duygularıma vuramıyorum gem Ş ikayetçiyim senden,işitmiyorsun beni ne söylesem E vet sensiz seninle...', ARRAY['Türk Edebiyatı','Şiir','Serhat Yücel']::text[], 8.5, '{"poet":"Serhat Yücel","poet_slug":"serhat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ayse-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı ve Mavi', 'kirmizi-ve-mavi-esref-uzulmez-ouvt8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidiyorsun! 

Kırmızı giy mavi bakışlım

Saçların dalgalansın,

Ellerim burada

Saçların okşuyor, uzatamadığım

Ellerimi

Gözlerin dalıyor maviye

Aşka susuyorum, acıyla

dayanamıyorum.

Kaldır bu kenti üstümden

dokunamıyorum.

Vazgeçtim! 

Kırmızı çok yakışıyor,giyme

orada

Saklı kalsın,hikayenin tam ortasında

Fark etmesinler

Ne maviyi,nede kırmızıyı

Şu anda saat kaç? Bilmiyorum

orada

Bütün saatler akşamı gösteriyor.

Hikayemize takılıyor yelkovan

Akrep kırmızı,sen mavi oluyorsun

Bütün zamanlarda

Ben sana,

dokunamıyorum

Bilmiyorum,bilmiyorum,bilmiyorum

Diyorsun,aşk''ı

Düş(sem) de gör,

Aşk''ın yakasından

Göreceksin bak martılarda ağlayacak

Mavi göz yaşlarıyla

Ne,uçurumlar kalacak

Ne de kırmızı saatler

orada', 'Gidiyorsun!  Kırmızı giy mavi bakışlım Saçların dalgalansın, Ellerim burada Saçların okşuyor, uzatamadığım Ellerimi Gözlerin dalıyor maviye ...', ARRAY['Türk Edebiyatı','Şiir','Eşref Üzülmez']::text[], 8.5, '{"poet":"Eşref Üzülmez","poet_slug":"esref-uzulmez","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kirmizi-ve-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belli ki;', 'belli-ki-i-smet-barlioglu-sjv64', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Belli ki; 

Ben, Tanrı ‘nın yarattığı en değersiz varlığım,

Ne yerim var, ne önemim bir elkızının yanında,

Umurunda bile değil varlığım, yokluğum,

Acırsa; dikenli yastığım acısın gözyaşlarıma,

Götürürse; rüzgarlar götürsün acılarımı,

Yıkarsa; yağmurlar yıkasın çilelerimi,

Bir büyük Tanrı ‘dan öte, kim ne yapsın ki; 

Beni? 

Ben; Mecnun ‘un ıssız çöllerde bıraktığı iz,

Ben; Kerem ‘in yanmış kemiklerinin külü,

Ben; Ferhat gibi külünk altında perişan olan yaralı,

Gün yüzü mü gördüm ki; 

Yaratıldım

Yaratılalı? 

Varsa bir zerre değerim; bir senin indinde Tanrı ‘m,

Yoksa; ne gündüzlerin benden yana, ne gecelerin,

Ne denizlerin, ne ormanların,

Ne saçıma karlar yağdıran zamanın,

Ne içinde bir karışlık yerim bulunan mekanın,

Ne yazın, ne kışın, ne baharların,

Bir elkızının eline geçmiş yüreğinden başka

Hiçbir şeyi yok

Fukaranın.

(GÜVERCİN isimli Serbest Şiirler ''inden > 77-78/100)', 'Belli ki;  Ben, Tanrı ‘nın yarattığı en değersiz varlığım, Ne yerim var, ne önemim bir elkızının yanında, Umurunda bile değil varlığım, yokl...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/belli-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Bilir?', 'kim-bilir-i-smet-barlioglu-lf7j2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kim bilir, içimde bir yüreğin çocuk gibi ağladığını? 

Gözyaşları döküp durduğunu bir köşede? 

İki elini göğsüne bağladığını öksüzler misali? 

Kim bilir, yanıp kavrulduğunu alevler arasında? 

Sine denilen şey camdan değil ki; 

Şunun şurasında.

Bir ben bilirim yüreğimin neler çektiğini,

Nice bir sellere kapılıp sürüklendiğini,

Nice bir yanıp kavrulduğunu alevler arasında,

Dumanının nice bir göklere yükseldiğini,

Küllerinin nice bir Kerem ‘leri tutuşturduğunu,

Bir ben bilirim bu kara başımla,

Gözlerimdeki bu kanlı yaşımla

Bir ben bilirim

Ve ben, bir elkızının ardında yıllar yılı

Ölüp ölüp

Dirilirim.

Ne hayalini tutup silebilirim gözlerimden,

Ne zerrelerimden kokunu,

Ne sesini kulaklarımdan,

Ne o körpe ellerinin temasını, ellerimden,

Bir ömür yerine binlerce ömür geçip gitse

Üzerinden.

(GÜVERCİN isimli Serbest Şiirler ''inden > 79-80/100)', 'Kim bilir, içimde bir yüreğin çocuk gibi ağladığını?  Gözyaşları döküp durduğunu bir köşede?  İki elini göğsüne bağladığını öksüzler misali?...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kim-bilir-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''a Sesleniş', 'i-stanbul-a-seslenis-kubra-gulbahar-ttp7y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstanbul, adına uçurum diyebilir miyim? 

Bir gün kalkacağımı bildiğim için,

Sende düşmekten korkmuyorum..! 

Hiç bitmiyor yolların...

Gizli karanlıkların başlıyor geceleri

Yine de sabaha tüm masumluğunla uyanıyorsun

Seni affetmeye hazır, yalnız senle mutlu

Yığınla insan biriktirmişsin kendinde...

Kimileriyse senin açtığın kollar güvensiz diyorlar

Ben sana sarılmaktan hiç çekinmiyorum, İstanbul! 

Biliyorum ki, geçmişin yorgunluğunu taşıyorsun

Bugünkü isyanlarında...

Halbuki bilmiyorlar! ! ! 

Sırrına varmaları için, 

Hep bir yanı saklı tuttuğun büyüklüklerin

Ve sana kör gözlerle bakanlar için

Cömertçe gösterdiğin küçüklüklerin var...

Hiçbir şehir senin kadar adil olmadı

Yine hiçbir şehir kalabalığı senin kadar güzel taşıyamadı...

Üzerine yalnızlık yüklediğin, gözleri donuk bakan ama içinden nehirler akan

Sana aşık, yorgun bir yürek yaşatıyorsun kendinde...

Bana verdiğin dertlerden gocunmuyorum, İstanbul

Seninle yaşamaya başlarken,

Mutlaka bir bedel ödeyeceğimi söylemişlerdi bana..! 

Bunlara hazırlıklıydım, yedi tepeli koca şehir..! 

Senden özgürlüğümü istediğimde, benden çocukluğumu alarak,

Seninle her zaman bir takas oyunu oynayacağımızı öğretmiştin bana...

Off İstanbul, bugünde beni çok yordun

Düşünüyorum da...

Bana ne çok şey vermişsin...

Benden ne çok şey almışsın...

Yine de seni seviyorum...

Sende doğdum...

Sana söz veriyorum yine sende öleceğim İstanbul!', 'İstanbul, adına uçurum diyebilir miyim?  Bir gün kalkacağımı bildiğim için, Sende düşmekten korkmuyorum..!  Hiç bitmiyor yolların... Gizli k...', ARRAY['Türk Edebiyatı','Şiir','Kübra Gülbahar']::text[], 8.5, '{"poet":"Kübra Gülbahar","poet_slug":"kubra-gulbahar","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/istanbul-a-seslenis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzülmeyecek misin?', 'uzulmeyecek-misin-i-smet-barlioglu-cnw5t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ömrüm kısaldıkça günüm değerleniyor,

Her günüm Reşat Altını değerinde anam-babam,

Doğan güne boynum eğri,

Batan güne eyvah ki; eyvah…

Geleceksen, artık gel uzaklardan,

Ne olacağı belli mi

Sabah? 

Bir bakarsın; el çekip gitmişim dünyadan,

Ayakizlerimi rüzgarlar alıp götürmüş,

Sesim silinmiş ormandan, denizden,

Kıyıdan, yamaçlardan,

Bir bakarsın; benimle birlikte

Ziyan olup gitmiş karasevdam,

Artık ne sana sevdalanan,

Ne ayaklarının dibinde ağlayan,

Ne de çilelerine ve zulmüne Eyüp Peygamber misali

Dayanan.

Aramayacak mısın sanıyorsun mahzun yüzümü? 

Üzülmeyecek misin sanıyorsun bir bekleyenin olmadığına,

Bir sevenin, uğrunda bir canverenin,

Seni senden çok düşünen birinin olmadığına

Üzülmeyecek misin sanıyorsun? 

Arkamdan gözyaşı dökmeyeceğine inanıyorsan; 

Aldanıyorsun.

(GÜVERCİN isimli Serbest Şiirler ''inden > 81-82/100)', 'Ömrüm kısaldıkça günüm değerleniyor, Her günüm Reşat Altını değerinde anam-babam, Doğan güne boynum eğri, Batan güne eyvah ki; eyvah… Gelece...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/uzulmeyecek-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelim benim', 'guzelim-benim-tuncay-akdeniz-5x99g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdamız düştü dile

Boyu güzelim benim

Yar etmem seni ele

Soyu güzelim benim

Sevdaya saldım başın

On beşi geçmiş yaşın

Hilal a benzer kaşın

Yayı güzelim benim

Sevdan eyledi deli

Sevdim mecnun misali

İkimiz aynı köylü

Köyü güzelim benim

Sen çiçek bende arı

İstemem dünya varı

Tuncay''ın olsan yarı

Toyu güzelim benim', 'Sevdamız düştü dile Boyu güzelim benim Yar etmem seni ele Soyu güzelim benim Sevdaya saldım başın On beşi geçmiş yaşın Hilal a benzer kaşın ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guzelim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Mayıs', '1-mayis-mustafa-gokcek-fr2o3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1 MAYIS

Yaşadıklarımı geçmişimle barıştırdığımda

Kızgınlıklarım, kırgınlıklarım ağır bastı

Yıllarca çıkınımızda biriktirdiğimiz kavgalarımız

Kuru bir söylevlere ve kuru bir anmalara dönüştü

Onurun duldasında lirik bir emek türküsü

Dağlarımda bahar, işçimle halay çekmeliyim

Kan kusarcasına değil, omuz omuza ve yüreklice

Nice ağalar ve nice puştlar hâlâ pusuda, ama yüreksizce

Bayramın kutlu olsun emekçim, şen olasın

İncir çekirdeğini doldurmayan geçmişinle

Kucakladığın devriminle ve 1 Mayısınla

Şanlı bayrağının altında şen olasın

Geçmiş zamanlarında geleceklere yol kat ettin 

İlerleyen bir yıldız kümesinin altında

Ve arşınladığın onca uğraşının yıldönümünde

Halkımın önünde, aydınlattığın bayrağı taşıdın

Gülmek pusatsız olmalı, ağlama emekçim

Seni bırakanları bir an bile satmadın

Işıldayan bir yüz, elbet yine ışıldar

Halkımla el ele yürürken şanlı devrimin yollarında

Kutlu olasın işçi kardeşim, benimle yaşadığın bayramın ve 1 Mayısınla…

15.04.05                                                                M.Gökçek', '1 MAYIS Yaşadıklarımı geçmişimle barıştırdığımda Kızgınlıklarım, kırgınlıklarım ağır bastı Yıllarca çıkınımızda biriktirdiğimiz kavgalarımız...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökçek']::text[], 8.5, '{"poet":"Mustafa Gökçek","poet_slug":"mustafa-gokcek","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/1-mayis-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyam', 'oyam-sair-salma-7vj3p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(Vefasızın birinden) 

           Olmasın artık sabah ne gezer

           Yarını beklemez günler sabırsız..

           Ağarsa saçlarım kar gibi beyaz

           Mecnun ben Leyla sen çöller sabırsız...

           Onsuz bir anım yok her yanımda

           Yapraksız açılan güller sabırsız...

           Aşkın yüreğimde canın canımda..

           Maveradan konuşan diller sabırsız', '(Vefasızın birinden)             Olmasın artık sabah ne gezer            Yarını beklemez günler sabırsız..            Ağarsa saçlarım kar gi...', ARRAY['Türk Edebiyatı','Şiir','Şair Salma']::text[], 8.5, '{"poet":"Şair Salma","poet_slug":"sair-salma","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/oyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Anne*', 'anne-seyhmus-sevilmez-gzr5g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dokuz aylık yük olmuşsam, taşımışsan sen beni

Doğar doğmaz ağlamışım,seni yormuşum Anne

O sütten şifa bulmuşsam, emip durmuşsam seni

Kalbe seni dağlamışım, hakkın sormuşum Anne

Cennet-i mekan dilersem, ayakların altında

Sana gönül bağlamışım, vefan olmuşum Anne

Hayır-duanı alırsam,  yer var  firdevs katında

Basireti sağlamışım, sefa bulmuşum Anne

Hak yoldan ırak gidersem, vebali var boynumda

Sözlerinle çağlamışım, düzen kurmuşum Anne

Sana yalan söz söylersem, iblis varsa koynumda

Kemendimi yağlamışım, dara vurmuşum Anne

Geceleri inlemişsem, sütten verdin kevseri

Uykusuzluk eylemişim, göze sürmüşüm Anne

Güzel sözün dinlemişsem, ben olmam hiç serseri

Hakkı kula yeğlemişim,kalbe dürmüşüm Anne

Seni bilmeden üzmüşsem, kalbin kırmışsam eğer

Kırda çiçekler yolmuşum, sana dermişim Anne

Sevgini kalbe süzmüşsem, gönlün almışsam değer

Canımdan  halı olmuşum, sana sermişim Anne

Ödemeden göçer isem, üstümdeki  hakkını

Mahşer günü beklemişim, secde durmuşum Anne

Helal sütün emmiş isem, ol sen Allah yakını

Dine iman eklemişim, kalbe örmüşüm Anne', 'Dokuz aylık yük olmuşsam, taşımışsan sen beni Doğar doğmaz ağlamışım,seni yormuşum Anne O sütten şifa bulmuşsam, emip durmuşsam seni Kalbe s...', ARRAY['Türk Edebiyatı','Şiir','Şeyhmus Sevilmez']::text[], 8.5, '{"poet":"Şeyhmus Sevilmez","poet_slug":"seyhmus-sevilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anne-135-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir...', 'siir-hikmet-feridun-demir-5q202', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duyguların damıtılmış özü...

Hisli yaşamımızda edindiklerimiz...

Objektif yaşananların, Subjektif olarak

Belleğimizde bıraktığı izler şiir olur...

Bizleri tüm yaşamımız boyunca yönlendirir...

Yaşadıklarımız, özlemlerimiz, hayallerimiz, 

Yaşamımızın  acı ve tatlı yanları...

Bizimle birlikte şiirsel olarak,

Yaşamımıza eşlik eder..

Nihai olana kadar...

Yaşam, yaşanmışlıklar 

Şiiri olur ruhumuzda...', 'Duyguların damıtılmış özü... Hisli yaşamımızda edindiklerimiz... Objektif yaşananların, Subjektif olarak Belleğimizde bıraktığı izler şiir o...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/siir-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar', 'cocuklar-rifki-kaymaz-nu14l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocuklar bir güldür vatan bağında

Kurur yaprakları ağladığında

Bugün, küçücük bir pınar belki

Yarın bir şelale çağladığında', 'Çocuklar bir güldür vatan bağında Kurur yaprakları ağladığında Bugün, küçücük bir pınar belki Yarın bir şelale çağladığında...', ARRAY['Türk Edebiyatı','Şiir','Rıfkı Kaymaz']::text[], 8.5, '{"poet":"Rıfkı Kaymaz","poet_slug":"rifki-kaymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cocuklar-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doksanlardayız 1', 'doksanlardayiz-1-mutlu-celik-c3dfr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anlayanın az olduğu andayız

Ya bir yanda yada öbür yandayız

Şerefsizin  çekinmeden çaldığı

Haysiyetten yoksun zamanlardayız

İşi bilen Üsküdar’ı geçiyor

Herkes kendi adamını seçiyor

Bin vaadle  iş başına gelenler

Gelir gelmez ağzıma sıçıyor.

El emeği el açar olmuş ele

Alınteri sahtekara amele,

Rüşvete günah diyen pezevenk

Hediyesiz yapmıyor muamele', 'Anlayanın az olduğu andayız Ya bir yanda yada öbür yandayız Şerefsizin  çekinmeden çaldığı Haysiyetten yoksun zamanlardayız İşi bilen Üsküda...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Çelik']::text[], 8.5, '{"poet":"Mutlu Çelik","poet_slug":"mutlu-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/doksanlardayiz-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doksanlardayız 2', 'doksanlardayiz-2-mutlu-celik-6kbgl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aynalarda gördük yalnız yüzümüz

Benziyor mu acep yüze özümüz

Bakmakla görseydi eğer gözümüz

Riyakar bu kadar caka satmazdı.

Dilimiz söz eder yürek habersiz

Doğrunun günü mü  oldu kedersiz

Sevenler olmasa eğer kadersiz

Yalancı bu kadar hava atmazdı.

İşbilir lafını dillere yaydık

Rüşveti iş bilir olmaya saydık

Biz eğer namuslu adam olsaydık

Pezevenk servete servet katmazdı.', 'Aynalarda gördük yalnız yüzümüz Benziyor mu acep yüze özümüz Bakmakla görseydi eğer gözümüz Riyakar bu kadar caka satmazdı. Dilimiz söz eder...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Çelik']::text[], 8.5, '{"poet":"Mutlu Çelik","poet_slug":"mutlu-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/doksanlardayiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsanedir İstanbul', 'efsanedir-i-stanbul-ozkan-sahin-b2p48', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'buram buram kokar, tarih

yedi tepeli kentim

kiliseden, camilere

kucak açan, kıyı şehrim.

Asya''yı o Avrupa''ya

bağlayan boğaz köprülerin

Karadenize uzanan

Marmara boğazın var.

nüfusundan çok fazlası

toprağında yatanlar...

coğrafyada önemli yer

toprağında insanlar var.

yeraltı,üstü metropol

kimler geldi, gidemedi

taşın, toprağın altındır

yetmişiki milletin var.

iki yarımadalı kent

antikkent,büyükşehir

efsanedir İstanbul''um

eşsiz konukseverli yer.

Dünya''da yok senin gibi

olamazda, İstanbul

iki kıtalı tek sensin

hayranım sana İstanbul.

                                          23-4-2004', 'buram buram kokar, tarih yedi tepeli kentim kiliseden, camilere kucak açan, kıyı şehrim. Asya''yı o Avrupa''ya bağlayan boğaz köprülerin Karad...', ARRAY['Türk Edebiyatı','Şiir','Özkan Şahin']::text[], 8.5, '{"poet":"Özkan Şahin","poet_slug":"ozkan-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/efsanedir-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin başağın', 'bin-basagin-tuncay-akdeniz-630ds', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgi dolu gönül bağı

Özü güzel Binbaşağın

Dostlara açık konağı

Yüzü güzel Binbaşağın

Ekin ekili tarlası

Oğuz gibi var ovası

Koyun kuzulu yaylası

Yazı güzel Binbaşağın

İlk bahar giyinir alı

Bin bir çiçek açar dalı

Desen,desen kilim halı

Haz-ı  güzel Binbaşağın

Ağustosda yağar dolu

Asfaltı yok çamur yolu

Eser durur rüzgar yeli

Tozu güzel Binbaşağın

Çağlamış akar ırmağı

İçinde sazan balığı

Çeçil peynir tere yağı

Kazı güzel Binbaşağın

Sevdaya saldım başımı

On sekiz sordum yaşını

Köyümden sevdim eşimi

Kızı güzel Binbaşağın

Köyüm olmuş gurbet yolu

Yüreğimiz hasret dolu

Ozanı var coşkun oğlu

Sazı güzel Binbaşağın

Tuncayım bitmez çilesi

Akar gözümün çeşmesi

Dili Ahıska lehçesi

Sözü güzel Binbaşağın', 'Sevgi dolu gönül bağı Özü güzel Binbaşağın Dostlara açık konağı Yüzü güzel Binbaşağın Ekin ekili tarlası Oğuz gibi var ovası Koyun kuzulu ya...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bin-basagin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doksanlardayız 3', 'doksanlardayiz-3-mutlu-celik-ejvc5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Boş yere isyana gerek yok beyler

Alkışı biz olduk yalan, riyanın

Düzene düz diye atılan reyler

Donunu indirdi güzel dünyanın

Vaadi onda bir tutabilseydik

Peşinden gitmezdik sahte rüyanın

Binde bir dürüstü bulabilseydik

İçine etmezdik güzel dünyanın.', 'Boş yere isyana gerek yok beyler Alkışı biz olduk yalan, riyanın Düzene düz diye atılan reyler Donunu indirdi güzel dünyanın Vaadi onda bir ...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Çelik']::text[], 8.5, '{"poet":"Mutlu Çelik","poet_slug":"mutlu-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/doksanlardayiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül nerde senin', 'gul-nerde-senin-tuncay-akdeniz-y3ora', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkın gemisine beni bindirdin

Rotasız  gidilmez yol nerde senin

Açık yelkenleri neden indirdin

Esmiyor rüzgarın yel nerde senin

Kendine tutmuşsun beni bakıcı

Yüzden gülüyorsun içten yıkıcı

Sevdalıyım dersin aşkın çok acı

Ömrüme katacak yıl nerde senin

Sevgi dallarının gülü dökülmez

Gönül söz dinlemez nazı çekilmez

Sevgi çağladı mı önü kesilmez

Çağlıyorum dedin sel nerde senin

Tuncay i kandırdın yüze gülerken 

Sevgi güllerini soldurdun erken

Ayrılmaz diyordun gül ile diken 

Seviyorum dedin gül nerde senin', 'Aşkın gemisine beni bindirdin Rotasız  gidilmez yol nerde senin Açık yelkenleri neden indirdin Esmiyor rüzgarın yel nerde senin Kendine tutm...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gul-nerde-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şerefe', 'serefe-efsun-aydin-zey03', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgarın sesine layık bir aşk,

Çalan şarkının kelimelere döktüğü hüzün,

Ve herşeye inat  Seviyorum'' lar...

Aşka,sevgiye onsuz olmama ihtimaline kaldırılan kadeh

Şerefe! 

Ne kadar içersen iç, 

Yaşam kadehte son buluyor.', 'Rüzgarın sesine layık bir aşk, Çalan şarkının kelimelere döktüğü hüzün, Ve herşeye inat  Seviyorum'' lar... Aşka,sevgiye onsuz olmama ihtimal...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/serefe-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale''den Lapsekili Ahmet''e Harput''tan Mehmet''e Mehmetlere', 'canakkale-den-lapsekili-ahmet-e-harput-tan-mehmet-e-mehmetlere-zekeriyya-bican-245wc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Önce bir mermi patladı sağ tarafımdan,

Fark ettim, bir anda girip çıktı sol şakağımdan...

Sardı gözlerimi bir an  kıpkızıl bir karanlık,

Yükseldi çavuşumdan, vurulduk diyen o son çığlık,

Sanırım, çavuşumla aynı mermiyle vurulmuştuk,

Zaten köyden çıkarken de, el ele tutuşmuştuk...

Yine el ele geçtik ışıklı yoldan, son menzilimize,

Birlikte kucaklaştık, özlenen o eşsiz efendimizle...

Ne de çabuk başlayıp bitmişti, o uzun seferimiz,

Geçti Sırattan yıldırım hızında, binlerce neferimiz...

Sustu bir anda top sesleri, söndü denizi yakan ateşler,

Bir anda sunuldu Rabbine, iki yüz elli üç bin nefer,

Her nefer için ayrı yapıldı, tarifi imkansız törenler,

Taşıdı sancağı önde, alemlere rehber olan peygamber...

Aradı gözlerim; babamı, anamı, bizlerle övünsünler diye,

Beklerim, her an, bu Cennet kapısında görünsünler diye...

Hâlâ ayaklarımın bir adım ötesinden Çanakkale görünüyor,

Tabyadan bir adım sonrasında, vaat edilen Cennet görünüyor...

Nasıl kesildi birden, o binlerce çığlık ve avaze sesler,

Tutuldu sanki, bu ulvi haz rüyasında, bütün nefesler...

Boğaz’da, ateş kusan gemiler, nasıl buharlaştı birden,

Nasıl çekildi aniden, binlerce Mehmet siperlerinden...

Hani az önce, denizler kabarıp üstümüze dökülüyordu,

Çocukken seyrettiğim yıldızlar, yerinden sökülüyordu...

Bu gün 18 Mart 2005, dediler doksan yıl geçmiş aradan,

Hayret, hâlâ bir  kan sızmada bizi şehit eden yaralardan...

Gördüm, bir mermer taşı oyup adımı üstüne yazmışlar,

İşte bu Lapsekili, Hasan oğlu Ahmet diye tanıtmışlar...

Biz hiç ölmedik ki, neden insanlar burada ağlıyorlar...

Biz herkesi görüyoruz, onlar galiba bizi görmüyorlar,

Bütün Anadolu çocuklarıyla beraber buradayız biz,

Gerçekten göremiyor mu, o nur damlayan  gözleriniz...

Bakın, bu Harputlu Mehmet, eşine mektup yazıyor,

Bu Lapsekili Ahmet, bıkıp usanmadan siper kazıyor...

Diyorlar ki, Mehmet’in mektubu eşine hâlâ ulaşmamış

Bakın, Koca Lapsekili de, nöbetini hâlâ bırakmamış...

İşte bu Kınalı Mehmet, gelirken anası kına yakmış başına,

Demiş ki koçumsun sen, vatanımın 18 Mart bayramına...

Anlamıyorum, peki siz neden ağlıyorsunuz hâlâ...', 'Önce bir mermi patladı sağ tarafımdan, Fark ettim, bir anda girip çıktı sol şakağımdan... Sardı gözlerimi bir an  kıpkızıl bir karanlık, Yük...', ARRAY['Türk Edebiyatı','Şiir','Zekeriyya Bican']::text[], 8.5, '{"poet":"Zekeriyya Bican","poet_slug":"zekeriyya-bican","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/canakkale-den-lapsekili-ahmet-e-harput-tan-mehmet-e-mehmetlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefret', 'nefret-sibel-maral-0mxmi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir çift söz söylemek istedim

Söylemeye çekindiklerime

Onlar ise korktular,

Sevgiden bahsederim diye

Oysa ben,

Düşlerin değil, gerçeğin elleriydim

Sıcacık gerçeğin,

Nefretle dolu yüreğiydim...', 'Bir çift söz söylemek istedim Söylemeye çekindiklerime Onlar ise korktular, Sevgiden bahsederim diye Oysa ben, Düşlerin değil, gerçeğin elle...', ARRAY['Türk Edebiyatı','Şiir','Sibel Maral']::text[], 8.5, '{"poet":"Sibel Maral","poet_slug":"sibel-maral","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nefret-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Handan', 'handan-mutlu-celik-uwb4n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zalimler zulmüne şapka çıkartır

Duysaydı istifa ederdi şeytan,

Nemrut’un utançtan yüzü kızarır

Bu senin yaptığın iş değil Handan.

Sılaya demir mi attın vefasız

Ne zarar gördün ki şu garip kuldan,

Öyle bir gittin ki sessiz sedasız

Herkesten yerini gizledin Handan.

On yıldır çırpındım iki arada

Gururum bir yandan, aşkım bir yandan,

Yerini bir bilen olsaydı burda

Gözümü kırpmadan gelirdim Handan.

Yılları gün ettim kahır içinde

Ne iyi ne kötü haber almadan,

Anılar beynimden bir bir geçince

Gözlerin takılıp kalıyor Handan.

Nerede ne yaptın, istersen sormam

Yeter ki geri dön gittiğin yoldan,

Bir günden bir güne başına kakmam

En büyük günah da işlesen Handan.

Yoksun ki küsmüşüm kara bağlarım

Hasretin bezdirdi beni bu candan,

Sanma ki yalnızca sana ağlarım

 Ayrılık demek de yetiyor, Handan

Ne hoca ne falcı ne kahin kaldı

Herkese yerini sordum bıkmadan,

Hasretin aklımı başımdan aldı

Bırak şu inadı gel artık Handan.

             --------', 'Zalimler zulmüne şapka çıkartır Duysaydı istifa ederdi şeytan, Nemrut’un utançtan yüzü kızarır Bu senin yaptığın iş değil Handan. Sılaya dem...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Çelik']::text[], 8.5, '{"poet":"Mutlu Çelik","poet_slug":"mutlu-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/handan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadehimle muhabbet-1', 'kadehimle-muhabbet-1-mutlu-celik-p9vnv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Derdimi bir sana anlatıyorum

Tek bir söz etmeden dinle kadehim,

Her gece içmeden yatamıyorum

Bari sen terk edip gitme kadehim.

Bana “hep içme şu zıkkımı” derdi

Seni hep kıskandı, kırdı kadehim,

O akşam terk edip giderken beni

“İnşallah ölürsün” dedi kadehim.

Bir günden bir güne sormadı bana

Sadece içmeme kızdı kadehim,

Giderken sebebi demedi ama

Sonradan bir mektup yazdı kadehim.

Ben ona göre bir yar değilmişim

Sırf sevgi yetmezmiş ona kadehim,

Aslında çok iyi yürekliymişim

Ama bu yetmezmiş ona kadehim.

Şerefi, namusu boş ver sen, diyor

Bunlarsız yaşayan çokmuş kadehim,

Parayla hepsini alırsın diyor 

Bende de o para yokmuş kadehim.

Seni kıskanması hep bahaneymiş

Bu sofra yetmezmiş ona kadehim,

O’nun istediği konforlu evmiş

Burada yaşamak değil kadehim

Sonunda,'' ben çoktan unuttum ''demiş

''Sen de unut beni'' diyor kadehim

Zengin bir eş bulup evlenecekmiş

''Sende git öyle yap'' diyor kadehim.

Bu mektup geleli tam bir yıl oldu

Bir daha görmedim O’nu kadehim,

Her gece içerken gözlerim doldu

Hep sende aradım o’nu kadehim.

Bir akşam postacı kapımı çaldı

Bir telgraf uzattı bana, kadehim

Yalnızca “hoşça kal” diye yazmıştı

İntihar etmeden önce kadehim.

İşte bu sırrımı bir sana açtım

Sessizce dinledin beni kadehim,

O günden bu güne her şeyden kaçtım

İzninle gideyim  artık kadehim.

                                                                             1994-Ankara

	---', 'Derdimi bir sana anlatıyorum Tek bir söz etmeden dinle kadehim, Her gece içmeden yatamıyorum Bari sen terk edip gitme kadehim. Bana “hep içm...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Çelik']::text[], 8.5, '{"poet":"Mutlu Çelik","poet_slug":"mutlu-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kadehimle-muhabbet-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımda saklı', 'canimda-sakli-mutlu-celik-un47e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Herkesin içinde birisi vardır,

Yalnızca kendine anlatacağı.

Kiminin can dostu,kiminin yardır,

Düşünüp gizlice ağlayacağı.

Küçük bir anıyı yıllarca taşır.

Derinden iç çeker,biri anınca,

Bazen de acı bir tebessüm kalır,

Bir yerde ölümden söz açılınca.

Benimde içimde birisi kaldı,

Yıllardır bir türlü atamadığım.

Geriye yalnızca bir resmi kaldı,

Koklayıp öpmeden yatamadığım.

İsmini hiç kimse öğrenmeyecek,

Çok eski bir şarkı içinde saklı,

Bilirim bir daha hiç gelmeyecek,

Cana rakibim,canımda  saklı.', 'Herkesin içinde birisi vardır, Yalnızca kendine anlatacağı. Kiminin can dostu,kiminin yardır, Düşünüp gizlice ağlayacağı. Küçük bir anıyı yı...', ARRAY['Türk Edebiyatı','Şiir','Mutlu Çelik']::text[], 8.5, '{"poet":"Mutlu Çelik","poet_slug":"mutlu-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/canimda-sakli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyoğlu''ndan Taksim''e Sen', 'beyoglu-ndan-taksim-e-sen-sitki-gokmen-7gsiz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerimin yanmasında sakladım seni.

İçime damlayan her sızı tanesinde saklısın.

Aynalara yansıyan sızılı kırmızılıklardasın.

Uykusuz gecelerde yanımdaki kadınsın.

Sen karalamalarımdaki umutlu düşlerim,

Çizgilerimdeki, fikirlerim, hayallerimsin.

Sen uykusuz gecelerimdeki yorgunluğum,

Çaresizliğim, düşsüzlüğüm, uykusuzluğumsun.

Sırtımdaki abanın kumaşı sensin.

Sen yemekten sonraki kahvem, sigaramsın.

Deniz kıyısında kaydırdığım taşım,

Damlalarımla doldurduğum denizimsin.

Sen dokunmaya korktuğum rüyalarsın.

Sen uzakta görüp yaşayamadığımsın.

Sen şiirlerimde yaşayan hayat kaynağım,

Sen hayatımı parmaklarına geçirmiş kadınımsın.

(BEYOĞLU 18 NİSAN 2005 12:00)', 'Gözlerimin yanmasında sakladım seni. İçime damlayan her sızı tanesinde saklısın. Aynalara yansıyan sızılı kırmızılıklardasın. Uykusuz gecele...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/beyoglu-ndan-taksim-e-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsaydım Temennisi+', 'olsaydim-temennisi-bayram-tunca-iacht', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Canı dudağına gelenlere su olsaydım

Kokuya hasret kalanlara yel olsaydım

Aşığı uğrunda ölene, toprak olsaydım

Toprak olanlara da, rahmet olsaydım

14.04.2005-14:04

Keşke ben de bir işe yaramış olsaydım

Aşk Ateşten Gömlek', 'Canı dudağına gelenlere su olsaydım Kokuya hasret kalanlara yel olsaydım Aşığı uğrunda ölene, toprak olsaydım Toprak olanlara da, rahmet ols...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/olsaydim-temennisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Desem olmaz', 'desem-olmaz-i-brahim-kilinc-0yghw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözleri evet der, dilleri hayır,

Çıkıp birgün bana, gel desem olmaz.

Gözü yükseklerde, gönülce mail,

Rüyalarda beni gör desem olmaz.

Dili sukut eder, gözü konuşur. 

Gözü de gerçeği, özü konuşur.

Yanaklar allaşır, nazı konuşur.

Yar diye bağrına, sar desem olmaz.

Gözlerim nemlidir, dudağım kuru,

Oturup aylarca, beklesem yolu,

Yar gelip geçerken, bu garip kulu, 

Görüpte hatrını, sor desem olmaz.

Kötü göz, kem sözler, yaralar seni,

Derde salar bu da, devasız beni,

Bu kim? diye bana, sorsalar seni,

Uzaktan sevdiğim, yar desem olmaz.

Dünyalar bahşeder, bana gülünce,

Bir tenhada biz göz göze gelince,

Bir gonca gül gibi, ince mi ince,

Gül diye baharda koklasam olmaz.

Orta boyu beyaz tene yakışır,

İnce beli ak gerdana yakışır,

Mavi gözler Kalem kaşa yakışır,

Yar diye gel beni sar desem olmaz.

İbrahim saz bilmez dinletse sana,

Söz bilmez aşkını anlatsa sana,

Birgün gizlemeyip çıkıp meydana,

Dünyaya bu aşkı haykırsam olmaz.', 'Gözleri evet der, dilleri hayır, Çıkıp birgün bana, gel desem olmaz. Gözü yükseklerde, gönülce mail, Rüyalarda beni gör desem olmaz. Dili su...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/desem-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göçebe', 'gocebe-metin-dikec-m5g0v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaralıydım, 

Ardımda rivayet sevaplarım

Önümde  günahlarım

Kurumuş ırmaklar geçtim

Çorak topraklar, 

Kaybedilmiş harçlıklara ağlama çağını tüketip

Lal rengi bir göğün altında

Yitik ruhumun izini sürerek

Ölü sevgililer anıtına diz çöken ben

Yoksa ölen ben miyim? 

Metin Dikeç', 'Yaralıydım,  Ardımda rivayet sevaplarım Önümde  günahlarım Kurumuş ırmaklar geçtim Çorak topraklar,  Kaybedilmiş harçlıklara ağlama çağını t...', ARRAY['Türk Edebiyatı','Şiir','Metin Dikeç']::text[], 8.5, '{"poet":"Metin Dikeç","poet_slug":"metin-dikec","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gocebe-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilesin oğul', 'bilesin-ogul-tuncay-akdeniz-5p57e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamana aldanıp durma boşuna

Çağın değerini bilesin oğul

Zahmetsiz çıkılmaz zirve başına

Dağın değerini bilesin oğul

Faydasız harcama hazır varını

Karanlık ettirir sana yarını

Bakarsan bağına verir ürünü

Bağın değerini bilesin oğul

Çalışana kısmet verir yaradan

Yeter ki perdeyi kaldır aradan

Ötesine bir şey götür buradan

Çoğun değerini bilesin oğul

Dostun bile gelmez darda acına

Sakın düşmeyesin kul muhtacına

Bir bak bu hayatın iki ucuna

Sağın değerini bilesin oğul 

Tuncay bu gün bitti yarını düşün

Her zaman ocakta kaynamaz aşın

Hünersiz aletsiz yürümez işin

Tığ''ın değerini bilesin oğul', 'Zamana aldanıp durma boşuna Çağın değerini bilesin oğul Zahmetsiz çıkılmaz zirve başına Dağın değerini bilesin oğul Faydasız harcama hazır v...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bilesin-ogul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Arıyorum', 'seni-ariyorum-ozan-eldeniz-5zj6z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece gibisin güzel, gizemli

Şimdi bende bu gece vakti

İstanbul’a seni anlatıyorum

Kimi zaman fısıldayarak,

Kimi zaman haykırarak…

Herkes duysun istiyorum

Seni ne kadar çok sevdiğimi

İlk aşkım İstanbul gizliden gizliye

Kıskanıyor seni…

Gemilerin sesi eşlik ediyor  şarkılarıma

Martılar ritim tutuyor çığlık çığlığa

Rüzgar sesimi taşıyor ulaşılmazlara

Kalbim deniz gibi hırçın,

Delice çarpıyor damarlarıma

Tutkuyla yaşıyorum tüm duygularımı

Bu İstanbul denilen şehir beni sarhoş ediyor

Dans ediyorum çılgınlar gibi 

Taksim’in sokaklarındaki binbir ezgilerle,

Kelimeler dökülüyor ağızımdan tutamıyorum…

Kar yağıyor şimdi

Buz tuttu ellerim

Soğuktan donmuş nefesim

Seni arıyor şimdi boş İstiklal Caddesinde

Gözlerimden dökülen damlalar donuyor yere değmeden

İsimsiz sokaklarda ayaklarım kalkmıyor yerden

Yürüyemiyorum

Kalbimi seninle öyle ısıttım ki

Ateş ateş yanıyor…

Sigaranın ateşiyle ısınan ellerim

Karanlık geceleri yoklayarak

Seni arıyor hala

Tipi bastırıyor beni de gömmek istercesine sokaklara

Fırtınayı tanımayan kalbim bocalıyor düşüyor kimi zaman

Çığlık çığlığa haykırarak ismini

Koşuyorum boş İstiklal caddesinde

Ellerimden göz yaşları kan olmuş damlıyor

Kargalar üşüşüyor üstüme

Usul usul beni geleceğe, beni geleceğe gömmek istercesine

Hepsi bir ısırık alıp

Uğultular içinde uzaklaşıyorlar etrafımdan

İşe yaramaz bedenim onlara da yaramıyor senin anlıyacağın

Şimdi adı olmayan bu sokakta; 

Tipinin üstünü örttüğü

Sigara izmaritinin ısıttığı

Beş para etmez bedenini teslim eden

Kargaların bile umursamadığı

Bu şehir beni hasta ediyor...', 'Gece gibisin güzel, gizemli Şimdi bende bu gece vakti İstanbul’a seni anlatıyorum Kimi zaman fısıldayarak, Kimi zaman haykırarak… Herkes duy...', ARRAY['Türk Edebiyatı','Şiir','Ozan Eldeniz']::text[], 8.5, '{"poet":"Ozan Eldeniz","poet_slug":"ozan-eldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/seni-ariyorum-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmelerim Benim', 'sevmelerim-benim-aysun-erat-vgwrd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dört nala sevmeliyim seni önce.

Sevişmek bir adım geride durmalı,

Uslu bir çocuk gibi.

Başka türlüdür benim sevmelerim,

Bilmelisin bunu.

Aşklarım başkadır benim.

Olur ya…

Sen beni,

Benim seni sevdiğimden çok, seversin bir gün,

Dayanamam buna.

Sevmek mi? 

Sevilmek mi? 

Daha güzel olan.

Sevmek canım, 

Sevmek benim için.

Aşklarım bitmemeli benim.

04/2005', 'Dört nala sevmeliyim seni önce. Sevişmek bir adım geride durmalı, Uslu bir çocuk gibi. Başka türlüdür benim sevmelerim, Bilmelisin bunu. Aşk...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevmelerim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğru olsun', 'dogru-olsun-tuncay-akdeniz-7e3kp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duyanlar ayıplar bizi

Sözde dilin doğru olsun

Eğrilerin şaşar izi

Özde yolun doğru olsun

Hasret çeker gurbet elde

Gözlerimiz kalır yolda

Çiçek açar dal baharda

Yazda gülün doğru olsun

Sevgi yoksa sevme boşa

Yaz baharın döner kışa

Keremi yakan ateşe 

Közde külün doğru olsun

Her işin başı okumak 

Arayıp da usta bulmak

Tuncay olamadı çırak

Sazda telin doğru olsun', 'Duyanlar ayıplar bizi Sözde dilin doğru olsun Eğrilerin şaşar izi Özde yolun doğru olsun Hasret çeker gurbet elde Gözlerimiz kalır yolda Çiç...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dogru-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer Sendense Gam da Neşe de Başımda Tac', 'eger-sendense-gam-da-nese-de-basimda-tac-mustafa-tanrikulu-wvlm3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'esmer bir titrekliktir yüzündeki perdeler...

cesaretle uzanıp,çekingen duran bakış,

incelik silahıyla incelikleri deler...

teklifsiz tahayyüçler,yüzünde bir ayrı süs

ayrılıktan dem vuran siyahi sazendeler

hayalî bir bahçenin hayali içindeler...

''canı kim cananı için sevse cananın sever...''

akıversin rûhuma susuzluk katre katre,

nedametle boğuşmak şimdi en kutsal görev...

ızdırap ikliminde milyonlar kilometre

kıvrılıp akıyorum,ne sessizlik ne de ses...

inleyen hemrahıyım şimdi ben her kılığın

matemini tutarım dönmezse nazın çarkı

cenaze gibi ben de dostuyum ayrılığın...

ayaklarımda kor var,yüreğim ise narda

neşe ve keder eğer sendense başımda tac...

aşinasıyız derdin,kardeşimizdir keder...

nihayetsiz zamana düştüğümüz bir gece

ıslanır pencereler,tüter baca,yanar ev

ince uzun bir çizgi olur üstümde hece...

çizgisiz ve noktasız,uzar gider mukaddes...

inan hep senin için,senin için hep,inan

nakşetmişler rûhuma hatsız,hudutsuz aşkı

senden özge tanımam tenim üstümde bir can

esiriyim sevdânın,bana zindan tüm dünyâ

vatansız kalmak ah...ah...ne çetin bir imtihan

sana vasıl olsaydım ak olurdu süveyda 

eğer sendense gam da neşe de başımda tac

ciğerimden içeri taze bir nefes girdi

anladım ki bu nefes senden fazla yakacak

neden sonra dağıldım,sönerken bakışlarım

altûnî endamıyla hayaletin belirdi.

nazla hayaletin de evet nazla yakacak

ıslanır gözyaşımla birgün beyaz ellerin

nasıl ki dökülüyor yere yağmur tanesi

seveni anlamamak ah ne büyük bir suç

enseleri koklarken aşığın sıcak sesi

vuslatsız ayrılıkla ellerimi bağladı

efsun-feşan gözlerin,sahib-i nâz ellerin

ram kılmışsın gönlümü bir zülfünün ucuna

    hem cefası hem vefası başımda daim tac.... 

hatıralar kuş olur; uçarlar kanatlanıp,

aktığında nefesi hayata perde perde...

tatlı bir meyve sükût,en güzel mevsim gözün

inci gibi ayağına dökülürken herşey

ceyhan parlaklığında bakışlar yine yerde

eski kitaplar gibi derin, su gibi aziz...

nedense artık beni yakmıyor kızıllığın; 

aramıyorum artık mutluluğu sularda...', 'esmer bir titrekliktir yüzündeki perdeler... cesaretle uzanıp,çekingen duran bakış, incelik silahıyla incelikleri deler... teklifsiz tahayyü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Tanrıkulu']::text[], 8.5, '{"poet":"Mustafa Tanrıkulu","poet_slug":"mustafa-tanrikulu","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/eger-sendense-gam-da-nese-de-basimda-tac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdama! -', 'sevdama-zafer-yazici-1dnry', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sanma ki unutuldun oralarda biçare, yalnızsın! 

Ellerim olmasa da yüreğim her zaman yanında, işte orada bir yerlerde, saklı! 

Veda edişin dün gibi aklımda, nasılda ağlamıştık deli gibi! gözlerimde hasretin yaşları

Daha dün gibiydi her şey, bugüne gelmeden az önceydi, taze idi, bozulmamıştı işte! 

Allah’a emanet ederken seni, “gitme” demelerin kulaklarımda hala! 

Mahşer mi vuslata erme, kavuşma zamanı? Sen biliyor musun? 

Ahiretliğimsin artık! Benim dünyada kavuşamadığımsın sen!', 'Sanma ki unutuldun oralarda biçare, yalnızsın!  Ellerim olmasa da yüreğim her zaman yanında, işte orada bir yerlerde, saklı!  Veda edişin dü...', ARRAY['Türk Edebiyatı','Şiir','Zafer Yazıcı']::text[], 8.5, '{"poet":"Zafer Yazıcı","poet_slug":"zafer-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevdama-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ol eder', 'ol-eder-tuncay-akdeniz-rxzkp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Alan odur veren odur

Cansızdan canlı ol eder

Çeşit,çeşit bitki vardır

Diken çalıyı gül eder

Karada gemi yüzdürür

Dümeni kendi döndürür

Buluttan yağmur indirir

Damla,damlayı sel eder

Yolun uzun bitmez senin

Ne yana dönmüşsün yönün

Yüksek dağlar keser önün

Düzler dağını yol eder

Tuncay hakka çevir yüzün

Bu dünyadan doymaz gözün

Hayırlıdır çoktan azın

Yakar malını kül eder', 'Alan odur veren odur Cansızdan canlı ol eder Çeşit,çeşit bitki vardır Diken çalıyı gül eder Karada gemi yüzdürür Dümeni kendi döndürür Bulut...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ol-eder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamın Adı Ayrılık', 'sevdamin-adi-ayrilik-zeynep-nilgun-gokceoz-2eaop', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim yüreğimden

Bir parça koparıyor ihanetin,

Yalanlar her soluk alışta

Saplanıyor kurşunlar gibi bedenime,

Mutsuzluğum aldanışlarda kök salıyor.

Umutlarım puslu karanlıklarda

Bir kurtuluş ışığı arıyor,

Boğuluyorum dipsiz girdaplarda...

Öfkeli nefretimi

Üzerime yapışmış gibi atamıyorum,

Ruhum ayrılığın acısıyla titriyor,

Kendimi arıyorum karanlık dünyada

Kayboluyorum avuçlarımdaki kör ışıkta.

Acının baharını yaşıyorum şimdi,

Sevda türkülerinin söylendiği her gecede

Efkar şafak vakti gibi çöküyor yüreğime...

Gözlerimin derinliğine

Hasretin sızıyor buram buram,

Bakmayın gönlümün delilendiğine

Hala kırılmış aşkımı yazıyor sevdam.

Dökülüp gidiyor hüzünlerim akşamın içinden,

Köpük köpük taşıyor gönlüm 

Dönüşü olmayan sevgimden,

Başka bir adı varmı isyanımın.

Yüreğimdeki ateşin kıvılcımıyla

Çöl yangınında hala yüreğim...

Biliyorum

Dönüşü yoktur zamanın,

Vakti yoktur ayrılığın,

Hüzünlerde saklıdır ondaki zulüm,

Alnımızdaki kaderdir,

Boyun eğmektir umutsuzca,

Tebessümün dudaklarda donması,

Yıldızların gözyaşlarına kavuşmasıdır,

Yürekten dökülen yanık bir türküdür,

Nasırlaşmış eldir,

Bitimsiz bir elemdir,

Gönüldeki sönmeyen yangındır, 

“Sevdamın Adı Ayrılıktır”...', 'Benim yüreğimden Bir parça koparıyor ihanetin, Yalanlar her soluk alışta Saplanıyor kurşunlar gibi bedenime, Mutsuzluğum aldanışlarda kök sa...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sevdamin-adi-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerimde Yaşlandı Sevgin', 'duslerimde-yaslandi-sevgin-kemal-cakir-64qy9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşlerimde yaşlandı sevgin

Asırlık çınar gibi

Ağır başlı ve yorgun 

Son mevsimini yaşıyor artık.

	

Önceleri kor yutar, alev kusardı

Bakışlarında çözülürdü buzullar.

Şimdi vefasızlığa gömülü bir kıvılcım

İliklerine kadar üşüyor, o güzelim duygular.

Sonunda isyan etti inan ki

Düşlerim bile bu umutsuz bekleyişe; 

Kapalı bir öfke saklı  her yerimde

Yol vermiyor dilim sözlerime.

Düşlerimde yaşlandı sevgin

Çaresiz ölümdür beklediği

Buluşalım bulutla yağmur gibi

Budur sevginin de bizden istediği.

		 Nisan 2001', 'Düşlerimde yaşlandı sevgin Asırlık çınar gibi Ağır başlı ve yorgun  Son mevsimini yaşıyor artık. 	 Önceleri kor yutar, alev kusardı Bakışlar...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/duslerimde-yaslandi-sevgin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıraların Ayakları Yok', 'hatiralarin-ayaklari-yok-kemal-cakir-uzcs4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bizden çok uzakta kaldı  hatıralarımız

Kimi heyecan, kimi de korkudan sapsarı

Gel diye seslensek  ulaşmaz çağrılarımız

Duysalar da gelmezler çünkü yok ayakları.', 'Bizden çok uzakta kaldı  hatıralarımız Kimi heyecan, kimi de korkudan sapsarı Gel diye seslensek  ulaşmaz çağrılarımız Duysalar da gelmezler...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hatiralarin-ayaklari-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda değilmi', 'sevda-degilmi-tuncay-akdeniz-ymyr4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akıl ermez aşk işine

Yazdıran sevda değil mi

Mecnunu Leyla peşine

Gezdiren sevda değil mi

Bülbül hasret olmuş güle

Kavuşamaz çeker çile

Göz yaşları döner sele

Süzdüren sevda değil mi

Gönlünde sevda yarası

Vuslatın uzun arası

Tutuşur canın ortası

Közdüren sevda değil mi? 

Sevenler arar yarını

Nebatlar verir barını

Arzu kanber mezarını

Kazdıran sevda değilmi? 

Ferhat gibi aşıkları

Ayrı düşmüştü yolları

Şirin için o dağları

Bezdiren sevda değil mi

Tuncay sevdalı ezelden

Anlamaz çirkin güzelden

Dal ayrı kalır gazelden

Üzdüren sevda geğil mi', 'Akıl ermez aşk işine Yazdıran sevda değil mi Mecnunu Leyla peşine Gezdiren sevda değil mi Bülbül hasret olmuş güle Kavuşamaz çeker çile Göz ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevda-degilmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklının içindeyim', 'aklinin-icindeyim-kemal-cakir-o9bii', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alkol gibisin bende

Ne zaman düşünsem dudaklarını

Kıpırdanmaya başlar duygularım

Sarhoşluğun başlar hemen içimde.

Önce ellerini, sonra saçlarını

Sonra da bakışlarını okşarım

Islanır duygularım bakışlarında

En yoğun çözünürlüğün bu sanırım.

Tahtında yalnızlığın olmayacak senin

Çünkü ben sarayının bekçisiyim

Ne zaman kalkıp yalnızlığa gitsen

Peşinden hep ben kadehle geleceğim.', 'Alkol gibisin bende Ne zaman düşünsem dudaklarını Kıpırdanmaya başlar duygularım Sarhoşluğun başlar hemen içimde. Önce ellerini, sonra saçla...', ARRAY['Türk Edebiyatı','Şiir','Kemal Çakır']::text[], 8.5, '{"poet":"Kemal Çakır","poet_slug":"kemal-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aklinin-icindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cama vuran yağmur damlalarının ardında', 'cama-vuran-yagmur-damlalarinin-ardinda-ziya-nizam-hjp1z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cama vuran yağmur damlalarının ardında

Parlayan yıldızları seyrediyorum.

İşte seni 

Bu kadar imkansız seviyorum.

			18.12.2004-Cumartesi

			22:53 Avcılar', 'Cama vuran yağmur damlalarının ardında Parlayan yıldızları seyrediyorum. İşte seni  Bu kadar imkansız seviyorum. 			18.12.2004-Cumartesi 			...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/cama-vuran-yagmur-damlalarinin-ardinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ne kadar uzak olsan da bana', 'sen-ne-kadar-uzak-olsan-da-bana-ziya-nizam-wg7en', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen ne kadar uzak olsan da bana

Bil ki hep içimdesin.

Gönlüm yanmayı bildikçe

Hep orada kal zaten.

Uzaktan sevmek

Sevmelerin en güzeli ne de olsa.

			18.12.2004-Cumartesi

			21:56 Avcılar', 'Sen ne kadar uzak olsan da bana Bil ki hep içimdesin. Gönlüm yanmayı bildikçe Hep orada kal zaten. Uzaktan sevmek Sevmelerin en güzeli ne de...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-ne-kadar-uzak-olsan-da-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllar ayırmadan önceydi', 'yillar-ayirmadan-onceydi-ziya-nizam-d6u5f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar ayırmadan önceydi

Kör karanlıklar basmamıştı daha aşkımızı.

Ne senin aklına geliyordu ayrılık

Ne de ben düşünüyordum sevgisizliği

Bilememişiz hayatın zorluğunu

Hazırlıksız yakalamış ayrılık bizi.

Şimdi haykırsam sevgimi deli gibi

Duyulur mu şehirlerce öteden? 

Ne sen benimsin artık

Ne de adı unutulmaya yüz tutmuş

Sevdalar aşkımızın ifadesi.

			14.12.2004-Salı

			15:26 Bauhaus Beylikdüzü', 'Yıllar ayırmadan önceydi Kör karanlıklar basmamıştı daha aşkımızı. Ne senin aklına geliyordu ayrılık Ne de ben düşünüyordum sevgisizliği Bil...', ARRAY['Türk Edebiyatı','Şiir','Ziya Nizam']::text[], 8.5, '{"poet":"Ziya Nizam","poet_slug":"ziya-nizam","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yillar-ayirmadan-onceydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Sevmem', 'hic-sevmem-atahan-cakir-abantli-zz9ck', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gereksiz ağlayanları hiç sevmem:

Sevmeden sevdiğini sanan

Dolmadan boşalmaya soyunan

Görmeden anlatmaya başlayan

Gitmeden dönüşe hazırlanan

İçmeden sarhoş olan

Açmadan kapanan...

Şeyleri sevmediğim gibi.

Bugün kış da gereksiz ağlıyor

Tam da kış ortasında.

Beyaz zengini olduğunu bilip 

Cömertliğini göstermek; 	

Ya da

Sertliğini, soğukkanlılığını hatırlayıp

Tir- tir titretmek varken

Bu ağlamak niye? 

Aslına bakarsanız, sadece sevmediğim

Buz gibi bir görüntüsü yanında

Bembeyaz duyguların da sahibi olan,

Ancak bunu zaman zaman  farkedemeyen

Kış değil ki! 

Güneşi yanına alıp 

Tabiatı uykusundan uyandıran; 

Doğurgan ya da değil

Çoğu ağaçla ilişkiye girip

bir kısmını hamile bırakan,

Sonra da yavrusunu

Ana rahminde acımasızca öldüren

Yalancı bahara ne demeli! 

Onu sevdiğimi mi söyledim? .

Gereksiz ağlayanları hiç sevmem.

Ama yalancıları, hiç mi hiç sevmem.', 'Gereksiz ağlayanları hiç sevmem: Sevmeden sevdiğini sanan Dolmadan boşalmaya soyunan Görmeden anlatmaya başlayan Gitmeden dönüşe hazırlanan ...', ARRAY['Türk Edebiyatı','Şiir','Atahan Çakır Abantlı']::text[], 8.5, '{"poet":"Atahan Çakır Abantlı","poet_slug":"atahan-cakir-abantli","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hic-sevmem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhteşem Kadın', 'muhtesem-kadin-vedat-gungorur-ip6p8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hamurunda mayanın hası var Özleştirmiş güzelliği

Suyunda volkanların sıcaklığı..Ateşlemiş kanını

Ve seni o zarif.. o yumuşak..o dokunulmazlığa

Biçimlemiş..özenti ve sevgi..duygusal hayaller

Duruyorsun öylece sana bakamıyorum

Korkuyorum,eritirim, kaybederim diye..gözlerimden

Üflenemeyecek kadar narinsin dayanamıyorum

Yaklaşsın istiyorum bir an olsun gözlerin..gözlerime

Arzularıma gem vurmaktayım.. seni.. bu kadar isterken

Çekmişim dizginleri sonuna kadar... ama... nafile

Titriyorum korkudan..kaçacak ellerimden arzu ve ihtiras

Acı çekiyorum karşında.. söyle... ne yapayım... muhteşem kadın

vedat GÜNGÖRÜR  ([email protected])', 'Hamurunda mayanın hası var Özleştirmiş güzelliği Suyunda volkanların sıcaklığı..Ateşlemiş kanını Ve seni o zarif.. o yumuşak..o dokunulmazlı...', ARRAY['Türk Edebiyatı','Şiir','Vedat Güngörür']::text[], 8.5, '{"poet":"Vedat Güngörür","poet_slug":"vedat-gungorur","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/muhtesem-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmek', 'gitmek-ozgur-kokturk-v5zo6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Terk edilmiş bir akşam üzeriyim şimdi 

Gözlerim ağlayan mutsuz çocuk 

Bitkin yüreğim 

Umuda sarılmış yasaklanmış düşlerim 

Bahar gelmiş 

Gelmesin! 

Kırık bir kuş kanadında 

Yarım kalmış sevdayım 

Sessizliği haykırır nefesim 

Kahrolası nefesini özledim 

Gülerdin 

Gülerdi elimde açılan gül 

Susardın 

Beklerdi sesini şarkım 

Giderdin 

Kalırdı çaresiz yollar 

Düşsem diyorum karanlıkta, gecede 

Üstüm başım çamur 

Ellerim kir pas içinde 

Yağmur yağıyormuş yağsın 

Daha 

Daha çok yağsın 

Yağmur ne yazar okyanusa 

Sensizlik ummanında kalmışım 

Gecedir yüreğin her atışı 

Hicran olur vuslatın hasreti 

Yaşamaktır ölmek gözlerinde 

İklimdir bu 

Hüzündür 

Sırdır... 

Kokuşmuş bir kuş cesedi kalır şimdi elimde 

Gözbebekleri oyulmuş... 

Yokluk kalır düşüme yoldaş 

Çok çok bir umutsuzluk 

Sessiz bir ıslık yalar bedenimi 

Altı üstü nedir ki 

Bir ömür 

Bir ölüm... 

Çekili perdesi, tülü sevmenin 

Çenesi bağlanmış yaşama sevincinin 

Korsan bir kitap kadar ahlâksız şimdi 

Çiçeğe durmuş körpe tomurcuk 

Bileklerinden bağlı intihar ranzasına... 

Yalan dediğimiz kaç kelime 

Neler açar başına 

Nelere mal olur 

Hınç ondan çıkar 

Sefalet ondan 

Rezalet ondan 

Sevmenin adı yalan şimdi 

Şimdi sevgili çıngıraklı yılan... 

Sığ limanda çürümeye durmuş bir vapur 

Kaptanı gitmiş 

Yolcusu yitmiş 

Umut kalır enkazlar altında 

Yıkık, harabe, perişan 

Günde sevda alev alev 

Gecede ihanet kokar 

Ne virane yürek para eder 

Ne sevilere susayan can 

Kan düşer günce yaprağına 

Sokaklarda siren sesi 

Alnımın içinde senin sesin 

Ellerim yanar 

Duman avuçlarımda 

Bakışında binlerce ciltlik ihanet 

Bakışımda milyonlarca isyan... 

Unutulmuş bir köşede ıslak bir mendil 

İzmarit dolu bir tabla 

Duman altı odalarda 

Tükenmiş bir adam... 

Adam şiir yazar karalar 

Şiir yazar yırtar 

Adam yazdıkça ağlar 

Ağladıkça yazar... 

Aşkın gözyaşları değil bunlar 

Nefretin zirvesinde bir sevgi 

Sevda sınırında öfke 

Dahiliğin uçlarında bir deli 

Delirecek bir dahi gibi 

Sonlara yaklaşır adım adım 

Son geldikçe uzaklaşır... 

Pus, ter, kan 

Paslanmış kalbin damarları 

Soluk soluğa 

Çığlık çığlığa geceler 

Çobanyıldızı da küskün 

Saçma sapan papatya falları da... 

Neyimi aldı benden seni sevmek 

Kangren yüreğine ne kazandırdı sevişim 

Ve ne verdi bana 

Tek avuntum hayalimdeki gülümseyişin 

Gidişin umuduma saplanan hançer 

Boş verdim artık sana da umutlara da... 

Duyurmadan suskunluğu kimseye 

İnat etmeden sevmeye 

Çekip gitmek sensizliğin ortasına 

Çizgilere dokunmadan 

Senin gidişin gibi bensizliğe... 

Gitmek şimdi körpe tomurcuğun bileklerinde! ! !', 'Terk edilmiş bir akşam üzeriyim şimdi  Gözlerim ağlayan mutsuz çocuk  Bitkin yüreğim  Umuda sarılmış yasaklanmış düşlerim  Bahar gelmiş  Gel...', ARRAY['Türk Edebiyatı','Şiir','Özgür Köktürk']::text[], 8.5, '{"poet":"Özgür Köktürk","poet_slug":"ozgur-kokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":100,"source_url":"https://www.antoloji.com/gitmek-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuturum Sanma--', 'unuturum-sanma-dursun-elmas-9tytt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Unuturum sanma; 

.................Islak bir öpücüğün yakan tadını

Unuturum sanma; 

................Öyle sımsıcacık sarıldığım kadını.

Unuturum sanma; 

................Tellerine takıldığım saçlarını

Unuturum sanma; 

................Ciğerimi söken o içten bakışlarını.

Unuturum sanma; 

................Gözlerimde sallanan sevgiliyi

Unuturum sanma; 

................Dokunulası o ipek tenliyi.

Unuturum sanma; 

................Aşka yelken açan o yosun gözlerini

Unuturum sanma; 

................''Ben de seviyorum''diyen o şirin sözlerini.

Ne tadını...

Ne adını.

Ne altın sarısı saçlarını...

Ne de yosun bakışlarını.

Unutamam...Unutamam....Unutmam! ..', 'Unuturum sanma;  .................Islak bir öpücüğün yakan tadını Unuturum sanma;  ................Öyle sımsıcacık sarıldığım kadını. Unutur...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/unuturum-sanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Derelim', 'gul-derelim-atahan-cakir-abantli-o83yt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel benimle güzelim

Gül bahçende gezelim

Tutuşalım el ele

Güllerini derelim 

  	

Bir bu gülden bir şundan

Kırmızıdan sarıdan

Pembesinden morundan

Kucak kucak derelim.

Güllerden de güzelsin

İnan bana güzelim 

Sen bin güle bedelsin

Gül endamlı sevgilim.', 'Gel benimle güzelim Gül bahçende gezelim Tutuşalım el ele Güllerini derelim    	 Bir bu gülden bir şundan Kırmızıdan sarıdan Pembesinden mor...', ARRAY['Türk Edebiyatı','Şiir','Atahan Çakır Abantlı']::text[], 8.5, '{"poet":"Atahan Çakır Abantlı","poet_slug":"atahan-cakir-abantli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gul-derelim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanarsın', 'yanarsin-huseyin-sigirtmac-sq410', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğe düşerse aşkın ateşi.

Görmez olur gözün yanan güneşi.

Yad eller sardıysa gönlüne eşi.

Göz yaşı içine akar yanarsın.

Ellerin uzanıp boşta kaldıysa.

Ayrılık elinden yari aldıysa.

Yıllar saçlarına aklar çaldıysa.

Zamana kafayı takar yanarsın.

Engel ile bağlandıysa yolların.

Bomboş kaldı ise yalnız kolların.

Meyve vermediyse yeşil dalların.

Yaprağına bakar bakar yanarsın.

Neşe ve kedere yoksa ortağın.

Ateş düşer yanar, kor olur bağrın.

Sığırtmaç el olur, yerin, otağın.

Gül diye dikene sarkar yanarsın.', 'Yüreğe düşerse aşkın ateşi. Görmez olur gözün yanan güneşi. Yad eller sardıysa gönlüne eşi. Göz yaşı içine akar yanarsın. Ellerin uzanıp boş...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanarsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Düşünmemiştim', 'hic-dusunmemistim-atahan-cakir-abantli-g529y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiç düşünmemiştim veda edeceğini

Bir gün ansızın çekip gideceğini

Ne de kolay söyledin bu kelimeyi

Güle güle demekten öte ne kaldı ki! 

Hayatta hep kaybettim aşk kumarını

Henüz bulamadım kazanmanın yolunu

Bir defa rest çektim olmadı

Anladılar hemen blöf yaptığımı.

Başedemedim bir türlü bu kumarla

Bir usta bulmam gerekir herhalde! 

Bir gün kendimi de koyarsam ortaya

Kalmayacak artık hiçbir şey bende.

		

Hiç düşünmemiştim veda edeceğini

Bir gün ansızın çekip gideceğini

Ne de kolay söyledin bu kelimeyi

Güle güle demekten öte ne kaldı ki! 

Hayatta hep kaybettim aşk kumarını

Henüz bulamadım kazanmanın yolunu

Bir defa rest çektim olmadı

Anladılar hemen blöf yaptığımı.

Başedemedim bir türlü bu kumarla

Bir usta bulmam gerekir herhalde! 

Bir gün kendimi de koyarsam ortaya

Kalmayacak artık hiçbir şey bende.', 'Hiç düşünmemiştim veda edeceğini Bir gün ansızın çekip gideceğini Ne de kolay söyledin bu kelimeyi Güle güle demekten öte ne kaldı ki!  Haya...', ARRAY['Türk Edebiyatı','Şiir','Atahan Çakır Abantlı']::text[], 8.5, '{"poet":"Atahan Çakır Abantlı","poet_slug":"atahan-cakir-abantli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hic-dusunmemistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arz-ı Hâl', 'arz-i-h-l-cel-lettin-cevik-amcvw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tehditkâr bakışların tetikler

Çılgın kâlp atışlarımı

O yüzden, yanaklarım al pembe

O yüzden, dilim damağım kurumuş

Akla ziyândır vaatlerin

''Zor, oyun bozar

Gece, kir aklar''

Gözlerin, yeşiller maviler denizi

Gözlerin, gecenin süsü, arzular bahçesi

Ay sana doğar, yıldızlar seni fısıldaşır

Yakamozlar yakışır tenine

''Geçitler daralır, uçurumlar büyür

Gözlerinin gel dediği yer gönlümdür''

Birazdan, ufukları bulutlar basar

Birazdan, hüzün eşkıyaları yol keser

Hangi bent durdurur, bu taşkınları

Aklım, sabır kamçılar habire

Yol, yolcuyla güzel

''Hangi saatin son “çın” sesidir

Başladı- bitti, sevda bir masal''', 'Tehditkâr bakışların tetikler Çılgın kâlp atışlarımı O yüzden, yanaklarım al pembe O yüzden, dilim damağım kurumuş Akla ziyândır vaatlerin ''...', ARRAY['Türk Edebiyatı','Şiir','Celâlettin Çevik']::text[], 8.5, '{"poet":"Celâlettin Çevik","poet_slug":"cel-lettin-cevik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/arz-i-hal-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bensizliğim Ölümün Olacak', 'bensizligim-olumun-olacak-atahan-cakir-abantli-r2jrb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bundan böyle yaşayacağın 

Hep sessizlik olacak.

Ne yağmurlar, ne çiçekler, 

Ne şiirler, ne de sen! 

Duymayacaksınız sesimi bir daha.

Yalnızlığın sancısı

Boğazında düğümlenip duracak; 

Gözlerin yanacak,

Öfkelenip oğuşturdukça

Kan göreceksin herşeyi.

Savrulup dağılacaksın

Gül kurusu akşamlarda,

Tıpkı kuru yapraklar misali. 

Yaşadığını anlayamıyacaksın,

Her gören seni ölü sanacak.

Çünkü ben olmayacağım artık,

Bundan böyle 

Hiçbir zaman yanında.', 'Bundan böyle yaşayacağın  Hep sessizlik olacak. Ne yağmurlar, ne çiçekler,  Ne şiirler, ne de sen!  Duymayacaksınız sesimi bir daha. Yalnızl...', ARRAY['Türk Edebiyatı','Şiir','Atahan Çakır Abantlı']::text[], 8.5, '{"poet":"Atahan Çakır Abantlı","poet_slug":"atahan-cakir-abantli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bensizligim-olumun-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adımız Türk', 'adimiz-turk-ahmet-atmaca-0peqn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Buna mecbur değiliz hakikat bir tarih var

Eğilmek te ne demek dünya zatenTürk''e dar,

Davamızdan ne düştü ne eksildi maziden

Utanmazmı bu millet şehitten ve gaziden,

Onlar ki başkoltukta ilerleyen bir ordu

Allah için söyleyin önünde kimler durdu? 

Kızıl elma, turan bir ülkümüz var şükür

Bu tunç bilekler, kim demiş ki bükülür,

Damarda akan kanın rengini çiz  ta baştan

Zamanı geri çevir,selam alsın Kürşat'' tan

Bitene denk durmasın  küfür ve küfür ehli

Kiliseler, havralar olana denk mimberli,

Ezan sesi vurmalı kıtalardan kıtaya

Uyan ey Türk evladı yer yok artık hataya,', 'Buna mecbur değiliz hakikat bir tarih var Eğilmek te ne demek dünya zatenTürk''e dar, Davamızdan ne düştü ne eksildi maziden Utanmazmı bu mil...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Atmaca']::text[], 8.5, '{"poet":"Ahmet Atmaca","poet_slug":"ahmet-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/adimiz-turk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu şıklık O'' nun Eseri', 'bu-siklik-o-nun-eseri-efsun-aydin-4mep0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şöyle sana yakışır bir elveda,

İçten gelen bir sunumla yaptığın o veda

Anısı bile acıtır durur o geride bıraktığın yarımı.

Şimdi anlat dur uğrumda kaybettiğin kelimelerle:

Aşkı, tutkuyu,tutunuşu

O sevdiğin renkte ki kadınlara…

Sahi ne renkteydiler ki? 

Ama artık inanmazlar sana,

Ben de ki inandırıcılığın yoktur  şimdilerde senin.

Ben aldım senden o mıh duyguları…

Şimdi onlara vereceğin tek duygu benimkiler olabilir,

Hani çalıp gittiğin o günlere ait hikayemde ki…', 'Şöyle sana yakışır bir elveda, İçten gelen bir sunumla yaptığın o veda Anısı bile acıtır durur o geride bıraktığın yarımı. Şimdi anlat dur u...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-siklik-o-nun-eseri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak Hayaller', 'tutsak-hayaller-mehmet-salih-seyhan-h5904', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilir misin Botan’da yükselen Cudi dağını

Bilir misin sır dolu bir meçhul olduğunu

Hangi Botanlı’nın gönlünde yok ki

Cudi’nin lekesiz aklığı,öfkesi ve sırdaşlığı

Bilmezler o kör ve yedi başlı canavarlar

Uçaklar,tanklar yetmez ki Cudi’yi fethetmeye.

Bilmezler kızıl kayaları kar ile değil

Kan ile sulanmış yamaçlarında

Bilmezler bin yılın öfkesi var eteklerinde

Sel olup aktığında kar ile akan kanlar

İşte o zaman tanımaz hiçbir engeli

Yakılır,yıkılır kirli zehirli gönüller

Zafer bizimdir der! ...

Büyük küçük,kadın erkek hep birden

Karlar akıp götürürken akan kanları

Bozkır yerine gül dolu çimenler yeşerir bir anda

Botan’da yükselen Cudi’nin eteklerinde.

Kor ateş gibi yanan Cudi’nin başında

Söndürülmüş volkan gibi atmosferin ötesinde

Parçalanmış şarapnel misali çorak geniş ovalara

Mezopotamya toprağında parçalanan gövdeler

Ve binlerce kefensiz vücut

Yeter be vicdansız milliyetçiler

Ne istersiniz körpecik beyinlerden

Bırakın cahil ediklerinizin cehaleti cebinde kalsın

Gafletin sancısını siz çekin.

Gözünüzü kırpmadan sıktığınız mermiler

Bir gün gelirde geri teperse

Çelik beyinlerinize ve kalplerinize isabet ederse

Adına özgürlük dediğiniz

Tutsaklığı yaşarsınız rezilce.

Artık yetsin diyorum

İntihar çarklarının döndüğü bu dağlarda

Lambasız ışıksız zifiri karanlıklarda

Bitsin artık bu ölümler

Sevinsin gülmeyi unutmuş yürekler.

Sevinsin gözlerdeki özlemli düşler

Maviyi oynayan çocuklar üşümesin

Üşümesin analarin gözlerinden dökülen yaşlar

Yani yetsin artık diyorum

Fırat aksın

Mezopotamya ağlamasın

Yanmasın bıyıkları yeni terlemiş gençler

Kirletilmesin kızlar kadar temiz düşler.

Özgürlük adıyla yaşatılan rezillikler bitsin

Bitsin kafalardaki köhne düşünceler

Sevdalar işleyelim genç kizlarin yazmalarina

Özgür koyalım çocuklarımızın adına

Yani kavgaları

Yani tutsaklığı diyorum

Yıldızların ardına saklayalım

Ve hasretini çektiğimiz o mavi dünyamızda

Buluşalim helallaşalim.', 'Bilir misin Botan’da yükselen Cudi dağını Bilir misin sır dolu bir meçhul olduğunu Hangi Botanlı’nın gönlünde yok ki Cudi’nin lekesiz aklığı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Salih Seyhan']::text[], 8.5, '{"poet":"Mehmet Salih Seyhan","poet_slug":"mehmet-salih-seyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/tutsak-hayaller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seve Seve Büyüyor İnsan', 'seve-seve-buyuyor-i-nsan-golge-gezgini-34fm7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Merhaba demeyi özledim

ben çocukken merhaba demeyi öğrendim

daha küçüktüm pırıl pırıldı gözlerim

misket tutan ellerim nasır tutmamıştı daha

gazoz kapaklarına aşıktım ozaman

merhabayı bakkal amcadan öğrendim

her gazoz bir merhaba

her sakız merhaba

hergün ekmek sakız gazoz merhabaydı

okula başlamışım zamanı anlamadan

hergün her harf için merhaba

harf harf yazmayıda öğrendim

yazı yazmayı bu yüzden sevdim

hergün bir öğretmen

bir merhaba oldu hayatımda

orta okul lise ise

sayıları toplayıp çıkarmakla

elma kafama düşmeden yer çekimi

hesaplamakla derken

yılları anlamadım

ama hergün bir merhaba için bir bahaneydi

mühendis olacaktım

uçaklar gemiler

gökdelenler yapacaktım

daha kalabalık bir hayat daha çok merhabam olacaktı

belkide daha fazla param daha çok merhaba alacaktı

oda oldu mühendis olmuştum

okuması zordu ama merhabası boldu

statikler mukavemetler mesnetler derken

merhaba bahanem olmuştu artık

yarı çapkın kızlar için

saya saya bitti okul 1 merhaba 1 aşk

her elveda yeni bir merhaba

ozaman anladım

seve seve büyüyor insan

bana sevmeyi öğrettin

meğer nekadar yalanmış

negatif sayılara benzer bahane merhabalar

mutlak değersizdi o merhabaların hepsi

parantezin içinden

ne artı çıkıyordu nede sevda

seve seve büyüttüğünü gördüm beni

sevgin sevdan arttıkça

saçlar beyazlar unutkanlılklar başlar oldu

şimdi merhabalarım yok

ne bakkal amca ne öğretmen

nede bahane merhabalar

şimdi sen varsın ama sende yanımda yoksun

bir nevi etkisiz eleman

merhabalara hasret kalmaya inanmazdım

büyümediğime inanmadığım gibi

şimdi sen orda ben burda

merhabam kalmadı belki ama

şiirlerim var kalemim kağıdım ve hislerim

matematik bunun için var

kalemi kağıdı hisleri toplayıp şiir çıkarıyorsun

sevgi yalanla aşk ise ihanetle kalansız bölünüyor

iyiki bizim aşkımız asal bölünemez aşk

çünkü senle beni çarpıp aşkı buluyoruz

nekadar çok işlem var aşkım

bizim merhabasızlığımızı bulacak

ama bu yazım sana merhabam olsun

seve seve büyür konuşa konuşa biter insan

artık yazmak kalmadı

yaza yaza erir insan

Merhaba hayatımın yutan elemanı.', 'Merhaba demeyi özledim ben çocukken merhaba demeyi öğrendim daha küçüktüm pırıl pırıldı gözlerim misket tutan ellerim nasır tutmamıştı daha ...', ARRAY['Türk Edebiyatı','Şiir','Gölge Gezgini']::text[], 8.5, '{"poet":"Gölge Gezgini","poet_slug":"golge-gezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/seve-seve-buyuyor-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döndü Yine Zaman', 'dondu-yine-zaman-mehmet-salih-seyhan-5if3h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kandemir dağlar paslandı zamanla 

Nehirlerle akıyor durmadan zaman

Bir bahar gününde tomurcuk dalında yeşeren yaprak

Yağmurlara karşı narin neşeli

Gökyüzüyle sukut içinde...

Tan doğmakta karanlık elveda demekte 

Sürüler yollardan yeşilliklere sürülmekte

Dağlar kamburlaştı geçen ömürle 

Şarkılar yağmur oldu yeşeren çiçeklerde

Bir bahar bitti yine apansız

Karlara esir oldu zaman

Donlu günlerde dondu zaman 

Çadırlar nefes kokuyor ah

Nefesler ter ve sevgi

Çocuklar ağlamakta bir gece boyu

Zemheride titreyen bir sessizlikte

Yırtılıyor bir anda göğün kulak zarı

Ağlamayı bıraktı çocuk

Sütünü emerek yıldızları saymakta

Fırat’ı düşünmekte düşlemekte

Düne kadar kan ısmarlayan Fırat’ı

Anadolu’nun bağrında kan emerken görmekte

Çocuk büyüdü Anadolu bağrında akan zamanla 

Sevgiyle kendini sormakta çocukluk aşkına

Anımsıyor geçmişi bağrı yanarak

Canını cananını kaybettiğine ağlayarak

Yeminlere gelmişti kuruyacaktı artık Fırat

Feryadı çınladı gökyüzüne

‘Sevgi dolu kanları emmek düşmez sana ey Fırat’

Gömüldü Fırat çocuğun gözyaşlarına

Bir ömür boyu yatağında vicdan azabı duyarak.', 'Kandemir dağlar paslandı zamanla  Nehirlerle akıyor durmadan zaman Bir bahar gününde tomurcuk dalında yeşeren yaprak Yağmurlara karşı narin ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Salih Seyhan']::text[], 8.5, '{"poet":"Mehmet Salih Seyhan","poet_slug":"mehmet-salih-seyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/dondu-yine-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunum', 'yorgunum-golge-gezgini-i853n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ayrılık yıllarının çizgisinde yürümekten

son hasret diye sevgimi yüklenmekten

kavuşmak arzularını her öğün yemekten

yorgunum

ufuktaki hayalini görüpte tutamamaktan

her günü bir şiirle geçmekten

adını yazmak için kalem açmaktan

özleyip fotoğrafını okşamaktan

yorgunum

kavuşmak rüyalarında uyumaktan

masama fazladan bir tabak koymaktan

aynada kendimle seni konuşmaktan

sensizken senliymişim gibi yapmaktan

yorgunum

nefesinin olmadığı havayı solumaktan

uyumak için kendime sarılmaktan

ellerin yerine kalem tutmaktan

dudaklarımdaki sigarayı öpmekten

yorgunum

sensiz uyuduğum geceler uyanmaktan

acımı azaltsın diye içmekten

içki masasında yediğim mezelerden

her hatırladığımda seni gülümsemekten

yorgunum

ulu orta hıçkıra hıçkıra ağlamaktan

yorgunum,

görüşürüz dediğimiz andan şimdiye kadar

o son bakıştan ve öpüşten

gözlerimin ve dudaklarımın kuruduğu şimdiye kadar

yorgunum,

ama yılmadım

bıkmadan usanmadan seni sevmekten

ve o müthiş kavuşmayı hayal etmekten.', 'ayrılık yıllarının çizgisinde yürümekten son hasret diye sevgimi yüklenmekten kavuşmak arzularını her öğün yemekten yorgunum ufuktaki hayali...', ARRAY['Türk Edebiyatı','Şiir','Gölge Gezgini']::text[], 8.5, '{"poet":"Gölge Gezgini","poet_slug":"golge-gezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yorgunum-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Özgürüm I', 'artik-ozgurum-i-mehmet-salih-seyhan-cr7k1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu birkaç hırçın kelime

Kaçamakların ardından

O kapkara dünyayı görmezden gelip

Gözlerini bembeyaz bir dünyaya kapamak

Aramak özgürlüğü tüm gizemiyle

Kahrolsun yok işte

Yine karabasan yine aynı son

Hep aynı nihayet

Ama hiç bitmedi ve bitmeyecek gibi

Yastığımı sana dayadım be dünya

Bunca insafsızlığın ardından,

Hep sen mi yükleyeceksin bel büken taşınmaz yükleri

Bu yorgunluğun ardından.

Ne umut ne hayal

Hiçbirini vermedin ki 

Bu can neden yıkık hala

Söylesene.....

Gidişler dönüşsüz

Ama yine gidiş.

Yan artık

Ama hangisine

Kendine mi sanamı mı

Yoksa tüm dünyaya mı? ...

Bitsin diye yalvarırken yeni başlangıçlar

Hep biten ama yine başlayan

Bu sakin ama fırtınalı sessizlik nereye kadar.', 'Bu birkaç hırçın kelime Kaçamakların ardından O kapkara dünyayı görmezden gelip Gözlerini bembeyaz bir dünyaya kapamak Aramak özgürlüğü tüm ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Salih Seyhan']::text[], 8.5, '{"poet":"Mehmet Salih Seyhan","poet_slug":"mehmet-salih-seyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/artik-ozgurum-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derdim Yazılmaz', 'derdim-yazilmaz-golge-gezgini-h0eco', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birtaneme; 

Sensiz geçen saniyeler dursun diye saatlere rüşvet verdim olmadı..! 

İçimdeki sızıyı bastırmak için sana aşağıdaki bir kaç dizeyi yazdım, sanırım oda olmadı.....

hanlar hamamlar mekanım olsa

ormanlar dağlar bahçem

benim rahatım olmaz

altınım malım mülküm olsa

parayla sikkeyle dolu kasam

benim ziynetim olmaz

ağaçlardan uzun ömrüm olsa

her an her daim sıhhatim

benim hayatım olmaz

kuşun kanadı kalem olsa

gökyüzü bulutlar kağıt

bir bir mutluluğum yazılsada

benim derdim yazılmaz', 'Birtaneme;  Sensiz geçen saniyeler dursun diye saatlere rüşvet verdim olmadı..!  İçimdeki sızıyı bastırmak için sana aşağıdaki bir kaç dizey...', ARRAY['Türk Edebiyatı','Şiir','Gölge Gezgini']::text[], 8.5, '{"poet":"Gölge Gezgini","poet_slug":"golge-gezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/derdim-yazilmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski şarkılar', 'eski-sarkilar-golge-gezgini-4dcrn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bıkınlık geldi bu eski şarkılardan,

Hani kordon boyunda,

Nazlı bir güzelden senden.

Yılların ötesine kalacak bir sevdadan,

Bana bahar ve aşk kokuları taşıyan ezgilerinden.

Seni sadece seni anlatmalı şarkılar.

En canlı,hareketli ritmiyle notaların.

Acımı,kavgamı ve kendimi bulmalıyım,

Namludan kurşun misali fırlayan nağmelerle.

Söküp atmalı duvağını başından,

Kendine zorla yükletilmiş gelinliği.

Görün! siz o zaman görün,

Seninle evlendiğimi.

Bir Musikide buluşup evet dermisin sevdama? ...', 'Bıkınlık geldi bu eski şarkılardan, Hani kordon boyunda, Nazlı bir güzelden senden. Yılların ötesine kalacak bir sevdadan, Bana bahar ve aşk...', ARRAY['Türk Edebiyatı','Şiir','Gölge Gezgini']::text[], 8.5, '{"poet":"Gölge Gezgini","poet_slug":"golge-gezgini","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/eski-sarkilar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerimdeki Hayal Şehir', 'hayallerimdeki-hayal-sehir-abacan-askisev-senkal-5bcwy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstanbul'' dayım uzun yıllardan sonra; 

Kulaklarımda hüzünlü bir rast şarkı,

Bugünü yaşayarak geçmişe dalarken

Eski Ramazan''ların o huzurlu iftar tadı,

Boğazda görünür mağrur Topkapı Sarayı...

Ufukta sıcacık güneşin son kızıllığı,

Rüzgarın nefesi savurur saçlarımı,

Denizin kokusunu çekerken içime,

Hayal şehir İstanbul uyanır içimde,

Sereserpe uzanır gözlerimin önünde...

Sultan Ahmet akşama merhaba derken,

Ayasofya'' nın karşısındaki yeşil bahçeden,

Uzarken gölgeler lacivert sulara doğru,

Dalgaların köpüğü ardında kaybolurken,

Süzülür Kadıköy vapuru, karşımda Anadolu...

Mazide bir Ağustos, yine böyle bir gün,

Veda ettiğimde bıraktığım gibi üzgün! 

Biraz şarktan sarı, biraz garptan mavi...

Sevgilimi çalan şehir İstanbul! ..

Aşklarımı içinde yaşatan şehir...

Derin sularda bir kıpırdanma olur,

Beşikte bebek misali sallanır vapur,

Bir müzik sesi duyulur uzaklardan,

Yankılanan martıların sesine karışır,

İnsan selleri akar durur sokaklardan...

Rüyalarımın ötesinde aşklara layık,

Masalların büyüsünde izlere tanık,

Gözlerimin önünde koca İstanbul,

Gözlerimin önünde bütün tarihin şanı,

Hayallerimdeki, hayal şehirlerin sultanı...', 'İstanbul'' dayım uzun yıllardan sonra;  Kulaklarımda hüzünlü bir rast şarkı, Bugünü yaşayarak geçmişe dalarken Eski Ramazan''ların o huzurlu i...', ARRAY['Türk Edebiyatı','Şiir','Abacan Aşkısev Şenkal']::text[], 8.5, '{"poet":"Abacan Aşkısev Şenkal","poet_slug":"abacan-askisev-senkal","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hayallerimdeki-hayal-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarap', 'sarap-mehmet-dag-jqveu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sendeledi direkleri bedenimin 

Eğildi diz çöktü

Bir şişe şarabın önünde

Esnedi,titredi kendine gelemedi

Bir camii imamı gibi duruyordu

Şarap şişesi meyhanede

Ama o bir ibadet saygısı gösteremeden

Kaydı oturduğu sandalyeden

Ayağı dolandı şişeye 

Birlikte yuvarlandılar masadan

Hiç biri bahsetmedi O gece

İsa dan Muhammet ten Musa dan

Şarap bedenine sırılsıklam

Bedense şaraba teslim

Bütün inançlardan uzak

İkisi bir birine tutsak

Sorun isterseniz adını 

Nedir mutlu yaşamak

Birisi şarap der diğeri sarhoş olmak

(Avcılar)', 'Sendeledi direkleri bedenimin  Eğildi diz çöktü Bir şişe şarabın önünde Esnedi,titredi kendine gelemedi Bir camii imamı gibi duruyordu Şarap...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Dağ']::text[], 8.5, '{"poet":"Mehmet Dağ","poet_slug":"mehmet-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sarap-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimlesin', 'benimlesin-alaeddin-i-kican-2n7oi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sev deme bana,seni sevemem,

Aşkını yüreğimde gizleyemem,

Nefret etsen de benden sana gelemem,

Çünkü sen,her şeyinle benimlesin.

Işıl ışıl bakan gözlerini ağlatamam,

İnci tanesi sözlerini ben kesemem,

Seni dermansız dertlere gönderemem,

Çünkü sen,her şeyinle benimlesin.

Hak’kın sana biçtiği bu ömrü,

Boşa harcadın, unutamam gösterdiğin zulmü,

Yıldızlarla yaşamak istediğin ölümü,

Göremezsin,çünkü sen benimlesin.

Sen  hak ver,Allah’ın bu garip kuluna,

Verdiğin umutları,aydınlık yarınları unutma,

Elveda sevgiye,elveda aşka,

Diyemezsin,çünkü sen benimlesin.

  Bu şiir şairin kendisine ait ''SEVGİDEN ÖTESİ YOK''adlı şiir kitabından alınmıştır.', 'Sev deme bana,seni sevemem, Aşkını yüreğimde gizleyemem, Nefret etsen de benden sana gelemem, Çünkü sen,her şeyinle benimlesin. Işıl ışıl ba...', ARRAY['Türk Edebiyatı','Şiir','Alaeddin İkican']::text[], 8.5, '{"poet":"Alaeddin İkican","poet_slug":"alaeddin-i-kican","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/benimlesin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beddua', 'beddua-sinan-ercan-3k6uh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Baştan aşağı yalansın

Etinle kemiğinle yılansın

Zehir olsun güzelliğin

Yara olsun bedenin

Toprak merhemin olsun

Sürün dilinde çatallı bir keşkeyle

Alçaklar dostun olsun

Aşağılar olsun seviyen

Tükensin onurun

Haysiyet hasretin olsun

Bükülsün benliğin

Kıvrıl içindeki kirli kibirinle', 'Baştan aşağı yalansın Etinle kemiğinle yılansın Zehir olsun güzelliğin Yara olsun bedenin Toprak merhemin olsun Sürün dilinde çatallı bir ke...', ARRAY['Türk Edebiyatı','Şiir','Sinan Ercan']::text[], 8.5, '{"poet":"Sinan Ercan","poet_slug":"sinan-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beddua-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk ile seyretmek...', 'ask-ile-seyretmek-i-brahim-ethem-bingul-39gnx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Doğadaki sesler ve bütün renkler

Şarkılarda dile gelir dilekler

Bahar kapı olur yeni hayata

Boşa gitmez bu kapıda emekler...

Aşk varsa boy verir, bedeni sarar

Bakışlar davettir, perde aralar

Kalp sevdayı bulur, erer rahata

İnsanın gönlünde olursa bahar...

Kara toprak yeşil gelinlik giyer

Ağaçlar süslenir, yürür serviler

Sanatkâr bir tablo sunar sanata

Âşığa, aşk ile seyretmek düşer...

www.iebingul.com', 'Doğadaki sesler ve bütün renkler Şarkılarda dile gelir dilekler Bahar kapı olur yeni hayata Boşa gitmez bu kapıda emekler... Aşk varsa boy v...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-ile-seyretmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demokrasi: Silah mı, Gül mü?', 'demokrasi-silah-mi-gul-mu-hikmet-feridun-demir-8y0kq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Pazarda her şey satılmalı.

Silah da, Çicek de, Gül de,

Yasaklanarak değil, 

seçenek kalbden olmalı.

Kalbden yansımalı,

Alabildiğince kendiliğinden,

Korkuya yer olmadan…

Özgürce, kendince his etmeli…

Alabildiğine yaşayabilmek…

Alabildiğine yaşatabilmek insanca…

Silahın da olsa, 

Düşman görmeden, 

Gül sunabilmek herkese.

Seçeneklerinden biri Silah, biri Gül ise! 

Kalpden, Gönülden Gülü seçebilmek,

Gül ikram edebilmek herkese...

Sevgiden köprü kurmak...

Kalbden kalbe giden...

Zora düştüğünde, o köprülerden geçebilmek...

Kalbin attığı müddetçe, 

Gül ikram edebilmek...

Gül ikramından nasibini alabilmek...

Silaha davranmaktan daha mı Zor! ! ! 

Gelecek Nesillere Gül bırakmak…

18.04.2005

Köln/Almanya', 'Pazarda her şey satılmalı. Silah da, Çicek de, Gül de, Yasaklanarak değil,  seçenek kalbden olmalı. Kalbden yansımalı, Alabildiğince kendili...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/demokrasi-silah-mi-gul-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Yüreğin Sonu', 'kucuk-yuregin-sonu-alaeddin-i-kican-7ja1r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-1-

Küçücük yüreği,ölümü tanımıyordu,

Hissetmiyordu soğuk tenini,

Hastaydı,ateşliydi,titriyordu,

Plastik bir yaprak gibi,

Eriyordu gıdım,gıdım.

Amma velakin mutluydu,

Gülücükler,tebessümler saçıyordu izleyenlerine,

Ona masum masum bakan,

Acıma duygusu hissettiren gözlere,

Sahte göstermelik sevgilere inat.,

Mutlu bir tebessüm,

Mahzun bir bakış,

Sadece bir umut düşlüyordu,

Geleceği için; 

Ak saçlı dedesinden,

Öpücüğe boğan ablasından,

Onunla ölüp dirilen babasından,

Canım diye saran anasından,

Yaradanı olan Tanrısından,

Beklediği sadece bir umut,

Bu düşlerle gülüyordu,

Sarıyordu,sarılıyordu,

Zaman zaman acıya dayanamayıp ağlıyordu.

		-2-

Nerden bilirdi ki böyle pür neşe yaşarken,

Doktorun annesiyle gizli gizli konuşurken,

Açık kapı aralığından ecelini duyabileceğini,

İçine attığı hayat arkadaşı ölümle,

Kucak kucağa yaşayacağını,

Nerden bilebilirdi ki? 

Günahı neydi yavrucağın,

Çernobil onun suçu muydu? 

Hormonlu sebzeler meyveler,

Radyasyon saçan aletler,

Onun günahı mıydı? 

Yokluktan hastane kapısına gelemiyen,

Acı haberi duyarım endişesi ile eriyen,

Babasını görmeden hayata veda etmek,

Onun hakkı mıydı? 

Küçücük bedeni savrulurken sağa sola,

Aniden çakı gibi dona kalacağını,

Son nefesinde sevdiklerinden ayrı,

Kimsenin elini tutmadan,

Tıp tıp atan yüreğinin,

Ritminin sona ereceğini bilebilir miydi? 

			-3-

Eğer tüm bunları bilseydi,

Dünyaya gelmek ister miydi? 

Arkadaşlarının coşkulu oyunlarını izlerken,

Bu acılara gücü yetmeyen babasının,

Yüreği kanlı labirent misali beyninin,

Duracağını,cinnetlere karacağını,

Karmaşık duygularla pencerede isyan ederken,

Boşluğun uçsuz bucaksız kollarına bırakıp,

Beton caddeyle öpüşeceğini bileblir miydi? 

Bir yanda eriyen yavrusunu,

Öte yanda kendini sonsuzluğa bırakan,

En dayanıklı bildiği aile direğini,

Gözler önüne getiren acılı anne yüreği,

Dayanır mıydı bu gaflete,

Bir avuç beyaz leblebide buldu kendini,

Hayalini,ümitlerini,geleceğini,

Yok etmişti,oda kolayı seçmişti,

Mücadele yerine,teslimiyeti tercih etti,

Bunlardan sonra nefes alıp veren,

O minicik can,

O yavru yürek,

Dayandı tüm bu acılara,

				-4-

Bir gün annesinin mezarını ziyarete gittiğinde,

Can dostu ecel,

Kucaklamıştı onu,

Ben seni sarmadan,

Sen geldin kollarıma dedi,

Annesinin mezarı başına yığıldı,

Yavru beden,cansız yatıyordu,

Ama mutluydu,Gülüyordu,

Varlığım diyebildiği,

Annesinin kucağındaydı,

Ömür boyu onu çağıran,

Eceline kavuşmuştu,

Miras olarak bıraktığı,,

Acı,keder ve hüzün,

Baki dostumuz kaldı,

Siz mutlu olun,

Kanser denen illetin,

Varolmasında katkısı olanlar,

Yavru beden yerine siz gülün,

Tebessüm edin,sevinin,

Neden mi? Siz kazandınız.', '-1- Küçücük yüreği,ölümü tanımıyordu, Hissetmiyordu soğuk tenini, Hastaydı,ateşliydi,titriyordu, Plastik bir yaprak gibi, Eriyordu gıdım,gıd...', ARRAY['Türk Edebiyatı','Şiir','Alaeddin İkican']::text[], 8.5, '{"poet":"Alaeddin İkican","poet_slug":"alaeddin-i-kican","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/kucuk-yuregin-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çarkında/Rüyamın', 'carkinda-ruyamin-cenk-aksal-jgls7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'okyanus kadar derin,

yüreğimdeki yerin

çin seddi kadar uzun,

içimde bıraktığın izlerin...

ben sevdim,sen sevdin,

beraberken benimle,

ada vapuruyla yarışan:

yunuslar kadar şendin! 

yeni doğmuş bebek gibi,

gülerdi melül gözlerin...

ne oldu böyle birden..

buz dağları girdi aramıza..

ekvatorda kaldın sen,

ben ise antartikada eskimo..

kutup ayıları gülüyor halime,

penguenler göbek atıyor..

sırılsıklam olmuş bedenim,

şafakta uyanıyorum...

çılgın bir rüyaymış gördüklerim,

derin bir nefes alıpta..

halime şükrediyorum....

    ''ada vapuru yandan çarklı''', 'okyanus kadar derin, yüreğimdeki yerin çin seddi kadar uzun, içimde bıraktığın izlerin... ben sevdim,sen sevdin, beraberken benimle, ada vap...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/carkinda-ruyamin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey İstanbul Irak Dostların Yakın Gönlü', 'ey-i-stanbul-irak-dostlarin-yakin-gonlu-hasan-ejderha-sjluk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sihirli lamba yanar üstünde başımın

Kaşının ortasında İstanbul’u görürüm

Boğazda martıların kanat çırpışı gibi

Hürüm elini çekse rüyamdan  sevgili

Saçlarında takılı kırmızı bir gül

Çok aşkların yalnız şehri İstanbul.

Bir martı uçar gönlümde sen gibi

Hasret yanar surlarında ben gibi

Üsküdar’da kendimi buldum

Sırlı zatların uğrağı bir atar dükkanında

Ümraniye’de aşkı 

Seni hissetmek ki tam yaşamaktı

Selahattin solumak isterim ömrümün her günü

Ey İstanbul ırak dostların yakın gönlü.

Bir şehir kokar burnuma sen gibi

Uzar ayağına yollar ben gibi

Hangi türküyü söylesem sanadır yolum

Okuduğum bir şiirde geçse adın

Hasret tüter de yüreğimde

Böğrümden kurşun yemiş gibi olurum

Hangi türküyü söylesem sanadır yolum

İstanbul, çok gün görmüş genç oğlum.

Bir mısra düşer içime sen gibi

Kelimeler buğulanır ben gibi

Rüyamdan çıkmayan kırmızı bir gül

Çok aşkların yalnız şehri İstanbul

Ey İstanbul ırak dostların yakın gönlü

Hangi türküyü söylesem sanadır yolum

İstanbul, çok gün görmüş genç oğlum', 'Bir sihirli lamba yanar üstünde başımın Kaşının ortasında İstanbul’u görürüm Boğazda martıların kanat çırpışı gibi Hürüm elini çekse rüyamda...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ey-istanbul-irak-dostlarin-yakin-gonlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamadı Bunu Yüreğin', 'anlamadi-bunu-yuregin-alaeddin-i-kican-ldjqf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk bakışındı içimi saran,

            Yüreğimdeki katran bakışı aydınlatan,

            Sevgimi,gönlümü,benliğimi esir alan,

            İlk bakışındı senin,anlamadı bunu yüreğin.

           Özgür kokan yüreğinde,beni bağlayan,

           İlk beni sevdiğini içtenlikle haykıran,

          Delirmiş duygularımda yaşatan,

          Çılgın duygularındı senin,anlamadı bunu yüreğin

         İlk sıcaklığındı sende duyduğum,

        Öperken sevgiye boğulduğum,

        Gül güzeli sana doyamadığım,

        Solmayan tenindi senin,anlamadı bunu yüreğin.

        Geçmişte sunduğum sevdalarda,

        Mecnun’a özendiğim masallarda,

        Ellerini tutarak durulan sevgilerde,

        Gönülden yaralıyım,anlamadı bunu yüreğin.

						

        Bu şiir şairin kendisine ait ''SEVGİDEN ÖTESİ YOK'' isimli şiir kitabından alınmıştır.', 'İlk bakışındı içimi saran,             Yüreğimdeki katran bakışı aydınlatan,             Sevgimi,gönlümü,benliğimi esir alan,             İl...', ARRAY['Türk Edebiyatı','Şiir','Alaeddin İkican']::text[], 8.5, '{"poet":"Alaeddin İkican","poet_slug":"alaeddin-i-kican","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anlamadi-bunu-yuregin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davet', 'davet-i-brahim-tamer-i2d1f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mert olmaya çalış,namertce değil

Yalancı olma gel,dürüstlüğünle sevil

İnsanları aldatmak,insanlık değil

Kazdığın kuyuya düşersin bir gün

İnsanız biz,bizi bir yaratan var

Bilmiyorsan dostum bir bilene sor

Aç gözünü artık hakikatı gür

Tükenir nefesimiz ölürüz bir gün

Bu dünya fani,sonsuz değildir

Uzun sanma ömrün, kısa bir andır

Hoşgörü,sabır,insanlık iyi olandır

Ne yaptıysan onunla anılırsın bir gün

Uzak dur kötülükten,kırıcı olma

Helal''e doğru koş,harama varma

Suçu yoksa dur,fakire vurma

İyiliğin karşılığını alırsın bir gün

Düşman kazanma,dostun çok olsun

Adın kalplerde hep iyi anılsın

Esirgeme yardımını,hoşgörün olsun

Sende yardıma muhtaç, kalırsın bir gün', 'Mert olmaya çalış,namertce değil Yalancı olma gel,dürüstlüğünle sevil İnsanları aldatmak,insanlık değil Kazdığın kuyuya düşersin bir gün İns...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tamer']::text[], 8.5, '{"poet":"İbrahim Tamer","poet_slug":"i-brahim-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/davet-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-dilek-temel-729d3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Koptu hayat bağları küstü gönlüm herşeye,

Umut yüklü ağaçlar döktü yapraklarını...

Ne çiçekler açacak nede bahar gelecek

Kıştan selam getirdi sonbahar rüzgarları.

Sevmiyorum bu hüzünlü  yalnız akşamları

Sürüklüyor anılar beni eski günlere......

Herşey daha dün gibi nasıl geçiyor zaman? 

Bir yol bulamam diyorum dönsem eski günlere.

Belkide bilemedim kıymetinizi

Haftalar aylar derken geçtiniz yıllar.

Engüzel günlerimi alıp gittiniz

Hakkınız kalmadı ödeştik yıllar....', 'Koptu hayat bağları küstü gönlüm herşeye, Umut yüklü ağaçlar döktü yapraklarını... Ne çiçekler açacak nede bahar gelecek Kıştan selam getird...', ARRAY['Türk Edebiyatı','Şiir','Dilek Temel']::text[], 8.5, '{"poet":"Dilek Temel","poet_slug":"dilek-temel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/veda-147-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dargın', 'dargin-dilek-temel-04b6f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kin kapımda nöbetçi

Gurur kollarımı bağlıyor.

Gece derin uykuda

Duvarlar konuşmuyor.

Bekliyorum boşyere

İçimde bir sıkıntı

Zamana dur diyemem

Akrep yelkovanla yarışa çıktı.

Çarpıyor kalbim saatle eş

Karanlığı yumruklar gibi.

Ağlaya ağlaya sabah oluyor

Korkulu bir düşten uyanır gibi.', 'Kin kapımda nöbetçi Gurur kollarımı bağlıyor. Gece derin uykuda Duvarlar konuşmuyor. Bekliyorum boşyere İçimde bir sıkıntı Zamana dur diyeme...', ARRAY['Türk Edebiyatı','Şiir','Dilek Temel']::text[], 8.5, '{"poet":"Dilek Temel","poet_slug":"dilek-temel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dargin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melek Annem', 'melek-annem-i-brahim-tamer-b1z7m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sımsıcaktın,öpüp basarken bağrına

Sevgi aşılayarak uğurladın beni yarına

Söz ver şimdi bana,hadi ALLAH aşkına

Ayrıldıktan sonra arkamdan ağlama anne

Seni unutabilirmiyim,benim canımsın

Yanında huzur bulduğum tek insansın

Yeterki ALLAH''ım uzun  ömür versin

Bırak şimdi gideyim,hosça kal annem

Dayanamassın bana biliyorum,sakın ağlama

Gidiyorum ama yine gelirim,yüreğimi dağlama

Sil gözyaşlarını gülümse,sarıl boynuma

ALLAH''a amanet ol,hosça kal annem

Mektup yazarsan eğer, dertli olmasın

Bak,gurbetelde hasretin beni yakmasın

Öyle yazki annem,satırlar özlem kokmasın

Ayrılığa ağıt yakma ağlama,hosça kal ANNEMMM', 'Sımsıcaktın,öpüp basarken bağrına Sevgi aşılayarak uğurladın beni yarına Söz ver şimdi bana,hadi ALLAH aşkına Ayrıldıktan sonra arkamdan ağl...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tamer']::text[], 8.5, '{"poet":"İbrahim Tamer","poet_slug":"i-brahim-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/melek-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azıyor İstanbul', 'aziyor-i-stanbul-canan-celik-nwgvr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Masmavi bir deniz önümde, 

Eski balıkçı motorları, vapur kıyıda.

Telâşlı değil martılar, insanlar kadar.

İskeledeyim Kadıköy'' de.

Nane şekeri satıyor bir çocuk,

Usul-usul kalkıyor vapur,

Canlanıyor dalgalar, hatta azıyor gitgide

Anlatıyor İstanbul'' u.', 'Masmavi bir deniz önümde,  Eski balıkçı motorları, vapur kıyıda. Telâşlı değil martılar, insanlar kadar. İskeledeyim Kadıköy'' de. Nane şeker...', ARRAY['Türk Edebiyatı','Şiir','Canan Çelik']::text[], 8.5, '{"poet":"Canan Çelik","poet_slug":"canan-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aziyor-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalimmiş Meğer', 'zalimmis-meger-i-brahim-tamer-36l4h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayatımı ben ona vermiştim

Kimseyi değil onu sevmiştim

Onunla ağlayıp onunla gülmüştüm

Öldürdü beni o, çıkıp giderken

Gözümde yaşlar sel olup aktı

Yıktı umudumu hosça kal derken

Alev alev yaktı,ateşe attı

Öldürdü beni o, çıkıp giderken

Ağladım arkasından beni duymadı

Neden ağlıyorsun diye sormadı

Diz çöküp yalvardım ama kalmadı

Öldürdü beni o, çıkıp giderken

Yok dostum gülemem artık

İstesemde kendime gelemem artık.', 'Hayatımı ben ona vermiştim Kimseyi değil onu sevmiştim Onunla ağlayıp onunla gülmüştüm Öldürdü beni o, çıkıp giderken Gözümde yaşlar sel olu...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tamer']::text[], 8.5, '{"poet":"İbrahim Tamer","poet_slug":"i-brahim-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zalimmis-meger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Gibiyim', 'olu-gibiyim-i-brahim-tamer-ho7w4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaprağı dökülmüş kuru ağaca döndüm

Suyum yok,sitilim yok,nede dalım var

Gülsüz kalmış ötmeyen bülbüle döndüm

Sevgim yok,sedam yok,nede sesim var

Gittin gideli hastayım,cansız gibiyim

Kuvet yok,derman yok,nede nefes var

Çölde susuz kalmış kuru çalı gibiyim

Rüzgarım yok,güneşim yok,nede gölgem var

Aşkından rüzgara karşı yelken açmışım

Önüm yok,sonum yok,nede yönüm var

Umutsuz aşkına canım, kucak açmışım

Dünüm olmadı, yok bugün,nede yarın var

Gemilerin terkedip gittiği limanım şimdi

Botum yok,sandalım yok,nede salım var

Herşeyini yitirmiş zavallı, fakirim şimdi

Sen yoksun,aşkın yok,nede bir yalım var', 'Yaprağı dökülmüş kuru ağaca döndüm Suyum yok,sitilim yok,nede dalım var Gülsüz kalmış ötmeyen bülbüle döndüm Sevgim yok,sedam yok,nede sesim...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tamer']::text[], 8.5, '{"poet":"İbrahim Tamer","poet_slug":"i-brahim-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olu-gibiyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben de İnsanım', 'ben-de-i-nsanim-sibel-oner-nxz1b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BENDE İNSANIM			

				

Ben de bir insanım				

Benim de duygularım var				

Herşeye rağmen				

Yaşama sevincim var				

İmkansıza karşı				

Çarelerim var				

Dertlerime karşı				

Tesellim var				

Oynamayın artık benimle				

İncitmeyin duygularımı				

Nazari itibari alın beni				

Hör görmeyin bari				

Beni sevmenizi de istemiyorum				

İmzalamayın fermanımı				

Açmayın karanlık çukurumu				

Bastırmayın hislerimi				

Anlayın gerçekleri				

Sizden tek isteğim olacak				

Şu üç günlük fani dünyada 				

Anlayışlı olalım hep birlikte				

Kırmayalım birbirimizi				

Unutmayalım fedekarlıklarımızı				

Çok şeymi istedim soruyorum size				

Kanıtlayamıyorum kimseyi kendim,				

Rahata bir türlü kavuşamıyorum				

Anlıyorum,anlaşılamıyorum				

Seviyorum,sevilemiyorum				

Unutuyorum,unutulamıyorum				

Ağlıyorum,akıtamıyorum				

Gülüyorum,inandıramıyorum				

				

				

			Sibel ÖNER', 'BENDE İNSANIM			 				 Ben de bir insanım				 Benim de duygularım var				 Herşeye rağmen				 Yaşama sevincim var				 İmkansıza karşı				 Çare...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ben-de-insanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamıyor; anlaşılamıyorum', 'anlamiyor-anlasilamiyorum-sibel-oner-vl9rm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ANLAMIYOR; ANLAŞILAMIYORUM				

				

Bugün günlerden pazardı				

İçimde bir hüzün vardı				

Ağlamak istiyorum durmadan				

Doyasıya hıçkıra hıçkıra				

Ağlarsam hesap vermek zorundayım				

Gülersem nedenini anlatmalıyım				

Kalp kırarsam kızdırmamalıyım				

Niye hep hesap vermek zorundayım				

Beni hiç mi hiç anlamıyorlar				

Halin nedir diye sormuyorlar				

Kendi başlarına konuşuyorlar				

Boş laf boş sözler sarfediyorlar				

Anlamıyorlarki sorsunlar				

Bilmiyorlar ki konuşsunlar				

Sevmemişler ki sevsinler				

İnsan değiller ki yaşasınlar				

Soruyorum kendime bu kızgınlığımı				

Arıyorum nedenlerini sorunlarımın				

Bulamıyorum çaresini				

Sancılanıyorum yaşadığım saatleri				

Eğer bir anne olursam ben				

Yakın olmalıyım ki konuşmalı benimle				

Ortak olmalıyım sorunlarına				

Çare aramalıyım dertlerine				

Sevmeliyim sevsin diye				

				

				

			Sibel ÖNER', 'ANLAMIYOR; ANLAŞILAMIYORUM				 				 Bugün günlerden pazardı				 İçimde bir hüzün vardı				 Ağlamak istiyorum durmadan				 Doyasıya hıçkıra h...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/anlamiyor-anlasilamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimde Herkes Gibi Düşlerim Var...', 'benimde-herkes-gibi-duslerim-var-sibel-oner-nroic', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BENİM DE HERKES GİBİ DÜŞERİM VAR					

					

Anlatamıyorum kimseyi kendimi,					

İspatlayamıyorum fikirlerimi					

Benimsetemiyorum benliğimi					

Anlamıyorlar beni					

Nedenini kendimde bilmiyor					

Soruyorum,söylemiyorlar					

Anlatıyorum,anlamıyorlar					

Ağlıyorum,avutmuyorlar					

Sevmiyorlar beni					

Böyle acımasız düşünenler var oldukça					

Ben için için eridikçe					

Düşünüp çaresiz kıvrandıkça					

Üstüme geliyor hepsi birer birer					

Erkekseniz tek tek gelin					

Gelin ki:sorunları detaylı inceleyelim					

Elbette bir karara varalım					

Herkes haddini bilsin					

Bilsin ki; bir daha asla haksızlık					

Adaletsizlik,merhametsizlik					

Gaddar ve vicdansız davranmasın					

Bilsin ki karşısında bir canlı var					

Benim de herkes gibi düşlerim var					

İncitmesinler söz konusu olmayan gururumu					

Dokunmasınlar yaralı kalbimi					

Maletmesinler kuru iftiraya					

					

				Sibel ÖNER', 'BENİM DE HERKES GİBİ DÜŞERİM VAR					 					 Anlatamıyorum kimseyi kendimi,					 İspatlayamıyorum fikirlerimi					 Benimsetemiyorum benliğimi...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/benimde-herkes-gibi-duslerim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bızdığım Benim', 'bizdigim-benim-sibel-oner-dd3qg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BIZDIĞIM BENİM				

					

Miniciktir benim bızdığım					

Daha 15 günlük bir ürün					

Küçücük kuyruğu					

Minicik bir burnu					

Kocaman bıyıkları					

Kepçe kulaklı					

Boyu desen 20 cm bir şey					

370 hr geliyor terazide					

Tüyleri var yumuşacık					

Gözleri fıldır fıldır					

Simsiyah döner yuvasında					

Meraklıdır bakışları					

Arar,dinler					

Kulaklarını dikerek					

Okşandımı uzanıverir,olur 30 cm					

Kulaklarnı yatırır,bir uysal kedi gibi					

Hiç kıpırdamaz sık sık solur					

Bekler,sonu gelmesini istemediği okşamaların					

Zıpladımı özgürce,tutmak imkansız					

Karnı doymak bilmez					

Takip eder,sürekli yılmadan					

Neredeysem oda mutlaka orada					

Benim canım bızdığım					

					

					

			Sibel ÖNER', 'BIZDIĞIM BENİM				 					 Miniciktir benim bızdığım					 Daha 15 günlük bir ürün					 Küçücük kuyruğu					 Minicik bir burnu					 Kocaman bıy...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bizdigim-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Oğlu', 'i-nsan-oglu-i-brahim-tamer-g3d7k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kardeş olmuş taşla toprak

İç içedir dalla yaprak

Sarmaş dolaş otla çapak

Yanlız kalan insan oğlu

Öter bülbül sesi güzel

Açar güller koku güzel

Yağar yağmur yaşı güzel

Kötü olan insan oğlu

Kökler salmış gül toprağa

Hayat vermiş su yaprağa

Aç gözünü bak doğaya

Kıskanç olan insan oğlu

Kin tutmazlar, yazlar kışa

Ötme demez, kartal kuşa

Göz muhtaç kirpikle kaşa

Kin tutanlar insan oğlu', 'Kardeş olmuş taşla toprak İç içedir dalla yaprak Sarmaş dolaş otla çapak Yanlız kalan insan oğlu Öter bülbül sesi güzel Açar güller koku güz...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tamer']::text[], 8.5, '{"poet":"İbrahim Tamer","poet_slug":"i-brahim-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/insan-oglu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoktan', 'coktan-sibel-oner-xc1gh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ÇOKTAN			

				

Seviyorum demek o kadar kolay olsaydı				

Çoktan derdim				

Sevildiğimi bilmek çok basit olsaydı				

Çoktan anlardım				

Nefes almak o kadar komik olsaydı				

Çoktan gülerdim				

Ölümü hissetmek son demim olsaydı				

Çoktan seçerdim				

Yediğim lokma kadar yakın olsaydı				

Çoktan hiç yutmazdım				

Bulutlar üstümde çiğ tanesi olsaydı				

Çoktan yağardım				

Damarlarımda akan bir kan olsaydı				

Çoktan dondururdum				

Hayalimde canlandırdığım bir büst olsaydı				

Çoktan müzeden çalardım				

Özlediğim sevginin kaynağı olsaydı				

Çoktan severdim				

Beklentilerimle bağdaşmayı bilseydi				

Çoktan kabullenirdim				

Hastalandığımda mutluluk ilacım olsaydı				

Çoktan felçli olurdum				

Bir ışık gibi içime girseydi				

Çoktan karanlıktım				

Bir mucize olup kalbime çalsaydı				

Çoktan verirdim				

Umduğum gibi çıkmaz yanıltsaydı				

Çoktan biterdim				

				

			Sibel ÖNER', 'ÇOKTAN			 				 Seviyorum demek o kadar kolay olsaydı				 Çoktan derdim				 Sevildiğimi bilmek çok basit olsaydı				 Çoktan anlardım				 Nefe...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/coktan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale Destanı', 'canakkale-destani-yusuf-dursun-cmy35', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben Yozgatlı Murat...Bir minik kuzu...

Girince böğrüne bir ince sızı

Anam, al kınayı yaktı başıma

Şahadet suyunu döktü başıma

Bir beyaz buluta bindirdi beni

Çanakkale için indirdi beni

Geride bin parça yürek bıraktım

Anamın sözünü göğsüme taktım:

“Vatan kurtulmadan ölünmez oğul

Sen ölürsen vatan bölünmez oğul! ”

Ağrı’dan, Bitlis’ten, Van’dan gelenim

Akın akın dört bir yandan gelenim

Adıyaman, Urfa, Samsun neresi

Çanakkale dersen, aha şurası

Gelmemek olmazdı benim bildiğim

Düğün davetiydi koşup geldiğim

Efeler zeybekte, dadaş bardadır

Çayda çıra, horon, halay burdadır

Sağdıca bayrakla kanımı verdim

Damada armağan canımı verdim

Seyit Onbaşı’yım sırtım demirden

Üç yüzlük mermiyi alırım yerden

“Ya Allah! ” diyerek şaha kalkarım

Topların sevinci kalmasın yarım

Mermiyle beraber ben de giderim

Vatana borcumu böyle öderim

Zemzemle yıkanır bu koca deniz

Gülistana döner Çanakkale’miz

Adımıza destan dizsin ozanlar

Unutmasın bizi tarih yazanlar

Anzak askeriyim olmaz olaydım

Boğazlar önüne gelmez olaydım

Çıplak gözle görülmeyen ordular

Kale gibi karşımızda durdular

Kellesi koltukta vuruşan vardı

Eyvah! Çanakkale dünya kadardı

Cengaverin adı Gazanfer olmuş

Mehmetçik ezelden muzaffer olmuş

Cihanda bir yiğit gördüm yine de 

Mutlu bir ölüyüm Çanakkale’de

Mustafa Kemal’im altın yeleli

Zulme baş eğmedim arşa geleli

Çanakkale savaş değil mahşerdi

Şehitlerin vuruştuğu bir yerdi

“Bedr’in aslanları” yalın kılıçtı

Barbaros denizde delikler açtı

Ulubatlı Hasan ok atıyordu

Rabb’im bize zafer yaratıyordu    

Dedem Korkut geldi soy soylamaya

Ebedî yurdumda boy boylamaya:

“Ergenekon denen bir ulu yerden

Geldim ki ordumuz gelir seferden

Malazgirt’te Alparslan’ı görendim

Söğüt’te postumu yere serendim

Yıldırım’da ümidimi bulmuştum

Fatih’le çağları süsledi muştum

Çanakkale tâcı oldu tarihin

Birlik olun, dirlik olun, sevinin

Elde kopuz başlayalım türküye

Haşre kadar hür yaşasın Türkiye! ”', 'Ben Yozgatlı Murat...Bir minik kuzu... Girince böğrüne bir ince sızı Anam, al kınayı yaktı başıma Şahadet suyunu döktü başıma Bir beyaz bulu...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Dursun']::text[], 8.5, '{"poet":"Yusuf Dursun","poet_slug":"yusuf-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/canakkale-destani-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Bir Sevda', 'yeni-bir-sevda-sibel-oner-jgu93', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'YENİ BİR SEVDA			

				

Bir ömür geçti ahlarla vahlarla				

Yinede bu ömrü seveceğim				

Nice sevdalar yaşadı kalbim				

Yinede yeni bir sevdayı seveceğim				

				

Aynaya baktığımda kırık dökük benliğim				

Yatağıma uzandığımda tatlı düşlerim				

Yalnız kaldığımda kurduğum hayallerim				

Ben yinede yeni bir sevdayı seveceğim				

				

Geriye döndüğümde izleri geçmişimin				

Düşündüğümde iz bırakan acılarımın				

Tutunduğumda kopan dallarımın				

Evet yinede yeni bir sevdayı seveceğim				

				

Akıl almaz duygularımın ardından				

İmkansız dediğim şeylerin peşinden				

Yıpranırken tamirat yaptığım aletlerin				

Ben yinede yeni bir sevdayı seveceğim				

				

Yaşamadığım hayatın içinden				

Sevilemediğim yarin birinden				

Sevmeyi bir türlü öğrenemediğim hayattan				

Ben yinede yeni bir sevdayı deneyeceğim				

				

				

				Sibel ÖNER', 'YENİ BİR SEVDA			 				 Bir ömür geçti ahlarla vahlarla				 Yinede bu ömrü seveceğim				 Nice sevdalar yaşadı kalbim				 Yinede yeni bir sevd...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yeni-bir-sevda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama', 'ama-sibel-oner-hwg3j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'AMA			

					

Sevdanın dili olsaydı  da konuşsaydı					

Yaşasaydım yüreklerde					

Ama sevdan olmadı					

					

Kapıyı çalmadan girseydi de kalbime					

Çalsaydı benliğimi					

Ama gelen olmadı					

					

Şarkı olup dolansaydım da dillerde					

Çınlasaydım kulaklarda					

Ama şarkı değil oldum gazel					

					

Aşk şiirleri olsaydım da mısralarda					

Okurlarken aksaydı yaşlarında					

Ama bir türlü yazılamadım					

					

Piyona olsaydım müzisyenin elinde					

Coştursaydı,sevenleri					

Ama akort olamadım					

					

Çocukların kitabında hikaye olsaydım					

Anlatsalardı mutlu sonumu					

Ama mutlu olamadım					

					

Uzakta yanan kandil ışığını bana verseydi					

Vererek hayra girerdi					

Ama ışığı göremedim					

					

Binlerce yıldız benim kalbime girmeyi çalışsaydı					

Giren her yıldız benim olurdu					

Ama hiçbirini yakalayamadım					

					

Adını bilmediğim uzaktaki sen yanımda olsaydın					

İnanki birbirimizin olurduk					

Ama olmadı					

					

Sen ve sensizliğin hücresinde olsaydık					

Kelepçeli zincirlerim olurdu					

Ama olmadı					

					

Ölümün soğuk nefesini ensemde duysaydım					

Giderdim bir daha dönmemek üzere					

Ama bak ölüm bile olmadı					

					

				Sibel ÖNER', 'AMA			 					 Sevdanın dili olsaydı  da konuşsaydı					 Yaşasaydım yüreklerde					 Ama sevdan olmadı					 					 Kapıyı çalmadan girseydi de k...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ama-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Coğrafyası', 'gonul-cografyasi-yusuf-dursun-bp3z2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her muradın verildiği bir anda

Şeyh Şamil’in düşlerini dilesem

Kartal gagasıyla süslü zamanda

Kafkasların kılıcını bilesem

Duysam gök atların soylu sesini

Demir dağın delindiği yerlerden

Alsam ecdadımın hür hevesini

Ötüken içinde kitabelerden

Bir manasçı olsam yol kenarında

Anlatsam ezelî hikâyemizi

Çekik gözleriyle göl kenarında

Kırgız güzelleri beklese bizi

Bir sabah, tan vakti varsam Gence’ye

Âzerî gözümle görsem dünyayı

Sunsam Karabağ’ı Vahapzade’ye

Şehriyar ustayla sarsam dünyayı

Ruhumun tayını sürsem ileri

Bozkırlar üstüne dökülse tasam

Türkmen atlarının geçtiği yeri

Ay yıldızlı nallarından tanısam

Kerkük’te gürleyen hoyrat avazım

Gökkubbenin sedasını süslese    

Ozanlar omzunda yorulan sazım

Tellerini kopuzuma yaslasa

Kırım’da kırılan binlerce çocuk

Yüreğimin ışığında yeşerse

Başlayınca gökyüzüne yolculuk

Rabb’im her anaya bir çiçek verse    

Kızıl bayrak gözlerimi delerken

Diksem Gökbayrak’ı göğsüm üstüne

Kızıl Çin içinde bir sabah erken

Kürşatlar kırk yerden parlasa yine

Gül dalında güzel, yiğit ilinde

Yiğide  il veren bir ferman olsam

Gönül coğrafyamın tatlı dilinde

Özümle beslenen bir lisan olsam

Dedem Korkut yelkenime yel olsa

“Aziz İstanbul” a bıraksa beni

İncilerim damla damla gül olsa

Taksa duvağına seven seveni

Her muradın verildiği bir anda

Resûl’ümün eteğine sarılsam

Kokusundan tanıdığım vatanda

Bayrağımın gölgesinde dirilsem', 'Her muradın verildiği bir anda Şeyh Şamil’in düşlerini dilesem Kartal gagasıyla süslü zamanda Kafkasların kılıcını bilesem Duysam gök atları...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Dursun']::text[], 8.5, '{"poet":"Yusuf Dursun","poet_slug":"yusuf-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/gonul-cografyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ssensizlik', 'ssensizlik-sibel-oner-biymg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SENSİZLİK				

					

Hayatı yalnız yaşamak kader mi alınyazımı					

Sensizliğin hücresinde kahrolmak dertmi,kedermi					

Var olduğum yaşantımda çektiğim acımı,yaramı					

Bilmediğim insan için çektiğim hasretlikmi,cezamı					

					

Dünyada bitip tükenmek boş yaşamak çilemi					

Kaderine küsüp boynu bükük kalmak hakmı					

Çektiğim sıkıntılar yanıma karmı					

Tanımadığım insana ümitlenmem suçmu					

					

Kader alınyazı buysa yalnız yaşayacağım					

Dert kederse hep kahrolacağım					

Acıysa hayatımda onuda seveceğim					

Artık biraz da benden başkalarını sorgulayın diyecem					

					

İsyan etmek istemiyor ama ettiriyorlar ya					

Küs olmak istemiyor hayata ama itiyorlar ya					

Yıkılmak istemiyor ama parçalıyorlar ya					

Artık yeter demek geliyor içimden anlamıyorlar ya					

					

Sevgini yüreğimde beklerken amansız					

Birgün çıkıp geleceksin diye apansız					

Yaşayabilirmisin uzaklarda bensiz					

Bilki bende bitiyorum sensizliğinde sensiz					

					

Biliyorum haykırışlarım biçaresiz					

Eminim ki sende benim gibi çaresiz					

Birbirinden haberimiz olmayan varlığımız					

Sadece sen ve ben olduğumuzu bilmeliyiz					

					

Sevdadan konuşanlar boş boş bakar					

Aşıklar kuş misali havada uçar					

Sevenler sevilenler mutluyum der					

Sende bende niye mutlu olmayalım					

					

Eğer seninle birgün bir yerlerde karşılaşırsak					

İlk diyeceğimiz şey olsun niye geciktik					

İlk vereceğimiz cevap olsun saygı sevgi					

Gelsin sonrada emsali görülmemiş mutluluk					

					

					Sibel ÖNER', 'SENSİZLİK				 					 Hayatı yalnız yaşamak kader mi alınyazımı					 Sensizliğin hücresinde kahrolmak dertmi,kedermi					 Var olduğum yaşantım...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ssensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum Geleceksin', 'biliyorum-geleceksin-sibel-oner-e5cfe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BİLİYORUM GELECEKSİN				

					

Bugün yaşıyorsak çünkü bugündür					

Yarın sa sonra olmalı					

Bugün seviyorsak sevdalıyımdır					

Yarın seveceksen umutların olmalı					

					

Dünümü sildim kader defterimden					

Temiz bir sayfa araladım bugünden					

Sonsuza kadar sildiğim dünlerimden					

Bugünden başlayan hayallerimden					

					

Bugün doğdum ben bugün duyun beni					

Yarın ne yapacağım bilmem sorun beni					

Acı çektiğim dünü bilin					

Güleceğim yarınlarımı bekleyin					

					

İnsan bir fanidir yok olup gidecek					

Dertlerimde birer birer gün olup bitecek					

Özlemlediğim her zaman yanımda olacak					

Diye beklediğim yarınlarımı görün					

					

Kendime söz geçiremiyorum nafile					

Aşkımı bulamıyorum ne çare					

Boşluklarda dolandım deli divane					

Yine de mutluyum yakında o görecek					

					

Dedim ya bitecek elbet bitecek					

Geç kalmadan bana mutluluk verecek					

Rotarlı günlerimizin acısı çıkacak					

Sonunda iki kafadar meydan okuyacak					

					

Umuyorum mutluluk çok yakınımda					

Gözyaşlarım tükendi kurudu gözümde					

Seni bekliyor bu gönül bugün de					

Sevmek istiyor kendim seni bulunca					

					

Hayalimdekileri gerçekte mahçup etme					

Sevince karşılığını bulursun merak etme					

Bir damlacık mutluluğu benden esirgeme					

Geç kalmışlığımın acısını çıkarma					

					

					

				Sibel ÖNER', 'BİLİYORUM GELECEKSİN				 					 Bugün yaşıyorsak çünkü bugündür					 Yarın sa sonra olmalı					 Bugün seviyorsak sevdalıyımdır					 Yarın sev...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/biliyorum-geleceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben İstanbul''a taparım! ...', 'ben-i-stanbul-a-taparim-omer-faruk-girgin-75ysh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstanbul’u aşkla ve sadakatle severim. 

Arada bir başka şehirleri özlesem bile asla İstanbul’u başka bir şehirden fazla sevemem. 

Bu şehirde doğdum, bu şehirde yaşamak ve bu şehirde ölmek isterim. 

Mutfağı, musikisi, mimarisi, mizahı, şiiri, birçok dini ve kavmi bir arada kucaklayan derin tarihi, içinde her renkten bir parça taşıyan ebemkuşağını andıran kültürü, bir yer altı nehri gibi yeryüzüne her gün hayat fışkıran muhteşem bir şehirdir, benim şehrim. 

Denizleri, kumsalları, ağaçları, ormanları,, tepeleri; tarih ve kültürden damıtılmış dünyanın altın halkasına yerleştirilmiş maviyeşil firuzeden bir yüzük taşı gibi dünyanın olağanüstü bir parçasıdır İstanbul. 

Ve, burası yeryüzünün en güzel şehridir. 

Tüm güzellikleri içinde barındıran muhteşem bir hazine. 

Bu şehirde her şeyi bulabilir, görebilir ve yaşayabilirsiz. 

Dünyanın en güzel kadınları, en hızlı çapkınları, en babayani soyluları, kabadayıları, hırsızları, dilencileri, gecekonduları ve şehrin görkemini yansıtan muhteşem binaları iç içedir… 

Fakat kimin hırsız, kimin polis, kimin orospu, kimin hanımefendi, kimin kültürlü, kimin soysuz olduğunu hemen fark edemeyebilirsiniz. 

Aynı günde dört mevsimi yaşayabilir, kara, güneşe, yağmura boğulabilirsiniz. 

Yani çok şaşırırsınız. 

Eski saatler gibi titreyerek yirmidört saat hayatı yaşayabilirsiniz. 

Çünkü buradaki hayat insanın içini kıpır kıpır titretir. 

Kerhanesi, meyhanesi ve camisi bu kadar bol başka hiçbir şehir yoktur. 

Hayatı dolu dolu yaşayabilir, kirlenen ruhunuzu hemen köşe başında bir camide temizleyebilirsiniz. 

En derin aşklara, en büyük yalanlara, en büyük soygunlara, cinayetlere şahit olabilir fakat hayatı bir başka güzel de yaşayabilirsiniz. 

Hayat yirmidört saat elinizindedir. 

Ben bu yüzden İstanbul’u büyük bir aşkla severim. 

Akşamları gök kızıla çaldığında içim kanar. 

Hep İstanbul yanacak korkusu yaşarım. 

Hemen bir tepeye koşar İstanbul’a tepeden bakarım. 

Ve ben İstanbul’un üstünde alev alev yanarım. 

Sadece, orospusuyla hanımefendisini zor ayırırım. 

Aslında ayırt etmem, her ikisini de severim. 

Hepsi süslüdür, İstanbul’a yakışmak için birbirleriyle yarış halinde olduklarını düşünürüm. 

İçlerinden biri daha güzel yemek yapar. 

Sadece onu bilirim. 

İstanbul’da yaşamak sanattır. 

Soyluluktur. 

Şanstır. 

Hiç ummadığınız anda aşık olabilir, hiç ummadığınız anda ihanete uğrayabilirsiniz. 

İlahi bir gücün İstanbul’da yaşayanları, denizlerin dereleri temizlediği gibi insanları temizlediğine inanırım. 

Gizemli bir şehirdir burası. 

Herkes mutlaka bir günaha değer burada. 

Belki bu yüzden dilencisi en bol şehirdir. 

Çünkü kimse merhametten sadaka vermez burada. 

Merhametten verselerdi dilenciler açlıktan ölürlerdi diye düşünürüm. 

Neyse, ben bu şehri çok severim. 

Burada doğdum, burada yaşarım ve burada ölmek isterim. 

Meyhanelerinde içer, kerhanelerinde gezer, camilerinde ağlarım. 

Ben İstanbul’da taçsız, tahtsız bir kralım. 

Ben İstanbul’a taparım..', 'İstanbul’u aşkla ve sadakatle severim.  Arada bir başka şehirleri özlesem bile asla İstanbul’u başka bir şehirden fazla sevemem.  Bu şehirde...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Girgin']::text[], 8.5, '{"poet":"Ömer Faruk Girgin","poet_slug":"omer-faruk-girgin","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ben-istanbul-a-taparim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende İstiyorum', 'bende-i-stiyorum-sibel-oner-ndw4l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BENDE İSTİYORUM				

					

Seveceğim bende Ahmet,Mehmet,Ayşe,Fatma gibi					

Seveceğim bende senin beni sevdiğin gibi					

Aşık olup gökyüzünde uçacağım bulut gibi					

Yere düşmemeye çalışacağım bir canlı gibi					

					

Kuşlar cıvıldayacak kulaklarımda ahenkli					

Çiçek açarken yayacak kokusunu					

Güneş batarken verecek kalan ısısını					

Yıldız kayarken sunacak parlaklığını biliyorum					

					

Bekliyorum kuşlar cıvıldasın uçsun					

Çiçekler kokusunu yaysın					

Güneş sıcaklığını versin					

Işığımı alayım yıldızdan bir kez					

					

And içtim birgün seveceğim					

Yarınım sen hep sen diyeceğim					

Geçmişinle seni sorgulamayacağım					

Geleceğimin mutluluğunu sunacağım					

					

				Sibel ÖNER', 'BENDE İSTİYORUM				 					 Seveceğim bende Ahmet,Mehmet,Ayşe,Fatma gibi					 Seveceğim bende senin beni sevdiğin gibi					 Aşık olup gökyüzün...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bende-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklediğimsin', 'bekledigimsin-sibel-oner-zuv6s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BEKLEDİĞİMSİN				

					

					

Bir gün çıkıp geleceksin diye beklediğim					

Hayallerimi henüz ismini bilmediğimle süslediğim					

Yarınlarımda sen olacaksın diye hazırlandığım					

Daha şimdiden umutlarım,yarınlarım herşeyimsin					

					

Farzet çıktın karşıma beklediğim beklentimsin					

Misal girdin kalbime kalbimin sahibisin					

Verdin aşkı,sevdayı,mutluluğu bu kadar bonkörmüsün					

İşte buldum dediğimde korkup cayacakmısın					

					

Dünü bugünü hiç yaşamamışbiriyim ben					

Yarınından hiç umudu olmayan biri					

Oysa tanımadığım sen,yıldız kadar aydınlık					

Sular kadar berrak,gelecek olmalısın					

					

Yürekli oldum içimdeki acılar kadar					

Hayaller kurdum gerçekleşinceye kadar					

Yaşamayı sarıldım sen yoksan da sonuna kadar					

Hadi çık gel,desem gelmedi mi zamanı daha					

					

Çok şey beklemiyor SİBEL kendince					

Minnacık mutluluk istiyor,oda beraberince					

Zincirlemiş duygularını bedenine sımsıkıca					

Mutluluğum hadi gel artık diyor sadece					

					

Bu kadar haykırış yalvarış niçin bilinmez					

Bilinen tek şey kendim için fakat anlaşılmaz					

Bende benim gibi mutluluk arayan birinden					

Bir yanıt bekliyor,onunla hayallerimi süslüyorum					

					

					Sibel ÖNER', 'BEKLEDİĞİMSİN				 					 					 Bir gün çıkıp geleceksin diye beklediğim					 Hayallerimi henüz ismini bilmediğimle süslediğim					 Yarınlarım...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bekledigimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dopdolu Bir Gün', 'dopdolu-bir-gun-sibel-oner-c49ap', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'DOPDOLU BİR GÜN				

					

Uyandığımda dertlerim beni yalnız bırakmıyor					

Sersemliğimi üzerimden atarken bile beni düşündürüyor					

Yeni birgün başlıyor sevinciyle başladığım bugün					

Daha erken saatlerde beni bunaltıyor					

					

Gün içinde zaten kafam karmakarışık					

Cevap bulamadığım sorularım darmadağınık					

Emin olamadığım yaşantım saçmalık					

Kötü bir hayatım olduğunu anlıyorum çarçabuk					

					

Kendini bilmez iki densiz çıkıverir					

Uğraşırsın ama seni biranda bitirir					

Tam peki pes ettim derken					

Sabrım direnir,karşılığını veriverir					

					

Gün yavaş yavaş bitmekte bittim sanır					

Oysa benim günüm yeni yeni başlar					

Gün içinde yaşananlara alıştım zaten					

Ciddisi gün sonu ve yeni birgün başına kadar					

					

Gece uzanırım yatağıma sanki hiçbirşey yok gibi					

Tırmalayıp çalışmışımdır tıpki bir amele gibi					

O yoğun gün içi birkaç saniyelere sığar yelkovan gibi					

Uyumaya çalışırsın ama uyutmaz içindeki					

					

Sıkıntılar buhranlar kara bulutlar çöker üstüme					

Git istemiyorum derim gitmez çullanır tepeme					

Ne yapayım çaresiz ben olduğumca var dertlerim					

Sanki bir tutuklu gibi kelepçeledim zincirlerimi					

					

Bazende o bırakmak ister beni ama alışmışım ya					

Acı versede sorunlarım onlar benim bir yandaşım					

Onlarda bırakırsa ben nasıl yaşarım					

Varsın onlarda olsun yaşantımda					

					

Dünya kahpeliklerle doluysa ben ne yapayım					

İyi biri olmak istiyorsam hatalımıyım					

Sevmek sevilmek istesem suçlumuyum					

Mutluluk peşinden koşsam acemimiyim					

					

Hayat zor bir imtihan çalışmalıyım					

Ümitsizde olsa bu sınavı vermeliyim					

Kendimle barışmalıyım					

Ve sevmeyi denemeliyim					

Ve aşkı					

Ve ve sonrasını					

					

				Sibel ÖNER', 'DOPDOLU BİR GÜN				 					 Uyandığımda dertlerim beni yalnız bırakmıyor					 Sersemliğimi üzerimden atarken bile beni düşündürüyor					 Yeni ...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/dopdolu-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..Sevgi Vermekle Çoğalır..', 'sevgi-vermekle-cogalir-veli-dalbudak-v7ka8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '...SAKIN  haa,

...........................

- Üzülme, söylemesede dilin,

...........................gözlerin varya.

-Iyi tut dizginleri, azmasın nefs`in

..................ondan öte Betermi var.

-Üzülme, görmesede gözlerin,

..........................gönlün varya.

-Sakın haa, kurumasın gönlün,

..................ondan öte değermi var.

....SAKIN  haa,...

................

-Yerinme yokluğa,

-Gerilme çokluğa,

-Kim düşmeyecek toprağa

.............ondan öte yarmi var.

...Bilesin ki...

....

.Sevgi, vermekle çoğalir. Azalmaz

.Paylaşmakla, dertler kaybolur

.............sevgi kaybolmaz

.N`olcak, alem senin olsa eyy uslanmaz,

---Ucunda Ölum Varya.

(Stockholm 2005)', '...SAKIN  haa, ........................... - Üzülme, söylemesede dilin, ...........................gözlerin varya. -Iyi tut dizginleri, azma...', ARRAY['Türk Edebiyatı','Şiir','Veli Dalbudak']::text[], 8.5, '{"poet":"Veli Dalbudak","poet_slug":"veli-dalbudak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevgi-vermekle-cogalir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsaydım', 'olsaydim-sibel-oner-puzkw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'OLSAYDIM			

				

Eğer ben anlaşılmaz biriysem				

Beni anlamıyorlar diye üzülmem				

Olmayacak hayaller kurduysam				

Sonuca katlanır yıkılmam				

				

Düşlerimi sadece hayalde yaşatsaydım				

O düşlerime roman yazardım				

Sevdanın bir zerresini nasip olsaydı				

Sevda kelimesinin sözlüğüme alırdım				

				

Erkeğimin hep yanında olsaydım				

Onu hiçbir zaman bırakmazdım				

Yargısız infaza uğrasaydım				

İdam sehpasına kendim çıkardım				

				

Suçlu denilip hep susturulsaydım				

Dilimi amatör doktora kestirirdim				

Hayat bana ikinci bir şans vermeseydi				

Yemin ederim intihar ederdim				

				

				

			Sibel ÖNER', 'OLSAYDIM			 				 Eğer ben anlaşılmaz biriysem				 Beni anlamıyorlar diye üzülmem				 Olmayacak hayaller kurduysam				 Sonuca katlanır yıkılm...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/olsaydim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ölüncemi? ? ?', 'sen-oluncemi-sibel-oner-nrd0g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SEN ÖLÜNCE Mİ? ? ? 				

					

					

Yaşadığımız bugünlerin sonu olacak elbet					

Başka mekanlarda açacaksın gözünü sabret					

Bulunduğun ortamda ne durumda olduğunu farket					

Şaşkın bakışlarla sağına bakacaksın					

Fakat kimseleri bulamayacaksın					

İşte anla ki; o zaman yalnız başınasın					

Yaşadıkların ve yaşayamadıklarınla					

Yüreğin yanacak acı çekeceksin					

Dünyadaki yetmezmiş gibi inleyerek					

Mutluluk bana nezaman bulacak diye soracaksın kendine					

Mutluluğu bulduğunda sahip çıktınmı sanki de					

Öbür dünyadamı bu soruna cevap bulacaksın.					

Bizler bu dünyada yaşarken kıymetini bilemediğimiz gibi					

Yaşarken yakalayamadığımız kaybettiğimiz aşkını					

Kendine soramadığın soruyu sevgiliye sorduğun gibi					

Güzelliklerin kıymetini ölüncemi anlayacaksın.					

					

					

					

					Sibel ÖNER', 'SEN ÖLÜNCE Mİ? ? ? 				 					 					 Yaşadığımız bugünlerin sonu olacak elbet					 Başka mekanlarda açacaksın gözünü sabret					 Bulunduğun o...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-oluncemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''da Bir Erguvan Akşamı', 'i-stanbul-da-bir-erguvan-aksami-yusuf-dursun-322eh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I

İstanbul’da bir erguvan akşamı,

Gurubun rengini çektim içime.

Boğaz’da suların “o gül endam”ı,

Çevirdi ruhumu bin bir biçime.

Kınalı’dan Heybeli’ye geçerken,

“Adalardan gelen yâr” i aradım.

Emirgân’ı yudum yudum içerken,

Çamlıca’nın saçlarını taradım.

Bülbülün yuvası, gülün kokusu…

Aşkın ateşinden izler taşıyan

Dua dua kabir, şifa şifa su…

Canlar tazelenir: İşte Âşiyan! 

Âhû gözlü, servi boylu Üsküdar

“Kâtibimin setresi” ni arıyor.

Kanlıca Sırtı’ndan Moda’ya kadar,

İstanbul, gönlüme huzur veriyor.

Eminönü anaç, Beyoğlu cömert,

Sevenleri âbâd eder İstanbul.

Kadıköy yiğittir, Kasımpaşa mert; 

Vefasızı bedbaht eder İstanbul.

Mahmutpaşa’dayım, kanım kaynıyor,

Mısır Çarşısı’nda duruluyorum.

Martılar, canımla oyun oynuyor,

Yetiş ey yüreğim, vuruluyorum! 

Ufkumda Topkapı, muhteşem gurur; 

Taşıyacak bizi dünden yarına.

Aşkın ve acının çığlığı vurur,

Sarayın esrarlı duvarlarına.

Bir yanda Avrupa, bir yanda Asya,

Ebemkuşağıdır Boğaz Köprüsü.

İşte gözbebeğim… İşte Avrasya…

Milletimin çağlar aşan türküsü.

II

Sur dibinden hâlâ sesler  geliyor,

Fatih, İstanbul’u yoklar gibidir.

Ulubatlı Hasan bayrak oluyor,

İstanbul, Fatih’i bekler gibidir.

Galip Dede can postuna kurulmuş,

Dilinde mısralar inciye döner.

Söz ateşi Beyatlı’ya verilmiş,

Şiir ikliminde daima yanar.

Eyüp Sultan  ile koyun koyuna

Sultanü’ş şuarâ Necip yatıyor.

Haliç’te kayıklar dalmış oyuna

Balıklar kiminle güreş tutuyor? 

Cumbalı bir evde taksim sesi var,

Tamburu bu akşam Cemil çalıyor.

Gazelle, şarkıyla geliyor bahar,

İstanbul, bu akşam Münir oluyor.

İstanbul’un süt kokulu Türkçesi,

Bir hanım/elinde çiçeğe döner.

Masalla canlanır bin bir gecesi,

İstanbul’da hayal, gerçeğe döner.

Sultan Ahmet Camii’nde müezzin,

Davûdî sesiyle ezan okuyor.

Yaradan aşkıyla  cümle ins ü cin

Kanat kanat camilere akıyor.

Sülün minareler, hilâl kubbeler…

Rabb’im bu ne sabır,  bu ne emektir? 

Ceşme çeşme nakışlanmış tepeler,

İstanbul,  biraz da Sinan demektir.

Nedim der ki: “İstanbul’un bir taşı

Acem ülkesinden üstündür elbet.”

Ben derim ki, kâinatın güneşi

İstanbul olacak ta ebed müddet.

III

İstanbul’a bugün gönlümü verdim,

Yarın da ruhumu vermek isterim.

Ebedî vuslata ben onda erdim,

Uykuya koynunda girmek isterim.', 'I İstanbul’da bir erguvan akşamı, Gurubun rengini çektim içime. Boğaz’da suların “o gül endam”ı, Çevirdi ruhumu bin bir biçime. Kınalı’dan H...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Dursun']::text[], 8.5, '{"poet":"Yusuf Dursun","poet_slug":"yusuf-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/istanbul-da-bir-erguvan-aksami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A ş k ı m ı z', 'a-s-k-i-m-i-z-sibel-oner-mtf3x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'A Ş K I M I Z 					

						

Bir zamanlar ne güzeldi aşkımız,roman gibi						

Sonra sayfa sayfa araladık,sevgi çıktı karşımıza						

Oldu romanımızın adı aşk masalı						

Yüreğimizin kapısını çalan kapıyı sevgi sandık açtık.						

Kim olduğunu bilmeden yüreğimize aldık						

Sonu bilemezdik,ayrıldığımızda onu atamayacağımıza						

Onun bana bu kadar acı vereceğini						

Ve aşkıma mahkum olacağıma						

Bu roman çok arsızmış bee gitmedi bir türlü						

Gitmesi aylarımı,yıllarımı aldı						

Ben kovdukça yapraklarını kopardıkça o hala						

Karşımda dimdik sırıtarak bakıyordu.						

Ve girmiştim ayrılık girdabına neyse						

Her şeyi aştım,romanı yaktım ama aşkım,						

Yüreğimde kaldı hep......						

						

						

				Sibel ÖNER', 'A Ş K I M I Z 					 						 Bir zamanlar ne güzeldi aşkımız,roman gibi						 Sonra sayfa sayfa araladık,sevgi çıktı karşımıza						 Oldu roma...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/a-s-k-i-m-i-z-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'S a y e n d e', 's-a-y-e-n-d-e-sibel-oner-v1rfq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'S A Y E N D E 			

					

Sayende sevmeyi öğrendim					

Aşkı,aşkın verdiği acıyı					

Sevgiyi tattım sayende					

Terkedilmişliğin verdiği ızdırabı					

Sayende nefretle tanıştım					

İnsanların insanlara söyledikleri yalanı					

İçimde yeşeren çiçeği soldurdun					

İçimde gülen bebeği susturdun					

İçimde kaynayan duygularımı bastırdın					

Sayende acıları yaşadım					

Sen terketmenin gururuyla gezerken					

Bense terkedilmişliğimin çaresizliği içinde					

Sen bitirmenin verdiği mutlulukla gülerken					

Bense kör kuyuların içinde					

Sen ihanetini benimle tanıştırıp giderken					

Bense anlaşılamaz bir boşluk içinde					

Sen hep sen doğru olduğunu söylerken					

Ben kayboldum sınavın içinde					

Evet sayende varya sayende					

Acıları göğüs gerdim					

Ve yine senin sayende					

Terkedilmişliğime alıştım					

Unutulmuşluğuma sevdim					

Yokluğunu öğrendim					

Varlığından artık şüphe ettim,anlarsın ya					

Senin SAYENDE					

					

				Sibel ÖNER', 'S A Y E N D E 			 					 Sayende sevmeyi öğrendim					 Aşkı,aşkın verdiği acıyı					 Sevgiyi tattım sayende					 Terkedilmişliğin verdiği ızd...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/s-a-y-e-n-d-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülistan İstanbul', 'gulistan-i-stanbul-yusuf-dursun-veu7w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçimde fırtına, dışımda bora; 

İstanbul diyerek düştüm yollara.

Yollarım bir ayaz, zehir zemberek

Yolları çözmeye bir şiir gerek.

“Gülistan”dan bahsedince ayaza,

Bir anda kara kış, çevrildi yaza.

Bahar bahar oldu yollar önümde,

Bir kıpırtı çiçek açtı canımda.

İstanbul yoluna şiir ekerim,

Şiirime yıldızları dökerim.

İçimde fırtına, dışımda bora; 

Yollarıma kilit vurma Ankara.

Bu yolun sonu yok içimden başka,

Bırak da geçeyim gönülden köşke.

Çamlıca’nın kirpiğine konayım,

Kadıköy’ün gözlerinde yunayım.

Haliç’ten içime gedik açılsın,

Âşiyan’dan yüreğime geçilsin.

Yollar beni sobelesin, ebeyim; 

Her şiirde İstanbul’a gebeyim.

İçimde fırtına, dışımda bora; 

Bir yanım gül beyaz, bir yanım yara.

Eyüp sırtlarına sorun yaramı,

Emirgân aşkıyla sarın yaramı.

Bolu Dağı başımıza yağmadan,

Beyaz âfet üstümüze doğmadan,

Hüzün dağlarına koyun ayazı,

İstanbul yazıyor alnımda yazı.

Lâleleri deste deste İstanbul,

Her tepesi bir güldeste İstanbul.

İçimde fırtına, dışımda bora; 

Üç yanım denizdir, bir yanım kara.

Deniz, kucağımda Bebek gibidir,

Kara, Gülhane’de çiçek gibidir.

Deniz, Adalar’da arı ve duru,

Kara, Beykoz’da bir Yûşâ yağmuru.

Deniz, Ortaköy’de sahile vurur,

Kara, Üsküdar’da namaza durur.

Denizim İstanbul, karam İstanbul,

Bana başka şehir haram İstanbul.

İçimde fırtına, dışımda bora; 

Açtım yüreğimi İstanbul, fora! 

Bir Boğaz şifresi verin içime,

“İstanbul” diyerek girin içime.

Çekmece Gölü’ne haber uçurun,

Heybeli’yi şiirime içirin.

Delinsin içimde hüzün dağları,

Serilsin önüme şiir çağları.

Kasideni gönlüme sun İstanbul,

Şiirime bayrak olsun İstanbul.', 'İçimde fırtına, dışımda bora;  İstanbul diyerek düştüm yollara. Yollarım bir ayaz, zehir zemberek Yolları çözmeye bir şiir gerek. “Gülistan”...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Dursun']::text[], 8.5, '{"poet":"Yusuf Dursun","poet_slug":"yusuf-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/gulistan-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Severim Seversin Diye! ! !', 'severim-seversin-diye-sibel-oner-ykijx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SEVERİM,SEVERSİN DİYE! ! ! 			

				

				

Dünü sildim,unuturum diye				

Çırpındım kuş gibi acım dinsin diye				

Çabaladım belki severim diye				

Ümitlendim belki seversin diye				

				

Bugün artık dedim,severim diye				

Beynimi hükmettim sevsin diye				

Zorladım benliğimi sever diye				

Ama başaramadım gibi				

				

Yarınımda da belki yine severim diye				

Umutla bekliyorum seversin diye				

Gözümü kapamıyorum belki gidersin diye				

Ümit ediyorum belki beni yeni seversin diye				

				

Gecenin her bitiminde sensizliğin				

Ümitle uyanıyorum sabahın				

Yaşıyorum belki birgün severim diye				

Belki de seni bulurum beni seversin diye				

				

				

				Sibel ÖNER', 'SEVERİM,SEVERSİN DİYE! ! ! 			 				 				 Dünü sildim,unuturum diye				 Çırpındım kuş gibi acım dinsin diye				 Çabaladım belki severim diye	...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/severim-seversin-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişmanmısın Ne Fayda kii? ? ?', 'pismanmisin-ne-fayda-kii-sibel-oner-2eaoz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'PİŞMAN MISIN NE FAYDA Kİ? ? ? 				

					

					

Hep bekledim pişman olacağın bugünü					

Ama ……………...tarihinde değil					

Hep arzuladım tekrar karşıma çıktığın günü					

Ama beni severek değil.					

					

Şans,şans,şans,şans,şans................					

Sana bana göre değil artık çok uzak					

Acı,acı,acı,acı,acı..................					

Bize layık değil artık çok ırak					

					

Beklediğim bugün soramıyorum pişmanmısın					

Biliyorum ki,çok hemde çok pişmansın					

Sanki pişman olduğunu inanabiliyormuyum					

Yine de pişmanmısın ne fayda ki? ? ? 					

					

Sana inanacak,inancım kalmadı biliyormusun					

Sana açacak yüreğim yok anlıyormusun					

Dayanamıyorum varlığını silmişken duyuyormusun					

Git diyorum,pişmanlığını  da bilmek istemiyorum biliyormusun					

					

Kendine benzetmeye çalışma ben pişman değilim					

Uzak dur benden ben artık kendimleyim					

Altı yıl önceki varlığın kalsın,benimleyim					

Yılları deşme boşuna,boş sayfalardayım					

					

Üzgün değilim artık inan karşındayım					

Sevmiyorum artık kendimleyim					

Unuttum artık seni sonsuzlardayım					

Şimde daha da mutluyum bak buralardayım					

					

					

					Sibel ÖNER', 'PİŞMAN MISIN NE FAYDA Kİ? ? ? 				 					 					 Hep bekledim pişman olacağın bugünü					 Ama ……………...tarihinde değil					 Hep arzuladım tekra...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/pismanmisin-ne-fayda-kii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldim Bir Kere', 'geldim-bir-kere-sibel-oner-j8bpw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'GELDİM BİR KERE				

					

Dünyaya geldin dedi ebeannem					

Ama yaşamaya hasretim					

Yaşayacaksın bu dünyada dedi alem					

Ama özgürlüğe hasretim					

					

Sonunda doğduğuma alıştım					

Ama mutsuz					

Ve yaşamayı öğrenmeyi çalıştım					

Ama beceriksiz					

Özgürlüğün tadına başladım					

Ama acımasız					

Sevemeyi,sevilmeyi çabaladım					

Ama imkansız					

Hasretim sevgiye					

Ama kaybettim					

Sevdiğimin yerine					

Hasreti koydum					

Sevgiliyi bulmaya çalıştım					

Ama onu bulmaya hasretim					

Geldim dünyaya hasret					

Gidiyorum yine hasret					

Yaşıyorum halen hayat bayat					

Bitiyorum yine yaşam koca bir hiççç.					

					

					

				Sibel ÖNER', 'GELDİM BİR KERE				 					 Dünyaya geldin dedi ebeannem					 Ama yaşamaya hasretim					 Yaşayacaksın bu dünyada dedi alem					 Ama özgürlüğe ...', ARRAY['Türk Edebiyatı','Şiir','Sibel Öner']::text[], 8.5, '{"poet":"Sibel Öner","poet_slug":"sibel-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/geldim-bir-kere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salıncak', 'salincak-ozgurcan-unal-uvjmj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ya bu salıncakta bir çocuk sallanacak

ya da salıncak hep ağlayacak', 'ya bu salıncakta bir çocuk sallanacak ya da salıncak hep ağlayacak...', ARRAY['Türk Edebiyatı','Şiir','Özgürcan Ünal']::text[], 8.5, '{"poet":"Özgürcan Ünal","poet_slug":"ozgurcan-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/salincak-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-ahmet-ozdemir-pf1t4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ruhumun gıdası bir tatlı kaygı,

Canıma can katan bengisin gülüm.

Kalpten kalbe akan en güzel duygu; 

Tüm güzelliklerin rengisin gülüm.

Saymadım kimlere inandım kandım,

Bir masal, bir öykü, bir oyun sandım.

Sonunda sevdayla tanıştım yandım; 

Bitmeyen sevgimin dengisin gülüm.

Aşk yolunda rastlanmaz mı engelle? 

Parmaklar perdeyle, mızraplar telle,

En güzel ritimler vurulur elle,

Gönül meyhanemin çengisin gülüm.', 'Ruhumun gıdası bir tatlı kaygı, Canıma can katan bengisin gülüm. Kalpten kalbe akan en güzel duygu;  Tüm güzelliklerin rengisin gülüm. Sayma...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özdemir']::text[], 8.5, '{"poet":"Ahmet Özdemir","poet_slug":"ahmet-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gulum-121-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlıklar Tepesi', 'yalnizliklar-tepesi-volkan-yoruc-1d0nb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir tepede gözlerim sevdayı

Ufukta parıldayan senmişsin diye

Her bir sabah selamlarım uzağı

Bir gün çıkarda geliverirsin diye

Gökyüzünden düşen her bir damlayı senin için alırım

Elimde buhar olurda gider her seferde

Ağlarımda yine dolar avuçlarım

Dost bildiklerimedir sözlerim

Bir tepede sizi sessizcesine gözlerim 

Herşeye rağmen sevdamı beklerim

Evet yalnızlar içindeyim

Ne bir dost ne bir aşk var yüreğimde

Ölmüşümde duyanım olmamış misali yanar ciğerim

Bir tepeden aşağı bakarken oluşmuş yüreğim

Bazen bir uçurum boyunda uyanmışım

Bazen bir dikenin ucuna saplanmışım

Kan kırmızı düşlerimle süslerken sevdamı

Yalnızlıklar tepesi koymuşum bu uçsuz damı', 'Bir tepede gözlerim sevdayı Ufukta parıldayan senmişsin diye Her bir sabah selamlarım uzağı Bir gün çıkarda geliverirsin diye Gökyüzünden dü...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yalnizliklar-tepesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-ferit-agca-9z197', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu şehir taşımaz diyorlar,

Büyük aşkları.

Beklerken sevgileri,

Saramaz koynunda seni.

Tutunamazsın kalbinde.

Bu şehir taşımaz diyorlar,

Birliktelikleri,

İnsan yığınlarında yalnızlıkları,

Beklemez seni vapurları,

Ve mehtabı.

Bu şehir taşımaz diyorlar,

Ayrılıkları,

Çürümüş ilişkileri,

Tutuksuz yargılar seni.

Yaşatır müebbeti.

Bu şehir taşımaz diyorlar,

Kendine âşıkları,

Sevdiğin kadar yorgunluğu,

İstediğin kadar özlemi,

Verir tutkusunu.

İstanbul taşımaz diyorlar.', 'Bu şehir taşımaz diyorlar, Büyük aşkları. Beklerken sevgileri, Saramaz koynunda seni. Tutunamazsın kalbinde. Bu şehir taşımaz diyorlar, Birl...', ARRAY['Türk Edebiyatı','Şiir','Ferit Ağca']::text[], 8.5, '{"poet":"Ferit Ağca","poet_slug":"ferit-agca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/istanbul-194-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-dua-ekseni-nvcib', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'DUA

sevda nedir sence? 

sevildiğin oranda sevmek mi? 

sevda bence; 

bir şiirde aynı tadı alabilmek,

ayrı bedenlerde atan iki kalbin

aynı sızıyı hissedebilmesidir.

bazen de; 

gönül yarasının aynısının 

sevdalıya da verilmesi,

veya sevgilinin vurdumduymazlığının

kendisine de lûtfedilmesi duasıdır.

benim duam bunlardan hiçbiri değil.

Vedûd olandan; 

senin yalnızca beni sevmeni dilemiyorum

sadece benim olmanı da beklemiyorum

beni sevdiğin sürece sevmeyi de istemiyorum

bunun adı sevda değil değiş tokuş olmaz mı? 

sevilirken sevmek kolay gelmez mi? 

sevmediğin zamanda da seni sevebilmek

marifetini bağışlamasını diliyorum….

(duaekseni)', 'DUA sevda nedir sence?  sevildiğin oranda sevmek mi?  sevda bence;  bir şiirde aynı tadı alabilmek, ayrı bedenlerde atan iki kalbin aynı sız...', ARRAY['Türk Edebiyatı','Şiir','Dua Ekseni']::text[], 8.5, '{"poet":"Dua Ekseni","poet_slug":"dua-ekseni","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dua-89-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Adım Pembe.', 'benim-adim-pembe-nurten-altinok-pk1zq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim adım Pembe olsun

Senin adın Mavi

Anlat bana

PEMBE ile MAVİ''yi 

Bir masal anlat bana

Gece uyanmasın

Benim adım Pembe olsun

Senin adın Mavi

Pembe’yle Mavi’yi anlat bana

Kimse duymasın

Pembe Mavi’ye yangın olsun

Mavi körkütük

Bir masal anlat bana

Bizim olsun', 'Benim adım Pembe olsun Senin adın Mavi Anlat bana PEMBE ile MAVİ''yi  Bir masal anlat bana Gece uyanmasın Benim adım Pembe olsun Senin adın M...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/benim-adim-pembe-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine de Sen', 'yine-de-sen-dua-ekseni-bops1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'YİNE DE SEN

unutmak mümkün mü o gülen gözü

gahi zehir,gahi baldan tatlıdır sözü

çeken varken can yükle dur nazı

değişmez kader,alından silinmez yazı

….

say ki yeniden yazılsın bir an

her dem gülünü mutluluğa boğsan

ruhla beden gibi hep yanımda olsan

ölsem elim elinde,gözümü yumsam

….

kahırla geçen günler geriye gelmez

pişmanım demen yaşanan acıyı silmez

anlatmadım cefanı hiç kimse bilmez

yinede bu yürek senden gayrıyı sevmez

(duaekseni)', 'YİNE DE SEN unutmak mümkün mü o gülen gözü gahi zehir,gahi baldan tatlıdır sözü çeken varken can yükle dur nazı değişmez kader,alından silin...', ARRAY['Türk Edebiyatı','Şiir','Dua Ekseni']::text[], 8.5, '{"poet":"Dua Ekseni","poet_slug":"dua-ekseni","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yine-de-sen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Hancı Uyan', 'ey-hanci-uyan-serap-buyuk-13nax', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey Hancı uyan! bir kere de sen misafir ol

Gönül bahçemin baş köşesine

Uzan kollarımın yumuşak şezlonguna

Kutsal kitabın sözcüklerini fısıldayayım sevgiyle

Göz yaşlarım sevinçten şelale olsun

Islak kirpiklerim hurilerden öte

Gökyüzüne bir de benim bahçemden bak

Senin bahçende olmayan sevgiyi göreceksin

Kuşların nasıl da cıvıldadığını duyacaksın

Konacak asmaları olmasa da

Mırıldanmayacak şarkıları söyleyeceksin

Sevda üzerine ne yazılmışsa

Dudaklarının ucunda birbiri ardına

Uyan hancı vakit azalıyor

Genç ruhlarımız yaşlanan bedenimize sıkışıyor

Biz başka rolleri oynarken

Bahçemizin ışığı azalıyor

Gel misafir ol bahçeme

O tahta masadaki semaverden yudumlarken çayını

Ne maziden gelmediğini, nede antik olmadığını,

Hep yeniden ve yeniden heyecan verdiğini,

Hep kalabalık yalnızlığımın başköşesinde kendini

Göreceksin

Gençliğimin kılıfını çıkarıp atarken

Taşıdığım özlemle karışmış kırgınlığım hep içimde

İşte asıl maziden gelen.

Mana arama sözcüklerimde,  düpedüz yazılmış gönlümün sesidir

Bir tek senin duyabileceğin

Bu kadar özgür, bu kadar rahat yazabildiğim

Bir tek sensin

Sıkıştırma duygularını bambuların sınırlarına

Benim bahçemden daha mavi daha güzel görünüyor gökyüzü

O eşsiz sınırsızlıkta

Ey hancı, benim gördüğüm senin hanında

Tapınağına saklanmış küçük bir çocuktu

Oyuncağı her an elinden alınacakmış gibi

Huzursuz, kıskanç, huysuz

Çocukça kıskançlığında tutkularına saklı

Dopdolu duyguları hep kapalı

Ama gözlerindeki ışığı saklayamadı

İşte benim gördüğüm o ışıktı

Kendini aydınlatmaktan bile korkan

Benim gördüğüm, beni uzaktan uzağa izleyen o gözlerindi

Başka şeyler söylerken

Mırıldanma sözcüklerini

Şöyle dolu dizgin özgürce söyle

Söyle ki bilinsin

Şimdi kaybedilen ne varsa elimizde

Kalan daha da fazla bizimdir

İster maziden, ister antik desen de

Tüm bunları kaybetmeme telaşı

Bir garip Serap işte

Kasım 1996', 'Ey Hancı uyan! bir kere de sen misafir ol Gönül bahçemin baş köşesine Uzan kollarımın yumuşak şezlonguna Kutsal kitabın sözcüklerini fısılda...', ARRAY['Türk Edebiyatı','Şiir','Serap Büyük']::text[], 8.5, '{"poet":"Serap Büyük","poet_slug":"serap-buyuk","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/ey-hanci-uyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Limanlarımda İstanbul', 'benim-limanlarimda-i-stanbul-yasin-yamak-555db', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar ne çok geçti üzerinden,

Altında sadece anlamın kaldı.

Sen İstanbul''dun oysa,

Seni bile sana bırakmadılar,

Sensiz kaldın.

Şimdi benim ruhumdasın ve

Sen İstanbul sen hep bende

Kalacaksın.

Suların kıyılarıma vuracak ve o kıyılardan

Seni anlamayanları uğurlayacaksın.

Çünkü sen hep güzeldin

Sende yaşayanları güzelliğinle besledin.

Tarihi yazdın surlarına,

Mürekkebini Fatih''in hırsına akıttın.

O seni tuttuğunda sen

Doruklara ulaştın

Ve öylesine güçlüydün ki; 

Tarihini silbaştan yaşadın,

Ama hiç sıkılmadın.

İşte en sonunda bendesin ve yorgunsun,

Artık benim limanlarımda İstanbul''sun...', 'Yıllar ne çok geçti üzerinden, Altında sadece anlamın kaldı. Sen İstanbul''dun oysa, Seni bile sana bırakmadılar, Sensiz kaldın. Şimdi benim ...', ARRAY['Türk Edebiyatı','Şiir','Yasin Yamak']::text[], 8.5, '{"poet":"Yasin Yamak","poet_slug":"yasin-yamak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/benim-limanlarimda-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efsane', 'efsane-serap-buyuk-ha5fh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'efsane yüklü Toros’lar

durup dinler şimdi yeni bir efsaneyi

aynı toprağın çocukları

yarım yüzyıldır bilmezler birbirlerini

şimdi yüzyıllara efsane olacak sevgileri

aynı toprağın,dağın,denizin,mavinin çocuklarıdır

biçilmiş kaderlerinden

bin acı,bin sevinç,bin hüsran yaşamıştır

yürekleri durmuştur sanki, birbirlerini bilene dek

öyle ki bir yangın başlar

için için tutuşur yürekleri

meydan okuyup zamana

tutuştururlar sevgilerini

bir efsanenin ilk şahitleridir şimdi

2003', 'efsane yüklü Toros’lar durup dinler şimdi yeni bir efsaneyi aynı toprağın çocukları yarım yüzyıldır bilmezler birbirlerini şimdi yüzyıllara ...', ARRAY['Türk Edebiyatı','Şiir','Serap Büyük']::text[], 8.5, '{"poet":"Serap Büyük","poet_slug":"serap-buyuk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/efsane-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Görevin', 'senin-gorevin-huseyin-avdic-2bp50', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senın Görevin

Seneler geçer ama,

Dünya bir yalan değil.

İnsan doğar, ölür ama,

Yaşam bir hayal değil.

Bir gerçeği var hepsinin,

Onu bulmak kolay değil.

İşte görevin budur senin,

Ondan kaçmak kurtuluş değil.

İşte dünyanın gerçeği:

Vardır onun bir ''öte''si.

İnsanları alır Rab''den,

Yine götürür O''na geri.

Kurtuluş istersen eğer,

Biraz gerçekçi oluver.

Senin bir Sahib''in vardır,

O''nu hemen buluver.

Emrine boyun eğiver,

Kurtuluşuna eriver! 

Hüseyin Avdıç-Mart 2005', 'Senın Görevin Seneler geçer ama, Dünya bir yalan değil. İnsan doğar, ölür ama, Yaşam bir hayal değil. Bir gerçeği var hepsinin, Onu bulmak k...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/senin-gorevin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Kefen', 'mavi-kefen-yasar-pullu-qw93a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerime bulaşmış bir kere mavı

Delirmişim 

Neyleyım 

İz bırakmış tenıme

Yurdumun dört bir yanı

Örsle dövmüşüm özümü

Avuçlarımdan sızmış keder 

neyleyim.

Gözyaşın düşmüş içime sevgili

Sıcağı kavurmuş beni

Çaputlara sarılmış bir çocuğu

Emzirirken annesi

Ayırıp gecekondu semtlerini

Yakarım bu şehri

İster adam gibi adam desinler

İsterse deli.

Geceye boşalttığım bu sancı

Hangi fırtınayla sarılır sevgili

Yani genç bir ölümdür bu

Unutmuş taranmayı saçları

Kefeni mavi', 'Gözlerime bulaşmış bir kere mavı Delirmişim  Neyleyım  İz bırakmış tenıme Yurdumun dört bir yanı Örsle dövmüşüm özümü Avuçlarımdan sızmış ke...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Püllü']::text[], 8.5, '{"poet":"Yaşar Püllü","poet_slug":"yasar-pullu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mavi-kefen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salat, selam olsun Muhammed’ime', 'salat-selam-olsun-muhammed-ime-mikdat-bal-6kp4w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hamd olsun Allah’a peygamberim var 

Salat, selam olsun Muhammed’ime 

Yolumu nur eden bir rehberim var 

Salat, selam olsun Muhammed’ime 

Onun sayesinde alem var oldu 

Allahı sevenler ona yar oldu 

Ona uymayanlar ziyankâr oldu 

Salat, selam olsun Muhammed’ime 

Gelişiyle cihan nura gark oldu 

İnsanların kalbi nur ile doldu 

Risalet zinciri onda son buldu 

Salat, selam olsun Muhammed’ime 

Alemlere rahmet, hem merhamettir 

Hayatı örnektir, bize sünnettir 

Sünnetine uyan sonu cennettir 

Salat, selam olsun Muhammed’ime 

Bize yol gösterip, müjdeler verdi 

“Kişi sevdiğiyle, biledir” derdi 

Ümmetine düşkün, hem çok severdi 

Salat,selam olsun Muhammed’ime 

Yüce Allah bilir, gizli halimden 

Her an salat,selam,düşmez dilimden 

Kıyamet sabahı, tutar elimden 

Salat, selam olsun Muhammedime 

Şefaatı haktır, günahkarlara 

Der ki şefaatim asi kullara 

Mikdat Bal günahkar, dahil bunlara 

Salat, selam olsun Muhammed''ime', 'Hamd olsun Allah’a peygamberim var  Salat, selam olsun Muhammed’ime  Yolumu nur eden bir rehberim var  Salat, selam olsun Muhammed’ime  Onun...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/salat-selam-olsun-muhammed-ime-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Kapıda', 'ask-kapida-akif-huseyin-ozmercan-43snj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Olaylar akıyor gözümün önünden

Ben bu filmi daha önceden gördüm sanki

Yine gece yürüyüşleri

Yine akşam sefaları

Yine cam güzelleri

Ve yine aşk kapıda…', 'Olaylar akıyor gözümün önünden Ben bu filmi daha önceden gördüm sanki Yine gece yürüyüşleri Yine akşam sefaları Yine cam güzelleri Ve yine a...', ARRAY['Türk Edebiyatı','Şiir','Akif Hüseyin Özmercan']::text[], 8.5, '{"poet":"Akif Hüseyin Özmercan","poet_slug":"akif-huseyin-ozmercan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-kapida-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkını İçmek İstiyor', 'askini-i-cmek-i-stiyor-muhiddin-ates-qadhn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecelerin sabaha hasreti gibi

Bu kul sana yanıp tütüyor

Bir bebeğin süte özlemi gibi

Elinden aşkını içmek istiyor

Hasret bile usandı,bitmek istiyor

Asılan suratım,gülmek istiyor

Ellerim elini tutmak istiyor

Çöle dönen gönlüm,aşkınla yeşermek istiyor

Veda etsin bırak,edenler

Gurbeti hasreti geriye atta gel

Gönlüm özler,ümitle bekler

Dönüşünü bu gözler görmek istiyor', 'Gecelerin sabaha hasreti gibi Bu kul sana yanıp tütüyor Bir bebeğin süte özlemi gibi Elinden aşkını içmek istiyor Hasret bile usandı,bitmek ...', ARRAY['Türk Edebiyatı','Şiir','Muhiddin Ateş']::text[], 8.5, '{"poet":"Muhiddin Ateş","poet_slug":"muhiddin-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askini-icmek-istiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Oldular', 'yalan-oldular-muhiddin-ates-u1vja', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdiğini söyleyen diller

Birbirine tutuşan eller

Buluşulan o yerler

Hepsi birden yalan oldular

Ölümüne sevdalar

Kavrulup yananlar

Kerem''ler Mecnun''lar

Hepsi birden yalan oldular

Kalplere taht kuranlar

O tahtta oturanlar

Kenetlenip tutunanlar

Hepsi birden yalan oldular', 'Sevdiğini söyleyen diller Birbirine tutuşan eller Buluşulan o yerler Hepsi birden yalan oldular Ölümüne sevdalar Kavrulup yananlar Kerem''ler...', ARRAY['Türk Edebiyatı','Şiir','Muhiddin Ateş']::text[], 8.5, '{"poet":"Muhiddin Ateş","poet_slug":"muhiddin-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalan-oldular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atışma', 'atisma-tuncay-akdeniz-nnvjr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gürkani ye cevap

Aşık gürkani de sormuş muamma

Çözemedim imdadıma pir geldi

Dayanamaz olduk yokluğa zama

Kurtaracak baba yiğit er geldi 

 	Enflasyon kızdı üstümüze yürüdü

	Dolar karşısında lira eridi

	İ.M.F den şükür çıktı kredi

	Emir baştan eşe dosta ver geldi

Dolar marklar yuro ile kavgalı

Türk lirası değerini bulmalı

Fikir bir olup el ele vermeli

Dalgalı malgalı birde kur geldi

	Enflasyonun belki kesilir hızı

	İnşallah geriye götürmez bizi

	Kalmadı ki daha orman arazı

	Satılacak gece kondu yer geldi

Oy zamanı vatandaştan sayıldım

Hak ararken sokaklarda dövüldüm

Ara sıra kapılardan kovuldum

Aklıma sandıkta şimdi sor geldi

	Tuncay değil vurguncular utana

	Oğlum asker hizmet eder vatana

	Yazmış baba harçlık göndersen bana

	Emekliğim geçim bana zor geldi

Not.bu şiir 2001 yılında türkiye gazetesinde yayınlandı', 'Gürkani ye cevap Aşık gürkani de sormuş muamma Çözemedim imdadıma pir geldi Dayanamaz olduk yokluğa zama Kurtaracak baba yiğit er geldi   	E...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/atisma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müzik', 'muzik-gokhan-oflazoglu-cf1qw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gerilmiş tutar tellerimi,

bir kuş konar üstüne,

ne söyler açık değil.

Berhava ettiği en derinim,

kopup gelen sessizliğim.

Ordan uzandığım netlik

ve sızıyan benliğim.

Müzik, gel götür beni

uçurumlarına, o var-yok arasına,

kutsal gömü törenine gözyaşlarımın.

19/04/2005', 'Gerilmiş tutar tellerimi, bir kuş konar üstüne, ne söyler açık değil. Berhava ettiği en derinim, kopup gelen sessizliğim. Ordan uzandığım ne...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/muzik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sualsiz Suskun Dudaklar', 'sualsiz-suskun-dudaklar-cetin-hacifettahoglu-5fgjo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günlüğünün O Güne Dairleriyle

Yarınlara Umutla Akan Kaleminin Ucuyla 

Ve Buruşuk Sakladığım Mektuplarındaki

O Zamanın Taze Ekmek Kokusu Misalleriyle

Bir Ben 

Ve Kara Tahtadan Uçup Giden Tebeşir Tozlarıyla

Bulanan Havayı Delip Geçen Bir Nefes Sigara Dumanında

Efkarını Dağıtan Nikotinler Ardından Sarı Lekeler Misalleriyle

Bir Sen

Nerdeyim Nerdesin 

Ben Bir Gül Sırtında Diken

Sen 

Bana Batan Elem

Kanın Döllenir Sırtımda

Biz Düşer Toprağın Bağrına

Sarmaşık Olur Sarar Bedenimi

Boğarcasına Sıkar Durur

Nefesim Kalmadı Koparma! 

Almak İçin Hırçınlaşma

Tomurcuklarımı…

Sorma Toprağa Neden Diye

Cevap Beklemeler,Sualsiz Suskun Dudaklarında Boğulsun…', 'Günlüğünün O Güne Dairleriyle Yarınlara Umutla Akan Kaleminin Ucuyla  Ve Buruşuk Sakladığım Mektuplarındaki O Zamanın Taze Ekmek Kokusu Misa...', ARRAY['Türk Edebiyatı','Şiir','Çetin Hacıfettahoğlu']::text[], 8.5, '{"poet":"Çetin Hacıfettahoğlu","poet_slug":"cetin-hacifettahoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sualsiz-suskun-dudaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldı Yarına', 'kaldi-yarina-yusuf-savas-w9d6q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Felek vurdu acımadan dertle yanan şu bağrıma

Bırak bari ümitlerim kalsın Allah’ın aşkına

Bir yol gösterin bana kaldım burda bir başıma

Bütün güzel hayallerim kaldı yarına

Kaldı yarına, kaldı yarına 

Ümitlerim hayallerim kaldı yarına

Bütün güzel hayallerim kaldı yarına

Gücüm yetmez derdim bitmez kader hep çektirdi bana

Güvendiğim bütün herkes atıp gitti bir başıma

Hep çektirdi şu talihim dünyada yokmuş bir yerim

Kurduğum şu hayallerim kaldı yarına

Kaldı yarına, kaldı yarına 

Ümitlerim hayallerim kaldı yarına

Bütün güzel hayallerim kaldı yarına', 'Felek vurdu acımadan dertle yanan şu bağrıma Bırak bari ümitlerim kalsın Allah’ın aşkına Bir yol gösterin bana kaldım burda bir başıma Bütün...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Savaş']::text[], 8.5, '{"poet":"Yusuf Savaş","poet_slug":"yusuf-savas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kaldi-yarina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahrımı Ren Nehri Çeker', 'kahrimi-ren-nehri-ceker-meral-vurgun-m4otf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'zamansız çıkıp gitmişsin

bilmediğim diyarlarda ayak izlerin 

yolsuz-yordamsız,  yorgun

yitik kentler geçmiş

kayıp düşler biriktirmişsim

umarsız anlarda gökyüzü

iteleyip kara mavisini gecenin

delmişsin gözbebeklerini

bulutlar sevdanı ağlar 

hani yağmurların... 

toprakların çorak

umut yeşermez 

sel sağanak dökerdin bir zaman

her damla bir başka hüzün

yüreğin kıraçları çöl şimdi

yıllar var ki ben

türkülerimi Alp dağlarına söylerim

kahrımı ren nehri çeker

nice ateşler yaktım sensiz

yalım yürek kül 

seni düşürdü 

iki gözüm kör şimdi

gayrı yıldızlarla bölüş sevdanı

senin dağlarına ay döner/ bedir

gün ışır, bahar çimlenir

su başları söğüt dalı

üveyikler eğleşir

ey sevda yürekli yarim

karayağızım

yaralı göğsünü dağlarım bildiğim

ayışığım gözlerin

kirpiklerin gölgem olsun

ben ki

vazgeçersem

bana yaşamak haram olsun...', 'zamansız çıkıp gitmişsin bilmediğim diyarlarda ayak izlerin  yolsuz-yordamsız,  yorgun yitik kentler geçmiş kayıp düşler biriktirmişsim umar...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kahrimi-ren-nehri-ceker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylece Çık da Gel', 'oylece-cik-da-gel-erdem-cetinkaya-8gupg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ÖYLECE ÇIKDA GEL

Sen teli duvağı olmayan bir gelin gibi

Sen yalnızlığa yazılan bir şiir gibi

Ablümlerden atılan bir resim gibi

Öylece çıkda gel

Bir dağ rüzgarı hırpalar seni

Gözlerinde demlendi yitik arzular

Okunmadan atılan bir mektup gibi

Öylece çıkda gel

İçimdeki nehir taşar durmadan

Oysa yağmur mevsimi geçti çoktan

Zamanı geldi

Kar beyazı giy hadi

Bir mezar taşı gibi bekledim seni

Öylece çıkda gel', 'ÖYLECE ÇIKDA GEL Sen teli duvağı olmayan bir gelin gibi Sen yalnızlığa yazılan bir şiir gibi Ablümlerden atılan bir resim gibi Öylece çıkda ...', ARRAY['Türk Edebiyatı','Şiir','Erdem Çetinkaya']::text[], 8.5, '{"poet":"Erdem Çetinkaya","poet_slug":"erdem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/oylece-cik-da-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-nihal-cinar-8vfqn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özgürlük

Geceyi seçtim nedeni bilmeden

Belki karanlıkta ayakta kalmaktı gayem

Cesaretin prılıtıları göründüğü an

Korkunun bulutları doldu heryan

Sisler içinde savaşmayı denedim

Ama rakibim insan değil karabasan

Onu öldürecek silahı bulsam

Ne korkum kalır ne tasam

Bazıları ödüldür dediler yaşam

''mutlu ol,nedir bu gam? ''

Çektiğimi bilseydi inan

Pes ederdi birçok adam gibi adam

Özgürlükle geçiyorsa zaman

Kolaydır tavsiyelerde bulunman

Ama bana verilen cezam

Ya müebbet,ya idam

Su gibi geçiyor zaman

Ne ümit kaldı ne derman

Hakim karar vermekte zorlanan

Oysa kolay,ince bir kalem kırılacak olan', 'Özgürlük Geceyi seçtim nedeni bilmeden Belki karanlıkta ayakta kalmaktı gayem Cesaretin prılıtıları göründüğü an Korkunun bulutları doldu he...', ARRAY['Türk Edebiyatı','Şiir','Nihal Çınar']::text[], 8.5, '{"poet":"Nihal Çınar","poet_slug":"nihal-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ozgurluk-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç', 'agac-nihal-cinar-jr69g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağaç

Ulu bir çınar olmak isterdim

Kökleri toprağı saran

Ulu bir çınar olmak isterdim

Dalları mavi gökyüzünü kucaklayan

Oysa sadece bir yaprak olabildim

Kısa baharı yaşayıp,sıcak yazla kavrulan

Sonbaharın ilk rüzgarı ile savrulan

Düştüğü nehirde bazen çalkantılı,bazen sakin yol alan

Ulu bir çınar olmak isterdim

Uzun yıllara tanık olan

Ulu bir çınar olmak isterdim

Gövdesinde gücü barındıran', 'Ağaç Ulu bir çınar olmak isterdim Kökleri toprağı saran Ulu bir çınar olmak isterdim Dalları mavi gökyüzünü kucaklayan Oysa sadece bir yapra...', ARRAY['Türk Edebiyatı','Şiir','Nihal Çınar']::text[], 8.5, '{"poet":"Nihal Çınar","poet_slug":"nihal-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/agac-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Rengini Söyle', 'bana-rengini-soyle-ahmet-agdere-177fi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kar taneleri arasında

Yitirmiştim rengimi

Beyaz hayallerim vardı

Çocukluğumdan kalma

Başı göğe kaldırınca

Bulutlar almıştı yerini

Karanlıktı ortam

Ve yorgan altında

Korkumda o vardı

Oysa bir güzel üstüne

Ne güzel yakışırdı..

Kiraz iki dudak arasında

Kıpraşınca vücudum

Kırmızılaşan yanaklarım

Sessizce çekip gittiğinde ise

Duvara çarpan parmaklarımdı..

Sığınınca yeryüzüne

Güzel bir çocukla

Aydınlığını paylaştı onunla

Isıttı içini, tekrar ısıttı

Ve acı verdi ona

Denizler, engin ve sırdaş

Onun rengi altında

Aşıklar tutuklu ölesiye

Ve gündüzden sonra gece

Soluğu sürer yine…', 'Kar taneleri arasında Yitirmiştim rengimi Beyaz hayallerim vardı Çocukluğumdan kalma Başı göğe kaldırınca Bulutlar almıştı yerini Karanlıktı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bana-rengini-soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni yazmak...', 'seni-yazmak-ferit-teksoy-jlks6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni yazmak zor

sözcükler eksik kalıyor sanki

kaç sözcükle kavga ettim? 

kaç kelime çöpe attım? 

seni yazarken

biri onu sorsa dedim,

nasıl tarif eder,ne derdim? ..

galiba...

gözlerim bir parlardı

derin bir iç geçirir,

gülümserdim

o yüreğimin sesi

gönlümün efendisi

delibozuğun delisi

o sabır abidesi

kız kulesinin mahzun prensesi,derdim..

mavi derdim rengi

deniz derdim sevdiği

onlara dalar gider

okyanus karası gözleri

hattâ derdim..

bu deniz kızının,

teni güneş yanığı,

elleri kürek nasırı

buram buram deniz,

iyot kokmalı erkeği

ve derdim ki! ..

o kadının hası

Alobar''ın Kudra''sı*

o gençlik aşım

ölümsüzlük ilâcım

dünyaya bin kez gelsem,

yine onu severdim,derdim...

19 Nisan 2005

*Alobar ve Kudra..Parfümün dansı romanının ölümsüzlüğü arayan iki kahramanı', 'seni yazmak zor sözcükler eksik kalıyor sanki kaç sözcükle kavga ettim?  kaç kelime çöpe attım?  seni yazarken biri onu sorsa dedim, nasıl t...', ARRAY['Türk Edebiyatı','Şiir','Ferit Teksoy']::text[], 8.5, '{"poet":"Ferit Teksoy","poet_slug":"ferit-teksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/seni-yazmak-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Işığı', 'gun-isigi-gokhan-oflazoglu-joyk4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiç gün ışığına kulak

verdiniz mi, neler söyler,

şaşırtır. Eski bir masaldan 

dem vurur, güler, güldürür.

Şarkılar mırıldanır, ağaçlara

sarılır, pencerenin camına

vurur.

Yaşamaya geldiniz, tam

bir dikkatle bakın der gibidir.

19/04/2005', 'Hiç gün ışığına kulak verdiniz mi, neler söyler, şaşırtır. Eski bir masaldan  dem vurur, güler, güldürür. Şarkılar mırıldanır, ağaçlara sarı...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Oflazoğlu']::text[], 8.5, '{"poet":"Gökhan Oflazoğlu","poet_slug":"gokhan-oflazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gun-isigi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'a-Farkı kalmadı', 'a-farki-kalmadi-mikdat-bal-c92o6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsanlar şaşırmış, değişmiş yönü! 

Hayatın ölümün farkı kalmadı! 

Bir o onu vurur bir de bu şunu

Mazlumun, zalimin farkı kalmadı! 

Helali haramı araştıran yok

Kitabı okuyup, karıştıran yok

Kavgaya son verip, barıştıran yok

Gaddarın, halim’in farkı kalmadı! 

Torpille rüşvetten şikâyet eder

Bir işi çıkarsa önce o öder

Bu işler böyledir, ne yapalım der

İhlâsın, çalımın farkı kalmadı! 

Vergiyi kaçırır, tespih elinde

Bir hesabı vardır, her amelinde

Faizi çekerken, zikir dilinde

Riyanın filimin, farkı kalmadı! 

Hepsi de bulaşmış, rüşvet, torpile

İşini yürütür, iltimas ile

Hacısı, hocası, müftüsü bile

Ümminin, âlimin farkı kalmadı! 

Mikdadî der aman, yandı çıramız

Bize torpil yoksa, gelmez sıramız

Alınır mutlaka bir kaç liramız

Malının, malımın farkı kalmadı! 

Ozan Mikdadî', 'İnsanlar şaşırmış, değişmiş yönü!  Hayatın ölümün farkı kalmadı!  Bir o onu vurur bir de bu şunu Mazlumun, zalimin farkı kalmadı!  Helali ha...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/a-farki-kalmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arıların Balıyız Biz', 'arilarin-baliyiz-biz-zulfikar-yapar-kaleli-co1jp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya duysun, cihan duysun 

Tanrıdağın gülüyüz biz 

Alem bizi böyle bilsin

Türklük ile doluyuz biz 

İster görün örnek alın 

İster mezellete dalın 

İsterseniz bize gülün 

Hak yolunda deliyiz biz 

Gayemiz müreffeh vatan 

Kalmasın tek sefil yatan 

Türkiye''yi hedef tutan 

Milli devlet yoluyuz biz 

Aklı olan öğüt neyler 

Hakkı bilir, doğru söyler 

Bizden tatlı var mı beyler? 

Arıların balıyız biz 

Her şey vatan için bizde 

Kurtuluş manada özde 

Yürüyoruz kutlu izde 

Turan ilin halıyız biz 

Şehitlerin, ölülerin 

Fatmaların, Alilerin 

İşçilerin, köylülerin 

Eliyiz biz, diliyiz biz 

1974', 'Dünya duysun, cihan duysun  Tanrıdağın gülüyüz biz  Alem bizi böyle bilsin Türklük ile doluyuz biz  İster görün örnek alın  İster mezellete ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/arilarin-baliyiz-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Yağdığında En Sevdiğin Şey', 'yagmur-yagdiginda-en-sevdigin-sey-cumhur-boratav-y7ajm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yaşadığım şey neyse 

senden gelmedi 

böcek bile kendisini nasıl bilirse 

kitaplığımı temizlerken bulduğum 

bir şey 

öyle kaldı yaşamımda 

senden hiç bir şey gelmedi 

keşke bir bebek ağlaması 

biraz kuru yaprağı yırtarak 

akan su damlası 

gökkuşağına oyun oynayan 

bir renk 

biraz 

yatağına kokusunu salgılayan bir beden 

-seninle merdivende karşılaştık 

birimiz iniyordu diğeri çıkmaktaydı 

ne sesini duydun helkopterin 

ne de bacaklarındaki merdiven acısına 

yoğunlaşan ışıkarını 

ne de solucanların 

çürümüşlüğüne yaşamak için 

sığındıklarını 

ucu ayağına uzun 

ayakkabınla, metal merdivenin başında 

durdun 

hayalindeki yataklarımı aklına getirme 

buruşuk çarşaf, seni hiç bir şeyimle saracak 

ucu ayağına uzun, bir salıncak 

seni yıldızlara sunacak 

göğün kuşağı uygun 

telefondaki sesine 

elindeki 

patlayan mantarı 

çevir başının üstünde 

öfkeli gülümsemenle- 

bir saygıya sunmuştum 

kendimi oysa 

yaşadığım şey neyse 

hepsi hepsi birkaç saat 

belki birkaç yaşam, 

hep bir gecesi var 

bu dünyanın gibi bir şey 

yaşadığım şey neyse 

şimdi evine kapanırsın sen 

yağmur yağdığında 

en sevdiğin şey', 'yaşadığım şey neyse  senden gelmedi  böcek bile kendisini nasıl bilirse  kitaplığımı temizlerken bulduğum  bir şey  öyle kaldı yaşamımda  se...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Boratav']::text[], 8.5, '{"poet":"Cumhur Boratav","poet_slug":"cumhur-boratav","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/yagmur-yagdiginda-en-sevdigin-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün-I (Asker Aaaabiii! ! !)', 'o-gun-i-asker-aaaabiii-ugur-deniz-ulkegul-ua0n7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Belki en susuz zamanlarında rastladım ona…Hani insanların yüzlerinde kederli bakışların dolaştığı, mutluluk izlerinin sokaklardan silindiği, en güzel anıların, en tatlı gülücüklerin unutulduğu zamanlarda…

Hiç bir evden alev yükselmiyordu…Ama her bir evin penceresinden keskin bir “is” kokusu geliyordu…Hiç kimse, kimseyi suçlamıyordu…Ama her insan “bir cezanın” mahkumu olmuş izlenimini veriyordu…Kadın kadınlığına, Erkek erkekliğine, çocuk çocukluğuna yasaklıydı sanki…

Trafik işlemiyordu, günün ışıkları şehre çoktan vurmuştu, rüzgar ağaçların dallarına, okşarcasına değip geçiyordu…Bomboştu sokaklar…Akşamcı kahvehaneleri erken kapatmıştı o akşam, sokak serserileri evlerine kapanmıştı, külhanbeyi afili endamlarından eser yoktu…Ya parkta yatan

bank müdavimleri? Onlara ne olmuştu? İşin doğrusu bu ya…Kimsenin bunu düşünecek hali yoktu…

O gün kimse işine gidemedi…O gün hiçbir sevgili buluşamadı…O gün hasta ziyaretleri ertelendi…Ve o gün…Gökyüzünde yarıştırdığımız rengarenk uçurtmalar, evlere kilitlendi…Ben mi? Ben, çocuktum o zamanlar…Ve daha uzun yıllar…Çocuk kalmaya mahkum edildim…O günden sonra bir daha hiç büyüyemedim…

Hatırlıyorum…

Canım sıkılmıştı evin içinde…Babam endişeli gözlerle oturmuş sigara üstüne sigara yakıyor, annem ikide bir korku nöbetlerine kapılıp ağlıyor, Hasan Mutlucan diye tok sesli bir adam - ikide bir- fakat; hep aynı türkülerle siyah beyaz televizyonda boy gösteriyordu...Çocuk olarak yapılması gereken en doğal şeyi yaptım bende…Canım sıkıldı…Ve babamın bana aldığı oyuncak tüfekle balkona çıktım! 

Eğer çocuksanız ve şartlar gereği hareket sahanız daraltılmışsa, her çocuk gibi şartları kendi lehinize çevirmesini “doğal yaradılış” gereği biliyorsunuz demektir…Kendime arkadaş bulmam, tam olarak iki saniye sürdü! Evet evet…Yanlış okumadınız…İki…Saniye…Aradan yirmi beş yıl geçmesine rağmen, bu olağanüstü meziyetimle hala övünürüm…O dönemin yasak koyucularının arasından, kendime hemen bir işbirlikçi bulmuştum…

Evimiz altıncı kattaydı…En üst kat…Karşı apartmanın “çatısında! ” miğferli, eli tüfekli o ağabeyi gördüğüm zaman duyduğum sevinci size asla anlatamam.

Asker aaabiiiiiii! 

? ? ......

Benk! Bennnnk! ....

! ! ! ! ! ......

Naaaapıyon orda? 

Bilmiyom ki cigerim? Bekliyom işte…

Niye bekliyon? 

? ? ? ..........

Bizi sen mi dışarı salmıyon? 

Yok gurban…Ben değil…

Söylesene salsınlar…Canım sıkılıyo içerde…

Yok…Olmaz…Evde oyna sen…

Siz kötü adamlarımı yakalıycaksınız? 

Bilmem ki…Öyle dediydiler…

Onlar şimdi saklanıyo mu? 

He ya…

Yakalayınca öldürceniz mi onları? 

! ! ! ! ! ! ............

Babamı öldürmeyin olur mu? O kötü adam değil…

…………………

O gün bütün çocukların babası iyiydi…Bütün çocukların annesi…Bazı çocuklar bununla gurur duydu sonraki günlerde…Bazı çocuklar ağladılar…Anne ve babalarına “kötü”damgası vurulmuştu…Oysa onlar da simit alırlardı, diğer çocukların anne babalarının yaptıkları gibi…Onlarda ateşlenince ilaç getirirlerdi…Onlarda ağlar üzüldükleri zaman, onlarda neşeli olduklarında gülebilirlerdi…Ama “kötüydüler…”Her gece yatarken gelip, yanaklarından öpen, saçlarını okşayan, hatta masal anlatan bir anne, yada baba…Nasıl

kötü olabilirdi ki? ....

Hakan ne oldu? 

Yok bir şey! 

Neden oynamıyorsun bizimle? 

Siz oynayın…Ben oynamıycam…

Ya hadi gel bak, bir kişi eksik…

Olmaz dedim! 

………………! 

Tamam bende çıktım oyundan…Şimdi eşsiniz…Biz oynamıyoruz…

Ne düşünüyorsun? 

Babamı…

Haber yok mu hala? 

Yok…Görüştürmüyorlar…Annem ağlıyo ikide bir…

Görüşürsün merak etme…Anneni üzme…Evin erkeği sensin şimdi…

Haaaayır! Haaaaayır! Evin erkeği olmak istemiyorum ben…Babamı istiyorum…Her akşam onu bekliyorum kapıda…Naber ufaklık! desin istiyorum…Beni ders çalıştırsın, benimle güreşsin, benle şakalaşsın istiyorum…Anneme sarılsın istiyorum, kitap okusun istiyorum…Neden götürdüler onu, nereye götürdüler, kötü biri değil Deniz! Değil…Ben biliyorum, değil işte! Bana sorsunlaaar…

………! 

Sekiz yaşında bir çocuğu hapse atmak nasıl bir şeydir? Dört duvar arasına koymak…İşkence yapmak…Mektupsuz, görüşsüz, baharsız, topraksız, sokaksız bırakmak…Yok…Böyle bir şey olmadı değil mi? ....Hiç bir çocuk hapse atılmadı bu memlekette…Hiçbir çocuk işkence görmedi…Ve hiçbir çocuk…Darağaçlarında sallanmadı…Peki ya kaç çocuk, Annesiz ve

Babasız büyümenin zindanlarında, yapayalnız, eksik, yarım bırakıldı…Ya sonra kaç çocuk İyi olmak erdemine sahip yetişkin olarak zamanımıza erişti…Kaç çocuk kendisinin olmayan “kötülük” damgasının acısını taşıdı bu günlere…Kaç “nü” tablosunda renk verildi gerçeğin acı ve bir o kadar sancılı “siyah-beyaz” görüntüsüne? 

“Bizimkiler kazandı! ” 

Uzaklardan…Çok uzaklardan gelen bir ses, deniz aşırı bir ülkenin gizli labirentleri arasında böyle fısıldıyordu…Bizden değildiler…Bizim gibi...

Bize yakın...Ama bizden bahsediyordu…

Kimse “kazananlara” bakmadı…Kaybedenleri düşünemedi…

Ya kaybedilen? O neydi? 

Lise çağlarımda son sınıf öğrencisiyim…Tuhaf bir öğrenciydim…Hemen hemen bütün derslerimde not ortalamalarım garip bir istikrarsızlık çizerdi…İlk dönem “beş…”İkinci dönem “On….” Yada ilk dönem” üç”…ikinci dönem

“dokuz”…gibi…Sanırım daha o zamanlar eğitim sisteminde ki saçmalıklara kızıyor olmamdan ötürü, derslerle ve dolayısıyla sistemle dalga geçmek gibi “kötü” bir huya sahiptim…Tek bir ders hariç…

Türk Dili ve Edebiyatı…

Bu derse ayrı bir önem verirdim…Dalga geçilmemesi gereken bir dersti…Son sene bütün sınav notlarım “on” gelmişti…Son sınav öncesine kadar…Sınav öncesi bir an…

Arkadaşlar…Türkiye Cumhuriyeti Bölünmez Bir Bütündür…

Refleks miydi? Aceleci bir davranış şekli mi…Yoksa kafam mı karışıktı bilmiyorum…Hemen söz istedim…

Söyle bakalım Deniz…

Hocam…Türkiye bölünemez…Ama bir bütün değildir…

Önce bir şaşkınlık ifadesi…Sonra kırmızıya dönen deri rengi…Büyüyen göz bebekleri…Buz gibi esen soğuk bir rüzgar? 

Nasıl yani? Sen ne demek istiyorsun? 

Toprak bütünlüğünden bahsetmiyorum hocam…Herhalde onu savunacak bütünlüğümüz mevcut…Ama eğitim bütünlüğü, ekonomik bütünlük, sanayi konusunda ki bütünlük, günümüz şartlarında nedense bir bütünden çok, parçalı bir görüntüye benziyor sanki…Olanakların eşit dağıtılması zorunluluğu, bütünlüğün sağlamlığı açısından zaruri bir koşulluk gerektirmez mi? 

Aç biraz! “Sınıfın kafasını karıştırdın…” Yalnız dikkat et söylediklerine…

! ! ! ! ...............

Konuş, seni dinliyorum…

Doğu Anadoluda ki eğitim sistemi aynı, fakat Batıyla eşit şartlarda mıdır? Ve yine Doğu Anadoluda’ ki Sanayi Yapılanması, Batıyla Paralel orantıda mıdır? Ve yine Doğu Anadoluda Okuyan bir öğrencinin ailesinin geçim standardı Batıda okuyan bir öğrenciyle aynı mıdır? Ve sizce bu eşitsizlik Toprağımızın Bölünmezliği adına Sosyolojik açıdan bir iç tehdit olarak değerlendirilmesi

gereken düşünce tarzını getirmez mi? Bütün olarak ele aldığınız bir nesnenin

bir yanını sağlam tutarken, bir yanını zayıf bırakırsanız bu eyleminiz kırılma noktalarının açığa çıkmasına neden olmaz mı? Ayakları felç olan bir insana

“Bütün” diyebilir miyiz? Ya akciğer kanseri olmuş bir adama? 

Atatürk “Sağlam kafa, sağlam vücutta bulunur” dediğine göre, biz kafamızı ne kadar önemsiyoruz sizce? 

Otur! ....Nerden alıyorsun böyle fikirleri sen? Ben seni çok yanlış tanımışım çok! 

Sustum…………

Son sınavdan “Altı” almak haricinde…Hasarsız atlattık seksenli yılların son döneminde söylenmiş bu sözlerin bedelini ödemek sürecini…Zaten okulda bitti…  :)) 

Efendim bu Eylül sürecini farklı bir bakış açısından değerlendirmek ve yorumlamak istedik…Lakin söz uzun…Kimileri hakkında şanlı kahramanlık hikayeleri yaza-dururken, kimileri “O gün” ün acısını bugünmüş gibi hala içinde hissediyor…Yazı dizisi bende sanırım alışkanlık yapmaya başladı mazur görün…Ama başka türlüde paylaşılamıyor ki bir şeyler…”O Gün” ün

“Bu Gün” e ne katkısı olmuştur, yada olmuş mudur…Etkisi nedir…”Ara dönemde” toplum nereye kaymış hangi yöne, yönlere savrulmuştur…”İkinci seride” bunu irdelemeye çalışacağız…Hatırlattığım için üzgünüm…Ama unutturulmaya çalışılan yüzlerce kavramın arasında bu konuyu “O dönem”de yaşayan bir “çocuk” olarak işlemeye mecbur hissettim kendimi…Amacı acıları ortaya çıkarıp tekrar yaşatmak değil, hali hazırda bu gün yaşanan, ve yaşatılmak istenen “başka acıların” dinmesi için bir nebze olsun çaba sarfetmektir…

Tekrar görüşmek dileğiyle…Saygılar sunarım…', 'Belki en susuz zamanlarında rastladım ona…Hani insanların yüzlerinde kederli bakışların dolaştığı, mutluluk izlerinin sokaklardan silindiği,...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/o-gun-i-asker-aaaabiii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Titriyorum', 'titriyorum-sahin-erturk-2hbh0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün sesim titriyordu

Bugün kalbim titriyor

Duygularım titriyor

Boğazıma düğümlenen

Birşeyler var...

Yutkunuyorum

Konuşamıyorum

Anlatamıyorum

Söyleyemiyorum

Ayazda kalmış gibiyim

Kutupta kalmış gibiyim

Zangır,zangır

Dünden beri,sadece

Titriyorum,titriyorum

(19.04.2005) 

KARABORSA SEVGİ adlı

5.nci şiir kitabımdan', 'Dün sesim titriyordu Bugün kalbim titriyor Duygularım titriyor Boğazıma düğümlenen Birşeyler var... Yutkunuyorum Konuşamıyorum Anlatamıyorum...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/titriyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader Bu İşte', 'kader-bu-i-ste-sahin-erturk-ixfbb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağları aşarak

Kilometreleri yutarak

Bir nefes alımı kadar

Yakınıma,bana gelmiştin

Elimi uzatsam

Ellerinden tutabilecektim

Belkide

Donup kalacaktım

Tek kelime konuşamıyacaktım

Belkide,daha kötüsü

Kalbim duracaktı

Seni görmeye

Dayanamıyacaktım? 

KADER BU İŞTE

Bir adım yakınımda

Göremedim,göremedim seni

(19.04.2005-Yeni)', 'Dağları aşarak Kilometreleri yutarak Bir nefes alımı kadar Yakınıma,bana gelmiştin Elimi uzatsam Ellerinden tutabilecektim Belkide Donup kal...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kader-bu-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizin Gözleri', 'denizin-gozleri-mehmet-salih-seyhan-iajqu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Denizin gözleri ha! 

Bilmezdim olduğunu,

Bir akşam serinliğinde 

Kolay parlayan ışıltılarını bilirdim

Eylül yorgunluğuyla zaman kavramını şiirleştirmeyi birde

Ama ben; 

Denizin gözleri olduğunu bilmezdim

Denizi hiç görmedim

Hiç yaşamadım ki gözleri olduğunu bileyim

Denizin gözleri ha! 

Ne renktir kim bilir

Nasıl ışıldardı dolunaylı gecede

Bilseydim kıskanırdım belki de

Belki de gözleriyle düşlerdim her şeyi

Yada usul usul dudaklarının maviliğini

öperdim gizliden.

Geride kalanlara varamamanın borçluğunu bilirdim

Değersiz bir ömre esir edilmenin utancını birde

Ama ben ne kaybettiklerimi 

Ne kazandıklarımı bilmezdim

Ne de denizin gözleri olduğunu

Denizin gözleri ha! ...', 'Denizin gözleri ha!  Bilmezdim olduğunu, Bir akşam serinliğinde  Kolay parlayan ışıltılarını bilirdim Eylül yorgunluğuyla zaman kavramını şi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Salih Seyhan']::text[], 8.5, '{"poet":"Mehmet Salih Seyhan","poet_slug":"mehmet-salih-seyhan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/denizin-gozleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O! Vahşiye', 'o-vahsiye-seyfettin-yazar-gz28a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Durduk yere doğmadı bilesin, bu vatan,

Kalemle çizilmedi bilesin, bu al bayrak,

Tenine kırmızı çalmak için o cananın,

Gökteki hilalin, yıldızın altına, al kanını serdi ecdadım! ,

Yanar mı? şimdi söyle bu kutsiyet, bu hürriyet,

Bayrak yanmıyor bilesiniz,

Can yanıyor can, canım yanıyor! ...

Her hücresinde bir Mehmet, bir Ahmet, bir Hüseyin …

Her zerresinde bir Emine, bir Hatice, bir Fatma …

Özünde bir yürek, bir can, yıkılmaz bir iman! 

Basit bir kumaş mı? zannetin, ey o hasiyetsiz insan! 

Yanar mı? şimdi söyle bu kutsiyet, bu hürriyet,

Bayrak yanmıyor bilesiniz,

Can yanıyor can, canım yanıyor! ...

Bu uğurda aç kalınıldı, susuz, uykusuz kalınıldı,

Canı candan olan bebeler beşikte öksüz bırakıldı! 

Uyansana insan! sana geride bir vatan,

Bir albayrak, bir hürriyet bırakıldı! ,

Yanar mı? şimdi söyle bu kutsiyet, bu hürriyet,

Bayrak yanmıyor bilesiniz,

Can yanıyor can, canım yanıyor! ...

Anlamsız bir telaş değildi bütün bunlar,

Bu namus! , bu hürriyet! , işte bu sendin,

Nasıl böyle bir kalpsiz, böyle bir vahşi oldun,

İşte sen anlamsız, sen hayasız, sen alçaksın,

Yanar mı? şimdi söyle bu kutsiyet, bu hürriyet,

Bayrak yanmıyor bilesiniz,

Can yanıyor can, canım yanıyor! ...

Ey! yontulmuş insan kılıklı sivri,

Bilesin sivri sinek dahi senden şerefli,

Vatanıma, dinime, al bayrağıma uzanmasın dilin, o kirli elin! ,

Sen insanlık dünyasında bir zerre dahi değilsin! 

Yanar mı? şimdi söyle bu kutsiyet, bu hürriyet,

Bayrak yanmıyor bilesiniz,

Can yanıyor can, canım yanıyor! ...', 'Durduk yere doğmadı bilesin, bu vatan, Kalemle çizilmedi bilesin, bu al bayrak, Tenine kırmızı çalmak için o cananın, Gökteki hilalin, yıldı...', ARRAY['Türk Edebiyatı','Şiir','Seyfettin Yazar']::text[], 8.5, '{"poet":"Seyfettin Yazar","poet_slug":"seyfettin-yazar","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/o-vahsiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇAĞRI...23 Nisan''da FeLeK FaSıLDa buluşalım', 'cagri-23-nisan-da-felek-fasilda-bulusalim-sule-aydemir-xo5j9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '...23 Nisan''da FeLeK FaSıLDa buluşalım... 

