INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MANİLER (66) ''Bağ Yanında Bahçalar''', 'mani-ler-66-bag-yaninda-bahcalar-abdullah-atay-pdejd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'evinin önü duvar 

feryadım kurt kuş duyar 

bir zalimin yüzünden 

gezerim diyar diyar... 

şu dağın ardı kayın 

duyun dostlarım duyun 

bugün yarim geliyor 

cümle aleme yayın... 

gülün bağına girip 

öter bülbülüm garip 

bu dünyadan göç eyler 

güle canını verip... 

yar bağında üzüm var 

üzümünde gözüm var 

haber verin yarime 

ona bir çift sözüm var... 

bağ yanında bahçalar 

yar yanımda saz çalar 

çaldıkça da göğsünde 

çözülüyor kopçalar... 

zalimdir acı gurbet 

sabret yüreğim sabret 

yardan haber gelince 

geçer bu sancı elbet... 

bu ayrılık zor oldu 

yandı yürek kor oldu 

her dertten yıkılmazdım 

sebebim o yar oldu... 

bahçelerde zerdali 

çiçek açmış her dali 

bu benim deli gönlüm 

nazlı yere sevdali... 

dağda ceylan meliyor 

sesi yürek deliyor 

sus artık deli gönlüm 

yar bu gece geliyor...', 'evinin önü duvar  feryadım kurt kuş duyar  bir zalimin yüzünden  gezerim diyar diyar...  şu dağın ardı kayın  duyun dostlarım duyun  bugün y...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/maniler-66-bag-yaninda-bahcalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın İle Yaşarım', 'askin-i-le-yasarim-osman-i-nci-l2k66', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önemsiz gelir bana, kaderin cilveleri,

Taşırım bir ömür boyu, acıları çileleri,

Yeter ki saklama, o tatlı tebessümleri,

Sevdan ile büyürüm, aşkın ile yaşarım…

Engeller yıldırmaz, hedefime koşarım,

Senin için hayatta, her zorluğu aşarım,

Tayfun olur acılara, ırmak gibi taşarım,

Sevdan ile büyürüm, aşkın ile yaşarım…

Yıldızları tutmak, aşkın ile mümkündür,

Bu hayatta var olmak, senin hükmündür,

Seni yanımda görmek, mutlu günümdür,

Sevdan ile büyürüm, aşkın ile yaşarım…

Hayran olmuşum senin, yeşil gözlerine,

Dinlemekle doyamam, o tatlı dillerine,

Tüm evrene ilandır, aynen böyle biline,

Sevdan ile büyürüm, aşkın ile yaşarım…', 'Önemsiz gelir bana, kaderin cilveleri, Taşırım bir ömür boyu, acıları çileleri, Yeter ki saklama, o tatlı tebessümleri, Sevdan ile büyürüm, ...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askin-ile-yasarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Kokulum', 'i-stanbul-kokulum-ayhan-yavuz-acikgoz-pat7o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağla sevdiğim…

Göz pınarların hiç bu kadar çaresiz değildi belki.

Ve sen hiç böylesine kederle bakmadın bu şehre, daha önce.

Üzülme! 

O ay gibi parlak göz bebeklerini titreten, 

    sımsıcak bakışlarını, Kız Kulesine zincirleyen,

    ıslatan, meltem soğuğunda pembeleşen yanaklarını, 

    dudağının kenarından geçip, yer çekimi istikametinde süzülen…

                                                                                        tertemiz damlalar,

    alelade bir yerin zeminine değil,

İstanbul’a düşüyor! 

Her gün, bir gün öncesinden daha güzel,

Ve daha masumdun her ağladığında, gülen güllerden...

Biliyorum, sen de sevdalıydın benim gibi,

                  sen de çay içerdin Küçük Ayasofya’da pazar ikindileri…

                  sen de binerdin Üsküdar vapuruna, seyretmek için martıları, akşam üzeri…

                  sen de erken kalkardın sabahları simit kokusuna…

                  sen de yürürdün Beyoğlu’nda, bir aşağı bir yukarı, öylesine…

Biliyorum, sen de sevdalıydın benim gibi,

				  	İstanbul’a...

Dökülürdü kirpiklerinden Çamlıca Akşamının kızıl güneşi...

Sessizliğinde boğardı, gündüz keşmekeşinin son kalıntılarını...

Böyle bir akşamın ardından, vururken avuçlarıma Eyüp Sultan sabahının ilk ışıkları, 

Üç şey için yakarmıştım Allah’a; 

                                         cennet bahçesi,

                                         İstanbul kokusu,

                                         ve sen...

Şimdi ise senin yokluğuna ağlar, kimsesiz güvercinler...

Alışamadım gidişine inan! 

Yine de kesmedim umudumu, ne cennetten ne İstanbul’dan...

Artık sen yoksun ama...

Beni teselli eden İstanbul var.

                              bir de Haliç yakamozunda asılı kalan gülümsemen...

Ben seninle yaşadım bu şehri, şimdiye kadar,

Ve bir gün bırakırsam, sensiz yaşamayı da,

                                       gene bu şehirde bırakırım.

İstanbul kokulum...

''Ne zaman ki vuslatlar, bu şehirde dem bulur

 O an her mevsim bahar, her yer İstanbul olur''

(istanbul-2005)', 'Ağla sevdiğim… Göz pınarların hiç bu kadar çaresiz değildi belki. Ve sen hiç böylesine kederle bakmadın bu şehre, daha önce. Üzülme!  O ay g...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Yavuz Açıkgöz']::text[], 8.5, '{"poet":"Ayhan Yavuz Açıkgöz","poet_slug":"ayhan-yavuz-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/istanbul-kokulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Manifestocular.', 'manifestocular-orkun-isik-p4qps', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seçilmiş manifestocularla

el ilanları dağıtılmakta,

can koridorlarının tam ortasında.

neyin ne olduğunu bilmeden,

iki can asılmakta bir yürek yontusunda

ve konuşmaktalar içten içe, göz göze.

hiç umarsızca

günümüzü basmaktalar

bizi düne asmaktalar,

varsın asılsın bedenimiz

sallansın darağacında

ya ruhumuz! 

yeşerecektir, 

leyla ile mecnunun can ocağın da...', 'Seçilmiş manifestocularla el ilanları dağıtılmakta, can koridorlarının tam ortasında. neyin ne olduğunu bilmeden, iki can asılmakta bir yüre...', ARRAY['Türk Edebiyatı','Şiir','Orkun Işık']::text[], 8.5, '{"poet":"Orkun Işık","poet_slug":"orkun-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/manifestocular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur Çıkıp Gel Bir Sabah Erkenden', 'ne-olur-cikip-gel-bir-sabah-erkenden-huseyin-erdogan-c736a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'inan ki gittiğinden beri

gözlerim hep ıssız yollarda

aşkım yankılanıyor yüksek dağlarda

sen hiç duymuyor musun beni? 

ne olur çıkıp gel bir sabah erkenden

bu sana bir mesaj değil mi benden? 

lütfen söyle ne zaman döneceksin geri? 

yorgun düştü bedenim sensiz hastayım

bil ki sen gelmedikçe ben hep yastayım

belki ararsın da sesini duyamam diye

numaralarımı hiç değiştirmedim canım

yerini bana söylemek istemesen de

dönüp dönmeyeceğini bilemesen de 

henüz bu konuda karar veremesen de

aşkım hiç olmazsa bana bir telefon et bari

                                    19.04.2005', 'inan ki gittiğinden beri gözlerim hep ıssız yollarda aşkım yankılanıyor yüksek dağlarda sen hiç duymuyor musun beni?  ne olur çıkıp gel bir ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-olur-cikip-gel-bir-sabah-erkenden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir akşam üstüydü çıktım yayladan', 'bir-aksam-ustuydu-ciktim-yayladan-hayri-arikan-serdaroglu-ma71h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir akşam üstüydü çıktım yayladan

Gönlümde karışık duygular vardı

Düşündüm sezsizce hayal hülyadan

Sanki aşktan yana kaygılar vardı

Oradan inmişim soğuk mohara

Dalmışım dünyadan geçip bir ara

Alaca karanlık bakıp dağlara

Yüreğim çoş etti türküler vardı

Bir dostum seslendi gel küplüceye 

Baktım ki karışmış gündüz geceye

Ün verip çağırdım Ali hocaya

Aşk ile rahmana övgüler vardı

Mohar gözü buladandan bellidir

Binbir çiçek kovanları ballıdır

Boyları selvidir yanak allıdır 

Her güzele nasib sevgiler vardır

Yürüyüb dolandım indim yazlara

Erikcileride sordum kızlara

Hayran oldum edalara nazlara

Güzel dudağında türküler vardır

Buradanda girenese varayım

Evlerinin tam önünde durayım

Serdaroğlu derki kurban olayım

Atla gel atımda terkiler vardır

 Hayri Arıkan (Serdaroğlu)', 'Bir akşam üstüydü çıktım yayladan Gönlümde karışık duygular vardı Düşündüm sezsizce hayal hülyadan Sanki aşktan yana kaygılar vardı Oradan i...', ARRAY['Türk Edebiyatı','Şiir','Hayri Arıkan (Serdaroğlu)']::text[], 8.5, '{"poet":"Hayri Arıkan (Serdaroğlu)","poet_slug":"hayri-arikan-serdaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-aksam-ustuydu-ciktim-yayladan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceleri Gelirdin', 'geceleri-gelirdin-ayse-yucel-kfk4g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerinde okyanus kokusuyla

Uzun, mavi gecelere gelirdin

Ertesi bahar bir mevsim olurdu zaman

Saatleri durdururdun, anlar kalırdı...

Tenimiz sevişme kokarken

İçinde ''biz'' geçen cümleler kurardık

Biz dünya olurduk, dünya biz olurdu

Dünya kadar biz, biz kadar dünyaya 

Sığamazdık...

Ve güneş doğarken ağlardı gece

Vakit ayrılığı çalardı

Yapraklarımı dökerdi sarı bir hazan

O zaman gitmenin sancısı konardı yüreğime

Ağzımda dilinin nikotin tadı

Avuçlarıma okyanus kokusu bırakıp

Giderdin gri, puslu sabahlara...', 'Ellerinde okyanus kokusuyla Uzun, mavi gecelere gelirdin Ertesi bahar bir mevsim olurdu zaman Saatleri durdururdun, anlar kalırdı... Tenimiz...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yücel']::text[], 8.5, '{"poet":"Ayşe Yücel","poet_slug":"ayse-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/geceleri-gelirdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizden Olmayan Onlar', 'bizden-olmayan-onlar-orhan-tuncay-9nnqu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayrıntının ayrıntısıydı

Kafasındaki kırıntılar

Yerlere saçıldılar ifade ederken

Un ufak olup parçalandılar.

Toplamaya çalışırken zihnimde

Çıkan fırtınalarla sarsıldılar

Koşuşup durdular belleğimde

Dört bir yana dağıldılar.

Öylece bakakaldık düşlerimize

Onlar kelimelere tutunamadılar

Toz olup  savruldular göklere

Düşlerimiz bizi kavramadılar.', 'Ayrıntının ayrıntısıydı Kafasındaki kırıntılar Yerlere saçıldılar ifade ederken Un ufak olup parçalandılar. Toplamaya çalışırken zihnimde Çı...', ARRAY['Türk Edebiyatı','Şiir','Orhan Tuncay']::text[], 8.5, '{"poet":"Orhan Tuncay","poet_slug":"orhan-tuncay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bizden-olmayan-onlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyordun', 'gidiyordun-ayse-yucel-539qv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çiğ düşmüştü o sabah yüreğime

Gözlerim yağmurdu

Sen fırtınaydın o sabah

Ben senin esintilerini severdim oysa

Sen fırtınaydın o sabah...

Bir filmin kayıp sahnelerini oynar gibiydik

Lirik dizeler sıkıştırıyorduk satır aralarına

Tutuk, yabancı ve acılıydık

Üstelik birlikteyken bile yalnızdık

Birbirimizin canını yakacak

içine işleyecek cümleler kurmak istiyor

Susuyorduk

Gözleri bağlı körebeler gibi

Sağa sola çarparak kendimizi arıyorduk

Biliyordum, gidecektin

Vakit ayrılığı vuruyordu

Sen fırtınaydın

Sen gidiyordun...', 'Çiğ düşmüştü o sabah yüreğime Gözlerim yağmurdu Sen fırtınaydın o sabah Ben senin esintilerini severdim oysa Sen fırtınaydın o sabah... Bir ...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yücel']::text[], 8.5, '{"poet":"Ayşe Yücel","poet_slug":"ayse-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gidiyordun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ne Sevda', 'bu-ne-sevda-mehmet-ali-cibikli-arq6s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sensiz geçen günlerim,

Umarım bir gün biter.

Çektiğimiz acılar,

İkimize de yeter.

Bu ne sevda,bu ne aşk? 

Hep üzüntü dert dolu.

Mutluluğu bulmanın

Yok mu başka bir yolu? 

Mutluluk denilen şey,

Neden küskün hep bize? 

Sevip de mutlu olmak

Haram mı ikimize? 

Günlerim gece gibi

Her dakika karanlık.

Bir an olsun bırakmaz

Peşimizi yalnızlık.

Karanlıklar dağılsın

Aydınlansın ruhumuz.

Gönüller bir olunca

Mutluluğu buluruz.', 'Sensiz geçen günlerim, Umarım bir gün biter. Çektiğimiz acılar, İkimize de yeter. Bu ne sevda,bu ne aşk?  Hep üzüntü dert dolu. Mutluluğu bu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-ne-sevda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-mehmet-ali-cibikli-yulkl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben senden kaçıyorum uzaklara,

Sakın gelme ardımdan,sevme beni.

Dönmek istemiyorum anılara,

Unutmaktan başka çare yok seni.

Bırak böyle yarım kalsın aşkımız,

Aşkımıza böylesi daha iyi.

Dostça olsun daima bakışımız,

Sanma sakın seni sevmediğimi.

Sevsem de fayda yok,yolumuz ayrı,

Sen kendi yoluna,ben de  yoluma.

Kalmadı artık sevgimizin hayrı,

Geldik işte yolumuzun sonuna.

En iyisi ayrılık ikimize,

Aşkımızın  şimdi son durağında.

Mutluluklar dileyelim biz bize,

Senden güle güle,benden elveda.', 'Ben senden kaçıyorum uzaklara, Sakın gelme ardımdan,sevme beni. Dönmek istemiyorum anılara, Unutmaktan başka çare yok seni. Bırak böyle yarı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/elveda-133-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharın Kızına', 'baharin-kizina-ayse-yucel-1d4g5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bırak uçsun yüreğin

Bir kelebeği kondur parmağının ucuna

Yalnızlığını sev

Ve inadına kaybol kalabalıklarda

Sen baharın çocuğusun

Yağmurların yağsın

Nergisler açsın yanağında

Gün senin, bu an senin olsun

Her gün senin, her an senin olsun

Bırak şimdi! 

Öyle bir savur ki küllerini

Bir güneş doğsun gecede

Sen bin güneş gör mavide

Bırak herkesi! 

Bırak herşeyi! 

Gel şimdi

Rüyanı, kavganı

Bir de nem kokan toprağını al yanına

Gel baharın kızı

Sen benim ol

Yüreğim sana konsun.', 'Bırak uçsun yüreğin Bir kelebeği kondur parmağının ucuna Yalnızlığını sev Ve inadına kaybol kalabalıklarda Sen baharın çocuğusun Yağmurların...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yücel']::text[], 8.5, '{"poet":"Ayşe Yücel","poet_slug":"ayse-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/baharin-kizina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme', 'gelme-ayse-yucel-m0j45', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelme bir daha

Giderken aldığım sevincimi

Ve papatya mevsimimi 

Geri vermek için ''sen''imi

Gel-me bir daha! 

Ellerimi tutmaya

Kipriğimi öpmeye

Tenimin tenine karıştığı gecelere

Ve yüzün varsa ''yeniden'' demeye

Gelme bir daha!', 'Gelme bir daha Giderken aldığım sevincimi Ve papatya mevsimimi  Geri vermek için ''sen''imi Gel-me bir daha!  Ellerimi tutmaya Kipriğimi öpmey...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yücel']::text[], 8.5, '{"poet":"Ayşe Yücel","poet_slug":"ayse-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gelme-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüyordum Bir Zamanlar', 'guluyordum-bir-zamanlar-mehmet-sait-simdi-dirxb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nerden çıktın sen karşıma,

Sen karıştın gözyaşıma,

Dert olacak,bu başıma,

Biliyordum bir zamanlar.

Ne dert vardı,ne düşünce,

Yaşıyordum ben gönlümce,

Ne yazık ki senden önce,

Gülüyordum bir zamanlar.

Renk kalmadı solan tende,

Kabahat seni sevende,

Gerçek aşkı,nasıl sende,

Buluyordum bir zamanlar.

O umutlar,o hayaller,

Boşa gitti tüm emekler,

İkimize güzel günler,

Diliyordum bir zamanlar.

Herşey senin ''yanın'' için,

Arzuların ''canın'' için,

Uykuları ''senin'' için,

Bölüyordum bir zamanlar.', 'Nerden çıktın sen karşıma, Sen karıştın gözyaşıma, Dert olacak,bu başıma, Biliyordum bir zamanlar. Ne dert vardı,ne düşünce, Yaşıyordum ben ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Şimdi']::text[], 8.5, '{"poet":"Mehmet Sait Şimdi","poet_slug":"mehmet-sait-simdi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/guluyordum-bir-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bundandı', 'bundandi-ayse-yucel-8rwei', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tertemiz aşkım nasıl özledim sevgini

Nasıl üşüyorum bilsen zor geçitlerde

Dipsiz kuyularda nasıl yalnızım şimdi

Nasıl bileceksin, bilemezsin...

''Unut, yeni bir hayat kur'' dedin

Sen bilmezsin ben nasıl unuturum

Bana gelen en temiz şey senken

Ve en gelmemesi gereken

Nasıl unuturum dünyaya isyanımızı

O zavallı çırpınışlardan ibaret isyanımızı

Çırpınmana kıyamadım

Bir de ben yoruldum hırpalanmaktan

Bundandı herşeyimi

Yani sevgimi, yani varlığımı, yani çırpınışlarımı

Toplayıp yola çıkmam bundandı

Gözyaşına el sallayıp gitmem

Ve gitmem bundandı...', 'Tertemiz aşkım nasıl özledim sevgini Nasıl üşüyorum bilsen zor geçitlerde Dipsiz kuyularda nasıl yalnızım şimdi Nasıl bileceksin, bilemezsin...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yücel']::text[], 8.5, '{"poet":"Ayşe Yücel","poet_slug":"ayse-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bundandi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gündür Bugün', 'o-gundur-bugun-burak-killioglu-m5egj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Issız bir patikasın, yemyeşil bir orman içinde,

O meçhul patikanın izindeki izciydim.

Kutup yıldızı gibi parla, bu gece gökyüzünde,

Uzak denizlerdeki kaybolmuş denizciydim.

Sen değildin benim derdim, ruhumdaki keşmekeş,

Saplamalı hançeri nefs suretli şeytana..

Huzur bulamaz yoksa bu yalandan çilekeş,

Hatırlarsan ismimi, kus öfkeni rüzgara.

İşte o gündür bugün, ismimi de unuttun,

Anlamını yitirmiş kupkuru bir sözcüğüm.

Karanlık bir dehlizde aydınlık bir umuttun,

Gönül kalesindeki kör olmuş bir gözcüyüm.', 'Issız bir patikasın, yemyeşil bir orman içinde, O meçhul patikanın izindeki izciydim. Kutup yıldızı gibi parla, bu gece gökyüzünde, Uzak den...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-gundur-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uymaz/Uydurduğun', 'uymaz-uydurdugun-cenk-aksal-dulz6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'karanlıklar...

senin mahkumluğun..

aydınlıklar,

benim yaşantım...

acılar:

senin uzantın,

mutluluk:

yaşam tarzım..

arkadaşlık:

yeni aşk kapın,

dostlar:

benim can yoldaşım,,

siyah:

senin tanımın/hayatın

beyaz:

ifadesi, hayata bakışımın..

aşığım:

diyorsun sevdim sanıyorsun,

sen:

arkadaşım bile olamazsın..

bırak..

temiz kalsın hayatım..

   ''onursuz olmasın aşk''', 'karanlıklar... senin mahkumluğun.. aydınlıklar, benim yaşantım... acılar: senin uzantın, mutluluk: yaşam tarzım.. arkadaşlık: yeni aşk kapın...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/uymaz-uydurdugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz''miyiz', 'biz-miyiz-mehmet-sait-simdi-s9vj3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zalimler akıllı,sevenler mazlum,

Dünyada son kalan,deli biz''miyiz,

Kavuşsak olmuyor,ayrılsak zulüm,

Tanrı''nın en kötü kulu biz''miyiz.

Taş  taşa kavuşur bina örerler,

Bilsen kuşlar bile yuva kurarlar,

Bizim sevgimize hançer vururlar,

Tanrı''nın en kötü kulu biz''miyiz.

El alem sevilip sevdiği anda,

Sevdiğine kıymet verdiği anda,

Hicranı yaşadık en mutlu günde,

Tanrı''nın en kötü kulu biz''miyiz.', 'Zalimler akıllı,sevenler mazlum, Dünyada son kalan,deli biz''miyiz, Kavuşsak olmuyor,ayrılsak zulüm, Tanrı''nın en kötü kulu biz''miyiz. Taş  t...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Şimdi']::text[], 8.5, '{"poet":"Mehmet Sait Şimdi","poet_slug":"mehmet-sait-simdi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biz-miyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşkın Var,Bin Kederin.', 'bir-askin-var-bin-kederin-mehmet-sait-simdi-9c8q2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senden bana miras kalan,

Bir aşkın var,bin kederin,

Senden doğan,senden gelen,

Bir aşkın var,bin kederin.

Damla damla gözlerimde,

Bomboş kalan ellerimde,

Yanıp duran yüreğimde,

Bir aşkın var,bin kederin.

Hayallerde,sezgilerde,

Şiirlerde,ezgilerde,

Yüzümdeki çizgilerde,

Bir aşkın var,bin kederin.

Ne gecem var.ne gündüzüm,

Dertle başlar,şarkım sözüm,

Yıllar yılı ben öksüzüm,

Bir aşkın var,bin kederin.', 'Senden bana miras kalan, Bir aşkın var,bin kederin, Senden doğan,senden gelen, Bir aşkın var,bin kederin. Damla damla gözlerimde, Bomboş kal...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Şimdi']::text[], 8.5, '{"poet":"Mehmet Sait Şimdi","poet_slug":"mehmet-sait-simdi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-askin-var-bin-kederin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hikmet Baba', 'hikmet-baba-alaattin-ceylan-5bqpt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hikmet baba Hikmet baba

Bu ne hiddet himmet baba

Yıllardır bu can feda sana 

Böyle gitmez Hikmet baba

Hikmet baba himmet baba

Sen konuştun ben hep sustum

Yedin içtin hep kan kustun

Sen vurdukça ben hep pustum

Böyle gitmez Hikmet baba

Hikmet baba himmet baba

Kemer sıktım inandım sana

Katık; bir bardak çay bir sigara

Sabrım taştı taşacak ha

Böyle gitmez Hikmet baba

Hikmet baba himmet baba

Bu düşmanlık neden bana

Kafirlik mi var soyunda

Bıçak kemiğe dayandı ha

Böyle gitmez Hikmet baba

Hikmet baba himmet baba

Kutsal saydım memleketi

Hem vatanı hem milleti

Düşünmedim ihaneti

Böyle gitmez Hikmet baba

Hikmet baba himmet baba', 'Hikmet baba Hikmet baba Bu ne hiddet himmet baba Yıllardır bu can feda sana  Böyle gitmez Hikmet baba Hikmet baba himmet baba Sen konuştun b...', ARRAY['Türk Edebiyatı','Şiir','Alaattin Ceylan']::text[], 8.5, '{"poet":"Alaattin Ceylan","poet_slug":"alaattin-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hikmet-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onun Adı Hüzündü', 'onun-adi-huzundu-cemal-gokmen-sp452', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş batıp,kuşlar uçar giderken yuvalarına 

o da yüreği alabildiğine yorgun 

iç içe karışmış duygularıyla 

yürümeğe başladı sessiz bir gecenin kapısını aralamak üzere evine 

iç çekişlerinin bastırılamaz isyanlarını 

derinliğine duyarak,kulaklarında ki uğultularla 

bir sağa bir sola bakarak karanlık sokaklara daldı 

yılların acımasızlığını düşündü 

sevgi adına bulduklarını 

onda kalan çaresizlikleri 

her daim bekçiliğini yaptığı umutlarını 

sonra yağan yağmur gözyaşlarını yıkarken 

dudaklarını ısırdı haince 

hatırlamak isterken onun adını 

kuytu sokaklardan yürüyüp geldi evine 

kapının anahtarını çevirirken 

durdu düşündü bir an,sonra gülümsedi 

alıştığı ruh,aynada gördüğü yüzü 

hatırlamıştı tekrar yıllar sonra 

onun adı hüzündü', 'Güneş batıp,kuşlar uçar giderken yuvalarına  o da yüreği alabildiğine yorgun  iç içe karışmış duygularıyla  yürümeğe başladı sessiz bir gece...', ARRAY['Türk Edebiyatı','Şiir','Cemal Gökmen']::text[], 8.5, '{"poet":"Cemal Gökmen","poet_slug":"cemal-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/onun-adi-huzundu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıra', 'hatira-mehmet-ali-cibikli-k3elw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzun yıllar öncesi,

Sevmiştim deli gibi.

Karşılık görmeyince,

Terketmiştim birini.

Fakat geçen gün birden,

O''nu gördüm aniden.

Aşka susayan gönlüm,

Alevlendi yeniden.

Ne O beni unutmuş,

Ne de ben unutmuşum.

Beklenilen umutmuş,

Beklerken yorulmuşum.

Beklemekte fayda yok,

Beklemek koca yalan.

Şimdi O''ndan  hatıra,

Bir çift göz bana kalan.', 'Uzun yıllar öncesi, Sevmiştim deli gibi. Karşılık görmeyince, Terketmiştim birini. Fakat geçen gün birden, O''nu gördüm aniden. Aşka susayan ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ali Çıbıklı']::text[], 8.5, '{"poet":"Mehmet Ali Çıbıklı","poet_slug":"mehmet-ali-cibikli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hatira-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-alaattin-ceylan-rjpai', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceden,kıştan,kardan

Fırtınadan,borandan sonra

Doğan güneşim

Hiç bir şey mutlu etmedi beni 

Senin gelişin kadar

Arzum beklediğim tek isteğim

Düşlerimin hayallerimin güzel kızı

Mavi dünyamın parlak yıldızı

Canımın canı ciğer parem

Derdin derdim sevincin sevincim

Ayça kızım nur bebeğim.

Sende toplanmış Allah''ın bütün güzelliği

Melekler seni kıskanmış

Bulutlar senin için ağlamış

Uğur böcekleri uçuşmuş,

Gelincikler açmış,senin için

Tabiat türkü yakmış

Masallar seni anlatmış

Rüzgarlar uçurtmalar uçurmuş 

Senin için bebeğim...', 'Geceden,kıştan,kardan Fırtınadan,borandan sonra Doğan güneşim Hiç bir şey mutlu etmedi beni  Senin gelişin kadar Arzum beklediğim tek isteği...', ARRAY['Türk Edebiyatı','Şiir','Alaattin Ceylan']::text[], 8.5, '{"poet":"Alaattin Ceylan","poet_slug":"alaattin-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bebegim-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim ll', 'bebegim-ll-alaattin-ceylan-ju38c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim bir parçam imtihanım olmasan

Yudum yudum sevgi olup yüreğime doğmasan

Her gece uykularımı bölüp beni yormasan

Böyle sever miydim kara gözlüm

Böyle sever miydim nur bebeğim

İlk ağlayışını, ilk göz açışını,

İlk gülüşünü ilk oturuşunu

İlk emekleyip yürüyüşünü görmesem

Böyle sever miydim kara gözlüm

Böyle severmiydim nur bebeğim.

Böyle sever miydim can bebeğim

Hayallerim olmasan

Karanlık dünyama güneş olup doğmasan

Aslınur,sevdiğimde olmasan

Böyle sever miydim kara gözlüm

Böyle sever miydim nur bebeğim

Böyle severmiydim can bebeğim

Sende sevdiğimi görmesem

Ayçanuruma kardeş gelmesen

Yokluğunuzun hasretini çekmesem

Böyle sever miydim kara gözlüm

Böyle sever miydim can bebeğim.', 'Benim bir parçam imtihanım olmasan Yudum yudum sevgi olup yüreğime doğmasan Her gece uykularımı bölüp beni yormasan Böyle sever miydim kara ...', ARRAY['Türk Edebiyatı','Şiir','Alaattin Ceylan']::text[], 8.5, '{"poet":"Alaattin Ceylan","poet_slug":"alaattin-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bebegim-ll-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Herşeyimdin Benim', 'sen-herseyimdin-benim-can-bilge-x28ab', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen gözlerimdin benim

Hiç tükenmeyen bir pınar misali

Süzülürken damla damla sular

Bazan ılık, yüreğinin sıcaklığında

Bazan buz kesmiş, kartal bakışlarında

Bakarken bazan, yıldız parlaklığında

Sen gözlerimdin benim

Sen sözlerimdin benim

Dilimden dökülen bir çağlayan misali

Ve yatağına sığmayan bir nehir

Bazan bir çığlık sessizliğimde

Bazan bir sitem haykırışlarımda

Dökülürken dilimden, uçurumdan dökülür gibi

Sen sözlerimdin benim

Sen ellerimdin benim

Rüzgarlarınla doldurduğun bir yelken misali

Bir saşa çekersin beni bir sola

Bazan savurursun açık denizlere

Bazan vurursun acımadan kıyılarına

Başıboş, dümensiz, kapılacakken girdaplara

Sen ellerimdin benim

Sen yüreğimdin benim

Ritimsiz çalan bir saat misali

Çalışıyorsun tik tak tak tak tik

Bazan ileri gidiyorsun koşar gibi

Bazan geri kalıyorsun sanki yorgun

Ha durdu ha duracak hala sana vurgun

Sen yüreğimdin benim

Sen herşeyimdin benim

Düşlerim, ümitlerim, geleceğim

Ellerimdin, gözlerimdin ve yüreğim

Bazan kapılsamda umutsuzluklara

Bazan kızsamda yüreğim alev alev

Sen ne görürsün beni, ne duyarsın

Yine de sen herşeyimdin benim

Ve yine de herşeyimsin.', 'Sen gözlerimdin benim Hiç tükenmeyen bir pınar misali Süzülürken damla damla sular Bazan ılık, yüreğinin sıcaklığında Bazan buz kesmiş, kart...', ARRAY['Türk Edebiyatı','Şiir','Can Bilge']::text[], 8.5, '{"poet":"Can Bilge","poet_slug":"can-bilge","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sen-herseyimdin-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatımın Son Şansısın', 'hayatimin-son-sansisin-i-smail-baharsen-swv1s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni bekler gibi düştüm yollara 

bilmem bende düştümmü aklına

hasatında kaldı yalın ömrüm

bahar düşmedi daha bağına

sen gelirsen açacak bütün çiçekler

sen gelirsen yolların yeşerecek

umutlarım tazelenip göğsümde titreyecek

sen hayatımın son şansısın 

karşısına ilk defa çıkan yolsuzluğunda

gülüşlerine takılan 

mavi bir pencere gökyüzüne bakan

hayatımda safir güzeli bir seni gördüm

bir seni özledim böyle kar yangını 

bir seni hayatıma teselli gördüm 

barış şarkım oldun kaderimle bana

seni kaybetmekmi asla

asla...', 'seni bekler gibi düştüm yollara  bilmem bende düştümmü aklına hasatında kaldı yalın ömrüm bahar düşmedi daha bağına sen gelirsen açacak bütü...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayatimin-son-sansisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak Aşk', 'islak-ask-musa-yasaroglu-utc1x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine yağmur yağıyor 

Usul usul ama heyecanlı

Ve karanlığında gecenin

Uslanmaz cesareti

Adeta sevdalı bir genç gibi

Yaralı ve suskun 

Aşk acısı ile yorgun

Ama yine dostu yalnızların

Hem de en vazgeçilmezinden

Bir nimet kadar gerekli

Bir nehir kadar asi

Ve de bir anne kadar şefkatli', 'Yine yağmur yağıyor  Usul usul ama heyecanlı Ve karanlığında gecenin Uslanmaz cesareti Adeta sevdalı bir genç gibi Yaralı ve suskun  Aşk acı...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/islak-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünme!', 'dusunme-sule-aydemir-bnkw2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'akıllar var

düşündüğünde 

kalır karanlık

düşünceler 

en evvel 

hem cumbalı 

hem aydınlık

ağlarken gülene 

________hüzün ellerimden

*kalemi gönülden mürekkepli kadının günlüğünden 

14.04.2005 İst.', 'akıllar var düşündüğünde  kalır karanlık düşünceler  en evvel  hem cumbalı  hem aydınlık ağlarken gülene  ________hüzün ellerimden *kalemi g...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dusunme-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Zamanlar', 'sensiz-zamanlar-i-smet-barlioglu-iwstw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni bana bırakma; mahvolurum,

Şöyle bir eli-ayağı düzgün düşünemem,

Bakarım; baktığımı göremem,

Dinlerim; dinlediğimi duyamam,

Söylerim; ne söylediğimi bilemem,

Geri gelmek için birkaç adım öteye gitmem gerekse; 

Dönemem.

İçim-dışım seninle dolu anam-babam,

Neyi görsem, ona takılırım anılarınla,

Neyi duysam; ona takılırım,

Ne söyleseler; seni söylemiş olurlar kulaklarıma,

Ne gösterseler; seni göstermiş olurlar,

Yürüsem; sana doğru yürürüm, kollarım açık,

Seni beklerim, dursam; ellerim koynumda,

Senden öte tek şey yok ki; 

Aklımda.

Uykuları gurbetlere gönderdim,

Yiyip içmeleri sürgünlere,

İzinler verdim bolganime mutluluklara

Gidip de dönmesinler diye.

Bir senin hayalinle kaldım baş başa

Ve yanında çile tepeleri, ızdırap çiçekleri,

Kederler, sızılar, yaslar, karabasanlar; 

Sensiz geçiyor mu sanıyorsun

Zamanlar? 

(GÜVERCİN isimli Serbest Şiirler ''inden > 83-84/100)', 'Beni bana bırakma; mahvolurum, Şöyle bir eli-ayağı düzgün düşünemem, Bakarım; baktığımı göremem, Dinlerim; dinlediğimi duyamam, Söylerim; ne...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sensiz-zamanlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulamazsın', 'bulamazsin-i-smet-barlioglu-vcvhp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Getirir mi sanıyorsun pişmanlıklar

O günleri geriye? 

Dünyada her şey esip geçen bir rüzgar,

Avuçlasan; avuçlayamazsın, tutsan; tutamazsın,

Şarkılarımız ak köpüklü suların sırtında akıp gitti,

Bulamazsın.

Bulamazsın çam oluğundan billur sular akan pınarı,

Saçımızı okşayan o eski rüzgarları,

Ayaklarımız altındaki çayırları, çimenleri,

Ulu ormanlardan gelen sarıçam kokularını,

Denizle oynaşan güneşleri,

Altından geçmeye yeltendiğimiz gökkuşaklarını,

Bulamazsın yüzlerimizi öpen mehtapları.

Aradığın hiçbir şey eski yerinde değil,

Kimi silindi, kimi eridi, kimi çürüdü, kimi soldu,

Bir büyük ortak hazinemiz vardı,

Kayboldu.

Bulamayacakların o kadarla kalsa; gam değil,

Ben de bıraktığın ben değilim; 

Beyaza kesti saçlarım biraz daha,

Biraz daha derinleşti yüzümdeki çizgiler,

Yüreğim biraz daha kavruk, biraz daha yaralı,

Kemiklerim daha bir sızılar içinde,

Omuzlarım biraz daha çökmüş çilemin ağırlığından,

Karasevdam biraz daha ağırlaşmış, biraz daha büyümüş,

Bırakanın bıraktığını ayni bulduğu

Nerde görülmüş? 

(GÜVERCİN isimli Serbest Şiirler ''inden > 85-86/100)', 'Getirir mi sanıyorsun pişmanlıklar O günleri geriye?  Dünyada her şey esip geçen bir rüzgar, Avuçlasan; avuçlayamazsın, tutsan; tutamazsın, ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bulamazsin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyi Unuttuğumuz İçin', 'sevmeyi-unuttugumuz-i-cin-i-smet-barlioglu-7h20r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Unuttun mu anam-babam, unuttun mu? 

Nice bir ayrıcalıklıydık bu ölümlü dünyada,

Biz ikimiz, öz çocuğuyduk Tanrı ‘nın,

Tanrı ‘mızı baba edinip sığınmıştık kucağına,

Melekleriydik,

Kullarıydık,

Çocuklarıydık,

Şımarıklarıydık sevecen Tanrı ‘mızın.

Gökleri, yerleri, denizleri bize vermişti,

Söken her şafakla bir ayrı lütuf göndermişti,

Güneş emrimizdeydi, ay emrimizdeydi,

Serperdik yıldızları istediğimiz gibi gökyüzüne,

Rüzgarlara şarkılar yüklerdik,

Türküler söylerdik yağmurlara,

Koskoca bir dünya

Ve biz; ikimiz,

Nasıl da bitmeyecek sanmıştık

Türkümüz.

Sevmeyi unuttuğumuz için

her şeyi çekip aldı Tanrı,

Ne göklerimiz, ne denizlerimiz, ne de yerimiz kaldı.

O yüzden tüm yağmurlarımız birer tufan,

O yüzden tüm rüzgarlarımız birer hışım,

O yüzden bildiğini okumakta güneş ve ay,

Bu yıldızlar ı yüzden darmadağın,

O yüzden tadı-lezzeti kalmadı gurubun,

Şafağın.

Sevilmeyi bilemedik en bilmemiz gereken günlerde,

Tanrı sevdanın en güzelini lütfetti

Hayrını göremedik,

Şımardık, kötüleştik, asileştik, sertleştik,

Yuva kurmaya kalkıştık yıldızlar arasına,

Gölgeler düşüre düşüre aşkımızın

Şurasına,

Burasına.

(GÜVERCİN isimli Serbest Şiirler ''inden > 87-88/100)', 'Unuttun mu anam-babam, unuttun mu?  Nice bir ayrıcalıklıydık bu ölümlü dünyada, Biz ikimiz, öz çocuğuyduk Tanrı ‘nın, Tanrı ‘mızı baba edini...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sevmeyi-unuttugumuz-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanı Yıktılar!', 'i-nsani-yiktilar-sule-aydemir-o63dw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ilkin damı yıktılar

orada uyurdum 

üç beş vakit

sonra duvarları

ayıp saklardım oysa

insanı yıktılar dahasında

___________çığlıklarım yalnızlık

*kalemi gönülden mürekkepli kadının günlüğünden 

14.04.2005 İst.

Şule Döğer Aydemir', 'ilkin damı yıktılar orada uyurdum  üç beş vakit sonra duvarları ayıp saklardım oysa insanı yıktılar dahasında ___________çığlıklarım yalnızl...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/insani-yiktilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belalım', 'belalim-zumrut-demirtas-k76hy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'B ir türlü atamıyorum seni kafamdan,

E n umutsuz anlarımda takılıyorsun,

L av olup akıyor benliğime sözlerin,

A niden gelip kalbime sokuluyorsun,

L ila renkli düşlerimde sen bana,

 I lımlı davranıp birden deliriyorsun,

M ühim değil BELALIM, bana yakışıyorsun....

Aşkın Belalılarına....', 'B ir türlü atamıyorum seni kafamdan, E n umutsuz anlarımda takılıyorsun, L av olup akıyor benliğime sözlerin, A niden gelip kalbime sokuluyo...', ARRAY['Türk Edebiyatı','Şiir','Zümrüt Demirtaş']::text[], 8.5, '{"poet":"Zümrüt Demirtaş","poet_slug":"zumrut-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/belalim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz...', 'sensiz-emine-deniz-4ksja', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensiz... 	

Eksik denizlere yürüyorum

 Yüzünün olmadığı aynalarda süsleniyor dudaklarım 

Omuzlarımda kaygan bir öpüşün tadı 

Ve

 Doğurmadığım çocuklar gömüyorum toprağa 

...sensin celladı.', 'Sensiz... 	 Eksik denizlere yürüyorum  Yüzünün olmadığı aynalarda süsleniyor dudaklarım  Omuzlarımda kaygan bir öpüşün tadı  Ve  Doğurmadığı...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sensiz-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misketlerin Çamur Olmuş Dediler', 'misketlerin-camur-olmus-dediler-sule-aydemir-qteus', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '___________misketlerin çamur olmuş dediler

misketlerim çamur! 

hiç çamurda oynamadım ki

kumlardaydım

gömüldü belki

hiç batmadı ki! 

(kumlardan peki...hep çamur....nasıl olaki) 

*kalemi gönülden mürekkepli kadının günlüğünden 

14.04.2005 İst.', '___________misketlerin çamur olmuş dediler misketlerim çamur!  hiç çamurda oynamadım ki kumlardaydım gömüldü belki hiç batmadı ki!  (kumlard...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/misketlerin-camur-olmus-dediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Menekşe', 'mor-menekse-musa-yasaroglu-l5unm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sızdı yine odama güneş ışığı

Camı kırık küçük penceremden

Ve hiç acımadan kamaştırdı

Uyku diye inleyen gözlerimi

Ama kaldırdı yine

Gecenin esaretini üzerimden

Hep bu yüzdendir

Ona olan delice sevdam

Ve yine bu sebeptendir

Benim gibi karanlığa düşman

Sevgili mor menekşemin 

Onu kapı önünde bekleyişi', 'Sızdı yine odama güneş ışığı Camı kırık küçük penceremden Ve hiç acımadan kamaştırdı Uyku diye inleyen gözlerimi Ama kaldırdı yine Gecenin e...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mor-menekse-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilememişim', 'bilememisim-ayse-yucel-ni30g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölürüm sanmıştım yokluğunda

Varlığın ölmekmiş her soluğumda

Bilememişim...', 'Ölürüm sanmıştım yokluğunda Varlığın ölmekmiş her soluğumda Bilememişim......', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yücel']::text[], 8.5, '{"poet":"Ayşe Yücel","poet_slug":"ayse-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/bilememisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Bulacağın Yerin Tam Adresi', 'beni-bulacagin-yerin-tam-adresi-baran-baransel-40290', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birtanem,

Bana,

Bağırlara basılan taşların

Neden çok ağır olduğunu ve

İnsanı soluksuz bıraktığını sorma

Olur mu? 

Yüreğimin çakısı neden kırıktır

Ve hal böyleyken

Niye hala ümit etmekten ve özlemekten yanadır tavrım? 

Hasat sonrası dökülen

Buğday tanelerinin içine saklanmış umutlarımı,

Paramparça düşlerimı,

Bulup yitirdiklerimi,

Umurumdakileri ve olmayanları...

Falanları, filanları işte.

Ama yanılıp da; 

Aşkı sormayı

Unutma sakın! ...', 'Birtanem, Bana, Bağırlara basılan taşların Neden çok ağır olduğunu ve İnsanı soluksuz bıraktığını sorma Olur mu?  Yüreğimin çakısı neden kır...', ARRAY['Türk Edebiyatı','Şiir','Baran Baransel']::text[], 8.5, '{"poet":"Baran Baransel","poet_slug":"baran-baransel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beni-bulacagin-yerin-tam-adresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile deryası', 'cile-deryasi-ejder-kose-ixero', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerim seni arıyor, her nereye baksam.

Yüzlerde cemal-ı ilahını göremiyorum! 

Beyaz tenlim, yanıyor yüreğim: aşk-ı sadetinle

Yine de hasret-i vuslatını yenemiyorum…

Bırak gülüm, hasret-i vuslatın yürekte yansın,

Dokunamasam da  gece karası saçlarına.

Bırak gülüm; avuçlarda yaşlar çağlasın

Dokunamasam da gül dudaklarına…

Bu bedbaht şair, düştü aşkınla çile deryasına

Bi-dad eyledi mecnunu sevda sahrasında

Deniz gözlüm, ne hacet düşmeye çöle

Yandı çöl misali yüreğim, çile deryasında

Dokunma nolursun yanaklarıma, yaşlar  vardır

Yastama başını göğsüme, gönlümde yangınlar vardır

Bakma gözlerimin içine,gözlerimde hayalin vardır

Duyarsan ağlama,ölmüş bedbaht şair……….vardır', 'Gözlerim seni arıyor, her nereye baksam. Yüzlerde cemal-ı ilahını göremiyorum!  Beyaz tenlim, yanıyor yüreğim: aşk-ı sadetinle Yine de hasre...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cile-deryasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bülbül ve gül', 'bulbul-ve-gul-ejder-kose-l9wej', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah edermiş bülbül gülün nazından, her nefeste

Acı acı yaş dökermiş kan çanağı gözlerinden,

Feryadı isyanı tükenmezmiş her hasrette,

Sende benim gülümsün hasretimsin sevgilim..

Sancıyor yüreğim gülüm çektirdiğin hasretten

Saatler gün günler yıl oluyor sensizlikten

Ben usanmadım sevmekten sen usanmadın hasretten

Bülbül güle bende sana muhtacım sevgilim…', 'Ah edermiş bülbül gülün nazından, her nefeste Acı acı yaş dökermiş kan çanağı gözlerinden, Feryadı isyanı tükenmezmiş her hasrette, Sende be...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bulbul-ve-gul-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin aşka fısıldıyor', 'gozlerin-aska-fisildiyor-ejder-kose-fz0xt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bak sustu yine şarkılar 

Çünkü güzel sesin aşkı fısıldıyor gel diye bana.

Bak yine sustu bülbüller, utancından sapsarı kesildi,

Çünkü baktığın yerde kırmızı güller açıyor.

İmkansız seni tarif etmek o bakışlarını, gülüşünü, yüreğini

Kelimeler yetersiz kalıyor,bırakma ellerimi n’olur

Ellerin yüreğimi sarıyor,çekme gözlerini gözlerimden

Gözlerin yüreğime akıyor,

Gözlerin aşkı fısıldıyor bana gel diye,

Ağaçlar baharda yapraklarını döküyor,

Gözlerinin rengini kıskanıyor ne olur toplama  saçlarını

Misk-i amber kokunu yüreğime yayıyor..', 'Bak sustu yine şarkılar  Çünkü güzel sesin aşkı fısıldıyor gel diye bana. Bak yine sustu bülbüller, utancından sapsarı kesildi, Çünkü baktığ...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerin-aska-fisildiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükenmeyen çilemsin', 'tukenmeyen-cilemsin-ejder-kose-b6cc8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adını yazdım yalnızlığa sevgilim diye

Göz yaşına boğuldum meleğim diye

Uğruna ne cefalar çileler çekmezdim ki

Belki bir gün gelir de seversin diye…

Adınla başladım yazdığım her satıra,,

Canımsın cananımsın, yarınımsın diye,

Yeminler etmiştim ömrümce seveceğime

Belki bir gün gelirde bunu anlarsın diye…

Dertleşiyorum saçın karası geceyle

Güzelliğini yüreğini sevgimi anlatıyorum

Her kelimede göz yaşlarına boğulup adını haykırıyorum

Belki kulağın çınlarda ağlarsın diye…

Dedim ya sevgilim tükenmeyen çilemsin diye

Dökülen her acı göz yaşımda sevdamsın diye

Adını anacağım aldığım her nefeste

Belki anlarda bir gün gelirsin diye

Seni arıyor gözlerim mahallenden geçerken

Belki beni görür pencereye çıkarsın diye,

Açıp ellerimi yalvarıyorum Allah’a

Sevdiğim ejder deyip haykırasın diye…', 'Adını yazdım yalnızlığa sevgilim diye Göz yaşına boğuldum meleğim diye Uğruna ne cefalar çileler çekmezdim ki Belki bir gün gelir de seversi...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tukenmeyen-cilemsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyankar', 'i-syankar-ejder-kose-vafwq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaratanına olur mu  insan isyankar,

İsyan kokuyor  aldığım her nefeste

Olur mu insan  günahkar tan vakti, 

Günahla doğuyor sanki  şafak,  her güneşte..

İsyan var  döktüğüm her göz yaşının damlasında

Hasret var yazdığım her şiirin mısrasında

Ağlamak,yaşlara boğulmak, çaresiz kalmak,

İsyan var deniz gözlüm sanki her kalp atışımda…

Ölümle yüz yüze gelmek durur her an yanı başım da

İsyanlar sel olur akar her göz yaşimda

Bir de senin hasretin var ya deniz gözlüm

Sıkılmaya hazır kurşun sanki alnımın şakağında..', 'Yaratanına olur mu  insan isyankar, İsyan kokuyor  aldığım her nefeste Olur mu insan  günahkar tan vakti,  Günahla doğuyor sanki  şafak,  he...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isyankar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-ejder-kose-iicqf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerinde hasret rüzgarı esiyor sevdiğim yine bu gece

Kaşların bir ok sanki,  kanatıp gidecek gibi yüreğimi,

Ne olur çekme gözlerini gözlerimden biliyorum son gecemiz

Seni buldum derken işte yine yenildiğim sensizliğe…

Demiştin ya yürek ümitlere gebedir diye…

Gidiyorum bak işte ümitleri doğmadan öldürerek…

Gidiyorum bak işte hasretine yenik düşerek..

Gidiyorum ayrılık seline kapılıp gözlerini gözlerime dökerek..', 'Gözlerinde hasret rüzgarı esiyor sevdiğim yine bu gece Kaşların bir ok sanki,  kanatıp gidecek gibi yüreğimi, Ne olur çekme gözlerini gözler...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayrilik-240-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vakti mi geldi ayrılığın?', 'vakti-mi-geldi-ayriligin-ejder-kose-4htrl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güller boynunu bükmüştü bu sabah 

Rüzgar acıtıyordu ta yüreğimi derinden.

Bülbüller bir başka ediyordu ah

Gülemiyordu gözlerim ağlıyordu sensizlikten.

Vaktimi geldi yoksa ayrılığın.

Güzel gözlerine iki damla yaş düşmüş.

Yaşlara boğuluyor bak bedbaht yüreğim.

Yoksa deniz gözlüsü o namı küsmüş.', 'Güller boynunu bükmüştü bu sabah  Rüzgar acıtıyordu ta yüreğimi derinden. Bülbüller bir başka ediyordu ah Gülemiyordu gözlerim ağlıyordu sen...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vakti-mi-geldi-ayriligin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlıyor', 'agliyor-ejder-kose-b2txj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne güzel günler yaşamıştık sevgilim seninle

Sanki dünyanın en mutlu insanı bizdik

Gözlerin yüreğimde, yüreğim ellerindeydi

Şimdi ise göz yaşlarına boğulmuş sabrım ağlıyor

İsmine şiirler yazdım her kelimede meleğim diye başladım

Aşkıma, bitmesin diye dualar ettim Allah’a yalvardım

Her köşeye adını yazıp meleğim,  sevenim dedim

Şimdi şiirimde duamda ağlıyor….', 'Ne güzel günler yaşamıştık sevgilim seninle Sanki dünyanın en mutlu insanı bizdik Gözlerin yüreğimde, yüreğim ellerindeydi Şimdi ise göz yaş...', ARRAY['Türk Edebiyatı','Şiir','Ejder Köse']::text[], 8.5, '{"poet":"Ejder Köse","poet_slug":"ejder-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/agliyor-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nalıncı Keseri..', 'nalinci-keseri-cenk-aksal-gjvg1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yüzleşiyorum her sabah:

aynada kendimle..

ne yaptın dün,

ne yapacaksın bugün..

kızarıyor suratım:

suç işlemişim sanki,

nalıncı keseri misali:

hep yontmuşum kendime..

marifetmiş sanki:

on lira tutuşturmuşum,

yaşlı dilencinin eline...

bir daha bakıyorum:

aynadaki kızarmış yüze,

başka yüzler görüyorum:

iskeledeki mendilci kız:

gülümsüyor yüzüme,

simitçi ahmet önlüğü üstünde:

okula hazırlanıyor,

öğretmenim emekli olmuş,

pazarda limon satıyor,

tinerci çocuklar köşede:

birbirlerine jilet atıyor,

komşum nalan teyze:

maaş kuyruğunda bayılıyor,

siliniyor aynadaki yüzler:

kendimle yüzleşiyorum yine,

utancım nefrete dönüşüyor:

yaşlar düşünce gözlerime,

soruyorum kendime:

ideallerim ne oldu diye:

cevapsız kalıyorum/kendime,

dün nasıl geçtiyse/biliyorum

yarın aynı olacak yine...

nalıncı keseri elimizde:

kendimize yontacağız..

ömrümüzce,ya/ölünce.

   ''bil kendini/cenk..korkma/vuslat saati gelince''', 'yüzleşiyorum her sabah: aynada kendimle.. ne yaptın dün, ne yapacaksın bugün.. kızarıyor suratım: suç işlemişim sanki, nalıncı keseri misali...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/nalinci-keseri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felek', 'felek-i-brahim-kilinc-pvcla', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayını şaşırır, günü bulurum

Gül ile eziyet edersin bana

Yolunu şaşırır, yönü bulurum

Yol ile eziyet edersin bana

Seslensem de duyuramam sesimi

Kendim de tutamam kendi yasımı

Karalardan kara yazıp yazımı 

Dil ile eziyet edersin bana

Gönlümce arayıp ona varamam

Derdini dinleyip hatır soramam 

Bu sineye başkasını saramam

Kol ile eziyet edersin bana

Nurlara boğarsın bazen cihanı

İlahi ışığın sarar heryanı 

Bana da  gösterip bir Nur Sultanı

Kul ile eziyet edersin bana', 'Ayını şaşırır, günü bulurum Gül ile eziyet edersin bana Yolunu şaşırır, yönü bulurum Yol ile eziyet edersin bana Seslensem de duyuramam sesi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kılınç']::text[], 8.5, '{"poet":"İbrahim Kılınç","poet_slug":"i-brahim-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/felek-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renklerin İstanbul’u', 'renklerin-i-stanbul-u-emin-kesmer-q8gef', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen angın bir hoyratlık azmindesin

Ben yılları saya saya çoktan unuttum

Gitmez aynımdan o mahzun resmin

Baktığım her çizgide seni görürüm

Nerdesin ey büyülü panorama, nerdesin? 

Sen kanımda eriyen bir denizin tuzusun

Aşkın içimde şaha kalkmış son atlı gibi

Bir kez içten gülümse yorgun ruhum uyusun

Hasretin çoğalıyor, aşıyor ülkeleri

Kalbim uçuyor sana sanki kanatlı gibi

Seni nerelerde bulayım ey İstanbul

Tenimde soluğunun sıcaklığı var

Durmadan çiziyorum güneşini sonsuzluklara

Göğsümde gizlediğim bu ıssız karanlıklar

Kazayla kırılıverecek mi yoksa – bir gün gelip son hatıran

Seni anlatmaya yetişmiyor şarkılar

Rum bir delikanlı hasret hüznünü söyler - duyar mısın? 

Türküsü senin sularına dökülüdür

Bazen ada sahillerine oturur sorar mısın? 

Bu ezgiler nasıl derinlere gömülüdür? 

Kahırlı bir ana gibisin - yitik mi çocukların? 

Temeline gömülen özlemleri bulacak mısın? 

Bütün renkler senindi, senindi bir zamanlar

Sen de bütün renklerin olacak mısın? 

Onu mu arıyorsun hâlâ – dirimin sabahında

Anılar denizinin hayal ufuklarında

Bir saadet şavkıyla bir daha gelecek mi? 

Bir daha uyuyacak mıyız afsunlu kollarında

Kuşların göçtü, renklerin soldu mu

Yağmurların dindi, yıldızların söndü mü

Yıkık bir değirmen misali çağıltılı ve sessiz

Bırakıldın mı hiç benim gibi çaresiz

Unuttun mu bizi ey hülyalı şehir

Nasıl gönül akıtmışız oysa sana

Bir yabancı gibi karşılasan da

Seviyoruz seni seveceğiz - anlasana.

./..

Dağlardan akın akın oğulların sana koşar

Arapların, Çerkezlerin, Ermenilerin, 

Azerilerin, Türkmenlerin, Kürtlerin,

İspanya’dan yola çıkar Musevilerin 

Ve tarih olur medarı maişet – firak her yerde

Önünden durmadan akar – lacivert sular gibi 

Tarih limanlarında demirleyen gemilerinde

Metruk yalılarında, perili köşklerinde

Tarih göğsünde bir dev hışmıyla soluk alır azametli

Cumbalı ahşap evlerindedir, tarih

Dar sokaklarında nüzullü bir âmâ gibi

Ey büyük İstanbul 

Kültür: Yazma eserlerinde, minyatüründe, müziğinde,

İkonalarında, eski şarkılarında, kantolarındadır

Sevgi: Halicinde, Boğazında, Adalarında

Üsküdar’ın Sütlüce’nin çamurundadır.

Aşk: Oynak dalgalarında – ağustosta esen serin rüzgârındadır.

Gizem: Tepelerinde, minarelerinde, kulelerinde

Sarı gelin Fırat’ın sularında kaybolmuş

Tamara bekliyor karşı kıyıda belki yine

“Dağlar bizimdir! ” diyor Dadaloğlun, Köroğlun

Bir taşını Acem mülküne değişmiyor o Nedim-i biçare

Ellerimiz aynı dilek taşında bir an

Titreriz büyük bir mirasın ruh doygunluğunda 

Ayaklarımız kaç bin yıllık basamakta buluşur-Ayasofya’da

Hikmeti özgürlük ve taş ilmindedir

Bir insancalık serpilir gönlümüze bir daha 

Kardeşliğimiz oluşur, oluşur sonra

Meğer İstanbul senin beynindir yüreğindir

En şaşmaz gözün, belleğin – en kudretli ve hünerli elindir.

İstanbul bütün çocuklarının ebedî sevgilisi, ezelî başkentidir.

Çocuklarını hatırla ey İstanbul

Çocuklarını hiç bırakma

ÇOCUKLARINI UNUTMA ANATOLİA… 

	Ne olur unutma

Unutma', 'Sen angın bir hoyratlık azmindesin Ben yılları saya saya çoktan unuttum Gitmez aynımdan o mahzun resmin Baktığım her çizgide seni görürüm Ne...', ARRAY['Türk Edebiyatı','Şiir','Emin Keşmer']::text[], 8.5, '{"poet":"Emin Keşmer","poet_slug":"emin-kesmer","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/renklerin-istanbul-u-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul ağlıyor', 'i-stanbul-agliyor-yasemin-candur-tovtl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstanbul ağlıyor

Sensiz sokakların üzerine

Birbir hasretini döküyor,insanların üzerine

Rüzgarlar seni fısıldıyor,İstanbul ağlıyor diye

Bir sis çöküyor omuzlarıma

Birsessizlik uğultusu dolaşıyor kulaklarımda

Yalnızlık çığlğık çığlığa bağırıyor

İstanbul ağlıyor

Sonbaharlarda bir seni düşünüyorum

Bir yaz yağmuru yağıyor üzerime 

Sensiz sokakları bomboş görünce

Ben ağlıyorum,İstanbul ağlıyor

Sana,sensizliğe ve senin çaresizliğine

İstanbul görüyorum gözlerim yaşlı

seni çağırıyor bulutlu göklere

Ve senin sonsuza dek dönmeyeceğini görünce

Ben ağlıyorum,sonkez İstanbul ağlıyor

Sana,sensizliğe ve imkansızlığa', 'İstanbul ağlıyor Sensiz sokakların üzerine Birbir hasretini döküyor,insanların üzerine Rüzgarlar seni fısıldıyor,İstanbul ağlıyor diye Bir s...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Çandur']::text[], 8.5, '{"poet":"Yasemin Çandur","poet_slug":"yasemin-candur","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/istanbul-agliyor-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul ve ölüm', 'i-stanbul-ve-olum-yasemin-candur-23ie9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ara sokaklardan kaçıyorum gelmesin diye

Ölüm beni bulup götürmesin diye

İstanbul''un sokaklarında kaçışıp duruyorum

Ne bir dost,ne bir insan çıkıyor karşıma

Sanki,yüreğimin derinliklerinde kaybolmuşum

Bir ara korkuyorum,duyuyorum ayak seslerini

Beni alıp götürecek diye titriyorum

Daha hızlı kaçıyorum ama beni yakalıyor

Yalvarıyorum kimse yok sokaklarda

Cansıs bedenim çürüyüp gidecek buralarda

Ve uyanıyorum korkulu bir rüya

Toptağın altındayım gidiyorum sonsuza.', 'Ara sokaklardan kaçıyorum gelmesin diye Ölüm beni bulup götürmesin diye İstanbul''un sokaklarında kaçışıp duruyorum Ne bir dost,ne bir insan ...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Çandur']::text[], 8.5, '{"poet":"Yasemin Çandur","poet_slug":"yasemin-candur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/istanbul-ve-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-sebahat-mayda-yavuz-jkhon', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'On yılda zor alıştım

Sana İstanbul,

Birlikte tekliği

Yaşatan şehir...

Adım atsan

Omuzun birine 

Çarpar,

Sen ona bakarsın

O, sana bakar,

Selâmı sabahı

Kesilmiş şehir...

Eskitmiş

Denizin maviliğini,

Bulutlara baksan

Tutmaz yerini,

Her gün biraz daha

Ölen bir şehir...

İnsanlar kaybetmiş

Kimliklerini,

Nüfûsta başka

Yazsa da yeri; 

O ne tam köylüdür,

Ne de şehirli...

Onulmaz hastalık

Gibidir şimdi; 

Bir gelen

Bir daha 

Dönemez geri,

Karasevda mısın 

Sen ey İstanbul? ..', 'On yılda zor alıştım Sana İstanbul, Birlikte tekliği Yaşatan şehir... Adım atsan Omuzun birine  Çarpar, Sen ona bakarsın O, sana bakar, Selâ...', ARRAY['Türk Edebiyatı','Şiir','Sebahat Mayda Yavuz']::text[], 8.5, '{"poet":"Sebahat Mayda Yavuz","poet_slug":"sebahat-mayda-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/istanbul-195-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Sevgilim', 'elveda-sevgilim-omer-bolat-o4p91', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne benden önce

Anlatıldı.

Ne ben anlatabildim.

Ne de benden sonra 

Anlatılacak,

Bu çelişkiler dünyası...

Ağzı olan konuştu.

Çok şeyler yazıldı 

ve çizildi

Umutla beklerken muştu

Hayallerim mahkum olup, 

Kurşuna dizildi...

Sevgilim...

Ne sen 

Ne de ben

Umutsuz değildik.

Çarpınca 

Buz gibi gerçeğe

Bu kahpe hayatın önünde

Eğildik.

Anlık heveslerim,

içimde yeşermeden soldu.

Ne zaman meyletsem aşka,

Sonsuz pişmalığım oldu.

Kalmadı bu dünyada yerim

Benim miadım doldu.

Ecel çöreklendi boğazıma

Son bir defa 

''Seni Seviyorum''

Diyemeyecek dilim.

Gidiyorum artık,

ELVEDA SEVGİLİM...

19 Nisan 2005

ALACA', 'Ne benden önce Anlatıldı. Ne ben anlatabildim. Ne de benden sonra  Anlatılacak, Bu çelişkiler dünyası... Ağzı olan konuştu. Çok şeyler yazıl...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bolat']::text[], 8.5, '{"poet":"Ömer Bolat","poet_slug":"omer-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/elveda-sevgilim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kelime Dikiyoruz Toprağa', 'bir-kelime-dikiyoruz-topraga-cigdem-demircan-h0rjy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kocaman, nasırlı ellerinin üzerinde yürüyorum

Kocaman, nasırlı ve narin ellerinin üzerinde...

Nasırlara takılıyor ayaklarım...

Susuzluktan çatlamış ellerinin yarıklarına takılıyor...

Canım yanıyor,

Canın yanıyor... 

biliyorum...

yürüyorum...

Bişeyler var yolumun sonunda, 

yolumuzun sonunda...

onu arıyorum...

Çocukluğumun şeker kabuklarına sığdırmaya çalıştığım

kar parçacıklarını mı arıyorum? 

Yoksa madımak topladığım o yeşillikleri mi...? 

Bacaklarını komşum yapıp oyun oynadığım 

O kırmızı sandalyeyi mi arıyorum? 

Ondörtlü yaşlarımın baharda mor çiçeklere bezenmiş tepeciklerini mi yoksa? 

Fıratın o nazlı

Fıratın o coşkulu

Fıratın o dinmek bilmeyen serinliğini mi arıyorum? 

Yeni yerlere karşı hissettiğim ürkekliği mi? 

Her şehir değiştirişimde ardımda bıraktıklarımı mı? 

Simalarını bıraktığım isimleri mi arıyorum? 

Ardımda bıraktığım tüm baharların kokularını mı? 

Bahar gibi karşıma çıkıveren

tüm şaşkınlıkları

farkedişleri

gülümseyişleri

sevinçleri mi...? 

Kirazlarını küpe yaparken

ağaçlarda bıraktığım, 

Buğday başaklarını okşarken 

tarlalarda bıraktığım,

Gökkuşağını aramaya koşarken,

yollarda bıraktığım

çocukluğumu mu arıyorum? 

Kocaman, nasırlı ve narin ellerinin üzerinde yürüyorum...

Seni arıyorum ellerinde...

Çocukluğunu, çocukluğumu...

Çocukluğuna, çocukluğumu getiriyorum...

Toprak gibi susamış ellerine, sevgisini yağdırıyorum geçmişimin...

Umutlarımı dikiyorum ellerine...

şaşkınlıklarım,

farkedişlerim,

gülümseyişlerim,

sevinçlerim mevye veriyor ellerinde... 

Kocaman, nasırlı ve narin ellerinin üzerinde yürüyorum...

Çocukluğumun özlediğim o toprakları gibi kokuyor ellerin

Çocukluğumun hüznü,

Çocukluğumun umudu,

Ellerine o tepelerden getirdiğim çiçeklerden de 

güzel kokuyor ellerin...

Ellerin bahar kokuyor...

Biryerlerde bıraktığım bir kelime gibi kokuyor ellerin...

Nasırların arasına sıkışmış bir kelime gibi kokuyor...

Ellerinin üzerine yavaşça uzanıyorum...

Ellerin yavaşça kapanıyor...

Bir kelime oluyor...

O kelimeyi fısıldıyor toprak...

Filizlenerek çıkıyoruz topraktan...

“Aşk” kokuyor heryer...

“Aşk” kokuyoruz...

14 Ocak 2004', 'Kocaman, nasırlı ellerinin üzerinde yürüyorum Kocaman, nasırlı ve narin ellerinin üzerinde... Nasırlara takılıyor ayaklarım... Susuzluktan ç...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Demircan']::text[], 8.5, '{"poet":"Çiğdem Demircan","poet_slug":"cigdem-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/bir-kelime-dikiyoruz-topraga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç Olmak', 'agac-olmak-yusuf-ter-cdfxt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağaç olmak

Kökü çok derinlerde

Ne kışlar gördü bu çınar

Fırtınalara dayandı 

Rüzgarlar estikçe

Dalları sallandı kırılmadı

Ağaç olmak

Toprağın derinliklerinde sitili

Ne baharlar gördü yapraklar açtı

Duldaladı çiçekleri otları

Arılara mekan oldu kozaları

Boş petekler dolu dolu

Ağaç olmak

Şehrin göbeğinde durmak

Ne sonbaharlar gördü döktü gözyaşlarını

Yağmurlar dinmedi yağdıkça yağdı

Ağaç gövdesiyle yapraklarını taradı

Gazeller örtü çiçeklerin  üzerini

Ağaç olmak

Boşatılmış içi çürümeye terkedilmiş

Ne yazlar gördü kuşlara yuvalar ördü

Sevgililere şiir oldu

Kökünden kestiler 

İnsan oğlunun zulmüne  dayanamadı

Yok olmamak için

Kökünü toprak altından patlattı

Ağaç olmak 

Ve saatlerce

Onun  altında

Bir yari beklemek

Yağmur damlaların birikiminde

Suya baktığında ayna olur

Gelmeyeceğini bile bile beklemek.…

16.04.05

Saat 22.28 İsviçre', 'Ağaç olmak Kökü çok derinlerde Ne kışlar gördü bu çınar Fırtınalara dayandı  Rüzgarlar estikçe Dalları sallandı kırılmadı Ağaç olmak Toprağı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/agac-olmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-hulya-karaca-ai119', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevmek, yüreğimdeki derin ızdırabım

Çığlık çığlık haykırışımdır sonsuzluğa

Sevmek, zihnimdeki kırık parçalar

Boşluğu içimde hissettiğim zaman

Sevmek, çaresizlikteki tek cevap

Zifiri karanlığımdaki umutsuz serap

Sevmek, sevgiliye hasret yürekteki 

Doymak bilmeyen ruhuma inat

Sevmek, onsuzken onu yaşamak

Biçare hülyalarla uykuya dalmak

Sevmek, odur yalnızca onu hissetmek

Onu istemek onu beklemek', 'Sevmek, yüreğimdeki derin ızdırabım Çığlık çığlık haykırışımdır sonsuzluğa Sevmek, zihnimdeki kırık parçalar Boşluğu içimde hissettiğim zama...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaca']::text[], 8.5, '{"poet":"Hülya Karaca","poet_slug":"hulya-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-sevmek-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairlerin Şairi', 'sairlerin-sairi-hulya-karaca-2rob3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şairlerin şairi

Gönüllerin tabiri

Sevdalara merhem

Dertlerin çizgisi

Kalemin sihri

Düşünceler ufku

Sözlerin dostu

Çarelerin başı

Anlam anlamını yitirir

Kifayetsizdir her şey

Sözüm ona şair

Şairlerin şairi', 'Şairlerin şairi Gönüllerin tabiri Sevdalara merhem Dertlerin çizgisi Kalemin sihri Düşünceler ufku Sözlerin dostu Çarelerin başı Anlam anlam...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaca']::text[], 8.5, '{"poet":"Hülya Karaca","poet_slug":"hulya-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sairlerin-sairi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Böyle Birşey', 'i-ste-boyle-birsey-hulya-karaca-vgg9f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş tenini yakar ya batarken

Hani ay doğar ya her geceye

Yıldızlar adını yazar ya gökyüzüne

Hani her an aklımda olursun ya

Baharı tenin de hissedersin ya

Hani bir çiçeğin açışını izlersin ya

Gözlerim arar ya her zaman seni

Hani beni sevdiğini söylersin ya

Karanlığın esen ayazında ararsın ya beni

Hani gözlerime bakmayı özlersin ya

Benimde gözlerine bakmayı özlediğim gibi

Hani ölesiye seversin ya

İşte böyle bir şey

Sevdan kalbimde böyle…', 'Güneş tenini yakar ya batarken Hani ay doğar ya her geceye Yıldızlar adını yazar ya gökyüzüne Hani her an aklımda olursun ya Baharı tenin de...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaca']::text[], 8.5, '{"poet":"Hülya Karaca","poet_slug":"hulya-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/iste-boyle-birsey-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Döneyim (Şarkı sözü)', 'nasil-doneyim-sarki-sozu-i-brahim-tamer-vw4av', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevginden izmi kaldı, boş şimdi yüreğim

Anılmadıki dudağında ismim, seni seveyim

Çağırmadın birgün olsun, nasıl geleyim

Bırak, anma adımı, bırak, artık öleyim

Öldürdün benliğimi, geçti seneler yıllar

Dağlar sıralandı aramızda, uzadı yollar

Çaldılar ömrümü sensiz geçen o yıllar

Bırak, hiç değilse kalsın bende anılar

Beni bana bırak, sensiz son anlarımda

Sen oldun, hep sen olacaksın, dudaklarımda

Silmedim duruyor, busen hep yanaklarımda

Ümidim kalmadı artık, sensiz yalan dünyada

Nasıl döneyim canım, neyle döneyim? 

Dönsemde artık gülüm, söyle, söyle nasıl seveyim?', 'Sevginden izmi kaldı, boş şimdi yüreğim Anılmadıki dudağında ismim, seni seveyim Çağırmadın birgün olsun, nasıl geleyim Bırak, anma adımı, b...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tamer']::text[], 8.5, '{"poet":"İbrahim Tamer","poet_slug":"i-brahim-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/nasil-doneyim-sarki-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özledim Annem', 'seni-ozledim-annem-hulya-karaca-o9u10', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O sıcak ellerin nerde annem 

Örterdin geceleri üzerimi

Bir öpücükle uyandırırdın gündüzleri

Bilsen ne kadar özlemişim seni

Gel artık dayanamıyorum annem

O güzel bakışların var ya annem 

Gülerken oluşan gamzelerin hani! 

Dünyadan zevk almamı sağlayan o tatlı sözlerin

Bilsen ne kadar ararım seni

Gel artık dayanamıyorum annem

Saçımı okşadığın ellerini

Bana gülen o gözlerini

Kalbimde yanan bu ateşi

Bilsen ne kadar bekledim seni

Gel artık dayanamıyorum annem', 'O sıcak ellerin nerde annem  Örterdin geceleri üzerimi Bir öpücükle uyandırırdın gündüzleri Bilsen ne kadar özlemişim seni Gel artık dayanam...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaca']::text[], 8.5, '{"poet":"Hülya Karaca","poet_slug":"hulya-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-ozledim-annem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavice Özlem (şarkı sözü)', 'mavice-ozlem-sarki-sozu-i-brahim-tamer-eolwi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mavi gözlerimde ışıktın benim, sevdiğimdin

Gönül bahçemde açan gülüm, sevğilimdin

Sana ait herşeyini, güzel tenini özledim

Dönmedin sevgilim, beni sen hiç sevmedin

Düşman oldum hatıralara,geçen yıllara

Seni benden ayıran uzun, katil yollara

Resimlere,duvarlara,bende kalan anılara

Dönmedin sevgilim,beni sen hiç sevmedin

Hani mavi gözlerimde kayboldum derdin

Bulduğun her fırsatta sevdiğini söylerdin

Ayrılamam derdin, her gün yemin ederdin

Dönmedin sevgilim,beni sen hiç sevmedin

Ömre bedel seneleri sensiz geçirdim

Terkedip giderken beni zehir içirdin

Günde on defa ecel kapısından geçirdin

Dönmedin sevgilim,beni sen hiç sevmedin

(Bu siir dostum Sedat''a armağanım olsun)', 'Mavi gözlerimde ışıktın benim, sevdiğimdin Gönül bahçemde açan gülüm, sevğilimdin Sana ait herşeyini, güzel tenini özledim Dönmedin sevgilim...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tamer']::text[], 8.5, '{"poet":"İbrahim Tamer","poet_slug":"i-brahim-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mavice-ozlem-sarki-sozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Yüzlü Sevgili', 'gunes-yuzlu-sevgili-efsun-aydin-djz1m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneş yüzlü sevgiline 

En çok gülmeyi yakıştırırsın sen,

Öyle güzel olur ki yüzü güldüğünde, 

Bilirim, O’ nu böyle görünce huzura kavuşursun sen.

Bir anlık mutluluk bir ömüre bedel olur o zamanlar yaa işte,

Sen en çok buna bağlanır ve bunu seversin 

Aslında gözlerinin oyuk çukurlarında gizlediğin 

O aşka layık bir kalpti ihtiyacın…

Verdiğinde alan, aldıkça veren bir bakış, bir dokunuş…

Dünyaya bedeldi senin için, 

Farkındaydım.

Bu yüzden sana bu sevgiliyi layık görüyorum.

O kız senin için doğuyor hergün 

Yer yurt aramadan, olduğun hernerdeysen sadece sana, senin için…

‘’Küçük duyguların adamı değilsin ki sen…

Hayatına gölge misali girip sonra çekip gideyim…’’

Öyle bir sevgi verir ki bu kız sana 

Gitse bile, gölgesi izler durur seni hiç unutma benim canım sevgilim! 

Sana sarılınca titrer vücudum,

Seninle sevişirken hisseder beynim

Bilirim ki her beden bir beyne eş…

Sen bedenimdeyken beynim,

Beynimdeyken de bedenim oluyorsun.

Bunu yaşarken ölmek bile,

Hayattan kopmak demek değildir benim için

Sana yemin ederim.

Bu kelimeler birleşince işte 

Oldu sana yazılan bir şiir.

Belki çok değer taşımaz ama her okuduğunda 

Damarına işleyen o yanı hep bu kağıtta kalacaktır.

Seni seviyorum.', 'Güneş yüzlü sevgiline  En çok gülmeyi yakıştırırsın sen, Öyle güzel olur ki yüzü güldüğünde,  Bilirim, O’ nu böyle görünce huzura kavuşursun...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gunes-yuzlu-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel İstanbul', 'guzel-i-stanbul-mustafa-ekinci-7q9ls', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Erenler evliyalar diyarısın,

Her neslin medh-i medarısın, 

Yuşa’nın Eyyub’un mezarısın, 

Dağı güzel, taşı güzel İstanbul.

Tarihin hisarlarda nakış nakış,

Burçlarında bayrak yaz ve kış,

Dimdik ayaktasın sana bin alkış,

Yazı güzel, kışı güzel İstanbul.

Osmanlı mutfağının baş şehrisin,

Seksenbir şehrin hemşehrisisin,

Hoş seda bülbüllerin gülşenisin,

Suyu güzel aşı güzel İstanbul.

Garip, gureba senin kucağında

Yolunu kaybedenler ocağında,

Duman tüter her bucağında

Hali güzel, işi güzel İstanbul.

Edirne’den Sakarya’ya uzanan boyun

Marmara’dan Karadeniz’e açılan kolun

Tarihler boyu  bükülmeyen dalın

Yüzü güzel kaşı güzel İstanbul.

Türküler söylendi senin adına

Şiirler yazıldı güzel namına

Ağıtlar yakıldı dramlarına

Özü güzel, sözü güzel İstanbul.

Elli sefer talip dayandı kapına

Tüm dünya hayran kaldı yapına

Ne canlar feda edildi yoluna

Talihi güzel, nazı güzel İstanbul.

Ne söylesem anlatamam seni

Çizemem kağıtlara resmini

Her karışın bir sanat eseri

Deseni güzel, tarzı güzel İstanbul.

Ankara-2005', 'Erenler evliyalar diyarısın, Her neslin medh-i medarısın,  Yuşa’nın Eyyub’un mezarısın,  Dağı güzel, taşı güzel İstanbul. Tarihin hisarlarda...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ekinci']::text[], 8.5, '{"poet":"Mustafa Ekinci","poet_slug":"mustafa-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/guzel-istanbul-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana, Seninle Uyanmak Vakti', 'sana-seninle-uyanmak-vakti-zafer-yazici-hyh0l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana bakmak, senin gibi yukarıdan, öyle içten! 

Sana sarılmak, hasret dolu, umut dolu, sımsıkı! 

Sen gibi bir şey hasretin adı, uzak yollarda ki yolcu gibi! 

Yaşam, gözlerindeki hayat pınarları, her daim akan gönlüme! ..

Kırık merdivenlere yaslanmışım şehrimin, elimde sigaram

Bir yanım sen, ışıltılı, nasıl da rengarenk! 

Diğer yanım sen, esintili, ruha huzur veren, yumuşak! 

Önüm – arkam hep sen, bir çocuk saflığında ki şen gülüşler! ..

Karanlığın içinde sana soyunmak, çırılçıplak, günahsız

Sen kokan sabahlara, tan vaktinde, kuş sesleri arasında

Gözlerinde uyanmak, en çapaksız gözlerle! 

Bahar esintileri teninde! ..

Gündüzlere çıkmak seninle, bir nefes daha almak, derin! 

En umulmadık anlarda, sırf senin için

Yıldızları düşürmek dallarından, koynumuza

Yattığımız yerden bulutlara yaslanmak! 

Sana, senin gözlerinden girip içeri

Yüreğinde uyanmak vakti şimdi!', 'Sana bakmak, senin gibi yukarıdan, öyle içten!  Sana sarılmak, hasret dolu, umut dolu, sımsıkı!  Sen gibi bir şey hasretin adı, uzak yollard...', ARRAY['Türk Edebiyatı','Şiir','Zafer Yazıcı']::text[], 8.5, '{"poet":"Zafer Yazıcı","poet_slug":"zafer-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sana-seninle-uyanmak-vakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görseydi gözlerim...', 'gorseydi-gozlerim-efsun-aydin-pvabo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni gördüğüm ilk gün 

Gözlerin gözlerimi oydu.

Bir tuhaf kamaştı gözlerim

Şimdi öylesi bir körlük var ki ben de,

Sanki her taraf senin karanlığın

Yazık...

Artık BİZ i göremiyorum.', 'Seni gördüğüm ilk gün  Gözlerin gözlerimi oydu. Bir tuhaf kamaştı gözlerim Şimdi öylesi bir körlük var ki ben de, Sanki her taraf senin kara...', ARRAY['Türk Edebiyatı','Şiir','Efsun Aydın']::text[], 8.5, '{"poet":"Efsun Aydın","poet_slug":"efsun-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gorseydi-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Sabahı', 'bayram-sabahi-ali-furkan-oguz-vybsw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ve bazen de düşlerimiz tutuşsa sisli gecelerde bulutlara,

sımsıcak sevinçler alsa kızıl ürpertilerin yerini,

bayramlar hiç kaybolmasa

küçük kalplerinde sokağın çocuklarının,

KIŞ UYUTMASA ÜŞÜTÜRKEN HİÇ...', 'Ve bazen de düşlerimiz tutuşsa sisli gecelerde bulutlara, sımsıcak sevinçler alsa kızıl ürpertilerin yerini, bayramlar hiç kaybolmasa küçük ...', ARRAY['Türk Edebiyatı','Şiir','Ali Furkan Oğuz']::text[], 8.5, '{"poet":"Ali Furkan Oğuz","poet_slug":"ali-furkan-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bayram-sabahi-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerisi Zifiri', 'gerisi-zifiri-ali-furkan-oguz-wdj6f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nefes alışlarım bile karmakarışık

en kısa yol gibi gözüken tek olan belki de

GERİSİ ZİFİRİ...', 'Nefes alışlarım bile karmakarışık en kısa yol gibi gözüken tek olan belki de GERİSİ ZİFİRİ......', ARRAY['Türk Edebiyatı','Şiir','Ali Furkan Oğuz']::text[], 8.5, '{"poet":"Ali Furkan Oğuz","poet_slug":"ali-furkan-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/gerisi-zifiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ilan-i A$k', 'ilan-i-a-k-huseyin-avdic-n5vbt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'A$k bu! 

Insani Leyla da eder,

Mecnûn da eder.

Cöllere düsürür,

Perisan eder.

Ne ederse etsin,

Kim ne derse desin,

A$kimi ilân ediyorum.

Bütün dünya duysun:

Seni seviyorum,

Seni seviyorum!', 'A$k bu!  Insani Leyla da eder, Mecnûn da eder. Cöllere düsürür, Perisan eder. Ne ederse etsin, Kim ne derse desin, A$kimi ilân ediyorum. Büt...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ilan-i-a-k-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yirmiüç Ellidokuz', 'yirmiuc-ellidokuz-ali-furkan-oguz-xv3k4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zamanaşımına uğradı sevdalarımız

zorlanmış hiçliklerden kalma bayat yarınlar sunuldu 

gençliğimize

hep ‘karanlık’ sanılmıştık oysa

ve nice ölümleri zamanaşımına uğratamadık

çoktan belirmişti ağarmış saçlar

son sigaram 23:59’da gasp edilmişti...', 'Zamanaşımına uğradı sevdalarımız zorlanmış hiçliklerden kalma bayat yarınlar sunuldu  gençliğimize hep ‘karanlık’ sanılmıştık oysa ve nice ö...', ARRAY['Türk Edebiyatı','Şiir','Ali Furkan Oğuz']::text[], 8.5, '{"poet":"Ali Furkan Oğuz","poet_slug":"ali-furkan-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yirmiuc-ellidokuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarsın', 'aglarsin-i-smail-dogan-mdkxw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey sevdiğim ne bu, halin perişan, 

Gözlerin beni mi arar ağlarsın? 

Bırakıp gidemem gözün yaşınan, 

Nere giden diye sorar ağlarsın. 

Aşkımın  özüsün  ne diye ağlan,

Damarımda kansın sevene bağlan,

Türlü türlü çilve,  yaparak çağlan,

Kolların boynuma sarar ağlarsın.

Seyredersin kumru, uçan kuşları,

İzlemeye  değer şu  bakışları,

Kurumadı  gitti  gözün  yaşları,

Kumru gibi hayal kurar ağlarsın.

Kitaplar  okudum,  ilaçlar aldım,

Bunca  mersiyeler  şiirler saldım,

Yapamadım bir şey şaşırdım kaldım,

Niye böyle kendin gerer ağlarsın.

Sevda ateşinde kor oldum yandım,

Elinden dem içtim sarhoşum sandım,

Bütün benliğimle sana bağlandım,

Masum nazlım nazlım durur ağlarsın.

Bütün  erenlari  ziyaret  ettim,

Neden ağlar diye hal sual ettim.

Bulamadım çare eridim bittim,

Yüreğine  acı  sürer  ağlarsın.

Sil göz yaşlarını  güzel görelim.

Sevgi bağımıza  güller derelim,

DOĞANİ kalbinde gönül cevherim.

İnciden gerdanı örer ağlarsın.

19.04.2005', 'Ey sevdiğim ne bu, halin perişan,  Gözlerin beni mi arar ağlarsın?  Bırakıp gidemem gözün yaşınan,  Nere giden diye sorar ağlarsın.  Aşkımın...', ARRAY['Türk Edebiyatı','Şiir','İsmail Doğan']::text[], 8.5, '{"poet":"İsmail Doğan","poet_slug":"i-smail-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aglarsin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bindokuzyüzseksenyedi Kışından Küçük Bir Fısıltı', 'bindokuzyuzseksenyedi-kisindan-kucuk-bir-fisilti-ali-furkan-oguz-a5ruo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başın sağolsun sabah seheri

demek bir daha üşümeyecekmişiz kapı hafif aralıkken

bindokuzyüzseksenyedi kışından küçük bir fısıltı dahi...

aralığın son günleri,

belki de nefes almanın çaresiz mahpusluğu

kar bütün yollarını kapamış çığlığımızın

okullar bu sabah da tatil

başımız sağolsun gündoğumunda ama...

BUGÜN DE PAZAR...', 'Başın sağolsun sabah seheri demek bir daha üşümeyecekmişiz kapı hafif aralıkken bindokuzyüzseksenyedi kışından küçük bir fısıltı dahi... ara...', ARRAY['Türk Edebiyatı','Şiir','Ali Furkan Oğuz']::text[], 8.5, '{"poet":"Ali Furkan Oğuz","poet_slug":"ali-furkan-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bindokuzyuzseksenyedi-kisindan-kucuk-bir-fisilti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nev Bahar', 'nev-bahar-mustafa-ekinci-go9q5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Erişti nev-bahar oldu dilim gülizâr 

Nâle-i mürgân ile doldu âlem pür zâr

Bu mevsim-i ferhunde - dem kül-eşcâr

Açıldı bir gonce gibi sahba-i  ezhâr. 

Ol kül eşcârın mâzisi idi ufacık nihâl,

Geçtikçe ferdâlar şecer oldu bu nihâl

Düşündüm dün-ü gün nedür bu hikmet-i Hudâ

Fehmettim ki misâl-i ahsen ba''s-ü mevt ü fenâ 

Ekinci cûşâ gelür yazarken bu gazeli

Sermest olur ederken temâşâ tâb-ı güzeli.

Yozgat, 1980', 'Erişti nev-bahar oldu dilim gülizâr  Nâle-i mürgân ile doldu âlem pür zâr Bu mevsim-i ferhunde - dem kül-eşcâr Açıldı bir gonce gibi sahba-i...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ekinci']::text[], 8.5, '{"poet":"Mustafa Ekinci","poet_slug":"mustafa-ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/nev-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeşiz biz', 'kardesiz-biz-i-brahim-tamer-dba49', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kültürü ananesi baş döndüren

Yüce Türk evladıyız biz

Kanunuyla kılıcıyla hak getiren

Osmanlı torunlarıyız biz

Anlımız açık olsun,sözümüz mertçe

Fatih sultan mehmet bizden biriydi

Kucaklaşalım hep olalım kardeşçe

Hacıbektaş velii bizden biriydi

Küfür kötü söz yakışmaz bize

Adımız şanımız büyüktür bizim

Hic kimse döğmeye kalkmasın haaa

Tarihte okunan zaferler bizim', 'Kültürü ananesi baş döndüren Yüce Türk evladıyız biz Kanunuyla kılıcıyla hak getiren Osmanlı torunlarıyız biz Anlımız açık olsun,sözümüz mer...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tamer']::text[], 8.5, '{"poet":"İbrahim Tamer","poet_slug":"i-brahim-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kardesiz-biz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu''luyum', 'anadolu-luyum-i-brahim-tamer-kockz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cumhuriyet temelinin atıldığı Sivas''ta doğdum

Sevgi,saygının hoşgörüyle adeta evli olduğu

Alevinin türkü,türkün kürdü, kardeş gördüğü

Anadolu''luyum ben, ben Türkiye''liyim

Pirsultan Abdal yetiştiren bu güzel yurdu

Siper edip göğsünü yiğitçe kanlı cephede

Atatürk''le,alevi, kürt,türk beraber kurdu

Anadolu''luyum ben,ben Türkiye''liyim

Bu vatan için alevi,kürt beraber öldü

Ağladı türk kardeşleri onlara cenaze kıldı

Beraber şehit verildi,beraber silah atıldı

Anadolu''luyum ben,ben Türkiyeliyim', 'Cumhuriyet temelinin atıldığı Sivas''ta doğdum Sevgi,saygının hoşgörüyle adeta evli olduğu Alevinin türkü,türkün kürdü, kardeş gördüğü Anadol...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tamer']::text[], 8.5, '{"poet":"İbrahim Tamer","poet_slug":"i-brahim-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anadolu-luyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Günleri', 'bayram-gunleri-nazli-guller-bwal6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İstanbul''da bir bayram sabahı, 

Bir şubat serinliği, 

Her yerde bir kıpırtı. 

Hasretle kucaklaşmalar 

Heyecanlı sohbetler 

Bak anlatacak ne çok şey var! 

İki lafın arasında, 

Aklım takıldı kaldı 

Başka bir sohbetin 

Zihnimdeki yansımasına. 

Onun özlediğim sözcükleri, 

Buğulandı bakışlarımda. 

Akşam yemeği, 

Müzikli bir meyhane, 

Uzatılan kadehler, 

Neşeli kahkahalar. 

Bedenimin sürüklendiği yerde 

Aldığım keyif, 

Ruhumun sürüklendiği yerdeyse 

Hep özlem var. 

Göremediğim yerlerde 

Düşlerken onu, 

Başka bir yerde, 

Başka bir bayram var. 

Meyhaneden gördüğüm 

Şu manzara, 

Sıcak bir Eylül akşamında, 

Birbirimize sokulurken heyecanla, 

Paylaştığımız aynı manzara. 

Boğaziçinde bir gemi 

Işık ışık, 

Kızkulesi, Üsküdar sahili... 

O da yanımdaymış gibi baktım, 

Ve hasreti gömdüm içime

Bu bayram akşamında.', 'İstanbul''da bir bayram sabahı,  Bir şubat serinliği,  Her yerde bir kıpırtı.  Hasretle kucaklaşmalar  Heyecanlı sohbetler  Bak anlatacak ne ...', ARRAY['Türk Edebiyatı','Şiir','Nazlı Güller']::text[], 8.5, '{"poet":"Nazlı Güller","poet_slug":"nazli-guller","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bayram-gunleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahardan', 'bahardan-ali-furkan-oguz-ibxd3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bahardan da birsey kalmadi aslinda 

ben de o maviligi ariyorum

bircok kez buldugumu sanip

ellerimden akip ugurladim o maviligi bir tren garinda

hem ben hic trene binmedim ki

gunes dogarken

CUNKU HEP YAGMUR YAGIYOR NE ZAMAN ELEKTRİKLER KESİLSE…!', 'bahardan da birsey kalmadi aslinda  ben de o maviligi ariyorum bircok kez buldugumu sanip ellerimden akip ugurladim o maviligi bir tren gari...', ARRAY['Türk Edebiyatı','Şiir','Ali Furkan Oğuz']::text[], 8.5, '{"poet":"Ali Furkan Oğuz","poet_slug":"ali-furkan-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bahardan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı', 'kirmizi-ali-furkan-oguz-txaob', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'zaten bulutlar bile soru isareti 

o yuzden gokyuzu kapalı, 

yagmur yok.

olsun 

yine de sarap kokuyor bileklerim! 

sarap alacak param olmasa bile...', 'zaten bulutlar bile soru isareti  o yuzden gokyuzu kapalı,  yagmur yok. olsun  yine de sarap kokuyor bileklerim!  sarap alacak param olmasa ...', ARRAY['Türk Edebiyatı','Şiir','Ali Furkan Oğuz']::text[], 8.5, '{"poet":"Ali Furkan Oğuz","poet_slug":"ali-furkan-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kirmizi-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuzluğumuza', 'sonsuzlugumuza-ali-furkan-oguz-gsvs0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yagmur yagsa, 

bahar bahar koksa diye bekliyor insan misafir oldugu

koylerde 

ama koyler bile betona donustukten sonra 

sen olsan yagar misin diye fisildiyor yagmur kulagima 

biraz olsun isyan, 

biraz olsun yosun kokusu, 

huznu de beraberinde getirse hani 

...yine kabul 

ama gelmiyor iste gelmiyor bahar 

hasret bahara 

ozgurluk duslere 

isyan 

gozlerdeki kirmiziya 

...gunes dogmadan hemen once 

belki bir damla 

belki sadece bir damla yagmur yagar diye 

...duslerimize, 

SONSUZLUĞUMUZA!', 'yagmur yagsa,  bahar bahar koksa diye bekliyor insan misafir oldugu koylerde  ama koyler bile betona donustukten sonra  sen olsan yagar misi...', ARRAY['Türk Edebiyatı','Şiir','Ali Furkan Oğuz']::text[], 8.5, '{"poet":"Ali Furkan Oğuz","poet_slug":"ali-furkan-oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sonsuzlugumuza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Beni Sevmeyecek Misin?', 'artik-beni-sevmeyecek-misin-muhammed-gacar-l4fm6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaç yıl oldu sen gideli

Hâla geri dönmeyecek misin

Unuttun mu yoksa beni

Artık beni sevmeyecek misin

Sebepsiz yere gittin ellere

Şimdi gözyaşım döndü sellere

İtilip kakıldım atıldım yerlere

Hâla geri dönmeyecek misin

Artık beni sevmeyecek misin

Aşkım canım bir tanem derdin

Sevgi uğruna ne sözler verdin

Bir gülüşünle beni mesut ederdin

Hâla geri dönmeyecek misin

Artık beni sevmeyecek misin

Ellerinin avucumda titrediğini

Gözlerini gözlerimde hissettiğini

Beni hâla delicesine sevdiğini

İnkâr mı edeceksin yoksa her şeyi

Dönmeyecek misin hâla geri

Isparta, 2004', 'Kaç yıl oldu sen gideli Hâla geri dönmeyecek misin Unuttun mu yoksa beni Artık beni sevmeyecek misin Sebepsiz yere gittin ellere Şimdi gözya...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Gacar']::text[], 8.5, '{"poet":"Muhammed Gacar","poet_slug":"muhammed-gacar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/artik-beni-sevmeyecek-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Birşeyler Oldu', 'bana-birseyler-oldu-sahin-erturk-fwf6m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnzivaya çekilmiştim

Söz vermiştim

Yazmayacaktım

Duygularımı dinlendirecektim

Kalbimi dinlendirecektim

Kafamı dinlendirecektim

Ama olmadı,olmadı işte

Tutamadım sözümü

Senden sonra

Bana birşeyler oldu

Kalemim,seni yazmak istiyor

Duygularım,senle olmak istiyor

Kalbim,senin için atmak istiyor

Bana birşeyler oldu güzelim

İnan bana birşeyler oldu

BANA BİRŞEYLER OLDU

(19.04.2005-Yeni)', 'İnzivaya çekilmiştim Söz vermiştim Yazmayacaktım Duygularımı dinlendirecektim Kalbimi dinlendirecektim Kafamı dinlendirecektim Ama olmadı,ol...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bana-birseyler-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '49''Lar', '49-lar-piro-evindare-ipixs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yıl 1959

tarihin duvarları gibi

hücre duvarları da rutubetli

düşer gibi ana rahmine

düşmüşler zalimin hücrelerine

ama niye hücreler kırk tane

ama niye? 

yıl

elli 

dokuz...

kırk

dokuz

kişi

aynı gün

bir rüya görmüşler

ilk defa bir ulus olmuşlar rüyalarında

rüyalarını

yorumlatmak ister gibi bir pire

gitmişler zulmün altında

kırk hücrede buluşmuşlar

ama hücreler niye kırk

ama niye? 

49''lar...

kırk dokuzlar! 

arkanızda milyonlar...

kürdüz demişler hakime

nasıl? 

demiş hakim

yani nasıl bir ulus olabilirsiniz

biz köylerinizi yakmadan nasıl? 

öldürmeden çocuklarınızı nasıl? 

burnunuzdan kan gelmeden

nasıl ulus olursunuz nasıl? 

hakim bunu sormuş

ama ''bizimkiler...

Allah için Can çocuklar''

demişler ki hakim bey

örneğin ''çarçove''

bu bizim kelimemizdir

bu Kurdi''dir

dört çubuk anlamına gelir

way! 

demek dört

demek otuz üç kurşun

demek kırk dokuz ha! 

way! 

demek bütün isyan sayıları bize ait ha

way! 

demek isyan etsek 29 olur

demek bir ülke kursak

çarçove düşman olacak ha! 

way! 

demek yansak 4''lerin gecesi olacak

demek parçalansak dört parça olacak

demek isyan etsek 29 ha! 

way...

evet onlar 49''lar

onlar kırk dokuz kişilik bir halk idiler yani

ama peki

ama peki hücreler niye kırk? 

ama niye? 

yüzü acı ve öfkeyle kavrulmuş bir Kürt

çünkü dedi

daha o zamandandır ki

sığmamışız zulmün zindanlarına

way...

söyleyin bana

söyleyin aynı rüyayı

kaç kişi görebilir

ve yine söyleyin

kim bir halkın rüyasını görür? 

söyleyin

kim bir ''halk rüyası'' görür

bizler...

Şeyh Saidler

Seyyid Rızalar

4''ler

49''lar...

geceleyin güneşin aşkından eriyenler

bizler...

Kürtler....

nisan/2003/Pir', 'yıl 1959 tarihin duvarları gibi hücre duvarları da rutubetli düşer gibi ana rahmine düşmüşler zalimin hücrelerine ama niye hücreler kırk tan...', ARRAY['Türk Edebiyatı','Şiir','Piro Evindare']::text[], 8.5, '{"poet":"Piro Evindare","poet_slug":"piro-evindare","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/49-lar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tehlikeli Şeyler Söylüyorsun', 'tehlikeli-seyler-soyluyorsun-sahin-erturk-53g5p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Farkındamısın bilmem

Tehlikeli şeyler söylüyorsun

Tehlikeli şeyler yazıyorsun

Farkındamısın? 

Aklın başındamı senin? 

Yoksa,yoksa diyorum

Sanada

Benim gibi,birşeylermi oldu...

Duygularına

Benim gibi

Gem vuramıyormusun? 

Kalbin küt.küt diye

18''lik mi çarpmaya başladı? 

Düşlerini

Ben''mi süslüyorum? 

Rüyalarına

Ben''mi girmeye başladım 

Bu gece

Başını ellerinin arasına al

Düşün,bir daha düşün

Ve bana

Açık,seçik söyle BİRTANEM

Şairini seviyormusun? 

SEVMİYORMUSUN? 



(19.04.2005)', 'Farkındamısın bilmem Tehlikeli şeyler söylüyorsun Tehlikeli şeyler yazıyorsun Farkındamısın?  Aklın başındamı senin?  Yoksa,yoksa diyorum Sa...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/tehlikeli-seyler-soyluyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-musa-yasaroglu-ca5ah', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Huzursuzluk katre katre içimde

Umutsuz, mutsuz yaşayan benim

Hayatın değişken yol düzeninde

Yalnızlık denizinde yüzer bedenim

Eklenmiş her hasret bir diğerine

Özleyen, seven, bekleyen benim

Dertlerin yol kesen seferlerinde

Yorulur, çırpınır, kanar yüreğim

Gökler perdelenmiş kuşlar dönüşte

Üzülen,ağlayan, kahrolan benim

Umutlar yitip kanat düşünce

Boşluğu parçalar, taşlar ellerim

Hayatım perişan yüzler önünde

İtilen, atılan, ezilen benim

Ömrün hicranlı her bir gününde

Yaşlarla dolar, taşar gözlerim', 'Huzursuzluk katre katre içimde Umutsuz, mutsuz yaşayan benim Hayatın değişken yol düzeninde Yalnızlık denizinde yüzer bedenim Eklenmiş her h...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalnizligim-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Ya', 'var-ya-musa-yasaroglu-56e74', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kere sevmek var ya seni

Mecnun kadar olmasa da

Uğruna ölmek var ya her bir hayalde

Unutmayıp yatmalardan öce

Rıhtımda senle seyretmek güneşi

Seninle yüzdürmek gemileri denizde

Cihana duyurmak bir de ismini

Anlatılan aşk olmak her an dillerde

Uçmak gibidir her hal masmavi göklerde', 'Bir kere sevmek var ya seni Mecnun kadar olmasa da Uğruna ölmek var ya her bir hayalde Unutmayıp yatmalardan öce Rıhtımda senle seyretmek gü...', ARRAY['Türk Edebiyatı','Şiir','Musa Yaşaroğlu']::text[], 8.5, '{"poet":"Musa Yaşaroğlu","poet_slug":"musa-yasaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/var-ya-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandil gibi yak beni', 'kandil-gibi-yak-beni-yusuf-ziya-leblebici-m276a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ay vururken gecede gözlerinin içine

Gökyüzünde parlayan yıldızda ara beni

Benim sevdam düşünce karanlık gecelere

Yakamozlara inat, kandil gibi yak beni

Çığırtkan sokaklarda duyarsan türküleri

İnan beni anlatır inleyen sazın teli

Şöylesine dalınca hatırla geçenleri

O ela gözlerinde kandil gibi yak beni

Gözünden yağmur yağsa altına tut elini

Düşecek her damlada görürsün gözlerimi

Yağmurumla okşarsam saçının her telini

Hissettiğinde elimi kandil gibi yak beni

Sana göz kırpan yıldız, seni izliyor seni

Bu gün geceler hırsız, seni istiyor seni

Düşündüğün zamanlar getirse mazileri

O hayaller içinde kandil gibi yak beni', 'Ay vururken gecede gözlerinin içine Gökyüzünde parlayan yıldızda ara beni Benim sevdam düşünce karanlık gecelere Yakamozlara inat, kandil gi...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ziya Leblebici']::text[], 8.5, '{"poet":"Yusuf Ziya Leblebici","poet_slug":"yusuf-ziya-leblebici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kandil-gibi-yak-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel İstanbul', 'guzel-i-stanbul-yilmaz-sertbas-1mf95', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1971 yılından beridir,

Birgün değişmedi yüzün,

Dönüyorum işte köyüme,

İçimde kaldı hüzün,

Neyini seveyim İstanbul,

Daracık,cadde,sokaklarını mı,

Mezar gibi konutlarını mı,

Kazılmadık topraklarını mı,

Yürüyemediğim kaldırımlarını mı,

Neyini seveyim İstanbul,

Kesilen elektrik,suyunu mu,

Su çıkmayan kuyunu mu,

Yoksa şans oyunlarını mı,

Başı boş koyunlarını mı,

Neyini seveyim İstanbul,

Çöp dolu köşe başlarını mı,

Sökülmüş kaldırım taşlarını mı,

Gece uçan martı kuşlarını mı,

Mini etekli kızlarını mı,

Neyini seveyim İstanbul, 

Susmayan sarhoş naralarını mı,

Kocaman lağım farelerini mi,

Kuduz kedi köpeklerini mi,

Gürültülü açılan kepenklerini mi,

Neyini seveyim İstanbul,

Köprü altında yatanları mı,

Esrar,kadın satanları mı,

Lokmayı çiğnemeden yutanları mı,

Ceket,pantolon yakanları mı

Neyini seveyim İstanbul,

Kör düğüm trafiğini mi,

Plansız çizilmiş grafiğini mi,

Çıkmayan yolların tarifini mi,

Talan olmuş sahilini mi,

Neyini seveyim İstanbul,

Berduş,kapkaç,hırsızını mı,

Görünmeyen yıldızını mı,

Yerde sürüklenen kızlarını mı,

Kışın buzlanan yollarını mı,

Neyini seveyim İstanbul,

Anten ekilmiş çatılarını mı,

Demirden yapılmış kapılarını mı,

Zehir tüten sobalarını mı,

Ulaşamadığım modalarını mı,

Neyini seveyim İstanbul,

Yağmurdan tıkanan mazgallarını mı,

Balkonda yanan mangallarını mı,

İnşaat önlerindeki kumlarını mı,

Sahte yapılan lokumlarını mı,

Neyini seveyim İstanbul,

Şehir eşkıyası magandalarını mı,

İnsana benzemeyen adamlarını mı,

Kara gözlü bademlerini mi,

Daha birçok nedenlerini mi

Neyini seveyim İstanbul,

Köprü geçiş ücretlerini mi,

Tiyatro,sinema,biletlerini mi,

Kontrolsüz kesilen etlerini mi,

Başıboş gezen itlerini mi,

Neyini seveyim İstanbul,

Kusura bakma gördükleri mi,

Üstüne alınma bildikleri mi,

Vallahi abartısız yazdıkları mı,

Ne sen duy,ne de okuyan,

Neyini seveyim İstanbul,

Şair isen mekansız Yılmaz,

Okuyan sıkıldı az yaz,

Kış gitti geldi yaz,

Biraz tebessüm biraz niyaz,

Neyini seveyim İstanbul......', '1971 yılından beridir, Birgün değişmedi yüzün, Dönüyorum işte köyüme, İçimde kaldı hüzün, Neyini seveyim İstanbul, Daracık,cadde,sokaklarını...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Sertbaş']::text[], 8.5, '{"poet":"Yılmaz Sertbaş","poet_slug":"yilmaz-sertbas","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/guzel-istanbul-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peygamber Sevgisi', 'peygamber-sevgisi-bayram-tunca-qiv2d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ümmetin oluşumuzla övünürüz

Kaybetmiş oluşumuza üzülürüz

Miski amberdir dokun ve kokun

Hala, üzerimizdedir ölüm şokun

Umarız kıyamet günü şefaatinize

İnşallah alırsınız hepimizi safınıza

Nebilerin piri, ölmedi yaşıyor dipdiri

O’nun gelmesiyle silindi beşerin kiri

Dünya, senin gelişinle anlam kazandı

Çünkü yokluğunuzda her yer hazandı

Ey Nebi, benzeyen değil, benzetilensin

Çünkü sen en güzel şekilde bezenensin

Duyduğumuz her sese, kulak kesiliyoruz

Ya gelmenizi/ya gel demenizi bekliyoruz

Nerde adınız anılsa ümmetin boyun eğer

Ümmetim deseniz başımız ta göğe değer

Ümmetin olmamızdandır bu ihsan ve lütuflar

Her adem ahrette şefaat edeceğinizi umutlar

Bencileyin, acizdir edipler seni met-ü senadan

Çünkü seni övmüştür en güzel şekilde Yaratan

Ey Nebi, hakkında ne yazıp söylesem, noksan olur

Bence tüm övgüleri sadakna demek en doğru olur

19.04.2005-17:04', 'Ümmetin oluşumuzla övünürüz Kaybetmiş oluşumuza üzülürüz Miski amberdir dokun ve kokun Hala, üzerimizdedir ölüm şokun Umarız kıyamet günü şe...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/peygamber-sevgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Benim Hallerim', 'ah-benim-hallerim-timucin-gecer-dnrjz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çirkin bir gerdanlıktır hayallerim

sanrılı hayattayım.

bim bam bom dillenmeyeli çok oldu şarkılarımda 

gurursuzluğum sakinsiz bir dünyanın efesi ince bıyıklı

sırıtkan sevdalardan kopalı çok oldu.

düşüncelerim beklenmedik misafir her saatte

aşkım en kısır rahimler kadar karanlık

sabahın en erken saatleri kurulurken guguklu saate

kahrolası bir alışkanlıktır kırılgan başlangıçlarım

her sabah semirir içimde büyüttüğüm domuzcuk 

kenarları dantelalı bir şapkadır çirkinliğim devrim fransasında

selamsız girerim her kavgama ve korkaktır dövüşüm

pasif loralara boğulmuşum sakinliğim serseri bir tufandır

yiten her engininde bilinmedik okyanusların

en fahişe halidir bu bende yiten duyguların

migrenim tutmuş başımda bremen mızıkacıları

içmemişim uykusuzum sabahçı kahvesinde bekleyen sırdaşım tüm sabahçılara 

kendi hallerine aşinayım.

akşam olmamış ne umur içime çektiğim sigaranın 

dumanında sarhoşum en rakılı hallerde

sevgilim sabah öpmeden çıkmış evden ve akşam döndüğünde 

tüm maceralardan ötede kemirir sevdamızı gizli saklı

gökyüzünde asılı keman sesleri 

sergüzeşt-i aşk a kapılmış hülyalarım 

ah benim hallerim... sanrılı hayattayım.', 'çirkin bir gerdanlıktır hayallerim sanrılı hayattayım. bim bam bom dillenmeyeli çok oldu şarkılarımda  gurursuzluğum sakinsiz bir dünyanın e...', ARRAY['Türk Edebiyatı','Şiir','Timuçin Geçer']::text[], 8.5, '{"poet":"Timuçin Geçer","poet_slug":"timucin-gecer","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ah-benim-hallerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Son Kez**', 'son-kez-burcu-alpaslan-guvenli-cht9e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yer var, biliyorum; 

Her şeyi söylemek mümkün; 

Epeyce yaklaşmışım, duyuyorum; 

Anlatamıyorum

................................Orhan Veli Kanık

Son kez 

Sarıl hadi

durma 

Ellerini koy saçlarıma 

yüzün başımın üzerinde uyu 

uyuduğunu anlamalıyım 

ağırlığından...

Ben kesik kesik nefes alırım /seni görünce

ama sen başımdayken uydururum nefesine nefesimi

sevmem gibi tıpkı

yolda yürürken adımlarımı adımlarına uydurmayı 

Düşüncesiz bir çocuğum ben bir o kadar şımarık

hayatımda gördüğüm en iyi baba sensin 

bazen deliririm ki bu benim ruhum

beni nasıl izlersin biliyorum.... öyle gülen göz görmedim ben! 

Bizi her sevdiğinde içimizden bir şeyler göçer

biz- ben ve uzuvlarım-

içimize saldıkların tepelenir durur ya

çıksa çıkamaz  / kalsa kalamaz 

biz ne yapacağımızı şaşırmış bir sürü organ...

bir o kadar da doğurgan...

Ne senden bebe yapabildik

ne de beben olabildik...

Haddimize değildi

arsızca zaman çaldık Tanrıdan belki

Birer hırsızız artık 

Biraz daha zaman var çalınacak 

Var var biliyorum  / görüyorum 

ama...

Tut elimi Orhan Veli zamansızlığımı anlatamıyorum...', 'Bir yer var, biliyorum;  Her şeyi söylemek mümkün;  Epeyce yaklaşmışım, duyuyorum;  Anlatamıyorum ................................Orhan Veli...', ARRAY['Türk Edebiyatı','Şiir','Burcu Alpaslan Güvenli']::text[], 8.5, '{"poet":"Burcu Alpaslan Güvenli","poet_slug":"burcu-alpaslan-guvenli","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/son-kez-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöl', 'col-sibel-maral-dve9u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya, sevgisizlikten çöl olmuş,

Sevenlerin gözyaşıymış,

Bu çölde görülen seraplar...', 'Dünya, sevgisizlikten çöl olmuş, Sevenlerin gözyaşıymış, Bu çölde görülen seraplar......', ARRAY['Türk Edebiyatı','Şiir','Sibel Maral']::text[], 8.5, '{"poet":"Sibel Maral","poet_slug":"sibel-maral","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/col-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir Yazacağım', 'bir-siir-yazacagim-i-brahim-yavuz-lb5vx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gün karşılaşırsak ilk işim bu olacak 

Bana son oynadığı oyunu bozacağım 

Bir ırmak gibi akıp gönüllere dolacak 

Ona hiç duymadığı bir şiir yazacağım

Sevenler sevilenler hep bizi ansın diye 

Duyunca vefasızın yüreği yansın diye 

Bana yaptıklarından biraz utansın diye 

Ona hiç duymadığı bir şiir yazacağım

Gönlümü alıştırdı ıstıraba eleme 

Bana yaptığı zülüm ibret olsun aleme

Son çarem diye şimdi sarılmışım kaleme 

Ona hiç duymadığı bir şiir yazacağım

Bir ömür geldi geçti güldürmedi yüzümü 

Büyülenmiş gibiydim kör etmişti gözümü 

Kararlıyım bu defa tutacağım sözümü 

Ona hiç duymadığı bir şiir yazacağım

Diviti mürekkebe batırmış bekliyorum 

Yüreğimi pusuya yatırmış bekliyorum 

İlham gelecek diye oturmuş bekliyorum 

Ona hiç duymadığı bir şiir yazacağım

Hedefe kilitlendim nişan alarak gezden 

İntikam alacağım ben o sürmeli gözden 

Kurtulma şansı hiç yok anlarsa güzel sözden 

Ona hiç duymadığı bir şiir yazacağım', 'Bir gün karşılaşırsak ilk işim bu olacak  Bana son oynadığı oyunu bozacağım  Bir ırmak gibi akıp gönüllere dolacak  Ona hiç duymadığı bir şi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Yavuz']::text[], 8.5, '{"poet":"İbrahim Yavuz","poet_slug":"i-brahim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-siir-yazacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '+Hayatın Dansı', 'hayatin-dansi-zeki-ergin-r46ur', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'aklım 

geçmişin süzgeci

duygularım mayasıdır

dünden yarına

aklımla duyguların dansıdır hayat

beni ben yapan

ve hayat yapısını ayakta tutan

__ezine 19nis''05', 'aklım  geçmişin süzgeci duygularım mayasıdır dünden yarına aklımla duyguların dansıdır hayat beni ben yapan ve hayat yapısını ayakta tutan _...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayatin-dansi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lorî', 'lor-cigerxw-n-0w3af', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'De lorî, lorî kurê min lorî

Bavê te kuştin dayik bi gorî

Gernas û mêrxas divê tu negrî

Millet ku sax bî nema tu dimrî

De lorî…

Millet şiyar e gelek gihaye

Tiving bi dest e li ser çiya ye

Şêr û piling in, hawîr dibazin

Doza me Kurdan, serbest dixwazin

De Lorî…

Bi xwîn nivîsîn li ser zinara

Li vir nemaye cihê neyara

Biqeşte dijmin, qada me berde

Ew der welatê gernasê Kurd e

De lorî…

Dijmin bi top û firok û leşker

Bumbardûman kir welat li her der

Hilweşandin tev mizgeft û dîwar

Kûr kûr dinalin, jar û birîndar

De lorî…

Zar û zêçên Kurd, pir têne kuştin

Dexl û rez û pez, tiştek nehiştin

Tazî û birçî, bin banger û berf

Wan naveşêrin, şikeft û berqef

De lorî…

Li ser zikên xwe diçin bi mestî

Din dest û hin pê, hin ser şikestî

Di şevreşan de gernas û rêber

Şêrên birîndar, dema diçin şer

De lorî…

Dijmin ji tirsan dişkên û dimrin

Derbend û rêçan li ber digrin

Ji wî distênin derb û berên xwe

Xwedî dikinpê em leşkerê xwe

De lorî

Serdar bilind e rêzan û mêr e

Zêrên serê xwe bişênim jê re

Bere bişroşî, bidî bi şeşar

Berdî dijmin û neyar

De lorî

Qada me berdin ji bo me yek ser

Aştî dixwazin, me navê ev şer

Em jî wekî xwe divên serbestî

Ma ki dixwezî, dîlî, bindestî? 

De lorî…

Cigerxwîn', 'De lorî, lorî kurê min lorî Bavê te kuştin dayik bi gorî Gernas û mêrxas divê tu negrî Millet ku sax bî nema tu dimrî De lorî… Millet şiyar ...', ARRAY['Türk Edebiyatı','Şiir','Cigerxwîn']::text[], 8.5, '{"poet":"Cigerxwîn","poet_slug":"cigerxw-n","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/lori-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşamlar Duvar Bana', 'aksamlar-duvar-bana-ali-osman-yilmaz-k5buh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kuş seslerinin kaybolduğu,

Yıldızsız  zamanlarda,

Kapkara bir duvar sanki,

Akşamlar bana.

Gözlerim yıldızlarda,

Seni görmek ister gibi,

Zindan gecelerin,

Karanlığında', 'Kuş seslerinin kaybolduğu, Yıldızsız  zamanlarda, Kapkara bir duvar sanki, Akşamlar bana. Gözlerim yıldızlarda, Seni görmek ister gibi, Zind...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aksamlar-duvar-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martılar bu gece,Deniz''i terketmiş.', 'martilar-bu-gece-deniz-i-terketmis-ali-osman-yilmaz-3ik0w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fırtına patlamış yine,

Deniz çılgınlar gibi,

Saldırdıkça kıyıya,

Islatıyor beni.

Tuzlu bir ıslaklık üstümde,

Denizin göz yaşları sanki,

Belli ki o da bu gece,

Benim gibi yapa yalnız.

Sordum usulca denize,

Martılar,denizi terk etmiş,

O yüzden bu gece,

Deniz böyle hırçınmış.', 'Fırtına patlamış yine, Deniz çılgınlar gibi, Saldırdıkça kıyıya, Islatıyor beni. Tuzlu bir ıslaklık üstümde, Denizin göz yaşları sanki, Bell...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/martilar-bu-gece-deniz-i-terketmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Mevsimi Gelmekte', 'hazan-mevsimi-gelmekte-ali-osman-yilmaz-cy14r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneş Sapsarı,

Ve rüzgar mavi gözleriyle,

Yaz sıcaklığını esmekte,

Bekleyin biraz,bekleyin,

Hazan mevsimi gelmekte.', 'Güneş Sapsarı, Ve rüzgar mavi gözleriyle, Yaz sıcaklığını esmekte, Bekleyin biraz,bekleyin, Hazan mevsimi gelmekte....', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hazan-mevsimi-gelmekte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Varmı? Ha! ! !', 'haberin-varmi-ha-ali-osman-yilmaz-45fk3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kim bilir ki? 

Yapayalnız,

Bir söğüt ağacının altında,

Yalnızlığa yatanların sırrını? 

Söğüt yaprakları,

Dere kenarlarında,

Söylerken,

Yalnızların türküsünü,

Kim duyar? Kim dinler? 

Su şırıltısının arasında,

Kimin haberi olur ki? 

Mesela senin dostum? 

Arkadaşım? 

Haberin varmı? ...Ha! ! ! !', 'Kim bilir ki?  Yapayalnız, Bir söğüt ağacının altında, Yalnızlığa yatanların sırrını?  Söğüt yaprakları, Dere kenarlarında, Söylerken, Yalnı...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/haberin-varmi-ha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Aşıksam', 'ben-asiksam-hasan-can-1e7su', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben aşıksam,

Şarkıları hep gece söylerim,

Şiirleri ıssız bir köşede yazarım,

Gözyaşlarımı yağmurlara bırakırım.

İçimde bir acı varsa eğer,

Sessizliğin hakim olduğu o anı,

Yani geceyi beklerim,

Acının karanlığa bürünmesi için.

Ben hep sessizliğin hakim olduğu o anı sevdim,

Sadece yarasaların kulakları azda olsa okşaması,

Ve ateş böceklerinin kendilerince ışık saçmasını.

Ben geceyi sevdim, karanlık ve sessiz olduğu için değil,

Seni bana acı vermeden hatırlattığı için.

Şimdi gözyaşlarımın silinmesi için yağmuru bekliyorum.

Aniden gelip, usulca gözlerimden alıp götürsün diye...', 'Ben aşıksam, Şarkıları hep gece söylerim, Şiirleri ıssız bir köşede yazarım, Gözyaşlarımı yağmurlara bırakırım. İçimde bir acı varsa eğer, S...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ben-asiksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ten, sen ve ışık', 'ten-sen-ve-isik-orhan-demirtas-r5y2g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'aşkınla teni aşıp cana ulaştım

sen,

........ışık ustası kadınım

söyle,

.......gittiğim her yerde neden durursun? 

yoksa,

..........içimde ateş bahçesi

.........................ve 

....gönlümde sonsuzluğummusun? 

Orhan DEMİRTAŞ', 'aşkınla teni aşıp cana ulaştım sen, ........ışık ustası kadınım söyle, .......gittiğim her yerde neden durursun?  yoksa, ..........içimde at...', ARRAY['Türk Edebiyatı','Şiir','Orhan Demirtaş']::text[], 8.5, '{"poet":"Orhan Demirtaş","poet_slug":"orhan-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ten-sen-ve-isik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Grift', 'grift-erol-dal-88oy2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Feryat; 

Bir gün yükselecek…

Ve sen,

Ve ben,

Göremeyeceğiz…

Bizler doğru önünde yılların harcadığı bir nefes kadar

soğuk; 

yaşama sıcak olduğumuz kadar da 

yakın; 

ÖLECEĞİZ…', 'Feryat;  Bir gün yükselecek… Ve sen, Ve ben, Göremeyeceğiz… Bizler doğru önünde yılların harcadığı bir nefes kadar soğuk;  yaşama sıcak oldu...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/grift-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Darağacı', 'daragaci-orhan-demirtas-zokrb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugünlerde bir hayli Sensizim

ve bir lokma nefes bile girmiyor kursağıma

Ey yar

......ölümler üretiyor beynim

.............intiharlar kol geziyor avuçlarımda

Ve biliyorum ki, eninde sonunda

.........................................mutlak bir anda

önce gözyaşlarımı

.......................sonra soluğumu asacağım

.............yokluğunun dar-ağacına

Orhan DEMİRTAŞ', 'Bugünlerde bir hayli Sensizim ve bir lokma nefes bile girmiyor kursağıma Ey yar ......ölümler üretiyor beynim .............intiharlar kol ge...', ARRAY['Türk Edebiyatı','Şiir','Orhan Demirtaş']::text[], 8.5, '{"poet":"Orhan Demirtaş","poet_slug":"orhan-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/daragaci-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dip', 'dip-erol-dal-97eux', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Feryat; 

Bir gün yükselecek…

Ve sen,

Ve ben,

Göremeyeceğiz…

Bizler doğru önünde yılların harcadığı bir nefes kadar

soğuk; 

yaşama sıcak olduğumuz kadarda 

yakın; 

ÖLECEĞİZ…', 'Feryat;  Bir gün yükselecek… Ve sen, Ve ben, Göremeyeceğiz… Bizler doğru önünde yılların harcadığı bir nefes kadar soğuk;  yaşama sıcak oldu...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dip-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendeki İstanbul', 'bendeki-i-stanbul-esin-aslan-evrub', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aklım karışıyor sana baktıkça; 

İstanbul, vefasız yarim gibisin.

Ruhumu kuytuda ansızın saran

Kurtulamadığım hüzün gibisin...

Özlemi sietme dönüştürmeden,

İstanbul, sabırla seven gibisin; 

Cesaret edip de açamadığım

Kalbimin sırrını bilen gibisin...

istanbul; sevgiye doymayan aşık,

Uyutamadığım sızım gibisin.

Aynanın sırrına karışıp yitmiş,

Güldüremediğim yüzüm gibisin...', 'Aklım karışıyor sana baktıkça;  İstanbul, vefasız yarim gibisin. Ruhumu kuytuda ansızın saran Kurtulamadığım hüzün gibisin... Özlemi sietme ...', ARRAY['Türk Edebiyatı','Şiir','Esin Aslan']::text[], 8.5, '{"poet":"Esin Aslan","poet_slug":"esin-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bendeki-istanbul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sevdam', 'benim-sevdam-dursun-elmas-t9o6d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Parlayan gözlerin bir hayâl oldu

Öpüp sevmeyeli hayli yıl oldu.

Kurudu gözeler,dilim lâl oldu

Seni mısralara koyamıyorum...

Uykularımda sen,düşlerimde sen! 

Ne kadar doluyum senle bir bilsen! 

Açsam yüreğimi,içini görsen

Sana bakmalara doyamıyorum...

Benim sevdam; kimselere benzemez.

İstersem severim,istersem sevmez; 

Buna sevda değil,sevgi hiç denmez

Seni sevmelere kıyamıyorum...', 'Parlayan gözlerin bir hayâl oldu Öpüp sevmeyeli hayli yıl oldu. Kurudu gözeler,dilim lâl oldu Seni mısralara koyamıyorum... Uykularımda sen,...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benim-sevdam-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nem Kaldı (yağmur Güzeli)', 'nem-kaldi-yagmur-guzeli-orhan-demirtas-zxt51', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sevdan bir nehir-ken sıcak bağrımda

gözlerimde gözlerinin

....................................izleri kaldı

yeşil düşlerim benden uzakta

gözümdeki yaştan başka

..............................nem kaldı

uzaklarda yaşayan yağmur güzeli

biliyorum yakarsam, yakarışlarımdan 

...................................sen boy verirsin

ve biliyorum

........hiç bir yakarışım seni getirmez bana

hayalimde olan senden başka

..........................................nem kaldı

kış gibi soğuk ve düş gibi serince

ne oldu söyle

...........ne oldu bizim yeşil mevsimlerimize

hasatsız yanan özlemlerden başka

..............................................nem kaldı

sen dur gece hüznü sevdam

.......................................ne olursun dur

dur da yerine ben öleyim

aldığım nefeslerde bir tek sen yaşa

..........ölüm yağmurlarında ben kalayım

hazan mevsimlerden

......ve soğuk ayaz gecelerden başka

..............................................nem kaldı

vurgun yanıyorum fırtınalı geçen günlerimde

kokunu özlüyorum, kokunu, yağmur güzeli

..............uzaklarda için için kanamam sana

saçının telini beklerken rüzgarlardan bana

belkilerden, belki gelir demekten başka

....................................................nem kaldı

sen kanıyorsun içimde

......................ağır yanık sızılarım kanıyor

ellerinin teni hala ellerimde yanıyor

kırık düşlerden

..................solan mevsimlerden

............................boynu bükük bir ömürden

ansızın ve delice ölmeyi beklemekten başka

......................................................nem kaldı

Orhan derki gönlüm yastadır

....yıllar gelip geçti kalbim hastadır

..........yangın oldu beden ateş ustadır

cehennem narından başka

...........................................nem kaldı

Orhan DEMİRTAŞ', 'sevdan bir nehir-ken sıcak bağrımda gözlerimde gözlerinin ....................................izleri kaldı yeşil düşlerim benden uzakta gözü...', ARRAY['Türk Edebiyatı','Şiir','Orhan Demirtaş']::text[], 8.5, '{"poet":"Orhan Demirtaş","poet_slug":"orhan-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/nem-kaldi-yagmur-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilen', 'bilen-goksel-dogru-0207y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(M''ilad''a) 

Ne şarkılarda aradım mutluluğu

Ne de belik belik örülmüş

Bir tutam saçta

Bilirim onu bu dünyada bulamam

Bulsamda tutamam avuçlarımda

Onun içindir varsın geçsin

Günler, aylar, yıllar

Varsın gelsin ömür son demine

Bilirim,ancak oradadır sonsuz saadet

Nasıl gideceğini bilene

(Ekim 2002, İzmir)', '(M''ilad''a)  Ne şarkılarda aradım mutluluğu Ne de belik belik örülmüş Bir tutam saçta Bilirim onu bu dünyada bulamam Bulsamda tutamam avuçlar...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçin', 'i-cin-goksel-dogru-1sr6f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(Çırakman''a) 

Eskiyor yüzler! 

Çocuklar evlendi,

Çocuklarını büyütüyor.

Dün göçenler toprak oldu,

Külleri savruluyor.

Ağaçlar fidandı,

Boy değil, boylar aşıyor.

Her şey,

Görmeyi bilmeyenin gözüyle

Hala aynı duruyor.

(Ağustos 2002, Samsun)', '(Çırakman''a)  Eskiyor yüzler!  Çocuklar evlendi, Çocuklarını büyütüyor. Dün göçenler toprak oldu, Külleri savruluyor. Ağaçlar fidandı, Boy d...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/icin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Sevgi', 'adi-sevgi-orhan-demirtas-0dnrd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kökleri bedenimin

......en ince ayrıntılarına uzanan

.........................olgun bir nar çiçeği

yüreğimde yanan sevdanın ateşi

......onu gönlümde eşsiz bir güle çevirdi

bu bir tapınak olmalı

..............................adı sevgi

bin yılların özlemi gibi ağlıyorum

ve yüzünün gölgeleri uzanıyor önüme

...........................................tutamıyorum

..........onurum adaleti özlüyor

Orhan DEMİRTAŞ', 'kökleri bedenimin ......en ince ayrıntılarına uzanan .........................olgun bir nar çiçeği yüreğimde yanan sevdanın ateşi ......onu ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Demirtaş']::text[], 8.5, '{"poet":"Orhan Demirtaş","poet_slug":"orhan-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/adi-sevgi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanayan Dağlar', 'kanayan-daglar-abdullah-oral-1iabc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaç tarih sığar bir takvime

Vurulur duvarların önünde 

Akşamlar saklar sesini namlunun

Çıplak bedenler döner durur yivlerde

Yada kaç umut tutsak

Nişangahında Soğuk namlunun

Kanayan dağlarında yurdumun

Eksik kalıyor bütün anlatımlar

Kollarına düştüğüm nehirler bilir

Şarapnel yemiş gibi hırçın.

Hançerlenir gözlerimde kamaşan sular.

Ağzımda sızılı tadı pas tuttu tütünün

Ey kendine çekilmiş gözlerim uyan.

Seni benden sökmek isterler

Bakışlarımı silmek gülüşlerimden

Kent ayaklanıyor fırtına sesiyle

Yüreğim kabına sığmıyor gayrı

Alıcı kuşlar pek te severler ölüm çığlığını.







Güneş ölüleri terletmez

Öldürenlere bıraktık terlemeyi.

Tam beş yıldır yaşamayı öğrendik ölümle

Koyun kuyuna sırt sırta ve omuz omuza

           

Pimi çekilmiş sabahlarda 

Yalın bir bıçak gibi bilenir öfke

Oturur yanı başına isyanın 

Ateşini bedenlere salarken kurşun.

Kimyasal gazlarla yaktılar gözlerimi. 

Direncin karşısında şaşkın.

İğdiş edilmiş keşiş edasıyla bağırırken cellat

Salyalı dudaklarından 

Dökmekteydi hırıltılar. teslim olun 

Aciz bir itin ekmeğe havaması gibi..

Değil dirileri teslim almak

Ölülerimiz direniyor teslimiyete

Yaşanan her anın hesabı sorulur diyerek.

Bakmayın nehirlerin coşkulu akışına

Kanayan dağlarıdır yurdun. 

Et tırnak gibi sökülüp dağlanan

Ve anaların gözleri değil dökülen 

Baharıdır aydınlığı ülkemin.............

Abdullah Oral 

                                                         Eylül 15 2004', 'Kaç tarih sığar bir takvime Vurulur duvarların önünde  Akşamlar saklar sesini namlunun Çıplak bedenler döner durur yivlerde Yada kaç umut tu...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kanayan-daglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurla Giden Mektup', 'yagmurla-giden-mektup-goksel-dogru-9er58', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(M''ilad''a...) 

Sana,

Kurumuş yağmur damlaları ile dolu

Sayfalar dolusu 

Sen gönderiyorum 

Biraz da 

Hüzün çığlıkları geceyi yaran 

Ben.

(Ağustos 2002, Samsun)', '(M''ilad''a...)  Sana, Kurumuş yağmur damlaları ile dolu Sayfalar dolusu  Sen gönderiyorum  Biraz da  Hüzün çığlıkları geceyi yaran  Ben. (Ağu...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yagmurla-giden-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Öldürmez', 'olum-oldurmez-abdullah-oral-ul2r6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu şehir her şeyi çürütüyor kendi içinde

Et tırnağı diş damağı

Omuzlarımdan ellerim dökülüyor

Gözlerim,

İçimdeki hapis duyguların tutsağı

Kaç kez kaçmayı düşündüm

Yıkıp duvarlarını esaretin

Doğduğu yere güneşin

Kent dışı özlem sarhoşluğuna

Sürgünlük ağrılarıyla ağlayanların 

Yurtsuzluk ağrıları dökülürmüş 

                          Yanaklarından.

Bir şeyler bulup yitirmiş gibi

Sancıda nasırlı ellerimde zincir

Prangalarım 

Gidersem dayanamaz bensizliğe

Çürür dökülür hasretimden

O kadar uzak duruyor ki yaşam bizden

Ne günü yaşaya biliyoruz

Nede yaşatabiliyoruz umudu

Sessiz bir ölü gibi sokaklar 

Gayrı suskunluk öldürür de beni

                   Ölüm öldürmez

Abdullah Oral 

                                                        EKİM 2003', 'Bu şehir her şeyi çürütüyor kendi içinde Et tırnağı diş damağı Omuzlarımdan ellerim dökülüyor Gözlerim, İçimdeki hapis duyguların tutsağı Ka...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Oral']::text[], 8.5, '{"poet":"Abdullah Oral","poet_slug":"abdullah-oral","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/olum-oldurmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuğum', 'cocugum-orhan-demirtas-9fby6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'melekler gezinir

........................yattığın yerde

ey günüme hayat veren çocuğum

........................................................uyu

bir gün yarin hasretiyle yüreğin titrer de

........anarsın bu derin 

..................................tatlı uykuyu

ORHAN DEMİRTAŞ', 'melekler gezinir ........................yattığın yerde ey günüme hayat veren çocuğum .........................................................', ARRAY['Türk Edebiyatı','Şiir','Orhan Demirtaş']::text[], 8.5, '{"poet":"Orhan Demirtaş","poet_slug":"orhan-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cocugum-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konya''dan geçerken', 'konya-dan-gecerken-goksel-dogru-c1mm7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(çekirdek''e) 

İnsanlar yaşıyor    

Bu soğuk diyarda    

Sıcak sımsıcak yürekleri,    

Isıtıyor başka yürekleri    

Bir gece vakti     

Yol üstüyken geçtiğim bu şehirde     

Isınan yüreğim uyandırdı beni.  

Isıttı benim de yüreğimi  

Bir başkasının yüreği.

Oysa ki tanımam etmem ne bu şehri  

Ne de bu şehrin gecesinde 

Yaşayan yürekleri   

O muydu içimi ısıtan,    

Yoksa bir ürpertimiydi    

Sesini duymadığım, 

Yüzünü görmediğim    

Biri vardı, bir hayaldi

Yoksa o hayal buradamıydı şimdi?     

Belki de kardı sebebi   

Isıtmak için kendimi 

Avuttum kendimi bu yürekle     

Kimbilir

Düşlediğim buydu belki de…

(Aralık 2001, Konya)', '(çekirdek''e)  İnsanlar yaşıyor     Bu soğuk diyarda     Sıcak sımsıcak yürekleri,     Isıtıyor başka yürekleri     Bir gece vakti      Yol ü...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/konya-dan-gecerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-goksel-dogru-j0l7l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(bir hayale dair...) 

O''na ilk kez

''Seni seviyorum'' dedim.

Şimdi ne yapıyor bilmem

İçindeki nefret mi sevgi mi 

Onu da bilmem

Ne farkeder ki

Hissettiği ne olursa olsun

Ömründe ilk kez 

Beni düşünüyor...

(17 Mart 1993, İzmir)', '(bir hayale dair...)  O''na ilk kez ''Seni seviyorum'' dedim. Şimdi ne yapıyor bilmem İçindeki nefret mi sevgi mi  Onu da bilmem Ne farkeder ki...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/itiraf-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitirme Beni', 'yitirme-beni-orhan-demirtas-nydqv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'duy sesimi

...........gel de,

....................güzelliğinle yıka içimi

yangınıma razıyım

............razıyım ateşten bahçelerden geçmeye

yeter ki bileyim duyduğunu sesimi

gel de,

..........bir boşluğun bilinmezliğinde

......................................................yitirme beni

Orhan DEMİRTAŞ', 'duy sesimi ...........gel de, ....................güzelliğinle yıka içimi yangınıma razıyım ............razıyım ateşten bahçelerden geçmeye ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Demirtaş']::text[], 8.5, '{"poet":"Orhan Demirtaş","poet_slug":"orhan-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yitirme-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hayale Dair', 'bir-hayale-dair-goksel-dogru-h31mp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(bir hayale dair...) 

Ben O''na layıkmıydım? 

O bana layıkmıydı? 

İkimiz de değildik 

Hiç olmadık.

Bir hayale dairdi,

Tüm düşlerim, düşüncelerim

Bu yüzdendir,

Hiç olmazdık.

(17 Mart 1993, İzmir)', '(bir hayale dair...)  Ben O''na layıkmıydım?  O bana layıkmıydı?  İkimiz de değildik  Hiç olmadık. Bir hayale dairdi, Tüm düşlerim, düşüncele...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-hayale-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mö-Ms', 'mo-ms-goksel-dogru-8kldg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(M''ilad''a) 

M’den önceleri de 

İçinde M olmayan 

“M’den sonraları” yaşadım.

Bir milat gibiydi hepsi.

s,e,n... 

ve içinde sairesi

S’den öncesi karanlık çağ

Yakın çağ N’den sonrası

Şimdilerde varsa yoksa 

M’den öncesi değil, M’den sonrası

(Kasım 2001, İzmir)', '(M''ilad''a)  M’den önceleri de  İçinde M olmayan  “M’den sonraları” yaşadım. Bir milat gibiydi hepsi. s,e,n...  ve içinde sairesi S’den önces...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mo-ms-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fatih''in Mirası', 'fatih-in-mirasi-halil-kesken-2rud0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Fatih’in mirası; canım, ciğerim İstanbul

Senden başka hangi şehirde karadan gemiler gitmiştir? 

Senden başka hangi şehir Mehmed’i Fatih etmiştir? 

Evim bildim, vatanım bildim ben seni

Denizine çöp atılıyor diye boynunu bükme,

Ne olur, sevmediniz diye gözyaşı dökme

Fatih’in mirası; canım, ciğerim İstanbul

Her yolu düşene kollarını açan şehir

Ekmek veren şehir, su veren şehir

Üsküdar’dan, Çamlıca’dan, Tarabya’dan seyrettim seni

Ağaçların kesiliyor diye boynunu bükme

Ne olur, sevmediniz diye gözyaşı dökme

Fatih’in mirası; canım, ciğerim İstanbul

İlkokul çağında, coğrafya kitabında sevmiştim seni,

Bir boğaz turunda, sırılsıklam aşık oldum

Hazreti Peygamber’den Mustafa Kemal’e kadar

Kimler sevmedi ki seni; canı kadar, ciğeri kadar

Kıymet bilmiyorlar diye boynunu bükme

Ne olur, sevmediniz diye gözyaşı dökme

Fatih’in mirası; canım, ciğerim İstanbul

Mimar Sinanımız’ın çalışma alanı

Aşıklarımızın buluşma alanı

Yeryüzündeki bütün dinlerin kaynaşma alanı

Yüzlerce milletin gözü var sende,

Fatih’in, askerinin,

Bu ülkenin milyonlarca neferinin izi var sende

Ulubatlı Hasan’ın şehadeti var,

Müslüman halkının ibadeti var sende...

Değer vermediniz diye boynunu bükme,

Ne olur, sevmediniz diye gözyaşı dökme

Canımız kadar, ciğerimiz kadar sevdik seni,

Güneşin kadar, denizin kadar, boğazın kadar sevdik seni,

Fatih’in mirası; canım, ciğerim İstanbul

19.04.2005', 'Fatih’in mirası; canım, ciğerim İstanbul Senden başka hangi şehirde karadan gemiler gitmiştir?  Senden başka hangi şehir Mehmed’i Fatih etmi...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/fatih-in-mirasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmece', 'bilmece-goksel-dogru-14bfy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'en yakını 

bir nefes kadar uzak

nefes alamadığım gün 

o da duracak', 'en yakını  bir nefes kadar uzak nefes alamadığım gün  o da duracak...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bilmece-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk', 'i-lk-goksel-dogru-enmxy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayrılık çanları çalıyor 

Akşamın dördünde

Almışım elime sigarayı

İçime çeker O''nu ölürüm.

(17 Mart 1993, Kordonboyu)', 'Ayrılık çanları çalıyor  Akşamın dördünde Almışım elime sigarayı İçime çeker O''nu ölürüm. (17 Mart 1993, Kordonboyu)...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ilk-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Platonik I', 'platonik-i-goksel-dogru-8sqo1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'uzak diyarlarda bir kentte

bir delikanlı

bir kızı sevmiş

kızın haberi olmamış

yine aynı kentte

yine delikanlı ve kız 

delikanlı artık hep aynı yerde! 

kız bunu hiç bilmemiş

(Kasım 2001, Samsun)', 'uzak diyarlarda bir kentte bir delikanlı bir kızı sevmiş kızın haberi olmamış yine aynı kentte yine delikanlı ve kız  delikanlı artık hep ay...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/platonik-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyemediklerimi biriktirdim II', 'soyleyemediklerimi-biriktirdim-ii-goksel-dogru-qhdz6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(M''ilad''a)      

Söyleyemeyip biriktirdiklerim vardı

Yazmaya çabaladıkça anladım ki

Dünden bugüne bütün yazdıklarım

Zaten söyleyemediklerimmiş 

Hiç olmamış sevgiliye

Ve asıl derdim

Yaşayamadan o sevgiliyle

İçimde öldürdüklerimmiş

(Temmuz 2002, İzmir)', '(M''ilad''a)       Söyleyemeyip biriktirdiklerim vardı Yazmaya çabaladıkça anladım ki Dünden bugüne bütün yazdıklarım Zaten söyleyemediklerimm...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/soyleyemediklerimi-biriktirdim-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Seninle', 'kalbim-seninle-ayse-birgul-yilmaz-d9tk7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Böyle ansızın bir güz mevsiminde

Neydi, nereden esti geldi bu fırtına

Köhnemiş metruk harabe yüreğime

Kalbim dosdoğru sevda eğiminde

Sana sevgimi anlattım durdum şiirlerce

Belki de var gibiydin benim dünyamda

Hep yanından geçtin aşkımın, günlerce

Düşündüm, bekledim seni ümitlerimce

Susmalı mı, konuşmalı mıyım, şaşkınım

Biraz da şaşırmayı seviyorum herhalde

Bakışlarım, bilinmeze açılan bir pencere

Sudaki görüntüye bakarcasına dikkatli ve

Ruhumun karmaşık dalgalanmaları içinde

Çırpınıyorum kararsız huzurlu bir sevinçle

Umut ver ışık tut bil ki her şey senin elinde

Hayata dönebilirim belki yeniden sevginle

Kalbimi dinle, kalbini dinle, kalbim seninle



19/05/2005', 'Böyle ansızın bir güz mevsiminde Neydi, nereden esti geldi bu fırtına Köhnemiş metruk harabe yüreğime Kalbim dosdoğru sevda eğiminde Sana se...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kalbim-seninle-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-goksel-dogru-1l2he', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İşte şu anda ilk kez açık ve net okuyorsun duygularımı. Bu küçük bir

deneme sadece, başlılar halinde yazılmış bir önsöz ya da index

diyebilirsin. Genele değil sana özel hissettiklrimdir. Duygusuzluğum için

özür diliyorum.Kalpsizliğim için de... İkincisi olmayabilir ya da üçüncüsü

, ''dur'' ve ''git'' demen yeter!  

      İlk; 

      Daha uyanmadan başlıyor sana hasretliğim. Rüyalar görüyorum rüya

içinde. Aradığım yalnızca sensin, düşünce hızıyla ulaştığım dünya ötesi

diyarlarda bile...Ama yoksun! 

      Gecenin sabaha yakın vakitlerinde ancak uyuyabiliyorum. Karşımda,her

gün biraz daha silik,güneşten sıcak gülüşüyle bir yüz; karanlığın içinde

gidip gelen bir ses, bitmek tükenmek bilmeyen hayaller, bir de bir sonrası

hep olan,art arda yaktığım sigaralar... Bunlar geceleri,senin

yokluğundaki varlığın. 

      Bir nebze olsun sildiği için hayalini benden, ışıkları yakıp da az

uyumadım geceleri.Oysa hiç istemezdim hayalinden kurtulmak. Hele ki,

yalnızca hayalinle yaşamak...

      Bir şairin dediği gibi: ''uyuyorum demek ki varsın''. Ancak senin

varlığında mümkün adına yakışır bir uyku hali! 

      Sen, sensizliği hiç bilmedin sevgili.Bense her gün yeni bir sayfa

açıyorum bu kitapta. Bir gün yakabilmeyi cok dilesem de her gün yeni

birşeyler öğreniyorum bu kitaptan, yüreğimde en küçük bir umuttan dahi

yoksun avuntularla yaşarken. 

      Gittiğim her yere seni de götürüyorum. Bu ister bir deniz kıyısı

olsun,ister herkesin birbirinden habersiz yaşadığı kalabalık bir cadde; 

değişmiyor sensizlik yere ve zamana göre. Herkese haykırmak isterken

sensizliğimi, duyacağından korkup yeniden yazılara sığınıyorum. Sana her

gün ulaştırdığım ''günaydın''lara...

      Dünyanın bütün yüklerinden daha ağır geliyor sensizlikte yaşamak.

Ellerin yok, gözlerin yok, varlığın yok. Daha ne olmasın? Yoksun işte.

Şiirlerin arasında kaybolmak; yüreğine ulaşmasını dileyerek, Orhan

Veli''nin de dediği gibi bir mısranın mahremiyetinde tüm bir geceyi

geçirmek, bende artık vazgeçilmez bir alışkanlık oldu. Kalbini kırmadan,

yıllardır yaşadığın mutluluğa engel olmadan, sadece duygularımın

bilinmesini ve anlaşılmasını dilemek, sensizliğin küçücük bir parçası. 

      Ellerinle olmak, hiç konuşmadan saatler günler haftalar gecirmek

gözlerinle; günbatımında kordon da bıkmadan usanmadan binlerce kez aşkımı itiraf etmek. Hayatın tüm zorluklarında ve güzelliklerinde yanında olmak...

       Seninle üzülmek, seninle sevinmek... Yaşamayı, birlikte en sevilir hale

getirmek. Seninle sevmeyi öğrenmek... Bunlar da küçük parçalar

sensizliğinden. 

      Yaşadığım bütün aşklar, sensizliğimden başka parçalardır. Belki

içinde küçük de olsa umut, keşke umutlar olsaydı, vardır diyerek, kaç aşka

düştüm kurtulmak için denizinden... Kurtulmak kolay değil, ufuksuz

denizlerden. Sanma ki çok çapkınım, aşk katiliyim... 

      Kıyısı olmayan denizde yaşamanın ne olduğunu hiç bilmedin,

bilemezsin. Geceleri ayazı, gündüzleri sıcağı kavurur.Zaten az olan

umudundan yersin an be an... Uzun süre kaldığında alışırsın, ama giden

bir ömürdür hiç farkında olmadan. Biten aslında umudundur. Bu seni boşluğa

sürükler, inancından alır, duygusuz yapar, içine kapanıp yalnızlığa

gömülürsün. Sonrası karakıştır kendi yarattığın denizin ortasında. 

     ... 

      Şimdi yine yoksun. Ben koca bir şehrin kalabalığında her zamanki

gibi senle dolu, yine yeni hayaller kurmaktayım. 

      Artık korkmuyorum.Bu hayatımda ilk kez oluyor.', 'İşte şu anda ilk kez açık ve net okuyorsun duygularımı. Bu küçük bir deneme sadece, başlılar halinde yazılmış bir önsöz ya da index diyebili...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/yoksun-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşit Olmalıyız', 'esit-olmaliyiz-ayse-birgul-yilmaz-cuz8c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hakkında fazla bilgim yoksa da

En başından beri ilgim var sana

Alacakaranlık duygularımda

Adı yok bir sevda, sadece imza

Bir şiir çok sözden çok şey anlatır

Aşkı fısıldamak ve haykırmaktır

Belki de aşk için bir ilk adımdır

Kalbimi okursun satırlarımda

Bir şeyler olmalı, yok! başka şeyler

Örneğin sen ve ben dur daha erken 

Bir şeyler olmalı çok başka şeyler

Ruhumda yükselen saran alevler

Seni de sarmalı..

Seni de yakmalı.. 

Eşit olmalıyız özlerken

Eşit olmalıyız acı çekerken

Eşit olmalıyız  aşkı yaşarken

Ayşe Birgül Yılmaz

17/04/2005', 'Hakkında fazla bilgim yoksa da En başından beri ilgim var sana Alacakaranlık duygularımda Adı yok bir sevda, sadece imza Bir şiir çok sözden...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Birgül Yılmaz']::text[], 8.5, '{"poet":"Ayşe Birgül Yılmaz","poet_slug":"ayse-birgul-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/esit-olmaliyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayret', 'hayret-goksel-dogru-60qwi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(M''ilad''a...) 

Denizdeyim nihayet! 

Dalgalar, rüzgar, 

Genzimi yakan tuz 

Can yoldaşı martılar

Denizdeyim nihayet! 

İyi ama,

Fırtına nerde? 

(Ekim 2002, İzmir)', '(M''ilad''a...)  Denizdeyim nihayet!  Dalgalar, rüzgar,  Genzimi yakan tuz  Can yoldaşı martılar Denizdeyim nihayet!  İyi ama, Fırtına nerde? ...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hayret-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf II', 'i-tiraf-ii-goksel-dogru-jt1pa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(M''ilad''a...) 

Ben sende, hep baharları düşledim.

Varlığını bildiğim ilk andan beri

Üzerime yağan karları umursamayıp

İçimdeki çiçeği,umutsuzlukla  besledim.

Ben sende, hep yağmurları düşledim. 

Asla sıcağı ve güneşi değil! 

Sevmeni düşlemeden beni; aşkı

Her gün biraz daha ama hep ezberledim.

Ben sende, hep yalnızlığı düşledim.

Düşlediklerimden yola çıkıp; seni

Her gün daha ulaşılmaza göndererek

Mısralara  müebbet, ellerimle şiirledim

Ben sende, hep özlemi düşledim.

Sürüp giden bahar yağmurlarında,

Yalnız dolaşırken şehrin sokaklarında,

Dilimde buruk bir türkü tadında, 

Bıkmadan, usanmadan seni söyledim.

Benim düşlediklerimi sende,

Sakın sen bende düşleme! 

Bazen bir ağaç olursun, bazen okyanus

Işıksız, dipsiz bir uçurum genellikle... 

Gün gelir her şeyi benden umar, 

Unutursun kendini yumuk gözlerimde

Alışık değilsin, çarpar seni bensizlik,

Kaybolursun hayaller içinde.

Ben sende, hep sensizliği düşledim.

Bir hayaldin yanımda, bilirdim.

Ellerimde,hiç tutamadığım ellerinle, 

Her gittiğim yere seninle gelirdim.

Fakat,

Ne yağmurlar vardı orada, ne bahar,

Ne de usandığım şairliğim.

Sadece ama sadece, bir kuru 

Senin, yanımda olduğun hissin! 

Ben sende, hep sensizliği düşledim.

Bir hayaldin yanımda, bilirdim.

Gözlerimde, ölemediğim gözlerin; 

Her geldiğim yerden, 

Sana sonsuz dünyalar getirirdim.

(Şubat 2003, İzmir)', '(M''ilad''a...)  Ben sende, hep baharları düşledim. Varlığını bildiğim ilk andan beri Üzerime yağan karları umursamayıp İçimdeki çiçeği,umutsu...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/itiraf-ii-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçüncü', 'ucuncu-goksel-dogru-0tv16', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(M''ilad''a...) 

Yılsonularından biri yine.

Çokluğun,

Evlere çekildiği bir vakit.

Sokağın ıssızlığında bir adam 

Işıkların süslediği bu şehirde 

Neden türküler söyler 

Bağıra bağıra

Neden bir sokak ötedeyken deniz, 

Delicesine bir özlem duyar ona? 

(Aralık 2002, İzmir)', '(M''ilad''a...)  Yılsonularından biri yine. Çokluğun, Evlere çekildiği bir vakit. Sokağın ıssızlığında bir adam  Işıkların süslediği bu şehird...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ucuncu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satılık', 'satilik-goksel-dogru-9qybc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '(M''ilad''a...) 

İki yıl oldu alalı... 

Aklıma düştüğünde, 

Henüz bir nokta kadardı. 

   

Sonra bir resim kağıdına 

Dağ, kır, bayır resmi çizer gibi

Onu resmettim gönlüme.

İçim içimi kemirip dururken, 

''Olmaz çizmemelisin! '' diye... 

Ellerini veya gözlerini değil 

Samimiyetini, dostluğunu, 

-Soyut şeyler çizilmezmiş güya-

Bana hissettirdiklerini işledim.

O anlatmadıkça ben uydurdum

Şu yemeği sever, ve bunu yapmayı...

Bir yandan, böyle gitmez derken

Öte yandan boyamaya başladım gönlümü

Onun, güneşi andıran gülüşüyle

Olduğu olacağı bu biliyorum

Fazlasını zaten istemiyorum

Biliyorum ki dokunursam bitecek rüyam

Gerçekler bir tokat gibi yapışacak 

Gönlüme

   

Kötü günler 

Ona ''seviyorum'' dediğim gün

Başlayacak.

Az kullanılmış 

Bol umutsuzluk, hiç gözyaşıyla

Elimde kalan son aşkı da 

Satıyorum, 

Hem de bir ''hiç'' fiyatına...

(Şubat 2003, İzmir)', '(M''ilad''a...)  İki yıl oldu alalı...  Aklıma düştüğünde,  Henüz bir nokta kadardı.      Sonra bir resim kağıdına  Dağ, kır, bayır resmi çize...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/satilik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aradığım', 'aradigim-goksel-dogru-mb9e4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(M''ilad''a...) 

Hiç tatmadığım bir yemek gibi

Ya da görmediğim bir yere özlem! 

Aradığım bir şey var,

Ne olduğunu bilmediğim.

İnsanların arasında insanlığımla,

Ama iyi ama kötü yaşadıklarımla,

Aslında mutlaka vardır dediğim... 

Aradığım bir birşey var,

Ne olduğunu bilmediğim.

Bir çiçeği koklamak belki, 

Şimdiye kadar görmediğim.

Ya da gerçek bir ütopya,

Bir kez olsun olmasını düşlediğim...

Aradığım birşey var, 

Ne olduğunu bilmediğim.

Şimdiye kadar hiç yazmadığım 

Bir şiir belki

Okuyunca, 

''Bu gerçekten benim'' dediğim.

Belki de sıyrılıp hayallerden,

Basit bir yaşamdır özlediğim.

Aradığım birşey var,

Ne olduğunu bilmediğim.

Yaz ortasında kışı gördüm de 

Kışın yazı yaşamak belki düşlediğim.

İmkansızlardan yorulduğumdan belki, 

Kumdan kaleleri yıkmaktır istediğim...

Aradığım birşey var, 

Ne olduğunu bilmediğim.

Yokluğunu çok yaşadım varlığıyla

Belki de elleriyle yaşamak varlığında!

Ya da hiç olmadığı bir dünya,

Varlığıyla yokluğundan bihaber! 

Aradığım birşey var,

Ne olduğunu bilmediğim.

Güneşli bir günde, 

Sırılsıklam ıslanmak aşkla! 

Ya da karda açan kardelenler gibi

Sadece bir mevsimlik yaşamak.

Aradığım birşey var, 

Ne olduğunu bilmediğim.

Şairlerin hep söylediği gibi,

Gözlerinde ölecek kadar sevmek belki; 

Ya da sevilmediğini umursamayacak kadar,

Kalpsiz, duygusuz olmak belki.

Aradığım birşey var, 

Ne olduğunu bilmediğim. 

Sahip olduğum akılla,

Şükrederken Yaratana,

Hep bir an var beklediğim.

Ecel, bir yerde bir zaman.

O güne dek bulamayacağımı bildiğim,

Aradığım birşey var,

Ne olduğunu bilmediğim.

Belki de bu yüzdendir, 

Bu soruyla yaşamayı öğrendim.

İster kral olayım, ister fukara,

Sahip olduğum bütün duygularla,

Bir gün bu dünyadan göçeceğim.

Bildiğim birşey varsa,

Aradığım birşey var, 

Ne olduğunu bilmediğim.

Ama beni beklediğinden eminim.

(Ekim 2002, İzmir)', '(M''ilad''a...)  Hiç tatmadığım bir yemek gibi Ya da görmediğim bir yere özlem!  Aradığım bir şey var, Ne olduğunu bilmediğim. İnsanların aras...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/aradigim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarık Kaya', 'yarik-kaya-goksel-dogru-w9lle', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(M''ilad''a...) 

Dağlara kar düştüğünde 

Durulmaz buralarda 

Yanmak isterken gönül

Umarsız sevdalarda

Şimal rüzgarları estiğinde 

Yol alınmaz bu denizde

Coşmak isterken gönül

Köpük köpük denizinde

Elma çiçekleri açtığında

Senin şehrinde olmalı insan 

Kalmak ister deli gönül 

Zifiri karanlık da olsan

Gönlüm bir kuş, kafeste sanki

Karakışta hasrettir aşka

Göçmek ister deli gönül

Biçaredir bu diyarda

(Aralık 2001, İskenderun)', '(M''ilad''a...)  Dağlara kar düştüğünde  Durulmaz buralarda  Yanmak isterken gönül Umarsız sevdalarda Şimal rüzgarları estiğinde  Yol alınmaz ...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yarik-kaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli', 'deli-goksel-dogru-1357p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben şiir delisiyim

Görmeyen bir insanın gözleriyle görür

Sağır bir insan kadar duyabilirim

Ben aşk delisiyim

Sevmekten bıkmış bir insan kadar tok

Hiç sevilmemiş bir ihtiyar kadar aç olabilirim

Ben 

Ben var ya ben,

O bu şu değil de

Her şeyden çok insan delisiyim....

(Ocak 2003, İzmir', 'Ben şiir delisiyim Görmeyen bir insanın gözleriyle görür Sağır bir insan kadar duyabilirim Ben aşk delisiyim Sevmekten bıkmış bir insan kada...', ARRAY['Türk Edebiyatı','Şiir','Göksel Doğru']::text[], 8.5, '{"poet":"Göksel Doğru","poet_slug":"goksel-dogru","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/deli-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben ve Şehir', 'ben-ve-sehir-cihan-demirci-5lor5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben yalnızlık adlı bir şehrin,

boş sokaklarında saklıyım.

Sürgüne gönderilmiş,

bir sevda türküsüyüm ben.

Umutlarım askıda kalmış.

Ağlayışlarım 

yokluğunun bağrında bir sancı.

Sen yaşarken gönlümdeki zamanı,                                     sana gözyaşlarımdan yağmurlar biriktirdim; 

geriye bıraktığım 

bir tutam ıslak kaygı.

Azrail son trenine biniyor artık hayatın.

Geriye kalanlar için bırakılan

ayrılıklar ülkesine giden bir kapı.

Ben yalnızlık adlı bir şehrin,

boş sokaklarında saklıyım.

Alınyazım olmuş; 

kaderin kendi el yazısıyla

ismimi yazdığı sokaklar. 

Ve en az Necip Fazıl''inki kadar 

serseri kaldırımlar...

Ben yalnızlık adlı bir şehrin, 

boş sokaklarında saklıyım.

Gözlerimin önünde sis bulutları var,

ömrümün kilometre taşları oluyor ayrılıklar.

Senin düşüncelerime uğramansa

ancak bir yaz yağmuru kadar.', 'Ben yalnızlık adlı bir şehrin, boş sokaklarında saklıyım. Sürgüne gönderilmiş, bir sevda türküsüyüm ben. Umutlarım askıda kalmış. Ağlayışlar...', ARRAY['Türk Edebiyatı','Şiir','Cihan Demirci']::text[], 8.5, '{"poet":"Cihan Demirci","poet_slug":"cihan-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ben-ve-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede Bu Devlet (Taşlama)', 'nerede-bu-devlet-taslama-i-smail-sahin-rn7vb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Avradı dövüp kahveye gider

Okeyde herkesten önce biter

Bir de iş yok diye figan eder

Utanmaz nerede bu devlet der

Cebinde yokken on kuruş para

Çocuklar çıkarır her bahara

Dahi kuma gelir bir fukara

Utanmaz nerde bu devlet der

Kız okul yahut da aşk deyince 

Para verene satar hemence

Yavru asınca kendin bir gece

Utanmaz nerede bu devlet der

Aslan oğluna okul boş gelir

Kavga,kumar...çook iyi bilir

Bir gece başına bir iş gelir

Utanmaz nerede bu devlet der

Bizi hor görme büyük devletim

Sen bu halka vermezsen eğitim

Değil AB göğe çıksa milletim

Utanmaz nerede bu devlet der', 'Avradı dövüp kahveye gider Okeyde herkesten önce biter Bir de iş yok diye figan eder Utanmaz nerede bu devlet der Cebinde yokken on kuruş pa...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nerede-bu-devlet-taslama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İSTANBUL''Da Mutlu Ol', 'i-stanbul-da-mutlu-ol-umut-simsek-ybcud', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şair olmalı bu şehirde

Dibini bulmalı buzbağ ın denize karşı

Denizi seyrederek yıldızlı gecede

İSTANBUL''u görmeli

Sirkeci-Kadıköy expresinde,yem atmalı kuşlara

Yaz akşamı Üsküdar''da,mey dağıt bi hoşlara

Eminönünde balık al tekneden

Pazar bitti Heybeli yi gezmeden

Adalara varıp fayton sürmeli

Yaz akşamı hisara bilet almalı

Tanımadığın şahsa adres sormalı

İSTANBUL''u Görmeli

Çin restorantında suşi,

Kasımpaşa''da cümbüşü

İSTANBUL''u Görmeli.', 'Şair olmalı bu şehirde Dibini bulmalı buzbağ ın denize karşı Denizi seyrederek yıldızlı gecede İSTANBUL''u görmeli Sirkeci-Kadıköy expresinde...', ARRAY['Türk Edebiyatı','Şiir','Umut Şimşek']::text[], 8.5, '{"poet":"Umut Şimşek","poet_slug":"umut-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/istanbul-da-mutlu-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Şehit', 'sehit-hikmet-kucuk-d8hml', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey şehit! duydum ki, alnından vurulmuşsun,

Hemen yükselmişsin, cennete kurulmuşsun.

Akan kanların birikti, zâlimi boğdu,

Bir tek vurulduğun yerden, bin nefes doğdu.

Sen varsan biz varız, vatan sana minnettar,

Hak cemâlini göstermiş, cennet gelmiş ki dar.

Mahşerde gülümser kanlı gömlek giyenler,

Utanır dolaşır, şehit öldü diyenler.

Şanlı sancağım alını, kanından almış,

Vurulup gülmüşsün hilâl, o günden kalmış.

Muhammed övmüşte sevmiş, sevmişte övmüş,

Senin makamını gören dizini dövmüş.

Allah Allah dedin koştun, içtin şerbeti,

Canı feda ettin yakın kıldın gurbeti.

Ardından bıraktıklarını tarih aldı,

Her günün bir destan, göğe asıldı kaldı.

	            (Eskişehir  29/11/2003)', 'Ey şehit! duydum ki, alnından vurulmuşsun, Hemen yükselmişsin, cennete kurulmuşsun. Akan kanların birikti, zâlimi boğdu, Bir tek vurulduğun ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Küçük']::text[], 8.5, '{"poet":"Hikmet Küçük","poet_slug":"hikmet-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sehit-96-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaksın Bana', 'uzaksin-bana-behzat-ozdemir-f0sng', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her zaman büyük bir ülke

Yok kimseyle sorunu işte

Ne yalancı ne de bir şike

İstanbul görülmeye değer bir ülke.

Kucak dolusu cümle,

Kırık ta olsa söyleniyor işte

Bir gül bahçesi diye,

İstanbul sevilmeye değer bir ülke.

Her ah sesi Denize bir öfke

Nicedir beklerim sessizce

Ah bir denizi görsem de ölsem diye

İstanbul, sonumun olmasını istediğim tek ülke.

Kınalı parmak gibidir incitilmez

Biir şiir asla ifade edemez,

Ben, şair''im İstanbul değil

Ben, İstanbulum ülke değil

Ben ülkeyim İstanbul  İstanbul değil.', 'Her zaman büyük bir ülke Yok kimseyle sorunu işte Ne yalancı ne de bir şike İstanbul görülmeye değer bir ülke. Kucak dolusu cümle, Kırık ta ...', ARRAY['Türk Edebiyatı','Şiir','Behzat Özdemir']::text[], 8.5, '{"poet":"Behzat Özdemir","poet_slug":"behzat-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/uzaksin-bana-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varılmaz Aşkına', 'varilmaz-askina-cenk-aksal-pn5fa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hıçkırıklar duyuyorum,

uzaklarda bir yerlerde.

ağlıyorsun biliyorum,

varılmaz yerlerdesin:

istesemde gelemiyorum,

çaresiz kaldım işte:

ellerimi ellerine

veremiyorum,saramıyorum,

sensiz geçen her güne:

isyanlar ediyorum,

yıllar geçti bak, aradan

ben senden geçemiyorum..

sabret sende melül gözlüm:

istesemde gelemiyorum,

seni çok çok seviyorum...

     ''uzansam tutmak için ellerini''

     ''görebilsem melül gözlerini''', 'hıçkırıklar duyuyorum, uzaklarda bir yerlerde. ağlıyorsun biliyorum, varılmaz yerlerdesin: istesemde gelemiyorum, çaresiz kaldım işte: eller...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/varilmaz-askina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Aşkın Yeri', 'askin-yeri-hikmet-kucuk-oce75', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben aşka aşık oldum,

Aşkın evini buldum,

Ev benim içimdeymiş,

Ben içime vuruldum.

Sevdinse hüner sende,

Aşıksan cevher sende,

Sevdalarda çiçekler,

Aslında açar sende.

Aşk sen varsan var imiş,

Yar, seversen yar imiş,

Aşkı dışta arayan,

Boşuna arar imiş.

                    (Eskişehir 8/1/2004)', 'Ben aşka aşık oldum, Aşkın evini buldum, Ev benim içimdeymiş, Ben içime vuruldum. Sevdinse hüner sende, Aşıksan cevher sende, Sevdalarda çiç...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Küçük']::text[], 8.5, '{"poet":"Hikmet Küçük","poet_slug":"hikmet-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/askin-yeri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudaklar', 'dudaklar-hikmet-feridun-demir-2yo3x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dudaklarına ulaşamasın göz yaşların..

lslanmasın, yansın kor olsun sevdaya..

Özlemimdir, kor dudaklar yakışır sevdana.

Dudakların çeker beni, için için özlemimdir.

içim içim, sevdayı tamamlamak dudaklarında. 

Yılların biriktirdiği hasretin yangını Alev Alev.

Özlemim oldu dudaklarında tattığım Sevdanın Busesi.

Sevdam olsan, seni yudum yudum içsem.

Gönlündeki özlem olsam, bitmeyen Arzularına.

Özlem yanlızlıktandır, arzuları kabartır sığmaz Kalbe.

Dudakların özlemmiş sevişmelerime, sevişmelerine muhtacım.

Gülmek sana yakışıyor, sevdan da içinde Alev Alev.

Gel sarıl bana, eski sevişmelerine yangınım kalbimde.

Bulutların üzerinde dolaşma vakti, kol kola, dudak dudağa..

Fantaziler bitsin, sevdalar, özlemler gömülsün, 

Yalım yalım erisin, gerçek Aşkın  ateşine. 

19.04.2005

Köln / Almanya', 'Dudaklarına ulaşamasın göz yaşların.. lslanmasın, yansın kor olsun sevdaya.. Özlemimdir, kor dudaklar yakışır sevdana. Dudakların çeker beni...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dudaklar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gencligim soldu', 'gencligim-soldu-cengiz-kucukcelik-bshm2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birlik oldum cember oldum umutlarla el ele

yarinlari bugun saydim aci dusler ile

var dedim ozgurlugum acep olum mu yakin

cigaramla efkardayim bakin halime bakin

Direndim de direndim gencligim soldu

maziyi dusunurken gozlerim doldu

sanma sakin yagan kar`i saclarim aldi

agardi da agardi bembeyaz oldu

Isyanimla feryadimla hickirdim durdum

koguslarda kose bucak dondum yoruldum

biraz gayret biraz sabir kendimi buldum

anam babam bacim yarim bagrima vurdum', 'Birlik oldum cember oldum umutlarla el ele yarinlari bugun saydim aci dusler ile var dedim ozgurlugum acep olum mu yakin cigaramla efkardayi...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kucukcelik']::text[], 8.5, '{"poet":"Cengiz Kucukcelik","poet_slug":"cengiz-kucukcelik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gencligim-soldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ortadogu', 'ortadogu-cengiz-kucukcelik-k6lh8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Semada bir yildiz parliyor

parliyorda duslerime bir umut bagliyor

merhametsizligi insafsizligi topraga gomdum de

icim hala durmaksizin kan agliyor

acimadan vurdular yargizis infaz ettiler

coluk cocuk yasli basli demeden katlettiler

birer birer cani cani sanki cellat idiler

evrendeki mali mulku guya kar bildiler

Varimi yogumu umuda sardim

sardimda bilinmeyen bir yola vardim

insanlik mazide kalmis hurriyet imkansiz

duygular kime kalmis artik canlilarda cansiz', 'Semada bir yildiz parliyor parliyorda duslerime bir umut bagliyor merhametsizligi insafsizligi topraga gomdum de icim hala durmaksizin kan a...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kucukcelik']::text[], 8.5, '{"poet":"Cengiz Kucukcelik","poet_slug":"cengiz-kucukcelik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ortadogu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel İstanbul', 'guzel-i-stanbul-garip-yetim-n1dff', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İstanbul, sen esrarengiz bir şehirsin.

Güneşin doğuşu başka, batışı başka.

Boğazınla dünyanın güzel şehrisin.

Denizin başka, kız kulen başka.

Harikalarını ben nasıl anlatayım.

Birazda senin tarihine göz atayım.

Yaşadığın çağları bir not tutayım.

Dolma bahçen başka, top kapın başka.

Güzel şehir sende biraz gezeyim dedim.

Fatih, laleli ve kapalı çarşıyı seyredeyim.

Zaman yeterse, İstiklal caddesine gireyim.

Gecen bir başka, gündüzün bir başka.

Gezerek vardım Rumeli hisara

Gördüm altında birkaç fukara

Bir elinde ekmek öbüründe sigara

Kanunun başka kuralın başka

Tekselvi ye baktım restore olmuş

Mimarı Hasan CAN işbaşına gelmiş

Tantavide bir de yazın şenlik kurmuş

Çalışman bir başka, eğlencen bir başka

Garip yetim, seni ne kadar övse yetmez.

İstanbul güzelliğin seyretmekle bitmez.

Gözlerimin gördüğünü, dil ifade etmez.

Haydar paşan başka, Ayasofyan başka.', 'İstanbul, sen esrarengiz bir şehirsin. Güneşin doğuşu başka, batışı başka. Boğazınla dünyanın güzel şehrisin. Denizin başka, kız kulen başka...', ARRAY['Türk Edebiyatı','Şiir','Garip Yetim']::text[], 8.5, '{"poet":"Garip Yetim","poet_slug":"garip-yetim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/guzel-istanbul-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey delalim guzel Tavsancalim', 'ey-delalim-guzel-tavsancalim-cengiz-kucukcelik-scqqt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'EY DELALIM GUZEL TAVSANCALIM... 

Sevdalarin ve umutlarin dogdugu mekansin

oksuzlere yetimlere hem baba hem anasin

gariplere kucak acar bagrina basarsin

her hatiradan asaletli ve olumsuz bir anisin

Bin-nur tepeden gorkemli manzaran bir baskadir

cevherin erisilmez,cevahirin nazardan askadir 

topraginla havanla suyunla cennetim diye bas kaldir

kisin sinendeki ak rengin,yazin terleten sicakligin bambaskadir

Her gecilen sokagin kaldirim kaldirim hatira kokuyor

mazidekiler gerek aci gerek tatli yureklere huzun dokuyor

nekadar versek kendimizi sana hasretlik zora sokuyor

onca kayip degerler seni bana sayfa sayfa okuyor

Doyumsuzsun hic doyulmuyor dugunlerine derneklerine

davuluna zurnana sazina sozune orf ve adetlerine

suslu puslu gelin arabalarina,halay basi cekenlerine

tasina topragina evlerine ve ani birakilmis virane caddelerine

Bize bir karislik yerin yokmuydu da saliverdin gurbete

bu gurbetin ahi cekilmez can cekisiyoruz elbetde

sana elveda cektigim an 1988,yuregimde hala o aci o iz

bize bir karislik degil iki metrelik yerin kabrindir suphesiz 

Gurbet ellerde sana hasretiz ey delalim guzel Tavsancalim...', 'EY DELALIM GUZEL TAVSANCALIM...  Sevdalarin ve umutlarin dogdugu mekansin oksuzlere yetimlere hem baba hem anasin gariplere kucak acar bagri...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kucukcelik']::text[], 8.5, '{"poet":"Cengiz Kucukcelik","poet_slug":"cengiz-kucukcelik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ey-delalim-guzel-tavsancalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmedi sana', 'yetmedi-sana-tuncay-akdeniz-ni3xq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu canımı feda ettim yoluna

O gezdiğim yollar yetmedi sana

Bülbül gibi hasret koydun dalına

O verdiğim güller yetmedi sana

Hep sevdanı çektim can pahasına

Sevdamı kapattın aşk kasasına

Mecnun oldum onun her yarasına

O yattığım çöller yetmedi sana

Dermanımsın dedim yaramı deştin

Gül verdim içinden rengini seçtin

Aşka köprü oldum üstümden geçtin

O döktüğüm seller yetmedi sana

Ben nehir in oldum sen kuru dere

Kilim halın oldum sen serdin yere

Şeker balın oldum kattın zehir e

O süzdüğüm ballar yetmedi sana

Tuncay’ı katlandı bin bir cefaya

Aşkın ihaneti varmaz sefaya

Aslı kerem için vurdu kafaya

O yandığım küller yetmedi sana', 'Bu canımı feda ettim yoluna O gezdiğim yollar yetmedi sana Bülbül gibi hasret koydun dalına O verdiğim güller yetmedi sana Hep sevdanı çekti...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Akdeniz']::text[], 8.5, '{"poet":"Tuncay Akdeniz","poet_slug":"tuncay-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yetmedi-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beter', 'beter-gokhan-ebren-x17uf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'korktum

ışıklarını

yakmaya odamın 

ve çarptım

yüreğimi

karanlık odamın

karanlık duvarlarına...

korktum

ışıklarını 

yakmaya yüreğimin

ve çarptım

korkularımı

karanlık odalarıma

odamın duvarlarına...

korktum

yüreğimi ışıklandırmaya

odam karanlıkta kaldı

duvarları çarpık! ..', 'korktum ışıklarını yakmaya odamın  ve çarptım yüreğimi karanlık odamın karanlık duvarlarına... korktum ışıklarını  yakmaya yüreğimin ve çarp...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Ebren']::text[], 8.5, '{"poet":"Gökhan Ebren","poet_slug":"gokhan-ebren","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beter-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime Desem Kime Yansam Derdimi', 'kime-desem-kime-yansam-derdimi-mehmet-lutfu-aydin-6zpif', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Görür görmez can evimden vuruldum

O ne endam, o ne gerdan kırışlar...

Bezm-i meyde baş köşeye kuruldum

O ne gözler, o ne ahu bakışlar...

Sarar efkâr, gün geceye erdi mi

O ne gonca, o ne allı yanaklar…

Kime desem, kime yansam derdimi

O ne kiraz, o ne ballı dudaklar…

Yakar beni o dilberin ateşi 

O ne gamze, o ne gizli gülüşler…

Çaresi yok, kimse çözmez bu işi 

O ne benler, o ne inci fildişler… 

Aç gözünü, uyan ey gafil uyan

Hayır gelmez tek taraflı sevdadan

İyisi mi, var sen ateşinle yan

İflâh etmez, vazgeç gel bu davadan', 'Görür görmez can evimden vuruldum O ne endam, o ne gerdan kırışlar... Bezm-i meyde baş köşeye kuruldum O ne gözler, o ne ahu bakışlar... Sar...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kime-desem-kime-yansam-derdimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Gözü Kör', 'askin-gozu-kor-mehmet-lutfu-aydin-7abp1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Görür görmez göz gözü, gözler infilâk etti                

Gözlerden gönüllere, göz göz ateşler düştü

Aşkın gözü kör imiş, dünya âlem gözledi

Ateşlenen bir sevda, yürekleri közledi

Tanık oldu kör gözler, doğuşuna bir aşkın

Kör gözler de görürmüş, gören gözler pür şaşkın

Birleşti iki beden, tek bedende eşleşti

Tutuştu iki yürek, tek yürekte devleşti

Taştı, aktı yürekten sevginin dalgaları

Yayıldı dört bir yana, bir aşkın halkaları

İki göz izin verdi, duygular şekillendi

İki dudak birleşti, bir sevda tescillendi 

Sevda sevdadan üstün, bir masal sanılacak 

Bu aşk dillere destan, yıllarca anılacak', 'Görür görmez göz gözü, gözler infilâk etti                 Gözlerden gönüllere, göz göz ateşler düştü Aşkın gözü kör imiş, dünya âlem gözled...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/askin-gozu-kor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davetsiz Konuk', 'davetsiz-konuk-mehmet-lutfu-aydin-ugq02', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Davetsiz konuğuyum bu gece sokakların

Ne bir ses ne bir nefes, çıt yok bu koca kentte

Nerde müdavimleri bahçelerin, parkların? 

Cinler cirit atıyor bu ıssız labirentte

Ölüm kokusu sinmiş kentin varoşlarına

Matem giysilerini giyinmiş tüm yapılar

Sokaklar kucak açmış azgın sarhoşlarına

Kapanmış sıkı sıkı, pencereler, kapılar

Ne ben kimseyi gördüm ne kimse beni gördü

Saklambaç oynanıyor, ebe kim belli değil

Bu kenti çevreleyen duvarları kim ördü? 

Hayaletler amele, usta kim belli değil

Uzaklarda havlayan kızgın bir köpek sesi

Parçalıyor geceyi, gecelerden habersiz

Aralanmış küçük bir pencerenin perdesi

Bakınmakta bir çift göz, ta ezelden kadersiz

İnsanoğlu vefasız, güvenilmez sözüne 

Yorgun ayaklar susmuş, ne ahı var ne vahı

Umutları tükenmiş, uyku girmez gözüne 

Kaldırımlar çaresiz, beklemekte sabahı

İşte bir köprü altı, kimsesizler sarayı

Ve bir serseri kral, yere sermiş postunu

Bir elinde şarabı, patlatıyor narayı

Sokak köpeği sessiz, izlemekte dostunu 

Bütün gün yemiş içmiş, karnı tok anlaşılan

Acımasız sokaklar karartmış her bir yanı                            

Davetsiz misafire rağbet yok anlaşılan

Kurdurmuş bin bir tuzak, almak için bu canı

Sokak ve caddelerin sahibi kim bu gece? 

Bilmediğim bu kentte, neler olup bitiyor? 

Neden takılı kaldı, dilimde iki hece? 

Ö-LÜM, uzak dur benden, aklım şaşıp yitiyor

Elveda ey sokaklar, geceler sizin olsun

Bize karanlık değil, aydınlık günler gerek

Dilerim gece gündüz, her yer neşeyle dolsun

Taşsın sokaklarından, sarsın kenti giderek', 'Davetsiz konuğuyum bu gece sokakların Ne bir ses ne bir nefes, çıt yok bu koca kentte Nerde müdavimleri bahçelerin, parkların?  Cinler cirit...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/davetsiz-konuk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetişemedim', 'yetisemedim-ali-fikri-karadeniz-h41ee', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kader terim düşerken toprağa

Hayallerim boy boy yeşerir

Sonra hüzünler çöker içime

Mevla’m diyor “Son kadehi içme…! ”

Tedavülden kalkmış bir benliğim var

Hani.. Hani bestelenmemiş şarkılar

Ve okunmamış dizeler gibi

Bir mana taşımazlar…

Sevgi yükledim çiçeklere

Kuşların kanatlarına ekledim

Bulutlara aşk tanecikleri dizip

Göklerden üzerine serpiştirdim…

Sevdim; 

Taparcasına sevdim

Sevgim benden bir adım öndeydi

Koştum koştum

Ama

Yetişemedim…!

                                                     20/05/2005

Ali Fikri Karadeniz', 'Kader terim düşerken toprağa Hayallerim boy boy yeşerir Sonra hüzünler çöker içime Mevla’m diyor “Son kadehi içme…! ” Tedavülden kalkmış bir...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yetisemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şikayetname', 'sikayetname-mehmet-cetin-2-qi8k9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç olmazsa eskiden,arada bir uğrar,

Hal,hatır sorarlardı,

Hani yasak savmak kabilinden diyelim,

Senden sonra evin yolunu unuttu çocuklar,

Geçenlerde ışığı açık görmüş,

Kapıdan şöyle bir göründü küçük oğlun,

Bir sitem,bir sitem,

Uğraşamam,diyor,üç buçuk emekli aylığınla senin,

Banka kuyruklarında bu iş güç arası,

O gitti,oturup bir güzel ağladım,

Hani,sana da kızmıyor değilim ara sıra,

Benden önce gittin de sanki,

Sultan mı ettiler seni Mısır''a? 

Büyük oğlun desen,bana hala dargın,

Getirdiği müteahhide vermemişim diye evi,

Ha bire söylenip duruyormuş,

Yok,babamın anıları varmış,

Yok,elleriye dikmişmiş bahçedeki sardunyaları.

Bıraksın diyormuş,

Bıraksın o eski hülyaları,

Ne babamdan,ne ondan anı kalır,

Bilsin ki,öldüğü gün o ev satılır,

Bu çocuklar kime çekti bilmiyorum ki canım,

Son günlerde dalıp dalıp gidiyorum,

Canım sıkılıyor canım.

Kız daha kırkın çıkmamıştı ki evlendi

İki çocuklu,o paragöz adamla,

Geçenlerde ayaküstü şöyle bir uğradılar,

Adam hem saygısız,hem de aşırı şişman,

Sana bir şey söyleyeyim mi canım,

Kız pek mutlu değil,yani bin pişman,

Hani dokunsan ağlayacak,

Ayrlırken elimi öptü,

Bu kış havalar soğuk geçecekmiş,

Aman kendine iyi bak,sakın hastalanma bu yaşında,

Sabah akşam mutlaka al o ilacı,

Biliyorsun,dedi,babam da yok artık başında,

O gitti oturup bir güzel ağladım,

Artık ne telefonum çalıyor,ne de kapım,

Mektup desen kimden gelecek be canım? 

Son günlerde zaten,

Karşı kaldırımlardan dolaşıyor postacı.

Yok,sakın aklından geçireyim deme,

İnan ki kırgın değilim,

Biraz burukluk işte,biraz hüzün,

Hüzün,bilirsin benim en doğal halimdir,

Hani bir de kahve yapmak zor gelmese,

Taşırmasam hani her defasında,

Şişşt,kimse duymasın,ilaç milaç da almıyorum artık,

Kokunu öyle özledim ki canım,

Dün gece kahverengi paltona sarılıp uyudum,

Hayalimde okşadım o güzel saçlarını,

Hani sana da kızmıyor değilim ara sıra,

Benden önce gittin de sanki,

Sultan mı ettiler seni Mısır''a? 

                                                          15 EYLÜL 1997

                                                              YEŞİLKÖYMEHMET', 'Hiç olmazsa eskiden,arada bir uğrar, Hal,hatır sorarlardı, Hani yasak savmak kabilinden diyelim, Senden sonra evin yolunu unuttu çocuklar, G...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çetin 2']::text[], 8.5, '{"poet":"Mehmet Çetin 2","poet_slug":"mehmet-cetin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/sikayetname-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygu Duygu İstanbul', 'duygu-duygu-i-stanbul-muhsin-durucan-lnphs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Pencereden Haliç''i yakaladı gözlerim

Umut yüklü motorlar denizde düşe kalka

Bir eylül sabahında İstanbullaştı sevgim

İstanbul''da İstanbul''u yaşamak bambaşka.

Türkü tadı gecede upuzun minareler

Uçuşan martıları sevinçten çığlık çığlık

meydan okur yıllara tarih tarih değerler

Al lâle güzelliği renk renk güler uygarlık.

Boğaz''da mavi boncuk anıt anıt yapılar

Ürkme, titreme gelir düşündükçe şöyle bir

Görkemini bozmasın fırtınalar, boralar

Şiirce güzellikler yaşanmıştır kim bilir.

Şerit şerit yolları gerdanda bir nakıştır

Soluklu düdük sesi uzaklardan duyulur

Geçmişten geleceğe muştulu bir bakıştır

Arayan mevlasını, belasını da bulur.

Acımasız dalgada kırıtır Kız Kulesi

Kaçışan yağmurları dökülür sicim sicim

Evrenin sabahları güzel midir böylesi

Ellere gülümseme ceylan gözlü sevgilim.', 'Pencereden Haliç''i yakaladı gözlerim Umut yüklü motorlar denizde düşe kalka Bir eylül sabahında İstanbullaştı sevgim İstanbul''da İstanbul''u ...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Durucan']::text[], 8.5, '{"poet":"Muhsin Durucan","poet_slug":"muhsin-durucan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duygu-duygu-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceren Gözlüm', 'ceren-gozlum-osman-fatih-xoft0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ankara kadar soğuktu ellerin,

Gözlerinde bir izmir sıcaklığı,

Kalbinde yarım kalmış aşkların tutsaklığı.

Zaman akıp giderken saatlerden

Bana kalan

Hüzünlerden yorgun bir kalbin kaçaklığı..

Acının ne olduğunu bilen bir ceylan olmalıydın susamış sevilmeye

kaçıp da kurtulduğun o hüzünlerden geriye..

Usulca diktim gözlerimi gözlerine 

Ve dedim ki,

''Güneş batarken kapatsan da gözlerini

silemezdi yanaklarından süzülen ürkekliğini

Çünkü sen bir ceylandın,

Ve tüm ceylanlar gibi karanlıktan korkardın..

Bu yüzden sevemedin yalnızlığı

Acıların hep bu yüzdendi..

Bu yüzden affetmedin

Seni koca bir geceye terkedenleri.''

Şimdi nerelerdesin bilmem,

Hangi rüzgar seni nerelere götürmüştür.

Ceren gözlerin kimlerin esiri

Ellerinde kimin elleri

Ama bil ki

Unutmayı bilemedim alışmayı bildim

Hala her gece gözlerinde gözlerim...', 'Ankara kadar soğuktu ellerin, Gözlerinde bir izmir sıcaklığı, Kalbinde yarım kalmış aşkların tutsaklığı. Zaman akıp giderken saatlerden Bana...', ARRAY['Türk Edebiyatı','Şiir','Osman Fatih']::text[], 8.5, '{"poet":"Osman Fatih","poet_slug":"osman-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ceren-gozlum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halk Temsili', 'halk-temsili-ahmet-aksoy-in8wk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gelişi yüz gidişi beş yüz mendillerle

…..trenlerde vekil oğulları

ne zenginlik bire beş satış

……bir tüccarın hayallerinde

hele ki

sabahtan akşam sekize

dolanıyor

……..dokuzuncu elinde 

……eve gidecek Mehmet', 'gelişi yüz gidişi beş yüz mendillerle …..trenlerde vekil oğulları ne zenginlik bire beş satış ……bir tüccarın hayallerinde hele ki sabahtan a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/halk-temsili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-Uykular', 'uykular-sair-ahrazi-0xbwl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kapanırken yavaşça göz kapakların,

Benliğin terk edip giderken aklını,

Kuytu bir yerdesindir.Açtığın kapı,

En yakın şehridir kaçak uykuların.

Bir rüyâ belki,ayrılık kadar uzun,

Belki bir mahşerin tam ortasındasın,

Kim bilir,belki de bütün zamanların,

Ertelenmiş sabahıdır bulunduğun.

Yapayalnız bir elvedâ,hüzün ve gam,

Takip ettikçe devleşen mesâfeler,

Gölgelikten ziyade birkaç izbe yer; 

Uykular,bitmeyen kâbus ve intikam.

Cana ait ne varsa ukdedir o an,

Ansızın kaybolan düşünceler gibi.

Gör demiş yokluğun mimarı belli ki,

Köhne bir uykudur dünyada manzaran.

* * *', 'Kapanırken yavaşça göz kapakların, Benliğin terk edip giderken aklını, Kuytu bir yerdesindir.Açtığın kapı, En yakın şehridir kaçak uykuların...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/uykular-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut', 'unut-avni-aydin-jqw6x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'unutuldum mu güzel? 

sabah hatırlamadığın rüyalar gibi? 

konuşurken birden unutulan cümleler gibi? 

belki daha da mutlusun yalnız; 

belki de değil 

konuşmak isteyip de söyleyemediklerimiz gibi

yalnızız artık

ne konuşacak bir söz var usumuzda

ne akacak bir kaç damla yaş; 

unutulmaya mahkum iki aşığız, yalnızız...', 'unutuldum mu güzel?  sabah hatırlamadığın rüyalar gibi?  konuşurken birden unutulan cümleler gibi?  belki daha da mutlusun yalnız;  belki de...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/unut-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başım Gözüm Üstüne', 'basim-gozum-ustune-adulera-ayza-rihay', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Artık vakit geldi.

Sorma nereye,

Belki bir dağa

Belki bir tepeye

Bir ömür geçti haybeye

Özlediğim ölüme

Artık vakti geldi

Ölüm gelmiş 

Başımın üstüne.', 'Artık vakit geldi. Sorma nereye, Belki bir dağa Belki bir tepeye Bir ömür geçti haybeye Özlediğim ölüme Artık vakti geldi Ölüm gelmiş  Başım...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/basim-gozum-ustune-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemek', 'i-stemek-muhsin-durucan-xiewr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben en çok; 

Derin izli bakışları 

Aklı karalı gözleri isterim.

Ben en çok; 

Olsa da olmasa da tanışları

Giz bırakan yüzleri isterim.

Ben en çok; 

Yay görünümlü kaşları

İçin için yanan közleri isterim.

Ben en çok; 

Adam onuru duruşları

Bal tatlısı sözleri isterim.', 'Ben en çok;  Derin izli bakışları  Aklı karalı gözleri isterim. Ben en çok;  Olsa da olmasa da tanışları Giz bırakan yüzleri isterim. Ben en...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Durucan']::text[], 8.5, '{"poet":"Muhsin Durucan","poet_slug":"muhsin-durucan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/istemek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedriye''ye Ağıt', 'bedriye-ye-agit-yusuf-ter-jslxk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey ırmaklar nereye  akarsınız 

 Böyle  uzun yolları  koşarsınız

 Koylar sizde pusuya düşersiniz

 Kara toprak Bedriye yi geri ver

Hesabı sorulur  gelirse günü

Nedir insafsızlık kesilmez önü

Nasıl oldu sığdı toprağa canı

Kara toprak Bedriye yi geri ver

Bir devrimci böyle kalleş vurulmaz

Yıllardır kan akar dere durulmaz

Kanıyor yaramız bir türlü durmaz

Kara toprak Bedriye yi geri ver

Yusuf’um  Denize İnana  yoldaş

Mahir, İbrahim’in  yolunda savaş

Bir gün hesap sorulur   gardaş

Kara toprak Bedriye yi geri ver

18.04.05

Saat 04:12 İsviçre

http://www.yusufter.tr.cx', 'Ey ırmaklar nereye  akarsınız   Böyle  uzun yolları  koşarsınız  Koylar sizde pusuya düşersiniz  Kara toprak Bedriye yi geri ver Hesabı soru...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bedriye-ye-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlu Mevsim', 'yagmurlu-mevsim-avni-aydin-5pwgt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir buruk içim

Yağmurlardan...

Gözlerimizde yorgunluk

Aşkın mevsimi

Hazan...', 'Bir buruk içim Yağmurlardan... Gözlerimizde yorgunluk Aşkın mevsimi Hazan......', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yagmurlu-mevsim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan', 'sevdan-avni-aydin-fjowh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'unutamadım o akşamı...

beraber geçirdiğimiz birkaç dakikayı...

neydi beni sana çeken? 

neydi sana başlayan? 

hiçbir fikrim yok ama...

o bir kaç dakikada guzel kız

bu deli gönlümü sana kaptırdım...

hayatında belki birisi vardır..

yada evlisindir....

ama herşeye rağmen

sonu belli olmayan bu sevdaya ben fena tutuldum.', 'unutamadım o akşamı... beraber geçirdiğimiz birkaç dakikayı... neydi beni sana çeken?  neydi sana başlayan?  hiçbir fikrim yok ama... o bir ...', ARRAY['Türk Edebiyatı','Şiir','Avni Aydın']::text[], 8.5, '{"poet":"Avni Aydın","poet_slug":"avni-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sevdan-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Çocuğunun Feryadı, Anneciğim Nerdesin?', 'sokak-cocugunun-feryadi-annecigim-nerdesin-kasim-kaplan-44n6j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anneciğim çok özledim ben seni

Ben sokakta, kim bilir sen nerdesin.

Özlüyorum o şefkatli sesini

Bilmiyorum, anneciğim nerdesin? 

Ne zamandır sevgi kokan sesini,

Duymuyorum, anneciğim nerdesin? 

Yıllardır gül kokan o nefesini,

Özlüyorum, anneciğim nerdesin? 

Çoktandır duymadım şefkatli bir ses,

Acıktım, açlıktan kokuyor nefes,

Gittikçe itiyor arkadan herkes,

Düşüyorum, anneciğim nerdesin? 

Geceler çok uzun varmaz sabaha,

Gerdiler gövdemi beton çarmıha,

Her geçen günümde, birazcık daha,

Soluyorum, anneciğim nerdesin? 

Bitmiyor geceler atmaz şafaklar,

Altımda döşeğim kuru yapraklar,

Geceler çok ayaz, soğuk topraklar,

Üşüyorum, anneciğim nerdesin? 

Gitmez hayalimden evimiz bizim,

Sokak bir canavar, bense güçsüzüm,

Takatim kalmadı, çok çaresizim,

Ölüyorum, anneciğim nerdesin? 

                                 Kasım KAPLAN', 'Anneciğim çok özledim ben seni Ben sokakta, kim bilir sen nerdesin. Özlüyorum o şefkatli sesini Bilmiyorum, anneciğim nerdesin?  Ne zamandır...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kaplan']::text[], 8.5, '{"poet":"Kasım Kaplan","poet_slug":"kasim-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sokak-cocugunun-feryadi-annecigim-nerdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mantarını savuruyorum köpek öldürenin, deniz zannederek karşı kaldırımı, denize aşkla.', 'mantarini-savuruyorum-kopek-oldurenin-deniz-zannederek-karsi-kaldirimi-denize-askla-lzcramcil-ceyhun-erdem-49qbz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağır kamlı bakarak camından kentte,

karanlığının köşelerinde yeşil otobüsün, açlığa terk ettim ruhumu

sessiz çığlıklarım yapay yüzlerinden geri döndü, o ışıklı, gündüz yalanı tabelaların

her otobüs durağında kafası kıyak sarhoşla yan yana duran o ürkek yirmilik öğrenciyi sana benzettim

ve onlar, sana benzeyenler, hep başka otobüslere binerek uzaklaştılar

şehrin ucu bucağında kimlerin koynuna girdiler, ben şehrin koynunda uyuya kalırken? 

Yolun sonuna doğru o uzak ışıklarıyla, o uzak kaldığım şehrin,

allı pullu, faydasından çok zararlı, göçebe minibüslerine takılıp

yalnızlığı daha bir derinlerde, daha bir gür ve geç saatte yaşadım.

kara bir baht gibi yapıştı geleceğime şehirn göbeğinde yazmak şehrin çiçeksiz parklarını.

Gece iyice karanlık, yollar iyice tenha iken

suretine bir sokak lambasının güneşini uman yaprakları, toz toprak ağacı mesken tutup

kapağını çakmakla açıyorum bunun yanında tövbemin ve köpek öldürenin 

mantarını savuruyorum

deniz zannederek karşı kaldırımı

bir yudum çekiyorum kafama, bir yudum döküyorum kaldırımına İstanbul''un,

çekiyoruz kafaları anlaşılan, çekiyoruz bu gece, yer altı geçidinin üstünde...

Despresyonist bir uykudur şimdi gözlerimden akan

sessiz eğlenmelerden sonra tövbelerle yıkanan.

denizin altında bir başka deniz, sokağın sonunda varoş şehir 

eskilikten mi, acılıktan mı bu karanlığı, eli cebinde uyanan, soğuktan birbirine sokulan üniversite talebelerinin sokaklarının.

Sesler çekiliyor, akrebin hareketiyle

sokakta kedigiller çöp evlerinde ziyaret ediyorlar birbirlerini,

kondusuna giderken vedalarşıyor, nemli bodrum kat işyerinde yaşayan arkadaşıyla,

aklından sosyal hayatının hareketliliği geçiyor, heyecanlanıyor...

kent yaşatıyor onları, diğerlerini ve herkesi bağrında, 

üzerek yada sevindirerek bir lokma çalıyor aslanın ağzından onlara,

usulca besliyor, aşık ediyor bizi İstanbul birbirimize...

aşk olsun İstanbul...', 'Ağır kamlı bakarak camından kentte, karanlığının köşelerinde yeşil otobüsün, açlığa terk ettim ruhumu sessiz çığlıklarım yapay yüzlerinden g...', ARRAY['Türk Edebiyatı','Şiir','Lzcramcil Ceyhun Erdem']::text[], 8.5, '{"poet":"Lzcramcil Ceyhun Erdem","poet_slug":"lzcramcil-ceyhun-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/mantarini-savuruyorum-kopek-oldurenin-deniz-zannederek-karsi-kaldirimi-denize-askla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haram Olsun', 'haram-olsun-hidayet-avsar-ysl0j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıllar önce senden yana,

Gördüğüm düş haram olsun.

Yollarına yana yana,

Koyduğum baş haram olsun.

Yokluğunu gurbet bilen,

Ey sevdalı, bendim kölen.

Senden selam ile gelen, 

Dost, arkadaş haram olsun.

Adın gülüm değil gayrı,

Sen ayrısın, sevda ayrı,

Gecelerden bekle hayrı,

Gündüz sana haram olsun.', 'Yıllar önce senden yana, Gördüğüm düş haram olsun. Yollarına yana yana, Koyduğum baş haram olsun. Yokluğunu gurbet bilen, Ey sevdalı, bendim...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/haram-olsun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Atmosferimde Ozon Deliği', 'ask-atmosferimde-ozon-deligi-nimetullah-sucu-ikvee', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin gözlerin hüzün tutmuş, benim gözlerim yosun,

Resimler çizgisinden sapmış, renkler özünden yoksun,

Çerçevesiz aşklarda ararken silüetini, kayboluyorsun,

Senin gözlerin hüzün tutmuş, benim gözlerim yosun.

Karpuz kabuğundan gemiler yüzerken beyaz denizde,

Parmaklarımız dans ediyor ellerimizin etten pistinde,

Bir rüyadan geriye, ozon kokusu kalıyor genzimizde,

Karpuz kabuğundan gemiler yüzerken beyaz denizde.

Kırık bir şemsiye gibi içime kapanıyorum akşam,

Sebebi vardır, kadehlerin ince beline sarılıyorsam,

Eşlik ediyor bu kederli sevişmeye vefalı masam,

Kırık bir şemsiye gibi içime kapanıyorum akşam.

Neden dayar şairler şiirlerini, dayanılmaz boşluğa,

Mısraları sallanan bir dizenin düşmemesi adına,

Sonunda, yazılanlar bir akşam, yaşandıysa boşuna,

Neden dayar şairler şiirlerini, dayanılmaz boşluğa.

Senin gözlerin hüzün tutmuş, benim gözlerim yosun,

Resimler çizgisinden sapmış, renkler özünden yoksun,

Çerçevesiz aşklarda ararken silüetini, kayboluyorsun,

Senin gözlerin hüzün tutmuş, benim gözlerim yosun.

Bir veda havasıysa soluduğum, ne kalıyor ne çıkıyorsun,

Hem alırken hem verirken sensizliği, nefesimi kesiyorsun,

Kokun sinmiş, aşk atmosferimde, ozon deliği açıyorsun,

Bir veda havasıysa soluduğum, ne kalıyor ne çıkıyorsun.

Senin gözlerin hüzün tutmuş, benim gözlerim yosun,

Renkleri solduran bakışlarınla, ''gidiyorum'' diyorsun,

Çerçevesiz aşklarda ararken silüetini, kayboluyorsun,

Senin gözlerin hüzün tutmuş, benim gözlerim yosun.', 'Senin gözlerin hüzün tutmuş, benim gözlerim yosun, Resimler çizgisinden sapmış, renkler özünden yoksun, Çerçevesiz aşklarda ararken silüetin...', ARRAY['Türk Edebiyatı','Şiir','Nimetullah Sucu']::text[], 8.5, '{"poet":"Nimetullah Sucu","poet_slug":"nimetullah-sucu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ask-atmosferimde-ozon-deligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-hidayet-avsar-mimha', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derdim sana, derdim sana,

Yük mü benim derdim sana.

Deryalarda balık olsam, 

Açabilsem, derdim sana.

Derdim sana, derdim sana,

Nice güller derdim sana.

Sevdalının sözü olsam,

Beni kandır, derdim sana.', 'Derdim sana, derdim sana, Yük mü benim derdim sana. Deryalarda balık olsam,  Açabilsem, derdim sana. Derdim sana, derdim sana, Nice güller d...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sana-103-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asil Sevdam-5', 'asil-sevdam-5-hidayet-avsar-1kkqj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman olur,

Masmavidir deniz.

Zaman olur, 

Bütün renkler sitemdir...

Çile çekmek riya,

Umut etmek kahır,

Ve seni özlemek; 

Ekmek kadar asildir güzel...

Cehennem kadar sıcak,

Ölüm kadar masum bir rüyadır

seni anlamak...

Oysa,

Özlem bitmeyecek geldiğin vakit.

Adı konmamış bir kuşun,

Çırpınan kanadında kalacaksın...

Yarı insan, yarı bulut...', 'Zaman olur, Masmavidir deniz. Zaman olur,  Bütün renkler sitemdir... Çile çekmek riya, Umut etmek kahır, Ve seni özlemek;  Ekmek kadar asild...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asil-sevdam-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Hikayemiz', 'bitmeyen-hikayemiz-nimetullah-sucu-13d72', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şairler, çektiklerini mısralarda yakar,

Acıların tütsüsü, yanmadan hasret kokar,

Sevilenler bir ömür, yakılanlarda yaşar,

Her kalp atışı, bir çocuktur umut kadar.

Aşk, bir ileri bir geri gitmekten çok öteydi,

Bir zambakta Balzac, zehrinde Goethe''ydi.

Hazanda sarı yaprak, ellere dökülmeni,

Bir gemi belirdi ufukta, andırıyor gövdeni,

Sular çekilinceye dek, seyredeyim gölgeni.

Beni affet sevgili, ne masalda bir peri,

Ne ayakları yerden kesilmiş bir serseri,

Sarabildi ruhuma biçtiğin elbiseni.

Aşk, bir ileri bir geri gitmekten çok öteydi,

Bir kadehte mavi mum, fitilinde Promethe''ydi.

Ateş sardıysa bacayı, anka kuşları çıkar,

Her is bulutu demlendikçe, yağmur kokar,

Beni unut sevgili, şiirlerde bul benzimi,

Hiç bir acı, sen kadar doldurmadı genzimi.

Aşk, bir ileri bir geri gitmekten çok öteydi,

Atılan adımlar gerçek, izleri hep sahteydi.

Karda yürümek zordur, kırık hayalle kırda,

Şarkısı yeryüzünün, kalmadıysa ayakta,

Beni yollar sevgili, kan değil, şarap tutar,

Dudaklarının kızılı yüreğimde yer tutar.

Kurtar sarhoşluktan çalkalanan mesanemi,

Derine daldır ellerimle çıkardığın meselemi.

Aşk, bir ileri bir geri gitmekten çok öteydi,

Belki de bu yüzden hikayemiz bitmedi.', 'Şairler, çektiklerini mısralarda yakar, Acıların tütsüsü, yanmadan hasret kokar, Sevilenler bir ömür, yakılanlarda yaşar, Her kalp atışı, bi...', ARRAY['Türk Edebiyatı','Şiir','Nimetullah Sucu']::text[], 8.5, '{"poet":"Nimetullah Sucu","poet_slug":"nimetullah-sucu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bitmeyen-hikayemiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklambaç', 'saklambac-guler-ilgaz-7enbe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tanrı çok seviyor

Saklambaç oynamayı

Tam buldum diyorum

Bakıyorum

Elimde bir çiçek

Kokluyorum

.....................................

Tam buldum diyorum

Bir şimşek çakıyor

Gördüm dediğim an

Bakıyorum kayboluyor

......................................

Tam buldum diyorum

Duyuyorum şırıl şırıl akan

Bir derenin sesini

.....................................

Tam buldum diyorum

Kedinin tüyleri arasında ellerim

Arıyor arıyorum

Bazen ümidimi kesiyor

Diyorum bulamayacağım

..........................................

Ara diyen sesi

Kulaklarımda şu an bile

Arayan ve aratan

Bende seviyor beni', 'Tanrı çok seviyor Saklambaç oynamayı Tam buldum diyorum Bakıyorum Elimde bir çiçek Kokluyorum ..................................... Tam buld...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/saklambac-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaldım Sana Getirdim', 'caldim-sana-getirdim-hidayet-avsar-8yuab', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mecnun''dan sevdasını,

Çaldım sana getirdim.

Ferhat''ın kazmasını,

Çaldım sana getirdim.

Yunus''tan doymamayı,

Mevlana''dan manayı,

Peygamber''den duayı,

Çaldım sana getirdim.

Şeytanlar''ın yasından,

Şarabın mayasından,

Lokman''ın kimyasından,

Çaldım sana getirdim.

Mürşid''den kerameti,

Kitap''tan alameti,

Güneş''ten kıyameti,

Çaldım sana getirdim.

Bedenimi gölgemden,

Merhameti Annem''den,

Hasretini sinemden,

Çaldım sana getirdim.', 'Mecnun''dan sevdasını, Çaldım sana getirdim. Ferhat''ın kazmasını, Çaldım sana getirdim. Yunus''tan doymamayı, Mevlana''dan manayı, Peygamber''de...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Avşar']::text[], 8.5, '{"poet":"Hidayet Avşar","poet_slug":"hidayet-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/caldim-sana-getirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanet', 'emanet-aysun-erat-jee4k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Emanet bir elbise gibi aşk üzerimde.

Sanki benimmişçesine,

Aynanın karşısına geçip,

Kendime bakıyorum uzun uzun.

Ne güzel yakıştı bana bu giysi! 

Bir gün gelip alacaklar üzerimden biliyorum.

Çırılçıplak kalacağım o zaman.

Kara kışlar basacak her yanı.

Zemheri ayazlarda üşüyeceğim.

Yoksulum işte! 

Ancak emanet taşırım aşkı üzerimde.

Bıraksalar kendi halime,

İlişmem kimselere.

Aşkı yaşarım usul usul, sessizce.

Olmaz ki…

Anlamıyor onlar hiç! 

Bir bilseler…

Her şeye rağmen,

Çırılçıplak kalsam da,

Yoksul olsam da,

İki kere ikinin dört ettiği gibi seviyorum seni.

Parmak hesabına gerek yok ki..

04/2005', 'Emanet bir elbise gibi aşk üzerimde. Sanki benimmişçesine, Aynanın karşısına geçip, Kendime bakıyorum uzun uzun. Ne güzel yakıştı bana bu gi...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/emanet-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-galip-kemali-gunay-japei', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Azdır, 

Özdür

