INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vasiyetname', 'vasiyetname-osman-sofuoglu-2puov', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ön bilgi:Ölümlü dünyada herkes gibi bende bir gün öleceğim.  Benim  sevenlerimin   ardımdan yapmalarını ümit ettiğim olaylar. 

                     Vasiyetnamem

Gençlik elbet biter, ömür de gider.

Yaptığın hayırlar, karşında biter.

Yaptığım kötülük, var ise eğer.

Hakkınızı helal, etmeniz yeter.

                 Bağlanma dünyaya, dünyada biter.

                 Buradan göçüp gitmek, elbette kader.

                 Konuşurken beni siz aranızda.

                 Ardımdan rahmetle anmanız yeter.

Kıldığın namaza verip de değer.

Namazın sonunda bir dua eder.

Ruhuna şad eyle, derseniz eğer.

Bu çok bile gelir, bu bana yeter.

                 Cumadan cumaya, cumadan sonra.

                 Ruhuma Fatiha okuman yeter

                 Bayramdan bayrama, bayramlaşmaya.

                 Gelip de kabrimde bulunman güzel.

                [Kabrimde bir Yasin okuman yeter.]

Üzerimde yeşil otlar bitse de.

Bedenimde toprak, olup gitse de.

Peşimden bir dua eden gelse de.

Ruhuma Fatiha okusa yeter.

                 Buda bana yeter, yeter dostlarım.

                 Sen belki görmezsin, ben hep buradayım.

                 Bugün ben yarın sen geçeriz buradan.

                 Allah ayırmasın Dinden İmandan.', 'Ön bilgi:Ölümlü dünyada herkes gibi bende bir gün öleceğim.  Benim  sevenlerimin   ardımdan yapmalarını ümit ettiğim olaylar.               ...', ARRAY['Türk Edebiyatı','Şiir','Osman Sofuoğlu']::text[], 8.5, '{"poet":"Osman Sofuoğlu","poet_slug":"osman-sofuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/vasiyetname-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-hava-kucuk-1euv6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimbilir ne çok aşklara şahit oldun

Kaç aşık sende ayrıldı, 

Ya da kavuştu.

Ayrılan aşıklara hiç ağladığın oldu mu İstanbul.

Güzelliğin tarifi imkansızdır senin

Bambaşkadır kalbimdeki yerin

Orhan Veli, Necip Fazıl ve bir çok şair sana seslendi.

Bunları duyup mutlu oldun mu İstanbul.

Sultan Fatih ne iyi etmiş almakla seni

Seyretmeye doyamıyorum büyüleyici güzelliğini

Boğaz köprünle gerdanlık takmış gelin gibisin

Ne harikulade olduğunun farkındasın değil mi İstanbul.

Bazen isyan ettim sana

Sevdiklerimi tek tek aldığında

Ama biliyorum ki

Onlarda senin bağrında

Üzme onları ne olur

Daimi sevdam İstanbul İstanbul.', 'Kimbilir ne çok aşklara şahit oldun Kaç aşık sende ayrıldı,  Ya da kavuştu. Ayrılan aşıklara hiç ağladığın oldu mu İstanbul. Güzelliğin tari...', ARRAY['Türk Edebiyatı','Şiir','Hava Küçük']::text[], 8.5, '{"poet":"Hava Küçük","poet_slug":"hava-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/istanbul-210-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Bakıyorum İstanbul', 'sana-bakiyorum-i-stanbul-yunus-yildiz-u3t9s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana bakıyorum İstanbul 

Yüksek tepelerinden sana tepeden bakan o dağlardan

Boğazın serin kıyılarından

  Sana bakıyorum 

Sana bakıyorum İstanbul

Etilerin o cıvıltılı hayatından

Sana bakıyorum 

Ekmeğe muhtaç arka sokaklardan

Sana bakıyorum İstanbul 

Kız kulesinin aşıklarıyla beraber 

Sana bakıyorum 

Sevdanın satıldığı yerlerden

Sana bakıyorum İstanbul

Ekmeğini taştan çıkarmak isteyen emekçilerin yanından

Sana bakıyorum

Menfaat uğruna yaşayanların yanından

Ne sevdaların yaşandığı ne hayatların karardığı

Ne emeklerin yok olduğu ne oyunların döndüğü

Ne güzelliklerin olduğu ne  çirkinliklerin dolduğu

Zalimlerin kol gezdiği aşıkların güzelliklerini sevdiği

Tepelerinle boğaz kıyılarınla

Kısacası her şeyle dolu olan su kısacık hayatımla

SENİ İZLİYOR VE SANA BAKIYORUM İSTANBUL

                                                                  (yunus yıldız) 

                                                                   (20.04.2005)', 'Sana bakıyorum İstanbul  Yüksek tepelerinden sana tepeden bakan o dağlardan Boğazın serin kıyılarından   Sana bakıyorum  Sana bakıyorum İsta...', ARRAY['Türk Edebiyatı','Şiir','Yunus Yıldız']::text[], 8.5, '{"poet":"Yunus Yıldız","poet_slug":"yunus-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sana-bakiyorum-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Tez Davran', 'hadi-tez-davran-cafer-tayyar-ozkan-bi8bl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neden yoksun ki en dar zamanımda,

Böyle mi sözleştik aşk yazılan mekanlarda,

Kadınım diye içtim seni,

Şimdiyse kusuyor yüreğim içindekileri,

Hain törelerin seni bağladığı yerlerde…

Oysa seni, Canparçam diyerek sevip,

Maziden hakkımın helalini istemiştim.

Kaderine kanma yoksa aldanırsın,

Elbet böyle gitmeyecek devran,

Sevgiyi yaşamada vakit kalmadı, 

Son bir gayretle hadi tez davran,

Gün gelip terk edecek seni saran dünyan…

Oysa sana, yeşil dünyam diyerek koşup,

Vuslatla candan can parçasını gözlemiştim. 

Hazanda sevgimize yönelen ufkun,

Sanki kaderine dolanmış mahkum,

Meyden başka yok yerine gelen arzum,

Eskiden şımarıp kollarına doladığın boynum,

Bükük kaldı zifiri karanlıklarda, artık suskun…

Oysa sana, ışıl gözlüm diyerek gelip,

Rızanla sevgini yaşatmanı ummuştum.

Su gibi akıp gitti zaman durmadan,

Şefkatli sevgini verdin umursamadan,

Aşk denizine dalıp giderken,

Düşünemedim sende de bir nefsin,

Senin de bir kadın olduğunu…

Oysa seni, meleğim diyerek sarıp,

Sevdaya borcunu ödemeni beklemiştim.

18 Nisan 2005 Ankara', 'Neden yoksun ki en dar zamanımda, Böyle mi sözleştik aşk yazılan mekanlarda, Kadınım diye içtim seni, Şimdiyse kusuyor yüreğim içindekileri,...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hadi-tez-davran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakın Bedenimi', 'yakin-bedenimi-tunahan-ermihan-ei4sz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir filmin silik bir sahnesinden hatırladığım bir Vekilharcın sözleri misali yakın bedenimi geçmiş çağların ilkel kralları misali yanayım.

Yanayım ki aksın yüreğimin orta yerine sapladığın buzdan hançerler. Akıp gitsin yıllardır kendime ve sana söylediğim tüm yalanlar. Geceleri kimselerin bilmediği diyarlarda işlenen sesli günahlar aksın hatıralarımdan.

Yanmalıyım beni ben yapan tüm insanlar. Elbirliği ile verin bedenimi ateşe. Alev alev yansın sevdiğimin sevdiği tenim. Yansın ki teninin tenime dokunduğu her noktadan aksın dudaklarına olan zaafım. Dumanlarımı salmayın rüzgâra sarın etrafımı. Akıp giden zaafımın dumanı doldursun ciğerlerimi koku alan her yerimi. Nefesim kesilsin ki akıp gitsin tüm duyularımdan mis kokulu parfümleri hatta en sesli günahların sessiz sesleri! 

Bir müddet ayrılmayın etrafımdan. Ruhum bedenimi terk edene kadar bekleyin. Yeterince yanınca bedenim, ruhumda yanan ateş sönecek ve o zaman terk edecek ruhum bedenimi.

Yakın bedenimi beni ben yapan tüm insanlar. Birilerinin bakma ihtimalinin çok zayıf olduğu pencere altlarında tutuşturun bedenimi ve salın bahçesinde açması muhtemel papatyaların toprağına küllerimi.', 'Bir filmin silik bir sahnesinden hatırladığım bir Vekilharcın sözleri misali yakın bedenimi geçmiş çağların ilkel kralları misali yanayım. Y...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yakin-bedenimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dur', 'dur-asuman-durbin-mt425', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '--Dur

Gözlerinde bir başkasını 

ellerinde başka elleri

dudaklarında başka dudak izi

tenine sinmiş başka bir koku

mutluluğuna, tebessümüne

benden başka bir neden

olmasın bir tanem

-dayanamam

dayanmaz bu yürek bu kadar acıya

gizlemeye çalışsam da sevgimi 

üzerini örtemem saklayamam

gözlerim ışıldarken sevgimden

kuytu köşelerde gizleyemem

duysun bilsin herkes- 

---isterim 

haykırmak dağlara taşlara 

çağıl çağıl coşkun akan sulara

martı kanadında yol almak

uçsuz bucaksız gözlerin

kadar maviliklerde

sonsuzluklara varmak

seninle birlikte…………..

13-04-2005', '--Dur Gözlerinde bir başkasını  ellerinde başka elleri dudaklarında başka dudak izi tenine sinmiş başka bir koku mutluluğuna, tebessümüne be...', ARRAY['Türk Edebiyatı','Şiir','Asuman Durbin']::text[], 8.5, '{"poet":"Asuman Durbin","poet_slug":"asuman-durbin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dur-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin', 'gittin-asuman-durbin-xwzw0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'mor tepeli dağlarda 

açmaz olmuş çiçekler

-------gittin diye

martılar maviliklere atmış kendini

-------yoksun diye

kuşlar umutsuzca çırpınmışlar

------dönmeyeceksin diye

taşlar sarsılmış. 

dereler coşmuş

çağlayanlar gürlemiş

------- gittin diye

söyle be sevdiceğim

dağlar taşlar 

dayanamazken yokluğuna 

bu küçücük 

biçare yürek

sessiz sensiz 

çaresizlikler içinde 

nasıl dayanır sensizliğe

 22-04-05', 'mor tepeli dağlarda  açmaz olmuş çiçekler -------gittin diye martılar maviliklere atmış kendini -------yoksun diye kuşlar umutsuzca çırpınmı...', ARRAY['Türk Edebiyatı','Şiir','Asuman Durbin']::text[], 8.5, '{"poet":"Asuman Durbin","poet_slug":"asuman-durbin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gittin-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Bir sigara içimi*', 'bir-sigara-icimi-kubilay-enginol-60po9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Paketinden bir sigara çıkardı

Gülümsedi doğumunu anımsadı

Kokladı sigarayı şöyle bir

Annesi yeni tenini nasıl koklamıştı kimbilir

Yaktı,bir duman çekti hafifçe

Gidiverdi ilkokul günlerine

Üfledi dumanı halka,halka

Geliverdi yaşındaki hakikata

Kahvesinden bir yudum aldı

Sevinçlerin,mutlulukların buruk tadı

Bitiyor sigara,hayatı gibi

Hüzünle bastırdı kül tablasına izmariti', 'Paketinden bir sigara çıkardı Gülümsedi doğumunu anımsadı Kokladı sigarayı şöyle bir Annesi yeni tenini nasıl koklamıştı kimbilir Yaktı,bir ...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-sigara-icimi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem Yazıver Beni', 'kalem-yaziver-beni-ozan-ozel-vip5v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kalem yazıver beni

ana karnındaki halimi

ilk çığlıklarımı

anamdan süt emişimi

doğduğum köy evini

sen doğrusuyla yazıver

yazıver emeklemelerimi

yürümeyi öğrenmemi

düşüp kalkmalarımı

misketlerimi, uçurtmalarımı 

okula başlamamı

sen doğrusuyla yazıver

yazıver delikanlılığa geçişimi

o ilk aşkımı

okulu kırışlarımı

sokak kavgalarımı

üniversite heyecanımı

sen doğrusuyla yazıver

yazıver üniversite yıllarımı

kantin sohbetlerimi

otobüs-yemek kuyruklarını

sevgili hocalarımı

can ciğer arkadaşlarımı

sen doğrusuyla yazıver

yazıver iş hayatımı

stajımı, mavi büromu

beklentilerimi, korkularımı

onunla tanışmamı

ilginç evlilik teklifimi

sen doğrusuyla yazıver

yazıver evliliğimi

aşk meyvemiz; çocuğumuzu

sımsıcacık evimizi

uzun mart gecelerini

kazanıp, kaybettiklerimi

sen doğrusuyla yazıver

yazıver askerliğimi

Azerbaycan’a gidişimi

Bakü anılarımı ve dönüşümü

ailemin beni karşılayışını

yeniden başlangıçlarımı

sen doğrusuyla yazıver

yazıver İzmit’i

oğlumuzun okula başlamasını

yaşadığım gururu, heyecanı

deprem korkumu

babamın ölümünü

sen doğrusuyla yazıver

kalem yazıver beni

yazıver bu garip özgeçmişimi', 'kalem yazıver beni ana karnındaki halimi ilk çığlıklarımı anamdan süt emişimi doğduğum köy evini sen doğrusuyla yazıver yazıver emeklemeleri...', ARRAY['Türk Edebiyatı','Şiir','Ozan Özel']::text[], 8.5, '{"poet":"Ozan Özel","poet_slug":"ozan-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/kalem-yaziver-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğün', 'dugun-burak-killioglu-hsgji', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sağır eden sessizlik, kesildi birden sesim.

Bilinmez bir yerlerde bulunmanın korkusu...

Durdu duracak gibi ağırlaşan nefesim,

Ardımdaki celladın varlığının tortusu.

Ömrümü geri sayan hissiz, mekanik saat,

Yetmezmiş gibi bir de, zembereği boşalmış,

İdam mahkumu için hepsi kuru laf, vaat

Hayatımın tamamı bir saatte yaşanmış.

Tüm dertler, sıkıntılar duvarlarda yazılı.

Karanlık iner inmez, hepsi birden dillenir.

Çözemediklerim bil ki, yüreğime kazılı,

Bir garibin rızkından tamamı sebeplenir.

Akıl; hem büyük nimet, hem kocaman kelepçe...

Nefse kilitledi mi, eder seni kördüğüm...

Beni bana götüren her yol, her gerekçe,

Ezer geçer nefsimi; 40 gün 40 gece düğün!', 'Sağır eden sessizlik, kesildi birden sesim. Bilinmez bir yerlerde bulunmanın korkusu... Durdu duracak gibi ağırlaşan nefesim, Ardımdaki cell...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dugun-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-aynur-baydar-hw5sk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkın tüm tanımları

Uyar uymaz 

Bana ne

Tarifler dilbigisi

Ruhum, gönlüm

Sana denk

Aşk denklemleri matematik

Çözemem, uğraşamam

Bana ne

Sen yoksan 

Döneceğin güne kadar

İzine çıkıyorum

Aşk hoşça kal…', 'Aşkın tüm tanımları Uyar uymaz  Bana ne Tarifler dilbigisi Ruhum, gönlüm Sana denk Aşk denklemleri matematik Çözemem, uğraşamam Bana ne Sen ...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-354-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelin Güvey Oldum', 'gelin-guvey-oldum-mustafa-dilki-0fz85', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu aşkın yegane suçlusu benim 

Ben kendim yanarım kendi derdime 

Ağlasın gözlerim tutuşsun tenim

Gelin güvey odum kendi kendime

Gönülden sevene sevgi pınarmış 

İnsan bir bakışa böyle kanarmış

Bir dağdan habersiz bir dağ yanarmış

Gelin güvey oldum kendi kendime

Ben yalnızca sevdim aşka inandım 

Bir başka bağlandım başka inandım 

Ben o gönlündeki köşke inandım

Gelin güvey oldum kendi kendime 

Belki boş koymazdın şu ellerimi 

Bilseydin hakkında emellerimi

Seninle süsledim hayellerimi

Gelin güvey oldum kendi kendime', 'Bu aşkın yegane suçlusu benim  Ben kendim yanarım kendi derdime  Ağlasın gözlerim tutuşsun tenim Gelin güvey odum kendi kendime Gönülden sev...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gelin-guvey-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı', 'yalanci-mustafa-dilki-vo64x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani 

Ayrılırsak ölürüm 

Demiştin 

Dün seni parkta 

Görmüşler 

Yalancı', 'Hani  Ayrılırsak ölürüm  Demiştin  Dün seni parkta  Görmüşler  Yalancı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalanci-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükenmez Kalemle', 'tukenmez-kalemle-huseyin-avdic-87att', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünya sahifesine yasilmi$im,

Kur$un kalemle.

Ölümle silinip gidecegim,

Ölümsüz bir âleme.

Sahipsiz degilmi$im,

Bu güzel sahifede.

Kâtibim yazacaktir beni,

Tekrar tükenmez kalemle.

Bati Berlin, Mart 1985.', 'Dünya sahifesine yasilmi$im, Kur$un kalemle. Ölümle silinip gidecegim, Ölümsüz bir âleme. Sahipsiz degilmi$im, Bu güzel sahifede. Kâtibim ya...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tukenmez-kalemle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Damlacıklar', 'yagmur-damlaciklar-mustafa-dilki-gvu0t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur damlacıkları gibi

Sırılsıklam aşkımı 

Bilemezsin

Yağmur damlacıkları gibi

Gözyaşlarım

Silemezsin

Güneşli yağmurdu tanıştığımız

Doyumsuz sevgiydi alıştığımız

Gittin, güneşleri de götürdün

Mızıkcılık ettin vefasız 

Hadi gel barışalım 

Hadi gel perişanım

Gönlüm dipsiz kuyularda 

Ağlamakta 

Hadi gel gel artık 

Uzak kıyılarda sabah 

Olmakta', 'Yağmur damlacıkları gibi Sırılsıklam aşkımı  Bilemezsin Yağmur damlacıkları gibi Gözyaşlarım Silemezsin Güneşli yağmurdu tanıştığımız Doyums...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yagmur-damlaciklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhlar Aleminin Gece Bekçisi', 'ruhlar-aleminin-gece-bekcisi-mustafa-dilki-8zg73', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkımı tarife güller gönderdim 

Zengin oldu şehrin tüm çiçekçisi

Senle mutluluktu benim tek derdim

Ben oldum bu aşkın tek emekçisi 

Ruhlar aleminin gece bekçisi 

Gözyaşım uğrunda oldu şelale 

Beni ömrünce almadın kaale

Seni etkilemez ne gül ne lale 

Ben oldum bu aşkın tek emekçisi

Ruhlar aleminin gece bekçisi

Yalnızlığa silah çektim olmadı

Yüreğime seni ektim olmadı

Yıldızlara dikkat çektim olmadı

Ben oldum bu aşkın tek emekçisi

Ruhlar aleminin gece bekçisi

Anla beni müzmin aşkım kör artık 

Dişi kuşum yuvamızı ör artık

Uyan da bir şu halimi gör artık 

Ben oldum bu aşkın tek emekçisi

Ruhlar aleminin gece bekçisi', 'Aşkımı tarife güller gönderdim  Zengin oldu şehrin tüm çiçekçisi Senle mutluluktu benim tek derdim Ben oldum bu aşkın tek emekçisi  Ruhlar a...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ruhlar-aleminin-gece-bekcisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazıyorum', 'yaziyorum-funda-soylemez-5ok4a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Varlıklar dünyasında evren; uçsuz, bucaksız 

Bu evrende bir sistem ''Samanyolu'' demiş birileri, sen ne dersen de

Ve bir gezegen ''Dünya'' diyelim kolay olsun anlaşılması

Bir ülke bu dünyanın yığınla ülkesinin herhangi biri

Bir kenti ülkenin ve bir mahallesi bu kentin

Mahallede bir sokak, diğer benzerleri gibi

Bir ev, yanında dizilmiş diğerleri

Bir oda, bu evin içindekilerden

Odada bir beden bir şeyler yazıyor; iki kollu, iki bacaklı, cinsiyeti dişi

Bir öz, bir ruh, bir dünya, bir varlığın ta kendisi

Üstelik ne eşi var, ne bir benzeri...', 'Varlıklar dünyasında evren; uçsuz, bucaksız  Bu evrende bir sistem ''Samanyolu'' demiş birileri, sen ne dersen de Ve bir gezegen ''Dünya'' diyel...', ARRAY['Türk Edebiyatı','Şiir','Funda Söylemez']::text[], 8.5, '{"poet":"Funda Söylemez","poet_slug":"funda-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yaziyorum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çünkü O Bir İstanbul''dur', 'cunku-o-bir-i-stanbul-dur-huseyin-avdic-y4oqs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu şehir bir Mekke değildir, 

Fakat onun kadar kutsaldır. 

Çünkü bağrında yaşayan, 

Koca bir Fatih Sultan vardır. 

Bu şehir bir Kâbe değildir, 

Fakat onun kadar yücedir. 

Çünkü düne kadar olmuştur, 

Din''e, Hilâfet''e bayraktar. 

Bu şehir Mescid-i Aksa değildir, 

Fakat onun kadar kıymetlidir. 

Çünkü bâtıldan Hakk''a kavuşmuş, 

Cami-i Ayasofya''sı vardır. 

Bu şehir bir Kudüs değildir, 

Fakat onun kadar seçkindir. 

Çünkü, olmuştur Muhammed''in 

Medhine, müjdesine mazhar. 

Ve bu şehir.... 

.... ne kadar yüceltilse, 

O kadar azdır. 

Çünkü o bir İstanbul''dur. 

Çünkü o bir İslâmbol''dur. 

Berlin, Nisan 2005', 'Bu şehir bir Mekke değildir,  Fakat onun kadar kutsaldır.  Çünkü bağrında yaşayan,  Koca bir Fatih Sultan vardır.  Bu şehir bir Kâbe değildi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cunku-o-bir-istanbul-dur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzeldik', 'ne-guzeldik-ayse-yucel-eflbg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne güzeldik biz

Karalama kağıtlarında 

İsminin yanına ismimi yazmak

Ne güzeldi.

Ne güzeldi hayalini kurmak

Bütün çirkinliklerini saklayıp

Seni düşünmek

Ve her sabah aynada görmek

Dudağımın kenarındaki tebessümü

Herşey ne güzeldi...

Varlığın değil de

Varlığını hissetmek

Ne güzeldi sevgilim

Senin bana düşen yansımanı sevmek.', 'Ne güzeldik biz Karalama kağıtlarında  İsminin yanına ismimi yazmak Ne güzeldi. Ne güzeldi hayalini kurmak Bütün çirkinliklerini saklayıp Se...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yücel']::text[], 8.5, '{"poet":"Ayşe Yücel","poet_slug":"ayse-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-guzeldik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyamam', 'uyamam-i-smet-barlioglu-pkt3z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu kadar mı beter edermiş insanı karasevda? 

Seleyi suya, umutlarımı yele vermişim.

Zikrine gönül veren,

Rabb ‘ine can adayan

Dervişlere dönmüşüm; 

Acılarım başlar körpe sabahlarla,

Sürer gider süresiye karanlık gecelerde,

Değil mi ki; 

Çıkarıp ona sunmuş iki elim yüreğini

Biryerlerde.

At benim, sevda benim, kum benim, çöller benim,

Gel gör ki; ben yaralı, atım umarsız,

Çöller desen; bir başına ıssız mı ıssız,

Ne rüzgar görmemiş bir iz, ne bir cömert çıkış yolu,

Yüreğim yarık yarık, dudaklarım çatlak çatlak,

Denize her düşen gibi; 

Yılana sarılacağım

Muhakkak.

Canıma güvenirim; fayda etmez,

Gençliğim akıp gitmiş avuçlarımdan rüzgar gibi

Ardında ak saçlar bırakarak,

İşte bir karasevdadır ki; menzil edinmişim kendime,

Yürürüm; ulaşamam,

Bakarım; göremem,

Dinlerim; duyamam,

Onu bırakıp kendime dönmemi istiyor kör şeytan,

Uyamam.

(KAVAKYELLERİ isimli Serbest Şiirler ''inden > 27-28/100)', 'Bu kadar mı beter edermiş insanı karasevda?  Seleyi suya, umutlarımı yele vermişim. Zikrine gönül veren, Rabb ‘ine can adayan Dervişlere dön...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/uyamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-koca-kus-gljjd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bitti koskoca bir saltanat

Debdebe ihtişam vardı bir zamanlar

Güzel zamanlardı o yaşanan anlar

Göz açıp kapayıncaya kadar süren

Hüzünlü bir duygu

Buruk bir tat bıraktı ardından 

An be an büyüyen bir heyecanla

Gidenin ardından baka kaldım

işte böyle başladı benim hayatım

Bir saltanatın ardından kalan yıkıntılar arasında

Debelenip duruyorum hala

Aklımda yaşanan anların hayali var

Birdaha hiç olmayacaklar biliyorum

Geri gelmeyecek

Dönülemeyecek bu yoldan geri

Dönersem biliyorumki bu bir başlangıç değil

Sonun başlangıcı olacak 

Hep ileri hep ileri gitmeli

Bu bedeni biran evvel  tüketmeli

Yetişmeli,yakalamalı gittiği yerde 

Bir hayal olmalı tekrar', 'Bitti koskoca bir saltanat Debdebe ihtişam vardı bir zamanlar Güzel zamanlardı o yaşanan anlar Göz açıp kapayıncaya kadar süren Hüzünlü bir ...', ARRAY['Türk Edebiyatı','Şiir','Koca Kuş']::text[], 8.5, '{"poet":"Koca Kuş","poet_slug":"koca-kus","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hayal-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılarımız', 'sarkilarimiz-i-smet-barlioglu-mxkhf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgara karşı şarkılar söyleyip duruyorum

Alıp sana getirsin diye,

Yıldızların altında, denizlerin üstünde değil,

Yanan dudaklarımın, kavrulan yüreğimin

Çöllerinde.

Esip esip geçiyor rüzgarlar benden sana doğru,

Şarkılar

Ellerinde.

Bunlar birer sevda şarkısıdır, rüzgarlara karışık,

İçlerinde mahzun yağmurlarımızdan damlalar,

Parıltılar mehtaplı denizlerimizdan

Ve buruk buruk birkaç eski söz

Bizden.

Rüzgarları dinlediğini biliyorum,

Görüyorum tıpkı yanındaymışım gibi; 

Bir elin çenende, bir elin pencerede, denize doğru,

Beyaz gemilere işliyorsun şarkılarımızı,

Martılara işliyorsun rüzgardan alıp

Ve bir beni dinliyorsun

İçe kapanıp.

Süs için mi

Birer tablo gibi bembeyaz gemiler denizde,

Süs için mi martılar böylesine hüzünlü,

Bu seniz süs için mi seni andırıyor mehtapta,

Sen ne kadar olursan ol

Uzakta.? 

(KAVAKYELLERİ isimli Serbest Şiirler ''inden > 29-30/100)', 'Rüzgara karşı şarkılar söyleyip duruyorum Alıp sana getirsin diye, Yıldızların altında, denizlerin üstünde değil, Yanan dudaklarımın, kavrul...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sarkilarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devlet Baba', 'devlet-baba-suleyman-kaya-r5nua', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Devle Baba dedik güvendik sana

Yemedik yedirmedik,içmedik içirmedik

Güvendik sana büyüksün dedik

Halimiz nicedir sorsana Baba

Yanlış yapmadık,haram yemedik

Çalıştık dürüstçe yangel yatmadık

Revamıdır bu hal bu durum bize

Çaresiz bıraktın,yapma be Baba

Yarına umutla bakar dururduk

Tükendi umutlar yarınsız kaldık

Daha güzel günler bekler dururken

Attın bizi ateşe kor olduk Baba

İçimizde değerin büyüktür bizim

Malını mülkünü koruruz Baba

Yaptığın bize cefada olsa

Her zaman saygımız büyüktür Baba

Özelleştirme dedin yaktın bizleri

Attın kuyuya çıkılmaz Baba

Ne makam kaldı,ne yer yurt

Derbeder ettin,yıktın be Baba

Halimiz nicedir gel bir baksana

Kaldık ortada ne olduk bilmem

Dağıttın bizi toplayan lazım

Bu devlete hizmet çalışan lazım

Kadromuz nedirdir bende anlamam

Ne işe yararmış,bende bilemem

Canımız sıkılır bir şey diyemem

Bu da geçer Babamız sabırlar bize

Araştırmacı diye atadın bizi

Neyi araştırır buluruz bilemem Baba

Gazetecimiyiz,yoksa Polismi bende bilemem

Düştük kör kuyuya çıkamam Baba

Halimiz nicedir böyle sürmekte

Ne olur ne biter bilemem Baba

Sayende döndük eski günlere

Sabrımız sonsuzdur bekleriz Baba', 'Devle Baba dedik güvendik sana Yemedik yedirmedik,içmedik içirmedik Güvendik sana büyüksün dedik Halimiz nicedir sorsana Baba Yanlış yapmadı...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Kaya']::text[], 8.5, '{"poet":"Süleyman Kaya","poet_slug":"suleyman-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/devlet-baba-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanmasaydım', 'uyanmasaydim-i-smet-barlioglu-q0msh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu sabah güneş yine sensiz doğdu,

Yine sensiz vurdu pencereme, kapıma.

Ne çimenlerde o eski canlılık,

Ne çiçeklerde o eski heyecan,

Ne de yeni bir güne başladı benim için

Yaşam.

Dilimde yine ayrılıkların o yakıcı tadı,

Yine gelip dudaklarıma oturmuş

Kalbimin feryadı.

Keşke gecelerim bitmeseydi, sabahlara varamasaydım,

Sensiz yeni bir güne başlayacağımı bilip

Uyanmasaydım.

Ne güzelliği var bana bu güneşin,

Bu çimenlerin, bu çiçeklerin, bu kuşların,

Saçımı-başımı birbirine katan bu rüzgarın,

Sensiz yağacak olduktan sonra

Ne güzelliği var

Yağmurların.

İnsafa bırakılmış bir bebek gibiyim; 

Umarsız, sahipsiz, karayazılı.

Boşluğa bırakılan bir taş gibi

Düşmeye mahkum.

Rüzgarda nasıl savrulup gidiyorsa; öyleyim

Şu toz-tozak,

Şu yaprak,

Şu kum.

Benim düşmanım sen değilsin,

Düşmanım bir büyük sensizlik; 

Güneş altında karanlık karanlık çevremi saran,

Beni sarıp sarmalayan,

Kolumu-kanadımı kıran.

Belli ki; bundan sonra hep böyle geçecek

Zaman.

(KAVAKYELLERİ isimli Serbest Şiirler ''inden > 31-32/100)', 'Bu sabah güneş yine sensiz doğdu, Yine sensiz vurdu pencereme, kapıma. Ne çimenlerde o eski canlılık, Ne çiçeklerde o eski heyecan, Ne de ye...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/uyanmasaydim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çırpıya Vurulmalı Yürek', 'cirpiya-vurulmali-yurek-hikmet-kavas-vc680', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yüreğini vur çırpıya

bak filistin çırpıdan hariç mi

...

iki tür çıplak var

birinin apışı barkodlu

birinin tavuk derisi gibi

üşümekten çıplak yerleri

bak üşüyen çırpıdan hariç mi

daha soğumadan toprak

göm yüreğini acılara

göm ki taşsın acılar

başka avlulara

göm fidelik sözcükleri

zaptedilmemiş topraklara

yeniden yeşersin

lekesi zehir zıkkım bir hayat

yüreğini vur çırpıya

bak cesaret senden hariç mi

çekil o zaman usul usul

sözük tarlasından

...

bu da onur sayılır', 'yüreğini vur çırpıya bak filistin çırpıdan hariç mi ... iki tür çıplak var birinin apışı barkodlu birinin tavuk derisi gibi üşümekten çıplak...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Kavas']::text[], 8.5, '{"poet":"Hikmet Kavas","poet_slug":"hikmet-kavas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cirpiya-vurulmali-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çınar', 'cinar-koca-kus-rsbhb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Koca çınar devrildi

Yorgundu bedeni

Dayanamadı gitti zor geçen yılların ardından

O koskoca bedeni taşımadı daha fazla 

Evsiz kaldı kuşlar

Gölgesiz kaldı küçük papatyalar

Boş kaldı toprak

Gök bile şaştı bu işe 

Ne kadar minikti bir zamanlar

Var gücüyle sarılmıştı toprağa

Büyümek için

Hep istediki geniş bir yuva olsun kuşlarla dolsun

Olduda...

Mutluydu.... takii uzun süren vakitsiz gelen kışa kadar

Önce dondu kolları,eğrildi bedeni

Dayandı gene kuşlar vardı yuvada,yavruydular daha

Sabretmek gerekir

Ama olmadı işte..

Vardı bir yazgı kesin bu işte

Odun olsam keşke dedi,yattığı yerde

Yada bir eşya

Kalsam bir köşede 

Bunca geçen yılların hatırı olarak

Anılarda yaşasam', 'Koca çınar devrildi Yorgundu bedeni Dayanamadı gitti zor geçen yılların ardından O koskoca bedeni taşımadı daha fazla  Evsiz kaldı kuşlar Gö...', ARRAY['Türk Edebiyatı','Şiir','Koca Kuş']::text[], 8.5, '{"poet":"Koca Kuş","poet_slug":"koca-kus","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cinar-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bence...', 'bence-i-brahim-ethem-bingul-xuoir', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül defterimden sildim

Tarihe gömdüm nice sevilenleri

Kendi isteklerince...

Ağlamadım

Acıdım hallerine

Kendimi koydum yerlerine

Seven bir gönülden

Silineceğime

Toprak olurum daha iyi

Bence...

Verdim iki canımı toprağa

Sezsizce

Dua oldular dilde

Yaş oldular gözde...

Sevgi ekmişlerdi

Sevgiyle buyur edildiler

Öze...

Dün ne idim, nelere geldim

Bilinmez nerelere giderim...

Tek dileğim

Her zaman sevginin

Hakkını vereyim...

www.iebingul.com', 'Gönül defterimden sildim Tarihe gömdüm nice sevilenleri Kendi isteklerince... Ağlamadım Acıdım hallerine Kendimi koydum yerlerine Seven bir ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bence-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görü-Yorum', 'goru-yorum-nal-n-yildiz-nxry7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ya kör değilsem, bütün mesele gözlükteyse,

Ve bu dünya göründüğü kadar ''el'' değilse...

Kim temizler camlarımı benim elim kolum dolu, kanadım yok...

Ah, ama benim gözlüğüm de yok!', 'Ya kör değilsem, bütün mesele gözlükteyse, Ve bu dünya göründüğü kadar ''el'' değilse... Kim temizler camlarımı benim elim kolum dolu, kanadım...', ARRAY['Türk Edebiyatı','Şiir','Nalân Yıldız']::text[], 8.5, '{"poet":"Nalân Yıldız","poet_slug":"nal-n-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/goru-yorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyet yapanlara eleştiri', 'diyet-yapanlara-elestiri-hasim-koc-rrsjj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yemekler var tatlı tuzlu

Dondurmam var buzlu buzlu

Güveç pişiyor kuzulu

Yiyene afiyet olsun

Birileri diyet yapıp aç geziyor

Allahım onlara akıl versin

Diyetten vaz geçip

Doya doya yemek yesin

Bir deli diyet adında

Bir kuyuya taş atmış

Doğrumu yanlışmı demeden

Birileri diyet yapıp aç kalmış

Diyet yapana yazık sararıp solmuş

Kış geçti bahara erdik

Bırak rejimi lütfen sende

Doya doya yemek ye', 'Yemekler var tatlı tuzlu Dondurmam var buzlu buzlu Güveç pişiyor kuzulu Yiyene afiyet olsun Birileri diyet yapıp aç geziyor Allahım onlara a...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/diyet-yapanlara-elestiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülser', 'ulser-i-brahim-cetinkaya-t7s0j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Keşke bende; 

Tapusunu hüznümden almış bir hastalık yerine 

Bütün hastalıklarıma şifa 

bir gülüşünle kalsaydın...

Çünkü seni; 

Şifasız bir hastalığın bedeni sevdiği gibi çok sevdim.', 'Keşke bende;  Tapusunu hüznümden almış bir hastalık yerine  Bütün hastalıklarıma şifa  bir gülüşünle kalsaydın... Çünkü seni;  Şifasız bir h...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çetinkaya']::text[], 8.5, '{"poet":"İbrahim Çetinkaya","poet_slug":"i-brahim-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ulser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale''nin Şehitleri -2', 'canakkale-nin-sehitleri-2-bulent-kilic-l02ba', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Astı sazını duvara Mehmet,

Düştü yollara bir kuşun kanadı üstüne asılmış 

O en güzel türküyü söylemek için.

“Uçtum ardın sıra yüce dağlarda

Sevdiğim beni bekler burdan uzaklarda”

Saz duvarda tüfek memedin omzundaydı.

Anası bağırdı ardından Mehmet’in 

“Oğul mukayıt ol kendine. 

Koma ananı buralarda öksüz.

Git. 

Git ama dön geri oğul.

Sensiz olmaz tadı bu dünyanın”

Mehmet’in omzunda silah,

Kulağında yankısı anasının uğurlamasının.

Sevgi’nin döküldü dudağından

Söylemeye gücünün yetmediği,

Söylemeye dilinin varmadığı

O kelime:

“Git. 

Beni bir başıma kosanda

Yüreğime tarifini bilemeyeceğim acıları kondursanda git.

Bırak ben yine senin sevdiği kalayım.

Git ama unutma verdiğimiz sözü.

İki cihanın gücü yetmez

Bizi ayrı kılmaya.”

Mehmetin omzunda silah

Sevgi’si yüreğindeydi.

Ne çok gürültü vardı.

Türküsünü söyleyemiyordu mehmet.

Söylese de duyulmayacaktı.

Ne çok gürültü vardı.

Anasını duyamıyordu mehmet.

Duysaydı ses verecekti.

Ne çok gürültü vardı.

Sevgisini hissedemiyodu mehmet.

Hissedebilseydi yüreğini bulacaktı.

Mehmet sağır, mehmet dilsiz, mehmet kalpsiz.

Mehmet bir garip oğlan.

Kapadı kulaklarını, yumdu gözlerini.

Açtı yüreğini.

Türküleri için, sazı için.

Anası için, yari için.

Söyledi son türküsünü sesinin yettiğince 

Yüreğinin yettiğince.

“hosçakalın sevdiklerim.

Gitmeliyim sizin için 

Sazım senin için.

Sen çalınmalısın özgürlük türkülerinde.

Anam senin için.

Duymamalısın başka anaların ağıtlarını.

Sevgi’m senin için.

Dokunmamalı yaban gözler gözlerine.”

Mehmet’in omzunda silah,

Yüreğinde badem gözlü bir cocuğun kurşunu.

Mehmet yatar kıpkırmızı, 

Bembeyaz ayın ve yıldızın altında.

Sessizdir Mehmet.

Bir mart ayının 18’inde 

Bahara girmeye yakın zamanlarda

Bademlerin çiçek açtığı o günde 

Çanakkale boğazında.

Ve söyler emperyalizme karşı.

Özgürlüğün marşını.

“Çanakkale geçilmez.”

Sazı için, anası için, sevdiği için...

Bülent KILIÇ', 'Astı sazını duvara Mehmet, Düştü yollara bir kuşun kanadı üstüne asılmış  O en güzel türküyü söylemek için. “Uçtum ardın sıra yüce dağlarda ...', ARRAY['Türk Edebiyatı','Şiir','Bülent Kılıç']::text[], 8.5, '{"poet":"Bülent Kılıç","poet_slug":"bulent-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/canakkale-nin-sehitleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oya Aydoğan', 'oya-aydogan-hasim-koc-5ikiy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzel yüzlü oyamız

Sanki dolunay

Tadı sanki kaymak

Anzer bal

Programlarınıza doyamıyoruz

Bize bir saat yetmiyor

Bize lazım aylar yıllar

Sevgili OYA AYDOĞAN

Seni zevkle izliyoruz

Tiryakilik oldun

Hayalimizde

Düşümüzde

Olmaya başladın

Beğenip seviyoruz

İyiki varsın diyoruz', 'Güzel yüzlü oyamız Sanki dolunay Tadı sanki kaymak Anzer bal Programlarınıza doyamıyoruz Bize bir saat yetmiyor Bize lazım aylar yıllar Sevg...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/oya-aydogan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nur demişler adına', 'nur-demisler-adina-hasim-koc-y6cvw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir güzelki ALLAH nazardan korusun

Dostu sevindirir düşmanı çatlatır

Giyinir kuşanır olur dünya güzeli

Dudak ısırtır yürekleri hoplatır

NUR demişler adına

Bal kaymak katmışlar tadına

Sıcaklık katmıslar kanına

Aman aman her övgüye

Layıktır bu nur

Sevmeye sevilmeye layıktır bu nur', 'Bir güzelki ALLAH nazardan korusun Dostu sevindirir düşmanı çatlatır Giyinir kuşanır olur dünya güzeli Dudak ısırtır yürekleri hoplatır NUR ...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nur-demisler-adina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudakların', 'dudaklarin-kamil-boyraz-eyrv3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Utanma bakınca yeşil gözüne

Bana hasret kaldı kor dudakların

Yüzünü öteye dönüpde gitme

Benden bir parçaydı bal dudakların.

Sahibiydim kiracıyım sayende

Bir saatlik mola versem sinende

Ne bende sabır kaldı ne sende

Öpmeye doyulmaz al dudakların.

Simana yakışan pembe yanakdan

Gerdana süzülen ipek saçından

Gökde ay misali hilal kaşından

Dahada güzeldir şol dudakların

Mimiğin üstünde siyahtır beni

Allah özenipde yaratmış seni

Doksan altmış olmuş bedeni

Karşımda konuşmaz lal dudakların

Tadı sakarindi çayıma koydum.

Kurt kadar açtım hemencik doydum.

Kadehlerime koydum yudum yudum.

İçtikce kandırdı bol dudakların', 'Utanma bakınca yeşil gözüne Bana hasret kaldı kor dudakların Yüzünü öteye dönüpde gitme Benden bir parçaydı bal dudakların. Sahibiydim kirac...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dudaklarin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin?', 'nerdesin-i-brahim-cetinkaya-y6dnr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Firari uykuların güler yüzlü meleği 

			Nerdesin? 

O kadar açım ki sana 

Bir o kadar aciz 

Yitirdim işte eski neşemi 

Sen gideli 

Sen gideli ne çok şarkı eskidi 

Kalbim kırıldı çok kez

Gözlerim ağlamaktan kesildi

Şiir yazmayı unuttum nerdeyse 

Nerdeyse gülmeyi

Hani dans ederdik seninle 

gece gönlümüze çökünce

hıçkıra hıçkıra ağlayarak 

Hani ben söylerdim 

Sen yazardın 

Altına bu benim için 

Ne çok şiir yazdım ben senin için 

Peki şimdi nerdesin 

Ben o kadar muhtaçken sana

Neden gelmiyorsun artık 

Üstelik kalbim kırık

yüreğim acıyor, ağlayamıyorum bile 

Nerdesin? 

Firari uykuların güler yüzlü meleği', 'Firari uykuların güler yüzlü meleği  			Nerdesin?  O kadar açım ki sana  Bir o kadar aciz  Yitirdim işte eski neşemi  Sen gideli  Sen gideli...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çetinkaya']::text[], 8.5, '{"poet":"İbrahim Çetinkaya","poet_slug":"i-brahim-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/nerdesin-111-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alabildiğince bahar', 'alabildigince-bahar-hayri-padak-udbxe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kardelen uyanır ilkin uykusundan

Uzaklardan, çok uzaklardan

Kuşlar döner, kanatlarında bahar 

Ve saçılır kanatlarından tohumlar

Sonra bir sabah toprak,

Toprak kokar

Apak örtüsünde

      Yeşil

             Sarı

                      Al

                          Mor

Alabildiğince hür

Alabildiğince bahar.

Mavi mavi kanat çırpar kuşlar

Uzaklardan, çok uzaklardan

Kuşlar döner kanatlarında bahar

Ve saçılır nil umutlar

Sonra bir sabah gök

Gök, gün kokar

Gök

       Mavi 

               Gök 

                      Beyaz 

Alabildiğince hür

Alabildiğince bahar.

Dalga dalga kanat çırpar kuşlar

Uzaklardan, çok uzaklardan

Kuşlar döner, cıvıl cıvıl

Ve tabiat kayulla uykusundan uyanır

Sonra bir sabah ağaçlar

Ağaçlar dal 

 Dal 

       Yaprak

                   Dal

    	       Çiçek 

Alabildiğince hür

Alabildiğince bahar', 'Bir kardelen uyanır ilkin uykusundan Uzaklardan, çok uzaklardan Kuşlar döner, kanatlarında bahar  Ve saçılır kanatlarından tohumlar Sonra bi...', ARRAY['Türk Edebiyatı','Şiir','Hayri Padak']::text[], 8.5, '{"poet":"Hayri Padak","poet_slug":"hayri-padak","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/alabildigince-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale''nin Şehitleri -1', 'canakkale-nin-sehitleri-1-bulent-kilic-v62yk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '“Böyle bir günde ölünmemeliydi! ” dedim.

Görünce pembe çiçek açmış bademleri.

Oysa onlar öldüler.

Belki de gözlerindeki son görüntü olan

Pembe çiçekli bademler arasında.

Açıklardan esen rüzgar taşıyordu.

Çok uzaklardan gelen acılı haykırışları.

Onlardı ölen evlerinden çok uzakta.

Kızıla boyayarak mavi bir denizi

Ve rüzgar bir taraftan söylüyor

Onların ağıtlarını; 

Uzaklardan annelerin rüzgara teslim ettiği.

Hatırlamıyorum kimin dediğini.

Ama demişti bir şair.

“bütün savaşlar annelerin şavaşıdır.

Çünkü en çok acıyı anneler çeker” diye.

Çünkü yitirirler badem gözlü çocuklarını 

Bir bahar vakti

Bilmedikleri bir yerlerde....

Bülent Kılıç', '“Böyle bir günde ölünmemeliydi! ” dedim. Görünce pembe çiçek açmış bademleri. Oysa onlar öldüler. Belki de gözlerindeki son görüntü olan Pem...', ARRAY['Türk Edebiyatı','Şiir','Bülent Kılıç']::text[], 8.5, '{"poet":"Bülent Kılıç","poet_slug":"bulent-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/canakkale-nin-sehitleri-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bana Bakma', 'sen-bana-bakma-timucin-gecer-byo27', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bırakma sakın yakamı 

sev beni ötelere hiç bakmadan 

kumarbaz rüyaların senaryolarına imza at ikimiz için 

son sabah olmayacak gibi tutkulu olsun sevdamız. 

tüm balıkları koy sofrasına yemeğimizin

rakı içeceksek bir mum yerleştir ortasına en romantik halimizin

gülümsemeyle yap makyajını ve çıplaklık olsun gece elbisen

kimselere haber vermeksizin ikimiz için bile değil.

yatağa ser temiz kokusunu havanın 

ormanın kenarında yetişmişsin sen

çamların kokusunu içinde büyütmüşsün 

ve paylaşmışsın onca zaman dudaklarınla.

kaburgalarının hemen üzerindedir kozalakları kadın ağacının

kökleri ince uzun sarılmış belime titremiş gecelerce

yaprak dökmeksizin bahar kış.

ağlayan ormanlar gibi bakma yüzüme 

otoyol tecavüzü değil bizimki

yada içten içe kemirmesi bir kurdun gövdeyi

küsmesi değil gölgede kalmış açmadan solmuş kardelenin

sakın deme.sevdanın eskimişliği de değil

ihtimal zamanın gelmişliği sabaha karşı.

bir bayram arifesinde alınmış ayakkabıyı görmüş gibi 

yastığının hemen yanında, içinde bir çığlıkla uyanacağına söz ver.

üstünden hemen komidinin bir sigara alacağına 

sevişmişiz gibi sıcak bir öpücükle paylaşacağına nikotini söz ver.

sabaha karşı uyandığında sevdadan ölecekmiş gibi hissedeceğine

ve mutluluktan yaşarmış olacağına gözlerinin söz ver.

taksime gideceksin bu haftasonu. sinemadan çıkar çıkmaz

ilk sokak satıcısından alacağın kestanelerin kabuklarını soy benim için.

kitapçılara bakmadan geçip ortasından insanların

ilk kürkçü dükkanına gireceksin sevmediğimi bile bile 

astragan bir kürk alacaksın. ojelerin parlayacak parmaklarında

kuaförsüz toplamış olacaksın saçlarını

beni unutmuş gibi bakacaksın moda dergilerinden taşanlara.

hiç incitmeyecek baharda yeniden sevdalanışın

haftasonu hiç içmemiş olacağım damarlarımda okunamayacak alkolün esamesi.

ihtimal geceden bulaşık olacak karaciğerime venlafaxin

miligram hesabı yapmadan kusacağım sevdamı klozete 

keskin bir tad bırakırsa çalkalayacağım ağzımı.

üst katta sürekli kaçıracak bir musluk ve ben hiç rahatsız olmayacağım

sen gidince inan hiç umursamayacağım yeniden sevdalanışını.', 'bırakma sakın yakamı  sev beni ötelere hiç bakmadan  kumarbaz rüyaların senaryolarına imza at ikimiz için  son sabah olmayacak gibi tutkulu ...', ARRAY['Türk Edebiyatı','Şiir','Timuçin Geçer']::text[], 8.5, '{"poet":"Timuçin Geçer","poet_slug":"timucin-gecer","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sen-bana-bakma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-ali-hamdi-eray-46up8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boğaza yerleşen ey anıt şehir,

Kıtalar birleşir sinende senin.

Ey koca çınarım, ey büyükşehir,

Kaç kültür barınır sinende senin.

Altın Boynuzdaki ılk yerleşimin,

Uzanır önceki üç bine değin.

Sinan mührü taşır en muhteşemi,

Eserlerle dolu Tarihin senin.

Karada yürüdü gemiler sende,

Denize sürüldü atlar seferde.

Ortaçağ nerdedir, yeniçağ nerde.

Yeni bir çağ açan Fatihin senin.

Sadabat sendedir, laleler sende, 

Şarkılar sen için, gazeller sende.

Bin türlü zevk ile yaşam var sende,

Şeyda Nedim idi Şairin senin.

Güzellik kimdedir zerafet kimde,? 

İhtişam kimdedir estetik kimde.? 

Kaybettik Atayı Dolmabahçende,

O Büyük acında içimde senin.

Göğsünde gerdanlık, senin köprüler.

Boğazında büyük küçük Gemiler.

Metronla insanlar güçlüğü yener, 

Şehirler içinde çağdaşlık senin.

Uğrunda can veren nicedir senin, 

Kan veren, şan veren, nicedir senin,

Cesur ve fedakar olan milletin,

Cefalı gönlünün sevgisi senin,

Vefalı gönlünün sevgisi senin.', 'Boğaza yerleşen ey anıt şehir, Kıtalar birleşir sinende senin. Ey koca çınarım, ey büyükşehir, Kaç kültür barınır sinende senin. Altın Boynu...', ARRAY['Türk Edebiyatı','Şiir','Ali Hamdi Eray']::text[], 8.5, '{"poet":"Ali Hamdi Eray","poet_slug":"ali-hamdi-eray","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/istanbul-211-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-funda-soylemez-tqkya', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat garipliklerle dolu

İnsanlar, içlerinden her an süpriz çıkabilecek tavan arası sandıkları

Günler ya çok dolu; öldüresiye yoran

Ya çok boş; insanı boğan

Ya da garip anlamlandırılamayan

Eğer bir açıklama getirmek istersen şu hayata

İnsanlara, günlere

O zaman vay haline

Tek çıkış yolu var; 

''Hayat garip'' demek

Bunu böyle kabul etmek

Bir çuvaldan kafa istemiyorsan omuzlarının üstünde

Kaşların çok yakınlaşmaya başlıyorsa birbirine

Ya da geç gördüğünü fark ediyorsan baharın ilk filizini

Sıyrıl kendinden ve yak ışıkları

Gör o filizi

Gül, gariplere, garipliklere

Yaşa, komik ya da eğlenceli

Bil, buraya geldin ve gideceksin

Yaşadıkların sana, yanlızca sana kalacak

Ne kızdığın ama kırmamak için asla söyleyemediğin insanlara

Ne kendini bir türlü ifade edemediğin kişilere

Ne de diğerlerinin başarmış olduğu halde 

Senin hala başlayamadığın işlere

Sev tarafsızca, kendinden, içten, karşılıksız

Koşulsuzcasına...

Sev

Ve yaşa

Anını, seni ve gözçeperleriyle akıldan oluşan çerçevenin içindeki hayatı', 'Hayat garipliklerle dolu İnsanlar, içlerinden her an süpriz çıkabilecek tavan arası sandıkları Günler ya çok dolu; öldüresiye yoran Ya çok b...', ARRAY['Türk Edebiyatı','Şiir','Funda Söylemez']::text[], 8.5, '{"poet":"Funda Söylemez","poet_slug":"funda-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hayat-199-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersen...', 'gidersen-hasan-can-7lkm2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gidersen gücüm yetmez sensizliğe,

Götürür beni bu deli gönül gecenin kuytusuna.

Yalnız olamam onca yaşananlardan sonra,

Gitme alamam kendimi bu çaresizlikten.

Gidersen, yağmurlar yağmaz artık caddelerin kirli yüzüne,

Rüzgar kendini salmaz sokakların kararan sessizliğine,

Hayat bana acı verir yürüdüğüm her yolun sonunda,

Gitme kaybolurum seni ararken sensizlikte.

Gidersen bütün kapılar kapanacak,

Gidecek yerim kalmayacak,

Bir yıl değil bir gün bile,

Sen olmasan olmayacak.

Gidersen o gülen yüzümden geriye yaşlı gözler kalır,

Dinlediğim her şarkı ömrümden bir gün alır,

Gitme. gidersen benden geriye sessiz bir beden kalır...', 'Gidersen gücüm yetmez sensizliğe, Götürür beni bu deli gönül gecenin kuytusuna. Yalnız olamam onca yaşananlardan sonra, Gitme alamam kendimi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gidersen-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perihan savaş', 'perihan-savas-hasim-koc-g23vr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'PERİHAN sın  han kadınsın

Tatlı dilli can kadınsın

Asaletli hanedansın

TÜRKİYE nin güzel kızı

PERİHAN SAVAŞ', 'PERİHAN sın  han kadınsın Tatlı dilli can kadınsın Asaletli hanedansın TÜRKİYE nin güzel kızı PERİHAN SAVAŞ...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/perihan-savas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülben diye bir kız', 'gulben-diye-bir-kiz-hasim-koc-duewd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gül bahçesinde gezermiş

GÜLBEN diye bir kız

Her kes onu çok severmiş

Kalamazmış yalınız', 'Gül bahçesinde gezermiş GÜLBEN diye bir kız Her kes onu çok severmiş Kalamazmış yalınız...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gulben-diye-bir-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaşlık', 'arkadaslik-hasim-koc-q4261', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arkadaşlık DÜNYA üzerinde

Bütün insanların kalplerini

Birleştiren

Altın

İplik gibidir

Buluşup görüşüldükçe parıldar', 'Arkadaşlık DÜNYA üzerinde Bütün insanların kalplerini Birleştiren Altın İplik gibidir Buluşup görüşüldükçe parıldar...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/arkadaslik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-hasim-koc-2dx15', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk ilk defa gözlerde

Başlar demişlerdide inanmamıştım

Aşk tatlı şeydir

Demişlerdide inanmamıştım

Aldanma büyüsüne

Demişlerdide inanmamıştım

Düştüm ben aşka

Yandım arkadaş yandım', 'Aşk ilk defa gözlerde Başlar demişlerdide inanmamıştım Aşk tatlı şeydir Demişlerdide inanmamıştım Aldanma büyüsüne Demişlerdide inanmamıştım...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-355-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek bir genç kızsa aşığı bülbül', 'cicek-bir-genc-kizsa-asigi-bulbul-hasim-koc-72148', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çiçek bir genç kızsa

Aşığı bülbül

Fazla naz aşık usandırır

Yorulur bülbül

Bir gülü ne kadar çok 

Sevsede bülbül

Fazla naz aşık usandırır

Yorulur bülbül', 'Çiçek bir genç kızsa Aşığı bülbül Fazla naz aşık usandırır Yorulur bülbül Bir gülü ne kadar çok  Sevsede bülbül Fazla naz aşık usandırır Yor...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cicek-bir-genc-kizsa-asigi-bulbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben maçoyum seni kırarım', 'ben-macoyum-seni-kirarim-hasim-koc-16sdk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevme beni be kızım

Ben maçoyum seni kırarım

Ellerini uzatma bana

Sertce sıkar incitirim

Bana sevgi dolu gözlerle bakma

Sana düşmanım gibi bakarım

Sevgilim gibi bakamam

Ben nezaket nedir bilmem

Hop oturur hop kalkarım

Kibarca konuşamam

Abuk subuk konuşurum

Ben uyku nedir bilmem

Ev bark bilmem

Bar pavyon dolaşır

İçerim sarhoş gezerim

Ricam bana bağlanma kızım

Mutlulukla tanışıp

Sana bağlanıyorum

Seninle mutlu oluyorum

Maçoyum ben

Sevmeyi beceremiyorum 

Acılarla doluyorum', 'Sevme beni be kızım Ben maçoyum seni kırarım Ellerini uzatma bana Sertce sıkar incitirim Bana sevgi dolu gözlerle bakma Sana düşmanım gibi b...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ben-macoyum-seni-kirarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev Beni Sebepsiz Yere', 'sev-beni-sebepsiz-yere-melih-coskun-stn5y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gördüm toprakta karaltıyı

Duydum dizlerimde 

İğrenç sızısını güneşsizliğimin.

Çölleşen göğsüm

Yağmura hasret nicedir.

Mutlu günlerimde oldu saniyeler gibi geçen 

Mutsuzluğumdu asırlar boyu sürüp giden 

Sahipsiz gönlüm

Sebebi olmadan sevilmeye hasret yıllardır.

Ne aynı kanı taşıdığın için damarlarında

Ne de aynı şarkılara ağladığın için hüzünlü akşamlarında.

Gönlüm severek sevilmeye hasret yıllardır

“Seni seviyorum

Çünkü…………” demeden sevilmeye.

Ne olur sev beni sebepsiz yere...', 'Gördüm toprakta karaltıyı Duydum dizlerimde  İğrenç sızısını güneşsizliğimin. Çölleşen göğsüm Yağmura hasret nicedir. Mutlu günlerimde oldu ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sev-beni-sebepsiz-yere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köy öğretmeniyim', 'koy-ogretmeniyim-hasim-koc-5qf9p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben ATATÜRK çü

Ben görev aşığı

TÜRK öğretmeniyim

Görevim sabahleyin

Görevim öğlenleyin

Her an beni bekliyor

Candan yakın talabelerim

Sabahleyin girince sınıfa

Sanki günlerce özlemiş

Sanki yıllarca beklemiş gibi

Toplanırlar başıma

Bakmazlar yaşlarına

Bırakmazlar dalayım

Geçmiş anılarıma

Gögüs gerecem 

Bütün sorunlarıma

Tükenmeyecek sabrım

Eğitimde her hizmete hazırım

Budur arzum kararım

İşte böyle aydınlık

Egitimde yolumuz

Mevla bile ilk sözde

Dememişmi oku kulum

Bende sana aşığım

Canım okulum', 'Ben ATATÜRK çü Ben görev aşığı TÜRK öğretmeniyim Görevim sabahleyin Görevim öğlenleyin Her an beni bekliyor Candan yakın talabelerim Sabahle...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/koy-ogretmeniyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zormuş', 'zormus-ayse-yucel-81ijk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir mutluluk tiyatrosunda oynamak ne zormuş

Ne zormuş sadece dudaklarınla gülmek

Yapayalnız arşınlarken sokakları

Ankara''nın ayazı ne zormuş

İki damla yaş dolunca gözlerine 

Akıtamamak

İki çift laf gelince dilinin ucuna

Söyleyememek

Her saniye yeniden ölmek

Ve aynı zamanda ölememek

En unutulası olanı unutamamak

Düşmek

Ve ayağa kalkamamak

Kimseyi göremem korkusuyla arkaya bakamamak

Sevmek

Nefret etmek

Yemek

Oturmak

Kalkmak

Yaşamak ne zormuş Allah''ım

Yaşamak ne zor...', 'Bir mutluluk tiyatrosunda oynamak ne zormuş Ne zormuş sadece dudaklarınla gülmek Yapayalnız arşınlarken sokakları Ankara''nın ayazı ne zormuş...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yücel']::text[], 8.5, '{"poet":"Ayşe Yücel","poet_slug":"ayse-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zormus-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstan''bul''a Yolculuk', 'i-stan-bul-a-yolculuk-eray-bayram-sahin-updf4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece oluyor iniyorum

Gökyüzünden bu şehre 

Işıkları vuruyor yüzüme camilerin

Düşerken tutunuyorum minarelerine

Bir ayağımı koyuyorum Asya`ya

Bir diğeri Avrupa`da

İki koca hamak boğazında kentin

Sallıyor bir aşktan

Bir akıldan yana

Ey deniz! Nedir bu kız kulesi? 

Göğsünde parlıyor, madalya sanki

Kime karşı, ne zaman ve neden bilinmez

Bir zafer kazanmış besbelli

Yedi kat yer,

Yedi kat gök

Bu şehir yedi tepe

Alem yoksa sen misin? 

İstanbul sırrını söyle!', 'Gece oluyor iniyorum Gökyüzünden bu şehre  Işıkları vuruyor yüzüme camilerin Düşerken tutunuyorum minarelerine Bir ayağımı koyuyorum Asya`ya...', ARRAY['Türk Edebiyatı','Şiir','Eray Bayram Şahin']::text[], 8.5, '{"poet":"Eray Bayram Şahin","poet_slug":"eray-bayram-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/istan-bul-a-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anka', 'anka-cigdem-bir-genc-lluea', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Savruldum...

bir tren garından el salladım kendime

giden ben...

kalan benden birşeyler...

tirajı yüksek bir mecmuanın

ziyade  kelimesi gibi  ayrılık

ve muhtemel her daim gitmeler......

gitmeler...

acı verir

gerekir! 

ve tren kalkar...

düşsel dumanlar bırakır ardında ırar...

bir çığlık koparır kalan yarım

yolculuk başlar...', 'Savruldum... bir tren garından el salladım kendime giden ben... kalan benden birşeyler... tirajı yüksek bir mecmuanın ziyade  kelimesi gibi ...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/anka-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denize Karşı Ağlayan Adamın Şiiri', 'denize-karsi-aglayan-adamin-siiri-ayse-yucel-73lia', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşam feryâd ederdi içimde

Çığlık çığlığa susardım

Aşkını öldürmeye çalışırdım

Tadını bilmediğim yabancı dudaklarda...

Bir odanın kapısını çarpıp çıkmamla başlardı seni her terkediş,

Senin olduğun bir başka odaya girmemle

Biterdi...

Bir koku sinerdi üzerime

Ve sonra hayatıma

Gitmek isteyip gidemezdim

Bağlıydım

Senindim

Ama bir de sensizdim üstelik

Denize karşı ağlayan

Yalnız bir adamın resmiydi bence hayat

Bilemezdim hangimizdik o resimdeki adam

Üşürdüm, ağlardım

Yokluğuna dokunurdum ellerimle de

Sana dokunamazdım

Anlatmak isteyip susardım

Kaçmak isteyip kalırdım

Doğrularımı kaybederdim 

Senin çizdiğin hayat yolumda

Eğrilerimle yaşamaya çalışır...

Ölürdüm

Asılı kalırdım bir saatin sarkacına

Yaşamla ölüm arasında gidip gelirdim', 'Yaşam feryâd ederdi içimde Çığlık çığlığa susardım Aşkını öldürmeye çalışırdım Tadını bilmediğim yabancı dudaklarda... Bir odanın kapısını ç...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yücel']::text[], 8.5, '{"poet":"Ayşe Yücel","poet_slug":"ayse-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/denize-karsi-aglayan-adamin-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Saklı', 'adi-sakli-zuhal-sonmez-gja23', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu sana ilk mektup gecenin sabaha vardığımız ocağı

Tadı insan tadı vazgeçemediğim

Arak tadı ağzındai öpücük

Gürültülerimiz,

sevişmenin başlangıcı

Sen kaldırım kahpesi kadar deneyimli

Sen Kardelen kadar 

                              mevsimini bilen çiçek gibi

                                       ayrıntılısın

Dün akşam vazgeçtim,

İşe yaramaz tüm saplantılarımdan

Sabahımdan ve yabancılıklarımdan

Utandım! 

Denizimden ve yağmurumdan

Sen gençliğimin eli sopalı,

sen kadınlığımın arzularında,

tekilliğimin uzun yoluydun

Hiçbirşey olan herşeydi yaşadıklarımız

Adı seviyorum olmayan

ADI SAKLI

                  ZUHAL SÖNMEZ', 'Bu sana ilk mektup gecenin sabaha vardığımız ocağı Tadı insan tadı vazgeçemediğim Arak tadı ağzındai öpücük Gürültülerimiz, sevişmenin başla...', ARRAY['Türk Edebiyatı','Şiir','Zuhal Sönmez']::text[], 8.5, '{"poet":"Zuhal Sönmez","poet_slug":"zuhal-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/adi-sakli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benimdin', 'sen-benimdin-ayse-yucel-igw21', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her hecesinde asılı kaldığım

Bitirmeye kıyamadığım 

Ama bir solukta okuduğum kitaplar gibiydin

Kaybetmek korkusuydun sen benim için,

Belâ bir iç sızısıydın

Yazıp bir kenara attığım kimbilir kaçıncı şiirin sebebiydin

Sen ilk farkına varışımdın yalnızlığımın

Suskunluğumdun

Karanlık sokaklarda tek çıkmazım,

Ve yine de herşeyin tek çaresiydin

Sızım, ateşim, dinginliğim

Deli çocuğum, serserimdin

Bayram sabahları gibi heveslenişim

Dünya dursa vazgeçmem dediğim

Ve bir gece yarısı ağlayarak geçtiğimdin', 'Her hecesinde asılı kaldığım Bitirmeye kıyamadığım  Ama bir solukta okuduğum kitaplar gibiydin Kaybetmek korkusuydun sen benim için, Belâ bi...', ARRAY['Türk Edebiyatı','Şiir','Ayşe Yücel']::text[], 8.5, '{"poet":"Ayşe Yücel","poet_slug":"ayse-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-benimdin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-i-lknur-cekici-k3tqx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgi emektir

Zamanla derinleşen

Bir iç ahenktir

Özen ister

İlgi bekler

Savunmasız bir kuş gibi

Korunmak ister

Kırılırsa kolu kanadı

Konmaz olur mutluluğa

Nafile yakarışlar

Anlamsız çırpınışlar

Zamanla tükenir

Tüm umutlar

Kavuşmaz sevdalılar

                                (17.04.2005)', 'Sevgi emektir Zamanla derinleşen Bir iç ahenktir Özen ister İlgi bekler Savunmasız bir kuş gibi Korunmak ister Kırılırsa kolu kanadı Konmaz ...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgi-173-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesaret Dedikleri', 'cesaret-dedikleri-ozgur-celik-19h5v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''küçük kıza...''

cesaret, hayatın içinde olmak mı sence 

cesaret, yürümümek mi sokaklarda 

yada yüzleşmek mi gerçeklerle 

bence hiç biri 

cesaret kabullenmektir acizliği 

cesaret kabullenmektir yenilğiyi 

bu acizlik hükmetmek degil kadere 

yada baştan yazmak değil kaderini 

düşünsene bir kılvılcım ışık olmasa nasıl görür insan 

nasıl hükmeder geceye 

yenilgi dedimse 

bu insana karşı değil 

duygulara karşı bir yenilgi 

hangi insan birebir 

hükmedebilirki hislerine 

bazan bir duygunun peşinde yiter gider 

işte demem o ki sana 

kabullenmişsen acizliği 

kabullenmişsen yenilgiyi 

işte o zaman cesursun 

işte o zaman çıkıp yürümelisin sokakta 

yoksa pence kenarında oturmalı 

kendine göre bir dünya görmelisin 

işte bende öyle yapıyorum 

oturup pencere kenarına 

griye boyuyorum herşeyi 

yoksa haksızlık olur 

pencereden görünen farklı objelere 

gökyüzüne mavi deyip 

yeşile boyarsan agaçları 

yada toz pembeye aşkları 

haksızlık olur 

inip aşagı birebir dokunup 

yaşadıktan sonra koymalısın herşeyin rengini

şimdilik cesaretim yok 

aşağı inip dokunmaya gökyüzüne 

yada yaşamaya aşkı 

hepsi uzak hepsi gri 

şimdi....', '''küçük kıza...'' cesaret, hayatın içinde olmak mı sence  cesaret, yürümümek mi sokaklarda  yada yüzleşmek mi gerçeklerle  bence hiç biri  ces...', ARRAY['Türk Edebiyatı','Şiir','Özgür Çelik']::text[], 8.5, '{"poet":"Özgür Çelik","poet_slug":"ozgur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/cesaret-dedikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Şehir', 'o-sehir-suleyman-eser-vdpke', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tırmanıyordu Ankara Caddesini

İnce kemerli kıvrak bel, narin ayak

Tırmalıyordu ardından cesedini

Sivri tırnaklı kediler, ağlayarak

Ve vurdu yere başını çelik asa 

İlk sevinç uçtu göklere, çekti gitti

Buyurdu bize başsızlar “uyun başa” 

Kalbim linç oldu gözlerim gökten mavi

Zaman devirdi üstüme duvarları

Kaldırım beni kaldırıp attı yola 

Sırtımı ezdi bu şehrin uygarları

Kan kokuları bulaştı sağa sola 

Karanlık içmiş Karanfil Sokak bugün

Ah! Yedikule,hasretin coştuğu yer,

Marmara bezmiş hayattan, Haliç üzgün

Şehirde mert yok, durmadan korkak türer

İstanbul! Sana “İstanbul” diyemem ben 

Ruhuna asla yakışmaz bunca elem

Ya sön, kalmasın ihtişam o günlerden

Ya dön Aslı’na cihanda olma Kerem 

                                                   24/05/2004', 'Tırmanıyordu Ankara Caddesini İnce kemerli kıvrak bel, narin ayak Tırmalıyordu ardından cesedini Sivri tırnaklı kediler, ağlayarak Ve vurdu ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Eser']::text[], 8.5, '{"poet":"Süleyman Eser","poet_slug":"suleyman-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/o-sehir-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Beddua', 'aska-beddua-huseyin-alan-0aszd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tanımsız bir ses, ıssız yokuşlarda

Gözbebeğimde korku...

Kapısız kalbimde heyacan

Nerde deli aşk? 

Nerde meydanlarda hüzünler

Biliyorum aklımın içinde duygular

Kanatlarımda suskun ağız.

Sönük ve sıkıntıda yazgım

Ölüm ülkesinde sevinç yüreklerimiz.

                                                          

Bu sahile vuran acılarım 

Kendimde değersiz bakışlar

Mutluluğun yanında  aşk bir gölge...

Sersem damarlarımda sisli sokaklar

                                                           

Bir çizgi, ne eğri ne doğru

O kadın kokusunun boş elleri.

Harabeler  mahyasında en son korku

Kemirir: bende kalan bir pis koku

                                                   

Beter ol ey! aşk

Yazık sahnesinde sevda yalanca...

Kurtuluş aşka beddua...', 'Tanımsız bir ses, ıssız yokuşlarda Gözbebeğimde korku... Kapısız kalbimde heyacan Nerde deli aşk?  Nerde meydanlarda hüzünler Biliyorum aklı...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Alan']::text[], 8.5, '{"poet":"Hüseyin Alan","poet_slug":"huseyin-alan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aska-beddua-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız Kızı', 'yildiz-kizi-suleyman-eser-m2clr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kızkulesi’nin önünde dalgın

Bir kız ve ona kızgın 

Kızıl bir ufuk

Ve uzaktan uzağa

Bulutları şekillendiren 

Lerzan tüylü bir martı

Aylardan ağustos

Yıldızlardan bir kız 

Aldığı her nefes yaşam

Verdiği her yaşam bir sızı

Mevsimlerden kaygısızlık yazı

Aylardan ağustos

Kızlardan yıldızın kızı

Kızkulesi’nin  önünde sakin 

Uysal ve nazlı bir kız 

Alnında kara bir yazı

Yazının altında ince bir sızı

Kara kaşlarında hüzün 

Dalgalı saçlarındaki poyraz 

Büşrasıdır erken gelen 

Soluk benizli güzün

Kızkulesi’nin önünde üzgün 

Kara kaşlı,kara saçlı,kara bahtlı

Kara gözlü bir kızı vardı

Yakınlardan bir yıldızın 

Melda yasemin kokulu 

Hülyadan bıktı

Canıyla kanıyla usulca sızdı 

Çatlak sulara yıldızın kızı

Ne ardına aydan yakamoz indi

Ne bir damla gözyaşı

Yalnız bir acı çığlık fırlattı

Boğazın üstüne martı

“Bakın” dedi “bu kız da seçti intiharı”

                                                        19/02/2004', 'Kızkulesi’nin önünde dalgın Bir kız ve ona kızgın  Kızıl bir ufuk Ve uzaktan uzağa Bulutları şekillendiren  Lerzan tüylü bir martı Aylardan ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Eser']::text[], 8.5, '{"poet":"Süleyman Eser","poet_slug":"suleyman-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yildiz-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adi Mutluluk Olmali...', 'adi-mutluluk-olmali-mehmet-yilmaz-vshit', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biri var karsimda sessiz sakin ve bir o kadar da aglamakli 

Gözleri bir eser, yüregi bir altindan daha kiymetli 

Mutluluk derlermis adina, o mutlulugun tek varisi, 

Sözcükler onunla güzellesir, cümleler onunla dize gelir 

Gözlerindeki yaslar mutlugun tek ifadesi... 

O da sevgiyi hakkedenlerden, yüregiyle sevenlerden, 

Sorgusuz, sualsiz,ve tipki benim düsündügüm gibi; 

Ve Kapimi actim ona, onun gibi olmak vardi, 

Acaba Mutlulugundan bir parca da bana verir miydi? 

Beklemek cözüm degildi söylemeliydim... 

Kapımı actım ona, biraz ağlamaklı, biraz buğulu bir sesle, 

''''Hosgeldin sevgili''''. ''''Hosgeldin gönlümün sarayına'''' dedim. 

Seninle olabilmek için, sana dokunabilmek için, 

Gönlümdeki tüm duyguları fethettim... 

Ya sen mutluluk iksirinden bir yudumda bana verebilir misin? 

Basını omuzuma yaslayıp, seni her gece uykunu bölen kabuslara inat bana sarilip aglar misin? 

Bende aglayacagim seninle.''dedim''. 

Bir an duraksadi gözlerime bakti; sustu tek kelime söylemedi, 

Ve aski o an nasil yasanacagini anlatti bana sessizce... 

Heyecan,korku, umut ve sevgi hepsini bir arada yasiyordum. 

Mutluluk karsimdaydi, hic hazirlikli degildim ona karsi... 

Ona verecegim güzel duygularim yoktu, 

Gülmeyi coktan unutmustum, sevincimi gözyaslarimla özdeslestirmek istedim. 

O gelmeden önce; ondan önce yasadiklarimi karanlik bir odaya saklayip, üzerine kilitlemistim...(Ve bunu o asla bilmeyecekti)

Sevilmek ne tuhaf bir duygu; mutluluk aniden kapimi calmis, 

Gözlerimin icine bakmis ve sessiz sessiz aski bana anlatmis. 

Rüyada miydim yoksa, gercekten o mutluluk muydu? 

Aciya, yalnizliga o kadar sürüklenmisim ki mutlulugu bile unutmusum... 

O gece hic uyumamistim, onu düsünerek geceme renk katmak istedim biraz... 

Ben mutlulugu düsünüyordum, ve arka odaya sakladigim aci, yalnizlik coktan sesini kesmisti, onlar yoktu artik hayatimda... 

Gecem ilk defa onunla güzellesti, iki yanagimda bulunan gamzelerin oldugunu farkettim aynaya bakinca, 

O sadece mutluluk degildi, güzellikti, umuttu ve hayatti... 

Yasanilan tek gecelik aski anlatmayacaktim, o gözlerdeki ifadeyi nasil anlatabilirdi insan? 

Suskun kalmaliydi o gece orda kalacakti... 

Ve her gün farkli yasanacakti... 

Ondaki Mutluluk zincirine her gün baska bir dügüm atilacak 

Ve Her günümün farkli güzellikleri olacakti... 

Onun adi hem bahar hem sonbahar olacakti. 

Hayatim onunla anlam kazanacak ve onunla bir kat daha anlamdirilacakti. 

Sevecektim onu sevilmeyi ögretecekti bana, 

Aglamayi, gülmeyi,belkide herseyi,

Hayati...', 'Biri var karsimda sessiz sakin ve bir o kadar da aglamakli  Gözleri bir eser, yüregi bir altindan daha kiymetli  Mutluluk derlermis adina, o...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/adi-mutluluk-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöküş', 'cokus-suleyman-eser-gw4hb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vuslatın cihana yağdığı gece

Aleme fezadan mazharmışım ben 

Kimsenin dilinde yokken bir hece 

Atiye bin destan yazarmışım ben

Sahrayı geçmişim altımda atım

Sulayıp geceyi sabahı yaktım 

Beklide güneşten yegane farkım

Asiye kabristan kazarmışım ben

Korkusuz mücahit aslandan cesur

Yanımda dolaşır yanımda durur 

Fark etmez Müslüman fark etmez gavur

Arife kurulan gül-zarmışım ben

Mertliğim canımdır yoktur benzerim

Bir Mevla’m  korkumdur bir peygamberim 

Doğruluk hissesi vazgeçilmezim

Adiye pek yaman kızarmışım ben

Gün olmuş çökmüşüm yıkık surlarda 

Gürz topuz zil sesi dinmiş kavgamda 

Saflarım boşalmış yalnızım dağda 

Ademe sunulan pazarmışım ben

Günlerin açmazı doldurmuş beni

Bir çıkmaz sokağa sığdırmış beni 

Yüklenmiş tepeme durmamış geri

Altay’a varılan Hazar’mışım ben

Boğazda takılıp kalmış bir pislik

İnmiyor üstüne ne sular içtik

Acele bağlanan çamurdan iplik

Afete takılan nazarmışım ben

Ne kadar yükselsem sonunda düştüm

Hayaldim umuttum varılmaz düştüm

Duramam ayakta bastırdı yüküm

Aleve yanmadan kızarmışım ben

      

                                                     26.04.2004', 'Vuslatın cihana yağdığı gece Aleme fezadan mazharmışım ben  Kimsenin dilinde yokken bir hece  Atiye bin destan yazarmışım ben Sahrayı geçmiş...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Eser']::text[], 8.5, '{"poet":"Süleyman Eser","poet_slug":"suleyman-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/cokus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıpkızıl Kan', 'kipkizil-kan-suleyman-eser-f1l3f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kıpkızıl kan 

Selam,yardım,ihanet

Kurtuluş, yalan

Yapraklar kuru

Beyinler aç

Kurtarın aman

Düşünemiyorum

Zaman zaman

Kardeş,vurgun,ihanet

Kavgalar,açlık

Zehir dolu kadehler

Mahremiyetler

Perdesiz,üryan

Kahrolan bir bayan 

Sokaklar karanlık

Lambalar kapalı

Ölüm hepten siyah

Ellerimi tutan 

Bir yoldaşa muhtacım

Gidemiyorum

Bu yolları tanıyan

Birini arıyorum

Birini bekliyorum

Beni hemen,o an

Aydınlığa çıkaran

Kıpkızıl kan 

Vaadler,kahırlar

Yalancı gözler

Ve durmaksızın 

Ağlayanlar

Satırlar,satırlar 

Her satırda

Bir gariban

Geçmişten bir izi

Tastamam hatırlar 

Bir şeyi hatırlar

Hiç yok olmayan

Kıpkızıl kan 

Güçlünün gücüne

Güçsüzün

Suçlunun suçuna 

Suçsuzun

Boş verişidir

Yardımcı olan

Ama tarlalar

Ama bahçeler,bağlar

Bir yudum su için 

Bir avuç emek için 

Durmadan ağlar

Yardım edin aman 

Dağlar,yollar,anneler

Kin,ihtiras,

Yorgan

Yorgun geceler

Boyunca

Korkaklara kalkan

Kıpkızıl kan

Bir gemi mi

Tren mi kalkan

Nereden gelir 

Bu simsiyah 

Bu kahreden 

Zalim duman

Kıpkızıl kan 

İçinde sahte dostluk 

Sahte bir buhran

“Bende yanıyorum

seninle,dostum.

Bana da elaman”

Ama var ya 

Kurşun,siper,mevzi

İnsanlar sıradan

Hayat karmaşık

Tren yolları paslı

İstasyonlar kapalı

Zincirler,kelepçeler

Karanlık odalar

Yılanlar,yalanlar

Bunlar başımı sarmadan 

Kurtarın aman

Kıpkızıl kan

Bir kaşık suya 

Balıklama dalan

Esrarengiz adam

Ya da bir keman

İniltisinde

Kurşunlara vurulan

Genç bir yürek

Sahte bir kurban

Işıklar altında oradan 

Oraya oynaşan

Birkaç yılan

Kıpkızıl kan

Kıpkızıl kandır 

Beni böylesine acı…

Böylesine ağlatan

Bulutlar, hayaller

Samanlar,altınlar

Bir minarenin dışı

Ve birde içi

Dolan babam 

Dolandıkça dolan

Ama var ya 

Sokaklar, kadınlar

Ah! Birde o

Birde o insanlık

Her yer karanlık

Duvarların yıkık 

Yalan dünya 

Yıkık duvarlı 

Dünya, yalan

Kıpkızıl kan 

Kıpkızıl kandır

Beni böylesine 

Ağlatan.

                                           01/01/2003', 'Kıpkızıl kan  Selam,yardım,ihanet Kurtuluş, yalan Yapraklar kuru Beyinler aç Kurtarın aman Düşünemiyorum Zaman zaman Kardeş,vurgun,ihanet Ka...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Eser']::text[], 8.5, '{"poet":"Süleyman Eser","poet_slug":"suleyman-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":116,"source_url":"https://www.antoloji.com/kipkizil-kan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim İçin', 'benim-i-cin-huseyin-alan-l4clb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece, gizledim çığlığımı

Hadi karanlık kal

Türkünü söyle matem

Bu akşam benim için

Susun sevda tüküren dudaklar

Ritmini tutun haşmetli gecenin

Ey deniz ve ey rüzgar

Hırçınla, parçala ümit yıldızlarını

Gökyüzü yüzüme vursun nazını

Alnımı soğuk hüzünler öpsün

Umutsa umutlar dehşete düşsün 

Gözlerim ateşinden sakınsın benim için', 'Gece, gizledim çığlığımı Hadi karanlık kal Türkünü söyle matem Bu akşam benim için Susun sevda tüküren dudaklar Ritmini tutun haşmetli gecen...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Alan']::text[], 8.5, '{"poet":"Hüseyin Alan","poet_slug":"huseyin-alan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benim-icin-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenilmeden buhrana', 'yenilmeden-buhrana-yahya-akbulut-vhwkh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşlenmiş nakış gibi güneşten yanığı 

Hançer acısı yüzümde izleri sancılarımın.

Ateşten kor...

İncelmiş telleri dağınık saçlarımın.

Alın terimi akıttığım topraklar -

ayrılık kokuyor.

Tükenir mi ecelden güzelliği

o inceden ruhumun! 

Meleklerim aslında yanlış 

hatırlıyor.

Tanımadık semalara aktım, 

çizerken düşlerimi yıllarca.

Gönlümce aktım...

Her kanat çırptığımda ıslanırken 

yağmurlarda - terk etmeden

 umutlarımı

Kulaklarıma kadar battım.

Tükenirken üşüdüğümde nefesim

buz bağlayan kirpiklerimdi -

zedelenmeden tutam tutam...

Damla damla, göz yaşımdan 

eriyip akarken suları...

Sazın tellerinde delinecekse yüreğim...

Ey ozan... Ne gelir geçer ki 

aklından! ..

Neyse ki, yüreğim hala dimdik ayakta

Cirit attığım, özlediğim her sokakta.

Derlediğim göstermelik masallar

artık çok uzaklarda! 

Ve bilmek isterim ey, talihsiz zaman! 

Kasvetli rüzgarın erittiği yıkımlar -

yenilmeden  buhrana...

Söyleyin bana -yaşadığım ıstıraplar...

Kaç yaşında! 

16.01.2004 / Çorlu', 'İşlenmiş nakış gibi güneşten yanığı  Hançer acısı yüzümde izleri sancılarımın. Ateşten kor... İncelmiş telleri dağınık saçlarımın. Alın teri...', ARRAY['Türk Edebiyatı','Şiir','Yahya Akbulut']::text[], 8.5, '{"poet":"Yahya Akbulut","poet_slug":"yahya-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yenilmeden-buhrana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse İnsanoğlu!', 'gulumse-i-nsanoglu-cigdem-demircan-frzzp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi Sırat Köprüsü’nden atlamak vardı ya… 

Balıklama… 

Gözlerimi kapamadan, 

Utanmadan ölümsüz(!)  ahlaktan, 

Korkmadan yanmaya alışmaktan… 

İyilerimi soyunup bir deniz kenarında 

balıklara atsam 

sonra atlasam… 

Üşüyorum insanlığımdan 

bir yaz öğlesinde.', 'Şimdi Sırat Köprüsü’nden atlamak vardı ya…  Balıklama…  Gözlerimi kapamadan,  Utanmadan ölümsüz(!)  ahlaktan,  Korkmadan yanmaya alışmaktan…...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Demircan']::text[], 8.5, '{"poet":"Çiğdem Demircan","poet_slug":"cigdem-demircan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gulumse-insanoglu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-yasar-karaman-iexkn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Fethin beşyüzüncü yılı, sekiz yaşımdaydım

Babam Zonguldak'' dan vapura bindirdi bizi,

Gece boyu, güvertede, heyecandan uyuyamadım

Hiç böylesine sevmemiştim, Karadeniz'' i

Şafağı bekliyordum, uzakta ışıklar yanıp, sönüyordu,

Babam dedi: Rumeli Feneri'' dir, şu gördüğün sağdaki

Soldaki de Anadolu Feneri,

Birazdan göreceksin boğaziçini.

Oğlum, bilir misin bu şehir,

İki  kıtanın üzerindedir,

Yani İstanbul, Asya ve Avrupa'' nın

En romantik biçimde buluştukları yerdir.

Beşiktaş göz kırpar Üsküdar'' a her akşam

Ortaköy'' e rüzgarlanır, Çengelköy'' ün gülleri

Bebek, Kandilli'' ye serenat yapar,

Kanlıca'' yı okşar gibi, Emirgan'' ın elleri.

Tarabya, Beykoz'' a söyler en çapkın şiirleri

Büyükdere aşıkların yeridir,

Sarıyer'' de akşamları, piyasa vakti

Gönül şarkıları söylenir.

Kavak'' lar mütevazi bekler hep sizi,

Biralar buz gibi, midyeler leziz,

İstanbul'' a biran evvel kavuşmak için,

Çılgın gibi çırpınır hep Karadeniz.

İstanbul bu, dile kolay, yedi tepeli şehir,

Unuttum sayısını, kaç kapıdan girilir,

Taşı, toprağı altındır derler,

Çalışırsan eğer, sana da verir.

Tarih mi istiyorsun, tekmil bu şehirdedir,

Şu gördüğün büyük kule Ceneviz işidir,

Jüstinyen Ayasofya'' yı yapmış, Sinan kıskanmış,

Asırlardır İstanbul, doğurgan bir dişidir.

İşte Süleymaniye, Koca Sinan'' dan eser,

Fatih'' de camiinin yanında yatar Sultan Mehmet,

Yeni Cami köprüyü bekler, İstanbul''a hoş geldin der,

Altı minaresiyle yücelir Sultan Ahmet.

Topkapı sarayı'' nda yaşarsın Osmanlı'' yı

Dolmabahçe'' den selam olsun cumhuriyete

Kasırlar, bahçeler, o güzelim yalılar,

Senden eser kalacak ebediyete..

Babam öldü, sonra ben  İstanbul'' a yerleştim,

Çalıştım, çabaladım, arada bir eğlendim,

Bazen karargah kurdum Asmalımescit'' e,

Rakı içtim, nöbetçi şairlerden şiir dinledim.

İkinci kadehten sonra sanki Vivaldi

Tepemde gıcırdayan roman kemancı

Usta yap bir hicaz derdim, ağlamak için,

Bir virtiöz edasıyla başlardı:

''Közfezdeki durgun suya bir bak, göreceksin''

Şarkı biterdi, başkasına geçerdi,

''İstanbul'' u sevmezse gönül, aşkı ne anlar''

Sarhoş ederdi beni İstanbul'' lu şarkılar...

Bir semtine ömrünü vermiş Yahya Kemal,

Münir Nurettin bu mısraları enfes bestelemiş,

İstanbul şarkıları dilden, dile söylenmiş.

Yüce sevgililer romanlarda yaşarmış,

En yüce sevgiler de İstanbul'' da başlarmış.

Oysa ben, sadece İstanbul'' u sevdim.

Nisanda erguvanlar açardı, umutlanırdım,

Eylülde yağmurlar başlar, sanki küserdin

Peşinden avare dolaşırdım sokaklarında,

Bana uykusuz geceler, kederler verdin.

Baktım ki; umut yok, bu böyle olmayacak,

Sonu yoktu bu aşkın tuttum evlendim..

Kızım ve oğlum İstanbul'' da doğdular,

Ne mutlu onlara ki; İstanbul'' lu oldular.

Yıllar ne çabuk geçti, artık yaşlandım

Fakat, gönül mangalım küllendi sanma sakın

Ve sakın gücenme bana vafalı eşim

Bir zamanlar ben seni İstanbul diye sevdim.

Çocuktum, İstanbul'' u önce babam anlattı bana

Büyüdüm,  İstanbul'' u yaşadım, ona vuruldum

İstanbul'' da ihtiyar

Ama bahtiyar oldum.

Tüm dünya ozanları methiyeler de yazsa,

Tüm dünya ressamları seni tuvale dökse,

Tüm orkestralar senfoni bestelese,

Hepsi havada kalır

İstanbul anlatılamaz ki; yaşanır...', 'Fethin beşyüzüncü yılı, sekiz yaşımdaydım Babam Zonguldak'' dan vapura bindirdi bizi, Gece boyu, güvertede, heyecandan uyuyamadım Hiç böylesi...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Karaman']::text[], 8.5, '{"poet":"Yaşar Karaman","poet_slug":"yasar-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/istanbul-212-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultanım Muhammed Mustafa', 'sultanim-muhammed-mustafa-kul-costuk-iyqzh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aleme nur Güneş doğdu seninle

Nur yüzlü sultanım güzel Muhammed

Kainat nura bezendi seninle

Nur yüzlü sultanım güzel Muhammed

Çarkı devran amade hep emrine

Dara durur beşer çeşmi sözüne

Müjdeler kattın insan can özüne

Nur yüzlü sultanım güzel Muhammed

Adem safiyullah okur adını

La ilahe illallah ol şanını

Alan doyarmı senin bal tadını

Nur yüzlü sultanım güzel Muhammed

Levh kalem yazdı adın kalbe seyran

Şefaat ganisin ol çarkı devran

Yareme melhem dertlerime derman

Nur yüzlü sultanım güzel muhammed

Müjdeledi adın sanın dört kitap

Bir adın Ahmet kıldın bize hitap

Söylenirsin dillerde  Ali cenap

Nur yüzlü sultanım güzel Muhammed

Dört kapı kırk makam ayni erkanın

Damara kan hem cansın ol cananın

Zikir eder çağırırım an anın

Nur yüzlü sultanım güzel Muhammed

Kul Coştuk kurban an efendisine

Cana can katan mis koku nefesine

Canın verir kerbela bendesine

Nur yüzlü sultanım güzel Muhammed

                           Güzel doğum gününe 04.04.2005', 'Aleme nur Güneş doğdu seninle Nur yüzlü sultanım güzel Muhammed Kainat nura bezendi seninle Nur yüzlü sultanım güzel Muhammed Çarkı devran a...', ARRAY['Türk Edebiyatı','Şiir','Kul Coştuk']::text[], 8.5, '{"poet":"Kul Coştuk","poet_slug":"kul-costuk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sultanim-muhammed-mustafa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Oluş...', 'yok-olus-sibel-maral-qr8vc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bir Gönüldüm,

Sevgisizlikte kayboldum...

Ben bir Sevgiydim,

Gönülsüzlükten yok oldum...', 'Ben bir Gönüldüm, Sevgisizlikte kayboldum... Ben bir Sevgiydim, Gönülsüzlükten yok oldum......', ARRAY['Türk Edebiyatı','Şiir','Sibel Maral']::text[], 8.5, '{"poet":"Sibel Maral","poet_slug":"sibel-maral","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yok-olus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ara', 'bir-ara-sitki-gokmen-i26iq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakışın bir kapı aralığından hayata,

Sıkışıp kalmış ufacık bir arada.

Ne yüzün tam görünmekte,

Ne gülüşün,

Ne de yüzündeki hüznün.

Aralık dediğim gibi hepsi bir ara zamanda.

Gülümsemende,

Bakışında,

Yaşantında,

Yüzündeki hüzün bile.

Bir itebilsen cesaretle,

Aralardan sıyrılıp çıkacaksın,

Yüzünde tam görünecek,

Gülüşünde,

Hayatında tam.

(ANKARA 22 NİSAN 2005 16:25)', 'Bakışın bir kapı aralığından hayata, Sıkışıp kalmış ufacık bir arada. Ne yüzün tam görünmekte, Ne gülüşün, Ne de yüzündeki hüznün. Aralık de...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Gökmen']::text[], 8.5, '{"poet":"Sıtkı Gökmen","poet_slug":"sitki-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-ara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Sence', 'kim-sence-huseyin-alan-q9z4g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağzında geveler sözleri,

Uzun zaman dili çözülmedi

Bağırıp çağırsa imdadı yalan

Nedir sağında solunda kıpırdaşan...

Bu hokkabaz kafanın sıyırmamalı gazabını; 

Meziyetine baksak alçakça,

Rezilliğine tükürsek her yana saçılmış

Hiç var mı erdem koynuna alacak

Tiryakisi kopuk günahlarının,

Şimdilerde kötülüğünde hayatın

Gecesi cehennem çukuru...

Korkutur elini uzatan herkesi

Filan kavga, filan kumar

Ve filan fuhuş hep sende

Yok mu faziletten bir nebze 

Asrın ağzında kokan kim sence?', 'Ağzında geveler sözleri, Uzun zaman dili çözülmedi Bağırıp çağırsa imdadı yalan Nedir sağında solunda kıpırdaşan... Bu hokkabaz kafanın sıyı...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Alan']::text[], 8.5, '{"poet":"Hüseyin Alan","poet_slug":"huseyin-alan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kim-sence-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bataklık', 'bataklik-sair-azeytinli-0tepf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sesimi duyuramıyorum çırpınırken bu bataklıkta

durmaksızın batıyorum gülüm, pislik artık boğazımda

tutunacak bir dal bulamazsam da batıp gitsem burada

söyleyeceklerim var son nefesimi verdiğim sırada

gözlerim kapansa, nefesim kesilse, kanım çekilse de

asla tükenmeyecek olan aşkım hala damarlarımda

sana olan sevgimin büyüklüğü ölü bakışlarımda

kalacak verdidiğin o son öpücük ıslak dudaklarımda', 'sesimi duyuramıyorum çırpınırken bu bataklıkta durmaksızın batıyorum gülüm, pislik artık boğazımda tutunacak bir dal bulamazsam da batıp git...', ARRAY['Türk Edebiyatı','Şiir','Şair Azeytinli']::text[], 8.5, '{"poet":"Şair Azeytinli","poet_slug":"sair-azeytinli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bataklik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik', 'yitik-huseyin-alan-lds1u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mesafeler uzun, kayıp sesler,

Kapkara sırlar, fırtınalarda..

Bozuk gözümde buğulu aşk..

Hani güneş hani yağmur...

Bazı geceler, düşüncelere dalıyor yüreğim

Hatırda yalnızlık hatırda acı...

Kararıyor umutlar,

Yitik şafağın ardında

Geleceğe kurulu tuzaklar,

Ablukada düşler,

Benlik baygın...

Gözlerde karanlık izler

Zincirin pençesinde duygular,

Dudaklar yoksun öpüşlerden

Pişkinliğe namzet sözlerden,

Aşk yitik, gönül yitik.', 'Mesafeler uzun, kayıp sesler, Kapkara sırlar, fırtınalarda.. Bozuk gözümde buğulu aşk.. Hani güneş hani yağmur... Bazı geceler, düşüncelere ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Alan']::text[], 8.5, '{"poet":"Hüseyin Alan","poet_slug":"huseyin-alan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yitik-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Vazgeçmedim', 'ben-vazgecmedim-elcin-orhan-6ckdf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ak çiçekleri düşüren bu deli fırtına 

kaç meyve katili? 

dörtnala geçen yolcu 

kaç karınca katletti? 

şimdi neden deli deli esmeli 

neden dörtnala geçip gitmeli 

kuşlar takvime bakıp göçmez 

göç vakti gelince giden gitti... 

kim neden gitti? 

sen neredesin şimdi? 

bu hırçınlık kimden miras kaldı, bilinmez. 

hasret bitimi kucaklaşmak gibi sımsıkı 

sarmaşık gibi, 

sarıldığın gibi sarılıyorum anılarıma 

ya benimsin, 

ya yalnız! 

seni düşünüyorum hep benden fazla 

ben yalnız seni 

“seviyorum” 

kızaran gözlerinin akmayan yaşı gibi, 

tutup sevgini yüreğimde 

yapraklarımı küstürene küsmemeyi öğreniyorum, seviyorum 

ola ki günün birinde 

koyuverirsen göz yaşını omzuma diye 

ucu yanık kalbimi taşıyorum göğsümde 

çöz düğmelerimi oku diye... 

ve söylüyorum sana “ben vazgeçmedim” diye...', 'ak çiçekleri düşüren bu deli fırtına  kaç meyve katili?  dörtnala geçen yolcu  kaç karınca katletti?  şimdi neden deli deli esmeli  neden dö...', ARRAY['Türk Edebiyatı','Şiir','Elçin Orhan']::text[], 8.5, '{"poet":"Elçin Orhan","poet_slug":"elcin-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ben-vazgecmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Şairlere', 'butun-sairlere-veysel-alkan-h6voz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman gelir, şair gibi,kuşlar da susar.

Esarete alışır, derde doyunca.

Zaman gelir,kuşlar gibi,şair de susar.

Suyu arar,pınar bulur, içer doyunca.

Kartal gibi yırtıcıdır,toprağı bilmez

Şairlerin mekânıdır dağların taşı

Seni kimse tanımaz,adını bilmez

Sen istersen ömrünce dağları taşı.

.', 'Zaman gelir, şair gibi,kuşlar da susar. Esarete alışır, derde doyunca. Zaman gelir,kuşlar gibi,şair de susar. Suyu arar,pınar bulur, içer do...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/butun-sairlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım İstanbul', 'canim-i-stanbul-i-brahim-tamer-8pc2a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Rüyalar şehrinde gizem İstanbul,

Sahil sularında yüzen İstanbul,

Süzülürsün iki deniz arası,

Mazilerde tarih yazan İstanbul.

Nazlısın,narinsin,peri gibisin.

Sende yaşanır aşk,sen sevgilisin.

Sana yanlız ben`mi, dünya aşıktır,

Huriler diyarı, cennet gibisin.

Bir ayrıcalıktır sende yaşamak,

Mavi denizinde suyuna dalmak,

İstanbul eşittir özgürlüktür ki; 

Yeterli, tarihte sayfaya bakmak.

Dokunmasın sana,yabancı eller,

Soldurmasın seni,esmesin yeller,

Saklasın ALLAH''ım seni kem gözden,

Yeşersin bağrında,solmasın güller.

Gerdanında kolye,Boğaz Köprüsü,

Kıtalar arası dostluk kapısı.

Dostluk türküsünü söyler dünyaya; 

Ayasofya ve Rum Patrikhanesi.

Tarihteki adın,şanla şöhrettir.

Kalplerdeki tadın,aşkla şehvettir.

Seni şu cihanda, değerli kılan; 

Her dine duyduğun  yüce şefkattir.

Asya biter, sende Avrupa başlar,

Can verdik uğruna,kesildi başlar.

Sel olup akmıştı,kalbine senin,

Fatih''in, boğazda döktüğü yaşlar.

Dünyanın kalbinin attığı yersin,

Bir millet ruhunun yattığı yersin,

Fatih''in,Ata''nın ruhu şad olsun,

Güneşin huzurla battığı yersin.

Dillerde destandır abidelerin,

Huzur,huşu eder minarelerin,

Koynunda yatıyor şehit Mehmet`in,

Ata yadigarı canım İstanbul.', 'Rüyalar şehrinde gizem İstanbul, Sahil sularında yüzen İstanbul, Süzülürsün iki deniz arası, Mazilerde tarih yazan İstanbul. Nazlısın,narins...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tamer']::text[], 8.5, '{"poet":"İbrahim Tamer","poet_slug":"i-brahim-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/canim-istanbul-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Gözlerime Baktığında', 'gozlerin-gozlerime-baktiginda-mustafa-demirci-2-v9kxm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin gözlerime baktığında

Kendimi tutamıyorum

Bir nisan yağmuruna dönüveriyor

Yalak yalak oluyor göz pınarlarım

Ve seni görüyorum, tatlı içten bakışlarını 

Ve seni düşünüyorum derin derinden....

Senin kaderini, senin ahvalini

Hiç gözümün önünden gitmiyorsun ki,

Zorluyorum kendimi kendime gelmek için

Ama nafile inat ediyorsun karşımda 

Git yahu, git ki işime bakayım

Hala duruyorsun, içimi sızlatıyorsun sanki

Parmaklarım titriyor Allah kahretsin

Yanlış yazıpta kalbini kıracağımdan

İncecik, narin çiçeğin dalları gibi seni koparacağımdan,

Seni ağlatacağımdan, üzeceğimden, senden geçeceğimden

Korkuyorum, içim gidiyor sanki...içim...

Sen beni anlıyorsun değilmi...

Ya senden ne istiyorum biliyormusun..

Düşünmedin ki beni..Ama ben

Ama ben, ama ben.....yandım, yandım 

Hani ağustos ayındaki çılgın güneşin 

Çöldeki toprağı yaktığı gibi.Yanıyorum

Ve gözlerin gözlerime baktığında

Birşeyler akıp gidiyor içimden

Terliyorum, yüzlerim kızarıyor sanki sen

Evet sanki sen bana birini hatırlatıyorsun

Neyse boş ver diyorum kendime

Teselli edemiyorumki lanet olsun

Ama çoook geç, herşey çok geç diyorum

Bak yine doldu gözlerim seninki gibi

..................', 'Gözlerin gözlerime baktığında Kendimi tutamıyorum Bir nisan yağmuruna dönüveriyor Yalak yalak oluyor göz pınarlarım Ve seni görüyorum, tatlı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Demirci 2']::text[], 8.5, '{"poet":"Mustafa Demirci 2","poet_slug":"mustafa-demirci-2","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gozlerin-gozlerime-baktiginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalak yalak oluyor göz pınarlarım', 'yalak-yalak-oluyor-goz-pinarlarim-mustafa-demirci-2-9hukm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin gözlerime baktığında

Kendimi tutamıyorum

Bir nisan yağmuruna dönüveriyor

Yalak yalak oluyor göz pınarlarım

